INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0740be8d-4ddd-4977-8e97-9463dcf979d0', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'The mode of nutrition in which organisms make food themselves from simple inorganic substances is called:', 'Autotrophic nutrition (Auto = self, trophos = nourishment) is the synthesis of organic food by green plants from simple substances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c25b62e-5c90-4bbf-95c5-572f8ddbc44b', 'Autotrophic Nutrition', true, '0740be8d-4ddd-4977-8e97-9463dcf979d0');
