INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('450467fd-402b-4d19-a8b2-d03f11d3ad33', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'The green pigment present in the leaves of plants that captures solar radiant energy for photosynthesis is called:', 'Chlorophyll is the green magnesium-containing pigment in chloroplasts that absorbs sunlight energy for photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
