INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee9ffd8d-fe98-4bc3-8d8d-c72802dc26d5', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'What are the essential raw materials required by green plants to carry out Photosynthesis?', 'Photosynthesis combines CO₂ and H₂O in the presence of light and chlorophyll to synthesize carbohydrates and O₂.', NOW()) ON CONFLICT DO NOTHING;
