INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20a7066d-e6e9-4428-a914-5bf0bf818702', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'What is the primary carbohydrate food product and by-product gas synthesized during photosynthesis?', 'Photosynthesis converts CO₂ + H₂O into Glucose (stored as Starch) while releasing Oxygen (O₂) as a vital by-product.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59426465-df93-459d-960a-3f5a4805e246', 'Glucose (stored as Starch) and Oxygen gas (O₂)', true, '20a7066d-e6e9-4428-a914-5bf0bf818702');
