INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('267ed4f2-09a9-4994-a958-c25f5f453ef7', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'Which yellow, tubular, non-green twining plant is a classic example of a total plant PARASITE that climbs on host trees?', 'Cuscuta (Amarbel) lacks chlorophyll and uses haustorial root suckers to derive ready-made nutrients from its host tree.', NOW()) ON CONFLICT DO NOTHING;
