INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c0bb2dc-1cb0-4b02-93ce-0c7401d0fceb', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'Organisms that derive their nourishment in solution form from dead and decaying organic matter (such as Fungi/Mushrooms) are called:', 'Saprotrophs secrete digestive enzymes onto decaying substrates and absorb the liquefied nutrients.', NOW()) ON CONFLICT DO NOTHING;
