INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a5fe06b-6cf9-4b73-a96e-e7f2b125b37f', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'A symbiotic association in which an Alga (autotroph) and a Fungus (saprotroph) live together in mutual benefit is called a:', 'In Lichens, the green alga manufactures food via photosynthesis while the fungus provides shelter, water, and minerals.', NOW()) ON CONFLICT DO NOTHING;
