INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64dbe00a-64b5-42f2-a277-3789c92cdf23', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'Which chemical test is used to detect the presence of Starch in a green leaf after photosynthesis?', 'Iodine solution forms a characteristic blue-black charge-transfer complex with starch molecules in leaves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('693c3a4e-95fe-4b6d-844c-c46c67ef232e', 'Iodine Solution Test (turns blue-black in presence of starch)', true, '64dbe00a-64b5-42f2-a277-3789c92cdf23');
