INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c61ca2d3-c596-4863-95b0-84f01a612dac', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'What are the slimy, green floating patches commonly seen in stagnant ponds and ditches formed by simple photosynthetic organisms called?', 'Algae are simple thallophyte organisms containing chlorophyll that conduct aquatic photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47430d6b-6baf-487f-9915-902b8c5d6ae3', 'Algae', true, 'c61ca2d3-c596-4863-95b0-84f01a612dac');
