INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32968576-fc90-45e9-9a2c-a6d90fb74314', 'Bacteria', false, 'c61ca2d3-c596-4863-95b0-84f01a612dac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('065ac30f-ee9e-45de-9c9a-45bbfc5826ee', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'Which beneficial bacterium lives inside the root nodules of leguminous crops (grams, peas, beans) to fix atmospheric nitrogen into soluble soil nitrates?', 'Rhizobium bacteria form symbiotic root nodules with legumes, biologically fixing inert atmospheric N₂ into fertile nitrates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09828c26-ea99-40c8-a2c1-7442b1a1f0f9', 'Rhizobium', true, '065ac30f-ee9e-45de-9c9a-45bbfc5826ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acf029c0-5b46-46d4-9ba8-487497992d34', 'Lactobacillus', false, '065ac30f-ee9e-45de-9c9a-45bbfc5826ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('979db701-4449-41ab-956b-a6e28bfde77f', 'E. coli', false, '065ac30f-ee9e-45de-9c9a-45bbfc5826ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8059a06-b03e-4889-b4ea-47b46acf1692', 'Salmonella', false, '065ac30f-ee9e-45de-9c9a-45bbfc5826ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0dda71fd-4e7c-45ed-9de2-c06c58ff4278', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why do insectivorous plants (like the Pitcher Plant) capture and digest insects even though their green leaves carry out photosynthesis?', 'Insectivorous plants are autotrophic for carbon/carbohydrates but carnivorous to supplement nitrogen deficient in marsh soils.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f57ffb03-94e4-4b28-98d3-182400a8c79e', 'They grow in nitrogen-deficient, boggy acidic soils and trap insects to obtain essential nitrogenous compounds required for protein synthesis', true, '0dda71fd-4e7c-45ed-9de2-c06c58ff4278');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('312a1478-6357-4a5b-87fd-a4f3fed50c7e', 'Because they cannot make any glucose at all', false, '0dda71fd-4e7c-45ed-9de2-c06c58ff4278');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3682192-5ad1-4a59-b149-9a9dd2639ee7', 'To protect themselves from insect bites', false, '0dda71fd-4e7c-45ed-9de2-c06c58ff4278');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a70c35d-10de-42fa-90be-549da8bdfdf2', 'Because they do not need sunlight', false, '0dda71fd-4e7c-45ed-9de2-c06c58ff4278');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bef3f54a-2ba6-48ec-83f0-e5b1e11a8c80', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'How do water and dissolved mineral nutrients absorbed by roots travel upwards to reach the green leaves?', 'Xylem vessels form continuous hollow tracheary conduits transporting water and minerals upwards by capillary and transpirational pull.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaf7b87e-6148-4741-a4b4-ecb51020b19c', 'Through continuous pipe-like vascular vessels (Xylem tissue) running like pipelines throughout roots, stem, branches, and leaves', true, 'bef3f54a-2ba6-48ec-83f0-e5b1e11a8c80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54dd8195-78b9-48c9-a800-d390b2a006f7', 'By diffusing across the outer bark', false, 'bef3f54a-2ba6-48ec-83f0-e5b1e11a8c80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc3910e8-5be4-4ef0-aaa2-da5d95c3f3fc', 'Carried inside pollen grains', false, 'bef3f54a-2ba6-48ec-83f0-e5b1e11a8c80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95f6f3ae-f819-40c5-a060-11fa31f98459', 'Through stomatal pores', false, 'bef3f54a-2ba6-48ec-83f0-e5b1e11a8c80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e1ddc2d-3f61-4bdf-9b6e-990e7c822be1', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why do leaves that are deep red, brown, or violet in color (such as Croton leaves) also carry out photosynthesis successfully?', 'Anthocyanin and carotenoid pigments mask the green chlorophyll optical color, but photosynthesis proceeds normally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ec7a637-b0ab-4c53-bbd4-686fbea90a78', 'They contain large amounts of red and brown accessory pigments that mask the green chlorophyll, but chlorophyll is still present and functional underneath', true, '3e1ddc2d-3f61-4bdf-9b6e-990e7c822be1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9c3aa57-b4eb-4fc4-9bce-27b28ffbff54', 'Because red color is better than green for photosynthesis', false, '3e1ddc2d-3f61-4bdf-9b6e-990e7c822be1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4f43125-0554-468f-85f3-d122115d872b', 'They absorb food directly from surrounding air', false, '3e1ddc2d-3f61-4bdf-9b6e-990e7c822be1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64d04126-0c75-41b8-b5dd-e6713a6b43eb', 'They only photosynthesize in the dark', false, '3e1ddc2d-3f61-4bdf-9b6e-990e7c822be1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c161563d-58f9-4427-b448-165203965502', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why does a piece of moist bread develop a fluffy, cottony growth (mold) of green, white, or brown patches when left in a warm, moist room for 2-3 days?', 'Dormant fungal spores (like Rhizopus bread mold) germinate upon contact with warm moist organic substrates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d0bc351-7157-456b-9e48-966768d91b01', 'Airborne fungal spores land on the moist nutrient-rich bread, germinate into thread-like hyphae, and feed saprotrophically', true, 'c161563d-58f9-4427-b448-165203965502');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7721110a-c88c-4544-9d7b-26f54f120c48', 'The bread converts into green grass', false, 'c161563d-58f9-4427-b448-165203965502');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('100556bc-7590-4812-bb67-7365881d4b67', 'Bacteria produce green paint', false, 'c161563d-58f9-4427-b448-165203965502');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30e0984e-78ba-43eb-ba74-72b79ef67a58', 'Moisture turns bread into plastic', false, 'c161563d-58f9-4427-b448-165203965502');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('171eed25-a653-4f29-9e75-3677b39e0329', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why is the Sun rightfully described as the ''Ultimate Source of Energy'' for all living organisms on planet Earth?', 'Solar photons captured during photosynthetic light reactions drive primary biomass production across the global biosphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('109e66e1-b1c3-4396-b20f-ca73d653ff41', 'Solar radiant energy captured by green autotrophic plants through photosynthesis forms the foundational chemical energy that powers all herbivores, carnivores, and human food webs', true, '171eed25-a653-4f29-9e75-3677b39e0329');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8e79e8d-fb55-48db-8bf1-fb8b8c24a086', 'Because the sun burns all waste materials', false, '171eed25-a653-4f29-9e75-3677b39e0329');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cf78370-689f-41b6-912d-7a76ae06da47', 'Because animals can make food directly from sunlight without plants', false, '171eed25-a653-4f29-9e75-3677b39e0329');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41ce5bd2-f6e3-4349-b98f-957b34bfa17a', 'Because the sun produces soil directly', false, '171eed25-a653-4f29-9e75-3677b39e0329');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d165beee-1ca3-4866-a04b-3ea6930d8a2a', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'How do green plants synthesize PROTEINS when photosynthesis only directly produces carbohydrates (Carbon, Hydrogen, and Oxygen)?', 'Proteins require nitrogen along with C, H, O. Plants utilize soil nitrates absorbed by roots to synthesize amino acids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('523f21d9-8c2a-451b-883f-7f10051cfcfb', 'Plants combine carbohydrates with soluble Nitrogen absorbed from soil (via nitrogen-fixing bacteria and fertilizers) to synthesize amino acids and proteins', true, 'd165beee-1ca3-4866-a04b-3ea6930d8a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cbfabf0-8375-4d38-97ab-fa1593d86b22', 'Plants absorb proteins directly from rainwater', false, 'd165beee-1ca3-4866-a04b-3ea6930d8a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b7bd07a-6289-4aa1-a1e1-35e749731d22', 'Chlorophyll turns directly into protein in sunlight', false, 'd165beee-1ca3-4866-a04b-3ea6930d8a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f0f3646-42b8-4d14-8370-d627965a1005', 'Plants convert sunlight into iron', false, 'd165beee-1ca3-4866-a04b-3ea6930d8a2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db4f9518-5c29-42b1-90cd-7b025edd3b99', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why do farmers rarely need to add synthetic nitrogenous fertilizers to fields where leguminous crops (like peas, grams, or lentils) are cultivated?', 'Rhizobium-legume symbiosis enriches rhizosphere nitrogen stocks, reducing synthetic chemical fertilizer requirements.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63adf99b-d797-4931-85dd-83d88921acfc', 'Symbiotic Rhizobium bacteria living in the legume root nodules naturally enrich the soil with fixed nitrogen, replenishing soil fertility naturally', true, 'db4f9518-5c29-42b1-90cd-7b025edd3b99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37127c1f-27bf-4b59-815f-fbcc588d253a', 'Because legumes do not require any nitrogen', false, 'db4f9518-5c29-42b1-90cd-7b025edd3b99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cee5b141-1cfa-4e60-8629-c0e8c0b6be13', 'Because legume leaves produce chemical fertilizer powder', false, 'db4f9518-5c29-42b1-90cd-7b025edd3b99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10c12d81-0237-4410-afd7-e5291043db64', 'Because legumes absorb nitrogen through flowers', false, 'db4f9518-5c29-42b1-90cd-7b025edd3b99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04153573-373e-49e4-89d6-8d266620ec5d', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'What happens when a potted green plant is kept inside a pitch-dark room for 72 hours (3 days) before an Iodine test?', 'Destarching in prolonged darkness exhausts leaf starch reserves via metabolic cellular respiration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16cf5fce-09ff-440c-ad57-0bef2c40d206', 'The plant gets ''destarched'' as it consumes all its stored starch reserve in respiration without producing new starch, testing negative with iodine (no blue-black color)', true, '04153573-373e-49e4-89d6-8d266620ec5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3085d746-1e7c-4752-9843-a950e65949e1', 'The leaves turn permanently blue-black', false, '04153573-373e-49e4-89d6-8d266620ec5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd47d495-ba5b-4b7c-a874-b3041a27898b', 'The plant produces double the amount of starch', false, '04153573-373e-49e4-89d6-8d266620ec5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('376635fb-85a3-4685-8f7d-5e24c38ff25b', 'The roots turn into stems', false, '04153573-373e-49e4-89d6-8d266620ec5d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38cf5619-2e02-4370-8d4c-9e3891959681', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'What is the symbiotic relationship between a Fungus and the roots of higher forest trees (such as Pinus / Oak) known as?', 'Mycorrhizal mutualism expands root surface area for phosphorus/water uptake in exchange for host plant photosynthate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54787a6f-9701-428a-8bfd-55c2357a7822', 'Mycorrhiza (Fungus absorbs water and minerals for the tree, while the tree provides photosynthetic carbohydrates to the fungus)', true, '38cf5619-2e02-4370-8d4c-9e3891959681');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85f6b898-26bc-49a1-9d6a-0fb9f165d3cd', 'Parasitism', false, '38cf5619-2e02-4370-8d4c-9e3891959681');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3909d623-7ed8-4b78-b976-637d4ca00f6f', 'Predation', false, '38cf5619-2e02-4370-8d4c-9e3891959681');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0123c91-7883-434b-a9b2-2df577c64b31', 'Insectivory', false, '38cf5619-2e02-4370-8d4c-9e3891959681');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19d436c3-0a77-4eb9-8936-d6885d795af8', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'How do Guard Cells regulate the opening and closing of stomatal pores on leaves?', 'Turgor pressure dynamics: osmotic potassium/water influx increases guard cell turgidity, bowing differential cell walls open.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff364ee0-439d-4a62-93e4-5b61b89d29aa', 'Guard cells swell and curve outward when water flows into them to open the pore, and shrink flaccid when water leaves to close the pore', true, '19d436c3-0a77-4eb9-8936-d6885d795af8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4e7e446-ee53-4e37-a4fd-52920707610f', 'Guard cells spin around like wheels', false, '19d436c3-0a77-4eb9-8936-d6885d795af8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('336b4248-26d2-4f01-9587-f95b3ec59ffa', 'They melt in hot sunlight', false, '19d436c3-0a77-4eb9-8936-d6885d795af8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce0489cb-c19b-467f-9049-6126912b223c', 'They break apart permanently at night', false, '19d436c3-0a77-4eb9-8936-d6885d795af8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7edd7343-cb18-4afc-a1dc-daa2a6e6c877', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why is Cuscuta (Amarbel) classified as a ''Parasite'' while the host tree is harmed?', 'Parasitism represents a (+/-) relationship where the parasite extracts vascular sap without returning metabolic reciprocity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dc4ba10-8134-48b3-9235-08f7ddd75f2b', 'It deprives the host tree of valuable synthesized nutrients without contributing any benefit, weakening the host''s vigor', true, '7edd7343-cb18-4afc-a1dc-daa2a6e6c877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15605aa7-29c2-4904-951b-c4be09a8dfeb', 'Because it provides water to the host', false, '7edd7343-cb18-4afc-a1dc-daa2a6e6c877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f872698b-d99b-4af6-a6d0-4720709bef05', 'Because it cleans the host tree leaves', false, '7edd7343-cb18-4afc-a1dc-daa2a6e6c877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f7bae35-2a1d-42e8-abc2-881b6c1fca07', 'Because it makes the tree grow twice as fast', false, '7edd7343-cb18-4afc-a1dc-daa2a6e6c877');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6d5710d-dbdf-491d-ac3e-c0c22ca46b24', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'What is the role of boiling a leaf in alcohol (ethanol) inside a water bath during the classic Starch test experiment?', 'Boiling in ethanol de-pigments the leaf by dissolving photosynthetic chlorophyll lipids, ensuring clear iodine colorimetry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('810b3c8b-f5d6-496b-b2cc-4aa74e28e596', 'To dissolve and extract the green chlorophyll completely so that the blue-black iodine color change can be observed clearly without green interference', true, 'b6d5710d-dbdf-491d-ac3e-c0c22ca46b24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f84b09c3-64b1-41bb-b5af-e9b3afba344e', 'To make the leaf grow bigger', false, 'b6d5710d-dbdf-491d-ac3e-c0c22ca46b24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13804aff-18f8-4e97-b73c-f70055840895', 'To kill the starch molecules', false, 'b6d5710d-dbdf-491d-ac3e-c0c22ca46b24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1fc1623-8f89-402c-b151-1235dc13797a', 'To turn the leaf into sugar', false, 'b6d5710d-dbdf-491d-ac3e-c0c22ca46b24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a12fb6e0-79d1-4a20-88c4-4063c1fb6916', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why cannot human beings or other non-green animals synthesize their own food from atmospheric CO₂ and water like green plants do?', 'Heterotrophs lack thylakoid chloroplast machinery and chlorophyll complexes capable of light-driven photophosphorylation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61668a67-e53f-47e2-ae8b-e46b5fe8905c', 'Animal cells lack chloroplasts and the green pigment Chlorophyll necessary to absorb and convert solar photonic energy into chemical bonds', true, 'a12fb6e0-79d1-4a20-88c4-4063c1fb6916');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9e97179-b9b7-4b3a-a830-e56b67cec5c4', 'Because animals do not drink enough water', false, 'a12fb6e0-79d1-4a20-88c4-4063c1fb6916');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('932dad73-9bb8-498a-b229-449ee7c387ad', 'Because animal skin is too thick', false, 'a12fb6e0-79d1-4a20-88c4-4063c1fb6916');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('533a9ec6-b3fd-4b63-9ca9-9cc1e27ad1d9', 'Because animals walk on legs', false, 'a12fb6e0-79d1-4a20-88c4-4063c1fb6916');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('152ed491-8565-4d97-be45-b4246c463137', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'What is the chemical word equation representing Photosynthesis?', 'Photosynthetic stoichiometry: 6CO₂ + 6H₂O + radiant energy → C₆H₁₂O₆ + 6O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5c266cb-d449-466f-bda4-71a3b53c24a5', 'Carbon dioxide + Water --(Sunlight / Chlorophyll)--> Carbohydrate (Glucose) + Oxygen', true, '152ed491-8565-4d97-be45-b4246c463137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d682a92-37ae-47fd-a2c9-b2c223b70aae', 'Glucose + Oxygen ----> Carbon dioxide + Water + Energy', false, '152ed491-8565-4d97-be45-b4246c463137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56aaa4b0-b30d-419f-85b0-f81f620c0a5d', 'Nitrogen + Water ----> Protein + Hydrogen', false, '152ed491-8565-4d97-be45-b4246c463137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('912daeb0-a285-4cc7-bc61-69ea369538cb', 'Carbon dioxide + Soil ----> Starch + Salt', false, '152ed491-8565-4d97-be45-b4246c463137');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('467a64d2-2086-42fa-b6cb-7ad057cbd987', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why do fungal infections frequently spoil leather shoes, pickles, wet clothes, and wood furniture during hot and humid monsoon weather?', 'Microscopic ubiquitous fungal spores require warm (25–35°C) and humid (>70% RH) substrates for vegetative hyphal growth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dae20690-cda0-42d5-a2ba-6cfad2712cca', 'High humidity (moisture) and warm ambient temperatures provide optimal ecological conditions for airborne fungal spores to settle, germinate, and proliferate rapidly', true, '467a64d2-2086-42fa-b6cb-7ad057cbd987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('121ca921-ed92-4938-9333-4c22d72ab6fe', 'Because leather shoes make food for fungi', false, '467a64d2-2086-42fa-b6cb-7ad057cbd987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a5927bb-673a-4d07-8b86-d33e54cd049a', 'Because rain turns clothes into fungi', false, '467a64d2-2086-42fa-b6cb-7ad057cbd987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f53e0ae2-f747-4b7f-941f-cd31257fc572', 'Because sunlight stops shining entirely', false, '467a64d2-2086-42fa-b6cb-7ad057cbd987');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4d5594d-817b-42d5-a077-f1efab024646', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'How do major macronutrients like Nitrogen, Phosphorus, and Potassium (NPK) get depleted in soil over continuous farming?', 'Crop harvest continuously exports bio-accumulated N-P-K mineral reserves from agricultural soils, requiring systematic replenishment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('262296c3-0c95-4b8e-b913-2b86955e8dbe', 'Growing crops continuously absorb massive quantities of mineral nutrients from the soil, requiring periodic replenishment via manure, compost, or fertilizers', true, 'b4d5594d-817b-42d5-a077-f1efab024646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('677aa2ed-c129-42a4-8418-27a2c46eb853', 'Rain washes away all soil rocks', false, 'b4d5594d-817b-42d5-a077-f1efab024646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d859aa-fd0b-49f6-8e78-cf8759969e3e', 'Earthworms eat all the soil nitrogen', false, 'b4d5594d-817b-42d5-a077-f1efab024646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92bc2257-2b73-4d16-a3af-241a7d2502dd', 'Wind blows away minerals into clouds', false, 'b4d5594d-817b-42d5-a077-f1efab024646');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be3de7f9-ac1f-42eb-90fb-fca52cee95e9', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95638b26-21c3-46df-8685-93f029371803', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'be3de7f9-ac1f-42eb-90fb-fca52cee95e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d318d6d-1d8a-47c9-a9ce-7672c6c4e6ea', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'be3de7f9-ac1f-42eb-90fb-fca52cee95e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7596845-0eba-4863-9fd6-e9779f381f01', '(A) is true, but (R) is false.', false, 'be3de7f9-ac1f-42eb-90fb-fca52cee95e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffdc683c-94fc-45ab-bc4d-a08d89ef9bee', '(A) is false, but (R) is true.', false, 'be3de7f9-ac1f-42eb-90fb-fca52cee95e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54522271-a789-4c29-bd36-fbadaba6c8d8', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Spot the IMPOSTER in the following group of organisms categorized by their primary mode of nutrition:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47e7e69f-ee57-4865-a772-5cb07969fd59', 'Mushroom - Saprotroph', false, '54522271-a789-4c29-bd36-fbadaba6c8d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8928342c-6da0-41f1-81d2-c14dc29b3c68', 'Yeast - Saprotroph', false, '54522271-a789-4c29-bd36-fbadaba6c8d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa8ad61d-33d6-404e-9df7-1c1bbb43aa65', 'Bread Mold (Rhizopus) - Saprotroph', false, '54522271-a789-4c29-bd36-fbadaba6c8d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b52c8c28-6cca-46e5-9981-217a05236b4b', 'Cuscuta (Amarbel) - Saprotroph', true, '54522271-a789-4c29-bd36-fbadaba6c8d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81f8eb07-a187-44fa-b142-6c08d6c40c1f', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'A variegated leaf of a Coleus plant (having green center and white non-green border) is exposed to bright sunlight for 6 hours and tested with Iodine solution. What will be the observed result?', 'Starch is synthesized exclusively in chlorophyll-containing green areas, confirming chlorophyll''s essential catalytic role.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7889811c-5a45-4993-bfae-766f77693b2b', 'Only the green central region turns blue-black (showing starch present), while the white non-green border remains pale yellow-brown (no starch), proving chlorophyll is indispensable for photosynthesis', true, '81f8eb07-a187-44fa-b142-6c08d6c40c1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63713e33-c748-4ebd-bb5a-69c62cd1cf76', 'The entire leaf turns uniform blue-black', false, '81f8eb07-a187-44fa-b142-6c08d6c40c1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4474458-c0df-4695-a890-cc5fbf1c4a47', 'Only the white border turns blue-black', false, '81f8eb07-a187-44fa-b142-6c08d6c40c1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb1cb012-c69e-4775-ba37-270c9c2d3c94', 'The whole leaf turns bright red', false, '81f8eb07-a187-44fa-b142-6c08d6c40c1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9acaa3f9-73ce-48d6-bb60-2b619e200a5d', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Match Column I (Modes of Plant Nutrition) with Column II (Representative Examples):
(a) Autotroph       -> (i) Cuscuta (Amarbel)
(b) Parasite        -> (ii) Pitcher Plant (Nepenthes)
(c) Saprotroph      -> (iii) Green Algae & Mango tree
(d) Insectivorous   -> (iv) Mushroom (Agaricus)', 'Autotroph = Algae/Mango; Parasite = Cuscuta; Saprotroph = Mushroom; Insectivorous = Pitcher plant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80d4bac2-328a-4260-bc61-df582dd2a9ad', 'a-(iii), b-(i), c-(iv), d-(ii)', true, '9acaa3f9-73ce-48d6-bb60-2b619e200a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('915d386b-7f45-4764-8fb4-3f7973f4e996', 'a-(i), b-(iii), c-(ii), d-(iv)', false, '9acaa3f9-73ce-48d6-bb60-2b619e200a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20f4ed22-88ec-4da1-8a81-96eea05951c9', 'a-(iv), b-(ii), c-(iii), d-(i)', false, '9acaa3f9-73ce-48d6-bb60-2b619e200a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9431da2-92d8-4a61-a604-a0c91b57d531', 'a-(ii), b-(iv), c-(i), d-(iii)', false, '9acaa3f9-73ce-48d6-bb60-2b619e200a5d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8374d051-b3d7-430f-b89d-92908e7619a1', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Read the statements regarding plant physiology:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa5c0c3-ff33-44e1-b58a-3d7398cee4ed', 'Statements 1 and 2 only', true, '8374d051-b3d7-430f-b89d-92908e7619a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd9fc6e0-7220-45db-988c-d6c0ed90aae7', 'Statements 2 and 3 only', false, '8374d051-b3d7-430f-b89d-92908e7619a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d050f20-722f-418b-8338-307f2f2c6c5b', 'Statements 1 and 3 only', false, '8374d051-b3d7-430f-b89d-92908e7619a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8edf75d0-5f2c-4caa-aa52-a5a5c20fa157', 'All Statements 1, 2, and 3', false, '8374d051-b3d7-430f-b89d-92908e7619a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93c3b513-082d-4bf7-8159-0b02f578a38a', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Why is the partial carnivorous adaptation in Drosera (Sundew) and Utricularia (Bladderwort) considered an evolutionary masterpiece?', 'Carnivory circumvents soil nitrogen/phosphorus limitations in bogs through enzymatic breakdown of captured arthropod biomass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5566dda2-1cc1-476b-b302-89af2f192433', 'It allows plants to colonize ultra-oligotrophic, waterlogged, and nutrient-poor wetlands where competing non-carnivorous autotrophs cannot survive due to nitrogen starvation', true, '93c3b513-082d-4bf7-8159-0b02f578a38a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27bd94ac-7136-46b8-bc27-c3302a8b3aaa', 'Because it turns the plants into active animals', false, '93c3b513-082d-4bf7-8159-0b02f578a38a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('970eeb96-6b11-43d0-a3bc-28fb9263dfd9', 'Because they no longer require any water or carbon dioxide', false, '93c3b513-082d-4bf7-8159-0b02f578a38a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f4b3745-e7a4-4fa6-bae8-e4ac0609579f', 'Because they live underground without light', false, '93c3b513-082d-4bf7-8159-0b02f578a38a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7717bd76-0e8f-45fa-8d54-5e872019627d', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Why do underwater submerged aquatic plants (like Hydrilla and Vallisneria) have narrow ribbon-like leaves and lack stomatal pores with cuticles?', 'Hydrophytic adaptations eliminate stomata/cuticles to allow direct trans-epidermal diffusion of dissolved aquatic gases.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ae2173-c0c4-4964-8f3d-ed77a238dd43', 'Narrow flexible leaves withstand flowing water currents without tearing, and dissolved gases (CO₂ and O₂) diffuse directly across thin epidermal cell walls', true, '7717bd76-0e8f-45fa-8d54-5e872019627d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2f54cc6-73c9-44ef-9906-e523ef3248af', 'Because they do not need any carbon dioxide', false, '7717bd76-0e8f-45fa-8d54-5e872019627d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('416b0383-fa14-4b94-a941-342e2211f15f', 'To avoid being eaten by sharks', false, '7717bd76-0e8f-45fa-8d54-5e872019627d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75958c5b-76f0-4f1a-b273-edf7e4578a74', 'Because they only absorb food from soil', false, '7717bd76-0e8f-45fa-8d54-5e872019627d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8d3d864-31e5-4160-b336-a318391b7851', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Consider four experimental setups of potted plants:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f225fa7-4ee5-4c26-804d-cfe03ff32008', 'Sets 2 and 4 only', true, 'e8d3d864-31e5-4160-b336-a318391b7851');
