INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f9ce31c-912b-44e6-a095-ea6e3a7a69b2', 'All 4 Sets', false, 'e8d3d864-31e5-4160-b336-a318391b7851');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('346365da-af3c-445a-be50-12c93651e699', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'How do Lichens serve as sensitive ''Bio-indicators'' of atmospheric air quality in environmental monitoring?', 'Lacking roots and protective cuticles, symbiotic lichens hyper-absorb atmospheric SO₂, serving as classic biological air quality monitors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf9ce150-d948-46ae-aee4-9fa71ac821fb', 'Lichens are extraordinarily sensitive to toxic atmospheric Sulfur Dioxide (SO₂) air pollution and cannot survive in heavily polluted urban/industrial areas', true, '346365da-af3c-445a-be50-12c93651e699');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5732f3a-0a8f-4442-9e4e-5757d2455c48', 'They change their color to neon purple in clean air', false, '346365da-af3c-445a-be50-12c93651e699');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bcdb195-1aca-49c6-bb7d-12d4a91e9151', 'They absorb plastic from the air', false, '346365da-af3c-445a-be50-12c93651e699');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12514f9c-2a6d-4a36-8887-9102722d9280', 'They only grow on factory chimneys', false, '346365da-af3c-445a-be50-12c93651e699');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('185c7a61-dae6-4761-8f38-3d89699dc752', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'What is the precise cellular organelle inside green plant mesophyll cells where photosynthesis takes place?', 'Chloroplasts contain thylakoid membranes with light-harvesting chlorophyll and stroma enzymes for Calvin cycle carbohydrate synthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6211f41-f2d0-4132-856c-1c89ac5b4694', 'Chloroplast', true, '185c7a61-dae6-4761-8f38-3d89699dc752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76c2e684-1f38-4595-b4cf-2a5c443cf401', 'Mitochondria', false, '185c7a61-dae6-4761-8f38-3d89699dc752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afdf1e8a-988f-4cb1-8f85-5a4b725e38ca', 'Ribosome', false, '185c7a61-dae6-4761-8f38-3d89699dc752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b2c46be-d31c-4ad9-83c0-7b2848c2f90c', 'Golgi apparatus', false, '185c7a61-dae6-4761-8f38-3d89699dc752');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c591a5f3-fc73-491a-a60d-a9ffcd47af30', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'What biochemical transformation happens to glucose molecules immediately after synthesis in leaf mesophyll cells?', 'Soluble osmotic glucose is condensed into insoluble, non-reactive amylose/amylopectin starch grains for osmotic equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b68a148-74e3-4520-a3b3-2946e697a340', 'Excess glucose is rapidly polymerized into insoluble complex Starch for compact long-term storage and later translocated as sucrose via phloem', true, 'c591a5f3-fc73-491a-a60d-a9ffcd47af30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c9f419d-9ef1-44d5-8fde-f0b9eca3268a', 'Glucose turns into pure gold crystals', false, 'c591a5f3-fc73-491a-a60d-a9ffcd47af30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02ba49fc-a46c-46c3-84e0-d74c969d26b2', 'It evaporates immediately into the sky', false, 'c591a5f3-fc73-491a-a60d-a9ffcd47af30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04ef1f3e-8438-4ea7-8561-0940d5464e6c', 'It converts into toxic carbon monoxide', false, 'c591a5f3-fc73-491a-a60d-a9ffcd47af30');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fc0bf3d-2200-439d-9325-327faae9022e', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'What overarching biological principle is illuminated in Chapter 1 of NCERT Class 7 Science?', 'Chapter 1 establishes plant autotrophy and ecological symbiosis as the foundational energy conduit of terrestrial biomes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f22f29b7-ae60-489b-af5f-8c2098683150', 'Autotrophic green plants form the indispensable biological bedrock of terrestrial life, sustaining global biogeochemical energy flow, oxygen renewal, and complex symbiotic networks', true, '2fc0bf3d-2200-439d-9325-327faae9022e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12ef0ae4-a4c6-40fa-929e-b5f677f88d06', 'Plants depend completely on animals for all their food', false, '2fc0bf3d-2200-439d-9325-327faae9022e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71b0054d-e8a6-4900-ba4d-29e7f1d2946a', 'Parasitic plants are the only beneficial organisms in nature', false, '2fc0bf3d-2200-439d-9325-327faae9022e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6383e0c-a9f8-400f-ab1c-5001ab16d1f3', 'Soil fertility never requires any replenishment', false, '2fc0bf3d-2200-439d-9325-327faae9022e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cda05ca7-c132-4315-9104-f55bff36ec09', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Easy', 'What is the result of evaluating: (-8) + (-7)?', 'Adding two negative integers yields a negative sum: (-8) + (-7) = -(8 + 7) = -15.', NOW()) ON CONFLICT DO NOTHING;
