INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7dc93579-3e22-4cb4-9ad7-5839c4d4ff0f', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Easy', 'What happens when ANY integer ''a'' is divided by ZERO (a ÷ 0)?', 'Division by zero has no mathematical definition and is undefined for all integers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93d1eb9b-6499-4b0f-acfc-f8cfd3119e3d', 'Division by zero is UNDEFINED (Meaningless in mathematics)', true, '7dc93579-3e22-4cb4-9ad7-5839c4d4ff0f');
