INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e03d7133-2b80-466b-a491-c47c145d64ee', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Easy', 'What is 0 divided by any non-zero integer ''a'' (0 ÷ a)?', '0 divided by any non-zero integer is always 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d4309df-26f0-41b6-bb41-f38040d1e7eb', '0 (Zero)', true, 'e03d7133-2b80-466b-a491-c47c145d64ee');
