INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f94f7b7-46c3-4daa-9b8a-061a2edb52c5', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Easy', 'What is the product of multiplying ANY integer ''a'' with ZERO: a × 0?', 'Any integer multiplied by zero equals zero (multiplicative property of zero).', NOW()) ON CONFLICT DO NOTHING;
