INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cd24eae-dca1-48f0-9808-18d7402b52a0', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Evaluate using the Distributive Property of multiplication over addition:
(-25) × [ 37 + (-17) ]', '(-25) × (37 - 17) = (-25) × 20 = -500.', NOW()) ON CONFLICT DO NOTHING;
