INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2854a277-bcc1-4301-840b-19e9f53c606a', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Evaluate using suitable property:
(-48) × 105', '(-48) × (100 + 5) = (-48 × 100) + (-48 × 5) = -4800 - 240 = -5040.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6886966c-2b79-4582-9b49-f89f6ec3d944', '-5040 ((-48) × (100 + 5) = (-4800) + (-240) = -5040)', true, '2854a277-bcc1-4301-840b-19e9f53c606a');
