INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba82e25c-77f7-4b86-bfef-11a6aa540aab', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Find the product: (-1) × (-2) × (-3) × (-4) × (-5):', 'There are 5 negative factors (odd count) → product is negative: -(1 × 2 × 3 × 4 × 5) = -120.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af40e6da-f764-4550-9bc9-349f31e013dd', '-120 (Multiplying an ODD number (5) of negative signs yields a NEGATIVE result)', true, 'ba82e25c-77f7-4b86-bfef-11a6aa540aab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3993b8ef-d8db-42b8-9fc9-5f008e99eb19', '+120', false, 'ba82e25c-77f7-4b86-bfef-11a6aa540aab');
