INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca7a9885-046a-49ce-b0af-584064c23315', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Find the product: (-2) × (-5) × (-4) × (-10):', '4 negative factors (even count) → product is positive: +(2 × 5 × 4 × 10) = +400.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfe95ab6-9a10-44e0-9ff2-6e6ca9ac6842', '+400 (Multiplying an EVEN number (4) of negative signs yields a POSITIVE result)', true, 'ca7a9885-046a-49ce-b0af-584064c23315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73c4eff5-a284-48c7-b16d-00898657d895', '-400', false, 'ca7a9885-046a-49ce-b0af-584064c23315');
