INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('143ca73e-1d3d-4a5a-9574-3731f41de720', '-200', false, 'ca7a9885-046a-49ce-b0af-584064c23315');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad7c7419-bfde-4213-be7d-ab068dc0ce08', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'In a class test containing 15 questions, 4 marks are given for every correct answer and (-2) marks are given for every incorrect answer. Gurpreet attempts all questions but only 9 of her answers are correct. What is her total score?', 'Correct marks = 9 × 4 = 36. Incorrect marks = (15 - 9) × (-2) = -12. Total = 36 - 12 = 24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c3d1d36-c34f-4d3c-aa99-c93d5488435f', '24 marks (Correct = 9 × 4 = 36 ; Incorrect = 6 × (-2) = -12 ; Total = 36 + (-12) = 24)', true, 'ad7c7419-bfde-4213-be7d-ab068dc0ce08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff781960-9548-4786-bb33-3263fcd967e0', '36 marks', false, 'ad7c7419-bfde-4213-be7d-ab068dc0ce08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('753522f8-908c-42ef-8318-cbcf6f8c43f8', '12 marks', false, 'ad7c7419-bfde-4213-be7d-ab068dc0ce08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c69a23d-b65f-4d73-9770-596296433ca4', '30 marks', false, 'ad7c7419-bfde-4213-be7d-ab068dc0ce08');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17fcc6da-a02c-47a3-a6fb-0b5bec95aaf1', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'In the same test (4 marks for correct, -2 for incorrect), one of Gurpreet''s friends gets only 5 answers correct out of 15 attempted questions. What is her friend''s total score?', 'Score = (5 × 4) + (10 × (-2)) = 20 - 20 = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14298d42-c738-40a6-a785-edb70fdcd8dc', '0 marks (Correct = 5 × 4 = 20 ; Incorrect = 10 × (-2) = -20 ; Total = 20 + (-20) = 0)', true, '17fcc6da-a02c-47a3-a6fb-0b5bec95aaf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72095305-4141-4377-b120-037387f888ee', '20 marks', false, '17fcc6da-a02c-47a3-a6fb-0b5bec95aaf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09618940-b5b0-4ccf-8535-fe932d1cd9ad', '-10 marks', false, '17fcc6da-a02c-47a3-a6fb-0b5bec95aaf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2f1fc7e-afc8-4997-8f19-53b9eaa46934', '10 marks', false, '17fcc6da-a02c-47a3-a6fb-0b5bec95aaf1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('813b4e09-7ef9-48d7-a96f-3208d6d8e283', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'An elevator descends into a mine shaft at the rate of 6 metres per minute. If the descent starts from 10 m ABOVE the ground level, how long will it take to reach -350 m (350 m below ground)?', 'Total vertical drop = 10 - (-350) = 360 m. Time = 360 ÷ 6 = 60 minutes = 1 hour.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38846871-480e-49bd-bb5d-17f1ce5e5b8e', '60 minutes (1 hour) (Total distance = 10 - (-350) = 360 m ; Time = 360 / 6 = 60 minutes)', true, '813b4e09-7ef9-48d7-a96f-3208d6d8e283');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea6c7be3-05bd-4e39-b232-223a1aa8937c', '50 minutes', false, '813b4e09-7ef9-48d7-a96f-3208d6d8e283');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17f49759-f504-43c7-b762-2fe05ac127ee', '45 minutes', false, '813b4e09-7ef9-48d7-a96f-3208d6d8e283');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e42247b-18c1-418c-ae26-aec7991886dc', '70 minutes', false, '813b4e09-7ef9-48d7-a96f-3208d6d8e283');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49628c08-8ebe-4bca-be0c-1e04a38267e8', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'At Srinagar, the temperature was -5°C on Monday and then it dropped by 2°C on Tuesday. What was the temperature of Srinagar on Tuesday? On Wednesday, it rose by 4°C. What was the temperature on Wednesday?', 'Tuesday = -5 - 2 = -7°C. Wednesday = -7 + 4 = -3°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46b4afb4-aad1-41e2-941b-2b94864b405f', 'Tuesday: -7°C ; Wednesday: -3°C', true, '49628c08-8ebe-4bca-be0c-1e04a38267e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfffb6cf-9429-4d59-9f1d-9a51f61d8bde', 'Tuesday: -3°C ; Wednesday: +1°C', false, '49628c08-8ebe-4bca-be0c-1e04a38267e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d05080f-6432-4652-a681-a4a29a6caacc', 'Tuesday: -7°C ; Wednesday: +4°C', false, '49628c08-8ebe-4bca-be0c-1e04a38267e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12dac399-e583-4a82-bd11-1c00535f4fb2', 'Tuesday: -10°C ; Wednesday: -6°C', false, '49628c08-8ebe-4bca-be0c-1e04a38267e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a02090f9-71d3-4c50-9218-51d0b69ab60b', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'A cement company earns a profit of ₹8 per bag of white cement sold and a loss of ₹5 per bag of grey cement sold. If the company sells 3,000 bags of white cement and 5,000 bags of grey cement in a month, what is its net profit or loss?', 'Profit on white = 3000 × 8 = ₹24,000. Loss on grey = 5000 × 5 = ₹25,000. Net = 24,000 - 25,000 = -₹1,000 (Loss).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0525fafb-7a77-4ec0-8649-3be57511df77', 'Loss of ₹1,000 (Profit = 3000 × 8 = ₹24,000 ; Loss = 5000 × (-5) = -₹25,000 ; Net = 24,000 - 25,000 = -₹1,000)', true, 'a02090f9-71d3-4c50-9218-51d0b69ab60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68e58ba1-bb5c-4bac-8b67-ca430c7943ea', 'Profit of ₹1,000', false, 'a02090f9-71d3-4c50-9218-51d0b69ab60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e603f5a6-13f3-4725-afa6-54f5f65138c3', 'Profit of ₹24,000', false, 'a02090f9-71d3-4c50-9218-51d0b69ab60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('882585a1-0ea8-469b-ba67-72ff9b0e9553', 'Loss of ₹5,000', false, 'a02090f9-71d3-4c50-9218-51d0b69ab60b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2f9d9b8-570d-49ff-8199-2d001ab30ac2', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'In the same cement problem (₹8 profit/white bag, ₹5 loss/grey bag), how many white cement bags must the company sell to have neither profit nor loss if the number of grey bags sold is 6,400 bags?', 'Total loss = 6400 × 5 = ₹32,000. Required white bags = 32000 ÷ 8 = 4,000 bags.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ce3f2dd-6db6-4a0f-beef-5c52f18e1b15', '4,000 bags (Loss on grey = 6400 × 5 = ₹32,000 ; White bags needed = 32,000 / 8 = 4,000 bags)', true, 'b2f9d9b8-570d-49ff-8199-2d001ab30ac2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a771faa-6fc0-44d7-b6ec-561385659839', '3,200 bags', false, 'b2f9d9b8-570d-49ff-8199-2d001ab30ac2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31b40902-f1fc-44c3-a8be-d5316963b423', '5,000 bags', false, 'b2f9d9b8-570d-49ff-8199-2d001ab30ac2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56deb76a-1566-4e1e-8065-df98e2929efc', '4,800 bags', false, 'b2f9d9b8-570d-49ff-8199-2d001ab30ac2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c9d5b7f-ecc3-490c-9cd8-7a7db6f17350', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Fill in the blank with suitable integer: (-3) × [ _____ ] = +27', 'Missing integer = 27 ÷ (-3) = -9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c2da14e-3b3b-4db3-9d2e-0b33fdf814ab', '-9 (Since (-3) × (-9) = +27)', true, '0c9d5b7f-ecc3-490c-9cd8-7a7db6f17350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e4834c7-c8a7-4ef8-96f4-9c33abfd6060', '+9', false, '0c9d5b7f-ecc3-490c-9cd8-7a7db6f17350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef3148bf-8274-4845-8093-7914ea21b065', '-30', false, '0c9d5b7f-ecc3-490c-9cd8-7a7db6f17350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b012d4d3-6d3a-458f-a2a6-f7ce6777e563', '+30', false, '0c9d5b7f-ecc3-490c-9cd8-7a7db6f17350');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8eb548a0-7356-49be-a6c9-cccb4c145953', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Fill in the blank with suitable integer: [ _____ ] ÷ (-12) = -8', 'Missing integer = (-8) × (-12) = +96.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b4cd3da-1e80-4463-a0b6-5f1c11785e27', '+96 (Since 96 ÷ (-12) = -8)', true, '8eb548a0-7356-49be-a6c9-cccb4c145953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fb0509b-3ffa-49c7-8c66-3bfca586ff1f', '-96', false, '8eb548a0-7356-49be-a6c9-cccb4c145953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4b9b511-d652-4e09-92ad-d2aed4a95a31', '+20', false, '8eb548a0-7356-49be-a6c9-cccb4c145953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12bcee10-79a6-400f-9c22-50a95c52e3bf', '-4', false, '8eb548a0-7356-49be-a6c9-cccb4c145953');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a8769f3-9e50-48d8-888a-c4c602934807', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Which of the following mathematical properties holds strictly TRUE for Division of Integers?', 'Division of integers violates both commutative property (a ÷ b ≠ b ÷ a) and associative property.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8625d12e-ec26-4e98-90bd-e0c5b58232ba', 'Division is NOT Commutative and NOT Associative for integers (e.g. 8 ÷ (-4) ≠ (-4) ÷ 8)', true, '0a8769f3-9e50-48d8-888a-c4c602934807');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63235862-f183-4de8-835a-3fc0a343f249', 'Division is Commutative for integers', false, '0a8769f3-9e50-48d8-888a-c4c602934807');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9bbb4de-089a-43b9-9342-ca72b88d46f0', 'Division is Associative for integers', false, '0a8769f3-9e50-48d8-888a-c4c602934807');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0cac200-473f-4d48-befd-a803217e3e43', 'Division by zero equals zero', false, '0a8769f3-9e50-48d8-888a-c4c602934807');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97878220-c8f1-4732-b25b-c4275ac7d1e3', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Evaluate: [ (-30) ÷ 10 ] ÷ 3', '(-30 ÷ 10) ÷ 3 = (-3) ÷ 3 = -1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9f3bdf9-4f73-490c-9e98-3f5e5ef28386', '-1 (Inside bracket: -30 ÷ 10 = -3 ; -3 ÷ 3 = -1)', true, '97878220-c8f1-4732-b25b-c4275ac7d1e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('839fd983-0272-480b-a0b8-c31b66f4cbc3', '+1', false, '97878220-c8f1-4732-b25b-c4275ac7d1e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e18dd0f-b022-4172-a2a3-cf08ae867c9c', '-9', false, '97878220-c8f1-4732-b25b-c4275ac7d1e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be2d4e02-826c-4753-9b35-2bd4fcd0eaad', '+9', false, '97878220-c8f1-4732-b25b-c4275ac7d1e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ad3f715-7ee7-4aeb-bf59-82c0321f241a', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Evaluate: [ (-6) + 5 ] ÷ [ (-2) + 1 ]', '(-6 + 5) ÷ (-2 + 1) = (-1) ÷ (-1) = +1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51b2f173-3593-40fe-acdc-b3f796df0294', '+1 (Numerator: -1 ; Denominator: -1 ; -1 ÷ -1 = +1)', true, '1ad3f715-7ee7-4aeb-bf59-82c0321f241a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67cdfd25-0fe9-49f6-9db0-e7c1663f5652', '-1', false, '1ad3f715-7ee7-4aeb-bf59-82c0321f241a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99aa963a-7902-4321-9329-622beaa2607e', '+2', false, '1ad3f715-7ee7-4aeb-bf59-82c0321f241a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62897c8d-88ae-4d00-925b-f738ac75eab4', '-2', false, '1ad3f715-7ee7-4aeb-bf59-82c0321f241a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e801211-ef17-43cb-9730-71175b41bff7', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'The temperature at 12 noon was 10°C above zero (+10°C). If it decreases at the rate of 2°C per hour until midnight, at what time will the temperature be 8°C below zero (-8°C)?', 'Total temperature drop = 10 - (-8) = 18°C. Time = 18 ÷ 2 = 9 hours. 12 noon + 9h = 9:00 PM.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46fa5cb7-8e93-41da-bfae-801f7b9c3ea9', '9:00 PM (Total decrease = 10 - (-8) = 18°C ; Hours required = 18 / 2 = 9 hours ; 12 noon + 9 hours = 9 PM)', true, '9e801211-ef17-43cb-9730-71175b41bff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('848bd339-8692-408f-9229-a0bb4b2ba867', '8:00 PM', false, '9e801211-ef17-43cb-9730-71175b41bff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02d3ae8d-431f-4652-b680-208cf02a32fe', '10:00 PM', false, '9e801211-ef17-43cb-9730-71175b41bff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a05ff29-58ed-41eb-8c36-c6f94fa3fa18', '11:00 PM', false, '9e801211-ef17-43cb-9730-71175b41bff7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2392acaa-7ab2-4f3a-951a-6db82e8177d9', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7634ee03-4013-4cfd-b19d-b7a30092f964', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '2392acaa-7ab2-4f3a-951a-6db82e8177d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4609364b-e112-4aad-a230-60eea1ce8195', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '2392acaa-7ab2-4f3a-951a-6db82e8177d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0062d43c-5dc3-47b0-9b5f-033c876b9f38', '(A) is true, but (R) is false.', false, '2392acaa-7ab2-4f3a-951a-6db82e8177d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6abe5fcf-7445-4296-88b5-13e880b65c52', '(A) is false, but (R) is true.', false, '2392acaa-7ab2-4f3a-951a-6db82e8177d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef5c49c4-4ca5-4a75-851b-27a56c8fffd6', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Spot the IMPOSTER among the following statements regarding Integer Properties:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c9f51f1-96b3-4665-b31b-245679bd08b6', 'Statement 1', false, 'ef5c49c4-4ca5-4a75-851b-27a56c8fffd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2199ca2f-e838-4cb7-865b-767efe76f02d', 'Statement 2', false, 'ef5c49c4-4ca5-4a75-851b-27a56c8fffd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('650f7850-34ad-4cd4-8acd-efb5248f3682', 'Statement 3 (Subtraction is NOT commutative for integers)', true, 'ef5c49c4-4ca5-4a75-851b-27a56c8fffd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9177c384-6221-4685-bbc3-0d046f109f26', 'Statement 4', false, 'ef5c49c4-4ca5-4a75-851b-27a56c8fffd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d996609-c7db-4956-99b8-f0dd1cff4697', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Evaluate the nested integer expression:
(-1) × (-1) × (-1) × ... (multiplied 99 times) + (-1) × (-1) × (-1) × ... (multiplied 100 times):', '(-1) raised to an odd power (99) is -1. (-1) raised to an even power (100) is +1. (-1) + (+1) = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('422868a0-0067-485e-92b9-fb0de506520f', '0 ((-1)^99 = -1 and (-1)^100 = +1 ; Sum = -1 + 1 = 0)', true, '8d996609-c7db-4956-99b8-f0dd1cff4697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a549decb-7812-43f4-864e-7e206f49042c', '-2', false, '8d996609-c7db-4956-99b8-f0dd1cff4697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c74c101-847f-42d2-a6bc-5644c2e7f57f', '+2', false, '8d996609-c7db-4956-99b8-f0dd1cff4697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('344a1278-1685-4652-988f-1bc8250b1c81', '-1', false, '8d996609-c7db-4956-99b8-f0dd1cff4697');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('557452cc-5b47-4e90-bdb9-7be31e8aa533', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Match Column I (Algebraic Integer Identity) with Column II (Name of Property):
(a) a + b = b + a              -> (i) Associative Property of Addition
(b) a × (b × c) = (a × b) × c  -> (ii) Distributive Property of Multiplication over Addition
(c) (a + b) + c = a + (b + c)  -> (iii) Commutative Property of Addition
(d) a × (b + c) = ab + ac      -> (iv) Associative Property of Multiplication', 'a+b = b+a (Commutative +); a(bc) = (ab)c (Associative ×); (a+b)+c = a+(b+c) (Associative +); a(b+c) = ab+ac (Distributive).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97fd781e-8863-4771-9e58-2b75b89730d2', 'a-(iii), b-(iv), c-(i), d-(ii)', true, '557452cc-5b47-4e90-bdb9-7be31e8aa533');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cbd6f1f-519c-44ec-a19c-b229c1808350', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '557452cc-5b47-4e90-bdb9-7be31e8aa533');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e16b02f-e836-4ca4-bd22-6ba103310a92', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '557452cc-5b47-4e90-bdb9-7be31e8aa533');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d52d6399-ab85-43dd-89d6-5cd941955879', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '557452cc-5b47-4e90-bdb9-7be31e8aa533');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('096364ba-d3a3-4ebf-a31f-0775ecd726c9', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Read the statements regarding integer verification:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be264ffb-ffb0-4db9-a926-3a00c383203e', 'Statements 1 and 2 only', true, '096364ba-d3a3-4ebf-a31f-0775ecd726c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e95e04a-c4d7-4fc6-98d0-28a0441c515d', 'Statements 2 and 3 only', false, '096364ba-d3a3-4ebf-a31f-0775ecd726c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fbf172e-bff2-4975-b081-f6bf4b73a845', 'Statements 1 and 3 only', false, '096364ba-d3a3-4ebf-a31f-0775ecd726c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e38a23dc-0d37-479a-9dc1-06003324373d', 'All Statements 1, 2, and 3', false, '096364ba-d3a3-4ebf-a31f-0775ecd726c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('efbcf0f4-b1bf-4ba0-9e78-03875365a228', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'If a = -8, b = -7, and c = 6, verify the value of (a + b) + c and a + (b + c):', '(-8 + -7) + 6 = -15 + 6 = -9. -8 + (-7 + 6) = -8 + (-1) = -9. Confirms Associative Property of Addition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7517ba2-a4d5-4273-86a1-ec3aba1f4641', 'Both equal -9 (((-8 + -7) + 6 = -15 + 6 = -9) and (-8 + (-7 + 6) = -8 + -1 = -9))', true, 'efbcf0f4-b1bf-4ba0-9e78-03875365a228');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9814669-03de-40d0-8655-fd908cdaf167', 'Both equal +9', false, 'efbcf0f4-b1bf-4ba0-9e78-03875365a228');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8326e2d-f7a8-4bfa-9699-ed6e6d15aa6e', 'First is -9, second is +5', false, 'efbcf0f4-b1bf-4ba0-9e78-03875365a228');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcf0de5e-94a1-4bad-9f00-dbc3d628d1e0', 'Both equal -21', false, 'efbcf0f4-b1bf-4ba0-9e78-03875365a228');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82bbde05-a66f-4a50-b3b2-b4cc312d144b', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Solve for x: (-15) × [ x + (-3) ] = (-15) × 8 + (-15) × (-3)', 'Comparing with Distributive law a × (b + c) = ab + ac: here a = -15, b = x = 8, c = -3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a14e5f1-480d-48c4-aeb8-cb9b07e6ff77', 'x = 8 (By the Distributive Property: a × (x + b) = a × x + a × b ⇒ x = 8)', true, '82bbde05-a66f-4a50-b3b2-b4cc312d144b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb4c7b6d-9e7f-445c-b72e-4959ba35d12b', 'x = -8', false, '82bbde05-a66f-4a50-b3b2-b4cc312d144b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd854036-eea4-49fe-8b50-d74b37d3d3a7', 'x = 3', false, '82bbde05-a66f-4a50-b3b2-b4cc312d144b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d79044b-1d7d-4a5e-8ebf-be60eef85d6f', 'x = -3', false, '82bbde05-a66f-4a50-b3b2-b4cc312d144b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42c67213-4ada-4e20-8e85-71c42e83d9c8', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'A submarine is cruising at a depth of -650 m below sea level. It ascends 230 m, then dives down 180 m, and finally ascends 320 m. What is the final operating depth of the submarine relative to sea level?', '-650 + 230 - 180 + 320 = -420 - 180 + 320 = -600 + 320 = -280 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5d98088-6de1-48db-a97c-9707f09f0b1e', '-280 m below sea level (-650 + 230 - 180 + 320 = -280 m)', true, '42c67213-4ada-4e20-8e85-71c42e83d9c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('155631e2-bb3f-4917-85f8-576bee3bf7fb', '-320 m below sea level', false, '42c67213-4ada-4e20-8e85-71c42e83d9c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a86e0e68-0b2e-4857-a87e-010eed8e287c', '-410 m below sea level', false, '42c67213-4ada-4e20-8e85-71c42e83d9c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3023e587-7eef-4d68-9782-f1d1b46c1eb9', '-180 m below sea level', false, '42c67213-4ada-4e20-8e85-71c42e83d9c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62544203-9537-4609-a6f2-43f1391e858c', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Evaluate: (-325) × (-45) + (-325) × (-55)', 'Factoring out -325: (-325) × [(-45) + (-55)] = (-325) × (-100) = +32,500.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51042568-efba-4006-866f-0c73f024b98c', '+32,500 ((-325) × [(-45) + (-55)] = (-325) × (-100) = +32,500)', true, '62544203-9537-4609-a6f2-43f1391e858c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17843713-bd1d-48f3-a9cb-172851672de1', '-32,500', false, '62544203-9537-4609-a6f2-43f1391e858c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('349d5013-3ae9-45d3-b195-025323b6aa62', '+3,250', false, '62544203-9537-4609-a6f2-43f1391e858c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a7c1d53-af08-4928-8f3f-5c4443dfed67', '-3,250', false, '62544203-9537-4609-a6f2-43f1391e858c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('328be957-7bfe-48a3-b72e-b24c88f0cc74', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'In a 20-question math competition, +5 marks are awarded for each correct answer, -3 marks for each incorrect answer, and 0 for unattempted questions. Rohan attempted 18 questions and got 14 correct. Priya attempted all 20 questions and got 15 correct. Who scored higher and by how many marks?', 'Rohan = 14×5 + 4×(-3) = 70 - 12 = 58. Priya = 15×5 + 5×(-3) = 75 - 15 = 60. Priya scored 60 vs 58 (+2 marks higher).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b0be578-98b6-4b99-bb42-8e75ed6dbb8d', 'Rohan scored higher by 2 marks (Rohan: 14(5) + 4(-3) = 70 - 12 = 58 ; Priya: 15(5) + 5(-3) = 75 - 15 = 60 ... Wait: Priya = 60, Rohan = 58 ⇒ Priya is higher by 2 marks)', false, '328be957-7bfe-48a3-b72e-b24c88f0cc74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c691dc04-425d-44d8-b455-5d9556d431a6', 'Priya scored higher by 2 marks (Priya: 15(5) + 5(-3) = 60 ; Rohan: 14(5) + 4(-3) = 58 ; Priya is higher by 2 marks)', true, '328be957-7bfe-48a3-b72e-b24c88f0cc74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7d72113-25e1-44a7-847f-a44deeed140a', 'Both scored exactly the same', false, '328be957-7bfe-48a3-b72e-b24c88f0cc74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44a40cd6-bfaf-43ee-8cd7-00c2c4575bb1', 'Rohan is higher by 5 marks', false, '328be957-7bfe-48a3-b72e-b24c88f0cc74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77132b31-547a-4603-a101-420d8074e7ba', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'If the product of two integers is -180 and one of the integers is +12, find the sum of the two integers:', 'Other integer = -180 ÷ 12 = -15. Sum = 12 + (-15) = -3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed2112fa-1708-4194-a818-9c77b427f49a', '-3 (Second integer = -180 / 12 = -15 ; Sum = 12 + (-15) = -3)', true, '77132b31-547a-4603-a101-420d8074e7ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50f1869d-be84-43e4-bba7-9903bb4a42b5', '+3', false, '77132b31-547a-4603-a101-420d8074e7ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f79c9782-38bd-4e28-9463-40dc13529497', '-27', false, '77132b31-547a-4603-a101-420d8074e7ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('156270d4-bd58-4da2-9d5a-bec8b5d77cca', '+27', false, '77132b31-547a-4603-a101-420d8074e7ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd334249-b76f-43a4-85b8-f92922717837', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Why is the complete mastery of Integers and their sign algebraic laws fundamental to all future mathematics (algebra, coordinate geometry, calculus, and computing)?', 'Integers provide the foundational algebraic ring (ℤ, +, ×) modeling directed quantities, vectors, and sign arithmetic in higher mathematics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd092368-c57c-4dcb-b940-05762639fda8', 'It establishes bidirectional numerical continuity across positive and negative domains, vector magnitudes, directed quantities, and rigorous symbolic operations', true, 'bd334249-b76f-43a4-85b8-f92922717837');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c831ff5a-810a-4cda-a906-51a1fc49cd29', 'Because negative numbers only exist in bank debts', false, 'bd334249-b76f-43a4-85b8-f92922717837');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80956f3c-ee68-4175-9988-ace0e558ce63', 'Because integers eliminate the need for multiplication', false, 'bd334249-b76f-43a4-85b8-f92922717837');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cea66f33-113a-4876-b19e-ba3cb72fe84f', 'Because only positive numbers are used in science', false, 'bd334249-b76f-43a4-85b8-f92922717837');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f34e1ad-7be8-44b7-a343-6c23e742f9f7', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'In Leo Tolstoy''s famous story ''Three Questions'', what were the three fundamental questions the King wanted answers to?', 'Tolstoy''s king sought wisdom on: right time to act, right people to heed, and most crucial enterprise to undertake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18c0d389-d4d0-4a31-a8cf-14d5148d7381', '1. What is the right time to begin something? 2. Which people should he listen to? 3. What is the most important thing for him to do?', true, '1f34e1ad-7be8-44b7-a343-6c23e742f9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90bbbcc8-033a-438e-94b7-ba288c8716a6', '1. How to defeat enemies? 2. How much gold to collect? 3. Where to build castles?', false, '1f34e1ad-7be8-44b7-a343-6c23e742f9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4952e4c-74eb-4aed-86b8-5aa81203e6e4', '1. When to sleep? 2. What to eat? 3. How to ride horses?', false, '1f34e1ad-7be8-44b7-a343-6c23e742f9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3343530e-04b6-4389-b16c-f889fbd882e3', '1. Who is the richest king? 2. Where is the magic cave? 3. How to live forever?', false, '1f34e1ad-7be8-44b7-a343-6c23e742f9f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f79a34de-8842-41aa-98ee-dc23cf6d7dce', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'Whom did the King decide to visit in the deep forest to seek true wisdom after being dissatisfied with the wise men''s conflicting answers?', 'The king disguised himself in simple peasant clothing and left his horse behind to consult the forest hermit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6955986a-0677-419d-93a5-ad3c31b51cec', 'A simple, wise Hermit who lived alone in a hut in the woods and received only common folk', true, 'f79a34de-8842-41aa-98ee-dc23cf6d7dce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d558e92d-33df-499a-afcd-4ae8f38ec3e5', 'A powerful sorcerer with a crystal ball', false, 'f79a34de-8842-41aa-98ee-dc23cf6d7dce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c71fbb-54ac-409e-89a7-92289a7988f8', 'An astrologer in the royal palace', false, 'f79a34de-8842-41aa-98ee-dc23cf6d7dce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97a08f9c-8d9f-4f07-b770-a81b1299e1a6', 'A foreign emperor', false, 'f79a34de-8842-41aa-98ee-dc23cf6d7dce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6b932ee-63b1-42d6-835d-59c85c7469ad', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'What was the frail, old Hermit doing when the King arrived at his forest hut?', 'The hermit was laboriously digging flower/seed beds in front of his hut, breathing heavily from physical exertion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e21d53ba-6ded-404e-a92b-7d43f8aac785', 'Digging ground beds in front of his hut with a spade', true, 'c6b932ee-63b1-42d6-835d-59c85c7469ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2672d15-c2ed-45df-a711-29f6d50439e3', 'Sleeping under a tree', false, 'c6b932ee-63b1-42d6-835d-59c85c7469ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81ee0cb6-cd50-44e0-86d2-c1a4b7d1c876', 'Reading a large book', false, 'c6b932ee-63b1-42d6-835d-59c85c7469ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('342cb78e-4f47-466a-bc84-831ea693f1ef', 'Cooking soup', false, 'c6b932ee-63b1-42d6-835d-59c85c7469ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('201e74cb-08fd-4a06-85dc-fca3fe4d5ca7', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'How did the King help the exhausted Hermit upon arrival?', 'Seeing the hermit''s frailty, the king took the spade and dug the ground tirelessly until evening.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22902629-dbc3-4f6c-bf84-f31b76d95a28', 'The King took the heavy spade from the hermit''s hands and dug the ground beds for him until sunset', true, '201e74cb-08fd-4a06-85dc-fca3fe4d5ca7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13ef02d0-df08-48e6-88c5-a791553cbf58', 'He gave the hermit a bag of gold', false, '201e74cb-08fd-4a06-85dc-fca3fe4d5ca7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('271c5a34-ad37-4445-8eb3-0cec7503779a', 'He ordered his soldiers to carry the hermit', false, '201e74cb-08fd-4a06-85dc-fca3fe4d5ca7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('132afc5a-5dcc-47aa-8716-aed0ae48c83b', 'He sat down and watched the hermit struggle', false, '201e74cb-08fd-4a06-85dc-fca3fe4d5ca7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c91807a9-b954-49f0-a965-1a0fd9555f7b', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'Who came running out of the dark woods towards the King and the Hermit with hands pressed against his bleeding stomach?', 'A bearded wounded man ran out of the forest, fainting and bleeding profusely from a severe abdominal wound.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66e5a17d-d512-4af1-8f22-9d560bc00ac8', 'A bearded man who was severely wounded by the King''s royal bodyguards', true, 'c91807a9-b954-49f0-a965-1a0fd9555f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19c4f746-6f47-4ff0-a1e3-45dd977dbba6', 'A wild forest tiger', false, 'c91807a9-b954-49f0-a965-1a0fd9555f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63267129-320c-4a02-a81f-4be79f9e8d56', 'A messenger from the palace', false, 'c91807a9-b954-49f0-a965-1a0fd9555f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dae54a28-a23f-405d-b21c-3376134bb89a', 'A robber looking for gold', false, 'c91807a9-b954-49f0-a965-1a0fd9555f7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93f1bf68-59ba-40a0-8ee3-43801be0612d', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'How did the King save the life of the bleeding bearded man?', 'The king washed and repeatedly redressed the severe wound with his handkerchief, nursing the man back to life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cae625ef-a3a4-4fbd-b0ee-decfc409254a', 'The King washed the wound repeatedly, bandaged it with his clean handkerchief and the hermit''s towel until the bleeding stopped, and gave him fresh water to drink', true, '93f1bf68-59ba-40a0-8ee3-43801be0612d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f18fb4c-54af-4d66-9485-7c5f01cb46e7', 'He called a helicopter', false, '93f1bf68-59ba-40a0-8ee3-43801be0612d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4d96c01-f77d-430f-a55d-fc6d587f06e6', 'He put the man in prison', false, '93f1bf68-59ba-40a0-8ee3-43801be0612d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1690d2da-1f54-4f86-842d-8138706c923d', 'He ran away into the forest', false, '93f1bf68-59ba-40a0-8ee3-43801be0612d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec6d0710-3c0e-4a24-bc5f-5acf3fb5799f', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'Why had the bearded man originally hidden in the woods to ambush and kill the King?', 'The bearded man sought blood revenge because the king had put his brother to death and seized his estate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ac6f507-f0d4-4f8c-aa5c-939363cffcdc', 'Because the King had earlier executed the man''s brother and confiscated all his family property', true, 'ec6d0710-3c0e-4a24-bc5f-5acf3fb5799f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('965ead2a-d8c2-4271-bea5-b064108380e8', 'Because he wanted to steal the King''s crown', false, 'ec6d0710-3c0e-4a24-bc5f-5acf3fb5799f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85228764-7334-4229-b4fe-9a57b2dc494b', 'Because the King owed him money', false, 'ec6d0710-3c0e-4a24-bc5f-5acf3fb5799f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1a76999-154c-439e-8060-f3970b900441', 'Because he was a spy for another kingdom', false, 'ec6d0710-3c0e-4a24-bc5f-5acf3fb5799f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c76b27f5-3488-42db-b902-818025aaeb2d', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'According to the wise Hermit, what is the SINGLE MOST IMPORTANT TIME in life?', 'The hermit revealed: ''The most important time is NOW, because it is the only time we have any power''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e5dbde7-cc34-4e40-8c97-998ed931de92', '''NOW'' (The Present Moment) — because it is the only time over which we possess any real power to act', true, 'c76b27f5-3488-42db-b902-818025aaeb2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df19a28a-dd2c-402b-aa48-e4769f897991', 'Yesterday', false, 'c76b27f5-3488-42db-b902-818025aaeb2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b137f5a-f211-4040-be38-4444ba7829c9', 'Tomorrow', false, 'c76b27f5-3488-42db-b902-818025aaeb2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84d24937-8cbf-43f8-b219-3abddaaa6bdb', 'Next year', false, 'c76b27f5-3488-42db-b902-818025aaeb2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('686a4a07-b5ab-4dc8-9cf0-763854c79531', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'According to the Hermit, who is the MOST IMPORTANT PERSON to a human being?', 'The most necessary person is the one with whom you are in the immediate present moment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d212782b-b071-49b8-b0c5-99937efd32c1', 'The person you are with at any given present moment (as no one knows if you will ever have dealings with anyone else)', true, '686a4a07-b5ab-4dc8-9cf0-763854c79531');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f80aa8de-d709-4a90-8fbb-6bf9bfe642a9', 'The King or Queen', false, '686a4a07-b5ab-4dc8-9cf0-763854c79531');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('640b5b57-b170-47b6-a4c1-93928996c4ae', 'The richest merchant', false, '686a4a07-b5ab-4dc8-9cf0-763854c79531');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c0fdc70-549a-4c2e-8ecf-b9a13cca8721', 'A distant celebrity', false, '686a4a07-b5ab-4dc8-9cf0-763854c79531');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d19ca13-1796-45f0-a366-9da09a915b6a', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'According to the Hermit, what is the MOST IMPORTANT BUSINESS/AFFAIR in human life?', 'The ultimate human mission is to do good to others: ''for that purpose alone was man sent into this life''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4acb6521-c22d-4c19-bae7-d0f2e6ab77bc', 'To do good to the person you are with (for that divine purpose alone were humans sent into this world)', true, '3d19ca13-1796-45f0-a366-9da09a915b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd8b6da2-77f0-4211-9329-19d146c4ec25', 'To amass gold and treasure', false, '3d19ca13-1796-45f0-a366-9da09a915b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5217c10a-9a45-488e-8df2-26eff0e6d6ee', 'To conquer new lands', false, '3d19ca13-1796-45f0-a366-9da09a915b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('692d07af-0ce7-4120-ac03-649cb9f07481', 'To become famous and feared', false, '3d19ca13-1796-45f0-a366-9da09a915b6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47418cf4-79ec-4719-bcbc-7054828f8ba0', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'In Mildred Bowers Armstrong''s delightful poem ''The Squirrel'', what did the playful squirrel wear for a tail?', 'Armstrong''s opening line paints an iconic visual metaphor: ''He wore a question mark for tail''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade3e3fa-1e55-4a18-a21d-71d38ea38080', 'A Question Mark (?) for a tail', true, '47418cf4-79ec-4719-bcbc-7054828f8ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21b16b20-5548-44bc-9ad7-b70f6ea404ba', 'An exclamation mark', false, '47418cf4-79ec-4719-bcbc-7054828f8ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('026f3eb0-7142-49d6-8555-cf5fe0a0dfee', 'A straight sword', false, '47418cf4-79ec-4719-bcbc-7054828f8ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('729ba35f-6bb6-4bb0-9c21-f6bccfec9bb5', 'A bushy broom', false, '47418cf4-79ec-4719-bcbc-7054828f8ba0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43a6cae0-e57f-4845-a901-d4b539855ff7', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'In the poem ''The Squirrel'', what color ''overcoat'' did the squirrel wear, and what food did he sit straight up to eat?', 'Armstrong describes the squirrel''s natural fur: ''An overcoat of gray / He sat up straight to eat a nut''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76ee38d7-be06-4155-b17e-66ecf6376581', 'An overcoat of Gray ; sitting up straight to eat a Nut', true, '43a6cae0-e57f-4845-a901-d4b539855ff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85f667f0-0b61-4fd9-a538-352050133913', 'An overcoat of Green ; eating an Apple', false, '43a6cae0-e57f-4845-a901-d4b539855ff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69c19a6f-8ce3-4813-868b-efd21106f492', 'An overcoat of Black ; eating a Fish', false, '43a6cae0-e57f-4845-a901-d4b539855ff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('318fc67f-56f0-467f-aa2e-725bd9e8e44a', 'An overcoat of Red ; eating Berries', false, '43a6cae0-e57f-4845-a901-d4b539855ff7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc927bbe-3db9-4c73-bc1c-851b46868ef7', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What dramatic moral transformation occurs between the King and his bitter enemy in ''Three Questions''?', 'Compassion and mercy transformed a bloodthirsty avenger into a lifelong loyal friend and ally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85081458-44ff-41a3-bca8-7c2db53d0d84', 'The wounded enemy asked for forgiveness, pledged eternal loyal service, and the King warmly forgave him, promised to restore his confiscated property, and sent his royal doctor to care for him (Enemy turned into devoted friend through compassion)', true, 'fc927bbe-3db9-4c73-bc1c-851b46868ef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e07c9a7d-73aa-4079-acf9-7dcaf3129d5b', 'The King executed the enemy in the forest', false, 'fc927bbe-3db9-4c73-bc1c-851b46868ef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8899bad-8adc-4160-834c-6fd325dc9911', 'The enemy escaped and attacked the palace', false, 'fc927bbe-3db9-4c73-bc1c-851b46868ef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee1d02f6-591e-4056-ad58-20266f1daf2a', 'The hermit asked for money from both', false, 'fc927bbe-3db9-4c73-bc1c-851b46868ef7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b1df2c5-e252-4f9d-b1ed-7fce1fe4cdfa', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'How did the Hermit prove to the King that his three questions had ALREADY been answered through living experience?', 'Tolstoy demonstrates that wisdom is experiential: lived compassionate action in the present moment provides its own truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dac329f2-41b2-4fe1-b35e-4abc7cebf03b', 'If the King had not pitied the Hermit and dug the beds, he would have been killed by the ambush; and if he had not bandaged the wounded man, the man would have died without making peace', true, '6b1df2c5-e252-4f9d-b1ed-7fce1fe4cdfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a124b5b-c6e2-4e37-b313-a1d4295129fb', 'The Hermit gave him a written parchment', false, '6b1df2c5-e252-4f9d-b1ed-7fce1fe4cdfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd107736-8b90-4af9-8900-bb847623b82c', 'The Hermit cast a magic spell', false, '6b1df2c5-e252-4f9d-b1ed-7fce1fe4cdfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cac0f1f-b40a-46fe-8867-2441f4ba56da', 'The Hermit sent him to another kingdom', false, '6b1df2c5-e252-4f9d-b1ed-7fce1fe4cdfa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8915ddc7-1654-4332-a383-1150d125183b', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'In the poem ''The Squirrel'', what playful game does the squirrel play when children run around his tree?', 'Armstrong captures the skittish, playful evasive antics of squirrels: darting to the opposite side of tree trunks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d03fec9-bc16-43e4-8f1a-1cd23c3a3e17', '"He liked to tease and play, / And if we ran around his tree, / He went the other way."', true, '8915ddc7-1654-4332-a383-1150d125183b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39acb130-b7e1-4768-bc4a-8b8e2f69575c', 'He throws nuts at the children', false, '8915ddc7-1654-4332-a383-1150d125183b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faa44371-4750-49fc-bfde-0781cca2bde7', 'He jumps into their hands', false, '8915ddc7-1654-4332-a383-1150d125183b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c0ac22d-8e49-4d09-9efd-baeae398dfd7', 'He flies into the sky', false, '8915ddc7-1654-4332-a383-1150d125183b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da5c94f5-f561-4b95-8b2f-7553b1d47749', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What is the SYNONYM for the word ''Council'' as used in ''Three Questions'' (''a council of wise men'')?', '''Council'' (noun) denotes an advisory assembly; distinct from ''counsel'' (verb/noun for advice).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bee0e82f-7dd6-439a-aa5b-717570938b3d', 'A body of advisors / committee of experts', true, 'da5c94f5-f561-4b95-8b2f-7553b1d47749');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37c10501-a06f-4998-8eab-d9c6f12765a0', 'To give advice to someone', false, 'da5c94f5-f561-4b95-8b2f-7553b1d47749');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f2330cc-fdbe-48a9-95e0-25e919b3c9c6', 'A battlefield', false, 'da5c94f5-f561-4b95-8b2f-7553b1d47749');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('674d410a-c0f7-4ae0-ba90-d11e26199212', 'A royal palace', false, 'da5c94f5-f561-4b95-8b2f-7553b1d47749');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3a82bc1-6b78-47cc-aa77-70fd5b9e1f0a', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What is the meaning of the word ''Fainted'' in: ''The bearded man reached the king and fainted.''?', '''Fainted'' (syncope) signifies transient loss of consciousness caused by hypovolemia or trauma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20e59ee0-6a13-4655-bd82-3edf902c285c', 'Lost consciousness temporarily due to weakness or loss of blood', true, 'd3a82bc1-6b78-47cc-aa77-70fd5b9e1f0a');
