INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('367758db-08d5-4c53-b6b0-ad1dfb152fb1', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'Choose the correct sentence with proper Subject-Verb Agreement:', 'In ''Neither... nor'' constructions, the finite verb agrees with the proximate plural subject (''ministers were'').', NOW()) ON CONFLICT DO NOTHING;
