INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb0e80ab-e7c0-416a-8d41-e329bd18e9d3', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Analyze the subtle irony in the arrival of the bearded wounded man in ''Three Questions'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28020f82-106d-45d9-8179-4b9ce9350f23', 'The man who came with the intent to murder the King had his own life saved by that very King, converting mortal hatred into eternal loyalty', true, 'bb0e80ab-e7c0-416a-8d41-e329bd18e9d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f7c4849-786d-483b-90f2-63576dc23f07', 'The King ran away from the wounded man', false, 'bb0e80ab-e7c0-416a-8d41-e329bd18e9d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83b7efd8-b1b6-4f41-bbe7-ac526f46383a', 'The Hermit turned out to be the man''s brother', false, 'bb0e80ab-e7c0-416a-8d41-e329bd18e9d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dfc80b0-f324-4a58-a9dd-539e1efcaac5', 'The King discovered the man was a ghost', false, 'bb0e80ab-e7c0-416a-8d41-e329bd18e9d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2c66fc9-76a2-499b-a1a2-b1c8e1411101', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Match Column I (Literary Character / Element) with Column II (Symbolic Representation in ''Three Questions''):
(a) The King     -> (i) The restless searcher for intellectual certainty
(b) The Hermit   -> (ii) Grounded spiritual wisdom living in harmony with nature
(c) The Spade    -> (iii) Humble, selfless labor in service of others
(d) The Bandage  -> (iv) Healing compassion that dissolves historical enmity', 'King = searcher; Hermit = wisdom; Spade = humble labor; Bandage = healing compassion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9c05f16-2983-4612-9d83-f81d9963c52d', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'd2c66fc9-76a2-499b-a1a2-b1c8e1411101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fc1ee4c-4863-46d2-b7a6-cbb15ffb3938', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'd2c66fc9-76a2-499b-a1a2-b1c8e1411101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d87aa2c-f57b-4ad0-85c0-1910a34797a6', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'd2c66fc9-76a2-499b-a1a2-b1c8e1411101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b59da613-94d9-46f1-a9e9-62f9bfe9a212', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'd2c66fc9-76a2-499b-a1a2-b1c8e1411101');
