INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bed70fad-02ec-4408-814e-5c6a23ae6eec', 'All Statements 1, 2, and 3', false, '6491270a-9c62-4640-8431-52bf15cc5cea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c22400d-feef-464b-8067-5a37dba927b9', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Identify the grammatical role of the underlined words in: ''The king was **greatly pleased** to have made peace with his enemy so easily.''', '''Greatly'' intensifies the participial adjective predicate ''pleased'', functioning as an Adverb of Degree.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba49ec3a-8fd0-45c8-999e-aef5239f70ee', '''Greatly'' is an Adverb of Degree modifying the participial adjective ''pleased''', true, '2c22400d-feef-464b-8067-5a37dba927b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f423b59-5e2f-46b4-809a-bb5848076aae', '''Greatly'' is a Noun', false, '2c22400d-feef-464b-8067-5a37dba927b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f76c20ef-2d7c-434b-ac99-040c89bff8fe', '''Pleased'' is a Preposition', false, '2c22400d-feef-464b-8067-5a37dba927b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fd6d399-2cf2-4ebf-8d3e-3c6292e0b3ae', '''Greatly'' is a Conjunction', false, '2c22400d-feef-464b-8067-5a37dba927b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33815636-9f6a-413d-8c9b-011fd901acb7', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Which of the following sentences correctly utilizes a CONDITIONAL CLAUSE (Type 3 / Unfulfilled Past Condition) matching the Hermit''s dialogue?', 'Third conditional structure: If + past perfect (had not pitied/dug) ... would have + past participle (would have been attacked).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ae1f521-48ef-4195-808b-d7babac2f343', '''If you had not pitied my weakness yesterday and had not dug these beds, you would have been attacked by that man.''', true, '33815636-9f6a-413d-8c9b-011fd901acb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d505fa2b-c9b9-44db-a09d-21745c3329c4', '''If you do not dig beds, you will be attacked.''', false, '33815636-9f6a-413d-8c9b-011fd901acb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fc536e9-02c8-41c5-a5b5-44d01e2467d4', '''If you dig beds, you are attacked.''', false, '33815636-9f6a-413d-8c9b-011fd901acb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb769b91-e3f9-4aad-ab37-a398eb5dc2e0', '''If you would dig beds, you had been attacked.''', false, '33815636-9f6a-413d-8c9b-011fd901acb7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c78e1107-93bf-4d3e-823c-19189a933e4c', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'What is the tone and poetic meter of Mildred Bowers Armstrong''s ''The Squirrel''?', 'Armstrong''s tone is whimsical, playful, and delighted by nature''s miniature vivacity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ac986ac-3173-420a-84fe-4e98e88dc4a3', 'Playful, affectionate, and lighthearted with rhythmic rhyming couplets capturing lively kinetic movement', true, 'c78e1107-93bf-4d3e-823c-19189a933e4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('131231e4-5c8b-4ac6-800d-7e5b34bc90ea', 'Somber, tragic, and mournful', false, 'c78e1107-93bf-4d3e-823c-19189a933e4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adf4b94e-3259-441a-9e5c-912c597437fd', 'Fierce, aggressive, and war-like', false, 'c78e1107-93bf-4d3e-823c-19189a933e4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a2140e0-0c10-4e88-beae-990674a61188', 'Scientific and analytical without emotion', false, 'c78e1107-93bf-4d3e-823c-19189a933e4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ee194fd-4602-49b1-ad76-3fd326c58e48', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Select the sentence that contains a TRANSITIVE verb with both a DIRECT and an INDIRECT object:', 'Ditransitive syntax: Verb (gave) + Indirect Object (the wounded man) + Direct Object (a cup of fresh water).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e992deab-dd62-4e82-9b9c-410d59a071e3', '''The King gave the exhausted wounded man a cup of fresh water.'' (''the wounded man'' = indirect object ; ''a cup of fresh water'' = direct object)', true, '8ee194fd-4602-49b1-ad76-3fd326c58e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cff6198-2cbe-44e8-a635-640d8fd15ea1', '''The squirrel ran up the tall tree.''', false, '8ee194fd-4602-49b1-ad76-3fd326c58e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15edb957-4dab-4065-96c4-d55313188ad8', '''The hermit was digging in the garden.''', false, '8ee194fd-4602-49b1-ad76-3fd326c58e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('423e12fa-cd1d-46ac-9c71-bc2483622ca7', '''The sun sank behind the trees.''', false, '8ee194fd-4602-49b1-ad76-3fd326c58e48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c1ee8d1-0222-487a-8fd3-2f1ca5bd02a5', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'What is the meaning of the archaic/literary term ''Quitted'' in ''He lived in a wood which he never quitted''?', 'Literary verb ''quit'' (past: quitted/quit) signifies to depart from or leave a location.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e774f28-b4a5-447e-9297-aa5f3ee3aca6', 'Departed from / left / abandoned', true, '0c1ee8d1-0222-487a-8fd3-2f1ca5bd02a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('496ef742-2bb5-481f-8835-2b5aa7fbe057', 'Destroyed with fire', false, '0c1ee8d1-0222-487a-8fd3-2f1ca5bd02a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77be3f00-72d0-4dc3-a35c-82719c6cbf67', 'Purchased with money', false, '0c1ee8d1-0222-487a-8fd3-2f1ca5bd02a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fecffeab-1fea-42bf-8afd-648148c4138d', 'Painted with colors', false, '0c1ee8d1-0222-487a-8fd3-2f1ca5bd02a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd949530-4b5c-4476-9581-05e245061008', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Transform the complex sentence into a SIMPLE sentence without changing its meaning:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cd6e41f-5491-42dc-8a3c-aac32b6fe531', '''On seeing the hermit, the King greeted him respectfully.''', true, 'cd949530-4b5c-4476-9581-05e245061008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('709808be-5bae-48e6-9266-705137988bc3', '''The King saw the hermit and he greeted him.''', false, 'cd949530-4b5c-4476-9581-05e245061008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cdc070f-8f49-42ff-86f5-27e7de84175c', '''The King saw the hermit because he greeted him.''', false, 'cd949530-4b5c-4476-9581-05e245061008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6793a319-746d-45bc-b961-c89b1d22f392', '''Although the King saw the hermit, he greeted him.''', false, 'cd949530-4b5c-4476-9581-05e245061008');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93b8cdce-696b-40ac-8a7d-3ccace572d9b', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'What enduring message does the opening chapter of NCERT Class 7 English impart to young learners?', 'Chapter 1 harmonizes philosophical mindfulness (Tolstoy) with affectionate ecological wonder (Armstrong).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cbaaa77-0e4e-4def-b7b7-4737dcf1afe1', 'True wisdom is not found in abstract academic speculation, but in practical mindfulness, living fully in the present moment, practicing unconditional kindness, and finding joy in the gentle creatures of nature', true, '93b8cdce-696b-40ac-8a7d-3ccace572d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c98889db-dc4f-4330-9d4f-a43fe822f5ab', 'That questions in life can never be answered', false, '93b8cdce-696b-40ac-8a7d-3ccace572d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7da9095-673f-4823-b459-bfca355e2d0b', 'That rulers should never listen to common people', false, '93b8cdce-696b-40ac-8a7d-3ccace572d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b434fb1f-8ccd-4f61-b57c-23e23d4971cd', 'That wild animals should be captured for research', false, '93b8cdce-696b-40ac-8a7d-3ccace572d9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3bf2fc7-5f76-483b-ad8f-7a513a00d6ca', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Easy', 'What is the National Emblem of the Republic of India adopted from on 26th January 1950?', 'India''s State Emblem is adapted from the Mauryan Lion Capital of Ashoka at Sarnath (250 BCE).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdfbe194-a024-4a87-aa26-0d147ff24969', 'The Lion Capital of Ashoka at Sarnath (featuring four Asiatic lions standing back to back)', true, 'f3bf2fc7-5f76-483b-ad8f-7a513a00d6ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('391e03c2-c184-40a4-a2f6-a4c89fb796d7', 'The Pillar of Allahabad', false, 'f3bf2fc7-5f76-483b-ad8f-7a513a00d6ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f098804-0773-45d1-95fb-260434703a08', 'The Sanchi Stupa Gateway', false, 'f3bf2fc7-5f76-483b-ad8f-7a513a00d6ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97a06bdf-11e6-4f8d-8e28-8f558c856305', 'The Sun Temple Wheel at Konark', false, 'f3bf2fc7-5f76-483b-ad8f-7a513a00d6ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12e6d356-f44e-4135-98de-b3320af05ee3', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Easy', 'What is the National Motto of India inscribed in Devanagari script at the base of the National Emblem below the Abacus?', '''Satyameva Jayate'' is taken from the sacred Mundaka Upanishad, signifying that divine truth alone prevails.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea1b139b-8669-479f-9afe-8177246dc826', '''Satyameva Jayate'' (Truth Alone Triumphs - from the Mundaka Upanishad)', true, '12e6d356-f44e-4135-98de-b3320af05ee3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d1ea315-6685-4507-84b0-d171f898625a', '''Vande Mataram''', false, '12e6d356-f44e-4135-98de-b3320af05ee3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6193a413-73ad-478c-b28c-4183d5f1f91b', '''Jai Hind''', false, '12e6d356-f44e-4135-98de-b3320af05ee3');
