INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6f6a75a-5cef-46c8-a15c-17e9a1149c13', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Easy', 'What is the official width-to-length ratio of the National Flag of India (Tiranga)?', 'The Flag Code of India stipulates the dimensional ratio of the National Flag as 2 : 3 (height : length).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cf02bfb-de47-4214-8a60-a6e4265bf5ae', '2 : 3 (Width to Length / Height to Length)', true, 'f6f6a75a-5cef-46c8-a15c-17e9a1149c13');
