INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f8e8e0d-a13e-42f7-93f3-d6b0edfd4b16', '3 : 4', false, 'f6f6a75a-5cef-46c8-a15c-17e9a1149c13');
