INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61ffc735-4b08-4b72-a7c1-ca956cd9e41c', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Easy', 'How many spokes are there in the navy blue Ashoka Chakra located at the center of the white band of the Indian National Flag?', 'The Ashoka Chakra has 24 spokes representing continuous dynamic moral progress and duty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('347d2864-0437-4f34-84ff-eb107a121e3d', '24 Spokes (representing the 24 hours of righteousness and continuous progress)', true, '61ffc735-4b08-4b72-a7c1-ca956cd9e41c');
