INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7aad575-4c3d-4c22-a5e9-1c4e03bf8949', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Easy', 'Who composed India''s National Anthem, ''Jana Gana Mana''?', 'Rabindranath Tagore composed ''Jana Gana Mana'' in 1911; its playing time is approximately 52 seconds.', NOW()) ON CONFLICT DO NOTHING;
