INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4832b9a7-5da6-4672-91b7-27cd4f73cc14', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Easy', 'Who composed India''s National Song, ''Vande Mataram'' (originally in his novel ''Anandamath'')?', 'Bankim Chandra Chattopadhyay wrote ''Vande Mataram'' in Sanskritized Bengali, published in Anandamath (1882).', NOW()) ON CONFLICT DO NOTHING;
