INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84273862-15de-41d5-a11b-7ce84d076904', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Easy', 'How many States and Union Territories does the Republic of India currently comprise?', 'As of 2026, the federal political map of India consists of exactly 28 States and 8 Union Territories.', NOW()) ON CONFLICT DO NOTHING;
