INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27b3995b-0d1e-4c6c-8a01-538ca4ea7c1f', 'The harmonious synthesis of thousands of dialects, ancient classical traditions, multiple world religions, diverse biogeographical landscapes, and vibrant regional cultures unified under a secular democratic constitutional framework', true, '60550ddf-3717-4be0-a238-34d774b9384f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd79f772-57a1-4e94-8b67-ee1a27e45ea1', 'A nation where everyone speaks only one language', false, '60550ddf-3717-4be0-a238-34d774b9384f');
