INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c3dda28-4e99-4bf0-9160-59d11d1f7363', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'How did the 12th-century Arab geographer Al-Idrisi (1154 CE) orient his famous map of the Indian subcontinent compared to modern maps?', 'Al-Idrisi''s 1154 CE Arabic map oriented South at the top, showing Sri Lanka at the upper summit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0bb51eb-04ea-4e69-a809-1e8e299751ad', 'South India was shown at the TOP where North India is today, and Sri Lanka was shown as an island at the top', true, '0c3dda28-4e99-4bf0-9160-59d11d1f7363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5940b03a-d6cd-42f5-b909-4adca423e1fb', 'He showed India upside down with Himalayas at the bottom', false, '0c3dda28-4e99-4bf0-9160-59d11d1f7363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af42c3b1-74e6-4a4f-8f38-60dbf80f4bab', 'He showed only oceans without land', false, '0c3dda28-4e99-4bf0-9160-59d11d1f7363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d2de02c-1eba-4ad9-8a67-4214c5e240b6', 'His map was identical to Google Maps', false, '0c3dda28-4e99-4bf0-9160-59d11d1f7363');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9be5370f-b078-4644-bd6c-5c33b0438d2f', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'In the 13th century, what geographical area did the Persian chronicler Minhaj-i Siraj mean when he used the term ''Hindustan''?', 'Minhaj-i Siraj used ''Hindustan'' in a political sense to denote the Gangetic and Doab domains of the Delhi Sultanate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27bcf492-df7e-4064-8c84-8f8b6a5d5671', 'The lands of Punjab, Haryana, and the fertile plains between the Ganga and Yamuna rivers ruled by the Delhi Sultan', true, '9be5370f-b078-4644-bd6c-5c33b0438d2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c592d147-e46a-49ce-aef9-66aa093a030b', 'The entire modern republic of India including south India', false, '9be5370f-b078-4644-bd6c-5c33b0438d2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d6adeb0-e4bf-484b-abf0-2ddbf77f9141', 'The continent of Asia', false, '9be5370f-b078-4644-bd6c-5c33b0438d2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9d83f56-44c6-4ac2-9067-00b4666f7093', 'Only the island of Sri Lanka', false, '9be5370f-b078-4644-bd6c-5c33b0438d2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62019395-1b14-4c54-8164-ee91938c6224', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'In the early 16th century, how did the Mughal Emperor Babur use the term ''Hindustan'' in his autobiography (Baburnama)?', 'Babur employed ''Hindustan'' in a biogeographical and cultural sense to describe the subcontinent''s fauna, flora, and customs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8748ee0-8330-4748-b33f-3e0f1f80ee8b', 'To describe the geography, the natural fauna, and the distinct cultural customs of the inhabitants of the subcontinent', true, '62019395-1b14-4c54-8164-ee91938c6224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d219a37b-1566-4e3c-8810-ce7b0530b5d6', 'As a political nation-state with a constitution', false, '62019395-1b14-4c54-8164-ee91938c6224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e65b198-3416-4563-a854-f622bccf6769', 'To describe only Afghanistan', false, '62019395-1b14-4c54-8164-ee91938c6224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6505ea92-6d10-447b-9b4f-62710d221c07', 'To refer to the Roman Empire', false, '62019395-1b14-4c54-8164-ee91938c6224');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf3f6592-7c9a-4273-add1-65a1c7b5ca32', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'In the medieval period, what did the term ''Foreigner'' (Pardesi in Hindi / Ajnabi in Persian) mean?', 'In medieval times, a ''foreigner'' (ajnabi/pardesi) was any outsider/stranger from another village, not necessarily from a foreign nation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68a54c57-4f02-4eed-8876-300fb6f3de4c', 'Any stranger who appeared in a given village or town and was not a part of that local society or culture', true, 'cf3f6592-7c9a-4273-add1-65a1c7b5ca32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1becc7b-136c-419d-b4e4-972298dccd0b', 'Only a person from another foreign country', false, 'cf3f6592-7c9a-4273-add1-65a1c7b5ca32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcaf2670-3387-4143-a415-70364313d61f', 'An English trader only', false, 'cf3f6592-7c9a-4273-add1-65a1c7b5ca32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49af1b73-6c5c-48dd-872a-ef3eea6375f5', 'A king from Rome', false, 'cf3f6592-7c9a-4273-add1-65a1c7b5ca32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0666273-2a1a-4c31-9349-156a1b2554a0', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'Before the invention of printing presses in India, who copied historical manuscripts by hand?', 'Scribes laboriously transcribed handwritten manuscript codices before the introduction of mechanical printing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf8caf53-d465-4a5c-8fe1-a3bf03fe9142', 'Scribes (professional handwritten copyists)', true, 'b0666273-2a1a-4c31-9349-156a1b2554a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f43b6147-c31c-4840-9be9-19cacd160bb8', 'Cartographers', false, 'b0666273-2a1a-4c31-9349-156a1b2554a0');
