INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9013cdab-6203-4ef0-9814-2317a1f872c2', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'A place or building where official historical documents, records, and original manuscripts are preserved and stored is called an:', 'An archive is a specialized repository where state administrative records, charters, and historical manuscripts are curated.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13f386d2-c1bb-4039-83b9-85120622cb18', 'Archive', true, '9013cdab-6203-4ef0-9814-2317a1f872c2');
