INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4237d6c1-a654-4f93-9534-3325715cdb4b', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'What new group of warrior Kshatriya clans rose to great political and military prominence between the 8th and 14th centuries, derived from the Sanskrit term ''Rajaputra'' (son of a king)?', 'The term ''Rajput'' (from Rajaputra) designated martial warrior clans claiming Kshatriya lineage across northern and western India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b4e0aec-b923-4b1b-873a-d1a897448ed9', 'Rajputs', true, '4237d6c1-a654-4f93-9534-3325715cdb4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('186563a4-509c-45c8-bf94-c8020ad8a35e', 'Cholas', false, '4237d6c1-a654-4f93-9534-3325715cdb4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a9abb02-0a1c-44ac-af29-282ca07418b4', 'Guptas', false, '4237d6c1-a654-4f93-9534-3325715cdb4b');
