INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38d6ced8-11e0-4c65-9ba9-bd69ab2707e9', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'Which of the following new agricultural crops and beverages were introduced to the Indian subcontinent from the Americas and foreign trade during this thousand-year period?', 'The Columbian exchange and trade brought potatoes, maize, chillies, tomatoes, tobacco, tea, and coffee to India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58d8bdef-8dad-40fb-98ab-315557c344bb', 'Potatoes, Corn (Maize), Chillies, Tea, and Coffee', true, '38d6ced8-11e0-4c65-9ba9-bd69ab2707e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aadea51f-a013-445b-ae88-6156e9ce6761', 'Wheat, Rice, and Barley', false, '38d6ced8-11e0-4c65-9ba9-bd69ab2707e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('929c75c1-12d2-4f06-af22-1ac89211dc77', 'Mustard and Cotton', false, '38d6ced8-11e0-4c65-9ba9-bd69ab2707e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e5571aa-b09b-4beb-83db-4269937fabcd', 'Jowar and Bajra', false, '38d6ced8-11e0-4c65-9ba9-bd69ab2707e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59171bcf-0ddb-4005-ba01-bc23d606977e', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'What was a sub-caste or social ranking formed within the caste hierarchy based on occupation, family background, and social status called?', 'Jatis were occupational sub-castes ranked fluidly according to their local wealth, power, and ritual status.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e8c9996-5da9-4193-a8e9-e4c58b9fb581', 'Jati', true, '59171bcf-0ddb-4005-ba01-bc23d606977e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e62df5a-eaaa-4dd6-b60e-9e8ddad9b9cb', 'Varna', false, '59171bcf-0ddb-4005-ba01-bc23d606977e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2dd6a49-f8bd-4e90-acc9-8eae43f25eb6', 'Samanta', false, '59171bcf-0ddb-4005-ba01-bc23d606977e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('785e27a8-18d2-4e46-b1a6-a5a4b3d43b5b', 'Ulama', false, '59171bcf-0ddb-4005-ba01-bc23d606977e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d19145e-6ebb-4a7a-9912-9dee0e7b1d82', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'Who framed the rules and regulations to manage the conduct of members within each Jati?', 'Jati Panchayats were self-regulating assemblies of caste elders enforcing community occupational and marital norms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fa5db1e-f9e5-4d4a-976d-ec62eb88b8b0', 'The Jati Panchayat (an assembly of village elders belonging to that specific jati)', true, '4d19145e-6ebb-4a7a-9912-9dee0e7b1d82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('566d85c9-a3ec-4f23-bd4c-136dac9d4c6c', 'The Mughal Emperor', false, '4d19145e-6ebb-4a7a-9912-9dee0e7b1d82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf5e46fa-084f-47ef-96c0-172e2a8b2ba3', 'Foreign merchants', false, '4d19145e-6ebb-4a7a-9912-9dee0e7b1d82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ed56f5b-5da0-425f-ae4d-ef0eaf0ff79e', 'Roman senators', false, '4d19145e-6ebb-4a7a-9912-9dee0e7b1d82');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60034d07-c78e-4df2-a28e-1f0eac5c65de', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'What is the holy scripture of Islam that contains the divine revelations received by Prophet Muhammad?', 'The Holy Quran is the central sacred liturgical text of Islam revealed to Prophet Muhammad in Arabic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beb43c27-1be5-4bff-9948-0358b97f389d', 'The Quran (Holy Quran)', true, '60034d07-c78e-4df2-a28e-1f0eac5c65de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01b35777-79fd-4f01-bed3-f73008bce4e6', 'The Zend Avesta', false, '60034d07-c78e-4df2-a28e-1f0eac5c65de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('500d23a0-9495-41b9-97bc-889ba173f601', 'The Tripitaka', false, '60034d07-c78e-4df2-a28e-1f0eac5c65de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2072085b-bf9b-4ea3-9f18-4d21c34219cc', 'The Torah', false, '60034d07-c78e-4df2-a28e-1f0eac5c65de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb12002f-0f7c-4736-b455-4607f19ead51', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Why do historians face enormous challenges and discrepancies when reading ancient handwritten manuscripts copied by scribes?', 'Manual transcription errors accumulated exponentially over generations of copyists, resulting in divergent recensions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e6967b7-077c-4db1-bae9-c3489a3ff8c1', 'As scribes copied by hand, they frequently made unintentional copying errors, added small modifications, or substituted words, which compounded over centuries until different manuscript copies differed significantly from the author''s original text', true, 'eb12002f-0f7c-4736-b455-4607f19ead51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7278042-aac0-46e5-9406-d4594be3e3ab', 'Because all scribes wrote in secret codes to trick historians', false, 'eb12002f-0f7c-4736-b455-4607f19ead51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c4a61e7-d4d5-4014-aaad-c2a660bb7801', 'Because paper was made of metal and faded', false, 'eb12002f-0f7c-4736-b455-4607f19ead51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3651dd5c-61d9-4fa7-9f8c-dea4960b32ec', 'Because manuscripts were burned by kings', false, 'eb12002f-0f7c-4736-b455-4607f19ead51');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7217c2b6-9806-452c-bb8e-4b04af9654df', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Who was the 14th-century chronicler Ziauddin Barani, and why did modern historians discover his first chronicle version only in the 1960s?', 'Ziauddin Barani''s 1356 CE recension of Tarikh-i Firuz Shahi was rediscovered in manuscript collections in the 1960s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7415c41-af7f-4906-a4f0-b3a8db128010', 'Barani wrote his first chronicle in 1356 and a revised second version in 1358; the first version remained lost in vast library archives undiscovered until 1960', true, '7217c2b6-9806-452c-bb8e-4b04af9654df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6764950-d3d4-43eb-95f9-34a5ea59b4ec', 'Because Barani hid his book inside a cave', false, '7217c2b6-9806-452c-bb8e-4b04af9654df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3bfb7df-7c11-4b93-b4ca-7c590bf41364', 'Because his book was written in hieroglyphics', false, '7217c2b6-9806-452c-bb8e-4b04af9654df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc53bb91-c41a-4eb1-9dc9-7701c3169504', 'Because Barani was a fictional character', false, '7217c2b6-9806-452c-bb8e-4b04af9654df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca288735-59b9-4a03-8770-3f1c7a120290', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What major technological innovations appeared in the Indian subcontinent between 700 and 1750 CE?', 'The medieval era witnessed crucial mechanical adoptions: saqia/Persian wheel, spinning wheel, and pyrotechnic firearms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c19915c-33c1-4a36-9ea9-24595495d72c', 'The Persian Wheel in irrigation, the Spinning Wheel (Charkha) in weaving, and Firearms (cannons & gunpowder) in combat warfare', true, 'ca288735-59b9-4a03-8770-3f1c7a120290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce329262-9399-473e-aea9-5a2fba16b6f9', 'Steam locomotives and telegraphs', false, 'ca288735-59b9-4a03-8770-3f1c7a120290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b39c9cf-e812-41f6-b29d-555dff9a5f52', 'Computers and electricity', false, 'ca288735-59b9-4a03-8770-3f1c7a120290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('543eb2c9-2ac0-440b-ac2f-eb2943fb3fe3', 'Airplanes and submarines', false, 'ca288735-59b9-4a03-8770-3f1c7a120290');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4cfb9a9-4806-4fb5-b2cc-c141d1687217', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Why were many forest dwellers forced to migrate or become peasant farmers during the medieval thousand years?', 'Agricultural expansion and deforestation transformed tribal forest habitats, integrating tribals into peasant jati hierarchies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b695369f-4439-4d7d-9595-54025a93008d', 'Extensive clearing of natural forests to expand agricultural arable land fundamentally changed forest habitats, pushing forest dwellers into agrarian village society', true, 'e4cfb9a9-4806-4fb5-b2cc-c141d1687217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('144294e4-b1ff-4e33-a9ce-d6d146d96bba', 'Because wild animals drove them out', false, 'e4cfb9a9-4806-4fb5-b2cc-c141d1687217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca10088a-1658-4d19-9cba-f4e73846fa1a', 'Because forests turned into deserts overnight', false, 'e4cfb9a9-4806-4fb5-b2cc-c141d1687217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a0f71e8-5f8b-421e-b6ff-603d8581f09d', 'Because kings banned living near trees', false, 'e4cfb9a9-4806-4fb5-b2cc-c141d1687217');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4a01647-cbc2-4001-abeb-b3b321d001c2', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What is a ''Pan-Regional Empire'' in medieval Indian history?', 'Pan-regional polities integrated multiple diverse geographical sub-regions under an overarching imperial state apparatus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adedfaa8-4135-41e1-8e06-22fbe8c97382', 'An expansive empire spanning diverse geographic, linguistic, and cultural regions (such as the Cholas, Khaljis, Tughluqs, and Mughals)', true, 'e4a01647-cbc2-4001-abeb-b3b321d001c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d59544b0-6f13-4160-94b7-ec85c175f4b5', 'A small city-state ruling one town', false, 'e4a01647-cbc2-4001-abeb-b3b321d001c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2cbe34-6c40-4046-9b51-a4f4bc0dabed', 'A maritime empire in Europe', false, 'e4a01647-cbc2-4001-abeb-b3b321d001c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db84dd3c-aa84-4ad2-beb2-750997448e26', 'An empire ruled by a single village council', false, 'e4a01647-cbc2-4001-abeb-b3b321d001c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c70b7201-cf29-4088-9bdf-be6d4ac1537f', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Who were the ''Ulama'' in medieval Islamic society?', 'The Ulama were authoritative theologians and jurists responsible for interpreting Islamic theology and Sharia law.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f5fa93e-2363-45bb-a108-1275596eb0ca', 'Learned Muslim scholars, jurists, and theologians expert in Islamic sacred law (Sharia) and religious jurisprudence', true, 'c70b7201-cf29-4088-9bdf-be6d4ac1537f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80696221-320a-4992-80f1-8686547a852a', 'Foreign horse merchants', false, 'c70b7201-cf29-4088-9bdf-be6d4ac1537f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c3cd745-aa69-4edb-8bf9-b24d219fade4', 'Architects who built forts', false, 'c70b7201-cf29-4088-9bdf-be6d4ac1537f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3969e96-fa7f-4212-8efb-bd493e3c7c8a', 'Musicians in royal courts', false, 'c70b7201-cf29-4088-9bdf-be6d4ac1537f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cd73458-9561-4e71-aa9d-cbf11e7219ec', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What was the fundamental theological difference between the SHIA and SUNNI traditions within Islam?', 'Schism: Sunnis recognized the historical succession of the Rashidun Caliphate; Shias recognized the hereditary leadership of Ali and Imams.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4be04daf-d148-425d-bafa-14b18e3ced08', 'Shia Muslims believed that Prophet Muhammad''s son-in-law Ali was the legitimate leader (Imam) of the Muslim community ; Sunni Muslims accepted the authority of the early Caliphs (Khalifas)', true, '6cd73458-9561-4e71-aa9d-cbf11e7219ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06c004cd-e6e9-48e0-95ea-184cb0b92cc6', 'Shias worshipped fire while Sunnis worshipped water', false, '6cd73458-9561-4e71-aa9d-cbf11e7219ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d043d9e-0e3e-45e4-8ac2-247e1a0b66a6', 'Sunnis did not believe in the Quran', false, '6cd73458-9561-4e71-aa9d-cbf11e7219ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53b604b0-08d1-4c74-a73d-f2a7a83a0c35', 'Shias did not pray at all', false, '6cd73458-9561-4e71-aa9d-cbf11e7219ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d35f599-8cc6-49c9-af71-f15a51506073', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What were the two prominent schools of Islamic legal jurisprudence (Fiqh) influential in medieval India?', 'The Hanafi and Shafi''i madhhabs (schools of Islamic jurisprudence) were the primary legal traditions in the subcontinent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('756cdfa9-6d20-4613-9bb5-bd17a266e9df', 'Hanafi and Shafi''i schools', true, '8d35f599-8cc6-49c9-af71-f15a51506073');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8dd02e8-5548-4c83-8830-f1dbb5c21e96', 'Maliki and Hanbali only', false, '8d35f599-8cc6-49c9-af71-f15a51506073');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5e4f83f-676d-4504-8e28-5fbcd9b5fa1a', 'Greek and Roman schools', false, '8d35f599-8cc6-49c9-af71-f15a51506073');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52809de2-b993-4895-8814-58c44f9fe38d', 'Vedic and Buddhist schools', false, '8d35f599-8cc6-49c9-af71-f15a51506073');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e5b40d1-854c-43fa-a835-8b6b2132fba9', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Why was the 19th-century British historian James Mill''s tripartite division of Indian history into ''Hindu'', ''Muslim'', and ''British'' periods fundamentally flawed?', 'Mill''s communal periodization reduced complex multifaceted socio-economic and cultural histories to simplistic sectarian labels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('052e54ed-dba5-477a-98c2-2e26271706cc', 'It characterized entire historical epochs solely by the personal religion of rulers, ignoring immense socio-economic diversity, scientific advances, and the diverse beliefs of ordinary people', true, '3e5b40d1-854c-43fa-a835-8b6b2132fba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9da9ef99-051d-4922-8bb6-a8d28017ff28', 'Because Mill was an Indian prince', false, '3e5b40d1-854c-43fa-a835-8b6b2132fba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('019ec54a-15f9-4eaa-8b06-f755d5bcf021', 'Because there were no religions in India', false, '3e5b40d1-854c-43fa-a835-8b6b2132fba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e51bf20-a5c9-4554-81b6-881af7b88dce', 'Because British rule lasted 2,000 years', false, '3e5b40d1-854c-43fa-a835-8b6b2132fba9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38daef66-9c9a-464f-a028-bf0dfa2bc47a', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'How do modern historians divide Indian history to reflect broader socio-economic, cultural, and technological transitions?', 'Historiographical periodization utilizes Ancient, Medieval (c. 700–1750 CE), and Modern frameworks reflecting structural socio-economic shifts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa641370-8098-423d-b1f7-7faf2e43ab9d', 'Ancient Period, Medieval Period, and Modern Period', true, '38daef66-9c9a-464f-a028-bf0dfa2bc47a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44e87633-4f20-44db-86da-41ef8890cdb5', 'Stone Age and Digital Age only', false, '38daef66-9c9a-464f-a028-bf0dfa2bc47a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('840cf170-9f8a-41d8-8cf3-56eb56920375', 'Kings Age and Queens Age', false, '38daef66-9c9a-464f-a028-bf0dfa2bc47a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10ab3c64-4cde-4f00-8fa6-62716eb1c6b7', 'War Age and Peace Age', false, '38daef66-9c9a-464f-a028-bf0dfa2bc47a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa80a05e-8c23-499e-b60b-35d9bf89890c', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What major transformation occurred in Hinduism during the medieval thousand years?', 'Medieval Hinduism saw temple-centered devotion, royal Brahmanical patronage, and popular personal Bhakti traditions without rigid rituals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a50b4615-f8cf-41c6-b505-90920acab9f5', 'The worship of new deities, the construction of massive royal stone temples, the growing social prestige and land grants (Brahmadeya) to Brahmanas, and the emergence of the Bhakti Movement', true, 'aa80a05e-8c23-499e-b60b-35d9bf89890c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1beab830-fac1-4fd7-8c94-9d25d1371d75', 'The complete disappearance of all temples', false, 'aa80a05e-8c23-499e-b60b-35d9bf89890c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99182c8d-8555-4606-9c92-5379a2a3fdaa', 'The ban on reading Sanskrit texts', false, 'aa80a05e-8c23-499e-b60b-35d9bf89890c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f5f84a3-1bad-4638-bbbb-ae3343d6a9be', 'The replacement of all gods by Roman deities', false, 'aa80a05e-8c23-499e-b60b-35d9bf89890c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c255ae46-adbe-42e3-8165-3299167400c4', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What was the central liberating appeal of the ''Bhakti Movement'' to ordinary common people during the medieval era?', 'Bhakti democratized spirituality: direct, unmediated personal love (prema/bhakti) open to all genders and castes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df7d31c2-bfc2-4b60-b239-66e395b1cb9b', 'The idea of an intimate, personal, loving God whom devotees could reach directly with pure love without the mandatory mediation of wealthy priests or elaborate, costly sacrifices', true, 'c255ae46-adbe-42e3-8165-3299167400c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ba0c296-9ab0-44c0-9cb7-b0301da8d815', 'Devotees had to give all their gold to kings', false, 'c255ae46-adbe-42e3-8165-3299167400c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf71f29a-f1cc-4b38-836e-b3d7701c9c6d', 'Devotees were forced to learn Greek', false, 'c255ae46-adbe-42e3-8165-3299167400c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('680026ca-af14-44ef-a521-904d55f7284d', 'Bhakti banned music and poetry', false, 'c255ae46-adbe-42e3-8165-3299167400c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92c86e38-d255-48aa-bb95-baff0d37f9b8', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What was the French cartographer Guillaume de L''Isle''s atlas map of India (1720s) famous for?', 'The 18th-century French atlas reflected advanced maritime surveying, exhibiting coastlines familiar to modern cartography.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ea1917d-3429-4780-a7af-7376ae0801fd', 'Remarkable scientific accuracy, modern orientation, and highly detailed coastal navigation geography used extensively by European maritime merchants', true, '92c86e38-d255-48aa-bb95-baff0d37f9b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da99e2e6-51b1-4e35-9355-5d8760285914', 'It showed South India at the top', false, '92c86e38-d255-48aa-bb95-baff0d37f9b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba37b1ea-7185-448d-98ad-cfc107577286', 'It omitted all Indian rivers', false, '92c86e38-d255-48aa-bb95-baff0d37f9b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('becc04e2-5e4d-4213-a25d-a25ad0653a90', 'It had no place names', false, '92c86e38-d255-48aa-bb95-baff0d37f9b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6223fc54-dd86-48ad-adfb-df09ec8649ec', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Who were the ''Kayasthas'' that gained prominent social and administrative status during this period?', 'Kayasthas emerged as an influential literate occupational community managing state archives, revenue ledgers, and scribal administration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cbd3b55-029e-498f-91cf-509c6c92eca8', 'A specialized caste of scribes, record-keepers, secretaries, and administrative accountants', true, '6223fc54-dd86-48ad-adfb-df09ec8649ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d66b72de-dead-4244-b55b-853060fb5938', 'Warrior cavalry officers', false, '6223fc54-dd86-48ad-adfb-df09ec8649ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6115cfbd-c553-46a1-a289-dd8f50a23625', 'Temple stone carvers', false, '6223fc54-dd86-48ad-adfb-df09ec8649ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('328d5385-3816-4f3a-923a-c7258f8456c4', 'Sea sailors', false, '6223fc54-dd86-48ad-adfb-df09ec8649ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9650ef51-40fc-4153-84b2-781675ba87da', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Why did the price of Paper fall and its availability increase dramatically during the 13th and 14th centuries in India?', 'Papermaking technology diffusion dramatically expanded codex production, record-keeping, and legal archiving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91a1e060-64ca-443a-840f-b4b8a7189664', 'Introduction of pulping watermills and spread of papermaking technology from China and the Islamic world led to widespread copying of religious, legal, and judicial texts', true, '9650ef51-40fc-4153-84b2-781675ba87da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50a1e081-fa4b-44a7-90db-9507026526e1', 'Because trees were made of paper', false, '9650ef51-40fc-4153-84b2-781675ba87da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88334060-303d-49f7-9eea-5635ad4327ef', 'Because kings banned writing on palm leaves', false, '9650ef51-40fc-4153-84b2-781675ba87da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0651c7b-a9a9-48a5-9027-e5faeb731338', 'Because books were imported from America', false, '9650ef51-40fc-4153-84b2-781675ba87da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e3caec9-dee0-4fae-af91-06a71c87d817', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What were the two major styles of Persian and Arabic handwriting used by scribes in medieval India?', 'Nastaliq was fluid and legible for literary codices; Shikaste was dense and rapid for state administrative correspondence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dbf5e30-af66-4164-9900-0d34d13f69c5', 'Nastaliq (flowing, cursive, easy to read) and Shikaste (dense, cramped, rapid, and difficult to decipher)', true, '1e3caec9-dee0-4fae-af91-06a71c87d817');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7a7ba1c-a6cb-4a16-98db-299aa09d0be2', 'Devanagari and Brahmi', false, '1e3caec9-dee0-4fae-af91-06a71c87d817');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a6c3007-4131-4cd1-9fa3-501a3f770370', 'Gothic and Latin', false, '1e3caec9-dee0-4fae-af91-06a71c87d817');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a873fcb-1752-42c6-8bbd-1f190d216838', 'Cuneiform and Hieroglyphic', false, '1e3caec9-dee0-4fae-af91-06a71c87d817');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('729c726c-d8d9-4ac7-b216-7e2fcea89171', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a13a8b6-b687-4cad-a483-e73ecdbc15e2', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '729c726c-d8d9-4ac7-b216-7e2fcea89171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a88afd9-3b2e-4f73-9e1a-be560b359fb1', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '729c726c-d8d9-4ac7-b216-7e2fcea89171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddf8879f-78bd-44fa-9eb7-e1aa21beb6c9', '(A) is true, but (R) is false.', false, '729c726c-d8d9-4ac7-b216-7e2fcea89171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0da9a98-ccf2-484d-8a69-406a0a79508f', '(A) is false, but (R) is true.', false, '729c726c-d8d9-4ac7-b216-7e2fcea89171');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad013429-7b08-44d7-9903-ace94915d5c9', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Spot the IMPOSTER in the following group of historical sources matched with their methodological limitations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('051426a8-9fd2-4598-862d-7fddda13cc3e', 'Statement 1', false, 'ad013429-7b08-44d7-9903-ace94915d5c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea6cc1cd-991f-486a-b123-d703e2da0a0f', 'Statement 2', false, 'ad013429-7b08-44d7-9903-ace94915d5c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ad627dd-67e2-4d9e-9887-102a63183715', 'Statement 3 (Handwritten manuscripts contain cumulative scribal errors)', true, 'ad013429-7b08-44d7-9903-ace94915d5c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d14a84bd-7577-4f31-8e73-1ac910c3bc04', 'Statement 4', false, 'ad013429-7b08-44d7-9903-ace94915d5c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22140557-cf54-4da0-a943-96a8abcecd66', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Analyze the multi-layered social hierarchy of Jatis in medieval villages:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('485df92e-1160-4bf2-97a0-78443b34e0ee', 'Each Jati had its own elders'' council (Jati Panchayat) to enforce internal customs, but every village was simultaneously governed by a Chieftain/Gramani, subject to overarching state revenue laws', true, '22140557-cf54-4da0-a943-96a8abcecd66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('604dd519-1ed5-4e91-8e96-45ae6b03689c', 'Jatis were completely independent and fought wars every day', false, '22140557-cf54-4da0-a943-96a8abcecd66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3369a14-7ee7-4080-9218-52b86f1f2c8e', 'Only the King could make laws for individual jatis', false, '22140557-cf54-4da0-a943-96a8abcecd66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb046b3d-1944-4d32-bf7b-50de6c16a704', 'There were no laws or village councils in medieval times', false, '22140557-cf54-4da0-a943-96a8abcecd66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f943ecc-2c8e-453f-b749-e730f92a8f91', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Match Column I (Historical Cartographers / Authors) with Column II (Work / Perspective):
(a) Al-Idrisi (1154 CE)           -> (i) Arabic map with South India at the top
(b) French Cartographer (1720s)   -> (ii) Scientifically detailed coastal maritime atlas
(c) Minhaj-i Siraj (13th Century) -> (iii) Sultanate political definition of Hindustan
(d) Ziauddin Barani (1356/1358)   -> (iv) Two distinct manuscript versions of Tarikh-i Firuz Shahi', 'Al-Idrisi = inverted map; French atlas = maritime surveying; Minhaj = political Hindustan; Barani = dual recensions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('695687dd-e830-454b-9813-aa38652ecd7e', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '3f943ecc-2c8e-453f-b749-e730f92a8f91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad25fe9c-e676-45c3-8cb4-e55f5b8eb209', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '3f943ecc-2c8e-453f-b749-e730f92a8f91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f699e47-ae56-4acc-b006-6f0011d70ed0', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '3f943ecc-2c8e-453f-b749-e730f92a8f91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('086f207f-f710-4185-acce-bf5436989bae', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '3f943ecc-2c8e-453f-b749-e730f92a8f91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98238832-e547-4f26-a17b-f56ff3131440', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Read the statements regarding religious developments in medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac0e5d40-1beb-4ae0-8fb4-e93effc4bac9', 'Statements 1 and 2 only', true, '98238832-e547-4f26-a17b-f56ff3131440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('357db8a2-1523-4994-8f36-9fe8e60a4c72', 'Statements 2 and 3 only', false, '98238832-e547-4f26-a17b-f56ff3131440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64bdfffe-58de-4301-9e35-94b2dbe4d40f', 'Statements 1 and 3 only', false, '98238832-e547-4f26-a17b-f56ff3131440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74dfb935-68da-480c-bee3-e3d2703a1c52', 'All Statements 1, 2, and 3', false, '98238832-e547-4f26-a17b-f56ff3131440');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19f192d8-f46e-47d9-babf-d42e4ef76e76', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Why do modern historians consider the period between 700 and 1750 CE as a time of ''Great Mobility and Dynamic Flux''?', 'The era witnessed high geographic/social mobility: agrarian colonization, pastoral sedentarization, and dynamic political reconfiguration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24a5aa24-7397-4fca-b3d9-6bc63b65061a', 'Groups of people traveled vast distances in search of economic opportunity, pastoralists settled as peasants, forest dwellers integrated into jatis, and new warrior confederacies reshaped frontiers', true, '19f192d8-f46e-47d9-babf-d42e4ef76e76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1622faf1-aa2d-41af-84b8-cc244adafc45', 'Because people lived in airplanes', false, '19f192d8-f46e-47d9-babf-d42e4ef76e76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5382f5f5-f734-4a90-9dda-04cb577fe2d1', 'Because all cities were completely destroyed', false, '19f192d8-f46e-47d9-babf-d42e4ef76e76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15131181-eece-4a6a-b179-2eff7d850d3d', 'Because money was abolished', false, '19f192d8-f46e-47d9-babf-d42e4ef76e76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6723ede4-53b8-40c0-bb84-473fe62f02ff', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'How did Brahmanas achieve unrivaled social prestige and dominant ideological authority in early medieval society?', 'Epistemic monopoly over Sanskrit liturgy combined with royal land grants (Brahmadeya) consolidated Brahmanical socio-ritual dominance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8756eff8-9a27-4944-9775-970b23510512', 'Their mastery of sacred Sanskrit texts earned them profound veneration, while royal rulers granted them vast tax-free estates (Brahmadeya/Agraharas) and state patronage', true, '6723ede4-53b8-40c0-bb84-473fe62f02ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2fe4eb2-36ff-4a21-9f17-e2913079130b', 'They possessed the largest armies of cavalry', false, '6723ede4-53b8-40c0-bb84-473fe62f02ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40fc3462-418b-4817-98e0-47ce65f606bf', 'They were the only merchants in the kingdom', false, '6723ede4-53b8-40c0-bb84-473fe62f02ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e03aeea6-3925-4e35-9305-07a7178230df', 'They lived outside the subcontinent', false, '6723ede4-53b8-40c0-bb84-473fe62f02ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f057e381-c236-4ef1-a01a-35668933cf03', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Consider four medieval occupational groups:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a52e81b-beb6-45fc-b4c4-affd1759e760', 'They utilized emerging socio-political opportunities to claim elevated social status, political autonomy, and state-building power', true, 'f057e381-c236-4ef1-a01a-35668933cf03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e656a222-b58e-4dad-ba4a-d27110f9512e', 'They all gave up their occupations to become monks', false, 'f057e381-c236-4ef1-a01a-35668933cf03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a52244a-a18d-40f8-802d-e5af29e66b46', 'They were all foreign invaders from Europe', false, 'f057e381-c236-4ef1-a01a-35668933cf03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01c60ec6-064e-4248-9bce-45e80f3277ba', 'They completely disappeared from Indian history', false, 'f057e381-c236-4ef1-a01a-35668933cf03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aacc902f-f3a3-433e-bc06-99b0a2fb9178', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'What is the critical distinction between ''Continuity'' and ''Change'' in historical analysis as emphasized in Chapter 1?', 'Historical methodology balances identifying enduring structural continuities against dynamic socio-cultural transformations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92062433-79dd-4e76-b863-11e7fd593e95', 'History is not a series of abrupt isolated events, but a continuous dialectical process where cultural traditions persist alongside profound technological, economic, and political shifts', true, 'aacc902f-f3a3-433e-bc06-99b0a2fb9178');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e97df88f-4761-4e55-86ee-407a0057fef8', 'History only records sudden catastrophic changes', false, 'aacc902f-f3a3-433e-bc06-99b0a2fb9178');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e392a3b8-9d13-4f4b-8794-a75459dc4dbe', 'Nothing ever changes in human civilization', false, 'aacc902f-f3a3-433e-bc06-99b0a2fb9178');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b8c27ff-3976-4c30-9059-49a1c4ac6611', 'Only kings determine the path of history', false, 'aacc902f-f3a3-433e-bc06-99b0a2fb9178');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('980b654d-d087-44e2-894f-6f57d3b48126', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Why is the term ''Medieval'' problematic when applied uniformly across global civilizations without regional nuance?', 'Eurocentric ''Dark Age'' medieval tropes contrast starkly with India''s vibrant urbanization, agrarian growth, and cultural synthesis (700–1750 CE).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5827717-aab0-471c-9a37-06bbc7ee31d8', 'In Europe, ''Medieval'' was long stereotyped as a dark age lacking intellectual progress before the Renaissance; in India, the same period was an era of extraordinary technological, artistic, and economic vitality', true, '980b654d-d087-44e2-894f-6f57d3b48126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c669bc6d-3be7-4ce5-81ba-7c277bf5fe41', 'Because medieval means modern', false, '980b654d-d087-44e2-894f-6f57d3b48126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18367dd4-33a5-4c3e-bbe3-fa21492652ea', 'Because India had no history during this time', false, '980b654d-d087-44e2-894f-6f57d3b48126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('252011c1-ec57-45d2-b173-8494a43a6fa3', 'Because Europe was ahead in every science', false, '980b654d-d087-44e2-894f-6f57d3b48126');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f25aac7a-0265-46f3-9e5b-c28a5be45bde', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'What primary archival material provides the most reliable primary chronological records of medieval Persianate court administration?', 'Tawarikh chronicles (e.g. Tarikh-i Firuz Shahi) authored by court literati provide primary narrative accounts of governance and military campaigns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8ba115a-d14b-4100-9e79-9be0fa439bd7', 'Tarikh / Tawarikh (Persian historical chronicles written by literate court officials, secretaries, and poets)', true, 'f25aac7a-0265-46f3-9e5b-c28a5be45bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca9b3352-97fd-4471-8739-94e0fc0a35ba', 'Oral folk gossip', false, 'f25aac7a-0265-46f3-9e5b-c28a5be45bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d1217f2-513b-4de6-8304-8901b569a058', 'Roman coin hoards only', false, 'f25aac7a-0265-46f3-9e5b-c28a5be45bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16b8d008-311e-40f8-830e-95d94d6f6e3d', 'Cave rock paintings', false, 'f25aac7a-0265-46f3-9e5b-c28a5be45bde');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3c4566a-a495-4e31-8100-0eee533a4458', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'What foundational intellectual mindset does Chapter 1 of NCERT Class 7 History instill in young scholars?', 'The chapter equips students with historiographical toolkits: contextual source criticism, semantic evolution, and composite cultural synthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49c0c0e1-2e8a-4e77-aeb9-0e85b440f431', 'Critical historical inquiry: examining primary sources with contextual skepticism, tracing semantic shifts in language, and appreciating the deep multicultural roots of modern Indian society', true, 'f3c4566a-a495-4e31-8100-0eee533a4458');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3f8708e-4609-44dd-9c3a-1d0a2e075c1f', 'Unquestioning memorization of dates and king names', false, 'f3c4566a-a495-4e31-8100-0eee533a4458');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('771a69f2-3504-4522-ae44-d653d15e9728', 'Viewing the past through narrow sectarian biases', false, 'f3c4566a-a495-4e31-8100-0eee533a4458');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c434052-f617-44f0-870f-66d729b632bd', 'Believing that ancient maps were always wrong', false, 'f3c4566a-a495-4e31-8100-0eee533a4458');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cdb8714-a5dc-4a2f-8094-62f9ccc4e71a', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'मनुष्य अपने मन के भावों और विचारों का परस्पर आदान-प्रदान (बोलकर या लिखकर) जिस माध्यम से करता है, उसे व्याकरण में क्या कहते हैं?', 'मनुष्य के वैचारिक विनिमय और भाव-संप्रेषण के सार्थक साधन को ''भाषा'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32ce3857-f03c-4265-ab98-6f523b4ca1b3', 'भाषा (Language)', true, '3cdb8714-a5dc-4a2f-8094-62f9ccc4e71a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d063d1f-68bd-4a5f-9c33-1f5282506c8d', 'लिपि', false, '3cdb8714-a5dc-4a2f-8094-62f9ccc4e71a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba9307c8-bb2c-473d-b328-a348fddfab4c', 'व्याकरण', false, '3cdb8714-a5dc-4a2f-8094-62f9ccc4e71a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8f1c316-4df0-4cb6-b92f-ea310f0bd69e', 'बोली', false, '3cdb8714-a5dc-4a2f-8094-62f9ccc4e71a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4bc4fcb5-bbc7-4aa7-8c5b-3ad0702dc357', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'भाषा के मुख्य रूप से कितने रूप होते हैं?', 'भाषा के दो मूल रूप हैं: मौखिक (ध्वन्यात्मक उच्चारण) तथा लिखित (लिपिबद्ध आलेखन)। सांकेतिक रूप को व्याकरण में गौण माना जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('363dd264-0088-4c11-b55c-8894d50035b9', 'दो रूप (1. मौखिक भाषा - Spoken, 2. लिखित भाषा - Written)', true, '4bc4fcb5-bbc7-4aa7-8c5b-3ad0702dc357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e7a228a-49d4-439f-8d8d-e8f8241db222', 'चार रूप', false, '4bc4fcb5-bbc7-4aa7-8c5b-3ad0702dc357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d43136c-bf8b-4723-ac34-4b1b7955a7b4', 'तीन रूप', false, '4bc4fcb5-bbc7-4aa7-8c5b-3ad0702dc357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fb9939e-e55a-4b35-a7c0-7c3437a5f9eb', 'पाँच रूप', false, '4bc4fcb5-bbc7-4aa7-8c5b-3ad0702dc357');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e5eeaaa-6160-496b-9f97-ba89b1f6bdcb', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'मुख से बोलकर अपने विचारों को प्रकट करना तथा कानों से सुनकर समझना भाषा का कौन-सा रूप कहलाता है?', 'परस्पर बोलकर और सुनकर विचार व्यक्त करने का माध्यम ''मौखिक भाषा'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('393e8011-91be-4788-bc03-dd6a9730a543', 'मौखिक भाषा (Oral / Spoken Language)', true, '8e5eeaaa-6160-496b-9f97-ba89b1f6bdcb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fa44dd1-e7bd-4237-b480-18c8431822dd', 'लिखित भाषा', false, '8e5eeaaa-6160-496b-9f97-ba89b1f6bdcb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c57ac58-a414-496b-a73a-438730987c13', 'सांकेतिक भाषा', false, '8e5eeaaa-6160-496b-9f97-ba89b1f6bdcb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('087e3347-a37f-4a96-92e5-4fdc57cda4f9', 'मातृभाषा', false, '8e5eeaaa-6160-496b-9f97-ba89b1f6bdcb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab4e9d10-4093-410a-8713-49092f908bea', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'ध्वनियों को लिखकर प्रकट करने के लिए निश्चित किए गए विशेष चिह्न-संकेतों (Writing System) को क्या कहते हैं?', 'मौखिक ध्वनियों को लिखित रूप देने हेतु निर्धारित प्रतीकों/चिह्नों की व्यवस्था ''लिपि'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d66ba43-f821-417a-8228-793eea3bbfd2', 'लिपि (Script)', true, 'ab4e9d10-4093-410a-8713-49092f908bea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e66e5128-4bbb-45d2-9a68-753c1034c5eb', 'व्याकरण', false, 'ab4e9d10-4093-410a-8713-49092f908bea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50b35805-9426-4119-b3ee-9cffd509cb9a', 'बोली', false, 'ab4e9d10-4093-410a-8713-49092f908bea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('273531ca-3c5c-4af5-880c-1767e25f184c', 'वर्णमाला', false, 'ab4e9d10-4093-410a-8713-49092f908bea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b53b651-1f58-4b32-b19d-5b848e2ec139', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'हिंदी और संस्कृत भाषाएँ किस लिपि में लिखी जाती हैं?', 'हिंदी, संस्कृत, मराठी और नेपाली भाषाएँ बाएँ से दाएँ लिखी जाने वाली ''देवनागरी लिपि'' में आलेखित होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58781711-a355-4996-bac0-21a9c2433381', 'देवनागरी लिपि (Devanagari Script)', true, '4b53b651-1f58-4b32-b19d-5b848e2ec139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8826f43e-a596-4ac2-9a01-eb76ace79349', 'रोमन लिपि', false, '4b53b651-1f58-4b32-b19d-5b848e2ec139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73fe7025-d158-407b-a9e4-7c5e410fe84b', 'गुरुमुखी लिपि', false, '4b53b651-1f58-4b32-b19d-5b848e2ec139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6efb364-abf7-4e90-864f-46dd83954c9a', 'फ़ारसी लिपि', false, '4b53b651-1f58-4b32-b19d-5b848e2ec139');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9ca8d16-db8b-4131-bc3a-986ab42d09a0', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'अंग्रेज़ी भाषा किस लिपि में लिखी जाती है?', 'अंग्रेज़ी, फ़्रेंच, जर्मन और स्पैनिश भाषाएँ ''रोमन लिपि'' (लैटिन वर्णमाला) में लिखी जाती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07811d6c-7e5b-48ec-89b0-04db526d7c97', 'रोमन लिपि (Roman Script)', true, 'f9ca8d16-db8b-4131-bc3a-986ab42d09a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ed8bc2c-da05-4ac9-9bd0-0f495d6adca9', 'देवनागरी लिपि', false, 'f9ca8d16-db8b-4131-bc3a-986ab42d09a0');
