INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44617df4-1543-48e9-8470-97025a30673e', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'किसी सीमित क्षेत्रीय भू-भाग में बोली जाने वाली भाषा के स्थानीय, अनौपचारिक रूप को क्या कहते हैं?', 'सीमित क्षेत्र में प्रयुक्त बोलचाल का मौखिक रूप ''बोली'' (जैसे: अवधी, ब्रज, हरियाणवी, भोजपुरी) कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
