INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88aff25f-999b-4825-b178-77992775ca46', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'वह शास्त्र जो किसी भाषा के शुद्ध उच्चारण, शुद्ध लेखन और शुद्ध प्रयोग के नियमों का सम्यक ज्ञान कराता है, उसे क्या कहते हैं?', 'भाषा को मानकीकृत, अनुशासित और शुद्ध रूप प्रदान करने वाला नियामक शास्त्र ''व्याकरण'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
