INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68493269-d708-4316-b6a4-dc6e547d3896', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'भारतीय संविधान की किस धारा / अनुच्छेद (Article) के अंतर्गत हिंदी को भारत संघ की ''राजभाषा'' (Official Language) घोषित किया गया है?', 'संविधान के अनुच्छेद 343(1) के अनुसार संघ की राजभाषा हिंदी और लिपि देवनागरी है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('195fed67-1a50-4020-96fe-e652f848b5aa', 'अनुच्छेद 343 (Article 343 - 14 सितंबर 1949)', true, '68493269-d708-4316-b6a4-dc6e547d3896');
