INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7a9ca94-4174-4316-814b-1c014968495b', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'प्रत्येक वर्ष संपूर्ण भारत में ''हिंदी दिवस'' (Hindi Diwas) किस तिथि को राष्ट्रीय स्तर पर मनाया जाता है?', '14 सितंबर 1949 को संविधान सभा द्वारा हिंदी को राजभाषा स्वीकार किए जाने के उपलक्ष्य में प्रतिवर्ष ''हिंदी दिवस'' मनाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
