INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31aa6990-5129-496f-ba1c-758d7ca6134c', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के मुख्य रूप से कितने अंग (भाग / विभाग) होते हैं?', 'व्याकरण के 4 प्रमुख विभाग हैं: वर्ण विचार (ध्वनि), शब्द विचार (व्युत्पत्ति), पद विचार (रूपांतरण), तथा वाक्य विचार (संरचना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02550831-62b3-413e-b082-504361fd82df', 'चार अंग (1. वर्ण विचार - Phonology, 2. शब्द विचार - Morphology, 3. पद विचार - Syntax of parts, 4. वाक्य विचार - Syntax)', true, '31aa6990-5129-496f-ba1c-758d7ca6134c');
