INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('484258e3-db6c-4c91-b9d5-57bfc4af7f5f', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'बच्चा अपने परिवार और माता-पिता से शैशवावस्था में जो भाषा सबसे पहले स्वाभाविक रूप से सीखता है, उसे क्या कहते हैं?', 'पारिवारिक परिवेश में बालक द्वारा प्रथम अर्जित प्राथमिक भाषा ''मातृभाषा'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
