INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f6e8ee8-50d9-406f-9d7d-fcbf72bf95da', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'देश के अधिकांश नागरिकों द्वारा बोली और समझी जाने वाली सर्वमान्य संपर्क भाषा को क्या कहते हैं?', 'राष्ट्र के बहुसंख्यक जनसमुदाय द्वारा प्रयुक्त संपर्क एवं सांस्कृतिक एकता की सूत्रधार भाषा ''राष्ट्रभाषा'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
