INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2f63e90-174e-463f-8458-86cc40a738c1', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'सरकारी कामकाज, न्यायिक प्रशासन और राजकाज में संवैधानिक रूप से प्रयुक्त होने वाली भाषा को क्या कहते हैं?', 'राज्य एवं केंद्रीय शासन के प्रशासनिक कार्यों में अधिकृत रूप से प्रयुक्त भाषा ''राजभाषा'' है।', NOW()) ON CONFLICT DO NOTHING;
