INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fb23300-1b5e-4b86-b905-021d0c982de5', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'भारतीय संविधान की आठवीं अनुसूची (8th Schedule) में वर्तमान में कुल कितनी भारतीय भाषाओं को आधिकारिक संवैधानिक मान्यता प्राप्त है?', 'संविधान की 8वीं अनुसूची में असमिया, बाङ्ला, गुजराती, हिंदी, कन्नड़, कश्मीरी, कोंकणी, मलयालम, मणिपुरी, मराठी, नेपाली, ओडिया, पंजाबी, संस्कृत, सिंधी, तमिल, तेलुगु, उर्दू, बोडो, संथाली, मैथिली और डोगरी कुल 22 भाषाएँ शामिल हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4b935f2-480f-4a60-ab8f-00697af5eb82', '22 भाषाएँ (22 Officially Recognized Languages)', true, '2fb23300-1b5e-4b86-b905-021d0c982de5');
