INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f902b02-726f-4181-aaf1-22677372bfa8', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', '''बोली'' और ''भाषा'' में क्या मुख्य अंतर होता है?', 'बोली स्थानीय और अलिखित/मौखिक होती है; भाषा व्यापक, व्याकरण-सम्मत, लिपिबद्ध और साहित्यिक रूप धारण करती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f443cff3-a772-44f7-b226-90e37d5b0814', 'बोली का क्षेत्र सीमित होता है और उसमें मानक साहित्य नहीं रचा जाता ; जबकि भाषा का क्षेत्र व्यापक होता है, उसकी अपनी मानक लिपि तथा समृद्ध लिखित साहित्य होता है', true, '2f902b02-726f-4181-aaf1-22677372bfa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adfe0e6c-4a52-41f2-932f-3f9a216d88be', 'बोली केवल विदेशी बोलते हैं', false, '2f902b02-726f-4181-aaf1-22677372bfa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a2c273-d1ca-4aec-85ee-3c6405422292', 'भाषा केवल किताबों में होती है', false, '2f902b02-726f-4181-aaf1-22677372bfa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('641a25da-f05d-4972-8cc1-3a06d2700de9', 'दोनों में कोई अंतर नहीं है', false, '2f902b02-726f-4181-aaf1-22677372bfa8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7775404-0587-4cf9-8b2d-7c3b698e6d88', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'जब किसी बोली में प्रचुर उत्कृष्ट साहित्य की रचना होने लगती है और उसका क्षेत्र विस्तृत हो जाता है (जैसे: सूरदास का ब्रजभाषा साहित्य, तुलसीदास की अवधी), तब वह क्या कहलाती है?', 'साहित्यिक सृजन से समृद्ध बोली ''उपभाषा'' का स्तर प्राप्त कर लेती है (जैसे: अवधी, ब्रजभाषा, मैथिली)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f626adf8-43e0-4ad4-964b-0f8b8dcedd44', 'उपभाषा (Sub-language / Literary Dialect)', true, 'f7775404-0587-4cf9-8b2d-7c3b698e6d88');
