INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e12730db-f57f-49bc-a79f-7edd887cade2', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'ज्ञान के संचित और व्यवस्थित कोष (कोष / खजाने) को क्या कहते हैं?', 'युग-युगांतर से संचित कल्याणकारी ज्ञानराशि और अनुभूतियों का व्यवस्थित लिखित संग्रह ''साहित्य'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b75bc5d3-bc74-46fd-ba0c-ff0db41a0528', 'साहित्य (Literature)', true, 'e12730db-f57f-49bc-a79f-7edd887cade2');
