INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a411d9f4-7f1d-4a1e-b6e5-abb88754693c', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'साहित्य के मुख्य रूप से दो भेद कौन-से होते हैं?', 'साहित्य के दो मूल वर्गीकरण हैं: गद्य (छंदमुक्त गद्यात्मक अभिव्यक्ति) तथा पद्य (गेय, लयात्मक, छंदोबद्ध काव्य)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89b9b77d-38c9-4d98-bc6f-05bf5715dfbd', 'गद्य साहित्य (Prose - कहानी, निबंध, उपन्यास) और पद्य साहित्य (Poetry - कविता, पद, दोहे)', true, 'a411d9f4-7f1d-4a1e-b6e5-abb88754693c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d52f9f50-01c5-4fa2-b2b5-f2b4eab064a3', 'मौखिक साहित्य और लिखित साहित्य', false, 'a411d9f4-7f1d-4a1e-b6e5-abb88754693c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0047208-b748-4e86-8f12-579d842213b4', 'प्राचीन साहित्य और नया साहित्य', false, 'a411d9f4-7f1d-4a1e-b6e5-abb88754693c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('784f0bbc-8732-4e43-81b4-f8f482ec9652', 'देशी साहित्य और विदेशी साहित्य', false, 'a411d9f4-7f1d-4a1e-b6e5-abb88754693c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e01e56a4-fc3c-4c68-bdcf-222a04280bc7', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'देवनागरी लिपि की सर्वप्रमुख वैज्ञानिक विशेषता क्या है?', 'देवनागरी की विशिष्टता उसका वैज्ञानिक ध्वनि-प्रतीक सामंजस्य है: पूर्ण ध्वन्यात्मक संगति और शिरोरेखा (Head-line)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5644c9df-bc9c-4476-853d-854acb39630c', 'यह पूर्णतः ध्वन्यात्मक (Phonetic) लिपि है — जैसा बोला और उच्चारित किया जाता है, ठीक वैसा ही अक्षरशः लिखा और पढ़ा जाता है (प्रत्येक ध्वनि के लिए अद्वितीय वर्ण)', true, 'e01e56a4-fc3c-4c68-bdcf-222a04280bc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ae955a8-0807-4283-93a9-7b41b9eb470e', 'इसमें केवल 10 वर्ण होते हैं', false, 'e01e56a4-fc3c-4c68-bdcf-222a04280bc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc593331-53ab-4d1a-b43b-b1e89e1968eb', 'यह ऊपर से नीचे लिखी जाती है', false, 'e01e56a4-fc3c-4c68-bdcf-222a04280bc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff31ac66-e7ea-403d-9a10-b32256a1579a', 'इसमें कोई स्वर नहीं होते', false, 'e01e56a4-fc3c-4c68-bdcf-222a04280bc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94b80d05-3dc2-492b-8d9e-a1b3031d86cc', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग के अंतर्गत वर्णों के आकार, उच्चारण, वर्गीकरण तथा संधि नियमों का अध्ययन किया जाता है?', 'वर्ण विचार में वर्णों के भेद, उच्चारण स्थान और ध्वनि संयोग का सैद्धांतिक अध्ययन होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd33fcc3-5c4f-446d-80ce-d92b755bbad3', 'वर्ण विचार (Phonology)', true, '94b80d05-3dc2-492b-8d9e-a1b3031d86cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c24bf83-3635-425f-b1d8-224d18701378', 'शब्द विचार', false, '94b80d05-3dc2-492b-8d9e-a1b3031d86cc');
