INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a09c0417-b20e-4ad3-991b-23930030bb6e', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग के अंतर्गत शब्दों के भेद, उत्पत्ति, व्युत्पत्ति तथा रचना का अध्ययन किया जाता है?', 'शब्द विचार में तत्सम, तद्भव, देशज, विदेशी, रूढ़, यौगिक और योगरूढ़ शब्दों की संरचना का विश्लेषण होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c04ebe5d-b6ff-4224-b3e1-d9a281c0843f', 'शब्द विचार (Morphology)', true, 'a09c0417-b20e-4ad3-991b-23930030bb6e');
