INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85f78600-07a2-48a9-8004-ad78d89b7e83', 'छंद विचार', false, 'a09c0417-b20e-4ad3-991b-23930030bb6e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e404f2aa-28d1-43d3-ace6-46d297e6e7b1', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'जब कोई स्वतंत्र शब्द वाक्य में व्याकरणिक नियमों (लिंग, वचन, कारक) के अनुसार प्रयुक्त होता है, तब वह क्या कहलाता है?', 'वाक्य में प्रयुक्त होकर व्याकरणिक संबंध स्थापित करने वाला शब्द ''पद'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c97204e-0f5a-496d-adce-8d5a79e013ec', 'पद (Word in syntactic context)', true, 'e404f2aa-28d1-43d3-ace6-46d297e6e7b1');
