INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12c907f0-cdf6-4fd4-8b8d-25d3667982c5', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग के अंतर्गत वाक्य की रचना, वाक्य के अंग (उद्देश्य और विधेय), भेद तथा विराम चिह्नों का अध्ययन किया जाता है?', 'वाक्य विचार में वाक्य के अंगों, रूपांतरण, संश्लेषण और विश्लेषण का नियमन होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4007b35-da34-4364-9853-a77d76e22994', 'वाक्य विचार (Syntax)', true, '12c907f0-cdf6-4fd4-8b8d-25d3667982c5');
