INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82aa168a-d044-4e6c-8744-e0da1bf9cd42', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'विश्व में सबसे अधिक बोली जाने वाली भाषाओं में हिंदी का स्थान कौन-सा है?', 'वैश्विक जनसांख्यिकी (Ethnologue) में अंग्रेजी और मंदारिन के उपरांत हिंदी विश्व की तीसरी सर्वाधिक प्रयुक्त भाषा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4a1771d-9e0a-4787-b19a-90014df012c9', 'विश्व की तीसरी (3rd) सर्वाधिक बोली जाने वाली वृहत्तम भाषा', true, '82aa168a-d044-4e6c-8744-e0da1bf9cd42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68f1be7b-4971-4102-a64a-4d92b68f62f1', 'दसवाँ स्थान', false, '82aa168a-d044-4e6c-8744-e0da1bf9cd42');
