INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd70ca0d-91ef-4090-94a6-3f7314996c33', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'निम्नलिखित में से कौन-सी भाषा देवनागरी लिपि में नहीं लिखी जाती है?', 'उर्दू फ़ारसी लिपि में लिखी जाती है; जबकि संस्कृत, मराठी, नेपाली और हिंदी देवनागरी में आलेखित होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ea93c58-b7a1-44e9-a69a-831cbcf32197', 'उर्दू (जो फ़ारसी लिपि में लिखी जाती है)', true, 'dd70ca0d-91ef-4090-94a6-3f7314996c33');
