INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d07502e-c735-4a91-9b25-16cfa08ecb53', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21feb5a6-b0d0-44f1-8603-9bb09df057c0', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '2d07502e-c735-4a91-9b25-16cfa08ecb53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d13e45e0-6aef-46d0-9c44-4db548077b68', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '2d07502e-c735-4a91-9b25-16cfa08ecb53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2c7538b-6a1b-444a-aa94-3bcbbb4fb098', '(A) सही है, परन्तु (R) गलत है।', false, '2d07502e-c735-4a91-9b25-16cfa08ecb53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a45b3af9-2ca3-4173-ae21-519a27c2b625', '(A) गलत है, परन्तु (R) सही है।', false, '2d07502e-c735-4a91-9b25-16cfa08ecb53');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25253376-905b-4bce-8a7f-de1d302fc372', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'Spot the IMPOSTER in the following group of भाषाएँ और उनकी मानक लिपियों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d436f569-51b4-416a-87c9-31a031453818', 'हिंदी - देवनागरी', false, '25253376-905b-4bce-8a7f-de1d302fc372');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e931c2b-d61d-4f27-8914-5ca99e0e7dec', 'अंग्रेज़ी - रोमन', false, '25253376-905b-4bce-8a7f-de1d302fc372');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b1a607e-6667-4b3f-bff0-b782d8280be4', 'Punjabi - गुरुमुखी', false, '25253376-905b-4bce-8a7f-de1d302fc372');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('705c5117-9506-454b-9022-983bcdbb6a0b', 'अरबी - देवनागरी', true, '25253376-905b-4bce-8a7f-de1d302fc372');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f9e6e00-73c7-4cd4-9a82-c6ef0a691e6a', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'सुमेलित कीजिए (भाषा/बोली और उसके भौगोलिक/सांस्कृतिक वर्ग):
(क) अवधी और ब्रजभाषा -> (i) पश्चिमी व पूर्वी हिंदी की समृद्ध उपभाषाएँ
(ख) मैथिली और भोजपुरी -> (ii) बिहारी हिंदी वर्ग की बोलियाँ
(ग) गढ़वाली व कुमाऊँनी -> (iii) पहाड़ी हिंदी वर्ग की बोलियाँ
(घ) मारवाड़ी व जयपुरी  -> (iv) राजस्थानी हिंदी वर्ग की बोलियाँ', 'अवधी/ब्रज = मध्य देश; मैथिली/भोजपुरी = बिहारी; गढ़वाली/कुमाऊँनी = पहाड़ी; मारवाड़ी = राजस्थानी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9413869b-62d1-4b25-9d93-224582360795', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '5f9e6e00-73c7-4cd4-9a82-c6ef0a691e6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18975e54-33e9-4a6a-864f-00b2b2d99bb1', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '5f9e6e00-73c7-4cd4-9a82-c6ef0a691e6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e6bb8a4-b15a-4490-957b-cce1b4a6f1b1', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '5f9e6e00-73c7-4cd4-9a82-c6ef0a691e6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8561b943-b4c8-49d6-8ce9-eb6e8ab9b9c1', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '5f9e6e00-73c7-4cd4-9a82-c6ef0a691e6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18a6fca0-744c-44c1-be16-8fec6611de44', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'व्याकरण भाषा का निर्माण करता है अथवा भाषा का नियमन और अनुशासन करता है? सही दार्शनिक संबंध बताइए:', 'भाषा नैसर्गिक रूप से अग्रगामी होती है; व्याकरण भाषा का अनुगामी विश्लेषक एवं मानकीकृत नियामक होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c99f5506-3a5d-41f4-9a89-3e4053a79620', 'भाषा पहले स्वाभाविक रूप से जन्म लेती है और लोकव्यवहार में विकसित होती है ; व्याकरण भाषा का निर्माण नहीं करता, अपितु प्रचलित भाषा के स्वरूप का वैज्ञानिक विश्लेषण करके उसके नियम निर्धारित और अनुशासित करता है', true, '18a6fca0-744c-44c1-be16-8fec6611de44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfbf0ad1-07f3-445c-94de-4fb52352dcac', 'व्याकरण पहले बनता है फिर भाषा बनती है', false, '18a6fca0-744c-44c1-be16-8fec6611de44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc18e7c-9326-4214-b8b4-7a8bf0b2a959', 'व्याकरण के बिना मनुष्य बोल ही नहीं सकता', false, '18a6fca0-744c-44c1-be16-8fec6611de44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43265cb1-f1f6-4e30-819f-bd40ffa15db8', 'भाषा और व्याकरण में कोई संबंध नहीं होता', false, '18a6fca0-744c-44c1-be16-8fec6611de44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('235be02c-8ba8-4b48-9c0f-76cec5d90e75', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'अंतर्राष्ट्रीय स्तर पर विश्व के विभिन्न देशों के बीच विचार-विमर्श, व्यापार तथा कूटनीतिक संपर्क के लिए स्वीकृत सर्वमान्य भाषा को क्या कहते हैं?', 'वैश्विक कूटनीति, वाणिज्य एवं वैज्ञानिक शोध हेतु प्रयुक्त वैश्विक संपर्क भाषा ''अंतर्राष्ट्रीय भाषा'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a54428d1-c15e-4ec1-adb4-87042ed4b4ab', 'अंतर्राष्ट्रीय भाषा (International Language - जैसे: अंग्रेज़ी)', true, '235be02c-8ba8-4b48-9c0f-76cec5d90e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94d88029-9211-41d8-8fef-6ebdd56442b6', 'राजभाषा', false, '235be02c-8ba8-4b48-9c0f-76cec5d90e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de2833ae-bdbb-4e12-bc0a-70630bfd5636', 'मातृभाषा', false, '235be02c-8ba8-4b48-9c0f-76cec5d90e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d45ebfe-7b83-4f39-8f77-2aa209b3e6a4', 'बोली', false, '235be02c-8ba8-4b48-9c0f-76cec5d90e75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38b9c3b0-6576-47fa-a887-7062b3ee904b', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'देवनागरी लिपि का ऐतिहासिक उद्भव और विकास भारत की किस प्राचीन ऐतिहासिक लिपि से हुआ है?', 'देवनागरी, बंगाली, तमिल, तेलुगु आदि अधिकांश भारतीय लिपियों की जननी प्राचीन ''ब्राह्मी लिपि'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fe1daca-9520-4da2-8a2f-10fedad0ff84', 'ब्राह्मी लिपि (Brahmi Script - सम्राट अशोक के अभिलेखों की मूल लिपि)', true, '38b9c3b0-6576-47fa-a887-7062b3ee904b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('034cac40-a291-473b-a0bd-dfb174f3ed6a', 'खरोष्ठी लिपि', false, '38b9c3b0-6576-47fa-a887-7062b3ee904b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('476ea579-5952-40c8-bba5-3d2399c0f5af', 'सिंधु घाटी लिपि', false, '38b9c3b0-6576-47fa-a887-7062b3ee904b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('201741f0-3c0a-44f7-ac85-4a2e9478770f', 'अरामी लिपि', false, '38b9c3b0-6576-47fa-a887-7062b3ee904b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bebf70e3-a5bf-45bb-a5eb-f28a34748eec', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', '''मानक भाषा'' (Standard Language) से क्या अभिप्राय है?', 'मानक भाषा (Standard Register) प्रामाणिक व्याकरणिक मानदंडों पर आधारित सर्वमान्य साहित्यिक व प्रशासनिक माध्यम है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('426b130b-5b67-4503-99f6-91d02fb198c6', 'विद्वानों, शिक्षाविदों तथा शासन द्वारा सर्वसम्मति से स्वीकृत भाषा का वह शुद्ध, व्याकरण-सम्मत, एकरूप तथा सर्वमान्य रूप जो पत्र-पत्रिकाओं, पुस्तकों और दूरदर्शन में प्रयुक्त होता है', true, 'bebf70e3-a5bf-45bb-a5eb-f28a34748eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2868c1fc-2b61-448f-a4ec-db1e2052ff20', 'केवल अनपढ़ लोगों द्वारा बोली जाने वाली भाषा', false, 'bebf70e3-a5bf-45bb-a5eb-f28a34748eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a63417f-a694-46c8-acd2-29df2a0b6de0', 'वह भाषा जिसमें कोई नियम न हो', false, 'bebf70e3-a5bf-45bb-a5eb-f28a34748eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03ceb423-b436-4945-9935-644fb18b379d', 'प्राचीन समय की मृत भाषा', false, 'bebf70e3-a5bf-45bb-a5eb-f28a34748eec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dddcb2d-3048-4d7f-82b2-69cefe428172', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'विचार कीजिए (चार कथन):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('822423f6-e080-4d31-955f-639abbb3646e', 'सभी 1, 2, 3 और 4 पूर्णतः सत्य हैं', true, '6dddcb2d-3048-4d7f-82b2-69cefe428172');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43b7fdbe-b225-4dca-86a1-23dd92553b3c', 'केवल 1 और 2', false, '6dddcb2d-3048-4d7f-82b2-69cefe428172');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2524503-e88e-457c-8bff-5e48fbfccb9e', 'केवल 2 और 3', false, '6dddcb2d-3048-4d7f-82b2-69cefe428172');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0669ade5-5fb5-4986-a52a-233acfc944b0', 'केवल 3 और 4', false, '6dddcb2d-3048-4d7f-82b2-69cefe428172');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dc54b8f-df04-4a81-b8b8-9b2709b53933', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'वाक्य में अशुद्ध अंश की पहचान कीजिए और व्याकरणिक दोष का कारण बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb4370e8-0cc0-4692-8382-c5f3bccd2998', '''मुझे आपकी बात समझ नहीं आई।'' (सर्वनाम संबंधी अशुद्धि : ''मेरे को'' के स्थान पर मानक सर्वनाम ''मुझे'' का प्रयोग)', true, '6dc54b8f-df04-4a81-b8b8-9b2709b53933');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29d295ef-911c-40e2-9b5a-47786cd6c4b1', '''मुझको आपकी बात समझ नहीं आई।''', false, '6dc54b8f-df04-4a81-b8b8-9b2709b53933');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('310b72f3-cc8d-4465-9318-fb0696e058b3', '''मैं को आपकी बात समझ नहीं आई।''', false, '6dc54b8f-df04-4a81-b8b8-9b2709b53933');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c707eff0-497d-4a1c-ae44-2931cada2e14', '''मेरे द्वारा आपकी बात समझी गई।''', false, '6dc54b8f-df04-4a81-b8b8-9b2709b53933');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4e911c0-af8d-4594-bba1-07f697ab4b8c', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'ध्वनि (Phoneme) और वर्ण (Letter) में क्या सूक्ष्म अंतर होता है?', 'ध्वनि श्रव्य/मौखिक न्यूनतम इकाई है; वर्ण उसका दृश्य/लिखित आलेखीय प्रतीक (Grapheme) है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('842ce50d-4848-420f-9c0f-24fcda56d2f2', 'ध्वनि मौखिक भाषा की सबसे छोटी अविभाज्य उच्चरित इकाई है (कानों से सुनाई देती है) ; जबकि वर्ण उसी ध्वनि का लिखित दृश्य रूप/चिह्न है (आँखों से देखा जाता है)', true, 'd4e911c0-af8d-4594-bba1-07f697ab4b8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('316487d4-366c-4f48-af01-f8243f02bf89', 'ध्वनि और वर्ण में कोई अंतर नहीं है', false, 'd4e911c0-af8d-4594-bba1-07f697ab4b8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2d32e0d-ae4a-471a-b480-6c06464ef7cf', 'ध्वनि केवल वाद्ययंत्रों में होती है', false, 'd4e911c0-af8d-4594-bba1-07f697ab4b8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08ea8497-fc21-4f28-9b25-46e005ae945b', 'वर्ण केवल कागज़ का नाम है', false, 'd4e911c0-af8d-4594-bba1-07f697ab4b8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('250813d8-45df-4d5c-9a72-9f59a31cf365', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'भाषा के मानकीकरण में केंद्रीय हिंदी निदेशालय और वैज्ञानिक तथा तकनीकी शब्दावली आयोग (CSTT) की क्या भूमिका है?', 'केंद्रीय हिंदी निदेशालय मानक वर्तनी, तकनीकी शब्दावली और देवनागरी यूनिकोड का मानकीकरण सुनिश्चित करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7e611d6-c76e-4759-a9e3-f500ce29c94b', 'हिंदी वर्तनी, पारिभाषिक शब्दावली और देवनागरी लिपि के मानकीकृत नियमों का निर्धारण करना ताकि पूरे राष्ट्र में एकरूपता बनी रहे', true, '250813d8-45df-4d5c-9a72-9f59a31cf365');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f9ffc4e-7aa8-490f-9310-84515d01fd61', 'नई बोलियों पर प्रतिबंध लगाना', false, '250813d8-45df-4d5c-9a72-9f59a31cf365');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41e1f3a0-75c9-4f5a-b7f1-c76f53744377', 'केवल पुरानी पुस्तकें छापना', false, '250813d8-45df-4d5c-9a72-9f59a31cf365');
