INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93045864-0b58-42ac-afc3-7194fead088a', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'कक्षा 7 हिंदी व्याकरण के प्रथम अध्याय का सारगर्भित निष्कर्ष क्या है?', 'अध्याय 1 भाषा के सांस्कृतिक महत्व, लिपि की ऐतिहासिकता तथा व्याकरण की नियामक सौंदर्य-चेतना को प्रतिष्ठापित करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7f9dcc3-034e-4d1b-8d31-4e55a54f3584', 'भाषा मानव अभिव्यक्ति का अमूल्य वरदान है, लिपि उसकी अमर स्मृति है, और व्याकरण वह प्रकाश स्तंभ है जो भाषा को शुद्धता, अनुशासन और अमरता प्रदान करता है', true, '93045864-0b58-42ac-afc3-7194fead088a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f04aa1a3-5bed-482d-a0f9-ed19ee129584', 'व्याकरण का अध्ययन केवल परीक्षा पास करने के लिए है', false, '93045864-0b58-42ac-afc3-7194fead088a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51bfc9fe-7b78-47f1-846b-57e4cdce174d', 'बिना व्याकरण के भी भाषा हमेशा शुद्ध रहती है', false, '93045864-0b58-42ac-afc3-7194fead088a');
