INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b668e4d-0001-4301-ab36-644f6b4ff0d4', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'What digestive fluid is secreted by the Salivary Glands into the mouth to moisten food and break down starch into simple sugars?', 'Saliva contains ptyalin/amylase which initiates the chemical digestion of starch into maltose sugar.', NOW()) ON CONFLICT DO NOTHING;
