INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5596f14-9da6-4e34-90cf-101dce93c8af', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'What acid is secreted by the inner lining of the Stomach to kill harmful bacteria ingested with food and provide an acidic medium for pepsin?', 'Gastric parietal cells secrete dilute HCl (pH ~1.5–2) to kill pathogens and activate the protein enzyme pepsin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51b01e09-5757-4136-8fd3-548b43446a19', 'Hydrochloric Acid (HCl)', true, 'e5596f14-9da6-4e34-90cf-101dce93c8af');
