INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd3e2c26-97ba-4815-a092-35dbe355c466', 'Citric Acid', false, 'e5596f14-9da6-4e34-90cf-101dce93c8af');
