INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02088cb9-3ecd-48d3-9d93-c13df1434dba', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'Which is the LARGEST gland in the human body, reddish-brown in color, situated in the upper abdomen on the right side?', 'The liver is the heaviest internal metabolic gland (~1.5 kg in adults), secreting bile for fat emulsification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb5804cc-1322-439a-986d-45284e46fb0c', 'Liver', true, '02088cb9-3ecd-48d3-9d93-c13df1434dba');
