INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63ac2950-c1ff-4da9-b9d2-1dd22dbf4e9d', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'Where is Bile juice stored in the body before being released into the small intestine?', 'Bile secreted by hepatic cells is concentrated and stored inside the muscular sac-like Gall Bladder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12cde0ce-9d26-4641-9aaf-5f8fd9498001', 'Gall Bladder', true, '63ac2950-c1ff-4da9-b9d2-1dd22dbf4e9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47acbf75-6738-4aeb-a45c-84d28639a081', 'Stomach', false, '63ac2950-c1ff-4da9-b9d2-1dd22dbf4e9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41e2e9a2-3729-4a6e-903f-e383f84200be', 'Pancreas', false, '63ac2950-c1ff-4da9-b9d2-1dd22dbf4e9d');
