INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddc4228c-d859-44f0-a141-72fc811a0dae', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'What are the thousands of tiny, finger-like outgrowths on the inner walls of the Small Intestine that dramatically increase the surface area for food absorption called?', 'Intestinal villi and microvilli expand internal surface area multi-hundredfold, lined with rich capillary networks for nutrient absorption.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a5a629d-30fc-4251-8ca8-3650c87572b5', 'Villi (singular: Villus)', true, 'ddc4228c-d859-44f0-a141-72fc811a0dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41b10420-921c-40a1-b109-f7c2e6689cfd', 'Cilia', false, 'ddc4228c-d859-44f0-a141-72fc811a0dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d78b40e-7cb7-4970-9cb3-941e2182ce78', 'Pseudopodia', false, 'ddc4228c-d859-44f0-a141-72fc811a0dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec7a989f-99e8-479a-b0fb-c48269544a74', 'Flagella', false, 'ddc4228c-d859-44f0-a141-72fc811a0dae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae59ea1f-a88e-45c9-a9e7-3d32635db738', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'How does the microscopic single-celled organism Amoeba capture and engulf its food?', 'Amoeba uses cytoplasmic streaming to extend pseudopodia, engulfing prey by phagocytosis into a food vacuole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('330e595e-a13f-46b6-9d15-aa054b6f6b2d', 'By extending finger-like false feet called Pseudopodia around the food particle to form a Food Vacuole', true, 'ae59ea1f-a88e-45c9-a9e7-3d32635db738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('922e55c0-6a2c-4585-b0c4-0cd250215646', 'Using sharp teeth', false, 'ae59ea1f-a88e-45c9-a9e7-3d32635db738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd8559fb-8560-4acd-8943-900e975bdc6f', 'Through a wide mouth', false, 'ae59ea1f-a88e-45c9-a9e7-3d32635db738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fdcd87b-5755-4eed-b0f1-c6593f7cb354', 'By swimming with fins', false, 'ae59ea1f-a88e-45c9-a9e7-3d32635db738');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e15d1ce-ef43-4801-a4f4-aae037cdfa55', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Why do cows, buffaloes, and other grass-eating animals chew continuously even when they are resting and not eating fresh grass?', 'Ruminants regurgitate cud from the rumen back to the buccal cavity for secondary mastication and enzymatic breakdown.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb191366-315c-46ad-b9d4-f00e32c1bf1c', 'They quickly swallow grass into the Rumen where it is partially digested into ''Cud''; later, cud returns to the mouth in small lumps for thorough chewing (Rumination)', true, '5e15d1ce-ef43-4801-a4f4-aae037cdfa55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5b5beb0-ede4-4850-91ae-2f6625ce858a', 'Because their teeth never stop growing', false, '5e15d1ce-ef43-4801-a4f4-aae037cdfa55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0ff9694-c7e7-4c05-bc94-1bf3fd4472b3', 'Because they are chewing bubblegum', false, '5e15d1ce-ef43-4801-a4f4-aae037cdfa55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c132fca6-4dd8-4c0c-baf5-183972f84420', 'To make grass colder', false, '5e15d1ce-ef43-4801-a4f4-aae037cdfa55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff08daf1-32f5-4aa0-9f9d-fcee392b2b46', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Why can ruminant animals (cows, goats) digest tough plant Cellulose while human beings CANNOT digest cellulose at all?', 'Ruminant caecum/rumen harbors cellulolytic microbes breaking β-1,4-glycosidic cellulose bonds, which humans pass as dietary fiber.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4541e39-90b3-4bec-93ee-168b2ace0183', 'Ruminants have a large sac-like Caecum containing specialized symbiotic anaerobic bacteria and protozoa that produce cellulose-digesting enzymes (cellulase), which humans lack', true, 'ff08daf1-32f5-4aa0-9f9d-fcee392b2b46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a24cb5b-b7b2-4146-a291-d3efcbcf888c', 'Because humans have smaller teeth than cows', false, 'ff08daf1-32f5-4aa0-9f9d-fcee392b2b46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c77ae49-f2ac-4b22-affb-5ffed73dbe3f', 'Because human stomachs have no acid', false, 'ff08daf1-32f5-4aa0-9f9d-fcee392b2b46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a220d162-1f8c-42e3-8599-88efefccfe46', 'Because cows drink more water', false, 'ff08daf1-32f5-4aa0-9f9d-fcee392b2b46');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e483e07d-9370-4dec-84f5-76a84051cda7', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What protects the delicate inner wall lining of the Stomach from being corroded and digested by its own potent Hydrochloric Acid?', 'Gastric epithelial mucous cells secrete a bicarbonate-rich mucosal barrier protecting against acid-peptic autodigestion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35325057-1c96-48ac-acec-ee5a80494280', 'A thick, slippery protective layer of Mucous secreted by gastric mucosal cells', true, 'e483e07d-9370-4dec-84f5-76a84051cda7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f2b7012-027b-4671-9a38-059f92346951', 'A layer of plastic', false, 'e483e07d-9370-4dec-84f5-76a84051cda7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5407da10-84b4-4803-a43b-621e39e3e494', 'Saliva from the mouth', false, 'e483e07d-9370-4dec-84f5-76a84051cda7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e737e5b-bb10-4e69-bb31-4ba4ee7ccb3b', 'Bile juice', false, 'e483e07d-9370-4dec-84f5-76a84051cda7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0db4cf26-2f79-4a67-a66b-2d596a1a6409', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is the wave-like muscular contraction and relaxation of the walls of the Food Pipe (Oesophagus) that pushes swallowed food down into the stomach called?', 'Peristalsis is the rhythmic, coordinated involuntary contraction of longitudinal and circular gastrointestinal muscles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7830d068-f6c7-46e1-9918-b6f401397e40', 'Peristalsis (Peristaltic Movement)', true, '0db4cf26-2f79-4a67-a66b-2d596a1a6409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5379954-b278-45e3-84d4-61854aaa2fd0', 'Circulation', false, '0db4cf26-2f79-4a67-a66b-2d596a1a6409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f77c18a-83ed-4b67-971c-084317d22009', 'Respiration', false, '0db4cf26-2f79-4a67-a66b-2d596a1a6409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13e6db3d-0cdb-4cc2-9521-b27e10b71542', 'Filtration', false, '0db4cf26-2f79-4a67-a66b-2d596a1a6409');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf6e5437-5370-4fd6-9d62-913ec51ad2aa', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What crucial digestive role does Bile Juice play in the digestion of dietary FATS in the small intestine?', 'Bile salts (sodium glycocholate/taurocholate) act as biological detergents, emulsifying lipid triglycerides for lipase action.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('453acdaf-2775-4fff-8510-6c3d3c9f9273', 'It emulsifies large fat globules into tiny micro-droplets, dramatically increasing the surface area for pancreatic lipase enzymes to break down fats into fatty acids and glycerol', true, 'bf6e5437-5370-4fd6-9d62-913ec51ad2aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd5e9b30-4c41-4991-8037-ba3893f7bb19', 'It converts fats directly into proteins', false, 'bf6e5437-5370-4fd6-9d62-913ec51ad2aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eb4ba2b-3031-43b4-8359-ba6e6e822bdd', 'It turns fats into solid bones', false, 'bf6e5437-5370-4fd6-9d62-913ec51ad2aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fcf2250-fa42-454e-b642-e729c4636632', 'It freezes fats so they cannot enter blood', false, 'bf6e5437-5370-4fd6-9d62-913ec51ad2aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09296c3c-0ecf-4115-b26b-29d43877f5f5', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is ''Tooth Decay'' (Dental Caries) and what causes it?', 'Streptococcus mutans ferment oral sucrose into lactic acid, demineralizing hydroxyapatite enamel below critical pH 5.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4161b8ae-da99-44db-bdd4-0669c0e9c94d', 'Bacteria present in mouth feed on leftover sugary food particles and produce corrosive ACIDS that gradually dissolve the hard calcium enamel and dentine', true, '09296c3c-0ecf-4115-b26b-29d43877f5f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0216967a-c8aa-4d63-9708-a268906efb9d', 'Eating too many green vegetables', false, '09296c3c-0ecf-4115-b26b-29d43877f5f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2731e23-652d-418c-beb6-91782b3b5f4b', 'Brushing teeth with toothpaste twice a day', false, '09296c3c-0ecf-4115-b26b-29d43877f5f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d39f2eaf-af95-44ad-b1cc-0bf41a5e98da', 'Drinking cold water', false, '09296c3c-0ecf-4115-b26b-29d43877f5f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d70a762-add1-45b9-8a63-58c7b75639a3', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is the primary physiological function of the LARGE INTESTINE in the human digestive system?', 'The colon/large intestine reabsorbs ~90% of residual luminal water and electrolytes, consolidating solid feces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96c15c35-80e1-4660-add6-7bdc43bc3fb5', 'Absorption of water and essential mineral salts from unabsorbed, undigested food matter, forming solid fecal waste for egestion', true, '0d70a762-add1-45b9-8a63-58c7b75639a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0540291-f55e-4d02-b93c-b099834f93f2', 'Complete digestion of proteins and fats', false, '0d70a762-add1-45b9-8a63-58c7b75639a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcea7368-1c8e-45c2-aa26-7c362ecec5e1', 'Secretion of hydrochloric acid', false, '0d70a762-add1-45b9-8a63-58c7b75639a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7d30b1b-2053-4eeb-960f-5f6ab2d3435a', 'Pumping blood to the heart', false, '0d70a762-add1-45b9-8a63-58c7b75639a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46bbc655-c966-4196-8af5-74c69b24b96c', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is ''Assimilation'' in animal nutrition?', 'Assimilation is the cellular anabolic incorporation of absorbed amino acids, monosaccharides, and fatty acids into living protoplasm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3202bbfc-fbed-4bcb-a96a-a6466be7834f', 'The transport and utilization of absorbed nutrient molecules by body cells to build complex tissues (proteins, cell membranes) and release energy for growth', true, '46bbc655-c966-4196-8af5-74c69b24b96c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7414491-0ede-46dd-b6d0-b9ea02e14cb6', 'The removal of undigested feces through anus', false, '46bbc655-c966-4196-8af5-74c69b24b96c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bdbd965-94c8-4837-979f-8f63313cdca2', 'Chewing food in mouth', false, '46bbc655-c966-4196-8af5-74c69b24b96c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71e6aa56-4157-45df-8df9-5b1a83e025fc', 'Swallowing water', false, '46bbc655-c966-4196-8af5-74c69b24b96c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06109546-2982-4fe3-88e1-b6e7b598ee0b', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What happens during severe Diarrhoea, and why is administering Oral Rehydration Solution (ORS) life-saving?', 'ORS exploits intestinal sodium-glucose co-transport mechanisms (SGLT1) to rapidly rehydrate hypovolemic patients.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fdcd335-47da-43c9-8b0e-329fc0b5cd9f', 'Severe diarrhoea causes rapid, life-threatening loss of water and vital electrolytes (dehydration); ORS restores fluid, sodium, and glucose balance rapidly', true, '06109546-2982-4fe3-88e1-b6e7b598ee0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caa0689c-030a-41de-8a70-81b15e6dc790', 'ORS makes a person sleepy', false, '06109546-2982-4fe3-88e1-b6e7b598ee0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ac741b1-ca03-47ec-8497-2ba3919d8259', 'ORS changes blood into milk', false, '06109546-2982-4fe3-88e1-b6e7b598ee0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed201186-aa29-4529-a063-92338c2437cb', 'Diarrhoea is harmless and needs no water', false, '06109546-2982-4fe3-88e1-b6e7b598ee0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07fb3e83-de5d-4e68-9fd9-1cf9602f7464', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'How does the unique marine animal Starfish (Asterias) feed on hard-shelled mollusks (clams and oysters)?', 'Starfish exhibit extraordinary eversible cardiac stomach feeding: everting stomach into bivalve shells for external enzymatic digestion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6e327d1-2743-4d3f-87d6-8a2392ac7393', 'It pries open the shell, pops its own stomach OUT through its mouth into the shell to digest the soft animal inside, and then pulls its stomach back in', true, '07fb3e83-de5d-4e68-9fd9-1cf9602f7464');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('304f6c88-d6be-4f13-af42-af34bfde8076', 'It swallows the whole shell and crushes it with teeth', false, '07fb3e83-de5d-4e68-9fd9-1cf9602f7464');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63ac3c73-45d1-48ea-9d6f-d5c9b1f35f5e', 'It drills a hole with a laser', false, '07fb3e83-de5d-4e68-9fd9-1cf9602f7464');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19bd0090-00a7-4c2d-8f9b-37f1cc06ff26', 'It injects poison and waits for 10 years', false, '07fb3e83-de5d-4e68-9fd9-1cf9602f7464');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1aacd892-e25e-4fc4-843f-3e252c76bb18', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is the historical medical discovery made by American doctor William Beaumont in 1822 through the unhealed gunshot stomach wound of Alexis St. Martin?', 'Dr. Beaumont''s pioneering gastric fistula experiments laid the empirical foundation of human gastrointestinal physiology.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e64ebe48-74dc-45d3-bc2e-2c23add7e0e9', 'He directly observed that the stomach walls churn food mechanically, secrete digestive acid/juices, and digestion proceeds only when food is exposed to these fluids', true, '1aacd892-e25e-4fc4-843f-3e252c76bb18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0211986-cd4a-44a9-a3d7-89b481b4cf18', 'He discovered that the stomach is made of bone', false, '1aacd892-e25e-4fc4-843f-3e252c76bb18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f10a24e-f7de-4baf-af58-9b6b6458195f', 'He found that food turns into gold inside', false, '1aacd892-e25e-4fc4-843f-3e252c76bb18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02fa763d-db48-4829-9234-99fab7123b96', 'He proved the stomach has teeth', false, '1aacd892-e25e-4fc4-843f-3e252c76bb18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fc6ab72-3634-48a7-b418-ab1d02088b69', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What are the four primary taste modalities detected by taste buds located on different regional zones of the human Tongue?', 'Gustatory papillae taste buds detect Sweet, Salty, Sour, Bitter (and Umami) gustatory modalities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00ab6379-ca75-45d1-ab7e-6ff75310b64c', 'Sweet, Sour, Salty, and Bitter', true, '2fc6ab72-3634-48a7-b418-ab1d02088b69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0bb66e5-7d76-45d4-bb39-92da700a88cb', 'Hot, Cold, Wet, and Dry', false, '2fc6ab72-3634-48a7-b418-ab1d02088b69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d521c841-4e8c-4201-a770-9d7bdb8f9827', 'Soft, Hard, Rough, and Smooth', false, '2fc6ab72-3634-48a7-b418-ab1d02088b69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfdacbe5-1832-4f5f-8404-771980b8ddb8', 'Red, Blue, Green, and Yellow', false, '2fc6ab72-3634-48a7-b418-ab1d02088b69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6956cb65-3b2d-4f30-9cfe-2c1663fc9395', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Into what simpler, absorbable end-products are the three major food components broken down during complete digestion in the small intestine?', 'Terminal enzymatic hydrolysis yields absorbable monomer units: glucose/monosaccharides, amino acids, and fatty acids/glycerol.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d0568a4-dab6-4f20-a917-cdf14aa3e788', 'Carbohydrates -> Glucose ; Proteins -> Amino Acids ; Fats -> Fatty Acids and Glycerol', true, '6956cb65-3b2d-4f30-9cfe-2c1663fc9395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5146ff45-cea6-47cc-a6fe-0f585a50702d', 'Carbohydrates -> Starch ; Proteins -> Meat ; Fats -> Oil', false, '6956cb65-3b2d-4f30-9cfe-2c1663fc9395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('330e9268-e62e-4b9e-8ef6-0be1c42e8dab', 'All three turn into pure water', false, '6956cb65-3b2d-4f30-9cfe-2c1663fc9395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03e8e908-92b9-4166-86bc-f5bd24f91685', 'Carbohydrates -> Carbon ; Proteins -> Nitrogen ; Fats -> Oxygen', false, '6956cb65-3b2d-4f30-9cfe-2c1663fc9395');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9538f8d-3df8-43a0-a75c-4d51046f3b77', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Why does chewing a piece of dry plain bread or boiled rice for several minutes without swallowing make it taste increasingly SWEET in the mouth?', 'Oral mastication blends salivary amylase with starch, hydrolyzing poly-saccharides into sweet disaccharide maltose.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c35bb9ab-d031-4ae8-b3f7-95d1fbec6afb', 'Salivary amylase enzyme present in saliva breaks down complex, tasteless starch molecules into sweet-tasting maltose sugar', true, 'b9538f8d-3df8-43a0-a75c-4d51046f3b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed3dbd8d-db54-4d67-96e2-cf27125334a3', 'Because teeth have sugar crystals', false, 'b9538f8d-3df8-43a0-a75c-4d51046f3b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77fadf62-c475-4bdb-8e81-f47f8da18256', 'Because bread absorbs sugar from air', false, 'b9538f8d-3df8-43a0-a75c-4d51046f3b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4560915a-2348-4edf-bbae-cd01e1c7f879', 'Because saliva turns into honey', false, 'b9538f8d-3df8-43a0-a75c-4d51046f3b77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31bfa34a-bf5e-4d0a-b418-53f8a56c0b17', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is the ''Milk Teeth'' set in human children, and at what age are they replaced by the permanent adult dentition?', 'Deciduous milk teeth (20 in total) shed sequentially between 6–8 years as secondary permanent teeth erupt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7fdeeaf-2965-405d-aa6c-b357e922ebc4', 'The first temporary set of 20 deciduous teeth that erupt in infancy and fall off between the ages of 6 and 8 years', true, '31bfa34a-bf5e-4d0a-b418-53f8a56c0b17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e682d245-0eaa-46df-abab-9e5b212be6ce', 'Teeth made of dried milk', false, '31bfa34a-bf5e-4d0a-b418-53f8a56c0b17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f791200-6cb2-4c39-8662-b229a2e99042', 'Teeth that never fall out', false, '31bfa34a-bf5e-4d0a-b418-53f8a56c0b17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7f84162-ff06-49c3-a26c-538bc98a8167', 'Adult teeth that appear at age 40', false, '31bfa34a-bf5e-4d0a-b418-53f8a56c0b17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('061e015e-8d07-43e8-ae8f-c75cd8821635', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Why do we cough or choke violently if we laugh or talk hurriedly while swallowing food?', 'Laryngeal epiglottic closure guards the glottis during deglutition; talking diverts food into the trachea, invoking the protective cough reflex.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8337c408-2ef5-4652-a840-2c675633d1fc', 'The flap-like Epiglottis fails to close the windpipe (trachea) entrance in time, allowing food particles to enter the windpipe and triggering the coughing reflex', true, '061e015e-8d07-43e8-ae8f-c75cd8821635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c317a08-4532-4afc-9be3-2ebb40401a26', 'Because food hits the ears', false, '061e015e-8d07-43e8-ae8f-c75cd8821635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4901365e-08b7-46e3-a2f0-b6e21e592936', 'Because teeth bite the tongue', false, '061e015e-8d07-43e8-ae8f-c75cd8821635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('390420dd-78bd-4bc4-8a6e-f4ef117847d6', 'Because the stomach is full of air', false, '061e015e-8d07-43e8-ae8f-c75cd8821635');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8407515-5964-4111-b5d8-1e4bfb42a3fe', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f45ebe6c-cbab-4642-8306-aa9c9eab25ec', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c8407515-5964-4111-b5d8-1e4bfb42a3fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7cd1370-1c60-4b12-a6e4-86413bc1d5c8', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c8407515-5964-4111-b5d8-1e4bfb42a3fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1d555b2-6c8e-4b47-8544-a4678ea5cb62', '(A) is true, but (R) is false.', false, 'c8407515-5964-4111-b5d8-1e4bfb42a3fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcc0c259-c0eb-487a-9b39-abb6429ea71d', '(A) is false, but (R) is true.', false, 'c8407515-5964-4111-b5d8-1e4bfb42a3fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f75fccd-7d94-4aa0-b8ef-c8f23aa324a5', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Spot the IMPOSTER in the following sequence of steps in Animal Nutrition:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0cb0caa-1f9c-45ee-aa12-98547535c631', 'Statement 1', false, '9f75fccd-7d94-4aa0-b8ef-c8f23aa324a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f8d6327-1842-4d55-8ddc-58ce8e7faa53', 'Statement 2 (Absorption is taking nutrients into blood ; Assimilation is cellular utilization)', true, '9f75fccd-7d94-4aa0-b8ef-c8f23aa324a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab2dd975-dfa0-4f09-b9e7-22c5dd3f9d46', 'Statement 3', false, '9f75fccd-7d94-4aa0-b8ef-c8f23aa324a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9d515ec-1604-4d72-a533-2a2e32f7b2f6', 'Statement 4', false, '9f75fccd-7d94-4aa0-b8ef-c8f23aa324a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bb9633d-8ebb-46db-af7a-548bb2fc0fd0', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'A student sets up two test tubes:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fed1c39-2eed-4853-8c09-2835fe5ae1f5', 'Test Tube A turns deep Blue-Black (starch present) ; Test Tube B shows NO blue-black color (remains pale yellowish-brown because salivary amylase broke starch down into sugar)', true, '1bb9633d-8ebb-46db-af7a-548bb2fc0fd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6473d5b-38da-4541-9002-7f6685338c79', 'Both turn deep blue-black', false, '1bb9633d-8ebb-46db-af7a-548bb2fc0fd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d04b5cd-02c3-4bee-8de0-d78f115acb1a', 'Neither tube shows any color change', false, '1bb9633d-8ebb-46db-af7a-548bb2fc0fd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e6e07dd-3338-431c-86c1-f276cf230bf1', 'Test Tube B turns blue-black and Tube A remains clear', false, '1bb9633d-8ebb-46db-af7a-548bb2fc0fd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec8fb900-f3d8-40ef-b3a2-ef39b278e9c9', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Match Column I (Digestive Organs) with Column II (Primary Biochemical Functions):
(a) Buccal Cavity   -> (i) Hydrochloric acid & pepsin protein digestion
(b) Stomach         -> (ii) Emulsification of fats via bile juice
(c) Liver           -> (iii) Complete digestion & villi nutrient absorption
(d) Small Intestine -> (iv) Mastication & starch digestion by salivary amylase', 'Mouth = starch hydrolysis; Stomach = HCl/protein; Liver = bile emulsification; Small Intestine = terminal absorption.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb299100-57ed-478d-ac3a-4a4afa5f81a2', 'a-(iv), b-(i), c-(ii), d-(iii)', true, 'ec8fb900-f3d8-40ef-b3a2-ef39b278e9c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e92000d1-c1fd-4576-858b-e51886bddf4e', 'a-(i), b-(iv), c-(iii), d-(ii)', false, 'ec8fb900-f3d8-40ef-b3a2-ef39b278e9c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fddda720-df1f-4fec-987a-fd19c2682f40', 'a-(ii), b-(iii), c-(iv), d-(i)', false, 'ec8fb900-f3d8-40ef-b3a2-ef39b278e9c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5be7d3d4-6551-4108-b76a-ffc03cfb0f01', 'a-(iii), b-(ii), c-(i), d-(iv)', false, 'ec8fb900-f3d8-40ef-b3a2-ef39b278e9c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66c89ed6-40ad-40d7-b053-06ec8e6220b4', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Read the statements regarding animal digestion:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('850c5c35-2e0c-4a70-bfa1-3c080b155f88', 'Statements 1 and 3 only', true, '66c89ed6-40ad-40d7-b053-06ec8e6220b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4a7325b-6c10-4a76-862d-6d87d5f065a3', 'Statements 1 and 2 only', false, '66c89ed6-40ad-40d7-b053-06ec8e6220b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cce1b089-3d87-4116-ac4a-c0d366cfa13c', 'Statements 2 and 3 only', false, '66c89ed6-40ad-40d7-b053-06ec8e6220b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8779a1dd-545f-4b52-aadc-dfc432a60928', 'All Statements 1, 2, and 3', false, '66c89ed6-40ad-40d7-b053-06ec8e6220b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de701fee-c7d0-4bdb-a0d9-5b8460879065', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Consider the anatomical dental formula of an adult human with 32 permanent teeth:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e65677e-2071-475f-b5d4-ca330441e6bc', 'Incisors: 8 ; Canines: 4 ; Premolars: 8 ; Molars: 12 (Dental formula: 2-1-2-3 / 2-1-2-3 × 2 = 32)', true, 'de701fee-c7d0-4bdb-a0d9-5b8460879065');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ac49538-3b96-4c1a-a01e-575f9df7b9fe', 'Incisors: 4 ; Canines: 8 ; Premolars: 12 ; Molars: 8', false, 'de701fee-c7d0-4bdb-a0d9-5b8460879065');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e70f3400-a13c-4928-aabd-8681a1e8fda7', 'Incisors: 8 ; Canines: 8 ; Premolars: 8 ; Molars: 8', false, 'de701fee-c7d0-4bdb-a0d9-5b8460879065');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca9ef2ba-afe6-42e1-af58-a367294482eb', 'Incisors: 10 ; Canines: 2 ; Premolars: 10 ; Molars: 10', false, 'de701fee-c7d0-4bdb-a0d9-5b8460879065');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3db04e08-d168-4d3a-9bac-371913e24526', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Why do fatty acids and glycerol absorbed by intestinal villi enter the central Lymphatic Lacteal vessels rather than direct blood capillaries?', 'Chylomicrons exit enterocytes via exocytosis, entering permeable lacteal lymphatics for thoracic duct delivery to circulation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a76366ae-44be-4353-ba54-34f6b9657084', 'Water-insoluble fatty acids are re-synthesized into chylomicron lipid droplets inside epithelial cells, which are too large to cross blood capillary pores and enter the wider lacteal lymphatic system', true, '3db04e08-d168-4d3a-9bac-371913e24526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9f2f2cd-0ff0-4554-991b-f48be7accc12', 'Because blood destroys all fats immediately', false, '3db04e08-d168-4d3a-9bac-371913e24526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b66d942f-2da2-4020-bfa7-6e32ef47fb45', 'Because lacteals are made of fat', false, '3db04e08-d168-4d3a-9bac-371913e24526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2a9a737-2997-4018-b6ae-ab325c291041', 'Because fats turn into blood in the liver', false, '3db04e08-d168-4d3a-9bac-371913e24526');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca3496a2-c39d-452a-abb1-f4baa47a92be', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'What is the structural and functional similarity between nutrition in the single-celled Amoeba and multi-cellular Human beings?', 'Universal holozoic nutrition across metazoa and protozoa follows identical sequential biochemical phases: ingestion, digestion, absorption, assimilation, egestion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23726eb6-6d25-4110-a99c-efaa04a33aa0', 'Both require complex food intake, chemical enzymatic breakdown into soluble nutrients, cellular absorption/assimilation, and expulsion of undigested waste', true, 'ca3496a2-c39d-452a-abb1-f4baa47a92be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bf9e1f1-94b9-4590-8044-d07c90ff2ee8', 'Both chew food with enamel teeth', false, 'ca3496a2-c39d-452a-abb1-f4baa47a92be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dda2af2-3731-44c1-8de5-7deae931f19f', 'Both possess an 8-meter long alimentary canal', false, 'ca3496a2-c39d-452a-abb1-f4baa47a92be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc63981d-083e-413f-b6ed-c3c51f75d8ad', 'Both use pseudopodia for swallowing', false, 'ca3496a2-c39d-452a-abb1-f4baa47a92be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4fa363b-6c3f-4535-aea4-dd75edb93c1d', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Why does the Pancreatic Juice contain sodium bicarbonate in addition to digestive enzymes (trypsin, amylase, lipase)?', 'Pancreatic ductal HCO₃⁻ neutralizes gastric HCl, establishing an alkaline duodenal environment (pH 7.8–8.2) for enzyme kinetics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb766c2-09bd-456a-a123-d89ed61ae054', 'To neutralize the highly acidic chyme arriving from the stomach, creating an optimal ALKALINE medium (pH ~8.0) required for pancreatic enzymes to function', true, 'f4fa363b-6c3f-4535-aea4-dd75edb93c1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f1b95ac-2906-4200-a51e-dd46e7c2ed3c', 'To make the food spicy', false, 'f4fa363b-6c3f-4535-aea4-dd75edb93c1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2731e9f-b30d-4772-a0b5-66ba717b6b1c', 'To cool the stomach down', false, 'f4fa363b-6c3f-4535-aea4-dd75edb93c1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f3d9f92-a0da-4fe9-9d32-3a3c83046120', 'To produce bubbles in blood', false, 'f4fa363b-6c3f-4535-aea4-dd75edb93c1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64bc2750-1739-45c1-a08a-47c2fbef180d', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Consider four physiological events in human digestion:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80e790d9-5513-4ad5-b9cd-c1d04e5f77c0', 'Event 3 (Mouth) -> Event 2 (Stomach) -> Event 1 (Small Intestine) -> Event 4 (Large Intestine)', true, '64bc2750-1739-45c1-a08a-47c2fbef180d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcbe59dd-93ed-47e0-be68-69ccd9d51311', 'Event 1 -> Event 2 -> Event 3 -> Event 4', false, '64bc2750-1739-45c1-a08a-47c2fbef180d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21ee6240-c8ce-4dc1-ab8c-96cf6b871641', 'Event 2 -> Event 1 -> Event 4 -> Event 3', false, '64bc2750-1739-45c1-a08a-47c2fbef180d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68e6a41e-c1a0-4a28-9bd2-db7445e5f5b6', 'Event 4 -> Event 3 -> Event 2 -> Event 1', false, '64bc2750-1739-45c1-a08a-47c2fbef180d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d20becca-3298-4101-a97c-326ff8b4dbb8', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'What is the specialized evolutionary adaptation in Hydra for capturing aquatic prey and injecting paralyzing neurotoxins?', 'Hydra fires microscopic pressurized nematocyst barbed threads containing hypnotoxin to immobilize aquatic prey.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb3a2b2c-fadb-42d1-a2a0-6bf5328c435e', 'Stinging cells called Nematocysts (Cnidocytes) located on its flexible tentacles around the mouth', true, 'd20becca-3298-4101-a97c-326ff8b4dbb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c02c3053-6550-4e01-b4ac-422cf8124fc1', 'Sharp incisor teeth', false, 'd20becca-3298-4101-a97c-326ff8b4dbb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b67688-9de0-46f7-b49c-c8ae7b5184e1', 'Pseudopodia', false, 'd20becca-3298-4101-a97c-326ff8b4dbb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ed9382c-d47c-4852-8383-d1f2286c1f00', 'A muscular tongue', false, 'd20becca-3298-4101-a97c-326ff8b4dbb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b278edf-2d81-4ee9-8835-505fb3d1ee01', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'What overarching biological concept summarizes Chapter 2 of NCERT Class 7 Science?', 'Chapter 2 synthesizes comparative digestive morphology, biochemical enzyme cascades, and metabolic assimilation across the animal kingdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8ecf33c-45ed-4c38-9eee-663cdeb5816f', 'Holozoic animal nutrition is a marvel of evolutionary specialization: diverse organisms possess intricate mechanical and biochemical systems tailored to ingest, hydrolyze, assimilate nutrients, and sustain metabolic life', true, '6b278edf-2d81-4ee9-8835-505fb3d1ee01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d505d4f0-566b-4fb3-9827-fbc9d5d28934', 'All animals have identical stomachs and teeth', false, '6b278edf-2d81-4ee9-8835-505fb3d1ee01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81c51091-1e2a-4384-95b8-7f802bc67279', 'Digestion only happens in mouth', false, '6b278edf-2d81-4ee9-8835-505fb3d1ee01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('055500df-94dd-4814-935a-494df26e41f6', 'Animals do not require any enzymes for digestion', false, '6b278edf-2d81-4ee9-8835-505fb3d1ee01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56e7b221-1643-4659-88af-a4ec4c73cb5a', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'A fraction where the Numerator is strictly LESS than the Denominator (such as 3/5, 7/9) is called a:', 'In a proper fraction, 0 < numerator < denominator, representing a quantity strictly less than 1 whole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ce0ca66-efd2-4090-b429-4f0383f5692d', 'Proper Fraction', true, '56e7b221-1643-4659-88af-a4ec4c73cb5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f9023fa-5ead-4bae-84fe-3529eeb9b6dc', 'Improper Fraction', false, '56e7b221-1643-4659-88af-a4ec4c73cb5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebb0e17d-2305-4d09-b9c8-02c6bdf15fca', 'Mixed Fraction', false, '56e7b221-1643-4659-88af-a4ec4c73cb5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62492726-0399-41e6-92d5-445b3eb74419', 'Reciprocal', false, '56e7b221-1643-4659-88af-a4ec4c73cb5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2194df45-e0e1-4b09-ad77-a3d662407fe7', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'A fraction where the Numerator is GREATER than or equal to the Denominator (such as 7/4, 9/5) is called an:', 'In an improper fraction, numerator ≥ denominator, representing a value ≥ 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67f9612b-f67e-4eb9-b9aa-0ab39f7c41f0', 'Improper Fraction', true, '2194df45-e0e1-4b09-ad77-a3d662407fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dc33e5d-e34f-42e7-90d8-5ac295fa0937', 'Proper Fraction', false, '2194df45-e0e1-4b09-ad77-a3d662407fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2557e3e1-634f-44b0-9748-7f25262c4da2', 'Decimal Fraction', false, '2194df45-e0e1-4b09-ad77-a3d662407fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d687ac3b-5000-4e9b-9fe6-fe6b6058b5f1', 'Unit Fraction', false, '2194df45-e0e1-4b09-ad77-a3d662407fe7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a67c888-5b36-4316-bf93-0d9b96705723', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'Convert the improper fraction 17/5 into a Mixed Fraction:', '17 ÷ 5 = 3 with remainder 2 → 3 2/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34657ee9-7813-4e8e-ba10-47c81bc4291b', '3 2/5 (17 ÷ 5 = Quotient 3, Remainder 2)', true, '8a67c888-5b36-4316-bf93-0d9b96705723');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93135f63-8c36-41ab-80c8-f77a6c9301da', '3 1/5', false, '8a67c888-5b36-4316-bf93-0d9b96705723');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9931261a-6ccd-40e0-9020-c71ecd8e1016', '2 3/5', false, '8a67c888-5b36-4316-bf93-0d9b96705723');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5681841-6b6e-4f60-9db3-9cd111f7e48c', '5 2/3', false, '8a67c888-5b36-4316-bf93-0d9b96705723');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff2b654c-df88-4bdf-898d-2c90fb1171c9', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is the product of multiplying two fractions: (2/3) × (5/7)?', 'Product of fractions = (Product of numerators) / (Product of denominators) = (2×5)/(3×7) = 10/21.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('691bc5a7-0760-433f-b291-67bdf487b13f', '10/21 ((2 × 5) / (3 × 7) = 10/21)', true, 'ff2b654c-df88-4bdf-898d-2c90fb1171c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cab3857f-a425-4bd9-a9d6-5fde3c131a2f', '7/10', false, 'ff2b654c-df88-4bdf-898d-2c90fb1171c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eacc6fbf-5fb5-4062-a5ec-40db51c10be9', '10/14', false, 'ff2b654c-df88-4bdf-898d-2c90fb1171c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('520659cc-d2f9-4cd6-924e-0fc51115e0bf', '14/15', false, 'ff2b654c-df88-4bdf-898d-2c90fb1171c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40653112-cc27-4d96-b487-e2b9aec0c9d8', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'Evaluate: (1/2) of 24:', 'In mathematics, the operator ''of'' represents multiplication: (1/2) × 24 = 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a35d3ab-6b23-42e1-ae12-e3e6f73dd832', '12 (1/2 × 24 = 12)', true, '40653112-cc27-4d96-b487-e2b9aec0c9d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1c90abb-48bc-4584-a411-e0ab0a76e363', '24', false, '40653112-cc27-4d96-b487-e2b9aec0c9d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20b73a26-a8cc-4c4d-99d3-aaa5ebd90565', '48', false, '40653112-cc27-4d96-b487-e2b9aec0c9d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd6cae8a-db7a-4463-9e2a-6c8ddf819379', '6', false, '40653112-cc27-4d96-b487-e2b9aec0c9d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7317aaba-bb7c-4fb5-bd8d-eacb92a78ec3', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is the non-zero Reciprocal (Multiplicative Inverse) of the fraction 4/9?', 'The reciprocal of a/b is b/a (inverting numerator and denominator).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72bd28c1-80d6-4d92-8dd8-ac328264f318', '9/4 (since 4/9 × 9/4 = 1)', true, '7317aaba-bb7c-4fb5-bd8d-eacb92a78ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec80102c-2b3e-404f-bec8-830ccbfcfe3f', '-4/9', false, '7317aaba-bb7c-4fb5-bd8d-eacb92a78ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('674e5530-ce9a-4579-b4d9-a17afa1b50d4', '4/9', false, '7317aaba-bb7c-4fb5-bd8d-eacb92a78ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a566507-74e4-486d-9858-d5a283de06d8', '1/4', false, '7317aaba-bb7c-4fb5-bd8d-eacb92a78ec3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a62d28f1-fc32-4d3f-9b6e-8caf572d6c2b', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'Evaluate the division of fractions: (3/5) ÷ (2/7):', 'Dividing by a fraction is multiplying by its reciprocal: (3/5) × (7/2) = 21/10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88acf152-a013-4704-b59b-ee2fe9fbf35d', '21/10 (3/5 × 7/2 = 21/10 = 2 1/10)', true, 'a62d28f1-fc32-4d3f-9b6e-8caf572d6c2b');
