INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6d4f9db-af92-4907-9f18-f803045160c4', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is 2.75 multiplied by 100?', 'Multiplying by 100 shifts the decimal point 2 places to the right: 2.75 × 100 = 275.', NOW()) ON CONFLICT DO NOTHING;
