INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b78d5948-cbc7-40e6-bf99-96eab9aabd5c', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is 45.8 divided by 10?', 'Dividing by 10 shifts the decimal point 1 place to the left: 45.8 ÷ 10 = 4.58.', NOW()) ON CONFLICT DO NOTHING;
