INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdca9d60-2530-48db-bf13-f8ece9184bfb', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is the product: 0.2 × 0.3?', '0.2 × 0.3 = (2/10) × (3/10) = 6/100 = 0.06.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f5dab4a-7d14-466c-b86f-9ee2dd6acfd7', '0.06 (2 × 3 = 6 ; with 1 + 1 = 2 decimal places)', true, 'bdca9d60-2530-48db-bf13-f8ece9184bfb');
