INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ebd62295-9834-4da5-a925-c69f565e4059', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is 7.2 divided by 9?', '7.2 ÷ 9 = 0.8.', NOW()) ON CONFLICT DO NOTHING;
