INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('055def1f-dd40-48b6-baa5-67da29004d3a', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'Express 7 cm in metres as a decimal (1 m = 100 cm):', '7 cm = 7 ÷ 100 = 0.07 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af5614a4-00af-4364-a78d-0b70b05645db', '0.07 m (7/100 m = 0.07 m)', true, '055def1f-dd40-48b6-baa5-67da29004d3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a34fb24-e1e0-495a-a3c4-e07735430c66', '0.7 m', false, '055def1f-dd40-48b6-baa5-67da29004d3a');
