INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f104751-bef3-4c82-80d2-c0db85bef9f7', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Ramesh solved 2/7 part of an exercise while Seema solved 4/5 of it. Who solved a LESSER part?', 'Converting to common denominator 35: Ramesh = 10/35, Seema = 28/35. Ramesh solved lesser.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1eca3d3d-16c9-4501-8d17-cfc515de0b7c', 'Ramesh solved a lesser part (2/7 = 10/35 ; 4/5 = 28/35 ⇒ 10/35 < 28/35)', true, '6f104751-bef3-4c82-80d2-c0db85bef9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9139a7b-fdbc-42b6-bf28-1fe716898f09', 'Seema solved a lesser part', false, '6f104751-bef3-4c82-80d2-c0db85bef9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93eda437-b7b6-4bba-9679-e6bc5913f048', 'Both solved exactly the same part', false, '6f104751-bef3-4c82-80d2-c0db85bef9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0179e10d-a5ce-40be-a165-0b7d36346a55', 'Cannot be compared', false, '6f104751-bef3-4c82-80d2-c0db85bef9f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('620bf167-6cd7-4426-9c55-cd0f47c27e1f', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Sameera purchased 3 1/2 kg apples and 4 3/4 kg oranges. What is the total weight of fruits purchased by her?', '3.5 + 4.75 = 8.25 kg = 8 1/4 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c50e326-7348-46be-ba7c-68da775baeb7', '8 1/4 kg (7/2 + 19/4 = 14/4 + 19/4 = 33/4 = 8 1/4 kg)', true, '620bf167-6cd7-4426-9c55-cd0f47c27e1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc84943b-8504-49e8-b07d-bddf446d9f3f', '7 4/6 kg', false, '620bf167-6cd7-4426-9c55-cd0f47c27e1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d851142-d2d4-493c-a1a4-d4aec4db1374', '8 1/2 kg', false, '620bf167-6cd7-4426-9c55-cd0f47c27e1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae5dc6b8-31bd-4e2b-bae6-ff04774cc55b', '7 3/4 kg', false, '620bf167-6cd7-4426-9c55-cd0f47c27e1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31aa55a1-8acb-4b0e-af8e-013353b77436', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'A car runs 16 km using 1 litre of petrol. How much distance will it cover using 2 3/4 litres of petrol?', 'Distance = 16 × (11/4) = 44 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('358729ce-c8e1-40bd-bf2b-8094eab9f0d6', '44 km (16 × 11/4 = 4 × 11 = 44 km)', true, '31aa55a1-8acb-4b0e-af8e-013353b77436');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d88c5687-7306-4e1f-af4b-8357e857eb38', '32 km', false, '31aa55a1-8acb-4b0e-af8e-013353b77436');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90d10437-7255-41f5-b4ef-71377cdd99d2', '48 km', false, '31aa55a1-8acb-4b0e-af8e-013353b77436');
