INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea0110b2-99b5-485f-8390-904e864cb1de', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Saili plants 4 saplings in a row in her garden. The distance between two adjacent saplings is 3/4 m. Find the total distance between the FIRST and the LAST sapling:', '4 saplings have (4 - 1) = 3 equal intervals: 3 × (3/4) = 9/4 m = 2 1/4 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1b4a1c0-767d-4be0-bc6d-74e682da1683', '2 1/4 m (There are 3 gaps between 4 saplings ; Distance = 3 × 3/4 = 9/4 = 2 1/4 m)', true, 'ea0110b2-99b5-485f-8390-904e864cb1de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('386c1035-1a37-49e9-81a2-8fd4e932420d', '3 m', false, 'ea0110b2-99b5-485f-8390-904e864cb1de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2168900e-07b3-48b0-8da9-3182e4a187ae', '2 1/2 m', false, 'ea0110b2-99b5-485f-8390-904e864cb1de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45efee30-1b0f-4d90-9518-e578c933a294', '1 3/4 m', false, 'ea0110b2-99b5-485f-8390-904e864cb1de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e40e9c78-1e96-4031-9243-2dcfec7314e0', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Lipika reads a book for 1 3/4 hours every day. She reads the entire book in 6 days. How many total hours were required by her to read the book?', 'Total hours = 6 × (7/4) = 42/4 = 21/2 = 10 1/2 hours (10.5 hours).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c99a8a8c-64aa-470c-806a-8cfa1a898cdd', '10 1/2 hours (6 × 7/4 = 42/4 = 21/2 = 10 1/2 hours)', true, 'e40e9c78-1e96-4031-9243-2dcfec7314e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51b614db-01ed-49c8-9589-8bfe98affac0', '8 hours', false, 'e40e9c78-1e96-4031-9243-2dcfec7314e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ae6bbbc-de14-474a-a017-dd18aaa30757', '12 hours', false, 'e40e9c78-1e96-4031-9243-2dcfec7314e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87334afb-468f-43d2-93c2-a4022a360c38', '9 1/4 hours', false, 'e40e9c78-1e96-4031-9243-2dcfec7314e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ba81651-3bc2-495f-b2c6-4cf8df543fb6', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'A picture is 7 3/5 cm wide. To fit in a frame, it cannot be more than 7 3/10 cm wide. How much should the picture be trimmed?', '7.6 cm - 7.3 cm = 0.3 cm = 3/10 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16da5989-fa34-43ba-a61d-186b1f4bd626', '3/10 cm (7 3/5 - 7 3/10 = 38/5 - 73/10 = 76/10 - 73/10 = 3/10 cm)', true, '9ba81651-3bc2-495f-b2c6-4cf8df543fb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18457ee5-005c-4491-a902-d367793744e1', '1/5 cm', false, '9ba81651-3bc2-495f-b2c6-4cf8df543fb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae170233-98ca-4b16-8a84-0fe6833ed75c', '1/10 cm', false, '9ba81651-3bc2-495f-b2c6-4cf8df543fb6');
