INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce771225-f8c1-42b5-9d3e-bc5b1e05476e', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Find the product: 11.2 × 0.15:', '112 × 15 = 1680. Decimal places = 1 + 2 = 3 → 1.680 = 1.68.', NOW()) ON CONFLICT DO NOTHING;
