INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2650917f-7558-4ed7-8b4d-3c5a8b212683', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Evaluate: 76.5 ÷ 0.15:', '76.5 ÷ 0.15 = 7650 ÷ 15 = 510.', NOW()) ON CONFLICT DO NOTHING;
