INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ded62abe-51e5-49ee-8326-02debfed9a45', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Find the average (mean) of the numbers: 4.2, 3.8, and 7.6:', 'Sum = 4.2 + 3.8 + 7.6 = 15.6. Average = 15.6 ÷ 3 = 5.2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53aa3c2d-00f2-4e29-8ecf-8e56c379ef5a', '5.2 ((4.2 + 3.8 + 7.6) / 3 = 15.6 / 3 = 5.2)', true, 'ded62abe-51e5-49ee-8326-02debfed9a45');
