INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('891106c4-3ffe-4b40-a352-a67593832f51', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'A two-wheeler covers a distance of 55.3 km in 1 litre of petrol. How much distance will it cover in 10 litres of petrol?', '55.3 × 10 = 553 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6ddb9ec-97b6-4a16-9167-02ef380248bd', '553 km (55.3 × 10 = 553 km)', true, '891106c4-3ffe-4b40-a352-a67593832f51');
