INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('392dbf31-4b80-4ac5-9823-1c971f1c89b1', '5530 km', false, '891106c4-3ffe-4b40-a352-a67593832f51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9638c673-0901-4305-b58e-91b0f90e3480', '5.53 km', false, '891106c4-3ffe-4b40-a352-a67593832f51');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7868197-e3b3-4978-ac31-537be05e33fb', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'The side of an equilateral triangle is 3.5 cm. Find its perimeter:', 'Perimeter = 3 × side = 3 × 3.5 = 10.5 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5b774cf-859f-4829-9140-f067f6588ed4', '10.5 cm (3 × 3.5 = 10.5 cm)', true, 'a7868197-e3b3-4978-ac31-537be05e33fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01388412-e3f8-4002-8a81-0c9dab8a9990', '7.0 cm', false, 'a7868197-e3b3-4978-ac31-537be05e33fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0c48651-b85b-4202-8711-caf732655bd3', '12.25 cm', false, 'a7868197-e3b3-4978-ac31-537be05e33fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8528f58b-879a-4ffd-82e0-d166597ddb05', '14.0 cm', false, 'a7868197-e3b3-4978-ac31-537be05e33fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e72a8eda-1307-4edd-8c67-d029e100c64b', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'The length of a rectangle is 7.1 cm and its breadth is 2.5 cm. What is the area of the rectangle?', 'Area = Length × Breadth = 7.1 × 2.5 = 17.75 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b1ff1db-3fbe-4247-8c41-312cade470ee', '17.75 cm² (7.1 × 2.5 = 17.75 cm²)', true, 'e72a8eda-1307-4edd-8c67-d029e100c64b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b7f09ef-e7c4-4359-ab80-8382d33fc895', '19.2 cm²', false, 'e72a8eda-1307-4edd-8c67-d029e100c64b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('582d2b0d-c647-4876-a3e2-424262e5eb71', '18.5 cm²', false, 'e72a8eda-1307-4edd-8c67-d029e100c64b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9cba872-adf4-4d17-bec2-31b59ef43bff', '16.85 cm²', false, 'e72a8eda-1307-4edd-8c67-d029e100c64b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c2ea5a5-cb35-4852-8f90-5de77b2f33c1', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Each side of a regular polygon is 2.5 cm in length. The perimeter of the polygon is 12.5 cm. How many sides does the polygon have?', 'Number of sides = Perimeter ÷ Side length = 12.5 ÷ 2.5 = 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf55fbe-bbe6-46f0-b741-19b8802a8bc1', '5 sides (12.5 ÷ 2.5 = 5 sides - Pentagon)', true, '4c2ea5a5-cb35-4852-8f90-5de77b2f33c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('868cbe47-b313-446c-99a5-5658c92e78e5', '6 sides', false, '4c2ea5a5-cb35-4852-8f90-5de77b2f33c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c73b672b-71f8-46a1-bacd-fa4bcf4e8913', '4 sides', false, '4c2ea5a5-cb35-4852-8f90-5de77b2f33c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71ff8dfd-2972-43c7-a89c-3d473c07ad52', '8 sides', false, '4c2ea5a5-cb35-4852-8f90-5de77b2f33c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24a67688-64ae-4951-8ab9-52ef98112fc5', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'A vehicle covers a distance of 43.2 km in 2.4 litres of petrol. How much distance will it cover in 1 litre of petrol?', '43.2 ÷ 2.4 = 432 ÷ 24 = 18 km/litre.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ebff358-f5f1-43f1-810b-69271b8cb175', '18 km (43.2 ÷ 2.4 = 432 ÷ 24 = 18 km)', true, '24a67688-64ae-4951-8ab9-52ef98112fc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9249f139-5445-4392-8856-457b5c698f66', '16 km', false, '24a67688-64ae-4951-8ab9-52ef98112fc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da700a99-be88-430d-9166-38cc98322eb0', '20 km', false, '24a67688-64ae-4951-8ab9-52ef98112fc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9d6a16a-db65-48a2-9fe0-c5ea2b7a9eaa', '14.5 km', false, '24a67688-64ae-4951-8ab9-52ef98112fc5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3a6b7f6-16b2-4e5d-86d2-4b55c6a6bb30', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Which of the following products is strictly LESS than each of the two fractions multiplied?', 'When two proper fractions (<1) are multiplied, the product is smaller than either factor: 8/15 < 2/3 and 8/15 < 4/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70b018c9-0026-4306-8c63-e3050740ea03', '(2/3) × (4/5) = 8/15 (Product of two proper fractions is ALWAYS less than each fraction)', true, 'a3a6b7f6-16b2-4e5d-86d2-4b55c6a6bb30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c9012a9-63ea-4b5d-ba2a-f5c1af2784e3', '(3/2) × (5/4) = 15/8', false, 'a3a6b7f6-16b2-4e5d-86d2-4b55c6a6bb30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6bafe03-b438-4727-8f09-e6b0d3c67d7c', '(4/3) × (2/5) = 8/15', false, 'a3a6b7f6-16b2-4e5d-86d2-4b55c6a6bb30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7ddcf45-a125-4614-aac8-0b7bf4ccaefe', '(5/2) × (3/1) = 15/2', false, 'a3a6b7f6-16b2-4e5d-86d2-4b55c6a6bb30');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('503ff2c5-3483-4802-9e87-e927f414217b', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Express 200 rupees and 5 paise in rupees as a decimal:', '5 paise = ₹0.05 → ₹200.05.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f66aabf-c0d7-498e-8cce-b67bb3145c86', '₹200.05 (5 paise = 5/100 = ₹0.05 ⇒ ₹200 + 0.05 = ₹200.05)', true, '503ff2c5-3483-4802-9e87-e927f414217b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b39d72-5c66-4bcc-9b7c-3b495eca7f02', '₹200.50', false, '503ff2c5-3483-4802-9e87-e927f414217b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaae4476-6f3e-4142-b16c-f32f8e55cae8', '₹200.5', false, '503ff2c5-3483-4802-9e87-e927f414217b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beddc5a6-8817-47a4-9d40-d251f9fdcc41', '₹20.05', false, '503ff2c5-3483-4802-9e87-e927f414217b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5299140-a635-4eea-8ff0-0141ac66adcf', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('324c9dda-dffb-40e2-9d48-6821aa9f65cd', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'd5299140-a635-4eea-8ff0-0141ac66adcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23bb1863-7f6e-4aee-a704-91dd90a5c459', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'd5299140-a635-4eea-8ff0-0141ac66adcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('081e5851-5904-4ddb-981a-402d65a9d9e3', '(A) is true, but (R) is false.', false, 'd5299140-a635-4eea-8ff0-0141ac66adcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fc6c45c-b986-4af8-bc8b-71f11454947e', '(A) is false, but (R) is true.', false, 'd5299140-a635-4eea-8ff0-0141ac66adcf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e89ce68-392a-4f28-b2fd-523eeb75c487', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Spot the IMPOSTER in the following mathematical fraction and decimal evaluations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a04402e-bcf5-4dbe-8cc8-44c5e719e396', 'Statement 1', false, '5e89ce68-392a-4f28-b2fd-523eeb75c487');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d46b28b1-c06f-4f66-98cf-8169e9521949', 'Statement 2', false, '5e89ce68-392a-4f28-b2fd-523eeb75c487');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bac747b7-2fac-4d85-a620-6df90061088d', 'Statement 3', false, '5e89ce68-392a-4f28-b2fd-523eeb75c487');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12a3677b-a313-460d-98c3-0c4f8abf33f0', 'Statement 4 (0.08 ÷ 0.4 = 0.2, NOT 2.0)', true, '5e89ce68-392a-4f28-b2fd-523eeb75c487');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf8546c4-3fc8-48ba-b49d-d93ec9d0bff6', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Simplify the complex nested fractional expression:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9acea4c-c889-4d55-937f-cf071a7fd124', '12/5 = 2 2/5 = 2.4 ((10/3 × 9/5) ÷ 5/2 = 6 ÷ 5/2 = 6 × 2/5 = 12/5 = 2.4)', true, 'cf8546c4-3fc8-48ba-b49d-d93ec9d0bff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25d19876-bb94-492d-8316-cb0c515eb5fb', '3 1/5', false, 'cf8546c4-3fc8-48ba-b49d-d93ec9d0bff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0827e9a0-b980-46f4-82c6-0d547652daaa', '1 4/5', false, 'cf8546c4-3fc8-48ba-b49d-d93ec9d0bff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c0f81b2-68ed-4a1d-9359-0c765f38b259', '4 1/2', false, 'cf8546c4-3fc8-48ba-b49d-d93ec9d0bff6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88f99d64-340c-48d9-a853-0c0182801d27', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Match Column I (Fractions & Decimal Operations) with Column II (Exact Evaluated Values):
(a) 0.5 × 0.05      -> (i) 0.025
(b) 0.5 ÷ 0.05      -> (ii) 10
(c) 3/4 of 4/3      -> (iii) 1
(d) (2/5) ÷ (4/15)  -> (iv) 1.5 (3/2)', '0.5×0.05=0.025; 0.5/0.05=10; 3/4×4/3=1; 2/5÷4/15 = 2/5×15/4 = 3/2 = 1.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96b74ab8-b026-4714-bed1-b848ef15d98f', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '88f99d64-340c-48d9-a853-0c0182801d27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be3e8ed3-61b6-439f-b195-e9756aca50f8', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '88f99d64-340c-48d9-a853-0c0182801d27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e45ff1c-c044-4baf-bf0b-77b2c7c64262', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '88f99d64-340c-48d9-a853-0c0182801d27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e1db0f0-925d-4a0f-b271-5876fd6b4a36', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '88f99d64-340c-48d9-a853-0c0182801d27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dee5fc38-4b07-44ed-8e49-c09f9ebb0c9d', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Read the statements regarding fractional arithmetic:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aae00224-452f-476a-a53a-b3afd9b23bda', 'All Statements 1, 2, and 3 are TRUE', true, 'dee5fc38-4b07-44ed-8e49-c09f9ebb0c9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52d7a824-4cf4-4177-a0b6-393f65d214ef', 'Statements 1 and 2 only', false, 'dee5fc38-4b07-44ed-8e49-c09f9ebb0c9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c50429e0-30a9-4a2d-a35e-d02589f49594', 'Statements 2 and 3 only', false, 'dee5fc38-4b07-44ed-8e49-c09f9ebb0c9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('486401dc-759d-4004-b76f-91815aadab49', 'Statements 1 and 3 only', false, 'dee5fc38-4b07-44ed-8e49-c09f9ebb0c9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7705bd2e-cd97-4187-bd4e-ba90d96844c1', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'A rectangular field has length 35.75 m and breadth 18.4 m. A running track running along the perimeter is fenced at ₹25.50 per metre. What is the total cost of fencing the field?', 'Perimeter = 2 × (35.75 + 18.4) = 108.3 m. Cost = 108.3 × 25.50 = ₹2,761.65.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b93206d-d7a9-48bf-96bd-cd67d5e75e41', '₹2,761.65 (Perimeter = 2(35.75 + 18.4) = 2(54.15) = 108.3 m ; Cost = 108.3 × 25.50 = ₹2,761.65)', true, '7705bd2e-cd97-4187-bd4e-ba90d96844c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9bce8fe-fb02-4f64-bd96-acd63d4912d7', '₹2,500.00', false, '7705bd2e-cd97-4187-bd4e-ba90d96844c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36c83083-43b6-4e72-8100-4ba2b1ff8e8a', '₹2,840.50', false, '7705bd2e-cd97-4187-bd4e-ba90d96844c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bca1a877-9809-4975-85a5-0cbb7b9d6622', '₹3,120.75', false, '7705bd2e-cd97-4187-bd4e-ba90d96844c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4fa57aa-dfeb-48f2-b6b6-619adf57f00b', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'In a class of 40 students, 1/5 of the total students like to study English, 2/5 of the total students like to study Mathematics, and the remaining students like to study Science. What FRACTION of the total students like to study Science, and how many students is that?', 'Science fraction = 1 - (1/5 + 2/5) = 1 - 3/5 = 2/5. Students = 2/5 × 40 = 16 students.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a41270b-87c3-492f-957a-ef4ce8f106c3', 'Fraction: 2/5 ; Number of students: 16 (English = 8, Math = 16 ; Science = 40 - 24 = 16 students = 16/40 = 2/5)', true, 'a4fa57aa-dfeb-48f2-b6b6-619adf57f00b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('361e90e0-97f5-4341-851c-c328cf0775d2', 'Fraction: 1/5 ; Number of students: 8', false, 'a4fa57aa-dfeb-48f2-b6b6-619adf57f00b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4171ce71-cbe6-4dd4-979a-a281c64705dc', 'Fraction: 3/5 ; Number of students: 24', false, 'a4fa57aa-dfeb-48f2-b6b6-619adf57f00b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b839c744-2624-49f1-82cb-ef06861a0232', 'Fraction: 1/2 ; Number of students: 20', false, 'a4fa57aa-dfeb-48f2-b6b6-619adf57f00b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37ccd2ae-38e0-4b76-8071-003e0a77e5cc', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'If 12 boxes of equal weight weigh a total of 49.8 kg, how much will 25 such boxes weigh?', 'Weight of 1 box = 49.8 ÷ 12 = 4.15 kg. Weight of 25 boxes = 4.15 × 25 = 103.75 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aec69c3-af7c-4d73-8cf8-a3a20452e4e1', '103.75 kg (1 box = 49.8 / 12 = 4.15 kg ; 25 boxes = 4.15 × 25 = 103.75 kg)', true, '37ccd2ae-38e0-4b76-8071-003e0a77e5cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb47a20b-2e91-4512-a159-e63f8a882ee6', '98.50 kg', false, '37ccd2ae-38e0-4b76-8071-003e0a77e5cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a6c0f05-8daa-4017-b700-756d3a25ed85', '105.25 kg', false, '37ccd2ae-38e0-4b76-8071-003e0a77e5cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('487d11ef-ddae-48a2-aca4-c1ff06041b3b', '101.40 kg', false, '37ccd2ae-38e0-4b76-8071-003e0a77e5cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bd56aaa-d375-4f93-89b1-ccc274613a65', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Arrange the following fractions in DESCENDING order (largest to smallest):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee5708c9-d5b8-4176-a92a-c82cae7a5aa6', '2/3 > 8/21 > 2/9 (Common denominator 63: 2/3 = 42/63 ; 8/21 = 24/63 ; 2/9 = 14/63)', true, '8bd56aaa-d375-4f93-89b1-ccc274613a65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c0b12d2-6d72-4d2e-bb22-6c4696f14bc0', '2/9 > 8/21 > 2/3', false, '8bd56aaa-d375-4f93-89b1-ccc274613a65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80beb238-e2a2-4161-a40f-3d8fe5aea5be', '8/21 > 2/3 > 2/9', false, '8bd56aaa-d375-4f93-89b1-ccc274613a65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0808cf5-f1d9-489b-81ba-5c2cf14be8ad', '2/3 > 2/9 > 8/21', false, '8bd56aaa-d375-4f93-89b1-ccc274613a65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af057ba5-0c11-41bb-ba22-9c4c5c135cb6', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Evaluate: (0.2 × 0.2 × 0.2) + (0.3 × 0.3 × 0.3):', '0.2³ = 0.008; 0.3³ = 0.027. Sum = 0.008 + 0.027 = 0.035.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04600626-58a3-4657-97be-614b0738cd99', '0.035 (0.008 + 0.027 = 0.035)', true, 'af057ba5-0c11-41bb-ba22-9c4c5c135cb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a22091a3-91f1-4532-8fbf-a0ee97edfb21', '0.35', false, 'af057ba5-0c11-41bb-ba22-9c4c5c135cb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6be7b830-f01a-4438-bdaa-c3cc8d1c8d10', '0.0035', false, 'af057ba5-0c11-41bb-ba22-9c4c5c135cb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67539d84-304b-4ded-9c22-9234866c3f9b', '0.05', false, 'af057ba5-0c11-41bb-ba22-9c4c5c135cb6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91cf21c1-b57d-42cd-8f9e-993ffa7d6361', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'A car covers a distance of 89.1 km in 2.2 hours. What is the average distance covered by it in 1 hour?', 'Speed = 89.1 ÷ 2.2 = 891 ÷ 22 = 40.5 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d1018cc-28b5-464f-825b-62b29cfc110a', '40.5 km (89.1 ÷ 2.2 = 891 ÷ 22 = 40.5 km/h)', true, '91cf21c1-b57d-42cd-8f9e-993ffa7d6361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f2c7968-70c5-4438-8e13-b476540fbfde', '42.0 km', false, '91cf21c1-b57d-42cd-8f9e-993ffa7d6361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d155c74a-346d-4644-a3a8-2e65d12d49aa', '39.5 km', false, '91cf21c1-b57d-42cd-8f9e-993ffa7d6361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3467ea79-83ad-4215-8bbd-5d404039a31d', '41.5 km', false, '91cf21c1-b57d-42cd-8f9e-993ffa7d6361');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60456721-aac8-4d99-9493-9f769b4a6c74', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Why is the rigorous understanding of rational fractional division (multiplying by reciprocal) and decimal positional scaling foundational in quantitative computing and applied science?', 'Rational fractions and decimal scaling form the basis of continuous mathematical analysis, dimensional normalization, and numerical algorithms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8218fc2d-4f2c-424c-ba77-94a8f71bac68', 'It allows precise non-integer continuous calculations, algorithmic scaling, unit conversions, and floating-point error control across physics and computational math', true, '60456721-aac8-4d99-9493-9f769b4a6c74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bc68dcd-e17c-466b-8d37-caa0d72998dc', 'Because computers can only understand whole numbers', false, '60456721-aac8-4d99-9493-9f769b4a6c74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e97ac4b-5e2a-4a03-9402-1a2645f07f6e', 'Because fractions eliminate decimals', false, '60456721-aac8-4d99-9493-9f769b4a6c74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e0e3ce7-7bd7-469e-8d6d-6a4650e94b1f', 'Because division by zero is allowed in decimals', false, '60456721-aac8-4d99-9493-9f769b4a6c74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57c25926-4ec9-4730-bd99-d1e3d5b40f42', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'In Vasantha Surya''s lively story ''A Gift of Chappals'', who went to her aunt Rukku Manni''s house with her grandmother Tapi in Madras (Chennai)?', 'Young Mridu visits her aunt Rukku Manni''s house accompanied by her grandmother (Tapi).', NOW()) ON CONFLICT DO NOTHING;
