INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a441532a-c6a6-4531-a174-ae7e8aa9c682', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What did Ravi and Meena secretly show Mridu hidden inside a torn football lined with sacking in the backyard behind a bitter-berry bush?', 'Ravi and Meena harbored a secret stray kitten drinking milk from a coconut shell in the backyard.', NOW()) ON CONFLICT DO NOTHING;
