INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e75a11a-31d7-4019-bd0b-1bd6517e5854', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What grand, aristocratic name did Ravi give to the secret little kitten?', 'Ravi fancifully claimed the kitten was descended from the Pallava royal emblem: Mahendravarma Pallava Poonai (M.P. Poonai).', NOW()) ON CONFLICT DO NOTHING;
