INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84df4f15-0e47-4ae2-8480-b462a0e09419', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What musical instrument was Lalli struggling and screeching to play while taking music lessons from the music master?', 'Lalli was awkwardly learning to play the violin, making screeching ''kreech'' noises resembling a derailed train.', NOW()) ON CONFLICT DO NOTHING;
