INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da61f5c0-f984-486f-9ca2-a04559eb47e8', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'How did the author humorously describe the physical appearance of the bald-headed Music Master?', 'The music master is caricatured with a bony frame, oiled tuft, glistening diamond ring, and gold chain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('966af242-889b-48bf-b1e6-b313c1dd5d1e', 'A bony figure with a mostly bald head fringed with oiled black hair tied in an old-fashioned tuft, wearing a shining gold chain and diamond ring', true, 'da61f5c0-f984-486f-9ca2-a04559eb47e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d6bbbce-e04a-487f-9636-83427acae5b0', 'A giant man with a long white beard', false, 'da61f5c0-f984-486f-9ca2-a04559eb47e8');
