INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('222c5024-5216-4f63-9ec9-85301ad6e325', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'Why was the poor Beggar groaning and leaning against the neem tree in the garden?', 'Walking barefoot on sun-baked asphalt caused severe blisters on the impoverished beggar''s soles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f293cac-6a4d-4bc6-8e70-cb15c5ca215b', 'The scorching afternoon tar road was boiling hot and had caused painful, peeling pink blisters on the soles of his bare feet', true, '222c5024-5216-4f63-9ec9-85301ad6e325');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b97491c7-5235-4e8c-a43b-6460bb1572fc', 'Because he wanted to steal mangoes', false, '222c5024-5216-4f63-9ec9-85301ad6e325');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b452b3-26af-48de-a1f9-548d2817d7ae', 'Because he was singing a song', false, '222c5024-5216-4f63-9ec9-85301ad6e325');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('769ca084-b4c5-46b1-ab6b-0a53f3acb5fb', 'Because he lost his glasses', false, '222c5024-5216-4f63-9ec9-85301ad6e325');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c6c9aaf-0e00-4278-9ba7-8337883f51c3', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What did the compassionate children (Ravi, Meena, and Mridu) decide to give to the blistered barefoot beggar?', 'Pitying his blistered feet, the children gifted the music master''s sturdy chappals to the beggar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0693f4b2-d459-4916-89bc-7f178848e625', 'The large, grey, dusty pair of chappals lying near the verandah (which belonged to the Music Master)', true, '5c6c9aaf-0e00-4278-9ba7-8337883f51c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7f9dd13-a60b-4853-a97c-f8742fcce89c', 'A bag of gold coins', false, '5c6c9aaf-0e00-4278-9ba7-8337883f51c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74eda85f-e9bf-4c71-ac75-1b477ca231cc', 'A pair of roller skates', false, '5c6c9aaf-0e00-4278-9ba7-8337883f51c3');
