INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('391de9ed-fe27-4045-a7e3-9892c73bbd70', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'To pacify the furious, search-weary Music Master whose chappals had vanished, whose brand new chappals did Rukku Manni give to him?', 'Rukku Manni surrendered Gopu Mama''s pristine chappals to appease the aggrieved music teacher.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1223cdb7-3e5b-4ef3-8734-10acda5f36b6', 'Gopu Mama''s hardly-worn chappals', true, '391de9ed-fe27-4045-a7e3-9892c73bbd70');
