INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7273498d-2229-464d-ad1a-4ed72a06eba7', 'Paati''s sandals', false, '391de9ed-fe27-4045-a7e3-9892c73bbd70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a2e2b1c-2c33-4b7c-81aa-94c3d69e8817', 'Tapi''s slippers', false, '391de9ed-fe27-4045-a7e3-9892c73bbd70');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d063d77-c5f5-4119-80f9-025dfd6f6ce7', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'In D.J. Enright''s poem ''The Rebel'', what does the Rebel do when everybody else has short hair?', 'Enright contrasts non-conformist behavior: when others cut hair short, the rebel grows long hair.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('578cdb79-3535-41f2-9ed6-e0e0950170a3', 'The rebel lets his hair grow long', true, '7d063d77-c5f5-4119-80f9-025dfd6f6ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd78b142-05b2-4373-b196-f2ee7f9bcac5', 'He cuts his hair off completely', false, '7d063d77-c5f5-4119-80f9-025dfd6f6ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6506cdf-60a3-4c0a-9ca8-275d50213b60', 'He paints his hair blue', false, '7d063d77-c5f5-4119-80f9-025dfd6f6ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e671ff4-15a0-49b6-9e8e-8fcbf05547d5', 'He wears a hat', false, '7d063d77-c5f5-4119-80f9-025dfd6f6ce7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48f60cac-f8ff-4000-ae02-e11797b7b458', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'In ''The Rebel'', what does the Rebel express when everybody else is praising the bright warm Sun?', 'The rebel systematically seeks contrast: desiring rain during sunshine and sunshine during rain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8d1bbf9-82de-471e-b6b2-e11b3e738a69', 'The rebel remarks on the need for Rain', true, '48f60cac-f8ff-4000-ae02-e11797b7b458');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b59a435-e9bf-487b-a8ae-2362875540cc', 'The rebel wears sunglasses', false, '48f60cac-f8ff-4000-ae02-e11797b7b458');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80c9e91d-8f47-4afb-8012-40d6edbe0136', 'The rebel praises the moon', false, '48f60cac-f8ff-4000-ae02-e11797b7b458');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c50136b3-30ee-4b3e-9ca7-4e535246e120', 'The rebel stays asleep', false, '48f60cac-f8ff-4000-ae02-e11797b7b458');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3315462e-dca3-4e5c-8e74-7975d89393e9', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What kind of sentence expresses a direct command, request, or advice (e.g. ''Don''t make that noise!'', ''Please give him chappals.'')?', 'Imperative sentences issue orders, prohibitions, entreaties, or instructional advice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a438ee4-cb9c-4404-9f5d-8ae40da5aee8', 'Imperative Sentence', true, '3315462e-dca3-4e5c-8e74-7975d89393e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21f865d5-ef5f-4324-afd1-6a78bc54e985', 'Interrogative Sentence', false, '3315462e-dca3-4e5c-8e74-7975d89393e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0edfd226-f7d0-4629-8d7c-ca9bbe5f8c90', 'Exclamatory Sentence', false, '3315462e-dca3-4e5c-8e74-7975d89393e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8238dd31-46fb-4783-b99c-2645f82ec6c8', 'Declarative Sentence', false, '3315462e-dca3-4e5c-8e74-7975d89393e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1b0bdd3-544a-4b4e-b6a8-81ef99db1f4e', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What is the past continuous tense form of the verb ''dig'' for a plural subject (They)?', 'Past Continuous plural: were + verb-ing → ''were digging''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22be404e-0245-4cf3-aa5e-46d576d08dba', 'They were digging', true, 'b1b0bdd3-544a-4b4e-b6a8-81ef99db1f4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('559a187a-ef55-4b44-92c8-e0472335fa17', 'They was digging', false, 'b1b0bdd3-544a-4b4e-b6a8-81ef99db1f4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f00eee20-31a1-4b37-8b7e-d6e7bb99eb2a', 'They are digging', false, 'b1b0bdd3-544a-4b4e-b6a8-81ef99db1f4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('373fbdfb-046e-4854-9766-28c9f7187f62', 'They have digged', false, 'b1b0bdd3-544a-4b4e-b6a8-81ef99db1f4e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('124b41f7-4c7c-4af6-9580-d26b91eb34a4', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'How did Ravi cleverly smuggle milk from the kitchen for the secret kitten without Paati suspecting him?', 'Ravi staged drinking the milk under Paati''s watchful eye before dashing to feed the kitten.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7593960d-6e26-41b6-9ecf-2db8f53efc4f', 'He took milk in a glass, pretending he was very hungry; when Paati saw him, he drank most of it right in front of her to prove he was drinking it, ran out, poured the remaining milk into the coconut shell, and quickly washed the glass', true, '124b41f7-4c7c-4af6-9580-d26b91eb34a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e05c9bf3-6a9c-428c-a289-71bf95f582ab', 'He bought milk from a store', false, '124b41f7-4c7c-4af6-9580-d26b91eb34a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa16c24-d49d-4d39-8f81-8caed0254cea', 'He told Paati the truth directly', false, '124b41f7-4c7c-4af6-9580-d26b91eb34a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98e9db6f-d41c-4c3d-90c6-ef6096c029bb', 'He hid a cow in the garden', false, '124b41f7-4c7c-4af6-9580-d26b91eb34a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c54185a8-49ce-48cb-aad1-3509d775e3f2', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'What humorous comparison did the author draw between the Music Master''s violin playing and Lalli''s violin playing?', 'Vasantha Surya contrasts the master''s melodic precision with Lalli''s discordant screeching derailments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d2a0dfa-6214-4647-a85a-4b3a4339f415', 'The music master''s notes glided smoothly on melody tracks like a train on smooth rails, while Lalli went off the rails completely, screeching and derailing constantly', true, 'c54185a8-49ce-48cb-aad1-3509d775e3f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15471259-414c-42b8-8abb-a2abb32070d3', 'Lalli played better than the teacher', false, 'c54185a8-49ce-48cb-aad1-3509d775e3f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbcef129-6d68-4852-9045-0515579cfbec', 'Both sounded like sweet singing birds', false, 'c54185a8-49ce-48cb-aad1-3509d775e3f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85d92f79-7528-4ff5-9bf4-00924e62e221', 'Both played with their eyes closed', false, 'c54185a8-49ce-48cb-aad1-3509d775e3f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('947caeb7-354e-47d0-95a8-795e20fbf2f3', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'Why did Ravi argue with Rukku Manni about ''Karna'' from the Mahabharata when she scolded him for giving away the music master''s chappals?', 'Ravi pointed out adult moral contradiction: preaching the legendary charity of Karna while penalizing genuine compassionate giving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce488642-1cb9-4824-814d-6973e62eeb78', 'Ravi argued that adults always preach about being generous and giving to the needy like the great giver Karna, yet get angry when children actually practice true generosity', true, '947caeb7-354e-47d0-95a8-795e20fbf2f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34e8b186-513e-4e58-a2ac-35264573cc9e', 'Because Ravi wanted to become a king like Karna', false, '947caeb7-354e-47d0-95a8-795e20fbf2f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eb52f50-7e22-468e-b93f-fe6dd5766711', 'Because Karna was a music master', false, '947caeb7-354e-47d0-95a8-795e20fbf2f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe86c53a-eae3-4796-b1f2-3f90c17dad14', 'Because Karna had chappals made of gold', false, '947caeb7-354e-47d0-95a8-795e20fbf2f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f30dd192-f665-4ea5-aa29-c5111eb81cf3', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'How did Rukku Manni react after the Music Master left with Gopu Mama''s chappals when she thought of Gopu Mama coming home from office?', 'Rukku Manni''s exasperation melts into rueful humor anticipating Gopu Mama''s predictable evening reaction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23daa7cf-6e0d-44ff-938f-411868f5a4ad', 'Her anger dissolved into laughter wondering what excuse she would give Gopu Mama, who always kicks off his shoes and wants his chappals the moment he enters the house', true, 'f30dd192-f665-4ea5-aa29-c5111eb81cf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ffb5841-4dd0-4a4e-bde4-6c2907ab58ad', 'She started crying loudly', false, 'f30dd192-f665-4ea5-aa29-c5111eb81cf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('163a50be-39f9-4ef7-86eb-54c70d36046b', 'She punished Ravi with no food', false, 'f30dd192-f665-4ea5-aa29-c5111eb81cf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f7753a2-a0ca-4e3c-bf1c-e043d823ee01', 'She chased the music master down the street', false, 'f30dd192-f665-4ea5-aa29-c5111eb81cf3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bf1f71e-cd4e-4819-b4f4-18fc29358ad2', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'In ''The Rebel'', what social value or perspective does the poet conclude with regarding rebels in society?', 'Enright balances social utility with personal cost: non-conformity enriches cultural vitality but invites social friction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66f95ac7-ca79-48f6-aa77-94cb892d23c6', 'It is good that we have rebels because they bring diversity and challenge rigid conformity, but it is not very good to BE one yourself because society often isolates and misunderstands them', true, '8bf1f71e-cd4e-4819-b4f4-18fc29358ad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aeccd0b-3709-4936-aa4a-5bd185fdf476', 'Rebels should all be put in prison', false, '8bf1f71e-cd4e-4819-b4f4-18fc29358ad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84cb3fae-5225-41d5-a23a-c6d0edf2f959', 'Everyone must become a rebel', false, '8bf1f71e-cd4e-4819-b4f4-18fc29358ad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0e035ec-96bd-4382-97a7-08eba94f140a', 'Rebels are always evil', false, '8bf1f71e-cd4e-4819-b4f4-18fc29358ad2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('988daa0f-c86f-4e09-8cff-080a2c290452', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'Identify the correct meaning of the underlined idiom in: ''The music master''s eyes **lit up** when he saw Gopu Mama''s brand new chappals.''', '''Eyes lit up'' idiomatically conveys spontaneous delight and concealed covetousness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0135716-8b41-4f82-9d50-49ea0f36cc2d', 'Showed sudden, unmistakable delight, greed, and satisfaction', true, '988daa0f-c86f-4e09-8cff-080a2c290452');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd55d64c-e297-4e1c-b8de-9200e0c0b67f', 'Caught fire literally', false, '988daa0f-c86f-4e09-8cff-080a2c290452');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f28f066-49a9-4637-9570-09dd0563129e', 'Turned bright yellow', false, '988daa0f-c86f-4e09-8cff-080a2c290452');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75b61960-5295-4794-8886-0a0a850f737c', 'Became blind', false, '988daa0f-c86f-4e09-8cff-080a2c290452');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23338722-65bf-4009-9385-257aa63ba50c', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'Choose the correct question framed using an ''IF'' conditional clause for: ''You want to know if it will rain tomorrow before planning a picnic.''', 'Standard first conditional interrogative: ''What will we do if it rains tomorrow?''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e5fe2a0-07f2-4d2e-92c8-611d657f9b5b', '''What will we do if it rains tomorrow?''', true, '23338722-65bf-4009-9385-257aa63ba50c');
