INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d976a494-04a6-4adb-ad22-601898b369f9', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'What is the SYNONYM of the word ''Snooze'' as used in ''The beggar was having a snooze under the neem tree''?', '''Snooze'' denotes a brief, light period of slumber or daytime nap.', NOW()) ON CONFLICT DO NOTHING;
