INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8dbcd41-c744-4505-96a2-d15f2c3f2377', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'What is the meaning of the word ''Lurking'' in: ''The kitten was lurking behind the bitter-berry bush''?', '''Lurking'' means remaining concealed in ambient cover, often stealthily.', NOW()) ON CONFLICT DO NOTHING;
