INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af829a7d-475b-4ec3-9144-127b800aa708', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'Choose the sentence that correctly uses the PAST CONTINUOUS tense:', 'Two concurrent past continuing actions: ''was teaching'' and ''was calling''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa539720-a9d7-4e27-9405-3c05f872dc33', '''While the music master was teaching Lalli, the beggar was calling from the gate.''', true, 'af829a7d-475b-4ec3-9144-127b800aa708');
