INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72718903-e1ae-4d37-bdf9-53fd182f1640', '''The music master taught while the beggar called.''', false, 'af829a7d-475b-4ec3-9144-127b800aa708');
