INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c90af681-184e-4ef9-8c0e-5e3d63ae6b55', 'Stingy / Miserly / Selfish', true, '2c1f1675-978c-4fa2-a934-5199033166bd');
