INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b674807c-86c4-4ae1-afed-616a64abf5f4', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'What literary device is used in the contrasting rhyming pairs of ''The Rebel'' (''When everybody has short hair, The rebel lets his hair grow long'')?', 'Antithesis pairs diametrically opposing behavioral traits in structured syntactic balance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('669486c8-4933-4260-b34e-9d3eee56d1ea', 'Antithesis / Contrast (juxtaposition of sharply opposing ideas)', true, 'b674807c-86c4-4ae1-afed-616a64abf5f4');
