INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ed95253-825e-40af-a998-1a6fa7eac660', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'Identify the part of speech of the underlined word in: ''The tar on the road had melted into **boiling** black lava.''', '''Boiling'' functions as a present participial adjective qualifying the noun ''lava''.', NOW()) ON CONFLICT DO NOTHING;
