INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0dd230ea-f7ef-4cc7-afd9-1bd0f7117ce8', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'Choose the correctly punctuated direct speech sentence:', 'Direct question punctuation: quotation marks enclose the question mark, followed by lower-case reporting clause.', NOW()) ON CONFLICT DO NOTHING;
