INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3ec3f23-6ce0-43b8-b3cb-546cdec0302f', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'Analyze D.J. Enright''s philosophical treatment of the ''Rebel'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eacecf1-825f-48dd-a760-1e1dbf97eb92', 'The innate dialectical counter-force of individualistic non-conformity that resists herd mentality and questions uniform social orthodoxy', true, 'c3ec3f23-6ce0-43b8-b3cb-546cdec0302f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a49481f-ef37-4375-87a3-a267f2095e6a', 'A violent criminal wanting to destroy society', false, 'c3ec3f23-6ce0-43b8-b3cb-546cdec0302f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('653cd917-7960-4089-ad0b-143cdb29985d', 'A foolish person who knows nothing', false, 'c3ec3f23-6ce0-43b8-b3cb-546cdec0302f');
