INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('813b4f53-25ec-4584-8502-b8a79c4bd80a', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'Identify the grammatical structure and mood of the sentence: ''Give the poor man some chappals, or his feet will burn to blisters!''', 'Compound imperative joined by disjunctive coordinator ''or'' outlining urgent action and consequence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('076f5c50-5ecf-4197-8964-59f7868848c9', 'Compound Imperative Sentence with a coordinating conjunction ''or'' expressing an urgent moral injunction and consequence', true, '813b4f53-25ec-4584-8502-b8a79c4bd80a');
