INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c51b8da2-5d38-4221-b650-1d900b965005', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'What is the situational irony in the Music Master''s description of his old stolen chappals:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c8f9d86-a779-4cd3-96ac-65c8c4ba63c0', 'The chappals were actually decrepit, faded grey with dust and toe-marks, but he exaggerated their value out of greedy vanity to demand a new replacement', true, 'c51b8da2-5d38-4221-b650-1d900b965005');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ad37f4d-a350-43fd-a9cb-69df28351016', 'The chappals were made of pure platinum', false, 'c51b8da2-5d38-4221-b650-1d900b965005');
