INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aba0dedc-1ca0-4647-b0d5-87efbe3aff31', 'The chappals were magical', false, 'c51b8da2-5d38-4221-b650-1d900b965005');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5f8d5b4-dd19-4bc9-aacd-abe036d95d67', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'Which of the following demonstrates the correct use of INVERSION after a negative adverb in formal literary English?', 'Negative adverbial inversion: ''Hardly had [subject] [past participle] when...''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9367eff-620b-4fa6-b72f-62196102c21d', '''Hardly had the beggar sat down when Rukku Manni ordered him to leave.''', true, 'b5f8d5b4-dd19-4bc9-aacd-abe036d95d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bae8239-2680-4ec9-bd34-379b96992911', '''Hardly the beggar had sat down when Rukku Manni ordered him.''', false, 'b5f8d5b4-dd19-4bc9-aacd-abe036d95d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76c5b028-64ef-462b-b81f-462303490bc6', '''Hardly the beggar sat down then Rukku Manni ordered.''', false, 'b5f8d5b4-dd19-4bc9-aacd-abe036d95d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7d08b37-481a-479d-b2d0-aafecc389007', '''Hardly was the beggar sitting when then Rukku Manni ordered.''', false, 'b5f8d5b4-dd19-4bc9-aacd-abe036d95d67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fbb35d5-0ccd-4bca-9c4a-b4edb2283298', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'What humorous family dynamic is captured when Ravi says about Gopu Mama: ''He''s always in such a hurry to throw off his shoes and socks and get into his chappals as soon as he comes home''?', 'The detail grounds the climax in recognizable domestic realism, creating anticipatory comedic tension.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bc6915e-ef91-4736-8160-94e07aef9107', 'The universal domestic habit of working adults shedding formal office attire for casual comfort, setting up the impending humorous confrontation', true, '2fbb35d5-0ccd-4bca-9c4a-b4edb2283298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f88a29e-e71a-400c-a095-e9d1c4ca07eb', 'That Gopu Mama never goes to office', false, '2fbb35d5-0ccd-4bca-9c4a-b4edb2283298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16f390d2-7e31-44f6-ab20-32d7e38b34f7', 'That Gopu Mama walks barefoot outside', false, '2fbb35d5-0ccd-4bca-9c4a-b4edb2283298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a12514-46bc-4543-bf47-6bf06559c70b', 'That Gopu Mama has no shoes', false, '2fbb35d5-0ccd-4bca-9c4a-b4edb2283298');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d1f22ca-d16e-456f-987c-84e23632d68c', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'In ''The Rebel'', when everybody goes to the meeting, what does the Rebel do?', 'Textual line: ''When everybody goes to the meeting, / The rebel stays at home and reads a book''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('742ba1ed-cd43-4e2f-8d5c-e34237790104', 'The rebel stays at home and reads a book', true, '0d1f22ca-d16e-456f-987c-84e23632d68c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bfedca2-c59c-41ef-9108-3295fda42cd1', 'The rebel gives a long speech', false, '0d1f22ca-d16e-456f-987c-84e23632d68c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00310bb6-66bd-4628-b761-7c0446afc5e4', 'The rebel dances outside', false, '0d1f22ca-d16e-456f-987c-84e23632d68c');
