INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('413c2017-f405-4b80-a4fc-082136d0c8f3', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'Transform the direct speech into INDIRECT SPEECH:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40cfcdde-e5d8-4c2a-886e-d5edbe11db41', 'Ravi argued that Karna had not given away other people''s things, but had given away what was his own.', true, '413c2017-f405-4b80-a4fc-082136d0c8f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8a98fd3-718d-42c8-b8c7-01c7e4efded6', 'Ravi says that Karna gives away other people''s things.', false, '413c2017-f405-4b80-a4fc-082136d0c8f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf19b830-fdd3-44bb-8b13-7fb3ba1a8523', 'Ravi asked why Karna gave away his own things.', false, '413c2017-f405-4b80-a4fc-082136d0c8f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c163c1dc-be92-4333-992a-05182a338774', 'Ravi told that Karna did not give his own things.', false, '413c2017-f405-4b80-a4fc-082136d0c8f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f40c24b-3d9e-46f4-bb21-4e30e46b3ec2', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'What common ethical thread unites the narrative of ''A Gift of Chappals'' with the poetic philosophy of ''The Rebel''?', 'Both texts champion autonomous moral agency and empathetic non-conformity against rigid conventional orthodoxies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93443aa4-6613-4f94-a4b6-5a7f92f56411', 'Both celebrate the courage of independent conscience—whether in children defying social norms to alleviate real suffering or in individuals resisting unthinking conformity', true, '2f40c24b-3d9e-46f4-bb21-4e30e46b3ec2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('860798de-e7d1-4643-a119-98718018d2cf', 'Both advocate punishing all children', false, '2f40c24b-3d9e-46f4-bb21-4e30e46b3ec2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4e9dffa-3264-4cec-b7de-f97b4715f77e', 'Both state that music is unnecessary', false, '2f40c24b-3d9e-46f4-bb21-4e30e46b3ec2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f8768ea-40dc-4159-8be9-f8593c3257ab', 'Both teach that one should never buy new shoes', false, '2f40c24b-3d9e-46f4-bb21-4e30e46b3ec2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e893094f-0199-4d0c-96dd-7e69d7ce2c73', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Easy', 'In which year was India''s landmark wildlife conservation initiative ''Project Tiger'' launched at Jim Corbett National Park to save the Royal Bengal Tiger?', 'Project Tiger was launched on 1 April 1973 under Prime Minister Indira Gandhi at Corbett National Park.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07534098-8026-4c17-aeae-fc59df370055', '1973 (1st April 1973)', true, 'e893094f-0199-4d0c-96dd-7e69d7ce2c73');
