INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba12fce0-ed2a-4536-8b16-01dddf42092c', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the unique evolutionary feature of Monotremes (such as the Duck-billed Platypus and Echidna of Australia)?', 'Monotremes are oviparous (egg-laying) mammals possessing mammary gland milk secretion and cloacal anatomy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e694ccc-1c51-4b20-8e9e-e031bf71ec47', 'They are the ONLY surviving mammals that lay EGGS instead of giving birth to live young, yet suckle their hatched young with mother''s milk', true, 'ba12fce0-ed2a-4536-8b16-01dddf42092c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7083a8c5-27bf-4a66-83ee-8b0f44cfb73a', 'They have scales like fish', false, 'ba12fce0-ed2a-4536-8b16-01dddf42092c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0073e2ea-2ff8-46e5-a32e-8d7b7b498e74', 'They can breathe underwater without lungs', false, 'ba12fce0-ed2a-4536-8b16-01dddf42092c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfa2dc20-2ffd-40ea-84e2-5110712e1750', 'They have no blood', false, 'ba12fce0-ed2a-4536-8b16-01dddf42092c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c24657bb-c5e5-4df1-b475-f4344bd8b8e3', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the unique biological feature of Marsupial mammals (such as Kangaroos, Koalas, and Wombats)?', 'Marsupials possess a short gestation period followed by post-natal lactation development inside a ventral pouch (marsupium).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9a6ea82-b794-41d0-a39e-363c412ee03f', 'Females give birth to tiny, underdeveloped embryonic young that crawl into an external maternal abdominal pouch (Marsupium) to nurse and complete development', true, 'c24657bb-c5e5-4df1-b475-f4344bd8b8e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dde134f-d6cc-4b82-9790-7feb0615299c', 'They can fly like eagles', false, 'c24657bb-c5e5-4df1-b475-f4344bd8b8e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3825e72e-64fc-45df-9021-5de1109d2de8', 'They are cold-blooded like snakes', false, 'c24657bb-c5e5-4df1-b475-f4344bd8b8e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ececabf-5535-48e4-ae1e-7716c4400f61', 'They have blue fur', false, 'c24657bb-c5e5-4df1-b475-f4344bd8b8e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8149583e-0eb8-449b-9138-525ce54e1b50', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is ''Echolocation'' used by Bats and Toothed Whales (Dolphins) to hunt prey and navigate in total darkness?', 'Biological sonar/echolocation computes spatial acoustic topographies from reflected ultrasonic wave reflections.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d870e7cf-81ca-4700-8238-4072eeda6536', 'Emitting high-frequency ultrasound sound pulses and listening to returning reflected echoes to calculate the exact distance, shape, and speed of objects', true, '8149583e-0eb8-449b-9138-525ce54e1b50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcfc7bdd-9e88-49a3-afb2-d3d6765b5f35', 'Using thermal heat vision', false, '8149583e-0eb8-449b-9138-525ce54e1b50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39026dc8-462b-47b7-b134-af782fb64ffb', 'Smelling underwater', false, '8149583e-0eb8-449b-9138-525ce54e1b50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2289d21d-dbfe-478e-9572-abe9c2601bd9', 'Using magnetic compasses in eyes', false, '8149583e-0eb8-449b-9138-525ce54e1b50');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6df7fe23-0414-43ae-ba4c-2e11dd3c49b2', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'Which marine reptile undertakes epic multi-thousand-kilometer trans-oceanic migrations to nest in millions simultaneously (''Arribada'') on the beaches of Gahirmatha and Rushikulya in Odisha?', 'Gahirmatha Marine Sanctuary in Odisha is the world''s largest mass-nesting rookery (Arribada) for Olive Ridley sea turtles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('966cabee-022d-4ce7-8c07-4df0d9a6c414', 'Olive Ridley Sea Turtle (Lepidochelys olivacea)', true, '6df7fe23-0414-43ae-ba4c-2e11dd3c49b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adc379f4-230b-4641-b031-f6086edc9374', 'Leatherback Sea Turtle', false, '6df7fe23-0414-43ae-ba4c-2e11dd3c49b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('847dc94e-20cf-4d84-8c51-7c13046408f0', 'Green Sea Turtle', false, '6df7fe23-0414-43ae-ba4c-2e11dd3c49b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21c02393-97b5-4790-b516-ee73e86a96c1', 'Hawksbill Turtle', false, '6df7fe23-0414-43ae-ba4c-2e11dd3c49b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76ffcb11-60ea-470b-9c59-f82526b7d9ed', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the specialized physiological adaptation that allows Camels to survive weeks in scorching desert heat without drinking water?', 'Fat oxidation in humps, non-nucleated oval erythrocytes, high renal water reabsorption, and variable body temperature allow camel xerophilic survival.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e11705-79be-4094-96a5-4024c0d88aeb', 'Storing energy-rich fat in their humps (which metabolizes into metabolic water and calories), having oval red blood cells that withstand dehydration, and minimizing sweat/urine loss', true, '76ffcb11-60ea-470b-9c59-f82526b7d9ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37b93dbd-6bfa-48d9-ae65-1c541563a71b', 'Storing 100 litres of liquid water in their stomach', false, '76ffcb11-60ea-470b-9c59-f82526b7d9ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4de5ca9-0e44-46ff-b2c5-cb35f30c2c07', 'Drinking seawater directly', false, '76ffcb11-60ea-470b-9c59-f82526b7d9ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d60f3674-b65e-424e-b829-2ad1ed177dee', 'Sweating 50 litres of water an hour', false, '76ffcb11-60ea-470b-9c59-f82526b7d9ed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2bb16f4-a3be-4ca7-9721-537c6a7489e1', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the venomous snake in the world that builds dedicated leaf-litter nests to incubate its eggs, growing up to 5.5 metres long?', 'The King Cobra is the world''s longest venomous snake and the only snake that constructs dedicated botanical nests for maternal incubation.', NOW()) ON CONFLICT DO NOTHING;
