INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd6d06ab-684b-49c6-b9c0-4a74f534bb0a', 'Black Mamba', false, 'a2bb16f4-a3be-4ca7-9721-537c6a7489e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69baf5e4-e7c2-4c6d-b489-2d9924cab440', 'Russell''s Viper', false, 'a2bb16f4-a3be-4ca7-9721-537c6a7489e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b35eebfa-bd71-49c0-a447-80b0606acc49', 'Common Krait', false, 'a2bb16f4-a3be-4ca7-9721-537c6a7489e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cb388b1-e040-4d7e-ab91-5bde2d16e059', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the specialized adaptation of the Arctic Polar Bear (Ursus maritimus) that keeps it warm in freezing sub-zero temperatures?', 'Subcutaneous blubber, dense underfur, hollow photon-scattering guard hairs, and melanin-rich black heat-absorbing epidermis insulate polar bears.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d0d84e-53b1-43c0-b051-3233be6dd29f', 'A thick 10 cm layer of insulating subcutaneous fat (blubber), two dense fur coats, and black skin underneath translucent hollow hair fibers that absorb solar heat', true, '8cb388b1-e040-4d7e-ab91-5bde2d16e059');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bd4b0a9-8b39-4503-ad20-680d7681b2e8', 'Feathers on its paws', false, '8cb388b1-e040-4d7e-ab91-5bde2d16e059');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb251606-9cfa-41e0-88be-d7727c339391', 'Drinking boiling water', false, '8cb388b1-e040-4d7e-ab91-5bde2d16e059');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f106d4d-ca6d-4451-be74-20d2421a4435', 'Sleeping for 10 years without waking', false, '8cb388b1-e040-4d7e-ab91-5bde2d16e059');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5253e90d-6bbb-4d37-b516-ec97fa74c69a', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'Which Indian state has the LARGEST number of wild Bengal Tigers according to the National Tiger Census (over 780 tigers)?', 'Madhya Pradesh leads national tiger counts with 785 tigers, earning its designation as the Tiger State of India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f89ac1c-e8bd-4e9e-9c8e-29991e49518c', 'Madhya Pradesh (''The Tiger State of India'')', true, '5253e90d-6bbb-4d37-b516-ec97fa74c69a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae011db0-5383-4cf2-940b-67d55573ded1', 'Karnataka', false, '5253e90d-6bbb-4d37-b516-ec97fa74c69a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8054867-b694-4e36-bac7-ceaaac271426', 'Uttarakhand', false, '5253e90d-6bbb-4d37-b516-ec97fa74c69a');
