INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('422c67cf-fbc5-4e0e-8b5e-9d7d0f40d0d4', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is ''Coral Bleaching'' in ocean ecosystems?', 'Thermal ocean stress disrupts the mutualism between scleractinian corals and endosymbiotic zooxanthellae, resulting in bleaching.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9029d79d-e62a-46e1-949c-0c28e8d358b0', 'Rising sea water temperatures cause stressed coral polyps to expel their symbiotic photosynthetic algae (Zooxanthellae), turning corals ghostly white and risking mass mortality', true, '422c67cf-fbc5-4e0e-8b5e-9d7d0f40d0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb711caa-436c-4c27-a91c-8c3dd4e3d4b7', 'Corals being painted with white bleach', false, '422c67cf-fbc5-4e0e-8b5e-9d7d0f40d0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('375edbb5-faab-4ec8-a617-aad781b6818e', 'Corals freezing into ice', false, '422c67cf-fbc5-4e0e-8b5e-9d7d0f40d0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2be12127-64e0-4172-8f34-df0f116c527c', 'Fish eating all coral rocks', false, '422c67cf-fbc5-4e0e-8b5e-9d7d0f40d0d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8efcc00f-6147-4be1-8187-9a1e0eb498ff', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the ONLY species of deer in the world where both males and females grow branched antlers?', 'Reindeer (Rangifer tarandus) are unique among cervids in that both stags and hinds grow annual branched bone antlers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fbfe8eb-1c41-418b-ae07-5708d206aa4b', 'Reindeer (Caribou)', true, '8efcc00f-6147-4be1-8187-9a1e0eb498ff');
