INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75756b75-2625-4149-801d-73ee6892ebbb', 'Sambar Deer', false, '8efcc00f-6147-4be1-8187-9a1e0eb498ff');
