INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('223e9e5c-ed5f-4109-9bca-0895c8e7b626', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the famous national park in Karnataka, part of the Nilgiri Biosphere Reserve, renowned for having the largest wild Asian elephant concentration in Asia?', 'The contiguous Nagarhole-Bandipur-Mudumalai complex holds the highest global density of wild Asian elephants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e43fa609-8548-4d5d-96b9-a594b3d518bb', 'Nagarhole National Park (Rajiv Gandhi National Park) and Bandipur', true, '223e9e5c-ed5f-4109-9bca-0895c8e7b626');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0491578a-951e-4221-94fa-9964dc4c2c19', 'Periyar National Park', false, '223e9e5c-ed5f-4109-9bca-0895c8e7b626');
