INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4773e973-de95-4032-9108-d36e20188611', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the international conservation convention CITES (Convention on International Trade in Endangered Species of Wild Fauna and Flora)?', 'CITES (1975) accords international trade protections across 38,000+ species via tiered Appendices (I, II, III).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22d0ebd2-1477-4d31-bb84-eb45da2e1b7c', 'A legally binding global treaty regulating and banning commercial international trade in endangered wildlife specimens (ivory, tiger skins, rhino horns, exotic timber) to ensure species survival', true, '4773e973-de95-4032-9108-d36e20188611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7309a04-ecb9-4a7d-8691-bb1bb98c1501', 'A treaty that encourages hunting in all national parks', false, '4773e973-de95-4032-9108-d36e20188611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d313ba9-dea2-47e1-ac6c-3af9ca3cf6ac', 'A convention that sells wild animals in markets', false, '4773e973-de95-4032-9108-d36e20188611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cd6987a-b8ff-4d27-a93a-d1ed916c883b', 'A club of zoo owners', false, '4773e973-de95-4032-9108-d36e20188611');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29ce0437-5730-4150-9d1f-adf8b3fe286a', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'Match Column I (Unique Animals) with Column II (Evolutionary Superpowers):
(a) Axolotl (Mexican Salamander) -> (i) Full regeneration of lost limbs, spinal cord & heart
(b) Tardigrade (Water Bear)       -> (ii) Survives vacuum of space, radiation & -200°C via cryptobiosis
(c) Immortal Jellyfish           -> (iii) Reverts adult medusa cells back to polyp stage endlessly
(d) Peregrine Falcon             -> (iv) Fastest dive speed on Earth (over 380 km/h)', 'Axolotl = limb regeneration; Tardigrade = extreme cryptobiosis; Turritopsis dohrnii = biological immortality; Peregrine = 380 km/h dive.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a30bfdb0-d292-4e8a-9ef3-ab8fc17b3f3e', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '29ce0437-5730-4150-9d1f-adf8b3fe286a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9095100f-276c-496a-9ba7-8e2156bb7aab', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '29ce0437-5730-4150-9d1f-adf8b3fe286a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eb76058-9332-444c-93cb-6befa9649f1a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '29ce0437-5730-4150-9d1f-adf8b3fe286a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40b7f321-f1c3-48b3-b477-0bb685e0d080', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '29ce0437-5730-4150-9d1f-adf8b3fe286a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f810f18-9051-4781-b343-df2fb6c66c47', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'Read the statements regarding biodiversity hotspots in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfbfcf50-afc6-47e9-b1ec-699449475be6', 'Statements 1 and 2 only', true, '6f810f18-9051-4781-b343-df2fb6c66c47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc5740cb-4473-484e-87c5-68178ba60b81', 'Statements 2 and 3 only', false, '6f810f18-9051-4781-b343-df2fb6c66c47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('429e3318-ef7a-456c-ba13-d6888917a40b', 'Statements 1 and 3 only', false, '6f810f18-9051-4781-b343-df2fb6c66c47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05b9f20a-ee0e-4a36-827a-bdf72c68301a', 'All Statements 1, 2, and 3', false, '6f810f18-9051-4781-b343-df2fb6c66c47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f15db3f9-ed9d-41ca-b64e-f5a49d3140b0', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the unique deep-sea biological phenomenon where 90% of abyssal marine organisms generate their own cold biological light through the enzyme luciferase?', 'Bioluminescence oxidizes luciferin substrate catalyzed by luciferase, producing cold photon emission for communication and predation in dark depths.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdd2e204-467f-43f3-836c-4d88b4783f0f', 'Bioluminescence', true, 'f15db3f9-ed9d-41ca-b64e-f5a49d3140b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5294b596-30a2-4aa9-967a-54c07be1de90', 'Photosynthesis', false, 'f15db3f9-ed9d-41ca-b64e-f5a49d3140b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec01b859-fc11-49a9-8b0f-7fdadaefbd9e', 'Chemosynthesis', false, 'f15db3f9-ed9d-41ca-b64e-f5a49d3140b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('933bd02b-02b5-49a7-a2e1-a4a7ca38cd84', 'Bioaccumulation', false, 'f15db3f9-ed9d-41ca-b64e-f5a49d3140b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f8f6e76-ddd3-4199-9d2d-e4b5c78d0e20', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'Why was the ''Bishnoi Community'' of Rajasthan historically celebrated for world-pioneering environmental martyrdom in 1730 at Khejarli?', 'In 1730, Amrita Devi and 363 Bishnoi martyrs gave their lives protecting Prosopis cineraria (Khejri) trees, inspiring the modern Chipko movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca8d1326-aaea-4cbb-8c89-f3124560073b', 'Amrita Devi Bishnoi and 363 Bishnois sacrificed their lives hugging sacred Khejri trees to prevent them from being felled by royal soldiers', true, '9f8f6e76-ddd3-4199-9d2d-e4b5c78d0e20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61d88d6c-7d58-455c-94c5-7de4b5fd7288', 'They discovered diamond mines in the desert', false, '9f8f6e76-ddd3-4199-9d2d-e4b5c78d0e20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('544d67fe-e81e-46fd-a651-45be95be565b', 'They built the first zoo in India', false, '9f8f6e76-ddd3-4199-9d2d-e4b5c78d0e20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6112d22-bb4e-4525-9eca-257a2f6a5e8a', 'They invented solar powered cars', false, '9f8f6e76-ddd3-4199-9d2d-e4b5c78d0e20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b6d9047-2232-49b0-80d2-9f7a0725bd32', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the specialized migratory adaptation of the Arctic Tern (Sterna paradisaea) that makes it the champion world traveler?', 'The Arctic Tern completes the longest circumpolar pole-to-pole migration on Earth (~90,000 km annually).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cd3189c-a9ab-4ced-8b04-80d6c339fe73', 'It undertakes an annual round-trip migration of over 70,000 to 90,000 km between the Arctic and Antarctic, experiencing two summers a year', true, '6b6d9047-2232-49b0-80d2-9f7a0725bd32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4a6bfc1-44c8-4620-ae9f-b92c514e5de3', 'It flies to the moon and back', false, '6b6d9047-2232-49b0-80d2-9f7a0725bd32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9984d34-8f5a-4ab0-8b87-212571e1e873', 'It swims across the bottom of the ocean', false, '6b6d9047-2232-49b0-80d2-9f7a0725bd32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f159f7a-adc4-4b5c-8a73-3ebd1c5bc20b', 'It stays asleep while flying for 20 years', false, '6b6d9047-2232-49b0-80d2-9f7a0725bd32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6f1f57e-6e75-414c-9db8-b25e288c61e6', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is ''Biomagnification'' (Biological Magnification) in wildlife food chains?', 'Lipophilic xenobiotics resist metabolic breakdown, bio-accumulating exponentially toward apex trophic consumers (e.g. raptor eggshell thinning).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('878cb40c-dd76-45df-8468-3cc3aa3c1ab9', 'The progressive increase in concentration of persistent toxic non-biodegradable chemicals (like DDT, heavy metals, microplastics) at each successively higher trophic level', true, 'f6f1f57e-6e75-414c-9db8-b25e288c61e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4358234d-9820-4ffb-9bd5-978fc8df8b70', 'Animals growing bigger in size every year', false, 'f6f1f57e-6e75-414c-9db8-b25e288c61e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eff08445-d80e-4f81-bf43-e009ce4cba36', 'Looking at animals through a giant magnifying glass', false, 'f6f1f57e-6e75-414c-9db8-b25e288c61e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33ebc41f-b158-4f97-9b77-5c4a36cf16db', 'Plants producing double the flowers in spring', false, 'f6f1f57e-6e75-414c-9db8-b25e288c61e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('516ce232-ba60-4bc4-8690-e736cabd792a', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the critically endangered avian raptor of India whose population plummeted by 99% due to toxic veterinary residues of the anti-inflammatory drug ''Diclofenac'' in cattle carcasses?', 'Diclofenac ingested from livestock carcasses caused catastrophic visceral gout and renal failure in Gyps vultures across South Asia.', NOW()) ON CONFLICT DO NOTHING;
