INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('086f7979-a5a5-4a44-b7e3-1b78701f2af4', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the unique ecosystem function performed by the ''Mangrove Sundari Trees'' in the Sundarbans against cyclones and tidal storm surges?', 'Rhizophora and Heritiera prop root lattices attenuate hydrodynamic kinetic energy from severe tropical cyclonic surges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4663d60c-7527-43aa-b996-f30ba3fabe74', 'Their dense interlaced stilt and prop root systems dissipate up to 66% of cyclonic wave energy, acting as resilient bio-shields preventing coastal soil erosion', true, '086f7979-a5a5-4a44-b7e3-1b78701f2af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43228e28-c5e4-434e-a845-2295e9161f22', 'They produce poisonous gas against storms', false, '086f7979-a5a5-4a44-b7e3-1b78701f2af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6786af92-b573-4b92-8e0e-00f785f809bb', 'They absorb all salt from the sea', false, '086f7979-a5a5-4a44-b7e3-1b78701f2af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91c5cf1b-d342-4deb-9384-c89995566aec', 'They make rain fall backwards', false, '086f7979-a5a5-4a44-b7e3-1b78701f2af4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c46dc792-d433-4686-b2bf-470a5d3a7f6f', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What ultimate moral and scientific mandate concludes our understanding of the Global Animal Kingdom and Wildlife Conservation?', 'Ecosystem stability and human biospheric survival depend directly on preserving biodiversity, genetic resilience, and ecological networks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96260368-1b65-4207-b39f-07c722ec4159', 'Biodiversity is the living life-support infrastructure of planet Earth; preserving intact habitats, ecological corridors, and endangered species is essential for the survival of human civilization itself', true, 'c46dc792-d433-4686-b2bf-470a5d3a7f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f3d2039-6ae9-45dd-875f-68a90786ec20', 'Wild animals should be completely replaced by domesticated pets', false, 'c46dc792-d433-4686-b2bf-470a5d3a7f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad73702a-d6b1-4b99-b686-d70d095a6d15', 'Deforestation is necessary to eliminate all wild predators', false, 'c46dc792-d433-4686-b2bf-470a5d3a7f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7e0da00-8857-487f-9bce-bd72a625cc43', 'Only animals useful to human commerce deserve protection', false, 'c46dc792-d433-4686-b2bf-470a5d3a7f6f');
