INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6e5bc7e-d662-4ad8-8fc9-fae118b38910', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'Which famous Tamil Nadu temple inscription in Kanchipuram district provides detailed, exact rules and democratic lottery qualification procedures for election to the Sabha committees?', 'The 10th-century Parantaka I Uttaramerur inscriptions lay down precise democratic eligibility criteria and the pot-lottery (Kudavolai) voting system.', NOW()) ON CONFLICT DO NOTHING;
