INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d42b3570-b2b2-408a-b5a1-9ea30b207e47', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'How did Kadamba Mayurasharman and Gurjara-Pratihara Harichandra establish their royal dynasties in Karnataka and Rajasthan despite being Brahmanas by birth?', 'Brahmana chiefs Mayurasharman and Harichandra abandoned sacerdotal duties, taking up arms to establish Kadamba and Pratihara kingdoms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd20660c-4f75-40cd-a0bc-896f37faff3e', 'They gave up their traditional priestly vocations, took up arms and military warfare, and successfully carved out independent sovereign kingdoms by force', true, 'd42b3570-b2b2-408a-b5a1-9ea30b207e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63c3fe71-93fd-46e6-8860-18ce3dd7dd29', 'They were crowned by Roman emperors', false, 'd42b3570-b2b2-408a-b5a1-9ea30b207e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75237dd8-8d69-4668-821b-b83b61e16f1b', 'They inherited the kingdoms from Buddhist monks', false, 'd42b3570-b2b2-408a-b5a1-9ea30b207e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a79f636a-623a-485f-9601-091e12d5185e', 'They purchased the land with Greek gold', false, 'd42b3570-b2b2-408a-b5a1-9ea30b207e47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c29b37d7-973e-4ada-bb53-eecaca416262', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What was the ''Kudavolai'' system of democratic committee selection recorded in the Uttaramerur inscription of the Cholas?', 'The Kudavolai pot-lottery system selected committee members (Variyams) for irrigation, gardens, and temples via blind ballot draws.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa19f34e-fefc-4583-8c26-38a2f74b9ff0', 'Names of eligible candidates were written on palm-leaf tickets, placed in an earthenware pot, and a young boy was asked to pick tickets one by one to form specialized governing committees (Variyams)', true, 'c29b37d7-973e-4ada-bb53-eecaca416262');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fed0bcc-9d7b-42e4-8fc6-25607800c92b', 'Candidates fought a sword duel', false, 'c29b37d7-973e-4ada-bb53-eecaca416262');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bd73bb4-a03e-4fbd-96fe-4f54af0b4196', 'The King chose his family members only', false, 'c29b37d7-973e-4ada-bb53-eecaca416262');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fb8e798-25ce-4622-958b-127740da4d11', 'People raised hands in a large stadium', false, 'c29b37d7-973e-4ada-bb53-eecaca416262');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('532feb8f-f0fc-41e8-8fdb-678ecf3d34c1', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What rigorous eligibility criteria were mandated for a candidate to contest election to the Chola Sabha committees at Uttaramerur?', 'Uttaramerur rules: age 35–70, Vedic literacy, property ownership, financial integrity, and mandatory 3-year term rotation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4d02915-9121-419e-b0bf-06cd565384a7', 'Must own tax-paying land, have a private house, be aged 35–70, possess knowledge of the Vedas, be honest, and must NOT have served on any committee in the previous 3 years', true, '532feb8f-f0fc-41e8-8fdb-678ecf3d34c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e16ab421-efb0-40dd-b79b-b81ce8235483', 'Must be the richest merchant in the city', false, '532feb8f-f0fc-41e8-8fdb-678ecf3d34c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16c91830-9d2b-4e7b-91df-b30ca7ad5e2a', 'Must have won at least 10 wars', false, '532feb8f-f0fc-41e8-8fdb-678ecf3d34c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8504403a-d658-4573-a527-8af85c2e53ab', 'Must be a relative of the King', false, '532feb8f-f0fc-41e8-8fdb-678ecf3d34c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4bf04d57-753b-4a43-b3c6-41231e2b0f6f', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'Why was Kalhana''s Sanskrit historical chronicle ''Rajatarangini'' unique and remarkably distinct from typical contemporary court Prashastis?', 'Kalhana practiced critical historiography: cross-examining multiple epigraphic sources and offering candid critiques of royal misrule.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cab8e572-c534-43d0-9b4f-4aa69c01d71c', 'Unlike eulogistic court poets who only praised monarchs, Kalhana critically analyzed inscriptions, coins, and earlier chronicles, openly criticizing rulers for bad policies and unjust governance', true, '4bf04d57-753b-4a43-b3c6-41231e2b0f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fab62d8f-bd85-4144-b769-ce6102e89684', 'Because it was written in Persian poetry', false, '4bf04d57-753b-4a43-b3c6-41231e2b0f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e564a73-f86c-4f5d-92ce-2547eaa82d36', 'Because Kalhana was an Arab cartographer', false, '4bf04d57-753b-4a43-b3c6-41231e2b0f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('721073f6-0180-4c9e-a424-4f78fd06f3ed', 'Because it contains only fictional fairy tales', false, '4bf04d57-753b-4a43-b3c6-41231e2b0f6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8441246d-1696-408b-ad8e-5f76181088a2', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'Why did Mahmud of Ghazni (ruler of Ghazni, Afghanistan) repeatedly raid and plunder wealthy northern Indian temple cities (such as Somnath in Gujarat) between 1000 and 1025 CE?', 'Mahmud of Ghazni raided temple treasuries (Somnath 1026 CE) to finance Central Asian military expansions and embellish Ghazni.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6037d697-37ec-413b-b8aa-16c4a838e4cf', 'To loot immense accumulated gold and diamond temple wealth to finance his imperial campaigns, armies, and grand capital city of Ghazni in Central Asia', true, '8441246d-1696-408b-ad8e-5f76181088a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbd5144e-9ec1-49c2-808e-974e8c304cf9', 'To build Hindu temples in Afghanistan', false, '8441246d-1696-408b-ad8e-5f76181088a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffc7a091-af03-45dd-acc1-1cf6b9048bb2', 'To settle down as a farmer in Gujarat', false, '8441246d-1696-408b-ad8e-5f76181088a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d557ab0b-951d-42f2-8382-810bbfeadb65', 'To study Sanskrit literature in Varanasi', false, '8441246d-1696-408b-ad8e-5f76181088a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5904a4dd-82a8-4504-945c-6ee03e30edc5', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'Who was the profound Persian scholar and polymath whom Mahmud of Ghazni brought to India to study Indian culture, who authored the definitive encyclopedic work ''Kitab al-Hind''?', 'Al-Biruni mastered Sanskrit and consulted Brahmana pandits to author ''Kitab al-Hind'' (1030 CE), a masterwork on Indian science, religion, and philosophy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dc53d0a-7a79-462d-a3b7-f9bd80aeba9c', 'Al-Biruni (Abu Rayhan al-Biruni)', true, '5904a4dd-82a8-4504-945c-6ee03e30edc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38830299-c4f8-4ed1-9a01-95ddba1fdad6', 'Ibn Battuta', false, '5904a4dd-82a8-4504-945c-6ee03e30edc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aa7641a-8fb2-4fcb-b209-bf7e35f93cb0', 'Ziauddin Barani', false, '5904a4dd-82a8-4504-945c-6ee03e30edc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a3884bf-a734-4bee-9844-a65b78d539fb', 'Amir Khusrau', false, '5904a4dd-82a8-4504-945c-6ee03e30edc5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c743158c-6fc5-4a33-b97f-a0b6765c93cd', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What agricultural and hydraulic revolution engineered by the Cholas transformed the Kaveri delta into the granary of South India?', 'Chola hydraulic engineering: sluices, bunds, inter-connected irrigation canals, and community rainfed tanks (eris) yielding 2–3 rice crops annually.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3426f7c5-f946-4677-97bc-b3466cabaa69', 'Constructing massive river embankments to prevent flooding, digging extensive canal networks to channel Kaveri waters directly into paddy fields, and building enormous water storage tanks (Eris)', true, 'c743158c-6fc5-4a33-b97f-a0b6765c93cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0efcc0d9-3e40-4cdb-a4b3-2c249366d14a', 'Spraying chemical fertilizers imported from China', false, 'c743158c-6fc5-4a33-b97f-a0b6765c93cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e50aeab-a106-426f-a8f6-791764266616', 'Building glass greenhouses across all farms', false, 'c743158c-6fc5-4a33-b97f-a0b6765c93cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0219a8ce-f5eb-4674-b15a-8b0fb7dff4e5', 'Planting only wheat in coastal mud', false, 'c743158c-6fc5-4a33-b97f-a0b6765c93cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('687435ef-aee0-46ff-8d87-fae799f36eea', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In Chola inscriptions, what did the term ''Brahmadeya'' signify?', 'Brahmadeya was revenue-exempt land granted by monarchs to Brahmanas to promote Vedic learning and agricultural settlement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea237416-f761-4a7d-aaee-1bd5aba61fef', 'Tax-free agricultural land gifted as a royal endowment to learned Brahmanas', true, '687435ef-aee0-46ff-8d87-fae799f36eea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2646ffd0-070b-4a0d-9aeb-a48efd527a16', 'Land gifted to military generals', false, '687435ef-aee0-46ff-8d87-fae799f36eea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a3a757e-98fd-4470-86e9-d9a1bb412642', 'Land belonging to non-Brahmana peasants', false, '687435ef-aee0-46ff-8d87-fae799f36eea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13f5bc1f-f823-4889-90a0-820cecbad642', 'Land maintained for royal hunting', false, '687435ef-aee0-46ff-8d87-fae799f36eea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec0fd281-36ba-44b0-b57a-290b563210f0', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What were the administrative territorial divisions in the Chola Empire called (from largest to smallest)?', 'Chola administrative hierarchy: Mandalam (province) → Valanadu (district) → Nadu (taluk/village cluster) → Grama/Ur (village unit).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16dcf386-dded-41cc-927c-1c55a2f362d0', 'Mandalams (Provinces) -> Valanadus (Districts) -> Nadus (Groups of villages) -> Grama / Ur (Village)', true, 'ec0fd281-36ba-44b0-b57a-290b563210f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04ec23ef-e47a-44a7-8932-1f945cc6f580', 'States -> Cities -> Towns -> Houses', false, 'ec0fd281-36ba-44b0-b57a-290b563210f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe594e07-4fb7-4da8-a937-10492fdabf5d', 'Janapadas -> Mahajanapadas -> Empires', false, 'ec0fd281-36ba-44b0-b57a-290b563210f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bfdab12-544e-4511-a75d-467a983debcf', 'Subas -> Sarkars -> Parganas', false, 'ec0fd281-36ba-44b0-b57a-290b563210f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04cf7b53-f73e-4a0a-bdf5-579d66f8c98a', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In the 400 different tax terms recorded in Chola inscriptions, what was ''Vetti'' and ''Kadamai''?', 'Chola fiscal records (e.g. Thanjavur): Vetti represented uncompensated corvée forced labor, while Kadamai was agricultural land revenue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c57c24d-1f1d-4083-81ce-6c1cf027cb94', '''Vetti'' was tax taken not in cash but in the form of FORCED LABOUR ; ''Kadamai'' was land revenue tax', true, '04cf7b53-f73e-4a0a-bdf5-579d66f8c98a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7784bb64-ab5e-4f0f-9f38-f28c9e78d640', '''Vetti'' was a tax on horses ; ''Kadamai'' was a tax on houses', false, '04cf7b53-f73e-4a0a-bdf5-579d66f8c98a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a349726c-f278-486f-b65b-0af40f78bdb1', '''Vetti'' was tax on gold ; ''Kadamai'' was tax on silk', false, '04cf7b53-f73e-4a0a-bdf5-579d66f8c98a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e92f2f63-1ad3-40d5-9419-3b05c15ba532', 'Both were voluntary donations', false, '04cf7b53-f73e-4a0a-bdf5-579d66f8c98a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69239a33-e985-41c4-bb56-362b9f96e2c5', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What happened to the Gurjara-Pratiharas, Rashtrakutas, and Palas at the end of the long Tripartite Struggle?', 'Protracted attrition over Kannauj drained the treasuries of all three empires, fragmenting northern and peninsular India into smaller Rajput and Deccan states.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('467843d1-cbeb-42eb-8e44-f79e95e9a1ff', 'All three dynasties exhausted their military and economic resources in continuous war, leading to their mutual decline and replacement by feudatories (like Chauhans, Paramaras, Senas)', true, '69239a33-e985-41c4-bb56-362b9f96e2c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dcfbf85-0276-4229-9359-bdab19d92cb9', 'They formed a single combined world empire', false, '69239a33-e985-41c4-bb56-362b9f96e2c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8060ec4-b484-4974-bea2-20c966d61049', 'They ruled India together until the 19th century', false, '69239a33-e985-41c4-bb56-362b9f96e2c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87586c32-342a-410c-9fe6-760f25c298d5', 'They all migrated to Rome', false, '69239a33-e985-41c4-bb56-362b9f96e2c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('018d1458-ee42-4b98-80d1-ec15180101cf', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What grand titles did powerful medieval monarchs adopt to display imperial sovereignty (e.g. Tribhuvana-chakravartin)?', 'Medieval monarchs adopted grandiloquent imperial epithets (Maharajadhiraja, Tribhuvana-chakravartin) to project absolute cosmological authority.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88650864-4124-4110-841a-57c7032637c7', 'Maharajadhiraja (Great King of Kings) and Tribhuvana-chakravartin (Lord of the Three Worlds)', true, '018d1458-ee42-4b98-80d1-ec15180101cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('546a4b71-2c32-4c52-8d5b-0233fe7fd3fc', 'Raja only', false, '018d1458-ee42-4b98-80d1-ec15180101cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4ab6cb2-61eb-4bb1-ae15-c115baa7d566', 'Samanta', false, '018d1458-ee42-4b98-80d1-ec15180101cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4218dd2f-aa11-43de-9f67-0ea760702d1f', 'Gramani', false, '018d1458-ee42-4b98-80d1-ec15180101cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('548e189d-c1ba-4283-a5a5-921033329e7f', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In Chola land classification, what was ''Vellanvagai'' land?', 'Vellanvagai designated agricultural land holdings belonging to non-Brahmana Vellalar peasant proprietors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c296ff96-82b9-4e72-94b5-239ad3ffaccc', 'Land of non-Brahmana peasant proprietors', true, '548e189d-c1ba-4283-a5a5-921033329e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5489e5a3-e7b3-4046-81d6-1e537bfea7d0', 'Land gifted to temples', false, '548e189d-c1ba-4283-a5a5-921033329e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b599e7b-8cb7-4e39-90ff-289eadef7508', 'Land for maintenance of schools', false, '548e189d-c1ba-4283-a5a5-921033329e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bd79bf2-2034-4a0e-9908-3e9dccbfa292', 'Land gifted to Jain institutions', false, '548e189d-c1ba-4283-a5a5-921033329e7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9256ce0b-d697-4f81-8272-d5444361ff6d', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In Chola land classification, what was ''Shalabhoga'' land?', '''Shala'' (school) + ''Bhoga'' (endowment): Shalabhoga was land reserved exclusively to fund educational academies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d52cf6ae-1897-408c-a274-d8bad7ae760d', 'Land granted for the maintenance of a school (shala)', true, '9256ce0b-d697-4f81-8272-d5444361ff6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9326565-0d39-4f92-bbff-2c23cc866c00', 'Land gifted to temples', false, '9256ce0b-d697-4f81-8272-d5444361ff6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d213b28-c209-4e90-917a-a636aa133c99', 'Land for cattle grazing', false, '9256ce0b-d697-4f81-8272-d5444361ff6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb04c736-3775-40ad-957f-9edcc6fa73ad', 'Land given to palace cooks', false, '9256ce0b-d697-4f81-8272-d5444361ff6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('deaf1841-0d4f-4237-9aa8-5c397bd9af86', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In Chola land classification, what was ''Devadana'' (or Tirunamattukkani)?', 'Devadana (gift to gods) lands generated perennial revenue to maintain temple rituals, priests, musicians, and festivals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06967ace-cf06-498b-bc3d-c9083e8629f4', 'Land gifted directly to temples as sacred endowments', true, 'deaf1841-0d4f-4237-9aa8-5c397bd9af86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd0c40f0-1da9-4e35-b611-5f46ba37b03a', 'Land gifted to soldiers', false, 'deaf1841-0d4f-4237-9aa8-5c397bd9af86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82c22bcc-5805-4333-9a41-d1765ef3c61b', 'Land belonging to the king', false, 'deaf1841-0d4f-4237-9aa8-5c397bd9af86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c2329ac-b98e-4496-923b-a3de3c5a9f0f', 'Forest land', false, 'deaf1841-0d4f-4237-9aa8-5c397bd9af86');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93e86d1b-b57f-42ea-b291-9e7e6189867e', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What was ''Pallichchhandam'' in Chola land grants?', 'Pallichchhandam represented tax-free land endowments donated to support Jain monastic establishments (basadis).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab53554b-8aa1-499d-9b0b-034ab5efd074', 'Land donated to Jaina institutions and basadis', true, '93e86d1b-b57f-42ea-b291-9e7e6189867e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3ce2890-2e7e-44a0-a739-09707dc6fc26', 'Land for Buddhist stupas', false, '93e86d1b-b57f-42ea-b291-9e7e6189867e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aed6f40-7bc6-4cb9-a41f-91f54ac8d32e', 'Land for building roads', false, '93e86d1b-b57f-42ea-b291-9e7e6189867e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea4bb3ba-bdba-478b-8900-f7780a20c4bb', 'Land for royal stables', false, '93e86d1b-b57f-42ea-b291-9e7e6189867e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c56b6ee-0dd0-4ceb-9d32-671db4560af1', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9c590a5-cc85-4abf-af35-50c38d52d826', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3c56b6ee-0dd0-4ceb-9d32-671db4560af1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cbbdb6e-1a29-4335-a655-8706accdbcbe', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '3c56b6ee-0dd0-4ceb-9d32-671db4560af1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4ec2d79-27bf-476a-b159-646f5ded57a6', '(A) is true, but (R) is false.', false, '3c56b6ee-0dd0-4ceb-9d32-671db4560af1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67574304-0d34-4db8-b79a-cc8c9924e479', '(A) is false, but (R) is true.', false, '3c56b6ee-0dd0-4ceb-9d32-671db4560af1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72164254-eebb-44d5-93eb-3899b6f425c5', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Spot the IMPOSTER in the following group of early medieval dynasties matched with their core geographical heartlands:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c06c0d3f-68b0-4176-b5d2-86553a676743', 'Match 1', false, '72164254-eebb-44d5-93eb-3899b6f425c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b13ca707-e5f4-444c-a9f8-cd8be9d30a2b', 'Match 2', false, '72164254-eebb-44d5-93eb-3899b6f425c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d40b242-7aa8-4e3c-b0c9-cbd1e952d46b', 'Match 3', false, '72164254-eebb-44d5-93eb-3899b6f425c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7a35e80-2e71-40c3-88bd-7daec056283a', 'Match 4 (Cholas ruled the Kaveri Delta and Tamil Country in South India, NOT Punjab/Kashmir)', true, '72164254-eebb-44d5-93eb-3899b6f425c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ba97863-c03b-49d7-a5fb-1e07d956d21e', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Analyze the ''Lost-Wax Technique'' (Cire Perdue) perfected by Chola master bronze craftsmen:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38cf1594-90c7-4244-af0f-16ec0d19bb66', 'Sculpt a detailed beeswax model -> coat with fine clay & dry -> heat to melt and drain wax out through a hole -> pour molten bronze into the hollow clay mold -> cool and break clay casing to polish the bronze statue', true, '0ba97863-c03b-49d7-a5fb-1e07d956d21e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6bcbeee-40cc-4556-9a03-9650a94b2368', 'Carve bronze with a hammer directly from stone', false, '0ba97863-c03b-49d7-a5fb-1e07d956d21e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cb151ea-745d-43fa-8292-db339281d569', 'Pour cold water on hot copper sheets', false, '0ba97863-c03b-49d7-a5fb-1e07d956d21e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d8096a6-5c8e-48d2-a24a-d5b1bcc18823', 'Dip wooden statues into gold paint', false, '0ba97863-c03b-49d7-a5fb-1e07d956d21e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bba7021-6768-4abe-ad5e-e6be90b02ff0', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Match Column I (Chola Land Terms) with Column II (Exact Definitions from Inscriptions):
(a) Vellanvagai    -> (i) Land of non-Brahmana peasant proprietors
(b) Brahmadeya      -> (ii) Land gifted to Brahmanas
(c) Shalabhoga      -> (iii) Land for the maintenance of a school
(d) Pallichchhandam -> (iv) Land donated to Jaina institutions', 'Vellanvagai = peasant land; Brahmadeya = Brahmana grant; Shalabhoga = school; Pallichchhandam = Jain grant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd7f9069-da09-4c1c-9839-429562f5dcdb', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '0bba7021-6768-4abe-ad5e-e6be90b02ff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4636691e-2db7-40f9-9777-aeee9d358992', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '0bba7021-6768-4abe-ad5e-e6be90b02ff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de72f197-5b88-4e23-afef-a08ccea4206e', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '0bba7021-6768-4abe-ad5e-e6be90b02ff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d880ee35-c473-4c66-ae42-2840002a0660', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '0bba7021-6768-4abe-ad5e-e6be90b02ff0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c79ad25-df85-4fe7-b3df-4ccefce65e95', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Read the statements regarding the Battle of Tarain:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29c4bc87-38dc-42a0-84a0-22e766d88fa5', 'Statements 1 and 2 only', true, '8c79ad25-df85-4fe7-b3df-4ccefce65e95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('230012e5-3079-4604-8aa3-70a3ba605ccd', 'Statements 2 and 3 only', false, '8c79ad25-df85-4fe7-b3df-4ccefce65e95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be64bd5a-48e2-4f71-a6ab-c668448c6e6b', 'Statements 1 and 3 only', false, '8c79ad25-df85-4fe7-b3df-4ccefce65e95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a8ed3be-eeee-48f3-933c-be0104acec6a', 'All Statements 1, 2, and 3', false, '8c79ad25-df85-4fe7-b3df-4ccefce65e95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecbd8b32-785e-4392-8250-b8b8d3857931', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Why did medieval kings deliberately build colossal, soaring stone temples and adorn them with lavish gold and jewel endowments?', 'Monumental temple patronage legitimized royal sovereignty, embodying divine kingship and cementing fiscal-agrarian hegemony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c2e1936-fbeb-4121-b19a-c6195b5418b9', 'To proclaim their supreme wealth, imperial power, piety, and divine sanction, while creating economic patronage networks with local elites', true, 'ecbd8b32-785e-4392-8250-b8b8d3857931');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c930b649-fa05-46be-aec3-990ad9a9c662', 'Because temples were used as prisons for soldiers', false, 'ecbd8b32-785e-4392-8250-b8b8d3857931');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eef2d41e-c9f8-4e8e-8ec4-bb758bb35e48', 'Because stone was the only building material available', false, 'ecbd8b32-785e-4392-8250-b8b8d3857931');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1198923a-1945-4f9c-9d34-290b388a9151', 'To hide from invading foreign armies', false, 'ecbd8b32-785e-4392-8250-b8b8d3857931');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55ed77c5-9474-4bb3-818c-987e5ddc0a4d', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'How did the Chola navy under Rajaraja I and Rajendra I achieve maritime hegemony across the Bay of Bengal (often called the ''Chola Lake'')?', 'Chola blue-water thalassocracy secured maritime trade networks across the Malacca Straits, trading with Song Dynasty China.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2c4fc1c-3306-4e27-8463-480e5711472d', 'They constructed a powerful high-seas naval fleet that conquered the Maldives, Sri Lanka, and launched maritime expeditions against the Srivijaya Empire (Sumatra/Malaysia) to protect strategic trade routes to China', true, '55ed77c5-9474-4bb3-818c-987e5ddc0a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f469356d-f0cb-4026-8b7d-af870a2a6f12', 'They hired European pirate ships', false, '55ed77c5-9474-4bb3-818c-987e5ddc0a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87fe2f6f-baca-420f-a5d9-39da3e3beee2', 'They built bridges across the entire ocean', false, '55ed77c5-9474-4bb3-818c-987e5ddc0a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3f90a3d-0338-4485-b8f6-17f736424262', 'They drained the Bay of Bengal', false, '55ed77c5-9474-4bb3-818c-987e5ddc0a4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d91bc02c-7de7-4006-bfb1-679b7a46af68', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'What democratic safeguard was enforced in the Uttaramerur Sabha election rules to prevent corruption, dynastic entrenchment, and power abuse?', 'Mandatory 3-year term limits and strict financial account auditing barred entrenched dynastic oligarchies in the Sabha.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('274256fc-97df-43bb-aa1a-77dd928d05a3', 'Anyone who had been a member of any committee for the past 3 years, or who had failed to submit full audited financial accounts of his past committee tenure, was STRICTLY DISQUALIFIED from contesting', true, 'd91bc02c-7de7-4006-bfb1-679b7a46af68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60792929-de1d-4b93-bd05-9eb3b8990b07', 'Candidates had to pay 100 gold coins to vote', false, 'd91bc02c-7de7-4006-bfb1-679b7a46af68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be35d7cf-5e72-4180-a140-895b93764955', 'Only the oldest man in the village could rule', false, 'd91bc02c-7de7-4006-bfb1-679b7a46af68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57d2af94-6e86-4cfe-93f5-ad30f76c852a', 'Votes were decided by sword fighting', false, 'd91bc02c-7de7-4006-bfb1-679b7a46af68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aea1734c-0727-48db-8e13-317c907cffbf', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Consider four prominent rulers of early medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6d86fc6-4b06-4720-92fd-9d012d87d256', 'Ruler 3 (Rajendra I Chola)', true, 'aea1734c-0727-48db-8e13-317c907cffbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d2d59ba-efcd-42ae-825d-7d09849e4cd6', 'Ruler 1', false, 'aea1734c-0727-48db-8e13-317c907cffbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4fc3bbe-72af-4f05-bc0e-3ebe27207c91', 'Ruler 2', false, 'aea1734c-0727-48db-8e13-317c907cffbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05421cc1-b73f-4847-ac48-49f1ddb478a1', 'Ruler 4', false, 'aea1734c-0727-48db-8e13-317c907cffbf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('833922fa-163f-452c-87f2-215ba224a9ca', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'What was the role of the ''Nagaram'' in the Chola imperial commercial economy?', 'Nagarams (like Ayyavole and Manigramam guilds) managed civic urban commerce, merchant law, and maritime emporiums.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20bb5fa8-b258-4d09-837e-f89e9c23eb5b', 'Merchant associations and trading guilds that maintained commercial markets, levied local trade tariffs, and performed municipal administrative functions in mercantile towns', true, '833922fa-163f-452c-87f2-215ba224a9ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25551230-0a5c-40e9-ac95-1fcc0603859d', 'Peasant farming assemblies in forests', false, '833922fa-163f-452c-87f2-215ba224a9ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2286567-a834-453b-9cea-ef69f93d7ad7', 'Assemblies of temple dancers only', false, '833922fa-163f-452c-87f2-215ba224a9ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c598d51-3d49-402c-9781-e0bc1b0bf87a', 'The King''s personal bodyguard unit', false, '833922fa-163f-452c-87f2-215ba224a9ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0920c69e-5b98-4e45-b813-6c087ad3cd84', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Why is the 9th–12th century Chola administration celebrated by modern political scientists as a pioneer of ''Decentralized Grassroots Democracy''?', 'The Chola state balanced centralized imperial thalassocracy with highly autonomous, democratic village-level communal governance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('773e3857-6e2a-4a6b-aef9-39dcc7ae55c4', 'While maintaining an overarching imperial defense and foreign policy, local village assemblies (Urs and Sabhas) enjoyed complete self-governance, running committees for canals, dispute settlement, and local taxation', true, '0920c69e-5b98-4e45-b813-6c087ad3cd84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bbd2990-a091-4696-8e43-e610b988586d', 'Because the Cholas had no central king', false, '0920c69e-5b98-4e45-b813-6c087ad3cd84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf53d3d5-7851-4562-af5d-84e8bfdb8801', 'Because elections were held on modern electronic machines', false, '0920c69e-5b98-4e45-b813-6c087ad3cd84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6491e64-f021-41f8-af2e-a5b0762de54f', 'Because all land was owned by the British', false, '0920c69e-5b98-4e45-b813-6c087ad3cd84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba58b5de-770c-4baa-8bac-3d651a1eb21f', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'What master historical synthesis is established in Chapter 2 of NCERT Class 7 History?', 'Chapter 2 illuminates the rise of dynamic regional kingdoms, military statecraft, temple-centered urbanization, and grassroots rural democracy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6294600a-4991-4c60-9964-219c57aeb019', 'The transition from early feudal chieftains (Samantas) to powerful regional and pan-regional imperial dynasties, characterized by grand temple building, sophisticated hydraulic agrarian engineering, fine bronze arts, and self-governing local village institutions', true, 'ba58b5de-770c-4baa-8bac-3d651a1eb21f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d78993fd-6de0-4d9a-9756-386a57d1e5a1', 'A period of total darkness without any kings or art', false, 'ba58b5de-770c-4baa-8bac-3d651a1eb21f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a114882a-41ec-4416-ae07-ffce5a0b8f69', 'The complete destruction of all agriculture', false, 'ba58b5de-770c-4baa-8bac-3d651a1eb21f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7f9dc56-e32d-4c4c-93a1-3dc524e478da', 'The end of Indian history', false, 'ba58b5de-770c-4baa-8bac-3d651a1eb21f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35d40e0b-cc99-47c6-bcc4-982690063581', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'भाषा की वह सबसे छोटी मूल मौखिक या लिखित इकाई, जिसके और टुकड़े (खंड) नहीं किए जा सकते, उसे क्या कहते हैं?', 'वर्ण भाषा की सूक्ष्मतम अविभाज्य मूल ध्वनि-इकाई है (जैसे: अ, इ, क्, ख्)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9848a88-3165-47a4-9849-0d16dfaf9beb', 'वर्ण (या ध्वनि / Letter)', true, '35d40e0b-cc99-47c6-bcc4-982690063581');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6894bdf4-2b38-4906-9216-74937fb9d670', 'शब्द', false, '35d40e0b-cc99-47c6-bcc4-982690063581');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53cd738a-3879-4e12-af42-725eb8be70e9', 'वाक्य', false, '35d40e0b-cc99-47c6-bcc4-982690063581');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca9fc9ba-9cf5-4dd7-a780-4b171de820ab', 'पद', false, '35d40e0b-cc99-47c6-bcc4-982690063581');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f6a21d7-3ba0-458c-b5ba-43f8ae68ea71', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'किसी भाषा के वर्णों के व्यवस्थित, क्रमबद्ध और मानक समूह को क्या कहते हैं?', 'वर्णों के व्यवस्थित एवं प्रामाणिक समूह को ''वर्णमाला'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7576166-7b51-4d2f-b80f-def44e424d55', 'वर्णमाला (Alphabet)', true, '8f6a21d7-3ba0-458c-b5ba-43f8ae68ea71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e8f009e-0fb7-42d4-b86a-f48ad74c2d49', 'शब्दकोश', false, '8f6a21d7-3ba0-458c-b5ba-43f8ae68ea71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98d44b29-3cf1-4df2-b645-5cb68d60a253', 'व्याकरण', false, '8f6a21d7-3ba0-458c-b5ba-43f8ae68ea71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cace4ec2-bef3-49c5-b446-c8e78252dfc7', 'लिपि', false, '8f6a21d7-3ba0-458c-b5ba-43f8ae68ea71');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39c94cdd-c3f8-4a7c-8f76-a5a58cd895d7', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'हिंदी वर्णमाला में वर्णों को मुख्य रूप से कितने वर्गों/भेदों में बाँटा गया है?', 'वर्णों के दो मूल भेद हैं: स्वर (स्वतंत्र उच्चरित ध्वनियाँ) तथा व्यंजन (स्वरों की सहायता से उच्चरित ध्वनियाँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ead07276-fd15-4dfd-a6cb-75636eedc9bb', 'दो भेद (1. स्वर - Vowels, 2. व्यंजन - Consonants)', true, '39c94cdd-c3f8-4a7c-8f76-a5a58cd895d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e6ccbe9-3880-4292-8ee5-f070db56a476', 'चार भेद', false, '39c94cdd-c3f8-4a7c-8f76-a5a58cd895d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d38fd513-3bc4-45ba-a9f3-97d209b73246', 'तीन भेद', false, '39c94cdd-c3f8-4a7c-8f76-a5a58cd895d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebf4fd19-cc23-4f77-8a4f-4a457c18cf32', 'पाँच भेद', false, '39c94cdd-c3f8-4a7c-8f76-a5a58cd895d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9e321b2-a47b-4875-a10d-b5eb916ddee2', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'जिन वर्णों का उच्चारण बिना किसी अन्य वर्ण की सहायता के स्वतंत्र रूप से होता है, उन्हें क्या कहते हैं?', 'स्वतंत्र रूप से अबाध गति से उच्चरित ध्वनियाँ ''स्वर'' कहलाती हैं (हिंदी में कुल 11 स्वर हैं)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6b77eac-004e-482e-a960-59af5029bfe0', 'स्वर (Vowels)', true, 'c9e321b2-a47b-4875-a10d-b5eb916ddee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f144b97f-2aaa-4273-8f07-f3ab964d5aad', 'व्यंजन', false, 'c9e321b2-a47b-4875-a10d-b5eb916ddee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e30543a3-fb03-4ccc-ab22-6bc3fdb4685e', 'संयुक्त व्यंजन', false, 'c9e321b2-a47b-4875-a10d-b5eb916ddee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c03d6287-97eb-44c4-b6d9-ce5a8b7b326f', 'अयोगवाह', false, 'c9e321b2-a47b-4875-a10d-b5eb916ddee2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9ad289b-6b11-4ed5-a22c-e51d6f996606', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'हिंदी वर्णमाला में मानक स्वरों की कुल संख्या कितनी है?', 'हिंदी वर्णमाला में 11 मानक स्वर होते हैं (अं और अः को अयोगवाह माना जाता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('866dd5b1-6173-45d9-a653-a1d9db666112', '11 स्वर (अ, आ, इ, ई, उ, ऊ, ऋ, ए, ऐ, ओ, औ)', true, 'b9ad289b-6b11-4ed5-a22c-e51d6f996606');
