INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45df499c-c5ee-4f8f-9c02-2e07d05c4adf', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'जिन स्वरों के उच्चारण में सबसे कम समय (एक मात्रा का समय) लगता है, उन्हें क्या कहते हैं?', 'एकमात्रिक मूल स्वर ''ह्रस्व स्वर'' कहलाते हैं (अ, इ, उ, ऋ - कुल 4)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('459de757-ebcc-4ce1-9441-78bc8deb01d6', 'ह्रस्व स्वर (Short Vowels : अ, इ, उ, ऋ)', true, '45df499c-c5ee-4f8f-9c02-2e07d05c4adf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a72d9300-ebd6-4e8e-a548-bebb039f9e7f', 'दीर्घ स्वर', false, '45df499c-c5ee-4f8f-9c02-2e07d05c4adf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13f57781-ea96-4a42-ba1b-52f1bfc206c0', 'प्लुत स्वर', false, '45df499c-c5ee-4f8f-9c02-2e07d05c4adf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee35a884-baff-4e3d-aeac-3103e9f339b0', 'संयुक्त स्वर', false, '45df499c-c5ee-4f8f-9c02-2e07d05c4adf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f725b17b-d400-423b-8d28-a2906d451a2e', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'जिन स्वरों के उच्चारण में ह्रस्व स्वर से दोगुना समय (दो मात्राओं का समय) लगता है, उन्हें क्या कहते हैं?', 'द्विमात्रिक स्वर ''दीर्घ स्वर'' कहलाते हैं (कुल 7 स्वर)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfad32fe-fb12-4fc4-bb0e-92f164a44f49', 'दीर्घ स्वर (Long Vowels : आ, ई, ऊ, ए, ऐ, ओ, औ)', true, 'f725b17b-d400-423b-8d28-a2906d451a2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e686bbf-c6e8-4fb2-a18e-3022b070a667', 'ह्रस्व स्वर', false, 'f725b17b-d400-423b-8d28-a2906d451a2e');
