INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3130da-f6f7-4410-8791-8978296626a3', 'अयोगवाह', false, 'f725b17b-d400-423b-8d28-a2906d451a2e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e548e7a1-7b1f-4ecb-b122-c3ec8cf56ad4', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'जिन वर्णों का उच्चारण स्वरों की सहायता के बिना नहीं किया जा सकता, उन्हें क्या कहते हैं?', 'स्वरों की सहायता से बोले जाने वाले वर्ण ''व्यंजन'' कहलाते हैं (प्रत्येक व्यंजन में ''अ'' स्वर अंतर्निहित होता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74600cc6-d703-46ca-a2d8-52bc314392e3', 'व्यंजन (Consonants)', true, 'e548e7a1-7b1f-4ecb-b122-c3ec8cf56ad4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2fb1193-b206-43ea-aea5-03852e32e12c', 'स्वर', false, 'e548e7a1-7b1f-4ecb-b122-c3ec8cf56ad4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7ef8b0b-fded-43a8-b5e3-9e365dd45bb1', 'अनुस्वार', false, 'e548e7a1-7b1f-4ecb-b122-c3ec8cf56ad4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('579a10f9-0828-4e31-8edd-ad33e3581883', 'विसर्ग', false, 'e548e7a1-7b1f-4ecb-b122-c3ec8cf56ad4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21015b70-da1f-4001-8d92-785d602d6fb7', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'हिंदी वर्णमाला में स्पर्श व्यंजनों (क-वर्ग से प-वर्ग तक) की कुल संख्या कितनी है?', 'कवर्ग, चवर्ग, टवर्ग, तवर्ग और पवर्ग में 5-5 वर्ण मिलकर कुल 25 ''स्पर्श व्यंजन'' बनाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a13e7f9-1b20-4350-af41-8fb936aab80d', '25 व्यंजन (5 वर्ग × 5 वर्ण = 25)', true, '21015b70-da1f-4001-8d92-785d602d6fb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('728cc8a4-b94a-4362-97cd-c1f822bc32af', '33', false, '21015b70-da1f-4001-8d92-785d602d6fb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d06f7ce-c2e7-42ea-976a-83510516bec8', '11', false, '21015b70-da1f-4001-8d92-785d602d6fb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f600de3-864a-461f-bdf4-824c3e36db4f', '4', false, '21015b70-da1f-4001-8d92-785d602d6fb7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0244d977-5a9e-4455-85f5-7e13be59b9e3', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'हिंदी में ''क्ष, त्र, ज्ञ, श्र'' वर्णों को किस श्रेणी में रखा जाता है?', 'दो भिन्न व्यंजनों के संयोग से बने वर्ण ''संयुक्त व्यंजन'' हैं (क्+ष्=क्ष, त्+र्=त्र, ज्+ञ्=ज्ञ, श्+र्=श्र)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43f23333-c450-45e9-8df3-20d5c017ff2f', 'संयुक्त व्यंजन (Compound Consonants)', true, '0244d977-5a9e-4455-85f5-7e13be59b9e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dd95c26-772b-4757-aefa-6669071c1a0e', 'स्पर्श व्यंजन', false, '0244d977-5a9e-4455-85f5-7e13be59b9e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39d42b92-60dd-43bc-9765-725116094406', 'अंतःस्थ व्यंजन', false, '0244d977-5a9e-4455-85f5-7e13be59b9e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cc7cd5c-6c27-40b1-ad2c-244151e90f3c', 'ऊष्म व्यंजन', false, '0244d977-5a9e-4455-85f5-7e13be59b9e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fcbf0fc-58f2-45ca-beda-fb4ee451a4f5', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'शिरोरेखा के ऊपर बिंदु (ं) के रूप में प्रयुक्त होने वाले नासिक्य चिह्न को व्याकरण में क्या कहते हैं?', 'पंचम वर्ण के स्थान पर प्रयुक्त बिंदु प्रतीक ''अनुस्वार'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf82dbb9-6f87-4b79-8007-e46288658e50', 'अनुस्वार (Anusvara - जैसे: गंगा, चंचल, पतंग)', true, '6fcbf0fc-58f2-45ca-beda-fb4ee451a4f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('766fe9d8-fc37-4c1a-b2ea-05b3f581d7f9', 'अनुनासिक (चन्द्रबिन्दु)', false, '6fcbf0fc-58f2-45ca-beda-fb4ee451a4f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64fadfc5-9330-4c7b-a867-1991b85de4b9', 'विसर्ग', false, '6fcbf0fc-58f2-45ca-beda-fb4ee451a4f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffafd426-04d5-46a6-97e7-77322540b1d2', 'हलंत', false, '6fcbf0fc-58f2-45ca-beda-fb4ee451a4f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e222768-0f11-4987-9779-f0cf8f802504', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'शिरोरेखा के ऊपर चन्द्रबिन्दु (ँ) के रूप में प्रयुक्त होने वाले ध्वनि चिह्न (जिसका उच्चारण मुख और नाक दोनों से होता है) को क्या कहते हैं?', 'मुख और नासिका दोनों के संयुक्त वायु-प्रवाह से उच्चरित स्वर ''अनुनासिक'' (चन्द्रबिन्दु ँ) कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aff1364-6cfe-49ce-b8eb-6368ebe7816e', 'अनुनासिक (Anunasika - जैसे: चाँद, आँख, गाँव)', true, '2e222768-0f11-4987-9779-f0cf8f802504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f79a576a-8c86-4fa9-b9fa-b7c36277c9b2', 'अनुस्वार', false, '2e222768-0f11-4987-9779-f0cf8f802504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d4e5b09-2749-4efe-a6a8-46818959e646', 'विसर्ग', false, '2e222768-0f11-4987-9779-f0cf8f802504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bb096ad-4d21-4809-8609-e880cc2f724a', 'नुक्ता', false, '2e222768-0f11-4987-9779-f0cf8f802504');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf1a8daf-70b9-4846-a472-b875ed8bdfd8', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'अंतःस्थ व्यंजन (Semi-vowels) के अंतर्गत कौन-से चार वर्ण आते हैं?', 'स्वर और व्यंजन के मध्य स्थित वायु-प्रवाह वाले वर्ण ''य, र, ल, व'' अंतःस्थ व्यंजन कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('470677d5-6211-46b3-95e7-d45e60d5a065', 'य, र, ल, व (Y, R, L, V)', true, 'bf1a8daf-70b9-4846-a472-b875ed8bdfd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30d07ea3-c216-4f82-8914-10af6e683ea2', 'श, ष, स, ह', false, 'bf1a8daf-70b9-4846-a472-b875ed8bdfd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47399494-4c78-473b-bd53-6d5b2d41c22c', 'क, ख, ग, घ', false, 'bf1a8daf-70b9-4846-a472-b875ed8bdfd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df879188-1913-462e-ab90-1dd4cc52e026', 'च, छ, ज, झ', false, 'bf1a8daf-70b9-4846-a472-b875ed8bdfd8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a7024a2-cb25-46aa-94a0-fcc7ceae5f9c', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'ऊष्म व्यंजन (Sibilants / Fricatives) के अंतर्गत कौन-से चार वर्ण आते हैं जिनके उच्चारण में मुख से रगड़ खाकर गर्म वायु निकलती है?', 'उच्चारण घर्षण से ऊष्मा उत्पन्न करने वाले वर्ण ''श, ष, स, ह'' ऊष्म व्यंजन कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e25ab0b-ff45-41c6-a261-a6f1fe53085c', 'श, ष, स, ह (Sh, Sh, S, H)', true, '7a7024a2-cb25-46aa-94a0-fcc7ceae5f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9c7cbbb-2f64-4f1f-80f3-8ba819e9df52', 'य, र, ल, व', false, '7a7024a2-cb25-46aa-94a0-fcc7ceae5f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d82016f9-d872-40fb-ad59-ccabc4cc2f82', 'क्ष, त्र, ज्ञ, श्र', false, '7a7024a2-cb25-46aa-94a0-fcc7ceae5f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcf20476-24aa-4e1a-afd6-dca3039dc286', 'ट, ठ, ड, ढ', false, '7a7024a2-cb25-46aa-94a0-fcc7ceae5f9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14c5d9ad-8ded-49fe-9eae-1002c2f94402', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''क, ख, ग, घ, ङ'' और स्वर ''अ, आ'' का उच्चारण मुख के किस स्थान से होता है?', 'कंठ (गले) से उच्चरित होने वाली ध्वनियाँ ''कंठ्य'' कहलाती हैं (अकुहविसर्जनीयानां कण्ठः)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d3c1dd7-6eaa-4622-82f8-8eeb0af3cd42', 'कंठ से (कंठ्य ध्वनियाँ / Velar)', true, '14c5d9ad-8ded-49fe-9eae-1002c2f94402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88a898c7-108c-43b9-8462-e89d4686dfdc', 'तालु से (तालव्य)', false, '14c5d9ad-8ded-49fe-9eae-1002c2f94402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9698971-50d6-4c45-982b-9f7f19e72ed4', 'मूर्धा से (मूर्धन्य)', false, '14c5d9ad-8ded-49fe-9eae-1002c2f94402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('916f919f-703e-4734-8b9e-c5197439045b', 'दाँतों से (दंत्य)', false, '14c5d9ad-8ded-49fe-9eae-1002c2f94402');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a39b2d55-b0da-4567-94a1-4e92ce31bb65', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''च, छ, ज, झ, ञ'' और स्वर ''इ, ई'' तथा ''य, श'' का उच्चारण स्थान क्या है?', 'जिह्वा के तालु स्पर्श से उच्चरित ध्वनियाँ ''तालव्य'' कहलाती हैं (इचुयशानां तालु)।', NOW()) ON CONFLICT DO NOTHING;
