INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ca145dc-f3aa-4249-9ba8-108d56a98e09', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''ट, ठ, ड, ढ, ण'' और स्वर ''ऋ'' तथा ''र, ष'' का उच्चारण स्थान क्या है?', 'मूर्धा (कठोर तालु के अग्र भाग) से उच्चरित ध्वनियाँ ''मूर्धन्य'' कहलाती हैं (ऋटुरषाणां मूर्धा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37ab9bc7-9e92-4ad4-ae9b-feebf43980de', 'मूर्धा (मूर्धन्य ध्वनियाँ / Retroflex)', true, '6ca145dc-f3aa-4249-9ba8-108d56a98e09');
