INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d2fe560-393b-4eeb-921e-d4b8fc85d200', 'कंठ', false, '6ca145dc-f3aa-4249-9ba8-108d56a98e09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd1aab8f-78f6-4b4e-856f-f72ac08fa3f6', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''त, थ, द, ध, न'' और ''ल, स'' का उच्चारण स्थान क्या है?', 'जिह्वा के दाँतों के स्पर्श से उच्चरित ध्वनियाँ ''दंत्य'' कहलाती हैं (लृतुलसानां दन्ताः)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44bee28d-9059-45aa-bcbc-c2764fb054b5', 'दाँत (दंत्य ध्वनियाँ / Dental)', true, 'bd1aab8f-78f6-4b4e-856f-f72ac08fa3f6');
