INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55cd75be-fe30-461d-ae85-9d3d730a0b5c', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''प, फ, ब, भ, म'' और स्वर ''उ, ऊ'' का उच्चारण स्थान क्या है?', 'दोनों ओष्ठों के परस्पर संसर्ग से उच्चरित ध्वनियाँ ''ओष्ठ्य'' कहलाती हैं (उपूपध्मानीयानामोष्ठौ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e677c15-85a3-45c0-b432-cdfe062064e5', 'दोनों होंठ (ओष्ठ्य ध्वनियाँ / Labial)', true, '55cd75be-fe30-461d-ae85-9d3d730a0b5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32504315-77bb-4547-a296-ee00dd9d9a3c', 'दाँत', false, '55cd75be-fe30-461d-ae85-9d3d730a0b5c');
