INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68927821-1e43-4734-85e3-ce7182720fc3', 'तालु', false, '55cd75be-fe30-461d-ae85-9d3d730a0b5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc09d4e1-2bd5-4e48-abd0-259892e3ff58', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'जब एक ही व्यंजन ध्वनि दो बार लगातार संयुक्त होकर आए (पहला स्वर-रहित और दूसरा स्वर-सहित, जैसे: ''पक्का'', ''दिल्ली'', ''बच्चा'', ''सच्चा''), तब उसे क्या कहते हैं?', 'समान व्यंजन का स्वररहित और स्वरसहित युग्म ''द्वित्व व्यंजन'' कहलाता है (क्+क = क्क, ल्+ल = ल्ल)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('964db06a-c4ff-4fc4-848c-7ef41efd7a77', 'द्वित्व व्यंजन (Geminate Consonants)', true, 'fc09d4e1-2bd5-4e48-abd0-259892e3ff58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f77d6d2c-9c2a-47a9-8e03-1fe44d31f989', 'संयुक्त व्यंजन', false, 'fc09d4e1-2bd5-4e48-abd0-259892e3ff58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b51f48db-6cbd-48b0-8e6f-63477a554443', 'स्पर्श व्यंजन', false, 'fc09d4e1-2bd5-4e48-abd0-259892e3ff58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbde6fd0-8aa1-4406-91d8-165835c77e4d', 'अयोगवाह', false, 'fc09d4e1-2bd5-4e48-abd0-259892e3ff58');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ded401b-f8de-4f12-a9e1-ebf22286b81f', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''ज्ञ'' संयुक्त व्यंजन किन दो वर्णों के शुद्ध संयोग से बनता है?', '''ज्ञ'' वर्ण का मानक व्याकरणिक निर्माण ''ज्'' और ''ञ्'' के योग से होता है (ज् + ञ् = ज्ञ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08854a21-36cb-4c95-8cc5-4b040cfe9873', 'ज् + ञ् + अ (J + Nya)', true, '9ded401b-f8de-4f12-a9e1-ebf22286b81f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f72f71b-2a80-4006-9264-7ee600bec048', 'ग् + य् + अ', false, '9ded401b-f8de-4f12-a9e1-ebf22286b81f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19eaf286-6c0c-43d6-a604-abfe7144be56', 'ज् + य् + अ', false, '9ded401b-f8de-4f12-a9e1-ebf22286b81f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd21fd42-198a-46d5-a629-0626bcc0bafd', 'द् + य् + अ', false, '9ded401b-f8de-4f12-a9e1-ebf22286b81f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34a5806b-f134-4a79-86b8-683681a2f274', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''श्र'' संयुक्त व्यंजन किन दो वर्णों के संयोग से बनता है?', '''श्र'' वर्ण का निर्माण तालव्य ''श्'' और ''र्'' के मेल से होता है (श् + र् = श्र, जैसे: श्री, श्रम)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1ea3ab4-04e6-423d-a83b-1034b3da5565', 'श् + र् + अ (Sh + R)', true, '34a5806b-f134-4a79-86b8-683681a2f274');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7df4e92f-5e26-4e8e-a6be-bc4437f8f821', 'ष् + र् + अ', false, '34a5806b-f134-4a79-86b8-683681a2f274');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('171ccf87-54be-40bb-93f9-4d75c4579f9e', 'स् + र् + अ', false, '34a5806b-f134-4a79-86b8-683681a2f274');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e684f287-29b3-4601-b58b-d655eb18383c', 'छ् + र् + अ', false, '34a5806b-f134-4a79-86b8-683681a2f274');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad9cfca1-7eba-4b1e-a8d2-39d29914a3a6', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''उद्यान'' शब्द का शुद्ध वर्ण-विच्छेद क्या होगा?', 'उ + द् + य् + आ + न् + अ = उद्यान (द्+य् = द्य)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f74e5c16-ef72-42e1-b999-3a2f0046840d', 'उ + द् + य् + आ + न् + अ', true, 'ad9cfca1-7eba-4b1e-a8d2-39d29914a3a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('819ea3ee-bf17-48c6-a0da-935f08c9ea6c', 'उ + द् + आ + य् + न् + अ', false, 'ad9cfca1-7eba-4b1e-a8d2-39d29914a3a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d60608c-51d9-4464-866a-950fb7dda202', 'उद् + या + न', false, 'ad9cfca1-7eba-4b1e-a8d2-39d29914a3a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fcb5006-c1ec-4ed2-a8f5-5bf6b0b3ef79', 'उ + द्या + न् + अ', false, 'ad9cfca1-7eba-4b1e-a8d2-39d29914a3a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adeb4b3c-c503-4706-92f2-3bd282f5d027', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''कृपा'' शब्द का शुद्ध वर्ण-विच्छेद क्या होगा?', 'क व्यंजन में ''ऋ'' स्वर की मात्रा + प् + आ = क् + ऋ + प् + आ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d47c7d2-043f-407c-9f9d-645166d1d943', 'क् + ऋ + प् + आ', true, 'adeb4b3c-c503-4706-92f2-3bd282f5d027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc1db758-97e5-44dd-81be-943dcf5729cc', 'क् + र् + इ + प् + आ', false, 'adeb4b3c-c503-4706-92f2-3bd282f5d027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb20b879-29ce-4d02-9e26-383c130025b1', 'क् + ऋ + पा', false, 'adeb4b3c-c503-4706-92f2-3bd282f5d027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2d07d2c-f913-4ef3-a03a-c2a2d50092f4', 'कृ + प् + आ', false, 'adeb4b3c-c503-4706-92f2-3bd282f5d027');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('826eef2e-f021-486f-94c5-b879b6e42ede', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'उर्दू, अरबी, फ़ारसी तथा अंग्रेज़ी से हिंदी में आए विदेशी शब्दों के शुद्ध उच्चारण हेतु वर्णों के नीचे लगाए जाने वाले बिंदु (जैसे: ज़, फ़, क़, ख़, ग़) को क्या कहते हैं?', 'आगत ध्वनियों के तल में लगने वाला लघु बिंदु ''नुक्ता'' कहलाता है (जैसे: ज़मीन, फ़िल्म)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2dc4ca-4860-41af-bc5f-62ac433de507', 'नुक्ता (Nukta)', true, '826eef2e-f021-486f-94c5-b879b6e42ede');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b9b13f1-0bb3-436f-a7a6-dfc8daa99c4d', 'अनुस्वार', false, '826eef2e-f021-486f-94c5-b879b6e42ede');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f958da20-f680-4bef-b5a9-a52db875153f', 'विसर्ग', false, '826eef2e-f021-486f-94c5-b879b6e42ede');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4b4b2e4-4dd4-4758-97c7-78952340d241', 'हलंत', false, '826eef2e-f021-486f-94c5-b879b6e42ede');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b6ee23d-7e75-449c-a886-55604ff99c99', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'अयोगवाह (Ayogavaha) किन्हें कहा जाता है, जो न तो पूर्ण स्वर होते हैं और न पूर्ण व्यंजन?', 'जो योग न होने पर भी साथ वहन करें, वे ''अयोगवाह'' कहलाते हैं (अनुस्वार अं तथा विसर्ग अः)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a5ba365-632a-4352-9558-fb01fad3b1c4', 'अनुस्वार (अं) और विसर्ग (अः)', true, '1b6ee23d-7e75-449c-a886-55604ff99c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0d11928-d40f-44ad-a6db-66263efdee14', 'क्ष और त्र', false, '1b6ee23d-7e75-449c-a886-55604ff99c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4732c38c-9135-4996-a6d7-1b6f9fb3683e', 'य और र', false, '1b6ee23d-7e75-449c-a886-55604ff99c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94e21eab-bf6c-4cc7-9b52-cad348880704', 'ड और ढ', false, '1b6ee23d-7e75-449c-a886-55604ff99c99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aca5f0c8-a1d8-4ab9-bdc9-e3522b9b8cbb', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''र्'' के विभिन्न रूपों में ''पर्वत'' और ''कर्म'' में प्रयुक्त शिरोरेखा के ऊपर लगने वाले ''र्'' के रूप को क्या कहते हैं?', 'स्वररहित ''र्'' जब अगले व्यंजन के ऊपर शिरोरेखा पर बैठता है, तो उसे ''रेफ़'' कहते हैं (प्+अ+र्+व्+अ+त्+अ = पर्वत)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0cba84b-c665-4e37-8223-86bb9a843241', 'रेफ़ (Reph - स्वर रहित र्)', true, 'aca5f0c8-a1d8-4ab9-bdc9-e3522b9b8cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a747e3f-173a-4d2b-9ce7-f2c0594b3610', 'पदेन', false, 'aca5f0c8-a1d8-4ab9-bdc9-e3522b9b8cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e880df0e-01ef-4b61-ace3-9571f1266baf', 'ऋ की मात्रा', false, 'aca5f0c8-a1d8-4ab9-bdc9-e3522b9b8cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('738e9a31-a5ac-4eb1-865f-a3de0c3584c9', 'हलंत', false, 'aca5f0c8-a1d8-4ab9-bdc9-e3522b9b8cbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1346a82-8cf3-413f-b361-7043850fe578', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''क्रम'' और ''प्रकाश'' में व्यंजन के पैरों में लगने वाले ''र्'' के रूप को क्या कहते हैं?', 'स्वरसहित ''र्'' जब पूर्ववर्ती स्वररहित व्यंजन के चरण में जुड़ता है, तो उसे ''पदेन'' कहते हैं (क्+र् = क्र)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2001f6f1-5c42-41af-9fa3-0008cf38d70c', 'पदेन (Paden - स्वर सहित र्)', true, 'f1346a82-8cf3-413f-b361-7043850fe578');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06f69df2-8b92-4f48-b2b4-98fbf4108ea6', 'रेफ़', false, 'f1346a82-8cf3-413f-b361-7043850fe578');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6609a750-7265-4ecc-9c49-9b5b7e4ad23b', 'अनुस्वार', false, 'f1346a82-8cf3-413f-b361-7043850fe578');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73295a58-bb96-4ced-a10c-9cc3d614cdc3', 'विसर्ग', false, 'f1346a82-8cf3-413f-b361-7043850fe578');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a51acdd5-b608-4dd4-abfd-864266c1bb14', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f400c20-78ed-48d5-9f80-4f33cb66df43', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'a51acdd5-b608-4dd4-abfd-864266c1bb14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad4d8c53-d7a0-4cca-bf0b-76c550c161bb', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'a51acdd5-b608-4dd4-abfd-864266c1bb14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('632d9294-4e8b-41e0-931c-06b274caddce', '(A) सही है, परन्तु (R) गलत है।', false, 'a51acdd5-b608-4dd4-abfd-864266c1bb14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4f16b1a-33f2-47f2-9a36-650a7f2ebe4a', '(A) गलत है, परन्तु (R) सही है।', false, 'a51acdd5-b608-4dd4-abfd-864266c1bb14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0405702f-4a46-4969-825e-4df5ebfabfa7', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'Spot the IMPOSTER in the following group of वर्ण और उनके उच्चारण स्थानों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bf45ea7-d15a-4c82-a4fd-3f2c25f1828f', 'क - कंठ्य', false, '0405702f-4a46-4969-825e-4df5ebfabfa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43b8881d-8b5b-49bc-82af-f8f6f4dcf933', 'च - तालव्य', false, '0405702f-4a46-4969-825e-4df5ebfabfa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c2c54a7-5143-4fa9-aab2-865eaf283072', 'त - दंत्य', false, '0405702f-4a46-4969-825e-4df5ebfabfa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ab99834-6bcf-4c63-8d84-def3dc0bd226', 'प - मूर्धन्य (प वर्ग ओष्ठ्य ध्वनियाँ हैं, मूर्धन्य नहीं)', true, '0405702f-4a46-4969-825e-4df5ebfabfa7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68a17538-b22a-40f9-89c5-08e832a0eda2', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'सुमेलित कीजिए (वर्ण-विच्छेद और उनके शुद्ध मानक शब्द):
(क) क् + ष् + अ + त् + र् + इ + य् + अ -> (i) क्षत्रिय
(ख) श् + र् + ऋ + ङ् + ग् + आ + र् + अ -> (ii) शृंगार
(ग) द् + व् + आ + र् + इ + क् + आ     -> (iii) द्वारिका / द्वारका
(घ) व् + इ + ज् + ञ् + आ + न् + अ     -> (iv) विज्ञान', 'क्+ष् = क्ष; श्+ऋ = शृ (शृंगार); द्+व् = द्व; ज्+ञ् = ज्ञ (विज्ञान)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22a3006e-803d-4a13-987a-9721dc310242', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '68a17538-b22a-40f9-89c5-08e832a0eda2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e66095a-1345-48f3-a47c-db8bb5f23ec9', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '68a17538-b22a-40f9-89c5-08e832a0eda2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d818b1d2-2ad3-4717-a8e0-d0d788cb8831', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '68a17538-b22a-40f9-89c5-08e832a0eda2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4068fe71-bfa9-427e-8f06-527eea67f0af', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '68a17538-b22a-40f9-89c5-08e832a0eda2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5b4bcf7-a5b6-48e8-9ba5-a864ce9f341e', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', '''शृंगार'' शब्द की मानक शुद्ध वर्तनी और वर्ण संरचना क्या है?', 'मानक वर्तनी: ''श्'' में ''ऋ'' जुड़ने पर ''शृ'' बनता है; ''श्रृ'' अशुद्ध द्वित्व दोष है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc81c8df-380a-4953-847d-c237d5a3e323', '''शृंगार'' (तालव्य ''श्'' में स्वर ''ऋ'' की मात्रा जुड़ने पर ''शृ'' बनता है ; इसमें ''र'' का पदेन नहीं लगता)', true, 'a5b4bcf7-a5b6-48e8-9ba5-a864ce9f341e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6a91e4d-66b2-4957-8f63-428397fcd012', '''श्रृंगार'' (अशुद्ध रूप जिसमें श् + र् + ऋ दो बार र् लगा दिया जाता है)', false, 'a5b4bcf7-a5b6-48e8-9ba5-a864ce9f341e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0d64072-9131-4c5c-9bf8-b5212d66c6f7', '''सिंगार''', false, 'a5b4bcf7-a5b6-48e8-9ba5-a864ce9f341e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('052abed3-0f21-4968-95ef-ac847db3e316', '''श्रिंगार''', false, 'a5b4bcf7-a5b6-48e8-9ba5-a864ce9f341e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('646117b6-504d-479d-9d14-974f722509a0', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'अल्पप्राण (Unaspirated) और महाप्राण (Aspirated) व्यंजनों में क्या वैज्ञानिक अंतर होता है?', 'अल्पप्राण (क, ग, ङ / 1,3,5) में न्यूनतम वायु-प्रक्षेप; महाप्राण (ख, घ / 2,4) में सघोष हकार ध्वनि का विमोचन होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e85dcc0-7420-435b-8c8d-b5f247165225', 'अल्पप्राण के उच्चारण में मुख से कम श्वास-वायु निकलती है (प्रत्येक वर्ग का 1, 3, 5 वर्ण) ; जबकि महाप्राण के उच्चारण में ''ह'' जैसी भारी श्वास-वायु निकलती है (प्रत्येक वर्ग का 2 और 4 वर्ण)', true, '646117b6-504d-479d-9d14-974f722509a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('511a2554-5c62-4cf9-9c8b-8189cacce901', 'अल्पप्राण केवल स्वर होते हैं', false, '646117b6-504d-479d-9d14-974f722509a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54dac9ff-9acc-4503-af40-dc7a11409094', 'महाप्राण केवल विसर्ग में होते हैं', false, '646117b6-504d-479d-9d14-974f722509a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('058eb014-3d72-4639-818c-43aeba31186d', 'दोनों में कोई अंतर नहीं है', false, '646117b6-504d-479d-9d14-974f722509a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45e15d7c-2817-4659-936f-f6a6fbc036cf', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'घोष (सघोष / Voiced) और अघोष (Voiceless) ध्वनियों में स्वर-तंत्रियों (Vocal Cords) का क्या कार्य होता है?', 'सघोष में स्वरतंत्री का ध्वनिक कंपन (3,4,5 + स्वर); अघोष में कंपन का अभाव (1,2 + श,ष,स)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0f1d00d-7ed1-476f-a688-e97960e9d022', 'घोष ध्वनियों के उच्चारण में स्वर-तंत्रियों में कंपन (Ghosha) होता है (वर्गों के 3, 4, 5 वर्ण + सभी स्वर) ; जबकि अघोष ध्वनियों में स्वर-तंत्रियों में कंपन नहीं होता (वर्गों के 1 और 2 वर्ण + श, ष, स)', true, '45e15d7c-2817-4659-936f-f6a6fbc036cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8d65624-5fe8-4694-bb47-e6c0f8ca8bd1', 'अघोष ध्वनियाँ केवल कानों में सुनाई देती हैं', false, '45e15d7c-2817-4659-936f-f6a6fbc036cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bc0b600-3992-4383-9fad-5d831055bd45', 'घोष ध्वनियाँ केवल गाई जाती हैं', false, '45e15d7c-2817-4659-936f-f6a6fbc036cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07ddeb58-e619-4450-b699-ab622dda6bf9', 'स्वर-तंत्रियों का ध्वनि से कोई संबंध नहीं है', false, '45e15d7c-2817-4659-936f-f6a6fbc036cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e8c72e3-991c-4ea0-9719-26d297d35f76', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'उच्छिप्त (तातंजात / Flap) व्यंजन किन्हें कहा जाता है जिनके उच्चारण में जिह्वा मूर्धा को छूकर झटके से नीचे गिरती है?', '''ड़'' और ''ढ़'' उच्छिप्त व्यंजन हैं जो कभी किसी शब्द के आरंभ में प्रयुक्त नहीं होते (जैसे: सड़क, पढ़ना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e11af203-3971-4830-831d-e76715c1cba8', 'ड़ और ढ़ (Dda and Ddha)', true, '6e8c72e3-991c-4ea0-9719-26d297d35f76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca63c8c6-de30-4e74-bcfc-753278ac0ff9', 'ड और ढ', false, '6e8c72e3-991c-4ea0-9719-26d297d35f76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42521e18-0e19-45cf-93d8-a4e9ae4264da', 'त और थ', false, '6e8c72e3-991c-4ea0-9719-26d297d35f76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d10521b-30c4-4fc2-9277-887e43131f5f', 'य और व', false, '6e8c72e3-991c-4ea0-9719-26d297d35f76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b60b7581-a983-4866-9007-31bad26b695e', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'मानक हिंदी वर्तनी के केंद्रीय नियम के अनुसार, संयुक्त क्रियाओं और ''गए / गए'' तथा ''हुए / हुए'' में से मानक रूप किसे माना गया है?', 'केंद्रीय हिंदी निदेशालय के अनुसार जहाँ स्वर का स्वाभाविक उच्चारण हो, वहाँ ''गए, नए, हुए'' मानक रूप हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('945f297d-59ad-42a8-8be0-520904563fee', 'स्वर रूप ''गए, नए, हुए, चाहिए'' को मानक माना गया है (य-श्रुति के स्थान पर मूल स्वर रूप)', true, 'b60b7581-a983-4866-9007-31bad26b695e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('add6ca9e-57ef-44be-9aac-2560de02b9bf', 'गये और नये को केवल माना गया है', false, 'b60b7581-a983-4866-9007-31bad26b695e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a99e023f-7006-4329-9a38-741145e8e15e', 'दोनों को अमान्य किया गया है', false, 'b60b7581-a983-4866-9007-31bad26b695e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8d6c682-01b2-4c10-895a-3f46604ebf5c', 'केवल संस्कृत शब्दों को माना गया है', false, 'b60b7581-a983-4866-9007-31bad26b695e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7cc33737-3341-4c7b-a1bc-3af19f08eaeb', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'प्लुत स्वर (Protracted Vowel) का प्रयोग हिंदी और संस्कृत में कहाँ किया जाता है?', 'त्रिमात्रिक दीर्घतम स्वर ''प्लुत स्वर'' (प्रतीक ३) दूर से संबोधन और ॐ के नाद में प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7c65b31-2d3d-4da8-8d07-9f4168882f34', 'किसी को दूर से पुकारने, रोने, गाने या ॐ (ओ३म्) के उच्चारण में जहाँ स्वर को तीन मात्राओं तक लंबा खींचा जाता है', true, '7cc33737-3341-4c7b-a1bc-3af19f08eaeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4686c413-132c-49e4-a03f-10c4d6162efb', 'केवल मौन रहने पर', false, '7cc33737-3341-4c7b-a1bc-3af19f08eaeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03f4fc44-7c27-4add-9428-28433f297469', 'केवल विराम चिह्नों में', false, '7cc33737-3341-4c7b-a1bc-3af19f08eaeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0e855a6-5119-4551-a973-6b000c2c10d6', 'साधारण बोलचाल में', false, '7cc33737-3341-4c7b-a1bc-3af19f08eaeb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7328685d-a426-4ad0-901c-2f1781c81137', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', '''उज्ज्वल'' शब्द की शुद्ध मानक वर्तनी क्या है और इसमें कौन-सा व्यंजन नियम प्रयुक्त हुआ है?', 'उत् + ज्वल: त् का ज् में परिवर्तन → दोनों ''ज'' अर्द्ध (ज्ज्) होकर ''उज्ज्वल'' बनाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34778804-b2a7-41e0-bb84-e253ba81c1a9', '''उज्ज्वल'' (उत् + ज्वल = उज्ज्वल, जिसमें दोनों ''ज'' स्वर-रहित / आधे ''ज्ज्'' होते हैं)', true, '7328685d-a426-4ad0-901c-2f1781c81137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f52498a-3a8e-46f4-b824-cf52227bb8b3', '''उज्वल''', false, '7328685d-a426-4ad0-901c-2f1781c81137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22e3adb4-6f1b-4d66-bce0-cda85a88dfa4', '''उज्जवल''', false, '7328685d-a426-4ad0-901c-2f1781c81137');
