INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('201c4f56-ddb8-42a3-96e4-c22fa697c67c', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'हिंदी में ''ऋ'' स्वर का मानक उच्चारण और लिपि प्रयोग क्या है?', '''ऋ'' तत्सम संस्कृत मूल स्वर है; देवनागरी में इसकी मात्रा (ृ) केवल व्यंजनों के पाद में जुड़ती है (जैसे: कृपा, मातृ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('574276d8-2d6f-45a4-b0f2-98f4de4e284b', '''ऋ'' एक तत्सम संस्कृत स्वर है जिसका आधुनिक हिंदी में उच्चारण ''रि'' जैसा होता है, किन्तु यह मूल रूप से स्वर माना जाता है (जैसे: ऋषि, ऋतु, ऋण)', true, '201c4f56-ddb8-42a3-96e4-c22fa697c67c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46bde99d-80bc-4d1e-9a68-9bdacf48bb74', '''ऋ'' केवल एक व्यंजन है', false, '201c4f56-ddb8-42a3-96e4-c22fa697c67c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b204a4c-7b0d-4703-b5f7-35ce9cfba787', '''ऋ'' का हिंदी में कोई प्रयोग नहीं है', false, '201c4f56-ddb8-42a3-96e4-c22fa697c67c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccf443e9-3055-413a-bf47-6f6d156a38a2', '''ऋ'' केवल नाम के आगे लगता है', false, '201c4f56-ddb8-42a3-96e4-c22fa697c67c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ccf755fc-6f5f-4980-9690-f61bcebf3006', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'वर्ण विचार और मानक वर्तनी के सम्यक अध्ययन का भाषा अधिगम में क्या सर्वोच्च महत्व है?', 'वर्ण विचार भाषाशास्त्र का मूलाधार है, जो उच्चारण-स्थान की शुद्धता, ध्वनिविज्ञान और वर्तनी मानकीकरण को परिपुष्ट करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0556fa27-aece-46a0-b6ef-31445e068da9', 'यह भाषा की नींव को सुदृढ़ करता है, अशुद्ध उच्चारण तथा वर्तनी दोषों का पूर्ण निवारण कर वैज्ञानिक एवं प्रामाणिक भाषा-दक्षता प्रदान करता है', true, 'ccf755fc-6f5f-4980-9690-f61bcebf3006');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e6a6576-8798-465d-a501-b659cebfbaae', 'यह केवल वर्णों को रटने का साधन है', false, 'ccf755fc-6f5f-4980-9690-f61bcebf3006');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ddfd50a-476b-4b47-9263-ac1005943457', 'इसका व्याकरण से कोई संबंध नहीं है', false, 'ccf755fc-6f5f-4980-9690-f61bcebf3006');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e89ac4f0-4edf-4bf1-88f1-6271256a5140', 'यह केवल परीक्षाओं में अंक लाने के लिए है', false, 'ccf755fc-6f5f-4980-9690-f61bcebf3006');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c389661-7c8e-4f1f-bf7b-1dc63eb35ddb', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'A reliable, scientific numerical measure of the degree of hotness or coldness of an object is called its:', 'Temperature is the objective physical quantity measuring the average kinetic energy of constituent particles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4a12b8a-f3b3-4cfa-ab35-35cbc2fa93b2', 'Temperature', true, '4c389661-7c8e-4f1f-bf7b-1dc63eb35ddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1c40089-9b3c-47e1-870b-785d872981fe', 'Heat energy', false, '4c389661-7c8e-4f1f-bf7b-1dc63eb35ddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1767611d-a936-4bbf-aa24-a38d143ca280', 'Density', false, '4c389661-7c8e-4f1f-bf7b-1dc63eb35ddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b888f3d-eb5e-40db-a626-d7be316412f5', 'Pressure', false, '4c389661-7c8e-4f1f-bf7b-1dc63eb35ddb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('769dcc13-3df4-4f58-8e93-8e287bc305d8', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'The device used specifically to measure the temperature of the human body is called a:', 'A clinical thermometer measures human body temperature across a narrow physiological range.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d62a4e00-d63a-4974-a364-854b7cc19295', 'Clinical Thermometer', true, '769dcc13-3df4-4f58-8e93-8e287bc305d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dd476d3-5659-44b4-b67c-fdc4f2deeb3a', 'Laboratory Thermometer', false, '769dcc13-3df4-4f58-8e93-8e287bc305d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('642f44f9-e70b-4139-a721-392e299eb6a4', 'Barometer', false, '769dcc13-3df4-4f58-8e93-8e287bc305d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5231efe0-a477-41ea-be6f-c7acd793b593', 'Speedometer', false, '769dcc13-3df4-4f58-8e93-8e287bc305d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc14448a-1b42-4dd5-9e9b-4f2bc08a90ae', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'What is the temperature scale range of a standard Clinical Thermometer in Celsius degrees?', 'Clinical thermometers span 35°C to 42°C because human body temperature rarely drops below 35°C or exceeds 42°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f9f5d3e-f2f9-4235-a143-afc84f23d9b6', '35°C to 42°C', true, 'cc14448a-1b42-4dd5-9e9b-4f2bc08a90ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f8e30b7-55f1-477d-9fdf-b57496f49911', '-10°C to 110°C', false, 'cc14448a-1b42-4dd5-9e9b-4f2bc08a90ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f89a4f7-f29b-4c45-b064-4a6a63df4e9b', '0°C to 100°C', false, 'cc14448a-1b42-4dd5-9e9b-4f2bc08a90ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c04304ea-71b1-4a11-9859-1fe3ae18dabd', '32°F to 212°F only', false, 'cc14448a-1b42-4dd5-9e9b-4f2bc08a90ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ab71ae8-5f73-481c-a4f0-fd7be36075a6', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'What is the normal healthy average temperature of the human body on the Celsius scale?', 'Standard basal human homeostatic body temperature averages 37.0°C (98.6°F).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe0cf69c-1bbc-462d-8b73-4288651667e4', '37°C (98.6°F)', true, '4ab71ae8-5f73-481c-a4f0-fd7be36075a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecbd7699-917b-4c22-9a21-fe2a01cb08ee', '35°C', false, '4ab71ae8-5f73-481c-a4f0-fd7be36075a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e42b3d8-3065-4193-a62f-4731e89c5196', '39°C', false, '4ab71ae8-5f73-481c-a4f0-fd7be36075a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05099325-b244-4288-b23e-f2d7d5f15f88', '100°C', false, '4ab71ae8-5f73-481c-a4f0-fd7be36075a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe533a70-cde2-4dee-8e36-1c712fd1b338', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'What is the standard measurement range of a Laboratory Thermometer?', 'Laboratory thermometers generally span from -10°C up to 110°C to measure physical and chemical reactions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f090a23e-a31d-4151-b098-9d63a2f43927', '-10°C to 110°C', true, 'fe533a70-cde2-4dee-8e36-1c712fd1b338');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('592bc15f-cd50-4e73-8dd5-d27d02c9f0ba', '35°C to 42°C', false, 'fe533a70-cde2-4dee-8e36-1c712fd1b338');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df872c93-844f-47a2-9e83-b51afbe7e59c', '0°C to 50°C', false, 'fe533a70-cde2-4dee-8e36-1c712fd1b338');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50332965-2f1d-4a62-b1c6-59c98039b04f', '-50°C to 200°C', false, 'fe533a70-cde2-4dee-8e36-1c712fd1b338');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab3b42c2-e137-4201-aea2-70f7332a977b', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'The process by which heat is transferred from the hotter end to the colder end of a SOLID object without the actual movement of its particles is called:', 'Conduction is solid-state thermal energy transfer through vibrational atomic collisions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6317828e-a4f9-4f73-a273-ba58c2ed65a3', 'Conduction', true, 'ab3b42c2-e137-4201-aea2-70f7332a977b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a298b2c-dd8e-4269-9ab8-ee4fd40b1129', 'Convection', false, 'ab3b42c2-e137-4201-aea2-70f7332a977b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9c3f4d3-ff45-4a9d-b7b0-1a98f67eb437', 'Radiation', false, 'ab3b42c2-e137-4201-aea2-70f7332a977b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18cf3e7b-8d19-4bde-9ae2-b92c29d53adf', 'Insulation', false, 'ab3b42c2-e137-4201-aea2-70f7332a977b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee2ddb34-5410-40f6-b628-eef569211c2c', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'Materials that allow heat to pass through them easily and rapidly (such as copper, aluminium, iron) are called:', 'Thermal conductors possess free electrons facilitating rapid kinetic energy transfer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37d93c59-d516-427b-87c0-7f08e727b6a6', 'Conductors of Heat', true, 'ee2ddb34-5410-40f6-b628-eef569211c2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e28373ca-58d9-41c4-942d-12e338b2e131', 'Insulators', false, 'ee2ddb34-5410-40f6-b628-eef569211c2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b00d447-e997-44b1-8937-0baf12425c90', 'Semiconductors', false, 'ee2ddb34-5410-40f6-b628-eef569211c2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c96e8cbf-b8ff-4f8f-9761-56845bd759c0', 'Radiators', false, 'ee2ddb34-5410-40f6-b628-eef569211c2c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9617d0e1-fb87-4914-841d-ff30027bb1a7', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'Materials that do not allow heat to pass through them easily (such as wood, plastic, rubber, air) are called:', 'Thermal insulators have high thermal resistance, impeding heat flux.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca86b23b-96f5-45e5-b554-198c5e7781a6', 'Insulators (Poor Conductors)', true, '9617d0e1-fb87-4914-841d-ff30027bb1a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('096ec3eb-6e2d-4a40-9a9f-1eaf2deaf60a', 'Good Conductors', false, '9617d0e1-fb87-4914-841d-ff30027bb1a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba968458-c190-488c-a327-bf80d0751115', 'Metals', false, '9617d0e1-fb87-4914-841d-ff30027bb1a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3156ac02-7b4c-4f64-9ccd-6611e12ad4a0', 'Absorbers', false, '9617d0e1-fb87-4914-841d-ff30027bb1a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a63593ad-77f1-4be3-b303-a97b39861d6f', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'The mode of heat transfer in LIQUIDS and GASES where the fluid particles themselves move physically from hotter to colder regions is called:', 'Convection is bulk macroscopic fluid transport driven by buoyancy and thermal density differentials.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4717764c-5ac4-4d5d-8776-6b13984fa5d7', 'Convection', true, 'a63593ad-77f1-4be3-b303-a97b39861d6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67fc0dce-ecf5-4959-8dcf-4f19ad78a666', 'Conduction', false, 'a63593ad-77f1-4be3-b303-a97b39861d6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0287777-4f62-47be-b45e-cb908df17f79', 'Radiation', false, 'a63593ad-77f1-4be3-b303-a97b39861d6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb4f3d62-0781-48bc-9bde-45f8d1eb07cb', 'Refraction', false, 'a63593ad-77f1-4be3-b303-a97b39861d6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8fcfe44c-cbe9-4656-b983-e26a4cd0d106', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'The mode of heat transfer that does NOT require any material medium and can travel through a vacuum (such as sunlight reaching Earth) is called:', 'Thermal radiation propagates as electromagnetic infrared photons across spatial vacuum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a6b3771-b8dd-4983-8180-3a5d02ac0fa0', 'Radiation', true, '8fcfe44c-cbe9-4656-b983-e26a4cd0d106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52167d50-6ca5-4315-aee1-00711e8fa300', 'Conduction', false, '8fcfe44c-cbe9-4656-b983-e26a4cd0d106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa1798d3-dc52-4eff-9dea-aad6d0da445b', 'Convection', false, '8fcfe44c-cbe9-4656-b983-e26a4cd0d106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6a0fbef-be3a-4d5e-a54d-d308d0fb00fc', 'Advection', false, '8fcfe44c-cbe9-4656-b983-e26a4cd0d106');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c96058a2-1146-4a93-af72-41ffd2498930', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'In coastal areas during the DAYTIME, cool breeze blowing from the sea towards the land is called:', 'During the day, land heats faster than water, creating lower pressure that draws cool oceanic air inland as Sea Breeze.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9892a77-858c-4c0b-9a87-ea449ccedc9e', 'Sea Breeze', true, 'c96058a2-1146-4a93-af72-41ffd2498930');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7f80269-b2b2-465f-8853-dbfbaf0ab496', 'Land Breeze', false, 'c96058a2-1146-4a93-af72-41ffd2498930');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0f684de-7b2a-41d9-a8a6-34530db2bc84', 'Monsoon', false, 'c96058a2-1146-4a93-af72-41ffd2498930');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3337f2b7-021b-4ca3-baf3-529404d2995a', 'Cyclone', false, 'c96058a2-1146-4a93-af72-41ffd2498930');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75b4e10b-953b-43af-a075-a389db2fee09', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'In coastal areas during the NIGHT-TIME, cool breeze blowing from the land towards the sea is called:', 'At night, land cools faster than the sea, so air over warmer ocean rises and cool land air flows seaward as Land Breeze.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e47499c-3e68-4682-b7c3-4ec1c1358020', 'Land Breeze', true, '75b4e10b-953b-43af-a075-a389db2fee09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c3e8a2d-3571-435b-b5f6-d7a0a114962b', 'Sea Breeze', false, '75b4e10b-953b-43af-a075-a389db2fee09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77167c4e-e364-4dce-be63-928c741f8b71', 'Trade Wind', false, '75b4e10b-953b-43af-a075-a389db2fee09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8355028-b718-42c4-b731-756dbbda4345', 'Tornado', false, '75b4e10b-953b-43af-a075-a389db2fee09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('941c1621-0bf0-45f8-af66-901db0b2fe43', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'What is the structural purpose of the tiny ''Kink'' (constriction) in the capillary tube just above the bulb of a traditional mercury clinical thermometer?', 'The capillary kink introduces mechanical surface tension resistance, preserving the peak mercury reading.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('208c1689-f076-4e66-af3f-6f230ca27fe9', 'It prevents the mercury level from falling down on its own when removed from the patient''s mouth, allowing accurate reading', true, '941c1621-0bf0-45f8-af66-901db0b2fe43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbe191b9-cb58-4b47-8b31-51e4420fe01c', 'It makes the mercury flow faster', false, '941c1621-0bf0-45f8-af66-901db0b2fe43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('379d520d-253a-4cf9-b4f1-5a85f7a91111', 'It prevents the thermometer from breaking', false, '941c1621-0bf0-45f8-af66-901db0b2fe43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b95a1303-693c-409c-b41d-18248c23de75', 'It colors the mercury silver', false, '941c1621-0bf0-45f8-af66-901db0b2fe43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e994730-5f6f-4079-ba45-66710e113ff6', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why should a clinical thermometer NEVER be washed or sterilized in boiling hot water?', 'High hydrothermal thermal expansion overpressurizes the narrow sealed glass bore, risking explosive rupture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb1fdc73-ea51-4e2b-b523-89a49715375a', 'Boiling water (100°C) far exceeds the 42°C upper limit; extreme mercury thermal expansion will shatter the glass capillary bulb', true, '6e994730-5f6f-4079-ba45-66710e113ff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aee337c-712e-4e87-99fe-fc1a50168167', 'Because hot water turns mercury into water', false, '6e994730-5f6f-4079-ba45-66710e113ff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0ee56e7-1c31-419c-8a05-bfa672067644', 'Because boiling water erases the painted numbers', false, '6e994730-5f6f-4079-ba45-66710e113ff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8bc8700-67be-46d5-a910-686d16d8bfaf', 'Because glass melts at 100°C', false, '6e994730-5f6f-4079-ba45-66710e113ff6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbf00ddb-8271-4c83-a9a7-c5302202895d', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why are digital thermometers rapidly replacing traditional mercury glass thermometers in clinics and homes?', 'Elemental mercury is a potent neurotoxin; digital thermistors eliminate breakage contamination hazards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52a22dd6-0361-4a64-8c0e-ff2b5611378b', 'Mercury is a toxic, hazardous heavy metal that is extremely difficult to dispose of safely if the glass thermometer breaks', true, 'bbf00ddb-8271-4c83-a9a7-c5302202895d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d647fc86-36fc-41b6-88e5-b56d241c95ce', 'Digital thermometers use laser light', false, 'bbf00ddb-8271-4c83-a9a7-c5302202895d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db4e2c7c-eea5-4845-ae84-01e025873ea1', 'Mercury has stopped being manufactured worldwide', false, 'bbf00ddb-8271-4c83-a9a7-c5302202895d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fac6149-3914-4d0e-a0d3-cd98da44f3a5', 'Digital thermometers are made of pure gold', false, 'bbf00ddb-8271-4c83-a9a7-c5302202895d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50f4b334-2ae5-47db-bebb-eaaf42f0096d', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why do we prefer to wear light-colored or white clothes in hot summer and dark/black clothes in cold winter?', 'High albedo white surfaces reflect incident thermal radiation, while black surfaces have high infrared emissivity and absorptivity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01868d12-7464-4666-8676-5dae9ca75d6a', 'Light-colored clothes reflect most radiant heat keeping us cool; dark clothes absorb more radiant heat keeping us warm', true, '50f4b334-2ae5-47db-bebb-eaaf42f0096d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cdf66cc-aa3e-435a-b3d8-e37cc20afc7f', 'White clothes are lighter in physical weight', false, '50f4b334-2ae5-47db-bebb-eaaf42f0096d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a7227d5-e47d-435e-9430-154013bdc11c', 'Dark clothes produce their own electricity', false, '50f4b334-2ae5-47db-bebb-eaaf42f0096d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ccb6db2-ab2f-41f6-a32f-165a816fc4ab', 'Light colors keep mosquitoes away', false, '50f4b334-2ae5-47db-bebb-eaaf42f0096d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8a532c9-1ff2-4230-9d0f-835299818388', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why does wearing TWO thin woolen sweaters keep us significantly WARMER in winter than wearing one single thick woolen sweater of equal thickness?', 'Trapped air gaps provide high boundary-layer thermal insulation due to air''s low thermal conductivity (k ≈ 0.026 W/m·K).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e6d3960-8894-4df9-a51b-2394ad6c8b16', 'A layer of still air is trapped between the two thin sweaters; air is an excellent thermal insulator that prevents body heat from escaping', true, 'b8a532c9-1ff2-4230-9d0f-835299818388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38eaa8ff-e242-4985-8193-031b277ca61c', 'Two sweaters create friction that generates fire', false, 'b8a532c9-1ff2-4230-9d0f-835299818388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f28c4d91-6630-4486-aa7b-89bde848d530', 'Two sweaters weigh twice as much', false, 'b8a532c9-1ff2-4230-9d0f-835299818388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56bf0d98-5ee6-4d5a-8990-f7aad3af639d', 'One thick sweater attracts cold radiation', false, 'b8a532c9-1ff2-4230-9d0f-835299818388');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('125ecd07-f2fd-4ad7-98d5-e663fde4c5d4', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why are cooking utensils (like frying pans) made of metals like aluminium or stainless steel, but their handles are made of bakelite plastic or wood?', 'Engineered thermal partitioning: metallic cooking vessel conducts heat to food while thermoset bakelite handles insulate user grasp.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49f7c71b-05ef-464f-be3d-ee211fe90146', 'Metal pans conduct heat quickly to cook food, while plastic/wooden handles are poor conductors (insulators) allowing safe handling without burning hands', true, '125ecd07-f2fd-4ad7-98d5-e663fde4c5d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbe6dcb9-a57c-4b99-ab01-700446299fd8', 'Because plastic is too heavy to make pans', false, '125ecd07-f2fd-4ad7-98d5-e663fde4c5d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('584ac931-26b7-4d5a-bc95-2f4d39f667e9', 'Because wood melts on fire', false, '125ecd07-f2fd-4ad7-98d5-e663fde4c5d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3c4636a-01df-473b-8edf-28ad372e939a', 'Because metal looks shiny', false, '125ecd07-f2fd-4ad7-98d5-e663fde4c5d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ffbfe80-7170-440a-bd3a-c4ab881ab68c', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'When heating water in a round-bottom flask, why does water at the bottom rise to the top while cold water from the sides moves downwards?', 'Thermal volumetric expansion reduces fluid density, initiating buoyancy-driven Rayleigh-Bénard convection loops.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('842dbad9-d92f-40e6-831b-205baf8279b5', 'Heated water expands, becomes less dense (lighter), and rises; cooler, denser water from sides sinks to replace it, setting up Convection Currents', true, '7ffbfe80-7170-440a-bd3a-c4ab881ab68c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9cf15b8-805e-4142-a636-ff3d3d4aaedc', 'Heated water becomes heavier', false, '7ffbfe80-7170-440a-bd3a-c4ab881ab68c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd3e9314-a9ee-4c3b-89bd-212dab70b1dd', 'Bubbles push the water down', false, '7ffbfe80-7170-440a-bd3a-c4ab881ab68c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85397409-23b2-4467-b7b8-a606311cf47c', 'Water molecules repel heat', false, '7ffbfe80-7170-440a-bd3a-c4ab881ab68c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('697af3d6-5b50-4018-85b1-25254f98dcf2', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why is a laboratory thermometer kept strictly vertical and read while ITS BULB IS STILL IMMERSED in the substance being measured?', 'Lacking a retentive kink, laboratory thermometers respond instantly to ambient thermal shifts upon removal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eca24f14-dedc-4d6f-bfbf-881081e090ad', 'Because it has NO kink; the moment it is removed from the substance, its mercury level immediately starts dropping or rising due to ambient air', true, '697af3d6-5b50-4018-85b1-25254f98dcf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01c8d2da-6d06-4bee-abf1-647e084a89be', 'Because tilting breaks the glass', false, '697af3d6-5b50-4018-85b1-25254f98dcf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('586f8eed-f331-407c-89c6-b1ab8cdbba12', 'Because mercury evaporates outside', false, '697af3d6-5b50-4018-85b1-25254f98dcf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a92d1659-e4c0-4dd0-9376-95c8f4e15460', 'Because laboratory thermometers only work under water', false, '697af3d6-5b50-4018-85b1-25254f98dcf2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aedbf7b1-4485-4e4d-9453-2a7478ad4b98', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why do houses in hot tropical climates have their outer walls painted WHITE or light pastel colors?', 'Passive architectural cooling: high solar reflectance index (SRI) coatings minimize thermal envelope heat gain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ace45a5-ce49-483e-be1f-e22392bbdf27', 'White walls reflect the majority of incoming solar radiant heat, keeping the interiors significantly cooler', true, 'aedbf7b1-4485-4e4d-9453-2a7478ad4b98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1be0ae2-ff02-44b7-92d5-11152a719940', 'White paint is waterproof only', false, 'aedbf7b1-4485-4e4d-9453-2a7478ad4b98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f90f8f0-36ec-4f9e-b2f5-4932a832f75b', 'To make houses look bigger', false, 'aedbf7b1-4485-4e4d-9453-2a7478ad4b98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c6be2a5-c1a2-4bda-b162-5926be4fcd23', 'White paint repels wind', false, 'aedbf7b1-4485-4e4d-9453-2a7478ad4b98');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7122ce06-25da-4e4a-8f84-3df56da09e53', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why do rooms have electric room heaters placed on the floor and air-conditioners installed near the ceiling?', 'Optimized convective atmospheric circulation: dense chilled air descends while buoyant warm air ascends.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('850b4b33-3e78-465f-8fed-1c939bcfb584', 'Heated air expands, rises up to warm the whole room via convection; cold air from AC is dense and sinks down to cool the living space', true, '7122ce06-25da-4e4a-8f84-3df56da09e53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6936dcbd-843f-457d-a4f8-9a8e059fc2b3', 'To keep AC out of reach of children', false, '7122ce06-25da-4e4a-8f84-3df56da09e53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fec93b7-3ce2-4863-98ce-ff14525c6e42', 'Because heaters look better on floors', false, '7122ce06-25da-4e4a-8f84-3df56da09e53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('289447ad-f588-4217-b802-83ac6c32c02d', 'Because ceilings are always hotter than floors', false, '7122ce06-25da-4e4a-8f84-3df56da09e53');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aaff4759-5a4c-4b50-a557-8b5f12588ee7', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why does a metal chair feel much COLDER to touch than a wooden table in the same room during cold winter mornings?', 'Both objects are at thermal equilibrium; metal feels colder due to its high thermal effusivity rapidly conducting hand heat away.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0b3cb2f-3f45-4619-bfd2-9c9abd10c31a', 'Metal is a good conductor that rapidly draws heat away from your hand; wood is an insulator that conducts heat very slowly', true, 'aaff4759-5a4c-4b50-a557-8b5f12588ee7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ea821a1-861b-4f87-a732-95298b416150', 'The metal chair is actually at a lower temperature than the wooden table', false, 'aaff4759-5a4c-4b50-a557-8b5f12588ee7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c229ebd5-582d-4d6c-99e8-fa3c3e0b7583', 'Wood produces its own internal heat', false, 'aaff4759-5a4c-4b50-a557-8b5f12588ee7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a369ede-742c-47ee-9dfa-620f7aefc7f7', 'Metal absorbs cold from the floor', false, 'aaff4759-5a4c-4b50-a557-8b5f12588ee7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b896895f-3cf8-4bf5-8b76-55f9879287c8', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'How does a double-walled thermos flask keep hot tea hot and cold water cold for hours?', 'Dewar flask design eliminates conduction/convection via evacuating interstitial air and halts radiation via reflective silvering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0fde94a-872a-416f-bebc-cc1976960b2c', 'A vacuum between double glass walls eliminates conduction and convection, while silvery mirrored surfaces reflect radiant heat back', true, 'b896895f-3cf8-4bf5-8b76-55f9879287c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5e23b83-cc55-4845-92e5-2cef6dd6120d', 'It contains an internal battery heater', false, 'b896895f-3cf8-4bf5-8b76-55f9879287c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1e3b229-35d5-4ed5-88b1-3173a0aad453', 'It is made of thick lead', false, 'b896895f-3cf8-4bf5-8b76-55f9879287c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('402d6d48-4203-4545-b34e-a951e0826205', 'It freezes air around it', false, 'b896895f-3cf8-4bf5-8b76-55f9879287c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('831b44d2-75a0-46ea-ae64-0079b921f95a', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'What happens when you hold one hand above a burning candle flame and one hand on the side of the flame?', 'Thermal buoyancy channels convective heat plumes vertically above the flame; lateral heat transfer occurs solely by radiation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72ae9c02-9f10-4da9-a6fa-d0a891863f43', 'The hand above the flame feels much hotter because air above is heated by CONVECTION currents rising upward; the side hand feels only mild radiation', true, '831b44d2-75a0-46ea-ae64-0079b921f95a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eddb29ac-e5e4-48e9-8a30-5023d58a0a58', 'Both hands feel exactly the same heat', false, '831b44d2-75a0-46ea-ae64-0079b921f95a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26b11629-88ad-4ec2-b426-97e5c742a3ba', 'The side hand feels hotter', false, '831b44d2-75a0-46ea-ae64-0079b921f95a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5963f21-1240-4f6e-858f-b9d8b43dbcb2', 'Neither hand feels any heat', false, '831b44d2-75a0-46ea-ae64-0079b921f95a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1236aa33-41d9-4ce5-a90d-34487cfa09d0', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'What is the relationship between Celsius (°C) and Fahrenheit (°F) temperature scales?', 'Linear thermometric conversion equation: °F = (°C × 9/5) + 32.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bea3ec7-ec22-4cc7-a589-eb906a34e2ed', 'F = (9/5 × C) + 32', true, '1236aa33-41d9-4ce5-a90d-34487cfa09d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97cc8cf3-572e-4e05-8f9c-6f010cb32136', 'F = (5/9 × C) - 32', false, '1236aa33-41d9-4ce5-a90d-34487cfa09d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21b4f3b1-b088-4292-a614-bcb85e750146', 'F = C + 100', false, '1236aa33-41d9-4ce5-a90d-34487cfa09d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c214724e-4b1a-41b0-96cc-e65a7d92894a', 'F = 2C + 32', false, '1236aa33-41d9-4ce5-a90d-34487cfa09d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b1714ba-cc55-431e-9a46-0ed779c36cce', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why does wool fiber provide superior thermal warmth in winter garments?', 'Crimp morphology in wool keratin fibers creates macroscopic porous dead-air insulation lattices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a0fb1b-3a49-414e-9fc8-b38e823dddf9', 'Wool fibers have natural crimp/curls that trap substantial air pockets, and air is a poor conductor that traps body heat', true, '0b1714ba-cc55-431e-9a46-0ed779c36cce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('707faa5e-b3b0-4bf2-afa9-3a9c4da1e5bf', 'Wool produces chemical heat', false, '0b1714ba-cc55-431e-9a46-0ed779c36cce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb0d3ef1-0844-4c43-81d6-9bcd1112e265', 'Wool absorbs sunlight into blood', false, '0b1714ba-cc55-431e-9a46-0ed779c36cce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a1a8961-9178-4833-b6dd-1406c1cb4066', 'Wool is a heavy metal', false, '0b1714ba-cc55-431e-9a46-0ed779c36cce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6f94d19-d0cb-481a-ae09-cb6b1ee47396', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'What is ''Thermal Equilibrium'' between two contacting bodies?', 'Zeroth Law of Thermodynamics: thermal equilibrium is attained when thermodynamic temperature gradient equals zero (dT/dx = 0).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1ff108a-8710-4885-91a6-6693a70a6fe0', 'The state where both bodies reach the exact same temperature, resulting in zero net transfer of heat energy between them', true, 'f6f94d19-d0cb-481a-ae09-cb6b1ee47396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9c5bbed-2858-43af-a82c-41c1907a1e6f', 'When both bodies melt', false, 'f6f94d19-d0cb-481a-ae09-cb6b1ee47396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8000a171-2d9b-48ab-b405-d0465ec3b832', 'When one body freezes the other', false, 'f6f94d19-d0cb-481a-ae09-cb6b1ee47396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b24254e5-23f7-4d3e-903a-aeebd1eb29a5', 'When heat doubles in both bodies', false, 'f6f94d19-d0cb-481a-ae09-cb6b1ee47396');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2eb9c99c-c7c5-42bc-b03b-3464a4ea933c', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bd2ad9a-b2e3-49e5-9db8-ac9d73e4d194', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '2eb9c99c-c7c5-42bc-b03b-3464a4ea933c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ac26288-28f6-4f63-a640-3f4288a39eb1', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '2eb9c99c-c7c5-42bc-b03b-3464a4ea933c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d428f009-4a47-455c-9887-eeb3237e54a4', '(A) is true, but (R) is false.', false, '2eb9c99c-c7c5-42bc-b03b-3464a4ea933c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c011208-b4cc-4cfd-8763-d33c216e3640', '(A) is false, but (R) is true.', false, '2eb9c99c-c7c5-42bc-b03b-3464a4ea933c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b7cc485-9b38-4922-b399-765d9a39e859', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Spot the IMPOSTER in the following group of heat transfer mechanisms and examples:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7fb6b90-4d91-4b83-84ae-25e88030c486', 'Example 1', false, '7b7cc485-9b38-4922-b399-765d9a39e859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('971e2258-d9fa-4d71-84b4-0277addfd05b', 'Example 2', false, '7b7cc485-9b38-4922-b399-765d9a39e859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3dd1496-811e-41ac-a4bb-b98fb6dfa404', 'Example 3', false, '7b7cc485-9b38-4922-b399-765d9a39e859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e46787b-6ff0-43b7-9ef3-cac85325c5db', 'Example 4 (Circulating boiling water transfers heat by CONVECTION, not conduction)', true, '7b7cc485-9b38-4922-b399-765d9a39e859');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3ec5806-5008-4b28-adf4-1271c92909d5', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'A copper rod has wax drops fixed at intervals of 5 cm along its length with thumbtacks attached. The other end is heated over a burner flame. What is observed?', 'Fourier''s Law of Heat Conduction: thermal flux diffuses progressively along the longitudinal temperature gradient.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b337b1b0-41ce-4f74-bca0-67d8d21703f2', 'The wax drop closest to the burner flame melts first and its tack falls off, followed sequentially by successive drops, demonstrating linear thermal conduction along solids', true, 'c3ec5806-5008-4b28-adf4-1271c92909d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e24979c-cc0b-421a-a01b-21faee270e85', 'All wax drops melt simultaneously at the exact same second', false, 'c3ec5806-5008-4b28-adf4-1271c92909d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b831fa50-c11c-415d-a4d1-ee2049ac838c', 'The farthest wax drop melts first', false, 'c3ec5806-5008-4b28-adf4-1271c92909d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62a62b4c-45fe-461b-91fe-dc79adec27f2', 'None of the wax drops melt', false, 'c3ec5806-5008-4b28-adf4-1271c92909d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9074e606-9e8a-4975-b597-02631572ad05', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Match Column I (Thermal Concepts) with Column II (Scientific Principles):
(a) Clinical Thermometer -> (i) Has capillary kink & spans 35°C to 42°C
(b) Laboratory Thermometer-> (ii) Measures -10°C to 110°C without kink
(c) Sea Breeze            -> (iii) Daytime oceanic convective airflow to land
(d) Radiation             -> (iv) Infrared electromagnetic heat transfer without medium', 'Clinical = kink/35-42°C; Lab = -10-110°C; Sea breeze = daytime onshore; Radiation = electromagnetic vacuum transfer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c86cd61e-3ef7-4a4b-a688-60ce662b68d7', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '9074e606-9e8a-4975-b597-02631572ad05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f9c61c5-c949-4dfc-8c8c-1bb789ddaf74', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '9074e606-9e8a-4975-b597-02631572ad05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38d9877f-da2d-43cc-b998-40d872deb885', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '9074e606-9e8a-4975-b597-02631572ad05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f2978d0-4335-4165-a263-400dc8b5d632', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '9074e606-9e8a-4975-b597-02631572ad05');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('befb5eda-f599-4610-a5c9-ffa08f451b1b', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Read the statements regarding thermometry:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d861317f-7eae-4549-b806-0a8cb910fdb2', 'Statements 1 and 2 only', true, 'befb5eda-f599-4610-a5c9-ffa08f451b1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9171f3b-6f92-4640-9925-305f185e9928', 'Statements 2 and 3 only', false, 'befb5eda-f599-4610-a5c9-ffa08f451b1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b4cbf32-d07d-4758-83d1-0749f8dc1044', 'Statements 1 and 3 only', false, 'befb5eda-f599-4610-a5c9-ffa08f451b1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4674826-2042-43c7-8950-48a6775c6bd6', 'All Statements 1, 2, and 3', false, 'befb5eda-f599-4610-a5c9-ffa08f451b1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d5227bb-0b94-4d95-b308-3958e5887868', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Why are stainless steel cooking pans frequently manufactured with a bonded COPPER BOTTOM plate?', 'Thermal conductivity of copper (k ≈ 385 W/m·K) exceeds stainless steel (k ≈ 15 W/m·K) by ~25×, eliminating localized hot spots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('415305d6-9fb5-47c5-8cf3-147cf3fd5ba7', 'Copper has much higher thermal conductivity than stainless steel, distributing heat uniformly across the base and eliminating localized food burning', true, '7d5227bb-0b94-4d95-b308-3958e5887868');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33f2a694-5698-46ab-bf47-aa5974948482', 'Copper makes the pan heavier so it does not shake', false, '7d5227bb-0b94-4d95-b308-3958e5887868');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc979d6a-bc82-4c76-86a8-a9c3348d4684', 'Copper changes the color of food', false, '7d5227bb-0b94-4d95-b308-3958e5887868');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f645ab8a-6873-4304-880e-2830cc3fc749', 'Copper stops water from boiling', false, '7d5227bb-0b94-4d95-b308-3958e5887868');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95c5b758-9ce7-41cc-b6bb-e1e23018047b', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'If 1 litre of water at 30°C is mixed thoroughly with 1 litre of water at 50°C in an insulated vessel, what will be the final equilibrium temperature?', 'Principle of Calorimetry for equal masses of identical fluid: T_final = (30 + 50) / 2 = 40°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e53d7f6f-9c49-437f-9d34-4dd1751ad65a', 'Between 30°C and 50°C (specifically 40°C)', true, '95c5b758-9ce7-41cc-b6bb-e1e23018047b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('563f5385-c58d-4a69-bd97-685925aa46ac', '80°C (30 + 50)', false, '95c5b758-9ce7-41cc-b6bb-e1e23018047b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d415414-4161-49c7-8151-6991ffd366e7', '20°C (50 - 30)', false, '95c5b758-9ce7-41cc-b6bb-e1e23018047b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8b8a94f-e90f-4992-a2a7-d2a5730fca3e', 'More than 50°C', false, '95c5b758-9ce7-41cc-b6bb-e1e23018047b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a51369e6-e52a-4b5b-8b87-6cc86eee6d38', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'An iron ball at 40°C is dropped into a mug containing water at 40°C. How will heat flow?', 'Thermal energy transfer requires a finite temperature gradient (ΔT ≠ 0); since ΔT = 0, net heat flux is zero.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4446bf73-99b6-4116-8ddf-dec96cf3eab0', 'Heat will NOT flow from iron ball to water or from water to iron ball (Zero net heat flow due to thermal equilibrium)', true, 'a51369e6-e52a-4b5b-8b87-6cc86eee6d38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('743f79fa-85ad-4315-9a70-cc2a8294e039', 'Heat will flow from iron ball to water', false, 'a51369e6-e52a-4b5b-8b87-6cc86eee6d38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0ab4eb5-6733-4f3d-9f44-db453209756e', 'Heat will flow from water to iron ball', false, 'a51369e6-e52a-4b5b-8b87-6cc86eee6d38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('163048e1-1b9a-4d40-8f45-4640602c1072', 'The temperature of both will increase to 80°C', false, 'a51369e6-e52a-4b5b-8b87-6cc86eee6d38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4410a0e-8af9-4c3f-a8e7-953087637229', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Why do birds fluff up their feathers during freezing winter mornings?', 'Piloerection expands boundary-layer air entrapment, increasing effective thermal resistance against ambient cold.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d44388-9ee9-4b54-936d-0a58a1c5d929', 'Fluffing feathers traps a thicker layer of stationary insulating air between plumage barbules, reducing convective and conductive body heat loss', true, 'f4410a0e-8af9-4c3f-a8e7-953087637229');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6298a5cb-f5f4-41f0-ac89-50988cf3177e', 'To make themselves look bigger to predators', false, 'f4410a0e-8af9-4c3f-a8e7-953087637229');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('639aad29-7137-45f9-a9c2-67d9744803f8', 'To absorb more rain', false, 'f4410a0e-8af9-4c3f-a8e7-953087637229');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7eaa521-3792-4a5a-9971-f630ba244fe4', 'Because feathers become heavier in cold', false, 'f4410a0e-8af9-4c3f-a8e7-953087637229');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f8f9982-a1f4-492a-a8af-343e487f5236', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Consider four identical metal blocks (Copper, Aluminium, Iron, Lead) of equal mass heated to 100°C and placed on a slab of ice. Which block melts the most ice?', 'Heat released Q = m·c·ΔT. Aluminium possesses the highest specific heat capacity (c ≈ 900 J/kg·K), yielding greatest enthalpy to melt ice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44471b1f-366f-466d-81fb-4e05391f726d', 'The block with the HIGHEST Specific Heat Capacity (Aluminium melts the most ice because it stores more thermal energy per unit mass)', true, '4f8f9982-a1f4-492a-a8af-343e487f5236');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3883d88b-4293-4adc-af17-73fcbc1a36cd', 'Lead block', false, '4f8f9982-a1f4-492a-a8af-343e487f5236');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58c84e6d-cbe5-4f6c-b721-64e0843930bb', 'Iron block', false, '4f8f9982-a1f4-492a-a8af-343e487f5236');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0b5fb80-2ff9-47dd-905a-511238386e78', 'All four melt the exact same amount of ice', false, '4f8f9982-a1f4-492a-a8af-343e487f5236');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('516b45fa-bd80-48c5-a225-1bf16353b696', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Why does the greenhouse effect trap heat inside a glass greenhouse or parked closed car in the sun?', 'Spectral selectivity: shortwave solar photons penetrate glass, heating interior surfaces which re-radiate longwave IR blocked by glass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('128deb98-18f8-4483-a7e8-ea71fdcb29a6', 'Glass is transparent to short-wavelength solar radiant light but opaque to long-wavelength infrared thermal radiation emitted by interior surfaces, trapping heat energy inside', true, '516b45fa-bd80-48c5-a225-1bf16353b696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('465681ec-5d47-4f2c-a914-2a1b3c3dbc3e', 'Glass produces heat from carbon dioxide', false, '516b45fa-bd80-48c5-a225-1bf16353b696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9d5dcdb-ada0-4703-a6aa-480406e09167', 'Because glass turns sunlight into hot water', false, '516b45fa-bd80-48c5-a225-1bf16353b696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c13ad868-b354-44f4-810b-c6eddf680b2c', 'Because car metal generates electricity', false, '516b45fa-bd80-48c5-a225-1bf16353b696');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb6537b6-bf58-4507-9682-e67ed04bf134', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'What fundamental thermodynamic principle summarizes Chapter 3 of NCERT Class 7 Science?', 'Chapter 3 provides an integrated thermodynamic foundation: modes of heat transfer, thermometry, meteorological breeze circulation, and thermal engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6262ce5f-f8b5-4312-a03e-8802b03f2b13', 'Heat is thermal energy in transit driven by temperature differentials, propagating via Conduction in solids, Convection in fluids, and Radiation through vacuum, governing terrestrial weather, thermal insulation, and life adaptation', true, 'cb6537b6-bf58-4507-9682-e67ed04bf134');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08d28aed-6980-4e9c-bf5a-218be19a5e98', 'Heat and temperature are identical concepts', false, 'cb6537b6-bf58-4507-9682-e67ed04bf134');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b9d28a4-8ebb-4b4d-bf36-5548566603bc', 'Heat only travels in metal wires', false, 'cb6537b6-bf58-4507-9682-e67ed04bf134');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('087454c4-51d2-4910-85b2-e934dc5f141b', 'Vacuum can conduct heat by convection', false, 'cb6537b6-bf58-4507-9682-e67ed04bf134');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5dee1fe0-92d7-4883-aff9-820664c2a6fe', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'The sum of all observations divided by the total number of observations is called the:', 'Mean = (Sum of all observations) / (Total number of observations).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('782e30c5-dfd8-4c08-aba6-6be71b70cadb', 'Arithmetic Mean (Average)', true, '5dee1fe0-92d7-4883-aff9-820664c2a6fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c95ab6c2-758b-43a7-b7de-7d738ce049f7', 'Median', false, '5dee1fe0-92d7-4883-aff9-820664c2a6fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80c37612-f8bf-4bb5-b431-d2d33f2ad4c2', 'Mode', false, '5dee1fe0-92d7-4883-aff9-820664c2a6fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1920ae38-9f27-488b-b771-5a19ecc05b14', 'Range', false, '5dee1fe0-92d7-4883-aff9-820664c2a6fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f60b3069-264b-4c8a-9b2a-6ee3b9b2890c', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'The difference between the HIGHEST and the LOWEST observation in a given dataset is called its:', 'Range = Highest Observation - Lowest Observation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8940d40c-cd3d-461e-aeff-068dbe22e236', 'Range', true, 'f60b3069-264b-4c8a-9b2a-6ee3b9b2890c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cf6f653-e1e3-4bce-b39c-29f3a79ef853', 'Mode', false, 'f60b3069-264b-4c8a-9b2a-6ee3b9b2890c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c6f2b5c-c048-445c-8598-711acf19fcaf', 'Median', false, 'f60b3069-264b-4c8a-9b2a-6ee3b9b2890c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a79ec7e-ded9-4d85-86ca-c4b1594659bb', 'Mean', false, 'f60b3069-264b-4c8a-9b2a-6ee3b9b2890c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fd5188b-9333-47c6-9838-729965bbdb52', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'The observation that occurs MOST FREQUENTLY (highest number of times) in a dataset is called the:', 'Mode is the value that appears with the maximum frequency in a given distribution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e18b91b-01c5-448c-8760-0fcbf4cc919b', 'Mode', true, '9fd5188b-9333-47c6-9838-729965bbdb52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b4784c7-dcc5-41ab-9be1-8fe0b70cdad0', 'Median', false, '9fd5188b-9333-47c6-9838-729965bbdb52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79c21563-baf3-482f-a0bf-b9ee534964f5', 'Mean', false, '9fd5188b-9333-47c6-9838-729965bbdb52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81bf2904-2073-48fc-b8da-823065724bd4', 'Range', false, '9fd5188b-9333-47c6-9838-729965bbdb52');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f390802-7f62-4f8d-a770-b270dc654bbb', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'The middle-most observation when a dataset is arranged in ascending or descending order of magnitude is called the:', 'Median is the central value dividing an ordered dataset into two equal halves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40a659ec-5034-452d-a544-76e07c8df224', 'Median', true, '3f390802-7f62-4f8d-a770-b270dc654bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5346e926-806e-4e6c-a8c1-81c15631a5c7', 'Mode', false, '3f390802-7f62-4f8d-a770-b270dc654bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0629887-829f-476a-8adf-058193e1a89b', 'Mean', false, '3f390802-7f62-4f8d-a770-b270dc654bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63a0e4a9-9d42-4e7c-bf64-8c240aa12664', 'Frequency', false, '3f390802-7f62-4f8d-a770-b270dc654bbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b37a1955-a98b-4874-8889-15aba74fff19', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'Find the Arithmetic Mean of the first five Natural Numbers: 1, 2, 3, 4, 5:', 'Mean = (1+2+3+4+5)/5 = 15/5 = 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc1ea72-6166-451c-902e-379c9cfe416a', '3 ((1 + 2 + 3 + 4 + 5) / 5 = 15 / 5 = 3)', true, 'b37a1955-a98b-4874-8889-15aba74fff19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5dc7658-676b-45f3-b933-339ccc886b4c', '2.5', false, 'b37a1955-a98b-4874-8889-15aba74fff19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('660a0884-c5a8-43de-af00-40128c61cd18', '4', false, 'b37a1955-a98b-4874-8889-15aba74fff19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ee44b34-7ddc-40e9-8026-86866fd46532', '5', false, 'b37a1955-a98b-4874-8889-15aba74fff19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46da3a43-465e-4ab3-8534-17b7521300d3', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'Find the Mode of the data: 1, 1, 2, 4, 3, 2, 1, 2, 2, 4:', 'Frequencies: 1 (3 times), 2 (4 times), 3 (1 time), 4 (2 times). Highest frequency is 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb044d8c-4334-4812-9152-e221188d0cc6', '2 (occurs most frequently: 4 times)', true, '46da3a43-465e-4ab3-8534-17b7521300d3');
