INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3405baa0-f87e-413d-b200-ddb53b6121e9', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'Find the Median of the data values: 24, 36, 46, 17, 18, 25, 35 (arranged in ascending order: 17, 18, 24, 25, 35, 36, 46):', 'With n = 7 (odd), Median = (7+1)/2 = 4th term = 25.', NOW()) ON CONFLICT DO NOTHING;
