INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fba1643-7483-4d41-9865-2020e5ba3334', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'A visual representation of numerical data using rectangular bars of uniform width with equal spacing between them is called a:', 'A bar graph represents categorical frequencies via proportional heights of uniform rectangular bars.', NOW()) ON CONFLICT DO NOTHING;
