INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea6e8d8f-7461-438e-85dc-d5aae680ff62', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'What is the Probability (P) of tossing a fair coin and getting ''HEADS''?', 'P(Head) = 1/2 = 0.5.', NOW()) ON CONFLICT DO NOTHING;
