INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8ae884f-37af-48ec-931b-0a3fc7b66a35', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'When rolling a standard 6-sided die, what is the probability of rolling a number GREATER than 4 (i.e. 5 or 6)?', 'Favourable outcomes = {5, 6} (2 numbers). P = 2/6 = 1/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1e74a13-c5e1-4002-9708-2e8071e694e3', '2/6 = 1/3 (Favourable: {5, 6} = 2 outcomes)', true, 'c8ae884f-37af-48ec-931b-0a3fc7b66a35');
