INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fac713f0-ff27-4900-9d2c-f62c8ff791b6', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'A batsman scored the following runs in six innings: 36, 35, 50, 46, 60, 55. Calculate his Mean run score:', 'Total runs = 282. Innings = 6. Mean = 282 ÷ 6 = 47 runs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2d0e404-91dc-4171-8ce3-dc3b01ae3189', '47 runs ((36 + 35 + 50 + 46 + 60 + 55) / 6 = 282 / 6 = 47)', true, 'fac713f0-ff27-4900-9d2c-f62c8ff791b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30162d06-93be-4dba-9f69-3bd613cf5ca5', '45 runs', false, 'fac713f0-ff27-4900-9d2c-f62c8ff791b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a71f67e0-02a8-46fe-8e2a-46a15fd63f89', '50 runs', false, 'fac713f0-ff27-4900-9d2c-f62c8ff791b6');
