INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd3e6474-7e77-475f-b9f1-4c2b41e2076e', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'The scores in mathematics test (out of 25) of 15 students are:
