INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49599abd-056d-4c3a-a7d3-c797e22c5137', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'Can a dataset have MORE than one Mode (e.g. Bimodal or Multimodal data)?', 'Distributions with multiple distinct equal peak frequencies are bimodal or multimodal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('750ad8d0-5984-4905-ad9d-50948e55c9a7', 'Yes, if two or more observations share the highest frequency equally (e.g. in 2, 2, 3, 3, 4, both 2 and 3 are modes)', true, '49599abd-056d-4c3a-a7d3-c797e22c5137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d761ccd5-63bc-4718-b756-78a4a73dacc9', 'No, data can only ever have one mode', false, '49599abd-056d-4c3a-a7d3-c797e22c5137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83da99ee-22b7-4592-9fa6-4f365eaacc8a', 'Only if the data contains negative numbers', false, '49599abd-056d-4c3a-a7d3-c797e22c5137');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f94635de-0160-4ba3-9830-e0e35cd311e7', 'Only when data has zero observations', false, '49599abd-056d-4c3a-a7d3-c797e22c5137');
