INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34a914d6-004e-4c46-b2e2-5050ad3a71e0', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'Find the Median of the first seven Prime Numbers: 2, 3, 5, 7, 11, 13, 17:', 'Ordered 7 primes: 2, 3, 5, 7, 11, 13, 17. Median = 4th value = 7.', NOW()) ON CONFLICT DO NOTHING;
