INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3091ccbc-d61f-43f3-b97c-686afe11f949', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'What is the Probability of an ''IMPOSSIBLE EVENT'' (such as rolling a 7 on a standard 6-sided die)?', 'An impossible event has 0 favourable outcomes; P(Impossible) = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33c4db6e-c80e-4851-8c07-e4612aa4eb03', '0 (Zero)', true, '3091ccbc-d61f-43f3-b97c-686afe11f949');
