INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5344a087-4f42-41a1-b6fe-eec8fec77cda', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'What is the Probability of a ''CERTAIN / SURE EVENT'' (such as the Sun rising in the East tomorrow)?', 'A certain event is guaranteed to occur; P(Sure) = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4a8d158-4f0d-4637-b8fb-cf9ad3d62c22', '1 (One / 100% certainty)', true, '5344a087-4f42-41a1-b6fe-eec8fec77cda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51039051-0a81-4fe4-90c2-4d84066fb0d3', '0', false, '5344a087-4f42-41a1-b6fe-eec8fec77cda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7789b1a8-6242-4ce8-a600-c1635755d1d8', '0.5', false, '5344a087-4f42-41a1-b6fe-eec8fec77cda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2541eece-e435-4414-bb39-be5e30d09688', 'Infinity', false, '5344a087-4f42-41a1-b6fe-eec8fec77cda');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ea42747-ba93-4b54-a242-8500590c2d22', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'There are 6 marbles in a box with numbers from 1 to 6 marked on each of them. What is the probability of drawing a marble with number 2?', 'Favourable outcome = 1 (marble 2). Total = 6. P = 1/6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86a067aa-84f9-451b-bc44-fc37a68bc740', '1/6', true, '5ea42747-ba93-4b54-a242-8500590c2d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31e7a2bd-150e-4d83-9c0a-d0ac589ef488', '2/6 = 1/3', false, '5ea42747-ba93-4b54-a242-8500590c2d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('473a0131-e0d1-4acd-b642-fddf06090ed5', '1/2', false, '5ea42747-ba93-4b54-a242-8500590c2d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e078955-fb67-4779-8ce7-f39600b32492', '6/1', false, '5ea42747-ba93-4b54-a242-8500590c2d22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3ded0f2-93bf-4473-82e8-8ec982a1eca5', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'There are 6 marbles in a box numbered 1 to 6. What is the probability of drawing a marble with an EVEN number (2, 4, 6)?', 'Even outcomes = {2, 4, 6} (3 outcomes). P = 3/6 = 1/2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91413a15-87ca-487f-8a85-1f205e138722', '3/6 = 1/2', true, 'b3ded0f2-93bf-4473-82e8-8ec982a1eca5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25b187db-ac72-42f0-a264-d6e285eb9743', '1/6', false, 'b3ded0f2-93bf-4473-82e8-8ec982a1eca5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e6ef289-5f97-41af-a4b3-d131d4b6a0e1', '2/6', false, 'b3ded0f2-93bf-4473-82e8-8ec982a1eca5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abf6782c-2c75-4752-a3b1-2b8f6215f9fc', '5/6', false, 'b3ded0f2-93bf-4473-82e8-8ec982a1eca5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbde28a5-debd-40ce-9904-1e8e9eabd1a1', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'The Mean of 5 numbers is 20. If one number is excluded, their mean becomes 18. What is the excluded number?', 'Old sum = 5 × 20 = 100. New sum = 4 × 18 = 72. Excluded = 100 - 72 = 28.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('430de262-c381-4118-9c25-4d4ebe3d4ff2', '28 (Sum of 5 numbers = 5 × 20 = 100 ; Sum of 4 numbers = 4 × 18 = 72 ; Excluded = 100 - 72 = 28)', true, 'fbde28a5-debd-40ce-9904-1e8e9eabd1a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6b99dc7-a640-4b41-bb76-8f1e1fb32942', '24', false, 'fbde28a5-debd-40ce-9904-1e8e9eabd1a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e33f928d-199b-4064-be36-28e405f7f6a0', '26', false, 'fbde28a5-debd-40ce-9904-1e8e9eabd1a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d8a2f65-bc0b-46a7-bdb7-62032b0e1755', '30', false, 'fbde28a5-debd-40ce-9904-1e8e9eabd1a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6213f510-4d96-4cf3-8caa-733ddc09b7de', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'The Mean of 10 observations was calculated as 40. Later it was found that an observation 45 was misread as 15. What is the correct Mean?', 'Correct sum = 400 - 15 + 45 = 430. Correct mean = 430 ÷ 10 = 43.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd95e009-2138-46be-809f-b50ea9e008bb', '43 (Calculated sum = 400 ; Correct sum = 400 - 15 + 45 = 430 ; Correct mean = 430 / 10 = 43)', true, '6213f510-4d96-4cf3-8caa-733ddc09b7de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eb43b4b-338a-4078-bf93-f06eaaf79f26', '41.5', false, '6213f510-4d96-4cf3-8caa-733ddc09b7de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('947b3f09-56bb-4e24-a1f5-a9eb57530059', '42', false, '6213f510-4d96-4cf3-8caa-733ddc09b7de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea85dae7-8f52-4b4e-8e0e-8a3fb5dff74c', '45', false, '6213f510-4d96-4cf3-8caa-733ddc09b7de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b63719ae-1248-4189-bf26-0da56d067f1f', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'Which measure of central tendency is MOST suitable for a shopkeeper deciding which shoe size to stock in the largest quantity?', 'Mode reflects peak modal consumer demand for inventory stocking decisions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02046b2d-84d6-4c09-a398-00df434ffecc', 'Mode (since it identifies the most popular, frequently purchased shoe size)', true, 'b63719ae-1248-4189-bf26-0da56d067f1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('981033ab-10d7-4605-9460-b427117431e8', 'Mean', false, 'b63719ae-1248-4189-bf26-0da56d067f1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16954a4e-c308-4bcd-9d50-2f2bc909d4ed', 'Median', false, 'b63719ae-1248-4189-bf26-0da56d067f1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82f7271e-17c2-4405-b89e-10b2d4ab5902', 'Range', false, 'b63719ae-1248-4189-bf26-0da56d067f1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d42fcca1-dcd3-4ae3-8b6d-da5a6d22d7ce', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'Which measure of central tendency is preferred when a dataset contains extreme outlier values (e.g. salaries where one billionaire skews the average)?', 'Median is a non-parametric robust statistic unaffected by skewness or extreme outliers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adeafe98-2ff6-419c-8fca-9009ba29a7d7', 'Median (because the median is resistant to extreme outliers)', true, 'd42fcca1-dcd3-4ae3-8b6d-da5a6d22d7ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5304094-617b-45d0-9a56-4458d94d1cc3', 'Mean (which gets heavily distorted by outliers)', false, 'd42fcca1-dcd3-4ae3-8b6d-da5a6d22d7ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bc46409-1f5c-46c9-9d54-2a40b8b9f389', 'Range', false, 'd42fcca1-dcd3-4ae3-8b6d-da5a6d22d7ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ddda131-8f3f-4234-bff6-22b8a8ea44d3', 'Total sum', false, 'd42fcca1-dcd3-4ae3-8b6d-da5a6d22d7ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52245717-c44f-439a-a44e-1d29ccca905e', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'On a bar graph, if a scale is chosen as 1 unit length = 10 students, what bar length in unit units represents 75 students?', 'Length = Value ÷ Scale factor = 75 ÷ 10 = 7.5 units.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28185e08-80e0-45a4-8390-b7d06e687623', '7.5 units (75 / 10 = 7.5 units)', true, '52245717-c44f-439a-a44e-1d29ccca905e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a6bbfff-bf51-4ab8-8e76-889537110fc4', '7 units', false, '52245717-c44f-439a-a44e-1d29ccca905e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be7569d5-abd9-437e-824b-c23e702dc275', '8 units', false, '52245717-c44f-439a-a44e-1d29ccca905e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ce06087-d728-4fde-b4da-3de0bacf9373', '75 units', false, '52245717-c44f-439a-a44e-1d29ccca905e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34d645e2-effe-48f0-802b-e0b636c4ff80', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'What is the Median of the EVEN number of observations: 12, 14, 16, 18, 20, 22?', 'For n = 6 (even), Median is the mean of 3rd and 4th terms: (16 + 18)/2 = 17.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc4e4cf3-7e58-49db-ab8f-b3344a223c16', '17 (Average of the two middle terms 16 and 18: (16 + 18) / 2 = 34 / 2 = 17)', true, '34d645e2-effe-48f0-802b-e0b636c4ff80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b14a6e3-24c4-4c99-a4f5-733cf4b54f16', '16', false, '34d645e2-effe-48f0-802b-e0b636c4ff80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b0bb372-4101-4f67-847b-b025573fe7ae', '18', false, '34d645e2-effe-48f0-802b-e0b636c4ff80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e82339ce-40fe-4ffd-9a12-11b24d400ffc', '16.5', false, '34d645e2-effe-48f0-802b-e0b636c4ff80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9ab9c91-7e93-4f90-abae-139c7d685d83', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e44450f6-b787-498b-a000-e7d2b6adce98', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'b9ab9c91-7e93-4f90-abae-139c7d685d83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56b4a64a-422a-40f2-911f-024c9bf1bbfb', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'b9ab9c91-7e93-4f90-abae-139c7d685d83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baf8665a-20b1-4cc8-85c9-bb3e598140ae', '(A) is true, but (R) is false.', false, 'b9ab9c91-7e93-4f90-abae-139c7d685d83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d3017b1-e032-413d-be34-6983655b5094', '(A) is false, but (R) is true.', false, 'b9ab9c91-7e93-4f90-abae-139c7d685d83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a71936c9-1ab0-4b0b-a284-16033600687d', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Spot the IMPOSTER among the following statements regarding Central Tendency:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba48de11-8586-4c9b-bc05-41be1100fb74', 'Statement 1', false, 'a71936c9-1ab0-4b0b-a284-16033600687d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c69aa23-d119-4de2-b0fd-a43346ccf7e8', 'Statement 2 (Mean is NOT necessarily one of the numbers in the data, e.g. Mean of 2 and 3 is 2.5)', true, 'a71936c9-1ab0-4b0b-a284-16033600687d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3c2f030-ab00-4f47-8ba7-29f8b8396313', 'Statement 3', false, 'a71936c9-1ab0-4b0b-a284-16033600687d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5616e636-8657-4bff-8cd8-00d747fa91c5', 'Statement 4', false, 'a71936c9-1ab0-4b0b-a284-16033600687d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5355cfa-8038-44fe-aaec-37aad537bd3e', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'The mean weight of a group of 20 boys is 52 kg, and the mean weight of another group of 30 boys is 47 kg. Find the COMBINED mean weight of all 50 boys:', 'Weighted average = (20×52 + 30×47) / 50 = (1040 + 1410)/50 = 2450/50 = 49 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1450fc8f-4b04-41bc-a2ce-fe809677477e', '49 kg (Total weight = (20 × 52) + (30 × 47) = 1040 + 1410 = 2450 kg ; Combined mean = 2450 / 50 = 49 kg)', true, 'd5355cfa-8038-44fe-aaec-37aad537bd3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('495400e8-0044-40a3-8958-47bc4abf3b05', '49.5 kg', false, 'd5355cfa-8038-44fe-aaec-37aad537bd3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a01e8c8c-c64c-44a6-b6ee-0e3eba58cf66', '48 kg', false, 'd5355cfa-8038-44fe-aaec-37aad537bd3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c8ec326-393f-4828-b742-a9ea570a1adc', '50 kg', false, 'd5355cfa-8038-44fe-aaec-37aad537bd3e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2217c22-527c-4204-b7e3-2275706d0cdc', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Match Column I (Statistical Concepts) with Column II (Properties & Formulas):
(a) Arithmetic Mean -> (i) Sum of observations / Number of observations
(b) Median          -> (ii) Middle value dividing ordered data into two halves
(c) Mode            -> (iii) Value with the maximum frequency
(d) Range           -> (iv) Spread of data (Maximum - Minimum)', 'Mean = sum/n; Median = middle; Mode = max frequency; Range = max - min.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db45b899-53d4-45ce-b03f-100952992faf', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'b2217c22-527c-4204-b7e3-2275706d0cdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e14539a-90d2-4b1f-9052-77c05fccc6bf', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'b2217c22-527c-4204-b7e3-2275706d0cdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7c4731b-1a6a-4385-8844-b0ce7fdac59d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b2217c22-527c-4204-b7e3-2275706d0cdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e199a4e-45a9-40e0-86a7-c86230a701bf', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b2217c22-527c-4204-b7e3-2275706d0cdc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cdc27448-426a-4e7a-b29a-614537952ba3', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Read the statements regarding Probability:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d284b92-080e-41ee-9a25-06ffd675910b', 'Statements 1 and 2 only', true, 'cdc27448-426a-4e7a-b29a-614537952ba3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10ff5115-1e68-4af1-9ff7-85a28d379a7d', 'Statements 2 and 3 only', false, 'cdc27448-426a-4e7a-b29a-614537952ba3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2988468-1498-49dc-ad08-b06b81021b95', 'Statements 1 and 3 only', false, 'cdc27448-426a-4e7a-b29a-614537952ba3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d09c398-3885-4928-bc63-3e9068fa7637', 'All Statements 1, 2, and 3', false, 'cdc27448-426a-4e7a-b29a-614537952ba3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58e5974f-5f92-49d8-b625-7396c7ce2484', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'The following observations are arranged in ascending order: 11, 14, 15, 17, x + 1, 2x - 1, 30, 32, 35, 41.
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ea81b63-f436-4670-bcee-606719825e60', 'x = 16 (Middle two terms are (x+1) and (2x-1) ; Median = [(x+1)+(2x-1)] / 2 = 3x/2 = 24 ⇒ 3x = 48 ⇒ x = 16)', true, '58e5974f-5f92-49d8-b625-7396c7ce2484');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c9d55b-7e78-474a-a1ee-bf7892a04ec5', 'x = 14', false, '58e5974f-5f92-49d8-b625-7396c7ce2484');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('589cfbaf-0b3e-422d-a1a2-fcc72eac3e20', 'x = 18', false, '58e5974f-5f92-49d8-b625-7396c7ce2484');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('818445eb-9a38-43cb-afce-83f79d436954', 'x = 15', false, '58e5974f-5f92-49d8-b625-7396c7ce2484');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e37e0bb-8874-40c1-9945-3c2798afbc24', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'A spinning wheel has 8 equal sectors: 3 Green, 2 Blue, 2 Red, and 1 Yellow. What is the probability of the pointer landing on a sector that is NOT GREEN?', 'P(Not Green) = 1 - P(Green) = 1 - 3/8 = 5/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c945d614-352b-4034-b35c-e4e3d436d7d8', '5/8 (Non-green sectors = 2 Blue + 2 Red + 1 Yellow = 5 sectors ; P = 5/8)', true, '4e37e0bb-8874-40c1-9945-3c2798afbc24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('418d5e72-d131-4b65-856c-fa9e8203e301', '3/8', false, '4e37e0bb-8874-40c1-9945-3c2798afbc24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('798c04ad-572f-4d42-9df7-391a0de0df5a', '1/2', false, '4e37e0bb-8874-40c1-9945-3c2798afbc24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c3a76ea-ca9f-4740-9f44-ef7f685da8ab', '7/8', false, '4e37e0bb-8874-40c1-9945-3c2798afbc24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0eaa41bc-0475-447a-870e-a94ef2f518d5', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'If every observation in a dataset is MULTIPLIED by 3, what happens to the Mean and Range of the dataset?', 'Linear transformation scaling: multiplying every value x_i by scalar ''c'' scales both mean and range by factor ''c''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f33bae1-a113-4c23-95d6-69302a16f186', 'Both the Mean and the Range become 3 times the original (New Mean = 3 × Old Mean ; New Range = 3 × Old Range)', true, '0eaa41bc-0475-447a-870e-a94ef2f518d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7876d58a-decb-4e7e-8940-e2971f516d6b', 'Mean triples but Range remains unchanged', false, '0eaa41bc-0475-447a-870e-a94ef2f518d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b522f03-0e37-450d-991e-4563af3e5a89', 'Range triples but Mean remains unchanged', false, '0eaa41bc-0475-447a-870e-a94ef2f518d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c0f7d96-349b-4a32-90dd-2c4d0c081bed', 'Neither changes', false, '0eaa41bc-0475-447a-870e-a94ef2f518d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5984437-e6a9-4a8e-b663-e1f21ee818dc', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'If the constant 5 is ADDED to every observation in a dataset, what happens to the Mean and Range?', 'Location shift translation adds constant ''k'' to mean, but distance measure Range remains invariant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('289c5631-6d07-4309-8aab-16192226a9e9', 'The Mean increases by 5, but the Range remains COMPLETELY UNCHANGED (since (Max + 5) - (Min + 5) = Max - Min)', true, 'd5984437-e6a9-4a8e-b663-e1f21ee818dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbb090f-f64d-4724-8e19-e203c0e78d64', 'Both Mean and Range increase by 5', false, 'd5984437-e6a9-4a8e-b663-e1f21ee818dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1de97fb-5aeb-480d-9535-8f21f080b208', 'Mean remains unchanged, Range increases by 5', false, 'd5984437-e6a9-4a8e-b663-e1f21ee818dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f37a9ef-53b0-4178-81cb-2f3e3ec5d952', 'Neither changes', false, 'd5984437-e6a9-4a8e-b663-e1f21ee818dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('932e483f-ffd6-45b9-a74e-a3efdcbaccc3', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Consider a dataset of 5 distinct positive integers whose Mean is 12 and Median is 14. What is the MAXIMUM possible value that the largest number can take?', 'To maximize x₅: choose minimum distinct integers x₁=1, x₂=2, x₃=14 (median), x₄=15. Sum = 32 + x₅ = 60 → x₅ = 28.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22132c84-224a-48bb-9e43-ce4a390daf42', '28 (To maximize 5th number, minimize 1st, 2nd, and 4th: values = 1, 2, 14, 15, x ; Sum = 5 × 12 = 60 ⇒ 1 + 2 + 14 + 15 + x = 60 ⇒ 32 + x = 60 ⇒ x = 28)', true, '932e483f-ffd6-45b9-a74e-a3efdcbaccc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e8029c-7ba0-4d67-8c1b-dd0c43673728', '30', false, '932e483f-ffd6-45b9-a74e-a3efdcbaccc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0150cf0-8ab7-4172-befe-55da941ffdee', '26', false, '932e483f-ffd6-45b9-a74e-a3efdcbaccc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa3e1116-6b1b-4118-a126-9bad6f45685f', '32', false, '932e483f-ffd6-45b9-a74e-a3efdcbaccc3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ffdae9a-ea4a-4b85-a33d-62f8de0b9f5f', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'A bag contains 5 red balls, 8 white balls, 4 green balls, and 7 black balls. One ball is drawn at random. What is the probability that the drawn ball is NEITHER white NOR black?', 'Total balls = 5+8+4+7 = 24. Neither white nor black = Red (5) + Green (4) = 9. P = 9/24 = 3/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('973b3599-4462-4bb0-8412-f111b3515c24', '9/24 = 3/8 (Total balls = 24 ; Favourable = Red + Green = 5 + 4 = 9 balls ; P = 9/24 = 3/8)', true, '0ffdae9a-ea4a-4b85-a33d-62f8de0b9f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcdc012b-a68a-4e2a-868a-7c2572ce5028', '15/24', false, '0ffdae9a-ea4a-4b85-a33d-62f8de0b9f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60eb3d00-7b3a-419e-8a43-c03397c06448', '5/24', false, '0ffdae9a-ea4a-4b85-a33d-62f8de0b9f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8571d6f-2a8e-4a53-977b-400faac1df63', '1/3', false, '0ffdae9a-ea4a-4b85-a33d-62f8de0b9f5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a879aeca-3380-4d70-ac0d-fb79a20c91b6', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Why is Data Handling and Statistical Analysis considered the foundation of modern data science, machine learning, economic planning, and scientific decision-making?', 'Descriptive and inferential statistics provide the foundational mathematical framework for data science, modeling uncertainty, and decision analytics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('040924be-f45d-482a-890b-9d723fc6ebef', 'It transforms raw unorganized measurements into meaningful summaries, measures variability, identifies patterns, and models empirical probability for evidence-based predictions', true, 'a879aeca-3380-4d70-ac0d-fb79a20c91b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60b526c4-ca6a-4ffa-a1e6-5fccc4e6a6d9', 'Because statistics eliminates the need for data collection', false, 'a879aeca-3380-4d70-ac0d-fb79a20c91b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50f44cb6-6904-449b-a431-220abc853a0f', 'Because averages are the only numbers used in computers', false, 'a879aeca-3380-4d70-ac0d-fb79a20c91b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5a37458-226e-459d-8539-f390bfcc4878', 'Because probability guarantees 100% certainty in all future events', false, 'a879aeca-3380-4d70-ac0d-fb79a20c91b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14a52f99-088c-4327-952f-eb0a5e30e8de', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'In the comic story ''Gopal and the Hilsa-fish'', what seasonal topic was EVERYONE in the kingdom—from fishermen to courtiers and the King—obsessively talking about?', 'It was the season for Hilsa-fish, and people could talk of nothing else.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b9492ed-c65d-4bd2-aa87-9855675aa281', 'Hilsa-fish', true, '14a52f99-088c-4327-952f-eb0a5e30e8de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e01a093-60ad-4b9b-8245-b6d5d4694a9e', 'A cricket tournament', false, '14a52f99-088c-4327-952f-eb0a5e30e8de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd138738-a02a-46e0-a906-a1e215bd1950', 'A royal wedding', false, '14a52f99-088c-4327-952f-eb0a5e30e8de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc4b1523-a64d-4dc6-96f4-616b9ade0e2b', 'A foreign war', false, '14a52f99-088c-4327-952f-eb0a5e30e8de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27c6bf76-81af-4af0-af81-bc2e435ea027', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What challenge did the King throw to his witty, clever courtier Gopal?', 'The King challenged Gopal to bring a giant Hilsa to the palace without anyone mentioning the fish.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beda38a1-c29b-4ad8-99dc-bf724005560f', 'To buy a huge Hilsa-fish and bring it all the way to the royal palace without a single person asking him even ONE question about the fish on the way', true, '27c6bf76-81af-4af0-af81-bc2e435ea027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79872e1e-6c25-4f87-b6fa-cc90e71e3faa', 'To catch 1,000 fish in one hour', false, '27c6bf76-81af-4af0-af81-bc2e435ea027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e88d1465-86fc-4453-9090-8657ef5a04bf', 'To cook the most delicious fish curry', false, '27c6bf76-81af-4af0-af81-bc2e435ea027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('741780c2-5c0d-4091-a36c-3497acd67a81', 'To swim across the ocean', false, '27c6bf76-81af-4af0-af81-bc2e435ea027');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a42b1699-0a1b-4b61-82fd-26063d1a2b7f', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'How did Gopal bizarrely disguise himself before going to the marketplace to buy the Hilsa-fish?', 'Gopal half-shaved, smeared ash over his face, and donned tattered rags to look like a madman.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa78c88c-34f9-497a-88ec-4a90c8c3f505', 'He half-shaved his face, smeared dark ash all over his body, and wore filthy, torn rags', true, 'a42b1699-0a1b-4b61-82fd-26063d1a2b7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b81929a-85f9-4f35-aeee-ccb9f457d898', 'He dressed up as a wealthy foreign prince', false, 'a42b1699-0a1b-4b61-82fd-26063d1a2b7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('343c4750-60f6-4151-ac13-b75c1f89380c', 'He wore golden royal armor', false, 'a42b1699-0a1b-4b61-82fd-26063d1a2b7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86b98b55-da2e-4e3d-b3bf-5ff6f8a0f1d4', 'He disguised himself as an old woman', false, 'a42b1699-0a1b-4b61-82fd-26063d1a2b7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad1f0636-baf1-4f7a-8ea2-eccd4048d23a', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What did Gopal''s wife think when she saw him half-shaven and smearing ash on himself?', 'Gopal''s wife was bewildered and exclaimed that he had lost his sanity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97ca463e-a0b6-4683-972b-f171300b67f1', 'She was shocked and thought he had gone completely MAD', true, 'ad1f0636-baf1-4f7a-8ea2-eccd4048d23a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e37de7f5-f218-4e18-ba17-aa39548bf742', 'She thought he was going to a wedding', false, 'ad1f0636-baf1-4f7a-8ea2-eccd4048d23a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5220c8d8-78e8-4721-b4dc-56337fabb7df', 'She asked him for money', false, 'ad1f0636-baf1-4f7a-8ea2-eccd4048d23a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0371cc6f-2918-42d3-a5ad-c345df328c0b', 'She did not notice anything', false, 'ad1f0636-baf1-4f7a-8ea2-eccd4048d23a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b25173df-b0e6-4053-aaf6-4670d2fb194b', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What did people on the streets and in the market say when Gopal walked past holding the giant Hilsa-fish?', 'People were so transfixed by Gopal''s bizarre comical appearance that no one paid attention to the fish.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61602800-f8b8-4212-9cac-7df36420ce22', '"Look at that man! Isn''t he comical? He must be a madman or a mystic!" (No one noticed the fish at all!)', true, 'b25173df-b0e6-4053-aaf6-4670d2fb194b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93f60614-f5e5-4d96-bfc4-f42186b1b563', '"Look at that huge Hilsa-fish!"', false, 'b25173df-b0e6-4053-aaf6-4670d2fb194b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b849e99c-ced7-4667-aff6-ea569463bb1e', '"How much did the fish cost?"', false, 'b25173df-b0e6-4053-aaf6-4670d2fb194b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b347d138-69f5-469e-8b17-c99a43a4ff0e', '"Where did you catch that fish?"', false, 'b25173df-b0e6-4053-aaf6-4670d2fb194b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c6276e1-9d6b-4f1f-9e28-cb76e6e46b55', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What happened when Gopal reached the palace gates?', 'Barred by guards, Gopal sang and danced wildly until the curious King ordered him inside.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08a2dfcb-6287-4ba4-a4d8-77815c6bfea6', 'The guards stopped him from entering; Gopal began to dance and sing loudly until the King ordered the noisy madman brought before him', true, '0c6276e1-9d6b-4f1f-9e28-cb76e6e46b55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bb5c306-7f7d-4cc0-819d-e246d8f9544c', 'The guards welcomed him with flowers', false, '0c6276e1-9d6b-4f1f-9e28-cb76e6e46b55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('721d784f-c277-4cae-b66e-47e0f7d8b294', 'The guards stole his fish', false, '0c6276e1-9d6b-4f1f-9e28-cb76e6e46b55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8193997e-1422-4753-b6ca-47c508a74900', 'Gopal climbed over the palace wall', false, '0c6276e1-9d6b-4f1f-9e28-cb76e6e46b55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ea1fadc-4af7-43c1-b06a-d21bd7fb9ba3', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'How did the King react when he realized Gopal had successfully accomplished the impossible challenge?', 'The King laughed heartily and lauded Gopal''s extraordinary wit in fulfilling the challenge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1f490fe-94f3-4a47-a278-db1ebe51b3ec', 'He burst into hearty laughter and congratulated Gopal for achieving the impossible once again', true, '0ea1fadc-4af7-43c1-b06a-d21bd7fb9ba3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4c72ba-ce6f-4e4d-851a-40847a4165b1', 'He was very angry and sent Gopal to prison', false, '0ea1fadc-4af7-43c1-b06a-d21bd7fb9ba3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e8acace-970a-46cd-bc89-2d9dd2240a08', 'He refused to give Gopal any reward', false, '0ea1fadc-4af7-43c1-b06a-d21bd7fb9ba3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e093395-beb3-4954-8d65-384099c360e1', 'He ordered the fish thrown away', false, '0ea1fadc-4af7-43c1-b06a-d21bd7fb9ba3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('577ddae9-c3c9-47fa-bd55-244c97f46816', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'In Frank Flynn''s evocative poem ''The Shed'', where is the mysterious old shed located?', 'The poem begins: ''There''s a shed at the bottom of our garden...''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('008427a8-75a4-4c27-ba91-ef0be77ebb6f', 'At the bottom of the garden', true, '577ddae9-c3c9-47fa-bd55-244c97f46816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb19ddfd-9f4b-4ecd-ba47-7171282783b9', 'On top of a hill', false, '577ddae9-c3c9-47fa-bd55-244c97f46816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e8cdd9b-0ec0-42c3-affc-953749d63577', 'Inside the forest', false, '577ddae9-c3c9-47fa-bd55-244c97f46816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e14df6d-06b5-498f-b8fd-98e9ef0adec9', 'Behind the school', false, '577ddae9-c3c9-47fa-bd55-244c97f46816');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bcfd4735-be7c-4f73-bdd9-ed416b7e5856', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'In ''The Shed'', what is hanging across the shed door, and what sound do the rusty hinges make in the wind?', 'Flynn describes the spider''s web across the door and the creaking of rusty hinges when the poet lies in bed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b47e8b5-21c1-422a-9112-873daf2ba3de', 'A Spider''s web hangs across the door ; the rusty hinges Creak in the wind', true, 'bcfd4735-be7c-4f73-bdd9-ed416b7e5856');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1190a4c8-c6ef-4416-860f-cb173f530dc9', 'A golden lock ; they ring like bells', false, 'bcfd4735-be7c-4f73-bdd9-ed416b7e5856');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b472ddb2-878e-47bc-877a-02af6b56ae77', 'A green curtain ; they make no sound', false, 'bcfd4735-be7c-4f73-bdd9-ed416b7e5856');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8a18520-7e5b-4ab2-8240-0b624ec63be1', 'A heavy iron chain ; they whistle', false, 'bcfd4735-be7c-4f73-bdd9-ed416b7e5856');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5b387e1-f721-4c6a-8412-2f3523caa613', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What scary warning does the speaker''s brother give him about the old shed?', 'The brother frightens him with tales of a head-chopping ghost hiding beneath rotten floorboards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a008f554-8c7b-4bde-8020-0f249b670373', 'There is a Ghost hiding under the rotten floorboards who will jump out and chop off his head if he dares to step inside', true, 'b5b387e1-f721-4c6a-8412-2f3523caa613');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('208031d5-b81c-46e3-83eb-e664129f6129', 'There are poisonous snakes inside', false, 'b5b387e1-f721-4c6a-8412-2f3523caa613');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('794a2e87-d1b2-4a14-abc8-eadf15bdfee4', 'There is a wild bear inside', false, 'b5b387e1-f721-4c6a-8412-2f3523caa613');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db31d1eb-a052-4d00-a11a-770a04b935fc', 'The roof will fall on him', false, 'b5b387e1-f721-4c6a-8412-2f3523caa613');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3368f907-5dc3-4245-93b8-da0d28cb1726', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What is a ''Reported Question'' in English grammar?', 'Reported questions transform direct inquiries into indirect assertive clauses without inversion or question marks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6172ee05-08da-42c6-b7b1-7645fec0015b', 'Converting a direct interrogative question into an indirect declarative reported statement using ''if/whether'' or ''Wh-'' words without question marks', true, '3368f907-5dc3-4245-93b8-da0d28cb1726');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('761a6e91-e5a8-4b26-a711-a39f9d6400b3', 'Shouting a question loudly', false, '3368f907-5dc3-4245-93b8-da0d28cb1726');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59671940-cef9-440b-884a-7f77c0f5fecf', 'Writing a question in bold', false, '3368f907-5dc3-4245-93b8-da0d28cb1726');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26ca5f75-f809-43ee-9559-d43508bae70b', 'Asking a question on television', false, '3368f907-5dc3-4245-93b8-da0d28cb1726');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f2227fb-3167-4e99-99ad-ae611d847c7c', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What is the past tense of the irregular verb ''Smear'' as used in ''Gopal smeared ash on himself''?', 'The past tense of the regular verb ''smear'' is ''smeared''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7f60259-894b-4760-a158-366ac11602ae', 'Smeared', true, '2f2227fb-3167-4e99-99ad-ae611d847c7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0652998-47b7-4099-a654-c8109761c910', 'Smearing', false, '2f2227fb-3167-4e99-99ad-ae611d847c7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53cc2742-e8b7-4d6f-94cc-1e3be65a3f92', 'Smear', false, '2f2227fb-3167-4e99-99ad-ae611d847c7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6798339a-f707-4c77-8929-8ab124980342', 'Smearned', false, '2f2227fb-3167-4e99-99ad-ae611d847c7c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86b43a43-d185-455e-b5e3-7e823a129358', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'What clever psychological principle did Gopal exploit to win the King''s challenge?', 'Gopal manipulated human cognitive salience: overpowering the seasonal obsession with a dramatic personal spectacle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caaacaf6-ad53-4d0c-a7ca-17c4b159e73f', 'The power of visual distraction: by creating an outrageous, shocking visual spectacle of himself, he diverted human curiosity completely away from the fish', true, '86b43a43-d185-455e-b5e3-7e823a129358');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2bdca9a-8530-44d6-9e85-9e45fd40e6ca', 'He hid the fish inside a wooden box', false, '86b43a43-d185-455e-b5e3-7e823a129358');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02c6ca94-18a6-400c-8198-ceb36680fa92', 'He cast a sleeping spell on everyone', false, '86b43a43-d185-455e-b5e3-7e823a129358');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('768005ab-3471-496c-8f46-3978102609a8', 'He walked through secret underground tunnels', false, '86b43a43-d185-455e-b5e3-7e823a129358');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbb40df0-e6ab-4ef9-82da-2924a9782093', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'In ''The Shed'', why does the speaker realize that his brother is lying about the ghost?', 'The speaker rationally deduces his brother''s territorial motive: inventing ghost tales to monopolize the shed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50de0fd0-9efb-44b6-b22c-87204dc6d384', 'His brother tells lies to keep the shed as his own private secret den, and the speaker sees no real ghost or spider webs anymore', true, 'cbb40df0-e6ab-4ef9-82da-2924a9782093');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c039e506-005c-4985-836c-e188ad9d9468', 'Because ghosts only live in castles', false, 'cbb40df0-e6ab-4ef9-82da-2924a9782093');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('355ad30f-b022-4481-9d1e-b41eb63f642e', 'Because the shed was built yesterday', false, 'cbb40df0-e6ab-4ef9-82da-2924a9782093');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a3b320-7932-499d-a1f6-19dddbbbc5e2', 'Because his mother told him there are no ghosts', false, 'cbb40df0-e6ab-4ef9-82da-2924a9782093');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73eeb095-2058-4d9f-9943-80a2dda3ad97', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'What is the subtle psychological nuance in the poet''s final declaration at the end of ''The Shed'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af0403d4-7139-4d88-ac92-977894d5be1f', 'A realistic portrayal of growing childhood courage mixed with lingering, natural hesitation and caution before conquering the unknown', true, '73eeb095-2058-4d9f-9943-80a2dda3ad97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('842a8179-cf7a-448f-a882-6fdd7442bdaa', 'The poet decided never to enter the shed', false, '73eeb095-2058-4d9f-9943-80a2dda3ad97');
