INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01031802-1622-47ab-abf2-64bd54b9ec80', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Analyze the structural contrast between Gopal''s external physical appearance and his internal intellect:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('035e1d4d-6772-4dc9-98c0-6c43a7466bde', 'Outwardly he appeared as a deranged, half-shaven, ash-smeared madman in rags, but inwardly he was operating with supreme tactical intellect and calculated rationality', true, '01031802-1622-47ab-abf2-64bd54b9ec80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5084404-ee54-44c4-8f4f-6bc1b522890d', 'He was genuinely mad and forgot what he was doing', false, '01031802-1622-47ab-abf2-64bd54b9ec80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8d74139-b91a-4410-b2de-8c5cade0a222', 'He wanted to become a real beggar', false, '01031802-1622-47ab-abf2-64bd54b9ec80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cff41ec1-47ce-48d5-abcb-b1f953e4704b', 'He was trying to hide from the police', false, '01031802-1622-47ab-abf2-64bd54b9ec80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6c7ad1f-7677-41de-8681-7e98cf3f5ef3', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Match Column I (Characters / Poetic Imagery) with Column II (Symbolic Meanings):
(a) The Hilsa-fish       -> (i) The all-consuming, trivial seasonal obsession of society
(b) The Ash and Rags     -> (ii) Deliberate sensory distraction to bypass collective prejudice
(c) The Rotten Floorboard-> (iii) The dark, unseen realm of childhood fear and superstition
(d) ''Not just yet...''   -> (iv) The realistic boundary of growing courage before action', 'Hilsa = obsession; Ash/rags = calculated distraction; Floorboard = childhood fear; Not yet = threshold of maturity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e561232-f5de-4c60-b99f-ff78ecd4dbf2', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'd6c7ad1f-7677-41de-8681-7e98cf3f5ef3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45660422-bb8d-476e-9e40-eec599dcd7c1', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'd6c7ad1f-7677-41de-8681-7e98cf3f5ef3');
