INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfa6bcb2-60cc-41d8-b313-8a0a2d2b1e4e', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Identify the grammatical role of the underlined clause in: ''I know **that there isn''t really a ghost**.''', '''That there isn''t really a ghost'' functions as a Noun Clause object answering ''what is known''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eedb4a47-27d0-49a4-b530-74f0bf7ae4fc', 'Noun Clause acting as the direct object of the transitive verb ''know''', true, 'cfa6bcb2-60cc-41d8-b313-8a0a2d2b1e4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('672a50ce-810e-47c2-8519-b0830855804b', 'Adverb Clause of Reason', false, 'cfa6bcb2-60cc-41d8-b313-8a0a2d2b1e4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eac22bb-c47c-489e-8f24-3adf78e3c207', 'Adjective Clause qualifying ''I''', false, 'cfa6bcb2-60cc-41d8-b313-8a0a2d2b1e4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66e84946-4896-4d3f-84b7-948fc002e780', 'Prepositional Phrase', false, 'cfa6bcb2-60cc-41d8-b313-8a0a2d2b1e4e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0df06151-d35a-4cd2-86f2-5195f7dba5bb', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Which of the following sentences exhibits correct SUBJUNCTIVE MOOD expressing an imaginary hypothetical situation?', 'Hypothetical conditional subjunctive: ''If I were to peer... I would find''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f66fec78-70a9-49e4-8066-36bd631347fb', '''If I were to peer through that window, I would find only dusty old cobwebs.''', true, '0df06151-d35a-4cd2-86f2-5195f7dba5bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6daa3fd-c67f-45b8-8e28-d03e334bc3f2', '''If I was to peer through that window, I will find.''', false, '0df06151-d35a-4cd2-86f2-5195f7dba5bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6e9d39e-e8fa-4445-baf7-b9a5e27b4fd8', '''If I am peering through that window, I would found.''', false, '0df06151-d35a-4cd2-86f2-5195f7dba5bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0e5800e-68ea-4766-a57d-30f437f28c14', '''If I peer through that window, I had found.''', false, '0df06151-d35a-4cd2-86f2-5195f7dba5bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0b087ae-bb73-40ac-bbfa-067f85a42edb', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'What is the psychological function of ''The Shed'' as an architectural motif in children''s literature?', 'The garden shed functions as a liminal psychological space where adolescent rationality conquers gothic fears.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d5109d2-c7fa-450f-91b9-030cbdefc2fb', 'It serves as a liminal space representing the mysterious unknown, the repository of childhood superstitions, and the eventual triumph of empirical rationality over irrational fear', true, 'a0b087ae-bb73-40ac-bbfa-067f85a42edb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3820249-8a2e-467b-b35a-54036a9cb40d', 'It represents a prison for bad students', false, 'a0b087ae-bb73-40ac-bbfa-067f85a42edb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd2e591a-be77-406a-9aad-e60713eeebbb', 'It shows the importance of building garden toolboxes', false, 'a0b087ae-bb73-40ac-bbfa-067f85a42edb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffcdbe5b-8736-4842-a922-0c8e8b849147', 'It is a storehouse for selling old fish', false, 'a0b087ae-bb73-40ac-bbfa-067f85a42edb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1de4255-bfc4-4573-94e8-59fea5677be2', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Transform the sentence from Active Voice into PASSIVE VOICE:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69f80317-47bc-4b31-b647-efcb052133c3', '''Not a word was mentioned about the Hilsa-fish by anyone.''', true, 'b1de4255-bfc4-4573-94e8-59fea5677be2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8066689c-cd08-4682-92c3-128900093ea0', '''A word mentioned not the Hilsa-fish.''', false, 'b1de4255-bfc4-4573-94e8-59fea5677be2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a74f0cc7-e473-40c1-a6df-6896950f9173', '''The Hilsa-fish was not mentioning a word.''', false, 'b1de4255-bfc4-4573-94e8-59fea5677be2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c37540b-becb-4da6-9a89-9d0d2e35d706', '''No one was mentioning the Hilsa-fish.''', false, 'b1de4255-bfc4-4573-94e8-59fea5677be2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('689cfa16-8d78-46ca-a3be-ac4c0479677d', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'In ''The Shed'', why does the speaker note that: ''The spider has been gone from his web since I don''t know when''?', 'Observing the absent spider provides empirical validation dispelling mythic ghostly terror.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da28df1d-519f-4528-995b-45705780f59e', 'It is the speaker''s empirical observation proving that the shed is abandoned and dormant, exposing his brother''s ghost tales as groundless fabrications', true, '689cfa16-8d78-46ca-a3be-ac4c0479677d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ffbccc2-d6c9-4ebe-aa63-60c7d56aa3ff', 'Because the spider flew to another country', false, '689cfa16-8d78-46ca-a3be-ac4c0479677d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73c5df80-e10e-4dca-8d36-c722ac48c77c', 'Because the ghost ate the spider', false, '689cfa16-8d78-46ca-a3be-ac4c0479677d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20eeae25-d0b7-4a7f-9715-d2e24725b555', 'Because the speaker sprayed pesticide', false, '689cfa16-8d78-46ca-a3be-ac4c0479677d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a142e67-c16c-4c0c-b875-799635d862b5', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'What comedic technique is used when Gopal''s wife shouts from the door: ''Why are you smearing yourself with ash? What is the matter with you?'' while Gopal calmly repeats: ''I''m telling you, I''m dressing up to buy a Hilsa-fish!''?', 'Deadpan comic incongruity: pairing extreme physical absurdity with serene, literal mundane justification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61863863-df53-4944-98d1-dad8f5868c03', 'Comic Incongruity and deadpan repetition (mismatch between bizarre visual madness and completely calm, matter-of-fact dialogue)', true, '9a142e67-c16c-4c0c-b875-799635d862b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25bc2133-3e62-47dc-8e4d-98670e44dc68', 'Tragic sorrow', false, '9a142e67-c16c-4c0c-b875-799635d862b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c79fba9-edc3-4bc8-b119-0d9ea8d5da6d', 'Violent anger', false, '9a142e67-c16c-4c0c-b875-799635d862b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6d06932-0346-4a4e-8da4-9ecbae1201a1', 'Scientific debate', false, '9a142e67-c16c-4c0c-b875-799635d862b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3555f66b-c302-41ac-be41-81f3d4d7402f', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'What master life philosophy links both the prose and poetic selections in Chapter 3 of NCERT Class 7 English?', 'Chapter 3 integrates intellectual ingenuity (Gopal) with psychological courage confronting the unknown (The Shed).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a24f2cb-2de7-4f67-9846-7fc633ff22c1', 'True intellect and courage conquer all challenges—whether using sharp lateral wit to outmaneuver societal obsessions or applying rational courage to overcome fear of the dark and unknown', true, '3555f66b-c302-41ac-be41-81f3d4d7402f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c12692ea-e20c-4c91-82a0-2ebb80eba285', 'That fish is the only food worth eating', false, '3555f66b-c302-41ac-be41-81f3d4d7402f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('864d18a5-84ca-4995-af36-f890e96c2de2', 'That garden sheds should always be locked', false, '3555f66b-c302-41ac-be41-81f3d4d7402f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78d47d0f-0d0b-4910-a997-3c1df1addbc3', 'That courtiers should never obey kings', false, '3555f66b-c302-41ac-be41-81f3d4d7402f');
