INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37f828db-a881-4ac7-87ff-d9fce5a29447', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Medium', 'What is the famous strait of water separating the continent of Europe (Spain) from the continent of Africa (Morocco)?', 'The Strait of Gibraltar (13 km wide) links the Atlantic Ocean to the Mediterranean Sea between Spain and Morocco.', NOW()) ON CONFLICT DO NOTHING;
