INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60fc1665-05ac-4bab-be79-d37288bee56e', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Medium', 'Which body of water is known as the ''Dead Sea'', situated between Jordan and Israel?', 'The Dead Sea (430 m below sea level) has 34.2% salinity, increasing fluid density so humans float buoyantly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e81e5165-d49f-45af-a6f3-182e89be3fe6', 'A hypersaline endorheic lake (~34% salinity) where people float effortlessly and no fish or aquatic plants can survive', true, '60fc1665-05ac-4bab-be79-d37288bee56e');
