INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a93424a-c3c0-466b-8fb2-18f1e7383972', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Medium', 'Which country in the world has the LARGEST number of natural lakes (over 60% of all the world''s lakes combined)?', 'Canada contains approximately 879,000 lakes formed by extensive Pleistocene glacial scouring.', NOW()) ON CONFLICT DO NOTHING;
