INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('934f94fb-784c-4cfb-b019-ed3edd11f59b', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is an ''Isthmus'' versus a ''Strait'' in physical geography?', 'Isthmus = terrestrial bridge between landmasses; Strait = navigable nautical channel between waterbodies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a5a86e3-e7b0-4b9c-b886-81eb61581c48', 'An Isthmus is a narrow strip of LAND connecting two larger landmasses (e.g. Isthmus of Panama) ; a Strait is a narrow body of WATER connecting two larger water bodies (e.g. Strait of Gibraltar)', true, '934f94fb-784c-4cfb-b019-ed3edd11f59b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('367cfa2a-ac06-44f0-bc4b-271a7a23faa9', 'An isthmus is made of ice, a strait is made of rock', false, '934f94fb-784c-4cfb-b019-ed3edd11f59b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('802300c7-4c6b-402e-95a5-7ea9018e6a5c', 'A strait is a river in a desert', false, '934f94fb-784c-4cfb-b019-ed3edd11f59b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af56fd45-7ebe-4fc6-b29c-65152e03edcb', 'Both are identical terms for mountains', false, '934f94fb-784c-4cfb-b019-ed3edd11f59b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('090194ff-4ee8-43c6-8954-867a2898dae1', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'Match Column I (Famous Global Landmarks) with Column II (Country / Architectural Feature):
(a) Taj Mahal         -> (i) White marble mausoleum in Agra, India (Mughal architecture)
(b) Colosseum         -> (ii) Flavian amphitheatre in Rome, Italy (Roman architecture)
(c) Chichen Itza      -> (iii) El Castillo step pyramid in Yucatan, Mexico (Maya civilization)
(d) Christ the Redeemer-> (iv) Art Deco statue atop Corcovado mountain in Rio de Janeiro, Brazil', 'Taj Mahal = Mughal marble; Colosseum = Roman arena; Chichen Itza = Maya pyramid; Christ the Redeemer = Rio Art Deco.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1aa490b-9164-4af7-99c6-29296c130011', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '090194ff-4ee8-43c6-8954-867a2898dae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2080756-d32a-46d1-8bc3-8e298f6d0abe', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '090194ff-4ee8-43c6-8954-867a2898dae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86566146-a134-40bb-ab96-0b86c50bcfed', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '090194ff-4ee8-43c6-8954-867a2898dae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fb3df8d-7a58-47c3-ab20-183724152d0d', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '090194ff-4ee8-43c6-8954-867a2898dae1');
