INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b36014be-9a7a-40eb-b851-ca361a61ec0c', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'Why is the Mariana Trench so deep, and what geological process formed it?', 'Convergent tectonic plate subduction forces heavy oceanic crust into the upper asthenosphere, carving deep bathymetric trenches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f434c39e-5afe-45c8-80c6-9c388ecbd17d', 'Subduction: the older, denser Pacific tectonic plate is being forced beneath the smaller Mariana plate into the Earth''s mantle', true, 'b36014be-9a7a-40eb-b851-ca361a61ec0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8faeb9ae-6d08-4448-9e8f-db2b27f28fd1', 'Two continents collided to form a mountain', false, 'b36014be-9a7a-40eb-b851-ca361a61ec0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c66228d-3560-41ac-9c01-b3044ca89f70', 'A giant meteor impacted the Pacific Ocean', false, 'b36014be-9a7a-40eb-b851-ca361a61ec0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4ab360c-73ce-4d14-9836-c6aeb78a088e', 'An underground nuclear explosion', false, 'b36014be-9a7a-40eb-b851-ca361a61ec0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1580491c-5a44-4052-968f-ed4a071c412a', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is the ''Great Rift Valley'' of East Africa stretching over 6,000 km from the Red Sea to Mozambique?', 'The East African Rift is an active intra-continental divergent plate boundary driving continental breakup.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('708e16d2-59b0-438b-a244-4124bdfc0075', 'A divergent geological rift system where the African tectonic plate is actively splitting into two new tectonic plates (Somali and Nubian plates)', true, '1580491c-5a44-4052-968f-ed4a071c412a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('595be20a-4a12-466e-9d53-f6bcfe69d446', 'A human-made canal for shipping', false, '1580491c-5a44-4052-968f-ed4a071c412a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('273f798a-e560-4e74-8f61-95ef7b5a3f63', 'A dried-up ancient riverbed', false, '1580491c-5a44-4052-968f-ed4a071c412a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('076b7db0-292a-44bd-b8ea-1fb5eeed34fb', 'A crater formed by a volcanic explosion', false, '1580491c-5a44-4052-968f-ed4a071c412a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('299b169e-1a1c-4c3c-b9a4-9666aec82fb4', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'Consider four capital cities located along famous global rivers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f650267-a448-4846-abb3-7c6aaf5927bd', 'Rivers provided perennial freshwater, fertile alluvial soil, critical inland navigation, and vital trade connectivity for ancient urban civilizations', true, '299b169e-1a1c-4c3c-b9a4-9666aec82fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0eb182c-bd72-474b-b265-a1b320cc9339', 'Because kings liked swimming competitions', false, '299b169e-1a1c-4c3c-b9a4-9666aec82fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad937ab5-497d-4dda-872d-98fb373020e7', 'Because bridges could only be built in cities', false, '299b169e-1a1c-4c3c-b9a4-9666aec82fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478ee5a7-4e96-4ce3-b757-c4f3fac0b2ea', 'Because stone was only found underwater', false, '299b169e-1a1c-4c3c-b9a4-9666aec82fb4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f630a729-3fc4-46b4-b10e-5cc5f587b9dd', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is the scientific term for an archipelago of coral islands enclosing a central shallow seawater lagoon?', 'An atoll is a ring-shaped coral reef rim surrounding a lagoon, formed over subsiding volcanic islands (Darwin''s theory).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53022823-008f-4274-9a4c-b82bf7d9d5e8', 'Atoll (e.g. Lakshadweep and Maldives)', true, 'f630a729-3fc4-46b4-b10e-5cc5f587b9dd');
