INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d766b6b-54ae-4414-953b-63fa50a40c20', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is the unique geographical status of the city of ISTANBUL in Turkey?', 'Istanbul spans the Bosphorus Strait, straddling European Thrace and Asian Anatolia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c91047b9-30ed-45e2-97e6-f9aa8fd055f1', 'It is the ONLY transcontinental metropolis in the world located simultaneously on TWO continents (Europe and Asia), separated by the Bosphorus Strait', true, '2d766b6b-54ae-4414-953b-63fa50a40c20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7be02b4e-fec7-4123-aee0-6febb032a374', 'It is located under the ocean', false, '2d766b6b-54ae-4414-953b-63fa50a40c20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45399493-6737-4a11-9fbb-91f176c2788b', 'It has no land roads', false, '2d766b6b-54ae-4414-953b-63fa50a40c20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d88dec64-f701-43a4-982e-0d78eee2a16e', 'It is governed by the United Nations directly', false, '2d766b6b-54ae-4414-953b-63fa50a40c20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('157c3ba9-55e3-4be6-bce5-472fb26058cf', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is the ''Sargasso Sea'' in the North Atlantic Ocean?', 'The Sargasso Sea is defined exclusively by ocean current gyres (Gulf Stream, North Atlantic Current, Canary Current, North Equatorial Current).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c714f16-5913-47a9-b61e-551a272484b3', 'The ONLY sea in the world that has NO land boundaries/shores, bounded entirely by four ocean currents forming the North Atlantic Gyre', true, '157c3ba9-55e3-4be6-bce5-472fb26058cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8287ecc9-4f18-4377-8f0a-2b7e2ceef4a7', 'A sea of fresh milk', false, '157c3ba9-55e3-4be6-bce5-472fb26058cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98a1b20e-bbe5-4b10-9489-3a1d749d8e09', 'An underground sea inside a cavern', false, '157c3ba9-55e3-4be6-bce5-472fb26058cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d933e2e-78db-41ca-928c-8a8dd712f3f1', 'A frozen sea in the Sahara Desert', false, '157c3ba9-55e3-4be6-bce5-472fb26058cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ac7039e-e317-4379-aba8-30159598e4d9', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What profound planetary perspective is revealed through the comprehensive study of World Geography and Landmarks?', 'World Geography unifies geomorphic planetary dynamics with anthropogenic cultural adaptations across diverse biomes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c041986a-ff02-4b52-9864-5ab15d584671', 'Earth is a dynamic, interconnected planetary biosphere where physical plate tectonics, atmospheric currents, oceanic gyres, and cultural human civilizations form an interdependent global tapestry', true, '8ac7039e-e317-4379-aba8-30159598e4d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa373e05-9520-48aa-a41b-64cae4e614f2', 'Continents are fixed and never change over billions of years', false, '8ac7039e-e317-4379-aba8-30159598e4d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24cf9634-c690-4555-95f6-e0b11b6a2005', 'All countries have identical climates and landforms', false, '8ac7039e-e317-4379-aba8-30159598e4d9');
