INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae1638de-1a77-4464-ac65-30ef5588b211', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'Under the rule of which Rajput dynasty did the city of Delhi first become the capital of a kingdom in the 12th century?', 'Delhi first became a capital under the Tomara Rajputs, who were subsequently defeated by the Chauhans of Ajmer.', NOW()) ON CONFLICT DO NOTHING;
