INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5dfbcb34-2179-41a8-abbe-ec068fc42f0f', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'What was the agricultural land tax levied on peasant produce, accounting for about 50% of the peasant''s crop yield under Alauddin Khalji?', 'Kharaj was the standard 50% agricultural crop tax levied directly on cultivators.', NOW()) ON CONFLICT DO NOTHING;
