INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3098b1c1-0a6c-410c-9c92-a320f23dd404', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'Who was the notorious Central Asian Mongol conqueror whose forces invaded Transoxiana in 1219 and repeatedly attacked the Delhi Sultanate?', 'Genghis Khan unified the Mongols, invading Khwarizm and pressing against the northwest frontiers of India.', NOW()) ON CONFLICT DO NOTHING;
