INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a623544f-2d31-4521-a80a-c6acac7bf92c', 'Timur', false, '3098b1c1-0a6c-410c-9c92-a320f23dd404');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebd44247-1d74-4877-9e10-7ac4ebb4001a', 'Babur', false, '3098b1c1-0a6c-410c-9c92-a320f23dd404');
