INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b2bfb7a-f841-4b72-b35d-da41bc0be59e', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'Which Moroccan traveler arrived in India during the 14th-century reign of Sultan Muhammad Tughluq and left an invaluable travelogue (Rihla)?', 'Ibn Battuta from Tangier, Morocco, served as Qazi of Delhi under Muhammad Tughluq and documented Sultanate governance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c1d1d6a-95ed-48d4-b587-cebdffa492f6', 'Ibn Battuta', true, '1b2bfb7a-f841-4b72-b35d-da41bc0be59e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e13b140d-a00a-4ff8-949f-6ba91fe7a8ee', 'Marco Polo', false, '1b2bfb7a-f841-4b72-b35d-da41bc0be59e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f976112-49df-4958-805e-d8ce7709e06e', 'Al-Biruni', false, '1b2bfb7a-f841-4b72-b35d-da41bc0be59e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('375e4e89-1aa9-4620-b782-8f3bffc5b98f', 'Duarte Barbosa', false, '1b2bfb7a-f841-4b72-b35d-da41bc0be59e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa243dba-5b2b-40c9-8dcf-814a366a7ef1', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was the ''Circle of Justice'' (Fakhr-i Mudabbir, 13th century) that explained the interdependent relationship between the King, soldiers, peasants, and state revenue?', 'The Circle of Justice (Daira-i Adalat) linked monarchical survival directly to peasant prosperity and judicial equity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e1cea4f-6a72-4cf2-b235-07f7a3be9959', 'A king cannot survive without soldiers -> Soldiers cannot live without salaries -> Salaries come from revenue collected from peasants -> Peasants can pay revenue only when they are prosperous and happy -> This happens when the king promotes justice and honest governance', true, 'fa243dba-5b2b-40c9-8dcf-814a366a7ef1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0600a8ab-2b54-46b5-b098-76d1b85561c7', 'A circle drawn on the ground for duels', false, 'fa243dba-5b2b-40c9-8dcf-814a366a7ef1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fd0afc3-a75c-4d29-af12-ce7be64f04ac', 'A round table where judges sit', false, 'fa243dba-5b2b-40c9-8dcf-814a366a7ef1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d6ecd09-e6ff-4b91-a866-153ed12efc72', 'A magic circle protecting Delhi forts', false, 'fa243dba-5b2b-40c9-8dcf-814a366a7ef1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abe10e9a-98f6-44d0-8d0b-43dcba5f0524', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Why did the 13th-century chronicler Minhaj-i Siraj acknowledge that Raziyya was more able and qualified than all her brothers, yet felt uncomfortable with her rule?', 'Minhaj articulated medieval patriarchal ideology: viewing female monarchs as disrupting divine gender hierarchies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0db4460-18a2-48d9-addf-94d0db4dd275', 'He believed that female sovereignty violated the patriarchal ideal social order ordained by God, where women were supposed to be subordinate to men', true, 'abe10e9a-98f6-44d0-8d0b-43dcba5f0524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d15d777-6b46-4d27-83b7-d6bf13de3d0d', 'Because Raziyya lost all wars', false, 'abe10e9a-98f6-44d0-8d0b-43dcba5f0524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc01bcf-56b5-4e5f-ab6e-4d6dc45b111b', 'Because Raziyya could not read Persian', false, 'abe10e9a-98f6-44d0-8d0b-43dcba5f0524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('968dc7b5-b7e9-4509-8b30-a78920305ae6', 'Because Raziyya gave all kingdom wealth to foreign traders', false, 'abe10e9a-98f6-44d0-8d0b-43dcba5f0524');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3149eedc-d8c6-4645-aae1-8e5ba63b89d3', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Why did early Delhi Sultans (like Iltutmish) prefer to appoint their purchased military slaves (Bandagan) to high governorships rather than traditional noble aristocrats?', 'Royal patronage of Bandagan secured a dedicated praetorian corps personally beholden to the Sultan alone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acba37db-53b9-449d-b7af-5cef0e5c13bc', 'Slaves had no family lineage or hereditary local loyalties; they were entirely dependent on the Sultan for their livelihood and were exceptionally loyal and obedient', true, '3149eedc-d8c6-4645-aae1-8e5ba63b89d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b8ebbd0-5ae6-4fd6-a744-9a27dce3c3e8', 'Because slaves cost no money', false, '3149eedc-d8c6-4645-aae1-8e5ba63b89d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b1d69ff-8ab0-4529-8695-936f9202e686', 'Because noble aristocrats could not fight wars', false, '3149eedc-d8c6-4645-aae1-8e5ba63b89d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('509e4d58-0d89-4a60-9197-bcf5f486ebf4', 'Because slaves knew magic', false, '3149eedc-d8c6-4645-aae1-8e5ba63b89d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e25c181d-b09e-4f7a-947c-cd66d1e61a2d', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'How did Alauddin Khalji maintain strict control over his Muqtis (Iqtadars) to prevent corruption and rebellion?', 'Alauddin enforced non-hereditary tenure, frequent transfers, and rigorous auditing of Muqti revenue and troop contingents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('729663bf-b9ec-4f40-93b6-378e3fc1e07c', 'Their offices were made non-hereditary, Iqtas were assigned for short periods before frequent transfers, and state accountants were appointed to audit revenues and verify troop numbers', true, 'e25c181d-b09e-4f7a-947c-cd66d1e61a2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6da4f33-1f3c-41f9-8834-933998333211', 'He let Muqtis keep all taxes without auditing', false, 'e25c181d-b09e-4f7a-947c-cd66d1e61a2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73797dea-0e87-4f54-b130-b3d9c4d3ca05', 'He abolished all soldiers', false, 'e25c181d-b09e-4f7a-947c-cd66d1e61a2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55807f42-0253-4faa-b4a2-2b3ad4ca0eba', 'He gave Muqtis absolute permanent ownership of lands', false, 'e25c181d-b09e-4f7a-947c-cd66d1e61a2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33e466b9-971e-47ef-8615-8d6ef241f467', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What market and price control measures did Alauddin Khalji implement in Delhi to maintain a large standing army at sustainable costs against Mongol invasions?', 'Alauddin''s economic reforms: price caps, state grain silos, and market superintendents (Shahna-i Mandi) to sustain military mobilization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11bb4993-ad1b-473f-8020-cb998929eb6f', 'He strictly fixed the maximum selling prices of all commodities (grains, cloth, sugar, horses), appointed market inspectors (Shahna-i Mandi), and harshly punished any merchant who cheated or overcharged', true, '33e466b9-971e-47ef-8615-8d6ef241f467');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55b6942b-01e3-4501-905e-348f4080f91e', 'He doubled the price of all foods', false, '33e466b9-971e-47ef-8615-8d6ef241f467');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c163dcee-686a-4f14-8094-d484cddf956e', 'He banned all private markets completely', false, '33e466b9-971e-47ef-8615-8d6ef241f467');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de344c95-fbd3-4907-9343-49567673bf8f', 'He printed unlimited paper money', false, '33e466b9-971e-47ef-8615-8d6ef241f467');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73906f8d-ba69-4c97-86ad-b6719a019fb4', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was Sultan Muhammad bin Tughluq''s infamous ''Token Currency'' experiment and why did it fail disastrously?', 'Unminted token brass/copper tokens were easily counterfeited by artisans, bankrupting the imperial exchequer (Gresham''s Law).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30c8483a-0cd0-4264-b8a7-e0a368d71068', 'He issued cheap copper and brass coins having the same face value as silver Tankas; people easily forged the simple copper coins at home, paid taxes in fake tokens, and hoarded genuine gold and silver coins', true, '73906f8d-ba69-4c97-86ad-b6719a019fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9f50d02-e0bf-4b4a-b01e-0560d88b8b4a', 'Because copper turned into water', false, '73906f8d-ba69-4c97-86ad-b6719a019fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd18fd2c-9780-4e5b-b8be-445989ae01d8', 'Because people threw coins into the river', false, '73906f8d-ba69-4c97-86ad-b6719a019fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dc09fc6-f393-4130-8bad-e831494bfec9', 'Because the coins had no numbers written on them', false, '73906f8d-ba69-4c97-86ad-b6719a019fb4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d8b633f-d0c5-4992-8cc7-69c9593e771e', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was Muhammad bin Tughluq''s controversial decision to shift the imperial capital from Delhi to DAULATABAD (Devagiri in Deccan)?', 'The forced relocation to Daulatabad (1327 CE) caused widespread fatalities during the transit and was subsequently abandoned.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6faef25-5c8f-4da7-9f34-fd2859d00f75', 'He wanted to govern southern peninsular India and defend against northern Mongol attacks more effectively, but forced the entire population of Delhi to march 1,500 km south, causing immense suffering', true, '3d8b633f-d0c5-4992-8cc7-69c9593e771e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04077d0b-8d9c-45e0-80bd-5a5d43606c30', 'Because Delhi ran out of drinking water', false, '3d8b633f-d0c5-4992-8cc7-69c9593e771e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b84d4a0-a350-4454-8a27-49828b028687', 'Because Daulatabad had gold houses', false, '3d8b633f-d0c5-4992-8cc7-69c9593e771e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8f869ba-8b6c-466c-80b2-4db516d19b8d', 'Because he wanted to move to Europe', false, '3d8b633f-d0c5-4992-8cc7-69c9593e771e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43a699ce-3df9-4dc4-8dde-eb82eb0de277', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'In mosque architecture, what is the orientation towards Mecca that Indian Muslims face during prayer (towards the West) called?', 'Qibla is the sacred directional orientation toward the Kaaba in Mecca (due West from the Indian subcontinent).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6681e7f7-4c79-4843-8d74-4f8f8c528da1', 'Qibla', true, '43a699ce-3df9-4dc4-8dde-eb82eb0de277');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d44f0ae7-ce53-4241-b252-ea627011e4d8', 'Mihrab', false, '43a699ce-3df9-4dc4-8dde-eb82eb0de277');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e977dc3c-0549-4182-8c7e-bdeb77a5e393', 'Minaret', false, '43a699ce-3df9-4dc4-8dde-eb82eb0de277');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1296a2b7-334c-407d-ade2-a7b25070d987', 'Khutba', false, '43a699ce-3df9-4dc4-8dde-eb82eb0de277');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6f0b47c-c19d-4099-975d-522f55a79d55', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was the Friday congregational sermon delivered by the Imam during Namaz called?', 'The Khutba is the formal liturgical address and sermon delivered during Friday Juma congregational prayers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0c4eab7-84be-40cf-8db2-530478ec0f8e', 'Khutba', true, 'd6f0b47c-c19d-4099-975d-522f55a79d55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601e3e0f-485d-43fe-80ec-3dee05d4f31a', 'Qibla', false, 'd6f0b47c-c19d-4099-975d-522f55a79d55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('035a1b09-dfe7-4521-bb72-d638df7caa70', 'Mihrab', false, 'd6f0b47c-c19d-4099-975d-522f55a79d55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('129d37b4-affa-4cd7-900e-3dd431c70a05', 'Iqta', false, 'd6f0b47c-c19d-4099-975d-522f55a79d55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77df5168-952d-49ae-b65d-b801138d6f79', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What were the five distinct ruling dynasties of the Delhi Sultanate in chronological order (1206 to 1526 CE)?', 'Chronological sequence: Mamluks (1206–1290) → Khaljis (1290–1320) → Tughluqs (1320–1414) → Sayyids (1414–1451) → Lodis (1451–1526).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a16582b9-b630-4a9b-8d08-0fd33d25e6a5', 'Early Turkish / Mamluk Slave Dynasty -> Khalji Dynasty -> Tughluq Dynasty -> Sayyid Dynasty -> Lodi Dynasty', true, '77df5168-952d-49ae-b65d-b801138d6f79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a755102e-d778-4863-8871-275656163ccf', 'Mughals -> Marathas -> British -> Cholas -> Guptas', false, '77df5168-952d-49ae-b65d-b801138d6f79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b50fde61-71be-4c29-b65e-728c24a328cd', 'Khalji -> Slave -> Lodi -> Sayyid -> Tughluq', false, '77df5168-952d-49ae-b65d-b801138d6f79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8341e405-a23e-41b6-a5f7-93049a43f47f', 'Rajputs -> Cholas -> Mauryas -> Palas -> Lodis', false, '77df5168-952d-49ae-b65d-b801138d6f79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90522cff-06e1-4f65-b30c-f2ee8b3095c4', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Which ambitious Afghan ruler defeated Mughal Emperor Humayun in 1540 and established the Sur Empire, creating an administrative model later adopted by Emperor Akbar?', 'Sher Shah Suri (r. 1540–1545 CE) standardized silver Rupiya currency, built the Grand Trunk Road, and designed administrative revenue systems.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5b8a996-bf83-4b1f-8489-e0f56b8f9f9a', 'Sher Shah Sur (Sher Shah Suri)', true, '90522cff-06e1-4f65-b30c-f2ee8b3095c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2afae193-5bad-42c3-bef7-9279d8d6cbeb', 'Ibrahim Lodi', false, '90522cff-06e1-4f65-b30c-f2ee8b3095c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ca13380-7757-4584-9a3d-68879c653286', 'Bahlul Lodi', false, '90522cff-06e1-4f65-b30c-f2ee8b3095c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0308f9ea-efa9-4030-9921-9e2203629cc0', 'Babur', false, '90522cff-06e1-4f65-b30c-f2ee8b3095c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3256c4d-8bd5-4fd2-946d-c31d6db55bb1', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was the massive congregational mosque built by the Delhi Sultans in their first city (Dehli-i Kuhna) called?', 'Quwwat al-Islam mosque and Qutb Minar were initiated by Qutbuddin Aibak and expanded by Iltutmish and Alauddin Khalji.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f270c31f-740c-413e-9b52-70a0d2175e3e', 'Quwwat al-Islam Mosque and Qutb Minar complex', true, 'b3256c4d-8bd5-4fd2-946d-c31d6db55bb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7fde479-0e01-4516-ab14-da0404bfc961', 'Jama Masjid of Shah Jahan', false, 'b3256c4d-8bd5-4fd2-946d-c31d6db55bb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601639a1-948d-4b65-9309-3d94adc01bcc', 'Moti Masjid', false, 'b3256c4d-8bd5-4fd2-946d-c31d6db55bb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3888eb45-68f4-425a-8538-4bb59ee30378', 'Taj Mahal', false, 'b3256c4d-8bd5-4fd2-946d-c31d6db55bb1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8a9cd54-7c02-4fb7-b464-a8a986765713', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Who was the military general under Alauddin Khalji who led sensational military campaigns deep into South India (Warangal, Dwarasamudra, Madurai)?', 'Malik Kafur commanded Alauddin''s southern military expeditions between 1309 and 1311 CE, extracting vast tribute in elephants and gold.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f8e458e-63ec-46b4-9457-eed6295f9e48', 'Malik Kafur (Hazar Dinari)', true, 'c8a9cd54-7c02-4fb7-b464-a8a986765713');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aed0b2a-a985-4db8-b9dc-ded10fbf56f3', 'Ulugh Khan', false, 'c8a9cd54-7c02-4fb7-b464-a8a986765713');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6940d9d-0e83-40d3-89a8-2bc880735395', 'Zafar Khan', false, 'c8a9cd54-7c02-4fb7-b464-a8a986765713');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c17d945-c142-47e2-bff7-f0cb4ab963a1', 'Minhaj-i Siraj', false, 'c8a9cd54-7c02-4fb7-b464-a8a986765713');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b52d0c09-272d-44ca-83b9-7b56a5634a98', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What new military garrison city was constructed by Alauddin Khalji for his soldiers in Delhi?', 'Siri was established by Alauddin Khalji c. 1303 as a heavily fortified military garrison town in Delhi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('279e713d-7d6d-42a7-830f-6aa8ef6effae', 'Siri Fort', true, 'b52d0c09-272d-44ca-83b9-7b56a5634a98');
