INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f874e601-0b1a-4180-b634-9787de4fba08', 'Jahanpanah', false, 'b52d0c09-272d-44ca-83b9-7b56a5634a98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1669f490-8e0a-4dc2-bcc5-982e24a439e0', 'Tughluqabad', false, 'b52d0c09-272d-44ca-83b9-7b56a5634a98');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('110066bf-2e41-4f4a-b423-d7beb6190c96', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was the primary language of administration and official court record-keeping throughout the Delhi Sultanate?', 'Persian was the elite court language and bureaucratic administrative medium of the Delhi Sultanate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b80d3307-143b-4e70-bc16-5114171f1fb8', 'Persian (Farsi)', true, '110066bf-2e41-4f4a-b423-d7beb6190c96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbeab090-09fc-4ae9-ab8c-19f8e11341be', 'Arabic', false, '110066bf-2e41-4f4a-b423-d7beb6190c96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3002ee50-dc9a-4187-a025-d13c023e4027', 'Sanskrit', false, '110066bf-2e41-4f4a-b423-d7beb6190c96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a74a12a-f408-4793-a6ec-4dc8b64792d0', 'Urdu', false, '110066bf-2e41-4f4a-b423-d7beb6190c96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f22d4f0-078a-415d-9cda-2d37461834c4', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Why did author Ziauddin Barani criticize Sultan Muhammad Tughluq for appointing wine distillers, barbers, cooks, and gardeners to high administrative posts?', 'Barani''s conservative aristocratic perspective decried merit-based or non-noble appointments as a decline of imperial judgment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ce3aa82-33a9-490a-92a8-51cdabdb3e5d', 'Barani reflected aristocratic elite bias and lamented the loss of aristocratic monopoly over state power to low-born individuals', true, '0f22d4f0-078a-415d-9cda-2d37461834c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e82093e-bb62-41da-b0a4-710d30ac4f16', 'Because the appointees could not cook well', false, '0f22d4f0-078a-415d-9cda-2d37461834c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95a90dfd-8f74-470b-9f91-aac242d6275f', 'Because the appointees were foreigners from England', false, '0f22d4f0-078a-415d-9cda-2d37461834c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dbccc63-7a14-475c-b069-723caa1cf190', 'Because they refused to accept salaries', false, '0f22d4f0-078a-415d-9cda-2d37461834c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f31cf7bd-f863-43c9-9f52-8bd0832ae4d5', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b20d6cd-131d-4110-83ee-5bee5b755822', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'f31cf7bd-f863-43c9-9f52-8bd0832ae4d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2383e8b-bb0d-4520-850c-f652165b8ee5', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'f31cf7bd-f863-43c9-9f52-8bd0832ae4d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481496a4-745e-4647-8c6d-5713358ad348', '(A) is true, but (R) is false.', false, 'f31cf7bd-f863-43c9-9f52-8bd0832ae4d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2508c6ca-e9fe-4793-8671-5a0d29e961a5', '(A) is false, but (R) is true.', false, 'f31cf7bd-f863-43c9-9f52-8bd0832ae4d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53bf06db-e02f-490c-8b85-7603dd5fa23c', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'Spot the IMPOSTER in the comparative administrative strategies between Alauddin Khalji and Muhammad bin Tughluq:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('404a160e-5a52-4d8f-b13d-4263ffc019b7', 'Statement 1', false, '53bf06db-e02f-490c-8b85-7603dd5fa23c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21b869d1-9e74-49de-bf47-d2cb2b7259bd', 'Statement 2', false, '53bf06db-e02f-490c-8b85-7603dd5fa23c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d380cdf-7424-4d3e-b0f2-a5d3e595693a', 'Statement 3', false, '53bf06db-e02f-490c-8b85-7603dd5fa23c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45103888-3c3f-4e81-992f-c71cc68526d3', 'Statement 4 (Muhammad Tughluq used cheap TOKEN COPPER/BRASS coins, NOT diamond coins)', true, '53bf06db-e02f-490c-8b85-7603dd5fa23c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57e95aa1-4353-4c57-ae34-70d7a4f9fb63', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'Analyze the fiscal mechanics of the ''Iqta System'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e14b877-c5b6-4a22-814a-9244bbf541d6', 'Muqtis were allowed to collect ONLY the taxes assessed by the state and maintain strictly prescribed contingents of soldiers; imperial accountants (Amils) audited tax records annually', true, '57e95aa1-4353-4c57-ae34-70d7a4f9fb63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17f413bc-8363-4a98-9095-57632c94f332', 'Muqtis could take 100% of all village property', false, '57e95aa1-4353-4c57-ae34-70d7a4f9fb63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bec9ac1-59a8-4c9b-9f45-5373d8dea5df', 'Peasants were forbidden from farming', false, '57e95aa1-4353-4c57-ae34-70d7a4f9fb63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efcc9e93-02c6-4852-8e41-a1f2f6d6c658', 'No records were maintained', false, '57e95aa1-4353-4c57-ae34-70d7a4f9fb63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d8443e0-01aa-4dd1-874d-66a7af6d5c75', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'Match Column I (Sultanate Dynasties) with Column II (Prominent Rulers / Timeline):
(a) Mamluk / Early Turkish (1206-1290) -> (i) Qutbuddin Aibak, Iltutmish, Raziyya, Balban
(b) Khalji Dynasty (1290-1320)         -> (ii) Jalaluddin and Alauddin Khalji
(c) Tughluq Dynasty (1320-1414)        -> (iii) Ghiyasuddin, Muhammad bin Tughluq, Firuz Shah
(d) Lodi Dynasty (1451-1526)           -> (iv) Bahlul, Sikandar, and Ibrahim Lodi', 'Exact chronological matching of the ruling dynasties and foundational sultans of Delhi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dbf4fb1-1a3b-4ef7-8fb0-08a143aa078e', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '1d8443e0-01aa-4dd1-874d-66a7af6d5c75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('501758c6-1d03-4b9f-863e-ffbcca5646a0', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '1d8443e0-01aa-4dd1-874d-66a7af6d5c75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0351f1b-a21b-4c70-b9ac-920519f53a8b', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1d8443e0-01aa-4dd1-874d-66a7af6d5c75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69e766d5-f10d-435c-a5b2-ea798e10df19', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1d8443e0-01aa-4dd1-874d-66a7af6d5c75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('efa84173-73a9-49fd-96c6-9e72728b0fd7', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'Read the statements regarding military expansion of the Delhi Sultanate:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcec0e50-f9c6-4998-b4ed-e48c9b77f22e', 'Statements 1 and 2 only', true, 'efa84173-73a9-49fd-96c6-9e72728b0fd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65463817-669d-4331-8bc0-4c7c75c4bad1', 'Statements 2 and 3 only', false, 'efa84173-73a9-49fd-96c6-9e72728b0fd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8617226-9820-4391-93a0-4a07b588e347', 'Statements 1 and 3 only', false, 'efa84173-73a9-49fd-96c6-9e72728b0fd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c180c681-fef6-4867-983f-79c614631d95', 'All Statements 1, 2, and 3', false, 'efa84173-73a9-49fd-96c6-9e72728b0fd7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d217f4d-4ba8-4126-9489-f2565d35bda3', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'Why was the Battle of Panipat (1526 CE) a watershed turning point in Indian history?', 'First Battle of Panipat (21 April 1526): Babur''s matchlocks and field artillery annihilated Ibrahim Lodi''s forces, inaugurating the Mughal era.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dedd17b-4a2a-492e-aa33-ff045ce9d121', 'Babur (Mughal ruler of Kabul) defeated Ibrahim Lodi (last Sultan of Delhi), ending the 320-year Delhi Sultanate and founding the Mughal Empire', true, '7d217f4d-4ba8-4126-9489-f2565d35bda3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed32cdeb-dbba-43da-962b-4c3c6ec49f72', 'It established British rule in India', false, '7d217f4d-4ba8-4126-9489-f2565d35bda3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b422026-8a5d-42f2-8e86-2febe7c05c8f', 'It ended all wars in Asia forever', false, '7d217f4d-4ba8-4126-9489-f2565d35bda3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a5faade-63db-43d0-a061-8ab5c11d8b6f', 'It resulted in the partition of India', false, '7d217f4d-4ba8-4126-9489-f2565d35bda3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31daebbc-3b98-44b2-8fd5-f8a614e6e864', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'How did Queen Rudramadevi (1262–1289 CE) of the Kakatiya dynasty of Warangal navigate patriarchal prejudices compared to Raziyya Sultan?', 'Rudramadevi adopted the masculine title ''Rudradeva Maharaja'' on epigraphs to bypass patriarchal prejudices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7517233e-aade-4e9e-8700-f5cd7cea25a5', 'She changed her name on her royal inscriptions to pretend she was a man, adopting male persona to avoid social resistance to female kingship', true, '31daebbc-3b98-44b2-8fd5-f8a614e6e864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('933c514c-ea91-4c3b-b654-37aaa44d0cf6', 'She fled to another country', false, '31daebbc-3b98-44b2-8fd5-f8a614e6e864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c594adbb-25f8-4428-b0ed-763685ee1a79', 'She surrendered her throne to the Delhi Sultan', false, '31daebbc-3b98-44b2-8fd5-f8a614e6e864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4908ad20-b1ad-4791-b7bb-1c2b3d59f673', 'She banned all men from her kingdom', false, '31daebbc-3b98-44b2-8fd5-f8a614e6e864');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4240f29-0813-4373-8081-021719b9b3c0', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'What was the significance of ''Begumpuri Mosque'' built in the reign of Muhammad Tughluq?', 'Begumpuri Mosque was the monumental central congregational Jami mosque of Jahanpanah, Tughluq''s fourth medieval city of Delhi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c83f813c-b7b1-4902-bef5-fc184f6b2b75', 'It was the main congregational mosque of Jahanpanah, the ''Sanctuary of the World'', Sultan Muhammad Tughluq''s new capital in Delhi', true, 'e4240f29-0813-4373-8081-021719b9b3c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dd8447f-bea7-47e9-88fd-884093cd0833', 'It was built entirely of wood', false, 'e4240f29-0813-4373-8081-021719b9b3c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87dccd0c-72e0-42d6-bd0c-324b5922aad3', 'It was a Buddhist monastery', false, 'e4240f29-0813-4373-8081-021719b9b3c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f68d6334-4ca9-44be-b5a7-aeef1a393001', 'It was built by the British', false, 'e4240f29-0813-4373-8081-021719b9b3c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8dbeb392-de5c-4207-9126-c55406e05fac', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'Consider four key administrative elements introduced under Alauddin Khalji:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dcef08a-ce67-4bb6-a0d4-7e9495bea28c', 'To maximize imperial revenue extraction and maintain a massive, highly efficient, standing military machine capable of crushing Mongol invasions', true, '8dbeb392-de5c-4207-9126-c55406e05fac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d09429e5-2189-4072-81b7-6d7cab6b3b0e', 'To encourage foreign merchants to take over the empire', false, '8dbeb392-de5c-4207-9126-c55406e05fac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('885ad9ec-ef32-4ace-9143-80bed1025a8e', 'To eliminate all agriculture', false, '8dbeb392-de5c-4207-9126-c55406e05fac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bc2a91b-64d5-4d00-84a7-48c305c15728', 'To prepare for a pilgrimage to Mecca', false, '8dbeb392-de5c-4207-9126-c55406e05fac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d2c187d-69ab-40b7-9eea-babb6e0d8031', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'What was the social background of the authors of Tawarikh (Persian histories)?', 'Tawarikh chroniclers were urban court literati dependent on royal patronage, articulating aristocratic perspectives.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b587c96-98da-4deb-9e9f-a596698d365b', 'Learned urban men (secretaries, administrators, poets, courtiers) who lived in cities (mainly Delhi) and hardly ever in rural villages, writing histories to earn rich rewards from Sultans', true, '1d2c187d-69ab-40b7-9eea-babb6e0d8031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14fca8cb-4c6d-4e7f-899f-826383b1482f', 'Poor peasant farmers in remote villages', false, '1d2c187d-69ab-40b7-9eea-babb6e0d8031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3064b98d-dd47-4716-aed5-fe2d05ae39fc', 'Tribal forest nomads', false, '1d2c187d-69ab-40b7-9eea-babb6e0d8031');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('329fbd03-c7b2-40e8-b11c-d347122648dc', 'Foreign sailors on the ocean', false, '1d2c187d-69ab-40b7-9eea-babb6e0d8031');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6724b99-d45c-4bc8-a883-754e996cc866', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'Why did Ibn Battuta describe the fortress-like bamboo groves in India as impenetrable fortifications for local chieftains?', 'Ibn Battuta documented how dense indigenous bamboo thickets formed natural defensive bastions impenetrable to imperial cavalry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('888a8035-cf21-4f5a-a797-47f357f6f46f', 'Giant interlocking bamboo clumps were dense, tough, and fire-resistant; chieftains lived securely inside them with their cattle and crops, cut off from cavalry attacks', true, 'e6724b99-d45c-4bc8-a883-754e996cc866');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a5e7507-b499-43c4-88cd-36ad9a2a1875', 'Because bamboos shoot poisonous arrows', false, 'e6724b99-d45c-4bc8-a883-754e996cc866');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae001698-04ef-4c62-a6a2-ab4a4097ec0d', 'Because bamboos were made of iron', false, 'e6724b99-d45c-4bc8-a883-754e996cc866');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('123ddb44-e3d4-4aac-a9ca-78a2624eb60e', 'Because wild tigers guarded the bamboos', false, 'e6724b99-d45c-4bc8-a883-754e996cc866');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e593ac0e-f04a-403c-9125-823292bf9479', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Hard', 'What master historical transformation is traced in Chapter 3 of NCERT Class 7 History regarding Delhi?', 'Chapter 3 chronicles the political, architectural, and fiscal institutional evolution of Delhi into an imperial metropolis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8af25d9-c686-4329-9279-863a04b1807d', 'The transformation of Delhi from a minor regional Rajput trade post into the monumental imperial capital of a pan-subcontinental sultanate, creating new models of administrative centralization, fiscal taxation, and Indo-Islamic architectural grandeur', true, 'e593ac0e-f04a-403c-9125-823292bf9479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff05b160-6f34-4e13-8317-47bbbc708dbc', 'The complete abandonment of Delhi as a ruined ghost town', false, 'e593ac0e-f04a-403c-9125-823292bf9479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f19a092-e5cb-47cc-ac7a-6610d699018e', 'The conquest of Delhi by Roman emperors', false, 'e593ac0e-f04a-403c-9125-823292bf9479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f423c97-538e-4362-9905-036f21ec2ee5', 'The conversion of Delhi into a farming village', false, 'e593ac0e-f04a-403c-9125-823292bf9479');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11048f96-a765-474f-b051-e8632d9923ff', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'एक या एक से अधिक वर्णों के मेल से बने सार्थक एवं स्वतंत्र ध्वनि-समूह को व्याकरण में क्या कहते हैं?', 'वर्णों के सार्थक, व्यवस्थित और स्वतंत्र समूह को ''शब्द'' कहते हैं (जैसे: कमल, पुस्तक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('400a4032-b29f-446a-906a-11c6e30fff79', 'शब्द (Word)', true, '11048f96-a765-474f-b051-e8632d9923ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58a6cbbe-c05a-44a6-9a7b-2bf3b1c12d9b', 'वर्ण', false, '11048f96-a765-474f-b051-e8632d9923ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1851b098-f15b-4e1a-86ca-ae26610a7cdf', 'वाक्य', false, '11048f96-a765-474f-b051-e8632d9923ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71fe1684-f90f-4c92-b956-2fa74d831378', 'पद', false, '11048f96-a765-474f-b051-e8632d9923ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05456035-980a-4275-9c19-ecac4cae63a0', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'हिंदी व्याकरण में शब्दों का वर्गीकरण मुख्य रूप से कितने आधारों पर किया जाता है?', 'शब्दों का वर्गीकरण 4 आधारों पर होता है: उत्पत्ति (स्रोत), व्युत्पत्ति (रचना), अर्थ तथा रूप-परिवर्तन (प्रयोग)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb23d313-71f2-4a4e-b245-3825c0f69b9a', 'चार आधारों पर (1. उत्पत्ति / स्रोत के आधार पर, 2. रचना / बनावट के आधार पर, 3. अर्थ के आधार पर, 4. प्रयोग / विकार के आधार पर)', true, '05456035-980a-4275-9c19-ecac4cae63a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a45a9ad2-4fcb-4c4a-9e9e-512cdf22d73f', 'दो आधारों पर', false, '05456035-980a-4275-9c19-ecac4cae63a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a58dc8cf-45d3-44a4-901a-e0e61d280d4e', 'छह आधारों पर', false, '05456035-980a-4275-9c19-ecac4cae63a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c294b49c-2e25-46cd-b8c1-f61c46017ef9', 'तीन आधारों पर', false, '05456035-980a-4275-9c19-ecac4cae63a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9851d8a3-5629-4dd0-b5ec-d706a8c60cdf', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'संस्कृत भाषा के वे मूल शब्द जो बिना किसी परिवर्तन के अपने मूल रूप में हिंदी में ज्यों के त्यों प्रयुक्त होते हैं, उन्हें क्या कहते हैं?', 'तत् + सम (उसके समान): संस्कृत के अविकृत मूल शब्द ''तत्सम'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('996fbf82-6507-4324-98b4-08456dadd8b4', 'तत्सम शब्द (जैसे: अग्नि, सूर्य, दुग्ध, रात्रि, मयूर)', true, '9851d8a3-5629-4dd0-b5ec-d706a8c60cdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19d18d2c-37e5-4aeb-9437-83f5e73080b9', 'तद्भव शब्द', false, '9851d8a3-5629-4dd0-b5ec-d706a8c60cdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ae05671-6f00-4fd5-aea8-5087909de7c8', 'देशज शब्द', false, '9851d8a3-5629-4dd0-b5ec-d706a8c60cdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6936f85-6b9c-4559-b033-eb984b0174cc', 'विदेशी शब्द', false, '9851d8a3-5629-4dd0-b5ec-d706a8c60cdf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5067edae-1d28-42ac-9160-e0eff6ec07f5', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'संस्कृत भाषा के वे शब्द जो समय के साथ प्राकृत और अपभ्रंश से रूप बदलकर (परिवर्तित होकर) हिंदी में आए हैं, उन्हें क्या कहते हैं?', 'तत् + भव (उससे उत्पन्न): संस्कृत से रूप परिवर्तित होकर आए शब्द ''तद्भव'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3123da06-c561-4038-a71a-c88ba61e9a54', 'तद्भव शब्द (जैसे: आग, सूरज, दूध, रात, मोर)', true, '5067edae-1d28-42ac-9160-e0eff6ec07f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa1fd53a-a854-49df-9895-7f401fd25dbd', 'तत्सम शब्द', false, '5067edae-1d28-42ac-9160-e0eff6ec07f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6da8b280-90d5-4a88-a96c-a3f78862d72f', 'रूढ़ शब्द', false, '5067edae-1d28-42ac-9160-e0eff6ec07f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb457c4c-4c1f-4acd-8953-f2426ee21e38', 'योगरूढ़ शब्द', false, '5067edae-1d28-42ac-9160-e0eff6ec07f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb52ca28-38bb-46b7-a214-99cc9206129d', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'वे शब्द जो स्थानीय बोलियों और जनसाधारण की आवश्यकतानुसार भारत के विभिन्न क्षेत्रीय परिवेश में विकसित हुए हैं, उन्हें क्या कहते हैं?', 'देश में ही जनभाषा के प्रभाव से उत्पन्न देशी शब्द ''देशज'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('731c2c52-80ef-4065-bdfd-9a6bc0f3d90f', 'देशज शब्द (जैसे: लोटा, पगड़ी, खिड़की, डिबिया, खटिया)', true, 'eb52ca28-38bb-46b7-a214-99cc9206129d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23fec109-7214-461d-b6c1-cc7606165586', 'विदेशी शब्द', false, 'eb52ca28-38bb-46b7-a214-99cc9206129d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eab6c553-0358-49a7-8cbc-7af13763c6c0', 'तत्सम शब्द', false, 'eb52ca28-38bb-46b7-a214-99cc9206129d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c555fcf0-7727-4d60-b342-56f9ce6e897c', 'यौगिक शब्द', false, 'eb52ca28-38bb-46b7-a214-99cc9206129d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46bcf70b-2f09-4d22-acee-b07607fdff69', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'विदेशी भाषाओं (अंग्रेज़ी, अरबी, फ़ारसी, पुर्तगाली, तुर्की) से संपर्क के कारण हिंदी में आए शब्दों को क्या कहते हैं?', 'अन्य विदेशी भाषाओं से हिंदी शब्दकोश में समाहित शब्द ''आगत/विदेशी'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4878d884-9259-41d9-b848-ccf16e146fd9', 'विदेशी / आगत शब्द (जैसे: स्कूल, डॉक्टर, किताब, अखबार, साबुन, कैंची)', true, '46bcf70b-2f09-4d22-acee-b07607fdff69');
