INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f2476e5-9c85-4fbe-b28e-d1bcc724c66d', 'रूढ़ शब्द', false, '46bcf70b-2f09-4d22-acee-b07607fdff69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('740ea412-da61-48bf-b112-ea73e0c1ccb2', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'रचना (बनावट) के आधार पर शब्द के कितने भेद होते हैं?', 'व्युत्पत्ति/रचना के 3 भेद हैं: रूढ़ (अखंड), यौगिक (संयुक्त) तथा योगरूढ़ (विशिष्ट अर्थ में रूढ़)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d177c0b-37ae-4b12-882b-8c23171a9a63', 'तीन भेद (1. रूढ़ शब्द, 2. यौगिक शब्द, 3. योगरूढ़ शब्द)', true, '740ea412-da61-48bf-b112-ea73e0c1ccb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4acd0305-eea6-4bb0-9e22-15fd73abf1a3', 'दो भेद', false, '740ea412-da61-48bf-b112-ea73e0c1ccb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90d08a6e-1bb3-44a5-be74-1a665e1fcae5', 'चार भेद', false, '740ea412-da61-48bf-b112-ea73e0c1ccb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd877705-3e30-47df-9896-c9c3bf53a52b', 'पाँच भेद', false, '740ea412-da61-48bf-b112-ea73e0c1ccb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d8f04f8-0448-4695-b3e6-1c36b02c17bb', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'वे मूल शब्द जिनके सार्थक टुकड़े (खंड) नहीं किए जा सकते और जो किसी विशेष अर्थ में परंपरा से प्रसिद्ध हैं, उन्हें क्या कहते हैं?', 'जिन शब्दों के खंड निरर्थक होते हैं, वे ''रूढ़ शब्द'' कहलाते हैं (घ + र का कोई स्वतंत्र अर्थ नहीं)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('838d8d87-da79-4f07-97e2-58e11815eee5', 'रूढ़ शब्द (जैसे: घर, जल, हाथी, पेड़, नाक)', true, '3d8f04f8-0448-4695-b3e6-1c36b02c17bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb706861-2044-45ae-a972-a9276c65aecf', 'यौगिक शब्द', false, '3d8f04f8-0448-4695-b3e6-1c36b02c17bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0796a7ac-da6d-4340-9575-1e99785a0af8', 'योगरूढ़ शब्द', false, '3d8f04f8-0448-4695-b3e6-1c36b02c17bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdaf7062-7875-4d87-8c52-77e4fc0aea41', 'तत्सम शब्द', false, '3d8f04f8-0448-4695-b3e6-1c36b02c17bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63486f51-5175-49f3-acd0-2e338edce07a', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'दो या दो से अधिक सार्थक शब्दों या शब्दांशों के योग से बनने वाले शब्द क्या कहलाते हैं?', 'सार्थक खंडों के योग से बने नए शब्द ''यौगिक शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29fec157-b889-4883-b695-55f45e187cac', 'यौगिक शब्द (जैसे: विद्या + आलय = विद्यालय, देव + दूत = देवदूत)', true, '63486f51-5175-49f3-acd0-2e338edce07a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e2037f4-e218-453d-90e2-5e4ef14af236', 'रूढ़ शब्द', false, '63486f51-5175-49f3-acd0-2e338edce07a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adc27a25-2ffe-4e9a-9cd4-8e7e2f26f8e2', 'योगरूढ़ शब्द', false, '63486f51-5175-49f3-acd0-2e338edce07a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6bf3ab-217d-45f2-bbd3-8b4f65368b56', 'देशज शब्द', false, '63486f51-5175-49f3-acd0-2e338edce07a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8d46252-6a24-4e03-b1a9-6ebe6b5330e6', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'वे यौगिक शब्द जो अपने सामान्य अर्थ को छोड़कर किसी विशेष अर्थ (विशिष्ट रूढ़ अर्थ) के लिए प्रसिद्ध हो जाते हैं, उन्हें क्या कहते हैं?', 'यौगिक होकर भी किसी रूढ़ लाक्षणिक अर्थ को प्रकट करने वाले शब्द ''योगरूढ़'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12e8a037-5abb-404d-a5de-c66538a8369b', 'योगरूढ़ शब्द (जैसे: पंकज = कीचड़ में जन्मा कमल, दशानन = रावण, लंबोदर = गणेश)', true, 'a8d46252-6a24-4e03-b1a9-6ebe6b5330e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93daef39-bcd8-4498-a4f6-5a33cd8b2065', 'रूढ़ शब्द', false, 'a8d46252-6a24-4e03-b1a9-6ebe6b5330e6');
