INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa42ca6f-718c-49bd-946f-a87aa045059e', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'प्रयोग / व्याकरणिक प्रकार्य (विकार) के आधार पर शब्द के मुख्य रूप से दो भेद कौन-से होते हैं?', 'व्याकरणिक विकार के 2 भेद हैं: विकारी (संज्ञा, सर्वनाम, विशेषण, क्रिया) और अविकारी/अव्यय।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e939be55-de1f-45f2-885f-ea9b31e109f7', 'विकारी शब्द (Mutable) और अविकारी शब्द (Immutable / अव्यय)', true, 'fa42ca6f-718c-49bd-946f-a87aa045059e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f625aba6-ed72-4c03-9f2d-85564eee2b99', 'तत्सम और तद्भव', false, 'fa42ca6f-718c-49bd-946f-a87aa045059e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aa96cf7-f523-44d8-97ed-07e7d42594e3', 'सार्थक और निरर्थक', false, 'fa42ca6f-718c-49bd-946f-a87aa045059e');
