INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('425c2190-9880-4158-be56-90e1cd0a71d3', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'जिन शब्दों का रूप लिंग, वचन, कारक और काल के प्रभाव से बदल जाता है (परिवर्तित होता है), उन्हें क्या कहते हैं?', 'लिंग, वचन, कारक के अनुसार रूपांतरित होने वाले शब्द ''विकारी'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96637491-9f21-4100-89b7-7ec25d57e3a6', 'विकारी शब्द (जैसे: लड़का, लड़के, लड़कों ; पढ़ता है, पढ़ती है)', true, '425c2190-9880-4158-be56-90e1cd0a71d3');
