INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bd3ca2b-b932-45e8-8fbd-dc7615323e35', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'दो भिन्न भाषाओं के शब्दों के मेल से बने नवीन शब्द को व्याकरण में क्या कहते हैं?', 'दो भिन्न भाषाई स्रोतों से निर्मित द्वैत-भाषी शब्द ''संकर शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
