INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b3e02a9-f183-4f27-a40a-cd555962a27e', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'विकारी शब्द के अंतर्गत कौन-से चार व्याकरणिक भेद आते हैं?', 'चारों विकारी कोटियाँ हैं: संज्ञा, सर्वनाम, विशेषण और क्रिया।', NOW()) ON CONFLICT DO NOTHING;
