INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac49ae9b-034f-4158-bf8a-7325c5d83da5', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'अविकारी (अव्यय) शब्द के अंतर्गत कौन-से चार मुख्य भेद आते हैं?', 'अव्यय के 4 प्रमुख भेद: क्रियाविशेषण, संबंधबोधक, समुच्चयबोधक, विस्मयादिबोधक (तथा निपात)।', NOW()) ON CONFLICT DO NOTHING;
