INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46aa8d27-2ad1-45df-a136-eee7669e1827', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'अर्थ के आधार पर जिन शब्दों का एक निश्चित अर्थ निकलता है, उन्हें ''सार्थक'' कहते हैं ; जबकि जिनका कोई स्वतंत्र अर्थ नहीं होता (जैसे: पानी-वानी, चाय-वाय, रोटी-वोटी में ''वानी, वाय, वोटी'') उन्हें क्या कहते हैं?', 'जिन ध्वनियों का कोई स्वतंत्र शब्दकोशीय अर्थ नहीं होता, वे बोलचाल के ''निरर्थक शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
