INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07be4511-134e-47cf-a367-0bd805dd8e42', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'परस्पर विपरीत (उल्टा) अर्थ प्रकट करने वाले शब्दों (जैसे: सत्य - असत्य, अमृत - विष, अनुराग - विराग) को क्या कहते हैं?', 'विपरीत भाव/अर्थ देने वाले शब्द ''विलोम'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
