INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3b3d269-7b87-4728-a647-3efaa433520d', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'जिन शब्दों के एक से अधिक अर्थ होते हैं (जैसे: ''कर'' = हाथ, टैक्स, किरण, सूंड), उन्हें क्या कहते हैं?', 'प्रसंगानुसार भिन्न-भिन्न अर्थ देने वाले शब्द ''अनेकार्थी शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
