INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6384af41-98b9-4440-b3a0-831b5377d14c', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'fb3919fd-7695-4958-ac63-e2517b782d31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55f8d629-3ea5-4a1f-a447-4668f1021552', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'fb3919fd-7695-4958-ac63-e2517b782d31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75d6ebff-64cf-490f-97f6-8caaa6c44e31', '(A) सही है, परन्तु (R) गलत है।', false, 'fb3919fd-7695-4958-ac63-e2517b782d31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e129d5e8-10e5-457c-a765-345e3b34c95a', '(A) गलत है, परन्तु (R) सही है।', false, 'fb3919fd-7695-4958-ac63-e2517b782d31');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('033f1f0f-251b-45df-ab08-813c2924f189', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'Spot the IMPOSTER in the following group of तत्सम - तद्भव युग्मों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a669d9-649c-4827-9eee-30eddc23538e', 'युग्म 1', false, '033f1f0f-251b-45df-ab08-813c2924f189');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2fe059e-e3cf-4e96-b7a3-4c88feb5fbee', 'युग्म 2', false, '033f1f0f-251b-45df-ab08-813c2924f189');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6d00711-892e-4ec3-a9f8-77c43d8e5366', 'युग्म 3', false, '033f1f0f-251b-45df-ab08-813c2924f189');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f8387b1-c7fd-4959-a0bd-d018ed5129f9', 'युग्म 4 (अग्नि का तद्भव ''आग'' होता है, ''पानी'' नहीं)', true, '033f1f0f-251b-45df-ab08-813c2924f189');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6abfbdc0-44e5-43c7-942c-5377fda861c4', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'सुमेलित कीजिए (शब्द और उनका उत्पत्तिगत भाषाई स्रोत):
(क) कूप, दंत, मुख     -> (i) तत्सम शब्द (संस्कृत)
(ख) हाथ, कुआँ, दाँत    -> (ii) तद्भव शब्द
(ग) पगड़ी, लोटा, जूता  -> (iii) देशज शब्द
(घ) लालटेन, डॉक्टर, पेन-> (iv) विदेशी / आगत शब्द', 'कूप/दंत = तत्सम; हाथ/कुआँ = तद्भव; लोटा/पगड़ी = देशज; लालटेन (lantern)/पेन = विदेशी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53550bc8-18d5-4283-8fdd-42c59232a7d5', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '6abfbdc0-44e5-43c7-942c-5377fda861c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d101a5f-f2e0-4cab-8221-198b6f02c92e', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '6abfbdc0-44e5-43c7-942c-5377fda861c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44fc4317-ce4d-4254-a957-a30fcee23950', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '6abfbdc0-44e5-43c7-942c-5377fda861c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e04a76a0-deb0-4706-916f-067b5f3618b9', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '6abfbdc0-44e5-43c7-942c-5377fda861c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db9dd405-f158-410e-bd09-a8c01a87106e', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'श्रुतिसम भिन्नार्थक शब्दों ''कुल'' और ''कूल'' का क्रमशः शुद्ध अर्थ क्या है?', 'कुल (ह्रस्व उ) = वंश/समग्र; कूल (दीर्घ ऊ) = नदी का किनारा/तट।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bd5b318-d4a5-4c40-aa63-c74dc352c8e2', '''कुल'' = वंश / सब (Total/Family) ; ''कूल'' = किनारा / तट (Bank of river)', true, 'db9dd405-f158-410e-bd09-a8c01a87106e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c47e3939-fcca-4728-a063-c74322990eb1', '''कुल'' = ठंडा ; ''कूल'' = परिवार', false, 'db9dd405-f158-410e-bd09-a8c01a87106e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92c4d48f-1cad-4644-b8d5-cf14fe88ffff', '''कुल'' = किनारा ; ''कूल'' = वंश', false, 'db9dd405-f158-410e-bd09-a8c01a87106e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bba5f75-f9ed-4787-8406-067c0df970e3', 'दोनों का अर्थ ''पानी'' है', false, 'db9dd405-f158-410e-bd09-a8c01a87106e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13cf96a3-35db-4991-9fae-dee2e963809d', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'श्रुतिसम भिन्नार्थक शब्दों ''गृह'' और ''ग्रह'' का क्रमशः सही अर्थ क्या है?', 'गृह (ऋ की मात्रा) = आवास/घर; ग्रह (पदेन र) = आकाशीय खगोलीय पिंड (Planet)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('211799a4-b25b-422f-a70d-5547bc42e9cb', '''गृह'' = घर (House) ; ''ग्रह'' = आकाशीय पिंड / नक्षत्र (Planet - जैसे: सूर्य, मंगल)', true, '13cf96a3-35db-4991-9fae-dee2e963809d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fee22759-e59d-44a7-bc12-7175b98effc7', '''गृह'' = नक्षत्र ; ''ग्रह'' = घर', false, '13cf96a3-35db-4991-9fae-dee2e963809d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e38ab43a-15f2-409a-bb93-aa428fae893b', 'दोनों का अर्थ ''सूर्य'' है', false, '13cf96a3-35db-4991-9fae-dee2e963809d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acfee37e-0a8d-4d46-8b4f-332905944e43', 'दोनों का अर्थ ''दुकान'' है', false, '13cf96a3-35db-4991-9fae-dee2e963809d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('928c06bb-bb48-43df-937f-01e0425de253', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'अनेकार्थी शब्द ''कनक'' के तीन प्रमुख संदर्भगत अर्थ क्या हैं?', '''कनक कनक ते सौगुनी...'' कनक के प्रमुख अर्थ: स्वर्ण (सोना), धतूरा और गेहूँ हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03480b4a-214d-46ee-abcd-45709c02c0a7', 'सोना (Gold), धतूरा (Poisonous plant), और गेहूँ (Wheat)', true, '928c06bb-bb48-43df-937f-01e0425de253');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b935dca-e0bb-4af3-804e-68796078a01c', 'चाँदी, लोहा, और पीतल', false, '928c06bb-bb48-43df-937f-01e0425de253');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba653002-b5c5-44dc-b29b-f80384c4d628', 'पेड़, फल, और फूल', false, '928c06bb-bb48-43df-937f-01e0425de253');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('070a6c33-fb6f-4313-b599-d9ec064a9eec', 'आकाश, बादल, और वर्षा', false, '928c06bb-bb48-43df-937f-01e0425de253');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c590fad5-7de7-4fd8-8a08-88429d480241', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'अनेकार्थी शब्द ''अंबर'' के दो मुख्य अर्थ क्या हैं?', 'अंबर = नभ/गगन (आकाश) तथा वस्त्र/पट (कपड़ा - जैसे: पीतांबर)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d48358f3-61f0-4b83-bd40-62e3820067f1', 'आकाश (Sky) और वस्त्र / कपड़ा (Cloth)', true, 'c590fad5-7de7-4fd8-8a08-88429d480241');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19020aad-f359-4737-9b14-0cc8c05f861e', 'धरती और पाताल', false, 'c590fad5-7de7-4fd8-8a08-88429d480241');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b315f4bb-7b37-4eab-8f3d-496101cf3b92', 'पानी और आग', false, 'c590fad5-7de7-4fd8-8a08-88429d480241');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eac01ac5-3ed6-4db6-bb84-263a83a529e4', 'राजा और रानी', false, 'c590fad5-7de7-4fd8-8a08-88429d480241');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03a235a9-cd24-4b3d-a600-8f5f13d7487f', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'अरबी और फ़ारसी भाषा से हिंदी में आए शब्दों का कौन-सा समूह पूर्णतः शुद्ध है?', 'कानून/फैसला/तारीख = अरबी; कागज़/चश्मा/बाज़ार/शादी = फ़ारसी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e95c030-020d-43d2-806f-1cbe7559c890', 'अरबी: कानून, फैसला, अमीर, तारीख ; फ़ारसी: कागज़, चश्मा, ज़मीन, बाज़ार, शादी', true, '03a235a9-cd24-4b3d-a600-8f5f13d7487f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ea82bd8-d42d-4244-bcde-d1b5b8499a70', 'अरबी: स्कूल, पेन ; फ़ारसी: डॉक्टर, बस', false, '03a235a9-cd24-4b3d-a600-8f5f13d7487f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c4cce72-65c5-4a14-b617-3149931aa66f', 'अरबी: चाय, लीची ; फ़ारसी: रिक्शा, सुनामी', false, '03a235a9-cd24-4b3d-a600-8f5f13d7487f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ee8ab14-3628-4fab-9e7d-49ada47ce53b', 'अरबी: कुर्ता, कैंची ; फ़ारसी: तोप, बारूद', false, '03a235a9-cd24-4b3d-a600-8f5f13d7487f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec9494dc-6e41-4cd7-ab6c-8abbd55870a7', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'चीनी भाषा और जापानी भाषा से हिंदी में आए शब्दों का सही युग्म कौन-सा है?', 'चीनी मूल: चाय, लीची, चीकू; जापानी मूल: रिक्शा (Jinrikisha), सुनामी (Tsunami)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87681a45-86d0-4341-8b7a-3cbab6a4eb81', 'चीनी भाषा: चाय, लीची ; जापानी भाषा: रिक्शा, सुनामी', true, 'ec9494dc-6e41-4cd7-ab6c-8abbd55870a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b3a892c-23c0-4b51-98e7-09fecfd2152f', 'चीनी भाषा: साबुन, बाल्टी ; जापानी भाषा: स्कूल, बस', false, 'ec9494dc-6e41-4cd7-ab6c-8abbd55870a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61739404-bbac-42a2-942c-095d7a882860', 'चीनी भाषा: तोप, बारूद ; जापानी भाषा: वकील, अदालत', false, 'ec9494dc-6e41-4cd7-ab6c-8abbd55870a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c15bc04-3832-4d74-a3fd-bb76d3f3505a', 'चीनी भाषा: रोटी, पानी ; जापानी भाषा: घर, मकान', false, 'ec9494dc-6e41-4cd7-ab6c-8abbd55870a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52f158d4-2cd7-4995-bcca-59bc77b2de05', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'योगरूढ़ शब्दों में कौन-सा समास विशेष रूप से अंतर्निहित होता है?', 'सभी बहुव्रीहि समास के समस्त पद रचना की दृष्टि से ''योगरूढ़ शब्द'' होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b897b97f-1dfa-49a2-b9b3-9214c5b3b439', 'बहुव्रीहि समास (जिसमें दोनों पद मिलकर किसी तीसरे अन्य पद की विशेषता बताते हैं, जैसे: चक्रपाणि = विष्णु)', true, '52f158d4-2cd7-4995-bcca-59bc77b2de05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('783aace7-f9bb-47b7-8dd3-ddf0e3f60950', 'द्वंद्व समास', false, '52f158d4-2cd7-4995-bcca-59bc77b2de05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49d6f7ad-efbc-4641-b2e5-75ee3e7201f2', 'अव्ययीभाव समास', false, '52f158d4-2cd7-4995-bcca-59bc77b2de05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('230a4a46-3320-424d-bb52-1d17a2780a6d', 'द्विगु समास', false, '52f158d4-2cd7-4995-bcca-59bc77b2de05');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6333dc0a-085c-46fe-b129-915524c5ac60', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'संकर शब्दों की शुद्ध संरचना पहचानीए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45d4a3d2-f902-410b-a99c-4e7557ef6319', 'संस्कृत (''छाया'') + फ़ारसी प्रत्यय (''दार'') = छायादार', true, '6333dc0a-085c-46fe-b129-915524c5ac60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18f2f5cb-828b-4eb8-a01c-77de677e4f32', 'अंग्रेज़ी + हिंदी', false, '6333dc0a-085c-46fe-b129-915524c5ac60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5450ece0-5858-4442-9c10-72c3b5cd3fe0', 'अरबी + तुर्की', false, '6333dc0a-085c-46fe-b129-915524c5ac60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8e4aff2-3409-4e7e-936c-b1915777b584', 'पुर्तगाली + जापानी', false, '6333dc0a-085c-46fe-b129-915524c5ac60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9584d2c-4b0d-4ef0-8852-1b97a41b0552', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'शब्द विचार (Morphology) के विशद अध्ययन का भाषा प्रयोग में क्या केंद्रीय निष्कर्ष है?', 'अध्याय 3 हिंदी की समावेशी बहु-सांस्कृतिक शब्द-संपदा, व्युत्पत्ति-सौंदर्य और समृद्ध पद-विन्यास को प्रतिपादित करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09eae9b3-5a2f-4157-9cd6-1de91226a2f7', 'हिंदी शब्द संपदा एक अविरल प्रवाहमयी नदी के समान है, जिसने संस्कृत की तत्सम-तद्भव परंपरा, देशज बोलियों की मौलिकता और विदेशी भाषाओं के आगत शब्दों को आत्मसात कर अद्भुत अभिव्यक्ति-क्षमता प्राप्त की है', true, 'd9584d2c-4b0d-4ef0-8852-1b97a41b0552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf84536-3c8f-4e81-bd26-98d424ff0927', 'शब्दों का केवल एक ही अर्थ होना चाहिए', false, 'd9584d2c-4b0d-4ef0-8852-1b97a41b0552');
