INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17921da6-372a-4333-a572-195989cc4e69', 'शब्द विचार केवल प्राथमिक स्तर की पढ़ाई है', false, 'd9584d2c-4b0d-4ef0-8852-1b97a41b0552');
