INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e780b21-56d7-489b-8422-719ed7e7290f', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Easy', 'What is the chemical name of the base ''Milk of Magnesia'' commonly used as an Antacid for relieving acidity?', 'Milk of Magnesia is a mild suspension of Magnesium Hydroxide [Mg(OH)₂].', NOW()) ON CONFLICT DO NOTHING;
