INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69d3a15d-69bc-4c8d-b3e9-829c14dc714c', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Easy', 'What color does the synthetic indicator Phenolphthalein show in a BASIC solution?', 'Phenolphthalein turns vivid pink in alkaline/basic solutions (pH > 8.2) and remains colorless in acidic solutions.', NOW()) ON CONFLICT DO NOTHING;
