INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63d872ec-3296-4a1f-8f09-f75f065b9e76', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Easy', 'What is the chemical name of Slaked Lime / Lime Water used to test carbon dioxide?', 'Lime water is a saturated aqueous solution of Calcium Hydroxide [Ca(OH)₂].', NOW()) ON CONFLICT DO NOTHING;
