INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a02e4abf-4c4c-4318-80de-a9a40a16083f', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What happens when a yellow turmeric stain on a white shirt is scrubbed with washing SOAP?', 'Curcumin in turmeric acts as a natural indicator, shifting from yellow to reddish-brown in basic alkaline media (soap).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccbafca9-88e4-4ca3-86b7-d632fa479ccf', 'The yellow turmeric stain turns REDDISH-BROWN because soap is basic in nature; when washed with plenty of water, it turns yellow again', true, 'a02e4abf-4c4c-4318-80de-a9a40a16083f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53bd7c5e-8615-483c-afc0-00f9ba15ab1c', 'The stain turns blue', false, 'a02e4abf-4c4c-4318-80de-a9a40a16083f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('565f773e-3302-4d04-8c82-6d2872dae076', 'The stain disappears completely', false, 'a02e4abf-4c4c-4318-80de-a9a40a16083f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82566388-95f2-41ca-b309-9ae232f99009', 'The shirt catches fire', false, 'a02e4abf-4c4c-4318-80de-a9a40a16083f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad8d32f0-2a42-456d-941c-41bcc19a7e5f', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'How does natural China Rose (Hibiscus) indicator change color in acidic and basic solutions?', 'China rose anthocyanin extract turns acidic solutions dark magenta/pink and basic solutions bright green.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('723f35ce-a0fb-44e6-83ec-414eb71f8484', 'Turns ACIDIC solutions to DARK PINK (Magenta) and BASIC solutions to GREEN', true, 'ad8d32f0-2a42-456d-941c-41bcc19a7e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f29ba66-6222-4f75-9d50-384ab3ed4a6f', 'Turns acidic to green and basic to pink', false, 'ad8d32f0-2a42-456d-941c-41bcc19a7e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c88d2f3-961e-4a9d-91c5-535c913d0b62', 'Turns both solutions blue', false, 'ad8d32f0-2a42-456d-941c-41bcc19a7e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca2e75e-33dc-40bf-85d9-517e2274d485', 'Shows no color change in either', false, 'ad8d32f0-2a42-456d-941c-41bcc19a7e5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0270985a-9f2f-4012-82c7-b9a33d9ef4d7', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Why is Calamine lotion (containing Zinc Carbonate) or moist Baking Soda applied to skin after an Ant bite?', 'Basic calamine (ZnCO₃) or sodium hydrogen carbonate (NaHCO₃) chemically neutralizes injected acidic formic acid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4af0cfa-2a22-4240-b19e-cc7a9da5cbeb', 'Zinc carbonate and baking soda are mild BASES that neutralize the acidic formic acid injected by the ant bite, relieving pain', true, '0270985a-9f2f-4012-82c7-b9a33d9ef4d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7706946-26c9-40e8-8f73-05ce3492a866', 'To kill the ant', false, '0270985a-9f2f-4012-82c7-b9a33d9ef4d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('291b401e-7bef-459f-8e2a-f2029d057b19', 'Because calamine is an acid', false, '0270985a-9f2f-4012-82c7-b9a33d9ef4d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('010da14d-53a5-4b56-8333-8a4a0eb6e18c', 'To make the skin waterproof', false, '0270985a-9f2f-4012-82c7-b9a33d9ef4d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c6982ff-3765-4798-8e56-fe69fade0517', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Why must agricultural soil that has become too ACIDIC due to excessive chemical fertilizer use be treated with Quicklime (Calcium Oxide) or Slaked Lime (Calcium Hydroxide)?', 'Liming agricultural soil neutralizes toxic soil acidity, optimizing nutrient uptake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('744760d0-8e96-4e38-878c-264b67c67e2a', 'Quicklime and slaked lime are BASES that neutralize soil acidity, restoring the optimal neutral pH for healthy plant root growth', true, '1c6982ff-3765-4798-8e56-fe69fade0517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fdf0830-ad5f-42ab-b740-2602cc629038', 'To add color to the soil', false, '1c6982ff-3765-4798-8e56-fe69fade0517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('587ab915-bc24-415a-b51b-cbdd307bc21a', 'To kill earthworms', false, '1c6982ff-3765-4798-8e56-fe69fade0517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd90e6c2-092d-41d6-8b8c-40a16f4d2897', 'To make the soil sandy', false, '1c6982ff-3765-4798-8e56-fe69fade0517');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ab8d49e-00c5-4a24-b280-7a2e158af461', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'If agricultural soil is too BASIC (alkaline), what is added to improve soil fertility?', 'Decaying organic compost/manure releases humic and fulvic acids, neutralizing alkaline soil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99b8276a-b4fd-470e-aa9d-2a9de557cb3d', 'Organic Matter / Manure (which decomposes to release natural acids that neutralize the basic soil)', true, '7ab8d49e-00c5-4a24-b280-7a2e158af461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4826f1e-db1d-4fea-a5ff-a1c3a62384df', 'More quicklime', false, '7ab8d49e-00c5-4a24-b280-7a2e158af461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f33000b3-d435-4044-bc1d-a55cd49516a6', 'Baking soda', false, '7ab8d49e-00c5-4a24-b280-7a2e158af461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e476342-a22e-405c-b702-b3b5688af7cb', 'Bleaching powder', false, '7ab8d49e-00c5-4a24-b280-7a2e158af461');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b51073a-968f-4b56-bffe-c4929f488f57', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Why must acidic factory effluents and industrial chemical waste be strictly treated with basic substances before being discharged into rivers?', 'Neutralization of industrial effluents prevents aquatic ecotoxicity and preserves aquatic biodiversity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95e37f38-6409-49a7-a8bc-17db82a6d5c8', 'Untreated acidic waste drastically lowers river water pH, poisoning and killing fish, aquatic organisms, and destroying freshwater ecosystems', true, '2b51073a-968f-4b56-bffe-c4929f488f57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce0531d2-8731-4d26-9d0f-7c9380ddb67e', 'To change the color of river water to red', false, '2b51073a-968f-4b56-bffe-c4929f488f57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1655736-93e7-40bf-b8a2-9c1f8ef15fcf', 'To make water boil', false, '2b51073a-968f-4b56-bffe-c4929f488f57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60d380a9-62fd-4a65-94ec-503f74c45363', 'Because fish like drinking base', false, '2b51073a-968f-4b56-bffe-c4929f488f57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41943a59-1818-4161-b43f-a249449cf50e', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What is ''Acid Rain'' and what atmospheric pollutant gases cause it?', 'Atmospheric SO₂ and NO₂ form H₂SO₄ and HNO₃, causing acid precipitation (pH < 5.6) damaging monuments (Taj Mahal marble cancer).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffeddf25-dd30-472d-9368-e2ec6ac72157', 'Rain containing excessive dissolved acids formed when atmospheric pollutants like Sulfur Dioxide (SO₂) and Nitrogen Dioxide (NO₂) react with rain droplets to form Sulfuric and Nitric acids', true, '41943a59-1818-4161-b43f-a249449cf50e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('366963a7-c9db-4f80-861d-9ba92b955893', 'Rain of pure hydrochloric acid falling from clouds', false, '41943a59-1818-4161-b43f-a249449cf50e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cc3fc5d-0bbe-4eca-a8fa-c253083184bf', 'Rain caused by burning wood only', false, '41943a59-1818-4161-b43f-a249449cf50e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('095134ea-55fe-45bc-b3dc-cbab1256dd3b', 'Rain containing lemon juice', false, '41943a59-1818-4161-b43f-a249449cf50e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52e32354-7d0e-44fc-a0a8-332d34c6308f', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What organic acid is naturally found in Tamarind (Imli), unripened green Grapes, and raw Mangoes?', 'Tartaric acid is a dicarboxylic organic acid abundant in tamarind and unripe grapes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e412b1a3-9d04-4235-9ce9-1607bb20ef66', 'Tartaric Acid', true, '52e32354-7d0e-44fc-a0a8-332d34c6308f');
