INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6428f30-d293-4eb8-bae7-db99b7ba0403', 'Lactic Acid', false, '52e32354-7d0e-44fc-a0a8-332d34c6308f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('725857b6-5623-4726-a775-d08ab0c240d2', 'Oxalic Acid', false, '52e32354-7d0e-44fc-a0a8-332d34c6308f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17976e45-de33-4ad7-86d5-3c2fb24aeb4e', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What acid is naturally present in Spinach (Palak) and Tomatoes?', 'Spinach and tomatoes contain naturally occurring Oxalic Acid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5853ee40-977e-4d00-9729-1d1a8a963d80', 'Oxalic Acid', true, '17976e45-de33-4ad7-86d5-3c2fb24aeb4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05fcfdae-e240-44e8-9d49-dd29ffb3ca0c', 'Citric Acid', false, '17976e45-de33-4ad7-86d5-3c2fb24aeb4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7725ee88-0eb9-4cdd-8e78-a5d7a03e3587', 'Formic Acid', false, '17976e45-de33-4ad7-86d5-3c2fb24aeb4e');
