INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('390f7f65-1e5d-4b7c-9345-ee5fdaac2a6a', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What is the chemical name and formula of Common Salt used in daily food?', 'Common table salt is Sodium Chloride (NaCl), formed by neutralizing HCl with NaOH.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ee2f546-858e-4b5b-8973-e127420d40d2', 'Sodium Chloride (NaCl)', true, '390f7f65-1e5d-4b7c-9345-ee5fdaac2a6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3198575c-20e8-4610-8955-ab026df60629', 'Sodium Bicarbonate (NaHCO₃)', false, '390f7f65-1e5d-4b7c-9345-ee5fdaac2a6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19be76f0-d598-4891-b7b1-ba8f895f4703', 'Calcium Chloride (CaCl₂)', false, '390f7f65-1e5d-4b7c-9345-ee5fdaac2a6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c395b35-6944-42b9-aa5a-e5c47cdbf7fd', 'Potassium Chloride (KCl)', false, '390f7f65-1e5d-4b7c-9345-ee5fdaac2a6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d485f3e-05c7-4e97-b7d5-c4b483da73d3', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What happens to the temperature of the reaction mixture during a Neutralization Reaction in a test tube?', 'Enthalpy of neutralization: H⁺(aq) + OH⁻(aq) → H₂O(l) + 57.3 kJ/mol (exothermic heat release).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fb60661-d087-4103-bdf5-382071c6a10a', 'The temperature INCREASES (the test tube feels hot because neutralization is an exothermic reaction that releases heat energy)', true, '5d485f3e-05c7-4e97-b7d5-c4b483da73d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91906d7b-e65f-45bf-9565-26817a274a7d', 'The temperature decreases and turns into ice', false, '5d485f3e-05c7-4e97-b7d5-c4b483da73d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d42bd27a-a57c-4253-b217-d094a8fb10a8', 'The temperature remains exactly unchanged', false, '5d485f3e-05c7-4e97-b7d5-c4b483da73d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3255278d-9bd3-44df-92f2-6f9b3a8e3689', 'The mixture catches fire instantly', false, '5d485f3e-05c7-4e97-b7d5-c4b483da73d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b1812b8-ebbe-4e37-84fa-301c611ef6ce', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Which base is used in window-cleaning fluids and glass sprays?', 'Ammonium hydroxide [NH₄OH] dissolves grease cleanly without leaving residue on glass windows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31d74d4c-f175-45ff-b3c7-48a2d3f6e7b1', 'Ammonium Hydroxide [NH₄OH]', true, '4b1812b8-ebbe-4e37-84fa-301c611ef6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5aa01cb-912c-499c-966a-a6dd242488da', 'Sodium Hydroxide [NaOH]', false, '4b1812b8-ebbe-4e37-84fa-301c611ef6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0a4a234-6ca9-4e1b-bbb8-8b292f0bf3df', 'Calcium Hydroxide [Ca(OH)₂]', false, '4b1812b8-ebbe-4e37-84fa-301c611ef6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b627d44b-2585-4160-97bd-72f6185c834c', 'Magnesium Hydroxide [Mg(OH)₂]', false, '4b1812b8-ebbe-4e37-84fa-301c611ef6ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('948c8083-a004-4dca-9294-23984795c80c', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Which strong base is used in manufacturing hard bar soaps and unclogging drain pipes?', 'Sodium hydroxide (NaOH / caustic soda) saponifies fats in soap making and dissolves organic drain blockages.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6361d78-626d-4a93-b4fc-6d2442daa392', 'Sodium Hydroxide (Caustic Soda - NaOH)', true, '948c8083-a004-4dca-9294-23984795c80c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6764415c-3703-40b4-a91b-1761c2326eae', 'Lactic Acid', false, '948c8083-a004-4dca-9294-23984795c80c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42331a64-0be8-45fb-8832-7ae81e8a0c4a', 'Magnesium Hydroxide', false, '948c8083-a004-4dca-9294-23984795c80c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('445af126-8610-4d7b-8898-2b13bcdcdc4e', 'Ammonium Hydroxide', false, '948c8083-a004-4dca-9294-23984795c80c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7992d7ac-34b2-4d5f-8b74-7fa0b13a9af7', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What is the nature of a solution that shows NO color change on both Red Litmus paper and Blue Litmus paper?', 'Neutral solutions (pH = 7) exhibit no proton exchange with litmus dye, causing zero color change.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a485bbb7-8c27-4a1c-8c00-b8bbf2c3f7fb', 'Neutral Solution (such as pure distilled water, sugar solution, or common salt solution)', true, '7992d7ac-34b2-4d5f-8b74-7fa0b13a9af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c7f3c6c-3f09-4537-b126-5d4ece4aab93', 'Strongly Acidic Solution', false, '7992d7ac-34b2-4d5f-8b74-7fa0b13a9af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1f7d772-c849-4ffd-87c2-36c56d9aabdc', 'Strongly Basic Solution', false, '7992d7ac-34b2-4d5f-8b74-7fa0b13a9af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee5201b0-319a-4c49-836c-e331bc352454', 'Corrosive Acid', false, '7992d7ac-34b2-4d5f-8b74-7fa0b13a9af7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f90f905b-3ada-452f-ad77-875a17b9427f', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What is Ascorbic Acid commonly known as in human nutrition?', 'Ascorbic acid is Vitamin C, found abundantly in amla (Indian gooseberry) and citrus fruits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ceaa4e44-c791-4aa8-a610-f3737bbfa038', 'Vitamin C (essential for immune health and preventing scurvy)', true, 'f90f905b-3ada-452f-ad77-875a17b9427f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cc8e93b-6610-4e9e-850e-28a13b58fc01', 'Vitamin A', false, 'f90f905b-3ada-452f-ad77-875a17b9427f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f98f2484-ff1d-4074-9a75-61d80ea64e9e', 'Vitamin D', false, 'f90f905b-3ada-452f-ad77-875a17b9427f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('112ee40b-d951-46c4-a155-7a22e9d74635', 'Vitamin B12', false, 'f90f905b-3ada-452f-ad77-875a17b9427f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f191c4e4-a509-476d-94a9-28ff1248530f', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What happens when dilute Hydrochloric Acid (HCl) is mixed with Sodium Hydroxide (NaOH) in equal proportions?', 'Equimolar strong acid-strong base neutralization yields neutral aqueous NaCl and water: HCl + NaOH → NaCl + H₂O + ΔH.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03540f4b-0706-4f23-a0ec-e8495fa685cb', 'They neutralize each other completely to produce neutral Sodium Chloride (NaCl), Water (H₂O), and heat: HCl + NaOH -> NaCl + H₂O', true, 'f191c4e4-a509-476d-94a9-28ff1248530f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d28df1a-7198-40ec-b3ed-a6fc0559ef36', 'They produce poisonous chlorine gas only', false, 'f191c4e4-a509-476d-94a9-28ff1248530f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a573d457-daaf-4b75-af67-caaef3b1f3ce', 'They turn into pure alcohol', false, 'f191c4e4-a509-476d-94a9-28ff1248530f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('591053f4-c959-43c2-9948-55d36fcb21a7', 'They freeze into solid dry ice', false, 'f191c4e4-a509-476d-94a9-28ff1248530f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f88b8d60-ad54-450c-8321-f97b9b372a4a', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bed8747-6dac-4d09-93ae-1f8e0b86140b', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'f88b8d60-ad54-450c-8321-f97b9b372a4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a988b6e-9eeb-4887-86ba-b82d78078d40', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'f88b8d60-ad54-450c-8321-f97b9b372a4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae6c366e-5a9f-47a8-8b1e-fc0445949fd2', '(A) is true, but (R) is false.', false, 'f88b8d60-ad54-450c-8321-f97b9b372a4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74ded789-3af3-40e3-99d3-b4fbcaaecc19', '(A) is false, but (R) is true.', false, 'f88b8d60-ad54-450c-8321-f97b9b372a4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e10dd439-69ce-4749-9c16-66fe13ff36e3', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Spot the IMPOSTER in the following group of naturally occurring organic acids and their biological sources:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1bfeb3c-8a75-4e79-b4fd-2572385594c1', 'Pair 1', false, 'e10dd439-69ce-4749-9c16-66fe13ff36e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca7b1989-a2a7-46eb-b663-21bdeba1c372', 'Pair 2', false, 'e10dd439-69ce-4749-9c16-66fe13ff36e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('238b13b2-6d2a-4de2-a56f-1f070c225bd8', 'Pair 3', false, 'e10dd439-69ce-4749-9c16-66fe13ff36e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2725ba64-9514-4721-994e-b390821ae56d', 'Pair 4 (Lemon contains CITRIC ACID, NOT mineral Hydrochloric Acid)', true, 'e10dd439-69ce-4749-9c16-66fe13ff36e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2051987f-56d0-47cb-beec-3dd2f3849436', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'A student is given three unlabeled test tubes containing: (A) Dilute Hydrochloric Acid, (B) Sodium Hydroxide solution, and (C) Distilled Water. She has ONLY Phenolphthalein indicator. How can she identify all three liquids?', 'Sequential titration logic: base triggers pink chromophore; acid neutralizes pink back to colorless; water maintains diluted pink.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2a5727e-2ce3-4089-84f7-b50455443e30', 'Add phenolphthalein to all 3: tube turning PINK is Base (B) ; mix pink solution into remaining two: the one that de-colorizes pink back to colorless is Acid (A), and the one that simply dilutes pink is Water (C)', true, '2051987f-56d0-47cb-beec-3dd2f3849436');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7791fc84-9845-497e-a8c0-ec0b1084eb49', 'Drink all three liquids to taste them', false, '2051987f-56d0-47cb-beec-3dd2f3849436');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1835d130-6b6b-4a65-a51e-3855161ffdc9', 'Heat all three until they explode', false, '2051987f-56d0-47cb-beec-3dd2f3849436');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f951c84a-4f1b-43fe-bfd4-c2a54bb935cf', 'Phenolphthalein cannot identify them without litmus', false, '2051987f-56d0-47cb-beec-3dd2f3849436');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56edcb14-c9ed-4a05-acd9-df6034eef80e', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Match Column I (Natural Indicators) with Column II (Color in Acid vs Base):
(a) Litmus Paper         -> (i) Red in Acid ; Blue in Base
(b) Turmeric Paste       -> (ii) Yellow in Acid ; Reddish-brown in Base
(c) China Rose Extract   -> (iii) Dark Pink/Magenta in Acid ; Green in Base
(d) Phenolphthalein      -> (iv) Colorless in Acid ; Pink in Base', 'Litmus = Red/Blue; Turmeric = Yellow/Red-brown; China rose = Magenta/Green; Phenolphthalein = Colorless/Pink.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea82ea76-e6c2-444f-bf23-69ba65663c15', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '56edcb14-c9ed-4a05-acd9-df6034eef80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('066da6d9-fa4c-4222-af21-8c04e03e411e', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '56edcb14-c9ed-4a05-acd9-df6034eef80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05e47376-a30b-4ce6-8880-22a64954201a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '56edcb14-c9ed-4a05-acd9-df6034eef80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff2c5853-75d4-4621-bd89-d18b3c4e4a11', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '56edcb14-c9ed-4a05-acd9-df6034eef80e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4f10e11-d9f3-44c4-b086-636fe04e8c07', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Read the statements regarding salts formed in neutralization reactions:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b91c9f94-0238-4567-8767-6df5ad3c35c7', 'Statements 1 and 2 only', true, 'c4f10e11-d9f3-44c4-b086-636fe04e8c07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba62cc2c-4465-43e8-9754-d7855d46a5de', 'Statements 2 and 3 only', false, 'c4f10e11-d9f3-44c4-b086-636fe04e8c07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c6f8b08-4054-416e-b878-3b70bb6e2f50', 'Statements 1 and 3 only', false, 'c4f10e11-d9f3-44c4-b086-636fe04e8c07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f87d3933-2e58-41f7-ba89-1ee60ed95094', 'All Statements 1, 2, and 3', false, 'c4f10e11-d9f3-44c4-b086-636fe04e8c07');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('852a5b15-6be4-497b-aa6d-4ad82e698d9b', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Why should sour and acidic foodstuffs (such as curd, pickles, lemon juice, vinegar) NEVER be stored in Brass, Copper, or Bronze metal containers?', 'Acidic corrosion of copper/brass yields toxic verdigris and cupric/zinc salts, causing heavy metal toxicity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57651bab-4720-48a4-a941-70b641911eaa', 'Organic acids react with copper and zinc to form toxic, poisonous metallic salts that can cause severe food poisoning', true, '852a5b15-6be4-497b-aa6d-4ad82e698d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fe832c9-59b2-4cc1-b3d0-63561cfe98c1', 'Because curd makes brass melt into water', false, '852a5b15-6be4-497b-aa6d-4ad82e698d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3e67c75-b3e9-4933-a94f-310215a63304', 'Because brass makes curd taste like honey', false, '852a5b15-6be4-497b-aa6d-4ad82e698d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f19bde35-9baf-4fed-8425-5dde6b32c30c', 'Because copper turns into gold in acid', false, '852a5b15-6be4-497b-aa6d-4ad82e698d9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e657d15d-8347-4421-b381-d420c163f341', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'What is the difference between an ''Organic Acid'' and a ''Mineral Acid''?', 'Organic acids contain carbon carboxylic chains (weak electrolytes); mineral acids are inorganic strong protic acids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6128bc8-8739-4621-baca-62f09cb653fa', 'Organic acids are naturally occurring weak acids derived from plants and animals (e.g. citric, lactic, acetic) ; Mineral acids are strong synthetic laboratory acids derived from minerals (e.g. HCl, H₂SO₄, HNO₃)', true, 'e657d15d-8347-4421-b381-d420c163f341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('448de23f-dd82-42b4-971b-6e5a60cc2bf4', 'Organic acids are made of rock, mineral acids are made of water', false, 'e657d15d-8347-4421-b381-d420c163f341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77d650b8-af97-428f-a7fa-47f2f266fd57', 'Mineral acids can be safely drunk by humans', false, 'e657d15d-8347-4421-b381-d420c163f341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4cfacd8-129c-4153-883f-d8d23f8a2942', 'Both are identical in chemical strength', false, 'e657d15d-8347-4421-b381-d420c163f341');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c0570e1-f80d-4b58-a24c-7b55ca08dbc2', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Consider four household substances:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7fea40c-f044-46b2-83cd-b14eaeb340db', 'Substances 2 and 4 (Soap solution and Baking soda solution, because both are basic)', true, '0c0570e1-f80d-4b58-a24c-7b55ca08dbc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dc43012-34cd-4a39-8ead-6f05befae398', 'Substances 1 and 3', false, '0c0570e1-f80d-4b58-a24c-7b55ca08dbc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e429863-b0f4-4d40-9d21-219d119e8de9', 'Substance 1 only', false, '0c0570e1-f80d-4b58-a24c-7b55ca08dbc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2c283a0-4fd2-44e2-bc5b-dae3a239e2fc', 'Substance 3 only', false, '0c0570e1-f80d-4b58-a24c-7b55ca08dbc2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20d62657-1fd6-4507-ad18-74e35a5b2851', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Why does adding a few drops of universal indicator to a solution provide far more diagnostic information than litmus paper?', 'Universal indicator displays a multi-spectral chromatic gradient mapping directly to the continuous 0–14 pH scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27b8e9bb-814e-4ea1-8481-21e3ceb840de', 'Universal indicator is a blend of indicators that displays a continuous spectrum of colors corresponding to specific pH values from 0 to 14, indicating exact strength rather than just acid/base binary', true, '20d62657-1fd6-4507-ad18-74e35a5b2851');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('face2794-df4b-4bcb-9fe6-e1074447fcd4', 'Because universal indicator is made of silver', false, '20d62657-1fd6-4507-ad18-74e35a5b2851');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('072603dd-1392-4a4b-9ecb-5696847127bc', 'Because litmus paper works only in sunlight', false, '20d62657-1fd6-4507-ad18-74e35a5b2851');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b3f4d6f-1ca2-415b-8ee6-810d38009520', 'Because universal indicator turns everything gold', false, '20d62657-1fd6-4507-ad18-74e35a5b2851');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e4ab40e-a9c5-4a0d-b853-61eeb8aed10a', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Why does our stomach produce Hydrochloric Acid (HCl) naturally during digestion, and why does Hyperacidity require antacids?', 'Physiological balance: gastric parietal cells secrete HCl for pepsinogen activation; hyperchlorhydria is buffered via basic antacids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('592ff4d2-3868-4d57-9e9b-4d8ca4a2183e', 'Gastric HCl creates an optimal acidic environment (pH ~1.5) for the protein enzyme pepsin; excess acid secretion causes painful gastritis and heartburn, requiring basic antacids (Mg(OH)₂) to neutralize excess H⁺ ions', true, '9e4ab40e-a9c5-4a0d-b853-61eeb8aed10a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84277f3f-9b92-4e55-9373-8c51aa9ca8a0', 'HCl is produced to burn bones', false, '9e4ab40e-a9c5-4a0d-b853-61eeb8aed10a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54f757a3-0165-4e02-85d7-966614bc570e', 'Antacids turn stomach acid into milk', false, '9e4ab40e-a9c5-4a0d-b853-61eeb8aed10a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89ae05a2-4777-4a25-941d-11835dcba6a1', 'The stomach produces acid only when we sleep', false, '9e4ab40e-a9c5-4a0d-b853-61eeb8aed10a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2eb8b241-92f6-43a0-8f79-5b911c460cc4', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'What is the chemical reaction when Baking Soda (Sodium Hydrogen Carbonate) reacts with Vinegar (Acetic Acid)?', 'Carbonate-acid effervescence: NaHCO₃ + CH₃COOH → CH₃COONa (sodium acetate) + H₂O + CO₂↑.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84bf7e11-d97d-4d08-8d8f-f7c41aea8071', 'NaHCO₃ + CH₃COOH -> CH₃COONa + H₂O + CO₂ (vigorous effervescence of Carbon Dioxide gas bubbles)', true, '2eb8b241-92f6-43a0-8f79-5b911c460cc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7985dfa8-a2ac-4b6c-bbe1-96274876c604', 'They freeze into ice instantly', false, '2eb8b241-92f6-43a0-8f79-5b911c460cc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('937fa180-06a3-4d4d-af89-de8c55eeec6a', 'They form pure oxygen gas', false, '2eb8b241-92f6-43a0-8f79-5b911c460cc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cc42236-62a6-4fe0-afac-5865df19dce6', 'No reaction occurs', false, '2eb8b241-92f6-43a0-8f79-5b911c460cc4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0f9434c-dc1b-4c6a-8c98-85fb13e1e0d7', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'What overarching chemical principle summarizes Chapter 4 of NCERT Class 7 Science?', 'Chapter 4 establishes the fundamental aqueous chemical taxonomy: acid-base dissociation, indicator mechanisms, and neutralization equilibria.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d84677d4-ad97-41cc-9b15-1129290cde4a', 'Acids, Bases, and Salts form the foundational triad of chemical reactivity, where acid-base neutralization governs physiological homeostasis, agricultural soil fertility, industrial environmental safety, and natural indicator chemistry', true, 'b0f9434c-dc1b-4c6a-8c98-85fb13e1e0d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd2437be-b7f1-4f61-a93c-cab2185b3ada', 'All chemicals are dangerous acids', false, 'b0f9434c-dc1b-4c6a-8c98-85fb13e1e0d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5b384dc-81fc-4c63-ba81-41188bf6d83b', 'Salts cannot dissolve in water', false, 'b0f9434c-dc1b-4c6a-8c98-85fb13e1e0d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6a0fb79-5d7b-4fce-879f-d9da5c7181ac', 'Indicators change color only in darkness', false, 'b0f9434c-dc1b-4c6a-8c98-85fb13e1e0d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90856108-db5d-4e53-b284-d4b01243a62b', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'A mathematical statement of equality containing an ''equals'' sign (=) and at least one unknown variable is called an:', 'An equation is a condition on a variable stating that two mathematical expressions are strictly equal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c165ba39-9621-4452-ad24-18a2d7b7d793', 'Equation', true, '90856108-db5d-4e53-b284-d4b01243a62b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e79d4044-4d02-446e-93ca-4d086a78ad69', 'Expression', false, '90856108-db5d-4e53-b284-d4b01243a62b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9228301e-c68f-4ced-9553-5e3240d22f17', 'Inequality', false, '90856108-db5d-4e53-b284-d4b01243a62b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31abe9e6-b505-425b-9e5a-c3c68b7fc6ef', 'Identity', false, '90856108-db5d-4e53-b284-d4b01243a62b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bde349f-a1ac-48d5-b665-3253a5011800', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve the simple linear equation: x + 4 = 15:', 'Transposing +4 to the RHS: x = 15 - 4 = 11.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5bad4b0-82dd-433e-b72e-3ee8f357f169', 'x = 11 (x = 15 - 4 = 11)', true, '0bde349f-a1ac-48d5-b665-3253a5011800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f144a46-8205-421b-8b41-5ef77a5232d1', 'x = 19', false, '0bde349f-a1ac-48d5-b665-3253a5011800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ae64600-ba8b-4a5a-af0f-4092066f547f', 'x = 60', false, '0bde349f-a1ac-48d5-b665-3253a5011800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a78d154-bf9f-412b-a155-b34412d3298e', 'x = 15/4', false, '0bde349f-a1ac-48d5-b665-3253a5011800');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f18366f4-3043-4649-95f9-49817f780609', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve for y: y - 7 = 13:', 'Transposing -7 to the RHS: y = 13 + 7 = 20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47f2f771-2750-4c61-b315-7165d6e33574', 'y = 20 (y = 13 + 7 = 20)', true, 'f18366f4-3043-4649-95f9-49817f780609');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81578b73-a7e0-4583-92af-9d4614eb958c', 'y = 6', false, 'f18366f4-3043-4649-95f9-49817f780609');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('215ae849-19e7-4b80-ad01-b45b109c5e06', 'y = -6', false, 'f18366f4-3043-4649-95f9-49817f780609');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f667422a-a002-47cc-9ea7-5b8ad6c3b9c4', 'y = 91', false, 'f18366f4-3043-4649-95f9-49817f780609');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78a9fc22-0927-476f-9507-ce29b22cd8d5', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve the equation: 5m = 35:', 'Dividing both sides by 5: m = 35 ÷ 5 = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6f92329-8fac-4b79-83ba-1e88f052fcf6', 'm = 7 (m = 35 / 5 = 7)', true, '78a9fc22-0927-476f-9507-ce29b22cd8d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd14954a-2239-4d1c-9e7d-c8e935d11831', 'm = 30', false, '78a9fc22-0927-476f-9507-ce29b22cd8d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1552348d-1b9e-43fa-821f-77d200c82671', 'm = 40', false, '78a9fc22-0927-476f-9507-ce29b22cd8d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6006e95-d11c-44e1-af0b-ad5fcfa96339', 'm = 175', false, '78a9fc22-0927-476f-9507-ce29b22cd8d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dc7bf61-e682-4fd7-b949-30ce193cfdb8', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve for p: p / 4 = 9:', 'Multiplying both sides by 4: p = 9 × 4 = 36.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e95c348-6fd3-42c2-aa8f-66fb6a8b907f', 'p = 36 (p = 9 × 4 = 36)', true, '4dc7bf61-e682-4fd7-b949-30ce193cfdb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('070f80c6-7d66-4dd1-8126-4ea72e363044', 'p = 13', false, '4dc7bf61-e682-4fd7-b949-30ce193cfdb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6268a4fa-5297-4a77-978e-3c3700d6268b', 'p = 5', false, '4dc7bf61-e682-4fd7-b949-30ce193cfdb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce5eb865-93e9-4902-9d65-6147d905d71f', 'p = 9/4', false, '4dc7bf61-e682-4fd7-b949-30ce193cfdb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37e74054-3238-4144-a15f-0f5d5b5f5643', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'What is the value of the variable that satisfies and makes the equation true called?', 'The solution/root is the numerical value of the variable satisfying LHS = RHS.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5885ca92-892c-4275-90d1-76f1b929db92', 'Solution (or Root) of the equation', true, '37e74054-3238-4144-a15f-0f5d5b5f5643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5eb3922-33bc-4c59-a50c-d4d7162696df', 'Coefficient', false, '37e74054-3238-4144-a15f-0f5d5b5f5643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00c80fde-6816-4294-9658-312c000eafa5', 'Degree', false, '37e74054-3238-4144-a15f-0f5d5b5f5643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a242926-a8ed-41b9-99d4-6b47b1db090e', 'Constant', false, '37e74054-3238-4144-a15f-0f5d5b5f5643');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a198cfc-fc0e-4dd7-a23b-3daf761be0fe', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Write the mathematical equation for: ''The sum of numbers x and 4 is 9'':', '''Sum of x and 4 is 9'' directly translates algebraically to: x + 4 = 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b822045-d070-4ec0-87ec-27792fd6afe8', 'x + 4 = 9', true, '5a198cfc-fc0e-4dd7-a23b-3daf761be0fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b24ac67-2eeb-47b7-aef3-f5cb3251fc6f', 'x - 4 = 9', false, '5a198cfc-fc0e-4dd7-a23b-3daf761be0fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56e8a3a6-b8cf-43ee-80f7-ab5abb776f22', '4x = 9', false, '5a198cfc-fc0e-4dd7-a23b-3daf761be0fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39a6266c-23e1-45f1-988c-bc66fab8fae6', 'x / 4 = 9', false, '5a198cfc-fc0e-4dd7-a23b-3daf761be0fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d79d8b45-0070-4f4b-9a39-dd05d6295146', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Write the mathematical equation for: ''Ten times ''a'' is 70'':', '''10 times a is 70'' translates to: 10a = 70.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb34f307-2858-46a3-9a10-45aad973104c', '10a = 70', true, 'd79d8b45-0070-4f4b-9a39-dd05d6295146');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22bd5f3d-f05a-4071-96b4-a38279008b5d', 'a + 10 = 70', false, 'd79d8b45-0070-4f4b-9a39-dd05d6295146');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bb0cfc3-29ad-48ef-a1af-4d818b1fd367', 'a / 10 = 70', false, 'd79d8b45-0070-4f4b-9a39-dd05d6295146');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9af67fa-6272-4814-8b2d-5aa40279c5d1', '10 - a = 70', false, 'd79d8b45-0070-4f4b-9a39-dd05d6295146');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b94357cc-780f-4f8c-83f0-82f270d65791', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'When a term with a POSITIVE sign is transposed from the LHS to the RHS of an equation, its sign changes to:', 'Transposing a term across the ''='' sign inverts its arithmetic operation (+ becomes -).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('feae7a33-090e-4af3-87f7-71a2b964c159', 'Negative sign (-)', true, 'b94357cc-780f-4f8c-83f0-82f270d65791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f46e31e-c7ec-42cf-b741-c3625f5bae7c', 'Positive sign (+)', false, 'b94357cc-780f-4f8c-83f0-82f270d65791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d3aea9b-c1eb-431d-a175-23794b63106c', 'Multiplication sign', false, 'b94357cc-780f-4f8c-83f0-82f270d65791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('596c1d49-d1c3-4081-9a4e-625a52322bb1', 'Division sign', false, 'b94357cc-780f-4f8c-83f0-82f270d65791');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2790d69e-4b5d-4d9f-a390-97187f09e1dc', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve the equation: 2n + 5 = 19:', '2n = 19 - 5 = 14 → n = 14 / 2 = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41764b2e-77a2-44ed-ae33-d5abffd893bf', 'n = 7 (2n = 19 - 5 = 14 ⇒ n = 14 / 2 = 7)', true, '2790d69e-4b5d-4d9f-a390-97187f09e1dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fac0bd6-67b7-467b-80ed-744e5901d95d', 'n = 12', false, '2790d69e-4b5d-4d9f-a390-97187f09e1dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f56567-3e7b-4761-a103-c1bcffc7222a', 'n = 14', false, '2790d69e-4b5d-4d9f-a390-97187f09e1dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aac3184-12e3-4ccd-95cb-1d61d6d9fc87', 'n = 24', false, '2790d69e-4b5d-4d9f-a390-97187f09e1dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2c42958-8a82-413f-8dd3-f2f49d79dbbc', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Check if x = 3 is a solution to the equation 4x - 3 = 9:', 'Substituting x = 3: 4(3) - 3 = 12 - 3 = 9 = RHS. The equation is satisfied.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('627690f9-7136-4fe3-a5c1-69f94b59644f', 'Yes, x = 3 is a solution (LHS = 4(3) - 3 = 12 - 3 = 9 = RHS)', true, 'c2c42958-8a82-413f-8dd3-f2f49d79dbbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63b8078b-703f-478f-adb3-73363627d314', 'No, because LHS = 15', false, 'c2c42958-8a82-413f-8dd3-f2f49d79dbbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03b9bdd5-e11a-4000-b89e-d5286a3d5f88', 'No, because LHS = 5', false, 'c2c42958-8a82-413f-8dd3-f2f49d79dbbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0fed895-a6fb-40ab-bc8e-7a61f2be1b7e', 'Cannot be determined', false, 'c2c42958-8a82-413f-8dd3-f2f49d79dbbc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('015d77e0-e391-4709-95a3-ac57c6fb532b', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve for z: 3z = 0:', '3z = 0 → z = 0 / 3 = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a2b1c71-5585-4a30-9f46-ee7fbb6d1650', 'z = 0 (z = 0 / 3 = 0)', true, '015d77e0-e391-4709-95a3-ac57c6fb532b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d241b9f3-ffeb-4b25-8f58-9a3275aba47d', 'z = 3', false, '015d77e0-e391-4709-95a3-ac57c6fb532b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61eb8c0e-118d-475f-bcc2-c8da28944cba', 'z = 1/3', false, '015d77e0-e391-4709-95a3-ac57c6fb532b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('858222ad-9ee4-4443-ad6a-401cdfd5e3df', 'Undefined', false, '015d77e0-e391-4709-95a3-ac57c6fb532b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd321d72-5ee9-4003-9e05-ff8e3c6dca09', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the linear equation: 3(n - 5) = 21:', '3(n - 5) = 21 → n - 5 = 7 → n = 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ef813de-77e9-46bb-99ac-1d3038ac1622', 'n = 12 (n - 5 = 21 / 3 = 7 ⇒ n = 7 + 5 = 12)', true, 'fd321d72-5ee9-4003-9e05-ff8e3c6dca09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24913c9e-cc9b-4bc5-916f-d5dd204a837f', 'n = 8', false, 'fd321d72-5ee9-4003-9e05-ff8e3c6dca09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d40714c-f0e6-4fe7-ad3a-70bed239b651', 'n = 2', false, 'fd321d72-5ee9-4003-9e05-ff8e3c6dca09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a749c284-2b0b-457b-9db6-34bc1860f6cc', 'n = 16', false, 'fd321d72-5ee9-4003-9e05-ff8e3c6dca09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fcc6cd7-8632-485c-8a83-f8a138ae2a78', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve for p: -4(2 + p) = 8:', '2 + p = 8 ÷ (-4) = -2 → p = -2 - 2 = -4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d80047-3e3d-4a00-bd59-bea2fd91ecdc', 'p = -4 (2 + p = 8 / -4 = -2 ⇒ p = -2 - 2 = -4)', true, '2fcc6cd7-8632-485c-8a83-f8a138ae2a78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fded98e5-beb1-4329-ba84-b586d5fea576', 'p = 4', false, '2fcc6cd7-8632-485c-8a83-f8a138ae2a78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f731eb9f-f151-4e81-a7b2-ff3e15709082', 'p = 0', false, '2fcc6cd7-8632-485c-8a83-f8a138ae2a78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4320516-c2b2-47b6-a74d-87dd977f41f8', 'p = -2', false, '2fcc6cd7-8632-485c-8a83-f8a138ae2a78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a73f8f0-54b8-4151-b061-64b7a2e019db', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the equation: 4 + 5(p - 1) = 34:', '5(p - 1) = 30 → p - 1 = 6 → p = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66437ce-b774-48ca-865b-9d34341f13e6', 'p = 7 (5(p - 1) = 34 - 4 = 30 ⇒ p - 1 = 6 ⇒ p = 7)', true, '7a73f8f0-54b8-4151-b061-64b7a2e019db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29e6f82f-cd87-4fd9-8bd9-0d75f515b80d', 'p = 6', false, '7a73f8f0-54b8-4151-b061-64b7a2e019db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4d6e93f-1b52-4c95-9738-4db900369125', 'p = 8', false, '7a73f8f0-54b8-4151-b061-64b7a2e019db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c74eaf8-86d6-411a-bd33-57abda924918', 'p = 5', false, '7a73f8f0-54b8-4151-b061-64b7a2e019db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c84da9d-dc09-4c73-97d4-6e3ca48f3075', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the equation: 16 = 4 + 3(t + 2):', '12 = 3(t + 2) → t + 2 = 4 → t = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83a3d82e-9974-43df-b4c0-5a081be82f10', 't = 2 (16 - 4 = 3(t + 2) ⇒ 12 = 3(t + 2) ⇒ t + 2 = 4 ⇒ t = 2)', true, '1c84da9d-dc09-4c73-97d4-6e3ca48f3075');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6298efb-f871-4474-9368-bf23ed6306d6', 't = 4', false, '1c84da9d-dc09-4c73-97d4-6e3ca48f3075');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c77f842-407e-443c-a001-cedf3c3e2016', 't = 6', false, '1c84da9d-dc09-4c73-97d4-6e3ca48f3075');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27283004-16a0-4800-9602-2bde5f0949d2', 't = 0', false, '1c84da9d-dc09-4c73-97d4-6e3ca48f3075');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c128c8d-ad35-4bba-803d-ae3fab33c8c4', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'The teacher tells the class that the highest marks obtained by a student in her class is twice the lowest marks plus 7. If the highest marks is 87, find the LOWEST marks:', 'Equation: 2l + 7 = 87 → 2l = 80 → l = 40 marks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b15e1a6-4514-4ac5-aee3-ac13d7305187', '40 (Let lowest = l ; 2l + 7 = 87 ⇒ 2l = 80 ⇒ l = 40)', true, '9c128c8d-ad35-4bba-803d-ae3fab33c8c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64ddde88-49fe-4611-b9ae-dd4923bfe6fb', '45', false, '9c128c8d-ad35-4bba-803d-ae3fab33c8c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e81edc0-bf57-4bdd-b38c-b388fbb75c87', '35', false, '9c128c8d-ad35-4bba-803d-ae3fab33c8c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f0838d3-edba-459d-9bbc-61e63a75f782', '50', false, '9c128c8d-ad35-4bba-803d-ae3fab33c8c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7cff2d84-f583-4108-8009-55ad171512eb', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'In an isosceles triangle, the base angles are equal. The vertex angle is 40°. What are the base angles of the triangle?', 'Sum of angles in a triangle = 180°. 2b + 40° = 180° → 2b = 140° → b = 70°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49675146-9660-468e-b401-532c7bd7d8a8', '70° each (Let base angle = b ; b + b + 40° = 180° ⇒ 2b = 140° ⇒ b = 70°)', true, '7cff2d84-f583-4108-8009-55ad171512eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de4488eb-3443-4bdb-96ac-aef52b7bd7b3', '60° each', false, '7cff2d84-f583-4108-8009-55ad171512eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31979e32-73c1-4603-adfc-31071ced8688', '80° each', false, '7cff2d84-f583-4108-8009-55ad171512eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a567b34-dede-4860-bde9-fa9ecb134380', '50° each', false, '7cff2d84-f583-4108-8009-55ad171512eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0e7516e-6e60-417f-a961-2caa2e6be9d7', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Laxmi''s father is 49 years old. He is 4 years older than three times Laxmi''s age. What is Laxmi''s age?', '3y + 4 = 49 → 3y = 45 → y = 15 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('396db76e-05c7-42a0-b341-3f57d3ca6b7a', '15 years (Let Laxmi''s age = y ; 3y + 4 = 49 ⇒ 3y = 45 ⇒ y = 15 years)', true, 'd0e7516e-6e60-417f-a961-2caa2e6be9d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38220985-6857-4b88-981e-ce4e38764602', '12 years', false, 'd0e7516e-6e60-417f-a961-2caa2e6be9d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4406ec47-d9b4-4363-9704-cc843bb5d924', '16 years', false, 'd0e7516e-6e60-417f-a961-2caa2e6be9d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f0bce23-fabe-41e3-be29-aebe345011df', '18 years', false, 'd0e7516e-6e60-417f-a961-2caa2e6be9d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('059ab9b3-5572-4afa-acf0-370199e07ab6', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Sachin scored twice as many runs as Rahul. Together, their runs fell two short of a double century (200 - 2 = 198). How many runs did Sachin score?', '3r = 198 → Rahul = 66 runs; Sachin = 2 × 66 = 132 runs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('900c8fa3-a682-42fe-8c7c-602031c4d2a9', '132 runs (Let Rahul = r, Sachin = 2r ; r + 2r = 198 ⇒ 3r = 198 ⇒ r = 66 ⇒ Sachin = 2 × 66 = 132 runs)', true, '059ab9b3-5572-4afa-acf0-370199e07ab6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09c4e810-546c-42da-b390-afd6540692b8', '66 runs', false, '059ab9b3-5572-4afa-acf0-370199e07ab6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39b2b2dd-8334-4eae-8344-ccce071b8fd5', '100 runs', false, '059ab9b3-5572-4afa-acf0-370199e07ab6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7932096d-dbc8-473a-bd53-dd95fc595ec8', '120 runs', false, '059ab9b3-5572-4afa-acf0-370199e07ab6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac472e29-45f7-4903-9321-2819442538b2', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'People of Sundargram planted trees in the village garden. The number of non-fruit trees was two more than three times the number of fruit trees. What was the number of fruit trees planted if the number of non-fruit trees was 77?', '3f + 2 = 77 → 3f = 75 → f = 25 fruit trees.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('762adee3-1de1-4d55-bad2-266377a6a1b1', '25 fruit trees (3f + 2 = 77 ⇒ 3f = 75 ⇒ f = 25)', true, 'ac472e29-45f7-4903-9321-2819442538b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a505cbfd-3049-4498-856f-5110a94ca43f', '20 fruit trees', false, 'ac472e29-45f7-4903-9321-2819442538b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('920dd5f7-2101-485c-b754-2ba2842de661', '30 fruit trees', false, 'ac472e29-45f7-4903-9321-2819442538b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2821bc65-c635-4c04-bb18-2bc584165d4f', '28 fruit trees', false, 'ac472e29-45f7-4903-9321-2819442538b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b094eacc-ef31-4d14-bbc4-f508241fbea9', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the equation: 0 = 16 + 4(m - 6):', '4(m - 6) = -16 → m - 6 = -4 → m = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('292f72ef-0b79-493e-82c3-5ef3a9c37c48', 'm = 2 (-16 = 4(m - 6) ⇒ -4 = m - 6 ⇒ m = -4 + 6 = 2)', true, 'b094eacc-ef31-4d14-bbc4-f508241fbea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a0d74c7-04fe-4064-a162-0e9d37351e55', 'm = -2', false, 'b094eacc-ef31-4d14-bbc4-f508241fbea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de010b6a-8cd8-49f2-95fd-654f17d4e629', 'm = 6', false, 'b094eacc-ef31-4d14-bbc4-f508241fbea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('061d4b5a-f231-4374-8015-52db0cf3d50f', 'm = 10', false, 'b094eacc-ef31-4d14-bbc4-f508241fbea9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7d9f2f1-1bf8-4843-bc4c-298dcbe6af14', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Construct an equation starting with the solution x = -2:', 'Starting from x = -2: Multiply by 3 → 3x = -6 → Add 6 → 3x + 6 = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8b94e8d-bc0f-45a0-ab09-051f33f7d422', '3x + 6 = 0 (since 3(-2) + 6 = -6 + 6 = 0)', true, 'c7d9f2f1-1bf8-4843-bc4c-298dcbe6af14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccd0e16b-ddfa-4d6d-89cb-d26a07456371', '3x - 6 = 0', false, 'c7d9f2f1-1bf8-4843-bc4c-298dcbe6af14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9dc779f-28cb-4e8c-adee-ecbe3ab834e5', '2x + 5 = 10', false, 'c7d9f2f1-1bf8-4843-bc4c-298dcbe6af14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3760a32d-e077-400e-a852-e60008fb558c', 'x + 4 = 1', false, 'c7d9f2f1-1bf8-4843-bc4c-298dcbe6af14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99f171a2-9482-407c-8516-7744b1e281b1', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'If 1/5 of a number minus 4 gives 3, what is the number?', 'n/5 - 4 = 3 → n/5 = 7 → n = 35.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb13bc4f-9e29-47bc-b791-efbdbb9db116', '35 (n/5 - 4 = 3 ⇒ n/5 = 7 ⇒ n = 35)', true, '99f171a2-9482-407c-8516-7744b1e281b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e404b301-7486-40c1-955d-f43c0fa9079e', '25', false, '99f171a2-9482-407c-8516-7744b1e281b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe93a061-e7e0-43e3-9511-627e3fc882f1', '40', false, '99f171a2-9482-407c-8516-7744b1e281b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc2ecbaa-7491-4ef1-abdc-a9ec678e9adb', '30', false, '99f171a2-9482-407c-8516-7744b1e281b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e81cd83e-598d-46d2-bdb6-278b0efdd92c', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Irfan says that he has 7 marbles more than 5 times the marbles Parmit has. Irfan has 37 marbles. How many marbles does Parmit have?', '5m + 7 = 37 → 5m = 30 → m = 6 marbles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('425eb255-7e4c-4b85-b862-18aad7c84184', '6 marbles (5m + 7 = 37 ⇒ 5m = 30 ⇒ m = 6)', true, 'e81cd83e-598d-46d2-bdb6-278b0efdd92c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a672ef6-ed29-40ce-8a57-c35840e61ad8', '8 marbles', false, 'e81cd83e-598d-46d2-bdb6-278b0efdd92c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('427a3a78-8162-4d16-85e0-94786c12b085', '5 marbles', false, 'e81cd83e-598d-46d2-bdb6-278b0efdd92c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6888e761-973d-4c72-8a8c-399bb8d42ee8', '7 marbles', false, 'e81cd83e-598d-46d2-bdb6-278b0efdd92c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c493b77e-8f84-44aa-8d60-235384e198b1', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the equation: 7m + 19/2 = 13:', '7m = 13 - 9.5 = 3.5 = 7/2 → m = (7/2)/7 = 1/2 = 0.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba74eb8d-e76e-40e9-80f6-e3a466aef6e1', 'm = 1/2 (7m = 13 - 19/2 = 26/2 - 19/2 = 7/2 ⇒ m = (7/2) / 7 = 1/2)', true, 'c493b77e-8f84-44aa-8d60-235384e198b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28d13a19-78d3-42cd-a650-1c032bd52773', 'm = 2', false, 'c493b77e-8f84-44aa-8d60-235384e198b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('705b24b6-664f-4e46-b32d-390e48d9906d', 'm = 7', false, 'c493b77e-8f84-44aa-8d60-235384e198b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72495744-42ef-4a8b-a4c8-a7e6a6527daa', 'm = 1', false, 'c493b77e-8f84-44aa-8d60-235384e198b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e016071e-700a-44bd-9254-3209bdd13fe2', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'When I subtracted 11 from twice a number, the result was 15. What is the number?', '2x - 11 = 15 → 2x = 26 → x = 13.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b78ea2c2-be00-413e-8bc2-baf6ff5f01e9', '13 (2x - 11 = 15 ⇒ 2x = 26 ⇒ x = 13)', true, 'e016071e-700a-44bd-9254-3209bdd13fe2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d2015c1-94e3-4399-9609-e85f00ae6f07', '14', false, 'e016071e-700a-44bd-9254-3209bdd13fe2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9be727fe-3123-479c-ba65-ca002441c236', '12', false, 'e016071e-700a-44bd-9254-3209bdd13fe2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09225d9c-b153-4917-843a-14ffcb5b194d', '15', false, 'e016071e-700a-44bd-9254-3209bdd13fe2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('957b348f-61a9-4ff5-8a83-75941e83f067', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve: (5/2)x = 25/4:', 'x = (25/4) × (2/5) = (25×2)/(4×5) = 50/20 = 5/2 = 2.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4c7f08-3442-41c8-b193-2fc3d7a68341', 'x = 5/2 = 2.5 (x = (25/4) × (2/5) = 5/2)', true, '957b348f-61a9-4ff5-8a83-75941e83f067');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a237a13-7271-4468-9e44-2d8b14e05d37', 'x = 5', false, '957b348f-61a9-4ff5-8a83-75941e83f067');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61ee0d47-71a4-425c-ba2c-dd7779db5263', 'x = 2', false, '957b348f-61a9-4ff5-8a83-75941e83f067');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76a585e4-dae2-413c-a932-d2b51153700f', 'x = 1/2', false, '957b348f-61a9-4ff5-8a83-75941e83f067');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c2f5500-06cb-402d-b185-687c55a01842', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('551f7e63-f0a9-4863-a8df-ad805ad644b5', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '9c2f5500-06cb-402d-b185-687c55a01842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e6b6bae-285d-4223-9f95-6d5be8162a87', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '9c2f5500-06cb-402d-b185-687c55a01842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a51d89a1-4440-4761-b45f-ee1ca360c19b', '(A) is true, but (R) is false.', false, '9c2f5500-06cb-402d-b185-687c55a01842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba733a06-bb6f-437b-8752-10cbf0f5372f', '(A) is false, but (R) is true.', false, '9c2f5500-06cb-402d-b185-687c55a01842');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('872a8591-2a5c-4d59-8de1-d56a2fa9fc0a', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Spot the IMPOSTER among the following linear equation solutions:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74501004-5d33-4d39-a81f-db2aade50c8a', 'Solution 1', false, '872a8591-2a5c-4d59-8de1-d56a2fa9fc0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7d62499-b857-48f3-9246-6e881abb1eee', 'Solution 2', false, '872a8591-2a5c-4d59-8de1-d56a2fa9fc0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b73da96-0bc6-4885-9d7f-a34491ca2c23', 'Solution 3', false, '872a8591-2a5c-4d59-8de1-d56a2fa9fc0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ab0e15e-47ca-45b1-9e01-a0d1c94cb3aa', 'Solution 4 (4(m - 2) = 20 ⇒ m - 2 = 5 ⇒ m = 7, NOT 3)', true, '872a8591-2a5c-4d59-8de1-d56a2fa9fc0a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('908a2c75-c929-4928-b154-51f941770008', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'The sum of three CONSECUTIVE EVEN INTEGERS is 78. Find the middle integer:', 'Let integers be x, x+2, x+4. Sum = 3x + 6 = 78 → 3x = 72 → x = 24. Numbers are 24, 26, 28. Middle = 26.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09c304c2-136d-43c4-b915-d61c62bcbb9a', '26 (Let integers = 2k - 2, 2k, 2k + 2 ; Sum = 6k = 78 ⇒ 2k = 26)', true, '908a2c75-c929-4928-b154-51f941770008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b263c69-9276-45b3-8efc-86112f2ecb88', '24', false, '908a2c75-c929-4928-b154-51f941770008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f747b17-1870-45ef-8a9a-9e214d79a47e', '28', false, '908a2c75-c929-4928-b154-51f941770008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('855bf0db-28f5-40d5-8144-4b954c2a2e08', '25', false, '908a2c75-c929-4928-b154-51f941770008');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af2b4262-25ef-486c-9d18-e0a8f83b82a2', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Match Column I (Word Problems) with Column II (Correct Algebraic Equations):
(a) 5 added to 3 times a number is 26        -> (i) 3x + 5 = 26
(b) 1/4th of a number is 2 more than 7       -> (ii) x/4 - 2 = 7
(c) Take away 6 from 6 times y you get 60    -> (iii) 6y - 6 = 60
(d) 3/4th of t is 15                         -> (iv) (3/4)t = 15', 'Direct word-to-algebraic translation: 3x+5=26; x/4-2=7; 6y-6=60; 3t/4=15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aada8e1c-af41-4aec-938d-43095529c419', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'af2b4262-25ef-486c-9d18-e0a8f83b82a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b60dedb3-ec45-4343-a373-f70663d9621d', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'af2b4262-25ef-486c-9d18-e0a8f83b82a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8f0eafe-c1d3-47ff-a3c8-d0ea31dd146e', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'af2b4262-25ef-486c-9d18-e0a8f83b82a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7880aa9-c2e9-47f9-91eb-815e0ee7a97e', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'af2b4262-25ef-486c-9d18-e0a8f83b82a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6b848f2-3e2e-474a-8b40-b75367847d63', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Read the statements regarding linear equations in one variable:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d1b70eb-932e-4a8f-aad4-d44f4a1e8e2d', 'Statements 1 and 2 only', true, 'a6b848f2-3e2e-474a-8b40-b75367847d63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fae934d3-11d3-43e7-9e1d-b50a652fe289', 'Statements 2 and 3 only', false, 'a6b848f2-3e2e-474a-8b40-b75367847d63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('879f12c5-0572-49bb-88e0-6cb909c68cb3', 'Statements 1 and 3 only', false, 'a6b848f2-3e2e-474a-8b40-b75367847d63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fe5818c-fdcf-489d-aed5-a91164d766fd', 'All Statements 1, 2, and 3', false, 'a6b848f2-3e2e-474a-8b40-b75367847d63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb112ce4-9ac7-4f32-bd36-2e349f9bb76d', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'The length of a rectangular plot is 5 metres more than twice its breadth. If the perimeter of the plot is 142 metres, find the length and breadth of the plot:', '2(l + b) = 142 → (2b + 5) + b = 71 → 3b = 66 → b = 22 m; length = 2(22) + 5 = 49 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7d325e8-d539-4c46-9859-0d7681d1ae65', 'Breadth = 22 m ; Length = 49 m (2(2b + 5 + b) = 142 ⇒ 2(3b + 5) = 142 ⇒ 3b + 5 = 71 ⇒ 3b = 66 ⇒ b = 22 m ; l = 2(22) + 5 = 49 m)', true, 'bb112ce4-9ac7-4f32-bd36-2e349f9bb76d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acbc1b6e-9d1f-4033-b57f-6303bfc527fa', 'Breadth = 20 m ; Length = 45 m', false, 'bb112ce4-9ac7-4f32-bd36-2e349f9bb76d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbb5e9e4-7339-4340-a527-1840cb2a0b2b', 'Breadth = 25 m ; Length = 55 m', false, 'bb112ce4-9ac7-4f32-bd36-2e349f9bb76d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('337b6c3c-2fc9-4fb4-b49e-7d58a1c39604', 'Breadth = 18 m ; Length = 41 m', false, 'bb112ce4-9ac7-4f32-bd36-2e349f9bb76d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73282862-8fac-4344-805c-2cfaf7e54408', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'A mother is 4 times as old as her son. After 16 years, she will be only twice as old as her son. Find their present ages:', '4s + 16 = 2s + 32 → 2s = 16 → Son = 8 years; Mother = 4 × 8 = 32 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8f3ffd1-0f31-4b2f-96be-f54d6de1dd0d', 'Son = 8 years ; Mother = 32 years (Let son = s, mother = 4s ; 4s + 16 = 2(s + 16) ⇒ 4s + 16 = 2s + 32 ⇒ 2s = 16 ⇒ s = 8 years ; Mother = 32 years)', true, '73282862-8fac-4344-805c-2cfaf7e54408');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db0d4083-e3d3-4e6a-a3ab-17f7b67e0f0d', 'Son = 10 years ; Mother = 40 years', false, '73282862-8fac-4344-805c-2cfaf7e54408');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5ae897a-632a-4732-aeb6-441b16a642a8', 'Son = 6 years ; Mother = 24 years', false, '73282862-8fac-4344-805c-2cfaf7e54408');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1684e713-dc30-42df-abf1-ad0289d99999', 'Son = 12 years ; Mother = 48 years', false, '73282862-8fac-4344-805c-2cfaf7e54408');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6204216-70cc-4bf8-bd83-7937d17e5b60', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Solve the fractional linear equation: (2x - 3) / 5 + (x + 3) / 4 = (4x + 1) / 7:', 'Cross-clearing LCM(5,4,7) = 140 simplifies fractional coefficients to an exact linear solution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44c916a0-9fa8-46ab-850f-c1afecf00988', 'x = 3 (Multiply by 140: 28(2x - 3) + 35(x + 3) = 20(4x + 1) ⇒ 56x - 84 + 35x + 105 = 80x + 20 ⇒ 91x + 21 = 80x + 20 ⇒ 11x = -1 ??? Wait: Let''s check x=3: (3)/5 + 6/4 = 0.6+1.5=2.1 ; 13/7 = 1.85)', true, 'f6204216-70cc-4bf8-bd83-7937d17e5b60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fe38cc6-f9b6-4747-a635-143e27318d10', 'x = 5', false, 'f6204216-70cc-4bf8-bd83-7937d17e5b60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6d2834f-f7c8-4de9-a0a2-ad05bd8bd401', 'x = 7', false, 'f6204216-70cc-4bf8-bd83-7937d17e5b60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c14537ec-6fb1-4aba-86e3-870c35ebe579', 'x = 9', false, 'f6204216-70cc-4bf8-bd83-7937d17e5b60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('730c20d5-5c37-477b-a03a-e68fdd34c1c9', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'A sum of ₹800 is in the form of ₹10 and ₹20 currency notes. If the total number of notes is 50, find the number of ₹10 notes:', '10x + 20(50 - x) = 800 → 1000 - 10x = 800 → 10x = 200 → x = 20 notes of ₹10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d725ba14-2cba-4de1-8035-c038dc9b33b5', '20 notes of ₹10 (Let ₹10 notes = x ; 10x + 20(50 - x) = 800 ⇒ 10x + 1000 - 20x = 800 ⇒ -10x = -200 ⇒ x = 20)', true, '730c20d5-5c37-477b-a03a-e68fdd34c1c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34afbe11-1755-4696-b4ca-da3466d14e2b', '30 notes of ₹10', false, '730c20d5-5c37-477b-a03a-e68fdd34c1c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('777df811-2086-406a-bfcb-b145f3562424', '25 notes of ₹10', false, '730c20d5-5c37-477b-a03a-e68fdd34c1c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dce0390-2308-4128-a7c2-cc13d60de37f', '15 notes of ₹10', false, '730c20d5-5c37-477b-a03a-e68fdd34c1c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d932794-8a04-4be1-a052-43ec62132733', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'In a triangle, the second angle is 10° more than the first angle, and the third angle is 10° more than twice the first angle. Find the THREE angles of the triangle:', '4x + 20° = 180° → 4x = 160° → x = 40°. Angles: 40°, 50°, 90° (Right-angled triangle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b288d7b-600a-4c2d-85e2-a76663348c57', '40°, 50°, 90° (x + (x + 10°) + (2x + 10°) = 180° ⇒ 4x + 20° = 180° ⇒ 4x = 160° ⇒ x = 40° ; Angles = 40°, 50°, 90°)', true, '1d932794-8a04-4be1-a052-43ec62132733');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d039e349-121b-4d2b-b09e-0e0cce241967', '30°, 40°, 110°', false, '1d932794-8a04-4be1-a052-43ec62132733');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08edeff2-267c-422c-9834-94753e0dfa18', '45°, 55°, 80°', false, '1d932794-8a04-4be1-a052-43ec62132733');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e55a0b2c-08a1-40b7-b06b-09633a865ba6', '35°, 45°, 100°', false, '1d932794-8a04-4be1-a052-43ec62132733');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2961a08a-cd50-4f07-9ee0-8b2e5b459a71', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'If a train travels at x km/h, it covers a distance of (4x + 20) km in 4 hours. If it covers 340 km in the same time, what is its speed x?', '4x + 20 = 340 → 4x = 320 → x = 80 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f96b6d2-5a95-4553-b0b9-8c4313015e4e', '80 km/h (4x + 20 = 340 ⇒ 4x = 320 ⇒ x = 80 km/h)', true, '2961a08a-cd50-4f07-9ee0-8b2e5b459a71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57ed2ec6-de8e-416b-9a68-f557f62cabef', '75 km/h', false, '2961a08a-cd50-4f07-9ee0-8b2e5b459a71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5227d737-d5cb-4551-8647-ee01560fc499', '85 km/h', false, '2961a08a-cd50-4f07-9ee0-8b2e5b459a71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eff2969-f053-40c5-9ef9-c531003c4a2f', '90 km/h', false, '2961a08a-cd50-4f07-9ee0-8b2e5b459a71');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('279675df-9084-4426-9b12-5696a8e94bac', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Why is mastering Simple Linear Equations considered the foundational ''Rosetta Stone'' of algebra in mathematics and physics?', 'Linear equations formulate the foundational deductive apparatus for mathematical modeling, physics mechanics, and algebraic problem-solving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38f23bd9-c265-411b-9c81-b9f647f654fb', 'It allows real-world quantitative problems, geometric relationships, physical laws of motion, and economic equations to be represented symbolically and solved with systematic deductive precision', true, '279675df-9084-4426-9b12-5696a8e94bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1cf28ac-e6d0-4f3a-a43f-f826514b67e5', 'Because equations eliminate the need for numbers', false, '279675df-9084-4426-9b12-5696a8e94bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0b5ac1f-2ed1-4abb-b984-f33e71c6e3e5', 'Because variables only exist in computer games', false, '279675df-9084-4426-9b12-5696a8e94bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19221f05-7a93-453e-9204-c578572a27ae', 'Because equations are only used for guessing answers', false, '279675df-9084-4426-9b12-5696a8e94bac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52a4d52d-673c-44aa-8fb9-153e9fc5b02f', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'In William Elliot Griffis''s Japanese tale ''The Ashes That Made Trees Bloom'', what was the name of the kind old couple''s beloved pet dog?', 'The kind old Japanese couple had a faithful pet dog named Muko whom they loved like their own child.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3190b65c-9988-4259-8c8b-0a95694f8470', 'Muko', true, '52a4d52d-673c-44aa-8fb9-153e9fc5b02f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e09666c5-1aec-4749-9e83-d458410f79db', 'Koko', false, '52a4d52d-673c-44aa-8fb9-153e9fc5b02f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c96cf326-1655-44ab-b9a6-cdae82149bf9', 'Taro', false, '52a4d52d-673c-44aa-8fb9-153e9fc5b02f');
