INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba681630-d880-4713-9d28-592e4c559116', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the central satirical message in Michael Rosen''s poem ''Chivvy''?', 'Rosen critiques the overbearing parental micromanagement that paralyzes juvenile self-confidence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ec428d8-b4a5-430e-a813-09c889ee16c4', 'Adults stifle children''s spontaneous autonomy through relentless, petty micro-regulations, yet hypocritically expect them to display independent decision-making', true, 'ba681630-d880-4713-9d28-592e4c559116');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4362207b-b4ef-4cae-a28d-585162468ec0', 'Children should never listen to their parents', false, 'ba681630-d880-4713-9d28-592e4c559116');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00c780fe-7f07-4f31-8690-fdc74ede6404', 'Manners are completely useless in society', false, 'ba681630-d880-4713-9d28-592e4c559116');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c11df616-2426-4976-8368-9ae3ed111dcc', 'Poems should only be written for adults', false, 'ba681630-d880-4713-9d28-592e4c559116');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d10c5da8-dc8d-4de4-bd28-00bfb8a9ce61', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'Identify the meaning of the archaic word ''Dame'' in ''The good old man and his dame'':', '''Dame'' archaically denotes the matronly mistress or wife of a household.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4e7a431-0299-47d9-ac86-7d12d59dccda', 'An elderly married woman / wife / lady of the house', true, 'd10c5da8-dc8d-4de4-bd28-00bfb8a9ce61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa1395e8-1f4b-4f32-940f-9dd26a8e8f70', 'A young princess', false, 'd10c5da8-dc8d-4de4-bd28-00bfb8a9ce61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24b93d54-d6f9-4af8-8364-acb7c618710e', 'A soldier', false, 'd10c5da8-dc8d-4de4-bd28-00bfb8a9ce61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2ea1496-fce3-4ab1-9aea-60e643ae0e7e', 'A fairy godmother', false, 'd10c5da8-dc8d-4de4-bd28-00bfb8a9ce61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55204cbf-676d-42b4-be0f-71001f8c42eb', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the meaning of the phrasal verb ''To turn up'' in: ''The dog turned up a heap of gold''?', 'In agriculture/excavation, ''turn up'' means excavating or exposing buried items from beneath the soil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4d30e0-7065-4267-b9dd-7a5a4b865752', 'To dig up or uncover by scratching/ploughing the soil', true, '55204cbf-676d-42b4-be0f-71001f8c42eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcd421e6-7bbd-45b4-ac0d-e429a0016629', 'To increase the volume', false, '55204cbf-676d-42b4-be0f-71001f8c42eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d529012-b2a8-4270-8dfb-f4f114936401', 'To arrive at a party', false, '55204cbf-676d-42b4-be0f-71001f8c42eb');
