INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35a734ea-b845-4ad6-bd4e-c5da920f7edd', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the SYNONYM of the word ''Covetous'' in: ''The covetous neighbor wanted the magic mill''?', '''Covetous'' means yearning greedily for another person''s possessions.', NOW()) ON CONFLICT DO NOTHING;
