INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14ecaa67-4a63-43f2-b798-58be199b3733', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the ANTONYM of ''Withered'' in: ''The withered cherry tree burst into bloom''?', 'The antonym of ''withered'' (shriveled/desiccated) is ''flourishing'' or ''blooming''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94cb4e54-5642-4340-8b84-178268be54e3', 'Flourishing / Lush / Blooming', true, '14ecaa67-4a63-43f2-b798-58be199b3733');
