INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6215be9c-f550-4389-8d72-1c23294bba03', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What poetic device is prominent in the short, staccato imperative lines of ''Chivvy'' (''Sit up'', ''Say please'', ''Less noise'')?', 'Short, brisk imperative clauses rhythmically recreate the relentless cadence of adult nagging.', NOW()) ON CONFLICT DO NOTHING;
