INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('648059be-2a66-4b8d-808b-1404209fdb4a', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'Identify the part of speech of the underlined word in: ''The dog ran **friskily** around the garden.''', '''Friskily'' is an adverb of manner modifying the intransitive verb ''ran''.', NOW()) ON CONFLICT DO NOTHING;
