INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bad2629-96f5-47f6-9a53-8dbed1a5d1cb', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'In ''Chivvy'', what are children told to do with their elbows at the dinner table?', 'A classic dining etiquette rule featured in the poem: ''Take your elbows off the table''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56e16e52-b301-481b-95fd-38edc3bd2285', '"Take your elbows OFF the table!"', true, '9bad2629-96f5-47f6-9a53-8dbed1a5d1cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cd140c2-d767-4ac5-8948-ce21b6e0eb9e', '"Put your elbows on the plate!"', false, '9bad2629-96f5-47f6-9a53-8dbed1a5d1cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ff7a22e-3493-43a6-9aa9-d6ae677739ac', '"Cross your elbows!"', false, '9bad2629-96f5-47f6-9a53-8dbed1a5d1cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16f342b0-47ae-41e0-95e6-d68100239125', '"Lean on your elbows!"', false, '9bad2629-96f5-47f6-9a53-8dbed1a5d1cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9f5b9f0-0538-483d-bb85-ab3b5d2aa046', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What does ''Haven''t you got a hankie?'' mean in ''Chivvy''?', '''Hankie'' is colloquial for handkerchief, used to enforce hygienic nasal etiquette.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cc789de-0402-404a-b6d6-bbe0b89cb90f', 'Adults reprimanding the child to use a clean handkerchief instead of wiping their nose on their sleeve', true, 'c9f5b9f0-0538-483d-bb85-ab3b5d2aa046');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8f0e77e-4ffc-4fce-8b2a-729cce5b0d65', 'Asking the child to buy a handkerchief', false, 'c9f5b9f0-0538-483d-bb85-ab3b5d2aa046');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60634627-84c3-4482-942b-33019b3fd238', 'Playing a game with handkerchiefs', false, 'c9f5b9f0-0538-483d-bb85-ab3b5d2aa046');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1a8b5fa-064f-4cea-a156-f097cfa5b7a4', 'Asking if they want to wash clothes', false, 'c9f5b9f0-0538-483d-bb85-ab3b5d2aa046');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c959ad36-d173-4541-826c-13a7acde2d33', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2350767d-c3a8-46eb-805f-f9b4b28fa7ae', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c959ad36-d173-4541-826c-13a7acde2d33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d681a8b1-fab9-4644-ab6c-39bfe9619b70', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c959ad36-d173-4541-826c-13a7acde2d33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34c10766-e25b-4b97-bfba-89f935456469', '(A) is true, but (R) is false.', false, 'c959ad36-d173-4541-826c-13a7acde2d33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e1849cb-117a-4693-8823-bdd578312a61', '(A) is false, but (R) is true.', false, 'c959ad36-d173-4541-826c-13a7acde2d33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f9a2b0e-385a-4ecf-a9ff-8c2091fe16b3', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'Spot the IMPOSTER in the following sequence of transformations in ''The Ashes That Made Trees Bloom'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9b4b718-b6d4-4d53-87be-145e98109df2', 'Step 1', false, '8f9a2b0e-385a-4ecf-a9ff-8c2091fe16b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3f359c2-6d78-4441-bd61-4433b277454e', 'Step 2', false, '8f9a2b0e-385a-4ecf-a9ff-8c2091fe16b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcee1518-b23a-4d97-98a6-039f1e66d8d2', 'Step 3 (The mill yielded squirming, foul worms for the wicked neighbors, NOT diamonds)', true, '8f9a2b0e-385a-4ecf-a9ff-8c2091fe16b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('067763f3-e1ca-466f-b6c3-315d1215527c', 'Step 4', false, '8f9a2b0e-385a-4ecf-a9ff-8c2091fe16b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('162af2d2-8c8a-45fe-bcec-48d67d1fc7e2', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'Analyze the profound irony in the climax of Michael Rosen''s poem ''Chivvy'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eec01f32-32ac-4636-8a83-762da5a1154f', 'By exhaustively scripting every microscopic movement of a child (speaking, walking, standing, nose-blowing, sock-pulling), adults systematically dismantle the child''s autonomous will, and then paradoxically scold them for being indecisive', true, '162af2d2-8c8a-45fe-bcec-48d67d1fc7e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('649dbbff-3cf9-4fb0-ab43-63f92eab44d5', 'By showing that all adults are secretly children', false, '162af2d2-8c8a-45fe-bcec-48d67d1fc7e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06fb6e40-ea89-47bc-a621-f8a2bb49d0a2', 'By encouraging children to become teachers', false, '162af2d2-8c8a-45fe-bcec-48d67d1fc7e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('120a56d9-1cf7-4fd4-81ae-6ede30077cdd', 'By proving that socks should never be worn', false, '162af2d2-8c8a-45fe-bcec-48d67d1fc7e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5627f388-66c8-461c-81cb-f68f92b85a2d', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'Match Column I (Folk Motifs / Poetic Injunctions) with Column II (Thematic Meanings):
(a) Sacred Ash on Barren Trees  -> (i) Spiritual revitalization of dead nature through pure virtue
(b) Foul Worms in Bean Paste    -> (ii) Inward moral rot projected outward by avarice and envy
(c) ''Pull your socks up!''       -> (iii) Incessant disciplinary conditioning of juvenile behavior
(d) ''Make your own mind up!''   -> (iv) Unreasonable adult contradiction after total micromanagement', 'Ashes = virtue/renewal; Worms = corrupt greed; Pull socks up = nagging drill; Make own mind up = paradoxical demand.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3e1d71e-e25d-482d-be27-586d8b3262d9', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '5627f388-66c8-461c-81cb-f68f92b85a2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00ade0ad-9049-43e1-999a-059d9446d51a', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '5627f388-66c8-461c-81cb-f68f92b85a2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5af4ae8a-fba0-455c-aab5-6f8c0ee74b16', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '5627f388-66c8-461c-81cb-f68f92b85a2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ae3dce1-607e-41a9-8dc0-9151bbb92e0e', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '5627f388-66c8-461c-81cb-f68f92b85a2d');
