INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4adefb69-59c6-4583-b74d-b4d77ae9cab5', '''A pinch of ashes was scattered over the withered cherry tree by the kind old man.''', true, 'c6bdbe11-f82f-457d-9179-c0f1765ca65f');
