INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fe7a87f-cb6d-439b-bd4b-8b48b018a8dd', '''Ashes were scattering by the kind old man.''', false, 'c6bdbe11-f82f-457d-9179-c0f1765ca65f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('724b0046-5c31-4a22-9f5f-138f31cc7027', '''A pinch of ashes had been scattering by the tree.''', false, 'c6bdbe11-f82f-457d-9179-c0f1765ca65f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac37aeda-4872-476b-8fe9-1c1dcc89b49c', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'Identify the grammatical role of the underlined participial phrase in: ''**Having gathered the sacred ashes in a basket**, the old man set out to meet the Daimyo.''', '''Having gathered...'' is a perfect participial phrase expressing prior completed temporal action modifying ''the old man''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bbb458e-985c-49cb-a401-fc27c0342952', 'Perfect Participial Phrase acting as an adverbial modifier of time/cause for the main clause', true, 'ac37aeda-4872-476b-8fe9-1c1dcc89b49c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28cd55a3-adee-43bc-9d7d-0567f1728ce5', 'Gerund acting as subject', false, 'ac37aeda-4872-476b-8fe9-1c1dcc89b49c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6769e58-f952-4ec4-a35c-62afa2c480d8', 'Noun Clause in apposition', false, 'ac37aeda-4872-476b-8fe9-1c1dcc89b49c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a20ccdc-34ac-4640-87c1-fd0063f39dfb', 'Infinitive phrase of purpose', false, 'ac37aeda-4872-476b-8fe9-1c1dcc89b49c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4c1a086-c07a-4651-a255-9ffba2ba084d', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'What is the psychological impact on children when constantly subjected to relentless ''Chivvying'' according to modern developmental psychology?', 'Over-regulation and hyper-critical micro-parenting induce self-doubt, anxiety, and suppressed creative problem-solving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8a94cc9-7181-440f-a5f6-cedf777aed75', 'It can induce learned helplessness, anxiety, loss of self-confidence, and stifle organic creative curiosity', true, 'c4c1a086-c07a-4651-a255-9ffba2ba084d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c6c6c39-921b-48f7-8c2b-5e7557526697', 'It makes children grow taller instantly', false, 'c4c1a086-c07a-4651-a255-9ffba2ba084d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f29837b-f6f3-459f-92a9-1a416c5f5bdf', 'It turns children into professional athletes automatically', false, 'c4c1a086-c07a-4651-a255-9ffba2ba084d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5983ccc4-3e14-43b8-9527-0b03844d2533', 'It eliminates the need for sleep', false, 'c4c1a086-c07a-4651-a255-9ffba2ba084d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f5aeecf-a585-4c1a-b419-499f3ab01dfe', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'In ''The Ashes That Made Trees Bloom'', how did the kind old couple spend their wealth after receiving gold from the Daimyo?', 'The couple exemplified unselfish community stewardship: buying land, hosting feasts, and aiding the indigent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb5ef787-5911-46b9-9517-cecf176a96c0', 'They bought fertile fields of land, gave a lavish feast to all their friends and neighbors, and generously provided for their poor neighbors', true, '0f5aeecf-a585-4c1a-b419-499f3ab01dfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06027c2d-b199-4667-8573-1757d6475988', 'They built a golden fortress and refused to speak to anyone', false, '0f5aeecf-a585-4c1a-b419-499f3ab01dfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c91a0549-64a5-4b57-8092-3f128294eee6', 'They sailed away to Europe on a private ship', false, '0f5aeecf-a585-4c1a-b419-499f3ab01dfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0153f60a-a5f6-4681-93f3-b65f79a36dcd', 'They buried all the gold in a deep cave', false, '0f5aeecf-a585-4c1a-b419-499f3ab01dfe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8af0486-797f-4ded-a358-56682cbb0235', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'Which of the following lines from ''Chivvy'' highlights social decorum regarding vocal volume and personal space?', 'This stanza directly addresses public decorum: vocal clarity, mastication silence, polite gaze, and hygienic boundaries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2b5f206-3558-4f37-91ed-99142f3ff2b6', '"Speak up! / Don''t talk with your mouth full / Don''t stare / Don''t point / Don''t pick your nose"', true, 'c8af0486-797f-4ded-a358-56682cbb0235');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d08c6ef-3b7f-48a6-9314-f4a27e17c533', '"Jump into the puddle!"', false, 'c8af0486-797f-4ded-a358-56682cbb0235');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2e71867-91f5-413b-b3c0-11d76384712e', '"Sing at midnight!"', false, 'c8af0486-797f-4ded-a358-56682cbb0235');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b101b48-85ab-4e02-87a8-8021459db572', '"Eat food with your fingers!"', false, 'c8af0486-797f-4ded-a358-56682cbb0235');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7398410c-a155-4fdf-b06c-356eaefac8e9', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'What cultural resonance does the ''Cherry Blossom'' (Sakura) hold in Japanese aesthetics as portrayed in this folktale?', 'Sakura (cherry blossom) in Japanese folklore represents ephemeral beauty, spiritual resurrection, and the auspicious triumph of pure virtue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('743891b1-f1f4-4506-b619-7d18474f6dde', 'Sakura symbolizes purity, spring renewal, the blossoming of divine grace, and the transient beauty of life restored through moral goodness', true, '7398410c-a155-4fdf-b06c-356eaefac8e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf174818-eb33-4982-90a1-e669daa5a71f', 'It is a symbol of war and destruction', false, '7398410c-a155-4fdf-b06c-356eaefac8e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c41a63cd-837f-4318-9854-b6e629dabd44', 'It is used only for making poison', false, '7398410c-a155-4fdf-b06c-356eaefac8e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdb64694-a273-4348-95a4-5f8940a6ddc5', 'It represents dark winter nights', false, '7398410c-a155-4fdf-b06c-356eaefac8e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c622589-756d-41a8-9413-eedea38e455c', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'What comprehensive ethical lesson links Chapter 4 of NCERT Class 7 English?', 'Chapter 4 weaves together ecological compassion, karmic benevolence, and insightful pedagogy balancing discipline with autonomy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b11da0bf-4b9b-48f0-884c-a71d887f8d07', 'True human dignity flourishes through unconditional kindness, respect for life, and understanding the delicate balance between guided discipline and nurturing independent personal thought', true, '4c622589-756d-41a8-9413-eedea38e455c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58588f07-6560-405c-9fdf-6966b31010c1', 'That children should never be corrected by anyone', false, '4c622589-756d-41a8-9413-eedea38e455c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b9d8737-7a75-44e1-89d7-2ac2d0163cee', 'That only dogs understand magic', false, '4c622589-756d-41a8-9413-eedea38e455c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8f5024b-88ab-4f4e-8e26-e0731c532090', 'That trees only bloom when beaten', false, '4c622589-756d-41a8-9413-eedea38e455c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5896689e-921e-4bc6-a212-56b6bbfa3a7a', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Easy', 'Who invented the movable-type mechanical Printing Press in Mainz, Germany around 1440 CE, sparking the global Information Revolution?', 'Johannes Gutenberg developed the movable metal type printing press c. 1440, printing the 42-Line Gutenberg Bible.', NOW()) ON CONFLICT DO NOTHING;
