INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ef80412-2e51-4a77-a38c-39eaf79683e8', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Easy', 'Who discovered the world''s first wonder antibiotic drug ''PENICILLIN'' from Penicillium notatum mold in 1928, revolutionizing medicine?', 'Alexander Fleming discovered penicillin in 1928, launching the antibiotic era and saving hundreds of millions of lives.', NOW()) ON CONFLICT DO NOTHING;
