INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b13571ae-39fc-40b2-bd95-640e40ffec33', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Easy', 'Which Portuguese explorer discovered the direct ocean sea-route from Europe to India around the Cape of Good Hope, landing at Calicut (Kozhikode) in May 1498?', 'Vasco da Gama''s 1497–1499 armada linked Europe and Asia via maritime navigation around the African continent.', NOW()) ON CONFLICT DO NOTHING;
