INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f0194bb-eb96-4856-a5cd-268e77e833ee', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Medium', 'Who was the legendary Chinese Ming Dynasty Admiral who commanded massive treasure fleets of hundreds of giant multi-decked ships across the Indian Ocean from 1405 to 1433?', 'Admiral Zheng He commanded 7 epic Ming maritime expeditions across Southeast Asia, India, Arabia, and East Africa.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f418589-d661-4d91-ae37-ffc8a888eaa4', 'Zheng He (Cheng Ho)', true, '0f0194bb-eb96-4856-a5cd-268e77e833ee');
