INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad7ecf0f-368f-4aef-a993-525e3083b152', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Medium', 'Who proved that lightning is a form of electricity using his famous kite and key experiment in 1752, inventing the Lightning Rod?', 'Benjamin Franklin demonstrated electrical charge conservation in thunderstorms and invented the grounding lightning conductor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b43cdf47-f1e3-43a1-8c7f-cb0da8417864', 'Benjamin Franklin', true, 'ad7ecf0f-368f-4aef-a993-525e3083b152');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e5cbf8b-3d06-4c13-bcfb-42ad0001fcb1', 'Thomas Edison', false, 'ad7ecf0f-368f-4aef-a993-525e3083b152');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4796517c-8b88-4a65-9ec8-d0bfbd11ac28', 'Isaac Newton', false, 'ad7ecf0f-368f-4aef-a993-525e3083b152');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb7c8fd2-d1b2-4a72-b3dc-04dd1bd035cb', 'Michael Faraday', false, 'ad7ecf0f-368f-4aef-a993-525e3083b152');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f953915-371d-44d3-b51c-bde0e23ad4f9', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Medium', 'Who discovered the fundamental Mathematical Laws of Planetary Motion in the early 17th century (elliptical orbits)?', 'Kepler formulated the three laws of planetary motion, establishing that planetary orbits are ellipses with the Sun at one focus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e451f7a-4bea-494d-af79-2e44a7f884b5', 'Johannes Kepler', true, '7f953915-371d-44d3-b51c-bde0e23ad4f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eee4ee68-b025-4c7a-a276-229decef2b11', 'Nicolaus Copernicus', false, '7f953915-371d-44d3-b51c-bde0e23ad4f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3703d23e-73ae-4d03-8b60-35adb5e3efd1', 'Galileo Galilei', false, '7f953915-371d-44d3-b51c-bde0e23ad4f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5608925-5ee2-4edc-a820-e54969db46bb', 'Tycho Brahe', false, '7f953915-371d-44d3-b51c-bde0e23ad4f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8637bbe3-2e4e-49b9-a809-562b0f2a11d5', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Medium', 'Who was the FIRST Indian citizen to travel into outer space aboard the Soviet Soyuz T-11 spacecraft on 3 April 1984, describing India as "Saare Jahaan Se Achha"?', 'Rakesh Sharma spent 7 days aboard Salyut 7 in April 1984 as India''s first cosmonaut.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddac0606-0853-465a-9e3d-21833e8613b3', 'Wing Commander Rakesh Sharma', true, '8637bbe3-2e4e-49b9-a809-562b0f2a11d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('794c2d0b-0027-4992-bd28-87b2f951cafc', 'Kalpana Chawla', false, '8637bbe3-2e4e-49b9-a809-562b0f2a11d5');
