INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('665a9c23-2a67-4e60-9778-2d5825a53244', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a4212c9-1b91-48c3-be02-7f2ca6b56a10', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '665a9c23-2a67-4e60-9778-2d5825a53244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da2bac4a-16e5-47e2-b19d-d3eabbe9c1d3', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '665a9c23-2a67-4e60-9778-2d5825a53244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26f99a7e-cf70-4305-ade5-eb3f69f0e6a0', '(A) is true, but (R) is false.', false, '665a9c23-2a67-4e60-9778-2d5825a53244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c113763-28bc-4682-9185-8fb36fc0f037', '(A) is false, but (R) is true.', false, '665a9c23-2a67-4e60-9778-2d5825a53244');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12a48e78-e666-42ab-ae39-298cc3fb3edf', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Spot the IMPOSTER in the following group of Inventors and their groundbreaking technological breakthroughs:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4a79ef0-25a7-469e-8dbd-324d4c61fa1e', 'Breakthrough 1', false, '12a48e78-e666-42ab-ae39-298cc3fb3edf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62da487f-1695-433e-942b-ad6fb21d1936', 'Breakthrough 2', false, '12a48e78-e666-42ab-ae39-298cc3fb3edf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe8ea028-2683-4c96-91e3-add2c6f9ccc7', 'Breakthrough 3', false, '12a48e78-e666-42ab-ae39-298cc3fb3edf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a027378-04fb-40fd-9486-c51b1068d996', 'Breakthrough 4 (Wright Brothers invented the FIRST AIRPLANE, not nuclear power plants)', true, '12a48e78-e666-42ab-ae39-298cc3fb3edf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cdf100f8-56e0-470b-873a-974efce900bc', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'What is the historical significance of the ''Columbian Exchange'' resulting from Christopher Columbus''s 1492 transatlantic voyage?', 'The Columbian Exchange fundamentally reorganized global ecology, nutrition (potatoes, maize to Eurasia; wheat, livestock to Americas), and demographics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('694f6c01-7a3d-4680-b875-affd9ccb62fc', 'The massive global transfer of agricultural crops (potatoes, maize, tomatoes, chillies), animals, populations, and infectious diseases between the Old World (Afro-Eurasia) and New World (Americas) that permanently transformed global diets and demographics', true, 'cdf100f8-56e0-470b-873a-974efce900bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f4ed31-afc7-41a4-b473-a5a4742ad53a', 'An agreement to sell Spanish ships to Asian kings', false, 'cdf100f8-56e0-470b-873a-974efce900bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66f6bc48-4ee4-47c7-aa21-2469e6eb872f', 'A chess tournament played in 1492', false, 'cdf100f8-56e0-470b-873a-974efce900bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('457555ff-f189-4cd1-9b5d-3c40fbe7bff6', 'The discovery of Antarctica', false, 'cdf100f8-56e0-470b-873a-974efce900bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a885a38e-2047-4567-b749-8c123263add1', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Match Column I (Great Pioneers) with Column II (Monumental Milestone):
(a) Galileo Galilei       -> (i) Telescopic discovery of Jupiter''s 4 moons & lunar craters
(b) Isaac Newton          -> (ii) Universal Law of Gravitation & Three Laws of Motion
(c) Charles Darwin        -> (iii) Theory of Evolution by Natural Selection (Origin of Species)
(d) Albert Einstein       -> (iv) Special & General Theory of Relativity (E = mc²)', 'Galileo = observational astronomy; Newton = classical mechanics; Darwin = natural selection; Einstein = relativistic physics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c106765-c3f0-4bda-bc7f-cbe523a829c5', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'a885a38e-2047-4567-b749-8c123263add1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62450263-ffe6-447a-9e2f-237b1f658fde', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'a885a38e-2047-4567-b749-8c123263add1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a4a320d-5b61-4fa6-93d8-215562e2b1ed', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'a885a38e-2047-4567-b749-8c123263add1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1955d64-208a-42ea-b108-8b09e21c5e08', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'a885a38e-2047-4567-b749-8c123263add1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b52e798b-6969-42ce-b7ae-195ab9fbc38b', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Read the statements regarding space exploration milestones:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('409a7de9-febe-4e7a-b88e-3ff2017ed0b8', 'Statements 1 and 2 only', true, 'b52e798b-6969-42ce-b7ae-195ab9fbc38b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb6c07b7-0b1a-4bc1-a671-c01e378b0076', 'Statements 2 and 3 only', false, 'b52e798b-6969-42ce-b7ae-195ab9fbc38b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('868d5da1-9538-4288-a5e5-3fdfe5e7f152', 'Statements 1 and 3 only', false, 'b52e798b-6969-42ce-b7ae-195ab9fbc38b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b888a1b-9072-4fa8-8159-114d9f34ff35', 'All Statements 1, 2, and 3', false, 'b52e798b-6969-42ce-b7ae-195ab9fbc38b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da5dbf9d-7993-40eb-abc1-111af79eac1b', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Who was the British mathematician and logician who broke the German ''Enigma'' naval code during World War II at Bletchley Park and laid the theoretical foundations of Artificial Intelligence and Computer Science (Turing Machine)?', 'Alan Turing engineered the Bombe codebreaking machine, formulated the Turing Machine universal computation model, and proposed the Turing Test for AI.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53ccd1ba-678f-442a-a527-a6272fb1cef4', 'Alan Turing', true, 'da5dbf9d-7993-40eb-abc1-111af79eac1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a938252f-50d4-44bd-92f9-59a65b9fae8f', 'John von Neumann', false, 'da5dbf9d-7993-40eb-abc1-111af79eac1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d4a0985-3390-4f3b-af70-7585e8e46869', 'Claude Shannon', false, 'da5dbf9d-7993-40eb-abc1-111af79eac1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56997d2f-de29-4b0a-ba88-e3b088b92007', 'Norbert Wiener', false, 'da5dbf9d-7993-40eb-abc1-111af79eac1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f7d4d23-3f1f-4b97-bef8-7314b254290c', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'What was the revolutionary medical discovery made by Edward Jenner in 1796 that transformed public health worldwide?', 'Jenner''s cowpox-smallpox cross-immunity trial established the scientific doctrine of vaccination (from Latin ''vacca'' meaning cow).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52cf0730-741c-4ae8-97be-5fa110ab7480', 'Inoculating humans with mild Cowpox blister fluid conferred immune protection (cross-immunity) against lethal Smallpox without causing fatal disease', true, '5f7d4d23-3f1f-4b97-bef8-7314b254290c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('587d9303-e5cd-4a01-814f-c4da6554c603', 'He discovered that boiling water prevents broken bones', false, '5f7d4d23-3f1f-4b97-bef8-7314b254290c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7efac258-1ad5-42e5-82f5-7254f7400ec3', 'He created synthetic aspirin pills', false, '5f7d4d23-3f1f-4b97-bef8-7314b254290c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1211fd56-6325-491a-bbef-663a6859ad6e', 'He proved that diseases are caused by bad smells (miasma)', false, '5f7d4d23-3f1f-4b97-bef8-7314b254290c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4d4af58-1507-4a87-adf6-68e219c33024', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Consider four foundational inventions:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b016e8b2-0268-4cd9-8d7b-1237cb64fde4', 'Each invention radically accelerated the velocity and scale of human communication, energy transformation, and global knowledge distribution', true, 'a4d4af58-1507-4a87-adf6-68e219c33024');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80bbbc05-ab54-425f-86d0-0e64768a7839', 'They were all invented in the same country', false, 'a4d4af58-1507-4a87-adf6-68e219c33024');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4433f017-c176-4e59-99af-b5249b77682f', 'They all use steam energy', false, 'a4d4af58-1507-4a87-adf6-68e219c33024');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aed7d1c3-c5b2-4f8e-a157-fe25dff3e60d', 'They all operate on batteries', false, 'a4d4af58-1507-4a87-adf6-68e219c33024');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e53d0aa2-0126-4265-8b52-68f9fcf4ff45', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Why was the discovery of the double helix structure of DNA by James Watson, Francis Crick, and Rosalind Franklin in 1953 so monumental?', 'Elucidating the double helical base-pairing (A-T, G-C) architecture of DNA launched molecular biology, biotechnology, and genomic medicine.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ced3dcdc-e0cb-4515-b1cc-4a2b4656e4fc', 'It unlocked the molecular genetic code of all biological life, revealing how hereditary information is stored, replicated, and expressed across generations', true, 'e53d0aa2-0126-4265-8b52-68f9fcf4ff45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('807c1335-692b-4db0-862e-a067ad2a1f71', 'It proved that cells are made of stone', false, 'e53d0aa2-0126-4265-8b52-68f9fcf4ff45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ea63a7e-e4db-47a3-9970-4d77b4c4513e', 'It allowed humans to stop eating food', false, 'e53d0aa2-0126-4265-8b52-68f9fcf4ff45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('407abb8a-7222-4f80-827b-9003ba2c0952', 'It proved that blood has no cells', false, 'e53d0aa2-0126-4265-8b52-68f9fcf4ff45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0c51777-1b89-46fc-9243-907d7f64ae95', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'What was the navigational breakthrough invented by John Harrison in the 18th century (the Marine Chronometer H4)?', 'Harrison''s H4 chronometer solved the famous ''Longitude Problem'', enabling precise oceanic navigational positioning.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7e4ac14-6431-478d-ad15-f84ce7133962', 'A precise mechanical clock that kept exact time at sea despite ship motion and temperature changes, enabling sailors to calculate exact LONGITUDE and preventing shipwrecks', true, 'f0c51777-1b89-46fc-9243-907d7f64ae95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f8dc64c-2855-44a9-bbfe-89acdbdaf561', 'A compass that pointed south', false, 'f0c51777-1b89-46fc-9243-907d7f64ae95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96686025-9e04-4142-b805-e9484c272322', 'A waterproof sail', false, 'f0c51777-1b89-46fc-9243-907d7f64ae95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b92c20b6-cecd-4cc9-ab0d-fd4311ef3840', 'A telescope that saw through clouds', false, 'f0c51777-1b89-46fc-9243-907d7f64ae95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d066bc5-6f28-471e-9d0b-71a8cb1b84b4', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Who was the Polish astronomer whose 1543 book ''De revolutionibus orbium coelestium'' shattered the 1,400-year Geocentric Ptolemaic model and proved the HELIOCENTRIC model (Earth orbits the Sun)?', 'Copernicus displaced Earth from the cosmological center, proposing the heliocentric planetary system and igniting the Scientific Revolution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0baacbd-29c4-46cd-8b7b-ae2cc151c1f9', 'Nicolaus Copernicus', true, '2d066bc5-6f28-471e-9d0b-71a8cb1b84b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8529c359-2463-491c-9150-96603a562999', 'Tycho Brahe', false, '2d066bc5-6f28-471e-9d0b-71a8cb1b84b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9669e176-6612-4fcd-ba02-3a9a0a78880c', 'Aristotle', false, '2d066bc5-6f28-471e-9d0b-71a8cb1b84b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4596b4fc-f987-44b4-8ae3-e73ac678adf3', 'Ptolemy', false, '2d066bc5-6f28-471e-9d0b-71a8cb1b84b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6da473d0-a608-4e9b-a460-0f885213831f', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'What unifying human spirit is celebrated through the history of Great Inventions, Discoveries, and Explorations?', 'Chapter 4 synthesizes the relentless human drive for scientific discovery, geographic exploration, and transformative technological innovation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('143667ad-2a66-44be-ae99-d282c31a4195', 'Humanity''s relentless curiosity, resilience, and courage to question prevailing orthodoxies, venture into uncharted frontiers, and innovate technologies that elevate human civilization', true, '6da473d0-a608-4e9b-a460-0f885213831f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('babb3319-d1ec-4d64-8b12-b6cd5c632a92', 'That all discoveries were made by pure accident without effort', false, '6da473d0-a608-4e9b-a460-0f885213831f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0a6a1ab-bab0-4765-a7f6-739cb613320e', 'That exploration has completely finished on Earth and in space', false, '6da473d0-a608-4e9b-a460-0f885213831f');
