INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e7c40f9-b6d5-4472-b102-6bda6c02df91', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'From which two great historical royal lineages were the Mughals descended?', 'Maternal descent from Genghis Khan (d. 1227) and paternal lineage from Timur (d. 1404).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3487d213-3458-40ab-a82e-f37b2ae4a45f', 'On their mother''s side from Genghis Khan (Mongol ruler) and on their father''s side from Timur (ruler of Iran, Iraq, and Central Asia)', true, '1e7c40f9-b6d5-4472-b102-6bda6c02df91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5bc3b2f-2bc2-4f65-9a58-93e181aabed2', 'From Alexander the Great and Julius Caesar', false, '1e7c40f9-b6d5-4472-b102-6bda6c02df91');
