INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5296ad40-94b6-4fec-870d-a6b5709df118', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Who was the founder of the Mughal Empire in India, who defeated Ibrahim Lodi in the First Battle of Panipat in 1526 CE?', 'Babur captured Delhi and Agra in 1526 after defeating Ibrahim Lodi at the First Battle of Panipat.', NOW()) ON CONFLICT DO NOTHING;
