INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc6fe384-a7f3-46f7-b939-d73492907ab7', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Which battle fought in 1527 CE cemented Babur''s control over northern India by defeating Rana Sanga of Mewar and his Rajput confederacy?', 'In 1527 at Khanwa, Babur defeated Rana Sanga and his Rajput allies, securing the Gangetic heartland.', NOW()) ON CONFLICT DO NOTHING;
