INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c46bd24-5265-4f39-be39-d8a21d85b5cc', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Who ascended the Mughal throne at the age of 13 in 1556 CE under the guardianship of Bairam Khan, expanding the empire into a pan-subcontinental powerhouse?', 'Akbar ascended the throne in 1556 at Kalanaur (Punjab) at age 13, guided by his regent Bairam Khan.', NOW()) ON CONFLICT DO NOTHING;
