INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b83257e-b7af-4d08-acf9-b8fc23dc8a54', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'What was the administrative and military ranking system introduced by Akbar to organize imperial nobility and soldiers called?', 'Akbar instituted the Mansabdari system to structure military command, noble status, and official salary.', NOW()) ON CONFLICT DO NOTHING;
