INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fbe031f-a55c-415c-bb65-a9a3c78d26bd', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'In the Mansabdari system, what did the numerical rank ''ZAT'' determine?', 'Zat was the numerical index determining personal prestige, protocol ranking, and salary scale.', NOW()) ON CONFLICT DO NOTHING;
