INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cdc1e1be-91fa-43a8-8058-c7ad3abcd689', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'In the Mansabdari system, what did the numerical rank ''SAWAR'' specify?', 'Sawar rank fixed the military cavalry contingent (horsemen) the officer was legally obligated to muster.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb94a614-ff4c-40d9-9694-b622462d2d21', 'The exact number of maintained cavalrymen (horsemen) the Mansabdar was required to maintain for state service', true, 'cdc1e1be-91fa-43a8-8058-c7ad3abcd689');
