INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dc78e84-4360-4e67-9db9-0cbc0aaab12b', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'What were the revenue assignments from which Mansabdars received their salaries (similar to Sultanate Iqtas) called?', 'Jagirs were revenue-yielding territorial tracts granted to Mansabdars to cover their sanctioned salary allowances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20127a8a-de3f-433a-98c2-d1e1dcd28d10', 'Jagirs (and the holders were called Jagirdars)', true, '6dc78e84-4360-4e67-9db9-0cbc0aaab12b');
