INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb9922cf-17d3-4b56-aadf-8eee72551974', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Who was Akbar''s brilliant Revenue Minister who carried out a careful 10-year survey (1570–1580) of crop yields, prices, and cultivated areas to establish the ''Zabt'' revenue system?', 'Raja Todar Mal formulated the ''Ain-i Dahsala'' (10-year revenue assessment) and Zabt cash-revenue schedules.', NOW()) ON CONFLICT DO NOTHING;
