INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72fc69a5-2837-4144-904d-531c8ff88281', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Who was Akbar''s close friend, courtier, and court historian who wrote the monumental three-volume official history ''Akbar Nama'' and ''Ain-i Akbari''?', 'Abul Fazl composed the Akbar Nama (Vol 1: ancestors, Vol 2: Akbar''s reign) and Vol 3: Ain-i Akbari (administration and statistics).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b205cc3-4ffc-40f4-8303-a413b5ef6651', 'Abul Fazl', true, '72fc69a5-2837-4144-904d-531c8ff88281');
