INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c441e39-dbf0-499b-a0be-2a32fad5b945', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'What was the philosophical doctrine of ''Universal Peace'' and religious tolerance formulated by Akbar and Abul Fazl called?', 'Sulh-i Kul (peace with all) promoted universal religious tolerance and justice without sectarian discrimination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7763dc4-7cba-4660-af7f-d3e2d01a0606', 'Sulh-i Kul (Universal Peace / Absolute Tolerance)', true, '1c441e39-dbf0-499b-a0be-2a32fad5b945');
