INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a529a0f-017c-4e08-90f1-7dda2112fc20', 'Mansab', false, '1c441e39-dbf0-499b-a0be-2a32fad5b945');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82275a1f-a802-4234-997d-7ed8de172e14', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'In which hall of inter-faith discussions built at Fatehpur Sikri in 1575 did Akbar hold spiritual dialogues with theologians of diverse religions (Ulama, Brahmins, Jesuit priests, Zoroastrians)?', 'The Ibadat Khana at Fatehpur Sikri hosted comparative theological debates leading Akbar to develop Sulh-i Kul.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a8d389d-8d9c-4987-b54f-384d8b827ba4', 'Ibadat Khana (House of Worship)', true, '82275a1f-a802-4234-997d-7ed8de172e14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72d67798-7a50-4beb-b982-d5981e2a4cfc', 'Diwan-i Aam', false, '82275a1f-a802-4234-997d-7ed8de172e14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afa95850-07b7-48a3-816e-c9e0b61a2259', 'Diwan-i Khas', false, '82275a1f-a802-4234-997d-7ed8de172e14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('754f592d-bf5e-425b-9ce9-a1d2f20632a1', 'Buland Darwaza', false, '82275a1f-a802-4234-997d-7ed8de172e14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0247ff95-5102-4a48-9d79-7609a1d59521', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the Mughal custom of dynastic succession regarding the inheritance of royal power?', 'The Mughals rejected strict primogeniture, adhering to Timurid coparcenary partition which sparked violent fratricidal succession wars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c09e0c8d-3d06-43b0-a816-15d765a21f36', 'Coparcenary Inheritance (Timurid tradition of dividing the empire among all brothers / sons), which frequently triggered bitter wars of succession among royal princes', true, '0247ff95-5102-4a48-9d79-7609a1d59521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afdbd361-19e2-4cd3-9eae-57a1be3ffe00', 'Strict Primogeniture (only the eldest son inherits everything)', false, '0247ff95-5102-4a48-9d79-7609a1d59521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('809ce546-fb93-4ebe-a91e-4c6c4084425b', 'Election by public voting', false, '0247ff95-5102-4a48-9d79-7609a1d59521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ad8738e-4a6a-4edb-a257-4c843f065663', 'The crown was passed to the King''s uncle', false, '0247ff95-5102-4a48-9d79-7609a1d59521');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc4acc82-4717-4d9f-a3ba-2a9f4f6e640d', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'How did Akbar build a lasting alliance with Rajput rulers (such as the Kachhwahas of Amber) to consolidate his pan-Indian empire?', 'Akbar''s Rajput policy combined diplomatic respect, matrimonial ties, high court ranks (Man Singh), and autonomy over Watan Jagirs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e431385-1b21-4799-b982-830953f1eb20', 'He respected Rajput martial honor, formed marital matrimonial alliances, granted high Mansabdari military commands to Rajput chiefs, and restored conquered lands as hereditary ''Watan Jagirs''', true, 'fc4acc82-4717-4d9f-a3ba-2a9f4f6e640d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d5f493b-b389-4d8e-9759-4a6851a1e915', 'He imprisoned all Rajput kings', false, 'fc4acc82-4717-4d9f-a3ba-2a9f4f6e640d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a2a36d-37aa-4814-969b-fec106a22ec7', 'He banned Rajput culture', false, 'fc4acc82-4717-4d9f-a3ba-2a9f4f6e640d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f812e27e-2805-4aba-bfaa-8fe02124b517', 'He forced Rajputs to migrate to Iran', false, 'fc4acc82-4717-4d9f-a3ba-2a9f4f6e640d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e6f5b4a-0272-4341-981b-ceb0b06ccbc7', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Who was Mehr-un-Nisa (Empress Nur Jahan) and what immense political authority did she exercise during the reign of Emperor Jahangir?', 'Nur Jahan exercised supreme administrative co-sovereignty, issuing sovereign farmans and appearing on imperial coinage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07b9528a-a56b-4b3d-bfb1-65bae3b62505', 'She was Jahangir''s brilliant, exceptionally influential empress who held supreme imperial power, issued royal farmans (orders), and had coins minted jointly in her name alongside the Emperor', true, '9e6f5b4a-0272-4341-981b-ceb0b06ccbc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('865b0356-56f9-4626-a1f0-b7aaf379323a', 'She was a court poetess with no political power', false, '9e6f5b4a-0272-4341-981b-ceb0b06ccbc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ff04467-d60c-4fd9-84a4-5d84c80f9ca3', 'She lived in exile outside India', false, '9e6f5b4a-0272-4341-981b-ceb0b06ccbc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('249d2853-3685-4294-8cab-6cea0e97f6a6', 'She was the ruler of Bengal', false, '9e6f5b4a-0272-4341-981b-ceb0b06ccbc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8edbb795-d26b-4e29-85bf-98651bb0b323', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the administrative division of the Mughal Empire under Akbar?', 'Suba (governed by Subadar and financial Diwan) → Sarkar (district under Faujdar) → Pargana (under Shiqdar and Amil) → Grama.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8894663f-a73a-4ffa-bc19-b1350ed15f36', 'The empire was divided into Subas (provinces) governed by a Subadar ; each Suba was subdivided into Sarkars (districts) and Parganas (sub-districts/parishes)', true, '8edbb795-d26b-4e29-85bf-98651bb0b323');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4449eacf-b3a8-4e20-9f82-f300546b1a21', 'The empire had no provinces', false, '8edbb795-d26b-4e29-85bf-98651bb0b323');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('625739c9-0860-45df-93f7-2f8d0115e254', 'The empire was divided into 100 kingdoms', false, '8edbb795-d26b-4e29-85bf-98651bb0b323');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1204c3b5-15e8-455a-bd6e-ad4f83d34c05', 'The empire was divided into two halves: North and South', false, '8edbb795-d26b-4e29-85bf-98651bb0b323');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef959a56-43df-4ffe-80ef-de4ef73bb1c9', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'In Mughal provincial administration, who were the ''Subadar'' and the ''Diwan'' of a province (Suba)?', 'Mughal checks-and-balances: executive-military authority resided in the Subadar; fiscal-financial authority resided independently in the Diwan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a738ecd-fca8-4002-a779-d861ed50d92b', 'The Subadar carried out political and military functions ; the Diwan was the financial officer responsible for revenue collection and accounting', true, 'ef959a56-43df-4ffe-80ef-de4ef73bb1c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bb72770-f3c1-4c01-a65c-2821ef4aa6ae', 'The Subadar was a doctor ; the Diwan was a teacher', false, 'ef959a56-43df-4ffe-80ef-de4ef73bb1c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caa82cad-cd0d-4c56-bedf-2c2f0688b65b', 'Both were palace musicians', false, 'ef959a56-43df-4ffe-80ef-de4ef73bb1c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f156b803-9535-4506-acdb-08f0ee624163', 'The Diwan was the supreme general and Subadar was the cook', false, 'ef959a56-43df-4ffe-80ef-de4ef73bb1c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0baafadd-4170-4a22-bb47-eae3b4245003', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the ''Zabt'' revenue system formulated by Todar Mal?', 'Zabt established empirical crop-specific cash schedules based on standard land measurement (bigha/jarib) and 10-year price averages.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bded822b-94cf-4ddb-92d8-df94414cb19b', 'A scientific revenue system where agricultural land was physically surveyed/measured, crop yields and market price indices over 10 years were calculated, and each crop was assigned a fixed cash revenue tax schedule', true, '0baafadd-4170-4a22-bb47-eae3b4245003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a4ae56b-4487-40e8-b719-abdf94e81bd8', 'A tax on all horses', false, '0baafadd-4170-4a22-bb47-eae3b4245003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f53712b-a692-4f45-9811-bf2e7dca0ba4', 'A system where soldiers took all food by force', false, '0baafadd-4170-4a22-bb47-eae3b4245003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3590c23-ad31-43b9-9a2e-c0d25de10471', 'A tax only on foreign traders', false, '0baafadd-4170-4a22-bb47-eae3b4245003');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c87ca856-7389-4add-95a4-374f5d4282f4', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'In Mughal society, what blanket umbrella term was used to describe all rural intermediaries—whether powerful local village headmen (Muqaddams/Chaudhuris) or hereditary regional chieftains?', 'The Mughals employed ''Zamindar'' generically for all rural landed intermediaries collecting agricultural surplus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38cb1331-48cc-417f-b02e-0628a19c43e8', 'Zamindars', true, 'c87ca856-7389-4add-95a4-374f5d4282f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d1eb138-52a6-4114-b55a-6e82294520f5', 'Mansabdars', false, 'c87ca856-7389-4add-95a4-374f5d4282f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dabc14a5-5bdf-4380-aea0-5239f176a06a', 'Jagirdars', false, 'c87ca856-7389-4add-95a4-374f5d4282f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64f93180-9a94-4425-abb7-71f3d4a539df', 'Subadars', false, 'c87ca856-7389-4add-95a4-374f5d4282f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7577d1da-2ad7-421e-ba99-6ed6e98f597a', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Why did the Sisodiya Rajputs of Mewar refuse to accept Mughal authority for a long time, and how did the Mughals treat them when they finally surrendered to Jahangir in 1614?', 'Jahangir preserved Sisodiya dignity by restoring Mewar as a hereditary Watan Jagir exempt from personal court attendance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57846b05-54c7-433f-807b-2f9e0bf12563', 'Mewar resisted fiercely under Maharana Pratap ; upon submission under Rana Amar Singh, Jahangir treated them with honorable nobility, returning their entire territory as a Watan Jagir', true, '7577d1da-2ad7-421e-ba99-6ed6e98f597a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6acb780f-476e-4865-93fc-49da1178f70f', 'Jahangir executed all Mewar princes', false, '7577d1da-2ad7-421e-ba99-6ed6e98f597a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdc8849b-e841-4e95-a0b0-fc1c330185e1', 'Jahangir annexed Mewar and destroyed its forts', false, '7577d1da-2ad7-421e-ba99-6ed6e98f597a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02988cee-838e-4538-b551-1bdf32858633', 'Mewar was given to foreign merchants', false, '7577d1da-2ad7-421e-ba99-6ed6e98f597a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb04dc6a-b88c-43b8-adcb-984ae81779c6', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Why did Aurangzeb''s long, grinding 25-year military campaigns in the Deccan (1681–1707) lead to the severe exhaustion and eventual decline of the Mughal Empire?', 'Aurangzeb''s Deccan ulcer drained the empire''s fiscal resources, disrupted Jagirdari stability, and triggered administrative paralysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('351ef208-cc55-4609-8281-8248ec67d83b', 'Endless Deccan wars drained imperial treasuries, overextended military logistics, sparked protracted guerilla warfare with Marathas, and caused the collapse of administrative supervision in the northern heartland', true, 'cb04dc6a-b88c-43b8-adcb-984ae81779c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6e711dd-e4a9-47d9-93ea-e29117b31e56', 'Because Aurangzeb gave up his empire to become a monk', false, 'cb04dc6a-b88c-43b8-adcb-984ae81779c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0718626-9f68-4e6b-a3ae-eb1acd010123', 'Because the Deccan had no soldiers', false, 'cb04dc6a-b88c-43b8-adcb-984ae81779c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cde5287-317a-44cb-aff6-a9ff144eab69', 'Because the British invaded Delhi in 1682', false, 'cb04dc6a-b88c-43b8-adcb-984ae81779c6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71a30f3a-0afa-4a44-99d0-8e9de3eeeeda', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the ''Jagirdari Crisis'' that crippled the Mughal administration in the late 17th century under Aurangzeb?', 'Shortage of revenue-bearing paibaqi land caused the Jagirdari crisis, triggering agrarian distress and peasant rebellions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1629db3-29fc-4c62-a828-d218cf4dde9c', 'The massive inflation in the number of Mansabdars created a severe shortage of productive Jagirs; Jagirdars ruthlessly squeezed peasants for maximum revenue during their brief assignments', true, '71a30f3a-0afa-4a44-99d0-8e9de3eeeeda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58f5cc17-aac6-4252-925a-1a963e8e44dd', 'All Jagirs were destroyed by floods', false, '71a30f3a-0afa-4a44-99d0-8e9de3eeeeda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56c08326-9837-45cc-8c23-d8733a2b6eba', 'Mansabdars refused to accept lands', false, '71a30f3a-0afa-4a44-99d0-8e9de3eeeeda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3191fd9-0849-41df-8f1d-13348754c3d0', 'Jagirs were banned by imperial law', false, '71a30f3a-0afa-4a44-99d0-8e9de3eeeeda');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d62e29ff-efc1-4684-8523-7ba48ad9e5ba', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Which Maratha warrior king established an independent Maratha kingdom, using brilliant guerilla warfare (Ganimi Kava) against Aurangzeb''s armies and escaped from house arrest in Agra in 1666?', 'Chhatrapati Shivaji Maharaj forged an autonomous Maratha swarajya, defying Mughal hegemony via mobile guerrilla tactics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcda8a3d-5582-4f4b-948f-f15ddca1dad3', 'Chhatrapati Shivaji Maharaj', true, 'd62e29ff-efc1-4684-8523-7ba48ad9e5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b7dbd06-15db-4639-88ab-9b15ffbb3f36', 'Sambhaji', false, 'd62e29ff-efc1-4684-8523-7ba48ad9e5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9321566a-4b3c-4c11-bba1-012e3dc3a4a0', 'Peshwa Baji Rao I', false, 'd62e29ff-efc1-4684-8523-7ba48ad9e5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58ae4dd0-b6fc-4741-9ba3-32722403b98b', 'Shahji Bhonsle', false, 'd62e29ff-efc1-4684-8523-7ba48ad9e5ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e1f195e-3c0c-480f-a4a6-6bb60afd1f0e', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What is the third volume of Abul Fazl''s Akbar Nama called, which contains rich statistical details about crops, yields, prices, wages, administrative regulations, and cultural traditions?', 'The Ain-i Akbari constitutes the definitive imperial gazetteer and administrative-statistical compendium of Akbar''s reign.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06228dd8-7473-498f-b938-d29f64190ee6', 'Ain-i Akbari', true, '2e1f195e-3c0c-480f-a4a6-6bb60afd1f0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e73c17f-5415-4e09-a6bc-5023f8675bdb', 'Tuzuk-i Baburi', false, '2e1f195e-3c0c-480f-a4a6-6bb60afd1f0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d24f84c-6d00-4c6d-b379-d7f70740c572', 'Padshahnama', false, '2e1f195e-3c0c-480f-a4a6-6bb60afd1f0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adafcd63-0301-4e19-a7d6-ca61f3e26fbc', 'Humayun-nama', false, '2e1f195e-3c0c-480f-a4a6-6bb60afd1f0e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c69682c0-d333-45d3-b1c2-120c98f38e0e', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Which Mughal prince translated fifty Upanishads from Sanskrit into Persian (''Sirr-i Akbar'' / The Greatest Secret), appreciating the unity of divine truth across Hinduism and Islam?', 'Dara Shikoh was a philosopher-prince who translated the Upanishads and authored ''Majma-ul-Bahrain'' (Mingling of Two Oceans).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb96e874-debb-4f44-99e9-fe5fdd2b84c1', 'Dara Shikoh (eldest son of Shah Jahan)', true, 'c69682c0-d333-45d3-b1c2-120c98f38e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99098658-d702-46d1-a5e2-c3a66e654346', 'Aurangzeb', false, 'c69682c0-d333-45d3-b1c2-120c98f38e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9738f3d6-2764-4e1d-a5c4-695710680976', 'Murad Bakhsh', false, 'c69682c0-d333-45d3-b1c2-120c98f38e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49bc037f-4f9c-4267-a7aa-bd9fd57bda1b', 'Shah Shuja', false, 'c69682c0-d333-45d3-b1c2-120c98f38e0e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be19ccf9-b6e3-49df-bcc0-6c0fd92caecc', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the ''Kotwal'' in Mughal urban municipal administration?', 'The Kotwal exercised municipal police, judicial oversight, market weights inspection, and urban safety policing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39d40273-e242-49c6-83a3-a4d41c94f37b', 'The chief town police officer responsible for urban law and order, night patrols, market surveillance, and citizen registry', true, 'be19ccf9-b6e3-49df-bcc0-6c0fd92caecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa2e931d-8786-440b-87c6-511561a0342f', 'The royal chef in Delhi', false, 'be19ccf9-b6e3-49df-bcc0-6c0fd92caecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9732882f-0276-4fe3-8bc2-f03179713790', 'The head priest of the mosque', false, 'be19ccf9-b6e3-49df-bcc0-6c0fd92caecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c3c6282-8cf7-4254-9bcb-2c19f37491a4', 'The commander of royal ships', false, 'be19ccf9-b6e3-49df-bcc0-6c0fd92caecc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9501c50f-df85-4596-8568-8842069f8af7', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Which rebellious son of Aurangzeb received military support from the Marathas and the Deccan Sultanate before fleeing to Safavid Iran in 1681?', 'Prince Akbar revolted against his father Aurangzeb in 1681, allied with Sambhaji, and sought refuge with the Safavid Shah of Persia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bc5a24a-3d31-4366-8257-4976a36446d3', 'Prince Akbar (Muhammad Akbar)', true, '9501c50f-df85-4596-8568-8842069f8af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d98fb6b-a0bf-438a-8e85-7b08e6e6f081', 'Prince Azam', false, '9501c50f-df85-4596-8568-8842069f8af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfd4d48-e891-4d8d-8517-2491dff43cab', 'Prince Muazzam', false, '9501c50f-df85-4596-8568-8842069f8af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4e6bdbe-f341-4333-b103-2ad128ee662d', 'Prince Kam Bakhsh', false, '9501c50f-df85-4596-8568-8842069f8af7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc416260-2d47-479a-93c7-b89cb974e91b', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What magnificent white marble mausoleum did Emperor Shah Jahan construct in Agra along the Yamuna river in memory of his beloved wife Mumtaz Mahal?', 'The Taj Mahal is the supreme masterpiece of Indo-Islamic symmetry, Pietra Dura inlay, and domed architectural engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d42f83c-959a-4177-85a3-2319693ed7b9', 'The Taj Mahal (built between 1632 and 1648 CE)', true, 'bc416260-2d47-479a-93c7-b89cb974e91b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a5b737e-93b0-4dc3-aff8-eff88326b0d9', 'Humayun''s Tomb', false, 'bc416260-2d47-479a-93c7-b89cb974e91b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ba0793a-cade-4acc-9c7e-7ba1f66a9b43', 'Bibi Ka Maqbara', false, 'bc416260-2d47-479a-93c7-b89cb974e91b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80936fa0-509d-4e97-9685-38196e90b6e4', 'Safdarjung Tomb', false, 'bc416260-2d47-479a-93c7-b89cb974e91b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d11fe197-51e1-49bf-93c7-aaca9f41cacf', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('589ea922-dcc5-4e43-8e2b-03f8dbf95eae', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'd11fe197-51e1-49bf-93c7-aaca9f41cacf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50028237-5202-4b44-b150-ebf30d66fb80', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'd11fe197-51e1-49bf-93c7-aaca9f41cacf');
