INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb3ebc2d-9d84-4fd9-8ac0-00b6305bc93c', '(A) is false, but (R) is true.', false, 'd11fe197-51e1-49bf-93c7-aaca9f41cacf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f13d8afb-c895-481c-9572-da49484aee36', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Spot the IMPOSTER in the following chronological sequence of Mughal Emperors and their major architectural/political milestones:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a16732-0e6d-47d9-9079-135e244c4a5d', 'Milestone 1', false, 'f13d8afb-c895-481c-9572-da49484aee36');
