INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e009e3d-fbf4-448d-8b8f-3063d8b29110', 'Milestone 3', false, 'f13d8afb-c895-481c-9572-da49484aee36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda3e7f8-012a-4b76-9fd4-404716b05b15', 'Milestone 4 (The Eiffel Tower is in Paris, France ; Aurangzeb built Moti Masjid and Badshahi Mosque)', true, 'f13d8afb-c895-481c-9572-da49484aee36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a90ff97a-64ca-47c1-b8db-b9a6bd7ea7b6', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Analyze the fiscal disparity in the Mughal Empire revealed in official records:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('145e45e0-34f2-4b9d-a260-7f26f40f1a41', '61.5% of the total estimated revenue of the empire was concentrated in the hands of this tiny elite of 445 nobles', true, 'a90ff97a-64ca-47c1-b8db-b9a6bd7ea7b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('037f3627-beb6-437f-8fd2-a6e899b30872', '10% of the total revenue', false, 'a90ff97a-64ca-47c1-b8db-b9a6bd7ea7b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e904754-d6aa-4366-8eda-169849b01666', '100% of the total revenue', false, 'a90ff97a-64ca-47c1-b8db-b9a6bd7ea7b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bce6fd28-603a-4a37-a221-9f779c256521', '5% of the total revenue', false, 'a90ff97a-64ca-47c1-b8db-b9a6bd7ea7b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('994523d1-114a-40fb-8423-8861e50a15f0', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Match Column I (Mughal Administrative Terms) with Column II (Exact Functional Meanings):
(a) Subadar -> (i) Provincial governor commanding political and military administration
(b) Diwan   -> (ii) Provincial chief revenue and finance officer
(c) Bakhshi -> (iii) Imperial military paymaster responsible for troop muster
(d) Sadr    -> (iv) Minister in charge of religious and charitable patronage', 'Subadar = governor; Diwan = finance; Bakhshi = military paymaster; Sadr = ecclesiastical/charitable minister.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d54666e5-29b7-4b35-bcdf-478d93151079', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '994523d1-114a-40fb-8423-8861e50a15f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4223f036-6af7-4096-8a5a-78171652a59a', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '994523d1-114a-40fb-8423-8861e50a15f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba55eee1-1d1f-49a6-a6b8-ae43af7f6146', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '994523d1-114a-40fb-8423-8861e50a15f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e811fbb0-c5ca-4223-8735-4f8a92dd6972', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '994523d1-114a-40fb-8423-8861e50a15f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98271005-f4ba-49b5-a66d-c81d00111025', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Read the statements regarding Akbar''s religious policy:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d113232a-84c6-4dec-9ae8-0214388a36a2', 'Statements 1 and 2 only', true, '98271005-f4ba-49b5-a66d-c81d00111025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a50039b4-638a-41e6-a946-cf4fe49bea74', 'Statements 2 and 3 only', false, '98271005-f4ba-49b5-a66d-c81d00111025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0a8b048-98c4-4971-a9cb-3075712978d2', 'Statements 1 and 3 only', false, '98271005-f4ba-49b5-a66d-c81d00111025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba3f66c2-ea45-4d76-b4f0-d4b807798a22', 'All Statements 1, 2, and 3', false, '98271005-f4ba-49b5-a66d-c81d00111025');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08bc79f2-994e-446d-bead-b2a47cdffbed', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Why did the Mughals prefer not to be called ''Moghol / Mongol'' and took great pride in their ''Timurid'' paternal lineage?', 'The dynasty distanced itself from the gory memory of Genghisid massacres, glorifying their Timurid renaissance patrimony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ead43eee-5571-40ed-9870-c8f9933f4ddb', 'The name Mongol was historically associated with Genghis Khan''s brutal massacres of countless innocent people, whereas their ancestor Timur had captured Delhi in 1398 with great royal prestige', true, '08bc79f2-994e-446d-bead-b2a47cdffbed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a577fc0e-99cb-43c2-bfc1-118bf0d637c6', 'Because Timur was a European king', false, '08bc79f2-994e-446d-bead-b2a47cdffbed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f1bc866-ec8f-4d99-9a22-48a166a0d498', 'Because Mongols had no horses', false, '08bc79f2-994e-446d-bead-b2a47cdffbed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f926f46b-6a8d-46a0-ae4c-4359cad308cd', 'Because Babur could not speak Persian', false, '08bc79f2-994e-446d-bead-b2a47cdffbed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e670319d-d6d1-4979-9c28-292dff0abc79', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'How did the introduction of Field Artillery (cannons and matchlocks) revolutionize military warfare in India during Babur''s 1526 Panipat campaign?', 'Babur deployed Ottoman tactical innovation: chaining baggage wagons to shield matchlock gunners, supported by deadly flanking cavalry encirclement (Tulghuma).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3c9a149-898d-438d-a933-f3bc7c2d1eff', 'Babur combined gunpowder artillery carts (Rumi device) with rapid flanking cavalry maneuvers (Tulghuma), completely decimating Ibrahim Lodi''s massive static war elephant army', true, 'e670319d-d6d1-4979-9c28-292dff0abc79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('784c4252-6743-4fc0-8b78-c55ca0eb8f1e', 'Artillery made soldiers walk backwards', false, 'e670319d-d6d1-4979-9c28-292dff0abc79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c90ef49-27da-4c74-807a-f232c4abdca6', 'Artillery destroyed all food in India', false, 'e670319d-d6d1-4979-9c28-292dff0abc79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('157b05ea-4cc6-4187-bd63-aa8d7b1a5b62', 'Cannons were made of wood and burned down', false, 'e670319d-d6d1-4979-9c28-292dff0abc79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b23123ca-bae8-4bc3-a949-647a5429f376', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'What was the structural relationship between the Mughal Emperor, the Zamindars, and the Peasantry?', 'Local Zamindars held traditional kinship ties with village cultivators; imperial over-exploitation frequently triggered joint agrarian revolts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0da58b3-28b2-44c7-9d05-3832a1901a39', 'Peasants produced the agrarian wealth; Zamindars collected the produce and shared local caste/lineage ties with peasants, occasionally leading armed peasant rebellions against excessive central Mughal tax demands', true, 'b23123ca-bae8-4bc3-a949-647a5429f376');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc814e5e-f1a2-409c-b147-b2e98029c3ae', 'Zamindars gave all their land to the Emperor for free', false, 'b23123ca-bae8-4bc3-a949-647a5429f376');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1461f775-c888-4e1e-b2dc-029356ef28c2', 'Peasants were paid salaries in gold by the Emperor', false, 'b23123ca-bae8-4bc3-a949-647a5429f376');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b93174bc-0f6c-4e11-8ae6-d78c54d43af5', 'There were no taxes in the Mughal Empire', false, 'b23123ca-bae8-4bc3-a949-647a5429f376');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a7ad756-5884-42b3-80a5-243a75431ee6', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Consider four key regions that mounted fierce resistance against Mughal expansion in the 17th century:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce467247-367d-4298-8c9b-6a3cf753ed59', 'They leveraged rugged regional terrain, intense local community cohesion, and decentralized mobile warfare to resist centralized imperial domination', true, '8a7ad756-5884-42b3-80a5-243a75431ee6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3bde668-9538-4543-8b62-83df2049b86f', 'They all surrendered without fighting', false, '8a7ad756-5884-42b3-80a5-243a75431ee6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbe1fe36-8381-4f34-80dd-36551a22b498', 'They allied with the British against the Mughals', false, '8a7ad756-5884-42b3-80a5-243a75431ee6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04c14e42-0942-4358-861e-f2c32da415fb', 'They abandoned their lands and moved to Central Asia', false, '8a7ad756-5884-42b3-80a5-243a75431ee6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e63bb33-ae6b-491f-b1fb-05c4a485e290', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Why is Abul Fazl''s ''Ain-i Akbari'' celebrated by modern socio-economic historians as a pioneering masterwork of statistical administration?', 'The Ain-i Akbari is a landmark in quantitative historiography, offering quantitative demographic, agricultural, and administrative inventories.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e31440a-cae6-4009-85b2-50e50096c70e', 'It provides rigorous empirical statistical surveys of agricultural revenue, price tables, daily wages, military rolls, fauna, flora, and socio-religious traditions across all 15 Subas of Akbar''s empire', true, '5e63bb33-ae6b-491f-b1fb-05c4a485e290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3d85331-6c31-4eeb-ad26-8b073e9d17b1', 'It is a fictional novel of magic and fantasy', false, '5e63bb33-ae6b-491f-b1fb-05c4a485e290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfd1a5d2-7664-4c05-bf74-f952bf750ab2', 'It was written in modern English', false, '5e63bb33-ae6b-491f-b1fb-05c4a485e290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32f03096-c809-446c-87f8-22cee33bceb2', 'It contains no numbers or records', false, '5e63bb33-ae6b-491f-b1fb-05c4a485e290');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1af9ec27-2a85-470a-a8ce-888353b7cf18', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'What architectural innovation distinguishes the ''Charbagh'' (Four-Gardens) layout perfected by Mughal emperors (e.g. Humayun''s Tomb, Shalimar Gardens)?', 'Charbagh architecture geometricizes Persian paradise garden symbology: quadripartite orthogonal grids bisected by flowing water channels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba7fdf8f-8071-4f36-8697-e1af438f5ede', 'A grand rectangular walled enclosure divided into four symmetrical quadrangles by intersecting, axial raised artificial water channels and walkways, symbolizing the four rivers of Paradise', true, '1af9ec27-2a85-470a-a8ce-888353b7cf18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01978d8a-23c8-422d-84c8-669ebf5d5b69', 'A garden with only four flowers', false, '1af9ec27-2a85-470a-a8ce-888353b7cf18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80321c22-75de-4b41-bcd7-3890fc9ebc56', 'A circular maze made of glass', false, '1af9ec27-2a85-470a-a8ce-888353b7cf18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20e678d4-5219-42d7-8d40-280fe7e50918', 'A underground garden without sunlight', false, '1af9ec27-2a85-470a-a8ce-888353b7cf18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ef17678-d2a4-4393-bc4b-ebd08df5f8c5', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'What overarching historical legacy defines Chapter 4 of NCERT Class 7 History regarding the Mughal Empire?', 'Chapter 4 synthesizes the political institutionalization, fiscal centralization, architectural elegance, and cultural pluralism of the Mughal Empire.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc5d9f99-c584-47c7-962d-ce6ad33aa5fe', 'The creation of a pan-Indian empire that established enduring administrative frameworks, standardized revenue and coinage systems, synthesized composite Indo-Islamic art and architecture, and promoted cultural pluralism under Sulh-i Kul', true, '1ef17678-d2a4-4393-bc4b-ebd08df5f8c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8cff6ea-e04d-45c6-a5a9-c15ca271a2d2', 'A period of constant darkness with no administration', false, '1ef17678-d2a4-4393-bc4b-ebd08df5f8c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4136d8f-570d-48f5-8f87-89b367c96b4d', 'The complete end of all Indian culture', false, '1ef17678-d2a4-4393-bc4b-ebd08df5f8c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5497c682-163b-42d4-95b5-e2039fa8e0b1', 'An empire that lasted only two weeks', false, '1ef17678-d2a4-4393-bc4b-ebd08df5f8c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06592240-e244-42ee-b0ab-d432bbe55fbc', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'वे शब्दांश जो किसी मूल शब्द के पहले (आरंभ में) जुड़कर उसके अर्थ में परिवर्तन या विशेषता ला देते हैं, उन्हें व्याकरण में क्या कहते हैं?', 'उप + सर्ग: मूल शब्द के पूर्व में जुड़कर अर्थ बदलने वाले सार्थक शब्दांश ''उपसर्ग'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cc32da4-dd6f-40cd-ae1a-8b97582b1bbd', 'उपसर्ग (Prefix)', true, '06592240-e244-42ee-b0ab-d432bbe55fbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ad3b5dd-9bd5-4351-a117-be318db19cd2', 'प्रत्यय (Suffix)', false, '06592240-e244-42ee-b0ab-d432bbe55fbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b423a8a-04ed-4324-82ed-0bf8930d98ec', 'समास', false, '06592240-e244-42ee-b0ab-d432bbe55fbc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d03c35d-5604-4045-be08-2f5c60c5c938', 'संधि', false, '06592240-e244-42ee-b0ab-d432bbe55fbc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1355784-f524-4905-8e66-621ae74180bb', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'वे शब्दांश जो किसी मूल शब्द के अंत (पीछे) में जुड़कर नए शब्द का निर्माण करते हैं और उसके अर्थ में विशेषता लाते हैं, उन्हें क्या कहते हैं?', 'प्रति + अय: शब्दों के अंत में जुड़कर नया अर्थ उत्पन्न करने वाले शब्दांश ''प्रत्यय'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0b08527-3824-4074-b861-baab5776c0d9', 'प्रत्यय (Suffix)', true, 'c1355784-f524-4905-8e66-621ae74180bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68c30eb0-16f1-4d9f-b105-488b69ecb9b4', 'उपसर्ग', false, 'c1355784-f524-4905-8e66-621ae74180bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ea848f7-c10b-40be-9dba-148ea278ec6a', 'कारक', false, 'c1355784-f524-4905-8e66-621ae74180bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e025b50-074c-4d73-93ee-fcb64efd44a2', 'अव्यय', false, 'c1355784-f524-4905-8e66-621ae74180bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5501d72f-004e-4d5e-be70-8aeb05940ca9', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'हिंदी में प्रयुक्त उपसर्गों को मुख्य रूप से कितने वर्गों में बाँटा गया है?', 'उपसर्गों के 3 मुख्य स्रोत हैं: संस्कृत (तत्सम), हिंदी (तद्भव), तथा उर्दू-फ़ारसी (आगत)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4642216-2cdb-4b0c-a9c4-a71966516c14', 'तीन प्रमुख वर्गों में (1. संस्कृत के तत्सम उपसर्ग, 2. हिंदी के तद्भव उपसर्ग, 3. उर्दू-फ़ारसी के विदेशी उपसर्ग)', true, '5501d72f-004e-4d5e-be70-8aeb05940ca9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e846dcf-b1f5-44ab-9e49-72b115c78859', 'दो वर्गों में', false, '5501d72f-004e-4d5e-be70-8aeb05940ca9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('387b5c96-1ec0-4c9d-bc40-ec4915527895', 'पाँच वर्गों में', false, '5501d72f-004e-4d5e-be70-8aeb05940ca9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2145d0f8-3b69-4dd6-b21b-4fae61804782', 'चार वर्गों में', false, '5501d72f-004e-4d5e-be70-8aeb05940ca9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1be0a8c6-31ec-4747-9de2-f13b0e5d38d0', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', '''अति'' (संस्कृत उपसर्ग - अर्थ: अधिक/परे) से बना शुद्ध शब्द कौन-सा है?', 'अति + अधिक = अत्यधिक (यण संधि के साथ ''अति'' उपसर्ग का प्रयोग)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d6ce7d5-2cec-47aa-b2f0-a89ad81d6b31', 'अत्यधिक (अति + अधिक) / अत्यंत', true, '1be0a8c6-31ec-4747-9de2-f13b0e5d38d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4020d54f-f350-4fb6-b812-874a5778128a', 'अधिकार', false, '1be0a8c6-31ec-4747-9de2-f13b0e5d38d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7ad4cf8-3543-4e4f-b4d3-e5c89cef700e', 'अभिमान', false, '1be0a8c6-31ec-4747-9de2-f13b0e5d38d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ef5714c-76ef-4dd0-ba42-2c4d1045e903', 'अनुवाद', false, '1be0a8c6-31ec-4747-9de2-f13b0e5d38d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df27988b-e1bc-4450-8b38-1ae47c7654e0', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', '''प्र'' उपसर्ग (अर्थ: अधिक/आगे) से बने शब्दों का सही समूह कौन-सा है?', 'प्र + हार = प्रहार, प्र + गति = प्रगति, प्र + बल = प्रबल।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7de47c2-c084-4483-9816-f797c6f3086e', 'प्रहार, प्रगति, प्रबल, प्रसिद्ध', true, 'df27988b-e1bc-4450-8b38-1ae47c7654e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cd890cb-3c50-4767-990f-86ba3e14198f', 'अपमान, अपराध', false, 'df27988b-e1bc-4450-8b38-1ae47c7654e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3181c89e-bd48-48a0-8026-445f5a6bbe1e', 'अनुज, अनुराग', false, 'df27988b-e1bc-4450-8b38-1ae47c7654e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbb0ca1b-ea0d-41e8-ad54-ff68033ea749', 'उपकार, उपवन', false, 'df27988b-e1bc-4450-8b38-1ae47c7654e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cde6629-5bdf-4431-b17b-b7b6f12cc457', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'हिंदी के तद्भव उपसर्ग ''अ'' / ''अन'' (अर्थ: अभाव/निषेध) से बने शब्दों का सही उदाहरण कौन-सा है?', 'अ + काल = अकाल; अन + पढ़ = अनपढ़; अन + जान = अनजान।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1921e57a-3b0f-44a2-9864-926dfd86ae13', 'अछूत, अकाल, अनपढ़, अनजान', true, '3cde6629-5bdf-4431-b17b-b7b6f12cc457');
