INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94f597cc-2b21-41e5-bfdb-4de3727b3ad2', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'उर्दू-फ़ारसी उपसर्ग ''बे'' (अर्थ: बिना / रहित) से बने शब्दों का सही समूह कौन-सा है?', 'बे + कसूर = बेकसूर, बे + इमान = बेइमान, बे + परवाह = बेपरवाह।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b37c998b-3566-4622-ac70-51386dd18d5b', 'बेकसूर, बेइमान, बेपरवाह, बेदाग', true, '94f597cc-2b21-41e5-bfdb-4de3727b3ad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('974dedd9-ad33-4ebb-b5bf-96368fa55c0d', 'लापरवाह, लावारिस', false, '94f597cc-2b21-41e5-bfdb-4de3727b3ad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b00e26c1-1df8-480c-8eaa-713df1ff059b', 'बदनाम, बदसूरत', false, '94f597cc-2b21-41e5-bfdb-4de3727b3ad2');
