INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b808b3b-7c38-465b-b3ef-7cfec0a0d9f3', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'प्रत्यय के मुख्य रूप से कितने भेद होते हैं?', 'प्रत्यय के दो मूल भेद हैं: कृत प्रत्यय (धातु/क्रिया के साथ) तथा तद्धित प्रत्यय (संज्ञा/सर्वनाम/विशेषण के साथ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54d968b2-5333-4dd8-9742-9a1f1267dc3a', 'दो भेद (1. कृत / कृदंत प्रत्यय - क्रिया/धातु के अंत में, 2. तद्धित प्रत्यय - संज्ञा/सर्वनाम/विशेषण के अंत में)', true, '0b808b3b-7c38-465b-b3ef-7cfec0a0d9f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b9a5489-cc6b-44d0-8a7c-465f8a4261ef', 'चार भेद', false, '0b808b3b-7c38-465b-b3ef-7cfec0a0d9f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41a48601-49d1-4580-bfaa-573e80c8830a', 'तीन भेद', false, '0b808b3b-7c38-465b-b3ef-7cfec0a0d9f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df14f7af-a4ab-4a60-9d1c-e55a66702499', 'पाँच भेद', false, '0b808b3b-7c38-465b-b3ef-7cfec0a0d9f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5520b69-ae20-4af5-8048-28306dffff33', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'क्रिया की मूल धातु के अंत में जुड़कर संज्ञा या विशेषण शब्द बनाने वाले प्रत्यय क्या कहलाते हैं?', 'धातु/क्रिया के अंत में प्रयुक्त प्रत्यय ''कृत प्रत्यय'' तथा निर्मित शब्द ''कृदंत'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bd8142e-5b2d-4832-84fd-aff201321e80', 'कृत प्रत्यय / कृदंत (जैसे: लिख् + आवट = लिखावट, पढ़् + आकू = पढ़ाकू)', true, 'b5520b69-ae20-4af5-8048-28306dffff33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da22b82a-fe0a-410a-a33d-61ea9200e08a', 'तद्धित प्रत्यय', false, 'b5520b69-ae20-4af5-8048-28306dffff33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7a9d7fd-eb5b-4da1-860a-5fe6dba936ce', 'उपसर्ग', false, 'b5520b69-ae20-4af5-8048-28306dffff33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1af0f38-5897-4a1f-beb4-bd495f3505ca', 'अव्यय', false, 'b5520b69-ae20-4af5-8048-28306dffff33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7329fddc-4185-4abd-ae81-106a38915bdd', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'संज्ञा, सर्वनाम और विशेषण शब्दों के अंत में जुड़कर नए शब्द बनाने वाले प्रत्यय क्या कहलाते हैं?', 'संज्ञा, सर्वनाम व विशेषण में जुड़ने वाले प्रत्यय ''तद्धित'' तथा निर्मित शब्द ''तद्धितांत'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb103e10-be17-433d-90d9-d1bcdd1a175c', 'तद्धित प्रत्यय (जैसे: मानव + ता = मानवता, मीठा + आस = मिठास)', true, '7329fddc-4185-4abd-ae81-106a38915bdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3017945-5108-4f0c-ad21-2c7db40314f0', 'कृत प्रत्यय', false, '7329fddc-4185-4abd-ae81-106a38915bdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02b86bff-1546-42ff-87a0-4f91a0bb279b', 'कृदंत प्रत्यय', false, '7329fddc-4185-4abd-ae81-106a38915bdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a522b7eb-5ff5-4cba-8529-0a27504203b2', 'धातु प्रत्यय', false, '7329fddc-4185-4abd-ae81-106a38915bdd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb5fc319-3254-47cd-9353-8f4fa03e9928', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', '''मिठास'' शब्द में मूल शब्द और प्रत्यय क्या है?', 'विशेषण ''मीठा'' में भाववाचक तद्धित प्रत्यय ''आस'' जुड़ने से ''मिठास'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f61a6aa-69e0-4891-a464-56a88f7a7626', 'मीठा (मूल शब्द) + आस (प्रत्यय)', true, 'fb5fc319-3254-47cd-9353-8f4fa03e9928');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57fc028d-6c7d-492a-a044-0946eb6689ec', 'मिठ + आस', false, 'fb5fc319-3254-47cd-9353-8f4fa03e9928');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ba9a9e6-d421-4084-87d0-50f25e0f56ac', 'मीठा + स', false, 'fb5fc319-3254-47cd-9353-8f4fa03e9928');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('082e1b1f-045b-4fb3-be5f-c8f673b8133a', 'मिठा + स', false, 'fb5fc319-3254-47cd-9353-8f4fa03e9928');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ad73edf-e9ad-4bcb-94a2-d326b9fe3aea', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', '''लिखावट'' शब्द में कौन-सा प्रत्यय प्रयुक्त हुआ है?', 'लिख् धातु में भाववाचक कृत प्रत्यय ''आवट'' जुड़ने से ''लिखावट'' शब्द बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('989adac8-5392-4bb1-a43a-6a08242e0171', 'आवट (कृत प्रत्यय)', true, '7ad73edf-e9ad-4bcb-94a2-d326b9fe3aea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4931fcef-d592-4c05-977c-c81e12ff1729', 'वट', false, '7ad73edf-e9ad-4bcb-94a2-d326b9fe3aea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab7fae49-2ded-4998-b888-aeffc1ef2375', 'आहट', false, '7ad73edf-e9ad-4bcb-94a2-d326b9fe3aea');
