INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5525d575-8ef9-42b1-a6cc-4ac76b7d950f', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''दुर्'' (संस्कृत उपसर्ग - अर्थ: बुरा/कठिन) से बने शब्दों का सही समूह कौन-सा है?', 'दुर् + लभ = दुर्लभ; दुर् + आचार = दुराचार; दुर् + गम = दुर्गम; दुर् + बल = दुर्बल।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3e35de3-3369-4c42-82d1-4b3ef2c7f441', 'दुर्लभ, दुराचार, दुर्गम, दुर्बल', true, '5525d575-8ef9-42b1-a6cc-4ac76b7d950f');
