INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bfa2679-763c-4b85-910c-5095fee9445a', 'निर्दोष, निर्धन', false, '5525d575-8ef9-42b1-a6cc-4ac76b7d950f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('daa5c2dc-d7eb-404d-bf1e-2f7a95b48d28', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''सम्'' (संस्कृत उपसर्ग - अर्थ: अच्छी तरह / पूर्णता) से बने शब्दों का सही उदाहरण कौन-सा है?', 'सम् + मान = सम्मान; सम् + तोष = संतोष (अनुस्वार रूप); सम् + कार = संस्कार।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12db2134-47e6-43a3-a5bb-597699a39642', 'सम्मान (सम्+मान), संतोष (सम्+तोष), संस्कार (सम्+कार), संपूर्ण (सम्+पूर्ण)', true, 'daa5c2dc-d7eb-404d-bf1e-2f7a95b48d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6093580d-fb50-4fbf-b2aa-56f9b316975e', 'सुपुत्र, सुगम', false, 'daa5c2dc-d7eb-404d-bf1e-2f7a95b48d28');
