INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0680a18-add7-4783-b1f6-463001b2bf98', 'स्वदेश, स्वराज्य', false, 'daa5c2dc-d7eb-404d-bf1e-2f7a95b48d28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88584a8a-bfde-49e9-8ef5-c979f5d72ae3', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''अभि'' उपसर्ग (अर्थ: सामने/श्रेष्ठ) से बने शब्दों का सही समूह कौन-सा है?', 'अभि + मान = अभिमान; अभि + नय = अभिनय; अभि + वादन = अभिवादन।', NOW()) ON CONFLICT DO NOTHING;
