INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3751b48f-ecf6-46ea-bd19-a5d7f2fb50d3', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', 'हिंदी के उपसर्ग ''कु'' (अर्थ: बुरा) से बने शब्दों का सही समूह कौन-सा है?', 'कु + पुत्र = कुपुत्र; कु + संगति = कुसंगति; कु + रूप = कुरूप।', NOW()) ON CONFLICT DO NOTHING;
