INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f026069d-0659-4f80-9db0-12fe93a1bf2e', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', 'उर्दू-फ़ारसी उपसर्ग ''कम'' (अर्थ: थोड़ा/हीन) से बने शब्दों का सही उदाहरण कौन-सा है?', 'कम + ज़ोर = कमज़ोर; कम + अक्ल = कमअक्ल; कम + उम्र = कमउम्र।', NOW()) ON CONFLICT DO NOTHING;
