INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33d5b474-5d1c-406b-9a57-c56067ad58d1', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', 'उर्दू-फ़ारसी उपसर्ग ''ला'' (अर्थ: बिना / रहित) से बने शब्दों का सही समूह कौन-सा है?', 'ला + परवाह = लापरवाह; ला + वारिस = लावारिस; ला + जवाब = लाजवाब।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19552506-fde8-43df-85f6-6ca953b015c2', 'लापरवाह, लावारिस, लाचार, लाजवाब', true, '33d5b474-5d1c-406b-9a57-c56067ad58d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55dd737b-c1cb-4310-9310-f54c01619142', 'बेकसूर, बेईमान', false, '33d5b474-5d1c-406b-9a57-c56067ad58d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('603bac1e-a257-4f34-885c-79b1045b0e7b', 'नादान, नापसंद', false, '33d5b474-5d1c-406b-9a57-c56067ad58d1');
