INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50008bb8-3379-41fc-9c21-6973b2734a34', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''इक'' प्रत्यय जुड़ने पर मूल शब्द के प्रथम स्वर में होने वाले दीर्घीकरण का सही उदाहरण कौन-सा है?', '''इक'' प्रत्यय आदि-स्वर वृद्धि करता है: अ→आ (सामाजिक), इ→ऐ (ऐतिहासिक), उ→औ (भौगोलिक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d10c6b5-41c7-49d9-842e-d43ff1d50395', 'समाज + इक = सामाजिक ; इतिहास + इक = ऐतिहासिक ; भूगोल + इक = भौगोलिक ; धर्म + इक = धार्मिक', true, '50008bb8-3379-41fc-9c21-6973b2734a34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45cd945f-17fd-41d9-be62-d591ed98e3dc', 'समाज + इक = समाजक', false, '50008bb8-3379-41fc-9c21-6973b2734a34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17d4c76c-9d53-4e9a-8ac8-41eebb0fa098', 'इतिहास + इक = इतिहासिक', false, '50008bb8-3379-41fc-9c21-6973b2734a34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25b17644-ebe5-4152-8d2f-1e23dd755b16', 'धर्म + इक = धर्मक', false, '50008bb8-3379-41fc-9c21-6973b2734a34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d51db973-30a1-42bb-9816-bb16fef30c22', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''इत'' प्रत्यय से बने शब्दों का सही समूह कौन-सा है?', 'हर्ष + इत = हर्षित; शिक्षा + इत = शिक्षित; पुष्प + इत = पुष्पित।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2c02b59-dfd6-4e04-a44a-3d85c65ea2bb', 'हर्षित (हर्ष + इत), शिक्षित (शिक्षा + इत), फलित (फल + इत), पुष्पित (पुष्प + इत)', true, 'd51db973-30a1-42bb-9816-bb16fef30c22');
