INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c672548b-b9ad-4d0d-8dcb-df84b7aec765', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''ता'' भाववाचक तद्धित प्रत्यय से बने शब्दों का सही समूह कौन-सा है?', 'मानव + ता = मानवता; सुंदर + ता = सुंदरता; कटु + ता = कटुता।', NOW()) ON CONFLICT DO NOTHING;
