INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0b33098-cf69-457a-8cce-4cd20fe39d4e', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''घबराहट'' शब्द में मूल शब्द और प्रत्यय का सही विग्रह क्या है?', 'घबराना क्रिया की धातु में भाववाचक कृत प्रत्यय ''आहट'' जुड़कर ''घबराहट'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03d7091e-156c-4fc4-96a9-62bf0346e248', 'घबराना (या घबरा) + आहट (प्रत्यय)', true, 'a0b33098-cf69-457a-8cce-4cd20fe39d4e');
