INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55e9feac-c39d-4050-a09a-4e16b45687c4', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', 'निम्नलिखित में से किस शब्द में उपसर्ग और प्रत्यय दोनों का एक साथ प्रयोग हुआ है?', 'अप (उपसर्ग) + मान (मूल शब्द) + इत (प्रत्यय) = अपमानित।', NOW()) ON CONFLICT DO NOTHING;
