INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd75a538-4a9a-415f-994c-5b044268ab1e', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', 'निम्नलिखित में से किस शब्द में उपसर्ग और प्रत्यय दोनों प्रयुक्त हुए हैं?', 'अ (उपसर्ग) + लोक (मूल शब्द) + इक (प्रत्यय) = अलौकिक।', NOW()) ON CONFLICT DO NOTHING;
