INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4679cf9b-6385-459c-a9e5-0f1ebec42e3d', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''परोपकार'' शब्द में कौन-सा उपसर्ग प्रयुक्त हुआ है?', 'पर (दूसरा) + उपकार = परोपकार (अ + उ = ओ, गुण संधि)।', NOW()) ON CONFLICT DO NOTHING;
