INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('489967e8-2061-4f49-826f-9d8132f6a145', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''प्रत्येक'' शब्द में कौन-सा उपसर्ग प्रयुक्त हुआ है?', 'प्रति + एक = प्रत्येक (इ + ए = ये, यण संधि)।', NOW()) ON CONFLICT DO NOTHING;
