INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92f9a0d4-fa61-450c-b02a-0019329667b2', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c978fba-baf9-4e7d-9a25-89d76eaf8b7b', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '92f9a0d4-fa61-450c-b02a-0019329667b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44b28c2a-48a7-4c5e-8a26-40b1de0a3452', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '92f9a0d4-fa61-450c-b02a-0019329667b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5077ee6a-efab-4f3f-9090-ef20d09c2cc9', '(A) सही है, परन्तु (R) गलत है।', false, '92f9a0d4-fa61-450c-b02a-0019329667b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a1e450-6928-49b9-a216-29addc1ea503', '(A) गलत है, परन्तु (R) सही है।', false, '92f9a0d4-fa61-450c-b02a-0019329667b2');
