INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1b42bdf-9482-4fbe-9b0f-696d92efdb16', 'युग्म 3', false, 'a4bd074a-076b-48d6-b612-09890c24e2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d0d755f-569b-4216-899a-0739e5cd281c', 'युग्म 4 (अनादर, अनहोनी में ''अन् / अन'' उपसर्ग है, ''अति'' नहीं)', true, 'a4bd074a-076b-48d6-b612-09890c24e2d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('746d07ac-67b3-4f13-9d32-cd105cee55f0', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'सुमेलित कीजिए (उपसर्ग और उनके अर्थ):
(क) उत् / उद् -> (i) ऊपर, श्रेष्ठ, ऊँचा (जैसे: उत्कर्ष, उन्नति)
(ख) दुर् / दुस् -> (ii) बुरा, कठिन, दुष्ट (जैसे: दुर्जन, दुस्साहस)
(ग) परा       -> (iii) विपरीत, पीछे, नाश (जैसे: पराजय, पराभव)
(घ) प्रति     -> (iv) प्रत्येक, सामने, विरुद्ध (जैसे: प्रतिकूल, प्रतिध्वनि)', 'उत् = ऊँचा; दुर् = बुरा; परा = विपरीत/पराजय; प्रति = प्रत्येक/सामने।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c98ef6c3-614e-43ed-92f3-df22feb33b47', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '746d07ac-67b3-4f13-9d32-cd105cee55f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9126eac2-740c-4c47-a533-60db99c46033', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '746d07ac-67b3-4f13-9d32-cd105cee55f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fc603fd-ba1d-4bbe-9ffb-25caacf399aa', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '746d07ac-67b3-4f13-9d32-cd105cee55f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b9b305-30d2-4f97-9c66-6116b46869c5', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '746d07ac-67b3-4f13-9d32-cd105cee55f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2175fff2-97e8-4fd1-b5c6-8c4384e19d0f', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'निम्नलिखित में से किस शब्द में ''निर्'' उपसर्ग प्रयुक्त हुआ है?', 'निर् + आकार = निराकार; निर् + अपराध = निरपराध (नियम/निबंध में ''नि'' उपसर्ग है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c1b6eeb-98f8-4b61-a2ad-b08b79d9877d', '''निराकार'' (निर् + आकार = निराकार) और ''निरपराध'' (निर् + अपराध = निरपराध)', true, '2175fff2-97e8-4fd1-b5c6-8c4384e19d0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61f61265-99f2-4a55-a6a7-4f23fe582f5b', '''नियम''', false, '2175fff2-97e8-4fd1-b5c6-8c4384e19d0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11a9fbaa-d965-4770-8328-cea3d090f8a8', '''निबंध''', false, '2175fff2-97e8-4fd1-b5c6-8c4384e19d0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4420f813-a4b9-4b80-b049-31a39b69dc20', '''निवास''', false, '2175fff2-97e8-4fd1-b5c6-8c4384e19d0f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0837c19e-7654-4142-96e5-9ff7b6d7127f', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', '''उन्नति'' शब्द का शुद्ध उपसर्ग-विच्छेद क्या होगा?', 'उत् + नति = उन्नति (त् के बाद न आने पर त् का न् हो जाता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c91c1e4-72c5-40e8-9759-6eda7d1c0eb8', 'उत् + नति (व्यंजन संधि के नियमानुसार ''त्'' का ''न्'' में परिवर्तन)', true, '0837c19e-7654-4142-96e5-9ff7b6d7127f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7257bb8f-d9fc-45c3-8fbc-c4d00cdd0dbd', 'उद् + नति', false, '0837c19e-7654-4142-96e5-9ff7b6d7127f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('433768a0-87cf-471d-8aff-d9a62de7d468', 'उन् + नति', false, '0837c19e-7654-4142-96e5-9ff7b6d7127f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f066c813-899e-4a8e-831e-04981d18b8aa', 'उ + नति', false, '0837c19e-7654-4142-96e5-9ff7b6d7127f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7cf5d8cd-3ea3-48ca-960e-cecf80e1e7fe', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'निम्नलिखित में से किस शब्द में ''कु'' उपसर्ग नहीं लगा है?', '''कुसुम'' (फूल) रूढ़ मूल शब्द है; बाकी तीनों में ''कु'' (बुरा) उपसर्ग है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f019c6a-9b3e-4f84-9fbb-c01302ce8252', '''कुसुम'' (क्योंकि यह एक रूढ़ मूल शब्द है, इसमें ''कु'' उपसर्ग नहीं है)', true, '7cf5d8cd-3ea3-48ca-960e-cecf80e1e7fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('830a33f1-6c62-475e-b883-86d03a3df720', '''कुकर्म''', false, '7cf5d8cd-3ea3-48ca-960e-cecf80e1e7fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc551fb3-eadd-4ac3-ba0d-2164a597ae4c', '''कुपात्र''', false, '7cf5d8cd-3ea3-48ca-960e-cecf80e1e7fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63c8364c-b843-4387-8988-5fd285850b59', '''कुपुत्र''', false, '7cf5d8cd-3ea3-48ca-960e-cecf80e1e7fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2dae7515-fc12-4901-b423-a3d0c0bb1ce2', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', '''ऐतिहासिक'' और ''वैधानिक'' शब्दों में मूल शब्द और प्रत्यय क्या हैं?', '''इक'' प्रत्यय से इ→ऐ (इतिहास→ऐतिहासिक) तथा इ→ऐ (विधान→वैधानिक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00d4f16f-3345-43c3-92d9-cbb5f4dce434', 'इतिहास + इक = ऐतिहासिक ; विधान + इक = वैधानिक', true, '2dae7515-fc12-4901-b423-a3d0c0bb1ce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44fcdef3-74b2-42b1-b9af-77d5d9e67e50', 'ऐतिहास + इक ; वैधान + इक', false, '2dae7515-fc12-4901-b423-a3d0c0bb1ce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e56f5cc-f0a9-461c-98c9-ccf5a8ad19ee', 'इतिहास + क ; विधान + क', false, '2dae7515-fc12-4901-b423-a3d0c0bb1ce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e96983a9-835a-4b31-ac05-114b749fd9c8', 'इति + हासिक ; वि + धानिक', false, '2dae7515-fc12-4901-b423-a3d0c0bb1ce2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('366e1a4b-e1ae-4fbd-927f-a307763cb669', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'निम्नलिखित में से किस शब्द में दो उपसर्गों का एक साथ प्रयोग हुआ है?', 'पर्यावरण = परि + आ + वरण (दो उपसर्ग); असुरक्षित = अ + सु + रक्षित (दो उपसर्ग)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('823d0cd7-defc-427d-8692-c1fd276beba4', '''पर्यावरण'' (परि + आ + वरण = पर्यावरण) और ''असुरक्षित'' (अ + सु + रक्षित)', true, '366e1a4b-e1ae-4fbd-927f-a307763cb669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('852eb981-abbc-4855-8691-56ea304c2ddf', '''अतिवृष्टि''', false, '366e1a4b-e1ae-4fbd-927f-a307763cb669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ac21150-1a00-4f10-8f9f-4f857cfedb97', '''दुर्लभ''', false, '366e1a4b-e1ae-4fbd-927f-a307763cb669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d74ccae-85c5-41e1-9091-1cf88e6d5b7c', '''अनपढ़''', false, '366e1a4b-e1ae-4fbd-927f-a307763cb669');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a633c3c2-861c-4eec-952d-37c041ea400a', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'निम्नलिखित में से किस शब्द में दो प्रत्ययों का एक साथ प्रयोग हुआ है?', 'राष्ट्र + ईय = राष्ट्रीय + ता = राष्ट्रीयता (दो तद्धित प्रत्ययों का क्रमिक संयोग)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2736c19b-285f-4019-8e98-848bb8514fcd', '''राष्ट्रीयता'' (राष्ट्र + ईय [प्रत्यय 1] + ता [प्रत्यय 2] = राष्ट्रीयता)', true, 'a633c3c2-861c-4eec-952d-37c041ea400a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd8860a8-40f3-45f7-9dc8-33d1411f1829', '''मानवता''', false, 'a633c3c2-861c-4eec-952d-37c041ea400a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f81992b5-5194-4577-9318-a96a1f1fddc0', '''सुंदरता''', false, 'a633c3c2-861c-4eec-952d-37c041ea400a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40a37d9e-f9dd-4613-a8fe-e74ec21694f0', '''लिखाई''', false, 'a633c3c2-861c-4eec-952d-37c041ea400a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83811b5c-292f-449d-abe7-23c055a1a724', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', '''सदाचार'' और ''सज्जन'' शब्दों में कौन-सा संस्कृत उपसर्ग प्रयुक्त हुआ है?', 'संस्कृत तत्सम उपसर्ग ''सत्'' (सत्+आचार=सदाचार, सत्+जन=सज्जन)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98062119-6931-46a8-9951-76f2c17e1049', '''सत्'' उपसर्ग (सत् + आचार = सदाचार ; सत् + जन = सज्जन)', true, '83811b5c-292f-449d-abe7-23c055a1a724');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3c32ad2-5a0a-4e03-a84c-d5ed3ace6941', '''सद्''', false, '83811b5c-292f-449d-abe7-23c055a1a724');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfe29872-df4e-47a5-a488-4e740f35ec87', '''स''', false, '83811b5c-292f-449d-abe7-23c055a1a724');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37a49644-187c-4708-a024-db6d3f13adc5', '''सम्''', false, '83811b5c-292f-449d-abe7-23c055a1a724');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e56ddf2-10af-41ec-8036-f8f3fc139692', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'उर्दू-फ़ारसी के उपसर्ग ''ना'' (अर्थ: अभाव/नहीं) से बने शब्दों का शुद्ध समूह कौन-सा है?', 'ना + लायक = नालायक; ना + पसंद = नापसंद; ना + बालिग = नाबालिग।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5b654af-ee79-434a-aef1-47eff49f54c6', 'नालायक, नापसंद, नादान, नाबालिग, नामुमकिन', true, '0e56ddf2-10af-41ec-8036-f8f3fc139692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('613d0587-0de9-4d2b-b2d0-40b2733eceb8', 'नाता, नाग', false, '0e56ddf2-10af-41ec-8036-f8f3fc139692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28c09f8f-e97c-4b96-afcf-e59dbe74a2da', 'नान, नाशपाती', false, '0e56ddf2-10af-41ec-8036-f8f3fc139692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa2b129-5702-4e9b-b328-6e05d37a55b9', 'नारी, नाटक', false, '0e56ddf2-10af-41ec-8036-f8f3fc139692');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e45efb33-7638-4771-9695-d4bda4fe98f1', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'उपसर्ग और प्रत्यय (Affixation) के सम्यक अध्ययन का हिंदी भाषा की शब्द-रचना में क्या सर्वोच्च योगदान है?', 'उपसर्ग और प्रत्यय शब्द-निर्माण की सर्वाधिक उर्वर रचनात्मक प्रविधियाँ हैं जो भाषा की शब्द-संपदा का असीमित विस्तार करती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7641de5-11d7-4e00-bdf3-4f54a92efcdc', 'यह सीमित मूल शब्दों से सहस्रों नवीन, सूक्ष्म, भावपूर्ण और पारिभाषिक शब्दों के सृजन की अद्भुत वैज्ञानिक सामर्थ्य प्रदान करता है, जिससे भाषा का शब्द-भंडार अनंत रूप से समृद्ध होता है', true, 'e45efb33-7638-4771-9695-d4bda4fe98f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1d56174-eb61-4bfb-9984-35b4eeb73471', 'यह शब्दों को छोटा करने का एकमात्र तरीका है', false, 'e45efb33-7638-4771-9695-d4bda4fe98f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('870e59a4-0710-488a-b70e-095072319f23', 'इसका व्याकरण में कोई विशेष प्रयोग नहीं है', false, 'e45efb33-7638-4771-9695-d4bda4fe98f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0334d242-ad9d-4e90-9147-7a270ce5bdcd', 'यह केवल परीक्षा में एक अंक के लिए पढ़ा जाता है', false, 'e45efb33-7638-4771-9695-d4bda4fe98f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8a32b74-af02-4dc0-9d2e-584a7c26b791', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'A change in which a substance undergoes a change in its physical properties (shape, size, color, or state) WITHOUT the formation of any new chemical substance is called a:', 'Physical changes alter physical dimensions or phase state without altering chemical composition or forming new molecular species.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d31fdb4-6ded-4b30-8f68-ff18ba65c6d0', 'Physical Change', true, 'd8a32b74-af02-4dc0-9d2e-584a7c26b791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('144681de-a092-4d4d-b545-ea52e63503f9', 'Chemical Change', false, 'd8a32b74-af02-4dc0-9d2e-584a7c26b791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94b58505-13fa-49da-8781-d1f3fe68732e', 'Rusting', false, 'd8a32b74-af02-4dc0-9d2e-584a7c26b791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57a890c6-7bc7-4eb6-ba6f-25bcdb1b060f', 'Neutralization', false, 'd8a32b74-af02-4dc0-9d2e-584a7c26b791');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81f88ca9-d13d-41e1-8f84-f347f7714428', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'A change in which one or more completely NEW substances with entirely different chemical properties are formed is called a:', 'A chemical change involves rearrangement of chemical bonds yielding distinct product substances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71e7829b-7386-4489-8f5f-e84c72f4eddc', 'Chemical Change (Chemical Reaction)', true, '81f88ca9-d13d-41e1-8f84-f347f7714428');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4ccf5df-93cb-46d2-bcf0-a8cceb4d2bd1', 'Physical Change', false, '81f88ca9-d13d-41e1-8f84-f347f7714428');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('194cfe05-253c-41ea-8ea6-917c26344515', 'Melting', false, '81f88ca9-d13d-41e1-8f84-f347f7714428');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0622b15-e6ea-4318-b1ed-4911f0eddfb4', 'Evaporation', false, '81f88ca9-d13d-41e1-8f84-f347f7714428');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea24f045-eba4-4d3a-99df-4dd62047ff20', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'Which of the following is an example of a REVERSIBLE PHYSICAL CHANGE?', 'Melting of ice is a reversible physical phase transition (H₂O solid ⇌ H₂O liquid).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db830b05-2c2e-44ec-9c6b-62c30fc2f257', 'Melting of Ice into Water', true, 'ea24f045-eba4-4d3a-99df-4dd62047ff20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c259634-9b56-4ccb-96cc-31cea5c0e508', 'Burning of paper into ash', false, 'ea24f045-eba4-4d3a-99df-4dd62047ff20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7abf5261-243a-4e1d-9616-96b207cc1823', 'Rusting of iron', false, 'ea24f045-eba4-4d3a-99df-4dd62047ff20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62c4245f-ab1f-4371-9442-d56da1a4c46d', 'Cooking of food', false, 'ea24f045-eba4-4d3a-99df-4dd62047ff20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4677ca25-17d0-48ed-ac10-9b5c16fcb1e5', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What white powdery substance is formed when a Magnesium ribbon is burned in air with a dazzling white flame?', 'Magnesium reacts vigorously with atmospheric oxygen to produce Magnesium Oxide powder: 2Mg + O₂ → 2MgO.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67c825ad-3f53-4cc7-a43b-240e83c0ff12', 'Magnesium Oxide (MgO)', true, '4677ca25-17d0-48ed-ac10-9b5c16fcb1e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f86b5113-2cd3-4321-82b9-6722d4b6f864', 'Magnesium Hydroxide', false, '4677ca25-17d0-48ed-ac10-9b5c16fcb1e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2339398e-0889-4cb1-9bd7-7b5eb1a406d1', 'Magnesium Chloride', false, '4677ca25-17d0-48ed-ac10-9b5c16fcb1e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('836c2f0c-3fa1-43e5-9429-1de563cde7e4', 'Magnesium Carbonate', false, '4677ca25-17d0-48ed-ac10-9b5c16fcb1e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8a828bd-20fa-412b-a199-43519e131c4b', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What new chemical substance is formed when Magnesium Oxide ash (MgO) is dissolved thoroughly in water?', 'MgO + H₂O → Mg(OH)₂ (a basic metal hydroxide turning red litmus blue).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00736b47-f001-42df-bf00-bf97f86cc14f', 'Magnesium Hydroxide [Mg(OH)₂] - which turns Red Litmus paper BLUE (Basic in nature)', true, 'e8a828bd-20fa-412b-a199-43519e131c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c373e2a-21ff-463f-bfb5-eddbf008f138', 'Hydrochloric acid', false, 'e8a828bd-20fa-412b-a199-43519e131c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11995e2c-b459-419d-9d89-82b236c48c0c', 'Magnesium metal', false, 'e8a828bd-20fa-412b-a199-43519e131c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e816f5a9-7269-4e25-bbda-e98f4291a562', 'Hydrogen gas', false, 'e8a828bd-20fa-412b-a199-43519e131c4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('104703bd-4860-4efc-90ab-e2ba6d77ed9f', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What two essential conditions are mandatory for the RUSTING of Iron to occur?', 'Rusting of iron is an electrochemical corrosion process requiring simultaneous exposure to oxygen and moisture: 4Fe + 3O₂ + xH₂O → 2Fe₂O₃·xH₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d05a3616-6551-427b-8cc1-692c7c960e41', 'Both Oxygen (air) and Water (or moisture/water vapor)', true, '104703bd-4860-4efc-90ab-e2ba6d77ed9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7be5b160-ed40-49e1-a471-6555063bbe60', 'Only dry oxygen', false, '104703bd-4860-4efc-90ab-e2ba6d77ed9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41fe850e-cb0f-4d75-bb56-555c6d46bc48', 'Only water without air', false, '104703bd-4860-4efc-90ab-e2ba6d77ed9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('311f94dd-7aef-4eda-b5eb-67126e131d3c', 'Only sunlight', false, '104703bd-4860-4efc-90ab-e2ba6d77ed9f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61b747e0-0e96-4c15-97c2-4720d0cb3ce2', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'The industrial process of depositing a protective thin layer of metal ZINC on iron objects to prevent rusting is called:', 'Galvanization coats ferrous metals with sacrificial zinc to shield against moisture and oxygen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3e3aaf3-3301-47b8-87a2-e8f555222633', 'Galvanization', true, '61b747e0-0e96-4c15-97c2-4720d0cb3ce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c53460f2-40f8-488c-9d14-be5292c5f66f', 'Crystallization', false, '61b747e0-0e96-4c15-97c2-4720d0cb3ce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f4026ed-f1e4-4361-9f6b-1de1a598cb7f', 'Neutralization', false, '61b747e0-0e96-4c15-97c2-4720d0cb3ce2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25075697-eb03-4609-b2fe-957b3253921f', 'Vulcanization', false, '61b747e0-0e96-4c15-97c2-4720d0cb3ce2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a38e2c36-4d61-4cee-862b-bd018f452106', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What is Stainless Steel made of that gives it permanent resistance to rusting?', 'Stainless steel is a corrosion-resistant alloy of iron, carbon, chromium (≥10.5%), nickel, and manganese forming a self-healing passive oxide film.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46e1e07d-9514-4e88-beef-4b3157bea866', 'Iron mixed/alloyed with Carbon and metals like Chromium, Nickel, and Manganese', true, 'a38e2c36-4d61-4cee-862b-bd018f452106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('833e7fb2-c1fb-4ff7-b238-cd5856afa3aa', 'Pure gold', false, 'a38e2c36-4d61-4cee-862b-bd018f452106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a748b86d-9a39-40dd-8558-abc1d15dd884', 'Iron painted with white plastic', false, 'a38e2c36-4d61-4cee-862b-bd018f452106');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6b6b8f-4568-4e14-b92d-59477ccaa50d', 'Pure aluminum', false, 'a38e2c36-4d61-4cee-862b-bd018f452106');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98cb983c-9990-4a29-80de-fdb75cf84d72', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'The physical purification process of obtaining large, pure geometric crystals of a substance (such as Copper Sulphate) from its saturated hot solution is called:', 'Crystallization is a physical separation and purification technique yielding highly ordered crystalline solids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d1f0e7c-6a36-405f-a003-fdf749cdf35f', 'Crystallization', true, '98cb983c-9990-4a29-80de-fdb75cf84d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7d0989f-7a4b-47a2-a48e-a2623b3a7e9e', 'Evaporation', false, '98cb983c-9990-4a29-80de-fdb75cf84d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df0ee1d2-470f-4038-bca1-ec9de3fe341f', 'Sedimentation', false, '98cb983c-9990-4a29-80de-fdb75cf84d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2acc4c0c-5fe0-40b3-a933-b623d72614bd', 'Condensation', false, '98cb983c-9990-4a29-80de-fdb75cf84d72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('503484b0-4422-4b60-9c6d-66ae88f9f9da', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What gas turns clear Lime Water milky when passed through it?', 'CO₂ reacts with lime water [Ca(OH)₂] to precipitate insoluble white Calcium Carbonate (CaCO₃), turning the solution milky.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41488216-171a-467a-b1bb-d454ea4fbfee', 'Carbon Dioxide (CO₂)', true, '503484b0-4422-4b60-9c6d-66ae88f9f9da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51461260-c070-4169-8912-62546c13c109', 'Oxygen (O₂)', false, '503484b0-4422-4b60-9c6d-66ae88f9f9da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06be69b9-9b17-425c-a43c-470b9340c9e5', 'Nitrogen (N₂)', false, '503484b0-4422-4b60-9c6d-66ae88f9f9da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52aacc75-5bcf-4573-afbf-f74425f583f6', 'Hydrogen (H₂)', false, '503484b0-4422-4b60-9c6d-66ae88f9f9da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6399227c-8c0f-4e34-8802-4f6bdeeae82b', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'When an iron nail is dropped into a blue Copper Sulphate solution (CuSO₄), why does the solution color turn GREEN after an hour?', 'Single displacement reaction: Fe + CuSO₄ (blue) → FeSO₄ (green) + Cu (reddish-brown deposit on nail).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad659c37-c6e1-4e22-81de-b89b2febec6c', 'Iron is more reactive than copper and displaces it, forming green Iron Sulphate (FeSO₄) solution', true, '6399227c-8c0f-4e34-8802-4f6bdeeae82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('006d3362-2b00-4119-b7a0-567dd744e163', 'Because the nail absorbs all blue paint', false, '6399227c-8c0f-4e34-8802-4f6bdeeae82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e67b2c27-f27a-4d88-9b32-124e9441135c', 'Because algae grows inside the water', false, '6399227c-8c0f-4e34-8802-4f6bdeeae82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2df1be3-29a5-46b8-b0a1-4129f377deb9', 'Because copper turns green', false, '6399227c-8c0f-4e34-8802-4f6bdeeae82b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cc1ee1d-ef9d-47b0-bea8-06afd2838936', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What color is the thin metal coating deposited on the iron nail in the Copper Sulphate experiment?', 'Elemental metallic copper (Cu) precipitates as a fine reddish-brown coating on the submerged iron nail.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5491f0f9-0d17-4cf8-a3d3-f468988bc5d2', 'Brown / Reddish-brown (pure metallic Copper)', true, '3cc1ee1d-ef9d-47b0-bea8-06afd2838936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73e88fcd-03b0-4413-b30b-1f2ad38e897d', 'Silver', false, '3cc1ee1d-ef9d-47b0-bea8-06afd2838936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf736331-9177-4b3c-bf36-55acf7fafd14', 'Yellow', false, '3cc1ee1d-ef9d-47b0-bea8-06afd2838936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad91e9c1-53e5-44f6-b334-6465e1e014a4', 'Black', false, '3cc1ee1d-ef9d-47b0-bea8-06afd2838936');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6525710-f0b3-487f-9388-509d18195850', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is the BURNING of a candle considered BOTH a Physical Change and a Chemical Change simultaneously?', 'Dual phenomenon: phase transition of solid wax to liquid wax is physical; exothermic hydrocarbon combustion is chemical.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa408632-a8af-4bbc-ad2c-f81d7bab83f7', 'Melting and solidification of wax is a Physical Change ; while burning of molten wax vapor in air to produce CO₂, water vapor, heat, and light is a Chemical Change', true, 'b6525710-f0b3-487f-9388-509d18195850');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30ea074e-f622-4522-857d-8427162a7296', 'Because the thread grows longer', false, 'b6525710-f0b3-487f-9388-509d18195850');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6da4272-55e5-4a99-b7f5-a5c941fb2ba7', 'Because the glass melts', false, 'b6525710-f0b3-487f-9388-509d18195850');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc6fbec0-e3cd-414f-9f06-637c805a0dfe', 'Because wax turns into water', false, 'b6525710-f0b3-487f-9388-509d18195850');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b62d985c-3b7c-45e5-a213-461818f7860d', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why do iron ships, bridges, and metal structures rust MUCH FASTER in coastal marine environments (near the sea) than in inland dry areas?', 'Saline marine electrolyte solutions increase ionic conductivity, accelerating galvanic redox corrosion of iron.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('362bd98c-b0db-4eb0-9eee-13a0bb3bf9f1', 'Seawater contains high concentrations of dissolved mineral SALTS (NaCl) which act as an electrolyte, dramatically accelerating the electrochemical rate of rust formation', true, 'b62d985c-3b7c-45e5-a213-461818f7860d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9bb3724-e419-4d8a-8bfb-fb8b772f74bd', 'Because sea fish eat the iron', false, 'b62d985c-3b7c-45e5-a213-461818f7860d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77847518-d865-4324-8d1d-77fab6363b9e', 'Because sea water is colder', false, 'b62d985c-3b7c-45e5-a213-461818f7860d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6beb5efe-908a-4664-9030-957e6ae6a28e', 'Because ships move faster in oceans', false, 'b62d985c-3b7c-45e5-a213-461818f7860d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac645aa3-8782-4a25-a7b3-5c121e7bbcf2', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What happens when Baking Soda (Sodium Hydrogen Carbonate) is mixed with Vinegar (Acetic Acid) in a test tube, and the resulting gas is bubbled into Lime Water?', 'Effervescence of CO₂: NaHCO₃ + CH₃COOH → CH₃COONa + H₂O + CO₂↑. CO₂ + Ca(OH)₂ → CaCO₃↓ (milky) + H₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('815b0a25-5087-40a2-901e-cb60c1454af8', 'A vigorous hissing sound produces Carbon Dioxide (CO₂) gas ; when bubbled through lime water, it forms insoluble white Calcium Carbonate (CaCO₃), making it MILKY', true, 'ac645aa3-8782-4a25-a7b3-5c121e7bbcf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af506f6d-baa3-4244-917a-5a6cb950afab', 'The test tube turns into ice', false, 'ac645aa3-8782-4a25-a7b3-5c121e7bbcf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f1da695-531b-4748-806b-5f4717b6e88f', 'Lime water turns bright yellow', false, 'ac645aa3-8782-4a25-a7b3-5c121e7bbcf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('111a8324-ae4f-4ed4-a7ae-b06e699699a8', 'No gas is produced', false, 'ac645aa3-8782-4a25-a7b3-5c121e7bbcf2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adcfd441-a0ab-4714-9f10-13b94cbd9ea4', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is the Digestion of food inside our alimentary canal classified strictly as a Chemical Change?', 'Enzymatic hydrolysis breaks covalent macromolecular bonds, producing irreversible monomer biochemical entities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01cadfb3-bc26-4885-9f31-cd4a284b8166', 'Digestive enzymes chemically hydrolyze complex starch, proteins, and fats into entirely new, simpler absorbable monomer molecules (glucose, amino acids) that cannot be reversed back into food', true, 'adcfd441-a0ab-4714-9f10-13b94cbd9ea4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8678000-f6e2-47d1-bafb-faeea280f73f', 'Because food just gets chewed smaller', false, 'adcfd441-a0ab-4714-9f10-13b94cbd9ea4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9db9a04e-c40a-4505-8ddd-9b9a530668dc', 'Because water dissolves food physically', false, 'adcfd441-a0ab-4714-9f10-13b94cbd9ea4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13f18306-f89b-43b3-a921-4529863f9eb7', 'Because the stomach is a blender', false, 'adcfd441-a0ab-4714-9f10-13b94cbd9ea4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c7bef06-22cf-41da-9f0d-a3416f836b39', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why does a freshly cut slice of an Apple or Brinjal (Eggplant) turn BROWN when left exposed to air for a few minutes?', 'Enzymatic browning: polyphenol oxidases catalyze oxidation of phenolic compounds into quinones and melanin pigments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a34ca53e-7dc2-4aa1-99b4-adf471fa6cf6', 'Polyphenol oxidase enzymes inside the apple react with atmospheric oxygen to form brown melanin pigments in an irreversible oxidation chemical reaction', true, '1c7bef06-22cf-41da-9f0d-a3416f836b39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12be81a9-37c7-43be-ae22-0ea48188d081', 'Dust settles on the apple', false, '1c7bef06-22cf-41da-9f0d-a3416f836b39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d63402b-a9e8-461f-9954-2d86165aa4df', 'The apple loses water and shrinks', false, '1c7bef06-22cf-41da-9f0d-a3416f836b39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ba62e1d-cce4-44ea-ab72-70190d84fa19', 'The apple turns into wood', false, '1c7bef06-22cf-41da-9f0d-a3416f836b39');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('090c8429-d311-4d1c-84ed-2e60f180fcee', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What observable accompanying signs typically indicate that a Chemical Reaction has occurred?', 'Enthalpy changes, gas evolution, chromophoric shifts, odor generation, and precipitation characterize chemical changes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b221b13f-4dc2-400b-be05-94eeabea77e5', 'Evolution of gas, production of heat/light/sound, noticeable change in color, emission of a new smell, or formation of a precipitate', true, '090c8429-d311-4d1c-84ed-2e60f180fcee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deec3725-71b1-4ae4-a1e1-8ba0eac5ec2e', 'Only change in size', false, '090c8429-d311-4d1c-84ed-2e60f180fcee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6352d9d7-d921-439a-abea-e80be11fd8ed', 'Only change in temperature without any new substance', false, '090c8429-d311-4d1c-84ed-2e60f180fcee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e1a6690-4161-479b-84ce-4b2a3072b3e8', 'The substance becomes invisible', false, '090c8429-d311-4d1c-84ed-2e60f180fcee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e385dcff-234d-4fc1-8472-e5dd3bc0bcb7', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is Photosynthesis in green plants classified as a Chemical Change?', '6CO₂ + 6H₂O + hν → C₆H₁₂O₆ + 6O₂ (anabolic synthesis of new carbohydrates).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c1bca40-1984-416c-9d48-7e8f3bd111f0', 'Carbon dioxide and water react in the presence of chlorophyll and sunlight to synthesize an entirely new chemical substance (Glucose) and release Oxygen gas', true, 'e385dcff-234d-4fc1-8472-e5dd3bc0bcb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abcd9f4c-e49f-4a13-987e-6d142fe45eb8', 'Because leaves stay green', false, 'e385dcff-234d-4fc1-8472-e5dd3bc0bcb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b09236ec-3a98-4f85-ade7-a76d41c114e0', 'Because sunlight warms the leaves physically', false, 'e385dcff-234d-4fc1-8472-e5dd3bc0bcb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3aec36d-3b80-4f58-84ec-2e8c5a51902f', 'Because water evaporates from leaves', false, 'e385dcff-234d-4fc1-8472-e5dd3bc0bcb7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94d20823-5bcb-430e-aabe-6cb2d45ddecd', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is cutting a log of wood into small pieces a PHYSICAL change, while burning that wood is a CHEMICAL change?', 'Mechanical severance preserves cellulose chemistry (physical); pyrolytic combustion oxidizes organic polymers into CO₂ and minerals (chemical).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ec41ee5-b0dd-48ca-a334-4b3785c44804', 'Cutting alters only size/shape without making a new substance ; burning reacts with oxygen to form ash, smoke, CO₂, and heat, which cannot be reversed', true, '94d20823-5bcb-430e-aabe-6cb2d45ddecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5d9fa00-6d79-4cd7-bdcf-fb496b9ef312', 'Cutting makes new wood', false, '94d20823-5bcb-430e-aabe-6cb2d45ddecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de128469-97d7-482c-9bb5-6fa41a9d3850', 'Burning is reversible', false, '94d20823-5bcb-430e-aabe-6cb2d45ddecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('372e86e9-9f46-4cf6-8534-d74ebd952d72', 'Both are physical changes', false, '94d20823-5bcb-430e-aabe-6cb2d45ddecd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4df2b44-ce8c-46fc-bcfb-680f320a9ce7', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What protective role does the Ozone Layer (O₃) in the stratosphere play by undergoing a continuous chemical change?', 'Photochemical Chapman cycle: O₃ + UV photon → O₂ + O· (absorbing lethal UV-B/UV-C radiation).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd6f9ad2-7e20-4412-8302-ed2c96e5cb08', 'It absorbs harmful high-energy Ultraviolet (UV) radiation from the Sun and breaks down into Oxygen (O₂); absorbing UV prevents skin cancer and cataracts', true, 'a4df2b44-ce8c-46fc-bcfb-680f320a9ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efca4ca9-5feb-4c99-a527-f3830f2c308e', 'It makes the sky blue', false, 'a4df2b44-ce8c-46fc-bcfb-680f320a9ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6662edb-2d2c-464d-8856-28b0e0ee09e1', 'It brings rain clouds', false, 'a4df2b44-ce8c-46fc-bcfb-680f320a9ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70b6a2a1-abd6-4817-b5c9-7a79ef74defe', 'It keeps the Earth warm by burning', false, 'a4df2b44-ce8c-46fc-bcfb-680f320a9ce7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1024bfb7-bf56-442f-875c-043056430284', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is the explosion of a Firecracker considered a Chemical Change?', 'Exothermic deflagration of oxidizers (KNO₃) and fuels (S, C) produces light, shockwaves, and gaseous products.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f97bfdb-cb3f-41eb-9af5-c3e5ac27f0dc', 'Gunpowder and chemicals react rapidly with oxygen, producing heat, brilliant light, explosive sound, and unpleasant sulfur gases', true, '1024bfb7-bf56-442f-875c-043056430284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('276802a4-492f-4beb-97dc-b6c3cbe68d69', 'Because firecrackers can be re-exploded', false, '1024bfb7-bf56-442f-875c-043056430284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81213631-8795-40f0-be06-4d46293523b6', 'Because firecrackers change only shape', false, '1024bfb7-bf56-442f-875c-043056430284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da0b4951-64fb-431f-9f77-7b495572d344', 'Because firecrackers turn into water', false, '1024bfb7-bf56-442f-875c-043056430284');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd87777e-b13c-4bfb-b8d6-979b55a2b7f1', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'How can Copper Sulphate crystals be prepared in the laboratory?', 'Supersaturation crystallization: dissolving solute at elevated temperature and slow cooling precipitates pure CuSO₄·5H₂O crystals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2425002-3b64-42d4-9605-66749c309ed2', 'Boil water, add dilute Sulfuric acid, slowly stir in Copper Sulphate powder until no more dissolves (saturated), filter while hot, and let it cool undisturbed to form blue crystals', true, 'fd87777e-b13c-4bfb-b8d6-979b55a2b7f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6575fd-bdfd-41d3-9db4-5940b5217eb8', 'Mix copper with cold tap water', false, 'fd87777e-b13c-4bfb-b8d6-979b55a2b7f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0126f36-58ac-4fdf-9df6-2050966da8e4', 'Burn copper metal over a flame', false, 'fd87777e-b13c-4bfb-b8d6-979b55a2b7f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('479d45ea-eaa0-4038-8267-388c51dab3ec', 'Freeze copper in ice', false, 'fd87777e-b13c-4bfb-b8d6-979b55a2b7f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3b94c51-edf1-4a18-b392-d2a6b0213619', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is tearing a piece of paper into 100 tiny pieces classified as a Physical Change?', 'Mechanical subdivision alters surface area and macroscopic geometry while molecular cellulose composition remains intact.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e757213-1467-426c-8879-cabaf8192df2', 'Each tiny scrap is still chemically made of the exact same Cellulose fibers; no new chemical substance is formed', true, 'f3b94c51-edf1-4a18-b392-d2a6b0213619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f67a798a-fdbf-4230-9967-e60c1be33b98', 'Because the scraps can be glued back', false, 'f3b94c51-edf1-4a18-b392-d2a6b0213619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71c416e5-b2cf-4bef-aebe-eea2766a61c0', 'Because the paper disappears', false, 'f3b94c51-edf1-4a18-b392-d2a6b0213619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8093022c-78eb-46a4-abec-0aae9d3f2920', 'Because paper turns into plastic', false, 'f3b94c51-edf1-4a18-b392-d2a6b0213619');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('694ee164-fc7a-4a27-8deb-f92e4c8724db', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What is the chemical formula of Rust formed on iron?', 'Rust is porous, reddish-brown hydrated ferric oxide: Fe₂O₃·xH₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7335d325-db7f-4c7a-8549-724d8c623ee0', 'Hydrated Iron(III) Oxide [Fe₂O₃·xH₂O]', true, '694ee164-fc7a-4a27-8deb-f92e4c8724db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1d49946-82c4-40e4-9b78-add3846aa96b', 'Iron Sulphide [FeS]', false, '694ee164-fc7a-4a27-8deb-f92e4c8724db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('992522f3-7d7c-424f-b46a-31597125485e', 'Iron Carbonate [FeCO₃]', false, '694ee164-fc7a-4a27-8deb-f92e4c8724db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('552ae1da-861d-495c-9597-743b7a44bf94', 'Iron Hydroxide only [Fe(OH)₂]', false, '694ee164-fc7a-4a27-8deb-f92e4c8724db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2276c25c-1ed0-4744-9b9a-95f851b7e51b', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why are overhead water transmission pipes and iron railings in houses galvanized?', 'Galvanized zinc provides a physical barrier and sacrificial anodic protection against rusting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92f3bdea-814a-4249-a560-dfa2ecdc4071', 'The zinc coating prevents direct contact of iron with atmospheric oxygen and water, preventing rust corrosion', true, '2276c25c-1ed0-4744-9b9a-95f851b7e51b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe28b5f9-c0fa-475d-812b-36b430e8a1ec', 'To make water flow faster', false, '2276c25c-1ed0-4744-9b9a-95f851b7e51b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('522b5890-452b-42e4-89cb-860082c067a8', 'To make pipes look shiny', false, '2276c25c-1ed0-4744-9b9a-95f851b7e51b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f079189-62c2-4f5b-ad1b-ffbfb036d12d', 'To heat the water', false, '2276c25c-1ed0-4744-9b9a-95f851b7e51b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66303fff-4056-4125-9408-e39186851005', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why does blowing breath through a straw into lime water turn it milky faster than letting it sit in open air?', 'Exhaled metabolic CO₂ (~40,000 ppm) rapidly precipitates calcium carbonate in Ca(OH)₂ solution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac3befe0-aec2-4590-9370-0543f8aa56b7', 'Exhaled human breath contains a much higher concentration of Carbon Dioxide (~4% CO₂) than ambient atmospheric air (~0.04% CO₂)', true, '66303fff-4056-4125-9408-e39186851005');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50a49f1a-89d6-450f-8c4e-bb2490aa385c', 'Exhaled breath contains water', false, '66303fff-4056-4125-9408-e39186851005');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fce9f6e-f4d2-40e0-9fee-8aab34354db5', 'Exhaled breath is hot', false, '66303fff-4056-4125-9408-e39186851005');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b66e4a89-3431-4fb4-a9e4-e0e2c305ee62', 'Exhaled breath contains oxygen', false, '66303fff-4056-4125-9408-e39186851005');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd0a3981-ce0e-4365-96fd-0ae340c293a7', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What happens when glowing red-hot charcoal reacts with air?', 'C(s) + O₂(g) → CO₂(g) + ΔH (exothermic chemical combustion).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c2ed79c-f560-4e1b-924d-bd16018602be', 'Carbon in charcoal combusts with oxygen to produce Carbon Dioxide gas (CO₂), heat, and light: C + O₂ -> CO₂ (Chemical Change)', true, 'dd0a3981-ce0e-4365-96fd-0ae340c293a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cc228dd-b0a0-418a-83aa-802ffe2df475', 'It turns into pure water', false, 'dd0a3981-ce0e-4365-96fd-0ae340c293a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdf3254d-0847-456a-a3d9-ba9d9bfce980', 'It becomes colder', false, 'dd0a3981-ce0e-4365-96fd-0ae340c293a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94d2ae3f-341a-4790-8a01-98c62544de49', 'It changes only into ice', false, 'dd0a3981-ce0e-4365-96fd-0ae340c293a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3af98c70-581e-4483-950b-0b3d7cd5749f', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c563c7a-32c4-4e8b-803a-01bfbfac1341', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3af98c70-581e-4483-950b-0b3d7cd5749f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e9bc72a-0f0f-4aa2-b90f-e030557c0b7d', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '3af98c70-581e-4483-950b-0b3d7cd5749f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7333009-d990-4414-af87-51e4eda3ce63', '(A) is true, but (R) is false.', false, '3af98c70-581e-4483-950b-0b3d7cd5749f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4eb561b-7fbb-4bca-8d69-b25a9d49f70b', '(A) is false, but (R) is true.', false, '3af98c70-581e-4483-950b-0b3d7cd5749f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c59fea5-4958-47cf-b4d0-143f74bc9294', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Spot the IMPOSTER in the following group of Changes and their scientific classifications:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aa8ceb1-ce1d-45b8-bd00-3583fce41765', 'Change 1', false, '1c59fea5-4958-47cf-b4d0-143f74bc9294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c5116eb-1756-498e-9372-192343fc9f82', 'Change 2', false, '1c59fea5-4958-47cf-b4d0-143f74bc9294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ffe1875-732c-4ee7-aea5-c449628cba34', 'Change 3', false, '1c59fea5-4958-47cf-b4d0-143f74bc9294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c821b9b-1847-4db3-8ccb-04d68af94fe5', 'Change 4 (Photosynthesis is a profound CHEMICAL CHANGE, not a physical change)', true, '1c59fea5-4958-47cf-b4d0-143f74bc9294');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a8653b2-08d7-4805-aa6b-539ace97b1f1', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'In the reaction between Copper Sulphate and Iron:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24367f0b-a9da-409a-a245-c5afdd8ca5d9', 'Single Displacement (Redox) Reaction: Iron is more electrochemically reactive than copper, so it loses electrons and displaces copper from its sulfate solution', true, '0a8653b2-08d7-4805-aa6b-539ace97b1f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42cf4996-9af5-4e9d-9f22-38c7e190a7e2', 'Double Decomposition Reaction', false, '0a8653b2-08d7-4805-aa6b-539ace97b1f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21d0c043-1820-4166-a98b-4d56efdc6379', 'Neutralization Reaction', false, '0a8653b2-08d7-4805-aa6b-539ace97b1f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae8bc0ec-4a71-4265-97d1-0ad3027aa600', 'Physical Phase Change', false, '0a8653b2-08d7-4805-aa6b-539ace97b1f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b427f87-68bf-4dc3-9137-fa33eb9489c0', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Match Column I (Chemical Processes) with Column II (Essential Chemical Equations):
(a) Burning of Magnesium ribbon  -> (i) 2Mg + O₂ -> 2MgO
(b) Making Milk of Magnesia      -> (ii) MgO + H₂O -> Mg(OH)₂
(c) Lime water turning milky     -> (iii) CO₂ + Ca(OH)₂ -> CaCO₃ + H₂O
(d) Iron rusting                 -> (iv) 4Fe + 3O₂ + 2xH₂O -> 2Fe₂O₃·xH₂O', 'Exact stoichiometric equations for the four foundational chemical reactions studied in Class 7 Chapter 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87418549-9cc8-4480-be9d-057d03d1e08a', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '1b427f87-68bf-4dc3-9137-fa33eb9489c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a124cb8-8dd1-4b3d-b34b-532ce242ac71', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '1b427f87-68bf-4dc3-9137-fa33eb9489c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('095994ce-4f21-45a0-9029-25b307830325', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1b427f87-68bf-4dc3-9137-fa33eb9489c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c09543b9-463b-4e02-8cb4-b69ee0c1fc71', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1b427f87-68bf-4dc3-9137-fa33eb9489c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de0e072a-8f7e-4ad9-8a55-c35ac9a2334c', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Read the statements regarding physical and chemical changes:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('853d547d-ee14-4f47-9e10-f25ffe772478', 'Statements 1 and 2 only', true, 'de0e072a-8f7e-4ad9-8a55-c35ac9a2334c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a037063f-97b8-4fab-82ab-6e174e95c34b', 'Statements 2 and 3 only', false, 'de0e072a-8f7e-4ad9-8a55-c35ac9a2334c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7bedcd5-3769-4fdc-85b4-02ffb9b847e1', 'Statements 1 and 3 only', false, 'de0e072a-8f7e-4ad9-8a55-c35ac9a2334c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acdbd6c2-714f-40de-881d-1a1bbd5305bc', 'All Statements 1, 2, and 3', false, 'de0e072a-8f7e-4ad9-8a55-c35ac9a2334c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c49e28d3-078a-42ba-86d9-c9b763bf62e4', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Why does applying a coat of paint or grease on an iron object prevent rusting only as long as the paint layer remains intact?', 'Barrier coatings prevent contact between iron and ambient moisture/O₂; breaches initiate localized crevice corrosion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('887d1a2e-7a08-4bd0-8b3d-27b23465aa73', 'Paint acts as a physical barrier preventing atmospheric oxygen and moisture from contacting iron atoms; any scratch exposes iron, initiating rapid localized galvanic rusting', true, 'c49e28d3-078a-42ba-86d9-c9b763bf62e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13b5017f-cd63-4e3a-b3f8-c1c663c58a3b', 'Because paint kills bacteria', false, 'c49e28d3-078a-42ba-86d9-c9b763bf62e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('148cefbf-df60-48e7-be6f-83cd53d3fe06', 'Because paint turns iron into plastic', false, 'c49e28d3-078a-42ba-86d9-c9b763bf62e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('521acf3e-e155-42bb-be92-8698e953646c', 'Because grease makes iron colder', false, 'c49e28d3-078a-42ba-86d9-c9b763bf62e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec9bc4f5-4e3b-4618-a37f-7d55ab89afa8', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'What is the crucial scientific difference between EVAPORATION (to dryness) and CRYSTALLIZATION when purifying dissolved solids?', 'Crystallization purifies by lattice exclusion (impurities remain in mother liquor), preventing thermal decomposition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23276413-bded-4731-add9-9499271f4ae7', 'Evaporation to dryness can decompose heat-sensitive substances or leave soluble impurities mixed in ; Crystallization precipitates pure geometric crystals from cooled saturated solutions, leaving impurities in the mother liquor', true, 'ec9bc4f5-4e3b-4618-a37f-7d55ab89afa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3cc5838-d939-43c9-a041-ec54ee75d4b3', 'Evaporation produces crystals and crystallization produces steam', false, 'ec9bc4f5-4e3b-4618-a37f-7d55ab89afa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4758c21-547e-456c-9ed8-a2b050e75701', 'Crystallization is a chemical change while evaporation is not', false, 'ec9bc4f5-4e3b-4618-a37f-7d55ab89afa8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd6fccfa-bf90-4777-a078-31409664d7ff', 'There is no difference', false, 'ec9bc4f5-4e3b-4618-a37f-7d55ab89afa8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('142c54e8-3169-4fd4-8817-e38cc8b4ab85', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Consider four events:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('986bf8c0-c9b8-4d73-858a-f3d803235a6a', 'Events 2 and 4 (Fermentation and Digestion)', true, '142c54e8-3169-4fd4-8817-e38cc8b4ab85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8026a43-ad78-4388-9a39-8b8bcc0fb50b', 'Events 1 and 3', false, '142c54e8-3169-4fd4-8817-e38cc8b4ab85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90a29107-aab9-4acf-84d4-58e56fc9bd6a', 'Events 1 and 2', false, '142c54e8-3169-4fd4-8817-e38cc8b4ab85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa73a0b2-90c7-4c06-a59a-7b2703bb5c3c', 'Events 3 and 4', false, '142c54e8-3169-4fd4-8817-e38cc8b4ab85');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abcbcf5f-69d1-4188-9a82-0ac0c0b15209', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'What happens when excess Carbon Dioxide gas is continuously bubbled into milky lime water for a prolonged duration?', 'CaCO₃ + H₂O + excess CO₂ → Ca(HCO₃)₂ (soluble calcium bicarbonate), clearing the milkiness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0796b89-bbd7-4280-b323-5d5eb1b7efd8', 'The milkiness DISAPPEARS and the solution becomes completely clear again because insoluble Calcium Carbonate converts into soluble Calcium Hydrogen Carbonate [Ca(HCO₃)₂]', true, 'abcbcf5f-69d1-4188-9a82-0ac0c0b15209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32b36ad8-318e-4b16-ab69-92d2be57efb5', 'The solution explodes', false, 'abcbcf5f-69d1-4188-9a82-0ac0c0b15209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dff3e6ff-ca62-4b26-b678-6844fb9661fb', 'The milkiness turns black', false, 'abcbcf5f-69d1-4188-9a82-0ac0c0b15209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50d845e9-7752-4f84-bbe6-2d8d85dcc3ba', 'The solution freezes solid', false, 'abcbcf5f-69d1-4188-9a82-0ac0c0b15209');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('deaeb5fa-15da-448b-8d01-4f715d23066a', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Why is the rusting of iron an electrochemical REDOX (Reduction-Oxidation) reaction?', 'Corrosion kinetics: Anodic oxidation Fe → Fe²⁺ + 2e⁻ coupled to cathodic reduction O₂ + 4H⁺ + 4e⁻ → 2H₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79ae700d-4b50-48d0-a64d-f3232d1fe37b', 'Iron atoms lose electrons (Oxidation: Fe -> Fe²⁺ + 2e⁻) and atmospheric Oxygen molecules gain electrons in the presence of water (Reduction), forming hydrated iron oxide', true, 'deaeb5fa-15da-448b-8d01-4f715d23066a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be0b0634-aebb-4451-a3d9-f1499eda55d9', 'Iron gains protons from water', false, 'deaeb5fa-15da-448b-8d01-4f715d23066a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fb4bc97-b192-4411-af9e-0f63b2e4b214', 'Oxygen turns into hydrogen', false, 'deaeb5fa-15da-448b-8d01-4f715d23066a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de7bebc1-bd54-43e9-aa1b-6fc1e54c6d91', 'Iron melts into liquid', false, 'deaeb5fa-15da-448b-8d01-4f715d23066a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e12f2bc-07e1-4af4-811c-a2de2e8f3f54', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'What happens during the Sublimation of Camphor or Ammonium Chloride when heated in a china dish covered with an inverted glass funnel?', 'Sublimation is a physical phase transition: solid ⇌ vapor without passing through intermediate liquid state.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1862e10e-e0f7-444d-9737-e8812d578a32', 'Solid camphor changes directly into gas vapors upon heating without passing through the liquid phase, condensing back to pure solid crystals on the cool funnel neck (Physical Change)', true, '7e12f2bc-07e1-4af4-811c-a2de2e8f3f54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58a073c6-c61b-4e08-ab19-5bc4b4ac15b8', 'It burns into black ash permanently', false, '7e12f2bc-07e1-4af4-811c-a2de2e8f3f54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5d44ec2-4b1d-42e6-ac54-cb8f8afad195', 'It turns into liquid water', false, '7e12f2bc-07e1-4af4-811c-a2de2e8f3f54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a09def1d-ce20-4ce3-923b-391d208c6493', 'It reacts with glass to form acid', false, '7e12f2bc-07e1-4af4-811c-a2de2e8f3f54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('115dc7e4-44c9-4298-b4a9-b6dc509c5516', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'What comprehensive scientific principle summarizes Chapter 5 of NCERT Class 7 Science?', 'Chapter 5 integrates the molecular taxonomy of matter: phase transitions, stoichiometry of chemical reactions, corrosion mechanisms, and purification metallurgy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f11e019c-21a5-4028-9dd5-544c1db75e4f', 'Matter undergoes physical transformations altering state and shape without changing chemical identity, alongside profound chemical reactions that synthesize new substances, drive biological metabolism, power metallurgy, and govern natural biogeochemical cycles', true, '115dc7e4-44c9-4298-b4a9-b6dc509c5516');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d8102ed-c120-47ca-a491-bae5f305e0f0', 'All physical changes are chemical changes', false, '115dc7e4-44c9-4298-b4a9-b6dc509c5516');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90a4d4ea-e289-4189-bab2-a81ffe697cc6', 'Chemical reactions only happen in laboratories', false, '115dc7e4-44c9-4298-b4a9-b6dc509c5516');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75b9470d-8061-4055-8639-12d9ae997ea0', 'Rusting can be prevented by heating iron to 1,000°C', false, '115dc7e4-44c9-4298-b4a9-b6dc509c5516');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbb92224-3729-4c85-abd2-32ff6e4c0160', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'When the sum of the measures of two angles is exactly 90°, the angles are called:', 'Two angles are complementary if their sum is 90° (∠A + ∠B = 90°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75631fee-ee72-4603-becc-7996a01f0eac', 'Complementary Angles', true, 'bbb92224-3729-4c85-abd2-32ff6e4c0160');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cce82a34-4a69-4818-bf74-88577aa86aa4', 'Supplementary Angles', false, 'bbb92224-3729-4c85-abd2-32ff6e4c0160');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba5f0a37-5340-4159-90b9-5fcb42c5d70e', 'Adjacent Angles', false, 'bbb92224-3729-4c85-abd2-32ff6e4c0160');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43e0b1f5-7cd7-47eb-95e5-eb0a9b7b3826', 'Vertically Opposite Angles', false, 'bbb92224-3729-4c85-abd2-32ff6e4c0160');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eeb19ae2-2e34-4f97-87de-b130526f9ae1', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'When the sum of the measures of two angles is exactly 180°, the angles are called:', 'Two angles are supplementary if their sum equals 180° (∠A + ∠B = 180°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e409d67b-df75-4227-ae01-fc0d74bf170e', 'Supplementary Angles', true, 'eeb19ae2-2e34-4f97-87de-b130526f9ae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab1c08b3-205c-45b9-b455-090d7dcb38a4', 'Complementary Angles', false, 'eeb19ae2-2e34-4f97-87de-b130526f9ae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2666703b-4e44-4718-bb9a-6c4b384aa51d', 'Linear Pair', false, 'eeb19ae2-2e34-4f97-87de-b130526f9ae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bf5f1a3-83cf-46ec-a9fb-2facf53a668e', 'Reflex Angles', false, 'eeb19ae2-2e34-4f97-87de-b130526f9ae1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4bba7032-8db6-4dcd-8e6a-582255264e44', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'Find the Complement of the angle 30°:', 'Complement = 90° - 30° = 60°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f05f518-4768-4316-8a2c-1edcc134f445', '60° (90° - 30° = 60°)', true, '4bba7032-8db6-4dcd-8e6a-582255264e44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f017c95e-5ef1-4eec-b141-73e5af7e8f0a', '150°', false, '4bba7032-8db6-4dcd-8e6a-582255264e44');
