INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15ebdd9e-23a9-4081-a794-6b80818fceb4', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'Find the Supplement of the angle 105°:', 'Supplement = 180° - 105° = 75°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45214451-32e8-4e58-99be-d6a770bb60b7', '75° (180° - 105° = 75°)', true, '15ebdd9e-23a9-4081-a794-6b80818fceb4');
