INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9956739-7bbe-4def-a3ae-724d148075cf', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'An angle which is equal to its own Complement is:', 'x + x = 90° → 2x = 90° → x = 45°.', NOW()) ON CONFLICT DO NOTHING;
