INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de831fc0-6415-409c-aa84-8649fb19c4eb', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'An angle which is equal to its own Supplement is:', 'x + x = 180° → 2x = 180° → x = 90°.', NOW()) ON CONFLICT DO NOTHING;
