INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4495b3ac-ead7-4d01-81b6-5d5b3112ac57', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'When two lines intersect at a point, the vertically opposite angles formed are ALWAYS:', 'Vertically opposite angles formed by intersecting lines are congruent (equal in measure).', NOW()) ON CONFLICT DO NOTHING;
