INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('094a9f0b-0f80-4fe6-bdcb-cfcf1985e0f5', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'A line that intersects two or more lines at distinct points is called a:', 'A transversal is a line intersecting two or more coplanar lines at distinct points.', NOW()) ON CONFLICT DO NOTHING;
