INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac00eaad-10b2-462b-9a80-78310d0cf9a1', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'If two parallel lines are cut by a transversal, each pair of Alternate Interior Angles is:', 'Alternate interior angles formed by parallel lines cut by a transversal are equal (Z-property).', NOW()) ON CONFLICT DO NOTHING;
