INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd508a81-c3b7-4197-a4ea-4883267fe3d1', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'If two parallel lines are cut by a transversal, each pair of Corresponding Angles is:', 'Corresponding angles situated in identical relative positions at each intersection are equal (F-property).', NOW()) ON CONFLICT DO NOTHING;
