INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e50867c-e824-4910-88a6-47ec02cc4489', 'Supplementary', false, 'fd508a81-c3b7-4197-a4ea-4883267fe3d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84f8db29-7149-4cda-b710-ba0b17825f40', '90°', false, 'fd508a81-c3b7-4197-a4ea-4883267fe3d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a51c54d-7c24-496e-817b-04cd49531e90', 'Unequal', false, 'fd508a81-c3b7-4197-a4ea-4883267fe3d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9435eef4-b8ac-4774-a15d-d32157c87f96', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'If two parallel lines are cut by a transversal, the interior angles on the SAME SIDE of the transversal are:', 'Consecutive interior angles on the same side of a transversal intersecting parallel lines sum to 180° (C-property).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb34caff-5cb7-4750-94dd-1c3683602acc', 'Supplementary (sum to 180°)', true, '9435eef4-b8ac-4774-a15d-d32157c87f96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('888f1b17-e410-4f1b-a880-1593dd904994', 'Equal', false, '9435eef4-b8ac-4774-a15d-d32157c87f96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14b05979-82b3-4110-92f6-577575d68140', 'Complementary (sum to 90°)', false, '9435eef4-b8ac-4774-a15d-d32157c87f96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd81f4e1-a0d4-413b-a0bf-4c1493bc7531', 'Zero', false, '9435eef4-b8ac-4774-a15d-d32157c87f96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d24b79d4-a273-4bdd-8d73-24644bc84847', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Two complementary angles are in the ratio 2 : 3. Find the measure of both angles:', '5x = 90° → x = 18°. Angles are 2(18) = 36° and 3(18) = 54°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d17f35-ef2f-438d-8a6e-62f406c2a29d', '36° and 54° (2x + 3x = 90° ⇒ 5x = 90° ⇒ x = 18° ⇒ 2(18) = 36°, 3(18) = 54°)', true, 'd24b79d4-a273-4bdd-8d73-24644bc84847');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69bc1359-bf98-4b21-8b93-22ab121d1bd2', '30° and 60°', false, 'd24b79d4-a273-4bdd-8d73-24644bc84847');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cb8f2eb-e0e2-4642-b767-88ed8088cb6a', '40° and 50°', false, 'd24b79d4-a273-4bdd-8d73-24644bc84847');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50a3a02a-e178-491d-843a-8ae852a364ac', '20° and 70°', false, 'd24b79d4-a273-4bdd-8d73-24644bc84847');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9cd536a4-9219-45ee-aa0f-d55b00772a27', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Two supplementary angles are in the ratio 4 : 5. Find the measure of the larger angle:', '9x = 180° → x = 20°. Larger angle = 5 × 20° = 100°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e26563cd-9678-4bfb-983c-57a456ece6bb', '100° (4x + 5x = 180° ⇒ 9x = 180° ⇒ x = 20° ⇒ Larger = 5(20) = 100°)', true, '9cd536a4-9219-45ee-aa0f-d55b00772a27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e88af67-e011-472a-b59f-345a230cc59b', '80°', false, '9cd536a4-9219-45ee-aa0f-d55b00772a27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7099ae24-2d8c-43aa-ac58-e0c39247af99', '120°', false, '9cd536a4-9219-45ee-aa0f-d55b00772a27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad6175dd-232d-4680-9d1c-3b83ee086cb0', '90°', false, '9cd536a4-9219-45ee-aa0f-d55b00772a27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c1c51c0-1d06-4b23-b7e3-fe6200890bc4', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'An angle is 24° more than its Complement. Find the measure of the angle:', 'x - (90 - x) = 24 → 2x = 114 → x = 57° (Complement = 33°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb281796-9b68-4d52-8380-227a409b75ab', '57° (x = (90° - x) + 24° ⇒ 2x = 114° ⇒ x = 57°)', true, '7c1c51c0-1d06-4b23-b7e3-fe6200890bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('377d1d53-af74-4068-8da5-08592fe3c54a', '33°', false, '7c1c51c0-1d06-4b23-b7e3-fe6200890bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3116abc0-68e3-4ddb-8181-f5372a31bc57', '66°', false, '7c1c51c0-1d06-4b23-b7e3-fe6200890bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd5f1d85-801d-4b73-a707-e18526d92fdf', '48°', false, '7c1c51c0-1d06-4b23-b7e3-fe6200890bc4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5300592-463a-4613-ab0a-4112b88fd95e', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'An angle is 44° less than its Supplement. Find the measure of the angle:', 'x = 180 - x - 44 → 2x = 136 → x = 68° (Supplement = 112°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9455ae5d-959b-4726-a1a6-8ab87d9cc97c', '68° (x = (180° - x) - 44° ⇒ 2x = 136° ⇒ x = 68°)', true, 'c5300592-463a-4613-ab0a-4112b88fd95e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1e67a80-5530-4679-aa1d-7ce53707e449', '112°', false, 'c5300592-463a-4613-ab0a-4112b88fd95e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa97b8da-08fa-40ac-831f-938a952e7be4', '72°', false, 'c5300592-463a-4613-ab0a-4112b88fd95e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd0095ef-5de8-4036-a86f-c0051644bb58', '56°', false, 'c5300592-463a-4613-ab0a-4112b88fd95e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cddb9ded-8421-4968-a10d-98f553301fdb', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Two lines AB and CD intersect at point O. If ∠AOC = 50°, find the measure of ∠BOD and ∠AOD:', 'Vertically opposite ∠BOD = ∠AOC = 50°. Linear pair ∠AOD = 180° - 50° = 130°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b29f77f-2e5f-43ac-95c2-35f4171ae44f', '∠BOD = 50° (vertically opposite) ; ∠AOD = 130° (linear pair: 180° - 50° = 130°)', true, 'cddb9ded-8421-4968-a10d-98f553301fdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('631fad75-82d7-497e-86b4-00cc4a6a66cd', '∠BOD = 130° ; ∠AOD = 50°', false, 'cddb9ded-8421-4968-a10d-98f553301fdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('422b8346-fcb1-4319-b0bc-d081c759f903', '∠BOD = 50° ; ∠AOD = 50°', false, 'cddb9ded-8421-4968-a10d-98f553301fdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50e2d32c-1519-484b-9158-0d97c89addc4', '∠BOD = 40° ; ∠AOD = 140°', false, 'cddb9ded-8421-4968-a10d-98f553301fdb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51489451-2f18-42e0-b7e7-3cbb09afc8f8', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'In the given linear pair, two angles are (2x - 10)° and (3x + 20)°. Find the value of x:', '5x + 10 = 180 → 5x = 170 → x = 34. (Angles: 58° and 122°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4cdc667-3716-41a2-bf7d-054a302e9615', 'x = 34 ((2x - 10) + (3x + 20) = 180° ⇒ 5x + 10 = 180° ⇒ 5x = 170° ⇒ x = 34)', true, '51489451-2f18-42e0-b7e7-3cbb09afc8f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c9c0c5f-7a5d-49d0-b6ed-3bc8544f78da', 'x = 30', false, '51489451-2f18-42e0-b7e7-3cbb09afc8f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('123b3a16-e8d5-4c61-9dce-59454ca54cf4', 'x = 35', false, '51489451-2f18-42e0-b7e7-3cbb09afc8f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c25af7b-2801-4c29-b21c-07130a7bbae0', 'x = 38', false, '51489451-2f18-42e0-b7e7-3cbb09afc8f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a05ca4fd-2526-400f-8412-c1fb55b0a393', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Can two ACUTE angles be supplementary to each other?', 'If ∠A < 90° and ∠B < 90°, ∠A + ∠B < 180°, so two acute angles can never be supplementary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb3525fb-3a91-407f-a6a1-ddc6d0607f2f', 'No, because acute angles are strictly < 90°, so their sum is ALWAYS strictly < 180°', true, 'a05ca4fd-2526-400f-8412-c1fb55b0a393');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e326e79-673b-476e-990a-e4f1d07b60d5', 'Yes, if both angles are 45°', false, 'a05ca4fd-2526-400f-8412-c1fb55b0a393');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86852210-ee0a-4e0b-92b9-6ecb72944281', 'Yes, in right-angled triangles', false, 'a05ca4fd-2526-400f-8412-c1fb55b0a393');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5e26c9c-cd00-46e7-8b4a-9381505589cb', 'Always yes', false, 'a05ca4fd-2526-400f-8412-c1fb55b0a393');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cdfb8891-edfa-4fcb-a2cd-74db66503d9d', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Can two OBTUSE angles be supplementary to each other?', 'If ∠A > 90° and ∠B > 90°, ∠A + ∠B > 180°, so two obtuse angles can never be supplementary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40619dd7-103f-4e55-ba82-67b10ce57b14', 'No, because obtuse angles are strictly > 90°, so their sum is ALWAYS strictly > 180°', true, 'cdfb8891-edfa-4fcb-a2cd-74db66503d9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df715d12-35e5-4638-bec0-88f19f2e93ca', 'Yes, if both are 100°', false, 'cdfb8891-edfa-4fcb-a2cd-74db66503d9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b71518c-a1d2-45f7-b8a4-c7ed691a9a64', 'Yes, in pentagons', false, 'cdfb8891-edfa-4fcb-a2cd-74db66503d9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86ec5618-d128-456a-9259-772d30db1ed7', 'Always yes', false, 'cdfb8891-edfa-4fcb-a2cd-74db66503d9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47bdfefd-868c-49d6-8663-62ac1405b0b0', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Can two RIGHT angles be supplementary to each other?', 'Two right angles (90° + 90° = 180°) are always supplementary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f03eef23-a10f-4786-b7cd-f1d18ff72046', 'Yes, because 90° + 90° = exactly 180°', true, '47bdfefd-868c-49d6-8663-62ac1405b0b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c749bead-3dcd-4dbd-8e2b-5822bc99db70', 'No, right angles can only be complementary', false, '47bdfefd-868c-49d6-8663-62ac1405b0b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0de3f260-5597-45c0-8924-01fba05caf87', 'Only in squares', false, '47bdfefd-868c-49d6-8663-62ac1405b0b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28f4f8b0-568f-4236-9def-108824d3a0f0', 'Never', false, '47bdfefd-868c-49d6-8663-62ac1405b0b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8349c3b3-8cfd-4150-ace3-50f85992175f', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'If line l is parallel to line m (l ∥ m) and a transversal t cuts them, one of the interior angles is 65°. What is the measure of the alternate interior angle?', 'Alternate interior angles formed by parallel lines cut by a transversal are equal: 65°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bd7c4d3-a4dc-4671-a5e6-b452e2974282', '65° (Alternate interior angles are equal)', true, '8349c3b3-8cfd-4150-ace3-50f85992175f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15fb7506-b611-4fd6-8228-f72bb5cd8e83', '115°', false, '8349c3b3-8cfd-4150-ace3-50f85992175f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6960245-05e9-4a6c-a7e0-30a99760f20e', '25°', false, '8349c3b3-8cfd-4150-ace3-50f85992175f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb973de3-73fa-4801-946a-08bb6eef7617', '90°', false, '8349c3b3-8cfd-4150-ace3-50f85992175f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3f0e65f-8c67-4a4f-973b-ec0b8de70b5d', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'If line l is parallel to line m (l ∥ m) and a transversal cuts them, one interior angle is 70°. What is the interior angle on the SAME SIDE of the transversal?', 'Interior angles on the same side sum to 180°: 180° - 70° = 110°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f98f4abf-7589-44f9-a2a1-5dfaae90719f', '110° (Consecutive interior angles are supplementary: 180° - 70° = 110°)', true, 'e3f0e65f-8c67-4a4f-973b-ec0b8de70b5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7af0079-771a-47ae-a0c6-47f7184df675', '70°', false, 'e3f0e65f-8c67-4a4f-973b-ec0b8de70b5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc744908-4a1b-4fe2-8c4a-3d5f67e441d3', '20°', false, 'e3f0e65f-8c67-4a4f-973b-ec0b8de70b5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7179852-ee5b-45b8-ad3e-447f0fac8774', '180°', false, 'e3f0e65f-8c67-4a4f-973b-ec0b8de70b5d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97455889-0b12-4ea0-bef5-f6828aed6f36', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Three angles at a point on a straight line are x°, (x + 20)°, and (x + 40)°. Find the value of x:', '3x + 60° = 180° → 3x = 120° → x = 40°. (Angles: 40°, 60°, 80°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a07b24f-4715-490e-95f2-a846df3405b4', 'x = 40 (x + (x + 20) + (x + 40) = 180° ⇒ 3x + 60 = 180° ⇒ 3x = 120° ⇒ x = 40)', true, '97455889-0b12-4ea0-bef5-f6828aed6f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a881d43d-e0d8-4262-9ede-ccf36180e628', 'x = 30', false, '97455889-0b12-4ea0-bef5-f6828aed6f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c86763c-0a1f-49dc-a483-695e9e249454', 'x = 50', false, '97455889-0b12-4ea0-bef5-f6828aed6f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2483c13-5a4c-451c-8d15-f9b4a345864e', 'x = 45', false, '97455889-0b12-4ea0-bef5-f6828aed6f36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dff4ac03-4238-443f-9264-281b1d240d97', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'In the figure, four rays meet at a common point O. What is the sum of all angles around a point?', 'The sum of all angles around a single point in a plane is 360° (complete angle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c345260-4683-4800-91e1-b1e5829bb312', '360° (Complete Angle)', true, 'dff4ac03-4238-443f-9264-281b1d240d97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('037f1afe-dce2-4d07-bd06-3dc13489e234', '180°', false, 'dff4ac03-4238-443f-9264-281b1d240d97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27f34b48-fa2a-4812-892d-c107a0a2dc0a', '270°', false, 'dff4ac03-4238-443f-9264-281b1d240d97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a78073a-9fa8-4c88-b914-980ca0a788ed', '90°', false, 'dff4ac03-4238-443f-9264-281b1d240d97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11948f10-ee0a-4e19-a2e2-54a7a1efb852', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Two parallel lines are cut by a transversal. If a pair of corresponding angles is represented by (3x - 15)° and (2x + 10)°, find the value of x:', 'Corresponding angles are equal: 3x - 15 = 2x + 10 → x = 25. (Angle = 60°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33ed0074-92b0-436e-b20d-5d27c89faa43', 'x = 25 (3x - 15 = 2x + 10 ⇒ x = 25)', true, '11948f10-ee0a-4e19-a2e2-54a7a1efb852');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e87e2f22-62d4-4427-b8e7-18a12df0aa7c', 'x = 20', false, '11948f10-ee0a-4e19-a2e2-54a7a1efb852');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97b759f2-31a1-41eb-9fd5-2dded1cdf435', 'x = 30', false, '11948f10-ee0a-4e19-a2e2-54a7a1efb852');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0fc9d4f-815c-498a-aba4-c3a75138c275', 'x = 15', false, '11948f10-ee0a-4e19-a2e2-54a7a1efb852');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d96b4453-1bd8-4711-975f-d2907b43ad7d', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'If an angle is five times its own Complement, what is the measure of the angle?', 'x = 5(90 - x) → 6x = 450 → x = 75° (Complement = 15°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4936876-0661-46cf-8dc8-3f02e375e05b', '75° (x = 5(90° - x) ⇒ x = 450° - 5x ⇒ 6x = 450° ⇒ x = 75°)', true, 'd96b4453-1bd8-4711-975f-d2907b43ad7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4f048b7-d295-425f-a873-c0ecfb06fd53', '15°', false, 'd96b4453-1bd8-4711-975f-d2907b43ad7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5b0cdee-408e-443c-a4a7-a5ee2222bc5e', '60°', false, 'd96b4453-1bd8-4711-975f-d2907b43ad7d');
