INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2211715-0a20-4077-884e-0c5f323a9a66', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'What geometric condition PROVES that two lines are parallel when intersected by a transversal?', 'Euclidean parallel postulates: equality of corresponding/alternate angles or supplementarity of interior angles proves parallelism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7f3d405-c0e1-4101-96be-6114862af4a3', 'Any one of the three: (1) Alternate interior angles are equal, OR (2) Corresponding angles are equal, OR (3) Consecutive interior angles are supplementary', true, 'e2211715-0a20-4077-884e-0c5f323a9a66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33fd74c8-96db-4a9d-9799-6801d3280c9a', 'The lines meet at a point', false, 'e2211715-0a20-4077-884e-0c5f323a9a66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b691ce1-674c-44be-80f5-217fc3ee8448', 'The lines are perpendicular', false, 'e2211715-0a20-4077-884e-0c5f323a9a66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c65e68b1-ca3d-45e0-9c1b-f57c54c0ead1', 'The lines are drawn in blue color', false, 'e2211715-0a20-4077-884e-0c5f323a9a66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da5042d1-ccaf-48f8-9ed1-9724f84de620', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edda2dd3-6c87-4447-960c-e1672bef9b34', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'da5042d1-ccaf-48f8-9ed1-9724f84de620');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72ed82dc-19d2-4a26-b598-7d5d39592d77', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'da5042d1-ccaf-48f8-9ed1-9724f84de620');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('280b72d3-3cc5-46c7-9fb9-01a4e3f1465b', '(A) is true, but (R) is false.', false, 'da5042d1-ccaf-48f8-9ed1-9724f84de620');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cd4e1e1-2e4f-47e0-b5ad-ba7592ba0712', '(A) is false, but (R) is true.', false, 'da5042d1-ccaf-48f8-9ed1-9724f84de620');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('950c1591-8cb2-47cd-89e0-4248d70a085b', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Spot the IMPOSTER among the following geometric statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30aaf3f2-ac95-40fa-a844-104ab3a67b1b', 'Statement 1', false, '950c1591-8cb2-47cd-89e0-4248d70a085b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97cf2c65-6b19-493f-a2fe-29657c803c8e', 'Statement 2', false, '950c1591-8cb2-47cd-89e0-4248d70a085b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdbeb232-0de6-4279-bc29-767d69ac36c8', 'Statement 3', false, '950c1591-8cb2-47cd-89e0-4248d70a085b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56fe4ac3-3bc3-4ad4-a245-8873148bacd8', 'Statement 4 (Two obtuse angles sum to > 180°, so they can NEVER form a linear pair)', true, '950c1591-8cb2-47cd-89e0-4248d70a085b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f09aaf3-d0bb-4e85-b3a7-b5a7c41eb354', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'In the figure, AB ∥ CD and CD ∥ EF. If y : z = 3 : 7, find the angle x (where x and y are consecutive interior angles between AB and CD, and x and z are alternate interior angles between AB and EF):', 'x = z (alternate angles across AB ∥ EF). y + z = 180° → 10k = 180° → k = 18° → z = 126° → x = 126°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc140e2d-bb40-46fa-a8b1-f1311dd8d088', 'x = 126° (Since AB ∥ EF, x = z ; Consecutive interior: x + y = 180° ⇒ z + y = 180° ; y:z = 3:7 ⇒ 10k = 180° ⇒ k = 18° ⇒ z = 7(18) = 126° ⇒ x = 126°)', true, '5f09aaf3-d0bb-4e85-b3a7-b5a7c41eb354');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1df75d7c-d4ad-4b53-b417-47412ba84bf9', 'x = 54°', false, '5f09aaf3-d0bb-4e85-b3a7-b5a7c41eb354');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3569a63-f111-45c7-b3d6-c363d1861841', 'x = 135°', false, '5f09aaf3-d0bb-4e85-b3a7-b5a7c41eb354');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d4b9f4e-6eba-4477-9f42-6b758df23c11', 'x = 120°', false, '5f09aaf3-d0bb-4e85-b3a7-b5a7c41eb354');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('275b162c-be80-495d-a9ed-14f32fa25d77', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Match Column I (Angle Relationships for Parallel Lines) with Column II (Geometric Letter Mnemonics / Properties):
(a) Corresponding Angles         -> (i) ''F'' Shape / Congruent (Equal)
(b) Alternate Interior Angles    -> (ii) ''Z'' Shape / Congruent (Equal)
(c) Consecutive Interior Angles  -> (iii) ''C'' or ''U'' Shape / Supplementary (Sum = 180°)
(d) Vertically Opposite Angles   -> (iv) ''X'' Shape / Congruent (Equal)', 'F = Corresponding; Z = Alternate; C = Consecutive interior; X = Vertically opposite.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aa04b56-de24-46f7-8771-2462abbfb6ad', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '275b162c-be80-495d-a9ed-14f32fa25d77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('444ef96d-5fa7-40b4-9538-5824c4d4d623', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '275b162c-be80-495d-a9ed-14f32fa25d77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30b5ad5f-a076-44cf-8410-b52a12ce5a8a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '275b162c-be80-495d-a9ed-14f32fa25d77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ad0b1fd-1df2-44f1-b4f7-b13a01267ce8', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '275b162c-be80-495d-a9ed-14f32fa25d77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3fec6a9c-25ac-45c6-9f38-e6d165b0718e', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Read the statements regarding lines and rays:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('380a9e5b-a88e-48c7-8bd5-302f9451ad30', 'Statements 1 and 2 only', true, '3fec6a9c-25ac-45c6-9f38-e6d165b0718e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38813a1c-9046-46c9-9289-97685e32212c', 'Statements 2 and 3 only', false, '3fec6a9c-25ac-45c6-9f38-e6d165b0718e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e42f9581-98b5-4206-b9b4-6acab982c8a9', 'Statements 1 and 3 only', false, '3fec6a9c-25ac-45c6-9f38-e6d165b0718e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d51edb2a-fffb-4068-95b4-42919dc2b36e', 'All Statements 1, 2, and 3', false, '3fec6a9c-25ac-45c6-9f38-e6d165b0718e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94d3e3f6-a60e-43dc-a6f9-5579b31ff391', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'An angle''s supplement is 10° more than THREE TIMES its complement. Find the measure of the angle:', '180 - x = 3(90 - x) + 10 → 180 - x = 280 - 3x → 2x = 100 → x = 50°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9ec795c-b734-49aa-8acc-c1a86989d82e', '50° (180° - x = 3(90° - x) + 10° ⇒ 180° - x = 270° - 3x + 10° ⇒ 2x = 100° ⇒ x = 50°)', true, '94d3e3f6-a60e-43dc-a6f9-5579b31ff391');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ead53e0-48ad-4d23-9b58-e21c2fac65c0', '40°', false, '94d3e3f6-a60e-43dc-a6f9-5579b31ff391');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('320c0d9d-0ea6-4cae-a972-ef89a0742258', '60°', false, '94d3e3f6-a60e-43dc-a6f9-5579b31ff391');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae6986e3-6d33-4ed6-84cd-0cdeaa3b3673', '45°', false, '94d3e3f6-a60e-43dc-a6f9-5579b31ff391');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3f055ba-f99c-48c6-90c4-09d9b842cb36', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'In the figure, arms of two angles are parallel (AB ∥ DE and BC ∥ EF). If ∠ABC = 70°, what is the measure of ∠DEF?', 'Parallel arms theorem: if both angle pairs point in the same directional orientation, ∠DEF = ∠ABC = 70°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03536a0d-13c8-41f8-8619-d5a8233bd066', '70° (Angles with mutually parallel arms are either equal or supplementary ; here both are acute, so ∠DEF = 70°)', true, 'f3f055ba-f99c-48c6-90c4-09d9b842cb36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fac246cf-22c7-4573-bf21-216016d86592', '110°', false, 'f3f055ba-f99c-48c6-90c4-09d9b842cb36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2091b883-9518-4ef2-81d1-9cbb2836406a', '20°', false, 'f3f055ba-f99c-48c6-90c4-09d9b842cb36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a6146e4-f9e3-4251-bff3-da21eb0d2ece', '90°', false, 'f3f055ba-f99c-48c6-90c4-09d9b842cb36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0a6528b-e907-41bd-88da-34bbf99251a4', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'If the bisectors of two adjacent supplementary angles are drawn, what is the exact angle formed BETWEEN THE TWO BISECTORS?', 'Half of supplementary linear pair: θ/2 + (180 - θ)/2 = 90° (perpendicular angle bisectors).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9713e1c4-10e3-415d-ae42-18d82b896650', '90° (Always a RIGHT ANGLE: if ∠1 + ∠2 = 180°, then ∠1/2 + ∠2/2 = 180°/2 = 90°)', true, 'e0a6528b-e907-41bd-88da-34bbf99251a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('894571d1-5770-415f-8bf3-f9b8ca603c6f', '45°', false, 'e0a6528b-e907-41bd-88da-34bbf99251a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e801803-8dad-499b-9851-0eba8bf81b13', '180°', false, 'e0a6528b-e907-41bd-88da-34bbf99251a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19175e17-667c-4bcf-b5da-2aa41b81050c', '60°', false, 'e0a6528b-e907-41bd-88da-34bbf99251a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c522339c-ddab-45d7-9e37-a8812a57255b', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Two parallel lines l and m are cut by transversal t. The interior angles on the same side are (2x + 30)° and (3x - 20)°. Find the value of x and both angles:', '5x + 10 = 180 → 5x = 170 → x = 34. Angle 1 = 2(34)+30 = 98°; Angle 2 = 3(34)-20 = 82°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb7cae9a-a56e-4371-9ed0-eb4e078c0860', 'x = 34 ; Angles are 98° and 82° ((2x + 30) + (3x - 20) = 180° ⇒ 5x + 10 = 180° ⇒ 5x = 170° ⇒ x = 34 ⇒ Angles: 98°, 82°)', true, 'c522339c-ddab-45d7-9e37-a8812a57255b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f53ef78-bddc-4d94-b463-6511d6efde82', 'x = 30 ; Angles are 90°, 90°', false, 'c522339c-ddab-45d7-9e37-a8812a57255b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d700928d-ec84-4bcb-aee9-3b4e963dfb60', 'x = 32 ; Angles are 94°, 86°', false, 'c522339c-ddab-45d7-9e37-a8812a57255b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae4825af-d1b7-43ec-bb5d-8351862826f4', 'x = 35 ; Angles are 100°, 80°', false, 'c522339c-ddab-45d7-9e37-a8812a57255b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b334f5a7-ddcd-4133-ad53-b6e836d0f647', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Line l ∥ line m. A transversal intersects them. If the exterior angle is (5x - 25)° and its alternate exterior angle is (3x + 15)°, find the measure of this angle:', 'Alternate exterior angles are equal: 5x - 25 = 3x + 15 → 2x = 40 → x = 20. Angle = 5(20) - 25 = 75°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c873db80-134e-46a7-8ab9-69c9c9de473f', '75° (5x - 25 = 3x + 15 ⇒ 2x = 40 ⇒ x = 20 ⇒ Angle = 5(20) - 25 = 75°)', true, 'b334f5a7-ddcd-4133-ad53-b6e836d0f647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92f59b91-63c9-450f-9e16-3b38298f167b', '65°', false, 'b334f5a7-ddcd-4133-ad53-b6e836d0f647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b9fa9e-1bc5-4fe7-97f4-569e919a8298', '85°', false, 'b334f5a7-ddcd-4133-ad53-b6e836d0f647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e62f3897-d97a-46e1-82a5-fd3f0b3cdbe0', '90°', false, 'b334f5a7-ddcd-4133-ad53-b6e836d0f647');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d731d685-5fe9-49df-a51c-170e344f31b4', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'If two parallel lines are intersected by a transversal, what quadrilateral is formed by the bisectors of ALL four interior angles?', 'Interior angle bisectors intersect at 90° and form parallel opposite segments, proving the enclosed quadrilateral is a rectangle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('517f0014-772c-4052-adab-7ab6fe6f9850', 'A RECTANGLE (All four interior angles of the formed quadrilateral are 90°, and opposite sides are parallel)', true, 'd731d685-5fe9-49df-a51c-170e344f31b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbd999b2-d185-471e-923e-6bc04352ee74', 'A Square only', false, 'd731d685-5fe9-49df-a51c-170e344f31b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('982aff51-b50d-406b-ad94-7c4c66270017', 'A Rhombus', false, 'd731d685-5fe9-49df-a51c-170e344f31b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('676b8ad9-3c01-4124-a271-a853d81b1c8d', 'A Trapezium', false, 'd731d685-5fe9-49df-a51c-170e344f31b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d9ff7cc-8205-47e3-bc9c-b6a6b1401563', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Why is the rigorous understanding of Lines, Transversals, and Angles foundational in structural engineering, architecture, optical ray tracing, and computer graphics?', 'Euclidean parallel line theory and angle relationships form the mathematical bedrock of structural mechanics, optics, spatial modeling, and vector graphics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77e8ee18-402f-4312-b9b6-299f2a6ed8d5', 'It provides the exact trigonometric and geometric axioms governing coordinate transformations, structural load balance in trusses, ray reflection/refraction, and 3D rendering projections', true, '8d9ff7cc-8205-47e3-bc9c-b6a6b1401563');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('036dee2e-68b2-4d6e-bd25-2a4c7d3cae75', 'Because angles are only used to draw circles', false, '8d9ff7cc-8205-47e3-bc9c-b6a6b1401563');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7258d9cd-78cd-449a-bad2-070750357018', 'Because parallel lines do not exist in reality', false, '8d9ff7cc-8205-47e3-bc9c-b6a6b1401563');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d097c4ac-1562-47a4-90c0-d0a8d28bba46', 'Because transversal lines eliminate the need for calculations', false, '8d9ff7cc-8205-47e3-bc9c-b6a6b1401563');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eca64709-4236-42a3-a955-bd62cc0faf9d', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'In John Galsworthy''s moving classic story ''Quality'', who was Mr. Gessler?', 'Mr. Gessler was an artisanal German bootmaker living in London, devoted entirely to the perfection of his craft.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42de1950-4a08-4b07-9073-5da3bb480a9d', 'A master German bootmaker who lived in London and made boots of supreme perfection and artistic quality', true, 'eca64709-4236-42a3-a955-bd62cc0faf9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaf2654e-5218-4db8-8d33-ee734427b287', 'A wealthy factory owner', false, 'eca64709-4236-42a3-a955-bd62cc0faf9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1a7feff-cd2f-4230-9525-41d202876a55', 'A famous theater actor', false, 'eca64709-4236-42a3-a955-bd62cc0faf9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9439b4b-5f88-43e7-a215-884623002108', 'A royal doctor', false, 'eca64709-4236-42a3-a955-bd62cc0faf9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34416919-1cc1-45b3-af1e-8db608a7a18d', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'Where was Mr. Gessler''s quiet little boot-making shop situated in London?', 'Gessler Brothers'' shop was nestled in a distinguished, quiet by-street in London''s fashionable West End.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3de67fc8-585a-4b62-bf0e-57e656e2f43d', 'In a small by-street in the fashionable West End of London', true, '34416919-1cc1-45b3-af1e-8db608a7a18d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9389ff5f-a2cb-4ea4-b8b0-fe0638d6b5ba', 'In the center of a crowded marketplace', false, '34416919-1cc1-45b3-af1e-8db608a7a18d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11081f0e-ec24-4dce-b066-dbe013faced6', 'Inside a large department store', false, '34416919-1cc1-45b3-af1e-8db608a7a18d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53d92101-1ad4-4aa2-b101-0d0bcde3c01e', 'Near London harbor', false, '34416919-1cc1-45b3-af1e-8db608a7a18d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('191d6afc-cc7c-470d-b2a3-d5272f26b824', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What was uniquely displayed in the modest shop-window of Gessler Brothers?', 'The shop had quiet dignity: no boastful signs, merely ''Gessler Brothers'' and a few masterfully crafted display boots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('127cf5c4-b85e-4e56-b11a-73e075d680f1', 'No sign above except the name ''Gessler Brothers'', and in the window a few pairs of exquisite bespoke handmade boots', true, '191d6afc-cc7c-470d-b2a3-d5272f26b824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dab2e84c-2849-450d-8af4-c3ddb54e8b91', 'Dozens of colorful neon lights', false, '191d6afc-cc7c-470d-b2a3-d5272f26b824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10ea24c2-631a-4c1c-8e92-cdb73a8c7b35', 'Piles of factory-made cheap shoes', false, '191d6afc-cc7c-470d-b2a3-d5272f26b824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('248d96bc-6ed7-4c8d-94b1-412c17b510f9', 'Gold and diamond jewelry', false, '191d6afc-cc7c-470d-b2a3-d5272f26b824');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a2555be-567d-4d0d-8668-875d00f44ed2', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'How did entering Mr. Gessler''s shop feel to the narrator, comparing it to a sacred place?', 'Galsworthy compares entering Gessler''s shop to entering a church, permeated by the solemn scent of fine leather.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76e96414-31a7-4bd1-92f2-2beda898efc9', 'It felt quiet and reverent, as if entering a Church, where one sat on a single wooden chair waiting with respect', true, '2a2555be-567d-4d0d-8668-875d00f44ed2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbbc1a6f-bc43-4e74-ad39-1922f494cbe7', 'It felt like a noisy railway station', false, '2a2555be-567d-4d0d-8668-875d00f44ed2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0442979d-cf55-4b1b-835a-3b461cb9491d', 'It felt like a crowded schoolroom', false, '2a2555be-567d-4d0d-8668-875d00f44ed2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('716c5130-2e16-4e4b-98c7-3e8b41f74a5b', 'It felt like a chaotic street market', false, '2a2555be-567d-4d0d-8668-875d00f44ed2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c98dcadd-ff68-4334-b96e-596bb6dd6101', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What famous sentence in his guttural German accent did Mr. Gessler say when the author asked if making boots was hard?', 'Mr. Gessler considered his bespoke craft an exalted vocation: ''Id is an Ardt!''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a725407-9606-4e21-a7c3-f1c7672f7264', '"Id is an Ardt!" (It is an Art!)', true, 'c98dcadd-ff68-4334-b96e-596bb6dd6101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5927dcef-e40f-4f90-859d-0b6e64dbae68', '"Id is for money!"', false, 'c98dcadd-ff68-4334-b96e-596bb6dd6101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c524116-a2a3-414c-b1bf-56e39b20c48c', '"Id is very easy!"', false, 'c98dcadd-ff68-4334-b96e-596bb6dd6101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79f2d573-16be-4541-b104-2d862fd54b35', '"Id is a factory job!"', false, 'c98dcadd-ff68-4334-b96e-596bb6dd6101');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7679d7d-db8b-42fd-8b6a-3e9cbaa79bd5', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What distinguished Mr. Gessler''s boots from all mass-produced commercial shoes?', 'Gessler''s boots embodied immaculate bespoke fit, finest leather selection, and astonishing durability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bd0301c-71e4-47e8-bb95-107e01450671', 'They fitted perfectly, were made of the finest top-grade leather, and lasted extraordinarily long without losing shape', true, 'a7679d7d-db8b-42fd-8b6a-3e9cbaa79bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e933bde8-9232-4741-92e7-ec6a9c1c1242', 'They were very cheap and broke in a week', false, 'a7679d7d-db8b-42fd-8b6a-3e9cbaa79bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27631865-72d3-476f-bf2e-e610fcc34619', 'They had flashing electric lights', false, 'a7679d7d-db8b-42fd-8b6a-3e9cbaa79bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1721c238-2fc1-4a12-8260-7a9aa503089a', 'They were made of plastic', false, 'a7679d7d-db8b-42fd-8b6a-3e9cbaa79bd5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be03fe89-b889-48e0-a885-e64e7828eb5c', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'Why did Mr. Gessler lose his business customers and face immense financial hardship over the years?', 'Corporate mass advertising crushed individual artisanry: ''Dey get id all... by adverdisement, nod by work''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82de3fcb-8bc0-4a09-ae6b-dd9ce347b8f5', 'Large commercial shoe corporations took away customers through aggressive mass advertising rather than genuine quality of craftsmanship', true, 'be03fe89-b889-48e0-a885-e64e7828eb5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f3456cd-67d2-41c3-914c-07250f998c9f', 'Because he forgot how to make boots', false, 'be03fe89-b889-48e0-a885-e64e7828eb5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7533a6d8-79e2-4ff0-a6b9-f170b219ae77', 'Because he moved to another country', false, 'be03fe89-b889-48e0-a885-e64e7828eb5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('427acd68-0407-483a-ab5a-6b34271727ab', 'Because people stopped wearing shoes', false, 'be03fe89-b889-48e0-a885-e64e7828eb5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce6d7ffb-f9bf-46b8-9e20-f80b7792a843', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What tragic fate befell Mr. Gessler at the end of the story?', 'The English shopman sadly reveals: ''Slow starvation, the doctor called it... he never gave himself time to eat''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b3df327-2b2d-450a-8be0-e6f1ee215a76', 'He died of slow starvation because he spent every penny on fine leather and shop rent without keeping enough food for himself', true, 'ce6d7ffb-f9bf-46b8-9e20-f80b7792a843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09f9648a-3d2a-44f8-9202-841132289d9d', 'He became a wealthy factory owner', false, 'ce6d7ffb-f9bf-46b8-9e20-f80b7792a843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4467d731-acb7-4d90-b360-dc5f4185b2cd', 'He retired to a farm in Germany', false, 'ce6d7ffb-f9bf-46b8-9e20-f80b7792a843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd804159-35b0-4be5-93dc-6a7a39170542', 'He became a famous singer', false, 'ce6d7ffb-f9bf-46b8-9e20-f80b7792a843');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45afba84-4136-4d2a-abeb-2d03b79b74f4', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'In Shirley Bauer''s poem ''Trees'', who are trees primarily for according to the opening stanzas?', 'The poem begins: ''Trees are for birds. / Trees are for children.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a46511d8-5c9a-416d-a7f0-dfbc349a4fb8', 'Trees are for Birds and Children', true, '45afba84-4136-4d2a-abeb-2d03b79b74f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4561d9bc-c365-408d-b0fe-3fe1c6241448', 'Trees are only for furniture makers', false, '45afba84-4136-4d2a-abeb-2d03b79b74f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb0187c8-f7a6-4882-8a69-16001ccc1170', 'Trees are only for painting', false, '45afba84-4136-4d2a-abeb-2d03b79b74f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0e8e043-5011-47b0-b5b7-8a7e4c95d215', 'Trees are for robots', false, '45afba84-4136-4d2a-abeb-2d03b79b74f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bffb6cc8-8c50-4a57-8e33-ac3fba47e1fc', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What recreational games and structures do children build in and around trees in the poem ''Trees''?', 'Bauer highlights childhood delights: building treehouses, swinging on boughs, and playing hide and seek.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28b443ea-d640-4a12-9992-f2a4d645dd30', 'Treehouses to live in, swings to swing on, and hiding spots to play ''Hide and Seek''', true, 'bffb6cc8-8c50-4a57-8e33-ac3fba47e1fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adaf88df-b5b2-4597-9bb6-295303382197', 'Swimming pools', false, 'bffb6cc8-8c50-4a57-8e33-ac3fba47e1fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2bb05f1-3a6e-49f3-a8b4-ec7daa90cb5a', 'Tennis courts', false, 'bffb6cc8-8c50-4a57-8e33-ac3fba47e1fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c622e977-c2ef-44ce-b1cf-3d7b75db77cc', 'Roller coasters', false, 'bffb6cc8-8c50-4a57-8e33-ac3fba47e1fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75ba460c-94f3-43b9-9a6a-e5845459e3db', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What seasonal comfort do trees provide during hot summer months?', 'Textual line: ''Trees are to make cool shade in summer''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb0e664d-6f5d-4637-8790-11a7c9882ffb', 'Cool, refreshing shade', true, '75ba460c-94f3-43b9-9a6a-e5845459e3db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('968944bd-cc95-466e-b052-af67d46913c4', 'Snow', false, '75ba460c-94f3-43b9-9a6a-e5845459e3db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f2622ac-bf47-42a1-847c-97721b44b76b', 'Hot tea', false, '75ba460c-94f3-43b9-9a6a-e5845459e3db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82e5f7f2-1efa-466b-b7c3-44e77a481039', 'Air conditioning', false, '75ba460c-94f3-43b9-9a6a-e5845459e3db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ade9775-e639-4ddb-ba1b-c1c6cf0aa4e8', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What gets caught in tree branches on windy days in the poem ''Trees''?', 'Line from the poem: ''Trees are for kites to get caught in''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23b01bdc-17c7-416c-b88d-8f8cbe737c57', 'Kites', true, '0ade9775-e639-4ddb-ba1b-c1c6cf0aa4e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eb5a084-9983-4533-8e9f-c81e8fbbe945', 'Aeroplanes', false, '0ade9775-e639-4ddb-ba1b-c1c6cf0aa4e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0705beb5-1602-4244-a430-880aa04896fb', 'Clouds', false, '0ade9775-e639-4ddb-ba1b-c1c6cf0aa4e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('225ff715-c846-41db-a9a3-54331723e92e', 'Cars', false, '0ade9775-e639-4ddb-ba1b-c1c6cf0aa4e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75a37841-e262-4468-9aaf-f52464c2c46c', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What did Mr. Gessler do when the narrator once mentioned that a particular pair of boots had creaked?', 'Gessler''s uncompromising professional pride: ''Send dem back... I will look ad dem. If I can do noding... I dake dem off your bill''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcee3ed3-7e02-4c45-814b-d7c028867e7f', 'He was deeply astonished, looked at the narrator incredulously, and promised with immense integrity to examine them and take them off the bill if he could not fix them', true, '75a37841-e262-4468-9aaf-f52464c2c46c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad231f17-353c-427f-91e7-30677eed8036', 'He shouted angrily and threw the author out', false, '75a37841-e262-4468-9aaf-f52464c2c46c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38ba090b-94ea-459c-b45c-93318fbc2fdd', 'He denied that he ever made the boots', false, '75a37841-e262-4468-9aaf-f52464c2c46c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72d99d4a-2cf7-40f0-9dc3-4882336e1bf4', 'He laughed and ignored the author', false, '75a37841-e262-4468-9aaf-f52464c2c46c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c9241e4-dd69-4918-acb8-4497001ec70b', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Why did Mr. Gessler touch the author''s shoe with his finger when the author once absent-mindedly entered wearing shoes bought from a large commercial firm?', 'Gessler''s master eye pinpointed the factory defect instantly: ''Dose big virms ''ave no self-respect... Id ''urds you dere''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8baf115d-30ed-4d86-83ca-56f0ffe38bcf', 'He immediately pressed the exact spot where the factory boot pinched the author''s foot, remarking sadly how big corporations exploit advertising without giving comfort', true, '1c9241e4-dd69-4918-acb8-4497001ec70b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('785808c2-f2d7-48d7-8f52-dd3a5226177b', 'He wanted to polish the shoe', false, '1c9241e4-dd69-4918-acb8-4497001ec70b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c9d5118-8753-4d26-bb35-bd04655ab323', 'He wanted to steal the shoe', false, '1c9241e4-dd69-4918-acb8-4497001ec70b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4739e32-4d93-45ba-a544-46652d9c8d0c', 'He did not care about the shoe', false, '1c9241e4-dd69-4918-acb8-4497001ec70b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8285736a-59ac-40f8-9c29-d74db116f89f', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What tribute did the young English shop assistant pay to Mr. Gessler after his passing?', 'The English successor honors Gessler''s uncompromising genius: ''He made the best boots in London... Never made a better boot in his life''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75819e89-67bc-4bf8-b980-6f07c23b2703', '"He made the best boots in London! Look at the leather he used, and he never compromised on time. He was a character who competed with nobody and starved for his art."', true, '8285736a-59ac-40f8-9c29-d74db116f89f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6254fbf-33cb-441e-ad4b-ed54c5c43df7', 'He said Mr. Gessler was a bad shoemaker', false, '8285736a-59ac-40f8-9c29-d74db116f89f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0aeec3c1-3410-41e6-82c7-bf7aaf021f23', 'He said Mr. Gessler was very lazy', false, '8285736a-59ac-40f8-9c29-d74db116f89f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6646fdae-eebd-4a27-ab30-7abb06f41606', 'He said Mr. Gessler was rich', false, '8285736a-59ac-40f8-9c29-d74db116f89f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('981abca9-d4f8-43f2-9f71-805b6c92c7c1', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'In the poem ''Trees'', what do fathers say when autumn leaves fall from trees?', 'Fathers view autumn pragmatically: ''What a lot of leaves to rake this fall!''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f04ffc1-6f24-40a2-aaea-ac05e54f6f0c', '"What a lot of leaves to rake this fall!"', true, '981abca9-d4f8-43f2-9f71-805b6c92c7c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d724892-ea45-4ec8-a6eb-7d4c1b3ae8bb', '"Let''s plant more flowers!"', false, '981abca9-d4f8-43f2-9f71-805b6c92c7c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08b11464-3640-4e88-8528-44b7568d40c6', '"Winter is over!"', false, '981abca9-d4f8-43f2-9f71-805b6c92c7c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5f8ace0-c629-41eb-bb51-b75f6f06c468', '"Look at the apples!"', false, '981abca9-d4f8-43f2-9f71-805b6c92c7c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2443ccb-511a-4dd1-b8cb-87e106ce355a', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'In the poem ''Trees'', what do mothers say when looking at lush green trees?', 'Mothers view the scenic visual aesthetic: ''What a lovely picture to paint!''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bca7790-5cda-43ed-850d-65a55e0753dc', '"What a lovely picture to paint!"', true, 'e2443ccb-511a-4dd1-b8cb-87e106ce355a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eba4031f-bc38-40ad-8ae1-6efa6be88837', '"Cut down the tree immediately!"', false, 'e2443ccb-511a-4dd1-b8cb-87e106ce355a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7324e7bb-d43e-4fec-8240-e43743bbdee4', '"Where are my keys?"', false, 'e2443ccb-511a-4dd1-b8cb-87e106ce355a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fee820d3-ee2b-4b49-a314-cf78bc01ece3', '"The tree is too big!"', false, 'e2443ccb-511a-4dd1-b8cb-87e106ce355a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25e55501-973d-4317-82fa-b31c0238a0e1', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What delicious fruits are mentioned as growing on trees in Shirley Bauer''s poem?', 'Textual line: ''Trees are for apples to grow on, and pears''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21ac223a-b09b-416c-b9ec-896333846bc8', 'Apples and Pears', true, '25e55501-973d-4317-82fa-b31c0238a0e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f0ac0b2-aa22-43a4-a309-5dc4cca34b23', 'Mangoes and Bananas', false, '25e55501-973d-4317-82fa-b31c0238a0e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('135be9a9-ced2-4ebf-8ca5-75e7761ba226', 'Oranges and Pineapples', false, '25e55501-973d-4317-82fa-b31c0238a0e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff8a0f32-850a-4448-a143-957db8232f95', 'Grapes and Watermelons', false, '25e55501-973d-4317-82fa-b31c0238a0e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a6075a7-d1ca-4c8d-8b64-46196ab24c6d', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What is the meaning of the word ''Splendid'' in: ''The boots were of splendid quality''?', '''Splendid'' denotes magnificent, outstanding artistic and functional excellence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88886e7b-2afd-4ad3-88fe-60f81fc1473a', 'Magnificent, superb, and of exceptional excellence', true, '9a6075a7-d1ca-4c8d-8b64-46196ab24c6d');
