INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5553cb44-987b-4c08-a70a-b946d15e2cb7', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What is the ANTONYM of ''Bespoke'' (custom-made / tailor-made)?', 'The antonym of ''bespoke'' (individually tailored) is ''mass-produced'' or ''ready-made''.', NOW()) ON CONFLICT DO NOTHING;
