INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4fa6ae44-f301-4732-9890-7f1098ed4c9a', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Choose the correctly framed question using the Wh-word ''Why'':', 'Past interrogative syntax: Wh-word + did + subject + base verb (''Why did Mr. Gessler refuse...'').', NOW()) ON CONFLICT DO NOTHING;
