INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5d3883a-5f54-4f0b-a75e-1927de1a9b15', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Identify the figure of speech in: ''The solemn shop was like a temple of leather.''', 'Simile uses ''like'' to explicitly compare the quiet reverence of the boot shop to a sacred temple.', NOW()) ON CONFLICT DO NOTHING;
