INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f02200d3-f288-41b4-aaf7-6707e1f8652e', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What is the meaning of the phrasal verb ''To take off'' in: ''He offered to take the boots off the bill''?', 'In commerce, ''to take off the bill'' means to refund or deduct the cost.', NOW()) ON CONFLICT DO NOTHING;
