INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5d575bb-672a-42ef-8351-c779b70af2cc', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '2ae497b3-1cf1-446e-b984-61b171270e1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('824e3f35-edde-4b12-831b-c8735affa3e1', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '2ae497b3-1cf1-446e-b984-61b171270e1a');
