INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73eab123-b39a-4aed-b1e1-1c5ccbfb9c9c', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'In the poem ''Trees'', what dual perspective is juxtaposed in the lines about autumn:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a1ff63e-640a-4768-a249-65d34def0741', 'A charming contrast between artistic aesthetic appreciation and practical domestic labor evoked by the exact same natural phenomenon', true, '73eab123-b39a-4aed-b1e1-1c5ccbfb9c9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c552bad4-14fc-4d07-9229-fa059bf28bbf', 'A bitter quarrel between parents', false, '73eab123-b39a-4aed-b1e1-1c5ccbfb9c9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33985475-7617-443b-a2cc-20fff1eb4f21', 'That fathers dislike trees', false, '73eab123-b39a-4aed-b1e1-1c5ccbfb9c9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04006204-f47c-47d2-a0fc-8c77f42486c0', 'That mothers paint trees on walls', false, '73eab123-b39a-4aed-b1e1-1c5ccbfb9c9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62ada46d-02ce-44e0-8629-cde5b352e29a', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'Why did the author order several extra pairs of boots from Mr. Gessler whenever he visited, even when he did not urgently need them?', 'The narrator''s repeated orders were altruistic acts of quiet patronage to sustain the noble craftsman.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c46e25d-617e-4220-8265-67a85660ca94', 'Out of deep, compassionate respect and affection, wanting to support the struggling master craftsman financially without wounding his fierce artisanal pride', true, '62ada46d-02ce-44e0-8629-cde5b352e29a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27eb6de4-5e3a-4c61-adb5-bba8d94b486e', 'Because he wanted to sell them for profit', false, '62ada46d-02ce-44e0-8629-cde5b352e29a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d3ee2e6-3684-487d-a721-c116a43d4b44', 'Because he collected 1,000 shoes', false, '62ada46d-02ce-44e0-8629-cde5b352e29a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01e95be9-da34-497e-8b41-2fa44377ecfc', 'Because Mr. Gessler forced him to buy', false, '62ada46d-02ce-44e0-8629-cde5b352e29a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4612bab3-fdf5-464d-aa79-45301df7e745', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'What is the literary significance of the single-word title ''QUALITY'' in Galsworthy''s story?', '''Quality'' operates as a profound philosophical motif: physical excellence fused with uncompromising spiritual and vocational integrity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b286da2-9b1b-47d8-a5da-1ecc278696ba', 'It represents not merely the physical excellence of boots, but the moral, spiritual, and artistic integrity of an uncorrupted human soul dedicated entirely to perfection', true, '4612bab3-fdf5-464d-aa79-45301df7e745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53613300-ef22-400d-b674-3e31380cee3b', 'It is the name of a shoe brand in London', false, '4612bab3-fdf5-464d-aa79-45301df7e745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3b24a3e-d4e4-45df-b351-6861fc0002b3', 'It refers to the price of leather in shops', false, '4612bab3-fdf5-464d-aa79-45301df7e745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b2f00f1-b6b1-4328-9fba-0e01df6894cb', 'It means making shoes quickly', false, '4612bab3-fdf5-464d-aa79-45301df7e745');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9d70796-ec14-4894-ac2b-432497715257', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'What overarching humanist philosophy unites both selections in Chapter 5 of NCERT Class 7 English?', 'Chapter 5 integrates environmental gratitude with reverence for uncorrupted human devotion to craftsmanship and beauty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3276191-0788-4783-b59a-cb7a6fffb882', 'Reverence for authentic value—whether celebrating the generous, quiet beauty of trees enriching the ecosystem or honoring the noble integrity of dedicated craftsmen who pour their souls into their art', true, 'a9d70796-ec14-4894-ac2b-432497715257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46b80f61-0ffe-4c76-93db-4b71e6898fb0', 'That factories are always superior to human hands', false, 'a9d70796-ec14-4894-ac2b-432497715257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('061fc2ab-28c0-4efa-b395-1e69f171dcd0', 'That trees should be chopped down for paper', false, 'a9d70796-ec14-4894-ac2b-432497715257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea113ed7-40ad-4b30-b42c-5f302ca5b31f', 'That shoes should be made only of wood', false, 'a9d70796-ec14-4894-ac2b-432497715257');
