INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6d09a69-82e1-4843-8476-fbb9f37b4017', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'Where is the main Asteroid Belt in our solar system situated?', 'The Asteroid Belt is a circumstellar disc located between the orbits of Mars and Jupiter containing Ceres, Vesta, Pallas, and Hygiea.', NOW()) ON CONFLICT DO NOTHING;
