INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea9aaf02-52a6-46ad-b125-b5cdfd2d4a6f', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'Why was PLUTO reclassified from a full ''planet'' to a ''dwarf planet'' by the International Astronomical Union (IAU) in August 2006?', 'Pluto shares its orbital zone with numerous trans-Neptunian Kuiper belt objects, failing the dynamic orbit clearance criterion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5393ec11-99d8-445a-9671-217556c32d58', 'It failed to meet the third criterion: it has NOT ''cleared the neighborhood around its orbit'' of other Kuiper Belt debris', true, 'ea9aaf02-52a6-46ad-b125-b5cdfd2d4a6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a19fc636-286a-4aea-8bde-a2243907732d', 'Because Pluto melted completely', false, 'ea9aaf02-52a6-46ad-b125-b5cdfd2d4a6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce746d67-7c5c-488e-811f-e7eb42762ee1', 'Because Pluto stopped orbiting the Sun', false, 'ea9aaf02-52a6-46ad-b125-b5cdfd2d4a6f');
