INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8e8a97c-5a92-4e64-bac9-539ffae5c27c', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What is an ''Astronomical Unit'' (AU) commonly used in planetary astronomy?', '1 AU = 149,597,870,700 metres (~150 million km), the baseline metric for interplanetary distances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('262bb2ec-7618-4b00-ad45-8e1e8530b327', 'The average mean distance from the center of the Earth to the center of the Sun (~149.6 million km)', true, 'c8e8a97c-5a92-4e64-bac9-539ffae5c27c');
