INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5452a37f-2e68-4828-8dea-f43cdf1a0e57', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What is the boundary around a Black Hole beyond which nothing can escape the gravitational pull called?', 'The Event Horizon is the theoretical boundary threshold where escape velocity equals the speed of light.', NOW()) ON CONFLICT DO NOTHING;
