INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1136a89e-ae67-4421-b6c2-6a69551f64ac', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What is a ''SUPERNOVA'' in astronomy?', 'A supernova is a stellar explosion triggering core collapse and synthesizing heavy elements (iron, gold, uranium) across space.', NOW()) ON CONFLICT DO NOTHING;
