INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c764c743-8d49-4aba-8956-c21253a1bb5b', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'Which is the LARGEST moon in the entire solar system (even larger in diameter than the planet Mercury), orbiting Jupiter?', 'Ganymede (5,268 km diameter) is Jupiter''s largest satellite and the only moon possessing an intrinsic magnetic field.', NOW()) ON CONFLICT DO NOTHING;
