INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('284344b5-900c-4cf9-a768-5204d1484771', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What is the ''Kuiper Belt'' in the outer solar system?', 'The Kuiper Belt extends from 30 to 50 AU, harboring primordial icy planetesimals and short-period comets.', NOW()) ON CONFLICT DO NOTHING;
