INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db1ea700-7e09-4392-a799-f68d56016746', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'Which was India''s historic maiden interplanetary mission to Mars launched in 2013, making ISRO the first space agency in the world to reach Martian orbit on its very FIRST attempt?', 'ISRO''s MOM (Mangalyaan) entered Martian orbit on 24 September 2014 on its maiden attempt at record cost-efficiency.', NOW()) ON CONFLICT DO NOTHING;
