INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee456299-a47f-41e9-b47e-ec46ae3f550f', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What is the nuclear reaction that powers our Sun and all main-sequence stars in the universe, releasing enormous light and heat?', 'Proton-proton chain nuclear fusion converts 600 million tons of hydrogen into helium every second in the Sun''s core.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f968a78a-ab37-491f-bf9e-5893bb4553ea', 'Nuclear Fusion (Hydrogen nuclei fusing into Helium nuclei in the stellar core)', true, 'ee456299-a47f-41e9-b47e-ec46ae3f550f');
