INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca123852-54f4-45b6-9d7b-f36b0fe467d8', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What is the ''International Space Station'' (ISS)?', 'The ISS is a joint multinational orbital research outpost traveling at 27,600 km/h, orbiting Earth 16 times a day.', NOW()) ON CONFLICT DO NOTHING;
