INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('129ebe2e-5984-4545-b7db-15b82897b891', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What are ''Pulsars'' in astrophysics?', 'Pulsars are remnant neutron star cores spinning up to hundreds of rotations per second, sweeping radio beams past Earth.', NOW()) ON CONFLICT DO NOTHING;
