INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09c8fe75-2575-47df-a57a-6e46d7b9b4c7', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What is the ''Chandrasekhar Limit'' discovered by Indian-American Nobel Laureate Subrahmanyan Chandrasekhar?', 'The Chandrasekhar limit (M ≈ 1.44 M_☉) dictates the relativistic quantum threshold separating white dwarf stability from supernova collapse.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d445245-2034-43d8-aa18-8a00eaebead3', 'The maximum stable theoretical mass (approx. 1.44 Solar Masses) of a White Dwarf star, beyond which electron degeneracy pressure fails and the star collapses into a Neutron Star or Black Hole', true, '09c8fe75-2575-47df-a57a-6e46d7b9b4c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45707bc3-ba9e-4b91-9b29-d43a2cdf0b8a', 'The maximum speed of a rocket', false, '09c8fe75-2575-47df-a57a-6e46d7b9b4c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e9a23e4-d948-4b46-bf37-7646623468db', 'The minimum temperature of a comet', false, '09c8fe75-2575-47df-a57a-6e46d7b9b4c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5613f478-de00-4e02-93ba-b29585c828ca', 'The distance between Earth and Moon', false, '09c8fe75-2575-47df-a57a-6e46d7b9b4c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('821ac5a4-6764-4a66-b918-332ce571d30f', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'Match Column I (Cosmic Mysteries) with Column II (Astrophysical Explanations):
(a) Dark Matter        -> (i) Invisible mass (~27% of universe) inferred via gravitational lensing
(b) Dark Energy        -> (ii) Unknown force (~68% of universe) driving accelerated cosmic expansion
(c) Cosmic Inflation   -> (iii) Exponential superluminal expansion of spacetime 10⁻³⁶ s after Big Bang
(d) Gravitational Waves-> (iv) Ripples in spacetime fabric generated by colliding black holes (LIGO)', 'Dark Matter = gravitational scaffolding; Dark Energy = cosmic acceleration; Inflation = exponential early growth; Gravitational waves = spacetime ripples.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17f03a3b-e027-40e5-8ae9-002b7c00ad3e', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '821ac5a4-6764-4a66-b918-332ce571d30f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24a9e879-00cb-44db-b2e2-49761625a489', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '821ac5a4-6764-4a66-b918-332ce571d30f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a946f85f-72e8-4087-996f-91f317bc1a56', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '821ac5a4-6764-4a66-b918-332ce571d30f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb0d0b93-9891-4092-be2a-af6be8edfe60', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '821ac5a4-6764-4a66-b918-332ce571d30f');
