INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04411e55-f1ed-40c6-b24e-4ce494bee3ee', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What is the ''Habitable Zone'' (or Goldilocks Zone) around a host star in astrophysics?', 'Circumstellar Habitable Zone: stellar radiative equilibrium permitting liquid water (0°C to 100°C) on rocky exoplanets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40b10348-0a3d-4b2c-a4d8-184e33afd401', 'The orbital sweet-spot distance from a star where surface temperatures permit LIQUID WATER to exist persistently on a rocky planet''s surface', true, '04411e55-f1ed-40c6-b24e-4ce494bee3ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f55c934-119a-4b45-8baa-d288b9d0997c', 'A region with pure gold soil', false, '04411e55-f1ed-40c6-b24e-4ce494bee3ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1acfc4b3-7f16-47a4-b8b6-b099dae12203', 'A region inside a black hole', false, '04411e55-f1ed-40c6-b24e-4ce494bee3ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6097c65-6ebf-4a37-9d8a-4559533a0afd', 'The space inside the Sun''s core', false, '04411e55-f1ed-40c6-b24e-4ce494bee3ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('055a2c37-f701-485e-bd3c-5484c7a32683', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What was the landmark breakthrough achieved by the Event Horizon Telescope (EHT) collaboration in 2019?', 'The EHT linked radio telescopes globally via VLBI, capturing the first direct shadow of the 6.5-billion-solar-mass black hole in M87*.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('622409be-c9fd-4489-8c3a-10811d59e624', 'Capturing the world''s FIRST DIRECT SHADOW IMAGE of a Supermassive Black Hole (in galaxy M87)', true, '055a2c37-f701-485e-bd3c-5484c7a32683');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('791d56fa-8ca9-4854-9c84-9534141d0c6e', 'Landing humans on Jupiter', false, '055a2c37-f701-485e-bd3c-5484c7a32683');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b828417f-58a8-4f54-a67d-66915c39da75', 'Travelling faster than the speed of light', false, '055a2c37-f701-485e-bd3c-5484c7a32683');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c7e7bda-b902-448b-8de2-7ffca55c3553', 'Finding alien cities on Mars', false, '055a2c37-f701-485e-bd3c-5484c7a32683');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad87e62d-5af7-4f8a-8e4a-4bf81990dfe9', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'Consider four space milestones achieved by India''s ISRO:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05918748-1582-492d-8bbe-224758294f4f', 'Indigenous, frugal engineering excellence and world-leading deep-space exploration capabilities at unparalleled cost-efficiency', true, 'ad87e62d-5af7-4f8a-8e4a-4bf81990dfe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62ded8d9-cab7-4301-88a5-3eddec1bdfaa', 'Total reliance on foreign imported rockets', false, 'ad87e62d-5af7-4f8a-8e4a-4bf81990dfe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50d0c51a-a717-49e4-963a-d55ab9e005ef', 'Focusing only on entertainment satellites', false, 'ad87e62d-5af7-4f8a-8e4a-4bf81990dfe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('435338a8-4ec0-4107-b03a-1f39c02ca530', 'Building space colonies on Venus', false, 'ad87e62d-5af7-4f8a-8e4a-4bf81990dfe9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b6a3dae-0afb-4703-8013-89de5ae10048', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What is ''Gravitational Lensing'' predicted by Albert Einstein''s General Relativity?', 'General Relativity: massive energy densities curve spacetime geodesics, bending and magnifying background electromagnetic photons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('021c13a8-b48a-4318-9ea9-b8aee4b50a11', 'Massive celestial objects (like galaxy clusters) warp the fabric of spacetime around them, bending the path of light from background objects like a giant cosmic lens', true, '3b6a3dae-0afb-4703-8013-89de5ae10048');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f96d2875-9035-4252-9431-4dd2cb4678c1', 'Looking at stars through a pair of reading glasses', false, '3b6a3dae-0afb-4703-8013-89de5ae10048');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8726f0a-9780-49b8-b426-37cfdc6415de', 'Gravity making planets shine brighter', false, '3b6a3dae-0afb-4703-8013-89de5ae10048');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28b30516-274f-4dc0-ab77-249bcf2697ff', 'Stars turning into glass lenses', false, '3b6a3dae-0afb-4703-8013-89de5ae10048');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d25956a-aff0-4d49-b27b-d6424c6c95ac', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What is the theoretical maximum velocity limit for the propagation of any physical information, matter, or light across the universe?', 'Special Relativity: c = 299,792,458 m/s represents the universal invariant speed limit of causality.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a4403b1-1a2e-43fd-b213-dae7ae4503a8', '299,792,458 metres per second (approx. 300,000 km/s - The Speed of Light ''c'')', true, '4d25956a-aff0-4d49-b27b-d6424c6c95ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ee6bb9b-e09c-4e29-a2fc-e556408e4df7', '1,000 km/s', false, '4d25956a-aff0-4d49-b27b-d6424c6c95ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c83db23-c1e8-4256-b35b-cb982071e3dd', '100,000 km/s', false, '4d25956a-aff0-4d49-b27b-d6424c6c95ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a0dee5d-813b-4265-af28-00758db952ab', 'Infinite speed', false, '4d25956a-aff0-4d49-b27b-d6424c6c95ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f13c676f-b0f4-4857-afbd-7b33fee83c9c', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'Why do astronauts experience weightlessness inside the International Space Station (ISS) in Low Earth Orbit?', 'Earth''s gravity at 400 km is ~90% of sea level; apparent microgravity results from continuous orbital free-fall.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d06e04a-8e96-45bc-89cc-a9a55e30142a', 'The ISS and astronauts are in a continuous, perpetual state of FREE FALL around the Earth (falling forward at orbital speed equal to Earth''s curvature)', true, 'f13c676f-b0f4-4857-afbd-7b33fee83c9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ee1f0de-53b0-44cc-ad3b-5b1bc782aa96', 'Because there is zero gravity in orbit', false, 'f13c676f-b0f4-4857-afbd-7b33fee83c9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2b18524-181a-4d91-b026-5afe626b353e', 'Because the ISS has an anti-gravity engine', false, 'f13c676f-b0f4-4857-afbd-7b33fee83c9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7a7f44b-18b9-43cc-a1fd-d4a0368cb477', 'Because Earth''s gravity stops at 100 km', false, 'f13c676f-b0f4-4857-afbd-7b33fee83c9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d898626b-097f-4814-988e-e962e5f30f39', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What ultimate cosmic perspective is illuminated by modern Space Science, Astronomy, and the Universe?', 'Astrophysics reveals our cosmological kinship: nucleosynthesis in dying stars created the biogenic elements (C, N, O, Fe) composing human life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efbef422-5ede-48c2-a263-2f8ac46b9563', 'Human beings are composed of ''stardust'' (elements forged inside exploding ancient stars), inhabiting a fragile ''Pale Blue Dot'' in a vast, majestic 13.8-billion-year-old cosmic web', true, 'd898626b-097f-4814-988e-e962e5f30f39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('131b2853-ace0-4dad-9182-011c4d9a26c0', 'Earth is the absolute geometric center of the universe', false, 'd898626b-097f-4814-988e-e962e5f30f39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4358eeef-8015-4faa-95e3-8e34538e2aec', 'Space exploration has revealed all secrets of the universe', false, 'd898626b-097f-4814-988e-e962e5f30f39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6883487-75b4-480e-b864-5b70e18b61f0', 'The universe will stop existing tomorrow', false, 'd898626b-097f-4814-988e-e962e5f30f39');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('933c1d0c-a347-41cd-aae6-9c734e0aa5d5', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'Between the 8th and 18th centuries, what two main categories of structural buildings were constructed by kings and their officers?', 'Medieval monument architecture comprised royal monumental structures (forts, tombs, palaces) and public civic infrastructure (tanks, stepwells, mosques, bazaars).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f64e3262-6f6d-414a-af73-08deca664d92', '1. Forts, palaces, and royal tombs (safe, protected places of grand rest) ; 2. Temples, mosques, tanks, wells, caravan serais, and bazaars (structures meant for public use)', true, '933c1d0c-a347-41cd-aae6-9c734e0aa5d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('217521c8-0f01-44c2-bd9f-7f044c54fe08', 'Only wooden huts and tents', false, '933c1d0c-a347-41cd-aae6-9c734e0aa5d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ad09a90-e550-48ac-8d3e-4d17fe671345', 'Only stone factories', false, '933c1d0c-a347-41cd-aae6-9c734e0aa5d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db6e7db8-0395-4069-8d1d-e22f0653dd4b', 'Only bridges over oceans', false, '933c1d0c-a347-41cd-aae6-9c734e0aa5d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('309aef61-b9b6-4cce-8d64-9f4924623c01', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What was the traditional Indian architectural style where roofs, doors, and windows were made by placing a horizontal beam across two vertical pillars called?', 'Trabeate/Corbelled architecture utilizes post-and-lintel structural beams across vertical support columns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4212b4f9-ffb2-479a-b03d-3c825113891b', 'Trabeate (or Corbelled) Architectural Style', true, '309aef61-b9b6-4cce-8d64-9f4924623c01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a2a91ce-3f7d-4225-bf82-e318fe9edec8', 'Arcuate Architectural Style', false, '309aef61-b9b6-4cce-8d64-9f4924623c01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5e1b1c3-edb2-4445-8dd2-1d3b40f4ed24', 'Gothic Style', false, '309aef61-b9b6-4cce-8d64-9f4924623c01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2671ccb1-f676-49e4-89ec-412b1bc1251c', 'Doric Style', false, '309aef61-b9b6-4cce-8d64-9f4924623c01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd49f0e6-24ac-4df3-9a1d-95c5b6a8dfdf', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'From the 12th century, what new technological architectural style emerged where the weight of the superstructure above doors and windows was carried by true circular ARCHES with a central Keystone?', 'Arcuate architecture distributes structural loads through true compressive voussoir arches stabilized by a central keystone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20266876-2742-42bd-83fe-ef570af26dce', 'Arcuate Architectural Style', true, 'bd49f0e6-24ac-4df3-9a1d-95c5b6a8dfdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c7165bc-1ee7-4619-9759-819543e07cbc', 'Trabeate Style', false, 'bd49f0e6-24ac-4df3-9a1d-95c5b6a8dfdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e867c433-b179-41c8-895a-9a91e89ca66a', 'Corbelled Style', false, 'bd49f0e6-24ac-4df3-9a1d-95c5b6a8dfdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('950c1cd5-8df7-41ec-b05a-be70599fec80', 'Cave Rock Style', false, 'bd49f0e6-24ac-4df3-9a1d-95c5b6a8dfdf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f4acb3d-c670-40e2-9a47-9b3b21a14b8b', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What high-quality cementing material mixed with stone chips became increasingly used in 12th-century large-scale construction, hardening rapidly into stone-like mortar?', 'Limestone cement mortar set rapidly with great tensile resilience, facilitating massive domes and arches.', NOW()) ON CONFLICT DO NOTHING;
