INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3519f8f9-ed30-44cf-916b-26e723465f44', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'Which magnificent Shiva temple with the tallest Shikhara of its time was constructed at Thanjavur by the Chola King Rajaraja I?', 'Brihadisvara Temple (Rajarajeshvara) at Thanjavur featured an 80-tonne granite monolithic shikhara capstone erected c. 1010 CE.', NOW()) ON CONFLICT DO NOTHING;
