INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('166ad736-3c57-4d89-b0f5-477ba69417c8', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'Which ornate Shiva temple with a series of graded rising Shikharas was constructed in 999 CE at Khajuraho by the Chandela King Dhangadeva?', 'The Kandariya Mahadeva temple in Khajuraho exemplifies Nagara temple architecture with soaring fractal shikhara spires.', NOW()) ON CONFLICT DO NOTHING;
