INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2a4162a-b70a-4125-a5c0-cfec4231282b', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What is a large traditional multi-storied stepped well with underground descending flights of stone stairs to reach the water reservoir called?', 'Baolis/Vavs are sub-surface stepped wells engineered for arid water storage, subterranean cooling, and public respite.', NOW()) ON CONFLICT DO NOTHING;
