INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a340a39-ff86-4585-9084-1c0c07c9d21e', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What is the famous grand stepped reservoir built by Sultan Iltutmish just outside Delhi (Dehli-i Kuhna) for public drinking water called?', 'Iltutmish won universal public acclaim for excavating Hauz-i Sultani (the Royal Reservoir) for Delhi citizens.', NOW()) ON CONFLICT DO NOTHING;
