INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4982eb51-6b25-4d4c-b684-42711ae9f09f', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What is the fine art technique of inlaying polished colored stones (like lapis lazuli, onyx, and jasper) into marble depressions to create floral patterns called?', 'Pietra Dura (Parchin Kari) inlays semi-precious gem stones into carved marble cavities to create radiant natural motifs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afa17c2d-3370-439c-a18a-382c31b8a3a6', 'Pietra Dura (Parchin Kari)', true, '4982eb51-6b25-4d4c-b684-42711ae9f09f');
