INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7ecf24f-21ac-40db-ba7b-662005cac89a', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What was the formal garden layout favored by Mughal emperors, divided symmetrically into four equal quadrants by artificial water channels, called?', 'Chahar Bagh is the quadripartite symmetrical garden layout divided by axial intersecting water rills.', NOW()) ON CONFLICT DO NOTHING;
