INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e172bcfd-a664-45a2-9a6b-5d30f1c58ee0', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What holy central Sikh shrine and stepped Amrit Sarovar tank was constructed at Amritsar under Guru Arjan Dev in the late 16th century?', 'Guru Arjan Dev constructed the Harmandir Sahib in the center of the holy Amrit Sarovar lake in Amritsar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fec8b6f-538d-4873-a8d8-4df4c12d6810', 'Harmandir Sahib (The Golden Temple)', true, 'e172bcfd-a664-45a2-9a6b-5d30f1c58ee0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93989a8d-547e-4abf-b4cc-4fbb0e6b1f1a', 'Bangla Sahib', false, 'e172bcfd-a664-45a2-9a6b-5d30f1c58ee0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63b83ed7-48a6-477b-a2b9-155840e3ad6a', 'Sis Ganj Sahib', false, 'e172bcfd-a664-45a2-9a6b-5d30f1c58ee0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aae0042-5bfd-4d8d-b664-a130dd09d3e3', 'Patna Sahib', false, 'e172bcfd-a664-45a2-9a6b-5d30f1c58ee0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f817595-cd47-4ae2-8e71-45b9eaf6bdd0', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'Who built the monumental 73-metre high sandstone Qutb Minar tower in Delhi, initiating its construction around 1199 CE?', 'Qutbuddin Aibak built the base balcony of Qutb Minar in 1199; Iltutmish added three upper storeys c. 1220.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d6a4ab9-e031-4ba9-bc1e-4ecb8ec27c63', 'Qutbuddin Aibak (completed by Iltutmish and repaired by Firuz Tughluq)', true, '8f817595-cd47-4ae2-8e71-45b9eaf6bdd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('787069b6-6315-4311-885c-0aa26bda5bd8', 'Alauddin Khalji', false, '8f817595-cd47-4ae2-8e71-45b9eaf6bdd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b3ef42e-9e42-49fc-9ab7-c18bdf0e76ff', 'Babur', false, '8f817595-cd47-4ae2-8e71-45b9eaf6bdd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f415176-b255-457b-ad60-d6a2c2e1d381', 'Shah Jahan', false, '8f817595-cd47-4ae2-8e71-45b9eaf6bdd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3321257a-bc72-44bf-a2bd-40c08f16fe44', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'How was the massive 90-tonne single granite stone placed atop the 60-metre high Shikhara of the Rajarajeshvara Temple at Thanjavur without modern cranes?', 'Chola master engineers constructed a 4-km earthen inclined gradient from the village of Charupallam to haul the 90-ton monolithic cupola.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af523bb4-e8c0-4d2a-83b1-5fe0211af553', 'Architects built an inclined earth ramp (over 4 km long) starting from a nearby village, rolling the heavy stone all the way up on log rollers to the temple pinnacle', true, '3321257a-bc72-44bf-a2bd-40c08f16fe44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0095ade0-ae1c-4131-9ff6-39057b732d05', 'They pulled it with a giant rope from the clouds', false, '3321257a-bc72-44bf-a2bd-40c08f16fe44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce3ebcb6-66b8-4423-912c-c062bf99eeb1', 'They dropped it from an airplane', false, '3321257a-bc72-44bf-a2bd-40c08f16fe44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('773a51fc-f014-4c62-8270-bc3752d76b51', 'The stone was made of foam', false, '3321257a-bc72-44bf-a2bd-40c08f16fe44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ac053ca-97da-4480-9f16-091e7b2be806', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'Why did medieval kings target, desecrate, and loot the main structural temples of rival kingdoms during military invasions?', 'Monumental temples embodied royal majesty and divine charisma; their targeted destruction symbolized the total subjugation of the rival state.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7be3aa61-8c94-4e82-9274-f18df6775f56', 'Temples were supreme symbols of a king''s political power, imperial wealth, and divine legitimacy; destroying the rival''s temple proclaimed total conquest and humiliated the defeated dynasty', true, '6ac053ca-97da-4480-9f16-091e7b2be806');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5671be4-4620-4798-b70c-e67bd5761f30', 'Because rival soldiers hid inside temples', false, '6ac053ca-97da-4480-9f16-091e7b2be806');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50f62da6-010d-43ba-afb0-a9c01062a6a5', 'Because temples were made of wood', false, '6ac053ca-97da-4480-9f16-091e7b2be806');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87d049da-671a-42e9-a9e0-ff6de8fba22f', 'Because kings wanted to build roads over them', false, '6ac053ca-97da-4480-9f16-091e7b2be806');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc4f83f4-95c0-4504-b6a1-48de2cc1226e', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'When the 9th-century Pandyan King Shrimara Shrivallabha invaded Sri Lanka and defeated King Sena I, what precious Buddhist relic did he carry away?', 'The Mahavamsa chronicles that Shrimara seized the golden Buddha image from the Jewel Palace, which Sena II later invaded Madurai to recover.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('421a9cef-199b-4667-a5b1-2f1ac98a5b17', 'The colossal jewel-encrusted Golden Statue of the Buddha from the Jewel Palace and all golden images from monasteries', true, 'bc4f83f4-95c0-4504-b6a1-48de2cc1226e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0de3e838-ef44-40c5-8af9-b27814142aab', 'A silver ship', false, 'bc4f83f4-95c0-4504-b6a1-48de2cc1226e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef48bab6-8ff8-446e-8738-fc3694ddced0', 'A sacred wooden chariot', false, 'bc4f83f4-95c0-4504-b6a1-48de2cc1226e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ead9d63-d279-4a1d-abdb-ce6d910dea3c', 'A bronze bell only', false, 'bc4f83f4-95c0-4504-b6a1-48de2cc1226e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea3c7156-2e33-40f6-b252-992f8d896711', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'Why did the 11th-century Chola King Rajendra I build a magnificent Shiva temple in his capital and fill it with captured statues from defeated rulers (Chalukyas, Palas, Kalingas)?', 'Rajendra I transformed his imperial temple into a pan-subcontinental trophy pavilion housing deities seized from vanquished rivals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55cd586d-0124-4acd-88a4-7e6dc836d5e5', 'To celebrate imperial pan-Indian hegemony by displaying captured sacred trophies (Ganesha, Durga, Nandi, Bhairava, Kali) from all four corners of the subcontinent', true, 'ea3c7156-2e33-40f6-b252-992f8d896711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec334b9b-70de-494c-8f5f-1bc543b30fea', 'Because he did not have sculptors in his kingdom', false, 'ea3c7156-2e33-40f6-b252-992f8d896711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b13e2c3-ce76-4907-8a6d-c77f0f8141f6', 'To sell them in foreign markets', false, 'ea3c7156-2e33-40f6-b252-992f8d896711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd391218-851d-474b-8e64-636d4e06ffcc', 'To hide them from his people', false, 'ea3c7156-2e33-40f6-b252-992f8d896711');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('283dbf73-e19d-4dd5-8765-35a4407876d0', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'In Shah Jahan''s newly constructed capital city of Shahjahanabad (Delhi), where was the grand imperial Red Fort situated along the river Yamuna?', 'Shah Jahan adapted the riverfront garden topology, positioning the imperial palace directly on the Yamuna to control riverine access.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bba1a7b5-0cd1-4dcd-a240-4decaecfa678', 'Directly overlooking the riverbank of Yamuna in a ''River-Front Garden'' layout, with only select favored princes (like Dara Shikoh) granted river access', true, '283dbf73-e19d-4dd5-8765-35a4407876d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fd22d07-86a9-42f0-b118-52a99c94d275', 'In the middle of a desert away from water', false, '283dbf73-e19d-4dd5-8765-35a4407876d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('934ff47f-1cdc-4335-8b5b-dc49ea5b384f', 'On top of the Himalayas', false, '283dbf73-e19d-4dd5-8765-35a4407876d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d967b843-abf1-4046-b4e0-125a06eb50fc', 'Inside an underground cave', false, '283dbf73-e19d-4dd5-8765-35a4407876d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f4ceeb3-b567-45dd-b42c-87aafdbf2b03', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What architectural connection did Shah Jahan create between the Emperor''s Throne (Diwan-i Aam) and divine justice in the Red Fort at Delhi?', 'Pietra dura inlays of Orpheus taming beasts behind Shah Jahan''s jharokha symbolized royal justice reconciling fierce discord into harmonious peace.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b331b6e1-2b06-4ccd-9dd9-c9032116d61c', 'Behind the throne was a series of Pietra Dura panels depicting the Greek god Orpheus playing his lute (taming savage beasts), symbolizing that the King''s justice treats the high and low as equals in peace', true, '4f4ceeb3-b567-45dd-b42c-87aafdbf2b03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5971d42a-7d6b-4722-84e9-17fee228e0ad', 'The throne was carved from a single diamond', false, '4f4ceeb3-b567-45dd-b42c-87aafdbf2b03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8861afaa-b4f5-45c1-be87-4a33ac27a016', 'The throne had cannons pointed at the crowd', false, '4f4ceeb3-b567-45dd-b42c-87aafdbf2b03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a44c3ad-7112-4d14-80e3-77274221476a', 'The throne was suspended in mid-air with magnets', false, '4f4ceeb3-b567-45dd-b42c-87aafdbf2b03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0eca9e0e-5e9a-4811-a03c-7f3ed9f9dd20', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What is the ''Bangla Dome'' / thatched roof architectural adaptation adopted by Mughal emperors into their stone palace architecture?', 'Mughal architects adapted regional Bengali vaulted hut profiles (''Bangla dome'') into imperial marble and sandstone pavilions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('156e7449-4508-4110-b7d5-f769999069e5', 'A graceful curved roof modeled on the traditional curved bamboo thatched roofs of Bengal huts, used in Agra Fort and Fatehpur Sikri', true, '0eca9e0e-5e9a-4811-a03c-7f3ed9f9dd20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f46dd7bf-a68b-4b80-a1a5-0eb37db93f50', 'A flat stone roof', false, '0eca9e0e-5e9a-4811-a03c-7f3ed9f9dd20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a4cad25-ba76-480c-8715-9579267b6e68', 'A pyramid made of glass', false, '0eca9e0e-5e9a-4811-a03c-7f3ed9f9dd20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e94713c0-f589-4048-8334-e9dd72970a2d', 'A tower made of metal', false, '0eca9e0e-5e9a-4811-a03c-7f3ed9f9dd20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c46592e7-c094-4ccc-abf1-ad9ec6148dd9', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'How did architectural styles cross-pollinate across regions during the 16th–17th centuries (e.g. temples in Vrindavan near Mathura)?', 'Cross-cultural architectural synthesis: Govind Deva temple''s ribbed vaulting in red sandstone mirrored Akbar''s Fatehpur Sikri palace engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72bede8b-c155-42fb-a19f-6ce2a3628d23', 'Temples in Vrindavan (like the Govind Deva temple, 1590) featured high intersecting ceiling arches constructed in architectural styles identical to Mughal palaces in Fatehpur Sikri', true, 'c46592e7-c094-4ccc-abf1-ad9ec6148dd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d3a456c-ca44-4698-8224-1491f1982c55', 'Temples were built in Greek and Roman style', false, 'c46592e7-c094-4ccc-abf1-ad9ec6148dd9');
