INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac58991b-f3b1-4d81-93da-3125c1c20b2d', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Garbhagriha'' in a classical Hindu temple?', 'The Garbhagriha (womb-chamber) is the central, sacred nucleus of a Hindu temple enshrining the principal consecrated deity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed8e0ad7-57fd-4f97-8e9a-d11519ebc4ed', 'The innermost sacred sanctum sanctorum where the main deity''s idol / murti was installed and consecrated for ritual worship', true, 'ac58991b-f3b1-4d81-93da-3125c1c20b2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e006f1a6-2cb7-4812-a83f-f72fa917cb31', 'The kitchen of the temple', false, 'ac58991b-f3b1-4d81-93da-3125c1c20b2d');
