INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('757e03cf-88b8-4f90-b8bf-38513a75cbb7', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Mandapa'' in classical temple architecture?', 'The Mandapa is the pillared congregational hall preceding the garbhagriha in Nagara and Dravida temple layouts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a9dd5f1-1685-433c-9b5a-c61db061c0f6', 'The pillared assembly hall where devotees gathered, sacred dances were performed, and religious rituals were conducted', true, '757e03cf-88b8-4f90-b8bf-38513a75cbb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98da3c6a-4af2-461e-a1dd-ccbcadd84b0c', 'The main tower over the deity', false, '757e03cf-88b8-4f90-b8bf-38513a75cbb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62bd0ace-c2f6-4d96-9c0d-b35db8371dd0', 'The water well outside', false, '757e03cf-88b8-4f90-b8bf-38513a75cbb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56355cba-1a2e-4c7b-bb22-d439a42c7456', 'The outer boundary wall', false, '757e03cf-88b8-4f90-b8bf-38513a75cbb7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68b98dc5-79e0-4202-b9f1-5af804f4aae7', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Shikhara'' (or Vimana in South India)?', 'The Shikhara/Vimana is the towering architectural mountain spire rising majestically above the central sanctum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebcc1b60-21d2-4a06-bdf5-8e31c809d342', 'The towering, rising conical superstructure/spire constructed directly over the Garbhagriha sanctum sanctorum', true, '68b98dc5-79e0-4202-b9f1-5af804f4aae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75637373-1363-4f2a-b683-c44022fa422b', 'The temple entrance gate', false, '68b98dc5-79e0-4202-b9f1-5af804f4aae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cda3a6a5-11c0-4859-a1a8-c0c12c26db85', 'The water tank', false, '68b98dc5-79e0-4202-b9f1-5af804f4aae7');
