INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98b4be96-40c4-4198-92ee-a3a67006d0cf', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Gopuram'' in South Indian Dravida temple complexes (such as Madurai and Thanjavur)?', 'Gopurams are monumental, multi-tiered sculpted gateway towers dominating the perimeter walls of Dravidian temple cities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1897a32e-c519-4887-bdb7-92a33fe90db7', 'The towering, colossal, richly sculpted monumental entrance gateway leading into the temple enclosure', true, '98b4be96-40c4-4198-92ee-a3a67006d0cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fba8397-1794-4c0c-8a41-5192825655bd', 'The inner room of the priest', false, '98b4be96-40c4-4198-92ee-a3a67006d0cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3502fcd-c5e0-4c6e-bb2f-4ff3e22c12a8', 'The stone pillar for tying horses', false, '98b4be96-40c4-4198-92ee-a3a67006d0cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e282728-d78b-4a1b-bb8f-7274bb350d5b', 'The kitchen for preparing prasad', false, '98b4be96-40c4-4198-92ee-a3a67006d0cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16f2c916-f05a-4d81-ac72-3d67520477ff', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What is the famous ''Rani ki Vav'' (The Queen''s Stepwell) in Patan, Gujarat, recognized as a UNESCO World Heritage site?', 'Rani ki Vav (built by Queen Udayamati c. 1063 CE) is a 7-tiered inverted temple stepwell celebrating subterranean sacred hydraulics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3474afac-2afe-4b2f-bacf-77943a46b6b1', 'An intricately carved seven-level inverted underground stepwell temple adorned with over 500 principal sculptures of Vishnu and his avatars', true, '16f2c916-f05a-4d81-ac72-3d67520477ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a192fa0a-eaba-4586-97e6-b0a31a75b922', 'A modern water dam', false, '16f2c916-f05a-4d81-ac72-3d67520477ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cd1b943-ba89-4271-9192-93b7e220e14c', 'A floating boat', false, '16f2c916-f05a-4d81-ac72-3d67520477ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0ccae0f-a630-4be1-bf98-dd112d1c9c7b', 'A royal palace on a mountain', false, '16f2c916-f05a-4d81-ac72-3d67520477ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64901990-5cd0-4e74-a3c9-13ad3e283898', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What is the ''Pishtaq'' in Indo-Islamic architecture?', 'A Pishtaq is a monumental projecting formal portal framing a central vaulted iwan arch.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b733047f-c53e-4069-bf74-faaa9f46dca8', 'The towering, majestic monumental arched gateway framing the entrance of a mosque, tomb, or palace (such as at Humayun''s Tomb and Taj Mahal)', true, '64901990-5cd0-4e74-a3c9-13ad3e283898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1df058cd-2c4b-4517-b8fc-e267ed968491', 'The minaret staircase', false, '64901990-5cd0-4e74-a3c9-13ad3e283898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ccab197-1ccc-4edd-8e80-d9d96f224b01', 'The floor carpet', false, '64901990-5cd0-4e74-a3c9-13ad3e283898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ede28b92-02b3-4433-a536-d04c66cd39d3', 'The water fountain', false, '64901990-5cd0-4e74-a3c9-13ad3e283898');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4fd324e1-68ea-440c-911a-c42fe7ee1811', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Hasht Bihisht'' (Eight Paradises) architectural floor plan introduced during Mughal tomb construction (e.g. Humayun''s Tomb)?', 'Hasht Bihisht is an octagonal radial architectural plan featuring 8 perimeter chambers radiating around a central domed chamber.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59204064-4a84-493d-8dfe-16c8cb907893', 'A central octagonal hall surrounded by eight interconnected rooms on two levels, symbolizing the eight heavenly paradises of Islamic cosmology', true, '4fd324e1-68ea-440c-911a-c42fe7ee1811');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('559a0d8d-9f9c-4b4a-9815-786e2b566b8a', 'A building with eight doors and no windows', false, '4fd324e1-68ea-440c-911a-c42fe7ee1811');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd495ba2-27a3-4870-994f-bc8e6cad8446', 'A garden with eight flowers', false, '4fd324e1-68ea-440c-911a-c42fe7ee1811');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44557401-7c3c-47af-9764-286fb286fa2d', 'A fortress with eight cannons', false, '4fd324e1-68ea-440c-911a-c42fe7ee1811');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06c93f3c-5fbe-43b6-90f7-e3800718d485', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the architectural purpose of constructing magnificent public water reservoirs (such as Hauz Khas and Baolis) by medieval monarchs?', 'Public hydraulic endowments (hauz, baolis, tanks) fused utilitarian water security with the moral prestige of benevolent kingship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b035f4f-1ad1-49e6-89f6-6e0b76a68688', 'To ensure reliable water security for urban citizens, while earning universal moral praise, religious merit, and cementing benevolent royal legitimacy', true, '06c93f3c-5fbe-43b6-90f7-e3800718d485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce2e16ab-69e8-4b3f-a6c9-82f4bf363264', 'To breed exotic sharks', false, '06c93f3c-5fbe-43b6-90f7-e3800718d485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ff29e73-087d-4438-b19c-3e06fde74c9e', 'To hold boat races every day', false, '06c93f3c-5fbe-43b6-90f7-e3800718d485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10b1de8b-bb39-4a99-9ec7-dd5efaae1950', 'To flood the city in times of war', false, '06c93f3c-5fbe-43b6-90f7-e3800718d485');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be53f4ec-da4f-4a4b-880e-99e08df75423', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea615c8a-8f87-424f-bb6a-0e26df24c98e', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'be53f4ec-da4f-4a4b-880e-99e08df75423');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9a697a7-9a7a-4449-904f-9b36169d6e44', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'be53f4ec-da4f-4a4b-880e-99e08df75423');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c644d8e5-8725-4773-a41a-87cccba6b65a', '(A) is true, but (R) is false.', false, 'be53f4ec-da4f-4a4b-880e-99e08df75423');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e81a9b4-ab5e-424e-b59f-24ae3465047b', '(A) is false, but (R) is true.', false, 'be53f4ec-da4f-4a4b-880e-99e08df75423');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63c85b22-d017-4369-a22f-d42b58b9860a', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Spot the IMPOSTER in the following architectural styles and their structural features:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bf2fa4e-5324-4bf6-8534-b54d44c0f3c5', 'Style 1', false, '63c85b22-d017-4369-a22f-d42b58b9860a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de1e7ce8-5a14-4f5e-84d0-379281543253', 'Style 2', false, '63c85b22-d017-4369-a22f-d42b58b9860a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('927d2b45-4256-461e-b3da-c4c3d72cb765', 'Style 3', false, '63c85b22-d017-4369-a22f-d42b58b9860a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5580f0b4-cf83-4659-a768-3ebbe6461dbd', 'Style 4 (Corbelled arches used stepped horizontal cantilevered stone courses, NOT modern steel cables)', true, '63c85b22-d017-4369-a22f-d42b58b9860a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b540c0f-e8e6-42af-8bca-df973db2005f', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Analyze the engineering transition from Humayun''s Tomb (1570) to the Taj Mahal (1648):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00cd61b3-1775-4543-b223-bd63d7c6394f', 'Evolution from red sandstone with marble trim to pure pristine Makrana white marble, perfected double-dome engineering with slender bulbous silhouettes, elevated riverfront garden placement, and flawless bilateral symmetry', true, '0b540c0f-e8e6-42af-8bca-df973db2005f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be70632b-8955-434d-b284-6b44be3959e8', 'Transition from stone to brick and mud', false, '0b540c0f-e8e6-42af-8bca-df973db2005f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0171d818-d642-4cad-9af4-25b231b1c96c', 'Replacement of gardens with stone courtyards', false, '0b540c0f-e8e6-42af-8bca-df973db2005f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc4382bb-7cc3-41cc-b89b-a24025939465', 'Abandonment of domes for flat wooden roofs', false, '0b540c0f-e8e6-42af-8bca-df973db2005f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0979413-bf43-421c-aeac-885d13e4b92a', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Match Column I (Monumental Structures) with Column II (Patron King / Dynasty & Location):
(a) Kandariya Mahadeva Temple -> (i) Chandela King Dhangadeva (Khajuraho, MP)
(b) Brihadisvara Temple        -> (ii) Chola King Rajaraja I (Thanjavur, Tamil Nadu)
(c) Qutb Minar Balconies      -> (iii) Qutbuddin Aibak & Iltutmish (Delhi)
(d) Red Fort Throne & Diwan   -> (iv) Mughal Emperor Shah Jahan (Shahjahanabad / Delhi)', 'Exact attribution: Kandariya = Chandela Dhangadeva; Brihadisvara = Chola Rajaraja; Qutb Minar = Aibak/Iltutmish; Red Fort = Shah Jahan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fa78ea0-3248-4843-854d-6ada32d42091', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'd0979413-bf43-421c-aeac-885d13e4b92a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10b10eac-42bf-4a41-9d74-9335b661f5e2', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'd0979413-bf43-421c-aeac-885d13e4b92a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b137996e-9afb-4a3c-81bf-8d4d28090bc9', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'd0979413-bf43-421c-aeac-885d13e4b92a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f20e6182-e32d-4287-aa6e-e081ccccdb7c', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'd0979413-bf43-421c-aeac-885d13e4b92a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6c3bb6e-bc8f-4549-8f34-73f819704f67', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Read the statements regarding hydraulic architecture in medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21cc8a9d-c291-4af0-9cf1-abbb6438a385', 'Statements 1 and 2 only', true, 'a6c3bb6e-bc8f-4549-8f34-73f819704f67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b258d9d8-8547-49b7-8253-fe933f2caabd', 'Statements 2 and 3 only', false, 'a6c3bb6e-bc8f-4549-8f34-73f819704f67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c217558-2baf-4bb2-9a5b-b52385d6a2a6', 'Statements 1 and 3 only', false, 'a6c3bb6e-bc8f-4549-8f34-73f819704f67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9b5c201-4bc7-42ff-9697-7d251f9e4958', 'All Statements 1, 2, and 3', false, 'a6c3bb6e-bc8f-4549-8f34-73f819704f67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('578142c8-7d09-4bb8-a181-f070a62fb32c', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'How did the ''Double Dome'' architectural innovation (seen in Humayun''s Tomb and the Taj Mahal) solve a complex structural and aesthetic engineering challenge?', 'Double-dome engineering decoupled exterior monumental elevation from interior volumetric proportions, preventing cavernous acoustic distortion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bea00722-150b-4aa5-9d02-0bd57b4ecb26', 'The outer dome provided an imposing, soaring silhouette visible from miles away on the exterior, while the lower inner dome created a proportionate, intimate ceiling inside the central tomb chamber', true, '578142c8-7d09-4bb8-a181-f070a62fb32c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd8719af-cade-4afc-8bb9-d77fb95811eb', 'It trapped hot air between two domes to heat the tomb', false, '578142c8-7d09-4bb8-a181-f070a62fb32c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82ebb21a-be1d-45e8-ab57-eed14be18821', 'It was built to store water between the domes', false, '578142c8-7d09-4bb8-a181-f070a62fb32c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f44b38df-6fd8-4559-a280-f76237810b68', 'It was made of glass to let rain in', false, '578142c8-7d09-4bb8-a181-f070a62fb32c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('455e17c7-2dcd-4fa3-9183-e569e75b3ea7', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Why did Akbar''s palace complex at Fatehpur Sikri incorporate extensive architectural traditions from Gujarat and Malwa (e.g. Jodha Bai''s palace)?', 'Akbar''s Fatehpur Sikri celebrated imperial syncretism by integrating Gujarati carved timber brackets, jalis, and Malwa torana motifs into sandstone palaces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6767f6db-6c3e-4fc6-9f13-2b3889206028', 'Akbar deliberately employed master stone craftsmen from newly conquered Gujarat and Malwa, creating an eclectic, syncretic architectural style that visually united his composite empire', true, '455e17c7-2dcd-4fa3-9183-e569e75b3ea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc261933-1526-43bf-a402-06ab13701564', 'Because there were no stone carvers in Agra', false, '455e17c7-2dcd-4fa3-9183-e569e75b3ea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65a64bad-1437-4d1d-b71f-4f841be14f21', 'Because Malwa was located in Europe', false, '455e17c7-2dcd-4fa3-9183-e569e75b3ea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ef5f13c-1ecb-4c0f-a496-905adbb42af6', 'Because Akbar wanted to demolish Fatehpur Sikri', false, '455e17c7-2dcd-4fa3-9183-e569e75b3ea7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fd26c03-c986-405d-9ea6-7288be51d858', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'What is the structural significance of the ''Keystone'' in true Arcuate architecture?', 'The keystone is the critical central crown voussoir of a stone arch that locks the masonry in self-supporting compression.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad8fb35a-7f43-4d5c-a67f-8fbfc59952dc', 'The wedge-shaped stone at the central apex of an arch that locks all the surrounding arch stones (voussoirs) together in compressive equilibrium, transferring load downwards to the pillars', true, '2fd26c03-c986-405d-9ea6-7288be51d858');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e821a47-c8d0-4de1-ae67-c552c9fac4fe', 'A stone made of pure gold for decoration', false, '2fd26c03-c986-405d-9ea6-7288be51d858');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c03228e4-a2b8-48b6-a0c2-7ffc4ca215a2', 'A key used to lock the palace gate', false, '2fd26c03-c986-405d-9ea6-7288be51d858');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d682803-3e23-41a1-91c5-71ca0607c9de', 'The foundation stone buried in the dirt', false, '2fd26c03-c986-405d-9ea6-7288be51d858');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea4f2c89-d2a1-4d1d-88ac-4d66e1ae4b56', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Consider four monumental ceiling engineering techniques in medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e43db8f1-1d5c-4fbc-a58b-df2dc7dacd9c', 'Extraordinary indigenous engineering versatility that continuously synthesized structural mechanics, regional cultural motifs, and aesthetic majesty', true, 'ea4f2c89-d2a1-4d1d-88ac-4d66e1ae4b56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dba69344-fb35-48b9-931d-437f65ef87f3', 'That builders only knew how to make flat wooden roofs', false, 'ea4f2c89-d2a1-4d1d-88ac-4d66e1ae4b56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('711c0414-7f3d-4304-ba2c-2b9c1605e290', 'That all buildings were copied from Roman blueprints', false, 'ea4f2c89-d2a1-4d1d-88ac-4d66e1ae4b56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b443c5bb-352b-48b0-8097-236ac71f9cbc', 'That medieval buildings had no roofs', false, 'ea4f2c89-d2a1-4d1d-88ac-4d66e1ae4b56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb1268a8-28fb-4b68-a6d2-a9726272b2f4', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Why was the construction of the 60-metre Shikhara of Brihadisvara Temple at Thanjavur considered an unprecedented structural marvel of the 11th century?', 'Thanjavur''s Brihadisvara temple stands as an all-granite interlocking structural tour-de-force, towering 66 m without binding cement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13df2586-e926-4108-b217-10b9212603ce', 'Granite was not available locally and had to be transported from distant quarries; the entire colossal multi-tiered temple was built without mortar using interlocking precision dry masonry', true, 'cb1268a8-28fb-4b68-a6d2-a9726272b2f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28044fdb-8d64-4585-a62e-f686e7ed3167', 'It was built under the ocean', false, 'cb1268a8-28fb-4b68-a6d2-a9726272b2f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3e50ae6-9b9e-43ab-b7ee-bb99f7f7674a', 'It was built out of solid ice', false, 'cb1268a8-28fb-4b68-a6d2-a9726272b2f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('674f407f-624e-46e3-9041-556fe0db362b', 'It was built in one single hour', false, 'cb1268a8-28fb-4b68-a6d2-a9726272b2f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a587fd35-baac-499f-ae1f-c9102a240fe4', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'What was the symbolic function of ''Jharokha Darshan'' in Shah Jahan''s palace architecture in the Red Fort?', 'Jharokha Darshan institutionalized divine monarchical viewing, projecting the Emperor as the illuminating cosmic patriarch before his subjects.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a165962-5d1c-4e8b-b708-0310f606fd70', 'The elevated royal balcony from which the Emperor appeared every morning at sunrise to the assembled common public below, blending Hindu concepts of divine vision (darshan) with imperial kingship', true, 'a587fd35-baac-499f-ae1f-c9102a240fe4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad79ab1d-3730-4e6d-844e-e0099070cd02', 'A window used to throw garbage', false, 'a587fd35-baac-499f-ae1f-c9102a240fe4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0a16f5b-5ef5-4bf8-a3af-40a3e150e2e2', 'A balcony for feeding pigeons only', false, 'a587fd35-baac-499f-ae1f-c9102a240fe4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d3f7508-ceb6-491e-bc44-e706b6ad1543', 'A secret door for escaping wars', false, 'a587fd35-baac-499f-ae1f-c9102a240fe4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6f48f08-a07d-447f-a20d-ba9ba4dc5b0e', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'What master architectural legacy defines Chapter 5 of NCERT Class 7 History?', 'Chapter 5 illuminates the technical, stylistic, and ideological evolution of India''s monumental architecture across a millennium of dynamic synthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b6042b4-d1d5-467d-a3bc-999c111d09b8', 'The evolution of magnificent engineering virtuosity across Hindu temple sacred geography, Indo-Islamic structural arcuate and dome innovations, Chahar Bagh symmetry, and rich cross-regional architectural synthesis that permanently shaped India''s built heritage', true, 'e6f48f08-a07d-447f-a20d-ba9ba4dc5b0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('900d1929-dbd2-43a7-8940-218a99b64f76', 'A period of total architectural ruin', false, 'e6f48f08-a07d-447f-a20d-ba9ba4dc5b0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a585a58e-c3d7-4119-b8c3-8ec26f2aeb8f', 'The destruction of all stone masonry', false, 'e6f48f08-a07d-447f-a20d-ba9ba4dc5b0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ad58e08-7579-4601-ae34-408b44cd035b', 'The end of building construction in India', false, 'e6f48f08-a07d-447f-a20d-ba9ba4dc5b0e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bd525c9-98c0-4e40-b950-8ad65c6a26d5', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'दो या दो से अधिक शब्दों के परस्पर मेल (संक्षिप्तिकरण) से एक नवीन एवं सार्थक शब्द बनाने की व्याकरणिक प्रक्रिया को क्या कहते हैं?', 'सम् + आस (पास बैठाना): दो या अधिक पदों के संक्षिप्तिकरण से नए सार्थक शब्द निर्माण की विधि ''समास'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc364829-8546-4bb7-b36d-2daf61123524', 'समास (Compound)', true, '0bd525c9-98c0-4e40-b950-8ad65c6a26d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dabcd9d9-8caf-44a4-9e09-df95102928f1', 'संधि', false, '0bd525c9-98c0-4e40-b950-8ad65c6a26d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edd621e4-b797-4c03-b4a6-0f267cbb6ad1', 'उपसर्ग', false, '0bd525c9-98c0-4e40-b950-8ad65c6a26d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3709c161-548d-423b-b11d-acfd8da26378', 'प्रत्यय', false, '0bd525c9-98c0-4e40-b950-8ad65c6a26d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dff5acd5-a48e-4b1b-8d37-3bcc16c274f1', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'समास के नियमों से बने नए संक्षिप्त शब्द को व्याकरण में क्या कहते हैं?', 'समास रचना से निर्मित नया संक्षिप्त शब्द ''समस्त पद'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d64cb92-0562-436f-a4f7-0df2ef429297', 'समस्त पद / सामासिक पद (जैसे: ''रसोईघर'', ''राजपुत्र'')', true, 'dff5acd5-a48e-4b1b-8d37-3bcc16c274f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea051964-77d3-4b8f-b824-a992bc0dd5de', 'संधि पद', false, 'dff5acd5-a48e-4b1b-8d37-3bcc16c274f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0a75684-03ee-4a6a-bb32-f2dfe86e7e55', 'उपसर्ग पद', false, 'dff5acd5-a48e-4b1b-8d37-3bcc16c274f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af049b65-7e01-4b1a-aa37-6c3de1bda416', 'कारक', false, 'dff5acd5-a48e-4b1b-8d37-3bcc16c274f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9f076ab-12c0-4315-a181-83f9f742d637', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'समस्त पद के सभी पदों को अलग-अलग करके उनके परस्पर संबंध को स्पष्ट करने की प्रक्रिया को क्या कहते हैं?', 'सामासिक पद के घटकों को कारक-चिह्नों सहित पृथक करना ''समास-विग्रह'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('300cdabf-fc1f-4e5a-b107-1ab8c4b93542', 'समास-विग्रह (जैसे: रसोई के लिए घर)', true, 'f9f076ab-12c0-4315-a181-83f9f742d637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6b6a1b0-a074-4936-99b1-4c249e43c629', 'संधि-विच्छेद', false, 'f9f076ab-12c0-4315-a181-83f9f742d637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c0f8a9a-35a5-4c46-9685-0f1f86252566', 'वर्ण-विच्छेद', false, 'f9f076ab-12c0-4315-a181-83f9f742d637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('666834bf-0a66-4455-ae9b-e148c81e59d3', 'उपसर्ग विच्छेद', false, 'f9f076ab-12c0-4315-a181-83f9f742d637');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('442a567d-6ea4-4928-ab61-67027f1d2acb', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'हिंदी व्याकरण में समास के मुख्य रूप से कितने भेद होते हैं?', 'समास के 6 प्रमुख भेद हैं: अव्ययीभाव, तत्पुरुष, कर्मधारय, द्विगु, द्वंद्व, और बहुव्रीहि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8793443-62a8-4898-bb3f-d536d1abf04a', 'छह भेद (1. अव्ययीभाव, 2. तत्पुरुष, 3. कर्मधारय, 4. द्विगु, 5. द्वंद्व, 6. बहुव्रीहि)', true, '442a567d-6ea4-4928-ab61-67027f1d2acb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae0c1ae4-9ed6-4408-9269-607039655ecf', 'चार भेद', false, '442a567d-6ea4-4928-ab61-67027f1d2acb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff569b1a-a02c-4f11-a8f5-8256819481c6', 'पाँच भेद', false, '442a567d-6ea4-4928-ab61-67027f1d2acb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('543306c3-e2d7-4883-b167-74a491f6e01f', 'तीन भेद', false, '442a567d-6ea4-4928-ab61-67027f1d2acb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f80a8da-21ea-4cf1-959f-0c982381abf8', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास का पहला पद (पूर्व पद) अव्यय तथा प्रधान हो और समस्त पद भी अव्यय बन जाए, उसे क्या कहते हैं?', 'पूर्व पद अव्यय और प्रधान होने पर ''अव्ययीभाव समास'' होता है (यथाशक्ति = शक्ति के अनुसार)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d62add0-f4d0-4261-82c5-fb5b2880e395', 'अव्ययीभाव समास (जैसे: यथाशक्ति, प्रतिदिन, आजन्म, भरपेट)', true, '2f80a8da-21ea-4cf1-959f-0c982381abf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27755adb-c583-4856-ad63-9fa8b0856f9a', 'तत्पुरुष समास', false, '2f80a8da-21ea-4cf1-959f-0c982381abf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79545368-afa3-426d-960a-9d0474403e89', 'द्विगु समास', false, '2f80a8da-21ea-4cf1-959f-0c982381abf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77c933f6-3554-4310-a777-043004718c77', 'द्वंद्व समास', false, '2f80a8da-21ea-4cf1-959f-0c982381abf8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00d9f749-524f-4a61-bcb8-c0f8aef96781', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास में दूसरा पद (उत्तर पद) प्रधान होता है तथा दोनों पदों के बीच कारक-विभक्ति चिह्नों (का, के, की, से, के लिए, में, पर) का लोप हो जाता है, उसे क्या कहते हैं?', 'उत्तर पद प्रधान और कारक चिह्नों के लोप वाला समास ''तत्पुरुष समास'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f865d818-3646-4082-b59a-7d4bebea49cb', 'तत्पुरुष समास (जैसे: राजमहल = राजा का महल, देशप्रेम = देश के लिए प्रेम)', true, '00d9f749-524f-4a61-bcb8-c0f8aef96781');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0e07dcd-7a84-467d-9267-ecf8a76b2a1d', 'अव्ययीभाव समास', false, '00d9f749-524f-4a61-bcb8-c0f8aef96781');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e28a1136-0115-4e3e-bca2-39077e21b404', 'द्विगु समास', false, '00d9f749-524f-4a61-bcb8-c0f8aef96781');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25e451d2-d2f1-42bb-9dbf-15ae1bfa0964', 'बहुव्रीहि समास', false, '00d9f749-524f-4a61-bcb8-c0f8aef96781');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1026957e-78f9-4f9f-9425-6c561030ddc4', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास का पहला पद संख्यावाचक विशेषण हो और समस्त पद किसी समूह (समाहार) का बोध कराए, उसे क्या कहते हैं?', 'संख्या-पूर्व पद समाहारक समास ''द्विगु समास'' कहलाता है (चौराहा = चार राहों का समाहार)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601c1297-74a8-4954-869e-807f64bd868e', 'द्विगु समास (जैसे: त्रिफला, चौराहा, तिरंगा, पंचवटी, नवग्रह)', true, '1026957e-78f9-4f9f-9425-6c561030ddc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1712d66e-a411-4704-9398-ccabd43d164f', 'द्वंद्व समास', false, '1026957e-78f9-4f9f-9425-6c561030ddc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ef1a22e-ceb3-4c3c-88d8-56fda697480e', 'कर्मधारय समास', false, '1026957e-78f9-4f9f-9425-6c561030ddc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('279a6ef0-6b41-488b-a217-10384f690d78', 'अव्ययीभाव समास', false, '1026957e-78f9-4f9f-9425-6c561030ddc4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('039fa32b-8575-45b2-8dd3-db0c41ed760a', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास में दोनों पद (पूर्व पद और उत्तर पद) समान रूप से प्रधान हों और विग्रह करने पर ''और'', ''या'', ''तथा'' योजक शब्द लगे, उसे क्या कहते हैं?', 'उभय-पद प्रधान समास ''द्वंद्व समास'' कहलाता है (दिन-रात = दिन और रात)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85362921-880f-4f9b-9768-a6102773b3ae', 'द्वंद्व समास (जैसे: माता-पिता = माता और पिता, सुख-दुख = सुख और दुख)', true, '039fa32b-8575-45b2-8dd3-db0c41ed760a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e159974c-1c1c-4167-982a-0c9488bf9bfa', 'द्विगु समास', false, '039fa32b-8575-45b2-8dd3-db0c41ed760a');
