INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cd5f6a6-ab9a-4f15-ae78-4e26b32d8d9d', 'कर्मधारय समास', false, '039fa32b-8575-45b2-8dd3-db0c41ed760a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33fc9120-4c31-468a-98a4-4b952831f77d', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास में दोनों पदों के बीच विशेषण-विशेष्य अथवा उपमान-उपमेय का संबंध हो और उत्तर पद प्रधान हो, उसे क्या कहते हैं?', 'विशेषण-विशेष्य / उपमान-उपमेय युक्त समास ''कर्मधारय समास'' कहलाता है (महात्मा = महान है जो आत्मा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19eabfd3-0fc0-4878-a68c-cabb664f4def', 'कर्मधारय समास (जैसे: नीलकमल = नीला है जो कमल, चरणकमल = कमल के समान चरण)', true, '33fc9120-4c31-468a-98a4-4b952831f77d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60b39689-7fde-40c7-a43f-8c359d8a5170', 'अव्ययीभाव समास', false, '33fc9120-4c31-468a-98a4-4b952831f77d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84d77237-adbf-4fe2-b85e-50df69199007', 'द्वंद्व समास', false, '33fc9120-4c31-468a-98a4-4b952831f77d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b4f5e6d-e27f-435a-bb72-8d1ed52a89c2', 'द्विगु समास', false, '33fc9120-4c31-468a-98a4-4b952831f77d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32de1923-1964-4746-b8e6-ffb096cf91e5', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास में दोनों पदों में से कोई भी पद प्रधान नहीं होता, बल्कि दोनों पद मिलकर किसी तीसरे अन्य विशेष पद (संज्ञा) की ओर संकेत करते हैं, उसे क्या कहते हैं?', 'अन्य-पद प्रधान समास ''बहुव्रीहि समास'' कहलाता है (पीतांबर = पीत हैं अंबर जिसके अर्थात श्रीकृष्ण)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9507cb04-e227-4827-9269-f95e7af4d2a6', 'बहुव्रीहि समास (जैसे: गजानन = गज के समान आनन है जिसका अर्थात गणेश, दशानन = रावण)', true, '32de1923-1964-4746-b8e6-ffb096cf91e5');
