INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af52988a-91f4-47a6-82e5-b81fed64567e', 'अव्ययीभाव समास', false, '32de1923-1964-4746-b8e6-ffb096cf91e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf5f137a-aa16-46c0-85cf-1d92ea027efe', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', '''राजपुत्र'' समस्त पद का सही समास-विग्रह क्या होगा?', 'राजपुत्र = राजा का पुत्र (षष्ठी संबंध कारक विभक्ति ''का'' का लोप होने से संबंध तत्पुरुष)।', NOW()) ON CONFLICT DO NOTHING;
