INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b690059-e0c6-4288-9ecd-1d895ec4ce87', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', '''यथाशक्ति'' समस्त पद में कौन-सा समास है?', '''यथा'' अव्यय पूर्व पद होने के कारण ''यथाशक्ति'' अव्ययीभाव समास है।', NOW()) ON CONFLICT DO NOTHING;
