INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('032a2488-6fcb-492f-a12b-0108a0851a86', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', 'कारक चिह्नों के आधार पर तत्पुरुष समास के कितने उप-भेद होते हैं?', 'कर्ता और संबोधन को छोड़कर द्वितीया कर्म से सप्तमी अधिकरण तक तत्पुरुष के 6 उप-भेद होते हैं।', NOW()) ON CONFLICT DO NOTHING;
