INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d6290fc-3ec1-4a7d-a659-12ea7050b9f3', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''नीलकंठ'' शब्द का कर्मधारय और बहुव्रीहि दोनों समासों में क्या अलग-अलग विग्रह होगा?', 'कर्मधारय (नीला है जो कंठ - विशेषण-विशेष्य) ; बहुव्रीहि (नीला है कंठ जिसका अर्थात् शिव - रूढ़ अन्य पद)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f718a03d-2fcd-43cc-a71b-cf5b8065046a', 'कर्मधारय विग्रह: ''नीला है जो कंठ'' ; बहुव्रीहि विग्रह: ''नीला है कंठ जिसका अर्थात् भगवान शिव''', true, '1d6290fc-3ec1-4a7d-a659-12ea7050b9f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d5b197c-910c-4ece-ba49-68e5dc9f4974', 'दोनों में एक ही विग्रह होता है', false, '1d6290fc-3ec1-4a7d-a659-12ea7050b9f3');
