INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd943fce-c93e-4499-abca-e95a51cb1627', 'नीलकंठ केवल तत्पुरुष समास है', false, '1d6290fc-3ec1-4a7d-a659-12ea7050b9f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5f5f635-6b79-4b8a-a318-df49eaa0c549', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''दशानन'' शब्द का द्विगु और बहुव्रीहि दोनों समासों में क्या अलग-अलग विग्रह होगा?', 'संख्या समाहार = द्विगु ; विशिष्ट व्यक्ति (रावण) की ओर रूढ़ संकेत = बहुव्रीहि समास।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98594000-a739-41b9-b7d5-10a88d01cab9', 'द्विगु विग्रह: ''दस आननों (मुखों) का समाहार'' ; बहुव्रीहि विग्रह: ''दस हैं आनन जिसके अर्थात् रावण''', true, 'e5f5f635-6b79-4b8a-a318-df49eaa0c549');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1daa88e6-bbc6-41d7-a4d5-ea98c325e0a4', 'द्विगु में रावण और बहुव्रीहि में दस', false, 'e5f5f635-6b79-4b8a-a318-df49eaa0c549');
