INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52525375-2b2e-4bbc-943d-c35d1e79c833', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''पाप-पुण्य'' और ''खट्टा-मीठा'' में कौन-सा समास है?', 'दोनों पद समान रूप से प्रधान और योजक ''और'' से जुड़े होने के कारण ''द्वंद्व समास'' है।', NOW()) ON CONFLICT DO NOTHING;
