INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58c8cb33-a389-4971-9980-9cdc3842781e', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''लंबोदर'' (लंबा है उदर जिसका अर्थात् श्री गणेश) में कौन-सा समास है?', 'दोनों पदों से भिन्न तीसरे विशिष्ट देवता (गणेश) का बोध कराने से ''बहुव्रीहि समास'' है।', NOW()) ON CONFLICT DO NOTHING;
