INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25e5659d-d82f-4316-8282-e46ea6793bc6', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''रातों-रात'' और ''दिनों-दिन'' शब्दों में कौन-सा समास है?', 'एक ही शब्द की पुनरावृत्ति से अव्यय बनने पर ''अव्ययीभाव समास'' होता है (रात ही रात में = रातों-रात)।', NOW()) ON CONFLICT DO NOTHING;
