INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a47943f6-7eb4-4302-8e2c-bb501a1c1749', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''वनवास'' समस्त पद का सही समास-विग्रह क्या होगा?', 'वन में वास = अधिकरण तत्पुरुष (सप्तमी विभक्ति ''में'' का लोप)।', NOW()) ON CONFLICT DO NOTHING;
