INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94b78c6b-ce0d-4fdc-9c72-435896aff17d', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', 'जिस तत्पुरुष समास में पहला पद निषेधवाचक (नकारात्मक - जैसे: न, अ, अन) होता है (जैसे: अनदेखा, अनहोनी, अन्याय, अधर्म), उसे क्या कहते हैं?', 'नकारात्मक अभाव सूचक पूर्व पद (अ/अन/न) वाला समास ''नञ् तत्पुरुष'' कहलाता है (न न्याय = अन्याय)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfdf19c8-449e-4953-9c18-413b5fa42e2e', 'नञ् तत्पुरुष समास (Negative Compound)', true, '94b78c6b-ce0d-4fdc-9c72-435896aff17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0dc2e0e-cc66-4efd-8076-c6bf3d8b1846', 'कर्म तत्पुरुष', false, '94b78c6b-ce0d-4fdc-9c72-435896aff17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('576746db-79f1-4376-84b0-229da9d06d48', 'अपादान तत्पुरुष', false, '94b78c6b-ce0d-4fdc-9c72-435896aff17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6446f68-b20f-4713-bf6e-1fc11cf4440d', 'अव्ययीभाव समास', false, '94b78c6b-ce0d-4fdc-9c72-435896aff17d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30af2038-86d6-454b-8c3b-d67ea8c9eae1', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''पंचामृत'' समस्त पद का सही समास-विग्रह और समास का नाम क्या होगा?', 'पाँच द्रव्यों (दूध, दही, घी, शहद, गंगाजल) का समाहार = द्विगु समास।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24d62500-6182-472c-b77d-59d77d3c8a6b', 'पाँच अमृतरूपी द्रव्यों का समाहार (द्विगु समास)', true, '30af2038-86d6-454b-8c3b-d67ea8c9eae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99e1a367-167d-423b-86af-4ccb4b9d329a', 'पाँच और अमृत (द्वंद्व)', false, '30af2038-86d6-454b-8c3b-d67ea8c9eae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a94d99f6-e336-4ff6-9c24-8dc58d8e7a5a', 'अमृत है जो पाँच (कर्मधारय)', false, '30af2038-86d6-454b-8c3b-d67ea8c9eae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a2b35d9-d26f-4b86-99a8-68e56f1d47d1', 'पाँच का अमृत (तत्पुरुष)', false, '30af2038-86d6-454b-8c3b-d67ea8c9eae1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('198eb57e-690b-4540-9b6d-4219cea5b382', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5964577d-6207-44ea-bc4b-b92360e021fe', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '198eb57e-690b-4540-9b6d-4219cea5b382');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bdbee43-4c46-4b1e-9237-fa59c3e1bf8d', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '198eb57e-690b-4540-9b6d-4219cea5b382');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7b81645-b288-41ed-924a-4a4c68bb7a1d', '(A) सही है, परन्तु (R) गलत है।', false, '198eb57e-690b-4540-9b6d-4219cea5b382');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('733f9fce-bf28-4814-a843-c97f84cd216b', '(A) गलत है, परन्तु (R) सही है।', false, '198eb57e-690b-4540-9b6d-4219cea5b382');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c1ce8fd-d8b4-4597-8e8f-f355d75fe6ed', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'Spot the IMPOSTER in the following group of समस्त पद और उनके समास भेदों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba8de7e1-22f6-4a88-8ade-a14338359f0e', 'युग्म 1', false, '5c1ce8fd-d8b4-4597-8e8f-f355d75fe6ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03646e5e-7ffd-4873-8859-3e3831ae89a2', 'युग्म 2', false, '5c1ce8fd-d8b4-4597-8e8f-f355d75fe6ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('574bc4df-c71f-4f05-80b8-bb700b8027ad', 'युग्म 3', false, '5c1ce8fd-d8b4-4597-8e8f-f355d75fe6ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6d5d138-5706-439d-b54d-0f8edb4c17e9', 'युग्म 4 (माता-पिता ''द्वंद्व समास'' है, बहुव्रीहि नहीं)', true, '5c1ce8fd-d8b4-4597-8e8f-f355d75fe6ed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa9b5560-f333-4a92-954c-fc7a1ee555be', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'सुमेलित कीजिए (समस्त पद और उनके समास भेद):
(क) चतुर्मुख (चार हैं मुख जिसके अर्थात् ब्रह्मा) -> (i) बहुव्रीहि समास
(ख) त्रिवेणी (तीन वेणियों का समाहार)            -> (ii) द्विगु समास
(ग) नरसिंह (सिंह के समान नर)                   -> (iii) कर्मधारय समास
(घ) बेखटके (बिना खटके के)                      -> (iv) अव्ययीभाव समास', 'चतुर्मुख = ब्रह्मा (बहुव्रीहि); त्रिवेणी = 3 नदियों का समाहार (द्विगु); नरसिंह = उपमान-उपमेय (कर्मधारय); बेखटके = अव्ययीभाव।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc18d895-0113-417d-bc1f-ed49e7ae9c80', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, 'aa9b5560-f333-4a92-954c-fc7a1ee555be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe580281-5808-4779-a53e-0fbe605a11eb', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, 'aa9b5560-f333-4a92-954c-fc7a1ee555be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25801767-269d-4bad-9a16-070f729aec1e', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'aa9b5560-f333-4a92-954c-fc7a1ee555be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b742c46c-bb26-4ae9-a1ae-265b565f8f75', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'aa9b5560-f333-4a92-954c-fc7a1ee555be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9736138-db20-404a-bc9f-07dca2fce8ba', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''चक्रपाणि'' (चक्र है पाणि/हाथ में जिसके अर्थात् भगवान विष्णु) और ''त्रिनेत्र'' (तीन नेत्र हैं जिसके अर्थात् भगवान शिव) में कौन-सा समास है?', 'अन्य विशिष्ट ईश्वरीय सत्ता (विष्णु/शिव) को ध्वनित करने के कारण ''बहुव्रीहि समास'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ed879d4-475e-44ab-9013-b84c81deb574', 'बहुव्रीहि समास (क्योंकि दोनों पद मिलकर किसी अन्य विशिष्ट देवता की ओर रूढ़ संकेत कर रहे हैं)', true, 'b9736138-db20-404a-bc9f-07dca2fce8ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5e29f90-8d2a-4234-82f2-7cd8d3e95152', 'द्विगु समास', false, 'b9736138-db20-404a-bc9f-07dca2fce8ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08c4523c-9397-463f-b41d-e420a4b3e72b', 'कर्मधारय समास', false, 'b9736138-db20-404a-bc9f-07dca2fce8ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a03318d9-385a-4f0b-9232-e1a721a8ee04', 'तत्पुरुष समास', false, 'b9736138-db20-404a-bc9f-07dca2fce8ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a382af01-58db-4eee-98b5-4e4ff1506667', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''कर्मधारय समास'' और ''बहुव्रीहि समास'' में निर्णय करने का सबसे प्रामाणिक व्याकरणिक आधार क्या है?', 'समास का निर्धारण विग्रह की प्रकृति पर निर्भर करता है: विशेषणात्मक विग्रह = कर्मधारय; अन्य-पदवाची विग्रह = बहुव्रीहि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3c865d8-69b6-4059-987c-7bf67cc0215b', 'समास-विग्रह ही निर्णय करता है: यदि विग्रह विशेषण-विशेष्य के रूप में हो तो ''कर्मधारय'' होगा ; यदि विग्रह किसी अन्य तीसरे पद के रूढ़ अर्थ में हो तो ''बहुव्रीहि'' होगा', true, 'a382af01-58db-4eee-98b5-4e4ff1506667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0688e61b-df21-4ff0-8a3d-b595e1ad1a47', 'शब्द का पहला अक्षर', false, 'a382af01-58db-4eee-98b5-4e4ff1506667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e7808ed-5fff-4dfa-818a-06704b7e65fc', 'शब्द में कितने वर्ण हैं', false, 'a382af01-58db-4eee-98b5-4e4ff1506667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81c3dc61-896c-4e50-ac01-28f15b6d2936', 'शब्द किस भाषा का है', false, 'a382af01-58db-4eee-98b5-4e4ff1506667');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bcc3f07-0802-4326-88a7-79b824dad22c', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'निम्नलिखित में से किस समस्त पद में ''अपादान तत्पुरुष समास'' है?', 'पथ से भ्रष्ट / देश से निकाला में अलगाव/वियोग सूचक ''से'' विभक्ति का लोप होने से ''अपादान तत्पुरुष'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8126dcd-a2bb-4092-9842-820f77b774c5', '''पथभ्रष्ट'' (पथ से भ्रष्ट / अलग होना) और ''देशनिकाला'' (देश से निकाला)', true, '7bcc3f07-0802-4326-88a7-79b824dad22c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3791c303-f67e-44ac-9706-925136957d56', '''रसभरा''', false, '7bcc3f07-0802-4326-88a7-79b824dad22c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('428619dc-cc6a-485c-841c-e50f6ad5e8eb', '''मूर्तिकार''', false, '7bcc3f07-0802-4326-88a7-79b824dad22c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('717c4f3b-9c6f-4f79-aa17-572e7391cf7a', '''रसोईघर''', false, '7bcc3f07-0802-4326-88a7-79b824dad22c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd2a4ba8-224a-439b-8e9c-242e17d92156', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''दाल-रोटी'', ''छोटा-बड़ा'', ''ऊँच-नीच'', ''हानि-लाभ'' में कौन-सा समास है?', 'उभय-पद प्रधान द्वंद्व समास (दाल और रोटी, हानि या लाभ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3640c254-6071-485d-9eb6-b8454231ecbf', 'द्वंद्व समास (दोनों पद प्रधान, विग्रह में ''और'' या ''या'' का प्रयोग)', true, 'bd2a4ba8-224a-439b-8e9c-242e17d92156');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ec49d85-251a-4ab3-9e0d-b07b06d6e139', 'द्विगु समास', false, 'bd2a4ba8-224a-439b-8e9c-242e17d92156');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fd05a3b-1609-4483-a17d-d01e150674dd', 'कर्मधारय समास', false, 'bd2a4ba8-224a-439b-8e9c-242e17d92156');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fa1698b-6526-486c-b3ae-19629c8f64ce', 'बहुव्रीहि समास', false, 'bd2a4ba8-224a-439b-8e9c-242e17d92156');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fe75024-486b-4b55-86bb-9c7d9471b127', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''महात्मा'' और ''परमानंद'' में कौन-सा समास है?', 'विशेषण-विशेष्य संबंध होने के कारण ''कर्मधारय समास'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7e56081-f9ca-4310-9794-c3358842d406', 'कर्मधारय समास (महान है जो आत्मा ; परम है जो आनंद - विशेषण-विशेष्य संबंध)', true, '9fe75024-486b-4b55-86bb-9c7d9471b127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef8e3210-a697-4c10-8a82-aa418b4ca179', 'तत्पुरुष समास', false, '9fe75024-486b-4b55-86bb-9c7d9471b127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('921bc572-137e-4f1c-86ea-3cefd9e17b38', 'अव्ययीभाव समास', false, '9fe75024-486b-4b55-86bb-9c7d9471b127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94259ca3-0cb7-48e8-86c5-e3dc1d533511', 'द्विगु समास', false, '9fe75024-486b-4b55-86bb-9c7d9471b127');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d8a57ea-843b-4d20-82e3-6f79c485b294', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''दिशानिर्देश'' और ''मार्गदर्शन'' में कौन-सा तत्पुरुष समास है?', 'दिशा का निर्देश / मार्ग का दर्शन = संबंध तत्पुरुष (''का'' विभक्ति का लोप)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c813175-3848-434b-b664-2e05d4440321', 'संबंध तत्पुरुष समास (दिशा का निर्देश ; मार्ग का दर्शन)', true, '4d8a57ea-843b-4d20-82e3-6f79c485b294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8a6de95-636c-4f4a-8fbb-2d4690da8b83', 'करण तत्पुरुष', false, '4d8a57ea-843b-4d20-82e3-6f79c485b294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ed3c6d-54c0-4c0f-841d-13a4c7983341', 'अपादान तत्पुरुष', false, '4d8a57ea-843b-4d20-82e3-6f79c485b294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45735764-b9de-427b-adb7-244aee93bf74', 'कर्म तत्पुरुष', false, '4d8a57ea-843b-4d20-82e3-6f79c485b294');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('489ed50d-1ea9-47b1-971d-e50d46b5de4c', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'निम्नलिखित में से कौन-सा समस्त पद ''अव्ययीभाव समास'' का उदाहरण नहीं है?', '''गंगाजल'' संबंध तत्पुरुष है; आजन्म, प्रत्यक्ष (प्रति+अक्ष) और बेखटके अव्ययीभाव समास हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d02bb74d-ed2a-4114-aaf3-1f0fd01fb68a', '''गंगाजल'' (क्योंकि यह ''गंगा का जल'' संबंध तत्पुरुष समास है, अव्ययीभाव नहीं)', true, '489ed50d-1ea9-47b1-971d-e50d46b5de4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d38a4a6b-0e7e-416b-875e-f3329a29937d', '''आजन्म''', false, '489ed50d-1ea9-47b1-971d-e50d46b5de4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad622ed9-ec88-40da-823b-712411eb1ef6', '''प्रत्यक्ष''', false, '489ed50d-1ea9-47b1-971d-e50d46b5de4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75478600-72f8-4306-a7fe-8205e139a412', '''बेखटके''', false, '489ed50d-1ea9-47b1-971d-e50d46b5de4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd7178b8-7a6e-4ad5-a229-fb6801d7a900', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''शताब्दी'' समस्त पद का शुद्ध समास-विग्रह क्या होगा?', 'शत + अब्द (वर्ष) = सौ वर्षों का समाहार (द्विगु समास)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19a63cba-88d3-426a-b9d2-49711b2e5835', 'सौ अब्दों (वर्षों) का समाहार (द्विगु समास)', true, 'fd7178b8-7a6e-4ad5-a229-fb6801d7a900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('513d8d6e-5a66-4ee4-b251-20c1c7c0a24d', 'सौ और वर्ष', false, 'fd7178b8-7a6e-4ad5-a229-fb6801d7a900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25b9bc17-083b-4dd2-8423-1a6e6ee87692', 'वर्ष है जो सौ', false, 'fd7178b8-7a6e-4ad5-a229-fb6801d7a900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55532831-aa9f-49a7-b83f-e445fb129624', 'सौ का वर्ष', false, 'fd7178b8-7a6e-4ad5-a229-fb6801d7a900');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83d44666-58a9-4c16-ad97-84437916de9b', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'समास (Compounding) के सम्यक अध्ययन का हिंदी भाषा में क्या सर्वोच्च व्यावहारिक महत्व है?', 'समास भाषा का संक्षेपण-कौशल है, जो वाक्य-विन्यास में लाघव, प्रभावोत्पादकता और ओजस्वी सौंदर्य का संचार करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4b44392-d07e-4629-96a3-ba110d32b8ca', 'समास भाषा को संक्षिप्त, चुस्त, प्रभावशाली, लालित्यपूर्ण और अर्थगर्भित बनाता है, जिससे विस्तृत विचारों को कम से कम शब्दों में सौंदर्यपूर्ण ढंग से व्यक्त किया जा सकता है', true, '83d44666-58a9-4c16-ad97-84437916de9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23e4aa64-5244-4d17-9e53-f392060f58a3', 'समास केवल शब्दों को लंबा करता है', false, '83d44666-58a9-4c16-ad97-84437916de9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23ea1fdf-8127-488b-b441-41895f0c5237', 'समास का वाक्यों में कोई प्रयोग नहीं होता', false, '83d44666-58a9-4c16-ad97-84437916de9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d506871-c5f9-4242-a6db-cc62eb18435c', 'समास केवल कविता में प्रयुक्त होता है', false, '83d44666-58a9-4c16-ad97-84437916de9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3113db4-3aba-46e8-a891-2cdfc6dac9cd', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'The biochemical process of breakdown of food (glucose) in the cells with the release of biological energy (ATP) is called:', 'Cellular respiration is the biochemical catabolism of glucose inside cells to liberate metabolic energy in the form of ATP.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f13def9c-df57-4c24-8dcb-3a1b24be19a4', 'Cellular Respiration', true, 'd3113db4-3aba-46e8-a891-2cdfc6dac9cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4565762-2272-42e0-944e-ab180a370419', 'Digestion', false, 'd3113db4-3aba-46e8-a891-2cdfc6dac9cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b36c94f-f86e-4339-9c50-9fe5e626d8c6', 'Photosynthesis', false, 'd3113db4-3aba-46e8-a891-2cdfc6dac9cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cb86708-9991-4644-9cd0-dc2519a47317', 'Transpiration', false, 'd3113db4-3aba-46e8-a891-2cdfc6dac9cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('005fca09-b86a-447b-bc55-8730184640ba', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'When the breakdown of glucose occurs in the PRESENCE of Oxygen gas, yielding carbon dioxide, water, and large energy, it is called:', 'Aerobic respiration breaks down glucose completely in the presence of O₂: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + Energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17063a7e-5109-4188-9d6e-f27a896ed4c5', 'Aerobic Respiration', true, '005fca09-b86a-447b-bc55-8730184640ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b73368b5-d9ff-4a08-ab26-3ea3cc64d207', 'Anaerobic Respiration', false, '005fca09-b86a-447b-bc55-8730184640ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41967aa3-29ac-4209-8fe3-99d05f3280e6', 'Fermentation', false, '005fca09-b86a-447b-bc55-8730184640ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a1279c3-cbf2-4ead-874d-b38ea166aa6c', 'Breathing', false, '005fca09-b86a-447b-bc55-8730184640ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e1e2f8f-88ad-462c-baba-988b887ae120', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'When the breakdown of glucose occurs in the ABSENCE of Oxygen (such as in single-celled Yeast), it is called:', 'Anaerobic respiration occurs without oxygen: Glucose → Alcohol (Ethanol) + Carbon dioxide + Energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cb62b51-d8e8-403a-9f09-c495dff57b1a', 'Anaerobic Respiration (Fermentation)', true, '8e1e2f8f-88ad-462c-baba-988b887ae120');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e443d6c-4d8c-41a2-99a9-afda61cf7027', 'Aerobic Respiration', false, '8e1e2f8f-88ad-462c-baba-988b887ae120');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('701e7e80-867f-430d-b5fb-2983c6d2ff49', 'Combustion', false, '8e1e2f8f-88ad-462c-baba-988b887ae120');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88672933-3d48-4e19-8574-757b92bfc68a', 'Inhalation', false, '8e1e2f8f-88ad-462c-baba-988b887ae120');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60fd5a62-1208-4654-9127-47378de19e63', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'What single-celled anaerobic fungus is widely used in breweries to make Wine and in bakeries to make fluffy Bread?', 'Yeast respires anaerobically, producing ethanol (for alcoholic beverages) and CO₂ gas (which causes bread dough to rise).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('793388d1-94ac-4d75-867d-d2b3e1105284', 'Yeast (Saccharomyces cerevisiae)', true, '60fd5a62-1208-4654-9127-47378de19e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f6e304d-7fe2-4fc2-aaab-350a43df8274', 'Amoeba', false, '60fd5a62-1208-4654-9127-47378de19e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81a0c143-f0ad-4749-91cb-461a56ad5a5c', 'Paramecium', false, '60fd5a62-1208-4654-9127-47378de19e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8e4a489-cc44-40e0-8ec5-6ab4a563ba3a', 'Bread mold (Rhizopus)', false, '60fd5a62-1208-4654-9127-47378de19e63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b742e2e-c0cb-4b04-9b9a-679630a2afd2', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'During heavy, rigorous exercise or fast running, the accumulation of which chemical substance in muscle cells causes painful MUSCLE CRAMPS?', 'Under temporary oxygen deficit during strenuous exercise, muscle cells respire anaerobically, producing lactic acid: Glucose → Lactic acid + Energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2865509-fda6-4852-8325-4e7e90117ba3', 'Lactic Acid', true, '6b742e2e-c0cb-4b04-9b9a-679630a2afd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8afacb7b-2d90-493f-b237-3af334fbc763', 'Hydrochloric Acid', false, '6b742e2e-c0cb-4b04-9b9a-679630a2afd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99faa54b-ff83-4b77-b4ce-859f910992ac', 'Acetic Acid', false, '6b742e2e-c0cb-4b04-9b9a-679630a2afd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5abc45be-0533-40fe-b6ca-2481c7a71d3b', 'Citric Acid', false, '6b742e2e-c0cb-4b04-9b9a-679630a2afd2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d60caae-3599-4bfc-9776-7cc246b2876e', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'How does taking a hot water bath or receiving a vigorous body massage provide immediate relief from muscle cramps?', 'Enhanced circulatory perfusion restores oxygen levels, metabolizing lactic acid into CO₂ and H₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9763bfa-f35b-4716-be0d-29b786b4531d', 'It improves blood circulation, increasing the oxygen supply to muscle cells which oxidizes accumulated lactic acid completely into CO₂ and water', true, '6d60caae-3599-4bfc-9776-7cc246b2876e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a994247a-deee-40c0-bbd8-bc096feaeb19', 'It cools the skin', false, '6d60caae-3599-4bfc-9776-7cc246b2876e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23efcb5e-482f-4371-bf8b-1c26481deb83', 'It removes water from muscles', false, '6d60caae-3599-4bfc-9776-7cc246b2876e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a550f209-8eea-437c-91a6-4798d52022b6', 'It stops blood flow', false, '6d60caae-3599-4bfc-9776-7cc246b2876e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('177ff4a3-3ea0-415c-b61c-6674cbc4d842', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'What is the normal resting Breathing Rate (breaths per minute) of an average adult human being at rest?', 'A healthy resting human adult breathes approximately 15 to 18 times per minute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a93cee1-bacf-40ba-a140-5f15e947fdda', '15 to 18 breaths per minute', true, '177ff4a3-3ea0-415c-b61c-6674cbc4d842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6055738b-9b5d-414b-8733-676f8ac9ca94', '40 to 50 breaths per minute', false, '177ff4a3-3ea0-415c-b61c-6674cbc4d842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccfdcf97-f645-4bf8-bdf9-04988ca8115a', '5 to 8 breaths per minute', false, '177ff4a3-3ea0-415c-b61c-6674cbc4d842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b200704-f8ea-4bb6-be3f-e3755f9d2792', '60 to 70 breaths per minute', false, '177ff4a3-3ea0-415c-b61c-6674cbc4d842');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f2e4173-2eed-4683-9d10-ad25af673324', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'What large, muscular dome-shaped sheet forms the floor of the human chest (thoracic) cavity and moves during breathing?', 'The diaphragm is the primary muscular partition separating the thoracic cavity from the abdominal cavity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2930293c-fa4f-4f2b-925f-6b5bb7cf96b9', 'The Diaphragm', true, '5f2e4173-2eed-4683-9d10-ad25af673324');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dd63d38-98a3-4cf2-9029-74efe1636e2e', 'The Trachea', false, '5f2e4173-2eed-4683-9d10-ad25af673324');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbfcd316-3982-42e3-b720-85261e56e466', 'The Bronchus', false, '5f2e4173-2eed-4683-9d10-ad25af673324');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b43cacf-1a52-4ead-8b50-7d44cfb218ed', 'The Rib cage', false, '5f2e4173-2eed-4683-9d10-ad25af673324');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('119f0f4f-d3ff-4322-9aaf-70b689e67b8f', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'Through which specialized respiratory organs do Fish breathe dissolved oxygen in water?', 'Fish utilize richly vascularized gill filaments with thin membranes to extract dissolved oxygen from water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0091474f-2e52-4811-acb7-2dc0db2887bb', 'Gills (vascularized filamentous branchiae)', true, '119f0f4f-d3ff-4322-9aaf-70b689e67b8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47cd2c79-7bcf-4377-80e1-eaa03db59067', 'Lungs', false, '119f0f4f-d3ff-4322-9aaf-70b689e67b8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9361b3dd-aacd-4abe-b9af-0448018d219b', 'Skin only', false, '119f0f4f-d3ff-4322-9aaf-70b689e67b8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb8f65b8-8bfa-4678-81a9-b9ba8e8d88e1', 'Tracheae', false, '119f0f4f-d3ff-4322-9aaf-70b689e67b8f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d1e9689-d035-4d1f-81c9-1a1ce69379ae', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'Through which organ does an Earthworm exchange respiratory gases (O₂ and CO₂)?', 'Earthworms absorb oxygen and expel CO₂ directly by diffusion through their moist, mucus-coated skin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92413eca-de44-45ad-b2e6-08fba9d645a0', 'Its thin, moist, and slimy skin (Cutaneous respiration)', true, '0d1e9689-d035-4d1f-81c9-1a1ce69379ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1a4ddab-691d-4f45-9ba4-018b8109ee1f', 'Lungs', false, '0d1e9689-d035-4d1f-81c9-1a1ce69379ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e281d309-6add-49de-b918-930fee12ca33', 'Gills', false, '0d1e9689-d035-4d1f-81c9-1a1ce69379ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da5fae58-1b30-4617-897b-c332030ee3bd', 'Spiracles', false, '0d1e9689-d035-4d1f-81c9-1a1ce69379ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('023e7f03-2b2b-4646-9ccd-dabecff0943d', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'Through which small lateral openings and network of air tubes do Cockroaches and insects breathe?', 'Insects have lateral body pores called spiracles connecting to a branching network of air tubes (tracheae).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('149ce313-cb7f-4c36-902c-3ea7ec00cd0a', 'Spiracles and Tracheal Tubes (Tracheae)', true, '023e7f03-2b2b-4646-9ccd-dabecff0943d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dc6d279-3a39-45ff-86a0-dfbabe0809e1', 'Gills', false, '023e7f03-2b2b-4646-9ccd-dabecff0943d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('387e3cf3-ce31-4d10-8b3f-a7b85e8d2681', 'Lungs', false, '023e7f03-2b2b-4646-9ccd-dabecff0943d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2692324d-9902-4a63-ae15-b178b51b5ecb', 'Moist skin', false, '023e7f03-2b2b-4646-9ccd-dabecff0943d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b35d15e5-cdda-443e-8ad5-9b3167e92482', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'What tiny microscopic pores on the surface of plant leaves facilitate the exchange of Oxygen and Carbon Dioxide during respiration and photosynthesis?', 'Stomata surrounded by specialized guard cells regulate gaseous exchange and transpiration in plant leaves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f063c0e3-9e39-4995-a97a-7e3e364b1752', 'Stomata (guarded by Guard Cells)', true, 'b35d15e5-cdda-443e-8ad5-9b3167e92482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ebd1ff5-2704-4cb0-9b9c-d50c8984390b', 'Xylem vessels', false, 'b35d15e5-cdda-443e-8ad5-9b3167e92482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f66b4e3-bbb1-47f9-b5eb-085d11383a06', 'Phloem tubes', false, 'b35d15e5-cdda-443e-8ad5-9b3167e92482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a687605-954e-43ad-8190-f8846244092f', 'Root caps', false, 'b35d15e5-cdda-443e-8ad5-9b3167e92482');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e7e0387-b395-457d-9db9-0b0c45c415f6', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What mechanical movements occur in the rib cage and diaphragm during human INHALATION (breathing in)?', 'Inhalation: external intercostal muscles elevate ribs (up/out), diaphragm flattens down, expanding lung volume and dropping intrapulmonary pressure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4622bf9b-119e-4f4a-a5ec-a89ce0ed9d25', 'The Ribs move UP and OUTWARDS, the Diaphragm contracts and moves DOWNWARDS, increasing the thoracic volume, lowering pressure, and drawing air in', true, '4e7e0387-b395-457d-9db9-0b0c45c415f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f43d522-00b0-4500-aa66-4e4962549352', 'The Ribs move down and in, and diaphragm moves up', false, '4e7e0387-b395-457d-9db9-0b0c45c415f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1abd84ac-7b4c-45e3-8936-16a8f4aac526', 'The lungs stop moving', false, '4e7e0387-b395-457d-9db9-0b0c45c415f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbe66581-af71-4b4d-b880-fc80b2b37174', 'The stomach contracts only', false, '4e7e0387-b395-457d-9db9-0b0c45c415f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc4c2c62-6767-4dc7-bdf8-bd5c4396c1eb', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What mechanical movements occur during human EXHALATION (breathing out)?', 'Exhalation: intercostal muscles relax, ribs depress down/in, diaphragm arches up to resting dome position, compressing thoracic space.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc94f9eb-108a-4c38-9084-8a4cd9fa1092', 'The Ribs move DOWN and INWARDS, the Diaphragm relaxes and arches UPWARDS into its dome shape, reducing thoracic volume and expelling air', true, 'bc4c2c62-6767-4dc7-bdf8-bd5c4396c1eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06a8dace-2f8e-4c98-9d35-a2f6fa66c906', 'The Ribs move up and outwards', false, 'bc4c2c62-6767-4dc7-bdf8-bd5c4396c1eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4276025-863e-4abc-a647-b42aae863c66', 'The Diaphragm moves down', false, 'bc4c2c62-6767-4dc7-bdf8-bd5c4396c1eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1b52267-3c7d-4e2c-9773-2719f4a58fff', 'The chest expands', false, 'bc4c2c62-6767-4dc7-bdf8-bd5c4396c1eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('446a56eb-d7d1-44ef-81bb-bbe70a547d59', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'How does the percentage composition of Inhaled Air compare with Exhaled Air in human beings?', 'Human respiration extracts ~4.6% oxygen from inhaled air and enriches exhaled air with ~4.4% CO₂ alongside saturated water vapor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd0e366e-5068-4968-9717-0d9f7c570d7a', 'Inhaled Air: 21% O₂ and 0.04% CO₂ ; Exhaled Air: 16.4% O₂ and 4.4% CO₂', true, '446a56eb-d7d1-44ef-81bb-bbe70a547d59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b811cf24-4943-4481-882b-709a57be9709', 'Inhaled Air: 100% O₂ ; Exhaled Air: 100% CO₂', false, '446a56eb-d7d1-44ef-81bb-bbe70a547d59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f53c7e76-0291-49dd-9cf9-28cd97840274', 'Inhaled Air: 0% O₂ ; Exhaled Air: 21% CO₂', false, '446a56eb-d7d1-44ef-81bb-bbe70a547d59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('702c33bc-731c-41b5-842e-6a1eaa52074f', 'Inhaled Air and Exhaled Air are identical', false, '446a56eb-d7d1-44ef-81bb-bbe70a547d59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('867a5f63-38ad-4bfe-a785-fa44d2cc5820', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'How do adult Frogs breathe in their dual (amphibious) habitats?', 'Amphibian respiration: terrestrial lung ventilation supplemented by aquatic cutaneous microvascular diffusion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6166ffd3-bff7-498d-94c5-313ec01dec17', 'On land they breathe through a pair of Lungs (pulmonary respiration) ; in water they breathe through their moist, slimy Skin (cutaneous respiration)', true, '867a5f63-38ad-4bfe-a785-fa44d2cc5820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abd773be-a1a5-421d-b9ab-80980ca1ab0b', 'They only breathe through gills', false, '867a5f63-38ad-4bfe-a785-fa44d2cc5820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb15d5cc-bf5d-4a46-922b-f0cfe09477d8', 'They only breathe through lungs', false, '867a5f63-38ad-4bfe-a785-fa44d2cc5820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a69b116-449a-42c8-bec7-6402a08cbeb7', 'They do not breathe in water', false, '867a5f63-38ad-4bfe-a785-fa44d2cc5820');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f9eeb98-ebb6-4edd-b391-a0326fde664f', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why do plant roots die and rot if a potted plant is over-watered continuously for many days (waterlogging)?', 'Waterlogging creates soil anoxia; root cells cannot perform aerobic respiration to generate ATP for active mineral transport, causing asphyxiation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c951c937-a9bf-464e-81d5-31951321111c', 'Water fills all the microscopic air spaces between soil particles, cutting off oxygen supply to root cells, preventing cellular respiration', true, '8f9eeb98-ebb6-4edd-b391-a0326fde664f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44c14fb3-fc06-443f-8f71-d8fe620d967b', 'Because roots drink too much water and explode', false, '8f9eeb98-ebb6-4edd-b391-a0326fde664f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('125cd17a-451e-4c94-83dd-30dd8923d1e0', 'Because water turns into acid', false, '8f9eeb98-ebb6-4edd-b391-a0326fde664f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39cca116-303d-4d03-8a70-1d1c025a38e2', 'Because sunlight cannot reach the leaves', false, '8f9eeb98-ebb6-4edd-b391-a0326fde664f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aaed4a7f-0bb3-4cc4-a256-5bd631d828bb', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why does breathing become much faster and deeper during vigorous physical exercise (like running or swimming)?', 'Elevated metabolic rate increases oxygen consumption and arterial CO₂ tension (hypercapnia), triggering central chemoreceptors to elevate ventilation rate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('205a7ffb-9a46-4a87-8a73-bdb346740e20', 'Working muscle cells demand more energy (ATP) rapidly, requiring increased Oxygen intake to accelerate aerobic respiration and quickly eliminate excess CO₂', true, 'aaed4a7f-0bb3-4cc4-a256-5bd631d828bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69669191-5240-4173-9544-a349097d933f', 'Because the lungs shrink in cold air', false, 'aaed4a7f-0bb3-4cc4-a256-5bd631d828bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3839bcb0-8a73-4cd0-a440-958b12bde88c', 'Because the heart stops beating', false, 'aaed4a7f-0bb3-4cc4-a256-5bd631d828bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05dcf7fd-cab2-4b86-b3ee-dacf33e8d040', 'To cool the shoes', false, 'aaed4a7f-0bb3-4cc4-a256-5bd631d828bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55b1dd4c-8ac9-4ffd-9ffb-c9755b759bde', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why do we sneeze when we inhale foreign irritants (like dust particles, smoke, or pollen)?', 'The sternutatory (sneeze) reflex forcefully expels air (~150 km/h) to cleanse the upper respiratory epithelium of particulate irritants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69b9751e-522b-418a-bc06-4de0704909b6', 'The irritants trigger sensory nerves in the nasal lining, initiating a powerful reflex violent expulsion of air to clear foreign contaminants from the nasal tract', true, '55b1dd4c-8ac9-4ffd-9ffb-c9755b759bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f80d100-d46a-41e9-bf89-112ad3c78057', 'To exercise chest muscles', false, '55b1dd4c-8ac9-4ffd-9ffb-c9755b759bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df047a85-12cf-4c72-b09d-2d75b2c3e158', 'To cool the brain', false, '55b1dd4c-8ac9-4ffd-9ffb-c9755b759bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e48e0607-a67c-4336-9941-44984b477cb8', 'Because the stomach is full', false, '55b1dd4c-8ac9-4ffd-9ffb-c9755b759bde');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96d298f5-aeaf-4f44-85e2-96cfd9e599b7', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why does a mirror fog up when you exhale your breath closely onto its clean glass surface?', 'Cellular respiration produces water vapor byproduct (C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O); exhaled warm vapor condenses on cool glass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('682054de-ec3d-41f1-8775-3d80e555f826', 'Warm exhaled breath is saturated with Water Vapor produced during cellular respiration, which immediately condenses into tiny liquid droplets on the cooler glass surface', true, '96d298f5-aeaf-4f44-85e2-96cfd9e599b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d08be630-d0c5-42d3-9da8-1b099c23f2e1', 'Dust settles on the mirror', false, '96d298f5-aeaf-4f44-85e2-96cfd9e599b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72dee2bb-e9b1-4243-9f71-7aeb72adee84', 'The mirror glass melts', false, '96d298f5-aeaf-4f44-85e2-96cfd9e599b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9fbb937-fe2a-4e09-acdc-d9b0ba3d7e6b', 'The mirror absorbs carbon dioxide', false, '96d298f5-aeaf-4f44-85e2-96cfd9e599b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67399b28-8d89-4e96-8529-6a793dd3e9aa', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'How do Whale and Dolphin mammals breathe while swimming underwater in oceans?', 'Cetaceans are air-breathing mammals with lungs that surface to exchange tidal volume via dorsal blowholes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53bc82dd-2d85-4dc4-a24f-1e619deaf91e', 'They do NOT have gills; they possess Lungs and must periodically surface to inhale fresh atmospheric air through a Blowhole located atop their heads', true, '67399b28-8d89-4e96-8529-6a793dd3e9aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d2854f2-25f9-4804-a197-d3487112fd15', 'They breathe through gills like fish', false, '67399b28-8d89-4e96-8529-6a793dd3e9aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01f36b08-34f5-4b5b-81f3-817add51a8e4', 'They absorb oxygen through their fins', false, '67399b28-8d89-4e96-8529-6a793dd3e9aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51619da1-bc2d-4e46-938e-b7dbe620a081', 'They do not breathe oxygen', false, '67399b28-8d89-4e96-8529-6a793dd3e9aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fb7dc70-9686-41c6-a271-ab478073c51c', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'In the human respiratory tract, what is the role of the fine Mucus and tiny Cilia lining the nasal passages?', 'Mucociliary escalator: goblet cell mucus traps airborne particulates while ciliated epithelium propels debris pharyngeally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90a8ab1a-2daa-4a37-a5cc-5ae9a4734b48', 'They trap dust, pollen, soot particles, and microbes from inhaled air, warming and humidifying the air before it reaches the delicate lungs', true, '5fb7dc70-9686-41c6-a271-ab478073c51c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50145cce-921a-42ed-abfe-9aa9d3b0b0cc', 'They cool the lungs to 0°C', false, '5fb7dc70-9686-41c6-a271-ab478073c51c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2397261d-1b6e-4bc4-b772-83ec559d9305', 'They make speaking louder', false, '5fb7dc70-9686-41c6-a271-ab478073c51c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed45ca09-5a9e-4a3b-9b4c-eb104f1d439c', 'They produce digestive enzymes', false, '5fb7dc70-9686-41c6-a271-ab478073c51c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1abeb63e-fc17-42b6-9efd-0765d4843577', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What are ''Lenticels'' in woody trees and stems?', 'Lenticels are specialized loosely-packed cork cell fissures in woody periderm enabling gas diffusion into internal parenchyma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bb90118-1705-4610-8a4e-f80e8c9a2c90', 'Small porous openings on the woody bark of old stems and roots that facilitate continuous respiratory gas exchange (O₂ and CO₂)', true, '1abeb63e-fc17-42b6-9efd-0765d4843577');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7102a81e-a4d6-4e72-bdbe-ffdc9cd3bee6', 'Flower buds', false, '1abeb63e-fc17-42b6-9efd-0765d4843577');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50e0c57a-7a88-482b-baff-8ee525ce414d', 'Roots that store sugar', false, '1abeb63e-fc17-42b6-9efd-0765d4843577');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a83c9a3a-9cf1-40aa-bb7c-7c3912d0c61b', 'Leaves that produce poison', false, '1abeb63e-fc17-42b6-9efd-0765d4843577');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53fc2ec4-268d-4581-9269-238fe173998d', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What happens in a bell-jar and Y-tube plastic bottle model when the rubber sheet tied at the bottom is PULLED DOWNWARDS?', 'Simulating Boyle''s Law: downward displacement of the rubber diaphragm expands internal volume, reducing chamber pressure and inflating lung balloons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84b029c1-16e7-4a25-ba60-48239523041b', 'The volume inside the bottle increases, air pressure drops, and atmospheric air rushes in to INFLATE the two small balloons (simulating lungs)', true, '53fc2ec4-268d-4581-9269-238fe173998d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d22cedc-d28b-498e-93fc-695a68420c54', 'The balloons deflate', false, '53fc2ec4-268d-4581-9269-238fe173998d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea56fb42-a4a7-4398-a15b-0ae5ab7cb6f2', 'The bottle cracks', false, '53fc2ec4-268d-4581-9269-238fe173998d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b37774e0-7d93-4767-aedc-d02dc74da4d1', 'Water fills the bottle', false, '53fc2ec4-268d-4581-9269-238fe173998d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9a5d754-320f-4e77-96b5-b608be90e6b5', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why do mountaineers climbing Mount Everest carry portable Oxygen Cylinders with them?', 'High-altitude hypobaric hypoxia: barometric pressure drops with altitude, reducing alveolar oxygen partial pressure (pO₂).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c00eb370-4a8d-4b50-b015-7ac15714c52d', 'At high altitudes, the atmospheric pressure and amount of available oxygen in the thin air is drastically lower than at sea level', true, 'f9a5d754-320f-4e77-96b5-b608be90e6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4feb1126-0d0f-4a4c-8fb6-8a32ef7d4c24', 'To make their backpacks heavier', false, 'f9a5d754-320f-4e77-96b5-b608be90e6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('567e4631-3047-49e5-aef5-4af1213dad05', 'To light campfires', false, 'f9a5d754-320f-4e77-96b5-b608be90e6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('593a244b-adf4-4b4d-9033-536272511ff4', 'Because mountains have no wind', false, 'f9a5d754-320f-4e77-96b5-b608be90e6b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b12360b3-821c-4d01-aecd-62232ef2032e', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why is yawning often triggered when we are sleepy, bored, or tired?', 'Shallow hypoventilation during drowsiness triggers reflex deep inspiratory yawning to expand collapsed alveoli and oxygenate blood.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60c3db17-42db-43ee-b631-ebb76590ed3f', 'When we are sleepy, our breathing rate slows down, causing oxygen levels in the blood to drop; a deep yawn takes in a large volume of oxygen to restore alertness', true, 'b12360b3-821c-4d01-aecd-62232ef2032e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eba2c7a-eef8-49c9-9433-86a08d6f0b5c', 'Because the jaw muscles are tired', false, 'b12360b3-821c-4d01-aecd-62232ef2032e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa83c522-e81a-4c58-8b9e-6bbcbd0ae49a', 'To make ourselves fall asleep faster', false, 'b12360b3-821c-4d01-aecd-62232ef2032e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a74357f-c7d4-4042-99c5-500dbe4dffe9', 'Because of loud noises', false, 'b12360b3-821c-4d01-aecd-62232ef2032e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87b62c28-aa48-47c7-8d2b-877ac89aa1cb', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What is the respiratory pigment in human red blood cells (RBCs) that binds with Oxygen to form Oxyhemoglobin for transport to all body cells?', 'Hemoglobin (Hb) tetramer binds up to four O₂ molecules forming oxyhemoglobin (HbO₈) for systemic cellular delivery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ce40c91-0e14-470a-89f9-372d1ee5b737', 'Hemoglobin (iron-containing protein)', true, '87b62c28-aa48-47c7-8d2b-877ac89aa1cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e86a60-db04-4750-94f9-42e2ac3862de', 'Chlorophyll', false, '87b62c28-aa48-47c7-8d2b-877ac89aa1cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f67d783d-184d-4e31-8d40-55e4e7820017', 'Melanin', false, '87b62c28-aa48-47c7-8d2b-877ac89aa1cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87f4c022-ff4a-43fc-9cbf-13332b50e736', 'Keratin', false, '87b62c28-aa48-47c7-8d2b-877ac89aa1cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70ff496b-b224-4ca6-b531-f63c66c74ab9', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'In what way is Breathing fundamentally different from Cellular Respiration?', 'Breathing is organismal biophysical ventilation; cellular respiration is enzymatic intracellular mitochondrial ATP bioenergetics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99cadd15-301d-4cf9-b9a2-586fc25d5a65', 'Breathing is a physical mechanical process of inhaling O₂ and exhaling CO₂ ; Cellular Respiration is a biochemical intracellular catabolic reaction that breaks down glucose to release energy', true, '70ff496b-b224-4ca6-b531-f63c66c74ab9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce08b088-22d5-4d54-b417-b8e5a93a8e4e', 'Breathing produces food and respiration destroys food', false, '70ff496b-b224-4ca6-b531-f63c66c74ab9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed14ba61-a0e2-48c4-a662-c5ca53d61aa8', 'Breathing only happens in plants', false, '70ff496b-b224-4ca6-b531-f63c66c74ab9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c93f38e3-71e4-4ebf-ab78-ac03b8aa8ff8', 'Both are exactly the same thing', false, '70ff496b-b224-4ca6-b531-f63c66c74ab9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3796a6d-c927-4fcf-960b-b3da72f607f4', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e219d08-a1fb-4494-94a0-0ea9ff61f908', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'f3796a6d-c927-4fcf-960b-b3da72f607f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d97fec6-32f2-4f27-9255-d6659d8d81fa', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'f3796a6d-c927-4fcf-960b-b3da72f607f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c89d162-c097-474e-a3b3-073bbf24042d', '(A) is true, but (R) is false.', false, 'f3796a6d-c927-4fcf-960b-b3da72f607f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e840f674-75ea-4e9e-984c-9533d60f2fd3', '(A) is false, but (R) is true.', false, 'f3796a6d-c927-4fcf-960b-b3da72f607f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c10f4d79-6069-434e-ac52-d22fac0a0a33', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Spot the IMPOSTER in the following animal respiratory adaptations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81d34d1e-ae3d-4236-b51e-a05434c74952', 'Adaptation 1', false, 'c10f4d79-6069-434e-ac52-d22fac0a0a33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13856c38-b01b-4e00-8d28-5267d167f3ff', 'Adaptation 2', false, 'c10f4d79-6069-434e-ac52-d22fac0a0a33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24f67ce0-0238-48c7-b3a2-6f5e955346ca', 'Adaptation 3', false, 'c10f4d79-6069-434e-ac52-d22fac0a0a33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb01b779-45bf-4bb5-9108-524f6372ba11', 'Adaptation 4 (Frog tadpoles breathe through GILLS in aquatic larval stage ; lungs develop upon metamorphosis)', true, 'c10f4d79-6069-434e-ac52-d22fac0a0a33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6acb6d6a-73c4-4002-a421-1799e9a0ac8b', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'In the countercurrent exchange mechanism operating in Fish Gills:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4df9ad81-a104-4248-80a0-b33ebc699764', 'Countercurrent flow maintains a continuous, steep oxygen concentration gradient across the entire length of the capillary bed, extracting over 80% of dissolved oxygen from water', true, '6acb6d6a-73c4-4002-a421-1799e9a0ac8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f39ca9c5-d973-45b4-b81b-a4c9738a6e1c', 'To prevent water from entering the stomach', false, '6acb6d6a-73c4-4002-a421-1799e9a0ac8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f337b488-59fb-4fa1-9738-212153696378', 'To make the fish swim backwards', false, '6acb6d6a-73c4-4002-a421-1799e9a0ac8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c77be45-b7f3-41c7-ac43-c6c72df2c294', 'To warm up the ocean water', false, '6acb6d6a-73c4-4002-a421-1799e9a0ac8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e975be1d-5785-441d-a8b2-863c0d0880d9', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Match Column I (Organisms) with Column II (Primary Respiratory Mechanism / Pathway):
(a) Yeast cells          -> (i) Anaerobic Fermentation yielding Ethanol + CO₂
(b) Active human muscles -> (ii) Anaerobic Glycolysis yielding Lactic Acid
(c) Cockroach            -> (iii) Network of Tracheal tubes carrying air directly to cells
(d) Plant roots          -> (iv) Root hairs absorbing soil air from particle interstices', 'Exact biological mapping: Yeast = ethanol fermentation; Muscle deficit = lactic acid; Insect = tracheae; Root = soil interstitial diffusion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a611558d-1df9-40dd-925e-1e2e73104939', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'e975be1d-5785-441d-a8b2-863c0d0880d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a2ac69-f9b9-41d8-95f7-ce9ec1fea507', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'e975be1d-5785-441d-a8b2-863c0d0880d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffa34a01-6eb4-4fe3-b7b6-7406b5389419', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'e975be1d-5785-441d-a8b2-863c0d0880d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72a9eedc-136e-4423-b44d-684b053ff615', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'e975be1d-5785-441d-a8b2-863c0d0880d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6830ffd-5cef-4242-803d-f9bbbf1a4a6c', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Read the statements regarding plant respiration:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3520805e-0e41-4d37-b49d-e52b1f79f862', 'Statements 1 and 2 only', true, 'f6830ffd-5cef-4242-803d-f9bbbf1a4a6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('480ae227-6b6c-43e1-9a57-16fc662a05dd', 'Statements 2 and 3 only', false, 'f6830ffd-5cef-4242-803d-f9bbbf1a4a6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c664f0bf-1c38-41d8-a120-8618d337b56f', 'Statements 1 and 3 only', false, 'f6830ffd-5cef-4242-803d-f9bbbf1a4a6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d8ce5e0-c4bf-4555-bc1a-241fdb644904', 'All Statements 1, 2, and 3', false, 'f6830ffd-5cef-4242-803d-f9bbbf1a4a6c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1ff343a-3d60-4ad5-8d54-3fb78c2b77e4', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'What is the structural and physiological significance of the microscopic ''Alveoli'' (air sacs) in human lungs?', 'Human lungs contain ~300-500 million alveoli, creating an enormous ~80 m² microvascular surface area for Fickian gas diffusion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9344fc5c-7193-4925-a5d4-be58998d9aad', 'Millions of thin-walled alveoli provide an immense total surface area (~80 m², size of a tennis court) densely wrapped in capillaries for rapid gas diffusion', true, 'a1ff343a-3d60-4ad5-8d54-3fb78c2b77e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4985fc29-8147-42a0-a22a-44949d5b0f47', 'They store food inside the lungs', false, 'a1ff343a-3d60-4ad5-8d54-3fb78c2b77e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd1df423-1540-4123-83d8-758b0595670f', 'They pump blood directly to the brain', false, 'a1ff343a-3d60-4ad5-8d54-3fb78c2b77e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46a3d491-50e3-44ff-87d2-a0c412772ac4', 'They filter water out of blood', false, 'a1ff343a-3d60-4ad5-8d54-3fb78c2b77e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c045b86f-33f9-4bdf-83e6-1f847d3bec5b', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Why do insect tracheal respiratory systems impose a strict physical upper limit on the maximum body size an insect can achieve?', 'Diffusion kinetics (scaling as distance squared) restrict effective tracheal oxygen delivery to small body lengths under modern 21% atmospheric O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('713fd0ac-6551-4499-8dcc-002ae869a65a', 'Tracheal gas transport relies primarily on passive gaseous diffusion through narrow tubes; over longer body distances (> a few centimeters), oxygen diffusion slows down drastically', true, 'c045b86f-33f9-4bdf-83e6-1f847d3bec5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b30f105a-7a08-435f-979d-70eb141f2588', 'Because insect legs cannot support weight', false, 'c045b86f-33f9-4bdf-83e6-1f847d3bec5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6786de24-8b47-4e90-b725-06fffc647274', 'Because insects have no eyes', false, 'c045b86f-33f9-4bdf-83e6-1f847d3bec5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d6d8b8a-8bf2-47ea-aaa6-9cf536047e11', 'Because insects do not eat meat', false, 'c045b86f-33f9-4bdf-83e6-1f847d3bec5b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34a13a7b-e4d2-416d-979e-ac80e78bc4f5', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Consider four physiological states:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a1df232-a1a3-4556-9970-67182d76ad1e', '1 < 4 < 2 < 3', true, '34a13a7b-e4d2-416d-979e-ac80e78bc4f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a55068e-90b3-44e7-8cb5-604e32713b27', '3 < 2 < 4 < 1', false, '34a13a7b-e4d2-416d-979e-ac80e78bc4f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d87f296f-0f40-4c9e-85bc-4439ff23a31d', '4 < 1 < 2 < 3', false, '34a13a7b-e4d2-416d-979e-ac80e78bc4f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa6ced7b-59b9-47d7-ace5-14610355df2a', '2 < 4 < 1 < 3', false, '34a13a7b-e4d2-416d-979e-ac80e78bc4f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31a8574c-9650-48d2-8d76-ece67a9c9a92', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Why does Carbon Monoxide (CO) gas poisoning cause rapid asphyxiation and death even when ambient oxygen is present?', 'CO binds competitively to heme iron with >200× affinity, stabilizing the R-state and preventing allosteric O₂ delivery to brain and heart.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9dfc315-2979-477b-9645-6ee47f2a8f22', 'Carbon monoxide has an affinity for Hemoglobin over 200 times higher than oxygen, forming stable Carboxyhemoglobin and completely blocking oxygen transport to tissues', true, '31a8574c-9650-48d2-8d76-ece67a9c9a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77960d5c-15a3-4f0f-93b1-7631a9caa621', 'CO freezes the lungs instantly', false, '31a8574c-9650-48d2-8d76-ece67a9c9a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2d0ecfc-65cc-4223-a738-9c315f61dae4', 'CO destroys all bones in the body', false, '31a8574c-9650-48d2-8d76-ece67a9c9a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('349c7e05-d25c-4134-be7b-682762e03a16', 'CO turns blood into water', false, '31a8574c-9650-48d2-8d76-ece67a9c9a92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73e34b9c-3241-4496-8f75-d2cfa9e56683', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'What is ''Oxygen Debt'' incurred during strenuous anaerobic exercise?', 'Excess Post-exercise Oxygen Consumption (EPOC / oxygen debt) metabolizes lactic acid via the Cori cycle in hepatocytes and restabilizes homeostatic reserves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf2af804-de0a-49ab-a0f8-fb6917a3465c', 'The extra volume of oxygen required after exercise to oxidize accumulated lactic acid in the liver back into pyruvate/glucose and replenish ATP/phosphocreatine reserves', true, '73e34b9c-3241-4496-8f75-d2cfa9e56683');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4498a46-e2c2-43b1-8131-fbd896a12649', 'The amount of money paid for oxygen cylinders', false, '73e34b9c-3241-4496-8f75-d2cfa9e56683');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c1cc3b6-b806-4388-b78f-2561a2bea2f3', 'The loss of breath during swimming', false, '73e34b9c-3241-4496-8f75-d2cfa9e56683');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e89f002-990a-4fd5-8d52-70f4284e8943', 'The oxygen stored in the stomach', false, '73e34b9c-3241-4496-8f75-d2cfa9e56683');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1566f0c6-287d-44ce-970f-33c94887995d', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'How do mangrove plants (like Rhizophora) growing in oxygen-poor, saline waterlogged coastal marshes breathe?', 'Halophytic mangroves deploy negatively geotropic pneumatophores (respiratory knee-roots) equipped with lenticels and aerenchyma for subterranean aeration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97d25631-d8fb-4200-9137-35bcbdd0a6e5', 'They produce specialized vertical aerial roots called ''Pneumatophores'' (breathing roots) that grow upwards out of the water and mud with lenticels to intake air', true, '1566f0c6-287d-44ce-970f-33c94887995d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ad977cd-fa4b-4c0d-843a-7a59c2ead07c', 'They absorb oxygen through ocean fish', false, '1566f0c6-287d-44ce-970f-33c94887995d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03a81e23-3644-4573-a710-4fa78c417838', 'They do not require oxygen', false, '1566f0c6-287d-44ce-970f-33c94887995d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03b88379-a17a-4c3c-a255-2637e4170f21', 'They grow only under sand', false, '1566f0c6-287d-44ce-970f-33c94887995d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04506da6-e4a5-4178-a364-81651b2fb36a', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'What overarching bioenergetic reality is established in Chapter 6 of NCERT Class 7 Science?', 'Chapter 6 illuminates the bioenergetic unity of life: metabolic breakdown of glucose to generate ATP through aerobic and anaerobic evolutionary pathways.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dea524a2-d203-4542-9ee6-42ff83e5d637', 'Respiration is the universal cellular engine of all biological life, converting chemical potential energy stored in organic nutrients into kinetic metabolic ATP that powers growth, repair, movement, and physiological homeostasis across every living kingdom', true, '04506da6-e4a5-4178-a364-81651b2fb36a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61ca5d14-cad5-4466-b64f-a3fceff7e08a', 'That only animals need energy to survive', false, '04506da6-e4a5-4178-a364-81651b2fb36a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7780592c-7ab7-4eed-ac43-89ceb81a8b0a', 'That respiration only occurs during running', false, '04506da6-e4a5-4178-a364-81651b2fb36a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('124b53c1-ed4a-4c4f-9d46-b4dc75f74e62', 'That breathing and burning wood are identical processes', false, '04506da6-e4a5-4178-a364-81651b2fb36a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d751b04-fd0e-4fd8-bf15-7b15e0c51a0b', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'A line segment connecting a vertex of a triangle to the MIDPOINT of the opposite side is called a:', 'A median connects a triangle''s vertex to the midpoint of the opposing side. Every triangle has 3 medians meeting at the centroid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb2e29c5-7cc9-46d1-a506-ebb26e97fa69', 'Median', true, '0d751b04-fd0e-4fd8-bf15-7b15e0c51a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a957655f-b012-4491-a274-5b597d9691fd', 'Altitude', false, '0d751b04-fd0e-4fd8-bf15-7b15e0c51a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8af3b0a-9e6b-44d8-bd1d-6d048f955029', 'Angle Bisector', false, '0d751b04-fd0e-4fd8-bf15-7b15e0c51a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca3b96ea-fcc1-4388-acaa-09e1751b21dd', 'Perpendicular Bisector', false, '0d751b04-fd0e-4fd8-bf15-7b15e0c51a0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c02fd61b-33c9-424f-ab67-d043802e0fe0', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'The perpendicular line segment drawn from a vertex of a triangle to the opposite side (or its extension) is called an:', 'An altitude is the perpendicular line dropped from a vertex to the opposite base line.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab2e4a12-abf0-4ed4-b2f4-3e1e40b7add4', 'Altitude (or Height)', true, 'c02fd61b-33c9-424f-ab67-d043802e0fe0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f56a3066-7cde-4f3f-98cf-39657720c923', 'Median', false, 'c02fd61b-33c9-424f-ab67-d043802e0fe0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2bb361e-76a8-4552-b492-e32baf67f4dc', 'Hypotenuse', false, 'c02fd61b-33c9-424f-ab67-d043802e0fe0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('277b05a8-3122-4c4d-991c-06197e4f4355', 'Diagonal', false, 'c02fd61b-33c9-424f-ab67-d043802e0fe0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c35eb50-5c0d-47e3-8ebf-046fb38ce880', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'What is the sum of the measures of all three interior angles of ANY triangle on a flat plane (Angle Sum Property)?', 'Euclidean angle sum property: ∠A + ∠B + ∠C = 180° for all triangles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3f644d7-8698-4564-8aba-b77b2997f3dd', '180° (Two Right Angles)', true, '5c35eb50-5c0d-47e3-8ebf-046fb38ce880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e73b9479-d8ce-40d7-b758-cc306017d4e6', '360°', false, '5c35eb50-5c0d-47e3-8ebf-046fb38ce880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d65d2e0-aca0-410c-b8d1-7e5b60f759c0', '90°', false, '5c35eb50-5c0d-47e3-8ebf-046fb38ce880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('645dddcd-c9bf-4204-85ac-5270791e39d6', '270°', false, '5c35eb50-5c0d-47e3-8ebf-046fb38ce880');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca403798-1ad3-4b60-b7be-cec2f46dc468', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'According to the Exterior Angle Property of a triangle, an exterior angle is ALWAYS equal to:', 'Exterior Angle Property: ∠Ext = ∠Int_opp1 + ∠Int_opp2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88e82ea4-e1d9-4c59-b9a6-f6dd6177cb41', 'The sum of its two interior opposite angles', true, 'ca403798-1ad3-4b60-b7be-cec2f46dc468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc649896-22c9-4211-8233-8ce11ffd5ec8', '180° minus the adjacent angle only', false, 'ca403798-1ad3-4b60-b7be-cec2f46dc468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42cc6d07-0fee-47d7-be74-cc021c05ff2a', '90°', false, 'ca403798-1ad3-4b60-b7be-cec2f46dc468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc83012f-6397-4280-a42a-b462fea47b3b', 'The sum of all three angles', false, 'ca403798-1ad3-4b60-b7be-cec2f46dc468');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe01fdf2-069c-494d-832c-a1cf4ec82193', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'In an Equilateral Triangle, what is the measure of EACH of the three interior angles?', 'All three sides and all three angles are equal in an equilateral triangle: 180° / 3 = 60°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73bb84ca-7d33-4cbf-90f2-43112fbbf0e3', '60° (All three angles are strictly equal: 180° / 3 = 60°)', true, 'fe01fdf2-069c-494d-832c-a1cf4ec82193');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('637eb5c8-c21e-4ee3-8660-2ff0db892262', '45°', false, 'fe01fdf2-069c-494d-832c-a1cf4ec82193');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b9fa8d-a7f6-4958-9be6-7766c36716af', '90°', false, 'fe01fdf2-069c-494d-832c-a1cf4ec82193');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e9d98c0-33b2-417b-aed8-149fbf7e82a5', '30°', false, 'fe01fdf2-069c-494d-832c-a1cf4ec82193');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75e81c77-cfd6-46de-afbd-8843faac69c7', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'In an Isosceles Triangle, if two sides are equal in length, what is true about the angles OPPOSITE to those equal sides?', 'Base angles theorem: in an isosceles triangle, angles opposite to equal sides are congruent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34a63ee3-fe3c-494e-a164-cceea1a5c387', 'The angles opposite to equal sides are ALWAYS equal in measure', true, '75e81c77-cfd6-46de-afbd-8843faac69c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7ca1e5d-6551-43db-95f0-a0ff3770c9e4', 'They sum to 90°', false, '75e81c77-cfd6-46de-afbd-8843faac69c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07a8a86a-24d1-4082-821c-68ffcf2a1f5a', 'They are unequal', false, '75e81c77-cfd6-46de-afbd-8843faac69c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d118c95-357c-452f-b0ee-480a58138422', 'One is always 90°', false, '75e81c77-cfd6-46de-afbd-8843faac69c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58ee1b93-8111-45ce-880a-cbc55f50fc69', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'According to the Triangle Inequality Property, the sum of the lengths of any two sides of a triangle must ALWAYS be:', 'Triangle inequality axiom: for any valid triangle with side lengths a, b, c: a + b > c, b + c > a, and c + a > b.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b0a9ee5-24f9-4f98-8efc-9cd9e8f3c914', 'Strictly GREATER than the length of the third side (a + b > c)', true, '58ee1b93-8111-45ce-880a-cbc55f50fc69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aa23d47-8367-4c1b-abee-b2ebcc44a6cd', 'Equal to the third side', false, '58ee1b93-8111-45ce-880a-cbc55f50fc69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2ba4896-d5c4-40b2-b5e4-3f1f73875969', 'Less than the third side', false, '58ee1b93-8111-45ce-880a-cbc55f50fc69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0a02e2c-2d89-490b-ab61-97358966fc6b', 'Zero', false, '58ee1b93-8111-45ce-880a-cbc55f50fc69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a16b17d-3eb6-4ee3-8416-e69cd52f1485', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'In a Right-Angled Triangle, the side opposite to the 90° right angle is the longest side, called the:', 'The hypotenuse is the side opposing the 90° right angle and is the longest side of a right-angled triangle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3dc8742-0d9c-470f-8ef1-e58404b9a527', 'Hypotenuse', true, '2a16b17d-3eb6-4ee3-8416-e69cd52f1485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26c670bf-edf2-4af2-81b0-2afb77d7bb7e', 'Base', false, '2a16b17d-3eb6-4ee3-8416-e69cd52f1485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11b69a58-11c4-4ce7-8621-449b227fe7cd', 'Altitude', false, '2a16b17d-3eb6-4ee3-8416-e69cd52f1485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b32f0ef9-931f-448c-b35d-a420ed2860e9', 'Median', false, '2a16b17d-3eb6-4ee3-8416-e69cd52f1485');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7cc1cd7-5b53-4c16-8968-309359bc0e68', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'What is the famous Pythagoras Theorem formula for a right-angled triangle with legs a, b and hypotenuse c?', 'Pythagorean Theorem: in any right-angled triangle, Hypotenuse² = Perpendicular² + Base² (c² = a² + b²).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf0f10bb-b8bf-409e-9d03-021f00133f5a', 'a² + b² = c² (Hypotenuse² = Base² + Perpendicular²)', true, 'c7cc1cd7-5b53-4c16-8968-309359bc0e68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84809b7e-77ee-45fe-9796-2a903904de85', 'a + b = c', false, 'c7cc1cd7-5b53-4c16-8968-309359bc0e68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('342f6ab1-c46b-453e-8df1-38ea4166815c', 'a² - b² = c²', false, 'c7cc1cd7-5b53-4c16-8968-309359bc0e68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c79477aa-1455-437d-a70f-45357d3275b8', 'a × b = c²', false, 'c7cc1cd7-5b53-4c16-8968-309359bc0e68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53aae153-d24d-4b58-bb9e-6364f89106de', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'Two angles of a triangle are 50° and 70°. Find the measure of the third angle:', 'Third angle = 180° - (50° + 70°) = 180° - 120° = 60°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1116c257-162b-41b9-8d12-630e05229699', '60° (180° - (50° + 70°) = 180° - 120° = 60°)', true, '53aae153-d24d-4b58-bb9e-6364f89106de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0d784f6-659e-453b-802b-7f7924bd303e', '50°', false, '53aae153-d24d-4b58-bb9e-6364f89106de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce741662-953d-43d7-bb78-3c3638846003', '70°', false, '53aae153-d24d-4b58-bb9e-6364f89106de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1e64a83-4512-413d-8de7-15014e671e82', '80°', false, '53aae153-d24d-4b58-bb9e-6364f89106de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60fd61df-21d4-42d1-addd-e2c9c06c0bb6', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'An exterior angle of a triangle is 110°, and one of the interior opposite angles is 40°. Find the other interior opposite angle:', 'Ext angle = Int1 + Int2 → 110° = 40° + x → x = 70°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ba60938-420b-47e0-af81-64155301f36a', '70° (110° - 40° = 70°)', true, '60fd61df-21d4-42d1-addd-e2c9c06c0bb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e24dc1d7-92d4-44a5-aceb-be760d13f4f5', '80°', false, '60fd61df-21d4-42d1-addd-e2c9c06c0bb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d360002-7893-4554-a94d-0101c26d872d', '60°', false, '60fd61df-21d4-42d1-addd-e2c9c06c0bb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a601e57-5812-4a47-a8c8-38bc9c8b6faf', '50°', false, '60fd61df-21d4-42d1-addd-e2c9c06c0bb6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65a63d36-f7f4-4f69-87d3-5f2bce613a5e', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'Can a triangle have two RIGHT angles (90° + 90°)?', 'Two 90° angles sum to 180°, which violates the angle sum property since the third angle must be strictly positive.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac53efc6-3037-4ff3-85dc-faef7e0b35f8', 'No, because two right angles sum to 180°, leaving 0° for the third angle, making a triangle impossible', true, '65a63d36-f7f4-4f69-87d3-5f2bce613a5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da7fd44c-9694-4abe-b6d5-7b32a186d08b', 'Yes, in right isosceles triangles', false, '65a63d36-f7f4-4f69-87d3-5f2bce613a5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eca7d716-9a2a-4047-86d6-94bf21ac2354', 'Yes, in large triangles', false, '65a63d36-f7f4-4f69-87d3-5f2bce613a5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e59fd60-cf4b-4e28-83d9-63ccb2450e83', 'Always yes', false, '65a63d36-f7f4-4f69-87d3-5f2bce613a5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1b9c198-a979-4475-a9e1-0b23204018c9', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'The three interior angles of a triangle are in the ratio 1 : 2 : 3. Find the measure of each angle:', '6x = 180° → x = 30°. Angles are 1(30) = 30°, 2(30) = 60°, and 3(30) = 90°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8818d332-8623-4efb-9438-65a395883951', '30°, 60°, and 90° (x + 2x + 3x = 180° ⇒ 6x = 180° ⇒ x = 30° ⇒ 30°, 60°, 90°)', true, 'f1b9c198-a979-4475-a9e1-0b23204018c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59367b93-16ce-4632-a8eb-6769ad8010be', '20°, 40°, 120°', false, 'f1b9c198-a979-4475-a9e1-0b23204018c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09fb4363-81ef-45df-996b-77707b767435', '45°, 45°, 90°', false, 'f1b9c198-a979-4475-a9e1-0b23204018c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f8bd32c-066b-44d0-a259-1aa5dfc25a5c', '30°, 75°, 75°', false, 'f1b9c198-a979-4475-a9e1-0b23204018c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b96fa39-fa2a-4015-9f25-8d8ba5c4a4df', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In an Isosceles Triangle, the vertex angle is 40°. What is the measure of each equal base angle?', '2x + 40° = 180° → 2x = 140° → x = 70°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea9be287-7f96-483c-80ae-133e525abf34', '70° each ((180° - 40°) / 2 = 140° / 2 = 70°)', true, '8b96fa39-fa2a-4015-9f25-8d8ba5c4a4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa2abe77-8836-4dde-b022-69d45492718b', '60° each', false, '8b96fa39-fa2a-4015-9f25-8d8ba5c4a4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21439380-a0d1-4b78-b590-d01410d949cd', '80° each', false, '8b96fa39-fa2a-4015-9f25-8d8ba5c4a4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('307aad8e-5d83-41b5-a78a-044ae01f2b60', '50° each', false, '8b96fa39-fa2a-4015-9f25-8d8ba5c4a4df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bc84f55-fa17-44c9-b2a8-ea2869bafca8', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'Which of the following sets of side lengths CAN form a valid triangle?', 'Only 6, 8, 10 satisfies the strict triangle inequality theorem (6 + 8 = 14 > 10).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51081f45-626e-452c-a519-160609652008', '6 cm, 8 cm, 10 cm (Since 6 + 8 > 10, 6 + 10 > 8, and 8 + 10 > 6)', true, '5bc84f55-fa17-44c9-b2a8-ea2869bafca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c90a019e-864c-42f9-92cf-30d3a56aca7e', '2 cm, 3 cm, 6 cm (2 + 3 = 5 < 6, impossible)', false, '5bc84f55-fa17-44c9-b2a8-ea2869bafca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d8b1e02-e4c4-46f3-a749-179a9233cd0b', '3 cm, 4 cm, 7 cm (3 + 4 = 7, not strictly greater, impossible)', false, '5bc84f55-fa17-44c9-b2a8-ea2869bafca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3463325-a60e-445b-b01e-25b5d57bf652', '1 cm, 2 cm, 5 cm (1 + 2 = 3 < 5, impossible)', false, '5bc84f55-fa17-44c9-b2a8-ea2869bafca8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f10529cd-77f8-499a-921d-e3d089281af4', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In a right-angled triangle, the lengths of the two legs are 3 cm and 4 cm. What is the length of the hypotenuse?', 'c = √(3² + 4²) = √(9 + 16) = √25 = 5 cm (classic 3-4-5 Pythagorean triplet).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37857bf4-1319-402d-9f3e-d63095d5be24', '5 cm (Hypotenuse = √(3² + 4²) = √(9 + 16) = √25 = 5 cm)', true, 'f10529cd-77f8-499a-921d-e3d089281af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f364379f-32e8-48b0-bb42-27571fc4f634', '7 cm', false, 'f10529cd-77f8-499a-921d-e3d089281af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa22bd54-893c-481f-879d-76dd990c4985', '6 cm', false, 'f10529cd-77f8-499a-921d-e3d089281af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34cc0a39-6a62-4cb9-bd21-4d2609a6d7e0', '8 cm', false, 'f10529cd-77f8-499a-921d-e3d089281af4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80a978a7-3ac1-45b2-97d4-db474dc0fa45', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'A 15 m long ladder reaches a window 12 m high from the ground on placing it against a wall. Find the distance of the foot of the ladder from the wall:', 'Base = √(15² - 12²) = √(225 - 144) = √81 = 9 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84a777fe-8b2c-40a2-8b81-87a41d1ab932', '9 m (Distance = √(15² - 12²) = √(225 - 144) = √81 = 9 m)', true, '80a978a7-3ac1-45b2-97d4-db474dc0fa45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e68cc06-c654-4d6d-abdc-f08a9991697c', '6 m', false, '80a978a7-3ac1-45b2-97d4-db474dc0fa45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('233381ac-478a-4f0c-9659-da55e457fe90', '8 m', false, '80a978a7-3ac1-45b2-97d4-db474dc0fa45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d93f00-eefe-45c9-a0b3-e1a8f50426ee', '10 m', false, '80a978a7-3ac1-45b2-97d4-db474dc0fa45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7ef21c5-cb7b-45d2-ae68-4f21f52e1024', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'The lengths of two sides of a triangle are 12 cm and 15 cm. Between what two whole numbers must the length of the third side lie?', 'Third side range: (15 - 12) < side < (15 + 12) → 3 cm < x < 27 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f7f49aa-dfe7-4349-96d7-9bbbbb3afd93', 'Between 3 cm and 27 cm (Difference: 15 - 12 = 3 cm < third side < Sum: 15 + 12 = 27 cm)', true, 'a7ef21c5-cb7b-45d2-ae68-4f21f52e1024');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('963e0f14-8a73-4612-9309-616a0e28bc99', 'Between 12 cm and 15 cm', false, 'a7ef21c5-cb7b-45d2-ae68-4f21f52e1024');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38cbce09-292c-4655-a6e8-7a6f7bf09e27', 'Between 0 cm and 12 cm', false, 'a7ef21c5-cb7b-45d2-ae68-4f21f52e1024');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71f6bfbd-9325-4539-b9f0-fcc64c4cf72f', 'Between 5 cm and 30 cm', false, 'a7ef21c5-cb7b-45d2-ae68-4f21f52e1024');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd50d89d-5d24-4ae4-b1d8-fa9f31685264', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'A tree broke at a height of 5 m from the ground and its top touched the ground at a distance of 12 m from the base of the tree. Find the ORIGINAL full height of the tree:', 'Hypotenuse = √(5² + 12²) = 13 m. Total original tree height = standing trunk (5 m) + fallen crown (13 m) = 18 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25db76b8-d8af-41ae-9141-aa340dcb5ef0', '18 m (Broken broken part = √(5² + 12²) = √(25 + 144) = √169 = 13 m ; Total height = 5 + 13 = 18 m)', true, 'cd50d89d-5d24-4ae4-b1d8-fa9f31685264');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec156564-a679-43fb-a575-3c541b3bbfa0', '17 m', false, 'cd50d89d-5d24-4ae4-b1d8-fa9f31685264');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5cdc6b3-2404-4cfd-b31b-3bb4f28403c0', '13 m', false, 'cd50d89d-5d24-4ae4-b1d8-fa9f31685264');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3839d88-5147-490f-b6b3-25c93eac5bd6', '20 m', false, 'cd50d89d-5d24-4ae4-b1d8-fa9f31685264');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35fa281e-330b-4b3b-96b9-c2cd9d34e94a', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In ΔABC, if ∠B = 35° and ∠C = 55°, which of the following is true?', '∠A = 180° - 90° = 90°. The right angle is at A, so opposite side BC is the hypotenuse: AB² + AC² = BC².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2f3f680-a6c1-41d4-8619-f7024ff3f754', 'AB² + BC² = AC² is FALSE, but AB² + AC² = BC² is TRUE (Since ∠A = 180° - (35°+55°) = 90°, so BC is the hypotenuse: AB² + AC² = BC²)', true, '35fa281e-330b-4b3b-96b9-c2cd9d34e94a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cebd4b80-68d1-422d-a58d-26d2a0cdb5b0', 'AB² + BC² = AC²', false, '35fa281e-330b-4b3b-96b9-c2cd9d34e94a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c9b1c79-2bf9-4b17-8de2-c07036097eeb', 'BC² + AC² = AB²', false, '35fa281e-330b-4b3b-96b9-c2cd9d34e94a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6bebb84-6cec-4c39-a782-504aacbd4bb5', 'AB + BC = AC', false, '35fa281e-330b-4b3b-96b9-c2cd9d34e94a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23d69005-0367-4e15-8fd4-42015f1472bb', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'Find the perimeter of the rectangle whose length is 40 cm and diagonal is 41 cm:', 'Width = √(41² - 40²) = √81 = 9 cm. Perimeter = 2(l + w) = 2(40 + 9) = 98 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c02e9433-1400-40e0-9996-01847f87c375', '98 cm (Breadth = √(41² - 40²) = √(1681 - 1600) = √81 = 9 cm ; Perimeter = 2(40 + 9) = 2(49) = 98 cm)', true, '23d69005-0367-4e15-8fd4-42015f1472bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d2032d4-44b5-4656-8f74-fcc4ba846981', '82 cm', false, '23d69005-0367-4e15-8fd4-42015f1472bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34767919-4c02-4acc-8bef-42f73371f254', '100 cm', false, '23d69005-0367-4e15-8fd4-42015f1472bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81a5f5d2-8620-4c2d-9da5-a3919b21f7b6', '90 cm', false, '23d69005-0367-4e15-8fd4-42015f1472bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90ecdde2-1723-4b1b-8afd-6427e952ad2b', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'The diagonals of a rhombus measure 16 cm and 12 cm. Find its perimeter:', 'Rhombus side = √(8² + 6²) = 10 cm. Perimeter = 4 × 10 = 40 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb417af6-aa42-407c-8f0d-9430e93eca0a', '40 cm (Diagonals bisect at 90°: half-lengths are 8 cm and 6 cm ; Side = √(8² + 6²) = √(64 + 36) = √100 = 10 cm ; Perimeter = 4 × 10 = 40 cm)', true, '90ecdde2-1723-4b1b-8afd-6427e952ad2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05928550-7da2-434d-8d9f-88d1cfc933dd', '28 cm', false, '90ecdde2-1723-4b1b-8afd-6427e952ad2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb68106a-d3b8-4239-95ac-382206952cfd', '48 cm', false, '90ecdde2-1723-4b1b-8afd-6427e952ad2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59ee6e16-e489-48df-b405-834fe5dddbb5', '56 cm', false, '90ecdde2-1723-4b1b-8afd-6427e952ad2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57d7e007-56b0-41ff-85af-94db574459bb', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'Can an OBTUSE-ANGLED triangle have an altitude that lies OUTSIDE the triangle?', 'In an obtuse triangle, altitudes drawn from acute vertices fall on extended bases outside the triangular boundary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7c5f749-0b0b-4799-80a1-27e604e76ec5', 'Yes, two of the altitudes in an obtuse-angled triangle fall outside the triangle onto the extended opposite sides', true, '57d7e007-56b0-41ff-85af-94db574459bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e07c0ac-eb80-4e9f-824e-4cd0c5a7fc0a', 'No, altitudes are always strictly inside', false, '57d7e007-56b0-41ff-85af-94db574459bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('928938fb-84f4-442a-b72d-47a1fad03fb0', 'Only in right triangles', false, '57d7e007-56b0-41ff-85af-94db574459bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b2e8c54-d34d-4495-a5db-d3df82c4ff55', 'Never', false, '57d7e007-56b0-41ff-85af-94db574459bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf72666d-7d38-4d7e-acf8-9337bec989e0', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In ΔPQR, D is the midpoint of side QR. What is line segment PM (where PM ⊥ QR) and line segment PD?', 'PM is perpendicular (altitude); PD joins vertex P to midpoint D of base QR (median).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82536a00-d7c7-4ee0-8fec-95658b686b21', 'PM is an ALTITUDE ; PD is a MEDIAN', true, 'cf72666d-7d38-4d7e-acf8-9337bec989e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da351ce1-e16c-4a62-865c-eebddaf2a5ba', 'PM is a median ; PD is an altitude', false, 'cf72666d-7d38-4d7e-acf8-9337bec989e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffdd7e03-c80f-4724-b74c-3fd7398e2527', 'Both are medians', false, 'cf72666d-7d38-4d7e-acf8-9337bec989e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66d9be54-9ddd-4676-9067-ca41044db923', 'Both are altitudes', false, 'cf72666d-7d38-4d7e-acf8-9337bec989e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a723d45-fd04-4b35-b5ea-d1a2e4a582d0', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'An exterior angle of a triangle is 120°, and the two interior opposite angles are EQUAL to each other. Find the measure of each interior opposite angle:', 'x + x = 120° → 2x = 120° → x = 60°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8b2f178-2262-41f7-bb59-c7cd4404205f', '60° each (2x = 120° ⇒ x = 60°)', true, '4a723d45-fd04-4b35-b5ea-d1a2e4a582d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a7e434f-f4db-4fe6-a6e0-44ca0b707ba2', '50° each', false, '4a723d45-fd04-4b35-b5ea-d1a2e4a582d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3023778c-b4df-4128-8896-21f72b5d8d10', '40° each', false, '4a723d45-fd04-4b35-b5ea-d1a2e4a582d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed28830a-12dd-4966-8c7f-351b2e4dd3f1', '70° each', false, '4a723d45-fd04-4b35-b5ea-d1a2e4a582d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a66a526e-4468-4fcd-982a-bd74b9415196', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'One of the acute angles of a right-angled triangle is 35°. What is the measure of the other acute angle?', 'The two acute angles in a right-angled triangle are complementary: 90° - 35° = 55°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c62c92ef-8122-4504-9a32-56aca26f4c5e', '55° (90° - 35° = 55°)', true, 'a66a526e-4468-4fcd-982a-bd74b9415196');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7b81ad2-5d46-4f29-9a1a-8d5d733d44f1', '45°', false, 'a66a526e-4468-4fcd-982a-bd74b9415196');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cb28016-56be-4feb-8dda-a0994bec8ef0', '65°', false, 'a66a526e-4468-4fcd-982a-bd74b9415196');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12aff24f-fa2b-40bf-bd39-e67fcfcbe494', '35°', false, 'a66a526e-4468-4fcd-982a-bd74b9415196');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffd6ab89-1a71-4f33-891b-ddf80c70e265', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In an equilateral triangle ΔABC, an altitude AD is drawn from A to BC. What special property does AD have?', 'Symmetry of equilateral triangles: altitude, median, angle bisector, and perpendicular bisector coincide along the same axis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5c5aee1-c770-455e-90db-42921985d897', 'In an equilateral triangle, Altitude AD is ALSO the Median (it bisects the opposite side BC) and also the Angle Bisector of ∠A', true, 'ffd6ab89-1a71-4f33-891b-ddf80c70e265');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d49f0ab-8116-42d3-9c46-f08028e1d912', 'AD only measures 1 cm', false, 'ffd6ab89-1a71-4f33-891b-ddf80c70e265');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f0675e0-a850-48aa-b0a8-2abe0c3f44b2', 'AD is parallel to BC', false, 'ffd6ab89-1a71-4f33-891b-ddf80c70e265');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35c5555a-0a4e-4b3a-af66-b399661efba9', 'AD lies outside the triangle', false, 'ffd6ab89-1a71-4f33-891b-ddf80c70e265');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3afb53b8-8105-4c48-a938-daf3f7254e23', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'Which of the following is a classic PYTHAGOREAN TRIPLET?', '5² + 12² = 25 + 144 = 169 = 13², confirming (5, 12, 13) is a primitive Pythagorean triplet.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b4a35cb-a99a-4fa3-bb76-38128835b17a', '(5, 12, 13) since 5² + 12² = 25 + 144 = 169 = 13²', true, '3afb53b8-8105-4c48-a938-daf3f7254e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3210ad6-2e23-4c12-a501-249dd083fab5', '(4, 5, 6)', false, '3afb53b8-8105-4c48-a938-daf3f7254e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94ce1b4b-da37-44dc-98d4-f80d1950e6eb', '(2, 3, 4)', false, '3afb53b8-8105-4c48-a938-daf3f7254e23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19942c40-5ad1-4842-9884-e4b92cde8882', '(6, 7, 8)', false, '3afb53b8-8105-4c48-a938-daf3f7254e23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8aaa2f18-cf6a-478b-a727-3f3216de3a06', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d064950-75ec-4698-81ae-cf0e69d614df', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '8aaa2f18-cf6a-478b-a727-3f3216de3a06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8828b69-5f2b-4e95-a96d-c5564c596899', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '8aaa2f18-cf6a-478b-a727-3f3216de3a06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd71beea-4068-4549-9eec-bf54f1729b9a', '(A) is true, but (R) is false.', false, '8aaa2f18-cf6a-478b-a727-3f3216de3a06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d641e141-15bc-456d-a53d-0e5e7f580c25', '(A) is false, but (R) is true.', false, '8aaa2f18-cf6a-478b-a727-3f3216de3a06');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2b0da35-aeb3-43a9-bd71-208dee81fa8f', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Spot the IMPOSTER in the following geometric triangle theorems:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9591a8e0-9ee3-455e-b846-268737503b27', 'Theorem 1', false, 'c2b0da35-aeb3-43a9-bd71-208dee81fa8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2e13b55-9498-4427-b02b-25e38322e416', 'Theorem 2', false, 'c2b0da35-aeb3-43a9-bd71-208dee81fa8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5614ed1-cecd-49c3-9537-4b12f9189f58', 'Theorem 3', false, 'c2b0da35-aeb3-43a9-bd71-208dee81fa8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('770006dc-ac71-42de-ba2e-1947ddf37db3', 'Theorem 4 (In any triangle, the LONGEST side is opposite to the LARGEST angle, not the smallest)', true, 'c2b0da35-aeb3-43a9-bd71-208dee81fa8f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f740a27-af20-4609-88c2-b225d87f1126', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'In ΔABC, AM is a median on side BC. Prove that:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9713f060-c408-47cb-a9c4-3c390327737c', 'In ΔABM: AB + BM > AM ; In ΔACM: AC + MC > AM ; Adding both: AB + (BM + MC) + AC > 2AM ⇒ AB + BC + CA > 2AM', true, '3f740a27-af20-4609-88c2-b225d87f1126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2d12673-abc3-4874-b512-dc4ada566c21', 'Because all sides of ΔABC are equal to AM', false, '3f740a27-af20-4609-88c2-b225d87f1126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfe7c267-d46d-438b-86eb-9bfd1534ac52', 'Because AM is perpendicular to BC', false, '3f740a27-af20-4609-88c2-b225d87f1126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2638d0b2-15de-4abd-9ba0-24158815a8ed', 'Because triangles have no perimeter', false, '3f740a27-af20-4609-88c2-b225d87f1126');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d618c598-42e9-4598-b02a-9d81997863d3', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Match Column I (Triangle Concurrence Centers) with Column II (Defining Line Intersections):
(a) Centroid      -> (i) Concurrence point of all 3 Medians (divides each median in 2:1 ratio)
(b) Orthocentre   -> (ii) Concurrence point of all 3 Altitudes
(c) Incentre      -> (iii) Concurrence point of all 3 Internal Angle Bisectors
(d) Circumcentre  -> (iv) Concurrence point of all 3 Perpendicular Bisectors of sides', 'Centroid = medians; Orthocentre = altitudes; Incentre = angle bisectors; Circumcentre = perpendicular bisectors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0f9706f-2e33-49e0-91e3-5192e7a35875', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'd618c598-42e9-4598-b02a-9d81997863d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('719227e5-150a-4418-b338-e479b5ae7532', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'd618c598-42e9-4598-b02a-9d81997863d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d67a9c5-4d4b-4c2e-bf8d-094aa73ad775', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'd618c598-42e9-4598-b02a-9d81997863d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d7c02d-c747-40c0-95f1-628673b034d0', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'd618c598-42e9-4598-b02a-9d81997863d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('709c1806-1d31-431f-9083-5a44e37bdb0c', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Read the statements regarding right triangles and Pythagoras property:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65685b26-c4d7-4b7e-9520-1fb508d8989b', 'Statements 1 and 2 only', true, '709c1806-1d31-431f-9083-5a44e37bdb0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f967f23b-ac1a-45cc-bd8c-6d5de1ede462', 'Statements 2 and 3 only', false, '709c1806-1d31-431f-9083-5a44e37bdb0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60a62ff4-ef6c-445a-91fb-e975abdebfab', 'Statements 1 and 3 only', false, '709c1806-1d31-431f-9083-5a44e37bdb0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5964afd-cd45-4745-95e5-8726e64d9f22', 'All Statements 1, 2, and 3', false, '709c1806-1d31-431f-9083-5a44e37bdb0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15a362a7-911a-454c-bf81-ff2ec8d6f04c', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'In a quadrilateral ABCD, prove that:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('323fbb2b-90ca-4e76-b109-b6991eb15bd7', 'In ΔABC: AB + BC > AC ; In ΔADC: CD + DA > AC ; In ΔABD: AB + DA > BD ; In ΔBCD: BC + CD > BD ; Adding all four inequalities and dividing by 2 gives AB + BC + CD + DA > AC + BD', true, '15a362a7-911a-454c-bf81-ff2ec8d6f04c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fd4cdbb-25b5-4d07-b7cc-c042bb395828', 'Because diagonals are always zero', false, '15a362a7-911a-454c-bf81-ff2ec8d6f04c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e89c1b3-6cf9-4619-93f1-3ce67696a252', 'Because all quadrilaterals are squares', false, '15a362a7-911a-454c-bf81-ff2ec8d6f04c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('727c3d7c-1dd3-46ee-a7c0-9b6c02ef5be1', 'Because perimeter equals area', false, '15a362a7-911a-454c-bf81-ff2ec8d6f04c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3790e28b-51e0-4057-9511-c587f571e68b', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Let O be any interior point in ΔABC. Which of the following inequalities is strictly true?', 'Triangle inequality on the three sub-triangles meeting at O gives 2(OA + OB + OC) > AB + BC + CA → OA + OB + OC > ½(AB + BC + CA).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdfc7ebc-a6ae-41bc-9932-b7206f24e9ca', 'OA + OB + OC > 1/2 (AB + BC + CA) (In ΔOAB: OA + OB > AB ; ΔOBC: OB + OC > BC ; ΔOCA: OC + OA > CA ; Adding gives 2(OA+OB+OC) > AB+BC+CA)', true, '3790e28b-51e0-4057-9511-c587f571e68b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f70ba4b9-d51d-47ec-b915-88d4911ab001', 'OA + OB + OC < 1/2 (AB + BC + CA)', false, '3790e28b-51e0-4057-9511-c587f571e68b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f2b9ee6-dfd7-417b-a571-5f2aeb24950f', 'OA + OB + OC = AB + BC + CA', false, '3790e28b-51e0-4057-9511-c587f571e68b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5338367b-dd22-43a3-bc3c-bac25b74fa57', 'OA = OB = OC = 0', false, '3790e28b-51e0-4057-9511-c587f571e68b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00cd0590-1a7d-4cd6-a820-bf06f99fd3bd', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'In an isosceles right-angled triangle, if each of the two equal perpendicular legs is of length ''x'', what is the length of the hypotenuse?', 'c = √(x² + x²) = √(2x²) = x√2 (the 45°-45°-90° special right triangle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ccb80be-8020-460f-908e-ff4f851b321b', 'x√2 (Hypotenuse = √(x² + x²) = √(2x²) = x√2)', true, '00cd0590-1a7d-4cd6-a820-bf06f99fd3bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('506a8644-d7a2-4746-a4db-064a635b9300', '2x', false, '00cd0590-1a7d-4cd6-a820-bf06f99fd3bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45c8cd26-75fe-4d26-bbbb-4b93e70768ce', 'x / 2', false, '00cd0590-1a7d-4cd6-a820-bf06f99fd3bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5f8f8c0-cf3a-4dc4-ae4e-0d4bef54fa35', 'x²', false, '00cd0590-1a7d-4cd6-a820-bf06f99fd3bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9027af54-47ff-449f-a8f7-de57a7ded1e5', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Two poles of height 6 m and 11 m stand vertically on a plane ground. If the horizontal distance between their feet is 12 m, find the direct distance between their tops:', 'Right triangle formed with base 12 m and vertical height (11 - 6) = 5 m. Distance = √(5² + 12²) = 13 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ad7dcaf-d15d-40cc-9f22-375493e8c674', '13 m (Vertical difference = 11 - 6 = 5 m ; Top distance = √(5² + 12²) = √(25 + 144) = √169 = 13 m)', true, '9027af54-47ff-449f-a8f7-de57a7ded1e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f68d9050-5fd0-424d-ab6f-9fa6728a7536', '12 m', false, '9027af54-47ff-449f-a8f7-de57a7ded1e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('871cd7a9-33d4-4b05-89ee-8bc7cbddf296', '14 m', false, '9027af54-47ff-449f-a8f7-de57a7ded1e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5012174-c55d-4353-b274-9f55027ea827', '15 m', false, '9027af54-47ff-449f-a8f7-de57a7ded1e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66518dae-359a-41a6-8ba6-32ed56b46027', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'In ΔPQR, the bisectors of interior ∠Q and interior ∠R meet at point O. What is the measure of ∠QOR in terms of ∠P?', 'In ΔQOR: ∠QOR = 180° - (∠Q/2 + ∠R/2) = 180° - ((180° - ∠P)/2) = 180° - 90° + ∠P/2 = 90° + ∠P/2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4e5752a-2e94-4a4c-bc67-916367c200fe', '∠QOR = 90° + (1/2) ∠P', true, '66518dae-359a-41a6-8ba6-32ed56b46027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50eae578-161e-4d78-a771-219b503da113', '∠QOR = 90° - (1/2) ∠P', false, '66518dae-359a-41a6-8ba6-32ed56b46027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b77b69fb-3fee-4ca0-ab2b-d8f4b3eb6af6', '∠QOR = 180° - ∠P', false, '66518dae-359a-41a6-8ba6-32ed56b46027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f14741a2-a800-4612-bed3-af079a6d015f', '∠QOR = 2 ∠P', false, '66518dae-359a-41a6-8ba6-32ed56b46027');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9736c4e-a508-4edd-baea-0aebb71fb9a9', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'If a line segment drawn from a vertex of a triangle is BOTH an altitude and a median to the opposite side, what type of triangle is it?', 'By SAS congruence of the two divided sub-triangles (common altitude, equal divided base, 90° angle), the adjacent sides are equal, proving it is isosceles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('860e5f50-54a0-4148-b810-959caf50fd75', 'It is at least an ISOSCELES TRIANGLE (and if true for all 3 vertices, an Equilateral Triangle)', true, 'b9736c4e-a508-4edd-baea-0aebb71fb9a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01d83ec-e8ae-4de0-9e3e-af7703e0b6e3', 'It is a Scalene triangle only', false, 'b9736c4e-a508-4edd-baea-0aebb71fb9a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2411a16d-4e10-4ff0-8135-e11e6e4a1dab', 'It is a circle', false, 'b9736c4e-a508-4edd-baea-0aebb71fb9a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5ee6313-8f3c-4b50-9008-69912d8ead65', 'It is an impossible line', false, 'b9736c4e-a508-4edd-baea-0aebb71fb9a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7ebc401-c001-49f4-a6b4-26e0b1453675', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Why is the Triangle considered the most rigid and fundamental structural element in civil engineering, bridge truss design, and geodesic domes?', 'Triangulation provides structural rigidity (SSS uniqueness theorem): pin-jointed triangular frames cannot flex under shear loads.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49f8cf0b-0bf7-4f6d-82c3-f48df134207c', 'A triangle is geometrically RIGID: once the three side lengths are fixed, its angles are locked and cannot deform without bending or breaking the sides (unlike quadrilaterals)', true, 'd7ebc401-c001-49f4-a6b4-26e0b1453675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('170010a2-4d3a-4031-999f-20c48a63b386', 'Because triangles are made of gold', false, 'd7ebc401-c001-49f4-a6b4-26e0b1453675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb430e71-b1ba-480b-abe2-cfe91fa9ec82', 'Because triangles have zero weight', false, 'd7ebc401-c001-49f4-a6b4-26e0b1453675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87355528-e1b5-4402-8a5b-f70be55c09d7', 'Because triangles eliminate gravity', false, 'd7ebc401-c001-49f4-a6b4-26e0b1453675');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f767e0c-6780-4d11-bbee-45d720919dd0', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'In Sharada Dwivedi''s story ''Expert Detectives'' (from ''The Broken Flute''), what is the nickname and real age of the boy Nishad?', 'Nishad is a 7-year-old boy nicknamed ''Seven'' because Nishad is the seventh musical note in the Indian classical octave (Sa-Re-Ga-Ma-Pa-Dha-Ni).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d61c1908-aa72-43c0-ba22-745c552e18bc', 'Seven (a 7-year-old boy named because his name refers to the 7th musical note ''Ni'')', true, '0f767e0c-6780-4d11-bbee-45d720919dd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9515c851-0f3c-4313-83e1-48e19bb1352e', 'Ten (a 10-year-old boy)', false, '0f767e0c-6780-4d11-bbee-45d720919dd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7da83b29-f7d9-4357-a953-9b2b963401bd', 'Five (a 5-year-old boy)', false, '0f767e0c-6780-4d11-bbee-45d720919dd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce9b738c-85fb-4569-94c2-0c41d0b51137', 'Miko', false, '0f767e0c-6780-4d11-bbee-45d720919dd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e8a7f1d-d6cb-4437-b548-96deb7ec492e', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'Who is Nishad''s 10-year-old elder sister who acts as the self-appointed lead detective?', 'Maya is Nishad''s 10-year-old sister who investigates their mysterious neighbor Mr. Nath.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57231662-075f-4d9c-a9f0-02f8c17ddfca', 'Maya', true, '1e8a7f1d-d6cb-4437-b548-96deb7ec492e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e8fa5c7-f052-4b09-bc83-dfb64137d160', 'Rani', false, '1e8a7f1d-d6cb-4437-b548-96deb7ec492e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('834c0c99-e702-4c75-8f98-7fb45a8603ab', 'Meena', false, '1e8a7f1d-d6cb-4437-b548-96deb7ec492e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c76defe7-b53d-40b8-8e52-18f29b62e77f', 'Shreya', false, '1e8a7f1d-d6cb-4437-b548-96deb7ec492e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f73b520c-9c6f-49b7-94db-5092fe327ae6', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'Who is the quiet, gaunt, scar-faced tenant in Room No. 10 at Shankar House whom Maya suspects of being a dangerous criminal?', 'Mr. Nath is the recluse tenant living in Room 10 of Shankar House, treated by their mother at her clinic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72de37c2-b843-4e7e-83e7-a424e0865741', 'Mr. Nath', true, 'f73b520c-9c6f-49b7-94db-5092fe327ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f61a1319-2491-4a6b-b006-2290283f9371', 'Mr. Sharma', false, 'f73b520c-9c6f-49b7-94db-5092fe327ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f87edece-6550-48ae-be75-cfc4b621da85', 'Mr. Mehta', false, 'f73b520c-9c6f-49b7-94db-5092fe327ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc1faec-67ba-437a-a5dd-46fafb6db205', 'Ramesh', false, 'f73b520c-9c6f-49b7-94db-5092fe327ae6');
