INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e0b56ac-22db-413e-814a-8cd5f2a7055b', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What unusual visitor comes to see Mr. Nath every SUNDAY afternoon at Shankar House?', 'Ramesh informs Nishad that every Sunday, a tall, fair, stout, bespectacled visitor visits Mr. Nath and chats incessantly.', NOW()) ON CONFLICT DO NOTHING;
