INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7b8e228-e8aa-426e-8fe0-22d02c2082d1', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What sweet treat did Nishad thrust into Mr. Nath''s hand during his unexpected visit to Room 10?', 'Moved by Mr. Nath''s gaunt, starving appearance, Nishad generously thrust a bar of chocolate into his palm.', NOW()) ON CONFLICT DO NOTHING;
