INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95ed68d6-3f9a-4ca6-b5ed-f09be02d8eaa', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'In Maude Rubin''s poem ''Mystery of the Talking Fan'', what was the ''talking'' or ''chattering'' sound made by the ceiling fan?', 'The fan''s ''talk'' was the dry, un-oiled rhythmic mechanical squeak of its electric motor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27bce6de-2fc0-4554-90a6-b5cd4e7761fb', 'An electrical squeak and mechanical whirring sound caused by lack of lubricating oil in its motor', true, '95ed68d6-3f9a-4ca6-b5ed-f09be02d8eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99e12a03-63ac-4503-a030-345758552cb2', 'Real human words spoken by a ghost', false, '95ed68d6-3f9a-4ca6-b5ed-f09be02d8eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cd7e8af-7c9a-4564-a1f4-46024e93fe81', 'Music from a radio', false, '95ed68d6-3f9a-4ca6-b5ed-f09be02d8eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6976c2d-f437-4218-9c74-d456591865cb', 'The sound of wind blowing through an open window', false, '95ed68d6-3f9a-4ca6-b5ed-f09be02d8eaa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e7a3a26-4727-4c51-a3dd-9a9bdc226907', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'How did the ''mystery'' of the talking fan suddenly come to an end?', 'The poem ends: ''He ran as still as water'' once somebody oiled its whirling motor, solving the mystery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eff9264e-9102-4907-ba56-97e536a11733', 'Somebody oiled its little whirling electric motor, and thereafter it ran as still and smooth as water', true, '8e7a3a26-4727-4c51-a3dd-9a9bdc226907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1260132c-d90d-4d15-830e-eef29f35a05b', 'The fan fell down from the ceiling', false, '8e7a3a26-4727-4c51-a3dd-9a9bdc226907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77b7dbae-9226-4bf3-98e3-d55dc741d481', 'The electricity was cut off permanently', false, '8e7a3a26-4727-4c51-a3dd-9a9bdc226907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d374705-1975-4e7c-85de-96e18cfb721f', 'The fan was thrown into the river', false, '8e7a3a26-4727-4c51-a3dd-9a9bdc226907');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53c6af02-f7b2-4af7-8c52-1010364db3b7', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What prefix can be added to the word ''Patient'' to mean ''Unable to wait calmly''?', 'The negative prefix ''im-'' attaches to roots starting with labial consonants (m/p): im + patient = impatient.', NOW()) ON CONFLICT DO NOTHING;
