INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37b1b8ab-c136-4a16-b7db-e6ae1bf08cbe', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What does the idiom ''To keep an eye on'' mean in detective contexts?', '''To keep an eye on'' means maintaining close surveillance or careful supervision over someone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd6a6aef-0e0d-4996-a531-09782633ba72', 'To watch, monitor, or observe someone very carefully and vigilantly', true, '37b1b8ab-c136-4a16-b7db-e6ae1bf08cbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6faa6ad0-f5b6-4ed3-b362-d2d0995811ed', 'To look at someone with one eye closed', false, '37b1b8ab-c136-4a16-b7db-e6ae1bf08cbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29057457-131b-4c73-9ff1-8f1810eae324', 'To wear spectacles', false, '37b1b8ab-c136-4a16-b7db-e6ae1bf08cbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910e0f67-9bff-4909-8e0d-1f4d6a12c478', 'To paint an eye', false, '37b1b8ab-c136-4a16-b7db-e6ae1bf08cbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e87477a3-7ce4-4a08-9745-a087c020c025', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'Why do Maya and Nishad have opposing viewpoints about Mr. Nath?', 'Maya views Mr. Nath through sensational detective melodrama; Nishad views him through compassionate human empathy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14debabe-d621-4874-b3bd-1fd1338903b8', 'Maya believes Mr. Nath is a dangerous fugitive criminal hiding millions in stolen loot ; Nishad empathizes with him as a lonely, impoverished, sick man who needs a friend', true, 'e87477a3-7ce4-4a08-9745-a087c020c025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22f8986a-3c75-4b20-9cab-37dcb7d0ca6a', 'Maya thinks he is a doctor and Nishad thinks he is a teacher', false, 'e87477a3-7ce4-4a08-9745-a087c020c025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('633a748b-f22e-4aaa-af49-df61f8a8c2ee', 'Both think he is a king', false, 'e87477a3-7ce4-4a08-9745-a087c020c025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c61de36-728e-4f34-a094-25d7a643f02b', 'Neither cares about him', false, 'e87477a3-7ce4-4a08-9745-a087c020c025');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c79ee08c-b2dd-4c39-bb29-d2075a7facc3', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'How does Maya explain the burn scars on Mr. Nath''s face, and what does their mother say about them?', 'Maya melodramatically assumes police shootout wounds; their doctor mother confirms they are medical burn scars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fa58f04-4e20-4343-8f9a-ce3874a54cae', 'Maya theorizes the police shot or burned him during a shootout ; Mama explains that they are severe burn scars from an accidental fire', true, 'c79ee08c-b2dd-4c39-bb29-d2075a7facc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd81c1ed-2e52-41a4-b823-c299c697a092', 'Maya says he was born with them', false, 'c79ee08c-b2dd-4c39-bb29-d2075a7facc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba52a761-6e7a-41fe-8afb-239c7a232224', 'Mama says he got them from an animal bite', false, 'c79ee08c-b2dd-4c39-bb29-d2075a7facc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9194589d-7d5f-4667-8d3f-2b11c7887266', 'Maya says he painted them', false, 'c79ee08c-b2dd-4c39-bb29-d2075a7facc3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5e9caad-8422-4926-985c-4a38d5ef01ee', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'What reason does Maya offer for why Mr. Nath has no friends and never talks to anyone at Shankar House?', 'Maya rationalizes his reclusive isolation as a criminal strategy to evade identification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e047c80-2c6f-42e9-822d-b1d042c40aa8', 'She claims he is terrified that someone might recognize him and inform the police about his criminal identity', true, 'a5e9caad-8422-4926-985c-4a38d5ef01ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e637a1d7-d3fe-45b0-bca9-f518e6e97c8e', 'Because he does not know any language', false, 'a5e9caad-8422-4926-985c-4a38d5ef01ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bdc94bb-f2a0-4027-8e89-67f500ae333f', 'Because he is deaf', false, 'a5e9caad-8422-4926-985c-4a38d5ef01ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e572e194-48ea-4464-87fc-6b17bbf551ec', 'Because he owns the whole building', false, 'a5e9caad-8422-4926-985c-4a38d5ef01ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b4b6bcd-65a6-4502-a5e4-48e70506e9bd', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'What conclusion does Nishad reach after visiting Mr. Nath, refusing to support Maya''s criminal accusations?', 'Nishad rebels against Maya''s prejudice, asserting his determination to offer genuine friendship to the isolated man.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd91e4c6-d402-46dc-8c94-0465daeb3f30', 'He declares: "I like him, and I''m going to try and be his friend! How can a lonely, poor man be a bad crook?"', true, '3b4b6bcd-65a6-4502-a5e4-48e70506e9bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a8698dd-cefc-4353-ae2d-323917f76554', 'He agrees to call the police immediately', false, '3b4b6bcd-65a6-4502-a5e4-48e70506e9bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e604da93-b394-40fe-b048-50b80a5181f8', 'He runs away from home', false, '3b4b6bcd-65a6-4502-a5e4-48e70506e9bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac59a497-fa60-4cc6-8c77-1484998c986f', 'He decides to steal Mr. Nath''s food', false, '3b4b6bcd-65a6-4502-a5e4-48e70506e9bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35ed1eaf-d89e-4f20-a483-277be17da086', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'What poetic device is prominent in the opening lines of ''Mystery of the Talking Fan'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601bcc34-9b22-4b41-bbc6-882b77708952', 'Personification (giving the mechanical ceiling fan the human ability to ''talk'' and ''chatter'')', true, '35ed1eaf-d89e-4f20-a483-277be17da086');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93e90435-e319-4a97-b38f-51961240fe10', 'Alliteration only', false, '35ed1eaf-d89e-4f20-a483-277be17da086');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3727bf3f-c48f-4610-be90-72f17316c122', 'Hyperbole only', false, '35ed1eaf-d89e-4f20-a483-277be17da086');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9203d13-31b4-4822-92b2-6957af4ef46a', 'Oxymoron', false, '35ed1eaf-d89e-4f20-a483-277be17da086');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c0975cb-93fd-4c3e-a2b8-790d170e77c4', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'Identify the figure of speech in: ''He ran as still as water.''', '''As still as water'' is a classic simile comparing mechanical fluidity to undisturbed liquid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bdf83d3-43c6-4190-9b40-af3d64a3763f', 'Simile (comparing the quiet, smooth motion of the oiled fan to calm water using ''as'')', true, '1c0975cb-93fd-4c3e-a2b8-790d170e77c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1e0549f-8715-40bb-9768-9900db500b5b', 'Metaphor', false, '1c0975cb-93fd-4c3e-a2b8-790d170e77c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55fe89ee-7c87-4b60-b314-9622a18fdfab', 'Personification', false, '1c0975cb-93fd-4c3e-a2b8-790d170e77c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('717d6b38-a7d4-4b7d-9e5e-89ac6c38952f', 'Irony', false, '1c0975cb-93fd-4c3e-a2b8-790d170e77c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa5424e9-29ac-45c3-97af-38bd66830b43', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'What is the meaning of the word ''Peculiar'' in: ''Mr. Nath is a peculiar person''?', '''Peculiar'' means strange, atypical, or distinctive from the ordinary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d892bdc9-d4dd-4620-b2c3-de11310b4a1e', 'Strange, unusual, odd, or unconventional', true, 'fa5424e9-29ac-45c3-97af-38bd66830b43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41c913c9-d7f0-4fd5-abff-7c32d609f25c', 'Extremely wealthy', false, 'fa5424e9-29ac-45c3-97af-38bd66830b43');
