INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46a5a812-0539-4e56-a024-ee08bdf03b2e', 'Because he refuses to participate in Maya''s unkind, unverified witch-hunt against Mr. Nath and intends to follow his conscience to befriend him', true, '9e0c6953-dd9f-40c3-9d82-bd2f5a4ef205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b307c903-f071-46f7-bedc-86ecfff567ff', 'Because he lost his chocolate bar', false, '9e0c6953-dd9f-40c3-9d82-bd2f5a4ef205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea4f13db-bfdd-4659-b2a9-84f2bdb8152a', 'Because Maya tore his notebook', false, '9e0c6953-dd9f-40c3-9d82-bd2f5a4ef205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e135c1d7-2e44-4cb0-9f72-078da3a1890a', 'Because it started raining heavily', false, '9e0c6953-dd9f-40c3-9d82-bd2f5a4ef205');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99a54b10-570d-41b8-99ae-de5572d5d56c', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'What is the metaphorical significance of the ceiling fan in Maude Rubin''s poem?', 'Rubin illustrates the poetic transformation of mundane mechanical friction into an imaginative narrative, effortlessly resolved by rational care.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28101c7d-5c24-41df-ba7f-d09e9aa08b34', 'It represents how everyday mundane objects can spark childlike wonder and imagination, until simple scientific logic demystifies the phenomenon', true, '99a54b10-570d-41b8-99ae-de5572d5d56c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba53fab9-46eb-4f10-a8ec-6cd17a956954', 'It symbolizes a spaceship', false, '99a54b10-570d-41b8-99ae-de5572d5d56c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f5f213a-deec-4afc-b49a-fe892e6cda7c', 'It represents an evil monster', false, '99a54b10-570d-41b8-99ae-de5572d5d56c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99c76595-a070-4910-9b93-6e94a2c606da', 'It shows that electricity is dangerous', false, '99a54b10-570d-41b8-99ae-de5572d5d56c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2356416e-751d-410a-873a-15b0b6c33435', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'What does the narrator mean by ''Electrical his chatter'' in the poem?', '''Electrical his chatter'' poeticizes the humming acoustic vibration created by the alternating electric current in the dry motor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e48d6fb7-f98c-4788-ada9-ab6c81d3c000', 'The noise of the fan was produced by electrical currents driving the friction in the unlubricated motor', true, '2356416e-751d-410a-873a-15b0b6c33435');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e2e127e-8d56-45a3-a9a5-8973dadca86f', 'The fan was connected to a telephone', false, '2356416e-751d-410a-873a-15b0b6c33435');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c353896-3120-4fed-a17e-3229226510a9', 'The fan was speaking about batteries', false, '2356416e-751d-410a-873a-15b0b6c33435');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c108a29-c217-4899-867f-627c580cfc6b', 'The fan gave people electric shocks', false, '2356416e-751d-410a-873a-15b0b6c33435');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99bb6c22-f5f6-4be3-bd3e-4b7f9fe226c5', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'Which of the following lines from ''Mystery of the Talking Fan'' contains an acoustic auditory image?', '''Electrical his chatter'' and ''couldn''t quite hear'' appeal directly to auditory sensory imagery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ab9644d-8aeb-48af-9eb6-e9698f7e97b4', '"Electrical his chatter / I couldn''t quite hear what he said"', true, '99bb6c22-f5f6-4be3-bd3e-4b7f9fe226c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfec5862-1951-4ace-a093-fa940ff4b8ab', '"He ran as still as water"', false, '99bb6c22-f5f6-4be3-bd3e-4b7f9fe226c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c31fb11a-de85-4423-b11b-b1e39af4806f', '"Somebody oiled his little whirling motor"', false, '99bb6c22-f5f6-4be3-bd3e-4b7f9fe226c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77f1702d-27a1-4ac3-9964-2deb2113797b', '"All the mystery was spoiled"', false, '99bb6c22-f5f6-4be3-bd3e-4b7f9fe226c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41ce46b8-1939-4577-9c66-843b5d229a01', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'What overarching moral theme unites Chapter 6 of NCERT Class 7 English?', 'Chapter 6 celebrates critical thinking, the rejection of hasty prejudice, and the supremacy of empathetic human understanding.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4bd1f39-1f58-4ed2-a07a-6c5ab3e24613', 'The necessity of looking beyond surface appearances—whether investigating human character with empathy and truth rather than sensational bias, or demystifying mechanical curiosities through rational understanding', true, '41ce46b8-1939-4577-9c66-843b5d229a01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5986aa3-1687-49fd-9347-68e9815243b2', 'That children should never play with marbles', false, '41ce46b8-1939-4577-9c66-843b5d229a01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6b8989a-eaab-4aae-bdee-6f729d28d785', 'That fans should be removed from houses', false, '41ce46b8-1939-4577-9c66-843b5d229a01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('839f8867-122f-479c-93fe-75f979d0f082', 'That doctors should never treat patients', false, '41ce46b8-1939-4577-9c66-843b5d229a01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('989613d9-1e90-4a36-a1af-aa77eedd2e94', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'In which year was the United Nations (UN) founded to maintain international peace and security following the devastation of World War II?', 'The UN Charter was signed on 26 June 1945 and entered into force on 24 October 1945 (celebrated globally as United Nations Day).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9a3ddce-26d3-4329-be55-63c6cd52c09d', '1945 (on 24 October 1945 in San Francisco / New York)', true, '989613d9-1e90-4a36-a1af-aa77eedd2e94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ec800f7-6dad-4df8-8a00-3ea6f8a19de6', '1919', false, '989613d9-1e90-4a36-a1af-aa77eedd2e94');
