INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('855dd63d-d59a-4513-be91-d346531fedf4', '1939', false, '989613d9-1e90-4a36-a1af-aa77eedd2e94');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0cb0133c-54ac-427f-8d74-2783bab1d786', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Where are the official Headquarters of the United Nations (UN) situated?', 'The UN Headquarters is located in international territory in Midtown Manhattan, New York City.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6394e5f0-b601-4294-8115-934d59c708b6', 'New York City, USA', true, '0cb0133c-54ac-427f-8d74-2783bab1d786');
