INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c479621f-8d1a-48c3-bd9c-45f1d3108bec', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'How many permanent members (P5) with VETO POWER are there in the United Nations Security Council (UNSC)?', 'The UNSC has 5 permanent members (US, UK, France, Russia, China) with veto power, alongside 10 non-permanent members elected for 2-year terms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19b7062a-918f-4955-b8c8-4f6b911a4bca', '5 Permanent Members (United States, United Kingdom, France, Russia, and China)', true, 'c479621f-8d1a-48c3-bd9c-45f1d3108bec');
