INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91b3be23-4421-4232-be44-37f8cf10831e', '7 Permanent Members', false, 'c479621f-8d1a-48c3-bd9c-45f1d3108bec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04b70c7b-1fbc-4b03-8f5d-320d38a50980', '3 Permanent Members', false, 'c479621f-8d1a-48c3-bd9c-45f1d3108bec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79b29add-8bf2-4329-a0a8-729a5e4efea2', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Where is the International Court of Justice (ICJ) — the principal judicial organ of the UN — located?', 'The ICJ sits at the Peace Palace in The Hague, Netherlands; it is the only principal UN organ not located in New York.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab778ed8-d771-4936-b015-3ffd4a83d017', 'The Hague, Netherlands (Peace Palace)', true, '79b29add-8bf2-4329-a0a8-729a5e4efea2');
