INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c92c8f8d-466f-4291-91b6-693e067880ad', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which specialized UN agency is responsible for international public health, disease eradication, and pandemic response, headquartered in Geneva?', 'The WHO (founded 7 April 1948, celebrated as World Health Day) directs global health guidelines and disease surveillance from Geneva.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('229bee80-94e0-4ede-8e0e-de5714f3911a', 'World Health Organization (WHO)', true, 'c92c8f8d-466f-4291-91b6-693e067880ad');
