INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e24e17fe-5821-40b0-ae62-ab70c8604d70', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which UN agency is dedicated to protecting children''s rights, healthcare, nutrition, and education worldwide, headquartered in New York?', 'UNICEF provides humanitarian and developmental aid to children in over 190 countries and territories.', NOW()) ON CONFLICT DO NOTHING;
