INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53961ee3-ae75-4567-a1d2-995d0d704157', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which UN agency promotes international peace through education, the sciences, culture, and World Heritage Sites, headquartered in Paris, France?', 'UNESCO (United Nations Educational, Scientific and Cultural Organization) oversees cultural preservation, literacy, and World Heritage classifications.', NOW()) ON CONFLICT DO NOTHING;
