INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33595420-e83a-4369-ae21-0e2641bfbf50', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which global financial institutions (the Bretton Woods twins) provide loans and financial stability to member nations, headquartered in Washington, D.C.?', 'The World Bank (reconstruction & development) and IMF (monetary stability & balance of payments) were founded at Bretton Woods in 1944.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2efb47e-ae9b-42df-977f-5c168ca5b07a', 'The World Bank and the International Monetary Fund (IMF)', true, '33595420-e83a-4369-ae21-0e2641bfbf50');
