INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ab809b1-e560-4263-95dc-3821de689353', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which international organization regulates global international trade rules between nations, headquartered in Geneva, Switzerland?', 'The WTO (established 1 January 1995 succeeding GATT) establishes multilateral trade agreements and arbitrates trade disputes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3a3e6c6-2cfb-48aa-b7da-d2881f8aa31b', 'World Trade Organization (WTO)', true, '4ab809b1-e560-4263-95dc-3821de689353');
