INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17665bf0-c20b-4402-8fef-effc571cd470', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'What was the theme of the historic G20 Summit hosted by India in New Delhi in September 2023 under its presidency?', 'India''s G20 presidency theme was ''Vasudhaiva Kutumbakam'' (One Earth · One Family · One Future), drawn from the ancient Maha Upanishad.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33984157-dc97-481b-9c8e-aab452fb2ad8', '"Vasudhaiva Kutumbakam" — ''One Earth, One Family, One Future''', true, '17665bf0-c20b-4402-8fef-effc571cd470');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38e86d49-4946-47eb-a813-3f2a941a07f4', '"Peace through Strength"', false, '17665bf0-c20b-4402-8fef-effc571cd470');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6943d704-fe09-4f97-8cd8-6f2e87bdc1cc', '"Trade without Borders"', false, '17665bf0-c20b-4402-8fef-effc571cd470');
