INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('caa44b7d-8e1d-4c46-8cbe-cc2ebce03f87', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'What does the geopolitical grouping acronym ''BRICS'' stand for?', 'BRICS brings together major emerging economies: Brazil, Russia, India, China, and South Africa (expanded with new member nations in 2024).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bccef471-fb65-4974-be9a-a668ece58471', 'Brazil, Russia, India, China, and South Africa', true, 'caa44b7d-8e1d-4c46-8cbe-cc2ebce03f87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5a226b5-a43e-404e-9a77-0cb9a6f7061f', 'Britain, Russia, Italy, Canada, and Spain', false, 'caa44b7d-8e1d-4c46-8cbe-cc2ebce03f87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c884266e-c911-41cc-8d05-9daa1a8e1af9', 'Belgium, Romania, India, Chile, and Sweden', false, 'caa44b7d-8e1d-4c46-8cbe-cc2ebce03f87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e84594a3-ac90-46f8-83b0-8b28ea640c22', 'Brazil, Rwanda, Indonesia, China, and Sudan', false, 'caa44b7d-8e1d-4c46-8cbe-cc2ebce03f87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('700f95d5-9e14-4d2f-a6fb-682638dd055f', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'What is the primary objective of the historic 2015 ''Paris Climate Agreement'' (COP21)?', 'The legally binding Paris Agreement commits 196 parties to hold anthropogenic global temperature rise well below 2.0°C and strive for 1.5°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6113776a-385a-4864-ae2c-2cd0f5f163b8', 'To limit global warming to well below 2°C (preferably to 1.5°C) above pre-industrial levels', true, '700f95d5-9e14-4d2f-a6fb-682638dd055f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88ba04bf-fd46-4a7e-b019-180bd3603c14', 'To ban all cars worldwide', false, '700f95d5-9e14-4d2f-a6fb-682638dd055f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91d49265-34c1-4fc1-950a-2b84319f7d15', 'To build a wall around Antarctica', false, '700f95d5-9e14-4d2f-a6fb-682638dd055f');
