INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('600067f9-d6b4-47ea-bdac-6d011a4edc3c', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''General Assembly'' (UNGA) of the United Nations often referred to in international relations?', 'The UNGA is the principal deliberative organ where all 193 sovereign member states participate on sovereign equality principles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ef41a75-0be7-46b3-8ffe-a0457af24ce8', 'The ''Town Hall of the World'' (where all 193 member states have equal representation and 1 vote each)', true, '600067f9-d6b4-47ea-bdac-6d011a4edc3c');
