INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e873054-3e71-428b-b7ab-1ce40efee048', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which regional intergovernmental organization comprises 10 Southeast Asian nations (e.g. Indonesia, Singapore, Malaysia, Thailand, Vietnam)?', 'ASEAN (founded 1967 in Bangkok) fosters regional economic integration, security, and cultural collaboration across 10 Southeast Asian states.', NOW()) ON CONFLICT DO NOTHING;
