INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8ec3a77-1ab7-4f76-ab6f-ca95affe2dcd', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''QUAD'' (Quadrilateral Security Dialogue) diplomatic partnership between four major democratic nations in the Indo-Pacific?', 'The QUAD comprises India, the US, Japan, and Australia, advancing a free, open, and resilient Indo-Pacific maritime order.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7e3dc98-4f6f-4cc6-af49-18dbf42b7985', 'India, the United States, Japan, and Australia', true, 'a8ec3a77-1ab7-4f76-ab6f-ca95affe2dcd');
