INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2029969e-8a2d-4435-b8a7-c82694be1911', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which international organization of 12 petroleum-exporting nations coordinates petroleum policies to stabilize international oil markets, headquartered in Vienna?', 'OPEC (headquartered in Vienna, Austria) coordinates crude oil production quotas among member states to regulate global petroleum pricing.', NOW()) ON CONFLICT DO NOTHING;
