INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18ccfe7b-4818-4e6c-a45a-9060f1f3bb91', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What are the ''Geneva Conventions'' in international humanitarian law?', 'The 1949 Geneva Conventions codify the core tenets of international humanitarian law (jus in bello), protecting non-combatants and war victims.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6494f93a-8255-4950-ae92-f32e27a6d345', 'Four landmark international treaties that establish the legal standards for humanitarian treatment of wounded soldiers, prisoners of war (POWs), and civilians during armed conflicts', true, '18ccfe7b-4818-4e6c-a45a-9060f1f3bb91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e1bb9f6-33dd-4806-a8d5-ae5a8e95f2ed', 'A treaty regulating air travel tickets', false, '18ccfe7b-4818-4e6c-a45a-9060f1f3bb91');
