INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75347b69-0d61-44be-a42e-d69baa935733', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''International Atomic Energy Agency'' (IAEA), headquartered in Vienna, Austria?', 'The IAEA (established 1957) monitors nuclear safeguards, promotes civilian nuclear technology, and verifies non-proliferation treaties.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29f4d23c-02db-46ad-8280-81e0a7b24b60', 'The ''Atoms for Peace'' world organization that promotes peaceful uses of nuclear energy and conducts inspections to prevent nuclear weapon proliferation', true, '75347b69-0d61-44be-a42e-d69baa935733');
