INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a32a623-8f2e-4565-8740-4ccbd6a4cb95', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Where is the Secretariat of SAARC (South Asian Association for Regional Cooperation) located?', 'The SAARC Secretariat was established in Kathmandu, Nepal in 1987 to facilitate regional dialogue across 8 South Asian member states.', NOW()) ON CONFLICT DO NOTHING;
