INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c47d6e2-41e6-491d-bd64-931d21fa4b1d', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''Universal Declaration of Human Rights'' (UDHR) adopted by the UN General Assembly on 10 December 1948?', 'Adopted under the leadership of Eleanor Roosevelt on 10 Dec 1948 in Paris, the UDHR articulates inalienable human dignities and fundamental liberties.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3d5e187-3909-46c3-aebf-b50ec45117aa', 'A milestone milestone proclamation setting out 30 fundamental human rights to be universally protected for all human beings everywhere (celebrated as Human Rights Day)', true, '4c47d6e2-41e6-491d-bd64-931d21fa4b1d');
