INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08038d53-d879-45f1-8411-ddf43c0bdfd6', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which global environmental treaty signed in 1987 successfully phased out ozone-depleting substances (Chlorofluorocarbons / CFCs)?', 'The 1987 Montreal Protocol is celebrated as the most universally ratified and successful multilateral environmental treaty, healing the stratospheric ozone layer.', NOW()) ON CONFLICT DO NOTHING;
