INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7de429d-9700-4405-9b17-db507bc9adcd', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is ''INTERPOL'' (International Criminal Police Organization), headquartered in Lyon, France?', 'Interpol enables law enforcement agencies worldwide to share biometric databases, track transnational criminals, and issue Red Notices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe8cf1a9-672e-405a-a691-85784bc44d6a', 'The world''s largest international police organization that facilitates cross-border police cooperation and crime control across 196 member countries', true, 'b7de429d-9700-4405-9b17-db507bc9adcd');
