INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46a430f7-498d-46a4-8213-185eba755f06', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which specialized UN agency leads international efforts to defeat hunger, improve agricultural nutrition, and food security, headquartered in Rome, Italy?', 'The FAO (founded 16 October 1945, World Food Day) coordinates global agrarian development and famine mitigation from Rome.', NOW()) ON CONFLICT DO NOTHING;
