INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b48c8775-56e9-45b9-83ca-a54dfaa1e3ef', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''European Union'' (EU)?', 'The EU represents a unique economic and political bloc established by the Maastricht Treaty (1993), governing a single market and freedom of movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e28a29c6-21c8-4c6a-9e24-9f4bb399790f', 'A supranational political and economic union of 27 European member states with a single market, common policies, and a shared currency (the Euro in the Eurozone)', true, 'b48c8775-56e9-45b9-83ca-a54dfaa1e3ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1183702e-6675-494b-9451-56a28c54cfb3', 'A military alliance of 5 countries', false, 'b48c8775-56e9-45b9-83ca-a54dfaa1e3ef');
