INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b4ca6b9-4174-4074-83db-ac7f430e7427', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is ''NATO'' (North Atlantic Treaty Organization)?', 'NATO was established by the 1949 Washington Treaty, anchored on collective defense solidarity among transatlantic allies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('344ece8c-08db-4605-83cd-91dff961e8e5', 'A collective defense military alliance between 32 North American and European countries governed by Article 5 (an armed attack against one is an attack against all)', true, '2b4ca6b9-4174-4074-83db-ac7f430e7427');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af8ff54d-2932-4e0a-adaa-56c8e640cff0', 'A global trade network for cars', false, '2b4ca6b9-4174-4074-83db-ac7f430e7427');
