INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3c9b10b-dd56-4a20-b8ca-72e931c6c679', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What are the 17 global goals adopted by all UN Member States in 2015 as a universal call to action to end poverty, protect the planet, and ensure peace by 2030 called?', 'The UN 2030 Agenda encompasses 17 Sustainable Development Goals (SDGs) tackling poverty, inequality, climate action, clean energy, and education.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7d4368f-2465-474a-af53-9dfa201b9dbf', 'Sustainable Development Goals (SDGs / 2030 Agenda)', true, 'c3c9b10b-dd56-4a20-b8ca-72e931c6c679');
