INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d468483-8cc5-48c3-ad96-a226f8a01c49', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which Indian diplomat served as the FIRST woman President of the United Nations General Assembly in 1953?', 'Vijaya Lakshmi Pandit was elected as the 8th President of the UN General Assembly in 1953, the first female diplomat to hold this supreme post.', NOW()) ON CONFLICT DO NOTHING;
