INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3250d0ae-0ec4-400d-bddb-c2ac48263bad', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''International Red Cross and Red Crescent Movement'', awarded three Nobel Peace Prizes, dedicated to?', 'Founded by Henry Dunant in 1863, the ICRC delivers frontline medical relief under strict humanitarian neutrality.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57640305-570d-4c38-82e9-d28b8378dd77', 'Providing neutral, impartial humanitarian protection and medical assistance to victims of armed conflicts and natural disasters worldwide', true, '3250d0ae-0ec4-400d-bddb-c2ac48263bad');
