INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1787b9bd-5152-4063-8562-e70e2441657b', 'Collecting taxes for governments', false, '3250d0ae-0ec4-400d-bddb-c2ac48263bad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4431b58-4179-4939-9fb0-e2eac671c0fd', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c063fb20-d76b-4eac-a723-110340a29daa', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'd4431b58-4179-4939-9fb0-e2eac671c0fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75c5b303-65de-4586-8583-89705ebacab7', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'd4431b58-4179-4939-9fb0-e2eac671c0fd');
