INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('237bee6c-ab6d-423e-9b06-9491f916f517', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'Spot the IMPOSTER in the following international organizations and their respective headquarters:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('743659b1-9407-40e2-bf16-e417ff9c95d4', 'Organization 1', false, '237bee6c-ab6d-423e-9b06-9491f916f517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b6318d1-566a-47b9-b617-214a94ce52c9', 'Organization 2', false, '237bee6c-ab6d-423e-9b06-9491f916f517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83587d95-a751-45f4-a25d-ffa5f714d115', 'Organization 3', false, '237bee6c-ab6d-423e-9b06-9491f916f517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a37dd628-d35c-463d-8c11-1d8f5a2071cf', 'Organization 4 (The IMF is headquartered in WASHINGTON, D.C., USA, not Tokyo)', true, '237bee6c-ab6d-423e-9b06-9491f916f517');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59f0e1f2-3f57-439c-a423-79652fab6fc6', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What historic achievement was realized at the New Delhi G20 Summit in September 2023 under India''s leadership regarding multilateral representation?', 'India championed the formal inclusion of the 55-nation African Union as a permanent member, transforming G20 into a truly representative global forum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('065d46d3-7433-45e6-a25a-e55ff60c8452', 'The induction of the AFRICAN UNION (comprising 55 African nations) as a permanent full member of the G20, amplifying Global South representation', true, '59f0e1f2-3f57-439c-a423-79652fab6fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4489ff36-823e-48c4-b430-21c4f06f4c06', 'The dissolution of the United Nations', false, '59f0e1f2-3f57-439c-a423-79652fab6fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c26bc44-9524-4682-9acf-9836ad69ca68', 'The creation of a single global currency', false, '59f0e1f2-3f57-439c-a423-79652fab6fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be385c28-c00d-4960-8248-e25800652dde', 'The banning of all sea trade', false, '59f0e1f2-3f57-439c-a423-79652fab6fc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55f3fd9c-1dbf-4aad-843a-6622b77504ea', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'Match Column I (UN Specialized Organs / Agencies) with Column II (Mandates / Responsibilities):
(a) UNHCR -> (i) Protection and humanitarian assistance for refugees and displaced persons
(b) UNEP  -> (ii) Environmental agenda, climate governance, and biodiversity conservation
(c) ILO   -> (iii) Setting international labor standards, worker rights, and social justice
(d) WIPO  -> (iv) Protection and promotion of Intellectual Property (patents, copyrights)', 'UNHCR = Refugees; UNEP = Environment; ILO = Labor standards; WIPO = Intellectual property rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f61092b2-c5e3-4868-b473-429858434af4', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '55f3fd9c-1dbf-4aad-843a-6622b77504ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f11b0bea-9dd6-48a0-a8f6-51e6a1d4d25e', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '55f3fd9c-1dbf-4aad-843a-6622b77504ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d9c408d-abfb-4506-901f-314271d7bb21', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '55f3fd9c-1dbf-4aad-843a-6622b77504ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('370f4167-8515-427e-b7be-d12fc5d2c05c', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '55f3fd9c-1dbf-4aad-843a-6622b77504ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98cebbdc-d7fd-41e2-8fd3-370046c5af7c', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'Read the statements regarding the Non-Aligned Movement (NAM):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('880fff37-3132-4a86-9246-4fe99250bad8', 'Statements 1 and 2 only', true, '98cebbdc-d7fd-41e2-8fd3-370046c5af7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e3c050f-1d14-4421-a02b-0a83f15ddc64', 'Statements 2 and 3 only', false, '98cebbdc-d7fd-41e2-8fd3-370046c5af7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7207d576-cd35-4e5d-9e7c-e7b82546b9f0', 'Statements 1 and 3 only', false, '98cebbdc-d7fd-41e2-8fd3-370046c5af7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1c6625a-4fde-4c3d-8fc1-f7ff25a3e9d1', 'All Statements 1, 2, and 3', false, '98cebbdc-d7fd-41e2-8fd3-370046c5af7c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2eae2d7b-5983-48b7-bfd8-8addac5d0359', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is the ''International Criminal Court'' (ICC) established by the 1998 Rome Statute?', 'The ICC (based in The Hague) exercises jurisdiction over individuals for core atrocity crimes under the principle of complementarity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77313912-2f78-4081-a60d-d1e1590df691', 'A permanent independent judicial institution that prosecutes individuals accused of the gravest international crimes: Genocide, Crimes Against Humanity, War Crimes, and the Crime of Aggression', true, '2eae2d7b-5983-48b7-bfd8-8addac5d0359');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23733493-c7ca-4059-9c9e-052b1d3fd75b', 'A court for traffic violations between countries', false, '2eae2d7b-5983-48b7-bfd8-8addac5d0359');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('100db484-2b06-4156-8cfb-806cc8f12f92', 'A private arbitration firm for sports disputes', false, '2eae2d7b-5983-48b7-bfd8-8addac5d0359');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74ea785d-6084-4f57-8143-e615bc36cd25', 'A tax collection agency in Europe', false, '2eae2d7b-5983-48b7-bfd8-8addac5d0359');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3e61c75-aa73-4005-9403-2f2d09030ca8', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is the ''Global South'' concept in contemporary international relations?', 'The Global South represents a political-economic coalition of developing nations seeking democratized global architecture and debt restructuring.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c81068af-28cc-41b7-8189-ebf653f42f0b', 'A geopolitical and economic term referring broadly to developing, emerging, and low-income nations across Asia, Africa, and Latin America advocating for equitable global financial and climate justice', true, 'e3e61c75-aa73-4005-9403-2f2d09030ca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cffc1c53-2390-4210-9f3c-00a470dfe6dd', 'Nations located only in the southern hemisphere below the equator', false, 'e3e61c75-aa73-4005-9403-2f2d09030ca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de173536-24a9-4e05-8103-d5ce3f5af3ce', 'A military alliance of 10 island nations', false, 'e3e61c75-aa73-4005-9403-2f2d09030ca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2f499b9-c4d6-4156-b06b-ea37c4164c1a', 'Countries that experience warm summers only', false, 'e3e61c75-aa73-4005-9403-2f2d09030ca8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f53acaa-1d77-4764-bb16-628be8f063e4', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'Consider four foundational international treaties:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b7b7328-6bd0-49a3-a8a2-a9a00e42e06c', 'Institutionalizing rule-based multilateral cooperation to safeguard collective security, human dignity, non-proliferation, and planetary ecological survival', true, '2f53acaa-1d77-4764-bb16-628be8f063e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfa20084-6e19-466c-9826-9e89d7f22ecb', 'Creating a single world government', false, '2f53acaa-1d77-4764-bb16-628be8f063e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57af73f0-6d5c-450c-9ac8-974c36ad61c5', 'Abolishing all national borders and languages', false, '2f53acaa-1d77-4764-bb16-628be8f063e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('730dbd34-b899-4eb6-9429-aab93af941da', 'Standardizing currency across all continents', false, '2f53acaa-1d77-4764-bb16-628be8f063e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12363a01-0f1b-4bf3-8e37-cf5d1837867a', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is the ''Common But Differentiated Responsibilities'' (CBDR) principle in international environmental treaties (UNFCCC)?', 'CBDR recognizes historical emission asymmetries, establishing that developed economies must lead emissions reductions and fund adaptation in the developing world.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c210340-9336-4c0c-8af4-b78dd3b8dbb4', 'All countries must address climate change, but developed nations that historically emitted the vast majority of greenhouse gases must take greater mitigation responsibility and provide climate finance to developing nations', true, '12363a01-0f1b-4bf3-8e37-cf5d1837867a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('107b6a44-1271-4f85-9fc0-33e700a71926', 'All nations pay the exact same amount of money', false, '12363a01-0f1b-4bf3-8e37-cf5d1837867a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4dc75c-8164-48f2-afc0-b8ed3c0a2272', 'Poor nations must stop all industries immediately', false, '12363a01-0f1b-4bf3-8e37-cf5d1837867a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59565751-d28c-4472-89ea-33f42b70bf78', 'Only island nations must plant trees', false, '12363a01-0f1b-4bf3-8e37-cf5d1837867a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1cf96cb9-701c-445d-bbb9-f187104fdc2a', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is the ''Shanghai Cooperation Organisation'' (SCO)?', 'The SCO (founded 2001, headquartered in Beijing) coordinates Eurasian regional security (RATS), counter-terrorism, and trade integration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('429487e3-f327-48eb-96fb-5c0854b4c07a', 'A major Eurasian political, economic, and defense organization comprising India, China, Russia, Pakistan, Iran, and Central Asian republics', true, '1cf96cb9-701c-445d-bbb9-f187104fdc2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd756798-0c75-4f2f-85ff-399bca12069d', 'A trade agreement between European cities', false, '1cf96cb9-701c-445d-bbb9-f187104fdc2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ac7d283-818c-4bb3-a8ea-c38294593db1', 'An African banking consortium', false, '1cf96cb9-701c-445d-bbb9-f187104fdc2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50fc9a28-f191-4134-8d91-0a5e9ff45804', 'A naval fleet in the Atlantic', false, '1cf96cb9-701c-445d-bbb9-f187104fdc2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db22f7f1-f066-4116-b627-348cee35e42c', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is ''UN Peacekeeping'' and what iconic gear distinguishes UN peacekeeping troops worldwide?', 'UN ''Blue Helmets'' maintain ceasefire monitoring and civilian protection (with India historically being among the largest troop-contributing nations).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('430942c8-3857-4b29-a16c-ea1c7b664f32', 'Multinational military and civilian personnel deployed by UNSC mandates to maintain peace and protect civilians in post-conflict zones, wearing distinctive BLUE HELMETS / Berets', true, 'db22f7f1-f066-4116-b627-348cee35e42c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('832e14a5-e5a1-4847-b780-5c992cd228b0', 'Soldiers who wear yellow jackets and carry no communication devices', false, 'db22f7f1-f066-4116-b627-348cee35e42c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e05d7ec-744c-45e5-afe8-38addf56ec31', 'A private army hired by banks', false, 'db22f7f1-f066-4116-b627-348cee35e42c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('774f8395-0c88-4155-87fb-5004f25cff3b', 'Naval sailors who guard cruise ships', false, 'db22f7f1-f066-4116-b627-348cee35e42c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('406231d0-87a1-47e1-b79c-e68ddcd07673', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What core vision for global humanity is embodied in Chapter 6 of General Knowledge?', 'Chapter 6 synthesizes global governance architecture, multilateral treaty frameworks, and the collective imperative for international cooperation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b61406ce-9772-4dd9-9455-2a2a7627abac', 'Multilateral diplomacy, international law, and global cooperation are essential instruments to resolve armed conflicts, eliminate poverty and disease, combat climate change, and build an inclusive, peaceful global community', true, '406231d0-87a1-47e1-b79c-e68ddcd07673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fd8529c-20ba-46bc-8720-ea9f16bf1962', 'That nations should isolate themselves completely from one another', false, '406231d0-87a1-47e1-b79c-e68ddcd07673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb2ebcd7-ec76-4d13-a862-d3e495fab229', 'That global problems solve themselves without international treaties', false, '406231d0-87a1-47e1-b79c-e68ddcd07673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7285337-c007-478e-976e-d0ac8e51bb7b', 'That international law applies only to small island states', false, '406231d0-87a1-47e1-b79c-e68ddcd07673');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79d818a9-c522-46d3-8b0d-1bd57b267a5f', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'What historic capital city of the Cholas was a premier administrative center, temple town, and thriving hub of craftspersons on the Kaveri river delta?', 'Thanjavur was the majestic Chola capital, home to the Brihadisvara Temple, royal palaces, silk weavers, and bronze sculptors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d697338e-fb56-45ea-bcf3-109e9f0c3373', 'Thanjavur (Tanjore)', true, '79d818a9-c522-46d3-8b0d-1bd57b267a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f3e8d1d-f797-4ae0-8199-9d098983f613', 'Hampi', false, '79d818a9-c522-46d3-8b0d-1bd57b267a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfb04e62-dce5-400d-be80-5e32a62a3ee1', 'Surat', false, '79d818a9-c522-46d3-8b0d-1bd57b267a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2955aae4-0e28-4da5-a91d-b77940e50cde', 'Masulipatnam', false, '79d818a9-c522-46d3-8b0d-1bd57b267a5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61f53da2-7de5-4ca0-910c-a81d54fac635', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'What ancient sculptural casting technique was used by bronze sculptors (Sthapatis) of Thanjavur to create world-famous Chola bronze idols (like Nataraja)?', 'The Lost-Wax (Cire Perdue) technique used beeswax models coated with clay, melted out, and replaced by molten bronze to cast exquisite idols.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('873ff80a-54ea-4fb7-beb5-f5ba3b9d4597', 'Lost-Wax Technique (Cire Perdue)', true, '61f53da2-7de5-4ca0-910c-a81d54fac635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1351b1e1-3c3b-4223-a52e-0640b4cd56d9', 'Sand Casting only', false, '61f53da2-7de5-4ca0-910c-a81d54fac635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff120871-e443-46b5-bf8e-740ea14bdd03', 'Hammering method', false, '61f53da2-7de5-4ca0-910c-a81d54fac635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a0ecf8a-3d51-40c9-9fbf-2747e169912d', 'Stone Carving', false, '61f53da2-7de5-4ca0-910c-a81d54fac635');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d82ad28-3f8d-4489-8d5d-ed8bd397e0a2', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'What was a weekly market in medieval small towns where villagers brought their agricultural produce to sell and bought articles from traders called?', 'Medieval towns had a mandapika (mandi) for grain trade and a hatta (haat) lined with shops for weekly rural and urban commerce.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ccf94ef-453c-41ab-912d-1801f6781927', 'Haat (or Hatta / Mandapika)', true, '0d82ad28-3f8d-4489-8d5d-ed8bd397e0a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aef4e72a-7714-480f-8ae5-6354e1efad17', 'Zabt', false, '0d82ad28-3f8d-4489-8d5d-ed8bd397e0a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1256c1d7-1d09-4258-b426-cdfaee1486aa', 'Jagir', false, '0d82ad28-3f8d-4489-8d5d-ed8bd397e0a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('691297ca-bbbf-4198-b127-1a683894f01c', 'Suba', false, '0d82ad28-3f8d-4489-8d5d-ed8bd397e0a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('491250f9-736c-4f54-8120-174d2a18e486', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'What were powerful merchant associations/corporations formed by medieval Indian traders (like Manigramam and Nanadesi) to protect their trade interests called?', 'Merchant Guilds (like Manigramam and Nanadesi) organized caravans, negotiated trade privileges, and traded across South India and Southeast Asia.', NOW()) ON CONFLICT DO NOTHING;
