INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1373c50-ca45-40fb-9617-b46d93ec06be', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'What financial credit instrument (a medieval bill of exchange) issued by Surat merchant bankers was honored in distant international markets like Cairo, Basra, and Antwerp?', 'A Hundi was a financial credit note recording a deposit that could be presented for payment at distant international trading banking houses.', NOW()) ON CONFLICT DO NOTHING;
