INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e7105fb-e265-4af4-988b-3a76d0dfcbbc', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'Which city in Rajasthan grew as a premier pilgrimage center around the Dargah of the revered 12th-century Sufi saint Khwaja Muinuddin Chishti and the sacred Pushkar lake?', 'Ajmer was a Chauhan capital and celebrated religious pilgrimage center housing the Chishti Dargah and ancient Pushkar lake.', NOW()) ON CONFLICT DO NOTHING;
