INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97daff17-2a70-4310-becb-9003683f5cd1', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'What prominent weaver communities of South India, such as the Saliyar and Kaikkolar, grew wealthy by donating large sums to monumental temple complexes?', 'The Saliyar and Kaikkolar textile weavers accumulated substantial wealth supplying temple flags, festival cloth, and royal garments.', NOW()) ON CONFLICT DO NOTHING;
