INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fa04827-9518-474a-8b89-bb4ac30259cc', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Why was Thanjavur considered a classic multifunctional town in medieval South India?', 'Thanjavur exemplified urban multifunctionality: combining administrative governance, temple-centered urbanization, and vibrant craft guilds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4108216-5c6d-4bd2-b33a-cba5fa066e55', 'It simultaneously performed three vital urban roles: an Administrative capital with royal courts, a sacred Temple Town with bustling pilgrim festivals, and a commercial Craft Center for bronze casting and silk weaving', true, '7fa04827-9518-474a-8b89-bb4ac30259cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('574ce8bf-58c7-4099-8765-1930bf31779c', 'Because it had no temples', false, '7fa04827-9518-474a-8b89-bb4ac30259cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('846e9d44-dd33-4a1f-ae78-de0055b685c4', 'Because only farmers lived there', false, '7fa04827-9518-474a-8b89-bb4ac30259cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3a1ae7b-b4ab-42a8-8aaa-6829506495a2', 'Because it was an underground town', false, '7fa04827-9518-474a-8b89-bb4ac30259cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cedd5da-5e75-4d4d-8c6c-660336b07019', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'How did Temple Towns (like Kanchipuram, Madurai, Tirupati, and Somnath) drive intense economic urbanization in medieval India?', 'Temple urbanization: temple endowments generated agrarian surpluses, financed credit networks, and fostered dense markets around sacred precincts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b2d1482-61e5-430e-b930-ed4287b9543b', 'Temples were endowed with massive royal land grants and gold; temple authorities invested their wealth in banking and trade, attracting large populations of priests, artisans, dancers, merchants, and pilgrims to settle permanently', true, '4cedd5da-5e75-4d4d-8c6c-660336b07019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9ac0fcb-38b5-4028-884d-9633d94634d8', 'Temples forced all citizens to become soldiers', false, '4cedd5da-5e75-4d4d-8c6c-660336b07019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9975b7f9-b805-432e-ac80-262179594ecf', 'Temples banned all buying and selling', false, '4cedd5da-5e75-4d4d-8c6c-660336b07019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbe561df-d21a-4162-88b8-e4b8e42fc981', 'Temples were closed to the public', false, '4cedd5da-5e75-4d4d-8c6c-660336b07019');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3fa8892-6533-4b16-9c5c-135f3e675038', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'How were the colossal stone fortifications of Hampi built without using any mortar or cementing material?', 'Domingo Paes and archaeological records show Hampi''s walls used precision interlocking dry-stone masonry without mortar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab074023-4ee9-44ab-9a00-f05ee5451e5c', 'The massive granite stone blocks were shaped with interlocking wedges and grooves, fitting tightly together like jigsaw puzzle pieces using pure dry masonry', true, 'e3fa8892-6533-4b16-9c5c-135f3e675038');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c40910af-482f-4472-99c3-32555e99bbb8', 'They were glued with clay', false, 'e3fa8892-6533-4b16-9c5c-135f3e675038');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca5501f1-36cc-40d9-94e8-3e25689f2599', 'They were melted together with fire', false, 'e3fa8892-6533-4b16-9c5c-135f3e675038');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14274253-3040-4ade-83eb-a58c883e1249', 'They were tied with ropes', false, 'e3fa8892-6533-4b16-9c5c-135f3e675038');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e38700b2-607f-40cc-aa42-db9c1d3935db', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What magnificent multi-pillared musical pavilion and chariot shrine in Hampi is dedicated to Lord Vishnu?', 'The Vittala temple in Hampi features the iconic monolithic Stone Chariot and pillared halls designed to resonate like musical instruments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9de171ad-099f-4848-9c24-6e5960d18c4a', 'The Vittala Temple (with its famous Stone Chariot and musical pillars)', true, 'e38700b2-607f-40cc-aa42-db9c1d3935db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2a3aa54-fe09-4a24-a271-28e5e0b6c8ff', 'The Virupaksha Temple', false, 'e38700b2-607f-40cc-aa42-db9c1d3935db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('916124f5-bf7e-4504-9635-7a0339bf1468', 'The Lotus Mahal', false, 'e38700b2-607f-40cc-aa42-db9c1d3935db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc793e71-210d-427e-9a1a-7fae8b7980fc', 'The Queen''s Bath', false, 'e38700b2-607f-40cc-aa42-db9c1d3935db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a315f69-174b-4202-9bd6-3f7f732cfec0', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What was the ''Mahanavami'' festival celebrated with immense royal pomp and military reviews on the grand Mahanavami Dibba platform at Hampi?', 'The Vijayanagara kings used the Mahanavami platform to project imperial sovereignty, review armed contingents, and collect feudal tribute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b53dc653-47e0-4680-939f-85ed51dc3d59', 'A 9-day grand festival (modern Navaratri / Durga Puja in the south) where the King received tribute from subordinate nayakas, inspected armies, and held wrestling and dance spectacles', true, '8a315f69-174b-4202-9bd6-3f7f732cfec0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a63c916e-faaf-45d2-baaf-6ebd8f4db36e', 'A harvest festival for rice', false, '8a315f69-174b-4202-9bd6-3f7f732cfec0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a5a9a16-4f1d-4373-a3d9-28da6b1e2e23', 'A celebration for the new year only', false, '8a315f69-174b-4202-9bd6-3f7f732cfec0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f5598c9-2a34-4c67-a2fb-d85860aa05a9', 'A feast for foreign ambassadors only', false, '8a315f69-174b-4202-9bd6-3f7f732cfec0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76e00751-b820-4741-ac94-c4511fb1b7ef', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'In what decisive battle in 1565 CE was the Vijayanagara Empire defeated, leading to the sacking and ruin of the city of Hampi?', 'In 1565 at Talikota, the unified confederacy of Deccan Sultanates crushed Rama Raya''s army, pillaging Hampi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('425aad5f-1d56-4152-860c-7ebfe7a0716b', 'The Battle of Talikota (Rakshasi-Tangadi), fought against the combined armies of the Deccan Sultanates (Bijapur, Golconda, Ahmadnagar, Bidar)', true, '76e00751-b820-4741-ac94-c4511fb1b7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4215277-8a50-4a42-9812-032ca8050b0c', 'The Battle of Panipat', false, '76e00751-b820-4741-ac94-c4511fb1b7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d871c85-8cea-46a3-ab66-bca92bc61b2c', 'The Battle of Plassey', false, '76e00751-b820-4741-ac94-c4511fb1b7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce38a3f9-7699-49e1-9651-c930cc0125a7', 'The Battle of Khanwa', false, '76e00751-b820-4741-ac94-c4511fb1b7ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c99e566-57f1-4bc3-892b-ccbdb98c3d72', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Why was Surat called a cosmopolitan city in the 17th century?', 'Surat was a global cosmopolitan entrepôt hosting multi-ethnic merchant houses, textile markets, and European chartered company factories.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('009414bf-8a85-47f6-bfb4-6628c6ea2a25', 'People of all castes, creeds, and nationalities (Indians, Persians, Arabs, Portuguese, Dutch, English, and French) lived, traded, and established commercial factories there', true, '1c99e566-57f1-4bc3-892b-ccbdb98c3d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65922d0d-0a8c-4f68-82d6-c2f89a78e918', 'Because everyone spoke only one language', false, '1c99e566-57f1-4bc3-892b-ccbdb98c3d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('befe134d-435b-49e6-b363-202996ff0b76', 'Because it had only one shop', false, '1c99e566-57f1-4bc3-892b-ccbdb98c3d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('609c21c3-652c-4094-b5d0-de612b5f87bf', 'Because only kings were allowed to enter', false, '1c99e566-57f1-4bc3-892b-ccbdb98c3d72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('111b1fdd-945b-48c1-a1c8-1c6102a489c9', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What specialty luxury cotton textile produced in Surat was famous across Asian and European markets for its woven gold-thread borders (Zari)?', 'Surat''s zari textiles (brocades with real gold and silver threads) were exported widely across West Asia, Africa, and Europe.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9412a30-f072-4508-89e5-6c6b20432682', 'Zari-bordered Cotton and Silk Textiles (Zardozi)', true, '111b1fdd-945b-48c1-a1c8-1c6102a489c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b83fbc47-f7bb-44b9-9660-0bae5894a27c', 'Kalamkari prints', false, '111b1fdd-945b-48c1-a1c8-1c6102a489c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4b4e270-6375-4893-bc26-4a2c329c53dd', 'Chintz prints', false, '111b1fdd-945b-48c1-a1c8-1c6102a489c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a40cd48b-a493-4050-836d-25ef90ddb93a', 'Muslin only', false, '111b1fdd-945b-48c1-a1c8-1c6102a489c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6da3d835-3012-41f3-a5fe-f1102b767837', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What caused the commercial decline of Surat towards the late 17th and early 18th century?', 'Surat''s decline followed Mughal imperial decentralization, Maratha raids (1664/1670), and the shift of English headquarters to Bombay.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('904c0bc7-5a91-4742-8135-7ff3f2d341f5', 'Loss of markets due to the decline of the Mughal Empire, control of sea trade routes by the Portuguese, and the rise of Bombay (Mumbai) as the English East India Company''s headquarters in 1668', true, '6da3d835-3012-41f3-a5fe-f1102b767837');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('990785cf-2d1e-4638-885a-1e3f41ffd76d', 'Surat was swallowed by an earthquake', false, '6da3d835-3012-41f3-a5fe-f1102b767837');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3001961-0963-4e88-b2d5-145ed78e6664', 'All merchants stopped wearing clothes', false, '6da3d835-3012-41f3-a5fe-f1102b767837');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d861b48-9913-449b-9a59-55fe0d521ec3', 'The river dried up in one day', false, '6da3d835-3012-41f3-a5fe-f1102b767837');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8cfa9c7-7d30-4ed7-9947-68f455da56af', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Why did the Golconda rulers enforce a strict royal monopoly on the sale of textiles, spices, and diamonds in Masulipatnam?', 'The Qutb Shahi kings imposed state monopolies to prevent monopolistic takeover of maritime commerce by the Dutch and English companies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1eea18a-f7b0-495a-a0a3-af2397bfb604', 'To prevent the trade from passing entirely into the hands of competing European East India companies (Dutch and English)', true, 'd8cfa9c7-7d30-4ed7-9947-68f455da56af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84b2fa35-0372-43d9-b722-f88128fa2967', 'Because they wanted to stop all trade', false, 'd8cfa9c7-7d30-4ed7-9947-68f455da56af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac606586-e0b3-47c0-8da3-dd30dd579697', 'Because they had no money to buy food', false, 'd8cfa9c7-7d30-4ed7-9947-68f455da56af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4432da70-a460-49a3-b106-e4a54dd22ea3', 'To destroy the city of Masulipatnam', false, 'd8cfa9c7-7d30-4ed7-9947-68f455da56af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b872453-d95b-42ec-98c2-f0af90fb3e41', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What is ''Kalamkari'' textile art, which flourished in Masulipatnam and Kalahasti?', 'Kalamkari (Kalam = pen, Kari = craftsmanship) employs natural mordants and vegetable dyes applied with bamboo pens on cotton cloth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d536da3-05fe-4faf-99a4-5556be3b1f21', 'The traditional craft of hand-painting or block-printing intricate floral and mythological motifs on cotton fabric using a natural bamboo reed pen (''Kalam'') and vegetable dyes', true, '1b872453-d95b-42ec-98c2-f0af90fb3e41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe93500f-89ce-46c5-b7fa-0f7b3fd608fd', 'Knitting wool with metal needles', false, '1b872453-d95b-42ec-98c2-f0af90fb3e41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cb8027d-87c5-4792-8161-0bfbc643e5d7', 'Stitching shoes with leather', false, '1b872453-d95b-42ec-98c2-f0af90fb3e41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a11abfc-b8c1-42e7-a6a7-68e3e2db9065', 'Painting on glass plates', false, '1b872453-d95b-42ec-98c2-f0af90fb3e41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba498223-662f-4719-8044-3f403e01bff7', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What was the ''Panchalas'' or ''Vishwakarma'' community of craftspersons, comprising goldsmiths, bronzesmiths, blacksmiths, masons, and carpenters?', 'The Vishwakarma (Panchala) collective united five master artisan castes essential to temple architecture, metallurgy, and royal infrastructure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a37913-5800-4cf9-8503-d338e159b996', 'Essential skilled builders and artisans who built monumental temples, royal palaces, massive tanks, and manufactured metal implements and idols', true, 'ba498223-662f-4719-8044-3f403e01bff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cbc9e16-46d4-46f5-a7ba-18a01a8dd5fa', 'A group of wandering musicians only', false, 'ba498223-662f-4719-8044-3f403e01bff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0873d24-4e5c-428f-bde0-4a5d328876a7', 'Soldiers who guarded fort gates', false, 'ba498223-662f-4719-8044-3f403e01bff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0c8aa46-0dbe-4597-a050-b31de2a7044f', 'Farmers who grew only wheat', false, 'ba498223-662f-4719-8044-3f403e01bff7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac8ac750-6a86-43e6-bb50-eba05bd3aead', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What were the ''Black Towns'' established by the British East India Company in newly rising port cities like Madras (Chennai), Bombay, and Calcutta?', 'Colonial racial spatial segregation: European administrators occupied fortified ''White Towns'', confining indigenous artisans to ''Black Towns''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a879d55-2a31-4962-87b2-a6da40781338', 'Segregated native quarters where Indian weavers, artisans, and merchant middlemen were forced to live and work, separate from the ''White'' residential forts (Fort St. George / Fort William)', true, 'ac8ac750-6a86-43e6-bb50-eba05bd3aead');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e5fc2f7-1d74-41ed-806c-ad679efe4bff', 'Towns where coal was mined', false, 'ac8ac750-6a86-43e6-bb50-eba05bd3aead');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e4ce976-fb98-4cad-a8d4-0b0ca417a2d2', 'Towns painted with black paint', false, 'ac8ac750-6a86-43e6-bb50-eba05bd3aead');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7d26c7a-5e14-4523-8e3a-f4e9d89ede6e', 'Towns with no street lamps', false, 'ac8ac750-6a86-43e6-bb50-eba05bd3aead');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('769e0ad6-a1aa-44de-a8d4-0ea80d828b8e', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Which Indian merchant banking family in Murshidabad (Bengal) became fabulously wealthy and wielded enormous political influence in 18th-century Bengal?', 'The House of Jagat Seth (''Banker of the World'') controlled Bengal''s mint, revenue remittances, and treasury operations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e278df57-e6ab-43a8-93d8-cc402b69ded0', 'The House of Jagat Seth', true, '769e0ad6-a1aa-44de-a8d4-0ea80d828b8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b74a9aae-4e8a-4195-bf48-5993c28e3966', 'The Oswal Bankers', false, '769e0ad6-a1aa-44de-a8d4-0ea80d828b8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ef3c3aa-16bb-418f-a2bc-41d3c38502cf', 'The Chettiar Trust', false, '769e0ad6-a1aa-44de-a8d4-0ea80d828b8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9af1ec74-9413-4ac7-889f-89e17865852f', 'The Peshwas', false, '769e0ad6-a1aa-44de-a8d4-0ea80d828b8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1ac8c84-9071-40dd-a4c9-2a0bfcc4f399', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What was the system of ''Advances'' (Dadni system) introduced by European trading companies that stripped Indian weavers of their economic independence?', 'The Dadni advance system bonded weavers to company procurement contracts, extinguishing their freedom to negotiate market prices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f003f6c6-8bb7-4e5e-831e-9c90ed825470', 'Weavers took cash loans in advance from European agents and were legally locked into producing cloth exclusively for that company at low fixed prices, unable to sell in the open market', true, 'b1ac8c84-9071-40dd-a4c9-2a0bfcc4f399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c68f941-7d77-4294-ae5d-fa2996f1892d', 'Weavers were given free houses', false, 'b1ac8c84-9071-40dd-a4c9-2a0bfcc4f399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c44b4dd5-e66a-46b4-a647-bcfb872a6483', 'Weavers were trained to be ship captains', false, 'b1ac8c84-9071-40dd-a4c9-2a0bfcc4f399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb8c08df-941f-4282-9ded-14850d8cc66f', 'Weavers were paid double wages', false, 'b1ac8c84-9071-40dd-a4c9-2a0bfcc4f399');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01e91f88-4547-400b-9246-76d7aeb3bbc6', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Why was bronze considered an ideal metal alloy for casting sacred temple idols in medieval India?', 'High-tin bell metal bronze provided superior fluidity for intricate cire-perdue molds, corrosion resistance, and sonorous resonance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07b8fcf9-e832-4a88-8307-60c48bb36ccd', 'Bronze is an alloy of Copper and Tin (Bell Metal contains greater tin), which does not rust, produces a melodious bell-like chime when struck, and allows intricate high-definition casting', true, '01e91f88-4547-400b-9246-76d7aeb3bbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9c78daa-c278-44f9-84ba-ed3291a33101', 'Because bronze is soft like butter', false, '01e91f88-4547-400b-9246-76d7aeb3bbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2c3b997-f9d2-475f-ab79-1a0066cacd59', 'Because bronze melts in cold water', false, '01e91f88-4547-400b-9246-76d7aeb3bbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a813bd33-c4b8-41cd-ab62-4c563c08d4cf', 'Because bronze is made of pure wood', false, '01e91f88-4547-400b-9246-76d7aeb3bbc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5fa3d34-9f24-4593-b2d2-a80aaffba969', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51e97876-8f79-4200-9f85-430340a93ec3', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c5fa3d34-9f24-4593-b2d2-a80aaffba969');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7d42a14-bc05-4a54-b2d2-b3e87f2742a7', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c5fa3d34-9f24-4593-b2d2-a80aaffba969');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1309d154-a650-4cd6-927a-587033f08119', '(A) is true, but (R) is false.', false, 'c5fa3d34-9f24-4593-b2d2-a80aaffba969');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99397ae5-e2f8-4535-9c99-0a1445cfc368', '(A) is false, but (R) is true.', false, 'c5fa3d34-9f24-4593-b2d2-a80aaffba969');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c12a218b-0b33-442a-b6ae-0b8c5973c6c6', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Spot the IMPOSTER in the following medieval Indian craft centers and their signature artisanal products:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62678df4-751d-46b5-bb4e-72701e2c7088', 'Center 1', false, 'c12a218b-0b33-442a-b6ae-0b8c5973c6c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ea620b9-36f2-4499-a64e-52d14884ae15', 'Center 2', false, 'c12a218b-0b33-442a-b6ae-0b8c5973c6c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68c5d942-c37c-4f70-b74d-1a21364234de', 'Center 3', false, 'c12a218b-0b33-442a-b6ae-0b8c5973c6c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f2d7ef1-053f-4eb8-899c-bb3b0fbf5ced', 'Center 4 (Thanjavur was celebrated for CHOLA BRONZE IDOL CASTING and silk weaving, not 19th-century railway engines)', true, 'c12a218b-0b33-442a-b6ae-0b8c5973c6c6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0081df60-fea4-4a20-85f1-e7563becaf5c', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Analyze the shifting spatial dynamics of urbanization in 17th–18th century India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6082b1e-b17b-4693-90c5-4771de4eb48a', 'European chartered companies secured naval hegemony, monopolized maritime shipping routes, redirected raw materials to their fortified presidency ports, and forced weavers into subordinated wage-labor networks', true, '0081df60-fea4-4a20-85f1-e7563becaf5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c63464d0-4331-44f0-87e1-2e86e4925bcb', 'Because all artisans voluntarily left India', false, '0081df60-fea4-4a20-85f1-e7563becaf5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4d35c98-f9af-4b2d-b00f-00d120d3f2f8', 'Because the Indian Ocean dried up', false, '0081df60-fea4-4a20-85f1-e7563becaf5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c17111b5-d3e8-4072-8444-eacf43aa737c', 'Because European ships were made of glass', false, '0081df60-fea4-4a20-85f1-e7563becaf5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7d48df2-b55e-41e4-959a-83d8b4f51101', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Match Column I (Medieval Trade / Craft Centers) with Column II (Prominent Distinctive Characteristics):
(a) Hampi        -> (i) Fortified capital with interlocking mortar-less granite masonry & lively bazaars
(b) Surat        -> (ii) Emporium of Western trade, pilgrim port to Mecca, famous for Zari & Hundis
(c) Masulipatnam -> (iii) Coromandel port city, center of Kalamkari cottons & Qutb Shahi monopolies
(d) Murshidabad  -> (iv) Bengal silk capital on Bhagirathi river, home to the wealthy Jagat Seths', 'Accurate historical profiling: Hampi (Vijayanagara); Surat (Mughal emporium); Masulipatnam (Coromandel port); Murshidabad (Bengal silk & banking).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00df6f49-e4c8-43d0-962f-51f0a88b0f2e', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'b7d48df2-b55e-41e4-959a-83d8b4f51101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0ba2ea2-d7c1-4479-9135-858784f334d5', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'b7d48df2-b55e-41e4-959a-83d8b4f51101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9583ffac-985f-4980-9289-2fe888e08a70', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b7d48df2-b55e-41e4-959a-83d8b4f51101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a23db3e-84f2-434a-a1bd-fce13dfd1b92', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b7d48df2-b55e-41e4-959a-83d8b4f51101');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3013eff2-df86-401d-a0a5-ed7c8c650dbb', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Read the statements regarding the Lost-Wax (Cire Perdue) bronze casting technique:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('440ce995-993f-4c21-85d4-81987651933c', 'All Statements 1, 2, and 3 are TRUE', true, '3013eff2-df86-401d-a0a5-ed7c8c650dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a381551e-436b-4263-b3f4-cf35b1c42214', 'Statements 1 and 2 only', false, '3013eff2-df86-401d-a0a5-ed7c8c650dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21dcf07a-778c-4321-a326-6157bb70237b', 'Statements 2 and 3 only', false, '3013eff2-df86-401d-a0a5-ed7c8c650dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1e61e9f-dc13-4112-a231-4b3178944372', 'Statements 1 and 3 only', false, '3013eff2-df86-401d-a0a5-ed7c8c650dbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f1b61a1-f606-4bd3-b225-6b6148d0d811', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'What was the socio-economic role of ''Samantas'' (feudal lords / chiefs) in the emergence of small medieval towns (Mandapikas and Hattas)?', 'Feudal lords extracted tolls on commodities (sugar, butter, cloth, salt) and patronized temple endowments with inscribed taxation rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f1c8041-3903-4c81-9c1b-a1ca4253d98d', 'Samantas built fortified palaces near markets, levied commercial transit tolls on traders, and donated the right to collect market taxes to temples in exchange for religious legitimacy', true, '3f1b61a1-f606-4bd3-b225-6b6148d0d811');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('215322e8-125e-4e7c-99da-07eb16b8c31c', 'Samantas lived as forest hermits', false, '3f1b61a1-f606-4bd3-b225-6b6148d0d811');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d34f6e9d-227d-408b-9aff-d6efca498c36', 'Samantas abolished all private trade', false, '3f1b61a1-f606-4bd3-b225-6b6148d0d811');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8df8aacf-fe7a-488b-9a8b-7ce5621f199e', 'Samantas built ships to invade Europe', false, '3f1b61a1-f606-4bd3-b225-6b6148d0d811');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0c8f70f-d9b6-48ec-8220-1e07892036f1', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Why did European travel chroniclers like Domingo Paes (Portuguese) and Duarte Barbosa express immense awe at the wealth of Hampi''s bazaars?', 'Paes and Barbosa documented open street diamond markets, global equine trade, and bustling multi-ethnic commerce in 16th-century Vijayanagara.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59e2fa89-95dd-42e8-a6f7-932269801d3a', 'The markets were overflowing with ruby, diamond, and pearl jewelry sold openly on streets, alongside Persian war horses, fine textiles, and precious spices', true, 'f0c8f70f-d9b6-48ec-8220-1e07892036f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6ddf90a-60e9-408d-9ec1-ad666a90a622', 'Because Hampi had no people', false, 'f0c8f70f-d9b6-48ec-8220-1e07892036f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca295d73-b327-4904-8a78-768fbc9d484c', 'Because everything was made of iron', false, 'f0c8f70f-d9b6-48ec-8220-1e07892036f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0472f6d6-68e2-46d9-9ad2-57f0f15cb382', 'Because all goods were imported from America', false, 'f0c8f70f-d9b6-48ec-8220-1e07892036f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('437f3406-5e2a-4e8b-8168-c8f8dbcd693b', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'How did the ''Kalamkari'' textiles of Golconda and Coromandel conquer international trade networks in Southeast Asia and Europe?', 'Indian mordant-dyeing chemistry created vibrant, wash-fast calicos and chintzes, making Indian textiles the preeminent global trade currency.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0252d144-5138-48a4-8676-d22fa390536f', 'Their brilliant natural vegetable dyes were exceptionally color-fast (resisting fading upon washing), while their exotic hand-painted Chintz designs appealed to European nobility and Indonesian spice traders', true, '437f3406-5e2a-4e8b-8168-c8f8dbcd693b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('282e0ed4-1f5a-4e7e-a230-377d27f7c709', 'Because they were made of plastic', false, '437f3406-5e2a-4e8b-8168-c8f8dbcd693b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('443d6ad6-8fff-434e-889b-2b6bd75d7c6e', 'Because they were given away for free', false, '437f3406-5e2a-4e8b-8168-c8f8dbcd693b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82e3424d-c963-44af-8927-3d02bd3fe2ce', 'Because European factories could not make any cloth', false, '437f3406-5e2a-4e8b-8168-c8f8dbcd693b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d909362f-37b7-418e-bd56-8c808d120fde', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Consider four merchant trading communities of medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49340188-2492-4afc-8101-88862bc157d5', 'They integrated diverse geographic regions into a unified trans-continental commercial and financial web, facilitating commodity exchange and capital flows', true, 'd909362f-37b7-418e-bd56-8c808d120fde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1ecad69-1dc4-4384-a154-3c49c9b99640', 'They only traded within their own single villages', false, 'd909362f-37b7-418e-bd56-8c808d120fde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bef18ee6-92d4-4b1f-b1dd-e6405b4420e1', 'They destroyed all money and used barter only', false, 'd909362f-37b7-418e-bd56-8c808d120fde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2553bd6b-0052-4a98-bfe9-2c5ef282e131', 'They served exclusively as palace cooks', false, 'd909362f-37b7-418e-bd56-8c808d120fde');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13cb9762-908b-44a9-ae46-f43814e19b4f', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'What does the English traveler Peter Mundy''s 17th-century eyewitness account reveal about the logistical scale of a Banjara ''Tanda''?', 'Peter Mundy recorded giant Banjara tandas with over 14,000 oxen transporting grain, functioning as autonomous nomadic freight corporations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d77dc6ad-fdee-405d-bb2f-e75b3c3af14f', 'A single Tanda caravan comprised up to 14,000 to 20,000 bullocks laden with grain, moving with families, children, and livestock over hundreds of miles to feed cities and military camps', true, '13cb9762-908b-44a9-ae46-f43814e19b4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb10a2a8-3b03-4dd8-8487-459c532a11d9', 'Banjaras traveled in flying carts', false, '13cb9762-908b-44a9-ae46-f43814e19b4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddc90303-ba72-4030-a5e8-8e835771911c', 'Banjaras carried goods on their heads only', false, '13cb9762-908b-44a9-ae46-f43814e19b4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7b6aa04-2653-4a68-abe1-bd3210d35766', 'A Tanda had only one donkey', false, '13cb9762-908b-44a9-ae46-f43814e19b4f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a2f5bf4-45be-472a-8316-a79646541f27', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'How did the invention and usage of the ''Hundi'' demonstrate the sophisticated level of financial capitalism in medieval India?', 'Hundis reflected mature indigenous mercantile capitalism, combining credit discounting, foreign exchange, and risk-hedged capital remittance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0a9f4ce-7199-4cbe-b27b-4cea9e70dc33', 'It proved the existence of an intricate inter-regional banking network based on trust, merchant creditworthiness, and standardized financial instruments operating across thousands of kilometers', true, '9a2f5bf4-45be-472a-8316-a79646541f27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec1d1705-f36b-4d5d-ad9c-9868604e0de0', 'It showed that paper did not exist', false, '9a2f5bf4-45be-472a-8316-a79646541f27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88ba99dc-4bcb-45ee-82fd-219ef18e9af3', 'It proved that kings had no gold', false, '9a2f5bf4-45be-472a-8316-a79646541f27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('960d70f4-ed4d-472b-9549-1b5e0d23f3e3', 'It was used to buy ships from pirates', false, '9a2f5bf4-45be-472a-8316-a79646541f27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('339eb16d-0691-4278-b427-b330b74a37e2', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'What master socio-economic narrative is highlighted in Chapter 6 of NCERT Class 7 History?', 'Chapter 6 celebrates the economic sophistication, architectural vibrancy, artisanal mastery, and global trade preeminence of medieval India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d94dae5a-2269-4aac-bdc6-02a684a197aa', 'The vibrancy of medieval Indian urban life, where specialized artisans, flourishing merchant guilds, dynamic pilgrimage temple towns, and world-class manufacturing ports formed a globally dominant trade ecosystem before colonial restructuring', true, '339eb16d-0691-4278-b427-b330b74a37e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6329e32-9d6f-4591-ac7d-bfc7f59f17a9', 'A period of total poverty and complete trade collapse', false, '339eb16d-0691-4278-b427-b330b74a37e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('840dcec1-ec3a-47aa-9aeb-f16e6ee440ca', 'An era without any towns or crafts', false, '339eb16d-0691-4278-b427-b330b74a37e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13c35f4a-d384-4c85-addd-0bf7957520c0', 'The destruction of all Indian textiles', false, '339eb16d-0691-4278-b427-b330b74a37e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2833746-a4e8-420b-9283-76f92034ce9b', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'किसी व्यक्ति, वस्तु, स्थान, प्राणी या भाव के नाम का बोध कराने वाले सार्थक शब्दों को व्याकरण में क्या कहते हैं?', 'संज्ञा: किसी व्यक्ति, वस्तु, स्थान, प्राणी या भाव के नाम को संज्ञा कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b2b6637-603d-45b6-a018-01b99761e1ad', 'संज्ञा (Noun)', true, 'b2833746-a4e8-420b-9283-76f92034ce9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f0fedd4-d44c-4ca4-9991-2579aeac1c5e', 'सर्वनाम', false, 'b2833746-a4e8-420b-9283-76f92034ce9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61beac0a-0e6a-4981-b5b2-d45a7c94dd9f', 'विशेषण', false, 'b2833746-a4e8-420b-9283-76f92034ce9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1f39d9a-8de6-43ff-8a97-e928cf012c7d', 'क्रिया', false, 'b2833746-a4e8-420b-9283-76f92034ce9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17870931-b39e-494d-826f-9288eb8be659', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'हिंदी व्याकरण में संज्ञा के मुख्य रूप से कितने भेद माने गए हैं?', 'संज्ञा के 3 मुख्य भेद हैं: व्यक्तिवाचक, जातिवाचक (जिसके अंतर्गत द्रव्यवाचक व समूहवाचक आते हैं), और भाववाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c37e1580-0f45-4531-a4bb-6bd43987a2e6', 'तीन मुख्य भेद (1. व्यक्तिवाचक संज्ञा, 2. जातिवाचक संज्ञा, 3. भाववाचक संज्ञा)', true, '17870931-b39e-494d-826f-9288eb8be659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f84ab01-dab0-419f-b296-ea5e1b0c609f', 'पाँच मुख्य भेद', false, '17870931-b39e-494d-826f-9288eb8be659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('517945a3-76ab-419f-9d5e-03837eeeaa36', 'दो मुख्य भेद', false, '17870931-b39e-494d-826f-9288eb8be659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78a67c73-0dd3-497c-a2d6-c0c5483ad9b7', 'चार मुख्य भेद', false, '17870931-b39e-494d-826f-9288eb8be659');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59b6ebb1-dbd0-472e-ba25-34baf96d426d', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन संज्ञा शब्दों से किसी एक ''विशेष'' व्यक्ति, विशेष प्राणी, विशेष वस्तु या विशेष स्थान का बोध होता है, उन्हें क्या कहते हैं?', 'किसी विशिष्ट सत्ता, व्यक्ति या भौगोलिक नाम का बोध कराने वाले शब्द ''व्यक्तिवाचक संज्ञा'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('130d6d0f-3554-4747-a6a1-3852cb688e60', 'व्यक्तिवाचक संज्ञा (Proper Noun - जैसे: भारत, गंगा, हिमालय, महात्मा गांधी, रामायण)', true, '59b6ebb1-dbd0-472e-ba25-34baf96d426d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77c4c0dc-31f1-4f17-98a0-db25e9430bef', 'जातिवाचक संज्ञा', false, '59b6ebb1-dbd0-472e-ba25-34baf96d426d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('489a4d34-31bb-4706-aaf6-0501c19b9c40', 'भाववाचक संज्ञा', false, '59b6ebb1-dbd0-472e-ba25-34baf96d426d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef51e178-dba8-4bf6-887b-e4663cb92581', 'द्रव्यवाचक संज्ञा', false, '59b6ebb1-dbd0-472e-ba25-34baf96d426d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4bbd0ab-4345-4e97-8c02-f711449a6c61', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन संज्ञा शब्दों से किसी प्राणी, वस्तु या स्थान की ''संपूर्ण जाति या वर्ग'' का बोध होता है, उन्हें क्या कहते हैं?', 'संपूर्ण प्रजाति, वर्ग या श्रेणी का सामान्य बोध कराने वाले शब्द ''जातिवाचक संज्ञा'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34becb32-6fa7-4076-8fa8-e062c2755819', 'जातिवाचक संज्ञा (Common Noun - जैसे: नदी, पर्वत, लड़का, देश, नगर, पुस्तक)', true, 'd4bbd0ab-4345-4e97-8c02-f711449a6c61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e77a650-10cc-44f4-b693-21f951aeba93', 'व्यक्तिवाचक संज्ञा', false, 'd4bbd0ab-4345-4e97-8c02-f711449a6c61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b11eab3e-ce40-435a-8945-db83edc3a1c5', 'भाववाचक संज्ञा', false, 'd4bbd0ab-4345-4e97-8c02-f711449a6c61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03fd037e-84b8-46a4-9998-437278dbab8e', 'सर्वनाम', false, 'd4bbd0ab-4345-4e97-8c02-f711449a6c61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a0a053d-e157-42bb-a88f-2716edbb77e5', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन शब्दों से किसी पदार्थ के गुण, दोष, दशा, अवस्था, स्वभाव या भाव का बोध होता है और जिन्हें केवल अनुभव किया जा सकता है, उन्हें क्या कहते हैं?', 'अमूर्त गुण, भाव, दशा और अवस्था का बोध कराने वाले शब्द ''भाववाचक संज्ञा'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfd0ed85-67e6-45fc-9a5a-cac1e1973c9a', 'भाववाचक संज्ञा (Abstract Noun - जैसे: मिठास, बचपन, सुंदरता, क्रोध, ईमानदारी, बुढ़ापा)', true, '0a0a053d-e157-42bb-a88f-2716edbb77e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65786734-6435-4b7e-a13d-6f8af93af77d', 'जातिवाचक संज्ञा', false, '0a0a053d-e157-42bb-a88f-2716edbb77e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92788eed-67eb-4b7c-9e83-543dae5f3d5d', 'द्रव्यवाचक संज्ञा', false, '0a0a053d-e157-42bb-a88f-2716edbb77e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf78ca0a-4cee-4c9f-969d-165d303643b5', 'व्यक्तिवाचक संज्ञा', false, '0a0a053d-e157-42bb-a88f-2716edbb77e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a127726-de6d-46f9-ac5c-da83bd4dff17', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन संज्ञा शब्दों से किसी धातु, द्रव्य, तरल या ठोस पदार्थ का बोध होता है जिन्हें नापा या तौला जा सकता है, उन्हें क्या कहते हैं?', 'माप-तोल योग्य धातुओं, खनिजों और द्रवों के नाम ''द्रव्यवाचक संज्ञा'' (जातिवाचक का उप-भेद) कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af267a3a-9785-4c5f-b459-2504d47c469a', 'द्रव्यवाचक संज्ञा (Material Noun - जैसे: सोना, चाँदी, दूध, पानी, तेल, गेहूँ)', true, '9a127726-de6d-46f9-ac5c-da83bd4dff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ddc2591-aa61-4376-800d-d6a85d338866', 'समूहवाचक संज्ञा', false, '9a127726-de6d-46f9-ac5c-da83bd4dff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db0dc62e-ed1b-4bc6-841b-b7933fedb417', 'भाववाचक संज्ञा', false, '9a127726-de6d-46f9-ac5c-da83bd4dff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16f848c3-e52d-49d8-a56f-0cf46d0c82d8', 'व्यक्तिवाचक संज्ञा', false, '9a127726-de6d-46f9-ac5c-da83bd4dff17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7986a230-4c95-4feb-b968-4e9cc9bd2955', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन संज्ञा शब्दों से व्यक्तियों या वस्तुओं के ''समूह अथवा समुदाय'' का बोध होता है, उन्हें क्या कहते हैं?', 'समूह या झुंड का एकवचन रूप में बोध कराने वाले शब्द ''समूहवाचक संज्ञा'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09ecc332-8f4a-4c04-97c4-e6d14ded00e9', 'समूहवाचक / समुदायवाचक संज्ञा (Collective Noun - जैसे: कक्षा, सेना, सभा, झुंड, भीड़, गुच्छा)', true, '7986a230-4c95-4feb-b968-4e9cc9bd2955');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da726607-2c11-475c-a5f6-7e249a1f272f', 'द्रव्यवाचक संज्ञा', false, '7986a230-4c95-4feb-b968-4e9cc9bd2955');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('529a8f49-c678-4424-bad4-34f9dc5a2514', 'व्यक्तिवाचक संज्ञा', false, '7986a230-4c95-4feb-b968-4e9cc9bd2955');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0324ad6-9fed-4399-b72d-d1106d58d0f0', 'भाववाचक संज्ञा', false, '7986a230-4c95-4feb-b968-4e9cc9bd2955');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a0f3120-bd14-4be0-a573-72c76b4dd14d', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', '''गंगा भारत की सबसे पवित्र नदी है।'' वाक्य में ''गंगा'' और ''नदी'' क्रमशः कौन-सी संज्ञाएँ हैं?', '''गंगा'' एक विशिष्ट नदी का नाम है (व्यक्तिवाचक); ''नदी'' संपूर्ण जलधाराओं की जाति है (जातिवाचक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f05bed7-3c27-4d6b-bd74-e00cc94f1d90', '''गंगा'' व्यक्तिवाचक संज्ञा है और ''नदी'' जातिवाचक संज्ञा है', true, '5a0f3120-bd14-4be0-a573-72c76b4dd14d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a7f0853-f621-4b54-836e-74cf60f104ac', 'दोनों व्यक्तिवाचक हैं', false, '5a0f3120-bd14-4be0-a573-72c76b4dd14d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c867a146-26ec-44b0-881a-e16f9f2b894e', 'दोनों जातिवाचक हैं', false, '5a0f3120-bd14-4be0-a573-72c76b4dd14d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cecde953-2bee-4391-9d78-f2fe0dad682b', '''गंगा'' भाववाचक है और ''नदी'' द्रव्यवाचक है', false, '5a0f3120-bd14-4be0-a573-72c76b4dd14d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a2644fe-7287-47d4-a9f4-d9e79741811a', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', '''बच्चा'' जातिवाचक संज्ञा शब्द से बनने वाली सही भाववाचक संज्ञा क्या होगी?', '''बच्चा'' में ''पन'' प्रत्यय लगने से भाववाचक संज्ञा ''बचपन'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75d35d41-1122-4248-8173-e64fd93efd8c', 'बचपन', true, '1a2644fe-7287-47d4-a9f4-d9e79741811a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf19607a-251d-4117-8ec0-4a294bf470ed', 'बच्चे', false, '1a2644fe-7287-47d4-a9f4-d9e79741811a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e3cf761-9951-454e-95e0-18ca7d15d7e5', 'बचपनापन', false, '1a2644fe-7287-47d4-a9f4-d9e79741811a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d44183a4-46e2-4379-b3fe-b391bfb40c25', 'बालक', false, '1a2644fe-7287-47d4-a9f4-d9e79741811a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b532640e-84a3-4c2e-ab78-98b82d2d23e1', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', '''सुंदर'' विशेषण शब्द से बनने वाली शुद्ध भाववाचक संज्ञा कौन-सी है?', 'सुंदर + ता = सुंदरता ; सुंदर + य = सौंदर्य (भाववाचक संज्ञाएँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27e00207-74f6-4cce-9f3e-988d77cea462', 'सुंदरता अथवा सौंदर्य', true, 'b532640e-84a3-4c2e-ab78-98b82d2d23e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f51bfc6e-b285-4812-97ce-887f4f44cd41', 'सुंदरी', false, 'b532640e-84a3-4c2e-ab78-98b82d2d23e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f46cf1df-440b-42d4-8261-f29859427918', 'सुंदरतम', false, 'b532640e-84a3-4c2e-ab78-98b82d2d23e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aefff26f-0d77-4f45-ab5a-7341bc2a5ffb', 'सुंदरपना', false, 'b532640e-84a3-4c2e-ab78-98b82d2d23e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('748fcfc1-09c7-4925-ad3c-57f6b4bf5d3c', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', '''हँसना'' क्रिया शब्द से बनने वाली सही भाववाचक संज्ञा क्या है?', '''हँसना'' क्रिया में ''ई'' प्रत्यय जुड़ने से भाववाचक संज्ञा ''हँसी'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f50ca6ac-2ea5-4072-85ca-57b38e55b274', 'हँसी', true, '748fcfc1-09c7-4925-ad3c-57f6b4bf5d3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f952405-4cbc-4cf9-a2d9-6fe619a09dba', 'हँसोड़', false, '748fcfc1-09c7-4925-ad3c-57f6b4bf5d3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34617cb6-fb04-4c01-8ff2-e2a5ac8e9851', 'हँसमुख', false, '748fcfc1-09c7-4925-ad3c-57f6b4bf5d3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ba6083c-e4c1-4fc1-a4a3-cb679536d3c5', 'हँसनापन', false, '748fcfc1-09c7-4925-ad3c-57f6b4bf5d3c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3f7d49b-78df-42f2-a3be-39c66025f8b3', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'निम्नलिखित में से ''समूहवाचक संज्ञा'' का सही उदाहरण कौन-सा है?', 'सेना, कक्षा, गुच्छा, भीड़ - व्यक्तियों/वस्तुओं के समूह का बोध कराते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e441fcf-0bec-443b-b38d-646f2fc392ea', 'सेना, कक्षा, चाबियों का गुच्छा, भीड़', true, 'b3f7d49b-78df-42f2-a3be-39c66025f8b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20fdcafc-f751-461d-a088-6414cdb54c53', 'सोना, चाँदी', false, 'b3f7d49b-78df-42f2-a3be-39c66025f8b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dd74a66-1787-4fec-9436-a50110c76747', 'मिठास, खटास', false, 'b3f7d49b-78df-42f2-a3be-39c66025f8b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c8fc3da-7174-4bbb-a2af-9675dcce2db0', 'राम, श्याम', false, 'b3f7d49b-78df-42f2-a3be-39c66025f8b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27e49e9f-8a2c-423c-90c7-036fb3b96d28', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'भाववाचक संज्ञाओं का निर्माण मुख्य रूप से कितने प्रकार के शब्दों से किया जाता है?', 'भाववाचक संज्ञाएँ 5 स्रोतों से बनती हैं: जातिवाचक संज्ञा (मित्र→मित्रता), सर्वनाम (अपना→अपनत्व), विशेषण (मीठा→मिठास), क्रिया (लिखना→लिखाई), अव्यय (दूर→दूरी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5f5269f-00a5-4d2c-9b75-17bc996620a0', 'पाँच प्रकार के शब्दों से (1. जातिवाचक संज्ञा से, 2. सर्वनाम से, 3. विशेषण से, 4. क्रिया से, 5. अव्यय से)', true, '27e49e9f-8a2c-423c-90c7-036fb3b96d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6e53907-6eca-4643-b7d3-9dbb44f1fbdf', 'दो प्रकार के शब्दों से', false, '27e49e9f-8a2c-423c-90c7-036fb3b96d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('045fea17-2859-49f1-8ddf-673d4fffcd92', 'आठ प्रकार के शब्दों से', false, '27e49e9f-8a2c-423c-90c7-036fb3b96d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47dc31dd-2512-4937-bf44-f71e605a7087', 'केवल क्रियाओं से', false, '27e49e9f-8a2c-423c-90c7-036fb3b96d28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07c72510-bea5-4562-a782-9751c4bfbc15', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'सर्वनाम शब्दों से बनी भाववाचक संज्ञाओं का सही समूह कौन-सा है?', 'सर्वनाम ''अपना, मम, निज, सर्व'' से ''अपनत्व, ममता, निजत्व, सर्वस्व'' बनते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4207949-531c-478c-a3da-74467109de78', 'अपना -> अपनत्व / अपनापन ; मम -> ममता / ममत्व ; निज -> निजत्व ; सर्व -> सर्वस्व', true, '07c72510-bea5-4562-a782-9751c4bfbc15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c51a1688-cac5-4be6-91ff-db54a6f57600', 'लड़का -> लड़कपन', false, '07c72510-bea5-4562-a782-9751c4bfbc15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1366737-c6b0-4495-bc90-99e3288707a6', 'सफेद -> सफेदी', false, '07c72510-bea5-4562-a782-9751c4bfbc15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbeb7d84-1542-4d19-a81d-f4f3c717f1f0', 'पढ़ना -> पढ़ाई', false, '07c72510-bea5-4562-a782-9751c4bfbc15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37ad9fc5-3d23-416b-9b96-b27005fefba9', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'विशेषण शब्दों से बनी भाववाचक संज्ञाओं का सही समूह कौन-सा है?', 'विशेषण ''मीठा, चतुर, वीर, आलसी, कठोर'' से ''मिठास, चतुराई, वीरता, आलस्य, कठोरता'' बनते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f117c10-0b0d-4364-bd72-d51e15ed7dcd', 'मीठा -> मिठास ; चतुर -> चतुराई ; वीर -> वीरता ; आलसी -> आलस्य ; कठोर -> कठोरता', true, '37ad9fc5-3d23-416b-9b96-b27005fefba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58314202-769d-42b5-8ba0-44019e02b1b5', 'मनुष्य -> मनुष्यता', false, '37ad9fc5-3d23-416b-9b96-b27005fefba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('581539f2-2b65-4bf5-98a1-d2ae48c80274', 'हँसना -> हँसी', false, '37ad9fc5-3d23-416b-9b96-b27005fefba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33de19e3-3871-4126-b146-7fcf71342b99', 'अहम -> अहंकार', false, '37ad9fc5-3d23-416b-9b96-b27005fefba9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97abab70-7d6f-4166-8d21-d2205bde4743', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'क्रिया शब्दों से बनी भाववाचक संज्ञाओं का सही समूह कौन-सा है?', 'क्रिया ''सजाना, थकना, चढ़ना, बहना, दौड़ना'' से ''सजावट, थकावट, चढ़ाई, बहाव, दौड़'' बनते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e13b55c4-62b3-47b8-b449-a791074c50ec', 'सजाना -> सजावट ; थकना -> थकावट / थकान ; चढ़ना -> चढ़ाई ; बहना -> बहाव ; दौड़ना -> दौड़', true, '97abab70-7d6f-4166-8d21-d2205bde4743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b10105e4-b763-470b-a643-6b8db3edbbe1', 'पशु -> पशुता', false, '97abab70-7d6f-4166-8d21-d2205bde4743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b091d05-18dd-4b37-8217-7e6e978e270b', 'सुंदर -> सुंदरता', false, '97abab70-7d6f-4166-8d21-d2205bde4743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be0be665-1e46-4b16-86ce-2d7d907568e8', 'आप -> आपा', false, '97abab70-7d6f-4166-8d21-d2205bde4743');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7481b1ec-5669-437f-a3f9-f07f07e6f8f4', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'अव्यय शब्दों से बनी भाववाचक संज्ञाओं का सही समूह कौन-सा है?', 'अव्यय ''निकट, दूर, मना, शीघ्र'' से ''निकटता, दूरी, मनाही, शीघ्रता'' भाववाचक संज्ञाएँ बनती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0aa9d63-d2ce-4dc7-98d7-7d5c654375ee', 'निकट -> निकटता ; दूर -> दूरी ; मना -> मनाही ; शीघ्र -> शीघ्रता ; नीचे -> नीचाई', true, '7481b1ec-5669-437f-a3f9-f07f07e6f8f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49d54e2b-7c05-48fd-8ff6-78b5c6ac95ca', 'बालक -> बालपन', false, '7481b1ec-5669-437f-a3f9-f07f07e6f8f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73bc76a9-6784-4489-89c2-339638711c7f', 'गर्म -> गर्मी', false, '7481b1ec-5669-437f-a3f9-f07f07e6f8f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7297bfdd-653e-4057-9042-349947487d27', 'लिखना -> लेख', false, '7481b1ec-5669-437f-a3f9-f07f07e6f8f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1705ee2a-d096-4f9e-bff4-4c13ee486b18', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''आज के युग में भी हरिश्चंद्रों की कमी नहीं है।'' वाक्य में रेखांकित शब्द ''हरिश्चंद्रों'' किस संज्ञा के रूप में प्रयुक्त हुआ है?', 'जब कोई व्यक्तिवाचक नाम अपने विशिष्ट गुण के कारण पूरे वर्ग/जाति का प्रतीक बन जाए (और बहुवचन में प्रयुक्त हो), तो वह जातिवाचक संज्ञा बन जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5db451c-8ec4-4874-b339-9fce5be793a9', 'जातिवाचक संज्ञा के रूप में (क्योंकि यहाँ ''हरिश्चंद्र'' किसी एक व्यक्ति का नाम न होकर ''सत्यवादी एवं निष्ठावान व्यक्तियों के संपूर्ण वर्ग'' का बोध करा रहा है)', true, '1705ee2a-d096-4f9e-bff4-4c13ee486b18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6e8a6e7-a06b-43e7-9caa-c90009e8a6a8', 'व्यक्तिवाचक संज्ञा के रूप में', false, '1705ee2a-d096-4f9e-bff4-4c13ee486b18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cce4b532-a220-4e37-a7a1-4189838fbb02', 'भाववाचक संज्ञा के रूप में', false, '1705ee2a-d096-4f9e-bff4-4c13ee486b18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919bf105-7974-4ff6-838c-0aa84e389e2a', 'द्रव्यवाचक संज्ञा के रूप में', false, '1705ee2a-d096-4f9e-bff4-4c13ee486b18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e3a82c9-b446-45d4-b213-67f6b90e54e5', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''गांधीजी ने देश को सत्य और अहिंसा का पाठ पढ़ाया।'' वाक्य में ''गांधीजी'' किस संज्ञा के रूप में प्रयुक्त हुआ है?', 'जब कोई जातिसूचक शब्द किसी एक ही विशिष्ट ऐतिहासिक महापुरुष के लिए रूढ़ हो जाता है (जैसे: गांधीजी, नेताजी, शास्त्रीजी), तो वह व्यक्तिवाचक संज्ञा बन जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95a00715-cff0-4893-9766-b9c0bfb8b55a', 'व्यक्तिवाचक संज्ञा के रूप में (यद्यपि ''गांधी'' एक जाति/उपनाम है, परन्तु यहाँ यह केवल एक विशिष्ट व्यक्ति ''महात्मा मोहनदास करमचंद गांधी'' के लिए रूढ़ हुआ है)', true, '3e3a82c9-b446-45d4-b213-67f6b90e54e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56bd56cb-660e-413c-944a-48365ca75f8a', 'जातिवाचक संज्ञा के रूप में', false, '3e3a82c9-b446-45d4-b213-67f6b90e54e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0290687d-5957-4ad2-8ca5-f974b132bc59', 'भाववाचक संज्ञा के रूप में', false, '3e3a82c9-b446-45d4-b213-67f6b90e54e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77371750-5718-4679-baec-4af876e8d7c6', 'समूहवाचक संज्ञा के रूप में', false, '3e3a82c9-b446-45d4-b213-67f6b90e54e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('088a3b64-289a-4b34-ab7e-87c8a9f4fb16', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''बुढ़ापा मनुष्य के जीवन का एक अभिशाप है।'' वाक्य में ''बुढ़ापा'' कौन-सी संज्ञा है?', '''बुढ़ापा'' ''बूढ़ा'' विशेषण/जातिवाचक से बनी अवस्था-सूचक भाववाचक संज्ञा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42ce6f75-7e9a-462c-baf0-e8cbfbb2f37a', 'भाववाचक संज्ञा (अवस्था सूचक)', true, '088a3b64-289a-4b34-ab7e-87c8a9f4fb16');
