INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4897f563-f9fa-4255-a8c3-9b3d846e2d43', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''पंडित'' जातिवाचक संज्ञा से बनने वाली शुद्ध भाववाचक संज्ञा क्या होगी?', '''पंडित'' में ''य'' प्रत्यय जुड़ने से आदि-स्वर वृद्धि होकर शुद्ध भाववाचक संज्ञा ''पांडित्य'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9c42e5a-6a80-4695-9143-f490fe9cd86e', 'पांडित्य (अथवा पांडित्यभाव)', true, '4897f563-f9fa-4255-a8c3-9b3d846e2d43');
