INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc26cb18-21ef-4ce5-b1f7-fec0550d1828', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''भाववाचक संज्ञा'' नहीं है?', '''मिठाई'' मूर्त खाद्य पदार्थ (जातिवाचक) है; अमूर्त स्वाद का भाव ''मिठास'' (भाववाचक संज्ञा) है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e01aa3a8-53c5-4d2c-9227-6a795b999c7f', '''मिठाई'' (क्योंकि मिठाई एक खाद्य वस्तु है - जातिवाचक संज्ञा है ; इसकी भाववाचक संज्ञा ''मिठास'' होती है)', true, 'cc26cb18-21ef-4ce5-b1f7-fec0550d1828');
