INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e5b32e6-b48c-48a6-a246-72fc803402e3', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''सोना, चाँदी, ताँबा, पीतल, लोहा'' किस संज्ञा वर्ग के अंतर्गत आते हैं?', 'सभी धातुएँ और खनिज पदार्थ ''द्रव्यवाचक संज्ञा'' के अंतर्गत आते हैं।', NOW()) ON CONFLICT DO NOTHING;
