INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66a1e6e3-1035-4b7d-b8de-a5b5323fe591', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''सभा में सैकड़ों लोग उपस्थित थे।'' वाक्य में ''सभा'' शब्द कौन-सी संज्ञा है?', '''सभा'' जनसमूह का बोध कराती है, अतः यह समूहवाचक संज्ञा है।', NOW()) ON CONFLICT DO NOTHING;
