INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b5e8342-a1f5-41e2-9a7b-af5ebd9f0d64', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'जब कोई भाववाचक संज्ञा शब्द ''बहुवचन'' रूप में प्रयुक्त होता है (जैसे: बुराई -> बुराइयाँ, दूरी -> दूरियाँ, प्रार्थना -> प्रार्थनाएँ), तब वह किस संज्ञा में परिवर्तित हो जाता है?', 'महत्वपूर्ण व्याकरणिक नियम: भाववाचक संज्ञाएँ सदैव एकवचन होती हैं; बहुवचन रूप में वे जातिवाचक संज्ञा बन जाती हैं।', NOW()) ON CONFLICT DO NOTHING;
