INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('419f5057-89f8-4aaa-8ad2-7694038abd12', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75f2812c-dc9e-476f-b86e-3ac6d2f46ecd', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '419f5057-89f8-4aaa-8ad2-7694038abd12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('308f4dcc-091f-4d41-916f-9a519424b012', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '419f5057-89f8-4aaa-8ad2-7694038abd12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0904144a-c34d-43b7-8476-75e1f23b35af', '(A) सही है, परन्तु (R) गलत है।', false, '419f5057-89f8-4aaa-8ad2-7694038abd12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c36f070e-8bb9-41de-83f0-3fd008099601', '(A) गलत है, परन्तु (R) सही है।', false, '419f5057-89f8-4aaa-8ad2-7694038abd12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8acc35c-05fa-4267-80b0-d3d8610a9beb', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'Spot the IMPOSTER in the following group of मूल शब्द और उनसे निर्मित भाववाचक संज्ञाओं में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f8fa6d0-40c2-4b71-b8c9-1e75ec884594', 'युग्म 1', false, 'e8acc35c-05fa-4267-80b0-d3d8610a9beb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ba7935f-661f-4bdb-98ea-3d892a757a6f', 'युग्म 2', false, 'e8acc35c-05fa-4267-80b0-d3d8610a9beb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0aae1504-d2cb-4a4d-ba42-b9c3655efbc7', 'युग्म 3', false, 'e8acc35c-05fa-4267-80b0-d3d8610a9beb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fb5397d-2f12-4187-ac83-d7fe71937f5c', 'युग्म 4 (''पनियाना'' एक नामधातु क्रिया है, भाववाचक संज्ञा नहीं)', true, 'e8acc35c-05fa-4267-80b0-d3d8610a9beb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bfe37e6c-ae4c-4510-86de-f5fd524d2510', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'सुमेलित कीजिए (संज्ञा शब्द और उनके सही भेद):
(क) रामायण     -> (i) व्यक्तिवाचक संज्ञा
(ख) पर्वत      -> (ii) जातिवाचक संज्ञा
(ग) ममता       -> (iii) भाववाचक संज्ञा
(घ) तेल        -> (iv) द्रव्यवाचक संज्ञा', 'रामायण = ग्रंथ का विशिष्ट नाम (व्यक्तिवाचक); पर्वत = जातिवाचक; ममता = भाववाचक; तेल = द्रव्यवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15592057-9d3d-4b3f-9a6a-dd60e3053ee9', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, 'bfe37e6c-ae4c-4510-86de-f5fd524d2510');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e73b026-6237-4690-80cf-349a5b9c8159', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, 'bfe37e6c-ae4c-4510-86de-f5fd524d2510');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2e07da1-c063-4484-a8fa-2bf45ac0fe0e', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'bfe37e6c-ae4c-4510-86de-f5fd524d2510');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37e8f19c-4ceb-4b92-b544-ed63fc02eab5', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'bfe37e6c-ae4c-4510-86de-f5fd524d2510');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63926741-df4c-4d00-8b8c-91addd289f5a', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''नेताजी ने आजाद हिंद फौज का गठन किया था।'' वाक्य में ''नेताजी'' किस संज्ञा का उदाहरण है?', 'जातिवाचक शब्द ''नेताजी'' केवल नेताजी सुभाष चंद्र बोस के अर्थ में रूढ़ होने के कारण व्यक्तिवाचक संज्ञा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5aeb4669-0772-4b22-b9e2-488617ff17e4', 'व्यक्तिवाचक संज्ञा का (क्योंकि ''नेता'' जातिवाचक संज्ञा होते हुए भी यहाँ केवल ''सुभाष चंद्र बोस'' के लिए रूढ़ है)', true, '63926741-df4c-4d00-8b8c-91addd289f5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11625cba-6c94-4d8d-8713-0a5c8007eb94', 'जातिवाचक संज्ञा का', false, '63926741-df4c-4d00-8b8c-91addd289f5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('603f2ed8-b1fb-450a-9e21-6824ae10d0a1', 'भाववाचक संज्ञा का', false, '63926741-df4c-4d00-8b8c-91addd289f5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaf5a430-1202-4893-abce-6fdd778b59f9', 'समूहवाचक संज्ञा का', false, '63926741-df4c-4d00-8b8c-91addd289f5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a34cd96a-9d68-4499-85cd-177c6857337e', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''भाववाचक संज्ञा'' का सही प्रयोग हुआ है?', '''मिठास'' और ''दया'' अमूर्त आंतरिक अनुभूतियाँ हैं, अतः वे शुद्ध भाववाचक संज्ञाएँ हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb76d8c6-f7c6-4baa-8df4-350b59f6986b', '''उसकी वाणी में अपार मिठास और हृदय में दया है।'' (''मिठास'' और ''दया'' भाववाचक संज्ञाएँ हैं)', true, 'a34cd96a-9d68-4499-85cd-177c6857337e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75deb452-4484-4e86-b821-6d115c3762ab', '''वह रोज चार मीठे सेब खाता है।''', false, 'a34cd96a-9d68-4499-85cd-177c6857337e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('489c7369-c2a9-4940-9961-aef9b2a2e387', '''दुकानदार बहुत सारी मिठाइयाँ बेच रहा है।''', false, 'a34cd96a-9d68-4499-85cd-177c6857337e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a95db08-2cae-472e-8bcf-fdaefc9878d4', '''मिठाई की दुकान खुली है।''', false, 'a34cd96a-9d68-4499-85cd-177c6857337e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('752716de-f342-416e-85f6-8decfc5201d0', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''व्यक्तिवाचक संज्ञा'' और ''जातिवाचक संज्ञा'' में मूलभूत व्याकरणिक अंतर क्या है?', 'व्यक्तिवाचक संज्ञा अनन्य, अद्वितीय और विशिष्ट सत्ता की परिचायक है; जातिवाचक संज्ञा संपूर्ण समरूप वर्ग की सामान्य संज्ञा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dcce4a7-1198-43aa-b952-f8060da8c082', 'व्यक्तिवाचक संज्ञा एकवचनीय, अद्वितीय और विशिष्ट सत्ता का नाम होती है ; जबकि जातिवाचक संज्ञा संपूर्ण समजातीय वर्ग/श्रेणी का सामान्य नाम होती है और इसका बहुवचन बनाया जा सकता है', true, '752716de-f342-416e-85f6-8decfc5201d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0ec3312-32cb-49ad-aaf5-a9080b17ff99', 'व्यक्तिवाचक संज्ञा केवल जानवरों की होती है', false, '752716de-f342-416e-85f6-8decfc5201d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('440616b4-ddd7-42b6-84b8-2e6e91a7e578', 'जातिवाचक संज्ञा केवल मनुष्यों की होती है', false, '752716de-f342-416e-85f6-8decfc5201d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f312f3c0-7986-4153-8562-95e4871082dd', 'दोनों में कोई अंतर नहीं होता', false, '752716de-f342-416e-85f6-8decfc5201d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('096dfb7d-1657-4568-acb8-67ab4a1309c4', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''अहं'' सर्वनाम से बनने वाली भाववाचक संज्ञा क्या होगी?', '''अहं'' संस्कृत सर्वनाम में ''कार'' प्रत्यय जुड़ने से भाववाचक संज्ञा ''अहंकार'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85886688-5e58-40de-9276-e3e74fb251b8', 'अहंकार (अथवा अहंता)', true, '096dfb7d-1657-4568-acb8-67ab4a1309c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5f59b38-ae66-4d3f-adaf-112fca6f4e94', 'अहंकारी', false, '096dfb7d-1657-4568-acb8-67ab4a1309c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c60e0817-4dca-41fd-a7ca-11e207348621', 'अहंवादी', false, '096dfb7d-1657-4568-acb8-67ab4a1309c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b798bd63-ad51-4b40-bc75-bb1d7fd43e23', 'अहंभावक', false, '096dfb7d-1657-4568-acb8-67ab4a1309c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48d0dccb-70b2-4d67-ac5f-7b750214cde9', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''पुरुष'' जातिवाचक संज्ञा से बनने वाली शुद्ध भाववाचक संज्ञा क्या होगी?', '''पुरुष'' में ''अण्/य'' प्रत्यय से स्वर-वृद्धि होकर ''पौरुष'' तथा ''त्व'' प्रत्यय से ''पुरुषत्व'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('917afc54-b021-4381-989a-123fd6c96b10', 'पौरुष (अथवा पुरुषत्व)', true, '48d0dccb-70b2-4d67-ac5f-7b750214cde9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1acfb464-0538-41a7-be61-5523941c5a10', 'पुरुषार्थी', false, '48d0dccb-70b2-4d67-ac5f-7b750214cde9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d0a465a-cc02-4e54-85ed-97066164e4aa', 'पुरुषोत्तम', false, '48d0dccb-70b2-4d67-ac5f-7b750214cde9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95941a6d-3d1f-494a-ac4c-cf30f85d021f', 'महापुरुष', false, '48d0dccb-70b2-4d67-ac5f-7b750214cde9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cff6f799-8202-4ff6-820b-d185d77e56ec', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'निम्नलिखित में से कौन-सा समूह केवल और केवल ''भाववाचक संज्ञाओं'' का है?', 'धैर्य, चतुराई, ईर्ष्या, सौंदर्य, वात्सल्य, करुणा - सभी अमूर्त आंतरिक गुण/भाव हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8b2af5e-a578-45d5-852a-7e94f7783baf', 'धैर्य, चतुराई, ईर्ष्या, सौंदर्य, वात्सल्य, करुणा', true, 'cff6f799-8202-4ff6-820b-d185d77e56ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('200e315c-173b-47e3-9f88-c69e7137171f', 'नदी, नगर, पर्वत, देश', false, 'cff6f799-8202-4ff6-820b-d185d77e56ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7eaefa9-c1a3-4c62-9546-eb1ac910ff57', 'सोना, घी, तेल, दूध', false, 'cff6f799-8202-4ff6-820b-d185d77e56ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9537e815-8e80-472a-96dc-1298d6bbf87b', 'कक्षा, सेना, सभा, दल', false, 'cff6f799-8202-4ff6-820b-d185d77e56ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd1eb5ef-691f-41db-96b2-2f7d5a1d10a2', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''शास्त्र'' जातिवाचक संज्ञा से बनने वाली सही भाववाचक संज्ञा क्या होगी?', 'शास्त्र + ईय = शास्त्रीय + ता = शास्त्रीयता (भाववाचक संज्ञा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d31a21c-2a02-490a-b48d-9a1762a40323', 'शास्त्रीयता', true, 'cd1eb5ef-691f-41db-96b2-2f7d5a1d10a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84437e19-6ff1-4e78-b975-4d4479c89dae', 'शास्त्रज्ञ', false, 'cd1eb5ef-691f-41db-96b2-2f7d5a1d10a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a2d569-5d64-4c08-a677-caa50db23bf9', 'शास्त्रार्थ', false, 'cd1eb5ef-691f-41db-96b2-2f7d5a1d10a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6593984c-530d-4bcf-85f0-1d45b2b94e13', 'शास्त्रकार', false, 'cd1eb5ef-691f-41db-96b2-2f7d5a1d10a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5cade02-021a-4e16-b3b1-93e5b415f1da', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''कुशल'' विशेषण से बनने वाली शुद्ध भाववाचक संज्ञा क्या होगी?', 'कुशल + अण् = कौशल (आदि-स्वर वृद्धि उ→औ) अथवा कुशल + ता = कुशलता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06ac1f60-5800-4bfb-b43c-dbf8997a89ed', 'कौशल (अथवा कुशलता)', true, 'a5cade02-021a-4e16-b3b1-93e5b415f1da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfe10272-3f0c-45e3-a32d-661c29e67bc6', 'कुशलतापूर्वक', false, 'a5cade02-021a-4e16-b3b1-93e5b415f1da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('609daf26-2334-4f89-8c71-d9a58ed1ff5a', 'कुशलतापन', false, 'a5cade02-021a-4e16-b3b1-93e5b415f1da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6a87346-e029-46e4-a8f2-911f2056be31', 'कुशली', false, 'a5cade02-021a-4e16-b3b1-93e5b415f1da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64e12131-9dc7-4444-a724-a8a278d09a92', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'संज्ञा (Noun) के सम्यक ज्ञान का संपूर्ण हिंदी भाषा और व्याकरण में क्या मूलभूत केंद्रीय स्थान है?', 'संज्ञा समूची भाषा का संज्ञानात्मक और व्यावहारिक मेरुदंड है, जो समस्त जगत की सत्ता को नाम और संप्रेषणीयता प्रदान करती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df76e8a7-97a4-4bdf-b294-921e0d79b7e2', 'संज्ञा भाषा का मूलभूत नामकरण-आधार (Nominal Backbone) है, जिसके बिना संसार की किसी भी सत्ता का प्रत्यक्षीकरण, विचार-संप्रेषण, वाक्य-रचना और अन्य विकारी पदों (सर्वनाम, विशेषण, क्रिया, कारक) का निर्धारण असंभव है', true, '64e12131-9dc7-4444-a724-a8a278d09a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e6006e9-914d-4123-b31b-4e69f73da723', 'संज्ञा केवल शब्दकोश का एक छोटा सा अंश है', false, '64e12131-9dc7-4444-a724-a8a278d09a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('963a8049-9958-4fbc-82cd-7508b0850155', 'संज्ञा का वाक्यों में कोई विशेष महत्व नहीं होता', false, '64e12131-9dc7-4444-a724-a8a278d09a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c44ee172-3a7a-4493-a8f4-b94a0700b50a', 'संज्ञा केवल बच्चों के सीखने के लिए होती है', false, '64e12131-9dc7-4444-a724-a8a278d09a92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a26a4055-ba20-4704-91a4-5ce780fafbb6', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'What is the fluid connective tissue in humans that transports oxygen, nutrients, hormones, and metabolic wastes throughout the body?', 'Blood is the primary circulating fluid comprising plasma, erythrocytes (RBCs), leukocytes (WBCs), and thrombocytes (platelets).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d283f1d6-1bc1-4ba6-b6b4-231747c69d95', 'Blood', true, 'a26a4055-ba20-4704-91a4-5ce780fafbb6');
