INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('467a356c-d189-4417-81d1-7dce66cd3aec', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'What is the straw-colored fluid matrix part of blood in which all blood cells are suspended?', 'Plasma is the liquid extracellular matrix containing 90–92% water, dissolved proteins, glucose, minerals, and waste products.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aba64285-59e5-4483-80d5-9dafb38276e9', 'Plasma (constituting ~55% of blood volume)', true, '467a356c-d189-4417-81d1-7dce66cd3aec');
