INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dab23ffe-40e6-4f89-8bff-259fca7b9a4c', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which red iron-containing protein pigment in Red Blood Cells (RBCs) binds with Oxygen to carry it to all body cells?', 'Hemoglobin in RBCs binds O₂ to form oxyhemoglobin, imparting the characteristic red color to blood.', NOW()) ON CONFLICT DO NOTHING;
