INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21efabf7-f2a9-4f72-bb8a-ed54ef1b9e01', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which blood cells act as the body''s immune soldiers, fighting and destroying disease-causing germs and foreign microbes?', 'White Blood Cells (Leukocytes) produce antibodies and perform phagocytosis to neutralize pathogens.', NOW()) ON CONFLICT DO NOTHING;
