INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64de9cf9-3bb9-4b3f-b0ca-23a72b73e5ad', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which cellular fragments in blood form a dark red clot over cuts and wounds to prevent excessive fatal bleeding?', 'Platelets initiate the coagulation cascade, forming fibrin mesh clots to seal broken blood vessels.', NOW()) ON CONFLICT DO NOTHING;
