INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1615e79-0d07-491c-a3f5-8b24c9a27094', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which blood vessels carry oxygen-rich blood away from the heart to all parts of the body under high pressure, having thick elastic walls?', 'Arteries possess thick, muscular, elastic walls to withstand pulsatile high hydrostatic systolic blood pressure from the heart.', NOW()) ON CONFLICT DO NOTHING;
