INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('421a165a-3ede-4fa9-b822-a00f3a986d19', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which blood vessels carry carbon dioxide-rich deoxygenated blood from all organs back towards the heart, having internal VALVES to prevent backflow?', 'Veins are thin-walled, low-pressure vessels equipped with unidirectional semilunar valves ensuring forward blood flow to the heart.', NOW()) ON CONFLICT DO NOTHING;
