INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7dac6988-50fa-45d0-b027-d8d8259b021d', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'What is the rhythmic throbbing felt in the radial artery at the wrist caused by blood surging through arteries called?', 'The arterial pulse reflects ventricular systole; normal human resting pulse rate ranges between 72–80 bpm.', NOW()) ON CONFLICT DO NOTHING;
