INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7288e72-6537-4fe1-a3ea-827fb266ba5f', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'How many muscular pumping chambers are there in the human heart to prevent the mixing of oxygenated and deoxygenated blood?', 'The human heart has 4 chambers: Right/Left Atria and Right/Left Ventricles, partitioned by an interventricular septum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb5a7d4f-7691-49fa-a6ef-ac7d36f2be75', '4 Chambers (Two upper Atria and two lower Ventricles separated by a muscular Septum)', true, 'd7288e72-6537-4fe1-a3ea-827fb266ba5f');
