INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c45de48c-1440-4ee2-89a5-efc4817d7613', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'What medical acoustic instrument invented by René Laennec in 1816 is used by doctors to amplify and listen to heartbeat sounds?', 'A stethoscope uses a chest diaphragm, acoustic tube, and earpieces to auscultate cardiac valve closure sounds (Lub-Dub).', NOW()) ON CONFLICT DO NOTHING;
