INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('097354ef-82ed-4d71-8ce1-fe305271b16c', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which specialized vascular conducting tissue transports Water and dissolved mineral nutrients UPWARDS from roots to leaves in plants?', 'Xylem vessels form a continuous microscopic hydraulic pipeline conducting water and minerals from soil to leaves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b5d8282-be69-40b5-a2b2-e886c314e04d', 'Xylem (Vascular tissue)', true, '097354ef-82ed-4d71-8ce1-fe305271b16c');
