INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1a97775-cf25-4ddc-9ba1-a2afc0d77d5b', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which vascular conducting tissue transports synthesized Food (sucrose/glucose) from the green leaves to all non-photosynthetic parts of the plant?', 'Phloem sieve tubes and companion cells translocate organic food bidirectional throughout the plant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6c76562-5669-4962-adf2-87c9371c03e5', 'Phloem (Translocation)', true, 'a1a97775-cf25-4ddc-9ba1-a2afc0d77d5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6683cdba-94f3-4f7b-a0c3-e17e60518850', 'Xylem', false, 'a1a97775-cf25-4ddc-9ba1-a2afc0d77d5b');
