INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0283d626-daaf-4c4b-a4bf-98ef11324451', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'Which is the ONLY artery in the human body that carries DEOXYGENATED (CO₂-rich) blood?', 'By definition, arteries carry blood away from the heart; the pulmonary artery delivers deoxygenated venous blood to pulmonary alveoli.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5743fc9b-868b-4e9a-aa9a-947892ed218b', 'The Pulmonary Artery (carries deoxygenated blood from the right ventricle to the lungs)', true, '0283d626-daaf-4c4b-a4bf-98ef11324451');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d5b451-5216-41fc-bc8e-57d787b806d4', 'The Aorta', false, '0283d626-daaf-4c4b-a4bf-98ef11324451');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f2b7739-d78b-49d9-96f6-7b712c55e535', 'The Renal Artery', false, '0283d626-daaf-4c4b-a4bf-98ef11324451');
