INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b44ca6e-7cd1-48cb-824b-d1c9f6ceb12b', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'Which is the ONLY vein in the human body that carries OXYGENATED (O₂-rich) blood?', 'Pulmonary veins drain oxygenated blood from pulmonary capillaries directly into the left atrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d205efa-9489-4175-997b-6f401462dd23', 'The Pulmonary Vein (carries oxygenated blood from the lungs back to the left atrium of the heart)', true, '9b44ca6e-7cd1-48cb-824b-d1c9f6ceb12b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92c754db-67bc-47da-b8c3-51241b9e7712', 'The Superior Vena Cava', false, '9b44ca6e-7cd1-48cb-824b-d1c9f6ceb12b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40d99b86-0f4a-4b50-b5af-581252f81721', 'The Inferior Vena Cava', false, '9b44ca6e-7cd1-48cb-824b-d1c9f6ceb12b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a363da4-ab1b-4a4a-8b12-a026c09aebc6', 'The Jugular Vein', false, '9b44ca6e-7cd1-48cb-824b-d1c9f6ceb12b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2440c51-a4d8-4481-8ebd-3d734bc9beac', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What are the microscopic, extremely thin single-cell-walled blood vessels connecting arterioles to venules, where diffusion of gases, glucose, and wastes occurs?', 'Capillaries have single-cell endothelial walls (diameter ~7-8 µm) permitting rapid nutrient, waste, and gas exchange.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aedc527b-4753-4327-a804-a41707739256', 'Capillaries', true, 'd2440c51-a4d8-4481-8ebd-3d734bc9beac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c984142-9379-44ab-91ed-156c6db12dff', 'Arteries', false, 'd2440c51-a4d8-4481-8ebd-3d734bc9beac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6940c748-b4c8-4009-9124-ae6c816d0fe1', 'Veins', false, 'd2440c51-a4d8-4481-8ebd-3d734bc9beac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89e70269-f8e0-4037-8faa-99244606280b', 'Aorta', false, 'd2440c51-a4d8-4481-8ebd-3d734bc9beac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66922800-b251-4c13-8a06-3fc84846c164', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the biological mechanism of ''Transpiration'' in plants and what vital cooling/suction force does it generate?', 'Transpiration generates negative hydrostatic tension (transpirational pull / cohesion-tension theory) elevating sap through xylem.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1430f74b-a04a-43e5-9a2f-2162082b43e6', 'Evaporation of water vapor through stomata creates a continuous negative suction pressure (Transpirational Pull) that pulls water hundreds of feet high in tall trees while cooling the foliage', true, '66922800-b251-4c13-8a06-3fc84846c164');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39994e72-0afd-40b7-b176-d4eaa6ace93f', 'Absorption of carbon dioxide by roots', false, '66922800-b251-4c13-8a06-3fc84846c164');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('216bf853-16b9-47f6-9046-9b26dc9619d6', 'Release of oxygen into the soil', false, '66922800-b251-4c13-8a06-3fc84846c164');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06c3d0e2-c4c3-4ed3-9b2c-ab32447af064', 'Transport of sugars to roots', false, '66922800-b251-4c13-8a06-3fc84846c164');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6774a3f0-5a08-438a-a075-769f5ad78e52', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the main toxic nitrogenous excretory waste filtered and removed from human blood by the Kidneys?', 'Human excretion is ureotelic: hepatic deamination converts toxic ammonia into urea, which is cleared by renal filtration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35f983d9-603c-4f42-9767-853148d57154', 'Urea', true, '6774a3f0-5a08-438a-a075-769f5ad78e52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35f2fff5-dff5-43ba-adb5-bb2670782516', 'Uric Acid only', false, '6774a3f0-5a08-438a-a075-769f5ad78e52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6fe420f-645f-41d5-8504-08fb7a665aaf', 'Ammonia gas only', false, '6774a3f0-5a08-438a-a075-769f5ad78e52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d246c378-7f3f-4a80-894c-d235ab8e8761', 'Carbon Dioxide', false, '6774a3f0-5a08-438a-a075-769f5ad78e52');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1afc3be6-59a6-45de-9788-4194db2ad6e4', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the average normal chemical composition of human Urine excreted by a healthy adult (approx. 1.0 to 1.8 liters per day)?', 'Normal urine consists of ~95% water, 2.5% urea, and 2.5% dissolved mineral ions (sodium, potassium, creatinine, phosphates).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da17ac22-ae0e-4ec7-afd9-10ae528bcc78', '95% Water, 2.5% Urea, and 2.5% other metabolic waste salts and minerals', true, '1afc3be6-59a6-45de-9788-4194db2ad6e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15df59b7-3f8d-47e7-938b-5ef9c5f9b6d2', '50% Water and 50% Sugar', false, '1afc3be6-59a6-45de-9788-4194db2ad6e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efb49fee-3c5a-4396-b521-dd6282754a75', '100% pure Water', false, '1afc3be6-59a6-45de-9788-4194db2ad6e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a07c9ea6-db0c-4b7a-afb5-0681fb1a3079', '90% Acid and 10% Blood', false, '1afc3be6-59a6-45de-9788-4194db2ad6e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58cbdea1-c6c3-4c47-9802-a865323eb800', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the correct pathway of Urine from formation to discharge in the human excretory system?', 'Renal glomeruli filter blood → nephron tubules drain into ureters → stored in urinary bladder → voided via urethra.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7115209f-af9f-4970-bcfd-cd252be8c5a8', 'Kidneys -> Ureters (muscular tubes) -> Urinary Bladder (storage pouch) -> Urethra (muscular exit opening)', true, '58cbdea1-c6c3-4c47-9802-a865323eb800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8c2414b-e812-461b-9d90-b35610f21942', 'Kidneys -> Urethra -> Bladder -> Ureters', false, '58cbdea1-c6c3-4c47-9802-a865323eb800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d6582b-3047-4d70-b3cd-033ffc5076de', 'Bladder -> Kidneys -> Ureters -> Urethra', false, '58cbdea1-c6c3-4c47-9802-a865323eb800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('238bfe21-b00b-4a1f-bdc7-95f6ca394955', 'Ureters -> Kidneys -> Bladder -> Urethra', false, '58cbdea1-c6c3-4c47-9802-a865323eb800');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc1fcde8-9256-4f72-af68-e0cd4c047c91', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the medical procedure of ''Dialysis'' used when a patient experiences acute or chronic Renal (Kidney) Failure?', 'Hemodialysis circulates patient blood through dialyzer semi-permeable cartridges to clear metabolic toxins and normalize electrolytes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('078fe1a2-2b74-408e-aa63-274392a76fc1', 'An artificial kidney machine periodically filters toxic nitrogenous wastes, urea, and excess salts from the patient''s blood through semi-permeable membranes', true, 'dc1fcde8-9256-4f72-af68-e0cd4c047c91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910a3d09-476d-4e0a-92ea-8ad8b250d637', 'Injecting water directly into the heart', false, 'dc1fcde8-9256-4f72-af68-e0cd4c047c91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eea2581-a5d5-4cd7-bbb2-4a8847f9d3d0', 'Pumping oxygen into the stomach', false, 'dc1fcde8-9256-4f72-af68-e0cd4c047c91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21d02193-a92e-42bf-ac81-b32e40f6c9b7', 'A surgery to replace bones', false, 'dc1fcde8-9256-4f72-af68-e0cd4c047c91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa8aaf7f-6d48-43c9-b382-b37ee6a2bd34', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'Why do we develop white salty patches on our cotton clothes under the armpits on hot summer days?', 'Eccrine sweat evaporation cools the epidermis (latent heat of vaporization), leaving solute sodium chloride residues on clothing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5fc07c5-caf1-474d-9052-69bfc86a223c', 'Sweat glands secrete sweat containing water and dissolved mineral SALTS (NaCl) ; as water evaporates to cool the body, white solid salt crystals are left behind on fabric', true, 'fa8aaf7f-6d48-43c9-b382-b37ee6a2bd34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba5f4ee9-02ef-44d4-a807-0925e050e6f4', 'Dust settles from the ceiling', false, 'fa8aaf7f-6d48-43c9-b382-b37ee6a2bd34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('146925ec-0184-4892-99d6-fdbb70f33541', 'The cloth bleach dissolves', false, 'fa8aaf7f-6d48-43c9-b382-b37ee6a2bd34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f2b7b0a-04e5-42cf-83b2-17363128c11b', 'Bacteria produce salt', false, 'fa8aaf7f-6d48-43c9-b382-b37ee6a2bd34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ca2ca8a-4de0-40c1-a390-b4ae0ed13cd4', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'Why do simple aquatic organisms like Sponges (Porifera) and Hydra NOT possess any specialized circulatory system or blood?', 'Sponges and Hydra have diploblastic body plans where ambient aquatic currents directly service cellular diffusion without vascular tissue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0f53c7e-8ef7-4674-a7f5-a001a9a8f61d', 'Water circulating through their porous body cavities continuously brings food and oxygen directly to all cells and washes away carbon dioxide and waste products', true, '5ca2ca8a-4de0-40c1-a390-b4ae0ed13cd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51965f4f-9b77-4f21-ae85-7a1481057fea', 'Because they have no cells', false, '5ca2ca8a-4de0-40c1-a390-b4ae0ed13cd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('022b5dbb-b120-451c-9197-c43db6c375ad', 'Because they live in trees', false, '5ca2ca8a-4de0-40c1-a390-b4ae0ed13cd4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edf6ce96-3399-4ac3-afc4-d780b8bbb595', 'Because they produce pure gold', false, '5ca2ca8a-4de0-40c1-a390-b4ae0ed13cd4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24eb6ab7-af32-4369-986b-ab2e2fcb016c', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'How do Root Hairs in plants increase the absorption of water and dissolved minerals from the soil?', 'Unicellular root hair extensions amplify root surface area thousands-fold, driving water uptake via osmotic potential gradients.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e72c7475-c134-431f-811d-53c56e987dc4', 'They massively increase the total surface area of root epidermal contact with soil capillary water films, facilitating rapid Osmosis', true, '24eb6ab7-af32-4369-986b-ab2e2fcb016c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6e989b4-b3b5-466c-91c3-034db21050b6', 'They drill deep holes like metal drills', false, '24eb6ab7-af32-4369-986b-ab2e2fcb016c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1de1059-cff2-4729-a3de-4080776962ce', 'They produce heat to melt soil', false, '24eb6ab7-af32-4369-986b-ab2e2fcb016c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('517829ef-f8b3-497f-9bee-3c85b0399c02', 'They turn soil into sand', false, '24eb6ab7-af32-4369-986b-ab2e2fcb016c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1fb3975-9826-4be2-b32a-b0210c0dbe2d', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'In what form do Birds, Lizards, and Snakes (terrestrial reptiles) excrete nitrogenous waste to conserve precious body water?', 'Uricotelic adaptation: birds and reptiles precipitate non-toxic insoluble uric acid paste to minimize evaporative water loss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da56cf3f-d94b-4960-a550-404ed48c7ca8', 'Semi-solid white paste composed of insoluble URIC ACID', true, 'c1fb3975-9826-4be2-b32a-b0210c0dbe2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('322ad7df-2e2d-469d-8fac-6ef073faf4e3', 'Liquid ammonia in large water volume', false, 'c1fb3975-9826-4be2-b32a-b0210c0dbe2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a704fb7-b415-43eb-81c1-c7dff011af3c', 'Liquid urea', false, 'c1fb3975-9826-4be2-b32a-b0210c0dbe2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('258dd744-7e4e-40ad-8fae-6f0e5cd65886', 'Dry carbon powder', false, 'c1fb3975-9826-4be2-b32a-b0210c0dbe2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10c57221-ff08-47ec-8f4d-61fae7e29000', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'In what form do aquatic freshwater Fish excrete their nitrogenous waste directly into surrounding water?', 'Ammonotelic fish diffuse toxic ammonia directly across branchial gill membranes into the surrounding aquatic sink.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b220e3f6-ce9b-4f3e-ac5b-23e974ff722c', 'Readily soluble gaseous AMMONIA (Ammonotelic excretion)', true, '10c57221-ff08-47ec-8f4d-61fae7e29000');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d41db1a8-6d12-4446-8778-9202f713bf93', 'Insoluble uric acid crystals', false, '10c57221-ff08-47ec-8f4d-61fae7e29000');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7553303-e537-49a4-a8dc-4c02811dd684', 'Solid urea pellets', false, '10c57221-ff08-47ec-8f4d-61fae7e29000');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d157c4cf-596a-4b0d-8afd-e0b9ff7f2e96', 'Gaseous nitrogen', false, '10c57221-ff08-47ec-8f4d-61fae7e29000');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98c3cb0b-d0f8-4138-a84a-ed8e009342a0', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the primary function of the ''Septum'' dividing the left and right halves of the human heart?', 'The cardiac septum enforces complete separation of pulmonary and systemic circulations, maximizing arterial oxygen saturation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33075ff0-ad3c-4132-a2d6-a83e2e997490', 'It acts as a complete muscular dividing wall preventing oxygen-rich blood on the left side from mixing with carbon dioxide-rich blood on the right side', true, '98c3cb0b-d0f8-4138-a84a-ed8e009342a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5afb9941-3d03-4259-aa6b-25fcc37c5079', 'It filters water from blood', false, '98c3cb0b-d0f8-4138-a84a-ed8e009342a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f74859e-6367-4d6f-b8e9-4589675f9815', 'It cools the heart muscle', false, '98c3cb0b-d0f8-4138-a84a-ed8e009342a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9230b055-520a-48dd-874c-6ed36cd545e4', 'It produces new red blood cells', false, '98c3cb0b-d0f8-4138-a84a-ed8e009342a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bcdf9c8e-0ceb-47ac-9744-7e9228bf6e8c', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What makes the ''Lub-Dub'' sound heard through a stethoscope during each complete cardiac cycle?', 'First heart sound S₁ (''Lub'') = AV (tricuspid/mitral) valve closure; Second sound S₂ (''Dub'') = semilunar (aortic/pulmonic) valve closure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('602b63d2-f4bb-42d7-ab20-f1b2ff4e9fd7', 'The rhythmic, rapid closure of cardiac valves (Atrioventricular valves snapping shut for ''Lub'', and Semilunar aortic/pulmonary valves for ''Dub'')', true, 'bcdf9c8e-0ceb-47ac-9744-7e9228bf6e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('649be9a9-8ebf-44c9-bdaa-bd6a567501c9', 'Blood splashing against the ribs', false, 'bcdf9c8e-0ceb-47ac-9744-7e9228bf6e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9186e1cd-b464-4d2b-8e72-e3780cf65c19', 'Air rushing into the lungs', false, 'bcdf9c8e-0ceb-47ac-9744-7e9228bf6e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c709d421-8599-4f7d-9090-bbe1689932ae', 'The heart rubbing against the stomach', false, 'bcdf9c8e-0ceb-47ac-9744-7e9228bf6e8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('907625a1-4835-42d9-a9b2-ff5f324a014f', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What happens when a leafy balsam plant stem is kept in water colored with Red Ink (Eosin) for a few hours?', 'Classic xylem transport demonstration: capillary xylem tracheary elements conduct eosin dye upwards into leaf petiole veins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ca1fa4d-cc9d-4ffa-936d-3bb3407cf880', 'The red colored water travels UPWARDS through the Xylem vessels, staining the stem vascular bundles and leaf veins distinctly red', true, '907625a1-4835-42d9-a9b2-ff5f324a014f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c3e712d-65ee-49b3-a9a3-ba15cb3f6fff', 'The leaves turn completely black', false, '907625a1-4835-42d9-a9b2-ff5f324a014f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f45b93d0-4b95-461e-91e9-db07ca2f212d', 'The plant catches fire', false, '907625a1-4835-42d9-a9b2-ff5f324a014f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be2ddbfa-c16d-4fc6-937a-c86a64aef0cd', 'The roots dissolve', false, '907625a1-4835-42d9-a9b2-ff5f324a014f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fcf4d726-8001-4cd3-8334-5875acdd0ca1', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b45a437-99d7-4457-9ec0-4e3735b134a6', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'fcf4d726-8001-4cd3-8334-5875acdd0ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d18ec931-917f-44a0-a2d4-f71cf6b3f149', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'fcf4d726-8001-4cd3-8334-5875acdd0ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84e9f9c6-998b-4603-9a8d-7ee6620838ad', '(A) is true, but (R) is false.', false, 'fcf4d726-8001-4cd3-8334-5875acdd0ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50fd74ec-ed5f-4553-84d7-5be790dbd5c4', '(A) is false, but (R) is true.', false, 'fcf4d726-8001-4cd3-8334-5875acdd0ca1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40c87b25-755e-49f4-acd9-f15c95f954db', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Spot the IMPOSTER in the following group of Nitrogenous Excretory Products and their animal classifications:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2b0d863-21e3-44bc-b7df-ec7c239fb990', 'Classification 1', false, '40c87b25-755e-49f4-acd9-f15c95f954db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd4365a5-48b8-4beb-a316-540194439747', 'Classification 2', false, '40c87b25-755e-49f4-acd9-f15c95f954db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ea2509-167b-428d-9d26-3348b7ff435d', 'Classification 3', false, '40c87b25-755e-49f4-acd9-f15c95f954db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('860c781b-75c4-4de6-ac44-fefb7a80ca2f', 'Classification 4 (Frogs and Earthworms excrete Urea and Ammonia, NEVER gold)', true, '40c87b25-755e-49f4-acd9-f15c95f954db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc11220e-9480-4cb8-8b85-72579b5eaf5f', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Trace the EXACT pathway of deoxygenated blood entering the human heart from body tissues until it leaves as oxygenated blood for systemic distribution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94f60c0b-b7c9-4971-a996-f73f33573df0', 'The LEFT VENTRICLE (which pumps oxygenated blood under immense pressure into the systemic Aorta)', true, 'bc11220e-9480-4cb8-8b85-72579b5eaf5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15487146-2c5e-4757-a113-0b41a1124ff1', 'The Right Atrium', false, 'bc11220e-9480-4cb8-8b85-72579b5eaf5f');
