INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2a86a18-4f77-4df2-a129-538f54f833f2', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Match Column I (Vascular / Circulatory Components) with Column II (Physiological Functions):
(a) Xylem Tracheids & Vessels -> (i) Unidirectional upward conduction of water & minerals via transpirational tension
(b) Phloem Sieve Tubes         -> (ii) Bidirectional translocation of synthesized sucrose/photosynthates
(c) Blood Platelets            -> (iii) Hemostasis and thromboplastin cascade for clot formation
(d) Renal Nephrons             -> (iv) Ultrafiltration and selective reabsorption to produce urine', 'Xylem = water tension; Phloem = food translocation; Platelets = coagulation; Nephrons = renal filtration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1b1f80e-8c1d-4435-8c89-71d3e1bf10b7', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'b2a86a18-4f77-4df2-a129-538f54f833f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f173c341-62fa-46dc-bc0b-dd5d60097d47', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'b2a86a18-4f77-4df2-a129-538f54f833f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7718bb38-8a83-4337-b56e-a503c51ce062', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b2a86a18-4f77-4df2-a129-538f54f833f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ff2ef91-cf66-4389-9492-20cc491fdefe', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b2a86a18-4f77-4df2-a129-538f54f833f2');
