INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d13af4ae-401f-47cf-978a-3cb42835bfd1', 'Statements 1 and 2 only', true, '91026041-2597-4c7b-aac4-d324c34b4078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08e7e7ac-d002-4921-9de0-4a2850a98920', 'Statements 2 and 3 only', false, '91026041-2597-4c7b-aac4-d324c34b4078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('898252a3-4959-4bcc-be9f-472f26f35a78', 'Statements 1 and 3 only', false, '91026041-2597-4c7b-aac4-d324c34b4078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f869c562-467e-4b84-a52d-0427aae0891e', 'All Statements 1, 2, and 3', false, '91026041-2597-4c7b-aac4-d324c34b4078');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f15d0eb-5e73-4da4-8620-f7ef299facf0', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'What physical-chemical properties of water molecules explain how tall redwood trees sustain unbroken water columns in xylem without snapping under massive tension?', 'Dixon-Joly Cohesion-Tension theory: hydrogen bonding provides immense tensile strength (>100 atm) resisting cavitation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2a10464-97e5-43a7-8ed7-93dc6869e85a', 'Cohesion (mutual attraction between water molecules) and Adhesion (attraction between water molecules and hydrophilic xylem cellulose walls)', true, '5f15d0eb-5e73-4da4-8620-f7ef299facf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5574aa4-2389-442c-bbf5-8805bcd26da9', 'Water molecules turning into ice inside the stem', false, '5f15d0eb-5e73-4da4-8620-f7ef299facf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5423d75b-866b-43c2-b0e3-3990f4043cfd', 'Magnetic attraction between roots and clouds', false, '5f15d0eb-5e73-4da4-8620-f7ef299facf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c5d8a85-dc6d-421d-ba7a-9ffc1a28ecdf', 'Air bubbles pushing the water', false, '5f15d0eb-5e73-4da4-8620-f7ef299facf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1c1c33e-cf7e-4b4b-bd3d-538443c3ef1b', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Why is William Harvey (1578–1657) celebrated as a founding father of modern physiology for his discovery of blood circulation?', 'Harvey''s ''De Motu Cordis'' (1628) established closed unidirectional hemodynamics driven by mechanical ventricular pumping.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcabe2bc-32a5-4f80-bf10-b67f5c01cc5f', 'He disproved Galen''s 1,400-year doctrine by experimentally demonstrating that the heart acts as a muscular pump circulating a fixed volume of blood unidirectionally through closed circuits of arteries and veins', true, 'a1c1c33e-cf7e-4b4b-bd3d-538443c3ef1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9516bc93-dacd-420b-b409-4add2d0fe32a', 'He invented blood transfusions in 1500', false, 'a1c1c33e-cf7e-4b4b-bd3d-538443c3ef1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36d760c9-0faf-46c6-94b7-9b62074f3ba1', 'He discovered that blood has no cells', false, 'a1c1c33e-cf7e-4b4b-bd3d-538443c3ef1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a82f2d6-7343-4cf3-9544-5d9f588579e6', 'He proved that the liver pumps blood to the lungs', false, 'a1c1c33e-cf7e-4b4b-bd3d-538443c3ef1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a4dc8ad-956b-48e5-8eb7-b30fb59d3b22', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Consider four physiological events:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98b07b58-485b-4ac4-87b1-43cd82c3ca69', 'All 1, 2, 3, and 4', true, '9a4dc8ad-956b-48e5-8eb7-b30fb59d3b22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74a2a773-4cd5-4b37-9b95-725234c84cfd', '1 and 2 only', false, '9a4dc8ad-956b-48e5-8eb7-b30fb59d3b22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffbc78bf-6939-4d7d-8a45-3d136f09500a', '3 and 4 only', false, '9a4dc8ad-956b-48e5-8eb7-b30fb59d3b22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('211e22ef-97cb-4344-99f4-5e93fea4730c', '1 and 3 only', false, '9a4dc8ad-956b-48e5-8eb7-b30fb59d3b22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09ef1190-8f89-4e94-a823-9584b2360717', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'What happens during ''Kidney Dialysis'' when blood is drawn from a patient''s radial artery?', 'Dialysis relies on concentration gradients across semi-permeable cellophane: metabolic wastes diffuse into dialysate while cellular components return safely.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1943c359-a220-4352-8eb9-3a881a8a14e2', 'Blood is mixed with an anticoagulant (heparin), passed through dialyzing cellophane tubes bathed in isotonic dialyzing fluid lacking nitrogenous wastes, where urea diffuses out, and purified blood is returned via a vein', true, '09ef1190-8f89-4e94-a823-9584b2360717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15749d16-ca8d-4f22-8628-b0080ae564eb', 'Blood is boiled to kill germs', false, '09ef1190-8f89-4e94-a823-9584b2360717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c903d37e-832d-448c-80ae-36fe9d64a3cd', 'Blood is replaced entirely with water', false, '09ef1190-8f89-4e94-a823-9584b2360717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b35f79f-f08d-47c9-b326-4c2a720bf0d1', 'All white blood cells are removed permanently', false, '09ef1190-8f89-4e94-a823-9584b2360717');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d10ecdb-447a-4511-8985-2a78a3856dfe', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Why does the left side of the heart handle ONLY oxygenated blood while the right side handles ONLY deoxygenated blood in mammals and birds?', 'Endothermic homeothermy demands high ATP turnover, requiring complete separation of systemic and pulmonary hemodynamics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('898ddd39-b1c1-4b3c-9416-c109f0bc37e9', 'High metabolic rates of warm-blooded endotherms require maximum oxygen supply to generate cellular body heat and sustain constant body temperature', true, '1d10ecdb-447a-4511-8985-2a78a3856dfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4efe0113-fd64-4be9-99d9-99fd0661b7cb', 'Because mammals have no veins', false, '1d10ecdb-447a-4511-8985-2a78a3856dfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d00fbc1-37e7-421d-8511-8ed052f023a7', 'Because birds have no lungs', false, '1d10ecdb-447a-4511-8985-2a78a3856dfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae8cac0a-2be8-4f73-aa5d-e3ca3a248093', 'To keep the lungs cold', false, '1d10ecdb-447a-4511-8985-2a78a3856dfe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0145980-7ac6-4d47-8622-cd84fa20546e', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'What would happen to a plant if all its Phloem tissue were carefully removed in a continuous ring around the stem (Girdling / Ringing experiment)?', 'Malpighi''s girdling experiment proves phloem translocates carbohydrates: removing the phloem ring starves root parenchyma, collapsing active ion uptake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e032e86f-d718-472e-95f6-f15fc09132d0', 'Photosynthesized sugars cannot reach the subterranean roots; the roots starve and die first, followed by the death of the entire plant', true, 'a0145980-7ac6-4d47-8622-cd84fa20546e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('885102ca-a05a-4a6d-8778-2e4ad0bf6a37', 'The plant grows twice as fast', false, 'a0145980-7ac6-4d47-8622-cd84fa20546e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e4541a0-095b-4e6b-bad8-70584d12788c', 'Water immediately stops reaching the leaves', false, 'a0145980-7ac6-4d47-8622-cd84fa20546e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b28cf818-d6e4-4d35-9830-7fc36a503984', 'The leaves turn into flowers', false, 'a0145980-7ac6-4d47-8622-cd84fa20546e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff06e0e5-acd1-429a-9bde-004b2f9f236c', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'What overarching biological principle is established in Chapter 7 of NCERT Class 7 Science?', 'Chapter 7 synthesizes organismal transport and excretion: convective hemodynamics, renal ultrafiltration, and botanical vascular sap translocation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f57b993e-c30e-44f6-bf8a-59404b5f5252', 'Complex multicellular organisms require specialized vascular internal transport networks (blood circulation and plant vascular bundles) and waste excretion systems to maintain cellular homeostasis, nutrient delivery, and metabolic balance across trillions of cells', true, 'ff06e0e5-acd1-429a-9bde-004b2f9f236c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bbe6dca-af39-432c-a115-0884352bc534', 'That small animals do not need any food', false, 'ff06e0e5-acd1-429a-9bde-004b2f9f236c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7756e3e-38a0-4bd2-bb31-57f21179ee31', 'That plants have hearts like mammals', false, 'ff06e0e5-acd1-429a-9bde-004b2f9f236c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80cc072f-cfdc-4849-868f-5460baf6dddc', 'That blood only moves when humans run', false, 'ff06e0e5-acd1-429a-9bde-004b2f9f236c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('348144fc-ca81-49d7-9c7e-4f505f08a434', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Find the Ratio of 5 m to 10 km in its simplest form:', 'Units must match: 10 km = 10,000 m. Ratio = 5 m : 10,000 m = 1 : 2000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df17b167-9e1f-49a3-828b-0dcd52d5c375', '1 : 2000 (10 km = 10,000 m ; 5 / 10,000 = 1 / 2000)', true, '348144fc-ca81-49d7-9c7e-4f505f08a434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fb536bd-e6af-40fc-ab76-22dc537c1aea', '1 : 2', false, '348144fc-ca81-49d7-9c7e-4f505f08a434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c8a4961-c6c7-4b00-9d3e-e0fe7200b910', '1 : 200', false, '348144fc-ca81-49d7-9c7e-4f505f08a434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b110f75-f4f7-4da4-b616-55343a249cf9', '1 : 20', false, '348144fc-ca81-49d7-9c7e-4f505f08a434');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89c7f207-8541-4cdb-9bb1-773b8390a42e', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Find the Ratio of 50 paise to Rs 5 in its simplest form:', 'Rs 5 = 500 paise. Ratio = 50 : 500 = 1 : 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('447c20fc-8555-4e8a-8bf9-4ba3673b438c', '1 : 10 (Rs 5 = 500 paise ; 50 / 500 = 1 / 10)', true, '89c7f207-8541-4cdb-9bb1-773b8390a42e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68080237-4fcc-4b29-a883-3cd1c42b3ea3', '1 : 100', false, '89c7f207-8541-4cdb-9bb1-773b8390a42e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2210d24a-d125-4516-a46d-dd2303cc33a1', '1 : 5', false, '89c7f207-8541-4cdb-9bb1-773b8390a42e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71155bf5-c3ad-401f-8287-a03b3c37b1e3', '10 : 1', false, '89c7f207-8541-4cdb-9bb1-773b8390a42e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f477330-3746-4ef1-8c5d-953b620c14a4', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Convert the fraction 3/4 into a Percentage:', 'Fraction to percentage: (3/4) × 100% = 75%.', NOW()) ON CONFLICT DO NOTHING;
