INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('498cd761-4766-4dd2-bb84-16a55765fda0', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Convert 65% into a Fraction in its simplest reduced form:', '65% = 65/100 = 13/20.', NOW()) ON CONFLICT DO NOTHING;
