INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('361a4dea-02bd-480d-9c74-d127bbe3986c', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Find 15% of 250:', '15% of 250 = 0.15 × 250 = 37.5.', NOW()) ON CONFLICT DO NOTHING;
