INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8859e94b-4871-42ad-8f93-18cd6e82aff7', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Convert the decimal 0.65 into a Percentage:', '0.65 × 100% = 65%.', NOW()) ON CONFLICT DO NOTHING;
