INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e53764ec-1628-477b-a834-0152136c567f', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'If Selling Price (SP) is GREATER than Cost Price (CP), the transaction results in a:', 'When SP > CP, there is a profit: Profit = SP - CP.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('976eb84b-2ce6-49c6-8437-6a108ee5bcd2', 'Profit (Profit = SP - CP)', true, 'e53764ec-1628-477b-a834-0152136c567f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65e60fae-db08-4005-ac0d-0d2462917ddc', 'Loss (Loss = CP - SP)', false, 'e53764ec-1628-477b-a834-0152136c567f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11213fcb-094e-40e0-b42b-86022c998bc0', 'No Profit No Loss', false, 'e53764ec-1628-477b-a834-0152136c567f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('469028a3-74ca-4783-a66a-9ce7a9581e39', 'Discount', false, 'e53764ec-1628-477b-a834-0152136c567f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5d94e4b-1ed1-447d-9bfa-429ce254beb9', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'If Cost Price (CP) is GREATER than Selling Price (SP), the transaction results in a:', 'When CP > SP, the seller incurs a loss: Loss = CP - SP.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5abbf401-57f3-40b6-8833-2196737d0775', 'Loss (Loss = CP - SP)', true, 'a5d94e4b-1ed1-447d-9bfa-429ce254beb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3d6ff0c-c85f-4baa-8747-9d8e6031e456', 'Profit', false, 'a5d94e4b-1ed1-447d-9bfa-429ce254beb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20afc785-26a8-4e80-a3b1-bc819b236b75', 'Interest', false, 'a5d94e4b-1ed1-447d-9bfa-429ce254beb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da71f577-e23f-4d25-8a6a-298690a3a5ae', 'Amount', false, 'a5d94e4b-1ed1-447d-9bfa-429ce254beb9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8e39975-a0ea-48ef-9e5e-e2cc08d8ce4a', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'What is the standard formula for calculating SIMPLE INTEREST (SI)?', 'Simple Interest formula: SI = (Principal × Rate × Time) / 100.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35835983-eb20-4e87-b769-f76ef1455cdb', 'SI = (P × R × T) / 100 (where P = Principal, R = Rate % per annum, T = Time in years)', true, 'c8e39975-a0ea-48ef-9e5e-e2cc08d8ce4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71e11200-13a6-4f4a-a747-c69c15142825', 'SI = P + R + T', false, 'c8e39975-a0ea-48ef-9e5e-e2cc08d8ce4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0176f1e-8387-4f7e-ab1f-9decde80d061', 'SI = (P × R) / T', false, 'c8e39975-a0ea-48ef-9e5e-e2cc08d8ce4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aa8e2e1-6698-47cf-aadb-db3b2d822693', 'SI = P × (1 + R/100)', false, 'c8e39975-a0ea-48ef-9e5e-e2cc08d8ce4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f140876-ebbe-4e26-899b-33c5c5fb8646', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'What is the total Amount (A) paid at the end of the loan tenure?', 'Total Amount A = Principal + Simple Interest (A = P + SI).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6bddd0a-0a27-421f-9181-96474c54b2ab', 'Amount = Principal + Simple Interest (A = P + SI)', true, '9f140876-ebbe-4e26-899b-33c5c5fb8646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90024756-ad0d-414b-9d91-e6436701318a', 'Amount = Principal - Simple Interest', false, '9f140876-ebbe-4e26-899b-33c5c5fb8646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1987216-5116-4eda-83d1-cccd93d4f258', 'Amount = Principal × Rate', false, '9f140876-ebbe-4e26-899b-33c5c5fb8646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b6a270b-1ecd-4c2f-9b51-7140ca797cf0', 'Amount = SI / Time', false, '9f140876-ebbe-4e26-899b-33c5c5fb8646');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a66d451a-9153-4d63-944c-43f7256e3729', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'An item bought for Rs 200 is sold for Rs 250. Find the Profit Percentage:', 'Profit = 250 - 200 = 50. Profit % = (50/200) × 100 = 25%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16679329-6e2c-4f99-b281-fffe20837447', '25% (Profit = 250 - 200 = Rs 50 ; Profit % = (50 / 200) × 100% = 25%)', true, 'a66d451a-9153-4d63-944c-43f7256e3729');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b42d685c-d553-4b0f-95ef-7e9ec3837423', '20%', false, 'a66d451a-9153-4d63-944c-43f7256e3729');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29da8a03-8e26-44a5-9ba8-351b0d59daa8', '50%', false, 'a66d451a-9153-4d63-944c-43f7256e3729');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bf547c8-d013-4e78-bf45-56dff9a047fa', '30%', false, 'a66d451a-9153-4d63-944c-43f7256e3729');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17c5aa62-aa1f-49f8-8a78-f7fb68ede616', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Find the Simple Interest on Rs 1,000 for 2 years at 5% per annum:', 'SI = (1000 × 5 × 2)/100 = Rs 100.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95e764f6-c9db-44dd-86e4-0c99d883de32', 'Rs 100 (SI = (1000 × 5 × 2) / 100 = Rs 100)', true, '17c5aa62-aa1f-49f8-8a78-f7fb68ede616');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c08bdb45-b256-434a-849a-f0215ef5dd8e', 'Rs 50', false, '17c5aa62-aa1f-49f8-8a78-f7fb68ede616');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94189f55-8984-40ab-b857-3c38535b2880', 'Rs 200', false, '17c5aa62-aa1f-49f8-8a78-f7fb68ede616');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c612c92-6513-40a5-b5da-ca1c297c2b1f', 'Rs 150', false, '17c5aa62-aa1f-49f8-8a78-f7fb68ede616');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0331e3f9-b0fd-432a-9567-0eb4f4a30957', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'Out of 25 students in a class, 72% are good in mathematics. How many students are NOT good in mathematics?', '28% of 25 = 0.28 × 25 = 7 students.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d02342ea-f3cf-4b90-94c2-95724b4d6726', '7 students (Not good % = 100% - 72% = 28% ; Number = (28 / 100) × 25 = 7 students)', true, '0331e3f9-b0fd-432a-9567-0eb4f4a30957');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf52fb37-cb38-4232-b2bc-14729e816400', '18 students', false, '0331e3f9-b0fd-432a-9567-0eb4f4a30957');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04818892-f16a-4630-9e7b-096e82a91411', '5 students', false, '0331e3f9-b0fd-432a-9567-0eb4f4a30957');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3836cf04-4f0d-4698-8061-da48af986f7e', '8 students', false, '0331e3f9-b0fd-432a-9567-0eb4f4a30957');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ff3c61e-94aa-45ed-92d4-18bbf0f2b795', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'A football team won 10 matches out of the total number of matches they played. If their win percentage was 40%, how many total matches did they play in all?', '0.40 × x = 10 → x = 10 / 0.40 = 25 matches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919313ac-1bd6-43cb-9db6-f8e623957e9e', '25 matches (40% of Total = 10 ⇒ (40/100) × x = 10 ⇒ x = 10 × (100/40) = 25 matches)', true, '1ff3c61e-94aa-45ed-92d4-18bbf0f2b795');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de5835c6-eb7d-41f0-a923-76277680491f', '20 matches', false, '1ff3c61e-94aa-45ed-92d4-18bbf0f2b795');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fdf190b-4cb3-4aa0-b846-fc2eda442034', '30 matches', false, '1ff3c61e-94aa-45ed-92d4-18bbf0f2b795');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e77a1070-4984-4d48-8997-b59af0478366', '40 matches', false, '1ff3c61e-94aa-45ed-92d4-18bbf0f2b795');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38146659-3297-4299-a6cd-2b4cd5900521', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'If Chameli had Rs 600 left after spending 75% of her money, how much did she have in the beginning?', '25% of x = 600 → x = 600 × 4 = Rs 2,400.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64fecb33-c1fe-4ae0-8c48-7e4162ae5746', 'Rs 2,400 (Remaining % = 100% - 75% = 25% ; 25% of Total = 600 ⇒ (1/4) × x = 600 ⇒ x = Rs 2,400)', true, '38146659-3297-4299-a6cd-2b4cd5900521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f5b5902-cf0b-4aa8-beae-47e84b3f32a9', 'Rs 1,800', false, '38146659-3297-4299-a6cd-2b4cd5900521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('407626e4-3c74-43e7-abdd-08f696ec4fc3', 'Rs 3,000', false, '38146659-3297-4299-a6cd-2b4cd5900521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27530398-4a9a-4df4-9db5-4c2a0e8438f1', 'Rs 2,000', false, '38146659-3297-4299-a6cd-2b4cd5900521');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5684da3b-13e7-45b3-88e8-c8898dfdc438', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'The population of a city decreased from 25,000 to 24,500. Find the Percentage Decrease:', '% Decrease = (500 / 25000) × 100 = 2%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc20ef77-b986-4365-9bf4-da07c1417e8e', '2% (Decrease = 25,000 - 24,500 = 500 ; % Decrease = (500 / 25,000) × 100% = 2%)', true, '5684da3b-13e7-45b3-88e8-c8898dfdc438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98ae9c58-fa05-416a-ac92-a01a8249ec1e', '5%', false, '5684da3b-13e7-45b3-88e8-c8898dfdc438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356c5f2a-4623-4c4b-a3d1-63c8b3ee661a', '2.5%', false, '5684da3b-13e7-45b3-88e8-c8898dfdc438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34c4127c-8c05-4680-803a-9a53f2f142f6', '4%', false, '5684da3b-13e7-45b3-88e8-c8898dfdc438');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('488d49a0-eceb-4384-b28d-248583d82dd6', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'I bought a TV for Rs 10,000 and sold it at a Profit of 20%. How much money do I get for it (Selling Price)?', 'SP = CP × (1 + 20/100) = 10,000 × 1.20 = Rs 12,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9818a8ed-19ee-45b2-ab44-75c2899c11de', 'Rs 12,000 (Profit = 20% of 10,000 = Rs 2,000 ; SP = 10,000 + 2,000 = Rs 12,000)', true, '488d49a0-eceb-4384-b28d-248583d82dd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bdc22a0-e836-42c5-9202-65eeb70f3a5d', 'Rs 11,000', false, '488d49a0-eceb-4384-b28d-248583d82dd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05df5379-c6b2-4ec8-af19-b5fd9891b346', 'Rs 12,500', false, '488d49a0-eceb-4384-b28d-248583d82dd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b89669b-b3e8-44b9-9ea7-dfd5f0915c54', 'Rs 8,000', false, '488d49a0-eceb-4384-b28d-248583d82dd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('637f5c5f-ef1c-4cf6-a69b-3c386275ad0f', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'Juhi sells a washing machine for Rs 13,500. She loses 20% in the bargain. What was the price at which she bought it (Cost Price)?', 'CP = SP / (1 - 0.20) = 13,500 / 0.80 = Rs 16,875.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('793414e6-2a50-4d25-9e0a-f84b84882b8f', 'Rs 16,875 (SP = CP × (1 - Loss%) ⇒ 13,500 = CP × 0.80 ⇒ CP = 13,500 / 0.80 = Rs 16,875)', true, '637f5c5f-ef1c-4cf6-a69b-3c386275ad0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2ff1536-11e5-4d63-a788-5bfb280c9d47', 'Rs 16,200', false, '637f5c5f-ef1c-4cf6-a69b-3c386275ad0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9042d764-6503-4158-ba8c-4892dd17f33d', 'Rs 15,000', false, '637f5c5f-ef1c-4cf6-a69b-3c386275ad0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9f766fb-302a-402a-88c1-03aaec330847', 'Rs 17,500', false, '637f5c5f-ef1c-4cf6-a69b-3c386275ad0f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a3ab929-580b-4d5c-886e-a9989b1800d6', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'Find the Amount to be paid at the end of 3 years on Principal = Rs 1,200 at 12% per annum:', 'SI = (1200 × 12 × 3)/100 = 432. Amount = 1200 + 432 = Rs 1,632.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54f8154b-21f9-464b-8287-7fe9d8e445a5', 'Rs 1,632 (SI = (1200 × 12 × 3) / 100 = Rs 432 ; Amount = 1200 + 432 = Rs 1,632)', true, '2a3ab929-580b-4d5c-886e-a9989b1800d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45c43075-4a66-434b-9209-b8a8e67d3292', 'Rs 1,532', false, '2a3ab929-580b-4d5c-886e-a9989b1800d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d030c9f5-b9b9-425e-8949-fd8497089de5', 'Rs 1,732', false, '2a3ab929-580b-4d5c-886e-a9989b1800d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06bfb761-d639-4936-a2d9-74b3673711eb', 'Rs 1,432', false, '2a3ab929-580b-4d5c-886e-a9989b1800d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58f622bb-7c41-4690-93d0-7e3f2b8b3799', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'What Rate gives Rs 280 as interest on a sum of Rs 56,000 in 2 years?', 'R = (280 × 100) / (56000 × 2) = 28000 / 112000 = 0.25%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e568e5f3-32fa-458b-a835-85c125458aa6', '0.25% p.a. (R = (SI × 100) / (P × T) = (280 × 100) / (56,000 × 2) = 28,000 / 112,000 = 0.25% or 1/4%)', true, '58f622bb-7c41-4690-93d0-7e3f2b8b3799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7275a7a-f711-4c77-ba22-644d6d6a0072', '2.5%', false, '58f622bb-7c41-4690-93d0-7e3f2b8b3799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f525fc2a-bc93-4f6c-ac1a-c2fc09a80854', '0.5%', false, '58f622bb-7c41-4690-93d0-7e3f2b8b3799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03763ae4-d5b4-4b96-a742-40a20c6602f5', '1%', false, '58f622bb-7c41-4690-93d0-7e3f2b8b3799');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d09161ec-3774-4b36-bc0a-1574346b0eb9', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'If Meena gives an interest of Rs 45 for one year at 9% rate p.a., what is the sum (Principal) she has borrowed?', 'P = (45 × 100)/(9 × 1) = 4500 / 9 = Rs 500.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('453bc5dd-cfea-4474-81ea-419a99a6fa46', 'Rs 500 (P = (SI × 100) / (R × T) = (45 × 100) / (9 × 1) = 4500 / 9 = Rs 500)', true, 'd09161ec-3774-4b36-bc0a-1574346b0eb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e288bee6-bc42-4ad5-b8e6-f1b0434680b6', 'Rs 450', false, 'd09161ec-3774-4b36-bc0a-1574346b0eb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9196bfda-361e-4eeb-bfb1-6bf9c48444e3', 'Rs 550', false, 'd09161ec-3774-4b36-bc0a-1574346b0eb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8b0f2b7-e1bd-4fdc-95a1-d74c13ddce56', 'Rs 600', false, 'd09161ec-3774-4b36-bc0a-1574346b0eb9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e40116de-ae63-4972-91e0-7d03371aafcd', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'The angles of a triangle are in the ratio 2 : 3 : 4. Find the measure of each angle in degrees and in percentages of the total sum (180°):', 'Parts: 2+3+4=9. Angles: 2/9(180)=40°, 3/9(180)=60°, 4/9(180)=80°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1824a131-d486-4bde-9121-00c2b5179495', '40° (22.2%), 60° (33.3%), and 80° (44.4%) (Sum of parts = 9 ; (2/9)×180 = 40°, (3/9)×180 = 60°, (4/9)×180 = 80°)', true, 'e40116de-ae63-4972-91e0-7d03371aafcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe443c9f-b67c-4be9-8a60-d3ffa96c1f72', '30°, 60°, 90°', false, 'e40116de-ae63-4972-91e0-7d03371aafcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f45eaea3-3c87-4bc5-a84f-16c91f85c9fc', '20°, 40°, 120°', false, 'e40116de-ae63-4972-91e0-7d03371aafcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8484e20c-7df4-45ba-b8a1-b1f7ea513f7b', '50°, 60°, 70°', false, 'e40116de-ae63-4972-91e0-7d03371aafcd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('587fe1a2-6515-43f7-8ea5-3568ba0e0c2d', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'A skirt is bought for Rs 250 and sold for Rs 150. Find the Loss Percentage:', 'Loss % = (100/250) × 100 = 40%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce64c274-4506-4258-bdf5-1df8d9960543', '40% (Loss = 250 - 150 = Rs 100 ; Loss % = (100 / 250) × 100% = 40%)', true, '587fe1a2-6515-43f7-8ea5-3568ba0e0c2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c20d20d9-265c-45c8-92e3-3e7f53a07a75', '30%', false, '587fe1a2-6515-43f7-8ea5-3568ba0e0c2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73265bd9-3047-4f88-ac44-e699f38da860', '25%', false, '587fe1a2-6515-43f7-8ea5-3568ba0e0c2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df5ce85f-0859-43e4-9a95-74bf393b4e21', '50%', false, '587fe1a2-6515-43f7-8ea5-3568ba0e0c2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e682222-958e-46c6-8cd5-5577db3732e5', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'An alloy contains 30% copper, 40% zinc, and the remaining is nickel. Find the percentage of nickel in the alloy:', '100% - (30% + 40%) = 30%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba733dae-50e6-4483-bc5c-baf1aaa226b3', '30% (Nickel % = 100% - (30% + 40%) = 100% - 70% = 30%)', true, '3e682222-958e-46c6-8cd5-5577db3732e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('688e2446-ff64-4bde-9dcd-d28b9ca4cef6', '20%', false, '3e682222-958e-46c6-8cd5-5577db3732e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ee35aec-1b00-45a0-986d-6f6fd998b610', '40%', false, '3e682222-958e-46c6-8cd5-5577db3732e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('863e7c29-2e81-4c2d-8d2c-36d28f737821', '25%', false, '3e682222-958e-46c6-8cd5-5577db3732e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3035acec-debe-41d2-b804-870a9f776800', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'A gardener bought a plant for Rs 120 and sold it for Rs 150. Find the profit percentage:', 'Profit % = (30/120) × 100 = 25%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c120da13-a37f-483e-a8ee-ea3456ba44d5', '25% (Profit = 150 - 120 = 30 ; Profit % = (30 / 120) × 100% = 25%)', true, '3035acec-debe-41d2-b804-870a9f776800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdaf4269-7fad-48a6-9de6-4763bfe8955b', '20%', false, '3035acec-debe-41d2-b804-870a9f776800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fafe802a-c9e4-4636-af37-7a9b0ef5746d', '30%', false, '3035acec-debe-41d2-b804-870a9f776800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d4e7a06-21bb-44bb-b63c-20abad72a7ee', '15%', false, '3035acec-debe-41d2-b804-870a9f776800');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8e390a4-ef54-4b47-8d6d-6fb6f8670bc9', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'A shopkeeper sells 1 dozen eggs for Rs 48, making a profit of 20%. What was the cost price of 1 dozen eggs?', 'CP = 48 / 1.20 = Rs 40.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5a29500-c805-4e90-bd69-e0dd69809450', 'Rs 40 (CP = SP / 1.20 = 48 / 1.20 = Rs 40)', true, 'a8e390a4-ef54-4b47-8d6d-6fb6f8670bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bf5edbf-a057-480c-8840-5e6ecdfcde6c', 'Rs 38', false, 'a8e390a4-ef54-4b47-8d6d-6fb6f8670bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d64947e-677a-4f2c-9936-245e80b20b12', 'Rs 42', false, 'a8e390a4-ef54-4b47-8d6d-6fb6f8670bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('551b64f0-41b6-491d-8324-942c1290b191', 'Rs 36', false, 'a8e390a4-ef54-4b47-8d6d-6fb6f8670bc9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('089228de-2366-4345-8193-16a7a6e95f9c', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'In a city, 30% are females, 40% are males, and the remaining are children. What percentage are children?', '100% - 70% = 30%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f40991e4-22d8-47af-b714-3e394f3e2b67', '30% (Children % = 100% - (30% + 40%) = 30%)', true, '089228de-2366-4345-8193-16a7a6e95f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e461dbf-d817-4efa-8759-42c522e0599f', '20%', false, '089228de-2366-4345-8193-16a7a6e95f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb838172-0ac6-421b-9bde-4357b2594bee', '40%', false, '089228de-2366-4345-8193-16a7a6e95f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('180a7341-0207-4093-84bf-a08bacee6755', '35%', false, '089228de-2366-4345-8193-16a7a6e95f9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3fc62604-fc3b-48fa-b4a4-f5b66fac066a', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'Find the ratio of the speed of a cycle (15 km/h) to the speed of a scooter (30 km/h):', 'Ratio = 15 : 30 = 1 : 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f4c0492-5282-4787-9360-d74b89fef435', '1 : 2 (15 / 30 = 1 / 2)', true, '3fc62604-fc3b-48fa-b4a4-f5b66fac066a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f05c1f52-4b05-4527-9ed3-6733740d4ece', '2 : 1', false, '3fc62604-fc3b-48fa-b4a4-f5b66fac066a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93ec2c88-dbd8-43af-946e-b0c7fa6ef12e', '1 : 3', false, '3fc62604-fc3b-48fa-b4a4-f5b66fac066a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e3c873d-3d64-4d19-98b8-79b173b60107', '3 : 2', false, '3fc62604-fc3b-48fa-b4a4-f5b66fac066a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('feb4d270-bd38-4d2d-b741-194ba4bc7535', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3d81492-f270-499e-b58c-feb2f5797a0a', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'feb4d270-bd38-4d2d-b741-194ba4bc7535');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45a94606-5efd-4429-a1d7-9a011bd3485a', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'feb4d270-bd38-4d2d-b741-194ba4bc7535');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80bb1d2b-ef62-44fb-8c75-5ab4566a617f', '(A) is true, but (R) is false.', false, 'feb4d270-bd38-4d2d-b741-194ba4bc7535');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4829f1b4-b243-4cd8-b513-e1d421883e4b', '(A) is false, but (R) is true.', false, 'feb4d270-bd38-4d2d-b741-194ba4bc7535');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33d16509-3242-4e1e-b637-9336725e98ba', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Spot the IMPOSTER in the following commercial arithmetic equivalence relations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2cd53d0-b233-434f-8143-09f636a63a76', 'Equivalence 1', false, '33d16509-3242-4e1e-b637-9336725e98ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42193cd6-876f-4b15-ae00-c198aad35b4a', 'Equivalence 2', false, '33d16509-3242-4e1e-b637-9336725e98ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43c56463-120f-4f11-9e5a-20e3ef21a138', 'Equivalence 3', false, '33d16509-3242-4e1e-b637-9336725e98ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8065651-1b2e-4172-b476-0c9cbfeb7af2', 'Equivalence 4 (2/3 is equal to 66.67% or 66 2/3%, NOT 75% ; 3/4 is 75%)', true, '33d16509-3242-4e1e-b637-9336725e98ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('100118a6-b0d9-47df-9e38-a486fec3c095', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'A sum of money doubles itself in 8 years under Simple Interest. What is the annual Rate of Interest?', 'SI = P → P = (P × R × 8) / 100 → R = 100 / 8 = 12.5% per annum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52a0b15b-fb05-4192-86fa-905928501f36', '12.5% p.a. (Let Principal = P ; Since money doubles, Amount = 2P, so SI = P ; SI = (P × R × 8)/100 ⇒ P = (P × R × 8)/100 ⇒ R = 100 / 8 = 12.5% p.a.)', true, '100118a6-b0d9-47df-9e38-a486fec3c095');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcd51844-e021-47e8-9625-7fe3ae1c8115', '10% p.a.', false, '100118a6-b0d9-47df-9e38-a486fec3c095');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f164079-4642-4747-868f-153ae112a576', '15% p.a.', false, '100118a6-b0d9-47df-9e38-a486fec3c095');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1809760d-1329-417b-a8f3-d465c615eb4c', '8% p.a.', false, '100118a6-b0d9-47df-9e38-a486fec3c095');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1389a94a-35b4-4750-9cad-a9143ced6b5b', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Match Column I (Commercial Math Problems) with Column II (Exact Solutions):
(a) Convert 5/8 to Percentage               -> (i) 62.5%
(b) Increase in price from Rs 20 to Rs 25    -> (ii) 25% Increase
(c) Simple Interest on Rs 5000 @ 10% for 3 yr-> (iii) Rs 1,500
(d) Loss % when CP = Rs 50 and SP = Rs 40    -> (iv) 20% Loss', '5/8 = 62.5%; (5/20)×100 = 25%; (5000×10×3)/100 = 1500; (10/50)×100 = 20%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77406e04-f9cd-4171-84f3-1adbf50a3c4b', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '1389a94a-35b4-4750-9cad-a9143ced6b5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa9ab6f2-d0a5-47a6-afb5-3ef8f3fc936a', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '1389a94a-35b4-4750-9cad-a9143ced6b5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25126195-d36a-4885-bdef-a91f9b6a0116', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1389a94a-35b4-4750-9cad-a9143ced6b5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('922393be-282f-436b-9b24-34047bec0c12', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1389a94a-35b4-4750-9cad-a9143ced6b5b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74d290a5-cf50-4097-a9be-95b1dffdeb54', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Read the statements regarding price variations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f321b241-553c-4680-b0cd-71b7c42f5cbc', 'Statements 1 and 2 only', true, '74d290a5-cf50-4097-a9be-95b1dffdeb54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab282065-e3b2-4cd5-9c47-bad5dbb6673b', 'Statements 2 and 3 only', false, '74d290a5-cf50-4097-a9be-95b1dffdeb54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a21fa7fe-b7d4-4f8f-9d99-68f5d6b62a9a', 'Statements 1 and 3 only', false, '74d290a5-cf50-4097-a9be-95b1dffdeb54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7002b2f6-08d5-4d01-b06e-3115acbd0534', 'All Statements 1, 2, and 3', false, '74d290a5-cf50-4097-a9be-95b1dffdeb54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3310b41e-4cf8-407d-a654-d63e0d2c539a', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'If the Cost Price of 12 pens is equal to the Selling Price of 15 pens, find the Gain or Loss percentage:', 'Loss % = (15 - 12) / 15 × 100 = (3/15) × 100 = 20% loss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bee07039-a103-432a-b68c-e72e536d89b7', '20% Loss (Let CP of 1 pen = Rs 1 ; CP of 15 pens = Rs 15 ; SP of 15 pens = CP of 12 pens = Rs 12 ; Loss = 15 - 12 = Rs 3 ; Loss % = (3 / 15) × 100% = 20%)', true, '3310b41e-4cf8-407d-a654-d63e0d2c539a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab07fdb0-f762-4159-965e-fa77f4fb8eb5', '25% Profit', false, '3310b41e-4cf8-407d-a654-d63e0d2c539a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40405c06-bcb4-4402-b5a6-02800a764db7', '20% Profit', false, '3310b41e-4cf8-407d-a654-d63e0d2c539a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdabe68b-7283-46b9-8b3c-179862553a12', '25% Loss', false, '3310b41e-4cf8-407d-a654-d63e0d2c539a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4e46d93-ba58-4028-bc0f-b196671fd655', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'A sum of money invested at Simple Interest amounts to Rs 850 in 3 years and to Rs 925 in 4 years. Find the Principal sum and the annual Rate of Interest:', 'Annual SI = 925 - 850 = Rs 75. P = 850 - 3(75) = Rs 625. R = (75 × 100)/(625 × 1) = 12%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6497f1ec-09b3-40f0-bd21-ae85f673b88c', 'Principal = Rs 625 ; Rate = 12% p.a. (SI for 1 year = 925 - 850 = Rs 75 ; SI for 3 years = 75 × 3 = Rs 225 ; Principal = 850 - 225 = Rs 625 ; Rate = (75 × 100) / (625 × 1) = 12% p.a.)', true, 'f4e46d93-ba58-4028-bc0f-b196671fd655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d06353ee-b5fc-492c-a983-d53ebeb83ae6', 'Principal = Rs 600 ; Rate = 10%', false, 'f4e46d93-ba58-4028-bc0f-b196671fd655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f515b0ba-2c7e-46a3-82a7-8ecec77b0870', 'Principal = Rs 650 ; Rate = 14%', false, 'f4e46d93-ba58-4028-bc0f-b196671fd655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee1766cc-a7bb-41f4-b8e3-459753579e8d', 'Principal = Rs 700 ; Rate = 8%', false, 'f4e46d93-ba58-4028-bc0f-b196671fd655');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8d21f41-245e-4f91-a58f-3875ad9aafaf', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'In an election between two candidates, the winning candidate secured 58% of the total valid votes and won by a majority of 4,800 votes. Find the total number of valid votes polled:', 'Vote differential = 58% - 42% = 16%. Total votes = 4,800 / 0.16 = 30,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d19dbf59-4fd9-4717-8157-6a0334f84ce3', '30,000 votes (Winner % = 58% ; Loser % = 42% ; Margin = 58% - 42% = 16% ; 16% of Total = 4,800 ⇒ Total = (4800 / 16) × 100 = 30,000 votes)', true, 'c8d21f41-245e-4f91-a58f-3875ad9aafaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04ff4795-c399-4c8d-906d-9ecfb7e833b7', '25,000 votes', false, 'c8d21f41-245e-4f91-a58f-3875ad9aafaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71f76d6b-f351-47c9-aa0e-29d882da6e42', '35,000 votes', false, 'c8d21f41-245e-4f91-a58f-3875ad9aafaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9820ebd-3eed-4a47-b8b1-cfd34b0ad93c', '40,000 votes', false, 'c8d21f41-245e-4f91-a58f-3875ad9aafaf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c17d7584-774c-4e73-80fb-bb530d9aba59', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'A man sold two fans for Rs 990 each. On one he gained 10% and on the other he lost 10%. Find his overall Gain or Loss percentage on the entire whole transaction:', 'When SP is identical with ±x% gain/loss, there is always a net loss of (x/10)²% = (10/10)²% = 1% loss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cf5858f-675f-4b3c-a0b9-72aebac99c18', '1% Loss (CP1 = 990 / 1.10 = Rs 900 ; CP2 = 990 / 0.90 = Rs 1100 ; Total CP = 2000 ; Total SP = 1980 ; Net Loss = Rs 20 ; Loss % = (20 / 2000) × 100% = 1%)', true, 'c17d7584-774c-4e73-80fb-bb530d9aba59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f66f6ffa-f442-429d-bd52-0e6e0d0017a5', 'No profit no loss', false, 'c17d7584-774c-4e73-80fb-bb530d9aba59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ceeaaae-0ffd-4e4e-9282-0e7c4d52d807', '1% Gain', false, 'c17d7584-774c-4e73-80fb-bb530d9aba59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32cc8fde-0d94-4dba-8430-496bcb6d9300', '2% Loss', false, 'c17d7584-774c-4e73-80fb-bb530d9aba59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26008023-d880-434c-81bc-d49ed0fe2aeb', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'The salary of an officer was increased by 20%. By what percentage must the new salary be reduced to bring it back to the original initial salary level?', '% Reduction = (r / (100 + r)) × 100% = (20 / 120) × 100 = 16.67% (or 16 2/3%).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82489484-efe5-4aae-8024-91435f2528b3', '16 2/3% or 16.67% (Let original = 100 ⇒ New = 120 ; Reduction required = 20 ; % Reduction = (20 / 120) × 100% = 100 / 6 = 16.67%)', true, '26008023-d880-434c-81bc-d49ed0fe2aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('600dda80-54f5-49b8-81a0-0fe8a1cfb091', '20%', false, '26008023-d880-434c-81bc-d49ed0fe2aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cebae82d-d47f-415f-a81d-762e4d116a89', '25%', false, '26008023-d880-434c-81bc-d49ed0fe2aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('141bfe29-4ff9-4001-b12f-6c2e1f7df336', '15%', false, '26008023-d880-434c-81bc-d49ed0fe2aeb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc445c85-362d-4c24-bf4f-903ca9668957', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'At what rate percent per annum simple interest will a sum of money TRIPLE itself in 16 years?', 'SI = 2P → 2P = (P × R × 16)/100 → R = 200 / 16 = 12.5% per annum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccd49dfb-58cc-4534-a4c5-de408c4d86a2', '12.5% p.a. (Amount = 3P ⇒ SI = 2P ; 2P = (P × R × 16) / 100 ⇒ R = 200 / 16 = 12.5% p.a.)', true, 'dc445c85-362d-4c24-bf4f-903ca9668957');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a7d830d-396e-4376-984e-9675acdfeae3', '10% p.a.', false, 'dc445c85-362d-4c24-bf4f-903ca9668957');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e53caafd-8bac-40e1-8ab6-c128c94edc0c', '15% p.a.', false, 'dc445c85-362d-4c24-bf4f-903ca9668957');
