INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7f54b62-3099-40dd-9f14-71140fa4fd59', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Why is the mathematical mastery of Comparing Quantities (Ratios, Percentages, Profit-Loss, and Simple Interest) fundamental across economics, financial literacy, demographic statistics, and everyday commerce?', 'Quantitative comparison frameworks underwrite modern financial literacy, economic metric normalization, accounting standards, and risk-adjusted capital pricing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9b4c52d-2a34-4dd9-8671-71506b4048ef', 'It provides the universal quantitative language for normalizing scales, calculating financial returns on capital, evaluating economic growth rates, and making sound personal financial decisions', true, 'b7f54b62-3099-40dd-9f14-71140fa4fd59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('918e679b-a209-4aa7-bb75-b2be0463c899', 'Because numbers are only used to count coins', false, 'b7f54b62-3099-40dd-9f14-71140fa4fd59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82bd3c52-46ab-445f-8f56-4bf3a9b37795', 'Because percentage was invented to make math harder', false, 'b7f54b62-3099-40dd-9f14-71140fa4fd59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97e34daa-eb77-4e1c-af55-9c755a9c40a0', 'Because interest is paid only in gold', false, 'b7f54b62-3099-40dd-9f14-71140fa4fd59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8daef5a-6f7d-4a7d-9b12-e7cb691c086d', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'In Roald Dahl''s imaginative excerpt ''The Invention of Vita-Wonk'', who is the eccentric, brilliant chocolatier and inventor?', 'Mr. Willy Wonka is the legendary eccentric inventor from Roald Dahl''s ''Charlie and the Great Glass Elevator''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d43c604-e990-4777-80dd-398434e8f1d0', 'Mr. Willy Wonka', true, 'c8daef5a-6f7d-4a7d-9b12-e7cb691c086d');
