INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae9ebb4a-01c7-46a0-bbb7-75295246ee9a', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What medicine did Mr. Willy Wonka first invent that made people become so much younger that some people vanished into negative ages (like minus eighty-seven)?', 'Wonka-Vite made people younger; but being too potent, it made some people have negative ages (minus 87) where they had to wait 87 years to be born!', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('887c65b8-1ae1-422f-8031-90f219f110c0', 'Wonka-Vite', true, 'ae9ebb4a-01c7-46a0-bbb7-75295246ee9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df57cf46-6f57-4604-9e2f-ad6f9f779147', 'Vita-Wonk', false, 'ae9ebb4a-01c7-46a0-bbb7-75295246ee9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('104dae8a-186a-4a41-b396-7218c226ee7d', 'Everlasting Gobstopper', false, 'ae9ebb4a-01c7-46a0-bbb7-75295246ee9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63fc350f-b589-4624-8b04-f4d729ddf9a3', 'Fizzing Whizzpopper', false, 'ae9ebb4a-01c7-46a0-bbb7-75295246ee9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef2d88b2-88d8-441b-a3c3-8e2823fa607b', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What opposite new medicine does Mr. Willy Wonka set out to invent to make people grow older and reverse the negative age catastrophe?', 'To undo the effects of Wonka-Vite, Mr. Wonka creates ''Vita-Wonk'' to age people up.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd2d6608-db0e-4e18-bb73-455fc3d42bb9', 'Vita-Wonk', true, 'ef2d88b2-88d8-441b-a3c3-8e2823fa607b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ab62032-c893-4b58-ac5b-02ae6efdde8a', 'Wonka-Vite', false, 'ef2d88b2-88d8-441b-a3c3-8e2823fa607b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16ff762e-e0e0-49aa-bb10-a7e95cd4531e', 'Snozzberry Syrup', false, 'ef2d88b2-88d8-441b-a3c3-8e2823fa607b');
