INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4aea206-2a1f-4f5b-b512-c637815474c1', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What is the OLDEST living thing on Earth from which Mr. Wonka collects sap for Vita-Wonk?', 'Mr. Wonka explains to Charlie that Bristlecone pines living on the slopes of Wheeler Peak in Nevada live over 4,000 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27daaed5-6eca-489d-9cf4-784eb20b6f7e', 'The Bristlecone Pine tree (living over 4,000 years on Wheeler Peak)', true, 'e4aea206-2a1f-4f5b-b512-c637815474c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8dd314a-e7bb-4ed2-95a0-d8af9b23fbe6', 'An Oak tree', false, 'e4aea206-2a1f-4f5b-b512-c637815474c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcadb6df-1607-4da3-9662-e90ce882c128', 'A Redwood tree', false, 'e4aea206-2a1f-4f5b-b512-c637815474c1');
