INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77d919f1-416d-4031-902b-afe66fcd1c4f', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'Which 20-year-old brave volunteer was given four drops of oily black Vita-Wonk liquid to test its aging power?', 'A brave 20-year-old Oompa-Loompa volunteer swallowed the four drops of oily black Vita-Wonk.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68e3b05f-1887-461e-8cec-e2e4933040c8', 'An Oompa-Loompa volunteer named Oompa-Loompa', true, '77d919f1-416d-4031-902b-afe66fcd1c4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88e36447-111c-407d-96b1-7a31e66b3b10', 'Charlie Bucket', false, '77d919f1-416d-4031-902b-afe66fcd1c4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afb47d89-17b8-4f2a-93c9-32e11376df4d', 'Mr. Bucket', false, '77d919f1-416d-4031-902b-afe66fcd1c4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d767dda7-c8e2-422d-b33e-bed537cf12b8', 'Augustus Gloop', false, '77d919f1-416d-4031-902b-afe66fcd1c4f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f656671-3e2a-4bdb-86bd-2b09c6a71673', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What dramatic physical transformation happened to the 20-year-old volunteer after swallowing the four drops of Vita-Wonk?', 'Vita-Wonk aged the 20-year-old instantly into a 75-year-old wrinkly man, proving the invention''s success.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a12dbdf-3b74-4941-97a3-fea6eee184de', 'He began wrinkling and shriveling up, his hair dropped off, his teeth fell out, and he instantly became a feeble old fellow of SEVENTY-FIVE (75 years old)!', true, '8f656671-3e2a-4bdb-86bd-2b09c6a71673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84a12bb8-065a-47ab-a9ad-43ef43f7e073', 'He turned into a giant green tree', false, '8f656671-3e2a-4bdb-86bd-2b09c6a71673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('332ace38-7c74-49c7-9e6d-e47a5fa68749', 'He became a newborn baby', false, '8f656671-3e2a-4bdb-86bd-2b09c6a71673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8643efb1-7940-467d-9742-1b5a27fa4fc3', 'He turned into solid ice', false, '8f656671-3e2a-4bdb-86bd-2b09c6a71673');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0132b277-d94b-400a-a7ba-79cb8725f652', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'In Kit Wright''s humorous poem ''Dad and the Cat and the Tree'', where was the cat stuck?', 'The poem begins: ''This morning a cat got stuck in our tree. / Dad said, "Right, just leave it to me."''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77c959ba-2625-4147-8ffa-14a900bde710', 'High up in a tall tree in the garden', true, '0132b277-d94b-400a-a7ba-79cb8725f652');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aed3feba-9815-4918-a64a-6d2c0e5eae81', 'On the roof of the house', false, '0132b277-d94b-400a-a7ba-79cb8725f652');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4868ef75-9fed-47fa-b5d6-f4db78a19758', 'In a deep well', false, '0132b277-d94b-400a-a7ba-79cb8725f652');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4a0ef09-aa2a-4d7f-8909-4e2ce8a84e01', 'On top of a telegraph pole', false, '0132b277-d94b-400a-a7ba-79cb8725f652');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b72a590-70d2-4ad9-a457-776eb66ba628', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What boastful remark did Dad make to Mum before attempting to rescue the cat from the tree?', 'Dad overconfidently dismisses Mum''s warnings: ''A climber like me? Child''s play, this is!''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3ebbcee-8d47-4b98-ae93-45f3e663bd36', '"Easy as winking to a climber like me! Just leave it to me!"', true, '2b72a590-70d2-4ad9-a457-776eb66ba628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21090ceb-acc4-4d02-8bfe-9e3efa248126', '"I will call the fire brigade!"', false, '2b72a590-70d2-4ad9-a457-776eb66ba628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3812fc8-1643-41f7-9d47-9ecce8dceba4', '"Let the cat stay there forever!"', false, '2b72a590-70d2-4ad9-a457-776eb66ba628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e730f3b0-6f17-4294-8cdb-31f6740c2559', '"I need to study climbing books!"', false, '2b72a590-70d2-4ad9-a457-776eb66ba628');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43c7bae6-ad34-4c97-adb3-f06279cfa390', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What happened to Dad''s ''PLAN A'' using a ladder from the garden shed?', 'Plan A failed: ''It slipped. He landed in the garden bed.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a31e5303-5991-40fb-8a20-f2cbc256cb5f', 'The ladder slipped and Dad landed flat in the flowerbed!', true, '43c7bae6-ad34-4c97-adb3-f06279cfa390');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('569b5781-d539-49ae-9aef-0a18fefbcdbd', 'The ladder reached the cat easily', false, '43c7bae6-ad34-4c97-adb3-f06279cfa390');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('934cc100-3290-46ef-893e-c1bd0b193db2', 'The ladder caught fire', false, '43c7bae6-ad34-4c97-adb3-f06279cfa390');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7f39e7-36b7-4b83-adb0-2a413aee3d20', 'The cat climbed down the ladder', false, '43c7bae6-ad34-4c97-adb3-f06279cfa390');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d295620-5aa8-4ee6-ad50-8c5b881c040f', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What happened to Dad''s ''PLAN B'' when he swung himself up onto a bough of the tree?', 'Plan B failed: ''He swung himself up on a bough. It broke. Dad grovelled.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e7af874-b8aa-4139-939d-6847c8104401', 'The bough snapped and Dad crashed heavily to the ground again!', true, '9d295620-5aa8-4ee6-ad50-8c5b881c040f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('611d1d83-7386-420e-a0e1-efc06fbdc282', 'He grabbed the cat gently', false, '9d295620-5aa8-4ee6-ad50-8c5b881c040f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a0a5f8c-7d6a-4b8e-b402-1c465d363d40', 'He fell asleep in the tree', false, '9d295620-5aa8-4ee6-ad50-8c5b881c040f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9fc4157-8e0b-4040-86ec-f3f4e179c00a', 'He flew into the air', false, '9d295620-5aa8-4ee6-ad50-8c5b881c040f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86239464-45a2-4c2b-a16b-7e5ff8b8cba2', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What hilarious twist occurs at the end of the poem when Dad tries ''PLAN C'' and leaps from the garden wall into the tree?', 'Ironical climax: the cat leaps safely to the ground unharmed, leaving boastful Dad stuck in the tree crook.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('438164fd-0eeb-4578-94c9-212a9c7de76c', 'Dad lands flat on the cat, which yells and drops safely to the ground smiling smugly, while Dad is left STUCK high in the tree!', true, '86239464-45a2-4c2b-a16b-7e5ff8b8cba2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('862d50b4-9fa8-4931-990e-4ab496be7aa3', 'Both Dad and the cat fly away', false, '86239464-45a2-4c2b-a16b-7e5ff8b8cba2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29dcf6d3-1cee-4e6d-8256-3127af90ae5e', 'The tree falls down', false, '86239464-45a2-4c2b-a16b-7e5ff8b8cba2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22b9a734-9a14-4b3a-95d0-12b71b555f95', 'Mum climbs up and rescues both', false, '86239464-45a2-4c2b-a16b-7e5ff8b8cba2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da33d832-e5e4-4918-a3b1-45de83a0d104', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What is the meaning of the colloquial idiom ''Child''s play'' used by Dad?', '''Child''s play'' is an idiom signifying an effortless, elementary task.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04647fb1-c1ff-449d-9f06-cdf2a829a1f3', 'Something that is very easy, simple, and effortless to do', true, 'da33d832-e5e4-4918-a3b1-45de83a0d104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de60363b-f093-4a7c-acc7-515fb6eb3fbe', 'A complicated puzzle', false, 'da33d832-e5e4-4918-a3b1-45de83a0d104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8652d1e-b783-4424-a49b-1723da09d25f', 'A board game for two players', false, 'da33d832-e5e4-4918-a3b1-45de83a0d104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0093f7c-7abb-4751-b751-f12924f17378', 'Playing with toys in a kindergarten', false, 'da33d832-e5e4-4918-a3b1-45de83a0d104');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4162772-7ebd-4f52-9dbd-03472e3df45b', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Medium', 'Which of the following absurd, whimsical ingredients was collected by Mr. Willy Wonka for brewing Vita-Wonk?', 'Dahl invents a surreal catalog of ancient biological curiosities for Wonka''s aging elixir.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c2107a0-969e-4529-a4b3-676e503c5bc8', 'A pint of sap from a 4,000-year-old Bristlecone pine, the tail of a 51-year-old horse, whiskers of a 36-year-old cat named Crumpets, and an egg laid by a 207-year-old giant tortoise', true, 'e4162772-7ebd-4f52-9dbd-03472e3df45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29ebd0c0-1383-4c27-a08e-bc95cd58954c', 'Pure fresh milk and brown sugar only', false, 'e4162772-7ebd-4f52-9dbd-03472e3df45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('532a8fa6-871f-451c-83c7-305c7655ebbf', 'Potatoes, onions, and salt', false, 'e4162772-7ebd-4f52-9dbd-03472e3df45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf9aa1f-c50a-408e-8823-49d3bfa8ab25', 'Gasoline and metal screws', false, 'e4162772-7ebd-4f52-9dbd-03472e3df45b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90db3edb-510d-4fa7-933b-fde25723a487', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Medium', 'How did Mr. Willy Wonka travel across the globe to collect bits and pieces from the world''s most ancient creatures?', 'Wonka zoomed across the planet in his fantastical Great Glass Elevator to harvest ancient specimen samples.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77ce5c31-23f2-43b5-97b3-220583344724', 'He tracked them down in his Great Glass Elevator, searching high and low across continents and oceans', true, '90db3edb-510d-4fa7-933b-fde25723a487');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a0ad8b9-34ad-4f6a-8690-e31d4501a49d', 'He walked on foot with a wooden stick', false, '90db3edb-510d-4fa7-933b-fde25723a487');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b2db114-1498-4947-b65f-4237f3100ca1', 'He rode on a bicycle', false, '90db3edb-510d-4fa7-933b-fde25723a487');
