INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dfce9d0-bef1-42d0-9e96-9e4c452a0db8', 'Dad wants to chop down the garden tree', false, '75a188db-7a72-480e-b789-54f158f9f531');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8c41beb-1755-4466-b634-c7f2cbfffde7', 'Dad hates all animals', false, '75a188db-7a72-480e-b789-54f158f9f531');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('744cadd2-f1fc-4eb9-ba84-a638c5fead86', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Match Column I (Literary Works / Episodes) with Column II (Central Humorous Elements):
(a) Wonka-Vite Recipe            -> (i) Over-potent youth formula resulting in negative chronological existence
(b) Vita-Wonk Extraction        -> (ii) Surreal distillation of ancient biological curiosities from around the globe
(c) Dad''s Plan A (Ladder)        -> (iii) Slipping into the flowerbed with dirt on hair and face
(d) Dad''s Plan C (Wall Leap)     -> (iv) Landing directly on the cat, triggering the cat''s escape and Dad''s entrapment', 'Wonka-Vite = negative age; Vita-Wonk = ancient ingredients; Plan A = flowerbed fall; Plan C = cat escape & father trapped.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad60c387-a3c5-458f-80fe-a96e33b48967', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '744cadd2-f1fc-4eb9-ba84-a638c5fead86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc0f04b6-444f-47d8-a2ff-5384a5156585', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '744cadd2-f1fc-4eb9-ba84-a638c5fead86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('544cc724-3c58-4b4a-b58b-30ab2e7afdaf', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '744cadd2-f1fc-4eb9-ba84-a638c5fead86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('489d2700-0e39-40a9-bad5-464fd9b31f63', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '744cadd2-f1fc-4eb9-ba84-a638c5fead86');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a387daa9-eb2b-43f7-9c10-37e2643409b5', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Read the statements regarding Roald Dahl''s imaginative techniques:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e0fd9a-be9d-48f1-9917-635a591656ed', 'Statements 1 and 2 only', true, 'a387daa9-eb2b-43f7-9c10-37e2643409b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f97f6acb-37d0-4be9-956b-9127aa08f2a8', 'Statements 2 and 3 only', false, 'a387daa9-eb2b-43f7-9c10-37e2643409b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72712af7-7297-4441-b0ea-3b5b2e8d2628', 'Statements 1 and 3 only', false, 'a387daa9-eb2b-43f7-9c10-37e2643409b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6b1e32d-5f0a-4d30-a0c9-86b140115abe', 'All Statements 1, 2, and 3', false, 'a387daa9-eb2b-43f7-9c10-37e2643409b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac45f231-0b20-4348-a882-64096d903b03', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Change the complex sentence into PASSIVE VOICE:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a92ba6-2876-4826-884f-9865435e3e36', '''The mysterious black liquid was distilled by Mr. Willy Wonka in his testing laboratory.''', true, 'ac45f231-0b20-4348-a882-64096d903b03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21f7e861-b2a7-42a2-838e-02d32635fc77', '''In his testing laboratory distilled Mr. Willy Wonka the liquid.''', false, 'ac45f231-0b20-4348-a882-64096d903b03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63985419-0413-42ad-8355-a3cecd97322b', '''The testing laboratory was distilling the mysterious black liquid.''', false, 'ac45f231-0b20-4348-a882-64096d903b03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdd04b73-08a5-44cb-9e20-add78300b649', '''The mysterious black liquid had been distilling by Mr. Wonka.''', false, 'ac45f231-0b20-4348-a882-64096d903b03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('edd53b6e-08ab-41ff-819e-b1c7a9dd3e69', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Identify the grammatical role of the underlined participial clause in: ''**Leaping from the garden wall**, Dad crashed straight into the crook of the tree.''', '''Leaping from the garden wall'' is an introductory participial phrase describing Dad''s dynamic action modifying the main clause.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97a171b1-6b56-474e-b494-12841db9e1d6', 'Present Participial Phrase acting as an adverbial modifier of manner/time for the subject ''Dad''', true, 'edd53b6e-08ab-41ff-819e-b1c7a9dd3e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('949c829f-93e5-4f48-890a-f06b3556d753', 'Noun Clause acting as object', false, 'edd53b6e-08ab-41ff-819e-b1c7a9dd3e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dee1cf20-9874-4892-a460-ab6afb2e4f36', 'Infinitive of purpose', false, 'edd53b6e-08ab-41ff-819e-b1c7a9dd3e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d43f1cf4-d4f0-4d19-924b-89f99e85ef15', 'Relative clause', false, 'edd53b6e-08ab-41ff-819e-b1c7a9dd3e69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('225966c8-a6b1-4aed-b57e-fe5622dafb22', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Why does Roald Dahl emphasize the precise botanical reality of the ''Bristlecone Pine'' in his dialogue with Charlie?', 'Dahl grounds his fantasy in genuine botanical awe: the ancient Bristlecone pine (Pinus longaeva) really is Earth''s oldest living non-clonal organism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc199f96-cfec-4d98-a5eb-103aa8e21dac', 'To anchor his fantastical narrative in authentic natural wonder, proving to children that nature''s real living marvels are often more incredible than fiction', true, '225966c8-a6b1-4aed-b57e-fe5622dafb22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bceb506d-9d35-4055-a928-8c176b41ec9b', 'To encourage people to cut down trees', false, '225966c8-a6b1-4aed-b57e-fe5622dafb22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45fbda71-d211-49c5-bd61-f330fdf508f2', 'To sell wood furniture', false, '225966c8-a6b1-4aed-b57e-fe5622dafb22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('febfcb53-8656-4f33-a9e1-29daeb78e42b', 'Because Dahl lived in Nevada', false, '225966c8-a6b1-4aed-b57e-fe5622dafb22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7541ecfa-7f7b-4782-8409-a6e759e2180f', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'In the rhythm and rhyme scheme of ''Dad and the Cat and the Tree'', what poetic form enhances the fast-paced slapstick delivery?', 'Bouncy ballad quatrains with sharp rhyming couplets propel the slapstick narrative forward with brisk comedic timing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('167a34ef-0e72-4066-8332-24a7207f9994', 'Rhyming quatrains (AABB / ABCB) with lively, bouncy anapestic and iambic meter that mimics the escalating cadence of cartoon physical comedy', true, '7541ecfa-7f7b-4782-8409-a6e759e2180f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c729482c-eda5-4b30-b8e2-c42ee80d777e', 'Sombre funeral elegiac verse', false, '7541ecfa-7f7b-4782-8409-a6e759e2180f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2b0ac5e-308b-4818-bed9-a6f5e7f98cde', 'Unrhymed blank verse in sonnet form', false, '7541ecfa-7f7b-4782-8409-a6e759e2180f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8e2e5ad-1ce4-44f3-b66c-3709f8b0e04f', 'Ancient Greek hexameter', false, '7541ecfa-7f7b-4782-8409-a6e759e2180f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d41349af-ebbb-49b6-bd91-56041e523dc7', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'What does the phrase ''Rubbed his hands together'' signify when Mr. Willy Wonka proclaims the success of his invention?', 'Rubbing hands together is a kinetic body language idiom expressing eager anticipation and triumphant professional delight.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('462bddea-dba5-4688-b70b-882589ef1718', 'A universal human physical gesture denoting extreme excitement, triumphant satisfaction, and anticipation of success', true, 'd41349af-ebbb-49b6-bd91-56041e523dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a7735e-6cdb-46b0-b266-ce4320485e59', 'That his hands were very cold', false, 'd41349af-ebbb-49b6-bd91-56041e523dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eeed5b5-d09a-401b-a6bc-baff7c6a7c23', 'That he wanted to wash his hands', false, 'd41349af-ebbb-49b6-bd91-56041e523dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac6ad291-f1de-4cb9-82b1-8e9be6af4987', 'That he was angry at Charlie', false, 'd41349af-ebbb-49b6-bd91-56041e523dc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2954746-b877-417b-832b-a6418f1adff4', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Which of the following lines from the poem contains an ONOMATOPOEIC sound word?', '''SMACK!'' is an onomatopoeic auditory word recreating the sharp physical acoustic impact of landing on the ground.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ece59b0-5f92-4a01-9460-c639cc139385', '"The bough broke — SMACK! / Dad grovelled."', true, 'c2954746-b877-417b-832b-a6418f1adff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76e17855-48f0-4b82-a367-4717d95bf893', '"A climber like me?"', false, 'c2954746-b877-417b-832b-a6418f1adff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e9bf752-921a-4fc1-9d59-3c6dc23056f1', '"This morning a cat got stuck in our tree."', false, 'c2954746-b877-417b-832b-a6418f1adff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3340c0b-e863-468c-9032-71454a5fd0ae', '"Smiling and smirking, smug as can be."', false, 'c2954746-b877-417b-832b-a6418f1adff4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('340412f1-596a-4941-8c06-140735fa84ae', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'What overarching literary value unites Chapter 7 of NCERT Class 7 English?', 'Chapter 7 champions the vitality of imaginative storytelling, joyful wordplay, and the playful subversion of self-serious adult authority.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94a138d4-651f-467a-8c1a-d7b01d1746a5', 'The celebration of exuberant literary imagination, boundless creative curiosity, and the therapeutic power of lighthearted humor in transforming everyday life into whimsical wonder', true, '340412f1-596a-4941-8c06-140735fa84ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbde2622-95ea-483c-88f6-9388ee2832dd', 'That climbing trees is strictly forbidden by law', false, '340412f1-596a-4941-8c06-140735fa84ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('251c8495-1348-448f-a4c6-ceeb2ef41443', 'That medicines should be mixed with tea', false, '340412f1-596a-4941-8c06-140735fa84ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f9af496-c2b3-4ff3-9d2c-5a9aaf5ac01d', 'That cats are always smarter than humans', false, '340412f1-596a-4941-8c06-140735fa84ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('150e6ff9-cbf0-419f-a962-85992dbdcebf', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Who is celebrated as the ''Father of the Indian Constitution'' and was the Chairman of the Drafting Committee of the Constituent Assembly?', 'Dr. Bhimrao Ramji Ambedkar chaired the Drafting Committee, shaping the foundational democratic architecture of the Indian Republic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caa35dde-1a40-4056-9d04-4e8f538b319d', 'Dr. B.R. Ambedkar', true, '150e6ff9-cbf0-419f-a962-85992dbdcebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cac671f6-878c-40ab-8b49-6fa4b25d3772', 'Dr. Rajendra Prasad', false, '150e6ff9-cbf0-419f-a962-85992dbdcebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a55ae60d-80ef-49e7-98f9-0b7dfe0a6d81', 'Jawaharlal Nehru', false, '150e6ff9-cbf0-419f-a962-85992dbdcebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('072da92c-f1fa-4258-8f06-1be54cd26e2b', 'Sardar Vallabhbhai Patel', false, '150e6ff9-cbf0-419f-a962-85992dbdcebf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea6feb15-32aa-47ef-9e1e-294eb99cee13', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'On which historic date did the Constitution of India come into full legal effect, celebrated annually as REPUBLIC DAY?', 'The Constitution came into force on 26 January 1950, commemorating the 1930 Purna Swaraj declaration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ce59808-d206-40fa-9908-a4484704c9d3', '26 January 1950', true, 'ea6feb15-32aa-47ef-9e1e-294eb99cee13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0984651-0965-4180-9e14-f16e687e43b4', '15 August 1947', false, 'ea6feb15-32aa-47ef-9e1e-294eb99cee13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9667052-335b-452f-a040-7870455d0b51', '26 November 1949', false, 'ea6feb15-32aa-47ef-9e1e-294eb99cee13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1b522fd-dbda-4521-bf13-e616c79a414f', '2 October 1950', false, 'ea6feb15-32aa-47ef-9e1e-294eb99cee13');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('940fec0e-ff6a-44ad-8495-15f46999ec74', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'On which date is ''Constitution Day'' (Samvidhan Divas) celebrated in India to commemorate the formal adoption of the Constitution by the Constituent Assembly in 1949?', 'The Constituent Assembly adopted the Constitution on 26 November 1949, observed nationally as Samvidhan Divas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5278817c-c752-48bf-80bc-c1688dfeb3bf', '26 November', true, '940fec0e-ff6a-44ad-8495-15f46999ec74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f887d5b-8c68-4a40-a4ef-e03ebc758b51', '26 January', false, '940fec0e-ff6a-44ad-8495-15f46999ec74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cdacf88-1e4b-477b-9e15-fdeb3271ff43', '15 August', false, '940fec0e-ff6a-44ad-8495-15f46999ec74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cd480a0-119c-41c5-959e-51e73d5e8a48', '30 January', false, '940fec0e-ff6a-44ad-8495-15f46999ec74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a4f9011-5d88-4721-9cbd-be129eeabd75', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Who was the elected permanent President of the Constituent Assembly of India and the First President of independent India?', 'Dr. Rajendra Prasad presided over the Constituent Assembly from Dec 1946 until its conclusion and served as India''s first President.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8130bfa9-e6c4-4abc-be07-68f398bd86b6', 'Dr. Rajendra Prasad', true, '3a4f9011-5d88-4721-9cbd-be129eeabd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c654388-4b55-4eb7-82b0-feef360c62fd', 'Dr. B.R. Ambedkar', false, '3a4f9011-5d88-4721-9cbd-be129eeabd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67f18755-b1c1-4727-9912-5e187dc37bf7', 'Dr. S. Radhakrishnan', false, '3a4f9011-5d88-4721-9cbd-be129eeabd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('892039de-c65c-403f-a0c5-b1c17019295e', 'C. Rajagopalachari', false, '3a4f9011-5d88-4721-9cbd-be129eeabd75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba26c24e-d919-4cfc-8a1e-a80b24a708cb', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'What is the introductory opening statement of the Constitution that outlines the core philosophy, values, and objectives of the Indian Republic called?', 'The Preamble proclaims India as a ''Sovereign Socialist Secular Democratic Republic'' securing Justice, Liberty, Equality, and Fraternity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34e7358d-4615-4058-865e-15b34e15defc', 'The Preamble', true, 'ba26c24e-d919-4cfc-8a1e-a80b24a708cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2c577d1-d049-4f96-8220-2b33ba7bf051', 'The Index', false, 'ba26c24e-d919-4cfc-8a1e-a80b24a708cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd7bed28-e142-472c-9cfb-889a4830da92', 'The Schedule', false, 'ba26c24e-d919-4cfc-8a1e-a80b24a708cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8add4d11-bd6f-47da-b56c-65b348d1c121', 'The Directive Principles', false, 'ba26c24e-d919-4cfc-8a1e-a80b24a708cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('edd365be-0045-42b5-9757-6f761cb7c3cd', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'How many broad categories of Fundamental Rights are guaranteed to all Indian citizens under Part III of the Constitution (Articles 12–35)?', 'The Constitution guarantees 6 Fundamental Rights (the 44th Amendment in 1978 removed the Right to Property as a fundamental right).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4f956cf-c81e-4354-a4eb-526d7ac36920', '6 Fundamental Rights (Right to Equality, Freedom, Against Exploitation, Freedom of Religion, Cultural/Educational, and Constitutional Remedies)', true, 'edd365be-0045-42b5-9757-6f761cb7c3cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2905f91c-c5a6-4183-ad1e-82d6cd0fe791', '7 Fundamental Rights (Right to Property was deleted)', false, 'edd365be-0045-42b5-9757-6f761cb7c3cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a3e7175-8ef6-446c-a6f4-179375e997f0', '10 Fundamental Rights', false, 'edd365be-0045-42b5-9757-6f761cb7c3cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46d2aa01-e1ec-4423-98f3-c42c23cc9d39', '4 Fundamental Rights', false, 'edd365be-0045-42b5-9757-6f761cb7c3cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74f29a52-ea9f-46ee-81d2-14171f551450', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Which Fundamental Right under Article 32 was described by Dr. B.R. Ambedkar as the "Heart and Soul of the Constitution"?', 'Article 32 empowers the Supreme Court to issue writs (Habeas Corpus, Mandamus, etc.) to enforce fundamental rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('942fc629-d863-497e-a352-a329d7a50698', 'Right to Constitutional Remedies (the right to petition the Supreme Court directly via writs)', true, '74f29a52-ea9f-46ee-81d2-14171f551450');
