INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8df07e7-8705-4bc3-890e-5ea89675e77e', 'Right to Freedom', false, '74f29a52-ea9f-46ee-81d2-14171f551450');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18468f27-f906-4786-9636-59debe17c135', 'Right to Education', false, '74f29a52-ea9f-46ee-81d2-14171f551450');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ebcf0da7-c01e-44ac-8468-b664fe2da839', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Who is the Constitutional Head of State of the Republic of India and the Supreme Commander of the Indian Armed Forces?', 'The President is the executive Head of State and supreme commander of the army, navy, and air force under Article 53.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79702807-c19e-43d8-8f92-51aeedfbd214', 'The President of India', true, 'ebcf0da7-c01e-44ac-8468-b664fe2da839');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b84b820d-8899-4531-b710-440a88b02b04', 'The Prime Minister', false, 'ebcf0da7-c01e-44ac-8468-b664fe2da839');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4a858db-5c31-45bf-b779-56ea62369bbe', 'The Chief Justice of India', false, 'ebcf0da7-c01e-44ac-8468-b664fe2da839');
