INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1300e648-94b4-4b3a-80c4-e2da759ab639', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'What are the two houses of the bicameral Parliament of India (Sansad)?', 'The Union Parliament comprises the President, Lok Sabha (directly elected lower house), and Rajya Sabha (states'' council upper house).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91d21bab-ff9c-41af-a4ba-39720cf79b95', 'The Lok Sabha (House of the People) and the Rajya Sabha (Council of States)', true, '1300e648-94b4-4b3a-80c4-e2da759ab639');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41eaa9d2-adce-4c9d-9435-4c8903861794', 'The Senate and House of Representatives', false, '1300e648-94b4-4b3a-80c4-e2da759ab639');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88e3e5d4-b2bb-428e-9b3a-1d35546d2dcb', 'The Vidhan Sabha and Vidhan Parishad', false, '1300e648-94b4-4b3a-80c4-e2da759ab639');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72e2381d-b850-44e3-8a63-31e3e3ef7998', 'The Supreme Court and High Court', false, '1300e648-94b4-4b3a-80c4-e2da759ab639');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1257bfb-cc2a-4c68-aa7d-66fbf7e46908', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'What is the highest judicial court of appeal and custodian of the Constitution in India, headquartered on Tilak Marg in New Delhi?', 'The Supreme Court of India (inaugurated 28 January 1950) is the apex judicial forum and constitutional interpreter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('341a01c4-2833-4dec-9ced-904b00a31dba', 'The Supreme Court of India', true, 'c1257bfb-cc2a-4c68-aa7d-66fbf7e46908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf9cd25e-ff16-4d2b-ad59-459c7580d6cd', 'The High Court of Delhi', false, 'c1257bfb-cc2a-4c68-aa7d-66fbf7e46908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad1825e8-700b-4293-ab00-eaea9eed0873', 'The National Green Tribunal', false, 'c1257bfb-cc2a-4c68-aa7d-66fbf7e46908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be9eeb39-742d-4d6e-a3b0-18e3fe39c9e5', 'The Parliament', false, 'c1257bfb-cc2a-4c68-aa7d-66fbf7e46908');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('790bbd3f-e1e3-4170-b583-4c2cae8726d8', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'What is the minimum voting age for Indian citizens in general elections under the Universal Adult Suffrage principle (lowered from 21 by 61st Amendment)?', 'The 61st Constitutional Amendment Act (1988) amended Article 326 to lower the voting age from 21 to 18 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('129d92e5-a368-4ab0-8af2-1509aa0d64ac', '18 years', true, '790bbd3f-e1e3-4170-b583-4c2cae8726d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79a5b58d-addc-40c4-ac99-fdb6318a9899', '21 years', false, '790bbd3f-e1e3-4170-b583-4c2cae8726d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69cc5c65-4ddb-4892-98cf-20bdda0b0744', '25 years', false, '790bbd3f-e1e3-4170-b583-4c2cae8726d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c80f591d-5075-4e8d-878d-71f15d1fefc4', '16 years', false, '790bbd3f-e1e3-4170-b583-4c2cae8726d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d100a5a-1d24-4f98-bc2b-d3a7e3c452cc', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Which independent constitutional body conducts free and fair elections to the Lok Sabha, Rajya Sabha, State Legislatures, and the offices of President and Vice President of India?', 'The Election Commission of India (established 25 Jan 1950, National Voters'' Day) oversees federal and state electoral processes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab0136f1-cf87-4ac4-b11c-4ba7601d3f27', 'Election Commission of India (ECI - Article 324)', true, '8d100a5a-1d24-4f98-bc2b-d3a7e3c452cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dd14452-88e0-47ee-83f1-2cac0efd2686', 'UPSC', false, '8d100a5a-1d24-4f98-bc2b-d3a7e3c452cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba939eeb-ef52-4486-9e7d-4c6d4307038c', 'NITI Aayog', false, '8d100a5a-1d24-4f98-bc2b-d3a7e3c452cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9d37d0e-0fd2-4cdb-9b4c-0481a6376945', 'Law Commission', false, '8d100a5a-1d24-4f98-bc2b-d3a7e3c452cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a2e9dbe-fa08-4de7-9888-976a535df018', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What are the ''Directive Principles of State Policy'' (DPSP) contained in Part IV (Articles 36–51) of the Indian Constitution, borrowed from the Irish Constitution?', 'DPSPs are socio-economic governance charters guiding state legislation towards establishing an equitable welfare society.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd6b8713-3a05-477a-ad80-98c11615e3cc', 'Non-justiciable constitutional guidelines and moral directives for the government to establish a Welfare State and achieve social-economic democracy', true, '0a2e9dbe-fa08-4de7-9888-976a535df018');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12fd8f1f-f66f-47e7-afa9-702587028090', 'Rules for arresting criminals', false, '0a2e9dbe-fa08-4de7-9888-976a535df018');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50753b40-6751-4e04-a207-277af959ca7f', 'Laws on international trade', false, '0a2e9dbe-fa08-4de7-9888-976a535df018');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6762f27d-220e-4a1e-8ab3-d45af0a108c5', 'Military commands', false, '0a2e9dbe-fa08-4de7-9888-976a535df018');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d05db3a-5ec9-4182-9847-505d7bbd5898', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'Which constitutional amendment in 1976 (known as the ''Mini-Constitution'') added the words ''SOCIALIST'', ''SECULAR'', and ''INTEGRITY'' to the Preamble, and inserted Fundamental Duties (Article 51A)?', 'The 42nd Amendment Act (1976) introduced secular-socialist preambular values and Part IV-A (Fundamental Duties) upon Swaran Singh Committee advice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6709d47-c09f-49e6-ad55-b0338a7599b4', 'The 42nd Constitutional Amendment Act, 1976', true, '4d05db3a-5ec9-4182-9847-505d7bbd5898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c0adcee-7c3c-4691-8cb3-3c29cd6abbf8', 'The 44th Amendment', false, '4d05db3a-5ec9-4182-9847-505d7bbd5898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3d646f0-5e71-4487-aa8a-75ab200bb355', 'The 86th Amendment', false, '4d05db3a-5ec9-4182-9847-505d7bbd5898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d63602bb-083e-4a36-b5a1-7e64cfe29194', 'The 73rd Amendment', false, '4d05db3a-5ec9-4182-9847-505d7bbd5898');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('004315bb-1a5d-428c-b1b7-f7685f3212df', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'Which Fundamental Right was inserted under Article 21A by the 86th Constitutional Amendment Act in 2002, making free and compulsory education for all children aged 6 to 14 years a fundamental right?', 'Article 21A guarantees free, compulsory elementary education for children aged 6–14 as an enforceable fundamental right.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5f2e0f9-32e2-4ba3-9f65-8f23906682fb', 'Right to Education (RTE)', true, '004315bb-1a5d-428c-b1b7-f7685f3212df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54277f1e-9320-4022-a804-cfc6213e50db', 'Right to Health', false, '004315bb-1a5d-428c-b1b7-f7685f3212df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b88d7fe-5003-493a-95fa-5250742ad38b', 'Right to Work', false, '004315bb-1a5d-428c-b1b7-f7685f3212df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dba6adc-7b55-4596-beba-8d5936b38995', 'Right to Clean Air', false, '004315bb-1a5d-428c-b1b7-f7685f3212df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c561acc-952f-4ee7-93ac-adf0aabdd721', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'Who is the ex-officio Chairman of the Rajya Sabha (Upper House of Parliament)?', 'Under Article 64, the Vice President of India is the ex-officio Chairman of the Rajya Sabha.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('471da5f3-b329-4cc7-a1a7-58b05a0cc4d1', 'The Vice President of India', true, '2c561acc-952f-4ee7-93ac-adf0aabdd721');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcb8413c-47d9-4d21-963e-9d102089572e', 'The Prime Minister', false, '2c561acc-952f-4ee7-93ac-adf0aabdd721');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1686118-3ea8-4aa8-b0e9-fe1fe42e1b42', 'The Chief Justice of India', false, '2c561acc-952f-4ee7-93ac-adf0aabdd721');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('333398ff-b8df-49cb-ac84-3ad4d4276dc8', 'The Lok Sabha Speaker', false, '2c561acc-952f-4ee7-93ac-adf0aabdd721');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0280704f-b36b-4317-b744-827d7f7aab31', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What are the three lists of legislative subjects in the Seventh Schedule dividing powers between the Central Union and State Governments?', 'The Seventh Schedule demarcates legislative competence: Union List (exclusive Centre), State List (exclusive States), Concurrent List (shared jurisdiction).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8c6cc0c-5eb7-43aa-a812-0ac5514d1396', '1. Union List (Defence, Foreign Affairs, Railways) ; 2. State List (Police, Agriculture, Health) ; 3. Concurrent List (Education, Forests, Marriage)', true, '0280704f-b36b-4317-b744-827d7f7aab31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('425070d3-c200-4da5-a11c-cfc07c70de10', 'Civil List, Military List, Tax List', false, '0280704f-b36b-4317-b744-827d7f7aab31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('455e91c6-1f32-4543-8d88-23d33bdcf1b2', 'Northern List, Southern List, Eastern List', false, '0280704f-b36b-4317-b744-827d7f7aab31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d6a6150-37cd-4abc-b774-9d5444c28ace', 'Urban List, Rural List, Forest List', false, '0280704f-b36b-4317-b744-827d7f7aab31');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03fbb084-7b2c-43c5-b8e3-31a677f18d40', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What historic constitutional amendments (73rd and 74th Amendments in 1992) institutionalized the third tier of local self-government in India?', 'The 73rd and 74th Amendments established three-tier Panchayati Raj (Gram, Block, Zilla) and Urban Local Bodies with mandatory reservations for women.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59263f82-e683-4a6d-a3de-ba8b9fb14189', 'Panchayati Raj Institutions (Rural local governance) and Urban Municipalities / Municipal Corporations', true, '03fbb084-7b2c-43c5-b8e3-31a677f18d40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af1dd03a-7f08-4b59-b58b-2be44f6ec72e', 'Creation of new High Courts', false, '03fbb084-7b2c-43c5-b8e3-31a677f18d40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bedf4200-5a7c-4100-828e-f148e32318c0', 'GST Council formation', false, '03fbb084-7b2c-43c5-b8e3-31a677f18d40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58c081c1-58f2-456e-b48a-d74c8fa5dcb1', 'Abolition of Privy Purses', false, '03fbb084-7b2c-43c5-b8e3-31a677f18d40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f38cb03d-152d-417c-96f1-1992d56c1ef0', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the ''Comptroller and Auditor General of India'' (CAG - Article 148), often described as the ''Guardian of the Public Purse''?', 'The CAG performs independent audit surveillance over the Consolidated Funds of Union and States, reporting to Parliament via PAC.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bd96e95-e489-4243-bbc5-b06360663e92', 'An independent constitutional authority that audits all receipts and expenditure of the Government of India and State Governments to ensure financial accountability', true, 'f38cb03d-152d-417c-96f1-1992d56c1ef0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec064d7c-7aac-4df3-afd4-5a38b5254e6e', 'The minister who collects income tax', false, 'f38cb03d-152d-417c-96f1-1992d56c1ef0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef5add6f-0d6e-4402-a8d4-60a44d5a9f63', 'The head of commercial banks', false, 'f38cb03d-152d-417c-96f1-1992d56c1ef0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65fb1b68-bbbb-49a1-91e0-3bdeb5b8949e', 'The manager of the stock exchange', false, 'f38cb03d-152d-417c-96f1-1992d56c1ef0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26d1d3e9-cd05-41ab-8326-6fe8c3970276', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the landmark ''Basic Structure Doctrine'' formulated by the Supreme Court of India in the famous 1973 Kesavananda Bharati case?', 'The 13-judge Kesavananda Bharati bench established that constitutional amendment powers cannot dismantle the foundational basic structure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bcad193-cfbf-41ff-9f8b-22fbeeed88ec', 'Parliament has the power to amend the Constitution under Article 368, but CANNOT alter, destroy, or abrogate the ''Basic Structure'' (Democracy, Secularism, Judicial Review, Rule of Law)', true, '26d1d3e9-cd05-41ab-8326-6fe8c3970276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fb39595-96d1-4d96-be92-182a9f77db40', 'All laws must be written in Sanskrit', false, '26d1d3e9-cd05-41ab-8326-6fe8c3970276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb1e8309-6bd3-4d38-8719-bce071740c03', 'The Prime Minister cannot travel abroad', false, '26d1d3e9-cd05-41ab-8326-6fe8c3970276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34d649e4-8074-4c75-81d3-20cd6e1860e8', 'Parliament cannot pass any budget', false, '26d1d3e9-cd05-41ab-8326-6fe8c3970276');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c09243a3-c221-4f72-b6a2-be2a3efbc887', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What does ''Sovereign'' mean in the Preamble of the Indian Constitution?', '''Sovereign'' signifies absolute national independence and supreme jurisdictional authority free from external hegemony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f4de893-43a5-4bb4-8ef0-d30a9c934eb3', 'India is completely independent, supreme, and free from any foreign control or external dictation in making internal and external decisions', true, 'c09243a3-c221-4f72-b6a2-be2a3efbc887');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('488a1468-cc67-4ed4-aad5-a2816a3097c9', 'India is ruled by a king', false, 'c09243a3-c221-4f72-b6a2-be2a3efbc887');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6511994-2f16-4a22-a7c4-cc3db040c0d6', 'India has no borders', false, 'c09243a3-c221-4f72-b6a2-be2a3efbc887');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8b62daf-6093-478b-88bc-c241ed3b10cd', 'India is an island', false, 'c09243a3-c221-4f72-b6a2-be2a3efbc887');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c921bf54-f500-4234-97c1-ee13adc6782a', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What does ''Secular'' mean in the context of the Indian democratic model (Sarva Dharma Sambhava)?', 'Indian secularism maintains principled distance and equal patronage towards all faiths, protecting religious freedoms under Articles 25–28.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccf76dc0-ab41-4355-9d91-cbb589f48fa1', 'The State has no official state religion and accords equal respect, protection, and freedom to all religions without discriminating against any citizen', true, 'c921bf54-f500-4234-97c1-ee13adc6782a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df560817-17c2-4b0b-a88a-8969c0a83d55', 'The State bans all religions', false, 'c921bf54-f500-4234-97c1-ee13adc6782a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b55b35a8-1941-444a-a814-b62ea9fdaa76', 'Only one religion is allowed in schools', false, 'c921bf54-f500-4234-97c1-ee13adc6782a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb462da-9914-4ecc-a8f8-fd7dba9aadb8', 'Citizens are not allowed to pray', false, 'c921bf54-f500-4234-97c1-ee13adc6782a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b331292-3b13-4d70-935e-4d5afc3647f7', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'How is the President of India elected?', 'Article 54: The President is elected through proportional representation with single transferable vote by elected MPs and MLAs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5115c9b3-ca4f-4fc0-88fa-47780eff7e92', 'Indirectly by an Electoral College consisting of elected members of both Houses of Parliament (Lok Sabha & Rajya Sabha) and elected MLAs of all State Legislative Assemblies', true, '4b331292-3b13-4d70-935e-4d5afc3647f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20d12c0d-ba6e-48a6-ae8b-32456f69ee23', 'Direct voting by all citizens', false, '4b331292-3b13-4d70-935e-4d5afc3647f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af238c28-abbb-4939-8d80-f54e0ea14f88', 'Nominated by the Supreme Court', false, '4b331292-3b13-4d70-935e-4d5afc3647f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23923411-8cae-4b67-a56e-8a6de190326e', 'Selected by previous President', false, '4b331292-3b13-4d70-935e-4d5afc3647f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11de8be7-b322-430d-a4b8-18d3b84e4935', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the maximum strength of members in the Lok Sabha permitted by the Constitution?', 'Article 81: Lok Sabha maximum ceiling is 550 (up to 530 from States, up to 20 from UTs; Anglo-Indian nomination was discontinued by 104th Amendment).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19949d54-27fd-4314-ad19-6c28a1b42b49', '550 members (representing States and Union Territories)', true, '11de8be7-b322-430d-a4b8-18d3b84e4935');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0793b31-f4fa-4046-8458-656b39e5fcae', '250 members', false, '11de8be7-b322-430d-a4b8-18d3b84e4935');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25505d96-b300-480c-a062-9660f4d324b3', '100 members', false, '11de8be7-b322-430d-a4b8-18d3b84e4935');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dab38a2-b5c3-411a-afc3-03f00a2bdf81', '700 members', false, '11de8be7-b322-430d-a4b8-18d3b84e4935');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('938c273f-ac70-405b-a9f7-75dc275c3ef0', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the maximum strength of members in the Rajya Sabha?', 'Article 80: Rajya Sabha has up to 250 members: 238 state/UT representatives and 12 presidential nominees with specialized eminence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e785f5b6-04f2-4c99-ba4c-04daf82f965f', '250 members (238 elected from States/UTs + 12 nominated by the President for literature, science, art, and social service)', true, '938c273f-ac70-405b-a9f7-75dc275c3ef0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6f2d957-f8ce-4113-b322-93903e14c8e4', '550 members', false, '938c273f-ac70-405b-a9f7-75dc275c3ef0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('061d4da8-d29f-4e7b-9506-6f6a11c43a45', '300 members', false, '938c273f-ac70-405b-a9f7-75dc275c3ef0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('991a577a-b2e9-4221-9c4f-9aeccabd6ece', '150 members', false, '938c273f-ac70-405b-a9f7-75dc275c3ef0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95db393c-4f3f-4418-aabe-dc5ceeaed07a', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is a ''Money Bill'' in the Indian Parliament, and which House has exclusive, overriding authority over it?', 'Money bills originate exclusively in the Lok Sabha; the Rajya Sabha has only 14 days to suggest non-binding recommendations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b99bc2e-951e-489a-b335-2fe646116c7b', 'A Bill dealing with taxation and government expenditure (Article 110) ; it can ONLY be introduced in the LOK SABHA with the prior recommendation of the President', true, '95db393c-4f3f-4418-aabe-dc5ceeaed07a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e6bbedc-46fa-417a-a3ac-54761171221e', 'A bill that can only be introduced in Rajya Sabha', false, '95db393c-4f3f-4418-aabe-dc5ceeaed07a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a74db62-b5c4-42a1-b604-b283cd433ef1', 'A bill passed by the Supreme Court', false, '95db393c-4f3f-4418-aabe-dc5ceeaed07a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('017d627f-ca2a-4c0f-bb53-5172d11ef77f', 'A bill passed by municipal ward councils', false, '95db393c-4f3f-4418-aabe-dc5ceeaed07a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2570b8fc-a294-4706-a1ea-51f64c7ab556', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is ''Judicial Review'' exercised by the Supreme Court and High Courts of India?', 'Articles 13, 32, and 226 empower the higher judiciary to invalidate ultra vires statutes violating constitutional mandates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9c00c83-de83-438b-8d88-add6b5897659', 'The constitutional power to examine the constitutional validity of legislative enactments and executive orders, and declare them NULL and VOID if they violate Fundamental Rights', true, '2570b8fc-a294-4706-a1ea-51f64c7ab556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ad38838-24ef-493d-88d6-0b34bf9f5a6f', 'The power of judges to change their salaries', false, '2570b8fc-a294-4706-a1ea-51f64c7ab556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ed36ea5-e6f0-4876-8b98-9184a982366f', 'The right of the police to make laws', false, '2570b8fc-a294-4706-a1ea-51f64c7ab556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53560ee1-3bef-45ed-b983-95c8106e5555', 'The review of school exam papers', false, '2570b8fc-a294-4706-a1ea-51f64c7ab556');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46bb811b-ef7a-44de-9e81-450fd2950a2b', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the ''Right to Information'' (RTI) Act passed by the Indian Parliament in 2005?', 'The RTI Act (2005) enforces participatory transparency, enabling citizens to inspect government files and demand institutional accountability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66be1b09-7348-4c5a-9242-b167d9dc18e3', 'A landmark transparency law empowering citizens to request and receive certified information from public authorities, curbing corruption and promoting accountability', true, '46bb811b-ef7a-44de-9e81-450fd2950a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5daa4846-8f59-4a0a-a595-a630f9d3f9b0', 'A law that bans newspapers', false, '46bb811b-ef7a-44de-9e81-450fd2950a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1422e12e-ad9b-4371-9759-cf2843a06b40', 'A secret government code', false, '46bb811b-ef7a-44de-9e81-450fd2950a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b6f34be-612a-41c4-a198-8c8fc7682fd5', 'A rule on television commercials', false, '46bb811b-ef7a-44de-9e81-450fd2950a2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34319386-78da-4a4b-a402-1038b1234e0a', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4bdbe85-7b0c-43dd-9030-20d85e11caa1', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '34319386-78da-4a4b-a402-1038b1234e0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eddf6edb-eef8-435a-92a5-3cc3f29e355c', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '34319386-78da-4a4b-a402-1038b1234e0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ac40836-bf73-4264-9ce4-00755b9fa79f', '(A) is true, but (R) is false.', false, '34319386-78da-4a4b-a402-1038b1234e0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('422158fa-44be-45e1-ae60-5eb39c0fc340', '(A) is false, but (R) is true.', false, '34319386-78da-4a4b-a402-1038b1234e0a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fba910a6-28c7-49dd-be96-83e23b236079', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Spot the IMPOSTER in the following constitutional bodies and their corresponding Articles in the Indian Constitution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22c658e1-feab-42e1-b8a0-3b2b88a51dc8', 'Body 1', false, 'fba910a6-28c7-49dd-be96-83e23b236079');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b760ed-b69c-463f-bbe8-a5564c7fffd0', 'Body 2', false, 'fba910a6-28c7-49dd-be96-83e23b236079');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94cf922d-0054-4ee8-96b4-2c75297a6c98', 'Body 3', false, 'fba910a6-28c7-49dd-be96-83e23b236079');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a13e188-7965-42d3-ad0f-9775f7dee214', 'Body 4 (The Finance Commission is constituted under ARTICLE 280, not Article 500 ; the Constitution has only 395 original articles)', true, 'fba910a6-28c7-49dd-be96-83e23b236079');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f645fcc-b870-4488-9a2f-684d0691de96', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Match Column I (Constitutional Writs under Articles 32 and 226) with Column II (Latin Meanings and Applications):
(a) Habeas Corpus -> (i) ''To have the body'' (releases a person unlawfully detained by state/police)
(b) Mandamus      -> (ii) ''We Command'' (orders a public official to perform their mandatory statutory duty)
(c) Prohibition   -> (iii) Orders a lower court/tribunal to cease proceedings exceeding its jurisdiction
(d) Quo-Warranto  -> (iv) ''By what warrant'' (inquires into the legality of a person holding a public office)', 'Habeas Corpus = personal liberty; Mandamus = public duty command; Prohibition = jurisdiction restraint; Quo-Warranto = title to public office.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('405ca3d1-e7ec-4e44-bdfd-3c3ce5cc3691', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '6f645fcc-b870-4488-9a2f-684d0691de96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a65f2ba2-a605-4a21-94e5-84308ff20c48', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '6f645fcc-b870-4488-9a2f-684d0691de96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99bc98e5-73b6-41b6-a01d-9635966ae59b', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '6f645fcc-b870-4488-9a2f-684d0691de96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffd8e826-8efe-4773-9dd3-80da44e6a011', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '6f645fcc-b870-4488-9a2f-684d0691de96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8a9d3f4-0ef9-43d9-8b72-918a0873f38d', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Read the statements regarding the Emergency Provisions in the Indian Constitution (Part XVIII):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21a7d9a4-779d-4c76-a673-3d568725da49', 'Statements 1 and 2 only', true, 'd8a9d3f4-0ef9-43d9-8b72-918a0873f38d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dde3e47-94a2-4835-bc51-f820cd173df1', 'Statements 2 and 3 only', false, 'd8a9d3f4-0ef9-43d9-8b72-918a0873f38d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81723a5e-c2f1-4fea-899c-252cbdaf7b25', 'Statements 1 and 3 only', false, 'd8a9d3f4-0ef9-43d9-8b72-918a0873f38d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b19aa08-bcd1-409a-9931-1bcf13469b2d', 'All Statements 1, 2, and 3', false, 'd8a9d3f4-0ef9-43d9-8b72-918a0873f38d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('afa5db92-29f9-4d88-963d-f783a66a1645', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What constitutes the ''Doctrine of Separation of Powers'' embedded with ''Checks and Balances'' in Indian parliamentary democracy?', 'Indian tripartite governance balances functional separation with mutual accountability (judicial review of laws, legislative oversight of ministers).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b576243-eccc-4486-ba41-03e41e4d60bf', 'The Legislature makes laws, the Executive implements laws, and the Judiciary interprets laws and invalidates unconstitutional actions, ensuring no branch exercises absolute tyranny', true, 'afa5db92-29f9-4d88-963d-f783a66a1645');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('606a90fe-eb15-4d8a-bec9-e7f273dd4ae3', 'The army controls all political leaders', false, 'afa5db92-29f9-4d88-963d-f783a66a1645');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22fdf88e-b8cf-4b78-b564-63aa072d0708', 'The President writes all court judgments', false, 'afa5db92-29f9-4d88-963d-f783a66a1645');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7e058c4-16f3-4991-9197-b92589eb9acf', 'Ministers serve as judges in court', false, 'afa5db92-29f9-4d88-963d-f783a66a1645');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40591725-5c8b-469d-95ff-eb15fbe37e94', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What is the procedure for the IMPEACHMENT of the President of India under Article 61 of the Constitution?', 'Article 61 prescribes stringent two-thirds total membership super-majority in both Houses for presidential impeachment on constitutional violations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('917db287-bf39-41b0-854e-1473deeddcc8', 'A quasi-judicial resolution passed by a special majority of NOT LESS THAN TWO-THIRDS of the total membership of both Houses of Parliament on grounds of ''Violation of the Constitution''', true, '40591725-5c8b-469d-95ff-eb15fbe37e94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a0dd459-6bc2-4af1-b46d-b90c2754979f', 'A simple majority vote in Lok Sabha only', false, '40591725-5c8b-469d-95ff-eb15fbe37e94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b4b55ea-4781-4bff-8d1c-66da763216e5', 'An order passed by the Chief Justice of India', false, '40591725-5c8b-469d-95ff-eb15fbe37e94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d199b058-13cd-4060-9a72-f62e3be5a6bd', 'A public referendum', false, '40591725-5c8b-469d-95ff-eb15fbe37e94');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2bda7be-9801-475b-bba4-7f931129616c', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Consider four features of the Indian Constitution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf3482fd-91e3-442f-8e34-5664572c440c', 'A masterful comparative constitutional achievement that adapted the world''s finest democratic practices to India''s unique civilizational pluralism', true, 'd2bda7be-9801-475b-bba4-7f931129616c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40bb6039-e605-46ee-8e31-df3c645b374c', 'A careless copy of other countries'' rules', false, 'd2bda7be-9801-475b-bba4-7f931129616c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37da957f-bf4a-4629-9e75-e3d2daa01608', 'An accidental document created in a few days', false, 'd2bda7be-9801-475b-bba4-7f931129616c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0c818d6-861c-40b3-b27a-7554b6a47606', 'A document that applies only to cities', false, 'd2bda7be-9801-475b-bba4-7f931129616c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e75a64ea-c0d9-4e9f-9884-c8e053bb7c0d', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What is the significance of the 101st Constitutional Amendment Act (2016) in Indian cooperative fiscal federalism?', 'The 101st Amendment revolutionized indirect taxation via ''One Nation, One Tax'', creating the federal consensus GST Council.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4716083-7b0c-4af5-88f2-100f1f855cee', 'The introduction of the unified Goods and Services Tax (GST) and the constitutional establishment of the joint Centre-State GST Council (Article 279A)', true, 'e75a64ea-c0d9-4e9f-9884-c8e053bb7c0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbc8dd40-70c2-4411-9b89-ed5c17dc1de1', 'The nationalization of private banks', false, 'e75a64ea-c0d9-4e9f-9884-c8e053bb7c0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9254088d-b49f-4a42-8bef-39edf5ba2c22', 'The abolition of states', false, 'e75a64ea-c0d9-4e9f-9884-c8e053bb7c0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a351eac-b8de-40bd-af33-660225d48353', 'The introduction of a new national anthem', false, 'e75a64ea-c0d9-4e9f-9884-c8e053bb7c0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6d94622-e9a7-4ace-b46a-ced6398a28ee', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What is the constitutional role of the ''Attorney General for India'' (Article 76)?', 'The Attorney General is the principal legal advisor to the Union and represents the Union Government in supreme appellate litigation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3dd1298-001c-413b-8430-fa1d23570553', 'The highest law officer of the Government of India, appointed by the President, who gives legal counsel to the Union government and has the right of audience in all courts in India', true, 'c6d94622-e9a7-4ace-b46a-ced6398a28ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55ee5892-d549-4213-b76a-013c5ecfbb0e', 'The chief of police', false, 'c6d94622-e9a7-4ace-b46a-ced6398a28ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98ae1f9c-a6e8-403a-b714-6b3d4d593abc', 'The commander of the navy', false, 'c6d94622-e9a7-4ace-b46a-ced6398a28ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f90ffdf8-531b-4f03-95ed-43fa8c3aebef', 'The governor of the Reserve Bank', false, 'c6d94622-e9a7-4ace-b46a-ced6398a28ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36b30e70-6b94-4d7a-b6bb-31d9a2b05a63', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Why is Article 21 (Protection of Life and Personal Liberty) regarded as the expansive cornerstone of human rights jurisprudence in India?', 'The Supreme Court expanded Article 21 to enshrine substantive due process, privacy, environmental rights, and human dignity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c16171dc-ddf1-456d-b9a2-ea8a7e4d2757', 'Through progressive judicial interpretations (Maneka Gandhi, Puttaswamy cases), it now encompasses the Right to Privacy, Right to Clean Environment, Right to Livelihood, and Right to Dignity', true, '36b30e70-6b94-4d7a-b6bb-31d9a2b05a63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('541c9ff0-4722-491e-a6c4-13da78cb2c8c', 'It allows citizens to break traffic laws', false, '36b30e70-6b94-4d7a-b6bb-31d9a2b05a63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4edf27ad-5f38-47bc-9f90-aa3fc48fbcc0', 'It guarantees free movie tickets', false, '36b30e70-6b94-4d7a-b6bb-31d9a2b05a63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d34a29a5-7549-4e30-8bd3-e4b4db9254c7', 'It applies only to foreign ambassadors', false, '36b30e70-6b94-4d7a-b6bb-31d9a2b05a63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('064b1d99-6b93-47ea-b17a-2e0cec230a89', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What was the landmark 106th Constitutional Amendment Act (Nari Shakti Vandan Adhiniyam) passed by Parliament in 2023?', 'The 106th Amendment mandates 33% constitutional reservation for women in legislative bodies to enhance democratic gender parity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b7afea8-b6d6-4a49-acb1-28b891852f97', 'Reserving 33% (one-third) of seats for WOMEN in the Lok Sabha, State Legislative Assemblies, and the Delhi Legislative Assembly', true, '064b1d99-6b93-47ea-b17a-2e0cec230a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3278262-2c12-434a-9fc7-8cc6cf040225', 'Making women eligible for driving licenses', false, '064b1d99-6b93-47ea-b17a-2e0cec230a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb4902a4-83b4-4c1a-80e0-6eef1f50e419', 'Abolishing all taxes for women', false, '064b1d99-6b93-47ea-b17a-2e0cec230a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ad6d06f-c7a8-4e8a-b592-374c220382d0', 'Granting free electricity to women', false, '064b1d99-6b93-47ea-b17a-2e0cec230a89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9a7ee6d-37cb-4cb5-8f8b-43de14e6fdda', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What core vision of constitutional patriotism and civic responsibility is established in Chapter 7 of General Knowledge?', 'Chapter 7 synthesizes constitutional democracy, rule of law, institutional checks and balances, and civic empowerment in the Republic of India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54e6d061-a7bd-4fdd-b624-129e72656a35', 'The Constitution is a living, sacred covenant of sovereign democratic self-governance, requiring vigilant citizens who cherish liberty, protect equality, defend institutional integrity, and fulfill their fundamental duties', true, 'f9a7ee6d-37cb-4cb5-8f8b-43de14e6fdda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffd633db-66ee-41cd-ba19-9b6b8469d514', 'That the Constitution is an unchangeable ancient stone that citizens should ignore', false, 'f9a7ee6d-37cb-4cb5-8f8b-43de14e6fdda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d86849d-df34-464a-972d-4f802b689ab2', 'That democracy works without citizens taking part in elections', false, 'f9a7ee6d-37cb-4cb5-8f8b-43de14e6fdda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f49e1f3b-0a6d-4cb2-b82d-d689be7fa681', 'That laws apply only to the poor', false, 'f9a7ee6d-37cb-4cb5-8f8b-43de14e6fdda');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c173a3ed-563d-46c1-b1d9-75e74bb4274a', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'What distinct social organization characterized tribal societies compared to the caste-based (Varna) societies of medieval India?', 'Tribal communities organized social life around kinship bonds, communal land ownership, and egalitarian clan structures without Brahmanical varna hierarchies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8995962-be28-481d-b152-3334cadbf5a0', 'Tribal societies did NOT follow rigid social rules and caste divisions prescribed by Brahmans; they were organized into egalitarian kinship / clan groups with shared natural resources', true, 'c173a3ed-563d-46c1-b1d9-75e74bb4274a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32029b03-d94c-4816-8914-4058c7c0c68c', 'They had hundreds of rigid sub-castes', false, 'c173a3ed-563d-46c1-b1d9-75e74bb4274a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('726eb78f-2f0b-438e-a46d-284689124999', 'They lived only in marble palaces', false, 'c173a3ed-563d-46c1-b1d9-75e74bb4274a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce277746-6d79-4497-95f9-c34c360d38de', 'They were ruled by foreign emperors', false, 'c173a3ed-563d-46c1-b1d9-75e74bb4274a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60638a42-da90-421e-bdb1-e72f16ad5f97', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which vast forested region of central India (comprising modern Madhya Pradesh, Chhattisgarh, and Maharashtra) was the homeland of the GONDS?', 'Gondwana was the historical central Indian forest region where Gond kingdoms practiced shifting cultivation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eb144cc-eb96-4a5e-a2ff-73fa29ea7b27', 'Gondwana (''Country inhabited by Gonds'')', true, '60638a42-da90-421e-bdb1-e72f16ad5f97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('507364d4-2551-45bb-ae2d-f1f3199b2a0f', 'Brahmaputra Valley', false, '60638a42-da90-421e-bdb1-e72f16ad5f97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ca3617d-c3ea-4719-8125-d6ec8313404c', 'Thar Desert', false, '60638a42-da90-421e-bdb1-e72f16ad5f97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa7c90bf-cfee-4f48-9b58-38b7df094fb8', 'Konkan Coast', false, '60638a42-da90-421e-bdb1-e72f16ad5f97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41a53f32-3e48-424f-b710-6a8aa21c522a', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'What rich Gond kingdom mentioned in the Akbar Nama contained 70,000 villages and grew wealthy by exporting wild elephants to other kingdoms?', 'Garha Katanga was a prosperous Gond kingdom ruling 70,000 villages, enriched through the capture and export of wild elephants.', NOW()) ON CONFLICT DO NOTHING;
