INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc9d3dde-8381-4a5a-9251-1a89b202a017', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which brave, heroic Rajput princess married the Gond King Dalpat and ruled Garha Katanga on behalf of her young son Bir Narain, dying in battle against the Mughal general Asaf Khan in 1565?', 'Rani Durgavati of Garha Katanga (daughter of Chandel king Salbahan) fought valiantly against Asaf Khan''s Mughal invasion until her martyrdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e073fc2c-c38c-4245-9d1b-38486dd113c2', 'Rani Durgavati', true, 'dc9d3dde-8381-4a5a-9251-1a89b202a017');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abe4ed65-a293-4181-89ef-18abe11b508e', 'Rani Lakshmibai', false, 'dc9d3dde-8381-4a5a-9251-1a89b202a017');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('777de479-9382-4d5d-b45e-9fd24ddbade1', 'Rani Padmini', false, 'dc9d3dde-8381-4a5a-9251-1a89b202a017');
