INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2a2a82e-a175-4ac2-89fe-8f251c80a9f7', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which powerful tribal community migrated from present-day Myanmar into the Brahmaputra River valley (Assam) in the 13th century, establishing a flourishing independent state?', 'The Tai-Ahom people under Sukapha settled the upper Brahmaputra valley in 1228 CE, creating the mighty Ahom kingdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bbab018-f93d-409d-8700-24b93c44e07e', 'The Ahoms (led by Chaolung Sukapha)', true, 'a2a2a82e-a175-4ac2-89fe-8f251c80a9f7');
