INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32c12e6f-e469-4889-b9c9-149f3740fadb', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'What were historical historical chronicles and official state records written in the Ahom language and later in Assamese called?', 'Buranjis are the invaluable historical chronicles written by Ahom court scribes recording political and diplomatic history.', NOW()) ON CONFLICT DO NOTHING;
