INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20769e4b-0946-4736-a087-a9817c880649', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'In the Ahom state, what were the adult male villagers who were legally obliged to render compulsory rotational labor for public works called?', 'Under the Ahom Paik system, each village supplied rotational corvée laborers (Paiks) for constructing dykes, canals, and military service.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db376983-3814-4696-8290-839ee616c776', 'Paiks', true, '20769e4b-0946-4736-a087-a9817c880649');
