INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('721d7f97-5911-4969-83bc-7b69fd96a613', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'In Ahom society, what were the clans or collective administrative units that controlled several villages called?', 'A Khel was a clan-based corporate unit commanding specific Paiks and distributing village land.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b73db7a-3e76-47f1-b142-251e938373e5', 'Khels', true, '721d7f97-5911-4969-83bc-7b69fd96a613');
