INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e95bf9e1-0464-430b-8264-f2b042a48a7e', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which major warrior tribes dominated the Punjab region during the 13th and 14th centuries (whose chief Kamal Khan Gakkhar was made a noble by Akbar)?', 'The Khokhars and Gakkhars were influential martial tribes of Punjab; Emperor Akbar appointed Gakkhar chief Kamal Khan as a high Mansabdar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0623bc27-2578-46fb-9d5b-b7c3573f69b3', 'Khokhars and Gakkhars', true, 'e95bf9e1-0464-430b-8264-f2b042a48a7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a90001-d6f3-4227-9a4c-8b6b4b47528a', 'Bhils and Kolis', false, 'e95bf9e1-0464-430b-8264-f2b042a48a7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2190be1-cddc-4cb7-8fab-a74cdc52b5e9', 'Ahoms and Nagas', false, 'e95bf9e1-0464-430b-8264-f2b042a48a7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3e1bd82-9ca8-47cb-a58c-beee4209207d', 'Gonds and Santhals', false, 'e95bf9e1-0464-430b-8264-f2b042a48a7e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11c71593-7678-40df-87f4-49372ed5005d', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which large tribal group inhabited the forested hilly regions of the Western Ghats and Central India across Rajasthan, Gujarat, and Maharashtra?', 'The Bhils spread across the Western Ghats and Vindhyas, transitioning between hunter-gathering, shifting farming, and archery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7ecca05-4c60-45bc-b5c4-0ca318e3eb44', 'The Bhils (and Kolis)', true, '11c71593-7678-40df-87f4-49372ed5005d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9478d958-aae2-4d3e-9645-cfcfcfcdd4a1', 'The Ahoms', false, '11c71593-7678-40df-87f4-49372ed5005d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61b61d93-08db-44b9-8d5b-22cdeaeab4c8', 'The Gakkhars', false, '11c71593-7678-40df-87f4-49372ed5005d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d46606ca-309d-4a54-9183-deb5c263e59b', 'The Cheros', false, '11c71593-7678-40df-87f4-49372ed5005d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b75089d-7520-41ff-9651-fbbefb97015e', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'What agricultural method involving cutting and burning trees and bushes in forest plots to plant crops in the fertile ash for a few years was practiced by Gonds?', 'Shifting cultivation (slash-and-burn) was the traditional agrarian system of forest-dwelling tribal communities like the Gonds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d26d7a0-698c-4d9b-b812-a794f9d30faf', 'Shifting Cultivation (Jhum / Podu)', true, '9b75089d-7520-41ff-9651-fbbefb97015e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87d47d68-79f8-489d-a238-c22ceb827804', 'Terrace Farming only', false, '9b75089d-7520-41ff-9651-fbbefb97015e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('133984c2-6092-4d9b-b31c-a97299206d1b', 'Hydroponics', false, '9b75089d-7520-41ff-9651-fbbefb97015e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c516e2e7-83c7-468b-ac5a-29b680bf36eb', 'Plantation Farming', false, '9b75089d-7520-41ff-9651-fbbefb97015e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1677bee-3cc3-49f0-b47c-67ddc7bae593', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which pastoral shepherd tribe lived in the western Himalayas (Himachal Pradesh), migrating with sheep and goat herds according to seasons?', 'The Gaddis are transhumant pastoral shepherds of the western Himalayas migrating between alpine meadows and valley winters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0360248d-d2f7-4b67-b16d-557f92574cb9', 'Gaddis (and Gujjar Bakarwals)', true, 'c1677bee-3cc3-49f0-b47c-67ddc7bae593');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62a9f672-92c8-4268-8892-977fc1c8414a', 'Ahoms', false, 'c1677bee-3cc3-49f0-b47c-67ddc7bae593');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95749877-d80d-4b57-b33b-285883b4f9c4', 'Gonds', false, 'c1677bee-3cc3-49f0-b47c-67ddc7bae593');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644201e2-0510-4ea8-9964-0397baf4f9b2', 'Cheros', false, 'c1677bee-3cc3-49f0-b47c-67ddc7bae593');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b70463a-578e-4627-9eb9-34a382062abf', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What was the administrative division hierarchy of the centralized Gond kingdom of Garha Katanga?', 'Gond administrative structure: Garh (clan territory) → Chaurasi (84 villages) → Barhot (12 villages).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b1685b5-bf6e-4ff4-8b51-32fc548e75cb', 'Kingdom was divided into Garhs (controlled by Gond clans) ; each Garh was divided into Chaurasis (units of 84 villages) ; each Chaurasi was subdivided into Barhots (units of 12 villages)', true, '3b70463a-578e-4627-9eb9-34a382062abf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17b67df2-c899-4aaf-93f5-05bc023c0f02', 'Kingdom -> Suba -> Sarkar -> Pargana', false, '3b70463a-578e-4627-9eb9-34a382062abf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6de2252b-63e8-4596-90d8-c6ee6b8ccc7a', 'Kingdom was divided into 1,000 islands', false, '3b70463a-578e-4627-9eb9-34a382062abf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4eae9b2-7ea5-46e7-9e9f-96d85862aa2b', 'Kingdom had no divisions', false, '3b70463a-578e-4627-9eb9-34a382062abf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a65d4730-3d37-4d4b-b2e8-6f68fab14f0c', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Why did the Gond Raja of Garha Katanga, Aman Das, adopt the prestigious title of ''Sangram Shah''?', 'Gond chieftains Sanskritized their identity (Rajputization) by assuming Kshatriya titles (Sangram Shah) and forming Rajput matrimonial alliances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a57a1838-bd82-424c-aea1-e35a2dd300a0', 'To elevate his social and political status to that of a Kshatriya / Rajput ruler, seeking parity with established northern dynasties', true, 'a65d4730-3d37-4d4b-b2e8-6f68fab14f0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a4707be-4e3b-49f9-959a-04ec28a6659f', 'Because he won an Olympic medal', false, 'a65d4730-3d37-4d4b-b2e8-6f68fab14f0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0525dc4e-e559-49c7-be31-091975a5b12c', 'Because the British gave him the title', false, 'a65d4730-3d37-4d4b-b2e8-6f68fab14f0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fe05d5d-525c-4a6c-8adb-0afca8c88fa8', 'Because he moved to Europe', false, 'a65d4730-3d37-4d4b-b2e8-6f68fab14f0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddf8fb38-9447-4db4-925f-ccc8e6f6fea2', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'How did the introduction of advanced Gunpowder and Firearms in the 16th century transform the military strength of the Ahom kingdom?', 'The Ahoms developed advanced indigenous pyrotechnic ballistics, manufacturing high-grade gunpowder and cannons from the 1530s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8732f883-e058-4bb2-92a0-6959f66fb346', 'The Ahoms quickly mastered metallurgy to manufacture high-quality gunpowder and cast heavy bronze cannons as early as the 1530s, successfully repelling numerous invasions', true, 'ddf8fb38-9447-4db4-925f-ccc8e6f6fea2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('872930f0-f1c0-48e9-8335-7585f0908851', 'They bought weapons from China only', false, 'ddf8fb38-9447-4db4-925f-ccc8e6f6fea2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fe3d7a5-36dd-4a2b-af2a-6e8a1743611b', 'Gunpowder destroyed the Ahom kingdom immediately', false, 'ddf8fb38-9447-4db4-925f-ccc8e6f6fea2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae5b088e-1b82-40a7-a577-1e0691caf451', 'They banned all weapons', false, 'ddf8fb38-9447-4db4-925f-ccc8e6f6fea2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bfb1d3bd-caf9-416a-8dd9-ec4de6b37a38', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Under which Mughal general was an army sent in 1662 to invade the Ahom kingdom, capturing the capital Garhgaon after fierce Ahom resistance?', 'Mir Jumla captured Garhgaon in 1662, but protracted guerrilla warfare and monsoon pestilence forced a Mughal treaty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ecede69-aaaa-47e4-8581-648ba2d6cba7', 'Mir Jumla (Governor of Bengal under Aurangzeb)', true, 'bfb1d3bd-caf9-416a-8dd9-ec4de6b37a38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8396ebd-b8fa-43a7-96a1-cf49c03d39e2', 'Raja Man Singh', false, 'bfb1d3bd-caf9-416a-8dd9-ec4de6b37a38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3560ae2d-0359-44e5-b9d2-5010cefabebc', 'Bairam Khan', false, 'bfb1d3bd-caf9-416a-8dd9-ec4de6b37a38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deb75405-a378-4ce5-8416-4a4f392ea950', 'Shaista Khan', false, 'bfb1d3bd-caf9-416a-8dd9-ec4de6b37a38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32442bfe-3fee-4f21-9ae8-f510a9e4513d', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Under which great Ahom King (reigned 1696–1714) did Hinduism become the predominant religion, while Ahom kings retained their traditional Tai cultural customs?', 'King Rudra Singha patronized Brahmanical Vaishnavism and built the grand amphitheater Rang Ghar while preserving Tai ancestral rituals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c00de53-ca7d-4957-96ec-1db0dbc5ce6c', 'Rudra Singha (Sukhrungphaa)', true, '32442bfe-3fee-4f21-9ae8-f510a9e4513d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27ceeb0e-6197-4c97-b0a8-93322f0254d8', 'Sukapha', false, '32442bfe-3fee-4f21-9ae8-f510a9e4513d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4549fab3-6036-4fce-a9dd-8930da396876', 'Pratap Singha', false, '32442bfe-3fee-4f21-9ae8-f510a9e4513d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1588731-2196-43f6-acb3-0163ab373ac1', 'Gadadhar Singha', false, '32442bfe-3fee-4f21-9ae8-f510a9e4513d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6bc23cb-5177-41a7-ba99-bafe321b813a', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What was the ''Tanda'' of the Banjaras described in Emperor Jahangir''s memoirs (Tuzuk-i Jahangiri)?', 'Jahangir recorded that Banjaras transported grain on bullocks from villages into towns: ''A tanda consists of many families... moving up to 100,000 oxen''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('603e9af7-dc6d-410b-80b2-74915dd7bdea', 'A massive mobile nomadic convoy/caravan of Banjara trader families moving with thousands of pack-bullocks loaded with grain to sell in town markets and provision Mughal armies', true, 'e6bc23cb-5177-41a7-ba99-bafe321b813a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a28eb94-27de-45e2-bd88-df5c87f9eb04', 'A musical instrument', false, 'e6bc23cb-5177-41a7-ba99-bafe321b813a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1797d870-67ab-4e91-8dfb-ffa806e9e7b2', 'A stone fort in the forest', false, 'e6bc23cb-5177-41a7-ba99-bafe321b813a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('705810f2-72df-4ac7-b6bb-5700d893c71e', 'A type of food', false, 'e6bc23cb-5177-41a7-ba99-bafe321b813a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20c1edd8-8e8e-42ff-a7e8-a6aa567d50cc', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'How did economic exchange operate between Pastoral Nomads and settled agricultural villagers?', 'Symbiotic rural-pastoral barter: pastoralists bartered pastoral commodities (ghee, wool, pack-animals) for agrarian food grains and textiles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba052ac4-22c3-4527-8c9f-7eca4cddbb08', 'Pastoral nomads exchanged animal products (ghee, wool, hides, milk) with settled farmers in return for agricultural grain, cloth, metal utensils, and salt', true, '20c1edd8-8e8e-42ff-a7e8-a6aa567d50cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4965b4e7-3782-401f-b255-4218e68a4f8f', 'They had no contact with farmers', false, '20c1edd8-8e8e-42ff-a7e8-a6aa567d50cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03770869-b98a-43f9-b955-ceb411fe1dbd', 'Nomads gave gold and bought land', false, '20c1edd8-8e8e-42ff-a7e8-a6aa567d50cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10ee50ba-b407-4e4a-8783-60f90ac36392', 'Farmers became nomads every winter', false, '20c1edd8-8e8e-42ff-a7e8-a6aa567d50cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9cfb0b3-75c3-46e2-bc35-9569d9944536', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Which powerful tribal chieftaincy in Bihar and Jharkhand was attacked and defeated by Akbar''s general Raja Man Singh in 1591, yielding vast booty?', 'Raja Man Singh defeated the Chero chief in 1591, seizing wealth and elephants, though complete subjugation occurred under Aurangzeb.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7441edd4-69a1-442a-8aac-ec508db74819', 'The Cheros', true, 'c9cfb0b3-75c3-46e2-bc35-9569d9944536');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e6ee602-1b50-42f9-8690-7d93ce509948', 'The Santhals', false, 'c9cfb0b3-75c3-46e2-bc35-9569d9944536');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7daf331-53a4-4f40-932c-b5c39b1f55e4', 'The Ahoms', false, 'c9cfb0b3-75c3-46e2-bc35-9569d9944536');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cc9d234-726d-4ca0-ab53-c38647a7eeef', 'The Gakkhars', false, 'c9cfb0b3-75c3-46e2-bc35-9569d9944536');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e118250-08f9-4bc1-bfba-1fb97526beb5', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'How did the proliferation of specialized crafts and professional occupational groups lead to the emergence of ''JATIS'' (sub-castes) within the Varna system?', 'Economic diversification spawned Jatis: specialized artisanal, mercantile, and tribal communities were accommodated as discrete jatis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4412d39c-690c-45c7-a582-1c4d644f6ee7', 'As the economy grew more complex, specialized occupational groups (smiths, carpenters, masons, sculptors) were recognized by Brahmans as distinct Jatis within the social framework', true, '8e118250-08f9-4bc1-bfba-1fb97526beb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2dd1ab3-b454-44bf-b69c-85bff68164a1', 'The Varna system was abolished completely', false, '8e118250-08f9-4bc1-bfba-1fb97526beb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c900bdea-aa6c-4c26-bef3-4e708d0e8d1b', 'All craftspersons were made kings', false, '8e118250-08f9-4bc1-bfba-1fb97526beb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cb1a1ea-8a96-47cd-af3e-ed03e04e2e81', 'Jatis were introduced by foreign traders', false, '8e118250-08f9-4bc1-bfba-1fb97526beb5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8378d5a1-f428-41ea-a3fc-5f359e8294b6', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What agricultural innovation in Wet-Rice Cultivation was introduced by the Ahoms in the Brahmaputra valley?', 'Ahoms engineered wet-rice hydraulic ecology: building bunds, earthen dykes, and canal networks across floodplains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e9a2c4f-ead8-4f3d-b51b-89a8957e8777', 'Advanced wet rice transplantation techniques, construction of extensive flood-control dykes and irrigation canals', true, '8378d5a1-f428-41ea-a3fc-5f359e8294b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7640daf8-3902-458f-bab9-02fbccabbc35', 'Growing rice without water in deserts', false, '8378d5a1-f428-41ea-a3fc-5f359e8294b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b9d704e-e9cb-44b5-84ed-ef3528ec793e', 'Importing rice from Europe', false, '8378d5a1-f428-41ea-a3fc-5f359e8294b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4db393b2-f2e4-497d-84a4-7df05f02871d', 'Using tractors and chemical fertilizers', false, '8378d5a1-f428-41ea-a3fc-5f359e8294b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('907d3a17-d3d3-424e-ad34-cd3f2ad8c66f', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What happened when the Mughals under Asaf Khan conquered Garha Katanga in 1565?', 'The Mughals appropriated Garha Katanga''s legendary treasury of gold and elephants, establishing indirect suzerainty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66b238f9-6226-4340-84c1-89724e6f25f3', 'The Mughals captured immense booty in precious gold coins and thousands of wild elephants, annexing a part and granting the rest to Bir Narain''s uncle Chhatar Shah', true, '907d3a17-d3d3-424e-ad34-cd3f2ad8c66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2141f9af-5097-44f0-9e65-3ec44a9ef95e', 'They destroyed all houses and left', false, '907d3a17-d3d3-424e-ad34-cd3f2ad8c66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77eebf92-f796-4cc7-a1cd-63aedfef4e18', 'They made Rani Durgavati the Mughal Empress', false, '907d3a17-d3d3-424e-ad34-cd3f2ad8c66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c1f4719-cfd8-4ecb-a024-7aa4945681c0', 'They planted a forest over the kingdom', false, '907d3a17-d3d3-424e-ad34-cd3f2ad8c66f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('163afe12-68d4-403a-8ce8-e150e911df33', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Which martial tribes inhabited the rugged Balochistan desert frontiers in the northwest of the subcontinent?', 'The Balochis formed a major confederacy of clan-based pastoral and warrior tribes across the northwestern arid frontiers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('774985f4-d839-4c6b-8b88-d6a0e2dd0fcc', 'The Balochis (divided into many powerful clans under chieftains)', true, '163afe12-68d4-403a-8ce8-e150e911df33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1548f2f-c142-46e2-83b3-71459548e1cc', 'The Ahoms', false, '163afe12-68d4-403a-8ce8-e150e911df33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dd5a5cb-1e09-4c7a-b748-9f0d3e0279c1', 'The Gonds', false, '163afe12-68d4-403a-8ce8-e150e911df33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a947816-2619-441b-a97c-484d621775a6', 'The Santhals', false, '163afe12-68d4-403a-8ce8-e150e911df33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3518ea8b-b56b-4eda-b01c-4be9374883f1', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Which tribal kingdoms inhabited the forested plateaus of Chota Nagpur and Odisha during the medieval era?', 'The Mundas, Santhals, and Oraons inhabited the mineral-rich Chota Nagpur plateau and forested Odisha tracts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cae6bb64-2c88-46c7-bb9b-85fbdcd1a47c', 'The Mundas and Santhals', true, '3518ea8b-b56b-4eda-b01c-4be9374883f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c52f548-a47b-414a-a071-d61e5aebf0b5', 'The Ahoms', false, '3518ea8b-b56b-4eda-b01c-4be9374883f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10428f97-02ff-4aa2-81a5-3965c4311d17', 'The Kolis', false, '3518ea8b-b56b-4eda-b01c-4be9374883f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f08c48b-de61-4e05-b722-3fc8b68c9d80', 'The Gakkhars', false, '3518ea8b-b56b-4eda-b01c-4be9374883f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('515cd4b4-14c1-449f-9879-8f10f1b3da6a', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What were the ''Itinerant Groups'' in medieval society?', 'Itinerant groups included nomadic blacksmiths, rope-makers, acrobats, and bards servicing rural communities on seasonal circuits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f9f9929-5ee9-4da3-b7c5-a2f23f626802', 'Mobile craftspersons, entertainers, pedlars, and puppeteers who traveled from village to village practicing their occupation and trade', true, '515cd4b4-14c1-449f-9879-8f10f1b3da6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b88b29b7-a3cf-46fd-85e0-0bb068b87b75', 'Kings who lived in tents', false, '515cd4b4-14c1-449f-9879-8f10f1b3da6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b177cba6-9f23-4a6d-a693-222a226cd825', 'Priests who never walked', false, '515cd4b4-14c1-449f-9879-8f10f1b3da6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2118f90-3ead-48fa-a27e-1c3c99f913a5', 'Soldiers guarding fort gates', false, '515cd4b4-14c1-449f-9879-8f10f1b3da6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('edea7ac6-cc5f-4f79-8f51-1d59a5f10c2a', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What was the ''Khel'' census mechanism used by Ahom kings to manage labor and military manpower?', 'The Ahom administration took regular Paik censuses, re-allocating corvée labor between densely and sparsely populated khels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69e0bebc-9834-4ad5-9b8e-aae45fca152c', 'A regular population census was taken; villages with large populations were forced to transfer Paik laborers to sparsely populated areas to balance labor resources', true, 'edea7ac6-cc5f-4f79-8f51-1d59a5f10c2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b68cf9a7-8332-451c-8f56-14ffdd01a3ba', 'Every person was given gold coins', false, 'edea7ac6-cc5f-4f79-8f51-1d59a5f10c2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e27b342-1140-40ee-801c-37d8eae62f32', 'People were counted by measuring their height', false, 'edea7ac6-cc5f-4f79-8f51-1d59a5f10c2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aa66dc6-4e2c-456e-aaf3-574d5ab9aee7', 'Only horses were counted', false, 'edea7ac6-cc5f-4f79-8f51-1d59a5f10c2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7a11fc4-be46-455c-a1c0-e1154e854ee9', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Why did Brahman scholars gain immense influence in Gond and Ahom royal courts in the 16th and 17th centuries?', 'Tribal rulers patronized Brahmans with land grants to legitimize their emergent monarchies within the pan-Indian royal pantheon.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9bfc28e-5690-42e9-b981-8abe282a2bd4', 'Tribal kings granted generous tax-free land endowments (Brahmadeya) to Brahmans to obtain Sanskrit genealogical legitimacy, Kshatriya status, and rituals for statecraft', true, 'c7a11fc4-be46-455c-a1c0-e1154e854ee9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48e4bae5-33ca-45ae-bc8e-e6b33858ef3f', 'Brahmans were the only soldiers in the kingdom', false, 'c7a11fc4-be46-455c-a1c0-e1154e854ee9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29771851-a15d-4203-b13a-c43cfddca598', 'Brahmans built all cannons', false, 'c7a11fc4-be46-455c-a1c0-e1154e854ee9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('648e16ad-a0d7-44ba-9459-987a926655b6', 'Brahmans controlled the elephant trade', false, 'c7a11fc4-be46-455c-a1c0-e1154e854ee9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6db3746-353c-424f-9871-5f4c15ce3361', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8c86c56-a00d-4d0a-9a0f-359f2f191a63', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'e6db3746-353c-424f-9871-5f4c15ce3361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e0d31d2-cf02-4dad-b36d-e35911af76ce', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'e6db3746-353c-424f-9871-5f4c15ce3361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d1e1e10-2ed7-4932-aff8-b7049245a6c8', '(A) is true, but (R) is false.', false, 'e6db3746-353c-424f-9871-5f4c15ce3361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06e4f13e-a957-4724-abe3-75aa372ebc89', '(A) is false, but (R) is true.', false, 'e6db3746-353c-424f-9871-5f4c15ce3361');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('839f92af-fc59-4ee6-9bb3-b05b96270507', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Spot the IMPOSTER in the following group of Tribal Communities and their historical regional homelands:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8f07b84-e60c-406d-a47f-3b7ae97c6b30', 'Tribe 1', false, '839f92af-fc59-4ee6-9bb3-b05b96270507');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8525c30f-5f20-403f-bf91-76488ca8b35e', 'Tribe 2', false, '839f92af-fc59-4ee6-9bb3-b05b96270507');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14c68bac-f1c0-4905-a08d-e670b860b2d8', 'Tribe 3', false, '839f92af-fc59-4ee6-9bb3-b05b96270507');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('107b5112-b68c-4efc-b77a-4285678a1a3b', 'Tribe 4 (The Khokhars were a powerful martial tribe of the PUNJAB region, not ocean reefs)', true, '839f92af-fc59-4ee6-9bb3-b05b96270507');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9d93f8c-69ef-4b64-aacd-59994c2274fa', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Analyze the state formation process in the Ahom kingdom:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d93effcd-12ea-4d22-9625-815f3ddd6705', 'They suppressed the older feudal lords (Bhuiyans), annexed neighboring kingdoms (Chhutiyas, Koch-Hajo), built extensive hydraulic dykes, and instituted the Paik rotational labor system backed by gunpowder ballistics', true, 'e9d93f8c-69ef-4b64-aacd-59994c2274fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7326c014-a13b-4890-80a0-831470a336f2', 'They moved the entire population to Tibet', false, 'e9d93f8c-69ef-4b64-aacd-59994c2274fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e23cc3cb-344a-4733-b270-0e406a36a861', 'They abolished agriculture and became pure hunter-gatherers', false, 'e9d93f8c-69ef-4b64-aacd-59994c2274fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('441b245a-6de9-4f33-8b8b-bcea2901a27a', 'They signed a treaty with Roman emperors', false, 'e9d93f8c-69ef-4b64-aacd-59994c2274fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9833dbf8-93ae-4f95-93b5-e3f24fb43088', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Match Column I (Tribal & Administrative Terminology) with Column II (Exact Historical Meanings):
(a) Chaurasi  -> (i) Unit of 84 villages in the Gond Garh administrative hierarchy
(b) Barhot    -> (ii) Sub-unit of 12 villages under a Chaurasi
(c) Buranji   -> (iii) Official historical chronicles written in Ahom and Assamese
(d) Paik      -> (iv) Obligatory rotational corvée laborer in the Ahom state system', 'Chaurasi = 84 villages; Barhot = 12 villages; Buranji = chronicle; Paik = corvée laborer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('518791a2-29f7-41fa-ba54-8dc5ab31f5a5', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '9833dbf8-93ae-4f95-93b5-e3f24fb43088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b8443c4-5387-453c-960c-18f5df05ede9', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '9833dbf8-93ae-4f95-93b5-e3f24fb43088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b519ae53-8cc1-4b51-9ca1-5b8bc236408d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '9833dbf8-93ae-4f95-93b5-e3f24fb43088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51dbc0d4-94e3-4258-b05b-6aae6e0cef2c', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '9833dbf8-93ae-4f95-93b5-e3f24fb43088');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9785a57-c4ce-412e-a627-7b2e1f03e36d', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Read the statements regarding the transition from Varna to Jati:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8a67213-e09e-4603-b841-e3a252c9362b', 'Statements 1 and 2 only', true, 'e9785a57-c4ce-412e-a627-7b2e1f03e36d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc7ea1ee-2ee5-4477-8abd-82eaae37ba65', 'Statements 2 and 3 only', false, 'e9785a57-c4ce-412e-a627-7b2e1f03e36d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9cbff15-c62b-45da-b339-79e78e2b0d9c', 'Statements 1 and 3 only', false, 'e9785a57-c4ce-412e-a627-7b2e1f03e36d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fc07287-8c1e-4d86-9931-bc78ab76d437', 'All Statements 1, 2, and 3', false, 'e9785a57-c4ce-412e-a627-7b2e1f03e36d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58dcfbb7-dea8-4448-8701-f02d130ea220', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Why was the heroic defense and martyrdom of Rani Durgavati of Garha Katanga (1565) celebrated in central Indian folklore?', 'Rani Durgavati''s resistance against Mughal imperial expansion embodies the indomitable martial pride of indigenous central Indian rulers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d43d1c9-eee4-4f0c-8ee5-0a2ff9a72056', 'She chose death in battle over surrender to Mughal subjugation, fighting with immense military valor alongside her wounded son to defend the sovereignty of her Gond kingdom', true, '58dcfbb7-dea8-4448-8701-f02d130ea220');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a138b52f-5a12-4b07-9957-6511837a9bda', 'Because she built the Taj Mahal', false, '58dcfbb7-dea8-4448-8701-f02d130ea220');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33624e67-11fc-4575-aaed-807249dd5098', 'Because she gave up her kingdom to live in a forest', false, '58dcfbb7-dea8-4448-8701-f02d130ea220');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b158eab8-9c74-43a4-b4fd-c1c7164bb0f3', 'Because she defeated the British in 1565', false, '58dcfbb7-dea8-4448-8701-f02d130ea220');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14646a71-00a7-48aa-b8a2-1bd19e628c14', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'How did the Paik labor system in Ahom Assam differ from traditional feudal slavery?', 'The Paik system was a reciprocal corvée obligation anchored in inalienable clan land tenure rather than chattel slavery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15f125ad-49d1-4757-9eee-03824cda431e', 'Paiks were free village peasants who contributed rotational state service (military, dyke construction) in exchange for community-allocated agricultural land that could not be taken away by the King without clan approval', true, '14646a71-00a7-48aa-b8a2-1bd19e628c14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6df79392-164c-46d7-96de-4a294181e02a', 'Paiks were bought and sold in markets as slaves', false, '14646a71-00a7-48aa-b8a2-1bd19e628c14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdf1dd82-1f20-4b72-918d-c2bc64901764', 'Paiks were foreign prisoners of war', false, '14646a71-00a7-48aa-b8a2-1bd19e628c14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87d33a1b-dcd2-47e4-b16b-c7f998d478c3', 'Paiks were only employed as palace cooks', false, '14646a71-00a7-48aa-b8a2-1bd19e628c14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f627e584-ea1d-44b9-b9b1-6ca1bbbfb209', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'What socio-religious transformation occurred as tribal states became large, centralized monarchies?', 'State centralization fostered syncretic integration: tribal deities (e.g. Kamakhya, Jagannath) were incorporated into Brahmanical temple worship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01212ff8-79b2-4370-9322-39f00e6bfbf8', 'Indigenous animistic and ancestral tribal deities were synthesized with Puranic Hindu pantheons, leading to composite temple patronage under royal sponsorship', true, 'f627e584-ea1d-44b9-b9b1-6ca1bbbfb209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63dec224-1016-4746-8b65-be7dee85acb5', 'All tribal languages were completely banned', false, 'f627e584-ea1d-44b9-b9b1-6ca1bbbfb209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0d73cd4-cbbd-43b9-b8ad-3d17c8ce0e17', 'Tribal people were forced to move out of India', false, 'f627e584-ea1d-44b9-b9b1-6ca1bbbfb209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e03e575-7077-47fe-9211-e0c7c329cee2', 'Monarchy was abolished', false, 'f627e584-ea1d-44b9-b9b1-6ca1bbbfb209');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68b681ce-5cf0-4c48-ac0d-52d8bc0ab4a7', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Consider four regional tribal communities of medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02b1a052-62d3-45dd-91d2-f7d703beb0fe', 'They developed powerful centralized kingdoms or formidable martial resistance networks that negotiated with or contested Mughal imperial expansion', true, '68b681ce-5cf0-4c48-ac0d-52d8bc0ab4a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72162148-162b-4661-a703-cc8efa5088b3', 'They had no chiefs or leaders', false, '68b681ce-5cf0-4c48-ac0d-52d8bc0ab4a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d639e1d-1ce7-4b59-ab6b-8b752fe6df67', 'They all converted to European religions in 1500', false, '68b681ce-5cf0-4c48-ac0d-52d8bc0ab4a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df9ce8e6-db7a-4d36-9891-f794cdda169a', 'They lived only on oceanic islands', false, '68b681ce-5cf0-4c48-ac0d-52d8bc0ab4a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e09569f9-4533-4924-8208-fe085474cf1f', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Why did the Ahom kingdom successfully resist Mughal conquest for over a century, despite repeated Mughal campaigns?', 'Ahom military resilience: naval riverine mastery (Battle of Saraighat 1671 under Lachit Borphukan), guerrilla tactics, and dense terrain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ebacb78-bd37-4cf6-83b2-5d811e043c12', 'The Ahoms mastered guerrilla warfare in dense riverine terrain, constructed formidable mud and brick fortifications, utilized rapid war-boat naval fleets on the Brahmaputra, and deployed effective firearms', true, 'e09569f9-4533-4924-8208-fe085474cf1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b427c73-874a-4eb0-96fd-5d839ee0eb86', 'Because the Mughals never entered Assam', false, 'e09569f9-4533-4924-8208-fe085474cf1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4f3f7de-678d-4434-bdd5-4e97339260d6', 'Because Assam had no rivers', false, 'e09569f9-4533-4924-8208-fe085474cf1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ca8208c-c4df-4b75-8501-4fac5bfa28ad', 'Because the British defended Assam', false, 'e09569f9-4533-4924-8208-fe085474cf1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5471433b-32c0-45cb-9fee-609d3a7088f2', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'What was the significance of ''Buranjis'' for modern historiography of Northeast India?', 'Buranjis constitute an unprecedented tradition of secular, chronological historiography in medieval Northeast India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b4a397-5aa9-4b64-86ed-e3d32da3a860', 'They provide a continuous, meticulously detailed chronological record of diplomacy, wars, treaties, administrative censuses, and royal successions over 600 years', true, '5471433b-32c0-45cb-9fee-609d3a7088f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0528c9cb-e581-4436-b847-260dcf878abe', 'They are fictional mythological poems only', false, '5471433b-32c0-45cb-9fee-609d3a7088f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8538e76c-b471-480b-ab43-a3228d3deaa9', 'They were written in modern English', false, '5471433b-32c0-45cb-9fee-609d3a7088f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c1b64c5-6eda-409e-a87f-c3eb5cc57630', 'They contain no historical dates', false, '5471433b-32c0-45cb-9fee-609d3a7088f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3134a4f-28a4-4dfe-a16d-891fd88ab05f', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'What master historical synthesis is illuminated in Chapter 7 of NCERT Class 7 History?', 'Chapter 7 restores historical balance by highlighting the agency, statecraft, and cultural contributions of indigenous tribal and pastoral societies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89c3d84a-64de-4b00-87be-fdac7fbd7331', 'Indian medieval history was shaped as much by dynamic tribal kingdoms, nomadic pastoralists, and frontier societies as by settled empires, revealing a vibrant pluralistic subcontinent defined by continuous cultural synthesis and political adaptation', true, 'd3134a4f-28a4-4dfe-a16d-891fd88ab05f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('834832ad-0b03-42e0-a3f4-e29475662d3c', 'That only kings living in Delhi mattered in Indian history', false, 'd3134a4f-28a4-4dfe-a16d-891fd88ab05f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('740eab8e-9ffc-4fb2-90a4-3d89c32bcaf3', 'That tribal societies had no culture or history', false, 'd3134a4f-28a4-4dfe-a16d-891fd88ab05f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf559ad8-cf7c-4dc6-8b40-487b244ca769', 'That India was completely uniform without any regional diversity', false, 'd3134a4f-28a4-4dfe-a16d-891fd88ab05f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f8c5e3b-e026-49b8-9462-aecb6e03d108', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'संज्ञा के जिस रूप से किसी व्यक्ति, प्राणी या वस्तु के पुरुष जाति अथवा स्त्री जाति होने का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'लिंग: संज्ञा के जिस रूप से पुरुष या स्त्री जाति का बोध हो, उसे लिंग कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3163b5a3-344c-479a-b885-a88d003323a9', 'लिंग (Gender)', true, '7f8c5e3b-e026-49b8-9462-aecb6e03d108');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e8f76f1-82a3-474d-ac48-bed9ca493485', 'वचन (Number)', false, '7f8c5e3b-e026-49b8-9462-aecb6e03d108');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3d58f67-b18d-453c-980f-1d83856f946d', 'कारक (Case)', false, '7f8c5e3b-e026-49b8-9462-aecb6e03d108');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03a02624-6b35-4e87-9b41-ec86f9d600f0', 'काल (Tense)', false, '7f8c5e3b-e026-49b8-9462-aecb6e03d108');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc293b85-26b4-459c-bd7d-ab3bc22cfc37', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'हिंदी भाषा में लिंग के मुख्य रूप से कितने भेद होते हैं?', 'संस्कृत में 3 लिंग होते हैं, परन्तु हिंदी व्याकरण में केवल 2 लिंग होते हैं: पुल्लिंग और स्त्रीलिंग।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e37e461-ed9c-43c1-bf9d-81b1c4485a9e', 'दो भेद (1. पुल्लिंग, 2. स्त्रीलिंग)', true, 'fc293b85-26b4-459c-bd7d-ab3bc22cfc37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30290d46-364c-4c99-a91f-aee01cc17fa3', 'तीन भेद (क्लीवलिंग सहित)', false, 'fc293b85-26b4-459c-bd7d-ab3bc22cfc37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1368559c-c976-49df-a694-601434993c51', 'चार भेद', false, 'fc293b85-26b4-459c-bd7d-ab3bc22cfc37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27c29e36-70c2-4045-a9ab-c0b7d9084e04', 'पाँच भेद', false, 'fc293b85-26b4-459c-bd7d-ab3bc22cfc37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d14a327d-a5d5-444e-bd30-4701f329f82a', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'शब्द के जिस रूप से किसी वस्तु, प्राणी या पदार्थ के ''एक'' अथवा ''एक से अधिक'' होने का बोध होता है, उसे क्या कहते हैं?', 'वचन: संज्ञा, सर्वनाम, विशेषण या क्रिया के जिस रूप से संख्या (एकत्व या अनेकत्व) का बोध हो, उसे वचन कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be5b21ac-ca6e-4486-993e-f2e4b1e6fbf6', 'वचन (Number)', true, 'd14a327d-a5d5-444e-bd30-4701f329f82a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02d79e10-8cc2-4082-9eef-a90350561744', 'लिंग', false, 'd14a327d-a5d5-444e-bd30-4701f329f82a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3d24a80-92a5-415c-9867-4de59ced05f8', 'पुरुष', false, 'd14a327d-a5d5-444e-bd30-4701f329f82a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7b889c-f421-43a1-b3f9-a4004f9727cb', 'समास', false, 'd14a327d-a5d5-444e-bd30-4701f329f82a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38f1daa4-392e-4971-b96d-b262cd1a42b1', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'हिंदी में वचन के कितने भेद होते हैं?', 'हिंदी में केवल 2 वचन होते हैं: एकवचन (Singular) और बहुवचन (Plural)।', NOW()) ON CONFLICT DO NOTHING;
