INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1168fef8-779e-4be0-93ab-df0abca77e99', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'दिनों के नाम (सोमवार, मंगलवार), महीनों के नाम (जनवरी, मार्च, चैत्र) तथा पर्वतों के नाम (हिमालय, विंध्याचल) सामान्यतः किस लिंग में होते हैं?', 'दिनों, महीनों, पर्वतों, देशों, ग्रहों (पृथ्वी को छोड़कर) और समुद्रों के नाम सदैव पुल्लिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
