INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05ccb21d-0371-47f7-87a9-cfb46ca84fb7', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'भाषाओं के नाम (हिंदी, अंग्रेजी, संस्कृत), लिपियों के नाम (देवनागरी, रोमन) तथा नदियों के नाम (गंगा, यमुना) सामान्यतः किस लिंग में होते हैं?', 'भाषाओं, बोलियों, लिपियों, नदियों (सिंधु/ब्रह्मपुत्र नद को छोड़कर) और तिथियों के नाम स्त्रीलिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
