INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be6f7c41-2205-4b42-a4cf-715e48dc4f4f', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', '''कवि'' शब्द का शुद्ध स्त्रीलिंग रूप क्या होगा?', 'कवि का शुद्ध वर्तनी-सम्मत स्त्रीलिंग रूप ''कवयित्री'' होता है।', NOW()) ON CONFLICT DO NOTHING;
