INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9957999e-eb27-480f-8d55-ae57ea1e45f3', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', '''विद्वान'' शब्द का सही स्त्रीलिंग रूप क्या होगा?', '''विद्वान'' का मानक स्त्रीलिंग ''विदुषी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
