INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0994d32-42a4-4185-8d33-aa4f0ea803bf', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', '''श्रीमती'' किस पुल्लिंग शब्द का स्त्रीलिंग रूप है?', 'श्रीमान् (पुल्लिंग) का स्त्रीलिंग ''श्रीमती'' होता है (मान्→मती)।', NOW()) ON CONFLICT DO NOTHING;
