INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d900f53-a2bc-469d-97b3-258e4b67ffee', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', '''प्राण, दर्शन, हस्ताक्षर, आँसू, होश, बाल'' शब्द हिंदी में सदैव किस वचन में प्रयुक्त होते हैं?', 'प्राण, दर्शन, आँसू, हस्ताक्षर, होश, बाल, लोग - ये शब्द हिंदी में नित्य बहुवचन होते हैं (जैसे: मेरे प्राण निकल गए)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('febeded4-7555-43ac-a0f4-6a68fe92d86c', 'सदा बहुवचन में (Always Plural)', true, '3d900f53-a2bc-469d-97b3-258e4b67ffee');
