INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49b3ea01-0c7b-4aaf-83a0-16eb04cf4ea4', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', '''पानी, दूध, तेल, घी, सोना, वर्षा, जनता, सत्य'' शब्द हिंदी में सदैव किस वचन में प्रयुक्त होते हैं?', 'द्रव्यवाचक संज्ञाएँ, धातुएँ, प्राकृतिक अवस्थाएँ (वर्षा) और ''जनता, सत्य'' सदैव एकवचन में प्रयुक्त होते हैं।', NOW()) ON CONFLICT DO NOTHING;
