INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e4ae9e3-573e-4eac-8f70-795abf41e414', 'उभयलिंग में', false, '49b3ea01-0c7b-4aaf-83a0-16eb04cf4ea4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e25022b-67af-46b9-95b3-d0cdaa3f62e9', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', '''लड़का'' शब्द का सही बहुवचन रूप क्या होगा?', 'आकारांत पुल्लिंग शब्द का बहुवचन ''आ'' को ''ए'' में बदलकर ''लड़के'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82ffdcf5-950c-4c7d-a4f9-d76c2353a287', 'लड़के', true, '4e25022b-67af-46b9-95b3-d0cdaa3f62e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f894bff-3a2e-4c73-8515-4e00f1ea484d', 'लड़कों', false, '4e25022b-67af-46b9-95b3-d0cdaa3f62e9');
