INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bd8057f-3896-47d9-b026-2c6700b48e0c', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''नेता'' शब्द का शुद्ध स्त्रीलिंग रूप क्या होगा?', 'संस्कृत ''ता'' अंत वाले पुल्लिंग शब्दों का स्त्रीलिंग ''त्री'' होता है: नेता→नेत्री, अभिनेता→अभिनेत्री, दाता→दात्री।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57661c5f-9afa-4b80-9c9a-d937f788bfd0', 'नेत्री', true, '1bd8057f-3896-47d9-b026-2c6700b48e0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d65cd53b-cd98-4f8d-94d9-41645880f868', 'नेतिन', false, '1bd8057f-3896-47d9-b026-2c6700b48e0c');
