INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc8fc353-8adb-40e3-acae-a06a8b83358b', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''सम्राट'' शब्द का सही स्त्रीलिंग रूप क्या होगा?', '''सम्राट'' का मानक स्त्रीलिंग ''साम्राज्ञी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5990e4a0-d58c-41f6-8f00-8b718a2b6f75', 'साम्राज्ञी', true, 'fc8fc353-8adb-40e3-acae-a06a8b83358b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09cce30b-b302-40c4-8c37-10119aa4b1f3', 'सम्राटी', false, 'fc8fc353-8adb-40e3-acae-a06a8b83358b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1b3d88c-d830-4e86-9775-272d92cfc5bf', 'सम्राटिन', false, 'fc8fc353-8adb-40e3-acae-a06a8b83358b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddb63941-821d-4d72-b68f-d34ef95e1437', 'रानी', false, 'fc8fc353-8adb-40e3-acae-a06a8b83358b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c10c9f03-201f-448e-a5ae-a0042febccb3', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'इकारांत और ईकारांत स्त्रीलिंग शब्दों (जैसे: नदी, लड़की, साड़ी) का बहुवचन बनाते समय क्या नियम लागू होता है?', 'ईकारांत स्त्रीलिंग का बहुवचन: ई→इ + याँ (नदी→नदियाँ, दवाई→दवाइयाँ, नीति→नीतियाँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d7af07-1d95-47f7-9573-e8a56e7ed067', 'अंतिम दीर्घ ''ई'' को ह्रस्व ''इ'' में बदलकर अंत में ''याँ'' जोड़ दिया जाता है (जैसे: नदी -> नदियाँ, लड़की -> लड़कियाँ, साड़ी -> साड़ियाँ)', true, 'c10c9f03-201f-448e-a5ae-a0042febccb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56ab6937-8a9c-41ec-8299-8ce4a8e07918', 'केवल बिंदी लगा दी जाती है', false, 'c10c9f03-201f-448e-a5ae-a0042febccb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c565712c-fa19-42c3-86cb-2c1ac939f884', 'शब्द को वैसे ही छोड़ दिया जाता है', false, 'c10c9f03-201f-448e-a5ae-a0042febccb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dc56c78-efbf-4f9e-bc17-36dcc6762b5a', 'शब्द के अंत में ''ए'' जोड़ा जाता है', false, 'c10c9f03-201f-448e-a5ae-a0042febccb3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2f748f9-533e-4f93-9c3c-f9f99d065d97', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'आदर और सम्मान प्रकट करने के लिए एकवचन संज्ञा (जैसे: गुरुजी, पिताजी, महात्मा गांधी) के साथ किस वचन की क्रिया का प्रयोग किया जाता है?', 'हिंदी में पूज्य एवं आदरणीय व्यक्तियों के लिए एकवचन कर्ता होते हुए भी क्रिया ''आदरार्थक बहुवचन'' में प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8cdd55c-5b35-426c-9f0c-0b6e632fe6bc', 'बहुवचन की क्रिया का प्रयोग (आदरार्थक बहुवचन - जैसे: ''गांधीजी सत्य बोलते थे'', ''गुरुजी आ रहे हैं'')', true, 'b2f748f9-533e-4f93-9c3c-f9f99d065d97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30948df7-508c-49e9-b147-44b7574f6875', 'एकवचन की क्रिया का ही प्रयोग होता है', false, 'b2f748f9-533e-4f93-9c3c-f9f99d065d97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6da31d3-0450-4c37-9545-43c48ffed09e', 'भविष्यत काल की क्रिया का प्रयोग', false, 'b2f748f9-533e-4f93-9c3c-f9f99d065d97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cf6594b-168e-475e-a404-6c169cd49065', 'क्रिया का लोप हो जाता है', false, 'b2f748f9-533e-4f93-9c3c-f9f99d065d97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bed66fb-3beb-4213-805d-7079a441be44', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''चिड़िया'' और ''डिबिया'' जैसे ''या'' अंत वाले स्त्रीलिंग शब्दों का बहुवचन कैसे बनाया जाता है?', '''या'' अंत वाले स्त्रीलिंग शब्दों के ऊपर चन्द्रबिन्दु लगाकर बहुवचन बनता है: चिड़िया→चिड़ियाँ, डिबिया→डिबियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caab16ed-9509-4ad4-99da-fba3ed3de2d9', 'अंतिम ''या'' के ऊपर अनुनासिक (चन्द्रबिन्दु - ''याँ'') लगाकर (जैसे: चिड़िया -> चिड़ियाँ, डिबिया -> डिबियाँ, गुड़िया -> गुड़ियाँ)', true, '0bed66fb-3beb-4213-805d-7079a441be44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25ae2729-674e-4c09-9062-cde2fb1804c9', '''या'' को हटाकर ''ए'' लगाकर', false, '0bed66fb-3beb-4213-805d-7079a441be44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a516b9-38bf-4050-8428-2d08e0cc721e', 'शब्द में कोई परिवर्तन नहीं होता', false, '0bed66fb-3beb-4213-805d-7079a441be44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4f7b9f2-e70e-4ff1-87e6-5aa5981e4568', '''या'' के आगे ''गण'' जोड़कर', false, '0bed66fb-3beb-4213-805d-7079a441be44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f26cb6e4-c7b9-461d-826c-2fccdcb9e8af', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''अध्यापक'' शब्द का आदरसूचक बहुवचन बनाने के लिए कौन-सा समूहवाचक प्रत्यय जोड़ा जाता है?', 'गण्य व्यक्तियों के बहुवचन हेतु ''गण, वृंद, जन, वर्ग'' जुड़ता है: अध्यापकगण, मुनिवृंद, भक्तजन, अधिकारीवर्ग।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('269c1179-552d-48e9-8be8-645b2d320e4a', 'अध्यापकगण (गण / वृंद / जन / वर्ग)', true, 'f26cb6e4-c7b9-461d-826c-2fccdcb9e8af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('354e342f-3281-460e-ab43-9e852efc06f8', 'अध्यापिकाएँ', false, 'f26cb6e4-c7b9-461d-826c-2fccdcb9e8af');
