INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e37d7d51-4590-496d-88b3-bb4331b8d3ab', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''साधु'' शब्द का स्त्रीलिंग रूप क्या होगा?', '''साधु'' का मानक स्त्रीलिंग रूप ''साध्वी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
