INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe4e5cd5-b5c7-4416-854e-37742605b1e5', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''वर'' शब्द का सही स्त्रीलिंग रूप क्या है?', 'संस्कृत तत्सम युग्म: वर (वर) का स्त्रीलिंग ''वधू'' होता है।', NOW()) ON CONFLICT DO NOTHING;
