INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68d76899-7176-4902-bb1f-00551b09b2c9', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''वधू'' शब्द का शुद्ध बहुवचन रूप क्या होगा?', 'ऊकारांत स्त्रीलिंग का बहुवचन: ऊ→उ + एँ (वधू→वधुएँ, बहू→बहुएँ)।', NOW()) ON CONFLICT DO NOTHING;
