INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a72b328-868c-469b-841d-f4fc78532fc2', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''नित्य स्त्रीलिंग'' है, जिसका पुल्लिंग बनाने के लिए ''नर'' शब्द जोड़ना पड़ता है?', 'मक्खी, कोयल, तितली, मछली, चील नित्य स्त्रीलिंग हैं; इनका पुल्लिंग ''नर मक्खी, नर कोयल'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7cb55eb-4824-4f3d-b45b-3cef5963d013', 'मक्खी (नर मक्खी), तितली (नर तितली), मछली (नर मछली), चील (नर चील)', true, '4a72b328-868c-469b-841d-f4fc78532fc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ae049fd-ffb2-4adc-b6b1-814e386fef23', 'शेर', false, '4a72b328-868c-469b-841d-f4fc78532fc2');
