INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abb572ae-b9c6-4fd4-a44b-3f640d77941d', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''नित्य पुल्लिंग'' है, जिसका स्त्रीलिंग बनाने के लिए ''मादा'' शब्द जोड़ना पड़ता है?', 'तोता, भालू, चीता, उल्लू, खटमल, मच्छर नित्य पुल्लिंग हैं; इनका स्त्रीलिंग ''मादा तोता, मादा भालू'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b8c175a-e9d3-4877-8ee2-720d7e924343', 'तोता (मादा तोता), भालू (मादा भालू), चीता (मादा चीता), खटमल (मादा खटमल)', true, 'abb572ae-b9c6-4fd4-a44b-3f640d77941d');
