INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ebf95cc-e04a-446b-ba8b-57464a5ad92d', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''दवा'' शब्द का शुद्ध बहुवचन रूप क्या होगा?', 'आकारांत स्त्रीलिंग ''दवा'' का बहुवचन ''दवाएँ'' होता है (''दवाई'' का बहुवचन ''दवाइयाँ'' होता है)।', NOW()) ON CONFLICT DO NOTHING;
