INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e9ff0cb-98ea-47bb-a972-c9725bb40953', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''उभयलिंगी'' (Common Gender - पुरुष और स्त्री दोनों के लिए समान रूप से प्रयुक्त) पदनाम है?', 'उच्च पदनाम एवं व्यवसाय (राष्ट्रपति, प्रधानमंत्री, डॉक्टर, प्रोफेसर) उभयलिंगी होते हैं, जिनका लिंग क्रिया से स्पष्ट होता है।', NOW()) ON CONFLICT DO NOTHING;
