INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f644764-69a8-43ff-805e-f49a555b18a8', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''पुस्तक'' शब्द का सही बहुवचन रूप क्या होगा?', 'अकारांत स्त्रीलिंग शब्द का बहुवचन ''अ'' के स्थान पर ''एं'' (अनुस्वार युक्त) लगाकर ''पुस्तकें'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('749d4114-04cb-4961-9764-4acaa8d9178d', 'पुस्तकें', true, '9f644764-69a8-43ff-805e-f49a555b18a8');
