INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4926a137-90bc-4389-ba5f-5ba80391de33', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''माला'' शब्द का सही बहुवचन रूप क्या होगा?', 'आकारांत स्त्रीलिंग के अंत में ''एँ'' जोड़कर बहुवचन बनता है: माला→मालाएँ, लता→लताएँ।', NOW()) ON CONFLICT DO NOTHING;
