INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2e2d575-052d-454b-8cb4-b450ae4e14e6', 'मालाओं', false, '4926a137-90bc-4389-ba5f-5ba80391de33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45621314-10e5-4a6e-afc4-eacb43d92a84', 'माली', false, '4926a137-90bc-4389-ba5f-5ba80391de33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28e3eb3d-cda7-46a7-bc9c-810189425fa3', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''दही'' शब्द व्याकरण की दृष्टि से किस लिंग के अंतर्गत आता है?', 'दही, घी, मोती, पानी, पानी, तेल - ये इकारांत अपवाद शब्द हिंदी में नित्य पुल्लिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e85a7e55-fc53-45ad-91a1-486e3c419fce', 'पुल्लिंग (जैसे: ''दही बहुत खट्टा है'', ''दही जम गया'')', true, '28e3eb3d-cda7-46a7-bc9c-810189425fa3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e4e6321-2472-4c46-9bc5-ff462a10398a', 'स्त्रीलिंग', false, '28e3eb3d-cda7-46a7-bc9c-810189425fa3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9db1904-79e9-41d4-8c10-9a8e09c18c02', 'उभयलिंग', false, '28e3eb3d-cda7-46a7-bc9c-810189425fa3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a7b363f-0303-40d6-ba69-7aa1820b965b', 'नपुंसकलिंग', false, '28e3eb3d-cda7-46a7-bc9c-810189425fa3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c2d4e05-af8c-4fd3-a7e7-b398b96f2bfd', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c54ff306-a95c-4636-b27b-cb63a39991d1', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '9c2d4e05-af8c-4fd3-a7e7-b398b96f2bfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1f22173-4f19-45a3-8313-b08fed10224d', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '9c2d4e05-af8c-4fd3-a7e7-b398b96f2bfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2a36edd-c897-47b8-836c-cb655aad4e65', '(A) सही है, परन्तु (R) गलत है।', false, '9c2d4e05-af8c-4fd3-a7e7-b398b96f2bfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ea69ce3-ecaf-4c04-9f68-79cb9a8415db', '(A) गलत है, परन्तु (R) सही है।', false, '9c2d4e05-af8c-4fd3-a7e7-b398b96f2bfd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af146b97-b3ef-4492-a567-8b16f3ad258b', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'Spot the IMPOSTER in the following group of पुल्लिंग-स्त्रीलिंग युग्मों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('204678ba-1d30-4882-8c4a-08fad8eac335', 'युग्म 1', false, 'af146b97-b3ef-4492-a567-8b16f3ad258b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e237112b-ffd4-4487-a408-2d62537c63fa', 'युग्म 2', false, 'af146b97-b3ef-4492-a567-8b16f3ad258b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b348b5e6-14b2-4398-b6c7-69072cdb3408', 'युग्म 3', false, 'af146b97-b3ef-4492-a567-8b16f3ad258b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('011fbcce-fed6-4d06-95c7-783b18eaf507', 'युग्म 4 (''धावक'' का शुद्ध स्त्रीलिंग ''धाविका'' होता है, धावकी नहीं)', true, 'af146b97-b3ef-4492-a567-8b16f3ad258b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c36bf9db-60bd-47fd-927c-8d8199b606f8', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'सुमेलित कीजिए (शब्द और उनका नित्य वचन व्यवहार):
(क) हस्ताक्षर -> (i) नित्य बहुवचन
(ख) जनता     -> (ii) नित्य एकवचन
(ग) दर्शन     -> (iii) नित्य बहुवचन
(घ) दूध       -> (iv) नित्य एकवचन', 'हस्ताक्षर/दर्शन = नित्य बहुवचन; जनता/दूध = नित्य एकवचन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4b0dbb9-1e52-409b-b020-6a9fd7b49ee9', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, 'c36bf9db-60bd-47fd-927c-8d8199b606f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ee90a20-049a-498f-88d5-a3411cb6bd71', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, 'c36bf9db-60bd-47fd-927c-8d8199b606f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a687bb-640d-4558-9ae5-6b836e9c45e7', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'c36bf9db-60bd-47fd-927c-8d8199b606f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35c7e542-24ec-46b5-979d-3c77a5a0f767', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'c36bf9db-60bd-47fd-927c-8d8199b606f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bf04310-1dd9-47f3-a381-66bead10054f', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'कारक-विभक्ति सहित (सप्रत्यय) होने पर किसी भी संज्ञा शब्द का बहुवचन बनाने के लिए कौन-सा प्रत्यय अनिवार्य रूप से प्रयुक्त होता है?', 'तिर्यक रूप (Oblique Plural): कारक विभक्ति चिह्नों के साथ सभी संज्ञाओं का बहुवचन ''ओं/यों'' से बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4600bdfd-1e4a-44c1-9106-50095116e60a', '''ओं'' अथवा ''यों'' प्रत्यय (तिर्यक बहुवचन - जैसे: लड़कों ने, नदियों में, घरों पर, माताओं को)', true, '1bf04310-1dd9-47f3-a381-66bead10054f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01d3fdf3-c32f-48c1-b1a9-6d3f663ac7d3', '''एँ'' प्रत्यय', false, '1bf04310-1dd9-47f3-a381-66bead10054f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6449b0a-4b3a-4dce-8f5f-498863d4ff6d', '''गण'' प्रत्यय', false, '1bf04310-1dd9-47f3-a381-66bead10054f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a180954-eac6-4625-93c3-ba6d32fccdbb', '''याँ'' प्रत्यय', false, '1bf04310-1dd9-47f3-a381-66bead10054f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04d3cf4b-f341-47b8-b5b3-9f09bd369e78', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''हाथी'' शब्द का शुद्ध स्त्रीलिंग रूप क्या होगा?', 'हाथी + इनी = हथिनी (मानक वर्तनी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eff20b1-5aed-40b9-a3ab-2dd62e0a7ebf', 'हथिनी (दीर्घ ''ई'' का ह्रस्व ''इ'' में परिवर्तन होकर ''इनी'' प्रत्यय)', true, '04d3cf4b-f341-47b8-b5b3-9f09bd369e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c959ff6-4c1b-46d9-a721-2a29ae8902d5', 'हाथिन', false, '04d3cf4b-f341-47b8-b5b3-9f09bd369e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd71e6d4-e056-4539-97d2-b0444c6389b5', 'हाथिनी', false, '04d3cf4b-f341-47b8-b5b3-9f09bd369e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15cfe429-01b2-41e6-8bf1-fa2a7f2f7c6b', 'हथनी', false, '04d3cf4b-f341-47b8-b5b3-9f09bd369e78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a420a6bd-ce33-4cc0-b84c-8a3791888034', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''महान'' विशेषण का शुद्ध स्त्रीलिंग रूप क्या होगा?', 'संस्कृत तत्सम ''महान्'' (पुल्लिंग) का स्त्रीलिंग रूप ''महती'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10f11e76-c8a8-4d2f-b9eb-6f7c60d7590b', 'महती (जैसे: ''महती कृपा'')', true, 'a420a6bd-ce33-4cc0-b84c-8a3791888034');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa550a30-21c8-418f-8793-380859b3dadb', 'महानी', false, 'a420a6bd-ce33-4cc0-b84c-8a3791888034');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13aeada3-ffe9-4a00-8afb-7beb6f88ee6a', 'महानता', false, 'a420a6bd-ce33-4cc0-b84c-8a3791888034');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fc8d4ce-89ea-413f-8ba2-4cfda78bfd3a', 'महिषी', false, 'a420a6bd-ce33-4cc0-b84c-8a3791888034');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fa60b6f-0974-4651-8421-ac139355345d', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'निम्नलिखित वाक्यों में से ''व्याकरणिक दृष्टि से पूर्णतः शुद्ध वाक्य'' का चयन कीजिए:', 'पिताजी के सम्मान में आदरार्थक बहुवचन ''आए हैं'' शुद्ध है; जनता एकवचन है और प्राण बहुवचन है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a64a51c4-b34f-4ff2-b086-8e6930f00549', '''कल रात मेरे पिताजी दिल्ली से लौट आए हैं।'' (आदरार्थक बहुवचन क्रिया का शुद्ध प्रयोग)', true, '1fa60b6f-0974-4651-8421-ac139355345d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91e85419-2341-446b-ac86-1de5510a5c5a', '''कल रात मेरा पिताजी दिल्ली से लौट आया।''', false, '1fa60b6f-0974-4651-8421-ac139355345d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11f307bb-6a27-43a1-a5b2-bebf1a85e291', '''वहाँ बहुत सारे जनता उपस्थित थे।''', false, '1fa60b6f-0974-4651-8421-ac139355345d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('276b9ec9-0f63-47f9-9eed-c326729292c3', '''उसका प्राण निकल गया।''', false, '1fa60b6f-0974-4651-8421-ac139355345d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b63a651-d483-4958-bc79-4b35202c7d19', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'निम्नलिखित में से किस विकल्प के सभी शब्द ''पुल्लिंग'' हैं?', 'दूध, दही, मोती, पानी, घी, रत्न (हीरा, पन्ना) और पर्वत (हिमालय) सभी शुद्ध पुल्लिंग शब्द हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('040aed84-dcd4-4de4-9039-41dd978cfb4a', 'दूध, दही, मोती, पानी, घी, हीरा, पन्ना, हिमालय', true, '6b63a651-d483-4958-bc79-4b35202c7d19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb27c527-a1d2-4581-8e3b-b4815d916bd7', 'गंगा, यमुना, देवनागरी, रोटी, दाल', false, '6b63a651-d483-4958-bc79-4b35202c7d19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('030986bf-20a6-4f1f-b7a1-f5d261127f7e', 'पुस्तक, कलम, मेज, कुर्सी', false, '6b63a651-d483-4958-bc79-4b35202c7d19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc0b5a05-3cd4-4cee-b597-3cfcf1f397bf', 'मक्खी, कोयल, तितली, चील', false, '6b63a651-d483-4958-bc79-4b35202c7d19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92dc9a85-8ee5-480b-a049-0a5ffc154641', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''भविष्यद्वक्ता'' शब्द का सही स्त्रीलिंग रूप क्या होगा?', 'वक्ता→वक्त्री के नियमानुसार ''भविष्यद्वक्ता'' का स्त्रीलिंग ''भविष्यद्वक्त्री'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e1503f-8d65-40f2-b63c-91959da6241c', 'भविष्यद्वक्त्री', true, '92dc9a85-8ee5-480b-a049-0a5ffc154641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb022a3c-e00b-48f3-80d0-5f732cc1ef40', 'भविष्यद्वक्ताइन', false, '92dc9a85-8ee5-480b-a049-0a5ffc154641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ab42e09-78f9-4395-b224-ab92ff54b631', 'भविष्यद्वक्तानी', false, '92dc9a85-8ee5-480b-a049-0a5ffc154641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e52d309-c7c4-40ef-b766-47c39fb0a247', 'भविष्यद्वक्तिन', false, '92dc9a85-8ee5-480b-a049-0a5ffc154641');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fe8dbe9-a020-4029-bc26-33b3040a7830', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''ताश के पत्तों में राजा और रानी होते हैं।'' वाक्य में ''राजा'' का स्त्रीलिंग ''रानी'' है। ''नर'' का स्त्रीलिंग ''नारी'' है। ''युवक'' का स्त्रीलिंग क्या होगा?', '''युवक'' का मानक तत्सम स्त्रीलिंग ''युवती'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03df8b27-b313-43c1-984e-406fbb38d170', 'युवती', true, '9fe8dbe9-a020-4029-bc26-33b3040a7830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1be36f2-a366-4e76-b2cf-ff956b323ba1', 'युवकी', false, '9fe8dbe9-a020-4029-bc26-33b3040a7830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97f36395-97db-4e5b-bc11-71ff80094664', 'युवतिन', false, '9fe8dbe9-a020-4029-bc26-33b3040a7830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67ab445b-b362-4848-86ec-4d7c7d0ef24c', 'तरुणी', false, '9fe8dbe9-a020-4029-bc26-33b3040a7830');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d75e87dd-21ea-4faf-839c-592358dd312f', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''ऋषि'' शब्द का सही स्त्रीलिंग रूप क्या होगा?', '''ऋषि'' का वैदिक एवं मानक स्त्रीलिंग ''ऋषिका'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b32b7a-ec0d-4a1e-8ba1-ac864ee928b9', 'ऋषिका', true, 'd75e87dd-21ea-4faf-839c-592358dd312f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5d75b0e-c2d1-4d7e-afd1-e74efd61ce8b', 'ऋषिणी', false, 'd75e87dd-21ea-4faf-839c-592358dd312f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1860cc44-f4bd-46f0-b846-3dec6ae4ee34', 'ऋषिन', false, 'd75e87dd-21ea-4faf-839c-592358dd312f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69402bdd-d8db-4cad-b801-133b51f880af', 'ऋषी', false, 'd75e87dd-21ea-4faf-839c-592358dd312f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7cf98d78-6a00-48da-8e9b-90380af338c7', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'लिंग और वचन (Gender & Number Agreement) के सम्यक ज्ञान का हिंदी वाक्य-रचना और क्रिया-अन्विति में क्या सर्वोच्च महत्व है?', 'हिंदी एक अत्यधिक अन्विति-प्रवण (Agreement-rich) भाषा है, जहाँ क्रिया और विशेषण का रूप लिंग-वचन के आधार पर ही निर्धारित होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a87b8401-0c1d-4fdd-84f1-817f6c933f90', 'हिंदी में क्रिया, विशेषण और सर्वनाम के रूप कर्ता और कर्म के लिंग एवं वचन के अनुसार परिवर्तित (विकृत) होते हैं ; इनके अशुद्ध ज्ञान से समूची वाक्य-संरचना अशुद्ध और हास्यास्पद हो जाती है', true, '7cf98d78-6a00-48da-8e9b-90380af338c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65195037-f808-4c7c-90e1-ee58dfb26980', 'लिंग और वचन केवल प्राथमिक कक्षाओं का विषय है', false, '7cf98d78-6a00-48da-8e9b-90380af338c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('108741a0-f52d-4336-910d-daacd9874844', 'हिंदी में लिंग और वचन का क्रिया पर कोई प्रभाव नहीं पड़ता', false, '7cf98d78-6a00-48da-8e9b-90380af338c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('304850d4-23d9-4abb-b259-bcc558a6dc96', 'इसका केवल वर्तनी में थोड़ा प्रयोग होता है', false, '7cf98d78-6a00-48da-8e9b-90380af338c7');
