INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed284e27-0d3d-4a29-b32d-fe1466e8b214', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What are the small vegetative scars/notches on a Potato tuber that contain buds capable of growing into new potato plants called?', 'Potato tubers are modified underground storage stems with nodal ''eyes'' containing vegetative axillary buds.', NOW()) ON CONFLICT DO NOTHING;
