INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99b7058c-9fd1-4da7-a053-ac1d4c9652b9', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'Which plant reproduces vegetatively by producing adventitious vegetative buds along the margins of its thick fleshy LEAVES?', 'Bryophyllum reproduces foliar vegetatively: marginal leaf notches develop adventitious plantlets that root upon falling onto moist soil.', NOW()) ON CONFLICT DO NOTHING;
