INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2508dd8f-b308-407d-a35d-cb1005643ea4', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What is the primary reproductive organ of a flowering plant for Sexual Reproduction?', 'Flowers are specialized angiosperm reproductive shoots bearing male (stamens) and female (carpels/pistils) organs.', NOW()) ON CONFLICT DO NOTHING;
