INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dadbd5c2-3f3c-4dd2-9cf7-67614b8d42e6', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What is the MALE reproductive organ of a flower called, consisting of an Anther and Filament?', 'The stamen is the male floral organ comprising a filament supporting a terminal anther that synthesizes pollen grains.', NOW()) ON CONFLICT DO NOTHING;
