INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d44ec1a-7487-4ccf-a961-37e1fed5cbe3', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What is the FEMALE reproductive organ of a flower called, consisting of Stigma, Style, and Ovary?', 'The pistil/carpel consists of a receptive stigma, slender style, and a basal ovary enclosing ovules with egg cells.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39980dea-b765-45b4-aaad-bc6f594da6f5', 'Pistil (or Carpel / Gynoecium)', true, '5d44ec1a-7487-4ccf-a961-37e1fed5cbe3');
