INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0c38f88-3390-43c1-9b88-881082947af3', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'Flowers that contain EITHER only stamens (male) OR only pistils (female) — like Papaya, Corn, and Cucumber — are called:', 'Unisexual (imperfect) flowers possess either androecium or gynoecium exclusively (e.g. dioecious papaya, monoecious maize).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20dd67c0-a2ae-44d0-8158-52513af2268a', 'Unisexual Flowers', true, 'c0c38f88-3390-43c1-9b88-881082947af3');
