INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('051d30e7-3de8-429d-8b34-7dd92fed24b3', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'Flowers that contain BOTH stamens and pistil within the same flower — like Mustard, Rose, and Petunia — are called:', 'Bisexual (hermaphroditic/perfect) flowers bear functional stamens and carpels in the same floral whorl.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91d77ded-ed0b-4cb6-a271-82edf846f14e', 'Bisexual Flowers (Hermaphrodite)', true, '051d30e7-3de8-429d-8b34-7dd92fed24b3');
