INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77394d5c-0b2a-45a6-a522-ba556070f76e', 'Sterile Flowers', false, '051d30e7-3de8-429d-8b34-7dd92fed24b3');
