INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3f96a6f-a9b2-4626-b6e5-f6209f2d7820', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'The transfer of pollen grains from the anther to the stigma of a flower is called:', 'Pollination is the mechanical transference of pollen grains from anther to receptive stigma by wind, water, or biotic vectors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32684625-c63e-4c48-b6d8-0923b5304733', 'Pollination', true, 'c3f96a6f-a9b2-4626-b6e5-f6209f2d7820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c4c69eb-37e0-4b75-85ae-0f37df1bbe28', 'Fertilization', false, 'c3f96a6f-a9b2-4626-b6e5-f6209f2d7820');
