INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eae6ee3b-0b14-4c02-b7bb-86f9c5d475e6', 'Germination', false, 'c3f96a6f-a9b2-4626-b6e5-f6209f2d7820');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac0637eb-fe48-43bd-bea4-94f99836e3de', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'The process of fusion of the male gamete with the female gamete (egg cell) to form a single-celled ZYGOTE is called:', 'Fertilization (syngamy) is the fusion of haploid male and female gametic nuclei inside the embryo sac to form a diploid zygote.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af203f9a-7cb5-4b16-979b-d7b7d5583629', 'Fertilization (Syngamy)', true, 'ac0637eb-fe48-43bd-bea4-94f99836e3de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ead0c622-2684-4397-b231-3941fb8a065f', 'Pollination', false, 'ac0637eb-fe48-43bd-bea4-94f99836e3de');
