INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d63be54-a482-433a-b097-4b1daebade8a', 'Fragmentation', false, 'ac0637eb-fe48-43bd-bea4-94f99836e3de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e80a92fb-b319-4b1b-963d-10d1923ed19f', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How does single-celled Yeast reproduce asexually under favorable nutrient conditions?', 'Yeast multiplies rapidly via asymmetric mitotic budding: blastospores pinch off or form pseudo-mycelial chains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4ffd6be-c50e-4507-9bf2-65140a182622', 'By BUDDING: a small bulb-like projection (bud) gradually grows from the parent cell, receives a replicated nucleus, and detaches to form a new yeast cell', true, 'e80a92fb-b319-4b1b-963d-10d1923ed19f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b26c4fa4-c605-47fb-b3c9-14b513dd52b2', 'By producing large flowers', false, 'e80a92fb-b319-4b1b-963d-10d1923ed19f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86611a37-1920-4c36-8861-4e237518db47', 'By laying eggs', false, 'e80a92fb-b319-4b1b-963d-10d1923ed19f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d00908c8-82d9-45dc-90a8-267844f9b73a', 'By forming seeds inside fruits', false, 'e80a92fb-b319-4b1b-963d-10d1923ed19f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('084ab409-c161-4714-8049-9d08dabcdfce', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How do green filamentous Algae (like Spirogyra) multiplying rapidly in stagnant ponds reproduce asexually?', 'Spirogyra undergoes vegetative fragmentation: mechanical cleavage of multicellular filaments yields independent surviving clones.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('446545b2-d09d-4fd5-ae6e-521fcf50cd70', 'By FRAGMENTATION: the long green filament breaks into two or more fragments, and each fragment grows into a complete new individual', true, '084ab409-c161-4714-8049-9d08dabcdfce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6af18a0-b6ca-4b10-8fff-382be8b2315b', 'By flying through the air', false, '084ab409-c161-4714-8049-9d08dabcdfce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03383f10-52f1-4eb7-95a2-9a01da2ddbb9', 'By forming woody cones', false, '084ab409-c161-4714-8049-9d08dabcdfce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e0b16d0-7d70-4cce-9212-0709e0d65b74', 'By underground tubers', false, '084ab409-c161-4714-8049-9d08dabcdfce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbf62c49-3e15-46bb-90c4-c2cd7a01823c', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How do Fungi (like Bread Mold / Rhizopus), Mosses, and Ferns reproduce asexually?', 'Sporogenesis: sporangiophores bear resistant haploid sporangiospores capable of withstanding environmental desiccation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f95fa90-08ed-4f13-9f46-9c804454767a', 'By SPORE FORMATION: microscopic spores protected by a hard, thick protective coat inside Sporangia disperse in air and germinate in moist conditions', true, 'fbf62c49-3e15-46bb-90c4-c2cd7a01823c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f8c9e92-c55e-473a-b61c-255835d0d527', 'By producing honey', false, 'fbf62c49-3e15-46bb-90c4-c2cd7a01823c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f4beff4-161b-471c-ba48-0aba7c709d47', 'By seeds in fruits', false, 'fbf62c49-3e15-46bb-90c4-c2cd7a01823c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94a3eafc-2b84-4892-9a77-cb7695987320', 'By root cuttings only', false, 'fbf62c49-3e15-46bb-90c4-c2cd7a01823c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0612bc5b-43cf-48a0-bc71-ee85c190a915', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'What is the difference between SELF-POLLINATION and CROSS-POLLINATION?', 'Self-pollination (autogamy/geitonogamy) transfers pollen within the same genetic individual; cross-pollination (xenogamy) transfers pollen between distinct plants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a2962b5-cc2c-4c06-8b8b-8a597d149a7c', 'Self-pollination occurs when pollen lands on the stigma of the SAME flower or another flower on the SAME plant ; Cross-pollination occurs when pollen lands on a flower of a DIFFERENT plant of the same kind', true, '0612bc5b-43cf-48a0-bc71-ee85c190a915');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22e8571a-52b1-4d1b-bcbe-293848a6f951', 'Self-pollination is done by birds only', false, '0612bc5b-43cf-48a0-bc71-ee85c190a915');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c18c822-ea7f-4efd-b263-c40a9aac1bfa', 'Cross-pollination occurs only in winter', false, '0612bc5b-43cf-48a0-bc71-ee85c190a915');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa7b3b3c-eb09-4762-8963-533395a49ab8', 'Both are identical processes', false, '0612bc5b-43cf-48a0-bc71-ee85c190a915');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4a5aceb-57d7-46ea-993c-3cd5eee11e64', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'After successful fertilization in a flower, what do the OVARY and the OVULE develop into?', 'Post-fertilization morphogenesis: pericarp ovary wall develops into fruit; fertilized integumented ovules mature into seeds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5557be8b-c729-43db-87c4-3272c8b92f8a', 'The OVARY ripens into the FRUIT ; and the OVULES develop into SEEDS containing the embryo', true, 'd4a5aceb-57d7-46ea-993c-3cd5eee11e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b7b17da-0b81-489a-9155-434e71cc780f', 'The ovary becomes a leaf and ovule becomes a flower', false, 'd4a5aceb-57d7-46ea-993c-3cd5eee11e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('badbd93b-9080-4aca-864c-ae73040e6186', 'The ovary becomes root and ovule becomes stem', false, 'd4a5aceb-57d7-46ea-993c-3cd5eee11e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdd412b8-49da-433b-9300-78d37786cb4d', 'Both turn into pollen grains', false, 'd4a5aceb-57d7-46ea-993c-3cd5eee11e64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba9e0624-b719-47ae-b424-02c8088235f4', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Which of the following plants reproduces vegetatively through modified underground STEM RHIZOMES containing nodes and scaly buds?', 'Ginger (Zingiber) and Turmeric (Curcuma) propagate vegetatively via horizontal subterranean rhizomes bearing dormant axillary buds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80fc8dfd-2fa9-43ba-b9a2-3fd2bd71ff37', 'Ginger and Turmeric', true, 'ba9e0624-b719-47ae-b424-02c8088235f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2c32cfb-8b86-4d4f-bce1-5d513abc7bfd', 'Sweet Potato', false, 'ba9e0624-b719-47ae-b424-02c8088235f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2646f478-6420-4769-957c-5bfc75a18989', 'Dahlia', false, 'ba9e0624-b719-47ae-b424-02c8088235f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af0b904a-a912-4cc8-8917-83703d792db7', 'Bryophyllum', false, 'ba9e0624-b719-47ae-b424-02c8088235f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc86a289-a3b8-4f51-964f-d7442c98a0d5', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Which plants reproduce vegetatively through fleshy swollen ROOT TUBERS?', 'Sweet potato (Ipomoea batatas) and Dahlia develop adventitious root tubers that sprout vegetative shoots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b73ca3a2-6228-465a-ad38-390856a6e0b7', 'Sweet Potato and Dahlia', true, 'cc86a289-a3b8-4f51-964f-d7442c98a0d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10354f6d-0264-4d6d-a225-c66544d3d193', 'Potato and Ginger', false, 'cc86a289-a3b8-4f51-964f-d7442c98a0d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9f50bd5-2c39-45e8-85d7-bfd9bd2522b5', 'Rose and Jasmine', false, 'cc86a289-a3b8-4f51-964f-d7442c98a0d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ba41f16-c0ec-4c3e-9b8d-1032733ad63f', 'Bryophyllum', false, 'cc86a289-a3b8-4f51-964f-d7442c98a0d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84b1d706-c3c6-4d1c-8089-613aa54c9628', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Why are light, winged seeds (such as Drumstick and Maple) and hairy parachutes (such as Aak / Madar and Dandelion) dispersed by WIND?', 'Anemochory adaptations: aerodynamic samara wings (Acer, Moringa) and pappus hair tufts (Calotropis, Taraxacum) facilitate wind buoyancy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a942e1b8-5ee6-4a9c-b08a-74f85ee9e284', 'Their lightweight wings and tufts of fine hair act like aerodynamic sails and parachutes, allowing air currents to carry them far away', true, '84b1d706-c3c6-4d1c-8089-613aa54c9628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('123f9dde-ed36-4e0d-adcc-5e061739baaf', 'Because wind eats the seeds', false, '84b1d706-c3c6-4d1c-8089-613aa54c9628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec573bfd-b0e4-4b23-bba2-4125c7c1f098', 'Because birds blow on them', false, '84b1d706-c3c6-4d1c-8089-613aa54c9628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f435a799-06da-4f83-85cb-f3f337a18e78', 'Because they are sticky', false, '84b1d706-c3c6-4d1c-8089-613aa54c9628');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b78d5a40-89cf-4a30-acd0-2b9bb493f7b3', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How are fibrous, buoyant fruits like the Coconut (Cocos nucifera) dispersed across distant islands?', 'Hydrochory adaptation: fibrous air-trapping coir mesocarp and impervious endocarp allow coconuts to float across marine currents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('024ea014-5f37-4dde-acff-bdaa992bec8e', 'By WATER: the thick, spongy, fibrous mesocarp traps air, making coconuts float effortlessly across ocean waves for thousands of miles', true, 'b78d5a40-89cf-4a30-acd0-2b9bb493f7b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa9aeb99-4f91-47f2-b1d4-028276a010d1', 'By wind blowing them in clouds', false, 'b78d5a40-89cf-4a30-acd0-2b9bb493f7b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16c167e0-fe32-476b-8463-a82730e0ce27', 'By birds carrying whole coconuts', false, 'b78d5a40-89cf-4a30-acd0-2b9bb493f7b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b33fff4-8b04-4d46-b3c7-b1c745447584', 'By exploding into pieces', false, 'b78d5a40-89cf-4a30-acd0-2b9bb493f7b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8af3e27e-f190-445b-ac7d-d1893e8b2eae', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How are spiny seeds equipped with sharp hooks (such as Xanthium and Urena) dispersed to new habitats?', 'Epizoochory adaptation: stiff hooked spines on Xanthium burs latch onto animal pelts and fleece for long-distance transport.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51eccd38-671b-4386-87b0-fb48f3c608dc', 'By ANIMALS: their hooked spines cling stubbornly to the fur of passing animals or human clothing and get transported far away', true, '8af3e27e-f190-445b-ac7d-d1893e8b2eae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccb02617-67bf-422d-9984-cb849578a766', 'By swimming in rivers', false, '8af3e27e-f190-445b-ac7d-d1893e8b2eae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad31b16a-33be-42f5-a046-1bf6124709a0', 'By flying with wings', false, '8af3e27e-f190-445b-ac7d-d1893e8b2eae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21232f59-3a29-4763-8aa8-74b9e413c56a', 'By melting in the sun', false, '8af3e27e-f190-445b-ac7d-d1893e8b2eae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('906fad04-31ac-4388-b147-57ae83d59101', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How do Castor and Balsam plants disperse their seeds through sudden explosive mechanical action?', 'Autochory / Ballochory: desiccation creates hygroscopic tissue tension that ruptures the capsule explosively, projecting seeds meters away.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd7242e8-678a-4c3c-954d-68af4f77fede', 'Their ripe seed pods burst open suddenly with explosive jerks upon drying, flinging the seeds forcefully far away from the parent plant', true, '906fad04-31ac-4388-b147-57ae83d59101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d9b519b-143e-4885-a124-ddda0631624d', 'By floating in water', false, '906fad04-31ac-4388-b147-57ae83d59101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8f9e41b-d662-4d49-b6fd-bb8e54ef0f42', 'By emitting sweet perfume', false, '906fad04-31ac-4388-b147-57ae83d59101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc3c2f40-61b6-44f0-a06b-780375ecee78', 'By growing underground', false, '906fad04-31ac-4388-b147-57ae83d59101');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d23b8d9-3954-415b-9033-53fb3ff65a82', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'What is the horticultural advantage of Vegetative Propagation (like stem cuttings in Roses, Sugarcane, and Grapes) for farmers?', 'Vegetative cloning bypasses juvenile seed dormancy, accelerates fruiting, and guarantees 100% true-to-type genetic fidelity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01c5be44-4266-41c2-a331-772771e252cd', 'Plants grown vegetatively take much less time to bear flowers and fruits, and are exact genetic clones preserving all desirable parental qualities', true, '9d23b8d9-3954-415b-9033-53fb3ff65a82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed6e975b-c560-452e-aa0d-0b635c80c86d', 'They produce seeds with random changes', false, '9d23b8d9-3954-415b-9033-53fb3ff65a82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fb077ed-3ca4-49af-9a31-de1021c5c10d', 'They do not need water or soil', false, '9d23b8d9-3954-415b-9033-53fb3ff65a82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('871895f5-76e4-48f3-8e4e-afb095860dd8', 'They never grow leaves', false, '9d23b8d9-3954-415b-9033-53fb3ff65a82');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f47be50b-b295-4749-a61a-d62d6bb67bf4', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'What grows out of a pollen grain after it lands on the sticky receptive stigma of a compatible flower?', 'Chemotropic pollen tube germination: the tube cell elongates through stylar transmitting tissue, conveying sperm nuclei to the micropyle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1280d5d6-4870-4388-baf9-f4307c7fc0f2', 'A long Pollen Tube that grows downwards through the style to deliver male gametes into the ovary''s ovule', true, 'f47be50b-b295-4749-a61a-d62d6bb67bf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a672fb-62fa-4485-8834-d28476714557', 'A new green leaf', false, 'f47be50b-b295-4749-a61a-d62d6bb67bf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bfba81e-8f34-47b9-914d-6d7a8620565f', 'A root hair', false, 'f47be50b-b295-4749-a61a-d62d6bb67bf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93f93e00-2ddd-4517-9a72-56ec4edb05c6', 'A seed coat', false, 'f47be50b-b295-4749-a61a-d62d6bb67bf4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82ee0b95-0348-4219-9bf6-2cea4b48ba08', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Why do insect-pollinated flowers (like Rose, Jasmine, and Sunflower) possess brightly colored petals, sweet fragrance, and sugary nectar?', 'Entomophilous floral syndrome: chromatic showy corollas, volatile terpenes, and nectar rewards co-evolved to attract insect pollinators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9751d1e6-8b7e-4a1f-8a82-c7236901d466', 'To attract insect pollinators (bees, butterflies) which brush against anthers and carry sticky pollen grains to other flowers', true, '82ee0b95-0348-4219-9bf6-2cea4b48ba08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84c099ed-4486-4948-8fdf-c6bee3b6470b', 'To scare away all insects', false, '82ee0b95-0348-4219-9bf6-2cea4b48ba08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be2845ff-8383-4d6c-88be-d53e600ac2af', 'To cool the flower during hot days', false, '82ee0b95-0348-4219-9bf6-2cea4b48ba08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e02c272-db66-491e-aea9-e074ebb5737b', 'To produce green chlorophyll', false, '82ee0b95-0348-4219-9bf6-2cea4b48ba08');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c026511-d1fd-4ab9-b1cd-021ccf40a37f', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'What are the distinguishing characteristics of Wind-Pollinated flowers (like Grasses, Corn, and Wheat)?', 'Anemophilous floral syndrome: reduced perianth, non-sticky aerodynamically buoyant pollen produced in billions, and plumose stigmas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6ac7131-3d2a-4838-8f31-910817a1c86d', 'They have small, dull non-scented flowers, enormous quantities of light dry powdery pollen, and large feathery stigmas exposed to catch windborne pollen', true, '7c026511-d1fd-4ab9-b1cd-021ccf40a37f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d750461-828a-4922-8b8d-045a5460ffc6', 'They have giant sweet-smelling red petals', false, '7c026511-d1fd-4ab9-b1cd-021ccf40a37f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5176e0d3-0427-4778-9772-58db3dfee4f6', 'They produce thick sticky nectar', false, '7c026511-d1fd-4ab9-b1cd-021ccf40a37f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37a9c76b-0489-4678-90e2-6baf559650f4', 'They open only underwater', false, '7c026511-d1fd-4ab9-b1cd-021ccf40a37f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('249f38f6-85fc-4b75-ba54-7303f26a23f7', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Why is Seed Dispersal essential for the healthy survival and distribution of plant species?', 'Seed dispersal reduces density-dependent sibling competition, mitigates pathogen transmission, and colonizes novel ecological niches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('119cde1d-05cb-4760-bd71-ba66f58b8d87', 'It prevents intense competition for sunlight, water, minerals, and space among seedlings near the parent plant, while invading new geographic habitats', true, '249f38f6-85fc-4b75-ba54-7303f26a23f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a48ba37-231f-46c4-a40b-b4aa840d2e68', 'It destroys old plants', false, '249f38f6-85fc-4b75-ba54-7303f26a23f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee5dfa54-aa05-4960-a2be-622d6e8ecbf3', 'It keeps all seeds in one single spot', false, '249f38f6-85fc-4b75-ba54-7303f26a23f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db24ec8c-45db-48c8-8369-381a0ed4bc85', 'It stops plants from growing', false, '249f38f6-85fc-4b75-ba54-7303f26a23f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88c9a552-48f9-4bec-84a4-89bc0b663ecf', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c31d32ba-a583-436f-aae3-65525bf02026', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '88c9a552-48f9-4bec-84a4-89bc0b663ecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13ce7a52-6021-4a39-b8a7-cc82f9e29bd7', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '88c9a552-48f9-4bec-84a4-89bc0b663ecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da2c00ad-6749-4f4a-be63-60000571dab3', '(A) is true, but (R) is false.', false, '88c9a552-48f9-4bec-84a4-89bc0b663ecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('366fd317-21c6-4280-a873-a756f884af05', '(A) is false, but (R) is true.', false, '88c9a552-48f9-4bec-84a4-89bc0b663ecf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ea67efa-7d46-4f10-8b07-224ff0c220d3', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Spot the IMPOSTER in the following group of Plants and their specific Modes of Asexual Reproduction:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb4e4726-8453-4a7b-ba36-3cab4dbeb208', 'Mode 1', false, '7ea67efa-7d46-4f10-8b07-224ff0c220d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d176567e-2be6-46c5-ada6-64d5811432fb', 'Mode 2', false, '7ea67efa-7d46-4f10-8b07-224ff0c220d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9be5b11-4fe9-485e-8fcf-8f08656cedb3', 'Mode 3', false, '7ea67efa-7d46-4f10-8b07-224ff0c220d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87a05b04-3dd7-4038-b2fe-5be12e975149', 'Mode 4 (Mango and Apple trees reproduce sexually via SEEDS in fruits ; foliar leaf budding occurs in BRYOPHYLLUM)', true, '7ea67efa-7d46-4f10-8b07-224ff0c220d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44e36ec4-e668-45be-8eea-afa1c4b74a8f', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Trace the chronological sequence of events in Angiosperm Sexual Reproduction:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8443a884-7de1-4e5e-b5fc-377076024592', 'The EMBRYO protected within the seed coat alongside nutritive cotyledons', true, '44e36ec4-e668-45be-8eea-afa1c4b74a8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a365afb7-2cf9-4037-91f7-1adc2f1025ff', 'The Pericarp fruit wall', false, '44e36ec4-e668-45be-8eea-afa1c4b74a8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cbf8a6a-6346-499c-8f18-56ac2783e76e', 'The Style', false, '44e36ec4-e668-45be-8eea-afa1c4b74a8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8f2c53d-3780-4efb-afdc-7a87ea4754c5', 'The Filament', false, '44e36ec4-e668-45be-8eea-afa1c4b74a8f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50cb4235-bc62-4b05-82bf-83aa3c122a3c', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Match Column I (Seed Dispersal Mechanisms) with Column II (Classic Botanical Plant Examples):
(a) Wind Dispersal (Wings / Hairs)      -> (i) Drumstick (Moringa), Maple, Aak (Madar), Dandelion
(b) Water Dispersal (Fibrous Buoyancy)   -> (ii) Coconut, Lotus water lily
(c) Animal Dispersal (Hooked Spines)     -> (iii) Xanthium, Urena, Tribulus (Gokhru)
(d) Explosive Bursting Mechanism         -> (iv) Balsam (Impatiens), Castor (Ricinus)', 'Exact botanical mapping: Wind = Moringa/Acer; Water = Coconut; Animal = Xanthium hooks; Explosive = Balsam/Castor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1745a73-3c10-47d9-839e-50a6656d4308', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '50cb4235-bc62-4b05-82bf-83aa3c122a3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6a36728-c3c9-487a-9b69-cc90ce29262e', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '50cb4235-bc62-4b05-82bf-83aa3c122a3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb3076e8-15d4-43c2-bbe9-2f0567a1b046', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '50cb4235-bc62-4b05-82bf-83aa3c122a3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c7072cd-1b7d-4a13-b404-6e40eed45ed2', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '50cb4235-bc62-4b05-82bf-83aa3c122a3c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69e7bd74-ce59-4c24-bad1-366467d7737c', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Read the statements regarding floral anatomy and reproduction:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7cb7e2f-663c-4d64-8938-0dcf8d88e22b', 'Statements 1 and 2 only', true, '69e7bd74-ce59-4c24-bad1-366467d7737c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('590e516b-77f0-4166-91b9-c6f09da26f2d', 'Statements 2 and 3 only', false, '69e7bd74-ce59-4c24-bad1-366467d7737c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e71c4c6-59ba-4053-86e8-aba92ceb6ed8', 'Statements 1 and 3 only', false, '69e7bd74-ce59-4c24-bad1-366467d7737c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74d25d6e-d7b2-47e5-884d-fdf1cd7ae10d', 'All Statements 1, 2, and 3', false, '69e7bd74-ce59-4c24-bad1-366467d7737c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bda92349-88c3-41de-8f67-c13eae4abaa7', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'What prevents the germination of foreign pollen grains when pollen from an unrelated species lands on a flower''s stigma (e.g. grass pollen on a rose stigma)?', 'Pollen-pistil biochemical dialogue mediated by S-RNases and stylar lectins enforces species-specific compatibility and self-incompatibility.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e6cce44-4675-4e1a-a401-3e1cdcafccdc', 'Biochemical Pollen-Pistil Incompatibility: specific protein ligand-receptor interactions on the stigma surface recognize and inhibit foreign pollen hydration and tube germination', true, 'bda92349-88c3-41de-8f67-c13eae4abaa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56f8f43b-2d13-4c96-9c7f-6df45bead4c0', 'Insects wash the pollen away with water', false, 'bda92349-88c3-41de-8f67-c13eae4abaa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1183f476-591e-488d-9ecc-348586d7dd3c', 'The style closes with a physical gate', false, 'bda92349-88c3-41de-8f67-c13eae4abaa7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02778586-6609-4c41-b649-c9e6ed236a24', 'Pollen grains turn into sugar', false, 'bda92349-88c3-41de-8f67-c13eae4abaa7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54fb3d05-6e5d-42fc-a051-8955305d6741', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Consider four plant propagation methods:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ada35c9-6134-4e84-a559-c0a2368ebd7f', 'Methods 1, 2, and 3 only (Vegetative Asexual Propagation)', true, '54fb3d05-6e5d-42fc-a051-8955305d6741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7839c0d2-db05-4395-9fb2-45ea765abd7e', 'Method 4 only', false, '54fb3d05-6e5d-42fc-a051-8955305d6741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f0bd7ab-9d3b-4541-ac2e-eb0750f51413', 'Methods 2 and 4 only', false, '54fb3d05-6e5d-42fc-a051-8955305d6741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76ee1c18-210e-429d-b334-28db19f4c5fa', 'All 1, 2, 3, and 4', false, '54fb3d05-6e5d-42fc-a051-8955305d6741');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9066096-21b4-4ad1-bc71-c10fe9e93ca8', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Why do Spores produced by Fungi (Bread Mold) and Mosses survive extreme harsh conditions (heat, freezing cold, lack of moisture) for years?', 'Spore sporopollenin / chitinous protective perispores confer extreme thermotolerance and cryptobiotic resistance against drought.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9726bfd-0c01-4bd5-a047-358f942ebaab', 'Each spore is encapsulated in a thick, resilient, desiccation-resistant protective wall that remains dormant until moisture and warmth trigger germination', true, 'a9066096-21b4-4ad1-bc71-c10fe9e93ca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec7da9fc-f17d-49bd-b0fa-27757bd3ff9d', 'Spores produce their own heat', false, 'a9066096-21b4-4ad1-bc71-c10fe9e93ca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('111edcfd-851e-4ad6-b0ca-a12e33d2b5f4', 'Spores are made of pure stone', false, 'a9066096-21b4-4ad1-bc71-c10fe9e93ca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4e6eb73-13c8-48a9-9892-fb4558f9359d', 'Spores are protected by adult animals', false, 'a9066096-21b4-4ad1-bc71-c10fe9e93ca8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e060cfe2-3dcb-4e81-b29b-52f859a1e7c9', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'What is ''Parthenocarpy'' observed in commercial fruits like Seedless Bananas and Seedless Grapes?', 'Parthenocarpy is the hormonal induction of ovarian development into edible fleshy fruits in the absence of ovular fertilization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d57ea81-47d8-4ea7-9321-d92edc9178ff', 'The development of fleshy fruit WITHOUT prior fertilization of ovules, resulting in seedless edible fruits', true, 'e060cfe2-3dcb-4e81-b29b-52f859a1e7c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f0c331e-c8a1-4b5f-8074-3bbb10c90505', 'Fruits growing on plant roots', false, 'e060cfe2-3dcb-4e81-b29b-52f859a1e7c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc80eb01-8274-4959-9f0f-18db35ae3aef', 'Fruits formed from leaves', false, 'e060cfe2-3dcb-4e81-b29b-52f859a1e7c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18e2f302-e070-4ad5-9804-e4b037cfa26f', 'Flowers turning into seeds without petals', false, 'e060cfe2-3dcb-4e81-b29b-52f859a1e7c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('259698d0-f80c-4f59-9590-bfae1c5130ac', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'In unisexual dioecious plant species (like Papaya and Date Palm), what agricultural practice must farmers adopt to ensure good fruit yield?', 'In dioecious crops, female pistillate trees require staminate male trees in proximity (approx 1:10 ratio) for wind/insect pollination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84cbea28-dbfc-4ca9-a869-a59d78c623ac', 'They must plant a balanced ratio of male (staminate) trees alongside female (pistillate) trees in the orchard to guarantee cross-pollination', true, '259698d0-f80c-4f59-9590-bfae1c5130ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9be5a0e2-e5d4-407e-a57c-eea21b49d48e', 'Plant only male trees', false, '259698d0-f80c-4f59-9590-bfae1c5130ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1db3ec87-ca42-40cd-a31f-65895979a8cc', 'Cut down all flowers in winter', false, '259698d0-f80c-4f59-9590-bfae1c5130ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7c3a80b-cdc9-4390-95e4-392ac2071f84', 'Keep trees in dark rooms', false, '259698d0-f80c-4f59-9590-bfae1c5130ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3c9f53f-906f-4500-a115-cdac64aa4964', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'What is the structural role of the ''Cotyledons'' in a germinating seed?', 'Cotyledons (seed leaves) store nutritive endospermic reserves mobilized by amylases to fuel early heterotrophic seedling growth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb703623-3b18-4aaa-972c-1f36c864271d', 'They store concentrated food reserves (starch, proteins, lipids) to nourish the young developing embryo seedling until it grows green leaves for photosynthesis', true, 'c3c9f53f-906f-4500-a115-cdac64aa4964');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf7abc9c-1720-4480-aa9c-fc17f469d107', 'They absorb sunlight underground', false, 'c3c9f53f-906f-4500-a115-cdac64aa4964');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f9d19be-385f-4419-aa78-83718b47c691', 'They produce flowers immediately', false, 'c3c9f53f-906f-4500-a115-cdac64aa4964');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d3c7a17-5e2f-4c39-a1da-580d0ed56850', 'They protect the seed from birds only', false, 'c3c9f53f-906f-4500-a115-cdac64aa4964');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7e25dbd-3b8a-4f69-9b20-2118c93fae21', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'What comprehensive evolutionary narrative unites Chapter 8 of NCERT Class 7 Science?', 'Chapter 8 explores the evolutionary continuum of plant reproduction: vegetative cloning, floral syngamy, embryogenesis, and diverse dispersal syndromes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b091d37-dedb-45bf-96db-ed0f9413c5fb', 'The remarkable diversity of plant reproductive strategies—balancing rapid, true-to-type asexual cloning with genetic recombination through floral cross-pollination and ingenious seed dispersal mechanisms that ensure species perpetuation across the biosphere', true, 'f7e25dbd-3b8a-4f69-9b20-2118c93fae21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d7b947-2281-461f-89fb-9a02cf184db7', 'That plants only reproduce when humans plant them', false, 'f7e25dbd-3b8a-4f69-9b20-2118c93fae21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b24df52-ec2f-48f5-a600-dc3c725772f2', 'That flowers exist only for decoration', false, 'f7e25dbd-3b8a-4f69-9b20-2118c93fae21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b789763-f612-4914-8bac-a687bd45f1e6', 'That all plants will stop reproducing in the future', false, 'f7e25dbd-3b8a-4f69-9b20-2118c93fae21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01074446-2682-4e50-921e-066473172758', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'A number that can be written in the form p/q, where p and q are integers and q ≠ 0, is called a:', 'A rational number is defined as the quotient p/q of two integers where denominator q ≠ 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e91f9bc-aa4f-4f86-96b0-cc1316dc565c', 'Rational Number', true, '01074446-2682-4e50-921e-066473172758');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6142798a-c075-4b7d-af62-432d331fddf2', 'Natural Number only', false, '01074446-2682-4e50-921e-066473172758');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8415c1cc-4e36-45cc-bdbd-3f3e327f5102', 'Whole Number only', false, '01074446-2682-4e50-921e-066473172758');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1360d7b8-7bce-4fe3-8d8f-2fde0795106a', 'Irrational Number', false, '01074446-2682-4e50-921e-066473172758');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c00275dc-a235-4666-85d8-da6ca45c895b', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'In the rational number -4/7, what are the Numerator and the Denominator?', 'In p/q, the integer p is the numerator (-4) and q is the non-zero denominator (7).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f59ed56-52ab-4dbf-ba1e-3a4d33dd88d7', 'Numerator = -4 ; Denominator = 7', true, 'c00275dc-a235-4666-85d8-da6ca45c895b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bf37083-7d7d-44f0-8419-5bad5331aa64', 'Numerator = 7 ; Denominator = -4', false, 'c00275dc-a235-4666-85d8-da6ca45c895b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a1da7de-6023-416c-b5b6-94a06fba0cd0', 'Numerator = 4 ; Denominator = 7', false, 'c00275dc-a235-4666-85d8-da6ca45c895b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70c1e455-75bb-4562-8856-5efe0640a8c9', 'Numerator = -7 ; Denominator = 4', false, 'c00275dc-a235-4666-85d8-da6ca45c895b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b647577f-fda8-40de-a303-30ab41eaadae', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'Which of the following is a POSITIVE Rational Number?', 'A rational number is positive if numerator and denominator share the same sign: (-3)/(-5) = 3/5 > 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be039089-4542-4fd1-badb-afe30ecfbe9b', '-3 / -5 (Both numerator and denominator are negative, so -3 / -5 = 3 / 5 > 0)', true, 'b647577f-fda8-40de-a303-30ab41eaadae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bad98080-c61b-4519-98ed-9e6765330255', '-3 / 5', false, 'b647577f-fda8-40de-a303-30ab41eaadae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('308bf848-59b8-4487-aa83-2472fdc5a818', '3 / -5', false, 'b647577f-fda8-40de-a303-30ab41eaadae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c388e402-a2a0-446d-81d1-3000d948f6a8', '-7 / 9', false, 'b647577f-fda8-40de-a303-30ab41eaadae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39dee1a6-3e8c-4227-b6cf-aa89f30f98ef', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'Which of the following is a NEGATIVE Rational Number?', 'A rational number is negative if numerator and denominator have opposite signs (-5/8 < 0).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c8376b4-8885-43c2-9c58-ba32f92413ba', '-5 / 8', true, '39dee1a6-3e8c-4227-b6cf-aa89f30f98ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08d5e698-bd3e-4248-ba22-049565aae30c', '3 / 7', false, '39dee1a6-3e8c-4227-b6cf-aa89f30f98ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5659b3a-37e3-47a4-ba39-03c297728c08', '-4 / -9', false, '39dee1a6-3e8c-4227-b6cf-aa89f30f98ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67b56dbc-c0af-4d95-82b5-cf8749857878', '0 / 1', false, '39dee1a6-3e8c-4227-b6cf-aa89f30f98ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3fd7207e-d443-4842-a61d-f39833419a18', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'Is the number ''0'' (Zero) a Rational Number?', '0 = 0/q (where q is any non-zero integer), so zero is a valid rational number (neither positive nor negative).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('835638d5-d68d-4e7f-8806-d168d6814c08', 'Yes, because 0 can be written as 0/1, 0/5, or 0/(-3) where denominator is non-zero', true, '3fd7207e-d443-4842-a61d-f39833419a18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b71046c-9967-4902-bb98-01ea9dfc5584', 'No, 0 is not a number', false, '3fd7207e-d443-4842-a61d-f39833419a18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12d1f56f-ccfb-4243-b196-35ab600a4bfd', 'Only in algebra', false, '3fd7207e-d443-4842-a61d-f39833419a18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('545f7139-295a-42e1-b48f-c094ba5637da', 'No, because denominator must be 0', false, '3fd7207e-d443-4842-a61d-f39833419a18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7329ae0-6776-4b35-9662-d505f3412f3a', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'Find the Standard Form (simplest reduced form) of the rational number -36 / 24:', 'Standard form: divide by GCD(36, 24) = 12 → (-36/12) / (24/12) = -3/2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd250efd-8b55-4835-8a6f-1742558d117f', '-3 / 2 (Dividing numerator and denominator by HCF = 12)', true, 'a7329ae0-6776-4b35-9662-d505f3412f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2707d72f-6ddd-40a6-9b32-a41c43808818', '-18 / 12', false, 'a7329ae0-6776-4b35-9662-d505f3412f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09bb2238-2caa-428a-a811-1d25649158d8', '-9 / 6', false, 'a7329ae0-6776-4b35-9662-d505f3412f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('346a3536-6a08-457d-9e54-f7d640e75c83', '-4 / 3', false, 'a7329ae0-6776-4b35-9662-d505f3412f3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c06d178-8b86-49ab-87ed-541d38cffba1', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'What is the Additive Inverse of the rational number 7/9?', 'The additive inverse of a/b is -a/b such that their sum equals the additive identity 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a313120-40ba-4fb6-8bba-24bcabccd230', '-7/9 (Since 7/9 + (-7/9) = 0)', true, '1c06d178-8b86-49ab-87ed-541d38cffba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31fc4ecf-ffee-4362-a1e4-28ca31107dbc', '9/7', false, '1c06d178-8b86-49ab-87ed-541d38cffba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a91f950-aa69-4e7a-881a-79a282ce7c4e', '-9/7', false, '1c06d178-8b86-49ab-87ed-541d38cffba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c6f4b5e-fe16-4726-8062-18bf076494af', '1', false, '1c06d178-8b86-49ab-87ed-541d38cffba1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8a45b52-11a7-40bb-a93a-95aacdd035d7', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'What is the Multiplicative Inverse (Reciprocal) of the rational number -5/8?', 'The multiplicative inverse of p/q is q/p such that their product equals the multiplicative identity 1.', NOW()) ON CONFLICT DO NOTHING;
