INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09e4fb6b-c43d-4029-afd6-6819d1e4ba4d', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'Which rational number has NO Multiplicative Inverse (no reciprocal)?', '0 has no reciprocal because division by zero (1/0) is mathematically undefined.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8352d16-6611-4f65-93b4-a97ec8508701', '0 (Zero, because 1/0 is undefined / division by zero is not permitted)', true, '09e4fb6b-c43d-4029-afd6-6819d1e4ba4d');
