INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('753f4ecd-ccd9-4643-862f-8ab464d3ccb5', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'Which two rational numbers are their OWN reciprocals (multiplicative inverses of themselves)?', '1/1 = 1 and 1/(-1) = -1, making 1 and -1 unique self-reciprocals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c42ed6c-b97c-4ef1-8f34-3e9ba88699ba', '1 and -1 (Reciprocal of 1 is 1 ; Reciprocal of -1 is -1)', true, '753f4ecd-ccd9-4643-862f-8ab464d3ccb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5b9ff4f-18c0-4ab7-916a-5956888ff20b', '0 and 1', false, '753f4ecd-ccd9-4643-862f-8ab464d3ccb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3ec6607-15a3-41f0-a257-76160ec9264f', '2 and -2', false, '753f4ecd-ccd9-4643-862f-8ab464d3ccb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7c1d766-17db-42fa-bb51-b31760c1a249', '1/2 and 2', false, '753f4ecd-ccd9-4643-862f-8ab464d3ccb5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3669ebfd-cae3-43aa-b8e9-4708fee3a096', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'Find the Sum: 7/3 + (-5/3):', '(7/3) + (-5/3) = (7 - 5)/3 = 2/3.', NOW()) ON CONFLICT DO NOTHING;
