INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aff4f64d-bba3-44fe-83ec-c99c9f1f4558', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Easy', 'Find the Product: (-9/2) × (-7/4):', 'Product = ((-9) × (-7)) / (2 × 4) = 63/8.', NOW()) ON CONFLICT DO NOTHING;
