INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d180e550-fd51-4996-83cc-72d16a3d060d', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'How many rational numbers exist between ANY two distinct rational numbers on the number line?', 'The set of rational numbers is dense: between any two rational numbers a and b, there exist infinitely many rational numbers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('974681ab-8d80-421b-bced-8c0ebd0c2516', 'INFINITELY MANY rational numbers (Dense Property of Rational Numbers)', true, 'd180e550-fd51-4996-83cc-72d16a3d060d');
