INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed590e66-fc9e-4d67-a87a-93f9806093ec', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the Sum: 5/4 + (-11/4):', '(5 - 11)/4 = -6/4 = -3/2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5101a490-d77d-42b8-85ea-53cbe3a015dc', '-3/2 ((5 - 11) / 4 = -6/4 = -3/2)', true, 'ed590e66-fc9e-4d67-a87a-93f9806093ec');
