INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d847b3b-9157-4692-9012-6f2d539785a0', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the Sum: (-9/10) + 22/15:', 'LCM(10, 15) = 30. (-27 + 44)/30 = 17/30.', NOW()) ON CONFLICT DO NOTHING;
