INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6ad1c15-877c-4c93-b1d1-5d133bf2d323', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the Difference: 5/63 - (-6/21):', '5/63 - (-6/21) = 5/63 + 18/63 = 23/63.', NOW()) ON CONFLICT DO NOTHING;
