INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1c3d29a-87f5-4705-aca9-2ae78a12adda', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the Value of: (-1/8) ÷ 3/4:', '(-1/8) ÷ (3/4) = (-1/8) × (4/3) = -4/24 = -1/6.', NOW()) ON CONFLICT DO NOTHING;
