INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f3a0684-4fe4-4a2d-a959-e0eb952de9e0', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Which of the following rational numbers is GREATER: -4/5 or -5/6?', '-24/30 > -25/30, hence -4/5 > -5/6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daca86a1-1d7c-4d79-8e5d-47bd277a28bf', '-4/5 is greater (Convert to common denominator 30: -4/5 = -24/30 and -5/6 = -25/30 ; Since -24 > -25, -4/5 > -5/6)', true, '8f3a0684-4fe4-4a2d-a959-e0eb952de9e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3bb0324-970f-4000-a6ee-58e2d23cbf8e', '-5/6 is greater', false, '8f3a0684-4fe4-4a2d-a959-e0eb952de9e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff8585a6-ac25-45ad-a727-e06e3aa92040', 'Both are equal', false, '8f3a0684-4fe4-4a2d-a959-e0eb952de9e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ed77be7-6757-4ad2-825d-7809a76cc9cd', 'Cannot be compared', false, '8f3a0684-4fe4-4a2d-a959-e0eb952de9e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c82ce68-1ec8-47bd-9567-482e5ac0bec7', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Express -3/5 as a rational number with Denominator = 20:', '(-3 × 4)/(5 × 4) = -12/20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0f0dc56-f564-4834-a16d-4ba662e2904d', '-12/20 (Multiply numerator and denominator by 4: (-3 × 4)/(5 × 4) = -12/20)', true, '1c82ce68-1ec8-47bd-9567-482e5ac0bec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d2ef1ed-b5bb-4e33-9b16-5d395b9cb486', '-15/20', false, '1c82ce68-1ec8-47bd-9567-482e5ac0bec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('748acd1d-e1d5-4618-8928-76d0e56e4f19', '-9/20', false, '1c82ce68-1ec8-47bd-9567-482e5ac0bec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('568ad44a-070a-4f51-a298-075bc6a40044', '12/20', false, '1c82ce68-1ec8-47bd-9567-482e5ac0bec7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1f10d31-ad4f-4c16-ab5c-e46a6b6171d4', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Which pair of rational numbers represents the SAME EQUIVALENT rational number?', '-16/20 = -4/5 and 20/(-25) = -4/5, making them strictly equivalent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b7fc159-36c2-43e4-8e60-e7b627a96fa6', '-16/20 and 20/-25 (Both simplify to -4/5 in standard form)', true, 'e1f10d31-ad4f-4c16-ab5c-e46a6b6171d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6880460e-728b-413c-ab50-13f5d8dd4fa9', '-7/21 and 3/9', false, 'e1f10d31-ad4f-4c16-ab5c-e46a6b6171d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1050e815-364b-4bf8-a380-3acb09be3bdb', '-2/-3 and 2/-3', false, 'e1f10d31-ad4f-4c16-ab5c-e46a6b6171d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cad5cac6-8873-4236-9416-34315ee882b7', '1/3 and -1/9', false, 'e1f10d31-ad4f-4c16-ab5c-e46a6b6171d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55eb9c73-0664-4cf7-ba10-32db2463f4f0', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the Value of: (-4/5) × (-5/4):', '(-4/5) × (-5/4) = 20/20 = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('935a5ea2-5d38-4a7d-9bdc-c35a0ffcd942', '1 (Product of a non-zero rational number and its reciprocal is always 1)', true, '55eb9c73-0664-4cf7-ba10-32db2463f4f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ffda89d-62db-4689-a4ec-5e98e68331c7', '-1', false, '55eb9c73-0664-4cf7-ba10-32db2463f4f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e26af2a2-c7dd-41a1-8cc4-123c075bb4f7', '0', false, '55eb9c73-0664-4cf7-ba10-32db2463f4f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56c9694c-8e9e-4fa2-851e-6d7f10d10934', '16/25', false, '55eb9c73-0664-4cf7-ba10-32db2463f4f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4de4bc39-e98e-4d67-8412-bd9391e57ab0', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the Value of: (-7/12) ÷ (-2/13):', '(-7/12) ÷ (-2/13) = (-7/12) × (-13/2) = 91/24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f22d8650-162a-437c-a2e3-90e74ebb4083', '91/24 ((-7/12) × (-13/2) = 91 / 24)', true, '4de4bc39-e98e-4d67-8412-bd9391e57ab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e1200b2-dc0b-4f3b-ab4a-26dd9d83b5a9', '-91/24', false, '4de4bc39-e98e-4d67-8412-bd9391e57ab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eece6c2-fe76-40e8-a66e-b149bbb62b48', '14/156', false, '4de4bc39-e98e-4d67-8412-bd9391e57ab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9187e9a8-f0e9-4093-b96a-47962cd7f4e9', '-14/156', false, '4de4bc39-e98e-4d67-8412-bd9391e57ab0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bc41fa4-0df2-4dbb-8f29-566ff89b6a4d', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'What number should be added to -5/8 so as to get -3/2?', 'x = -3/2 - (-5/8) = -12/8 + 5/8 = -7/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebca33f5-944b-4dc7-8fef-731d7b835017', '-7/8 (x = -3/2 - (-5/8) = -3/2 + 5/8 = (-12 + 5)/8 = -7/8)', true, '1bc41fa4-0df2-4dbb-8f29-566ff89b6a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb56bec7-9924-464a-ac44-5eab364a3c21', '7/8', false, '1bc41fa4-0df2-4dbb-8f29-566ff89b6a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a5117e7-ff01-4600-8eda-9e7fa71b4eac', '-11/8', false, '1bc41fa4-0df2-4dbb-8f29-566ff89b6a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9cb7bdb-6e71-456d-b100-aa0135587064', '-17/8', false, '1bc41fa4-0df2-4dbb-8f29-566ff89b6a4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4351533-0287-4245-9fad-817d70066626', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'What number should be subtracted from -2/3 to get -1/6?', '-2/3 - x = -1/6 → x = -2/3 + 1/6 = -3/6 = -1/2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda66312-d331-4a7e-8492-e8bbefe51b9e', '-1/2 (x = -2/3 - (-1/6) = -2/3 + 1/6 = (-4 + 1)/6 = -3/6 = -1/2)', true, 'c4351533-0287-4245-9fad-817d70066626');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03f12e10-931b-4cfe-9c50-224d86d39b39', '1/2', false, 'c4351533-0287-4245-9fad-817d70066626');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31c853e3-772e-41f3-9a0e-a8e3de6bee78', '-5/6', false, 'c4351533-0287-4245-9fad-817d70066626');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ec10dcd-917a-4633-b4b4-eb3311b11bb8', '5/6', false, 'c4351533-0287-4245-9fad-817d70066626');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2c249ba-5219-4a66-ae59-4a3c7474c462', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'The product of two rational numbers is -9/16. If one of the numbers is -4/3, find the other number:', 'x = (-9/16) ÷ (-4/3) = (-9/16) × (-3/4) = 27/64.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfb2c4e5-d92c-4415-9e49-4ebbf80adeb1', '27/64 (Other number = (-9/16) ÷ (-4/3) = (-9/16) × (-3/4) = 27 / 64)', true, 'f2c249ba-5219-4a66-ae59-4a3c7474c462');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2734c70b-27a9-40c8-9bed-4ef2f376136b', '-27/64', false, 'f2c249ba-5219-4a66-ae59-4a3c7474c462');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bba7034-251e-4aaa-8045-c6aa19db63d3', '12/48', false, 'f2c249ba-5219-4a66-ae59-4a3c7474c462');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e45f7662-4515-4be7-a07a-b3f1826246ff', '3/4', false, 'f2c249ba-5219-4a66-ae59-4a3c7474c462');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc8a6eaa-2106-4c48-95e1-eb53e62a598c', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Write three rational numbers between -2 and -1:', '-2 = -8/4 and -1 = -4/4. Intervening rational numbers: -7/4, -6/4, -5/4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7112f8d2-eeb9-44e4-a2f6-0e109a66a693', '-7/4, -6/4 (-3/2), and -5/4 (Converting to denominator 4: -8/4 and -4/4)', true, 'fc8a6eaa-2106-4c48-95e1-eb53e62a598c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c155cf0c-4f14-4b0e-a0db-d8023f039d98', '-1/2, 0, 1/2', false, 'fc8a6eaa-2106-4c48-95e1-eb53e62a598c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('484dde5c-2c53-44e8-97c6-525095d6d879', '-3, -4, -5', false, 'fc8a6eaa-2106-4c48-95e1-eb53e62a598c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c2fff15-073a-4f50-bd36-451defd5eef2', '1, 2, 3', false, 'fc8a6eaa-2106-4c48-95e1-eb53e62a598c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fdb4309-155b-48ee-977b-469eaa94f350', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Arrange the rational numbers -3/5, -2/5, -1/5 in ASCENDING order (smallest to largest):', 'With identical positive denominators, compare numerators: -3 < -2 < -1, so -3/5 < -2/5 < -1/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b672abc-40d3-4887-bd89-66d52871964f', '-3/5 < -2/5 < -1/5', true, '1fdb4309-155b-48ee-977b-469eaa94f350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e28ea88-0d0f-4973-b5c5-74b8d14f1971', '-1/5 < -2/5 < -3/5', false, '1fdb4309-155b-48ee-977b-469eaa94f350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6e56d75-7e9f-4599-958b-931dbcee970f', '-2/5 < -3/5 < -1/5', false, '1fdb4309-155b-48ee-977b-469eaa94f350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4db8407f-c9cd-4093-a542-46831f95366a', '-3/5 < -1/5 < -2/5', false, '1fdb4309-155b-48ee-977b-469eaa94f350');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c43e0ce-ef89-452c-96af-64e5a6893693', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the mean (average) of the rational numbers 1/3 and 1/2:', 'Mean = ½(1/3 + 1/2) = ½(5/6) = 5/12 (lies strictly between 1/3 and 1/2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('058471e3-96d1-46fa-8731-555dc4d0b580', '5/12 (Mean = (1/3 + 1/2) / 2 = (5/6) / 2 = 5/12)', true, '1c43e0ce-ef89-452c-96af-64e5a6893693');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e76885a4-bfa1-4f3e-b5a1-d33fe4e5a73f', '2/5', false, '1c43e0ce-ef89-452c-96af-64e5a6893693');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02fc83ba-a9d6-4d10-9e68-637bb3acce0c', '1/5', false, '1c43e0ce-ef89-452c-96af-64e5a6893693');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a24067f0-f18a-4732-9d74-785ac0727fa3', '7/12', false, '1c43e0ce-ef89-452c-96af-64e5a6893693');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f95861e7-171c-4eb5-ada2-a2931dcf4ae7', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf596335-c0c7-4086-9e15-1059a5933a2b', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'f95861e7-171c-4eb5-ada2-a2931dcf4ae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f5b4407-143a-496e-b640-8a5b6169516c', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'f95861e7-171c-4eb5-ada2-a2931dcf4ae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd7784b3-5b24-412c-aac8-42ce92d107d4', '(A) is true, but (R) is false.', false, 'f95861e7-171c-4eb5-ada2-a2931dcf4ae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('491e90f0-cf6f-477e-878d-42573063e266', '(A) is false, but (R) is true.', false, 'f95861e7-171c-4eb5-ada2-a2931dcf4ae7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49487d0b-20d7-403e-aa19-fc63c325e84b', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Spot the IMPOSTER in the following mathematical properties of Rational Numbers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cffd5b6-d8a0-43e3-aa5e-81944554b9b2', 'Property 1', false, '49487d0b-20d7-403e-aa19-fc63c325e84b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b270404c-ea5c-42da-a7ef-006fda474ccf', 'Property 2', false, '49487d0b-20d7-403e-aa19-fc63c325e84b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5af94a2-7fd9-4c27-99cf-cec8d66153b4', 'Property 3', false, '49487d0b-20d7-403e-aa19-fc63c325e84b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59e4050b-ae05-4b4b-8b66-88f5016c8fce', 'Property 4 (Subtraction is NOT commutative ; for example: 2/3 - 1/3 = 1/3 ≠ 1/3 - 2/3 = -1/3)', true, '49487d0b-20d7-403e-aa19-fc63c325e84b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5059b692-fce8-430c-98ab-33fe3651893f', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Evaluate the arithmetic expression using distributive property:
(-3/5) × (3/7) + (2/5) × (3/7):', 'Distributive property: 3/7 × (-3/5 + 2/5) = 3/7 × (-1/5) = -3/35.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('149416c0-8876-43c9-af60-ff1d6637c9f7', '-3/35 ((3/7) × (-3/5 + 2/5) = (3/7) × (-1/5) = -3 / 35)', true, '5059b692-fce8-430c-98ab-33fe3651893f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('190df111-a167-4b01-ad4d-2d42ec45013f', '3/35', false, '5059b692-fce8-430c-98ab-33fe3651893f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3d1fa61-95e3-4889-8d6f-df9ade3badc4', '-1/7', false, '5059b692-fce8-430c-98ab-33fe3651893f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03ad1c05-cf07-45d4-96ae-849d4bf7c30f', '1/5', false, '5059b692-fce8-430c-98ab-33fe3651893f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8f7c017-a73c-45d9-8ccb-0744f49ac1ba', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Match Column I (Rational Operations) with Column II (Evaluated Values in Simplest Form):
(a) (-3/7) + (5/14)        -> (i) -1/14
(b) (-2/3) - (-5/6)        -> (ii) 1/6
(c) (-8/9) × (-27/16)      -> (iii) 3/2
(d) (-3/5) ÷ (9/10)        -> (iv) -2/3', '(-6+5)/14 = -1/14; (-4+5)/6 = 1/6; (8×27)/(9×16) = 3/2; (-3/5)×(10/9) = -2/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15de65c1-7d44-4e47-854a-e71f90c6fcf9', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'b8f7c017-a73c-45d9-8ccb-0744f49ac1ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f9f29b4-e34f-4a5f-b970-b672876f08be', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'b8f7c017-a73c-45d9-8ccb-0744f49ac1ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a3283c3-e604-4c5b-a851-a6d0783f369c', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b8f7c017-a73c-45d9-8ccb-0744f49ac1ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc9c4a46-6d19-4ba8-8217-32e16b3ecd6b', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b8f7c017-a73c-45d9-8ccb-0744f49ac1ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bbcb5af-2f75-4048-b15d-fbdf7e38b03f', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Read the statements regarding number classifications:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('521ea441-103c-46b2-a39a-ce6e589f39dd', 'Statements 1 and 2 only', true, '0bbcb5af-2f75-4048-b15d-fbdf7e38b03f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ae143da-a924-47db-b694-a5b1412863cd', 'Statements 2 and 3 only', false, '0bbcb5af-2f75-4048-b15d-fbdf7e38b03f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d955ac41-428a-476f-8655-1ca6ec0ea221', 'Statements 1 and 3 only', false, '0bbcb5af-2f75-4048-b15d-fbdf7e38b03f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d711678-0eac-4145-8969-f95feb29e16c', 'All Statements 1, 2, and 3', false, '0bbcb5af-2f75-4048-b15d-fbdf7e38b03f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e4ad0ac-7be4-4792-b8ff-fcb86c30e395', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'If x = -2/3 and y = 4/5, verify that |x + y| ≤ |x| + |y| (Triangle Inequality for Rational Numbers):', 'Absolute value triangle inequality: |(-2/3) + (4/5)| = 2/15 ≤ |-2/3| + |4/5| = 22/15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda20ad2-a0a1-4e3f-b97e-e98c061ff694', '|x + y| = |-2/3 + 4/5| = |2/15| = 2/15 ; |x| + |y| = 2/3 + 4/5 = 22/15 ; Since 2/15 < 22/15, the inequality strictly holds true', true, '3e4ad0ac-7be4-4792-b8ff-fcb86c30e395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('007cc822-3468-4cd1-8327-2bef1af520dc', '|x + y| = 22/15', false, '3e4ad0ac-7be4-4792-b8ff-fcb86c30e395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('341a87c9-f41d-49d3-b2dc-430e4e9baac5', '|x| + |y| = 2/15', false, '3e4ad0ac-7be4-4792-b8ff-fcb86c30e395');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3945bcb7-e5ec-4955-abe8-3c1edb731cd0', 'The inequality is false', false, '3e4ad0ac-7be4-4792-b8ff-fcb86c30e395');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3e078bf-f43f-4505-9e4d-212a0f01b6b9', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Find the rational number exactly HALFWAY (the midpoint) between -3/4 and 5/6:', 'Midpoint = ½((-9/12) + (10/12)) = ½(1/12) = 1/24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f807291b-c4fd-493b-9fc5-bee00991bb81', '1/24 (Midpoint = 1/2 × (-3/4 + 5/6) = 1/2 × ((-9 + 10) / 12) = 1/2 × (1/12) = 1/24)', true, 'e3e078bf-f43f-4505-9e4d-212a0f01b6b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d47d2815-81c6-40ab-8f3f-d458eba32c23', '1/12', false, 'e3e078bf-f43f-4505-9e4d-212a0f01b6b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ed9b7da-7aaa-4bfb-b783-62e797ee21ad', '-1/24', false, 'e3e078bf-f43f-4505-9e4d-212a0f01b6b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4e03629-7f8d-4279-b4a8-ca5ade016c47', '1/6', false, 'e3e078bf-f43f-4505-9e4d-212a0f01b6b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a0fb7b7-7012-48db-9459-bb290e5d4d25', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'A car is traveling at an average speed of 40 2/5 km/h. How much distance will it cover in 7 1/2 hours?', 'Distance = (202/5) × (15/2) = 101 × 3 = 303 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('221abf7f-d670-47a0-a557-eea230838206', '303 km (Speed = 202/5 km/h ; Time = 15/2 h ; Distance = (202/5) × (15/2) = (202 × 3) / 2 = 101 × 3 = 303 km)', true, '0a0fb7b7-7012-48db-9459-bb290e5d4d25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebc04e29-0205-4a95-86e5-dcce9864953c', '300 km', false, '0a0fb7b7-7012-48db-9459-bb290e5d4d25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b104842-108f-4c1e-8101-a4342d68bf97', '295 km', false, '0a0fb7b7-7012-48db-9459-bb290e5d4d25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bbb7f7c-5c9b-4eb5-9839-20587f6ad408', '310 km', false, '0a0fb7b7-7012-48db-9459-bb290e5d4d25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97d177f0-6ffa-48a2-897d-05130b9e347f', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'From a rope of length 11 metres, two pieces of lengths 2 3/5 m and 3 3/10 m are cut off. What is the length of the REMAINING rope?', 'Total cut = 5.9 m. Remaining = 11 - 5.9 = 5.1 m = 51/10 = 5 1/10 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b262ece3-1688-4203-b957-debfdbc2ab32', '5 1/10 m (Total cut = 13/5 + 33/10 = 26/10 + 33/10 = 59/10 m ; Remaining = 11 - 59/10 = (110 - 59)/10 = 51/10 = 5 1/10 m)', true, '97d177f0-6ffa-48a2-897d-05130b9e347f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b174bb48-940b-4dad-b05d-062f9f0a930e', '4 9/10 m', false, '97d177f0-6ffa-48a2-897d-05130b9e347f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50fbcf33-adba-4899-bb68-f86456ed4c15', '5 3/10 m', false, '97d177f0-6ffa-48a2-897d-05130b9e347f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9088398d-27b5-4d81-a0d5-59571af925e2', '6 1/10 m', false, '97d177f0-6ffa-48a2-897d-05130b9e347f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67352d83-5f8e-4c36-9daf-91a57c41653b', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Divide the sum of 65/12 and 8/3 by their difference:', 'Sum = 97/12. Difference = 33/12. Quotient = (97/12) / (33/12) = 97/33.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dab32495-a3a6-4cdc-a814-95bbe3bb6f05', '97/33 (Sum = 65/12 + 32/12 = 97/12 ; Difference = 65/12 - 32/12 = 33/12 ; Division = (97/12) ÷ (33/12) = 97 / 33)', true, '67352d83-5f8e-4c36-9daf-91a57c41653b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3c54392-4245-45e8-b735-9d669edac24b', '33/97', false, '67352d83-5f8e-4c36-9daf-91a57c41653b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b549929-066a-4f60-85f6-6b7f5ffc239a', '97/12', false, '67352d83-5f8e-4c36-9daf-91a57c41653b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50ee48be-b23b-44d7-9764-3ed72cd39e99', '33/12', false, '67352d83-5f8e-4c36-9daf-91a57c41653b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7263414c-4122-4683-8d18-194afd6f28fa', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'If a = 1/2, b = -1/3, and c = 2/5, verify the Associative Law of Addition: (a + b) + c = a + (b + c):', 'Both sides evaluate identically to 17/30, demonstrating associativity of rational addition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5082114f-9611-4ff0-abeb-a2b2f4899a93', '(1/2 + (-1/3)) + 2/5 = (1/6) + 2/5 = (5 + 12)/30 = 17/30 ; 1/2 + (-1/3 + 2/5) = 1/2 + (1/15) = (15 + 2)/30 = 17/30 (Verified)', true, '7263414c-4122-4683-8d18-194afd6f28fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bf03421-a522-4422-b7ec-fb4082bcf3dc', '17/30 and 19/30 (False)', false, '7263414c-4122-4683-8d18-194afd6f28fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0e96833-39da-4e98-bc88-dbda1a11f5e4', '15/30', false, '7263414c-4122-4683-8d18-194afd6f28fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c26c3b36-c10f-4647-bb1d-d9b362a8fc6c', '0', false, '7263414c-4122-4683-8d18-194afd6f28fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90505f46-c0d1-4d71-b9fb-14ffa94e29f9', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Why is the algebraic Field of Rational Numbers (ℚ) indispensable in scientific measurement, engineering calibrations, and computational arithmetic?', 'The rational field ℚ provides the rigorous mathematical infrastructure for fractional ratios, dimensional analysis, and digital arithmetic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6af79d6f-7b07-4cc6-b3e4-af194fe2f0cf', 'Rational numbers provide the exact fractional precision required for discrete physics ratios, scale conversions, financial balance accounting, and floating-point numeric approximations', true, '90505f46-c0d1-4d71-b9fb-14ffa94e29f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd248242-d50e-4363-9a92-b6a1c593a1b7', 'Because rational numbers are the only numbers that exist', false, '90505f46-c0d1-4d71-b9fb-14ffa94e29f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5a1d5f8-4b2b-49e4-98a4-5f3a4fea8bf1', 'Because rational numbers eliminate the need for division', false, '90505f46-c0d1-4d71-b9fb-14ffa94e29f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bfda17f-39fd-4c35-9f2d-268557258680', 'Because rational numbers are always whole integers', false, '90505f46-c0d1-4d71-b9fb-14ffa94e29f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('907aba82-fdd7-4446-b132-f597494dc54f', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What was early primitive man''s initial attitude toward fire before understanding its scientific nature?', 'Early humans feared fire because of its destructive devastation in volcanic eruptions and lightning forest fires.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48ea9c69-1dc6-48b3-a557-f7bd69118bd6', 'Early humans were deeply frightened of fire, viewing it as a mysterious, terrifying, and dangerous destructive force', true, '907aba82-fdd7-4446-b132-f597494dc54f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71473cbd-5301-4a0f-9eb0-cd6ebf70e1d4', 'They loved fire and played with it', false, '907aba82-fdd7-4446-b132-f597494dc54f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffa6afce-b6c9-4eb5-9947-dc6fdac049da', 'They ignored fire completely', false, '907aba82-fdd7-4446-b132-f597494dc54f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cd4fb53-a916-4aaa-8908-d2f5f1c78794', 'They kept fire in ice boxes', false, '907aba82-fdd7-4446-b132-f597494dc54f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81cea9be-8c57-441a-ae4b-4400227a04e5', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'Scientifically, what three essential things are required to make and sustain FIRE?', 'Fire triangle: Fuel + Oxygen (from air) + Heat (reaching ignition temperature) are the three mandatory elements.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6d41cfa-2008-4178-b42b-639aaba35277', 'Fuel, Oxygen, and Heat', true, '81cea9be-8c57-441a-ae4b-4400227a04e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72811384-9af7-4c6c-b6c7-387f653a2edc', 'Water, Wood, and Air', false, '81cea9be-8c57-441a-ae4b-4400227a04e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eae5ce46-650d-4bff-9a6b-8c8e5392067b', 'Coal, Ice, and Smoke', false, '81cea9be-8c57-441a-ae4b-4400227a04e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6208dbe-2dfd-4393-a11a-039274fca11b', 'Gasoline, Sand, and Wind', false, '81cea9be-8c57-441a-ae4b-4400227a04e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1129b9e3-3c69-4968-be9d-08cff06e34d0', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What is the particular minimum temperature at which a specific fuel begins to catch fire and burn called?', 'The minimum temperature at which a combustible fuel begins burning is its ''flash point'' or ''kindling temperature''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c67714df-49db-4fba-b66e-89a7755d41b6', 'Flash Point (or Kindling Temperature)', true, '1129b9e3-3c69-4968-be9d-08cff06e34d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e3ef517-bbb3-4626-a944-9cd1cc723df4', 'Boiling Point', false, '1129b9e3-3c69-4968-be9d-08cff06e34d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b0f015e-3db7-467c-a37b-2db077133ef6', 'Freezing Point', false, '1129b9e3-3c69-4968-be9d-08cff06e34d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a21254f8-5655-4540-8f1d-3221ed0830e0', 'Melting Point', false, '1129b9e3-3c69-4968-be9d-08cff06e34d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b458792e-bfd1-43d9-b266-4713acb27ecd', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'Why is Fire described as ''a good servant but a bad master'' in the prose text?', 'The proverb highlights that controlled combustion serves human civilization, whereas runaway infernos cause catastrophic destruction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de91b427-1e43-4d6c-b2dc-f515a111b962', 'As long as fire is kept under control, it is incredibly useful for cooking, heating, and generating power ; but if it gets out of control, it destroys homes, forests, and lives', true, 'b458792e-bfd1-43d9-b266-4713acb27ecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eef3ccb-0650-4ecf-b200-2a4769867e55', 'Because fire works in restaurants', false, 'b458792e-bfd1-43d9-b266-4713acb27ecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57a7bc9a-5bed-49b0-a476-47ea8186a8f4', 'Because fire can be bought in shops', false, 'b458792e-bfd1-43d9-b266-4713acb27ecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2469b65-1376-4621-b3a6-207007ef10b1', 'Because fire only burns in winter', false, 'b458792e-bfd1-43d9-b266-4713acb27ecd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96cc124a-71be-4dab-af9e-d7313a028f8e', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What are the three fundamental ways to extinguish or put out a fire?', 'Extinguishing fire involves breaking the fire triangle: fuel starvation, oxygen smothering, or thermal cooling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('defe6ef6-0e7f-44a5-bd4a-ca7f45ef6c18', '1. Take away the Fuel ; 2. Prevent Oxygen from reaching it (smothering) ; 3. Remove the Heat / bring temperature below flash point (spraying water)', true, '96cc124a-71be-4dab-af9e-d7313a028f8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96d3df5d-2f3e-459b-80ce-4e052e3aa1d9', '1. Add more wood ; 2. Blow air ; 3. Pour oil', false, '96cc124a-71be-4dab-af9e-d7313a028f8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('305e4b86-31b4-4b4b-a0d5-13d676f5e488', '1. Run away ; 2. Close eyes ; 3. Shout', false, '96cc124a-71be-4dab-af9e-d7313a028f8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f0b595c-e3c5-40ed-bbf2-debbcee78cb7', '1. Paint the walls ; 2. Open windows ; 3. Plant trees', false, '96cc124a-71be-4dab-af9e-d7313a028f8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('131f5e74-8e2a-46e8-906a-8d189f487266', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'Why should Water NEVER be used to extinguish an Electrical Fire or an Oil Fire?', 'Tap water conducts lethal current in electrical fires, and low-density oil floats atop water, spreading flames.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05fbd1e9-24bb-40c6-8c7d-4d2e5a6f9da0', 'Water conducts electricity (risking lethal electric shocks) ; and burning oil floats on water and spreads the blazing fire everywhere', true, '131f5e74-8e2a-46e8-906a-8d189f487266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1baa1c5-d190-478c-9e0c-50cb40c2c703', 'Because water catches fire', false, '131f5e74-8e2a-46e8-906a-8d189f487266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('321ec8ae-390e-4c87-861a-32339ad18e4b', 'Because water turns into oil', false, '131f5e74-8e2a-46e8-906a-8d189f487266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d06dc139-20e2-4548-a2d4-4031f1582686', 'Because water is too expensive', false, '131f5e74-8e2a-46e8-906a-8d189f487266');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad23b4aa-3b9d-412e-a54e-af333bfd7229', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What type of fire extinguisher is safest and most effective for combating Electrical and Oil fires?', 'CO₂ extinguishers displace oxygen and do not conduct electricity, suffocating oil and electrical fires safely.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a6d0053-f905-416c-a149-826504d0b5ee', 'Carbon Dioxide (CO₂) Fire Extinguisher', true, 'ad23b4aa-3b9d-412e-a54e-af333bfd7229');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f72b0ff5-4b5c-4bef-925c-61d30b268589', 'Plain tap water bucket', false, 'ad23b4aa-3b9d-412e-a54e-af333bfd7229');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ceed4487-f292-4093-923c-5a4f0b88dbd6', 'Blowing breath', false, 'ad23b4aa-3b9d-412e-a54e-af333bfd7229');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ee68a94-b2fc-4fbf-91ea-9e73160ae359', 'Spreading paper', false, 'ad23b4aa-3b9d-412e-a54e-af333bfd7229');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1eb19afe-50fe-49d8-9378-4d5f0e571343', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'In Lois Brandt Phillips''s poem ''Meadow Surprises'', what two sensory habits must a visitor have to discover hidden wonders in a meadow?', 'The poem begins: ''Meadows have surprises, / You can find them if you look; / Walk softly through the velvet grass, / And listen by the brook.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac9ba55d-880f-4d05-abdf-61f292f7dc0a', 'A keen, observant Eye and a sharp, patient Ear', true, '1eb19afe-50fe-49d8-9378-4d5f0e571343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a4ac7a0-b31d-4012-80ab-f0cce24c28fa', 'A loud voice and big boots', false, '1eb19afe-50fe-49d8-9378-4d5f0e571343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b94d557a-9b44-48cd-be74-cbdae2263d18', 'A camera and a telephone', false, '1eb19afe-50fe-49d8-9378-4d5f0e571343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('885a1cdd-7a78-4768-a194-169662747045', 'A net and a cage', false, '1eb19afe-50fe-49d8-9378-4d5f0e571343');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98a75e71-ad3f-4ab5-81d3-601e1bfd8d3f', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What is the butterfly resting upon and sipping nectar from in the poem ''Meadow Surprises''?', 'Line from the poem: ''You may see a butterfly / Rest upon a buttercup / And unfold its drinking straws / To sip the nectar up.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1d3268d-ab95-4f59-90a1-84abdd63b986', 'A Buttercup flower (using its drinking straws / proboscis)', true, '98a75e71-ad3f-4ab5-81d3-601e1bfd8d3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e13c785-0aea-4c58-a8e9-dab241e65f9e', 'A rose petal', false, '98a75e71-ad3f-4ab5-81d3-601e1bfd8d3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa05aef-0e41-47b6-8824-023605207bf8', 'A tree trunk', false, '98a75e71-ad3f-4ab5-81d3-601e1bfd8d3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faf03687-6058-4ac1-87f8-8ffe78ca3da2', 'A rock', false, '98a75e71-ad3f-4ab5-81d3-601e1bfd8d3f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eda18a6f-399d-40c7-91e5-cb39cd7434e6', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What small creature sits so still in the grass that you won''t see it until it suddenly hops away in fright?', 'Textual lines: ''You may scare a rabbit / Who is sitting very still; / Though at first you may not see him, / When he hops you will.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c24bfafb-b4bb-42fa-b978-02d11d2ebc1b', 'A Rabbit', true, 'eda18a6f-399d-40c7-91e5-cb39cd7434e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db1be944-7ae0-4c8d-bcee-20eab8d59e73', 'A Squirrel', false, 'eda18a6f-399d-40c7-91e5-cb39cd7434e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b020b68-3694-4665-b0f0-3f7560dbbf3e', 'A Frog', false, 'eda18a6f-399d-40c7-91e5-cb39cd7434e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c917789-d85e-45b4-9aee-f8f1610252dc', 'A Mouse', false, 'eda18a6f-399d-40c7-91e5-cb39cd7434e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26af37fe-cea0-4fae-8900-ad8415ad0896', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What yellow fuzzy flower whose head turned into airy parachutes flutters away when you blow on it in the meadow?', 'Textual lines: ''A dandelion whose fuzzy head / Was golden days ago / Has turned to airy parachutes / That flutter when you blow.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3809bb3-fd13-4cbd-a905-837a71f71b16', 'A Dandelion', true, '26af37fe-cea0-4fae-8900-ad8415ad0896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('717b2ff8-adbb-4eb8-be53-22f63e216c5d', 'A Sunflower', false, '26af37fe-cea0-4fae-8900-ad8415ad0896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74f83086-2e4b-4fb0-8b53-7ecf96ef4e72', 'A Marigold', false, '26af37fe-cea0-4fae-8900-ad8415ad0896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b9ff7ab-08fe-44b2-b4bf-fe07404c7e07', 'A Lotus', false, '26af37fe-cea0-4fae-8900-ad8415ad0896');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e73861d-76f2-4671-b9de-97bb8fe65cf0', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What meadow dwellings and animal homes are mentioned in ''Meadow Surprises''?', 'The poem catalogs natural habitats: ''Burrows in the ground, / A nest beneath tall grasses, / The ant''s amazing mound.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07a09535-94da-495b-af57-a4badcf9e057', 'Burrows in the ground, birds'' nests beneath tall grasses, and magnificent mounds of ants', true, '7e73861d-76f2-4671-b9de-97bb8fe65cf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e27db273-6c7a-4066-995b-003a814146c9', 'Brick houses and skyscrapers', false, '7e73861d-76f2-4671-b9de-97bb8fe65cf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4b9bb58-5079-4922-9056-87cf2dde7b89', 'Fish ponds and aquariums', false, '7e73861d-76f2-4671-b9de-97bb8fe65cf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce2b6bd0-287e-4d14-b560-47045d917957', 'Caves of bears', false, '7e73861d-76f2-4671-b9de-97bb8fe65cf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('710d23f5-b996-4252-9b24-3954bfffad32', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the chemical reaction called when oxygen in the air combines rapidly with carbon and hydrogen in a fuel to release heat and light?', 'Combustion is the rapid exothermic oxidation of hydrocarbons yielding CO₂, H₂O, heat, and radiant photon emission (light).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5ee6973-f4ad-442f-ad3c-5db27725597a', 'Combustion (Exothermic Chemical Reaction)', true, '710d23f5-b996-4252-9b24-3954bfffad32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cae80c9-af3d-4ffc-8234-0caebe273274', 'Evaporation', false, '710d23f5-b996-4252-9b24-3954bfffad32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44b181ef-27fc-476e-ab7e-7aeed6c508b7', 'Condensation', false, '710d23f5-b996-4252-9b24-3954bfffad32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e06ba3ab-422e-418a-b7cd-cf7299f2fe4a', 'Photosynthesis', false, '710d23f5-b996-4252-9b24-3954bfffad32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9c30cf6-65c7-4092-91e6-ae6809cd5b0a', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'How did people fight fires in towns before the advent of organized fire brigades and motorized fire engines?', 'Historic firefighting utilized bucket chains where lines of citizens swiftly relayed water buckets from hydrants/wells to the flames.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa77a8a3-8320-4509-8d8e-ed64885cb810', 'People formed human bucket brigades, passing buckets of water hand-to-hand from nearby wells and ponds to pour onto the burning building', true, 'b9c30cf6-65c7-4092-91e6-ae6809cd5b0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2beb739-6669-46ee-b885-d3a0ac711ba8', 'They waited for winter rain', false, 'b9c30cf6-65c7-4092-91e6-ae6809cd5b0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2251842-9445-4216-ac08-83c9a29a9f19', 'They blew on the fire with fans', false, 'b9c30cf6-65c7-4092-91e6-ae6809cd5b0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf1287bc-4edb-4ac6-ad61-5ce2c2e5e81e', 'They covered the town with blankets', false, 'b9c30cf6-65c7-4092-91e6-ae6809cd5b0a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d92bb3f6-8557-4ae3-be47-ca855878f69b', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'Why do modern city building construction laws require leaving open space between large buildings?', 'Fire safety building codes mandate setback spaces to create thermal firebreaks that prevent structural flame leap.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be65cf14-cfb7-4c4f-a5d2-f3f42460d4ff', 'To reduce the risk of fire jumping and spreading from one structure to neighboring buildings', true, 'd92bb3f6-8557-4ae3-be47-ca855878f69b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ab6013b-76f4-4917-80bf-091ebd392bd5', 'To build wider roads for racing', false, 'd92bb3f6-8557-4ae3-be47-ca855878f69b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9189885c-58c3-4dae-a216-f9e914be06f0', 'To let wild animals walk through', false, 'd92bb3f6-8557-4ae3-be47-ca855878f69b');
