INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('531638e7-d144-4e67-9438-704d150e2589', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'How does throwing a damp, heavy blanket or sack over a small kitchen fire extinguish it immediately?', 'Fire blankets smother flames by oxygen starvation, dropping O₂ below the 16% threshold needed for combustion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f544c9dd-cd0c-4bd4-a21c-271f5154593c', 'It cuts off the supply of atmospheric Oxygen from reaching the burning fuel, instantly smothering the flame', true, '531638e7-d144-4e67-9438-704d150e2589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bf37663-6c33-418a-b3ec-0f0ce0f05305', 'It makes the fire hotter', false, '531638e7-d144-4e67-9438-704d150e2589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b481230d-dde6-44f9-b1a1-1a370428b3e2', 'It adds fuel to the fire', false, '531638e7-d144-4e67-9438-704d150e2589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3901eb16-e5f7-4ad0-83a2-abea773812fd', 'It makes the fire disappear into the blanket', false, '531638e7-d144-4e67-9438-704d150e2589');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc5ece05-3e01-4dba-95c3-4853b34d888c', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the poetic metaphor in describing a butterfly''s mouthparts as ''Drinking Straws'' in ''Meadow Surprises''?', 'The metaphor illuminates insect anatomy: the elongated tubular proboscis acts like an organic drinking straw siphoning nectar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1c27be4-a987-488e-acfb-7d5da6f91b23', 'It poetically visualizes the butterfly''s coiled tubular proboscis that unrolls to siphon sweet liquid nectar from flower chalices', true, 'cc5ece05-3e01-4dba-95c3-4853b34d888c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf13da09-9ad4-4ce5-ab63-3e18f0a45f88', 'The butterfly carries plastic straws from a store', false, 'cc5ece05-3e01-4dba-95c3-4853b34d888c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('434b1e5f-7134-48c2-8d72-34f7c516d00b', 'The butterfly is drinking lemonade', false, 'cc5ece05-3e01-4dba-95c3-4853b34d888c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab0f8586-3038-4c6c-891a-04d995f6b9be', 'The flower is made of glass', false, 'cc5ece05-3e01-4dba-95c3-4853b34d888c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07ac0fc0-1139-4104-bfed-a6e516df97ca', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the meaning of the word ''Smother'' in firefighting contexts?', '''Smother'' means suffocating or extinguishing combustion by cutting off atmospheric oxygen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e785f793-beb3-4c70-81f3-48a6a67c1d81', 'To extinguish a fire by depriving it of air and cutting off oxygen supply', true, '07ac0fc0-1139-4104-bfed-a6e516df97ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('869d4db1-3ec1-42d0-a1f0-097833535381', 'To burn brightly', false, '07ac0fc0-1139-4104-bfed-a6e516df97ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('219bd5b0-35e6-4c38-b132-1a9dcf1c962d', 'To pour gasoline on fire', false, '07ac0fc0-1139-4104-bfed-a6e516df97ca');
