INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7205fe06-911c-4c36-a911-d016d13e9b2c', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the meaning of ''Kindling'' in: ''Kindling temperature of wood''?', '''Kindling temperature'' is the minimum thermal threshold required to ignite combustion.', NOW()) ON CONFLICT DO NOTHING;
