INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d474c966-6ecf-45f8-91cd-c0f8d3da60ee', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the meaning of ''Airy parachutes'' in the description of a mature Dandelion flower?', '''Airy parachutes'' poeticizes the pappus parachute hairs of dandelion seeds designed for wind dispersal.', NOW()) ON CONFLICT DO NOTHING;
