INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5cec60f4-fa0b-45b7-8684-c289a588cb13', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What happens when you blow gently on a dandelion seed-head according to the poem?', 'Line from poem: ''Airy parachutes that flutter when you blow''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a497098-eaaf-4ad8-a934-a5aec14af962', 'The tiny parachute seeds detach and flutter away through the air', true, '5cec60f4-fa0b-45b7-8684-c289a588cb13');
