INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ab8df83-9e73-44ec-8961-4fc32dd409fd', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Spot the IMPOSTER in the following methods of Firefighting and their scientific operational principles:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c89a89b-51f8-4b0e-b1eb-19d5e4a24d07', 'Method 1', false, '1ab8df83-9e73-44ec-8961-4fc32dd409fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ca2494b-7204-43c7-9bd3-2bd56d813640', 'Method 2', false, '1ab8df83-9e73-44ec-8961-4fc32dd409fd');
