INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d5ac8ec-845b-49bb-a7ea-e9e4ecd7324a', 'Method 4 (Alcohol and Gasoline are HIGHLY INFLAMMABLE FUELS that will violently explode and feed the fire, NOT cool it)', true, '1ab8df83-9e73-44ec-8961-4fc32dd409fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a4696cc-eae6-4b86-a6ea-7f4314120d39', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Analyze the environmental aesthetics in Lois Brandt Phillips''s ''Meadow Surprises'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba7650f2-c085-4766-b772-f6578c591a1e', 'Nature does not shout its beauty; discovering the rich biodiversity of meadows (micro-habitats, animal architecture, camouflage) requires gentle stillness, patient observation, and deep reverence', true, '9a4696cc-eae6-4b86-a6ea-7f4314120d39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ab17926-4fd3-4953-b534-7ffe1cff01ee', 'Meadows are empty fields with nothing to see', false, '9a4696cc-eae6-4b86-a6ea-7f4314120d39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0b25615-d54a-411a-9dbe-36ba5bd070b3', 'Children should run loudly to scare all animals away', false, '9a4696cc-eae6-4b86-a6ea-7f4314120d39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6acfcd98-f04c-45b2-90cd-caf21513ec9b', 'Meadows should be paved over with concrete', false, '9a4696cc-eae6-4b86-a6ea-7f4314120d39');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67048b1f-7408-4e16-8801-ee1aa01024ac', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Match Column I (Fire Safety & Poetic Images) with Column II (Scientific & Literary Mechanisms):
(a) Fire Triangle               -> (i) The tripartite triad of Fuel, Oxygen, and Ignition Heat
(b) Flash Point                 -> (ii) The critical kindling temperature threshold initiating combustion
(c) Butterfly''s Drinking Straws -> (iii) Extended tubular proboscis harvesting floral nectar
(d) Dandelion Airy Parachutes   -> (iv) Anemochorous pappus seed adaptations for wind dispersal', 'Fire Triangle = fuel/O₂/heat; Flash point = ignition temp; Proboscis = drinking straw; Pappus = airy parachute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9dd11fe-9bdb-49c8-8a33-129a570e9cbc', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '67048b1f-7408-4e16-8801-ee1aa01024ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52d2e685-cc16-49c9-9d33-6f838d12a547', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '67048b1f-7408-4e16-8801-ee1aa01024ac');
