INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cd60850-bfe1-40d0-8354-ec082c17c623', 'Statements 1 and 2 only', true, '6ac444e7-ad48-45f9-a272-4fc1e398ad34');
