INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19004508-1cd0-45ab-ab05-ee3e9cfa792a', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Identify the grammatical role of the underlined clause in: ''When a fire breaks out, **firefighters immediately rush to the scene**.''', '''Firefighters immediately rush to the scene'' is the independent principal clause preceded by the temporal subordinate clause.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ded8005-aea5-437f-92aa-d52ab0768cb9', 'Main (Independent) Clause expressing the primary action', true, '19004508-1cd0-45ab-ab05-ee3e9cfa792a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9cb99ce-0092-424a-9c3d-745c034a0bd6', 'Dependent Adverb Clause of Time', false, '19004508-1cd0-45ab-ab05-ee3e9cfa792a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68cac771-9c9a-4038-abb1-a7a292cd6c69', 'Noun Clause in apposition', false, '19004508-1cd0-45ab-ab05-ee3e9cfa792a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5baa7067-5078-4f72-a588-f7e9d8dab10a', 'Relative Clause', false, '19004508-1cd0-45ab-ab05-ee3e9cfa792a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ec2cba5-4e82-41bd-8929-d2184b91b2bd', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Why does spraying water on a normal wood or paper fire put it out effectively?', 'Thermodynamics of water dousing: massive enthalpy absorption lowers temperature below flash point, while expanding steam blankets oxygen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9ac6f41-9ce4-4f7e-98fd-b4ac6dd83ca2', 'Water absorbs vast amounts of thermal heat energy (high specific heat and latent heat of vaporization), dropping the fuel''s temperature below its kindling flash point, while steam blocks surrounding oxygen', true, '6ec2cba5-4e82-41bd-8929-d2184b91b2bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc05efd-6bce-4496-b4d9-8c9e9ecfcf9c', 'Water turns the wood into metal', false, '6ec2cba5-4e82-41bd-8929-d2184b91b2bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cffab879-aae8-45d7-9b25-51cbad888cef', 'Water produces freezing ice instantly', false, '6ec2cba5-4e82-41bd-8929-d2184b91b2bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('038d9ae6-2616-4ec4-8132-4ef9c4140e4e', 'Water creates chemical poison for fire', false, '6ec2cba5-4e82-41bd-8929-d2184b91b2bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d17a144-7f7f-4511-a4bd-a80b408b6494', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'In ''Meadow Surprises'', what camouflage survival mechanism of the rabbit is highlighted in the lines:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c35258d9-e69a-40cb-aa73-679f510e9d35', 'Crypsis / Freezing behavior: prey animals blend motionless with meadow background to evade visual predator detection until forced into explosive flight', true, '8d17a144-7f7f-4511-a4bd-a80b408b6494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d3d295f-e57e-4a30-927d-01417c229075', 'Rabbits change their skin color like chameleons', false, '8d17a144-7f7f-4511-a4bd-a80b408b6494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee0afc61-692e-4903-b4a9-79b994482172', 'Rabbits become invisible with magic', false, '8d17a144-7f7f-4511-a4bd-a80b408b6494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33472cd6-58c1-4956-a4f9-4f242550727d', 'Rabbits dig holes with their ears', false, '8d17a144-7f7f-4511-a4bd-a80b408b6494');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa6989eb-4321-4d7f-b6f3-b5b1db819fae', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'What is the ecological significance of the ''Ant''s amazing mound'' mentioned in the poem?', 'Formicary ant mounds are sophisticated subterranean bio-architectural complexes regulating ventilation, brood humidity, and colony defense.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33fb724b-0bd0-4b9b-b0d5-04a0d4733154', 'It represents a marvel of social insect architectural engineering, featuring complex subterranean galleries for fungal cultivation, brood chambers, and thermal regulation', true, 'aa6989eb-4321-4d7f-b6f3-b5b1db819fae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c664927-4486-4aa5-b087-8898010b301e', 'It is a pile of trash left by hikers', false, 'aa6989eb-4321-4d7f-b6f3-b5b1db819fae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('296eb411-a96e-4349-924b-c82a240a9d64', 'It is a natural rock formation', false, 'aa6989eb-4321-4d7f-b6f3-b5b1db819fae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b427c1de-17a4-49c8-8a51-6e8d40797714', 'It is built by meadow birds', false, 'aa6989eb-4321-4d7f-b6f3-b5b1db819fae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7367d569-0a98-4691-a5ce-010836d9ce0c', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Which of the following sentences correctly utilizes the Conditional Clause (Type 1) for fire safety?', 'Standard first conditional syntax: If + simple present (''see''), main clause modal + base verb (''should report'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92dd1aa3-18f6-41ff-924a-e1dec6a5dde3', '"If you see a fire hazard in your building, you should immediately report it to the fire officer."', true, '7367d569-0a98-4691-a5ce-010836d9ce0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55630e20-83a2-4983-b356-7665f2391d5e', '"If you saw fire, you will run."', false, '7367d569-0a98-4691-a5ce-010836d9ce0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f25e722c-52ec-4280-a428-a4edc6d6c9d1', '"If fire is burning, water had been sprayed."', false, '7367d569-0a98-4691-a5ce-010836d9ce0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57edec18-1704-4b8b-abc0-4912bacaf29e', '"If fuel burns, smoke was rising."', false, '7367d569-0a98-4691-a5ce-010836d9ce0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5d2c224-3fa9-46b3-961c-279fddae9599', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'What sensory contrast is created between the prose ''Fire: Friend and Foe'' and the poem ''Meadow Surprises''?', 'Chapter 8 creates thematic balance: industrial thermodynamics and civic safety paired with contemplative botanical and ecological wonder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89d295a6-1a21-4891-9303-5c1addec9890', 'The prose explores the fierce, energetic thermodynamic power of combustion and human technology, while the poem invites gentle, contemplative immersion in the quiet micro-wonders of living nature', true, 'e5d2c224-3fa9-46b3-961c-279fddae9599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4bb72b2-0b89-459d-aba3-48baa0b1d5d1', 'Both texts describe destructive earthquakes', false, 'e5d2c224-3fa9-46b3-961c-279fddae9599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b307ffb-cbc6-4904-8d99-9eee0841d1a1', 'Both texts are mathematical formulas', false, 'e5d2c224-3fa9-46b3-961c-279fddae9599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e647a48-d97c-45af-a12a-6e3221107e8c', 'There is no contrast', false, 'e5d2c224-3fa9-46b3-961c-279fddae9599');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('580e978d-4dad-4b83-aa46-8f13284257a9', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'What overarching humanist education unites Chapter 8 of NCERT Class 7 English?', 'Chapter 8 bridges physical science literacy, civic safety protocols, and ecological sensitivity to the natural world.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b700b1cd-27d4-4a1a-99f6-e457e93d0af8', 'Scientific literacy, safety consciousness, and environmental mindfulness—equipping young minds to master dangerous physical forces responsibly while nurturing gentle curiosity for nature''s delicate ecosystems', true, '580e978d-4dad-4b83-aa46-8f13284257a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5011de34-c145-49d0-a305-529345cc913b', 'That humans should never explore meadows', false, '580e978d-4dad-4b83-aa46-8f13284257a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('019799ed-ecf6-4b7f-9ad5-7e0e77711820', 'That fire should never be used for any purpose', false, '580e978d-4dad-4b83-aa46-8f13284257a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('146cd7e3-ccd9-4b1f-883e-f56d396179d8', 'That animals should be kept in cages', false, '580e978d-4dad-4b83-aa46-8f13284257a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2bc3d83a-f7e1-4a72-8312-7727f98b7361', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which is the HIGHEST mountain peak in India (located in the Karakoram range in Ladakh / Gilgit-Baltistan), standing at 8,611 metres?', 'K2 (8,611 m) is the highest peak in India and second highest on Earth; Kanchenjunga (8,586 m) in Sikkim is the highest peak entirely in undisputed Indian territory.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88861c13-ecc3-42e6-9889-b7bebfc9871f', 'K2 (Mount Godwin-Austen)', true, '2bc3d83a-f7e1-4a72-8312-7727f98b7361');
