INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4683a661-ac51-442f-8137-abb0d4d1e4ac', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which is the LONGEST river flowing entirely within India, having a total length of approximately 2,525 km originating from Gangotri Glacier?', 'The Ganga (2,525 km) is India''s longest and most sacred river, formed at Devprayag by the confluence of Bhagirathi and Alaknanda.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b01d54d7-2d77-47ba-bfe2-c26daa35f783', 'The Ganga', true, '4683a661-ac51-442f-8137-abb0d4d1e4ac');
