INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d3e47b7-55ba-4029-aafd-bd6d319915c0', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which place in the Khasi Hills of Meghalaya holds the world record for the HIGHEST AVERAGE ANNUAL RAINFALL on Earth (~11,872 mm)?', 'Mawsynram in Meghalaya is the wettest inhabited place on planet Earth due to funnel-shaped monsoon cloud trapping in the Khasi hills.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23b3db3a-3d56-4ede-91da-2b11394e5f2f', 'Mawsynram (near Cherrapunji)', true, '2d3e47b7-55ba-4029-aafd-bd6d319915c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abf4d38f-9503-4f81-a86d-8bb79cde98ca', 'Agumbe', false, '2d3e47b7-55ba-4029-aafd-bd6d319915c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76e63a86-2b56-4ebf-99f2-30ed87fb162d', 'Mahabaleshwar', false, '2d3e47b7-55ba-4029-aafd-bd6d319915c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6098af8-9063-4ed1-81be-8ec7ee9e44fb', 'Shillong', false, '2d3e47b7-55ba-4029-aafd-bd6d319915c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e61a4f7d-03b7-438c-9fa9-4b3dd1f2e9e6', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which is the LARGEST peninsular river in India, often called ''Dakshin Ganga'' (Ganga of the South)?', 'The Godavari is the second-longest river in India (1,465 km) and largest in the Peninsular plateau, earning the title Dakshin Ganga.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92aa321e-9c55-4be5-bb1e-04c919876596', 'The Godavari (length ~1,465 km originating at Trimbakeshwar, Nashik)', true, 'e61a4f7d-03b7-438c-9fa9-4b3dd1f2e9e6');
