INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6448e623-d788-4601-8893-9d30cdb25142', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which is the ONLY active volcano in India and South Asia, located in the Andaman and Nicobar Islands?', 'Barren Island in the Andaman Sea is South Asia''s only confirmed active volcanic island.', NOW()) ON CONFLICT DO NOTHING;
