INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da436daf-a076-422f-892c-c04107069bc3', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which National Park in Assam is world-famous for protecting over two-thirds of the world''s population of the Great ONE-HORNED RHINOCEROS?', 'Kaziranga National Park (UNESCO World Heritage Site) is the global stronghold of the Indian one-horned rhinoceros (Rhinoceros unicornis).', NOW()) ON CONFLICT DO NOTHING;
