INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7eb25efb-0d77-4f1a-8839-b59d1275dca6', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which National Park in Gujarat is the ONLY natural habitat in the world where the majestic ASIATIC LION (Panthera leo persica) survives in the wild?', 'Gir National Park and Wildlife Sanctuary in Saurashtra, Gujarat is the exclusive global refuge of wild Asiatic lions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b3b0eac-ae15-48b7-90b0-1a355506c661', 'Gir National Park', true, '7eb25efb-0d77-4f1a-8839-b59d1275dca6');
