INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa23a78e-c882-4af7-874d-973b547a5341', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which is the OLDEST National Park in India, established in 1936 in Uttarakhand for the protection of the Bengal Tiger?', 'Jim Corbett National Park in Nainital/Pauri Garhwal was established in 1936 and was the first to launch Project Tiger in 1973.', NOW()) ON CONFLICT DO NOTHING;
