INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9775f9fe-932d-4017-9159-1db21d801a18', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which parallel of latitude passes almost halfway through the middle of India, dividing the country into Tropical and Sub-tropical zones?', 'The Tropic of Cancer (23°30''N) passes through 8 Indian states: Gujarat, Rajasthan, MP, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.', NOW()) ON CONFLICT DO NOTHING;
