INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fc9c14a-1d90-4358-a7e7-8c7b7bfb20bf', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'What are the three parallel longitudinal ranges of the mighty Himalayas from north to south?', 'Himalayan tripartite physiography: Himadri (highest perennial snow ranges, >6,000 m), Himachal (hill resorts, 3,700–4,500 m), and Shiwaliks (outer foothills, 900–1,100 m).', NOW()) ON CONFLICT DO NOTHING;
