INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77808228-758a-4d51-a0f0-6457efb97d16', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which is the OLDEST fold mountain range in India (and one of the oldest in the world), running from Gujarat across Rajasthan to Delhi?', 'The Aravalli Range is a relict Precambrian fold belt eroded over hundreds of millions of years, terminating near Mount Abu.', NOW()) ON CONFLICT DO NOTHING;
