INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d298ca76-fa3e-48e4-8338-7d5d2914b1f4', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which two major Peninsular Indian rivers flow WESTWARDS through fault-formed Rift Valleys and drain into the Arabian Sea without forming deltas?', 'The Narmada (in rift between Vindhyas and Satpuras) and Tapi flow westwards into the Gulf of Khambhat, creating estuaries rather than deltas.', NOW()) ON CONFLICT DO NOTHING;
