INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6565523b-5ca2-4331-89ba-5aef4a12f2ec', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'What are the two major seasonal branches of the advancing South-West Summer Monsoon that brings over 75% of India''s annual rainfall between June and September?', 'The SW monsoon splits into the Arabian Sea branch (striking the Western Ghats) and the Bay of Bengal branch (striking the Northeast and Gangetic plains).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a8da631-6d88-40d7-a088-0b17e29bae53', 'The Arabian Sea Branch and the Bay of Bengal Branch', true, '6565523b-5ca2-4331-89ba-5aef4a12f2ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69b794fb-b4ec-41d5-9e83-ee6213466714', 'The Northern Branch and Southern Branch', false, '6565523b-5ca2-4331-89ba-5aef4a12f2ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68251f60-8140-46eb-8068-abc3feb2d565', 'The Himalayan Branch and Thar Branch', false, '6565523b-5ca2-4331-89ba-5aef4a12f2ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a4772eb-7652-4f9d-821a-4ade5acc3e0a', 'The Pacific Branch and Atlantic Branch', false, '6565523b-5ca2-4331-89ba-5aef4a12f2ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('434a912c-2cd6-4360-866e-076ffcb2afed', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which Indian coastal region receives the majority of its annual rainfall during the RETREATING North-East Winter Monsoon (October–November)?', 'Retreating NE monsoon winds pick up moisture over the Bay of Bengal and deposit heavy winter precipitation along the Coromandel coast.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be00cab0-91f2-4da6-a77e-d56af33664b0', 'The Coromandel Coast (Tamil Nadu and coastal Andhra Pradesh)', true, '434a912c-2cd6-4360-866e-076ffcb2afed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a6e00ca-af82-4bfa-9204-044904254dd2', 'The Malabar Coast', false, '434a912c-2cd6-4360-866e-076ffcb2afed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('807f611c-28d9-4be4-afba-3e2d04787844', 'The Konkan Coast', false, '434a912c-2cd6-4360-866e-076ffcb2afed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6c9bd47-bdf1-4e09-ae0b-7c4cf4b5abe9', 'The Gujarat Coast', false, '434a912c-2cd6-4360-866e-076ffcb2afed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6b2af16-da0b-4fe8-95d6-3045e5503426', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'What are the four physical soil zones of the Northern Plains from north to south along the Himalayan foothills?', 'Northern plains geomorphology: Bhabar (porous gravels) → Terai (swampy re-emergence) → Bhangar (older alluvium) → Khadar (annual renewed silt).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acb60029-2840-4f4b-9f62-a25545cabe9f', 'Bhabar (pebble zone where streams disappear) -> Terai (marshy wet jungle) -> Bhangar (older alluvial terrace) -> Khadar (new fertile flood plain)', true, 'a6b2af16-da0b-4fe8-95d6-3045e5503426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e9db217-dd29-4726-8172-c1b0fe2e5921', 'Desert -> Forest -> Sand -> Mud', false, 'a6b2af16-da0b-4fe8-95d6-3045e5503426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4985619a-67f4-4ba7-9e21-6034839f27e0', 'Black soil -> Red soil -> Laterite -> Peaty', false, 'a6b2af16-da0b-4fe8-95d6-3045e5503426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f27fc955-49b1-45ad-8ae5-efcc4cff3375', 'Mountain -> River -> Ocean -> Delta', false, 'a6b2af16-da0b-4fe8-95d6-3045e5503426');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e71d653-d8e1-422e-a945-f6dc6ae21e74', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which fertile soil formed from the weathering of ancient Deccan lava flows (basalt) is ideal for growing COTTON in Maharashtra and Gujarat?', 'Regur (Black Soil) is rich in clay minerals, highly moisture-retentive, and renowned for cotton agriculture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d8265fe-b4e3-43ef-be2c-4d42070e036c', 'Black Soil (Regur Soil / Black Cotton Soil)', true, '6e71d653-d8e1-422e-a945-f6dc6ae21e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8467bc0a-945a-4916-8118-2d4d2fb489ec', 'Alluvial Soil', false, '6e71d653-d8e1-422e-a945-f6dc6ae21e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('343461cd-2d6d-4747-8356-fdc062b26011', 'Laterite Soil', false, '6e71d653-d8e1-422e-a945-f6dc6ae21e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfee0474-1c85-4749-9c74-440acfb68af6', 'Red Soil', false, '6e71d653-d8e1-422e-a945-f6dc6ae21e74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('878e23ba-e012-4713-869c-861eb8e4b98d', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Where do the Western Ghats and the Eastern Ghats mountain ranges converge in South India?', 'The Western and Eastern Ghats meet at the Nilgiri orographic node in Tamil Nadu/Karnataka/Kerala.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb1d3057-5acc-405e-b010-c7797e2f6ae5', 'The Nilgiri Hills (Blue Mountains - with Dodabetta peak)', true, '878e23ba-e012-4713-869c-861eb8e4b98d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01aec9d0-1056-4196-8829-d40edd0c4935', 'The Cardamom Hills', false, '878e23ba-e012-4713-869c-861eb8e4b98d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f15d3af7-9eb3-47ed-9a3d-1aea6c0ea57f', 'The Anamalai Hills', false, '878e23ba-e012-4713-869c-861eb8e4b98d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c138bca3-b217-4823-b255-762dcd0cfa33', 'The Shevaroy Hills', false, '878e23ba-e012-4713-869c-861eb8e4b98d');
