INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('751b2c4b-a3dd-4301-a601-35744e9fc2f0', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3f08a622-854e-408a-9611-d785386e0ad5');
