INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6712c4a-4f90-4fee-8c37-6fb013d9f7f0', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Spot the IMPOSTER in the following group of Major River Tributaries and their Master River systems in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6129b8c-12a4-4913-97a5-0b3fb16c04d8', 'System 1', false, 'c6712c4a-4f90-4fee-8c37-6fb013d9f7f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d9b0e77-8adb-476d-9e91-661216983a9f', 'System 2', false, 'c6712c4a-4f90-4fee-8c37-6fb013d9f7f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4df39279-c242-4085-817e-e345b03544c6', 'System 3', false, 'c6712c4a-4f90-4fee-8c37-6fb013d9f7f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de3ac702-0e23-4ba9-a145-943853dab041', 'System 4 (Tungabhadra, Bhima, and Koyna are major tributaries of the KRISHNA RIVER, not the Narmada)', true, 'c6712c4a-4f90-4fee-8c37-6fb013d9f7f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0889039f-acef-4855-8ec9-a0a69b2dea73', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What are the ''Western Disturbances'' that bring crucial winter rainfall and snowfall to Northwest India (Punjab, Haryana, Jammu & Kashmir, Himachal)?', 'Mediterranean extratropical depressions transported via westerly jet streams sustain the vital winter Rabi wheat harvest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('936662b6-b21d-4d4e-a57c-de71934df4bb', 'Extratropical cyclonic low-pressure storms originating over the Mediterranean Sea, steered into northwest India by the Subtropical Westerly Jet Stream', true, '0889039f-acef-4855-8ec9-a0a69b2dea73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e3e477c-84dc-4c42-8fd4-fa361b8d681d', 'Dust storms blowing from the Thar desert', false, '0889039f-acef-4855-8ec9-a0a69b2dea73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ba4736e-9b42-4531-bcfa-723a1b052594', 'Cyclones rising from the Indian Ocean', false, '0889039f-acef-4855-8ec9-a0a69b2dea73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cea63993-1e75-43ad-9f76-9e8cf26c18da', 'Winds blowing from the South Pole', false, '0889039f-acef-4855-8ec9-a0a69b2dea73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8eb63ce8-e0b1-4bd7-b1db-83df4ab8f55e', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Match Column I (Indian Biosphere Reserves / National Parks) with Column II (Keystone Flora/Fauna & Geographic Features):
(a) Gulf of Mannar       -> (i) Marine Biosphere Reserve famous for Dugongs (Sea Cows) & coral reefs
(b) Sundarbans           -> (ii) Mangrove ecosystem, Royal Bengal Tiger, Sundari trees & estuarine crocodiles
(c) Great Rann of Kutch  -> (iii) White salt desert sanctuary of the Indian Wild Ass (Khur)
(d) Hemis National Park  -> (iv) High-altitude Ladakh park, global capital of the Snow Leopard', 'Gulf of Mannar = Dugongs; Sundarbans = Mangrove tigers; Rann of Kutch = Wild Ass; Hemis = Snow Leopards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a48c479b-25cd-4ed8-86e0-d2e731af960a', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '8eb63ce8-e0b1-4bd7-b1db-83df4ab8f55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7a16bb1-9ce6-40e4-85ea-8ff8298402aa', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '8eb63ce8-e0b1-4bd7-b1db-83df4ab8f55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa04ab4f-16a5-4130-97c8-9cada2688aec', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '8eb63ce8-e0b1-4bd7-b1db-83df4ab8f55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdd4c883-2081-40cd-96f0-ddcc864255ff', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '8eb63ce8-e0b1-4bd7-b1db-83df4ab8f55e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('306f8c68-2eca-432e-9b1e-42284eda7cfb', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Read the statements regarding India''s geomorphology:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38e46778-73f8-4103-be77-15f68a9c6a0e', 'Statements 1 and 2 only', true, '306f8c68-2eca-432e-9b1e-42284eda7cfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05e37f17-d0f0-43d0-a8cd-de7074dc8b9b', 'Statements 2 and 3 only', false, '306f8c68-2eca-432e-9b1e-42284eda7cfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('690a8673-0eb2-4dfd-9905-cba69f4562d7', 'Statements 1 and 3 only', false, '306f8c68-2eca-432e-9b1e-42284eda7cfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ce70271-182c-42a5-9840-314ff305d218', 'All Statements 1, 2, and 3', false, '306f8c68-2eca-432e-9b1e-42284eda7cfb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e94e7f16-02ef-4689-86cb-323e2c085ba0', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What is the strategic and ecological significance of the ''Siliguri Corridor'' (often called the ''Chicken''s Neck'')?', 'The Siliguri Corridor is the critical geopolitical chokepoint linking mainland India to the eight northeastern sister states.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f77eaf2-4f31-43a4-a4a0-4eb4cef43570', 'A narrow strip of land in West Bengal (~22 km wide at its narrowest) connecting the entire eight states of Northeast India with the rest of mainland India', true, 'e94e7f16-02ef-4689-86cb-323e2c085ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9dc7ba6-38d9-42e2-bfa1-b20b5029d5e1', 'A bridge between India and Sri Lanka', false, 'e94e7f16-02ef-4689-86cb-323e2c085ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd3a4a4a-8c09-4863-9549-a882c8897968', 'A mountain pass to Afghanistan', false, 'e94e7f16-02ef-4689-86cb-323e2c085ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d43fcd-0ad2-4f0b-a4b8-c058ec6048c0', 'A canal through the Thar desert', false, 'e94e7f16-02ef-4689-86cb-323e2c085ba0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36d1528b-17be-4e5b-b845-3de270390e7c', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Why is the Chota Nagpur Plateau in eastern India celebrated as the ''Ruhr of India''?', 'Like Germany''s Ruhr basin, the Chota Nagpur plateau is India''s mineral heartland, powering the nation''s steel and heavy manufacturing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b29e0157-1128-45b5-8ef3-1f050f7189a8', 'It contains the richest concentration of metallic and mineral wealth in India, including massive reserves of Iron Ore, Coal (Jharia, Bokaro), Mica, Bauxite, and Uranium', true, '36d1528b-17be-4e5b-b845-3de270390e7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3d358aa-0622-4f9f-bc0e-9fbd9a8d1cd1', 'Because it has the most rivers', false, '36d1528b-17be-4e5b-b845-3de270390e7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eb216a8-75e4-4668-887d-87ca479d1b5e', 'Because it is covered in snow all year', false, '36d1528b-17be-4e5b-b845-3de270390e7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25361fc1-7d35-492b-a979-61f1ec1838c8', 'Because it produces gold only', false, '36d1528b-17be-4e5b-b845-3de270390e7c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6ece147-8076-4951-8f6e-ea159d4ae0bd', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Consider four major multi-purpose river valley projects in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644df49f-5459-4028-bf5d-c7ae5bef0b62', 'Hydroelectric power generation, extensive canal irrigation networks for agriculture, flood mitigation, and industrial drinking water security', true, 'c6ece147-8076-4951-8f6e-ea159d4ae0bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cd91ea3-5dfa-44e0-88a8-22d92c6ad430', 'They stop all rivers from flowing', false, 'c6ece147-8076-4951-8f6e-ea159d4ae0bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('023100a9-123a-4cba-a4ec-916e594728ca', 'They are built only for boating tourist sports', false, 'c6ece147-8076-4951-8f6e-ea159d4ae0bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('964eaaf0-7847-4783-9f99-54f7908b48e9', 'They turn fresh water into salt water', false, 'c6ece147-8076-4951-8f6e-ea159d4ae0bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b876828-219c-4cb5-ba43-2b52b2cbfa45', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What is the ''Tropical Evergreen Forest'' biome in India (found in the Western Ghats, Northeast India, and Andaman & Nicobar)?', 'Tropical evergreen rainforests exhibit complex vertical stratification, dense multi-tiered canopies, and immense biodiversity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2af3b44-1ea1-4c14-8d12-421657802656', 'Dense, multi-layered rain forests receiving >200 cm rainfall with trees (Rosewood, Mahogany, Ebony) that do not shed leaves simultaneously, remaining green throughout the year', true, '3b876828-219c-4cb5-ba43-2b52b2cbfa45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31835039-ab8a-49e1-b33a-0562bd71fbba', 'Forests with thorny bushes and no leaves', false, '3b876828-219c-4cb5-ba43-2b52b2cbfa45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06a4a9f0-f288-41a1-b667-709ca407e08d', 'Forests that only grow in snow', false, '3b876828-219c-4cb5-ba43-2b52b2cbfa45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a5bedd4-f8e3-4ed7-b988-fe9635979433', 'Forests of pure pine needles', false, '3b876828-219c-4cb5-ba43-2b52b2cbfa45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53cdb9d0-ce2e-4c16-8f7b-40698dc0dae4', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What is the ''Indira Point'' in the Nicobar Islands?', 'Indira Point on Great Nicobar (submerged partially in the 2004 tsunami) marks India''s southernmost geographical point.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('837ecfb1-9b70-4164-a234-b0c8705f9e4b', 'The southernmost geographic point of the sovereign territory of the Republic of India (located at 6° 45'' N on Great Nicobar Island)', true, '53cdb9d0-ce2e-4c16-8f7b-40698dc0dae4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7692fdf1-b33a-4df9-bb09-c51cd0e73f92', 'The northernmost point in Kashmir', false, '53cdb9d0-ce2e-4c16-8f7b-40698dc0dae4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3214b59-b754-487b-8d5b-912479b92e8a', 'The highest peak in Rajasthan', false, '53cdb9d0-ce2e-4c16-8f7b-40698dc0dae4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea9f04ae-6207-4792-b51a-8e539d63a764', 'The easternmost point in Arunachal Pradesh', false, '53cdb9d0-ce2e-4c16-8f7b-40698dc0dae4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('898a2da2-06a6-4fbe-a5f7-b5d7ae1458c9', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Why is the Western Ghats recognized by UNESCO as one of the world''s eight ''Hottest Hotspots'' of Biological Diversity?', 'The Western Ghats harbor immense floral/faunal endemism (Lion-tailed macaque, Nilgiri tahr, Malabar gliders) under acute conservation vulnerability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ba76128-8f66-45f1-b742-ff082eb8b8e4', 'It harbors thousands of endemic species of flora, fauna, birds, amphibians, and reptiles found nowhere else on Earth, amidst high anthropogenic habitat pressure', true, '898a2da2-06a6-4fbe-a5f7-b5d7ae1458c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fbaa9d0-457e-4e74-b658-76c5e0b99ea9', 'Because it is the hottest desert on Earth', false, '898a2da2-06a6-4fbe-a5f7-b5d7ae1458c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b4614db-937d-422b-b3bf-5baeafc70405', 'Because it has no trees', false, '898a2da2-06a6-4fbe-a5f7-b5d7ae1458c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33775b6e-2e51-4ad8-b0db-ef70f48b905e', 'Because it has active gold mines', false, '898a2da2-06a6-4fbe-a5f7-b5d7ae1458c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80577b70-a106-40fb-abea-f6770da313b6', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What overarching geographic reality defines the Indian Subcontinent in Chapter 8 of General Knowledge?', 'Chapter 8 synthesizes India''s diverse physiography, drainage basins, tropical monsoon meteorology, and precious mineral-ecological patrimony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf6e9790-2ad1-42aa-bdbb-b2ed3820af7d', 'An extraordinary physical mosaic uniting towering Himalayan snow ranges, fertile riverine alluvial plains, ancient mineral-rich plateaus, sun-drenched coastlines, and monsoon rhythms that sustain India''s immense biological and civilizational vitality', true, '80577b70-a106-40fb-abea-f6770da313b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02f87699-0c3d-42d3-8160-408375c7e35c', 'A uniform desert with no physical variation', false, '80577b70-a106-40fb-abea-f6770da313b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74e0edb2-6b09-43dc-8fa5-bbe4100d78e4', 'An island completely cut off from the rest of the world', false, '80577b70-a106-40fb-abea-f6770da313b6');
