INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0fe05c2-fbaf-4c18-99df-6afa6bb05e1c', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Which revered Sufi saint of the Chishti order made AJMER in Rajasthan his spiritual hospice, drawing millions of pilgrims to his sacred Dargah?', 'Khwaja Muinuddin Chishti (1142–1236) established the Chishti silsila in Ajmer, preaching universal love, tolerance, and service to the destitute.', NOW()) ON CONFLICT DO NOTHING;
