INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8ece32a-d7b1-49db-bd3f-106f005708c4', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Which 15th-century saint-reformer introduced the ''Ekasarana Dharma'' (devotion to One Supreme Lord Krishna) in Assam, pioneering devotional music (Borgeet) and community prayer halls (Namghars)?', 'Srimanta Sankaradeva founded the Neo-Vaishnavite movement in Assam, establishing Satras and village Namghars (prayer houses).', NOW()) ON CONFLICT DO NOTHING;
