INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b7620a7-f597-4a6d-a960-6f3857a9b5e0', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What was Shankara''s philosophical doctrine of ''ADVAITA'' (Non-dualism) propounded in the 8th century in Kerala?', 'Adi Shankaracharya preached Advaita: absolute non-dual monism where Brahman alone is real, the empirical world is Maya, and Atman is Brahman.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('282f93fd-7cc2-4e25-8c07-fea453a507b3', 'The fundamental oneness and identity of the individual soul (Atman) with the ultimate Supreme Reality (Brahman) ; the world is Maya (illusion) and true liberation comes through knowledge (Jnana)', true, '6b7620a7-f597-4a6d-a960-6f3857a9b5e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9a46ec9-6496-4225-aa92-a40659f70bc6', 'That there are thousands of separate supreme gods', false, '6b7620a7-f597-4a6d-a960-6f3857a9b5e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18292fe1-3546-41d3-bf42-935277c1a378', 'That the world is made of pure gold', false, '6b7620a7-f597-4a6d-a960-6f3857a9b5e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a883c5fe-7fa1-4e3e-b384-2ad1de3fabd7', 'That humans can never attain salvation', false, '6b7620a7-f597-4a6d-a960-6f3857a9b5e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87530729-ad3e-44e6-98e1-6c1967fb1dca', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What was Ramanuja''s 11th-century philosophical doctrine of ''VISHISHTADVAITA'' (Qualified Non-dualism) preached in Tamil Nadu?', 'Ramanuja harmonized Vedanta with Bhakti: the individual soul is an organic part (amsha) of Vishnu, finding salvation through loving surrender (Prapatti).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66e1bdf4-1d90-4584-9f11-93610505914e', 'The individual soul remains distinct and qualified even when united with the Supreme Brahman through passionate, loving devotion (Bhakti) to Vishnu', true, '87530729-ad3e-44e6-98e1-6c1967fb1dca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a55edd3-0c3a-42db-9bdf-086205afdb23', 'That God has no love for humans', false, '87530729-ad3e-44e6-98e1-6c1967fb1dca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71fa3759-fd4d-43db-ba87-ee59d26db3f8', 'That all rituals must be conducted in silence', false, '87530729-ad3e-44e6-98e1-6c1967fb1dca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5993c073-811f-42c9-a278-8ad05df8f95a', 'That souls are completely destroyed after death', false, '87530729-ad3e-44e6-98e1-6c1967fb1dca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16425c32-9e04-4464-8daf-584843995633', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What are the famous canonical song anthologies of the Nayanars and the Alvars called in Tamil literature?', 'Nayanar hymns are compiled in the 12 Tirumurais (including Tevaram & Tiruvacakam); Alvar hymns comprise the 4,000 verses of the Divya Prabandham.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0041f79-740f-40da-96c4-16a00b940cb6', 'Nayanars: ''Tevaram'' and ''Tiruvacakam'' ; Alvars: ''Divya Prabandham''', true, '16425c32-9e04-4464-8daf-584843995633');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8d8b8b7-caa2-40ec-b9c9-6dd0bf67238a', 'Vedas and Upanishads', false, '16425c32-9e04-4464-8daf-584843995633');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebe6c986-6770-44d8-9558-b63e80ab40c9', 'Ramayana and Mahabharata', false, '16425c32-9e04-4464-8daf-584843995633');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38a9f8ec-585c-4e8f-b9ef-8acb33bc243c', 'Puranas and Gita', false, '16425c32-9e04-4464-8daf-584843995633');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9307a12-84c7-46b9-9052-58c27a8664ea', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What radical social reform did the Virashaiva Vachana literature champion in 12th-century medieval society?', 'Virashaiva Vachanas (by Basavanna, Allama, Akkamahadevi) attacked caste oppression, empty ritualism, and patriarchal subordination of women.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef706500-bdf7-4a09-b319-70c5a6dfa233', 'Fierce denunciation of caste hierarchies, untouchability, sacrificial animal slaughter, and ritual pollution, while asserting the spiritual equality and independence of women', true, 'd9307a12-84c7-46b9-9052-58c27a8664ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('255d7c92-a579-4abd-957b-8fc798d287bb', 'Building large stone prisons', false, 'd9307a12-84c7-46b9-9052-58c27a8664ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4330a601-cad0-45ac-9f9e-88166b9e434c', 'Banning all books and music', false, 'd9307a12-84c7-46b9-9052-58c27a8664ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e33453f9-f391-4c82-90e3-30436b6db597', 'Forcing people to fast every day', false, 'd9307a12-84c7-46b9-9052-58c27a8664ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50870bec-7723-4cd1-9d11-51410286501f', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Why did the medieval Bhakti saints of Maharashtra (Jnaneshwar, Eknath, Tukaram) REJECT the traditional concept of ascetic renunciation (Sannyasa)?', 'The Marathi saints humanized Bhakti: Tukaram proclaimed that he who recognizes the suffering of the distressed as his own is a true saint.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5f50fd6-1fd4-4689-b881-6c6fcdd2c233', 'They believed true spirituality lay in living as ordinary householders, earning an honest livelihood, and serving fellow human beings in distress with compassion (active social service)', true, '50870bec-7723-4cd1-9d11-51410286501f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a4cec5-3ff9-45ca-b1a9-2a63dcf402d9', 'Because they wanted to become wealthy kings', false, '50870bec-7723-4cd1-9d11-51410286501f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('265284ed-c295-4ae0-8450-6599f1b97011', 'Because they disliked nature', false, '50870bec-7723-4cd1-9d11-51410286501f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3a7ffb0-033a-4a4a-bfd6-d014d47ecfea', 'Because forests were too cold', false, '50870bec-7723-4cd1-9d11-51410286501f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5d34d74-8fd4-42bb-a75e-bf34a6353f66', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What were the ''Khanqahs'' of the Sufi masters in medieval India?', 'Khanqahs served as inclusive spiritual hospices where people of all faiths gathered for discourse, music, blessings, and community meals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d4aabb-77cf-4def-b89e-714c3e508838', 'Hospices and community centers where Sufi Pir masters taught disciples, hosted spiritual assemblies (Sama), and fed travelers, nobles, and commoners from all walks of life', true, 'd5d34d74-8fd4-42bb-a75e-bf34a6353f66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bcf7523-317f-4500-93ba-f67d3be50982', 'Military forts for weapons', false, 'd5d34d74-8fd4-42bb-a75e-bf34a6353f66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c21d690-09b1-47f5-9079-6adeeb794980', 'Royal tax collection offices', false, 'd5d34d74-8fd4-42bb-a75e-bf34a6353f66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7b816bd-7084-4de8-8f1e-ebe1d41fd8f0', 'Prisons for criminals', false, 'd5d34d74-8fd4-42bb-a75e-bf34a6353f66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93849cb6-904e-4a5f-babd-9999bdd858f6', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What is ''Zikr'' and ''Sama'' in the devotional spiritual practice of Sufi mysticism?', 'Sufi praxis: Zikr (contemplative remembrance of God) and Sama (ecstatic mystical music/qawwali) dissolve ego in divine love.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa8fec75-00e5-4c0e-930c-352b9a03f282', 'Zikr is the rhythmic chanting/repetition of the divine Name of God ; Sama is spiritual music and audition evoking divine ecstatic love', true, '93849cb6-904e-4a5f-babd-9999bdd858f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c1c9936-c917-4f19-8bef-e5a5732f09f4', 'Zikr is sword fighting and Sama is swimming', false, '93849cb6-904e-4a5f-babd-9999bdd858f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d09af250-b30b-4047-bdd4-1923f551db5c', 'Zikr is eating food and Sama is sleeping', false, '93849cb6-904e-4a5f-babd-9999bdd858f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3b21693-4b71-4a3f-adbf-129531e53520', 'Both are names of desert horses', false, '93849cb6-904e-4a5f-babd-9999bdd858f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1409fb62-be1d-4b89-a6e7-a552dd8c21e1', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What were the core principles of Guru Nanak''s spiritual teachings summarized in three cardinal pillars?', 'Guru Nanak''s core triadic ethics: Nam Japna (devotional remembrance), Kirt Karna (honest labor), and Vand Chhakna (charitable sharing).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc5a0cf8-b746-472d-99a1-d18d9d2eaca0', '1. Nam Japna (Chanting the Name of God) ; 2. Kirt Karna (Honest, ethical labor) ; 3. Vand Chhakna (Sharing one''s earnings with others in charity)', true, '1409fb62-be1d-4b89-a6e7-a552dd8c21e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f865c076-5e4c-49ee-8f07-05deabe24aa1', 'Fasting, Penance, and Forest Exile', false, '1409fb62-be1d-4b89-a6e7-a552dd8c21e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a8c7e98-98f5-4a78-af0e-9f41f47b5afe', 'Sacrifice, Rituals, and Pilgrimages', false, '1409fb62-be1d-4b89-a6e7-a552dd8c21e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0776a5e9-d9cb-41ad-b964-c2d024eb0cb1', 'Wars, Conquests, and Taxes', false, '1409fb62-be1d-4b89-a6e7-a552dd8c21e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4198edb1-a010-48e6-b866-d77242d3e0be', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What was the historical significance of the ''Langar'' (community kitchen) instituted by Guru Nanak and expanded by Guru Angad and Guru Amar Das?', 'Langar institutionalized radical social equality: emperor and peasant sat side by side in pangat, sharing identical food prepared communally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1840f77d-dcaf-4240-a8e2-cd004144afe7', 'People of ALL castes, religions, and social backgrounds sat together on the floor (Pangat) to eat the exact same meal together, completely destroying caste taboos and untouchability', true, '4198edb1-a010-48e6-b866-d77242d3e0be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61f8538f-8f34-4ad9-9cef-48dc9ad1133b', 'It was a restaurant for wealthy merchants', false, '4198edb1-a010-48e6-b866-d77242d3e0be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910a5371-4ecf-43bd-aba5-4f71c1c2b606', 'It was a feast held only once a year', false, '4198edb1-a010-48e6-b866-d77242d3e0be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c64df0b-d9da-4728-8e0a-698ba11916dd', 'Only kings were allowed to eat there', false, '4198edb1-a010-48e6-b866-d77242d3e0be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83942695-222e-48bd-a228-d34ebeb031f9', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Why did the Mughal Emperor Jahangir view the growing influence and autonomous political-military stature of Guru Arjan Dev Ji as a potential threat, leading to the Guru''s martyrdom in 1606?', 'Jahangir recorded in Tuzuk that the expanding spiritual authority of Guru Arjan Dev threatened imperial control, prompting state persecution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ffb699b-1fa2-4b12-88e9-13145ae22493', 'The Sikh community had transformed into a dynamic, prosperous, self-governing socio-religious brotherhood centered at Amritsar, attracting large numbers of both Hindu and Muslim followers', true, '83942695-222e-48bd-a228-d34ebeb031f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('396ac2d9-888d-45fe-b455-6eb74963ddc7', 'Because Guru Arjan refused to pay road tax', false, '83942695-222e-48bd-a228-d34ebeb031f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51c2f5c5-8ee7-4cad-bf01-e18c07dfd048', 'Because the Sikhs built a navy', false, '83942695-222e-48bd-a228-d34ebeb031f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e55a8013-3ccb-4b62-b059-70eec3c4cde1', 'Because of a boundary dispute over a farm', false, '83942695-222e-48bd-a228-d34ebeb031f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f53ad1e-1dcf-4c86-9997-d9bbba1ba5cb', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Who founded the ''Khalsa Panth'' (the community of the pure saint-soldiers) at Anandpur Sahib on Baisakhi Day in 1699, forging the Sikhs into a formidable martial and spiritual brotherhood?', 'Guru Gobind Singh Ji established the Khalsa in 1699 with the Five Ks (Kesh, Kangha, Kara, Kachhera, Kirpan) to defend justice against tyranny.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c691111-0301-435d-9bf0-0d0e7cb443bb', 'Guru Gobind Singh Ji (the 10th Sikh Guru)', true, '3f53ad1e-1dcf-4c86-9997-d9bbba1ba5cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a673467-184c-4911-9c7b-752294e5fc95', 'Guru Nanak Dev Ji', false, '3f53ad1e-1dcf-4c86-9997-d9bbba1ba5cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c9e2ee9-0f85-41f4-98be-87c435b1fcb1', 'Guru Tegh Bahadur Ji', false, '3f53ad1e-1dcf-4c86-9997-d9bbba1ba5cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbbcf2ad-6652-4ee6-b550-4ea9d1d4e229', 'Banda Singh Bahadur', false, '3f53ad1e-1dcf-4c86-9997-d9bbba1ba5cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca08600f-1f78-4911-8a8a-2a5085151722', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Which blind poet of Braj composed the monumental devotional anthology ''Sursagar'', celebrating the childhood lilas of Lord Krishna in Brajbhasha?', 'Surdas (a disciple of Vallabhacharya) composed the Sursagar, Sur Saravali, and Sahitya Lahari celebrating Krishna''s Vatsalya and Madhurya rasas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98402662-752a-4741-8925-d4f3e24c59b4', 'Sant Surdas', true, 'ca08600f-1f78-4911-8a8a-2a5085151722');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77750ffb-dff3-4caa-81d7-589ed0110efc', 'Tulsidas', false, 'ca08600f-1f78-4911-8a8a-2a5085151722');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6bc2d9d-be24-4381-a011-977d50de5d22', 'Kabir', false, 'ca08600f-1f78-4911-8a8a-2a5085151722');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04dc76a6-c817-4f91-be05-fd06fa0bba03', 'Raskhan', false, 'ca08600f-1f78-4911-8a8a-2a5085151722');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01d22f0a-10e6-4489-b0be-db3932587b48', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What was the ''Ekasarana Dharma'' propagated by Sankaradeva in Assam?', 'Sankaradeva''s Ekasarana Dharma focused on monotheistic Krishna bhakti centered on congregational chanting in village Namghars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d746c32-fb99-42d5-9f4d-2233f9562321', 'Devotional surrender to the Supreme Lord Krishna alone, discarding idol worship and complex rituals, and seeking spiritual solace in chanting the Name of God (Nam-Kirtan)', true, '01d22f0a-10e6-4489-b0be-db3932587b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8230751e-3f4a-46e1-9d48-730fafa7ff78', 'Worship of 100 deities simultaneously', false, '01d22f0a-10e6-4489-b0be-db3932587b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('650c473b-12d9-4dcd-bed0-bfaa428049d6', 'Renunciation of all food', false, '01d22f0a-10e6-4489-b0be-db3932587b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('898bbf75-12a0-4ef3-8237-26ebd91edad6', 'Building giant stone statues', false, '01d22f0a-10e6-4489-b0be-db3932587b48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('827ada52-67cc-4f32-9e93-3acdaf08f4f2', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What were the ''Nathpanthis, Siddhas, and Yogis'' who challenged conventional ritual orthodoxy in northern India?', 'Nathpanthis and Yogis (associated with Gorakhnath) taught Hatha Yoga, breath control, and inner esoteric realization beyond ritual dogma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af1fee2c-ea1d-49a6-9a66-82b84fd638df', 'Renouncers from lower artisanal groups who advocated intense meditation on formless reality, breathing exercises (Pranayama), yogasanas, and mind-body purification to attain liberation', true, '827ada52-67cc-4f32-9e93-3acdaf08f4f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b33aeb5-b0ce-4ef6-81ec-a42dd089f2f3', 'Royal priests in Delhi palaces', false, '827ada52-67cc-4f32-9e93-3acdaf08f4f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69481a1b-be74-4bc0-917e-0b201a0a76ff', 'Foreign merchants who sold silk', false, '827ada52-67cc-4f32-9e93-3acdaf08f4f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47e1b391-e85b-47c1-8e60-344b78031c6d', 'Soldiers who fought on horses', false, '827ada52-67cc-4f32-9e93-3acdaf08f4f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0642cbcc-df2a-47db-af45-a9fd00c544f8', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Who was the revered 14th-century Sufi saint of Delhi known as ''Mehboob-e-Ilahi'' (Beloved of God), who lived in Ghyaspur (Delhi) and inspired Amir Khusrau?', 'Hazrat Nizamuddin Auliya preached boundless charity and tolerance; his court disciple Amir Khusrau pioneered Hindavi and Qawwali music.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6081ff23-ef51-44de-b2c1-2402e3eb7f0e', 'Hazrat Nizamuddin Auliya', true, '0642cbcc-df2a-47db-af45-a9fd00c544f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0538787-5a40-419d-9452-b527a431855e', 'Khwaja Muinuddin Chishti', false, '0642cbcc-df2a-47db-af45-a9fd00c544f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d5935bd-0628-4c4d-8f86-7b4518fc3b49', 'Baba Farid', false, '0642cbcc-df2a-47db-af45-a9fd00c544f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04281e08-0d6c-464b-a585-a29008ddd745', 'Qutbuddin Bakhtiyar Kaki', false, '0642cbcc-df2a-47db-af45-a9fd00c544f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('018bf271-d51a-45d4-80ea-e94de679ee63', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'In what language did Kabir compose his powerful verses (Sakhis, Dohas, and Rekhtas)?', 'Kabir wrote in direct, forceful vernacular Hindi (Saddukkadi), utilizing sharp colloquial idioms that pierced through scholastic pretension.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a0bea9-990a-44b1-b5ff-ad94cfe3f19f', 'In the rough, rustic colloquial vernacular Hindi of the common people (Saddukkadi / Khari Boli / Bhojpuri), making them directly accessible to ordinary peasants and weavers', true, '018bf271-d51a-45d4-80ea-e94de679ee63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac0990a0-9f8a-4e52-8408-b880fdd4500b', 'In difficult classical Sanskrit only', false, '018bf271-d51a-45d4-80ea-e94de679ee63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7228d7c2-a704-4ccf-bfe6-5294f82a2dc7', 'In ancient Latin', false, '018bf271-d51a-45d4-80ea-e94de679ee63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d74ca038-fb88-4bcf-87bd-4cb5104df839', 'In Portuguese', false, '018bf271-d51a-45d4-80ea-e94de679ee63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b90ed864-ef60-4b69-b307-ec9ea7b0ea27', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af915f6b-c2b0-444b-80ca-b641ad17dfcb', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'b90ed864-ef60-4b69-b307-ec9ea7b0ea27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5607fd34-b748-42f7-9bfc-1e6c8ed7c171', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'b90ed864-ef60-4b69-b307-ec9ea7b0ea27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72682de3-e26b-4160-94b7-aacf5c63c7f8', '(A) is true, but (R) is false.', false, 'b90ed864-ef60-4b69-b307-ec9ea7b0ea27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('795ba6e8-a08d-4b4b-ae39-fa719faa1e7a', '(A) is false, but (R) is true.', false, 'b90ed864-ef60-4b69-b307-ec9ea7b0ea27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('182d75c6-aaa6-4c49-919e-7b18abebdd25', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Spot the IMPOSTER in the following group of Bhakti Saints and their signature devotional masterworks:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffde44b6-376e-4461-abc5-ff79bdb734d5', 'Masterwork 1', false, '182d75c6-aaa6-4c49-919e-7b18abebdd25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab4065dc-67c7-44e1-9c86-617094cec2f4', 'Masterwork 2', false, '182d75c6-aaa6-4c49-919e-7b18abebdd25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88d517bf-1a6c-4d8a-867e-0b8315bb7aec', 'Masterwork 3', false, '182d75c6-aaa6-4c49-919e-7b18abebdd25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('976c0a89-0798-45a7-adbd-578fda15dade', 'Masterwork 4 (Sant Kabir composed the BIJAK, Sakhis, and Dohas, NOT French chemistry books)', true, '182d75c6-aaa6-4c49-919e-7b18abebdd25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5723bfa9-18c3-4ad0-8ed4-aca1f4fb61a8', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Analyze the philosophical distinction between ''NIRGUNA BHAKTI'' and ''SAGUNA BHAKTI'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea68ec79-7393-4486-ac45-bf3d45261144', 'Nirguna Bhakti (Kabir, Guru Nanak) envisioned God as the abstract, formless, attribute-less ultimate spiritual Truth ; Saguna Bhakti (Tulsidas, Surdas, Mirabai, Chaitanya) worshipped God in tangible human incarnational forms (Avatars like Rama and Krishna) through personal devotion', true, '5723bfa9-18c3-4ad0-8ed4-aca1f4fb61a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3630f91-8f81-4d29-a739-a99c90abeca8', 'Nirguna Bhakti is worship of trees and Saguna Bhakti is worship of fire', false, '5723bfa9-18c3-4ad0-8ed4-aca1f4fb61a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('369dad8d-7cf2-4253-bf36-876aa4a45699', 'Nirguna Bhakti was practiced only by kings', false, '5723bfa9-18c3-4ad0-8ed4-aca1f4fb61a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92902d8a-3b45-4ed6-854b-9ee6cd3cc6df', 'Both are identical without any difference', false, '5723bfa9-18c3-4ad0-8ed4-aca1f4fb61a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('334368f6-e044-4dba-b518-88b074f97cd0', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Match Column I (Bhakti / Sufi Masters) with Column II (Primary Regional Sphere of Devotion):
(a) Basavanna              -> (i) Karnataka (Virashaiva Movement / Vachanas)
(b) Jnaneshwar & Tukaram   -> (ii) Maharashtra (Varkari Vitthala Bhakti)
(c) Srimanta Sankaradeva   -> (iii) Assam (Brahmaputra Valley / Satras & Namghars)
(d) Khwaja Muinuddin       -> (iv) Rajasthan (Ajmer / Chishti Sufi Silsila)', 'Basavanna = Karnataka; Jnaneshwar/Tukaram = Maharashtra; Sankaradeva = Assam; Muinuddin = Ajmer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d35a6b5b-7050-414e-8389-ac4a22513bab', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '334368f6-e044-4dba-b518-88b074f97cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c09f32d1-3ccc-4318-b94f-223b2b022477', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '334368f6-e044-4dba-b518-88b074f97cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72c707df-8d18-430b-8553-8af55142d121', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '334368f6-e044-4dba-b518-88b074f97cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f386131f-68c0-4d4b-841d-49404f990ef4', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '334368f6-e044-4dba-b518-88b074f97cd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5172f10f-d017-4b6b-8c04-92fa9600950f', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Read the statements regarding the Varkari pilgrimage tradition in Maharashtra:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8155338a-44fb-42ed-ad75-0ac1a59936fb', 'Statements 1 and 2 only', true, '5172f10f-d017-4b6b-8c04-92fa9600950f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caa57707-caba-48ae-b79f-f131376f2d04', 'Statements 2 and 3 only', false, '5172f10f-d017-4b6b-8c04-92fa9600950f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c4c3331-d69e-4624-ac13-d48bd3ed2c57', 'Statements 1 and 3 only', false, '5172f10f-d017-4b6b-8c04-92fa9600950f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1619ca48-167c-4a68-bb08-8d324593aa98', 'All Statements 1, 2, and 3', false, '5172f10f-d017-4b6b-8c04-92fa9600950f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdf21bb4-3332-467f-a883-1df78ee45310', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Why did Mirabai''s fearless rejection of caste and royal Mewar palace luxury make her an enduring symbol of feminist and social defiance in Indian history?', 'Mirabai dismantled Rajput patriarchal and caste norms: taking Sant Ravidas (a Chamar) as guru and proclaiming autonomous spiritual sovereignty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fcc2ce7-ecd0-4245-a6de-209f5caa0e41', 'She openly defied royal patriarchy, drank poison sent by the Rana without fear, accepted the low-caste leather worker Sant Ravidas as her Guru, and sang in public streets dedicated only to Krishna', true, 'bdf21bb4-3332-467f-a883-1df78ee45310');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('452c6abb-7e39-4a54-bfca-752fed8e5472', 'She built an army to conquer Delhi', false, 'bdf21bb4-3332-467f-a883-1df78ee45310');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bffba82c-52a7-4041-8448-468aed6f8f75', 'She became the queen of Portugal', false, 'bdf21bb4-3332-467f-a883-1df78ee45310');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51469ec1-57fa-4844-a371-da5a92719f2d', 'She abolished music in Rajasthan', false, 'bdf21bb4-3332-467f-a883-1df78ee45310');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4791d377-5a31-4ccf-b24b-f396f7ea755b', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'How did the compilation of the ''Guru Granth Sahib'' embody an unprecedented inter-faith ecumenical syncretism?', 'The Guru Granth Sahib is an ecumenical masterpiece of interfaith harmony, enshrining Bhagat Bani from 15 diverse Hindu and Muslim saints.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26ccb16a-0c39-49a3-952b-39339066fc32', 'It sanctified and bound together the holy compositions of Sikh Gurus alongside the verses of Hindu Bhakti saints (Jaidev, Namdev, Ravidas, Ramananda) and Muslim Sufi mystics (Baba Farid, Kabir, Bhagat Bhikhan) under one supreme eternal Scripture', true, '4791d377-5a31-4ccf-b24b-f396f7ea755b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9580eab1-877c-4a91-8565-2e02bd4dbd30', 'It excluded all non-Sikh writers', false, '4791d377-5a31-4ccf-b24b-f396f7ea755b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05dd62aa-1a9c-4b9c-9a74-0a48114c1503', 'It was written only in Persian', false, '4791d377-5a31-4ccf-b24b-f396f7ea755b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12a6472c-edcc-417b-a2f0-b3734487d00b', 'It contained only military strategies', false, '4791d377-5a31-4ccf-b24b-f396f7ea755b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a39a303-aa42-4bd0-a069-e0cdcb2b9a2a', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'What was the revolutionary social function of ''Namghars'' established by Sankaradeva across Assamese villages?', 'Namghars functioned as decentralized socio-cultural epicenters integrating congregational prayer, Assamese Vaishnava drama (Bhaona), and village democracy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e529ce8-61f0-4274-8125-ae259466344a', 'Village community prayer halls that served simultaneously as sacred sanctuaries for chanting, local courts for resolving disputes, community theaters for Ankiya Nat dramas, and village libraries', true, '7a39a303-aa42-4bd0-a069-e0cdcb2b9a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55c88451-3ae9-44d0-bcae-6d14441f339d', 'Commercial banks for money lending', false, '7a39a303-aa42-4bd0-a069-e0cdcb2b9a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ac1fc5a-0c45-4e71-a2d2-ece43ce6a77e', 'Forts with cannons', false, '7a39a303-aa42-4bd0-a069-e0cdcb2b9a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aea7147a-9033-4687-884e-86659789a8b2', 'Prisons for villagers', false, '7a39a303-aa42-4bd0-a069-e0cdcb2b9a2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41d03a94-a445-4819-af2d-5caf44c834d3', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Consider four foundational tenets of the Chishti Sufi order in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc785bbc-0901-4f22-b484-a1c723925277', 'Their genuine ascetic purity, deep compassion for the impoverished, and cultural synthesis with local Indian traditions', true, '41d03a94-a445-4819-af2d-5caf44c834d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14515d41-d584-4cba-9b0b-7d5468f8abef', 'Their massive private armies', false, '41d03a94-a445-4819-af2d-5caf44c834d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03b7a8be-87e2-4fd1-b0b7-264e1065b9d9', 'Their royal tax collections', false, '41d03a94-a445-4819-af2d-5caf44c834d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a037c2-e56c-4e47-abd8-c483194d09c7', 'Their strict enforcement of foreign languages', false, '41d03a94-a445-4819-af2d-5caf44c834d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43d23515-ed75-4706-94c4-0036fca1d3d7', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Why did Sant Kabir relentlessly lampoon both orthodox Hindu Pandits and Muslim Qazis in his verses?', 'Kabir''s razor-sharp verses deconstructed scholastic dogmatism: ''Moko kahan dhundhe re bande, main to tere paas mein'' (Where do you search for Me? I am beside you).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9171d8d6-2f8a-44b9-96fa-4ccc5072a94a', 'He believed that external ritual dogmas (sacred threads, temple pilgrimages, circumcisions, ritual fasts) were meaningless hypocrisies that divided humanity and blinded people to the divine residing within every human heart', true, '43d23515-ed75-4706-94c4-0036fca1d3d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7565db0-2a5f-4110-b3f2-0c5204c3c50d', 'Because Kabir wanted to become a king', false, '43d23515-ed75-4706-94c4-0036fca1d3d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5b450ac-70aa-4e0c-b666-e7261b2e8adb', 'Because Kabir had no religion', false, '43d23515-ed75-4706-94c4-0036fca1d3d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba871e43-7d3f-4f38-8379-c27d4fd88b79', 'Because he wanted to sell books', false, '43d23515-ed75-4706-94c4-0036fca1d3d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c417216f-18e9-43c9-8b1f-d7755585647e', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'What is the enduring cultural impact of the Bhakti movement on the modern regional languages and literature of India?', 'Bhakti literature was the catalyst for the flowering of modern Indian languages, infusing vernacular poetry with emotional resonance and philosophical depth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86eba083-7771-4118-87db-950cbe9b8f0a', 'It gave birth to the golden age of regional Indian vernacular literatures (Tamil, Kannada, Marathi, Hindi, Assamese, Bengali, Punjabi, Gujarati), elevating popular speech into exquisite classical literary idioms', true, 'c417216f-18e9-43c9-8b1f-d7755585647e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95e0e288-2368-4bfc-806a-6315c9f393ea', 'It caused all regional languages to disappear', false, 'c417216f-18e9-43c9-8b1f-d7755585647e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32d8c361-2c8a-4510-bc67-245227329fb1', 'It forced everyone to speak English', false, 'c417216f-18e9-43c9-8b1f-d7755585647e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('198e5c2a-43fe-49e3-bcb8-cc1c01630908', 'It stopped people from writing poetry', false, 'c417216f-18e9-43c9-8b1f-d7755585647e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97b01307-6fc1-4d1f-bfb1-7619129379e1', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'What overarching humanist spiritual vision is celebrated in Chapter 8 of NCERT Class 7 History?', 'Chapter 8 illuminates the transformative spiritual ethos of medieval India: love as the supreme path to God and universal compassion as the highest worship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bd54b83-02a8-4338-89c7-cb6625fc5fad', 'The transcendent universal message that the divine is accessed not through rigid caste barriers, empty ritualism, or institutional dogma, but through pure, unconditional love, inner moral righteousness, and compassionate service to all living beings', true, '97b01307-6fc1-4d1f-bfb1-7619129379e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a94ba89c-ed41-4085-96cd-391ad8fbd990', 'That only kings can achieve salvation', false, '97b01307-6fc1-4d1f-bfb1-7619129379e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87c590cd-54c2-4daa-864e-9834df70d2ad', 'That rituals are the only way to reach God', false, '97b01307-6fc1-4d1f-bfb1-7619129379e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9fbf9f9-2f57-46f8-8ac8-c3e24f011d5f', 'That humanity was divided forever without hope', false, '97b01307-6fc1-4d1f-bfb1-7619129379e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('565ce24f-0644-4e35-b219-84a199a8eecb', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', 'संज्ञा के स्थान पर प्रयुक्त होने वाले सार्थक शब्दों को व्याकरण में क्या कहते हैं?', 'सर्वनाम: जो शब्द संज्ञा के स्थान पर भाषा को सुंदर, संक्षिप्त और पुनरुक्ति-दोष से मुक्त बनाने के लिए प्रयुक्त होते हैं, उन्हें सर्वनाम कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c24eb30-f9a2-493f-8d5e-83044acde1a0', 'सर्वनाम (Pronoun)', true, '565ce24f-0644-4e35-b219-84a199a8eecb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa77e57f-11d9-4ee6-9534-21b3f5f2adda', 'विशेषण', false, '565ce24f-0644-4e35-b219-84a199a8eecb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13238df1-ef77-4ffc-846b-ba72a3e8c8d5', 'क्रिया', false, '565ce24f-0644-4e35-b219-84a199a8eecb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d566a99-5e31-4763-b93c-5951fa161a54', 'कारक', false, '565ce24f-0644-4e35-b219-84a199a8eecb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79a829c1-19f7-4c78-881f-44e846c37985', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', 'हिंदी व्याकरण में सर्वनाम के मुख्य रूप से कितने भेद होते हैं?', 'सर्वनाम के 6 भेद होते हैं: 1. पुरुषवाचक, 2. निश्चयवाचक, 3. अनिश्चयवाचक, 4. संबंधवाचक, 5. प्रश्नवाचक, 6. निजवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae78c240-7b10-48ac-b7d1-d0b064e4e1d7', '6 भेद (पुरुषवाचक, निश्चयवाचक, अनिश्चयवाचक, संबंधवाचक, प्रश्नवाचक, निजवाचक)', true, '79a829c1-19f7-4c78-881f-44e846c37985');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2252162-1d43-4e32-8066-0fd398f94a90', '4 भेद', false, '79a829c1-19f7-4c78-881f-44e846c37985');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3bae133-ee03-4321-ba48-1c1398d2948a', '5 भेद', false, '79a829c1-19f7-4c78-881f-44e846c37985');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57fd9d9b-f6c4-4cb8-bae3-9788f27dad5d', '8 भेद', false, '79a829c1-19f7-4c78-881f-44e846c37985');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24207157-d1e7-409b-baac-8b9f6f307aec', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', 'वक्ता (बोलने वाले), श्रोता (सुनने वाले) अथवा किसी अन्य व्यक्ति के लिए प्रयुक्त होने वाले सर्वनाम को क्या कहते हैं?', 'पुरुषवाचक सर्वनाम वक्ता, श्रोता या अन्य तीसरे व्यक्ति का बोध कराते हैं (इसके 3 भेद होते हैं: उत्तम, मध्यम, अन्य पुरुष)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2c8f5f-8513-4758-91ad-c358fca441f7', 'पुरुषवाचक सर्वनाम (Personal Pronoun)', true, '24207157-d1e7-409b-baac-8b9f6f307aec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9c5a811-0c39-4a6c-8129-6b50bf7db695', 'निश्चयवाचक सर्वनाम', false, '24207157-d1e7-409b-baac-8b9f6f307aec');
