INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0791402b-2e0e-48a1-8fd1-694ed0338411', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', '''मैं, हम, मुझे, मेरा, हमारा'' शब्द पुरुषवाचक सर्वनाम के किस उप-भेद के अंतर्गत आते हैं?', 'बोलने वाला (वक्ता) अपने लिए जिन सर्वनामों का प्रयोग करता है, वे ''उत्तम पुरुष'' कहलाते हैं (जैसे: मैं, हम)।', NOW()) ON CONFLICT DO NOTHING;
