INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40d8fbe4-363b-4916-b42e-a1725928f985', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', '''तू, तुम, आप, तुझे, तुम्हारा'' शब्द पुरुषवाचक सर्वनाम के किस उप-भेद के अंतर्गत आते हैं?', 'श्रोता (सुनने वाले) के लिए प्रयुक्त होने वाले सर्वनाम ''मध्यम पुरुष'' कहलाते हैं (जैसे: तू, तुम, आप)।', NOW()) ON CONFLICT DO NOTHING;
