INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ebee798e-cab3-4a7c-a213-c4f757e9a4a5', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', '''वह, वे, यह, ये, उसे, उनका'' शब्द पुरुषवाचक सर्वनाम के किस उप-भेद के अंतर्गत आते हैं?', 'वक्ता और श्रोता जिसके बारे में बात करते हैं, वे ''अन्य पुरुष'' कहलाते हैं (जैसे: वह, वे)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f5f3c04-7930-4e31-b5e8-6d39b12f9173', 'अन्य पुरुष (Third Person - जिसके विषय में बात की जाए)', true, 'ebee798e-cab3-4a7c-a213-c4f757e9a4a5');
