INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c989b7d-f8f6-4a0b-a245-33969371a9e0', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', 'जो सर्वनाम किसी निश्चित व्यक्ति, वस्तु या घटना की ओर संकेत करते हैं (जैसे: ''यह मेरी पुस्तक है'', ''वह मेरा घर है''), उन्हें क्या कहते हैं?', 'निश्चयवाचक सर्वनाम निकट या दूर की निश्चित वस्तु/व्यक्ति का निश्चयपूर्वक बोध कराते हैं (यह, वह, ये, वे)।', NOW()) ON CONFLICT DO NOTHING;
