INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('caf3455c-6ba8-4f0d-a2f9-5dffe03ab3ca', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', '''दरवाजे पर कोई खड़ा है।'' और ''दूध में कुछ गिर गया है।'' वाक्यों में ''कोई'' और ''कुछ'' किस प्रकार के सर्वनाम हैं?', 'अनिश्चयवाचक सर्वनाम किसी निश्चित वस्तु या व्यक्ति का बोध नहीं कराते (प्राणियों के लिए ''कोई'' तथा पदार्थों के लिए ''कुछ'')।', NOW()) ON CONFLICT DO NOTHING;
