INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20921687-18c4-48ac-a25c-dfefe0f8b599', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', '''जो परिश्रम करेगा, वह सफल होगा।'' और ''जैसी करनी, वैसी भरनी।'' वाक्यों में ''जो-वह'', ''जैसी-वैसी'' किस प्रकार के सर्वनाम हैं?', 'संबंधवाचक सर्वनाम वाक्य में किसी दूसरी संज्ञा या सर्वनाम से संबंध प्रकट करते हैं (जो-सो, जैसा-वैसा, जिसकी-उसकी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('143235e7-f3e9-478b-bc6c-b3357416b8f0', 'संबंधवाचक सर्वनाम (Relative Pronoun)', true, '20921687-18c4-48ac-a25c-dfefe0f8b599');
