INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4a45f40-5aa7-46ef-ac9f-95caa5e92953', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', 'जिन सर्वनाम शब्दों का प्रयोग किसी व्यक्ति, वस्तु या घटना के विषय में प्रश्न पूछने के लिए किया जाता है (जैसे: ''वहाँ कौन खड़ा है?'', ''तुम क्या लाए हो?''), वे क्या कहलाते हैं?', 'प्रश्नवाचक सर्वनाम: प्रश्न पूछने के लिए प्रयुक्त होने वाले शब्द (कौन, क्या, किसे, किसको, कहाँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c581c41-3992-4636-a9b6-d891605c1c6a', 'प्रश्नवाचक सर्वनाम (Interrogative Pronoun)', true, 'c4a45f40-5aa7-46ef-ac9f-95caa5e92953');
