INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e0b56c9-175e-40a4-8a69-e15ddf3efbfe', 'अनिश्चयवाचक सर्वनाम', false, 'c4a45f40-5aa7-46ef-ac9f-95caa5e92953');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33a66296-dacd-424a-a4f6-d0d7dcc03e97', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', '''मैं अपना काम स्वयं (खुद / अपने आप) करूँगा।'' वाक्य में ''स्वयं'' और ''अपने आप'' किस प्रकार का सर्वनाम है?', 'निजवाचक सर्वनाम: कर्ता अपने लिए जिन शब्दों का प्रयोग करता है (स्वयं, खुद, अपने आप, आप ही)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51ad9500-df18-4edf-a398-616aa4fa1101', 'निजवाचक सर्वनाम (Reflexive Pronoun)', true, '33a66296-dacd-424a-a4f6-d0d7dcc03e97');
