INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c528beda-78e2-475a-bcce-c6db1a470688', 'प्रश्नवाचक सर्वनाम', false, '33a66296-dacd-424a-a4f6-d0d7dcc03e97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e2046bb-53ed-4624-9772-e6426a959741', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', 'हिंदी भाषा में मूल सर्वनाम शब्दों की संख्या कुल कितनी मानी जाती है?', 'हिंदी व्याकरण में 11 मूल (मौलिक) सर्वनाम माने गए हैं: मैं, तू, आप, यह, वह, जो, सो, कोई, कुछ, कौन, क्या।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46f55730-8014-479d-94e3-7d721562a78a', '11 मूल सर्वनाम (मैं, तू, आप, यह, वह, जो, सो, कोई, कुछ, कौन, क्या)', true, '7e2046bb-53ed-4624-9772-e6426a959741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae13035a-7bf6-40a6-a654-3c09e61ddf92', '5 मूल सर्वनाम', false, '7e2046bb-53ed-4624-9772-e6426a959741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c751c1c-489e-4b8b-8c16-e9e932a51782', '20 मूल सर्वनाम', false, '7e2046bb-53ed-4624-9772-e6426a959741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ce0cc1d-1332-4967-8a9f-04089903ee57', '7 मूल सर्वनाम', false, '7e2046bb-53ed-4624-9772-e6426a959741');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b794619-6227-4649-87ec-24838441176a', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', 'निश्चयवाचक सर्वनाम और सार्वनामिक विशेषण में क्या मुख्य अंतर होता है?', '''यह मेरी पुस्तक है'' = निश्चयवाचक सर्वनाम; ''यह पुस्तक मेरी है'' = सार्वनामिक विशेषण (संज्ञा से पूर्व प्रयुक्त)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5784176-d90f-44d7-b907-a171db677a2c', 'जब ''यह'' या ''वह'' अकेले आकर संज्ञा के स्थान पर प्रयुक्त हों, तो वे ''निश्चयवाचक सर्वनाम'' होते हैं (जैसे: ''यह मेरा घर है'') ; परन्तु जब वे संज्ञा से ठीक पहले लगकर उसकी विशेषता बताएँ, तो वे ''सार्वनामिक विशेषण'' बन जाते हैं (जैसे: ''यह घर मेरा है'')', true, '5b794619-6227-4649-87ec-24838441176a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8b0a481-6d79-43a4-a216-3246cb05378f', 'दोनों में कोई अंतर नहीं होता', false, '5b794619-6227-4649-87ec-24838441176a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9757ac4d-7300-4515-9d7c-9d21c4dbfde5', 'सार्वनामिक विशेषण केवल पुल्लिंग होते हैं', false, '5b794619-6227-4649-87ec-24838441176a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c8e9a31-bdc9-42e6-8afa-b91216d84f38', 'सर्वनाम कभी वाक्य में प्रयुक्त नहीं हो सकते', false, '5b794619-6227-4649-87ec-24838441176a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00dee9cc-2423-4f83-8dc4-341ff93fa80c', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''आप'' शब्द का प्रयोग मध्यम पुरुष और निजवाचक सर्वनाम—दोनों में किस प्रकार भिन्न अर्थ में होता है?', 'आदरार्थक मध्यम पुरुष: ''आप बैठिए''; निजवाचक (स्वयं के अर्थ में): ''वह अपने आप चला जाएगा''।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('153d1701-5a45-4abc-82b8-5d663d7b1642', 'श्रोता के आदर के लिए प्रयुक्त ''आप'' मध्यम पुरुष होता है (जैसे: ''आप कब आए?''); जबकि कर्ता द्वारा अपने लिए प्रयुक्त ''आप'' निजवाचक होता है (जैसे: ''मैं यह काम आप ही कर लूँगा'')', true, '00dee9cc-2423-4f83-8dc4-341ff93fa80c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0172206-0ab5-4034-a4a9-02f88701c598', 'दोनों सदैव एकवचन होते हैं', false, '00dee9cc-2423-4f83-8dc4-341ff93fa80c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f0c28a1-6e14-4c2c-8b18-793eb78e5da6', '''आप'' केवल बहुवचन में ही आता है', false, '00dee9cc-2423-4f83-8dc4-341ff93fa80c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('389a45cf-acdb-4ec5-aac1-154f5f758f9c', 'निजवाचक में ''आप'' का प्रयोग अशुद्ध है', false, '00dee9cc-2423-4f83-8dc4-341ff93fa80c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78cffc0d-f8e8-4b06-be07-14381dae1b01', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''जिसकी लाठी, उसकी भैंस।'' वाक्य में ''जिसकी'' और ''उसकी'' सर्वनाम के किस भेद के उदाहरण हैं?', '''जिसकी... उसकी'' परस्पर आश्रित उपवाक्यों में संबंध स्थापित करने वाले संबंधवाचक सर्वनाम हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('577a3bee-1f16-485d-8ff3-1f2f112669e7', 'संबंधवाचक सर्वनाम', true, '78cffc0d-f8e8-4b06-be07-14381dae1b01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da14c83b-d0ac-431e-a993-61a1133a11bc', 'निश्चयवाचक सर्वनाम', false, '78cffc0d-f8e8-4b06-be07-14381dae1b01');
