INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24b5610e-c6c3-45c5-b90c-0c29da80aa45', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''पानी में कुछ पड़ा है।'' वाक्य में ''कुछ'' का प्रयोग किस संदर्भ में हुआ है?', '''कुछ'' का प्रयोग अप्राणिवाचक (निर्जीव/द्रव्य) अनिश्चित वस्तुओं के लिए होता है (''कोई'' का सजीव प्राणियों के लिए)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('319bec2b-cc4a-4e08-afcb-db3afeed416a', 'निर्जीव वस्तु या पदार्थ के लिए अनिश्चयवाचक सर्वनाम के रूप में', true, '24b5610e-c6c3-45c5-b90c-0c29da80aa45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f2a3413-63f5-4574-b8d0-09ac6b8eade7', 'सजीव प्राणी के लिए', false, '24b5610e-c6c3-45c5-b90c-0c29da80aa45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10d26c9f-c6f7-4073-8231-cdc21b3a3114', 'प्रश्न पूछने के लिए', false, '24b5610e-c6c3-45c5-b90c-0c29da80aa45');
