INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8f2e54d-99ef-41cd-92fb-becbe877f470', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''बाहर कोई आया है।'' वाक्य में ''कोई'' का प्रयोग किस संदर्भ में हुआ है?', '''कोई'' प्राणिवाचक अनिश्चयवाचक सर्वनाम है (जैसे: कोई आया है, किसी ने बुलाया है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e965d72b-c176-42c1-bf33-c8393b1a9ae6', 'सजीव प्राणी (व्यक्ति) के लिए अनिश्चयवाचक सर्वनाम के रूप में', true, 'f8f2e54d-99ef-41cd-92fb-becbe877f470');
