INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c3f9cc2-84d3-4ed9-8bad-5508d914c8f5', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''तुमने क्या खाया है?'' वाक्य में ''क्या'' किस प्रकार का सर्वनाम है?', '''क्या'' अप्राणिवाचक प्रश्नवाचक सर्वनाम है (''कौन'' प्राणिवाचक प्रश्नवाचक है)।', NOW()) ON CONFLICT DO NOTHING;
