INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aeeb7852-e978-453b-b3c2-707f65f92742', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', 'सर्वनाम शब्दों में किस कारक की विभक्ति का प्रयोग कभी नहीं होता?', 'सर्वनाम शब्दों में केवल 7 कारकों (कर्ता से अधिकरण तक) की ही रूप-रचना होती है; संबोधन कारक सर्वनामों में नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f4bd315-0cf0-4f64-adc7-8daf9c4bf306', 'संबोधन कारक (हे, अरे, भो का प्रयोग सर्वनामों के साथ नहीं होता)', true, 'aeeb7852-e978-453b-b3c2-707f65f92742');
