INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6be17aa0-bb39-4651-8404-74201e498904', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''मैं'' (उत्तम पुरुष एकवचन) का करण कारक में एकवचन रूप क्या बनेगा?', 'मैं + से (करण कारक) = मुझसे / मेरे द्वारा।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c40e2f04-dca1-4848-a283-5439e33d5825', 'मुझसे / मेरे द्वारा', true, '6be17aa0-bb39-4651-8404-74201e498904');
