INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4439209-1480-4186-bb73-e5564c60e32c', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''वह'' (अन्य पुरुष एकवचन) का संप्रदान कारक में बहुवचन रूप क्या होगा?', 'वह (बहुवचन ''वे'') + को/के लिए = उन्हें / उनके लिए / उनको।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('022ae02b-5d0c-438c-b15c-c8e5ef0f78fa', 'उन्हें / उनके लिए / उनको', true, 'c4439209-1480-4186-bb73-e5564c60e32c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b45aab4a-ab72-44e7-828f-769e4c72fe10', 'उसको', false, 'c4439209-1480-4186-bb73-e5564c60e32c');
