INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d02d7c59-9498-4f36-a935-dc034ffc2984', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', 'निम्नलिखित वाक्यों में से ''अशुद्ध सर्वनाम प्रयोग'' वाला वाक्य चुनिए:', 'हिंदी मानक व्याकरण में ''तेरे को / मेरे को'' अमानक और अशुद्ध है; इसके स्थान पर ''तुझे/तुम्हें'' और ''मुझसे'' का प्रयोग होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c990e260-4cde-482d-a4ac-78e683cef3d8', '''तेरे को मेरे से क्या काम है?'' (अशुद्ध रूप ; शुद्ध होगा: ''तुम्हें मुझसे क्या काम है?'')', true, 'd02d7c59-9498-4f36-a935-dc034ffc2984');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef152d08-a8b5-428b-8db3-02fb38a9a869', '''आप यहाँ बैठिए।''', false, 'd02d7c59-9498-4f36-a935-dc034ffc2984');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72c58ebe-340b-4193-a60e-b5d15e25fe8c', '''वह अपना काम कर रहा है।''', false, 'd02d7c59-9498-4f36-a935-dc034ffc2984');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16d4d6a0-fefc-4145-848b-d9fd0e4466b8', '''जो पढ़ेगा, वह पास होगा।''', false, 'd02d7c59-9498-4f36-a935-dc034ffc2984');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('364d439c-a57a-4d2b-a888-9ce3bc52d64e', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''यह वही बालक है, जिसे कल पुरस्कार मिला था।'' वाक्य में ''जिसे'' सर्वनाम का कौन-सा रूप है?', '''जिसे'' संबंधवाचक सर्वनाम ''जो'' का कर्म कारक एकवचन रूप है (जो + को = जिसे)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da47f8fd-14d0-4b05-b039-997e980b4738', 'संबंधवाचक सर्वनाम (कर्म कारक रूप)', true, '364d439c-a57a-4d2b-a888-9ce3bc52d64e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbff185b-de31-4c29-bf2b-468aee1be194', 'निजवाचक सर्वनाम', false, '364d439c-a57a-4d2b-a888-9ce3bc52d64e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44cedfb1-ae59-47fa-8692-b2ce6a0f7edb', 'अनिश्चयवाचक सर्वनाम', false, '364d439c-a57a-4d2b-a888-9ce3bc52d64e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e2002bb-8fe4-4883-8d20-78b8b50b8aa3', 'पुरुषवाचक सर्वनाम', false, '364d439c-a57a-4d2b-a888-9ce3bc52d64e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d493ef14-bb6d-4aa3-a599-847e0f7ac377', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''हम कल मुंबई जाएँगे।'' वाक्य में रेखांकित सर्वनाम ''हम'' किस वचन और पुरुष में है?', '''हम'' उत्तम पुरुष का बहुवचन रूप है (एकवचन ''मैं'' होता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4204106a-6c46-4e39-a2ba-4f6337371cdb', 'बहुवचन, उत्तम पुरुष', true, 'd493ef14-bb6d-4aa3-a599-847e0f7ac377');
