INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49831553-2077-4bd8-8dff-4dded39d96bb', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''उसकी गाय बहुत सीधी है।'' वाक्य में ''उसकी'' किस कारक का रूप है?', 'वह + का/के/की = उसका / उसकी / उसके (संबंध कारक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('288aa27b-0142-4ba2-9ef6-3d7c7f2ff339', 'संबंध कारक (वह + की = उसकी)', true, '49831553-2077-4bd8-8dff-4dded39d96bb');
