INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85151b73-6754-4c5e-9136-a4f2d0d150d7', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''वे सब अपने घर चले गए।'' वाक्य में ''अपने'' किस सर्वनाम का उदाहरण है?', '''अपना / अपनी / अपने'' निजवाचक सर्वनाम के रूप हैं, जो कर्ता के स्वयं के संबंध का बोध कराते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c46d94f0-f8cd-4d50-88c6-6796f5972b72', 'निजवाचक सर्वनाम (या संबंधवाचक निज रूप)', true, '85151b73-6754-4c5e-9136-a4f2d0d150d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf1634ff-b26d-412c-b5dd-9400b2335a2a', 'प्रश्नवाचक सर्वनाम', false, '85151b73-6754-4c5e-9136-a4f2d0d150d7');
