INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('515b1534-9c95-442a-b93e-2832326be42f', 'मध्यम पुरुष', false, '85151b73-6754-4c5e-9136-a4f2d0d150d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df2ed60d-60de-4cb5-be25-ee10186f5bf7', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''कोई तुम्हें बुला रहा है।'' वाक्य में ''कोई'' और ''तुम्हें'' क्रमशः कौन-से सर्वनाम हैं?', '''कोई'' अनिश्चयवाचक है और ''तुम्हें'' मध्यम पुरुष (तुम + को) है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dce14722-e1a7-4765-aada-1c860fd5d5b8', '''कोई'' = अनिश्चयवाचक सर्वनाम ; ''तुम्हें'' = मध्यम पुरुषवाचक सर्वनाम', true, 'df2ed60d-60de-4cb5-be25-ee10186f5bf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faa40a28-5229-4822-90b1-7bc27765bc88', '''कोई'' = निश्चयवाचक ; ''तुम्हें'' = उत्तम पुरुष', false, 'df2ed60d-60de-4cb5-be25-ee10186f5bf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f97d7f95-424e-4eaa-bc15-ee0a2bbae77e', '''कोई'' = प्रश्नवाचक ; ''तुम्हें'' = निजवाचक', false, 'df2ed60d-60de-4cb5-be25-ee10186f5bf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b70fec63-d9ee-458a-a561-5a63d4e3c590', 'दोनों निजवाचक हैं', false, 'df2ed60d-60de-4cb5-be25-ee10186f5bf7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e0bd15b-830e-4f73-9db4-ecccf961c148', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''सच्चा मित्र वही है, जो विपत्ति में काम आए।'' वाक्य में ''वही-जो'' किस सर्वनाम युग्म का बोध कराते हैं?', '''वही... जो'' सह-संबंधी सर्वनाम हैं जो दो उपवाक्यों को परस्पर जोड़ते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('352ed665-6fe3-4482-a516-f6dfc55edf05', 'संबंधवाचक सर्वनाम', true, '3e0bd15b-830e-4f73-9db4-ecccf961c148');
