INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb5ece89-8a49-47e8-8a89-d013bceb7d6e', 'अनिश्चयवाचक सर्वनाम', false, '3e0bd15b-830e-4f73-9db4-ecccf961c148');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91761c22-401f-458a-9709-174acaa127fe', 'निजवाचक सर्वनाम', false, '3e0bd15b-830e-4f73-9db4-ecccf961c148');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69b8f76a-bae5-4bf0-8174-e918b68db41d', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df303cbf-7b3e-4f6c-bafc-f445b97ee896', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '69b8f76a-bae5-4bf0-8174-e918b68db41d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dd75518-9a8e-4f76-99d3-dd409fa4adc4', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '69b8f76a-bae5-4bf0-8174-e918b68db41d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1c556d4-fe73-4510-bc50-a5da19b82902', '(A) सही है, परन्तु (R) गलत है।', false, '69b8f76a-bae5-4bf0-8174-e918b68db41d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee5265ff-6f12-4ef7-bd5b-57b947e007df', '(A) गलत है, परन्तु (R) सही है।', false, '69b8f76a-bae5-4bf0-8174-e918b68db41d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63e13296-e7ab-41d7-b25e-e9eaa5346bc8', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'Spot the IMPOSTER in the following group of सर्वनाम और उनके भेद वर्गीकरण में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a6883c6-2dfc-4928-bb0a-8c1e78525801', 'वर्गीकरण 1', false, '63e13296-e7ab-41d7-b25e-e9eaa5346bc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6650e7-3387-4e0a-8b0d-4be01b3f5364', 'वर्गीकरण 2', false, '63e13296-e7ab-41d7-b25e-e9eaa5346bc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ee198fe-58bc-4fdd-aa2f-bdb44b0db67b', 'वर्गीकरण 3', false, '63e13296-e7ab-41d7-b25e-e9eaa5346bc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efeef71f-b52a-4397-83c9-d1dc9b2d57c0', 'वर्गीकरण 4 (''सुंदर'' सर्वनाम नहीं, बल्कि गुणवाचक विशेषण [Adjective] है)', true, '63e13296-e7ab-41d7-b25e-e9eaa5346bc8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfd342e3-673e-4a38-910b-a78164c66351', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'सुमेलित कीजिए (सर्वनाम शब्द और उनका सही भेद):
(क) जो... सो -> (i) संबंधवाचक सर्वनाम
(ख) आप ही    -> (ii) निजवाचक सर्वनाम
(ग) कोई      -> (iii) अनिश्चयवाचक सर्वनाम
(घ) कौन      -> (iv) प्रश्नवाचक सर्वनाम', 'जो-सो = संबंधवाचक; आप ही = निजवाचक; कोई = अनिश्चयवाचक; कौन = प्रश्नवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cf5748f-4d29-4ec4-b5c7-ab365bbc91e2', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, 'cfd342e3-673e-4a38-910b-a78164c66351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dec092a4-1dc9-4889-bf93-235cebc1862d', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, 'cfd342e3-673e-4a38-910b-a78164c66351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c055dbc8-a3bd-43e9-a967-8e692df174c9', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'cfd342e3-673e-4a38-910b-a78164c66351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3fe9a7c-b83d-4cb1-9262-f843c1585f8e', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'cfd342e3-673e-4a38-910b-a78164c66351');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97c8b122-eb91-4d48-9a02-635ffa45cc15', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''निजवाचक सर्वनाम'' का बिल्कुल शुद्ध प्रयोग हुआ है?', '''स्वयं'' का प्रयोग कर्ता के अपने आत्म-बोध हेतु निजवाचक सर्वनाम के रूप में शुद्ध है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f96f4191-b990-4292-a728-45211e9f78b1', '''मैं यह निबंध स्वयं अपने हाथों से लिखूँगा।''', true, '97c8b122-eb91-4d48-9a02-635ffa45cc15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6954dbc-a9bc-4aa9-bc68-a69aba674370', '''आप भला तो जग भला'' में ''आप'' केवल अन्य पुरुष है।', false, '97c8b122-eb91-4d48-9a02-635ffa45cc15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('855595ba-229b-4c33-b200-6e0366789408', '''मुझको मेरे को काम करने दो।''', false, '97c8b122-eb91-4d48-9a02-635ffa45cc15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d565d97-690d-4f85-b024-3552406dc59f', '''कोई ने मेरी पुस्तक चुरा ली।''', false, '97c8b122-eb91-4d48-9a02-635ffa45cc15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e971215d-7ae2-4266-be7a-dd54ecd85a26', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''यह'' सर्वनाम के तिर्यक (विभक्ति-सहित) एकवचन और बहुवचन रूप क्रमशः क्या होते हैं?', '''यह'' का तिर्यक रूप एकवचन में ''इस'' और बहुवचन में ''इन'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdc0f41c-6222-48e2-b9d6-921e7d562055', 'एकवचन: ''इस'' (जैसे: इसने, इसको, इससे) ; बहुवचन: ''इन'' (जैसे: इन्होंने, इनको, इनसे)', true, 'e971215d-7ae2-4266-be7a-dd54ecd85a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f7e0ab8-31a8-4faf-8329-3b3b147ae982', 'एकवचन: उस ; बहुवचन: उन', false, 'e971215d-7ae2-4266-be7a-dd54ecd85a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed21a8e2-1a5c-4e7f-9295-1a184912a659', 'एकवचन: जिस ; बहुवचन: जिन', false, 'e971215d-7ae2-4266-be7a-dd54ecd85a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93e96884-8488-47e0-bacf-49b096e80007', 'एकवचन: किस ; बहुवचन: किन', false, 'e971215d-7ae2-4266-be7a-dd54ecd85a26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd37d90e-a9cb-4f79-9f78-0b51aebcf73d', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''वह'' सर्वनाम के तिर्यक (विभक्ति-सहित) एकवचन और बहुवचन रूप क्रमशः क्या होते हैं?', '''वह'' का तिर्यक रूप एकवचन में ''उस'' और बहुवचन में ''उन'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16b2adca-b9ed-4ad5-85f4-27caeb49a526', 'एकवचन: ''उस'' (जैसे: उसने, उसको, उससे) ; बहुवचन: ''उन'' (जैसे: उन्होंने, उनको, उनसे)', true, 'bd37d90e-a9cb-4f79-9f78-0b51aebcf73d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3703f6c1-bc86-4319-b5a8-aaabf965ce14', 'एकवचन: इस ; बहुवचन: इन', false, 'bd37d90e-a9cb-4f79-9f78-0b51aebcf73d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff199d0e-2fbf-476f-a7e8-c282fa9d09b0', 'एकवचन: जो ; बहुवचन: सो', false, 'bd37d90e-a9cb-4f79-9f78-0b51aebcf73d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cb8aa2b-9272-447c-b5ff-f7c22de87cad', 'एकवचन: आप ; बहुवचन: हम', false, 'bd37d90e-a9cb-4f79-9f78-0b51aebcf73d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53a5bf0f-d06c-4cad-8f46-e00ab13a0a4b', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से ''शुद्ध वाक्य'' का चयन कीजिए:', 'कर्ता के स्वयं के संदर्भ में ''मेरा/उसके/हमारा'' के स्थान पर ''अपना/अपनी/अपने'' का प्रयोग ही व्याकरणिक दृष्टि से शुद्ध होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f55abf3-3667-4b30-8c9d-74616c6c6dec', '''मैंने अपना काम समय पर पूरा कर लिया है।'' (शुद्ध निजवाचक अन्वय)', true, '53a5bf0f-d06c-4cad-8f46-e00ab13a0a4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e654559-b204-4194-9c79-5693983611de', '''मैंने मेरा काम समय पर पूरा कर लिया है।''', false, '53a5bf0f-d06c-4cad-8f46-e00ab13a0a4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('177ff5bb-f058-47e9-b684-25b6ac57f702', '''उसने उसके भाई को बुलाया।''', false, '53a5bf0f-d06c-4cad-8f46-e00ab13a0a4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ca522e1-83a3-4c57-b664-aad4c442cba0', '''हम हमारा कर्तव्य जानते हैं।''', false, '53a5bf0f-d06c-4cad-8f46-e00ab13a0a4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a46b4472-28ed-44ec-ab04-d5fc2c2ae4d1', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'संयुक्त सर्वनाम (Compound Pronouns) जैसे ''कोई-न-कोई'', ''कुछ-न-कुछ'', ''जो-कोई'', ''सब-कुछ'' किस प्रकार के सर्वनाम होते हैं?', 'डॉ. दीमशित्स के अनुसार, ''कोई न कोई, कुछ न कुछ, जो कोई, सब कुछ'' संयुक्त सर्वनाम कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4872625-607f-4063-861a-cc85644aff7c', 'जब दो या दो से अधिक सर्वनाम शब्द मिलकर एक विशिष्ट यौगिक सर्वनाम का निर्माण करते हैं', true, 'a46b4472-28ed-44ec-ab04-d5fc2c2ae4d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07145804-f630-4d4b-b7ae-30c5113d6411', 'क्रिया विशेषण होते हैं', false, 'a46b4472-28ed-44ec-ab04-d5fc2c2ae4d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86c02ed9-f2f7-401a-8cc2-5cd7e29bab04', 'तद्धित प्रत्यय होते हैं', false, 'a46b4472-28ed-44ec-ab04-d5fc2c2ae4d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b67af582-b5e1-4131-b5b0-e6287133d01e', 'अव्ययीभाव समास के उदाहरण मात्र होते हैं', false, 'a46b4472-28ed-44ec-ab04-d5fc2c2ae4d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f278668-239d-4f8b-81df-ff7a87049027', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''गांधीजी राष्ट्रपिता कहलाए। आपने देश को अहिंसा का पाठ पढ़ाया।'' इस दूसरे वाक्य में ''आपने'' किस पुरुष का बोध करा रहा है?', 'किसी अनुपस्थित आदरणीय महापुरुष का परिचय देते समय ''आप'' का प्रयोग ''अन्य पुरुष'' के रूप में होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f393f7a0-a0ab-404d-bc34-f4ed8096504f', 'अन्य पुरुष (आदरार्थक ऐतिहासिक महापुरुष के परिचय के संदर्भ में ''आप'' का अन्य पुरुष के रूप में प्रयोग)', true, '6f278668-239d-4f8b-81df-ff7a87049027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38a4ec7f-87b9-4e31-86c5-f1ae80fceb1a', 'मध्यम पुरुष', false, '6f278668-239d-4f8b-81df-ff7a87049027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d06420a-54ff-4f08-ab9d-eaf7f90a5b86', 'उत्तम पुरुष', false, '6f278668-239d-4f8b-81df-ff7a87049027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1422003a-a96d-4b55-9649-d16492c657d2', 'निजवाचक', false, '6f278668-239d-4f8b-81df-ff7a87049027');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f02b2f4-364b-40e9-9791-64778684c9b4', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''किस-किस ने अपना गृहकार्य नहीं किया?'' वाक्य में ''किस-किस'' किस प्रकार का सर्वनाम रूप है?', 'प्रश्नवाचक सर्वनाम की पुनरुक्ति (''किस-किस'', ''क्या-क्या'') बहुलता और व्यापकता का बोध कराती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('247b165a-47fe-407d-b583-b326ea20bec9', 'पुनरुक्त प्रश्नवाचक सर्वनाम (विस्तार एवं अनेकता का बोध कराने वाला)', true, '9f02b2f4-364b-40e9-9791-64778684c9b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7381a8c0-7212-4d03-b3a7-4aa2bf1abeef', 'अनिश्चयवाचक सर्वनाम', false, '9f02b2f4-364b-40e9-9791-64778684c9b4');
