INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d59f6d4-5b04-4a44-905b-f79aaa21d45b', 'निजवाचक सर्वनाम', false, '9f02b2f4-364b-40e9-9791-64778684c9b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76a776c9-2e48-4bd8-8a3e-691e0238c21f', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''जो करेगा, सो भरेगा।'' वाक्य में ''सो'' के स्थान पर आधुनिक मानक हिंदी में किस सर्वनाम का प्रयोग अधिक प्रचलित है?', 'प्राचीन हिंदी में ''सो'' संबंधवाचक था; आधुनिक मानक हिंदी में ''जो'' के सह-संबंधी के रूप में ''वह'' प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f50d37ed-6b1f-4b9e-af3d-6514c1eb20f2', 'वह (जैसे: ''जो करेगा, वह भरेगा'')', true, '76a776c9-2e48-4bd8-8a3e-691e0238c21f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dd3f159-4eb7-4bfa-b41a-ce65c3e18ed8', 'यह', false, '76a776c9-2e48-4bd8-8a3e-691e0238c21f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('759f501d-93f4-4f89-b688-6c0ad3f61c0d', 'आप', false, '76a776c9-2e48-4bd8-8a3e-691e0238c21f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8653cd98-92ca-4fb2-8be6-79df9e244bc6', 'कुछ', false, '76a776c9-2e48-4bd8-8a3e-691e0238c21f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0cd31bad-4c83-40e8-be3b-1a55ac5ee117', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'सर्वनाम (Pronoun) के सम्यक ज्ञान और सटीक प्रयोग का भाषा की अभिव्यक्ति में क्या सर्वोच्च महत्व है?', 'सर्वनाम संज्ञा की नीरस पुनरुक्ति दूर कर गद्य एवं पद्य में प्रवाहमयता, संक्षिप्तता और संरचनात्मक सुदृढ़ता प्रदान करते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efd24339-d60e-4857-858e-e630c123fb79', 'सर्वनाम संज्ञा की अवांछित पुनरावृत्ति (Repetition) को रोककर भाषा में संक्षिप्तता, लालित्य, गतिशीलता और तार्किक सुसंबद्धता (Cohesion) स्थापित करते हैं', true, '0cd31bad-4c83-40e8-be3b-1a55ac5ee117');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('379965b1-1ddd-4409-8eff-7fb3c87df76a', 'सर्वनाम केवल काव्य में प्रयुक्त होते हैं', false, '0cd31bad-4c83-40e8-be3b-1a55ac5ee117');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04de1073-6444-49b2-bfbd-6e6ed020d3db', 'सर्वनाम के बिना भी भाषा पूर्णतः शुद्ध रहती है', false, '0cd31bad-4c83-40e8-be3b-1a55ac5ee117');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e3e74ad-b124-466b-9bb5-870807827b6d', 'सर्वनाम केवल संख्याओं को गिनने के काम आते हैं', false, '0cd31bad-4c83-40e8-be3b-1a55ac5ee117');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f2092c3-543a-4045-9d14-84c22530f49f', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is defined as the total distance covered by a moving object per unit of time?', 'Speed is the scalar physical rate of change of position: Speed = Distance covered / Time taken.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b15bca8-fa6d-4520-9d9f-ed7006c41e87', 'Speed (Speed = Distance / Time)', true, '5f2092c3-543a-4045-9d14-84c22530f49f');
