INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdea9134-51d3-43e0-a318-932de8727b57', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is the basic SI unit of SPEED?', 'The standard SI unit of distance is metre (m) and time is second (s), making the SI unit of speed m/s.', NOW()) ON CONFLICT DO NOTHING;
