INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75ca9c70-bda4-4182-9676-20ba9efaa4be', 'Kilometre per hour (km/h)', false, 'bdea9134-51d3-43e0-a318-932de8727b57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d694fc0-4732-4e6f-97ee-78f7238656cd', 'Metre per minute', false, 'bdea9134-51d3-43e0-a318-932de8727b57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('516754da-cff8-486f-884f-3cfa39ba153f', 'Centimetre per second', false, 'bdea9134-51d3-43e0-a318-932de8727b57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35faba97-8bb5-4827-9b7a-b9b8db640d41', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is the basic SI unit of TIME?', 'The International System of Units (SI) base unit of time is the second (s).', NOW()) ON CONFLICT DO NOTHING;
