INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2f6e908-8df4-4dc4-bc84-0c46b338b77f', 'Hour (h)', false, '35faba97-8bb5-4827-9b7a-b9b8db640d41');
