INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f62a1b24-da38-40a5-9e86-225099fd120a', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is the time taken by a pendulum to complete ONE FULL OSCILLATION called?', 'The Time Period of a pendulum is the duration required for one complete to-and-fro cycle.', NOW()) ON CONFLICT DO NOTHING;
