INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b085607-a925-4134-ae0a-3e2afc2ff168', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'Which ancient astronomical time-measuring instrument at Jantar Mantar (New Delhi and Jaipur) measures time by tracking the moving shadow of the Sun cast on a calibrated dial?', 'A sundial uses the gnomon''s solar shadow cast across graduated hour arcs to track solar time.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e532c4d7-3c2e-4877-979a-b1ca6f8bf0e5', 'Sundial (e.g. Samrat Yantra)', true, '8b085607-a925-4134-ae0a-3e2afc2ff168');
