INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ec8a85a-cacb-4a8e-be8a-ab7a16de921f', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'Which dashboard instrument in automobiles records and indicates the INSTANTANEOUS speed of the vehicle in km/h?', 'A speedometer measures and displays the vehicle''s instantaneous travel speed in km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13fedea9-7ee4-4f9c-a66f-b216395c8138', 'Speedometer', true, '6ec8a85a-cacb-4a8e-be8a-ab7a16de921f');
