INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07d722e3-f5dc-440c-8c52-0bde7fabb650', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'Which vehicle dashboard instrument measures and displays the TOTAL DISTANCE traveled by the vehicle in kilometres?', 'An odometer (mileometer) computes total cumulative vehicular distance in kilometres.', NOW()) ON CONFLICT DO NOTHING;
