INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbd6ff1c-2f75-4ae7-b7d2-108f7dfb86a2', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'A car covers a distance of 100 km in 2 hours. What is the average speed of the car?', 'Average speed = Total distance / Total time = 100 km / 2 h = 50 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45b5e969-fae8-4f14-a64a-911360d829dd', '50 km/h (Speed = 100 km / 2 h = 50 km/h)', true, 'fbd6ff1c-2f75-4ae7-b7d2-108f7dfb86a2');
