INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d13782a-c1dd-45ca-8358-16b02abf4d77', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What shape does the Distance-Time Graph of an object moving with CONSTANT UNIFORM SPEED have?', 'For constant speed, distance is directly proportional to time (d = v·t), yielding a straight linear slope on a distance-time graph.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46ae008b-20c0-41fb-b1bb-e4fe94898234', 'A straight straight inclined line passing through the origin', true, '8d13782a-c1dd-45ca-8358-16b02abf4d77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('506ef5e6-ab3e-4490-beca-2babdd1ff0ed', 'A curved wavy line', false, '8d13782a-c1dd-45ca-8358-16b02abf4d77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18f28949-92fc-4be1-b701-01ef7d84b777', 'A circle', false, '8d13782a-c1dd-45ca-8358-16b02abf4d77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6371d428-2de6-45f6-9480-377fd052be5e', 'A zig-zag line', false, '8d13782a-c1dd-45ca-8358-16b02abf4d77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff7d467d-110b-4e20-b418-ec6520cfa621', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What does a HORIZONTAL FLAT LINE parallel to the time axis on a Distance-Time Graph represent?', 'Zero slope (horizontal line) indicates distance remains constant as time elapses, meaning speed = 0 (object at rest).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7594fdf3-c2b4-4197-b354-f5823aba7408', 'The object is stationary (at rest / not moving)', true, 'ff7d467d-110b-4e20-b418-ec6520cfa621');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a941a24-5b07-40db-bcaa-8440f713cd4f', 'The object is moving at light speed', false, 'ff7d467d-110b-4e20-b418-ec6520cfa621');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4a85537-cee2-4176-9506-5701c1c7e486', 'The object is moving backwards', false, 'ff7d467d-110b-4e20-b418-ec6520cfa621');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b225b04-6e81-451f-b1e5-4df73ea7d3b7', 'The object is accelerating', false, 'ff7d467d-110b-4e20-b418-ec6520cfa621');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ba5798f-10c9-4177-97bb-a3cf7b41ad4c', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Which famous Italian scientist discovered that a pendulum of a given length always takes the EXACT SAME TIME to complete one oscillation (Isochronism of the Pendulum)?', 'Galileo observed swinging cathedral chandeliers and proved that pendulum period depends solely on length, independent of mass or small amplitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74816641-bb54-4905-acb8-c6c86175adc1', 'Galileo Galilei (in 1583)', true, '5ba5798f-10c9-4177-97bb-a3cf7b41ad4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72409fe4-2e10-4cea-b70f-416b4a64b43f', 'Isaac Newton', false, '5ba5798f-10c9-4177-97bb-a3cf7b41ad4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cfcfd4b-ff30-4d68-86eb-bb70daff74fb', 'Albert Einstein', false, '5ba5798f-10c9-4177-97bb-a3cf7b41ad4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b2c2e14-fd71-446f-9b8c-e40f034609c3', 'René Laennec', false, '5ba5798f-10c9-4177-97bb-a3cf7b41ad4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83ab5e3c-fbbd-4a19-acfd-1348df34d995', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'A simple pendulum takes 32 seconds to complete 20 full oscillations. What is the TIME PERIOD of the pendulum?', 'Time period T = 32 s / 20 = 1.6 seconds per oscillation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7897ca43-e05e-47c0-b750-f2fba6717382', '1.6 seconds (Time Period = Total time / Number of oscillations = 32 / 20 = 1.6 s)', true, '83ab5e3c-fbbd-4a19-acfd-1348df34d995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4343e3fe-0042-4e08-938b-208554bcf223', '0.625 s', false, '83ab5e3c-fbbd-4a19-acfd-1348df34d995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed2fd8d3-cb09-4c2b-a677-e02b28b62489', '640 s', false, '83ab5e3c-fbbd-4a19-acfd-1348df34d995');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a18fe4c-9b20-41be-b802-00cf2535fa06', '2.0 s', false, '83ab5e3c-fbbd-4a19-acfd-1348df34d995');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b630a6fd-97db-4f09-9a27-25924b5f670f', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Convert a speed of 72 km/h into metres per second (m/s):', 'Conversion factor: 1 km/h = 5/18 m/s. 72 × (5/18) = 20 m/s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bef105c6-a238-434e-8e7f-1378ed956e73', '20 m/s (72 × (5 / 18) = 4 × 5 = 20 m/s)', true, 'b630a6fd-97db-4f09-9a27-25924b5f670f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf99d856-7201-4407-a556-4408f2d53579', '25 m/s', false, 'b630a6fd-97db-4f09-9a27-25924b5f670f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('893fd70f-3b04-4ba5-8792-9e798da58d03', '15 m/s', false, 'b630a6fd-97db-4f09-9a27-25924b5f670f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b764c17f-fc6c-4141-9f85-721848255cde', '30 m/s', false, 'b630a6fd-97db-4f09-9a27-25924b5f670f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ad01a46-07c7-4f96-a819-a5e4453a0733', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Convert a speed of 15 m/s into kilometres per hour (km/h):', 'Conversion factor: 1 m/s = 18/5 km/h. 15 × (18/5) = 54 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d2718a2-1fea-4fe4-86fd-6a8436c39f55', '54 km/h (15 × (18 / 5) = 3 × 18 = 54 km/h)', true, '8ad01a46-07c7-4f96-a819-a5e4453a0733');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9411eb7d-5634-4458-a387-586e398b5adb', '60 km/h', false, '8ad01a46-07c7-4f96-a819-a5e4453a0733');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d4e6f88-f2cd-4fdf-8efe-36d131f90533', '45 km/h', false, '8ad01a46-07c7-4f96-a819-a5e4453a0733');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d24d3b56-d8c0-44f9-acb0-c6f374fd687d', '50 km/h', false, '8ad01a46-07c7-4f96-a819-a5e4453a0733');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e73e782-9625-40a0-8a8c-7a516aec218a', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'A train is traveling at a speed of 90 km/h. How much distance in kilometres will it cover in 20 minutes?', '20 min = 1/3 h. Distance = 90 km/h × 1/3 h = 30 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f142d449-8041-4771-a002-7f9064f2e7b0', '30 km (Time = 20/60 h = 1/3 h ; Distance = 90 × (1/3) = 30 km)', true, '1e73e782-9625-40a0-8a8c-7a516aec218a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48c3f682-59eb-4f9d-9c6d-e4c7f28a65f2', '45 km', false, '1e73e782-9625-40a0-8a8c-7a516aec218a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d62b6b91-8244-4b35-8dde-e95deb0d4cfd', '25 km', false, '1e73e782-9625-40a0-8a8c-7a516aec218a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e389081e-43f9-4bbc-b386-dbf7885a7570', '60 km', false, '1e73e782-9625-40a0-8a8c-7a516aec218a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d051ae7-3058-4b57-a929-7a29c071b0c7', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'The odometer of a car reads 57321.0 km at 08:30 AM. At 08:50 AM, the odometer reading increases to 57336.0 km. Calculate the speed of the car in km/min and km/h:', 'Δd = 15 km, Δt = 20 min (1/3 h). Speed = 15/20 = 0.75 km/min = 45 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c60c7910-e441-4a00-9cce-9ff552e79b47', '0.75 km/min and 45 km/h (Distance = 15 km ; Time = 20 min = 1/3 h ; Speed = 15 / 20 = 0.75 km/min ; Speed = 15 / (1/3) = 45 km/h)', true, '5d051ae7-3058-4b57-a929-7a29c071b0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b7e3d19-4acc-481b-8d82-4f1d80077d97', '0.5 km/min and 30 km/h', false, '5d051ae7-3058-4b57-a929-7a29c071b0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54750607-93c0-4b47-9f34-5907a86fc9e6', '1.0 km/min and 60 km/h', false, '5d051ae7-3058-4b57-a929-7a29c071b0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3efc0c29-ecbe-4c1f-9233-3ac8130067a5', '0.8 km/min and 48 km/h', false, '5d051ae7-3058-4b57-a929-7a29c071b0c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f54d6b7f-93a1-4430-9311-33d2e42f0fab', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Salma takes 15 minutes from her house to reach her school on a bicycle. If the bicycle has a speed of 2 m/s, calculate the distance between her house and school in metres and kilometres:', 'Time = 15 × 60 = 900 s. Distance = 2 m/s × 900 s = 1800 m = 1.8 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40e699af-08e1-4ea5-94d1-50893c28f8a0', '1,800 m or 1.8 km (Time = 15 × 60 = 900 s ; Distance = 2 m/s × 900 s = 1,800 m = 1.8 km)', true, 'f54d6b7f-93a1-4430-9311-33d2e42f0fab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e28051e-6a65-45ef-a885-9e44b6fefe16', '1,200 m or 1.2 km', false, 'f54d6b7f-93a1-4430-9311-33d2e42f0fab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a01b9614-4596-470b-bcd5-d6ebd64da7bb', '2,400 m or 2.4 km', false, 'f54d6b7f-93a1-4430-9311-33d2e42f0fab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('787f9d7d-f6ef-4ce6-8f7f-f6d196cd2bac', '1,500 m or 1.5 km', false, 'f54d6b7f-93a1-4430-9311-33d2e42f0fab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27896098-625f-4626-9225-433b3266e60b', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'How do modern electronic Quartz Clocks and wristwatches measure time with extreme precision?', 'Piezoelectric quartz crystals oscillate at precisely 32,768 Hz when energized, providing accurate electronic frequency division.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b30431ab-420e-4f3f-b40a-c92b14da289e', 'They contain a micro-electric circuit driven by the extremely steady, high-frequency piezoelectric vibrations of a tiny Quartz Crystal (32,768 Hz)', true, '27896098-625f-4626-9225-433b3266e60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d461d43-c9ca-4f4c-aa2a-755c8ce2236d', 'They have tiny gears moved by running water', false, '27896098-625f-4626-9225-433b3266e60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40cacaef-7fab-4b55-b256-ccf8bb08d760', 'They contain tiny burning candles', false, '27896098-625f-4626-9225-433b3266e60b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6076f39d-ff04-4e0f-9407-24736372aae7', 'They track shadows inside the watch', false, '27896098-625f-4626-9225-433b3266e60b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79a69547-f6cb-4ed5-99b4-cd87a60546e1', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'What physical property determines the Time Period of a simple pendulum?', 'Period T depends only on pendulum length L and gravitational acceleration g (T = 2π√(L/g)).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c234fb-8cf3-4df0-8ff4-6b5ab779a702', 'The LENGTH of the pendulum string (T = 2π√(L/g)) ; it is independent of the mass of the bob or small amplitude swings', true, '79a69547-f6cb-4ed5-99b4-cd87a60546e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('516324ce-d2e6-4903-8aa8-a7d84a269ad1', 'The color of the bob', false, '79a69547-f6cb-4ed5-99b4-cd87a60546e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca7ef7c-38a0-446d-a83f-78b2c8a5d526', 'The heaviness of the bob only', false, '79a69547-f6cb-4ed5-99b4-cd87a60546e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a91c29c-c742-4122-8b8c-8ea477534450', 'The room temperature', false, '79a69547-f6cb-4ed5-99b4-cd87a60546e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('834c47e8-cd1e-4726-8155-23fd996ea4e3', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'What does a CURVED line with increasing steepness on a Distance-Time Graph indicate?', 'A convex ascending curve shows that distance increases at an accelerating rate per unit time, indicating acceleration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fdf4b2a-1c1a-4234-afea-65f1dcb1b880', 'Non-uniform motion with accelerating (increasing) speed', true, '834c47e8-cd1e-4726-8155-23fd996ea4e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3004634-7c18-4638-bc31-694054de8214', 'Uniform constant speed', false, '834c47e8-cd1e-4726-8155-23fd996ea4e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a08ee28-b478-4d13-919a-117b4c49ef19', 'The object is at rest', false, '834c47e8-cd1e-4726-8155-23fd996ea4e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab932913-606f-40cf-a2e7-dd0580194d9f', 'The object is going backwards in time', false, '834c47e8-cd1e-4726-8155-23fd996ea4e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9aea070-6816-467f-a206-8fedde038f7c', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Which of the following natural events was used by ancient humans to measure a ''MONTH''?', 'Synodic lunar month: the 29.53-day cycle between successive new moons formed the basis of calendar months.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6b1972-f634-4ad0-a68d-b3b5444cef73', 'The time between one New Moon and the NEXT New Moon (Lunar Cycle ~ 29.5 days)', true, 'd9aea070-6816-467f-a206-8fedde038f7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93df55b2-f7c6-4eaf-aef7-32bbaa1995c5', 'The time between one sunrise and the next', false, 'd9aea070-6816-467f-a206-8fedde038f7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c18de420-caf6-4cef-8ff5-2e948a195df2', 'The time taken for a tree to grow fruit', false, 'd9aea070-6816-467f-a206-8fedde038f7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a774c4ce-5290-441c-bfcb-e8dca579c7c6', 'The time taken for a river to dry', false, 'd9aea070-6816-467f-a206-8fedde038f7c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('064e4c6f-1f60-40c6-854b-0288b587720a', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Which of the following natural events was used by ancient humans to measure a ''YEAR''?', 'The solar year is defined by Earth''s heliocentric orbital revolution (~365.25 days) governing the annual return of seasons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('280a046d-8924-457e-a73f-9a9a27c73a78', 'The time taken by the Earth to complete one full revolution around the Sun (approx. 365 1/4 days, marked by seasonal cycles)', true, '064e4c6f-1f60-40c6-854b-0288b587720a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bd0eb2a-415f-40e5-8516-c24df2ee2fe8', 'The time between morning and evening', false, '064e4c6f-1f60-40c6-854b-0288b587720a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bb72760-1a87-40be-b1ca-6b5a7d1f2967', 'The duration of a single rainfall', false, '064e4c6f-1f60-40c6-854b-0288b587720a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6f785dc-54b9-413e-88dd-0a31ea7d299a', 'The life of a flower', false, '064e4c6f-1f60-40c6-854b-0288b587720a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c056b7c-b8d3-4118-beea-84bb02e6967e', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'A rocket travels at a speed of 8 km/s. How much time will it take to reach a satellite stationed 36,000 km away in orbit?', 'Time = 36,000 km / 8 km/s = 4500 seconds (75 minutes / 1.25 hours).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22ba1235-6a2d-4b0e-a370-7a47d3c1eef8', '4,500 seconds or 1.25 hours (Time = 36,000 / 8 = 4,500 s = 75 min = 1.25 h)', true, '8c056b7c-b8d3-4118-beea-84bb02e6967e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f4029aa-07ff-4fc2-9f55-2cc7350225e6', '3,600 seconds', false, '8c056b7c-b8d3-4118-beea-84bb02e6967e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86da56f3-837f-47bf-8fac-617ba52738a3', '4,000 seconds', false, '8c056b7c-b8d3-4118-beea-84bb02e6967e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b9ebdfe-08cc-4e81-ba7e-a83d2b9ff374', '5,000 seconds', false, '8c056b7c-b8d3-4118-beea-84bb02e6967e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20742158-d4ec-497a-9116-b0a3e938c598', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'If two cars A and B are moving in the same direction, and on a Distance-Time graph the line for Car A is STEEPER than the line for Car B, what does this conclude?', 'Slope of distance-time graph = Δd/Δt = Speed. Greater slope signifies higher velocity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('580d1e99-948f-4f2d-a4f3-c03c6c838e7d', 'Car A is moving FASTER than Car B (Steeper slope = Higher speed)', true, '20742158-d4ec-497a-9116-b0a3e938c598');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c16fcfd-bc4c-428b-bf27-3b015280533d', 'Car B is faster than Car A', false, '20742158-d4ec-497a-9116-b0a3e938c598');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a7e1e69-992e-4fd2-8f91-20672a5ef566', 'Both cars have equal speed', false, '20742158-d4ec-497a-9116-b0a3e938c598');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff4d5fcc-5e73-42a6-968f-d010cbe47789', 'Car A has stopped moving', false, '20742158-d4ec-497a-9116-b0a3e938c598');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5d5348c-1e4f-4615-ac3e-7bcac97aaad9', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'What is the speed of a cheetah that runs a distance of 100 metres in exactly 4 seconds?', 'Speed = 100 m / 4 s = 25 m/s = 25 × 3.6 = 90 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07f32062-39de-4c73-a57b-fc2d21b14808', '25 m/s or 90 km/h (Speed = 100 / 4 = 25 m/s ; 25 × (18/5) = 90 km/h)', true, 'c5d5348c-1e4f-4615-ac3e-7bcac97aaad9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76aff429-d011-42b0-b831-7846d8ee8e5e', '20 m/s or 72 km/h', false, 'c5d5348c-1e4f-4615-ac3e-7bcac97aaad9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d59d27a4-e7f3-4c51-8139-ae76ac4d5a77', '30 m/s or 108 km/h', false, 'c5d5348c-1e4f-4615-ac3e-7bcac97aaad9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('552d8e7f-ba44-49f8-8177-fb22bda0ae29', '15 m/s or 54 km/h', false, 'c5d5348c-1e4f-4615-ac3e-7bcac97aaad9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e554079-b637-4a51-a28d-8a3150e8bb6a', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'What is the speed of sound in dry air at room temperature (approx. 20°C)?', 'The acoustic velocity of sound in dry air at 20°C is approximately 343 m/s (1,235 km/h).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8d73de5-ed44-47b3-bd9a-94f81c0aab28', 'Approx. 343 m/s (approx. 1,235 km/h)', true, '1e554079-b637-4a51-a28d-8a3150e8bb6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('927c5db9-721d-46a4-8070-269a95274009', '3,000 m/s', false, '1e554079-b637-4a51-a28d-8a3150e8bb6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f9984c1-c76b-4cbc-b828-bfb0c424e86c', '30 m/s', false, '1e554079-b637-4a51-a28d-8a3150e8bb6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4ee6f62-076a-4719-bf70-b183c3d2c538', '300,000 km/s', false, '1e554079-b637-4a51-a28d-8a3150e8bb6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a98cd7e-fa02-49bb-940b-da52ab4193d0', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e54432d-0305-49e0-986e-5ebcc30fad6a', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '0a98cd7e-fa02-49bb-940b-da52ab4193d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('867382de-2c81-4f54-9090-5d4ab118da6a', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '0a98cd7e-fa02-49bb-940b-da52ab4193d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f844dd1b-6a69-4515-9cca-01aa8ffc7020', '(A) is true, but (R) is false.', false, '0a98cd7e-fa02-49bb-940b-da52ab4193d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6558c76-5418-410d-ad8f-8c6f1cd848a0', '(A) is false, but (R) is true.', false, '0a98cd7e-fa02-49bb-940b-da52ab4193d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09d09056-f203-4351-a272-9aaae43f9203', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Spot the IMPOSTER in the following group of Time-Measuring Devices and their operating principles:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd2864aa-6633-46bd-9e92-05c24d134ea3', 'Device 1', false, '09d09056-f203-4351-a272-9aaae43f9203');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c7b6c5b-48db-4cf4-8857-6bc442e171ae', 'Device 2', false, '09d09056-f203-4351-a272-9aaae43f9203');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07fe7d8e-d586-4d36-bac3-06b2b20429b0', 'Device 3', false, '09d09056-f203-4351-a272-9aaae43f9203');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b45d674a-aff3-46cf-9142-f59c13984ba1', 'Device 4 (A simple pendulum uses MECHANICAL GRAVITATIONAL HARMONIC OSCILLATION, not burning gunpowder)', true, '09d09056-f203-4351-a272-9aaae43f9203');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb4f8c99-ee70-4b07-b105-be98643f5582', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'If a simple pendulum of length L has a time period of 2.0 seconds, what will happen to its time period if its length is increased by FOUR TIMES (4L)?', 'Formula T = 2π√(L/g). If length becomes 4L, new period T'' = √(4) × T = 2 × 2.0 = 4.0 s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5daa8b57-cdaa-418a-8379-ce4bf6765647', 'The time period will DOUBLE to 4.0 seconds (Since T ∝ √L, T'' = √(4) × T = 2 × 2.0 = 4.0 s)', true, 'bb4f8c99-ee70-4b07-b105-be98643f5582');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acff4445-bfcd-4ac9-893b-520bdfc06972', 'The time period will quadruple to 8.0 s', false, 'bb4f8c99-ee70-4b07-b105-be98643f5582');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe9dc792-cad2-4475-a37b-508e99b103da', 'The time period will reduce to 1.0 s', false, 'bb4f8c99-ee70-4b07-b105-be98643f5582');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e4b4313-8398-4e2f-8cc5-89e1588a36cc', 'The time period remains unchanged at 2.0 s', false, 'bb4f8c99-ee70-4b07-b105-be98643f5582');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19ef77e1-516a-4f17-9be8-b10d06cc88dc', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Match Column I (Speed & Time Concepts) with Column II (Exact Definitions & Formulas):
(a) Speedometer          -> (i) Instantaneous vehicular speed in km/h
(b) Odometer             -> (ii) Cumulative distance traversed in km
(c) Slope of D-T Graph   -> (iii) Rate of change of distance yielding speed
(d) Atomic Clock (Cesium)-> (iv) Ultra-precise atomic microwave resonance (loss < 1 sec in millions of years)', 'Speedometer = instantaneous speed; Odometer = distance; Slope = speed; Cesium clock = atomic frequency standard.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69cba93e-6cc2-4792-9703-d9593bec9237', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '19ef77e1-516a-4f17-9be8-b10d06cc88dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98756ce0-8d7b-44e7-84d0-d9f859823846', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '19ef77e1-516a-4f17-9be8-b10d06cc88dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffd557c4-837d-419e-922e-8e1ed8b3f01e', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '19ef77e1-516a-4f17-9be8-b10d06cc88dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac93c174-763f-4d34-9ee2-3a66db1f0ac2', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '19ef77e1-516a-4f17-9be8-b10d06cc88dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11c414fc-a65b-4a54-8413-a45cb5a3df60', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Read the statements regarding kinematics:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59302bf9-c6dd-4f78-9d91-1428a5442542', 'Statements 1 and 2 only', true, '11c414fc-a65b-4a54-8413-a45cb5a3df60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cf6e6f0-ab8f-42be-9d13-6a1e40b045e7', 'Statements 2 and 3 only', false, '11c414fc-a65b-4a54-8413-a45cb5a3df60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09fddddf-f733-4e51-ac41-5bca6ec75e12', 'Statements 1 and 3 only', false, '11c414fc-a65b-4a54-8413-a45cb5a3df60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c521e7b3-73df-433c-b155-b7664d0d6524', 'All Statements 1, 2, and 3', false, '11c414fc-a65b-4a54-8413-a45cb5a3df60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97a898bf-5c34-4de5-97ec-b4e4db0c17eb', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'A bus travels the first 30 km of its trip at a uniform speed of 30 km/h, and the next 30 km at a uniform speed of 60 km/h. What is the AVERAGE SPEED of the bus for the entire 60 km journey?', 'Harmonic average speed: Total distance (60 km) / Total time (1.5 h) = 40 km/h (NEVER arithmetic average (30+60)/2=45).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aebcb77-9294-4a66-a506-f8faea588794', '40 km/h (Total Distance = 60 km ; Time 1 = 30/30 = 1 h ; Time 2 = 30/60 = 0.5 h ; Total Time = 1.5 h ; Avg Speed = 60 / 1.5 = 40 km/h)', true, '97a898bf-5c34-4de5-97ec-b4e4db0c17eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('448d7c2f-cc6b-4e54-8b96-4cb84e08b3e1', '45 km/h (Arithmetic mean error)', false, '97a898bf-5c34-4de5-97ec-b4e4db0c17eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2220f9c3-cf97-4475-b550-3b2fbd7fa5ab', '50 km/h', false, '97a898bf-5c34-4de5-97ec-b4e4db0c17eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c68745a-bbf7-4dc9-9c97-6dbe1cb8034b', '35 km/h', false, '97a898bf-5c34-4de5-97ec-b4e4db0c17eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47782930-006c-4cf0-bd7c-5b8cf65917f8', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Why do international scientific metrology standards define 1 Second using the Cesium-133 Atomic Clock rather than astronomical earth rotation?', 'SI second is defined by 9,192,631,770 hyperfine transitions of Cs-133 ground state, eliminating planetary rotational perturbations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aae17c25-addc-4853-bc7d-62993765711d', 'Earth''s orbital rotation experiences slight irregularities due to tidal friction and mass redistribution, whereas the Cesium-133 atomic hyperfine transition frequency (9,192,631,770 Hz) is invariant and absolute', true, '47782930-006c-4cf0-bd7c-5b8cf65917f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b44ac9a3-bad9-4dd0-a5c3-46433efda028', 'Because watches run out of batteries', false, '47782930-006c-4cf0-bd7c-5b8cf65917f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7ad20e3-ce5a-4c17-bcf2-4456d327f90f', 'Because the Sun is cooling down', false, '47782930-006c-4cf0-bd7c-5b8cf65917f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('889dc9da-3b4b-4c9e-afd1-04c4ee1f8923', 'Because the moon is drifting away', false, '47782930-006c-4cf0-bd7c-5b8cf65917f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2153dd5c-23c4-4e66-99a2-4f06530d6ff4', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Consider four kinematic events:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d0334e8-4ca7-4f32-9bd6-cffaf1fcbf78', 'Events 2 and 4 only', true, '2153dd5c-23c4-4e66-99a2-4f06530d6ff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57d45a67-985b-4e98-a14d-2ad70d636e3a', 'Events 1 and 3 only', false, '2153dd5c-23c4-4e66-99a2-4f06530d6ff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55a3eeee-2927-4bb1-9755-2abd2b3045cf', 'Events 1, 2, and 4 only', false, '2153dd5c-23c4-4e66-99a2-4f06530d6ff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2a2d2a7-b887-424e-b98f-cdd9aab23bc1', 'All 1, 2, 3, and 4', false, '2153dd5c-23c4-4e66-99a2-4f06530d6ff4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b6d9448-d1f7-41fb-bc9f-c8f55beb1e69', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'What mathematical property explains why a Simple Pendulum''s time period remains CONSTANT even if its bob''s mass is increased from 50 g to 500 g?', 'Equivalence principle: gravitational mass equals inertial mass, so acceleration and period are strictly mass-independent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd316466-1e5c-4f18-bce8-749b9cea6960', 'In the pendulum equation T = 2π√(L/g), mass ''m'' does not appear; inertial resistance cancels gravitational restoring force identically for all masses', true, '9b6d9448-d1f7-41fb-bc9f-c8f55beb1e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ef6e826-8147-4ea2-a288-47e57f33a979', 'Because larger mass makes the pendulum longer', false, '9b6d9448-d1f7-41fb-bc9f-c8f55beb1e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5324523b-ac1c-41b8-b2ae-3bd336e19861', 'Because heavier bob pushes air away', false, '9b6d9448-d1f7-41fb-bc9f-c8f55beb1e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25ba7702-97bc-4aa7-84c7-f75ab8fdb3a6', 'Because gravity acts only on light objects', false, '9b6d9448-d1f7-41fb-bc9f-c8f55beb1e69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da9bc3fe-1112-4b51-a897-bf30277e4561', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'If the Distance-Time graph of a moving vehicle is a straight line sloping DOWNWARDS from left to right, what does it signify?', 'Negative displacement slope indicates uniform return motion reducing distance relative to the frame of reference.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08bc4bc4-f895-4593-88a3-59b69014e01a', 'The vehicle is returning back towards the starting reference origin point at a uniform speed', true, 'da9bc3fe-1112-4b51-a897-bf30277e4561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53f43b82-af45-482b-9f74-8bd09e196149', 'The vehicle has negative mass', false, 'da9bc3fe-1112-4b51-a897-bf30277e4561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59e0f51b-3db8-4d17-ad88-f59c78a74401', 'Time is moving backwards', false, 'da9bc3fe-1112-4b51-a897-bf30277e4561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91c92d0c-d438-4891-a5c1-a69b351e3691', 'The car is falling off a cliff', false, 'da9bc3fe-1112-4b51-a897-bf30277e4561');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90f5102e-7b83-4247-8598-495049a8d251', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'How does GPS (Global Positioning System) navigation calculate a car''s real-time position and speed?', 'GPS trilateration measures nanosecond radio signal transit delays (d = c·Δt) from ≥4 atomic satellite clocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ac9720e-5656-44bf-8eb3-ce3df4b10269', 'By calculating precise time-of-flight radio signal delays from atomic clocks aboard multiple orbiting GPS satellites to triangulate position and velocity', true, '90f5102e-7b83-4247-8598-495049a8d251');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5040152-1568-42a7-9da6-0db40620dd1e', 'By taking photos of road signs', false, '90f5102e-7b83-4247-8598-495049a8d251');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed659d09-7496-4455-b62e-9fd474fa3fdc', 'By measuring air pressure around wheels', false, '90f5102e-7b83-4247-8598-495049a8d251');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29c02079-6dd4-4327-ab75-c89eb50dd690', 'By counting wheel revolutions only', false, '90f5102e-7b83-4247-8598-495049a8d251');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f563aefe-47ee-42f5-9096-fcdb8c1eb17d', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'What master scientific principle is established in Chapter 9 of NCERT Class 7 Science?', 'Chapter 9 establishes fundamental kinematics: scalar rates, periodic isochronism, metrology history, and Cartesian graphical analysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f5be2cc-0844-4acc-ad5d-dd7cb301c6e6', 'Quantitative measurement of physical motion and temporal duration—from ancient shadow gnomons and pendulums to modern quartz oscillators and graphical kinematics—forms the bedrock of physics, astronomy, technology, and navigation', true, 'f563aefe-47ee-42f5-9096-fcdb8c1eb17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e9d8f0d-19a9-4dc1-9e27-11492cac2121', 'That time cannot be measured accurately', false, 'f563aefe-47ee-42f5-9096-fcdb8c1eb17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa908df3-f084-428c-9db1-da799c13de7e', 'That speed is always random', false, 'f563aefe-47ee-42f5-9096-fcdb8c1eb17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c7f14d4-3fb6-472e-85e3-b4740de68b79', 'That clocks only work when someone watches them', false, 'f563aefe-47ee-42f5-9096-fcdb8c1eb17d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b442d26-22d6-464f-97de-16a1d1eb798f', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for finding the PERIMETER of a Rectangle of length l and breadth b?', 'Rectangle perimeter P = 2(length + breadth).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49e41a97-f7f6-4eeb-9a0e-486ccc3dd918', 'Perimeter = 2 × (l + b)', true, '7b442d26-22d6-464f-97de-16a1d1eb798f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a13c9c6-cf94-42d8-9a3e-ee0d1b2972df', 'Perimeter = l × b', false, '7b442d26-22d6-464f-97de-16a1d1eb798f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('701fb6b3-4d27-41f1-bd80-943453756e72', 'Perimeter = 4 × l', false, '7b442d26-22d6-464f-97de-16a1d1eb798f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6db21207-fe83-4753-a071-9b6c4801c731', 'Perimeter = l + b', false, '7b442d26-22d6-464f-97de-16a1d1eb798f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64f991da-e697-44e4-ae9f-2cc2708ef212', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the AREA of a Square of side ''a''?', 'Area of a square = side × side = a².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83f047a8-f182-49db-af2c-d307f8abcd86', 'Area = a² (Side × Side)', true, '64f991da-e697-44e4-ae9f-2cc2708ef212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa5734a3-170a-414f-96ba-0cc5ea297c9f', 'Area = 4 × a', false, '64f991da-e697-44e4-ae9f-2cc2708ef212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('592035fb-3232-4cd9-af95-45e261ba8f52', 'Area = 2 × a', false, '64f991da-e697-44e4-ae9f-2cc2708ef212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c4dd10d-f938-450e-a545-5ab019171317', 'Area = a / 4', false, '64f991da-e697-44e4-ae9f-2cc2708ef212');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae8a5485-5d2d-4f08-bc8d-a619d4412c34', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the AREA of a PARALLELOGRAM with base ''b'' and corresponding height ''h''?', 'Area of a parallelogram = base × corresponding height (b × h).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbdaac4-788a-4bbf-b2b4-5baf59096ade', 'Area = Base × Height (b × h)', true, 'ae8a5485-5d2d-4f08-bc8d-a619d4412c34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('501c6b14-b8a8-4e6c-89a9-ab75fd92e6be', 'Area = 1/2 × b × h', false, 'ae8a5485-5d2d-4f08-bc8d-a619d4412c34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e64de8d0-6919-4bf6-9679-531c05b17b18', 'Area = 2 × (b + h)', false, 'ae8a5485-5d2d-4f08-bc8d-a619d4412c34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d3822c-20ea-4688-ba42-51c16ba81321', 'Area = b² × h', false, 'ae8a5485-5d2d-4f08-bc8d-a619d4412c34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b10fff9b-97cf-49a3-b5c3-3923e073da6a', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the AREA of a TRIANGLE with base ''b'' and height ''h''?', 'A triangle is half of a parallelogram, so Area = 1/2 × base × height.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a76e3aae-3cce-447a-92d5-11ac7abac60c', 'Area = 1/2 × Base × Height (1/2 × b × h)', true, 'b10fff9b-97cf-49a3-b5c3-3923e073da6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e7c92e0-5643-4d79-8a05-26cc9fcc01db', 'Area = b × h', false, 'b10fff9b-97cf-49a3-b5c3-3923e073da6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b977aea-a39d-4570-9794-00272f5ebf46', 'Area = 2 × b × h', false, 'b10fff9b-97cf-49a3-b5c3-3923e073da6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e69da575-9c42-4449-8be5-7ff5afcfe688', 'Area = (b + h) / 2', false, 'b10fff9b-97cf-49a3-b5c3-3923e073da6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e42281cd-19f3-4542-927c-cb0ccb4e72b3', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the CIRCUMFERENCE (perimeter) of a circle of radius ''r'' (or diameter ''d'')?', 'Circumference of a circle C = 2πr = πd.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6df312f6-0efb-47a5-a80f-a61396a19dfa', 'Circumference = 2πr (or πd)', true, 'e42281cd-19f3-4542-927c-cb0ccb4e72b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61644863-06f8-48e2-bf40-08dd71805b14', 'Circumference = πr²', false, 'e42281cd-19f3-4542-927c-cb0ccb4e72b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac1c495f-8d27-4463-b23d-725e19e26042', 'Circumference = 4πr', false, 'e42281cd-19f3-4542-927c-cb0ccb4e72b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0149ae4-0532-4bea-846c-56c3f49c6d5a', 'Circumference = 2πr²', false, 'e42281cd-19f3-4542-927c-cb0ccb4e72b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('732420b1-50af-4b93-97e3-0eb77dc57f3a', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the AREA of a Circle of radius ''r''?', 'Area enclosed by a circle A = πr².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f4237a1-b45c-4d4d-932e-b9b1c531bab8', 'Area = πr²', true, '732420b1-50af-4b93-97e3-0eb77dc57f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('414fca49-c128-437d-94a4-7c6dea91e750', 'Area = 2πr', false, '732420b1-50af-4b93-97e3-0eb77dc57f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ead3a04-1532-435a-b388-4f1e4b31d801', 'Area = πd', false, '732420b1-50af-4b93-97e3-0eb77dc57f3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51d22ebe-4219-4086-be3b-5bd55833f474', 'Area = 4πr²', false, '732420b1-50af-4b93-97e3-0eb77dc57f3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('488b9148-59e9-4094-b305-1be4fce2e320', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'How many square metres (m²) are there in 1 HECTARE?', '1 hectare = 10,000 m² (a square of 100 m × 100 m).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('180bbdb8-967b-4432-94c1-4a5d612da29c', '10,000 m² (1 Hectare = 100 m × 100 m = 10,000 m²)', true, '488b9148-59e9-4094-b305-1be4fce2e320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d80b2158-7dc4-43ac-8369-56353cbf66d6', '1,000 m²', false, '488b9148-59e9-4094-b305-1be4fce2e320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f53d5a16-aba3-4592-ba85-6fe9e457d1a7', '100 m²', false, '488b9148-59e9-4094-b305-1be4fce2e320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('557d07e8-6819-4f53-b247-acd2920b9565', '100,000 m²', false, '488b9148-59e9-4094-b305-1be4fce2e320');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ade1ac42-8008-4c82-ba1f-992517384433', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Circumference of a circle of radius 14 cm (Take π = 22/7):', 'C = 2 × (22/7) × 14 = 88 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec4730ec-14ca-4e67-ab20-9579d64a99a1', '88 cm (C = 2 × (22/7) × 14 = 2 × 22 × 2 = 88 cm)', true, 'ade1ac42-8008-4c82-ba1f-992517384433');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b36346d4-3cf8-4510-9efb-f95d82cc5336', '44 cm', false, 'ade1ac42-8008-4c82-ba1f-992517384433');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6550449f-797d-4d9f-ac69-b76e8612d88f', '176 cm', false, 'ade1ac42-8008-4c82-ba1f-992517384433');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69b99049-d039-4331-b345-f04eb821d9bb', '616 cm', false, 'ade1ac42-8008-4c82-ba1f-992517384433');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59e9d43c-40f8-4063-b1b8-4ce9f13c89c3', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Area of a circle of radius 7 cm (Take π = 22/7):', 'Area = (22/7) × 7² = 154 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f000614b-d3a5-41de-9f8b-e70257c01216', '154 cm² (Area = (22/7) × 7 × 7 = 154 cm²)', true, '59e9d43c-40f8-4063-b1b8-4ce9f13c89c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d28cef1-7f17-47fe-bcae-e44ce75344d6', '44 cm²', false, '59e9d43c-40f8-4063-b1b8-4ce9f13c89c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2954770-3f60-4cdd-85b1-4f6389772e96', '308 cm²', false, '59e9d43c-40f8-4063-b1b8-4ce9f13c89c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcd78ff2-116f-4d4a-b03f-2cbe4936d7b2', '77 cm²', false, '59e9d43c-40f8-4063-b1b8-4ce9f13c89c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47cc00b8-1749-4397-a384-c0a431e502d7', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Area of a square park whose perimeter is 320 m:', 'Side = 320 / 4 = 80 m. Area = 80² = 6,400 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a18ce715-2055-4db8-9e18-692511c3c598', '6,400 m² (Side = 320 / 4 = 80 m ; Area = 80 × 80 = 6,400 m²)', true, '47cc00b8-1749-4397-a384-c0a431e502d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edb29ee7-3742-49f0-a094-2bef766e05a9', '3,200 m²', false, '47cc00b8-1749-4397-a384-c0a431e502d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3ee2586-b3a4-42b8-b8fd-32328dc83347', '1,600 m²', false, '47cc00b8-1749-4397-a384-c0a431e502d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6db8bae0-24e5-4f05-8de4-7afb4d9968fa', '8,000 m²', false, '47cc00b8-1749-4397-a384-c0a431e502d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f92dec49-ffac-4cec-8c7f-e153c4730696', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Area of a triangle with base = 15 cm and corresponding height = 6 cm:', 'Area = 1/2 × 15 × 6 = 45 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fa555ed-0911-4c0e-b939-b745987d8f0e', '45 cm² (Area = 1/2 × 15 × 6 = 15 × 3 = 45 cm²)', true, 'f92dec49-ffac-4cec-8c7f-e153c4730696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d8883ab-e859-4373-b3ba-0ee49adad35e', '90 cm²', false, 'f92dec49-ffac-4cec-8c7f-e153c4730696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ade6064-daa4-4339-a9d4-4461134342ae', '30 cm²', false, 'f92dec49-ffac-4cec-8c7f-e153c4730696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d7779ea-930c-4bff-bcb0-9fe7b32d0f06', '60 cm²', false, 'f92dec49-ffac-4cec-8c7f-e153c4730696');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('846dd511-12e6-4ae7-a87d-b630a7b6c0de', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Area of a parallelogram with base = 8 cm and height = 4.5 cm:', 'Area = 8 × 4.5 = 36 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ff0d161-370e-4c7e-adce-ad574e7689fe', '36 cm² (Area = 8 × 4.5 = 36 cm²)', true, '846dd511-12e6-4ae7-a87d-b630a7b6c0de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('701ddfbe-b78a-40ef-b5d8-c1bac68477cb', '18 cm²', false, '846dd511-12e6-4ae7-a87d-b630a7b6c0de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('686f367a-0252-4e8e-9368-0fde95b768bc', '72 cm²', false, '846dd511-12e6-4ae7-a87d-b630a7b6c0de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0cf1ae4-1a38-436d-afdc-9538287ea8c7', '25 cm²', false, '846dd511-12e6-4ae7-a87d-b630a7b6c0de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba29fada-4f00-442a-a1fd-55ad8a8f7fa4', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A door of length 2 m and breadth 1 m is fitted in a wall. The length of the wall is 4.5 m and the breadth is 3.6 m. Find the cost of white washing the wall at the rate of Rs 20 per m²:', 'Area to whitewash = 16.2 - 2.0 = 14.2 m². Cost = 14.2 × 20 = Rs 284.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f91066e7-f0ca-4b43-838f-bec813f4ab08', 'Rs 284 (Wall Area = 4.5 × 3.6 = 16.2 m² ; Door Area = 2 × 1 = 2 m² ; Area to whitewash = 16.2 - 2 = 14.2 m² ; Cost = 14.2 × 20 = Rs 284)', true, 'ba29fada-4f00-442a-a1fd-55ad8a8f7fa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b8d11ff-ee75-4f00-bac2-752b9d1faf9c', 'Rs 324', false, 'ba29fada-4f00-442a-a1fd-55ad8a8f7fa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('659f1dc9-1c27-4e0f-b533-e35a0f8101fc', 'Rs 260', false, 'ba29fada-4f00-442a-a1fd-55ad8a8f7fa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c978e0a6-651d-4628-b867-9692e6cb5d9d', 'Rs 300', false, 'ba29fada-4f00-442a-a1fd-55ad8a8f7fa4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fda26967-e7b5-4d1f-9e84-48362d1d350f', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'The area of a square and a rectangle are equal. If the side of the square is 40 cm and the breadth of the rectangle is 25 cm, find the length of the rectangle and its perimeter:', 'Area = 1600. Length = 1600 / 25 = 64 cm. Perimeter = 2(64 + 25) = 178 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a38fa39-3504-491b-822b-2eb7e1868e7e', 'Length = 64 cm ; Perimeter = 178 cm (Area = 40² = 1600 cm² ; Length = 1600 / 25 = 64 cm ; Perimeter = 2(64 + 25) = 2 × 89 = 178 cm)', true, 'fda26967-e7b5-4d1f-9e84-48362d1d350f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58c763eb-93e4-4820-b361-d62bf15e4455', 'Length = 50 cm ; Perimeter = 150 cm', false, 'fda26967-e7b5-4d1f-9e84-48362d1d350f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3845bf4a-1207-4ef4-b457-7849ec34a4fd', 'Length = 60 cm ; Perimeter = 170 cm', false, 'fda26967-e7b5-4d1f-9e84-48362d1d350f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42587230-497d-4cba-b098-985dbb1ac71c', 'Length = 64 cm ; Perimeter = 160 cm', false, 'fda26967-e7b5-4d1f-9e84-48362d1d350f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15437247-9db5-47e6-92a2-5a8cc9a8ec6d', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A wire is in the shape of a rectangle of length 40 cm and breadth 22 cm. If the SAME wire is rebent in the shape of a square, what will be the measure of each side of the square and which shape encloses more area?', 'Wire length = 124 cm. Square side = 31 cm. Area of square (961 cm²) > Area of rectangle (880 cm²).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93150e3e-e8eb-48b9-839d-5f9d223ffe75', 'Side of square = 31 cm ; The SQUARE encloses more area (Perimeter = 2(40+22) = 124 cm ; Side = 124/4 = 31 cm ; Square Area = 31² = 961 cm² > Rect Area = 40×22 = 880 cm²)', true, '15437247-9db5-47e6-92a2-5a8cc9a8ec6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bf967d6-0438-427e-8df8-b3ed9982e267', 'Side = 30 cm ; Rectangle encloses more', false, '15437247-9db5-47e6-92a2-5a8cc9a8ec6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff79011f-d5f1-41f3-8aa7-879c21362b0b', 'Side = 31 cm ; Both have equal area', false, '15437247-9db5-47e6-92a2-5a8cc9a8ec6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d63ab1c-32d6-4e51-9bb7-79b3a2e9531a', 'Side = 32 cm ; Square encloses more', false, '15437247-9db5-47e6-92a2-5a8cc9a8ec6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c29bdbbd-7c6a-43a1-b1d8-145a78529c29', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A garden is 90 m long and 75 m broad. A path 5 m wide is to be built outside and around it. Find the AREA OF THE PATH in m² and in hectares:', 'Outer rectangle = 100 × 85 = 8500 m². Inner = 90 × 75 = 6750 m². Path = 8500 - 6750 = 1750 m² = 0.175 hectare.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86f56a57-88dd-4af9-9764-868778900a0d', '1,750 m² (0.175 hectares) (Outer dim = 100 m × 85 m ; Outer Area = 8,500 m² ; Inner Area = 90 × 75 = 6,750 m² ; Path Area = 8,500 - 6,750 = 1,750 m² = 0.175 ha)', true, 'c29bdbbd-7c6a-43a1-b1d8-145a78529c29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96750d2c-061f-4fdb-be6f-06d952a96321', '1,500 m² (0.15 ha)', false, 'c29bdbbd-7c6a-43a1-b1d8-145a78529c29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb44a1e-1f1a-49da-a250-6e76f7200f2b', '2,000 m² (0.2 ha)', false, 'c29bdbbd-7c6a-43a1-b1d8-145a78529c29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb3f3280-6c78-4029-a184-4d4a5929f096', '1,650 m² (0.165 ha)', false, 'c29bdbbd-7c6a-43a1-b1d8-145a78529c29');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55d87937-c5e4-4339-a8d5-71979ebe510b', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A picture is painted on a cardboard 8 cm long and 5 cm wide such that there is a margin of 1.5 cm along each of its sides. Find the total AREA OF THE MARGIN:', 'Outer = 40 cm². Inner = 5 × 2 = 10 cm². Margin = 40 - 10 = 30 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ee8d3af-7d13-489f-baf2-49fc0b2af313', '30 cm² (Outer Area = 8 × 5 = 40 cm² ; Inner dim = (8 - 3) × (5 - 3) = 5 cm × 2 cm ; Inner Area = 10 cm² ; Margin Area = 40 - 10 = 30 cm²)', true, '55d87937-c5e4-4339-a8d5-71979ebe510b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c2ae43c-f255-48d5-be2f-3f0ac0aa421f', '25 cm²', false, '55d87937-c5e4-4339-a8d5-71979ebe510b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f667c433-8aae-4cd5-821d-9e60dabaac48', '35 cm²', false, '55d87937-c5e4-4339-a8d5-71979ebe510b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8298197c-6547-4453-86de-df793675e4c4', '20 cm²', false, '55d87937-c5e4-4339-a8d5-71979ebe510b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8b694f5-11b7-4521-ab6b-eacb99b02db4', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'Two cross roads, each of width 10 m, cut at right angles through the centre of a rectangular park of length 700 m and breadth 300 m and parallel to its sides. Find the total AREA OF THE ROADS:', 'Area of cross roads = 700(10) + 300(10) - 10² = 7000 + 3000 - 100 = 9,900 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1cd2b67-9ef0-4c37-bd8b-53fab86eade4', '9,900 m² (0.99 hectares) (Road 1 = 700 × 10 = 7,000 ; Road 2 = 300 × 10 = 3,000 ; Common intersection = 10 × 10 = 100 ; Total = 7,000 + 3,000 - 100 = 9,900 m²)', true, 'b8b694f5-11b7-4521-ab6b-eacb99b02db4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6787292c-8e6d-4ec4-9a2f-2bd19282b0ae', '10,000 m²', false, 'b8b694f5-11b7-4521-ab6b-eacb99b02db4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e36e89d-4c9d-478b-96db-a655935d6f19', '9,800 m²', false, 'b8b694f5-11b7-4521-ab6b-eacb99b02db4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6874664b-e28f-439a-99d2-74ec9e8c09e6', '9,500 m²', false, 'b8b694f5-11b7-4521-ab6b-eacb99b02db4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74eb5ef3-7047-4a25-bcd0-9f72edfe691b', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'From a circular sheet of radius 4 cm, a concentric circle of radius 3 cm is removed. Find the AREA OF THE REMAINING SHEET (Take π = 3.14):', 'Remaining area = π(4² - 3²) = 3.14 × 7 = 21.98 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8727a92a-9cc5-4217-b7e7-ff64d5d8468a', '21.98 cm² (Area = π × (R² - r²) = 3.14 × (16 - 9) = 3.14 × 7 = 21.98 cm²)', true, '74eb5ef3-7047-4a25-bcd0-9f72edfe691b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c3563df-b680-4af4-8cc5-ffeef6061b98', '22.5 cm²', false, '74eb5ef3-7047-4a25-bcd0-9f72edfe691b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e669636-5c59-40bc-a168-977d534e6136', '20.84 cm²', false, '74eb5ef3-7047-4a25-bcd0-9f72edfe691b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fa93569-e5d2-403f-9c30-b34b19c4fd37', '25.12 cm²', false, '74eb5ef3-7047-4a25-bcd0-9f72edfe691b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4f7f4d0-c4df-48a3-a98d-37297f5f7df9', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A gardener wants to fence a circular garden of diameter 21 m. Find the length of rope he needs to purchase if he makes 2 rounds of fence, and the cost of rope at Rs 4 per metre (Take π = 22/7):', 'C = πd = (22/7) × 21 = 66 m. Two rounds = 132 m. Cost = 132 × 4 = Rs 528.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3df3b12a-0fd3-4e9e-b91f-bf35586282ac', 'Length of rope = 132 m ; Cost = Rs 528 (Circumference = (22/7) × 21 = 66 m ; 2 rounds = 66 × 2 = 132 m ; Cost = 132 × 4 = Rs 528)', true, 'a4f7f4d0-c4df-48a3-a98d-37297f5f7df9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86eb6257-0920-4da8-8787-41ec5295ac2e', 'Length = 66 m ; Cost = Rs 264', false, 'a4f7f4d0-c4df-48a3-a98d-37297f5f7df9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0c4786c-9a11-496e-9385-0121a62c160f', 'Length = 132 m ; Cost = Rs 600', false, 'a4f7f4d0-c4df-48a3-a98d-37297f5f7df9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce89cba0-bd57-464b-aa33-c50f1f6ee059', 'Length = 150 m ; Cost = Rs 528', false, 'a4f7f4d0-c4df-48a3-a98d-37297f5f7df9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ae076fa-eaef-4279-8aa9-8a1a0c3ee0a1', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'The circumference of a circle is 31.4 cm. Find the radius and the area of the circle (Take π = 3.14):', 'r = 31.4 / (2 × 3.14) = 5 cm. Area = 3.14 × 25 = 78.5 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5964b426-713b-4c7e-be22-6833ebec640e', 'Radius = 5 cm ; Area = 78.5 cm² (2 × 3.14 × r = 31.4 ⇒ r = 5 cm ; Area = 3.14 × 5² = 3.14 × 25 = 78.5 cm²)', true, '0ae076fa-eaef-4279-8aa9-8a1a0c3ee0a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52e09391-544d-43f8-8c01-49cab1adab47', 'Radius = 10 cm ; Area = 314 cm²', false, '0ae076fa-eaef-4279-8aa9-8a1a0c3ee0a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23ea4140-18b3-44be-a7a4-8386d1ede547', 'Radius = 5 cm ; Area = 154 cm²', false, '0ae076fa-eaef-4279-8aa9-8a1a0c3ee0a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74ef49b6-c814-48b5-9831-555d0503e78a', 'Radius = 7 cm ; Area = 154 cm²', false, '0ae076fa-eaef-4279-8aa9-8a1a0c3ee0a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e31583e8-0283-4438-b263-81809d27dd9a', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A circular flower bed is surrounded by a path 4 m wide. The diameter of the flower bed is 66 m. What is the AREA OF THIS PATH? (Take π = 3.14)', 'Ring area = π(37² - 33²) = 3.14 × (70 × 4) = 3.14 × 280 = 879.2 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f76db3bc-ab39-4064-82d0-ede6bc68f833', '879.2 m² (Inner radius r = 33 m ; Outer radius R = 33 + 4 = 37 m ; Path Area = π(R² - r²) = 3.14 × (37² - 33²) = 3.14 × (1369 - 1089) = 3.14 × 280 = 879.2 m²)', true, 'e31583e8-0283-4438-b263-81809d27dd9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b816b9ab-60b8-4730-bb31-43b66a2fa22d', '850.5 m²', false, 'e31583e8-0283-4438-b263-81809d27dd9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb6defee-d245-4886-bce1-18213db6ab54', '900.2 m²', false, 'e31583e8-0283-4438-b263-81809d27dd9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6ba486f-935a-4cd0-a7dd-6739b3634748', '864.0 m²', false, 'e31583e8-0283-4438-b263-81809d27dd9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5b32cbd-acba-4688-b785-80739b42e5bf', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A circular flower garden has an area of 314 m². A sprinkler at the centre of the garden can cover an area that has a radius of 12 m. Will the sprinkler water the ENTIRE garden? (Take π = 3.14)', 'Garden radius = √(314/3.14) = 10 m. Sprinkler radius = 12 m > 10 m, so it covers the entire garden.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbc3ee37-ad68-4ed6-bcff-b4d380d61025', 'Yes, because the sprinkler covers an area of 452.16 m² (π × 12² = 3.14 × 144 = 452.16 m²), which is greater than the garden''s area of 314 m²', true, 'c5b32cbd-acba-4688-b785-80739b42e5bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b6ceaf5-7fec-4416-b22c-3128765fad62', 'No, the sprinkler only waters 200 m²', false, 'c5b32cbd-acba-4688-b785-80739b42e5bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3d88099-3144-4989-89da-912969786985', 'No, because the radius is too small', false, 'c5b32cbd-acba-4688-b785-80739b42e5bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f58a7d5-1fb9-405f-b19a-1d1d912c2ccd', 'Cannot be determined', false, 'c5b32cbd-acba-4688-b785-80739b42e5bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7594235-b4ad-4ab5-a06c-4e460bb091ea', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'How many times a wheel of radius 28 cm must rotate to go a distance of 352 m? (Take π = 22/7)', 'C = 2 × (22/7) × 28 = 176 cm = 1.76 m. Rotations = 352 / 1.76 = 200.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d642a5b-1cdb-4811-938a-a5529952524c', '200 rotations (Circumference = 2 × (22/7) × 28 = 176 cm = 1.76 m ; Rotations = 352 / 1.76 = 200)', true, 'a7594235-b4ad-4ab5-a06c-4e460bb091ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb3658b4-6807-457c-85cc-62a8918b10a2', '100 rotations', false, 'a7594235-b4ad-4ab5-a06c-4e460bb091ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8af1a23b-0bdb-45d0-bbb3-f978048cdf9a', '300 rotations', false, 'a7594235-b4ad-4ab5-a06c-4e460bb091ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('487dba9e-fbb0-4cd1-aaaf-1d4f820f96c6', '250 rotations', false, 'a7594235-b4ad-4ab5-a06c-4e460bb091ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c9e2f86-3c1d-484a-996c-f3ceeccf1ce3', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'The minute hand of a circular clock is 15 cm long. How far does the TIP of the minute hand move in 1 hour? (Take π = 3.14)', 'Distance = 2πr = 2 × 3.14 × 15 = 94.2 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('095362f4-acb3-42fa-80f4-1630ac61ee7e', '94.2 cm (In 1 hour, the minute hand completes 1 full rotation = Circumference = 2 × 3.14 × 15 = 94.2 cm)', true, '1c9e2f86-3c1d-484a-996c-f3ceeccf1ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f25c2630-e492-4642-9b13-9459d3cdb4e7', '47.1 cm', false, '1c9e2f86-3c1d-484a-996c-f3ceeccf1ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32cc8600-6a16-4a11-9bd0-a346f9907e27', '150 cm', false, '1c9e2f86-3c1d-484a-996c-f3ceeccf1ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3cc33e9-7e87-4808-865a-a40f30bf4010', '31.4 cm', false, '1c9e2f86-3c1d-484a-996c-f3ceeccf1ce3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fccc9c7b-f71a-4466-9cf9-262215a10a3d', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'The area of a triangle is 50 cm². If one of its sides is 20 cm, find the corresponding altitude (height) to that side:', '50 = ½(20)h → 10h = 50 → h = 5 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('460bb736-cc88-40c0-8bad-ef816eb0d78f', '5 cm (Area = 1/2 × b × h ⇒ 50 = 1/2 × 20 × h ⇒ 50 = 10h ⇒ h = 5 cm)', true, 'fccc9c7b-f71a-4466-9cf9-262215a10a3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e323801-208a-4045-81b0-38986592dbc6', '10 cm', false, 'fccc9c7b-f71a-4466-9cf9-262215a10a3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d627f66-8805-4567-8c19-7dd6c2a89f67', '2.5 cm', false, 'fccc9c7b-f71a-4466-9cf9-262215a10a3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f4fb8e-066a-47c5-8b3a-da268f1b2167', '4 cm', false, 'fccc9c7b-f71a-4466-9cf9-262215a10a3d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7bd4140-7a69-4e96-be54-9ce4c8317ac7', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'Find the perimeter of a semicircle of radius 7 cm including its diameter base (Take π = 22/7):', 'Perimeter of closed semicircle = πr + 2r = 22 + 14 = 36 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8707327a-d6c9-46fb-8a41-c612635b5d2a', '36 cm (Perimeter = πr + 2r = (22/7) × 7 + 14 = 22 + 14 = 36 cm)', true, 'c7bd4140-7a69-4e96-be54-9ce4c8317ac7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adf29065-7ee6-4fec-8b70-8950352e52f3', '44 cm', false, 'c7bd4140-7a69-4e96-be54-9ce4c8317ac7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17e02e6a-d624-436f-91cf-7427ffaedea4', '22 cm', false, 'c7bd4140-7a69-4e96-be54-9ce4c8317ac7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e819e840-c3f6-481a-995f-05ff2ace9316', '29 cm', false, 'c7bd4140-7a69-4e96-be54-9ce4c8317ac7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3a6fe40-7e38-4a35-8871-edd93be65df3', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'Convert 5.4 m² into cm²:', '5.4 × 10,000 = 54,000 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca43cba6-4281-49b7-bfd6-2f2762c2ff5e', '54,000 cm² (1 m² = 10,000 cm² ; 5.4 × 10,000 = 54,000 cm²)', true, 'd3a6fe40-7e38-4a35-8871-edd93be65df3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94763279-2ed1-4187-bfec-0809b9dda9e4', '540 cm²', false, 'd3a6fe40-7e38-4a35-8871-edd93be65df3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfa7cd1f-ede7-4a2a-af2a-2217b3631b70', '5,400 cm²', false, 'd3a6fe40-7e38-4a35-8871-edd93be65df3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc458c96-0ac1-4591-b231-3d83d637c900', '540,000 cm²', false, 'd3a6fe40-7e38-4a35-8871-edd93be65df3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54044fa9-1a5e-4ec9-96b3-92c2215e271c', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a492cc6-749f-44ae-af71-74c5213c6f29', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '54044fa9-1a5e-4ec9-96b3-92c2215e271c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0dccd53-eefa-4093-ab82-5d95785f3131', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '54044fa9-1a5e-4ec9-96b3-92c2215e271c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22d53725-21d2-4aaa-b345-f30970ffd3d0', '(A) is true, but (R) is false.', false, '54044fa9-1a5e-4ec9-96b3-92c2215e271c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d700779a-d828-4169-abd1-be0fc8f30440', '(A) is false, but (R) is true.', false, '54044fa9-1a5e-4ec9-96b3-92c2215e271c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b262a37-6360-430b-a65d-3854c6ff2e5d', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Spot the IMPOSTER in the following area and metric unit conversion formulas:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a57248-cb4a-4755-abcc-0367b8306f8d', 'Formula 1', false, '9b262a37-6360-430b-a65d-3854c6ff2e5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('820bff7b-a84f-44e2-9b9c-09d7114482bb', 'Formula 2', false, '9b262a37-6360-430b-a65d-3854c6ff2e5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf1a579f-0d97-4858-958e-343db77eeb3a', 'Formula 3', false, '9b262a37-6360-430b-a65d-3854c6ff2e5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb596281-0f02-4834-8f13-6fda9a58619d', 'Formula 4 (Circumference is 2πr or πd ; πr² is the formula for the AREA of a circle)', true, '9b262a37-6360-430b-a65d-3854c6ff2e5d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7a73ebe-9e26-472b-9d67-104e057693ba', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'In ΔABC, right-angled at A, AD is perpendicular to BC. If AB = 5 cm, BC = 13 cm, and AC = 12 cm, find the Area of ΔABC and the length of AD:', 'Area = ½(5)(12) = 30 cm². Also 30 = ½(13)(AD) → AD = 60/13 ≈ 4.615 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('827e69f6-062b-4280-8891-561a5e20523e', 'Area = 30 cm² ; AD = 4.61 cm (60/13 cm) (Area = 1/2 × 5 × 12 = 30 cm² ; Also Area = 1/2 × BC × AD ⇒ 30 = 1/2 × 13 × AD ⇒ AD = 60/13 ≈ 4.61 cm)', true, 'f7a73ebe-9e26-472b-9d67-104e057693ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a049dcd-3c89-4632-b6f8-ab8b96291a1d', 'Area = 60 cm² ; AD = 5 cm', false, 'f7a73ebe-9e26-472b-9d67-104e057693ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f21ec6a6-c571-4be2-9b66-caf272f9ff99', 'Area = 30 cm² ; AD = 6 cm', false, 'f7a73ebe-9e26-472b-9d67-104e057693ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd81f46b-68b1-41d7-ab92-8d397f8beb37', 'Area = 65 cm² ; AD = 4.61 cm', false, 'f7a73ebe-9e26-472b-9d67-104e057693ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b513e1a-977f-4146-8b57-d387bf5cab0d', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Match Column I (Geometric Figures with Dimensions) with Column II (Calculated Areas):
(a) Square of perimeter 60 cm              -> (i) 225 cm² (Side = 15 cm ; Area = 15² = 225)
(b) Circle of radius 7 cm                  -> (ii) 154 cm²
(c) Parallelogram (base 12 cm, height 8 cm)-> (iii) 96 cm²
(d) Triangle (base 14 cm, height 10 cm)    -> (iv) 70 cm²', 'Square: 15² = 225; Circle: 22/7(49) = 154; Parallelogram: 12×8 = 96; Triangle: ½(14)(10) = 70.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c22e146a-cef8-46f2-b37a-36df6f806d7b', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '7b513e1a-977f-4146-8b57-d387bf5cab0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37a59b74-73d2-4382-a6da-b7ef0cee1436', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '7b513e1a-977f-4146-8b57-d387bf5cab0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbb97283-443b-48d0-b332-9a9b5b303ba9', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '7b513e1a-977f-4146-8b57-d387bf5cab0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2d81809-c1ac-4d4d-803f-fef6eeb16c23', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '7b513e1a-977f-4146-8b57-d387bf5cab0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dba6f0b2-b681-4455-a38e-0a00a6d5f108', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Read the statements regarding metric area relationships:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09c596e0-1216-471e-ba9e-923110ee3e57', 'Statements 1 and 2 only', true, 'dba6f0b2-b681-4455-a38e-0a00a6d5f108');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faf35535-b57d-425c-9730-95949bfe4860', 'Statements 2 and 3 only', false, 'dba6f0b2-b681-4455-a38e-0a00a6d5f108');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f52172b4-359d-4601-845f-a44a88fd7c5d', 'Statements 1 and 3 only', false, 'dba6f0b2-b681-4455-a38e-0a00a6d5f108');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('863aa3fd-5ea1-4674-8daf-95f994d54bac', 'All Statements 1, 2, and 3', false, 'dba6f0b2-b681-4455-a38e-0a00a6d5f108');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3684c188-ac6d-4263-adf8-cfacfef0ec68', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'If the ratio of the areas of two circles is 49 : 64, find the RATIO OF THEIR CIRCUMFERENCES:', 'Circumference ratio equals radius ratio = √(49/64) = 7/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e589ff0-c3d3-4ec1-af76-d1117f22650d', '7 : 8 (Area ratio = (r1/r2)² = 49/64 ⇒ r1/r2 = 7/8 ; Circumference ratio = 2πr1 / 2πr2 = r1/r2 = 7 : 8)', true, '3684c188-ac6d-4263-adf8-cfacfef0ec68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('603c5b82-4153-444a-94f4-c5cd0e1b96e8', '49 : 64', false, '3684c188-ac6d-4263-adf8-cfacfef0ec68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('357e5770-d1fb-4c37-b3d9-9c2a3d7ec5cb', '14 : 16', false, '3684c188-ac6d-4263-adf8-cfacfef0ec68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0b72718-f0d7-4752-90c0-01aee8d9f2c3', '343 : 512', false, '3684c188-ac6d-4263-adf8-cfacfef0ec68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf4c9a5d-17ad-4431-aa03-f7d5e9f2464d', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'A racetrack is in the form of a circular ring whose inner circumference is 352 m and outer circumference is 396 m. Find the WIDTH of the track (Take π = 22/7):', 'R = 396 / 44 × 7 = 63 m. r = 352 / 44 × 7 = 56 m. Width = 63 - 56 = 7 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7c90790-9842-4e2b-bda4-1064991d56f8', '7 m (Outer radius R = 396 / (2 × 22/7) = 63 m ; Inner radius r = 352 / (2 × 22/7) = 56 m ; Width = R - r = 63 - 56 = 7 m)', true, 'bf4c9a5d-17ad-4431-aa03-f7d5e9f2464d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('100ef232-5e1a-4952-b231-b3a702c0332e', '14 m', false, 'bf4c9a5d-17ad-4431-aa03-f7d5e9f2464d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3689b37c-4493-493e-8adf-5ac66c1d1ac9', '3.5 m', false, 'bf4c9a5d-17ad-4431-aa03-f7d5e9f2464d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49bd37d0-a058-45a0-a3ec-9f5313a47032', '10 m', false, 'bf4c9a5d-17ad-4431-aa03-f7d5e9f2464d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0704c48-10b3-4044-90fc-f449f68259ce', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'A wire loop of radius 21 cm is straightened and then bent into an equilateral triangle. Find the length of each side of the triangle (Take π = 22/7):', 'Wire perimeter = 2 × (22/7) × 21 = 132 cm. Side of triangle = 132 / 3 = 44 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('614dabec-0704-4991-ad7b-e8bad1c723bc', '44 cm (Wire length = Circumference = 2 × (22/7) × 21 = 132 cm ; Side of equilateral triangle = 132 / 3 = 44 cm)', true, 'a0704c48-10b3-4044-90fc-f449f68259ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9819081a-ba37-4dc1-942c-ee54f64e0013', '33 cm', false, 'a0704c48-10b3-4044-90fc-f449f68259ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31f8f24a-aaa5-4ce3-92c7-ac9a873a6162', '22 cm', false, 'a0704c48-10b3-4044-90fc-f449f68259ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee118c9a-42b7-4592-9f38-21aac0bb62b2', '66 cm', false, 'a0704c48-10b3-4044-90fc-f449f68259ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b07eb83-cd60-4534-ab45-a5ec457bcfdf', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'The base of a parallelogram is TWICE its height. If the area of the parallelogram is 512 cm², find its base and height:', '2h² = 512 → h = √256 = 16 cm. Base = 32 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81adfbac-18fc-470a-9a9a-bda6ba514b26', 'Base = 32 cm ; Height = 16 cm (Area = b × h ⇒ (2h) × h = 512 ⇒ 2h² = 512 ⇒ h² = 256 ⇒ h = 16 cm ; b = 2 × 16 = 32 cm)', true, '6b07eb83-cd60-4534-ab45-a5ec457bcfdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5396ff6-7e81-4838-98fb-a8fa131d0712', 'Base = 16 cm ; Height = 8 cm', false, '6b07eb83-cd60-4534-ab45-a5ec457bcfdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec5d29e8-c76c-4cbc-97ac-b6940a3fcdeb', 'Base = 64 cm ; Height = 32 cm', false, '6b07eb83-cd60-4534-ab45-a5ec457bcfdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08ecd45a-fd8f-4bfe-b80f-e28eaf179442', 'Base = 24 cm ; Height = 12 cm', false, '6b07eb83-cd60-4534-ab45-a5ec457bcfdf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fc443e4-6660-421e-8ec3-be6d82bc8818', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Four equal circles, each of radius 7 cm, are placed touching each other so that their centres form a square of side 14 cm. Find the AREA of the shaded space enclosed between the four circles (Take π = 22/7):', 'Area between 4 circles = a² - πr² = 14² - (22/7)(7²) = 196 - 154 = 42 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80109895-3a7b-450a-872c-a3dba0047143', '42 cm² (Square Area = 14 × 14 = 196 cm² ; 4 quadrants = 1 full circle area = (22/7) × 7² = 154 cm² ; Enclosed Area = 196 - 154 = 42 cm²)', true, '6fc443e4-6660-421e-8ec3-be6d82bc8818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('401aaf73-1ba3-47e8-b9aa-f4724eda8cc9', '56 cm²', false, '6fc443e4-6660-421e-8ec3-be6d82bc8818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('540b990f-a848-4e05-a453-c911c225ef57', '28 cm²', false, '6fc443e4-6660-421e-8ec3-be6d82bc8818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d734191-bfff-4aef-ada8-c4a67cd1f08b', '36 cm²', false, '6fc443e4-6660-421e-8ec3-be6d82bc8818');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fed56d2f-4750-476e-9646-adf0842fbfbe', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'A copper wire when bent in the form of a square encloses an area of 484 cm². If the same wire is bent into a circle, find the area enclosed by the circle (Take π = 22/7):', 'Square side = 22 cm → P = 88 cm. Radius = 14 cm. Circle area = (22/7)(196) = 616 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a62f194c-c7bc-4f84-9411-dca9efa9f3bd', '616 cm² (Side of square = √484 = 22 cm ; Perimeter = 4 × 22 = 88 cm ; Circle radius = 88 / (2 × 22/7) = 14 cm ; Circle Area = (22/7) × 14² = 616 cm²)', true, 'fed56d2f-4750-476e-9646-adf0842fbfbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3755c053-0512-40d9-a446-36918c4fa175', '550 cm²', false, 'fed56d2f-4750-476e-9646-adf0842fbfbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40769305-5ebc-495e-a673-7b59cffcf307', '484 cm²', false, 'fed56d2f-4750-476e-9646-adf0842fbfbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d81b40db-f6eb-4afd-ae13-933970398f99', '625 cm²', false, 'fed56d2f-4750-476e-9646-adf0842fbfbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('096d6fed-1b55-44d2-8219-812280b64616', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Why is the geometric calculation of Perimeter and 2D Area vital across civil architecture, land revenue cartography, urban planning, and material engineering?', 'Perimeter and area calculations are the universal geometric foundations for material procurement, boundary demarcation, and structural design.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cad84a29-4e77-4eb9-9905-850cbcf43fc6', 'It determines exact material quantities required for boundaries, fencing, tiling, paving, surface coatings, structural loads, and agricultural land taxation', true, '096d6fed-1b55-44d2-8219-812280b64616');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44c84810-341a-44d5-8ae9-35c00be3a72f', 'Because area is used only to draw circles', false, '096d6fed-1b55-44d2-8219-812280b64616');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf959092-a1b6-4dc9-9988-bb0d94ee1db8', 'Because perimeter is measured only with sticks', false, '096d6fed-1b55-44d2-8219-812280b64616');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baafcb14-6e2c-4921-86c3-99e0c412056c', 'Because modern construction ignores geometry', false, '096d6fed-1b55-44d2-8219-812280b64616');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('067d90e8-dc18-498f-9187-ac77a0c0d37c', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'In Jerome K. Jerome''s comedic story ''A Bicycle in Good Repair'', what excursion was planned for the following day?', 'The narrator and an acquaintance arranged to go for a long bicycle ride together early the next morning.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9c460aa-4b9a-4850-be8e-06b7967c8638', 'A long bicycle ride together out into the countryside', true, '067d90e8-dc18-498f-9187-ac77a0c0d37c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fac3ea2-55dc-4a3e-86f7-118d7729c4d5', 'A train journey to London', false, '067d90e8-dc18-498f-9187-ac77a0c0d37c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ee1555e-d079-42e4-bc0a-6886e746ff39', 'A boat trip down the river', false, '067d90e8-dc18-498f-9187-ac77a0c0d37c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fdc5d04-0be3-4174-a8ba-6c1875c81562', 'A mountain climbing hike', false, '067d90e8-dc18-498f-9187-ac77a0c0d37c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e1d57b1-26ad-47aa-a22e-14bac57abe91', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What did the acquaintance do to the bicycle as soon as he saw it, before they had even set off?', 'The acquaintance aggressively shook the bicycle: ''He took hold of it by the front wheel and the fork, and shook it violently.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('443b9cc3-7b6c-481e-87d2-dd7dcf2e7de1', 'He shook it violently by the front wheel and handlebars, claiming the front wheel wobbled dangerously', true, '2e1d57b1-26ad-47aa-a22e-14bac57abe91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34bb83d2-3976-4051-abc4-85db20723d08', 'He rode it happily down the road', false, '2e1d57b1-26ad-47aa-a22e-14bac57abe91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f75a397-0909-41ce-a9be-95bf9c630026', 'He washed it with soap', false, '2e1d57b1-26ad-47aa-a22e-14bac57abe91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b4cfcf9-6a6e-4515-bc2d-826ce0e57c33', 'He painted it blue', false, '2e1d57b1-26ad-47aa-a22e-14bac57abe91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab8274ab-97b7-4364-a3f5-e25091746c12', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What small, rolling metal items spilled out everywhere across the gravel path when the acquaintance unscrewed the front wheel bearing?', 'Unscrewing the axle housing released a dozen little ball-bearings that rolled all over the gravel.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae01ae5f-c0de-457f-a5fe-e34ef99b7715', 'Little steel ball-bearings (little balls)', true, 'ab8274ab-97b7-4364-a3f5-e25091746c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9536029b-c672-4f0e-bc8d-684c168a53fa', 'Small wooden screws', false, 'ab8274ab-97b7-4364-a3f5-e25091746c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8edcc334-e980-4776-9d98-afaec6810001', 'Gold coins', false, 'ab8274ab-97b7-4364-a3f5-e25091746c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae62a135-61a5-4092-98bf-a6e0bb968085', 'Glass marbles', false, 'ab8274ab-97b7-4364-a3f5-e25091746c12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ef6dc50-a97b-49de-ac0b-acf38a6827c4', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'Where did the narrator and his friend put the rescued ball-bearings for safekeeping?', 'They stored the collected ball bearings in the narrator''s hat, which was subsequently blown off by the wind.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d5290f7-f36c-4e42-a9e6-4170889abbf6', 'Inside the narrator''s Hat (which later blew away in the wind)', true, '2ef6dc50-a97b-49de-ac0b-acf38a6827c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41e35a96-a290-4aa2-be3f-8838ba0bb68e', 'In a metal box', false, '2ef6dc50-a97b-49de-ac0b-acf38a6827c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5fe2823-4dec-4c96-aa69-021a3927606f', 'In a leather wallet', false, '2ef6dc50-a97b-49de-ac0b-acf38a6827c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72b0a4c1-7e90-4fed-8b52-99ebd39cf3f7', 'In a glass jar', false, '2ef6dc50-a97b-49de-ac0b-acf38a6827c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3441ab07-adc3-4efe-8ad8-7ae4dd2dbebf', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What part of the bicycle did the acquaintance next take to pieces, despite an experienced friend having advised the narrator NEVER to touch it?', 'He dismantled the gear-case, cutting it in two pieces, ignoring the advice to buy a new bicycle rather than tamper with it.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ea03f6f-7b5d-475e-9de3-f2c40830a806', 'The Gear-case', true, '3441ab07-adc3-4efe-8ad8-7ae4dd2dbebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8961853d-aa4a-4807-b327-499c3f8233ac', 'The Saddle', false, '3441ab07-adc3-4efe-8ad8-7ae4dd2dbebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bf71a35-978c-46c1-947b-6532ad24aa8f', 'The Bell', false, '3441ab07-adc3-4efe-8ad8-7ae4dd2dbebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff06b4a8-3721-4edd-8fb2-5d604d24d13d', 'The Brake levers', false, '3441ab07-adc3-4efe-8ad8-7ae4dd2dbebf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01f5be85-80f4-437d-ae25-ad6e41fb6727', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What happened to the bicycle chain during the acquaintance''s destructive repair attempts?', 'Comedic incompetence: he first tightened the chain until it jammed, then loosened it until it hung double.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98ddd713-ce04-4492-bbe1-ac6dbbfb9da2', 'He tightened it until it would not move at all, and then loosened it until it was twice as loose as before', true, '01f5be85-80f4-437d-ae25-ad6e41fb6727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0c9c5dc-c40c-4609-9504-9127978ab7a2', 'He threw it into the pond', false, '01f5be85-80f4-437d-ae25-ad6e41fb6727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0912cbe2-4e50-4507-82a4-bea5abe52f7c', 'He tied it to a tree', false, '01f5be85-80f4-437d-ae25-ad6e41fb6727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('211fff14-b6c4-4c67-8e2d-c5a747e319d8', 'It turned into gold', false, '01f5be85-80f4-437d-ae25-ad6e41fb6727');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf480027-68f6-4075-93f2-cc1defe226c1', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What physical condition were both the acquaintance and the bicycle in by late afternoon?', 'The scene ended in utter slapstick wreckage: a grease-stained man struggling against a wrecked bicycle on the lawn.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67a89508-0ab1-4c63-a90c-52b84d73613f', 'The acquaintance was covered in black oil, grease, and dirt, bleeding from scratches, and the bicycle was lying in a mangled heap across the path', true, 'cf480027-68f6-4075-93f2-cc1defe226c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1b20868-a912-46b4-9ceb-b3a165043461', 'Both were clean and ready for a race', false, 'cf480027-68f6-4075-93f2-cc1defe226c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8af381fe-a300-4d70-9eeb-c046b04846e6', 'The bicycle had flown away', false, 'cf480027-68f6-4075-93f2-cc1defe226c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('000873c9-4337-4f36-8b6d-8076b9aea0d2', 'They had ridden 50 miles', false, 'cf480027-68f6-4075-93f2-cc1defe226c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91ffa6b5-1373-419f-b859-80d86bd9ec5a', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'In Muriel L. Sonne''s poem ''Garden Snake'', what does the child do upon first spotting a snake in the garden?', 'The poem begins: ''I saw a snake and ran away... / Some snakes are dangerous, they say;''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bebe74d-287d-4eff-a0c4-b4899e3d2854', 'The child runs away in fright, believing that ''some snakes are dangerous''', true, '91ffa6b5-1373-419f-b859-80d86bd9ec5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f0af801-9da7-4ff1-ba63-263c3157672e', 'The child tries to catch the snake with a stick', false, '91ffa6b5-1373-419f-b859-80d86bd9ec5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6894319d-771d-4f4e-a2fa-e653e2b1850d', 'The child steps on the snake', false, '91ffa6b5-1373-419f-b859-80d86bd9ec5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('206807a2-da54-4669-9c13-68e7f007fc8f', 'The child takes a picture', false, '91ffa6b5-1373-419f-b859-80d86bd9ec5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('066ac130-5351-41b6-8a50-40d5137219a2', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What comforting and reassuring advice does Mother give to the frightened child in ''Garden Snake''?', 'Mother says: ''"that kind is good, / And eats up insects for his food." / So when he wiggles in the grass / I''ll stand aside and watch him pass''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07ab1a87-f5a8-4c0a-b34f-fba41bad0364', 'She explains that the garden snake is completely harmless (''that kind is good'') and eats only ordinary garden insects for its food', true, '066ac130-5351-41b6-8a50-40d5137219a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec02fb1b-9be6-454f-8061-f4dcb361c8b0', 'She tells the child to kill the snake', false, '066ac130-5351-41b6-8a50-40d5137219a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60ad0b0d-a14b-499e-8bee-385e5c29fe27', 'She tells the child to stay inside the house forever', false, '066ac130-5351-41b6-8a50-40d5137219a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f123d5a2-6c72-4fa6-bdff-83a42025c33e', 'She tells the child to call the police', false, '066ac130-5351-41b6-8a50-40d5137219a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6b39158-bdde-4fc6-8870-3e9a96c48089', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'How does the child''s perspective on the garden snake change by the end of the poem?', 'Ending lines: ''I''ll stand aside and watch him pass, / And tell myself, "There''s no mistake, / It''s just a harmless garden snake!"''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44cd543c-aa26-436d-9448-b89fd4b038c7', 'The child stands aside calmly to admire the harmless little green snake wriggling through the grass with affection and respect', true, 'c6b39158-bdde-4fc6-8870-3e9a96c48089');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33f8d61f-753b-4b91-bd71-fdf732013da9', 'The child continues to scream in terror', false, 'c6b39158-bdde-4fc6-8870-3e9a96c48089');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b12dd23-b8ea-445e-9c2a-c49e331cfa1b', 'The child buys a pet dog', false, 'c6b39158-bdde-4fc6-8870-3e9a96c48089');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f329d2ae-df63-4072-9d6a-fd5a1dcb8834', 'The child moves to another city', false, 'c6b39158-bdde-4fc6-8870-3e9a96c48089');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43207e83-8d85-4b4b-a803-a4de6a212e8c', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What is the meaning of the word ''Wobble'' as applied to the bicycle wheel?', '''Wobble'' means an unsteady, irregular side-to-side oscillation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71cf0177-23be-401a-b081-42501dfba3c1', 'To move unsteadily from side to side in an unsteady manner', true, '43207e83-8d85-4b4b-a803-a4de6a212e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58321f0d-ac42-4559-8eee-e68403d16707', 'To roll very fast', false, '43207e83-8d85-4b4b-a803-a4de6a212e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c37a34-0a06-44f9-a66d-4ea35c4145d7', 'To stop suddenly', false, '43207e83-8d85-4b4b-a803-a4de6a212e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5673aaad-301c-49a9-bad7-3bbabfed7813', 'To shine brightly', false, '43207e83-8d85-4b4b-a803-a4de6a212e8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4e97bcc-5323-4400-911c-776cbd60afe1', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What is the meaning of ''Wiggles'' in the description of the garden snake?', '''Wiggle'' describes the undulating serpentine lateral movement of a snake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ce6b738-296a-424f-a23e-10815a098abc', 'Moves with quick, small, wave-like side-to-side undulating motions', true, 'f4e97bcc-5323-4400-911c-776cbd60afe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9905a8f6-9021-4a02-af55-88663c06f968', 'Jumps up in the air', false, 'f4e97bcc-5323-4400-911c-776cbd60afe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9518dbb9-01f7-4c7b-8ca8-ab4b94a52bb2', 'Stands completely still', false, 'f4e97bcc-5323-4400-911c-776cbd60afe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb65f850-d034-4482-a79d-90f44edcf4c3', 'Flies with wings', false, 'f4e97bcc-5323-4400-911c-776cbd60afe1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a260b9ef-233b-452c-a9e3-3cb9a16e24bb', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'Why was the narrator unable to prevent his destructive acquaintance from completely dismantling his perfectly functioning bicycle?', 'Narrator''s comedic flaw: excessive English social politeness and self-doubt prevents him from stopping blatant mechanical vandalism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00ca0f49-68fd-4042-952a-a20055e36cba', 'The narrator suffered from excessive politeness, timid hesitation, and a mistaken deference that made him afraid of hurting his friend''s enthusiastic self-confidence', true, 'a260b9ef-233b-452c-a9e3-3cb9a16e24bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5545ad6-03f1-443f-9352-17c8b0179bcc', 'Because the acquaintance had a gun', false, 'a260b9ef-233b-452c-a9e3-3cb9a16e24bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e645a76e-84d2-4897-8bf3-0b6ba73d2a04', 'Because the bicycle belonged to the acquaintance', false, 'a260b9ef-233b-452c-a9e3-3cb9a16e24bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54b75158-e087-4e2c-8d90-50de2dfface9', 'Because the narrator was fast asleep', false, 'a260b9ef-233b-452c-a9e3-3cb9a16e24bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5cd455e-b188-4668-affd-4c3e4e3efe0d', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'How did the acquaintance personify the bicycle during their furious physical struggle in the garden?', 'Hyperbolic comic personification: the bicycle becomes a combatant: ''Now he was on top of the bicycle, and now the bicycle was on top of him.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57e720b0-a7df-40a1-be15-915b9e9c7099', 'He treated the bicycle like a willful, vicious adversary that fought back, hit him over the head with the handlebars, and leaped onto him in the dirt', true, 'e5cd455e-b188-4668-affd-4c3e4e3efe0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96d6d95b-8b4c-40d6-bf90-aab97b99939c', 'He treated it like a loyal horse', false, 'e5cd455e-b188-4668-affd-4c3e4e3efe0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2bee560-9c09-41e7-bdc9-3a3222283afc', 'He treated it like an electric train', false, 'e5cd455e-b188-4668-affd-4c3e4e3efe0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5911a69-bdc8-4aa0-a08a-c91fa2b84720', 'He treated it like a clock', false, 'e5cd455e-b188-4668-affd-4c3e4e3efe0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdcdea4b-a00c-4624-a530-91e38b2e7800', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the central ecological theme of Muriel L. Sonne''s poem ''Garden Snake''?', 'The poem deconstructs the irrational ophidiophobia (fear of snakes), celebrating the ecological value of harmless garden reptiles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2719c677-af13-477a-82dc-485fee116400', 'Overcoming irrational fear of nature through knowledge: understanding that garden snakes are harmless, beneficial predators that control garden insect pests', true, 'fdcdea4b-a00c-4624-a530-91e38b2e7800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7dd42c4-eb13-4d19-91f7-6eaae54c2b8b', 'Teaching people how to build cages', false, 'fdcdea4b-a00c-4624-a530-91e38b2e7800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ffd262d-0819-4726-8f4e-74545896af5f', 'Warning that all animals in gardens are poisonous', false, 'fdcdea4b-a00c-4624-a530-91e38b2e7800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d774767-5601-4fba-bb40-a6dd7ce6baaa', 'Explaining how to cut lawn grass', false, 'fdcdea4b-a00c-4624-a530-91e38b2e7800');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('135bf460-c464-4842-a543-cddbfbdadf38', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the meaning of the idiom ''To take to pieces'' in: ''He took the gear-case to pieces''?', '''To take to pieces'' is an idiom meaning completely disassembling a mechanical device.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ea5d6d7-9be2-4707-8744-4133e0dd982e', 'To dismantle or disassemble into separate component parts', true, '135bf460-c464-4842-a543-cddbfbdadf38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96017f9b-0c42-4bce-948b-38e7e62a65f5', 'To throw away into a river', false, '135bf460-c464-4842-a543-cddbfbdadf38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0626e098-8f7e-4799-92f8-d233dcc9c035', 'To break with a hammer', false, '135bf460-c464-4842-a543-cddbfbdadf38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d449fad-3367-4bea-a742-8e32cb518300', 'To paint each piece a different color', false, '135bf460-c464-4842-a543-cddbfbdadf38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f513a576-0c6f-4919-b7da-884301c72769', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the meaning of the adjective ''Grotesque'' in: ''The bicycle looked a grotesque skeleton''?', '''Grotesque'' characterizes an incongruously distorted, bizarre, or deformed physical state.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf8ae95e-e0bf-4405-92f9-b045f3e35eca', 'Comically or repulsively distorted, bizarre, and unnatural in appearance', true, 'f513a576-0c6f-4919-b7da-884301c72769');
