INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('234d2623-9810-46f4-9376-22a9715df974', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the ANTONYM of ''Harmless'' in: ''A harmless garden snake''?', 'The antonym of ''harmless'' is ''harmful'', ''dangerous'', or ''venomous''.', NOW()) ON CONFLICT DO NOTHING;
