INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f54ab40b-c9e6-45bf-b112-8f6fbd084564', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'Convert the sentence into INDIRECT SPEECH:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f533d14-4b13-4531-89db-955c75b00561', 'Mother told me that that kind was good and ate insects for food.', true, 'f54ab40b-c9e6-45bf-b112-8f6fbd084564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ddd4edc-16c3-4cd9-8650-1e2e8d59982a', 'Mother said that that kind is good.', false, 'f54ab40b-c9e6-45bf-b112-8f6fbd084564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed900d33-b874-4238-9343-b9fe70e7b514', 'Mother asked if the snake eats insects.', false, 'f54ab40b-c9e6-45bf-b112-8f6fbd084564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8abbceb9-c57f-45dd-b4b7-729c440221fc', 'Mother told me don''t touch the snake.', false, 'f54ab40b-c9e6-45bf-b112-8f6fbd084564');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a99dd4fd-54c0-439d-90a8-ac38afdcfeec', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the rhyming scheme of Muriel L. Sonne''s poem ''Garden Snake''?', 'The poem employs simple, musical AABB rhyming couplets throughout.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d17d215-d740-48cd-88a9-81ef13a01f40', 'AABB (Rhyming couplets: away/say, good/food, grass/pass, mistake/snake)', true, 'a99dd4fd-54c0-439d-90a8-ac38afdcfeec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aff212d6-2c5d-44df-9a7c-083d8529a90f', 'ABAB', false, 'a99dd4fd-54c0-439d-90a8-ac38afdcfeec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebc2fea5-4d98-4222-bd55-ab8fa6b07f93', 'ABCB', false, 'a99dd4fd-54c0-439d-90a8-ac38afdcfeec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('292901b9-f30c-4052-b540-738694b26cc9', 'AABBCC', false, 'a99dd4fd-54c0-439d-90a8-ac38afdcfeec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63e9d2c5-ff1b-4d89-836c-67fca573c0b6', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the comedic irony in the title ''A Bicycle in Good Repair''?', 'Situational irony: a flawless bicycle is dismantled into junk under the guise of an expert ''repair''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55b4866a-85d5-4d97-ba6e-1e9aca31a383', 'The bicycle was initially in perfect working condition, but by the time the acquaintance finished ''repairing'' it, it was completely ruined and unusable', true, '63e9d2c5-ff1b-4d89-836c-67fca573c0b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c917c9b-4fce-4fa4-93fe-3b78f4124b73', 'The bicycle had gold wheels', false, '63e9d2c5-ff1b-4d89-836c-67fca573c0b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a347fd82-4278-4b7b-9f8c-11aca7fabdb4', 'The bicycle won a race', false, '63e9d2c5-ff1b-4d89-836c-67fca573c0b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f8663c5-18e2-42df-9976-b2a12503da87', 'The bicycle turned into a car', false, '63e9d2c5-ff1b-4d89-836c-67fca573c0b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae727145-cc23-472c-8c7f-c60c809f9acc', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What did the acquaintance say about the front wheel after putting it back together missing half its ball bearings?', 'He shrugs off the missing bearings: ''"It''ll do for the present,"'' despite egregious wobbling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb17a4b8-f0d9-4b9d-9e41-9533aee362aa', '"It''ll do for the present," though it wobbled like a child''s toy top', true, 'ae727145-cc23-472c-8c7f-c60c809f9acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c7ea297-bb00-4384-8e4e-71f59b58a8f4', '"It is as good as new!"', false, 'ae727145-cc23-472c-8c7f-c60c809f9acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07bab6b4-1cbb-44ca-b1b9-8320fd304348', '"We should buy a new wheel."', false, 'ae727145-cc23-472c-8c7f-c60c809f9acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3377891-4bae-4957-842f-79a2bf075c56', '"It can fly now!"', false, 'ae727145-cc23-472c-8c7f-c60c809f9acc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db0a6a86-e664-407c-b16e-2d714f67ec38', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What happened when the friend tried to put the chain back on the bicycle?', 'The chain episode is a masterclass in clumsy tinkering, swinging between unyielding tension and dangling slack.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c302b8da-99f6-45c0-9be4-f601be3f3075', 'He completely lost the screws, struggled for an hour, and made it alternately too tight and too loose', true, 'db0a6a86-e664-407c-b16e-2d714f67ec38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('988b813b-2f29-4a48-9f9a-491a2d01f8a8', 'He fixed it in two seconds', false, 'db0a6a86-e664-407c-b16e-2d714f67ec38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('652c98f5-ecd5-49b2-9d4f-8ee69d8ae77c', 'He replaced it with a gold chain', false, 'db0a6a86-e664-407c-b16e-2d714f67ec38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c4f32ee-17b4-4725-b427-5a836144897a', 'He gave up and walked away', false, 'db0a6a86-e664-407c-b16e-2d714f67ec38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d15cb09f-fe37-4553-bf8b-d7df5a3746b8', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'How did the narrator finally get rid of the exhausting friend at the end of the day?', 'The ordeal concludes with the narrator escorting the exhausted, blackened tinkerer to the railway station.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d59957e2-5482-4fa9-9b04-bd888e01cf97', 'He took him to the railway station, sent him off home on a train, and breathed a sigh of immense relief', true, 'd15cb09f-fe37-4553-bf8b-d7df5a3746b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db9d6efd-2280-486d-847f-51dd74788536', 'He gave him the bicycle as a gift', false, 'd15cb09f-fe37-4553-bf8b-d7df5a3746b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('425b0fcd-e29c-472e-89ac-f77b0391b0ae', 'He called the police', false, 'd15cb09f-fe37-4553-bf8b-d7df5a3746b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47025269-e943-47ed-9fb8-3f05e52f701d', 'He invited him to stay for a month', false, 'd15cb09f-fe37-4553-bf8b-d7df5a3746b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e1ce200-81d0-41b4-81b7-89611997c162', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5f46665-6678-4301-9433-f1e116bdec70', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '1e1ce200-81d0-41b4-81b7-89611997c162');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca412a29-b75d-467d-9942-242e9cd1b5b8', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '1e1ce200-81d0-41b4-81b7-89611997c162');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e793509-3ec1-4dee-9645-0fead01b9284', '(A) is true, but (R) is false.', false, '1e1ce200-81d0-41b4-81b7-89611997c162');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d64241f-a72d-4e08-ad64-5e6ca0656a69', '(A) is false, but (R) is true.', false, '1e1ce200-81d0-41b4-81b7-89611997c162');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b2ffcac-95e2-4598-9746-cf4499ddbd9d', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Spot the IMPOSTER in the following sequence of mechanical catastrophes inflicted on the bicycle by the friend:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0a0533d-3f36-426b-8fad-671e37c5bacb', 'Event 1', false, '4b2ffcac-95e2-4598-9746-cf4499ddbd9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e76534c6-9bb5-43af-887f-11eaa0e82855', 'Event 2', false, '4b2ffcac-95e2-4598-9746-cf4499ddbd9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b1aa7ec-1c3f-463e-9852-a3c5fe1d5f41', 'Event 3', false, '4b2ffcac-95e2-4598-9746-cf4499ddbd9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dc849ce-ef3d-4131-84df-e90f0e55bc61', 'Event 4 (Supersonic rocket engines do NOT belong to Jerome''s Victorian Victorian bicycling comedy)', true, '4b2ffcac-95e2-4598-9746-cf4499ddbd9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83f30a3c-225f-4669-9e8a-fd0c0695e745', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Analyze the psychological shift in ''Garden Snake'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dafa27d-4dc6-406a-8af6-641bef8244b6', 'The child moves from unthinking cultural fear (''Some snakes are dangerous, they say'') to informed scientific understanding (''that kind is good / eats insects''), replacing blind panic with serene appreciation', true, '83f30a3c-225f-4669-9e8a-fd0c0695e745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('745e113e-3c5d-4a5a-8469-441eb350c396', 'The child learns how to capture snakes in jars', false, '83f30a3c-225f-4669-9e8a-fd0c0695e745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36b6105-442a-4280-936b-49d1e7e95771', 'The child decides never to enter a garden again', false, '83f30a3c-225f-4669-9e8a-fd0c0695e745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e99de57-97ad-4536-bc24-b2842675905d', 'The child buys poison to spray on grass', false, '83f30a3c-225f-4669-9e8a-fd0c0695e745');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2f7a947-f57b-4b06-b435-ea92cccc1412', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Match Column I (Narrative Episodes / Literary Devices) with Column II (Comic & Thematic Functions):
(a) Ball-Bearings in Hat      -> (i) Slapstick disaster when the hat blows off and rolls away
(b) Bicycle Wrestling Match    -> (ii) Personification of the bicycle fighting back against its torturer
(c) Mother''s Reassurance      -> (iii) Voice of ecological wisdom dispelling irrational fears
(d) Over-polite Narrator       -> (iv) Comedic straight-man character enabling escalating chaos', 'Hat = slapstick loss; Wrestling = personification; Mother = ecological wisdom; Narrator = enabling straight-man.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5220e386-7ddd-48d4-9c8a-0996b2568f6a', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'b2f7a947-f57b-4b06-b435-ea92cccc1412');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30b9e103-e8fa-41eb-ac82-0e6a88731c1c', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'b2f7a947-f57b-4b06-b435-ea92cccc1412');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda237b1-a5be-4bf4-b211-71896f6a7f0a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b2f7a947-f57b-4b06-b435-ea92cccc1412');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2729866f-d85f-42e5-b7e3-8d33bae8bed6', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b2f7a947-f57b-4b06-b435-ea92cccc1412');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0911153a-7085-4e36-8ee9-8b413f1ff9af', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Read the statements regarding Jerome K. Jerome''s comedic style:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdcda646-eed2-4dc4-b5ec-4f44c4ebee26', 'Statements 1 and 2 only', true, '0911153a-7085-4e36-8ee9-8b413f1ff9af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cb5d50b-6e62-4c2a-b419-22dbf42bbe10', 'Statements 2 and 3 only', false, '0911153a-7085-4e36-8ee9-8b413f1ff9af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daab48af-59c8-489b-9e7c-d8faa1c372dd', 'Statements 1 and 3 only', false, '0911153a-7085-4e36-8ee9-8b413f1ff9af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ac4dce8-ec48-450d-bf23-d836dcad4bde', 'All Statements 1, 2, and 3', false, '0911153a-7085-4e36-8ee9-8b413f1ff9af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7431ea3-2bd9-47f5-9983-b056c5e6e6e8', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Identify the figure of speech in: ''The bicycle seemed to have also developed a malicious temper, leaping up and hitting him violently with its pedal.''', 'Personification endows the mechanical bicycle with deliberate malicious temper and physical aggression.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('842da820-fd07-4b3c-8eac-006f63102dba', 'Personification (attributing malicious intent and agency to an inanimate machine)', true, 'a7431ea3-2bd9-47f5-9983-b056c5e6e6e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2c808a6-471f-4a4d-9d0c-5392b73e6d68', 'Hyperbole only', false, 'a7431ea3-2bd9-47f5-9983-b056c5e6e6e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('175b60ad-f809-4b1d-9d16-56e74ed7d0b7', 'Simile', false, 'a7431ea3-2bd9-47f5-9983-b056c5e6e6e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de5d010b-0eaf-4a3c-abea-551b8b6d0a46', 'Alliteration only', false, 'a7431ea3-2bd9-47f5-9983-b056c5e6e6e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2612981e-c96a-4538-ade2-b46f173941fe', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'What is the grammatical construction in: ''Had the narrator spoken firmly at the beginning, the bicycle would not have been ruined.''?', 'Third conditional with inverted protasis (''Had he spoken'' = ''If he had spoken'') expressing counterfactual past regret.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e6ff7e5-7c49-4754-a0ee-8c9cfe173a64', 'Third Conditional (Inverted condition with past perfect ''Had he spoken'' and conditional perfect ''would not have been ruined'')', true, '2612981e-c96a-4538-ade2-b46f173941fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0497a5e6-01a7-4f34-8146-ab2427ecd538', 'First Conditional', false, '2612981e-c96a-4538-ade2-b46f173941fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('398a171e-6276-4f70-a6ab-e1a9cd2d2d38', 'Second Conditional', false, '2612981e-c96a-4538-ade2-b46f173941fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09e96585-fb1a-41d2-a412-8ba09b5ece91', 'Imperative sentence', false, '2612981e-c96a-4538-ade2-b46f173941fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc1e9e84-a523-49ea-8224-4be569c219d6', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Why does Jerome K. Jerome emphasize the advice given by the experienced friend regarding the ''gear-case''?', 'The gear-case warning reinforces the core comedic theme: unnecessary meddling with functional machines invites catastrophe.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36def780-28d6-48cc-a5cc-9c43ee55d0de', 'To underscore the timeless golden rule of mechanics: ''If it ain''t broke, don''t fix it'' — and to highlight the folly of tampering with complex mechanisms without expertise', true, 'cc1e9e84-a523-49ea-8224-4be569c219d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f285ca79-9248-4cc9-bfd6-b2e8d84ab4bb', 'To encourage people to destroy their bicycles', false, 'cc1e9e84-a523-49ea-8224-4be569c219d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1b4522d-7ef1-4353-9998-02c24b46ef49', 'To advertise gear-case manufacturers', false, 'cc1e9e84-a523-49ea-8224-4be569c219d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acc95387-3ef8-4562-b0f4-2c1a37656023', 'Because gear-cases are dangerous weapons', false, 'cc1e9e84-a523-49ea-8224-4be569c219d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('998457ca-5723-43f4-8eaa-414de472aac1', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'In ''Garden Snake'', what does the phrase ''There''s no mistake'' emphasize in the final line?', '''There''s no mistake'' affirms total intellectual certainty: rational comprehension replaces superstitious dread.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bd67179-e155-41c6-ad6a-94f812c5a5a9', 'The child''s newfound absolute confidence in scientific understanding, banishing all lingering doubts and fears', true, '998457ca-5723-43f4-8eaa-414de472aac1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f221bc91-dfdf-4574-8d19-6c5058d15d41', 'That the child made a mistake in an exam', false, '998457ca-5723-43f4-8eaa-414de472aac1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f7bb7cf-239d-4a05-9182-12c2a4c7c319', 'That the snake was a toy', false, '998457ca-5723-43f4-8eaa-414de472aac1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e546be85-ed6d-4409-b05e-bb96d4a87a4d', 'That the mother was wrong', false, '998457ca-5723-43f4-8eaa-414de472aac1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41bfc469-e3fc-46ae-85df-744bf8b2825b', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'What tone permeates the narrator''s observation: ''He was a person of boundless energy and incurable optimism, which made him all the more dangerous.''?', 'Deadpan irony: cheerful optimism paired with total incompetence is humorously diagnosed as a perilous combination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('812f0acd-d5da-4bcf-a894-a30bf70c7672', 'Dry, ironic, deadpan British humor highlighting the menace of enthusiastic incompetence', true, '41bfc469-e3fc-46ae-85df-744bf8b2825b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e43d1242-855e-4e30-b68c-f552f5f9b036', 'Furious hatred and violent anger', false, '41bfc469-e3fc-46ae-85df-744bf8b2825b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1f355b4-0089-437c-9abc-ab289c0701a1', 'Tearful grief and despair', false, '41bfc469-e3fc-46ae-85df-744bf8b2825b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4b23973-d9b3-4969-a81a-7e647d6326f7', 'Boring scientific recitation', false, '41bfc469-e3fc-46ae-85df-744bf8b2825b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f09a875-c3c0-46f2-b4e5-0da22255e7c5', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Which of the following proverbs best captures the central moral lesson of ''A Bicycle in Good Repair''?', 'The story epitomizes Pope''s adage ''A little learning is a dangerous thing'' applied to meddlesome tinkering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9baaa274-c138-4477-9ffa-6475855e97f5', '"A little learning is a dangerous thing" / "Leave well enough alone"', true, '4f09a875-c3c0-46f2-b4e5-0da22255e7c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab76f2ab-eec5-4ca1-94ad-e4fb1e7b77dc', '"All that glitters is not gold"', false, '4f09a875-c3c0-46f2-b4e5-0da22255e7c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c14c83d-0509-4b91-b34f-cf1eceb95919', '"A rolling stone gathers no moss"', false, '4f09a875-c3c0-46f2-b4e5-0da22255e7c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e838fad-474d-4358-8c0a-db93d3c7c8c1', '"Look before you leap into water"', false, '4f09a875-c3c0-46f2-b4e5-0da22255e7c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab3e1747-7e0d-4cc5-81e5-e3f7a44addf9', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'What overarching humanist message unites Chapter 9 of NCERT Class 7 English?', 'Chapter 9 weaves together social psychology, self-assertiveness, comedic humility, and rational coexistence with nature.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be65ca23-b1b1-452b-877a-e3c15dc764c8', 'The balance between polite social boundaries, humble self-awareness of one''s own limitations, and the courage to replace irrational superstitions with gentle ecological understanding', true, 'ab3e1747-7e0d-4cc5-81e5-e3f7a44addf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('006e6a7a-5439-4457-b1d4-19cc16984ccd', 'That bicycles should never be ridden by anyone', false, 'ab3e1747-7e0d-4cc5-81e5-e3f7a44addf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20b148b5-3ff5-473b-b4e2-a86cbf92ee3c', 'That snakes should be kept inside houses', false, 'ab3e1747-7e0d-4cc5-81e5-e3f7a44addf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa2991e6-df0c-4932-a98b-a9c451a74bfa', 'That all repairs should be done with hammers', false, 'ab3e1747-7e0d-4cc5-81e5-e3f7a44addf9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('532c5318-2bc7-4da3-82b2-1a4db2f03a93', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'In which year did the American Revolution reach its climax with the adoption of the historic ''Declaration of Independence'' on July 4?', 'The Second Continental Congress adopted the Declaration of Independence penned by Thomas Jefferson on 4 July 1776.', NOW()) ON CONFLICT DO NOTHING;
