INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca175f89-06bd-45e7-8ff6-948a6f0dd73b', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What historic event on July 14, 1789, in Paris marked the explosive outbreak of the FRENCH REVOLUTION?', 'The storming of the royal fortress-prison Bastille on 14 July 1789 became the symbol of the French Revolution (celebrated as Bastille Day).', NOW()) ON CONFLICT DO NOTHING;
