INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ccb501a-abf4-4920-9183-6c5bb9204035', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What was the famous inspiring tripartite slogan of the French Revolution that reshaped modern global political philosophy?', 'Liberté, Égalité, Fraternité was the rallying cry of the French Revolution and is enshrined in the preamble of modern democratic constitutions.', NOW()) ON CONFLICT DO NOTHING;
