INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b68a577-8570-46ba-aab2-f26b7f23774b', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'Who was the brilliant Scottish engineer who patented the modern condensing STEAM ENGINE in 1769, powering the Industrial Revolution?', 'James Watt''s separate condenser steam engine dramatically increased thermodynamic efficiency, powering industrial factories and locomotives.', NOW()) ON CONFLICT DO NOTHING;
