INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2904550f-f17b-4155-925e-b1a811470758', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What event in Sarajevo on June 28, 1914, triggered the outbreak of WORLD WAR I?', 'The assassination of Archduke Franz Ferdinand in Sarajevo sparked the chain reaction of military mobilizations that erupted into World War I (1914–1918).', NOW()) ON CONFLICT DO NOTHING;
