INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('341e8ec8-d573-4569-bd3c-f4420002bbe2', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What peace treaty signed in 1919 formally ended World War I and established the League of Nations?', 'The Treaty of Versailles (1919) imposed heavy war reparations on Germany and established the League of Nations.', NOW()) ON CONFLICT DO NOTHING;
