INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41c94f88-c815-4b1d-a38c-5ddda7b1bd87', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'Who led the Bolsheviks in the 1917 October Russian Revolution to overthrow the Provisional Government and establish the world''s first socialist state (USSR)?', 'Vladimir Lenin led the Bolshevik party to victory in 1917 under the slogan ''Peace, Land, and Bread'', founding the Soviet Union.', NOW()) ON CONFLICT DO NOTHING;
