INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('557494c7-6ad1-4fef-9025-96a238f753da', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'Which aggressive military action by Nazi Germany on September 1, 1939, triggered the immediate outbreak of WORLD WAR II?', 'Hitler''s blitzkrieg invasion of Poland on 1 Sept 1939 forced Britain and France to declare war on Nazi Germany, igniting WWII.', NOW()) ON CONFLICT DO NOTHING;
