INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d75b758c-be89-4ee9-a466-23bc16575c32', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What surprise military strike by Imperial Japan on December 7, 1941, brought the United States directly into World War II?', 'Japan''s carrier air raid on Pearl Harbor crippled the US Pacific Fleet and prompted US President Franklin D. Roosevelt''s declaration of war.', NOW()) ON CONFLICT DO NOTHING;
