INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41101bde-dd5b-4b98-9e21-a9d3ba02ff01', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'Which two Japanese cities were destroyed by American atomic bombs (''Little Boy'' and ''Fat Man'') in August 1945, bringing World War II to an end?', 'The atomic bombings of Hiroshima and Nagasaki in August 1945 caused unprecedented devastation, leading to Japan''s unconditional surrender.', NOW()) ON CONFLICT DO NOTHING;
