INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7f630c8-62cd-43e2-8f01-9f258b339c19', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What concrete barrier built in 1961 divided East and West Berlin during the Cold War, whose dramatic fall in November 1989 symbolized the collapse of communism in Eastern Europe?', 'The Berlin Wall fell on 9 November 1989, paving the way for German reunification and the dissolution of the Soviet bloc.', NOW()) ON CONFLICT DO NOTHING;
