INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be7c7738-d0a8-422d-9e48-b74e4ebe6b01', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'Who was the First Prime Minister of India who co-founded the NON-ALIGNED MOVEMENT (NAM) in 1961 along with President Tito of Yugoslavia and President Nasser of Egypt?', 'Jawaharlal Nehru, Josip Broz Tito, Gamal Abdel Nasser, Sukarno, and Kwame Nkrumah founded NAM in Belgrade (1961) to resist Cold War superpower blocs.', NOW()) ON CONFLICT DO NOTHING;
