INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7afbe0fb-0860-49e2-aaac-f9abc69f4bd0', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Boston Tea Party'' of December 16, 1773, that escalated tensions leading to the American Revolutionary War?', 'The Sons of Liberty dumped British tea to protest the Tea Act (1773), rallying the famous slogan ''No taxation without representation''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a612ed6b-60c0-4778-a636-85ff62a7b6ad', 'American colonists disguised as Mohawk Indians dumped 342 chests of British East India Company tea into Boston Harbor to protest unfair taxation without representation', true, '7afbe0fb-0860-49e2-aaac-f9abc69f4bd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40669e63-d8b1-499c-a93a-5d959f4e1104', 'A tea drinking festival in Boston', false, '7afbe0fb-0860-49e2-aaac-f9abc69f4bd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('844a22cd-8a6d-41a1-823c-61f640f21bf0', 'A British tea factory opening', false, '7afbe0fb-0860-49e2-aaac-f9abc69f4bd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95a96cfe-d0e7-49b6-bca6-944cfdfefb9d', 'A peaceful trade agreement between Britain and America', false, '7afbe0fb-0860-49e2-aaac-f9abc69f4bd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28f744af-734d-4239-bc20-81b7b2eb1091', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Reign of Terror'' (1793–1794) during the French Revolution led by Maximilien Robespierre?', 'Robespierre''s Jacobin regime executed over 17,000 citizens by guillotine until Robespierre himself was overthrown in the Thermidorian Reaction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18f1f9f1-d1d0-448f-bc37-30a36e31d62d', 'A period where the Committee of Public Safety executed tens of thousands of suspected ''counter-revolutionaries'' using the Guillotine', true, '28f744af-734d-4239-bc20-81b7b2eb1091');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0e463e8-f31d-469d-98a6-19f04d6add35', 'A war with Spain', false, '28f744af-734d-4239-bc20-81b7b2eb1091');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e98dc551-06fe-47d4-b70b-4d1c9c08b04f', 'A famine caused by freezing winter', false, '28f744af-734d-4239-bc20-81b7b2eb1091');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d5e0272-2f10-483e-a797-72823cc7337a', 'A military coup by Napoleon', false, '28f744af-734d-4239-bc20-81b7b2eb1091');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3e8a101-a086-4521-b114-b72e6c2956ca', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Which battle in 1815 in modern-day Belgium marked the final, decisive military defeat of Emperor Napoleon Bonaparte?', 'Napoleon was decisively routed at Waterloo on 18 June 1815, leading to his exile on the remote South Atlantic island of Saint Helena.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66d6516-b00b-4ec0-bd16-c9e2e19ca0f4', 'The Battle of Waterloo (defeated by Duke of Wellington and Blücher)', true, 'e3e8a101-a086-4521-b114-b72e6c2956ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7165e6e-16cd-4683-a1c7-0a995acbe665', 'The Battle of Austerlitz', false, 'e3e8a101-a086-4521-b114-b72e6c2956ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('190dda4a-ca5b-4dbe-944d-e60b98e387e9', 'The Battle of Trafalgar', false, 'e3e8a101-a086-4521-b114-b72e6c2956ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b7cc655-01fa-4e45-919b-7df0a27e685c', 'The Battle of Leipzig', false, 'e3e8a101-a086-4521-b114-b72e6c2956ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6a4b777-f7f2-47b5-9be4-531958af80f8', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Why is the Industrial Revolution considered a fundamental turning point in human civilization?', 'Mechanized mass manufacturing, urban industrialization, railways, and fossil energy fundamentally reshaped global demography and socio-economics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13dc6eff-b891-44a8-a86f-334bad04264f', 'It transformed agrarian, hand-craft economies into industrial, machine-driven manufacturing powerhouses fueled by steam, coal, electricity, and mass factory production', true, 'a6a4b777-f7f2-47b5-9be4-531958af80f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e969a109-a0d9-400c-ac85-c52e290d041c', 'It abolished all farming forever', false, 'a6a4b777-f7f2-47b5-9be4-531958af80f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ffba5e7-dd59-4c3b-9951-6405c65b676b', 'It made everyone become soldiers', false, 'a6a4b777-f7f2-47b5-9be4-531958af80f8');
