INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d6b1a13-b145-408c-a871-9f42333a2e7e', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Great Depression'' that began with the catastrophic Wall Street Stock Market Crash in October 1929 (''Black Tuesday'')?', 'The 1929 crash plunged global economies into severe contraction, deflation, and catastrophic unemployment until WWII rearmament.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a6d9807-8538-4fea-b740-da14feeaf705', 'The longest, deepest, and most widespread economic collapse of the 20th century, leading to mass unemployment, bank failures, and trade collapse worldwide', true, '8d6b1a13-b145-408c-a871-9f42333a2e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48afd7f3-0e75-49f6-b174-0a46128469cc', 'A medical disease in 1929', false, '8d6b1a13-b145-408c-a871-9f42333a2e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be3e1be2-033b-49c5-9b63-64e3aa1ecf90', 'A storm that flooded America', false, '8d6b1a13-b145-408c-a871-9f42333a2e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c985588-5c83-4f03-a527-a1b4c8c2a2d9', 'A war between banks', false, '8d6b1a13-b145-408c-a871-9f42333a2e7e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e504658-4277-47c0-b7f3-8d13ead4f0e3', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Battle of Stalingrad'' (1942–1943) in World War II, widely considered the decisive turning point on the European Eastern Front?', 'Stalingrad was the bloodiest battle in human history (~2 million casualties); the Soviet victory broke the backbone of the Wehrmacht.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5040c88a-de18-4403-a9c8-027de0a6cc7e', 'The bloody Soviet defense that completely encircled and destroyed the German 6th Army, reversing the Nazi advance and beginning Germany''s retreat to Berlin', true, '5e504658-4277-47c0-b7f3-8d13ead4f0e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21eaef0a-7b0c-4f57-a590-5966b4d3863f', 'A naval battle in the Atlantic', false, '5e504658-4277-47c0-b7f3-8d13ead4f0e3');
