INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4b20554-9c76-423b-94f3-0c64dd57cd7b', 'A tank battle in North Africa', false, '5e504658-4277-47c0-b7f3-8d13ead4f0e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a25f8ddd-9f5f-403c-84a0-06b87a6294b9', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was ''D-Day'' (Operation Overlord) on June 6, 1944?', 'General Dwight D. Eisenhower commanded the largest amphibious armada in history landing across Normandy beaches on 6 June 1944.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d14b9abb-26e7-40c8-8a60-359fa377ac88', 'The massive Allied amphibious invasion of Normandy (France) by American, British, and Canadian forces, establishing a western front to liberate Europe from Nazi occupation', true, 'a25f8ddd-9f5f-403c-84a0-06b87a6294b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('230797b7-8d6f-48f3-95c0-180b470ec06f', 'The surrender of Japan', false, 'a25f8ddd-9f5f-403c-84a0-06b87a6294b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5c0e1a7-e24f-490a-81de-1ff24fc9466d', 'The German invasion of Russia', false, 'a25f8ddd-9f5f-403c-84a0-06b87a6294b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85fbcf74-13cb-4ac2-ba22-0b1a82bdbaa3', 'The signing of the UN Charter', false, 'a25f8ddd-9f5f-403c-84a0-06b87a6294b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5312868-b5de-4165-82a0-0c0dbecc0319', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Cuban Missile Crisis'' in October 1962 during the Cold War?', 'The 1962 crisis was the closest the Cold War came to full-scale thermonuclear war, resolved by Soviet missile withdrawal and US pledge not to invade Cuba.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30064e18-e7d8-4c57-ae76-a9d77ee15fc1', 'A perilous 13-day nuclear standoff between the USA (President Kennedy) and USSR (Premier Khrushchev) over Soviet nuclear missiles deployed in Cuba, bringing the world to the brink of nuclear war', true, 'd5312868-b5de-4165-82a0-0c0dbecc0319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64c331d1-8e19-4c12-8d85-e6895616d236', 'A civil war in Cuba', false, 'd5312868-b5de-4165-82a0-0c0dbecc0319');
