INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3478d3b5-f8ec-40e2-b09f-843a03382d3a', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Holocaust'' perpetrated by Nazi Germany during World War II?', 'The Shoah / Holocaust was the horrific Nazi genocide that exterminated two-thirds of European Jewry in gas chambers and death camps.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bda4f08f-02de-4568-a1e5-14eb92c0f3fa', 'The systematic, state-sponsored genocide of six million European Jews and millions of others (Roma, Slavs, dissidents) in industrialized extermination camps (like Auschwitz-Birkenau)', true, '3478d3b5-f8ec-40e2-b09f-843a03382d3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5babc554-2333-4504-a552-1277fb3d5153', 'A military parade in Berlin', false, '3478d3b5-f8ec-40e2-b09f-843a03382d3a');
