INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6004f4e1-0f7e-4422-8740-4c973ba01808', 'A treaty between Germany and Italy', false, '3478d3b5-f8ec-40e2-b09f-843a03382d3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0680b8f0-041c-4140-980e-2881fecbe1d2', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Marshall Plan'' (European Recovery Program) enacted by the United States in 1948?', 'Initiated by US Secretary of State George Marshall, the plan revived Western European industrial production and economic stability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d25ef5d-8500-4578-b9b5-04851ca400d0', 'A massive American financial foreign-aid program ($13+ billion) to rebuild war-devastated Western European economies and prevent the spread of Soviet communism', true, '0680b8f0-041c-4140-980e-2881fecbe1d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2701a1ff-1fcf-4404-bdae-9cde8c661779', 'A military plan to conquer Asia', false, '0680b8f0-041c-4140-980e-2881fecbe1d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10046fba-d03a-4de7-85a0-885173aeed6e', 'A plan to build spaceships', false, '0680b8f0-041c-4140-980e-2881fecbe1d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1497f305-a13f-4ced-b091-507a032c06bc', 'A treaty to divide Germany', false, '0680b8f0-041c-4140-980e-2881fecbe1d2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1de8569-bbd0-49e1-920e-154b097a2870', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Which international treaty signed in 1968 aimed at preventing the spread of nuclear weapons and promoting nuclear disarmament?', 'The NPT (1968) established three pillars: non-proliferation, peaceful use of nuclear technology, and disarmament.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e46746e8-3cb5-4e03-ba1d-874fca2fc779', 'The Treaty on the Non-Proliferation of Nuclear Weapons (NPT)', true, 'b1de8569-bbd0-49e1-920e-154b097a2870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5dc36f7-cf84-4226-a880-9642d07ddf0d', 'The Kyoto Protocol', false, 'b1de8569-bbd0-49e1-920e-154b097a2870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13c06296-9110-4b7b-8f63-9e41eb099b0a', 'The Geneva Convention', false, 'b1de8569-bbd0-49e1-920e-154b097a2870');
