INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38f4c74a-a42f-49ae-942d-e35ce59806f5', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Meiji Restoration'' (1868) in Japanese history?', 'The Meiji era transformed feudal samurai Japan into an industrialized, modernized constitutional empire in just a few decades.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d51b81ae-62f2-41df-9693-4de4e85ac08c', 'The political revolution that ended the Tokugawa Shogunate, restored imperial rule under Emperor Meiji, and rapidly modernized and industrialized Japan into a global power', true, '38f4c74a-a42f-49ae-942d-e35ce59806f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c88d75b1-623c-4d68-b447-bfd932088802', 'The construction of Tokyo city', false, '38f4c74a-a42f-49ae-942d-e35ce59806f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfd6146-031e-4694-a517-71a327a39183', 'The adoption of Buddhism in Japan', false, '38f4c74a-a42f-49ae-942d-e35ce59806f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fab5f03-c3df-48c0-a942-ec1928e7ebcc', 'The isolation of Japan from the world', false, '38f4c74a-a42f-49ae-942d-e35ce59806f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('faf9413a-9493-4fa4-a6e6-9801daa3cb84', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Who was the South African anti-apartheid leader who spent 27 years imprisoned on Robben Island and became South Africa''s first black President in 1994?', 'Nelson Mandela led the ANC''s struggle against racial apartheid, earning the Nobel Peace Prize and inspiring global human rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1713f68a-42f5-4527-b001-6e5db79f68b9', 'Nelson Mandela', true, 'faf9413a-9493-4fa4-a6e6-9801daa3cb84');
