INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00a0c3b8-ab61-4418-905c-95fe0e0584ab', 'Kofi Annan', false, 'faf9413a-9493-4fa4-a6e6-9801daa3cb84');
