INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbb77e0d-5425-46c3-9da9-f6ee89d09b34', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Bandung Conference'' held in Indonesia in 1955?', 'The 1955 Bandung Conference articulated the Panchsheel principles and catalyzed the post-colonial Third World solidarity movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2644705e-da2d-45d1-b24e-dd1de17bed9d', 'A landmark summit of 29 Asian and African nations promoting Afro-Asian economic and cultural cooperation and opposing colonialism, which laid the foundation for the Non-Aligned Movement', true, 'cbb77e0d-5425-46c3-9da9-f6ee89d09b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4671b8d5-bc34-4f10-ab95-4de321783550', 'A trade summit of European bankers', false, 'cbb77e0d-5425-46c3-9da9-f6ee89d09b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2564db01-aa4b-4b70-aab8-ace48c328693', 'A military meeting of NATO', false, 'cbb77e0d-5425-46c3-9da9-f6ee89d09b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('577c6a1e-cc82-4770-948d-f804050b064f', 'A sports competition in Asia', false, 'cbb77e0d-5425-46c3-9da9-f6ee89d09b34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('915e3acb-25e5-45d0-97d8-18b56372c9c8', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What policies of ''Glasnost'' (Openness) and ''Perestroika'' (Restructuring) introduced by Soviet leader Mikhail Gorbachev in the late 1980s led to the dissolution of the Soviet Union in December 1991?', 'Gorbachev''s dual reforms intended to revitalize the USSR unleashed unstoppable democratic movements culminating in the peaceful collapse of the Soviet Union.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91fafb84-4055-4ddc-9d2e-a7c86271b7fc', 'Political democratization, freedom of the press, and economic decentralization that unintentionally dismantled Soviet totalitarian control', true, '915e3acb-25e5-45d0-97d8-18b56372c9c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf7deb76-e3db-4b7e-b950-4194e541e387', 'A plan to start a war with China', false, '915e3acb-25e5-45d0-97d8-18b56372c9c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66cbfd23-dce0-4f5e-8634-830e97e75b56', 'The banning of all private businesses', false, '915e3acb-25e5-45d0-97d8-18b56372c9c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e40abe7e-69f4-4680-8137-4f24f82d4178', 'The building of new missile bases', false, '915e3acb-25e5-45d0-97d8-18b56372c9c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a354b454-7974-4016-8e0b-ef922d3450b3', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Which international treaty signed in 1992 created the European Union (EU) and laid the groundwork for the single European currency (the Euro)?', 'The Maastricht Treaty (1992) established the European Union, European citizenship, and the Economic and Monetary Union (Eurozone).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ef55299-9572-44a7-8b33-404a84791cfd', 'The Maastricht Treaty', true, 'a354b454-7974-4016-8e0b-ef922d3450b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('befbec67-2a0e-4546-a83e-626cb018656c', 'The Treaty of Rome', false, 'a354b454-7974-4016-8e0b-ef922d3450b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4fa6e90-92da-4cd3-946a-343a023f7d79', 'The Schengen Agreement', false, 'a354b454-7974-4016-8e0b-ef922d3450b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e582d7c-b759-43ff-b36c-c4e75e815993', 'The Lisbon Treaty', false, 'a354b454-7974-4016-8e0b-ef922d3450b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('807beb30-534f-4126-ac79-d2b2ef0f3d1f', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a45896ef-8103-488d-9847-67b0f94bd535', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '807beb30-534f-4126-ac79-d2b2ef0f3d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30274e1f-97ec-4bbf-80d0-86da606f628f', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '807beb30-534f-4126-ac79-d2b2ef0f3d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8be96247-b169-4190-a663-8ec04553d905', '(A) is true, but (R) is false.', false, '807beb30-534f-4126-ac79-d2b2ef0f3d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58e00200-b771-4674-8592-5dce47a924e9', '(A) is false, but (R) is true.', false, '807beb30-534f-4126-ac79-d2b2ef0f3d1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78e888de-3817-4af4-afea-a1cd4b9c4cd6', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Spot the IMPOSTER in the following major World Revolutions and their defining historical milestones:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f42ee88d-8f91-4f91-aa08-3b2de731b188', 'Revolution 1', false, '78e888de-3817-4af4-afea-a1cd4b9c4cd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4c324c9-b67c-4bca-92f3-a081e4760278', 'Revolution 2', false, '78e888de-3817-4af4-afea-a1cd4b9c4cd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9d413da-dde2-4a8c-8aaa-d03b06904681', 'Revolution 3', false, '78e888de-3817-4af4-afea-a1cd4b9c4cd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4daf6b2c-4e7b-4d0d-afb6-5b87dddd51f4', 'Revolution 4 (The First Industrial Revolution involved steam engines, mechanized spinning jenny, and ironworks, NOT 21st-century smartphones)', true, '78e888de-3817-4af4-afea-a1cd4b9c4cd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4281bfd-4f05-419f-b276-19e8954f5423', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Analyze the geopolitical mechanism of the ''Cold War'' (1947–1991):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3d205a3-054d-4d7d-ad8f-73b99ab72294', 'The two nuclear-armed superpowers (USA and USSR) never engaged in direct direct military combat against each other due to Mutually Assured Destruction (MAD), fighting instead through ideological rivalry, proxy wars (Korea, Vietnam), the nuclear arms race, and the Space Race', true, 'c4281bfd-4f05-419f-b276-19e8954f5423');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf5b6a3f-bfb4-4627-b694-3fd2b3d57446', 'Because all battles were fought in freezing Siberia', false, 'c4281bfd-4f05-419f-b276-19e8954f5423');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83b9a9ef-0c54-4155-b387-692b1c767d58', 'Because both countries banned the use of gunpowder', false, 'c4281bfd-4f05-419f-b276-19e8954f5423');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a141a736-a7e2-4555-9ece-ae1dcb921a8f', 'Because wars were fought only in winter months', false, 'c4281bfd-4f05-419f-b276-19e8954f5423');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e45ad7d-ec1e-4d00-9a75-21844a867c05', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Match Column I (Historic Global Summits / Treaties) with Column II (Defining Historical Milestones):
(a) Treaty of Westphalia (1648) -> (i) Established modern nation-state sovereignty and diplomatic immunity
(b) Congress of Vienna (1815)     -> (ii) Restored European balance of power after the fall of Napoleon
(c) Yalta Conference (1945)      -> (iii) Churchill, Roosevelt, and Stalin planned the post-WWII division of Europe
(d) Geneva Conventions (1949)    -> (iv) Codified international humanitarian laws of war and prisoner protection', 'Westphalia = state sovereignty; Vienna = post-Napoleonic balance; Yalta = post-WWII spheres; Geneva = laws of war.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dc34d58-c340-4874-b670-349fba890769', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '3e45ad7d-ec1e-4d00-9a75-21844a867c05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f89f059-11f4-41cc-92f6-49d75d2bd3bd', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '3e45ad7d-ec1e-4d00-9a75-21844a867c05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ea619dc-76aa-485e-b8d1-15828714f531', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '3e45ad7d-ec1e-4d00-9a75-21844a867c05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6924c08f-0542-4b7d-ad1d-8312b37da1d7', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '3e45ad7d-ec1e-4d00-9a75-21844a867c05');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56f7bf20-a8c9-494e-8f33-31c07cb2f2bd', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Read the statements regarding the Decolonization era (1945–1975):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('686c34cc-3a4e-4ee3-b080-09a77ebf8f73', 'Statements 1 and 2 only', true, '56f7bf20-a8c9-494e-8f33-31c07cb2f2bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddad9e1d-c6f0-4fad-957b-65d6e2b440e7', 'Statements 2 and 3 only', false, '56f7bf20-a8c9-494e-8f33-31c07cb2f2bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e90bcbf0-518a-47e7-b9cf-1bab75863207', 'Statements 1 and 3 only', false, '56f7bf20-a8c9-494e-8f33-31c07cb2f2bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2ba2917-024e-49d2-8519-53ceab7fa831', 'All Statements 1, 2, and 3', false, '56f7bf20-a8c9-494e-8f33-31c07cb2f2bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c775fd7-b7cf-4a96-a5d4-4dc407d45f72', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What was the significance of the ''Nuremberg Trials'' (1945–1946) conducted after World War II?', 'Nuremberg established modern international criminal law: leaders cannot claim sovereign immunity or ''following orders'' for crimes against humanity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bc267d3-83bf-493a-b33e-3a1644f7dafa', 'The historic international military tribunal that prosecuted top Nazi leaders for ''Crimes Against Peace'', ''War Crimes'', and ''Crimes Against Humanity'', establishing individual legal accountability under international law', true, '9c775fd7-b7cf-4a96-a5d4-4dc407d45f72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc2fe735-174b-4bca-9394-aba243b09210', 'A conference to set world oil prices', false, '9c775fd7-b7cf-4a96-a5d4-4dc407d45f72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2ae7ab5-0699-4036-ab31-cf5005294484', 'The division of Berlin into zones', false, '9c775fd7-b7cf-4a96-a5d4-4dc407d45f72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c228e98c-6bad-4ece-8566-6f44719e3928', 'The creation of the Euro currency', false, '9c775fd7-b7cf-4a96-a5d4-4dc407d45f72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8172ece5-613f-41d8-bc8a-e4e7cce87741', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What was the ''Space Race'' between the USA and the USSR during the Cold War?', 'The Space Race showcased ideological and technological superiority: Soviet orbital triumphs balanced by Apollo 11''s historic lunar landing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('969b6f55-d10d-4fa5-9064-e573b96adaa4', 'A high-stakes scientific-technological competition for space dominance: USSR launched the first satellite (Sputnik, 1957) and first human in space (Yuri Gagarin, 1961) ; USA achieved the first manned Moon landing (Apollo 11, Neil Armstrong, 1969)', true, '8172ece5-613f-41d8-bc8a-e4e7cce87741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6f747dc-bd21-40c1-9d3a-e168152f9566', 'A military battle fought with space laser weapons on Mars', false, '8172ece5-613f-41d8-bc8a-e4e7cce87741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27c5e8c4-1420-4400-97ae-0fb23c7af3ca', 'A race to build the tallest skyscraper', false, '8172ece5-613f-41d8-bc8a-e4e7cce87741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d53684ca-ab24-4237-9780-9b2498e68f90', 'A telescope building competition', false, '8172ece5-613f-41d8-bc8a-e4e7cce87741');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b918970f-ac0e-4ad4-9538-997f6bb134d6', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Consider four major global economic and geopolitical institutions established at the 1944 Bretton Woods Conference:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('704fc038-1d47-4d70-96da-0e08ac7d5303', 'To prevent global depressions through stable international exchange rates, finance post-war reconstruction, and foster open multilateral international trade', true, 'b918970f-ac0e-4ad4-9538-997f6bb134d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5c003b3-a96f-4c92-92ee-3375c111d542', 'To enforce military occupation over poor nations', false, 'b918970f-ac0e-4ad4-9538-997f6bb134d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('248a1be7-f9a5-4d1c-9072-29bbe36c7f37', 'To abolish all paper money worldwide', false, 'b918970f-ac0e-4ad4-9538-997f6bb134d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ff88802-3e1e-40f6-b7f1-f836b3881d4a', 'To print a single world newspaper', false, 'b918970f-ac0e-4ad4-9538-997f6bb134d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('104c5f1e-ac66-48b5-9a97-8effce1dcd41', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Why was the ''Suez Crisis'' (1956) a watershed moment in the decline of British and French imperial dominance?', 'The 1956 Suez debacle revealed that old European colonial powers could no longer exercise independent global military force without US consent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a85757e-9d86-4998-8908-a07af5f240cb', 'When Britain, France, and Israel invaded Egypt after President Nasser nationalized the Suez Canal, diplomatic condemnation and economic pressure from both the US and USSR forced a humiliating Anglo-French withdrawal, cementing the end of European imperial hegemony', true, '104c5f1e-ac66-48b5-9a97-8effce1dcd41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be1c83e9-1e79-419d-9651-d11e4601c6a4', 'Because Egypt conquered all of Europe', false, '104c5f1e-ac66-48b5-9a97-8effce1dcd41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7588df11-daf3-46b2-bd72-816a36ba9119', 'Because the canal was filled with concrete', false, '104c5f1e-ac66-48b5-9a97-8effce1dcd41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aabb15ac-bbf1-47f6-a3ea-20b13c4b70cc', 'Because Britain annexed Egypt permanently', false, '104c5f1e-ac66-48b5-9a97-8effce1dcd41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ece3c1f3-5b78-4e4e-a2e4-abbb84da82e5', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What is the historical significance of the ''Universal Declaration of Human Rights'' (UDHR) adopted by the UN General Assembly on December 10, 1948?', 'Adopted in Paris (10 Dec 1948, Human Rights Day), the 30 articles of the UDHR enshrine inalienable civil, political, economic, and social rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d25086-b296-4025-bc86-2ce44bf29e69', 'The first global proclamation of fundamental human rights to be universally protected for all human beings everywhere, authored by a diverse committee chaired by Eleanor Roosevelt', true, 'ece3c1f3-5b78-4e4e-a2e4-abbb84da82e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('171100d2-7108-4e10-bdc5-60ca3d82a207', 'A treaty that ended the Korean war', false, 'ece3c1f3-5b78-4e4e-a2e4-abbb84da82e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09101ce0-0d88-40e0-97b0-329ec33b1182', 'A law allowing countries to buy nuclear weapons', false, 'ece3c1f3-5b78-4e4e-a2e4-abbb84da82e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20ca6f25-7a54-47c4-a3e6-48e996fbbd6f', 'A rule on maritime fishing quotas', false, 'ece3c1f3-5b78-4e4e-a2e4-abbb84da82e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2841ac6-485d-4622-bc43-976fb3e8d12c', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What historic transformation occurred in South Africa with the 1994 General Election?', 'The 1994 election birthed the multiracial ''Rainbow Nation'', inaugurating a democratic constitutional state underpinned by truth and reconciliation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99c585b9-4bb1-4852-b0cc-b2f9f58ef771', 'The peaceful end of four decades of institutionalized white-minority Apartheid, and the election of Nelson Mandela as President in the country''s first fully representative multiracial democratic election', true, 'b2841ac6-485d-4622-bc43-976fb3e8d12c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc7ea87b-497b-47f2-b07b-abd9edf0fdeb', 'The partition of South Africa into four countries', false, 'b2841ac6-485d-4622-bc43-976fb3e8d12c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08ea3e06-3be1-4834-b9ef-d199ab86d656', 'The coronation of a new British monarch', false, 'b2841ac6-485d-4622-bc43-976fb3e8d12c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc95b4d5-36d9-44f5-8ae7-51ea4f897194', 'The expulsion of all foreign diplomats', false, 'b2841ac6-485d-4622-bc43-976fb3e8d12c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4caf474-c4af-4215-baed-da0565dbf647', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What overarching historical lesson is illuminated in Chapter 9 of General Knowledge?', 'Chapter 9 synthesizes modern revolutions, the trauma of total wars, the Cold War balance of power, decolonization, and the quest for universal human rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76591d2b-feef-4bbc-9ec1-90d9cb535f94', 'Modern world history is a dynamic chronicle of humanity''s unrelenting struggle for liberty, equality, scientific modernization, and international legal institutions to replace imperial domination and catastrophic wars with peaceful global multilateral cooperation', true, 'd4caf474-c4af-4215-baed-da0565dbf647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c134d39-6571-4419-bb99-ead6bfcb5c22', 'That wars are always inevitable and peace is impossible', false, 'd4caf474-c4af-4215-baed-da0565dbf647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('376cf460-9403-4132-bcd2-5cd48a7f6682', 'That only monarchs should rule the world', false, 'd4caf474-c4af-4215-baed-da0565dbf647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('939995b5-8078-4a0a-af67-0b18ea732ecd', 'That technology has never changed human society', false, 'd4caf474-c4af-4215-baed-da0565dbf647');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e0ae5f0-d467-49ad-8c84-df01995c7416', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which 9th-century kingdom established in southwestern India (modern Kerala) introduced the MALAYALAM language and script in its official royal inscriptions?', 'The Chera kingdom of Mahodayapuram (est. 9th century) was one of the earliest examples of an Indian regional kingdom using a vernacular language (Malayalam) in official administrative records.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1cd88ac-ff32-4fde-b1a8-5c1979edb233', 'The Chera Kingdom of Mahodayapuram', true, '5e0ae5f0-d467-49ad-8c84-df01995c7416');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45df4cde-2db4-40ca-802a-f760af480c0d', 'The Chola Kingdom', false, '5e0ae5f0-d467-49ad-8c84-df01995c7416');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8b5855b-f82d-48be-b7e2-1d95d1b8cbbe', 'The Pandya Kingdom', false, '5e0ae5f0-d467-49ad-8c84-df01995c7416');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fd67f4f-7cdc-41c1-8253-7950de721329', 'The Rashtrakuta Kingdom', false, '5e0ae5f0-d467-49ad-8c84-df01995c7416');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('281ac0f8-33bf-482e-b329-e57eee1a459a', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'What is the 14th-century Sanskrit-Malayalam literary style called ''Manipravalam'' (literally meaning ''Diamonds and Corals'')?', 'Manipravalam (literally ''diamonds and corals'') combined Sanskrit and regional Malayalam, celebrated in the 14th-century text Lilathilakam.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('736593a9-ae65-4a3c-b4e1-9a9676be0f2d', 'A rich blend of two languages: Sanskrit and the regional Malayalam language in literary compositions', true, '281ac0f8-33bf-482e-b329-e57eee1a459a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94fe4251-4356-457a-8691-f00c3a1cd018', 'A technique for cutting jewelry', false, '281ac0f8-33bf-482e-b329-e57eee1a459a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4628c11-3b41-4566-9e2d-c881b578338e', 'A style of temple architecture', false, '281ac0f8-33bf-482e-b329-e57eee1a459a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e725d66a-e1a4-4e65-bbd7-fc5269b156f6', 'A type of silk saree', false, '281ac0f8-33bf-482e-b329-e57eee1a459a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90ff89e1-0027-4315-8100-09a60e4bde94', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which famous temple cult in Puri (Odisha) became the supreme centre of regional and religious identity, where the wooden deity was originally made by local tribal people and later identified with Lord Vishnu?', 'Lord Jagannath (Lord of the World) at Puri evolved from an indigenous tribal wooden deity into a pan-Indian manifestation of Vishnu/Krishna.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a1b0247-f947-4e47-a571-8419695a1889', 'The Jagannath Cult at Puri', true, '90ff89e1-0027-4315-8100-09a60e4bde94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71e410da-a0c9-4065-b8e1-4461717d89da', 'The Meenakshi Cult', false, '90ff89e1-0027-4315-8100-09a60e4bde94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f57e34a-eb54-4a7b-9058-1de3102289ae', 'The Lingaraja Cult', false, '90ff89e1-0027-4315-8100-09a60e4bde94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a0aad95-5c9b-4ec0-b50c-f22c749a5665', 'The Kamakhya Cult', false, '90ff89e1-0027-4315-8100-09a60e4bde94');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75560e24-7c24-4420-bb9b-437f4a45d2ab', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which 12th-century king of the Eastern Ganga dynasty decided to erect a magnificent temple for Purushottama Jagannath at Puri?', 'King Anantavarman of the Eastern Ganga dynasty initiated the construction of the monumental Puri Jagannath Temple in the 12th century.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1230d60-8dbc-4f39-b929-84a3f7c1eb2f', 'King Anantavarman', true, '75560e24-7c24-4420-bb9b-437f4a45d2ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fd24c29-3262-41fa-87f9-40af98e61420', 'King Anangabhima III', false, '75560e24-7c24-4420-bb9b-437f4a45d2ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b39f1197-e72c-4af9-9fee-ed0c52f67fe6', 'King Kharavela', false, '75560e24-7c24-4420-bb9b-437f4a45d2ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bd6065b-f5ac-4073-9201-8996464afc3d', 'King Rajaraja I', false, '75560e24-7c24-4420-bb9b-437f4a45d2ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc219402-937f-4b24-b29d-776be93091e8', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which king in 1230 CE dedicated his entire kingdom to Lord Jagannath and proclaimed himself as the ''Deputy'' (Rauta) of the god?', 'King Anangabhima III dedicated his realm to Lord Jagannath, governing the Odishan state as the earthly servant/deputy of the deity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d64db92d-1b14-4dcf-9a3f-aeed18c57143', 'King Anangabhima III', true, 'dc219402-937f-4b24-b29d-776be93091e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52c0259a-af08-4345-bd53-17925e1b670d', 'King Prataparudra', false, 'dc219402-937f-4b24-b29d-776be93091e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2335a43c-ddc8-4818-8817-9a7e12add311', 'King Narasimhadeva I', false, 'dc219402-937f-4b24-b29d-776be93091e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfaf71e-9872-4a7f-ba91-1ef9ed940e9c', 'King Kapilendra Deva', false, 'dc219402-937f-4b24-b29d-776be93091e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e5f19cd-1e5c-408e-b967-4adb90b9b0e9', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which classical dance form of North India originated from a caste of temple storytellers (''Kathakars'') who illustrated mythological stories with gestures and songs?', 'Kathak evolved from North Indian temple bardic storytellers (katha-kars) performing dramatic gestures to narrate sacred epics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dd862e5-34c3-4fb1-bbd1-cf5af1a4448c', 'Kathak', true, '2e5f19cd-1e5c-408e-b967-4adb90b9b0e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1331d039-4fa2-4ffd-9b9a-bb77e46dddaf', 'Bharatanatyam', false, '2e5f19cd-1e5c-408e-b967-4adb90b9b0e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('206e6a60-7c9a-4c7b-b812-31f332c031d3', 'Kathakali', false, '2e5f19cd-1e5c-408e-b967-4adb90b9b0e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e54d262b-a0a3-41a4-9948-a742eb2e2830', 'Odissi', false, '2e5f19cd-1e5c-408e-b967-4adb90b9b0e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79f1b34f-c4fc-4aba-ad7c-2c10cb766008', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Under which Nawab of Awadh (1847–1856) did the Lucknow Gharana of KATHAK dance reach its golden age of artistic refinement?', 'Nawab Wajid Ali Shah was a passionate patron and maestro of Kathak, Thumri, and dramatic dance-dramas (Rahas) in Lucknow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d27acbec-f378-4dc3-a181-fd58ed27231c', 'Nawab Wajid Ali Shah', true, '79f1b34f-c4fc-4aba-ad7c-2c10cb766008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5bc7714-6a07-41b7-8cb2-6dd0c91294e4', 'Nawab Asaf-ud-Daula', false, '79f1b34f-c4fc-4aba-ad7c-2c10cb766008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57ffa924-381f-4cb4-89a4-570afa3ba5e2', 'Nawab Saadat Ali Khan', false, '79f1b34f-c4fc-4aba-ad7c-2c10cb766008');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa1ecdbd-a997-4cde-aec3-05d3ed4b9ec2', 'Nawab Shuja-ud-Daula', false, '79f1b34f-c4fc-4aba-ad7c-2c10cb766008');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d54f0002-a10f-4508-81db-d6a65a639402', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'What are the two major traditional court ''Gharanas'' (schools/traditions) of KATHAK dance?', 'Kathak branched into the rhythmic, energetic Jaipur Gharana and the lyrical, expressive Lucknow and Banaras Gharanas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea80aee6-19cb-4cea-8a1e-cca525a7a0d9', 'The Jaipur Gharana and the Lucknow Gharana (along with Banaras)', true, 'd54f0002-a10f-4508-81db-d6a65a639402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0611797-daf6-4fb2-8aea-78cb2b26ba40', 'The Delhi and Agra Gharana', false, 'd54f0002-a10f-4508-81db-d6a65a639402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dc1abe0-6cee-45bf-8933-e9f4ff1f640c', 'The Gwalior and Patiala Gharana', false, 'd54f0002-a10f-4508-81db-d6a65a639402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d92fc56-10de-4528-8eab-7f3c7b7041fc', 'The Tanjore and Mysore Gharana', false, 'd54f0002-a10f-4508-81db-d6a65a639402');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('402318dc-a185-4f8d-99bf-ac9c8cb17def', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'What are small-sized paintings executed in watercolours on cloth or handmade paper, known for intricate fine detailing, called?', 'Miniatures are delicate, small-scale paintings rendered with natural mineral/vegetable pigments and fine squirrel-hair brushes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3999bde-d4e6-4302-b174-635d4d0943e8', 'Miniature Paintings (Miniatures)', true, '402318dc-a185-4f8d-99bf-ac9c8cb17def');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1326a860-2e5a-4be3-9f11-f74d27ac9812', 'Fresco Murals', false, '402318dc-a185-4f8d-99bf-ac9c8cb17def');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42e47d50-97e0-4e8c-b8e3-1ddb61708061', 'Oil Canvas', false, '402318dc-a185-4f8d-99bf-ac9c8cb17def');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('451878f9-ebe5-4509-badd-a06ab54be21a', 'Cave Paintings', false, '402318dc-a185-4f8d-99bf-ac9c8cb17def');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03753dca-ac38-4a1c-bfc5-21fd86793614', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which bold, intense regional style of miniature painting developed in the Himalayan foothills (Basohli in modern Jammu and Kashmir), famous for illustrating Bhanudatta''s ''Rasamanjari''?', 'Basohli painting is renowned for bold, vibrant primary colors, passionate facial profiles, and expressive depictions of the Rasamanjari.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b84efd9e-00c9-4776-a7f9-09c17913a213', 'Basohli Style of Painting', true, '03753dca-ac38-4a1c-bfc5-21fd86793614');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab320cec-40c6-4930-91c8-24e30de5da41', 'Kangra School', false, '03753dca-ac38-4a1c-bfc5-21fd86793614');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f07ae41b-d11e-4a49-ac76-36da38ffeda6', 'Mewar School', false, '03753dca-ac38-4a1c-bfc5-21fd86793614');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4736871-0bfe-49d0-9cbc-469939b8e7f4', 'Kishangarh School', false, '03753dca-ac38-4a1c-bfc5-21fd86793614');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c61d7f08-0b09-4788-82d5-f25d93b06205', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which lyrical Pahari miniature painting school developed in the Kangra valley of Himachal Pradesh by the mid-18th century, inspired by Vaishnavite traditions with soft colors and poetic treatment of Radha-Krishna?', 'The Kangra school under Raja Sansar Chand is celebrated for lyrical delicacy, rhythmic lines, and cool soft greens and blues portraying Krishna-bhakti.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b52fbc66-5b07-4949-bd7d-460597973f3c', 'The Kangra School of Painting', true, 'c61d7f08-0b09-4788-82d5-f25d93b06205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0edc15cb-459a-4d55-bfa7-26b3fa8a3e34', 'The Mughal School', false, 'c61d7f08-0b09-4788-82d5-f25d93b06205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dbe2f4d-c383-4fe4-bccb-e9644fe16307', 'The Tanjore School', false, 'c61d7f08-0b09-4788-82d5-f25d93b06205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a638c13-9736-4880-9ad1-05f2852c1003', 'The Madhubani School', false, 'c61d7f08-0b09-4788-82d5-f25d93b06205');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e2651c9-3581-4d5b-8fc8-c40ba4edd185', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'From which ancient primary language did the BENGALI language evolve over centuries, absorbing words from Persian, Austro-Asiatic, and European languages?', 'Bengali derived from Sanskrit through Magadhi Prakrit, later enriching its lexicon with Persian, Arabic, Austric, and Portuguese loanwords.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dd9130e-c245-4617-ac19-65b4b4aa1981', 'Sanskrit (via Magadhi Prakrit)', true, '5e2651c9-3581-4d5b-8fc8-c40ba4edd185');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96753f3b-ac45-4357-8ca4-96d911dd1fd6', 'Tamil', false, '5e2651c9-3581-4d5b-8fc8-c40ba4edd185');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d532f0c-db38-4b5e-ac90-16a6de8ccbb8', 'Arabic', false, '5e2651c9-3581-4d5b-8fc8-c40ba4edd185');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb341cf1-e8d4-4981-88fc-2ee5226bebf8', 'Greek', false, '5e2651c9-3581-4d5b-8fc8-c40ba4edd185');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3582f8a8-755e-4de9-9a5a-7f1521547fb3', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What is the 14th-century grammatical and poetic treatise ''Lilathilakam'' famous for?', 'The Lilathilakam is a 14th-century linguistic masterpiece codifying the syntax, meter, and aesthetics of Manipravalam.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d19845f7-aa51-4d9b-8790-adb145b9cc03', 'It is the earliest extant text composed in Manipravalam, dealing with the grammar and poetics of the joint Malayalam-Sanskrit literary tradition', true, '3582f8a8-755e-4de9-9a5a-7f1521547fb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8271079-2e45-4271-b7f7-ac4cce4f54ac', 'It is a cookbook for royal feasts', false, '3582f8a8-755e-4de9-9a5a-7f1521547fb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6593f455-6710-46df-a445-d0ad0c403640', 'It is a manual of sword fighting', false, '3582f8a8-755e-4de9-9a5a-7f1521547fb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('311ed59a-da01-4124-b34c-c8f9c119abfb', 'It is a maritime trade law book', false, '3582f8a8-755e-4de9-9a5a-7f1521547fb3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e65d5051-9aa7-4a1c-8c0b-a0e428248181', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Why did successive conquerors of Odisha (Mughals, Marathas, English East India Company) all attempt to establish control over the Jagannath Temple at Puri?', 'Puri Jagannath Temple was the sanctum of regional sovereignty; political legitimacy in Odisha was inextricably linked to temple patronage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fd280bb-dfaa-460a-88f6-f6ecc292ffca', 'They realized that the Puri temple held supreme socio-cultural and political legitimacy among the local Odia people; controlling the temple made their rule acceptable to the local population', true, 'e65d5051-9aa7-4a1c-8c0b-a0e428248181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f718386-7300-48b1-bef4-1a0a21e80a5b', 'Because the temple contained only gold cannons', false, 'e65d5051-9aa7-4a1c-8c0b-a0e428248181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34dfd311-c5f6-45ce-8b7b-c1652a8591d3', 'Because they wanted to destroy the temple completely', false, 'e65d5051-9aa7-4a1c-8c0b-a0e428248181');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('157ed836-7e48-4b43-9c5f-d1d6aed878c7', 'Because the temple was a military fort', false, 'e65d5051-9aa7-4a1c-8c0b-a0e428248181');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6184b91e-0921-4d82-a545-06309f8851c7', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'How did Rajput heroic ideals, preserved in bardic poems and songs in Rajasthan, shape regional identity?', 'Charans and Bhats preserved epic bardic songs immortalizing Rajput chivalric codes, battlefield valor, and heroic self-sacrifice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0862cc47-d533-4d06-88ef-4419385973cd', 'They celebrated heroic martial valor, undying loyalty to clan and friendship, fearlessness in battle, choosing death over dishonor, and the tragic practice of Sati / Jauhar', true, '6184b91e-0921-4d82-a545-06309f8851c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c771ec0a-201d-47c8-95cf-a5660d94f7fa', 'They taught merchants how to trade silk', false, '6184b91e-0921-4d82-a545-06309f8851c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ca03928-3f87-484a-920f-ba4c18d1c13b', 'They banned all weapons in Rajasthan', false, '6184b91e-0921-4d82-a545-06309f8851c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('712b8459-7235-429b-823c-bea950c6bf31', 'They encouraged soldiers to flee from battles', false, '6184b91e-0921-4d82-a545-06309f8851c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0d071f2-c922-45b2-b3da-622f8a76eedc', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'How did the transition of Kathak from temple performance into Mughal court entertainment transform the dance form?', 'Mughal and Awadh royal courts refined Kathak: fusing devotional bhakti narratives with complex rhythmic footwork and virtuosic spins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed0e16b1-d3e0-44e8-81ea-26c7a294f256', 'It acquired its distinctive rapid, intricate footwork (Tatkar), dizzying pirouettes (Chakkars), elegant court costumes, and dramatic enactments of Radha-Krishna love stories (Rahas)', true, 'f0d071f2-c922-45b2-b3da-622f8a76eedc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bc1d3af-45ad-47fb-92ae-98877f4a0780', 'It became a silent meditation without music', false, 'f0d071f2-c922-45b2-b3da-622f8a76eedc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14cf9315-d747-4ee6-862d-708a0978456a', 'It was banned by all emperors', false, 'f0d071f2-c922-45b2-b3da-622f8a76eedc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6cfe09b-b10e-4cf6-b4d3-214f959e8253', 'It was performed only underwater', false, 'f0d071f2-c922-45b2-b3da-622f8a76eedc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bec37f0c-d0e1-4165-8f09-115a54539e42', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What are the traditional thatched-roof architectural styles that inspired the famous medieval Brick and Terracotta Temples of Bengal?', 'Bengal temple architecture mimicked vernacular curved bamboo thatch roofs: Dochala (double-curved) and Chauchala (four-roofed pyramid).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a41ae3b7-4f59-4d72-a838-461ec7a4b2e5', 'The ''Dochala'' (two-roofed curved bamboo hut structure) and the ''Chauchala'' (four-roofed structure with four triangular roofs meeting at a curved point)', true, 'bec37f0c-d0e1-4165-8f09-115a54539e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2999380b-d792-4cbc-a253-14a539d00341', 'The Gopuram and Mandapa style', false, 'bec37f0c-d0e1-4165-8f09-115a54539e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b79886c8-5b5a-4da7-90b8-c930d5de30b2', 'The Pagoda style', false, 'bec37f0c-d0e1-4165-8f09-115a54539e42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b113d4aa-173e-4886-b5cd-5c4a17f196a4', 'The Greek column style', false, 'bec37f0c-d0e1-4165-8f09-115a54539e42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('784b30ea-520d-44ef-a73a-8c3e0c69bfc8', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Which historic town in Bankura district of West Bengal is world-famous for its magnificent 17th- and 18th-century Terracotta Temples built by Malla kings (like Shyam Rai and Jore Bangla)?', 'Bishnupur under the Malla dynasty flourished as a terracotta architectural capital, featuring intricately carved clay tile temples.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02dd0c6e-33c6-48a1-b805-c049c5ede195', 'Bishnupur (Malla Kingdom)', true, '784b30ea-520d-44ef-a73a-8c3e0c69bfc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e533b7fe-ea2d-4582-a2c1-37f88c9aab40', 'Darjeeling', false, '784b30ea-520d-44ef-a73a-8c3e0c69bfc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e771c56a-5ea5-40f0-9cc4-a13118e64954', 'Murshidabad', false, '784b30ea-520d-44ef-a73a-8c3e0c69bfc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31d055c4-3d73-4870-8c04-2e2938c3b093', 'Chittagong', false, '784b30ea-520d-44ef-a73a-8c3e0c69bfc8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e795191f-6e90-423b-8f82-ec62dedb8715', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What are the two distinct major categories of early Bengali literature?', 'Early Bengali literature comprised elite Sanskritized written works (Mangalkavyas, Vaishnava padavali) and popular oral Nath folklore.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23c0b585-b90e-40ef-acef-642f46fdf08b', '1. Sanskrit-derived literature (translations of Epics, Mangalkavyas, Chaitanya biographies) ; and 2. Independent vernacular Nath literature (songs of Maynamati and Gopichand, fairy tales of Thakurmar Jhuli, Pir tales)', true, 'e795191f-6e90-423b-8f82-ec62dedb8715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a04641b0-6df9-4c78-a4f3-d9818eca433b', 'Persian war novels and Greek dramas', false, 'e795191f-6e90-423b-8f82-ec62dedb8715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baccce02-b650-4f3e-90fd-f649237718f2', 'Modern newspaper articles', false, 'e795191f-6e90-423b-8f82-ec62dedb8715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('605e06e7-a628-4e6d-b810-16c72f0a3d03', 'English legal documents', false, 'e795191f-6e90-423b-8f82-ec62dedb8715');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c434f33e-291c-4989-8e2d-a6068b1385d0', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Who were the ''Pirs'' in medieval Bengal, revered across religious boundaries by both Hindus and Muslims?', 'Pirs were charismatic frontier leaders, spiritual masters, and land colonizers in the Bengal delta, worshipped at shrines by all faiths.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('296767ff-0fcd-45b7-946d-76824c7958c7', 'Community leaders, spiritual guides, Sufi saints, and pioneer forest settlers who cleared dense delta mangroves, brought order, and were believed to possess supernatural powers', true, 'c434f33e-291c-4989-8e2d-a6068b1385d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aad2dbd-f008-4c2f-880b-02db0c2f7f79', 'Tax collectors who arrested villagers', false, 'c434f33e-291c-4989-8e2d-a6068b1385d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('498cdca2-98be-4efe-97e9-82b6c51d6e22', 'Foreign silk merchants', false, 'c434f33e-291c-4989-8e2d-a6068b1385d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb97b547-6d3c-4a1c-a1a0-a4f0058d94fd', 'Military captains of war fleets', false, 'c434f33e-291c-4989-8e2d-a6068b1385d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ccc2752b-3883-4f6a-ab39-3558e13c9413', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Which Mughal Emperor was a passionate patron of miniature painting who maintained grand royal imperial ateliers (Karkhanas) where master painters illustrated the Akbarnama?', 'Akbar and Jahangir patronized master miniature painters (Basawan, Daswant, Mansur, Abul Hasan), creating the celebrated Mughal imperial atelier.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e092cb22-8904-459b-9007-c5b783afccc9', 'Emperor Akbar (and Jahangir)', true, 'ccc2752b-3883-4f6a-ab39-3558e13c9413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c1dd19f-d779-4af3-8874-0b2f029f1465', 'Emperor Aurangzeb', false, 'ccc2752b-3883-4f6a-ab39-3558e13c9413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35c4762f-576c-487b-b27b-5a23837d56d0', 'Emperor Babur', false, 'ccc2752b-3883-4f6a-ab39-3558e13c9413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7af26a11-1098-4550-89df-b844afbfb973', 'Emperor Bahadur Shah I', false, 'ccc2752b-3883-4f6a-ab39-3558e13c9413');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02c0b7e4-ddbc-4857-b238-34f605285b7a', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Why did master painters migrate away from Delhi to regional Rajput and Himalayan hill states (Pahari courts) in the early 18th century?', 'Mughal political fragmentation and Nadir Shah''s sack of Delhi triggered an artistic diaspora to Kangra, Basohli, Guler, and Rajasthan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4828ee86-6ffb-492f-a6e1-329cd5274eb7', 'The political decline and instability of the Mughal capital under Nadir Shah''s invasion (1739) and Aurangzeb''s disinterest in court arts prompted painters to seek patronage in flourishing regional courts', true, '02c0b7e4-ddbc-4857-b238-34f605285b7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfe1b098-e795-4a66-a0ea-223eaa6587f5', 'Because Delhi ran out of paint', false, '02c0b7e4-ddbc-4857-b238-34f605285b7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f50985b-16bd-4489-bdc3-f1b1c8d077e1', 'Because painters were banned from living in plains', false, '02c0b7e4-ddbc-4857-b238-34f605285b7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40fd47d9-82fe-4f13-a28b-c36bb4172f2b', 'Because the climate in Delhi became too hot', false, '02c0b7e4-ddbc-4857-b238-34f605285b7a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3dc7b902-c664-4805-96a9-95f28d62cf93', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What are the ''Mangalkavyas'' in medieval Bengali literature?', 'Mangalkavyas are auspicious verse epics recounting how local indigenous goddesses established their worship across rural Bengal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f78f5fc-7bba-4ccd-93e9-e90c8a2ecf84', 'Eulogistic narrative poems praising local regional deities (such as Chandi, Manasa, and Dharma Thakur), ensuring prosperity and auspiciousness for devotees', true, '3dc7b902-c664-4805-96a9-95f28d62cf93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a04ab0f-7537-4441-afb0-032ea49e4758', 'Books on mathematical calculations', false, '3dc7b902-c664-4805-96a9-95f28d62cf93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f9a480c-2a1f-48bf-9776-62abead2c8b8', 'War treaties signed with kings', false, '3dc7b902-c664-4805-96a9-95f28d62cf93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('183b23e4-b71b-4f6f-a283-ea4f8204eb90', 'Medical prescriptions for diseases', false, '3dc7b902-c664-4805-96a9-95f28d62cf93');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fce1273-f5be-4289-b5bb-93a14fbda9f6', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Why did traditional fish eating become widely accepted in Bengali Hindu culture, even among high-caste Brahmans?', 'The Brihaddharma Purana adapted scriptural law to deltaic ecology, canonizing fish consumption among Bengali Brahmans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56b52843-5b0f-4a70-ac89-88ad866d6bd2', 'In the riverine, flood-prone Bengal delta with thousands of rivers and ponds, rice and fish were the indispensable staples of life, leading the 13th-century Sanskrit text ''Brihaddharma Purana'' to explicitly permit local Brahmans to eat certain varieties of fish', true, '7fce1273-f5be-4289-b5bb-93a14fbda9f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5e3b778-efb0-4ad5-b818-6432e8e3058d', 'Because the Mughal emperor ordered everyone to eat fish', false, '7fce1273-f5be-4289-b5bb-93a14fbda9f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('097eb069-a93c-4b3a-b56c-9987cf715b05', 'Because vegetables did not exist in Bengal', false, '7fce1273-f5be-4289-b5bb-93a14fbda9f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81b9d688-459f-45ba-a82d-5b24f0f56196', 'Because fish was used as money', false, '7fce1273-f5be-4289-b5bb-93a14fbda9f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecb2dd4a-5f0c-4526-85b3-32db4daacff7', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What are the Eight Recognized Classical Dance Traditions of India recognized by the Sangeet Natak Akademi?', 'The 8 classical dance traditions codified by Sangeet Natak Akademi trace lineage to Bharata Muni''s ancient Natyashastra.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a41250f-232f-40df-b555-8804b27a9515', 'Bharatanatyam (TN), Kathakali (Kerala), Kathak (North India), Odissi (Odisha), Kuchipudi (AP), Mohiniyattam (Kerala), Manipuri (Manipur), and Sattriya (Assam)', true, 'ecb2dd4a-5f0c-4526-85b3-32db4daacff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42e819d1-5d2f-4989-bd7c-459f06b156d1', 'Bhangra, Garba, Giddha, Lavani, Bihu, Rouf, Dandiya, Chhau', false, 'ecb2dd4a-5f0c-4526-85b3-32db4daacff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b2bd53e-a18f-4fc7-bd6d-55544264b0aa', 'Salsa, Ballet, Tango, Tap, Hip-hop, Waltz, Breakdance, Flamenco', false, 'ecb2dd4a-5f0c-4526-85b3-32db4daacff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('922efcb0-1a2d-4b1f-b9d9-d39dd6d4a58a', 'Classical singing only without dance', false, 'ecb2dd4a-5f0c-4526-85b3-32db4daacff7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89e4d1b9-8b67-423d-a6f0-78ada8cc8d74', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Which legendary miniature painting masterwork created in Kishangarh (Rajasthan) by artist Nihal Chand is celebrated as the ''Mona Lisa of India''?', 'The Kishangarh miniature portrait of ''Bani Thani'' (courtesan-poet of Raja Sawant Singh) by Nihal Chand is famed for stylized serpentine grace.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea106383-3b06-4123-a4ee-850bb776c9ce', 'Bani Thani', true, '89e4d1b9-8b67-423d-a6f0-78ada8cc8d74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b553c5d3-f061-4dc7-ac0a-e5dae91d22f6', 'Rasamanjari', false, '89e4d1b9-8b67-423d-a6f0-78ada8cc8d74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c5b5e58-d84d-4410-8027-5765968c592e', 'Gita Govinda', false, '89e4d1b9-8b67-423d-a6f0-78ada8cc8d74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77e54553-762f-4223-b1d5-13020e12a0de', 'Padmavat', false, '89e4d1b9-8b67-423d-a6f0-78ada8cc8d74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('659f8a2d-8057-4830-9349-a4281359fe83', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What distinct literary genre was the ''Maynamati-Gopichand'' cycle of songs in eastern India?', 'The Maynamati-Gopichand songs celebrate Queen Maynamati guiding her son into Gorakhnathi yogic initiation to conquer mortality.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1146846b-4dac-424d-bf6a-42c038b9aa9a', 'Popular oral folk songs about Queen Maynamati and her son Prince Gopichand embracing the esoteric ascetic path of the Nathpanthi Yogis to attain immortality', true, '659f8a2d-8057-4830-9349-a4281359fe83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87899f19-6f7c-406b-ac5b-5e2241f46888', 'A story of a sea voyage to Africa', false, '659f8a2d-8057-4830-9349-a4281359fe83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb6fd55f-1865-4c54-9840-b444e807541d', 'A commercial trade ledger', false, '659f8a2d-8057-4830-9349-a4281359fe83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('705aba5b-1376-468e-871c-c0cc046d7f91', 'A military manual of archery', false, '659f8a2d-8057-4830-9349-a4281359fe83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fb7adaa-b329-45d5-afeb-0c93da9dff6c', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What was the ''Gita Govinda'' composed by Jayadeva in 12th-century Bengal and Odisha, which inspired countless miniature paintings across India?', 'Jayadeva''s Gita Govinda revolutionized devotional aesthetics, providing the thematic source for Pahari and Rajasthani miniatures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34eb9231-cc9e-412e-ae3c-8eafefd1e6eb', 'An exquisite Sanskrit lyrical poem celebrating the passionate, mystical love of Lord Krishna and Radha in the springtime groves of Vrindavan', true, '2fb7adaa-b329-45d5-afeb-0c93da9dff6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dea0add4-05e3-4ca6-9e20-fee976521ba0', 'A treatise on horse riding', false, '2fb7adaa-b329-45d5-afeb-0c93da9dff6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a034665-6bd3-4be1-b9bd-698f3df6fac6', 'A book on fort construction', false, '2fb7adaa-b329-45d5-afeb-0c93da9dff6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df537687-ef52-4030-a1ae-b837c1aaf229', 'A collection of tax laws', false, '2fb7adaa-b329-45d5-afeb-0c93da9dff6c');
