INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12ebdc7c-3ff1-4163-846e-1389dc3d881d', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'b84ae1a9-af16-4c67-b989-90b231c102e9');
