INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaf8e08a-0fc9-4b85-ab48-fab5d3449026', '(A) is true, but (R) is false.', false, 'b84ae1a9-af16-4c67-b989-90b231c102e9');
