INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d908b02-66d3-4120-9453-fbe5dd00af42', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'Spot the IMPOSTER in the following group of Indian Classical Dance Traditions and their corresponding States of Origin:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8381ec00-e0e1-4917-8c6a-592cafe9cecd', 'Tradition 1', false, '8d908b02-66d3-4120-9453-fbe5dd00af42');
