INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644a7b1d-41cc-4378-afd1-31a96cb4312a', 'Tradition 3', false, '8d908b02-66d3-4120-9453-fbe5dd00af42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2878b9e-a217-4d88-af83-7588f6445f9c', 'Tradition 4 (Kathak is the premier classical dance form of NORTH INDIA [Uttar Pradesh, Rajasthan, Delhi], not Antarctica)', true, '8d908b02-66d3-4120-9453-fbe5dd00af42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69b44e4a-b838-4634-93c8-edf3013957a0', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'Analyze the unique syncretic evolution of the ''Jagannath Cult'' at Puri:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6fcfe86-708d-4e29-aaf9-7526f3413527', 'The massive wooden icons of Jagannath, Balabhadra, and Subhadra are carved from sacred neem logs by traditional tribal Daitapati priests, reflecting an indigenous non-anthropomorphic tribal deity seamlessly synthesized into the Vaishnavite Puranic pantheon', true, '69b44e4a-b838-4634-93c8-edf3013957a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3370789-3fcf-436e-8437-82f446c3b3d8', 'The icons are made of European marble imported by ship', false, '69b44e4a-b838-4634-93c8-edf3013957a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b5eb853-9307-4898-8cb9-4c20efe134b4', 'The worship excludes all local tribal communities completely', false, '69b44e4a-b838-4634-93c8-edf3013957a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1d12643-3b7e-4580-8b0a-625685c84a21', 'The temple was originally a Mughal palace', false, '69b44e4a-b838-4634-93c8-edf3013957a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b487f94-52ca-4bd4-bc56-15fb10e9d216', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'Match Column I (Regional Cultural Forms / Texts) with Column II (Geographic & Linguistic Spheres):
(a) Manipravalam & Lilathilakam -> (i) Kerala (Chera / Sanskrit-Malayalam synthesis)
(b) Dochala & Chauchala Temples  -> (ii) Bengal (Vernacular terracotta brick architecture)
(c) Basohli & Kangra Painting    -> (iii) Pahari Region (Himachal Pradesh / Jammu foothills)
(d) Jaipur & Lucknow Gharanas    -> (iv) North India (Classical Kathak dance development)', 'Manipravalam = Kerala; Dochala = Bengal; Kangra = Pahari; Gharanas = Kathak.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8d758d3-2292-4599-a61d-dd482648f52f', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '4b487f94-52ca-4bd4-bc56-15fb10e9d216');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('972ae02f-e318-48fb-97e4-0ea384ecd405', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '4b487f94-52ca-4bd4-bc56-15fb10e9d216');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('540affd9-5cbf-4eed-98b1-e99e963aac81', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '4b487f94-52ca-4bd4-bc56-15fb10e9d216');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72cbdd4d-f3ca-4858-8be4-63b30a8a260a', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '4b487f94-52ca-4bd4-bc56-15fb10e9d216');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c39cc3d7-e922-4fb7-9c5f-1106702ce3fd', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'Read the statements regarding the development of the Bengali language:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4180e2f4-1b69-47f4-9e7e-4cf30048e260', 'Statements 1 and 2 only', true, 'c39cc3d7-e922-4fb7-9c5f-1106702ce3fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3f4dda7-22bc-43a8-971f-db215323ffde', 'Statements 2 and 3 only', false, 'c39cc3d7-e922-4fb7-9c5f-1106702ce3fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdb09374-25ac-4712-9d06-ff0dff54aff5', 'Statements 1 and 3 only', false, 'c39cc3d7-e922-4fb7-9c5f-1106702ce3fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68a61335-4784-4862-bb8a-e706fdb4e2f3', 'All Statements 1, 2, and 3', false, 'c39cc3d7-e922-4fb7-9c5f-1106702ce3fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d712d0d2-4fd4-4076-9f2c-e6f3d414ebf8', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'How did the British colonial perception of the ''Rajput'' identity in the 19th century flatten and romanticize the complex history of Rajasthan?', 'Colonial historiography essentialized Rajasthan as ''Rajputana'', eclipsing the vital agency of diverse non-Rajput subaltern and tribal communities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5bb4f31-88f6-41a9-a9b1-113f3971ad92', 'The British called the entire region ''Rajputana'' and propagated the myth that all inhabitants were uniform martial Rajputs, overlooking the immense diversity of merchants, peasants, artisans, and tribal Bhils who shaped Rajasthan''s composite culture', true, 'd712d0d2-4fd4-4076-9f2c-e6f3d414ebf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2984e26b-1664-4c15-aa0a-47edd11f32f9', 'They declared that no Rajputs existed in Rajasthan', false, 'd712d0d2-4fd4-4076-9f2c-e6f3d414ebf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50f7d568-5a7e-43dc-a798-05f368bda432', 'They claimed Rajasthan was an island in the ocean', false, 'd712d0d2-4fd4-4076-9f2c-e6f3d414ebf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20ff649d-f9d1-4e19-bb5a-d231e478cb38', 'They renamed all cities in Rajasthan after British generals', false, 'd712d0d2-4fd4-4076-9f2c-e6f3d414ebf8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e10b1955-3808-4e51-9167-40b034580c83', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'What technical mastery distinguished the ''Kangra Miniature Painting'' school from earlier Mughal court painting?', 'Kangra aesthetic triumph: transforming imperial technical draftsmanship into a lyrical, emotionally luminous visual poetry of Krishna-Radha bhakti.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db9dd3ed-1e89-469d-9126-60ebae6d68b9', 'Kangra masters utilized pure, cool mineral pigments (soft greens, ethereal blues), delicate lyrical contours, and an intimate spiritual atmosphere suffused with Vaishnava poetic emotion rather than imperial Mughal court pomp and battles', true, 'e10b1955-3808-4e51-9167-40b034580c83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3169c4f3-7415-4065-909b-5ae0ee4c7837', 'Kangra paintings were made on metal sheets using oil paints', false, 'e10b1955-3808-4e51-9167-40b034580c83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24423d1e-399c-4933-9687-e0ad2a05d95b', 'They painted only geometric black-and-white grids', false, 'e10b1955-3808-4e51-9167-40b034580c83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d417242-874a-4043-89c6-60e739c3581c', 'They never painted human figures', false, 'e10b1955-3808-4e51-9167-40b034580c83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d568357-fa69-46de-916c-ff3a1682cc1f', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'Why was the ''Sattriya'' dance of Assam, developed by Sankaradeva in the 15th century, recognized as a Classical Dance form of India?', 'Sattriya dance is an exquisite, rigorously codified monastic dance-drama tradition nurtured for five centuries in Assam''s Satras.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f55036a-3247-4c64-9846-736610b148ec', 'It preserves a 500-year-old unbroken spiritual performance tradition codified with intricate mudras, tala rhythms, Borgeet melodies, and dramatic narrative integrity within Assamese Vaishnavite Satras', true, '9d568357-fa69-46de-916c-ff3a1682cc1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6fca6bd-28d5-4f9e-b428-10226351648a', 'Because it is a modern European dance', false, '9d568357-fa69-46de-916c-ff3a1682cc1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41be4da9-3553-4df7-9be4-d2638e8ed47a', 'Because it is performed without any music', false, '9d568357-fa69-46de-916c-ff3a1682cc1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cad3d049-2944-4640-bf12-c7c1cfe00ba9', 'Because it was invented for film movies', false, '9d568357-fa69-46de-916c-ff3a1682cc1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84cdf061-ad81-4452-a56e-381cde6781d5', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'Consider four regional cultural innovations of medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99f2eeba-4169-426a-8067-a460c9a5c656', 'The decentralized flowering of distinct, sophisticated regional cultures that enriched the mosaic of Indian civilization through localized vernacular genius', true, '84cdf061-ad81-4452-a56e-381cde6781d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('062bf642-e8b6-459c-a296-ce7544afb84d', 'The complete destruction of Indian culture', false, '84cdf061-ad81-4452-a56e-381cde6781d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce306f04-435c-4c09-9acd-da88c42ecfa3', 'A series of failed attempts to copy foreign traditions', false, '84cdf061-ad81-4452-a56e-381cde6781d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfe8833f-0c33-4945-8ed3-1c44d93d89a8', 'An identical culture with no regional differences', false, '84cdf061-ad81-4452-a56e-381cde6781d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e44b8e45-d913-4de0-8aa5-49d5c530d703', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'How did the terracotta plaques on medieval Bengal temples (such as at Vishnupur) provide a visual mirror of everyday social life?', 'Bengal terracotta friezes are invaluable visual chronicles: blending sacred mythological epics with candid snapshots of 17th/18th-century deltaic social life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6e45a28-7b1f-4ed4-b2e7-95d11d8d3425', 'Besides portraying Ramayana and Krishna scenes, they vividly depicted everyday social scenes: Europeans traveling in ships, merchants smoking hookahs, domestic chores, hunting expeditions, and local festivals', true, 'e44b8e45-d913-4de0-8aa5-49d5c530d703');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8e07b2f-6bfa-4972-a086-4a33d85e7ae5', 'They contained only abstract math numbers', false, 'e44b8e45-d913-4de0-8aa5-49d5c530d703');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('542510b4-4fcc-42ea-a422-d1886e8d5f73', 'They depicted only kings sleeping', false, 'e44b8e45-d913-4de0-8aa5-49d5c530d703');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cc4242a-62d7-436d-aeab-a4cb1c6e1581', 'They were left completely blank without carvings', false, 'e44b8e45-d913-4de0-8aa5-49d5c530d703');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3eeddb2-282c-4a8f-85d0-bc9a55a256be', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'What is the historical significance of the ''Rasamanjari'' painted in the Basohli style by artist Devidasa in 1694?', 'Devidasa''s 1694 Basohli Rasamanjari is a landmark of Pahari art, renowned for opulent chromatic vigor and iridescent beetle-wing casing inlays.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6790e739-8a2c-48bc-b98f-fcd5ef85061b', 'It represents the zenith of early Pahari painting, characterized by intense glowing colors, beetle-wing fragments for jewelry embellishment, and emotionally charged stylized figures', true, 'a3eeddb2-282c-4a8f-85d0-bc9a55a256be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b8e35ef-e595-409c-9256-eac201389569', 'It was a military battle map', false, 'a3eeddb2-282c-4a8f-85d0-bc9a55a256be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('472322fc-f818-4b36-b33f-3c4f3fb2eb67', 'It was a legal code for judges', false, 'a3eeddb2-282c-4a8f-85d0-bc9a55a256be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9eb00f2-3c1d-41d2-9355-22f3be41524f', 'It was a textbook of Sanskrit mathematics', false, 'a3eeddb2-282c-4a8f-85d0-bc9a55a256be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c089ba3f-93f3-486a-bbb0-e50ce78846c7', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'What comprehensive historiographical insight emerges from Chapter 9 of NCERT Class 7 History?', 'Chapter 9 synthesizes the organic evolution of India''s composite regional identities: linguistic pride, artistic excellence, and syncretic cultural heritage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b34cb182-2c10-489c-8e90-13df814d01dd', 'Indian regional cultures are dynamic historical creations—forged through centuries of cross-pollination between local languages, folk rituals, classical arts, and overarching political patronages—constituting the glorious pluralistic tapestry of Indian nationhood', true, 'c089ba3f-93f3-486a-bbb0-e50ce78846c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83015c15-ce4f-45ff-94b7-b25ebc2a057b', 'That India was always a monolithic culture with no diversity', false, 'c089ba3f-93f3-486a-bbb0-e50ce78846c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1df2c04-2daf-43f5-8ca6-8dc791ed7982', 'That regional cultures disappeared after the medieval period', false, 'c089ba3f-93f3-486a-bbb0-e50ce78846c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c7387e9-68cb-4898-99f6-50645d0b5647', 'That art was unimportant in medieval India', false, 'c089ba3f-93f3-486a-bbb0-e50ce78846c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c4edf6b-fa92-4d35-9c2d-19c70febedcd', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'संज्ञा अथवा सर्वनाम की विशेषता (गुण, दोष, रूप, रंग, आकार, संख्या, परिमाण आदि) बताने वाले शब्दों को क्या कहते हैं?', 'विशेषण: जो शब्द संज्ञा या सर्वनाम की विशेषता प्रकट करते हैं, उन्हें विशेषण कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2858fbd6-fb26-41db-ab8b-9ae767aea6ec', 'विशेषण (Adjective)', true, '8c4edf6b-fa92-4d35-9c2d-19c70febedcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac64934b-1ec6-4ed4-9609-431d04a71a67', 'क्रिया', false, '8c4edf6b-fa92-4d35-9c2d-19c70febedcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('227b61aa-e5de-42f0-8dd9-4bbad0253fdc', 'अव्यय', false, '8c4edf6b-fa92-4d35-9c2d-19c70febedcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('972313a2-8e33-4af2-bf01-ab83ac7bdaa6', 'कारक', false, '8c4edf6b-fa92-4d35-9c2d-19c70febedcd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0aa1f9f0-1b0f-48da-9e2b-fb1fb32731aa', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'विशेषण शब्द जिस संज्ञा अथवा सर्वनाम की विशेषता बताता है, उस संज्ञा/सर्वनाम को व्याकरण में क्या कहते हैं?', 'विशेष्य: जिसकी विशेषता बताई जाए, वह विशेष्य कहलाता है (जैसे: ''काली गाय'' में ''काली'' विशेषण और ''गाय'' विशेष्य है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6679d898-8e88-4de1-ac25-85b26532301d', 'विशेष्य (जैसे: ''मीठा आम'' में ''आम'' विशेष्य है)', true, '0aa1f9f0-1b0f-48da-9e2b-fb1fb32731aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52ecc940-2b19-450d-9388-37f795c66580', 'प्रविशेषण', false, '0aa1f9f0-1b0f-48da-9e2b-fb1fb32731aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02a5ad9f-4f41-48bf-a3c5-399a5da6f6bb', 'क्रिया', false, '0aa1f9f0-1b0f-48da-9e2b-fb1fb32731aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1551c5be-6e7b-4163-8cdd-011bf051175d', 'उद्देश्य', false, '0aa1f9f0-1b0f-48da-9e2b-fb1fb32731aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e32c965-05ba-4656-8f17-0585b9698ca8', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'विशेषण की भी विशेषता बताने वाले शब्दों को क्या कहा जाता है (जैसे: ''वह बहुत परिश्रमी है'' में ''बहुत'')?', 'प्रविशेषण: जो शब्द विशेषणों की भी विशेषता (तीव्रता/मात्रा) बताते हैं, उन्हें प्रविशेषण कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ce0fac7-9c6f-4bfd-bb2a-b842cc50db6c', 'प्रविशेषण (जैसे: बहुत, अत्यंत, बड़ा, अत्यधिक)', true, '0e32c965-05ba-4656-8f17-0585b9698ca8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('957941d1-cd8f-4f62-be50-4f4470af524b', 'क्रियाविशेषण', false, '0e32c965-05ba-4656-8f17-0585b9698ca8');
