INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('670b1881-7ee7-4404-b677-b7e62f37537a', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'हिंदी व्याकरण में विशेषण के मुख्य रूप से कितने भेद होते हैं?', 'विशेषण के 4 भेद हैं: गुणवाचक, संख्यावाचक, परिमाणवाचक, तथा सार्वनामिक (संकेतवाचक) विशेषण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f246ab2-547c-4058-9e01-8ec339e52fda', '4 भेद (1. गुणवाचक, 2. संख्यावाचक, 3. परिमाणवाचक, 4. सार्वनामिक विशेषण)', true, '670b1881-7ee7-4404-b677-b7e62f37537a');
