INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df4a0fc1-4715-4500-ac27-0b627ba77dbc', '5 भेद', false, '670b1881-7ee7-4404-b677-b7e62f37537a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16fcdffc-ea41-4227-b407-70ca92a39da5', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'जो विशेषण शब्द संज्ञा या सर्वनाम के गुण, दोष, रंग, रूप, आकार, स्वभाव या दशा का बोध कराते हैं (जैसे: ''ईमानदार बालक'', ''लाल गुलाब''), वे क्या कहलाते हैं?', 'गुणवाचक विशेषण: किसी वस्तु/व्यक्ति के गुण, दोष, रंग, आकार, अवस्था का बोध कराने वाले शब्द।', NOW()) ON CONFLICT DO NOTHING;
