INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7671c0e9-f225-46aa-ae8c-5febaa787f3f', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'जो विशेषण शब्द संज्ञा या सर्वनाम की संख्या (गिनती) का बोध कराते हैं (जैसे: ''चार लड़के'', ''कुछ पुस्तकें''), वे क्या कहलाते हैं?', 'संख्यावाचक विशेषण: गणनीय वस्तुओं की निश्चित अथवा अनिश्चित संख्या का बोध कराने वाले शब्द।', NOW()) ON CONFLICT DO NOTHING;
