INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5e8b72e-990a-45ac-8ef1-ea501c978337', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'जब कोई सर्वनाम शब्द संज्ञा से ठीक पहले आकर उसकी विशेषता प्रकट करता है (जैसे: ''वह लड़का बहुत चतुर है'', ''यह पुस्तक मेरी है''), तो वह क्या कहलाता है?', 'सार्वनामिक विशेषण: जब सर्वनाम संज्ञा से पहले लगकर संज्ञा की ओर संकेत/विशेषता बताता है।', NOW()) ON CONFLICT DO NOTHING;
