INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4ea5612-89c6-4cae-b5cc-6e65b40fc942', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', '''कक्षा में तीस विद्यार्थी उपस्थित हैं।'' वाक्य में ''तीस'' किस प्रकार का विशेषण है?', '''तीस'' विद्यार्थियों की निश्चित गणनीय संख्या का बोध कराता है, अतः यह निश्चित संख्यावाचक विशेषण है।', NOW()) ON CONFLICT DO NOTHING;
