INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7efaf522-6ce5-437e-aac6-004b8de93f64', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', '''बाजार से दो किलो टमाटर ले आओ।'' वाक्य में ''दो किलो'' किस प्रकार का विशेषण है?', '''दो किलो'' तौल (मात्रा) का निश्चित परिमाण बताता है, अतः यह निश्चित परिमाणवाचक विशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('064c4cd9-33e2-44aa-813c-fab9a41557a4', 'निश्चित परिमाणवाचक विशेषण', true, '7efaf522-6ce5-437e-aac6-004b8de93f64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71c7a994-d070-45fa-bf98-4ea867f5f163', 'अनिश्चित परिमाणवाचक', false, '7efaf522-6ce5-437e-aac6-004b8de93f64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f413717-1ee9-44b0-b24b-e4e0baf12a1c', 'निश्चित संख्यावाचक', false, '7efaf522-6ce5-437e-aac6-004b8de93f64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('449ed6fd-6683-440d-b118-47a442551e9a', 'सार्वनामिक विशेषण', false, '7efaf522-6ce5-437e-aac6-004b8de93f64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11ce7af6-da48-403e-9e2c-89763095c6a4', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', '''भारत'' संज्ञा शब्द से बनने वाला उपयुक्त विशेषण क्या होगा?', 'भारत (संज्ञा) + ईय (प्रत्यय) = भारतीय (विशेषण, जैसे: ''भारतीय संस्कृति'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abcce9ee-e0b4-4912-844b-e9aeba01eaca', 'भारतीय', true, '11ce7af6-da48-403e-9e2c-89763095c6a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d1acf01-ff37-4552-8b04-2a57fd11887b', 'भारतवासी', false, '11ce7af6-da48-403e-9e2c-89763095c6a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b48036db-2a2f-44e4-bc2f-6d65787b8f57', 'भारतवर्ष', false, '11ce7af6-da48-403e-9e2c-89763095c6a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dc08038-589f-4f14-a070-179bdc185563', 'भारती', false, '11ce7af6-da48-403e-9e2c-89763095c6a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('271bc755-ef88-4c7a-ba8a-d50d07e7be55', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', '''इतिहास'' संज्ञा शब्द से बनने वाला मानक विशेषण शब्द क्या होगा?', 'इतिहास में ''इक'' प्रत्यय लगने से आदि स्वर ''इ'' की वृद्धि ''ऐ'' होकर ''ऐतिहासिक'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e697edc5-2a17-49dc-9c92-8f17d6473ebe', 'ऐतिहासिक (इतिहास + इक)', true, '271bc755-ef88-4c7a-ba8a-d50d07e7be55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a56a7b-ffe6-44a3-984a-e206ed05b38c', 'इतिहासकार', false, '271bc755-ef88-4c7a-ba8a-d50d07e7be55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d2cfda-b517-49fe-a45d-4d38cced129e', 'ऐतिहास', false, '271bc755-ef88-4c7a-ba8a-d50d07e7be55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8d5f163-abfa-4ce9-946a-a0c411c974ec', 'इतिहासी', false, '271bc755-ef88-4c7a-ba8a-d50d07e7be55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40bfe496-8d12-4394-aff0-2f98a042a97b', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', 'संख्यावाचक विशेषण और परिमाणवाचक विशेषण की पहचान करने का सबसे सरल और सटीक नियम क्या है?', 'गणनीय संज्ञाओं के साथ संख्यावाचक विशेषण तथा नाप-तौल योग्य अगणनीय संज्ञाओं के साथ परिमाणवाचक विशेषण आता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1b9c9dc-9b6c-45c1-9174-e138569333ac', 'यदि विशेष्य को ''गिना जा सकता है'' (Countable), तो वह ''संख्यावाचक'' है (जैसे: चार केले, दस पुस्तकें) ; यदि विशेष्य को ''नापा या तौला जाता है'' (Uncountable/Measurable), तो वह ''परिमाणवाचक'' है (जैसे: चार लीटर दूध, दो किलो दाल)', true, '40bfe496-8d12-4394-aff0-2f98a042a97b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6160f8dc-def0-4102-8924-0b348131d850', 'दोनों में कोई अंतर नहीं है', false, '40bfe496-8d12-4394-aff0-2f98a042a97b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e090a1f6-7a95-4f18-afa9-ce3a515c673c', 'संख्यावाचक केवल स्त्रीलिंग में आता है', false, '40bfe496-8d12-4394-aff0-2f98a042a97b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09bde306-18b1-4d12-9885-4c0c523ae64f', 'परिमाणवाचक हमेशा बहुवचन होता है', false, '40bfe496-8d12-4394-aff0-2f98a042a97b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75e3ddc4-f521-4b8b-85b8-0a85dbbe4f03', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''मुझे थोड़ा पानी दीजिए।'' और ''सभा में थोड़े लोग आए थे।'' दोनों वाक्यों में प्रयुक्त ''थोड़ा / थोड़े'' क्रमशः किस भेद के अंतर्गत आते हैं?', 'पानी अगणनीय द्रव्य है (अनिश्चित परिमाण), जबकि लोग गणनीय प्राणी हैं (अनिश्चित संख्या)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68acbb9b-8857-4393-84b8-24e2ee88b1da', '''थोड़ा पानी'' = अनिश्चित परिमाणवाचक विशेषण ; ''थोड़े लोग'' = अनिश्चित संख्यावाचक विशेषण', true, '75e3ddc4-f521-4b8b-85b8-0a85dbbe4f03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca381382-7e10-4c3d-ae7c-0ac3c2b3ba55', 'दोनों संख्यावाचक हैं', false, '75e3ddc4-f521-4b8b-85b8-0a85dbbe4f03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d8bb813-831e-43b1-850c-b9c465954d6b', 'दोनों परिमाणवाचक हैं', false, '75e3ddc4-f521-4b8b-85b8-0a85dbbe4f03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b26d503e-0bd4-4d7f-9699-27f5a66b9901', 'दोनों सार्वनामिक विशेषण हैं', false, '75e3ddc4-f521-4b8b-85b8-0a85dbbe4f03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6b40ad6-2ae1-4f58-87bd-a64bcdb2a299', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', 'तुलना की दृष्टि से विशेषण की कुल कितनी अवस्थाएँ (Degrees of Comparison) होती हैं?', 'विशेषण की 3 अवस्थाएँ हैं: मूलावस्था (उच्च), उत्तरावस्था (उच्चतर), उत्तमावस्था (उच्चतम)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dd6c089-b698-4274-86e8-9c10fa2f8382', 'तीन अवस्थाएँ (1. मूलावस्था [Positive], 2. उत्तरावस्था [Comparative - तर], 3. उत्तमावस्था [Superlative - तम])', true, 'a6b40ad6-2ae1-4f58-87bd-a64bcdb2a299');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf88f711-ff90-4ff0-8b77-678cebeb4041', 'दो अवस्थाएँ', false, 'a6b40ad6-2ae1-4f58-87bd-a64bcdb2a299');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc8cf09-895a-431b-ae2a-f34edf0ce06b', 'चार अवस्थाएँ', false, 'a6b40ad6-2ae1-4f58-87bd-a64bcdb2a299');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4779486-aa58-4387-972c-4f863d643e41', 'पाँच अवस्थाएँ', false, 'a6b40ad6-2ae1-4f58-87bd-a64bcdb2a299');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1832bee4-4cc3-4fb3-821f-744ceaa14c44', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''सुंदर'' विशेषण की ''उत्तरावस्था'' (Comparative Degree) और ''उत्तमावस्था'' (Superlative Degree) क्रमशः क्या होंगी?', 'मूलावस्था = सुंदर; उत्तरावस्था = सुंदरतर; उत्तमावस्था = सुंदरतम।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aaf9b0d-55fa-4e5a-9e40-126739a46830', 'सुंदरतर और सुंदरतम', true, '1832bee4-4cc3-4fb3-821f-744ceaa14c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee4876b4-d38f-4582-9a32-8014aa7a884c', 'सुंदरी और सुंदरा', false, '1832bee4-4cc3-4fb3-821f-744ceaa14c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43b2642c-41e0-44ff-aaf2-addf7c2d46a5', 'अधिक सुंदर और सबसे सुंदर मात्र', false, '1832bee4-4cc3-4fb3-821f-744ceaa14c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e0a86af-80e3-4bce-88e6-c461786d93b8', 'सुंदरता और सौंदर्य', false, '1832bee4-4cc3-4fb3-821f-744ceaa14c44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dae6dd7d-dd38-44be-ae67-1ed40ad8a1ab', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''कश्मीरी सेब सिंदूरी लाल होता है।'' इस वाक्य में ''सिंदूरी'' शब्द व्याकरण की दृष्टि से क्या है?', '''लाल'' विशेषण की विशेषता ''सिंदूरी'' बता रहा है, अतः ''सिंदूरी'' यहाँ प्रविशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c9536d5-ffae-42d5-baa9-c3df3e97cfb6', 'प्रविशेषण (क्योंकि यह ''लाल'' विशेषण के रंग की गहराई/विशेषता बता रहा है)', true, 'dae6dd7d-dd38-44be-ae67-1ed40ad8a1ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf2634fe-c771-48ff-a2b6-43bb359d6af6', 'विशेष्य', false, 'dae6dd7d-dd38-44be-ae67-1ed40ad8a1ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28c8055d-73e8-4764-b7c7-fa454476ad68', 'क्रियाविशेषण', false, 'dae6dd7d-dd38-44be-ae67-1ed40ad8a1ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e584e556-20c6-49c2-b236-010f655eab44', 'सार्वनामिक विशेषण', false, 'dae6dd7d-dd38-44be-ae67-1ed40ad8a1ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97bc547a-bc84-40c1-aa3a-a6e0285f0ba0', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''यह'' शब्द का प्रयोग निम्नलिखित दो वाक्यों में किस रूप में हुआ है?
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1452d5ab-1b5d-49e8-8903-3d1dd5a197d2', 'वाक्य 1 में ''यह'' = निश्चयवाचक सर्वनाम ; वाक्य 2 में ''यह'' = सार्वनामिक विशेषण', true, '97bc547a-bc84-40c1-aa3a-a6e0285f0ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eca1a90-00e4-4472-a631-ef97c2029be6', 'दोनों में निश्चयवाचक सर्वनाम है', false, '97bc547a-bc84-40c1-aa3a-a6e0285f0ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96ba12ff-4dc3-497a-97e9-2bf452f73cd3', 'दोनों में सार्वनामिक विशेषण है', false, '97bc547a-bc84-40c1-aa3a-a6e0285f0ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2850d435-04de-4122-b420-5150d26f7784', 'वाक्य 1 में विशेषण और वाक्य 2 में सर्वनाम है', false, '97bc547a-bc84-40c1-aa3a-a6e0285f0ba0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d7fc099-4f37-4efc-84f9-ac8865415de0', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''दिन'' संज्ञा शब्द से बनने वाला शुद्ध विशेषण रूप क्या होगा?', 'दिन + इक = दैनिक (जैसे: दैनिक समाचार पत्र)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb2c11d5-b472-4f69-92d2-a891e94ee1c4', 'दैनिक (दिन + इक)', true, '0d7fc099-4f37-4efc-84f9-ac8865415de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cbddc4f-2038-4df1-bb97-e071506ea392', 'दीन', false, '0d7fc099-4f37-4efc-84f9-ac8865415de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('409fa318-7096-43fd-a93a-0b14bb431f6f', 'दिनांक', false, '0d7fc099-4f37-4efc-84f9-ac8865415de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edffc2cc-7776-4335-9814-bb78d1c5f6f8', 'दिवस', false, '0d7fc099-4f37-4efc-84f9-ac8865415de0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95288617-3e34-45fc-85f0-d91ca02a93e4', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''भूख'' संज्ञा शब्द से बनने वाला सही विशेषण शब्द क्या होगा?', 'भूख (भाववाचक संज्ञा) से ''भूखा'' (विशेषण) बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa6328ad-e363-4565-8d4a-08d53b5cdae1', 'भूखा (जैसे: ''भूखा कुत्ता'')', true, '95288617-3e34-45fc-85f0-d91ca02a93e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43585ab3-67d0-414e-b308-b345ec6d2dae', 'भुखमरी', false, '95288617-3e34-45fc-85f0-d91ca02a93e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a682919-950d-4435-89f6-5814a67cd63a', 'भूखिला', false, '95288617-3e34-45fc-85f0-d91ca02a93e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24aaf200-80bc-43ef-aacd-fff642d1f822', 'भूखापन', false, '95288617-3e34-45fc-85f0-d91ca02a93e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cbb0aec-7fa9-42c4-af5a-193ef53ea1e4', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''स्थान'' संज्ञा शब्द से बनने वाला मानक विशेषण शब्द क्या होगा?', 'स्थान + ईय = स्थानीय (जैसे: स्थानीय प्रशासन)।', NOW()) ON CONFLICT DO NOTHING;
