INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('309e6c7e-89a6-44f9-8cd9-57dff79dd83c', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''पहला, दूसरा, तीसरा, पाँचवाँ'' किस प्रकार के निश्चित संख्यावाचक विशेषण हैं?', 'क्रमवाचक: जो क्रम या सिलसिले का बोध कराएँ (पहला, दूसरा, तीसरा, दसवाँ)।', NOW()) ON CONFLICT DO NOTHING;
