INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a54e16e-c0d5-4a6a-998e-8f8af3058196', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''दुगुना, तिगुना, चौगुना, सौगुना'' किस प्रकार के निश्चित संख्यावाचक विशेषण हैं?', 'आवृत्तिवाचक: जो किसी संख्या की आवृत्ति या गुणन (Multiple) का बोध कराएँ (दुगुना, चौगुना)।', NOW()) ON CONFLICT DO NOTHING;
