INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e02ab092-a204-4f21-b7c6-41f12db8c787', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''दोनों, तीनों, चारों, दसों'' किस प्रकार के निश्चित संख्यावाचक विशेषण हैं?', 'समुदायवाचक: जो सभी इकाइयों के समूह या समुदाय का बोध कराएँ (दोनों, तीनों, चारों)।', NOW()) ON CONFLICT DO NOTHING;
