INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1990790c-b52d-4a55-8fbd-4281ca3bc307', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''प्रत्येक, हर-एक, प्रति'' किस प्रकार के निश्चित संख्यावाचक विशेषण हैं?', 'प्रत्येकबोधक: जो अनेक में से हर-एक का पृथक बोध कराएँ (प्रत्येक नागरिक, हर-एक छात्र)।', NOW()) ON CONFLICT DO NOTHING;
