INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('670e93ef-f55f-4ec0-abd5-9531d3628a17', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''रंग'' संज्ञा शब्द से बनने वाला उपयुक्त विशेषण क्या होगा?', 'रंग + ईला = रंगीला; रंग + ईन = रंगीन (विशेषण रूप)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40f8d564-20e3-4d1f-9d39-4dcd018cb865', 'रंगीला / रंगीन', true, '670e93ef-f55f-4ec0-abd5-9531d3628a17');
