INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7db1640-0365-4022-80d2-3fab1bfd089f', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''उड़ना'' क्रिया शब्द से बनने वाला विशेषण शब्द क्या होगा?', 'उड़ना क्रिया से ''उड़ाऊ'' (धन उड़ाने वाला) या ''उड़ाका'' विशेषण बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61e142e3-0fc4-46b2-83bf-ba2a144cc068', 'उड़ाऊ (या उड़ने वाला / उड़ाका)', true, 'f7db1640-0365-4022-80d2-3fab1bfd089f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1677b988-ad83-440e-9a06-0d5ce0765e76', 'उड़ान', false, 'f7db1640-0365-4022-80d2-3fab1bfd089f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d22ebc24-68d9-4ca0-92b9-204e25be0925', 'उड़ना', false, 'f7db1640-0365-4022-80d2-3fab1bfd089f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c089f75-3d1e-44fe-ab2d-044ae7613ab6', 'उड़न', false, 'f7db1640-0365-4022-80d2-3fab1bfd089f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3daa3fd0-2ceb-4292-abe4-f66de071514b', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''आगे'' अव्यय शब्द से बनने वाला विशेषण शब्द क्या होगा?', 'आगे (स्थानवाचक अव्यय) से ''अगला'' विशेषण बनता है (''पीछे'' से ''पिछला'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b43de9a4-c112-4353-bd99-743eb793c6b8', 'अगला (जैसे: ''अगला स्टेशन'')', true, '3daa3fd0-2ceb-4292-abe4-f66de071514b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0852338-5ddc-4206-b42a-67aab2528082', 'आगेवाला', false, '3daa3fd0-2ceb-4292-abe4-f66de071514b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e98eb4e-43d1-4581-b3d6-d6be415f53ed', 'अग्रणी', false, '3daa3fd0-2ceb-4292-abe4-f66de071514b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1c4658c-f599-46ed-8bf6-33045bc1d1b7', 'आगामी', false, '3daa3fd0-2ceb-4292-abe4-f66de071514b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a12ea445-c2c3-4854-b23a-19f8422ee36a', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6685bcc6-98f8-41fa-9b7d-e2339401a48a', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'a12ea445-c2c3-4854-b23a-19f8422ee36a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0244999f-207d-4fa7-822f-d427595497a7', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'a12ea445-c2c3-4854-b23a-19f8422ee36a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('421bb717-6983-401b-8354-96b8fdd64c69', '(A) सही है, परन्तु (R) गलत है।', false, 'a12ea445-c2c3-4854-b23a-19f8422ee36a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b53b2668-b1f7-4a8c-be55-bfe8bd206467', '(A) गलत है, परन्तु (R) सही है।', false, 'a12ea445-c2c3-4854-b23a-19f8422ee36a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8d98012-e5db-4234-89b1-f2c24e92555b', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'Spot the IMPOSTER in the following group of संज्ञा से बने विशेषण शब्दों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f640f52-8525-455d-94ad-cfa4bc42ce71', 'युग्म 1', false, 'b8d98012-e5db-4234-89b1-f2c24e92555b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89f94304-345f-4065-a6f8-2e1d02389a1e', 'युग्म 2', false, 'b8d98012-e5db-4234-89b1-f2c24e92555b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e13f6b2-01e6-4110-8753-9cdcf2aa5000', 'युग्म 3', false, 'b8d98012-e5db-4234-89b1-f2c24e92555b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d55775d2-2c9a-497a-9ea3-5eac027fa68d', 'युग्म 4 (''पढ़ना'' संज्ञा नहीं, बल्कि ''क्रिया'' [Verb] है ; अतः ''पढ़ाकू'' क्रिया से बना विशेषण है, संज्ञा से नहीं)', true, 'b8d98012-e5db-4234-89b1-f2c24e92555b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ade33420-6b1b-4c93-855f-c6b3c42665e6', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'सुमेलित कीजिए (विशेषण की तुलनात्मक अवस्थाएँ):
(क) लघु      -> (i) मूलावस्था (Positive Degree)
(ख) लघुतर    -> (ii) उत्तरावस्था (Comparative Degree)
(ग) लघुतम    -> (iii) उत्तमावस्था (Superlative Degree)
(घ) अति लघु   -> (iv) हिंदी में उत्तरावस्था/प्रविशेषण युक्त रूप', 'लघु = मूलावस्था; लघुतर = उत्तरावस्था; लघुतम = उत्तमावस्था।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fb7672a-52d2-48c6-901a-137a8f2cb570', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, 'ade33420-6b1b-4c93-855f-c6b3c42665e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44941cd4-53da-4e32-9d44-8bd70ef48d0d', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, 'ade33420-6b1b-4c93-855f-c6b3c42665e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c6f9e4f-ed28-4cdf-b185-e25ab6060642', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'ade33420-6b1b-4c93-855f-c6b3c42665e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be488761-c7b0-4c3a-8565-3ab6fd671201', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'ade33420-6b1b-4c93-855f-c6b3c42665e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('807ec438-bf2f-4636-b3cd-6153a8a04fa9', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''उद्देश्य विशेषण'' (Attributive Adjective) और ''विधेय विशेषण'' (Predicative Adjective) में क्या व्याकरणिक अंतर होता है?', 'संज्ञा से पूर्व विशेषण = उद्देश्य विशेषण (''सफेद गाय''); संज्ञा के उपरांत विशेषण = विधेय विशेषण (''गाय सफेद है'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0942cef4-9399-4dde-9bd4-705dae50c763', 'जब विशेषण विशेष्य (संज्ञा) से पहले आता है, तो वह ''उद्देश्य विशेषण'' कहलाता है (जैसे: ''काला घोड़ा दौड़ा'') ; जब विशेषण विशेष्य के बाद और क्रिया से पहले आता है, तो वह ''विधेय विशेषण'' कहलाता है (जैसे: ''घोड़ा काला है'')', true, '807ec438-bf2f-4636-b3cd-6153a8a04fa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('099f3722-84b0-4922-8e2b-ca6961ab8158', 'दोनों में कोई अंतर नहीं होता', false, '807ec438-bf2f-4636-b3cd-6153a8a04fa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('414610f8-111c-4daf-b9e1-430878042eca', 'उद्देश्य विशेषण केवल स्त्रीलिंग होता है', false, '807ec438-bf2f-4636-b3cd-6153a8a04fa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fca61160-0a11-42bf-8e7c-5189bfdeeb93', 'विधेय विशेषण केवल भविष्यत काल में आता है', false, '807ec438-bf2f-4636-b3cd-6153a8a04fa9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0803d39e-3d16-4e09-b5f7-ce1709cfb6c2', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''विधेय विशेषण'' का शुद्ध प्रयोग हुआ है?', '''मेरा कुर्ता बहुत पुराना है'' में ''पुराना'' विधेय भाग में विशेष्य के बाद आया है, अतः यह विधेय विशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1573be13-10c3-4107-aeb0-ee3bcd476ad7', '''मेरा कुर्ता बहुत पुराना है।'' (''पुराना'' विशेषण विशेष्य ''कुर्ता'' के बाद प्रयुक्त हुआ है)', true, '0803d39e-3d16-4e09-b5f7-ce1709cfb6c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40598f8b-e737-4c04-a5af-c7b326b0e8fa', '''पुराना कुर्ता अलमारी में रखा है।''', false, '0803d39e-3d16-4e09-b5f7-ce1709cfb6c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e53279fe-c55f-4709-add3-c2ec6b8c67b2', '''सफेद हंस तैर रहा है।''', false, '0803d39e-3d16-4e09-b5f7-ce1709cfb6c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdb5eb1f-d244-4259-b45b-c9ba50d1aa0a', '''मीठा आम खाओ।''', false, '0803d39e-3d16-4e09-b5f7-ce1709cfb6c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e7b5598-fd4c-4ae4-911d-babd8217f3d7', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''शास्त्र'' संज्ञा शब्द से बनने वाला मानक व्याकरणिक विशेषण क्या होगा?', 'शास्त्र + ईय = शास्त्रीय (Classical, जैसे: शास्त्रीय नृत्य)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7fcbf21-0b4b-49ea-ab66-de341c402a50', 'शास्त्रीय (शास्त्र + ईय, जैसे: शास्त्रीय संगीत)', true, '3e7b5598-fd4c-4ae4-911d-babd8217f3d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601017d8-ed2f-46d3-8436-5def310adf70', 'शास्त्रज्ञ', false, '3e7b5598-fd4c-4ae4-911d-babd8217f3d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23462d20-d300-4910-8357-8abd1c6a2941', 'शास्त्रार्थ', false, '3e7b5598-fd4c-4ae4-911d-babd8217f3d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16872079-ebf0-40c5-ac2e-2528fc6fe3a1', 'शास्त्री', false, '3e7b5598-fd4c-4ae4-911d-babd8217f3d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cad38278-23bc-426c-97a2-f1aa6b36a701', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''आत्मा'' संज्ञा शब्द से बनने वाला शुद्ध विशेषण रूप क्या होगा?', 'आत्मा + इक = आत्मिक (जैसे: आत्मिक शांति)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7efb64f8-934e-4d06-9455-03544214b375', 'आत्मिक (आत्मा + इक)', true, 'cad38278-23bc-426c-97a2-f1aa6b36a701');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d985acd-1d97-4bde-bf2e-016b264bd362', 'आत्मीय', false, 'cad38278-23bc-426c-97a2-f1aa6b36a701');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('283f7482-06b4-4425-be9f-13c3f7ee9f18', 'आत्मवान', false, 'cad38278-23bc-426c-97a2-f1aa6b36a701');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('625eafb5-0f04-4740-9b27-183541b1b9c1', 'आत्मावान', false, 'cad38278-23bc-426c-97a2-f1aa6b36a701');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57328aa6-337c-4b5e-bf23-a5e69835aa59', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''नगर'' और ''ग्राम'' शब्दों से बनने वाले विशेषण युग्म का सही चयन कीजिए:', 'नगर + इक = नागरिक; ग्राम + ईण = ग्रामीण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f51a7a5-1486-4be9-a667-dd33a6f15b3d', 'नागरिक और ग्रामीण (नगर + इक = नागरिक ; ग्राम + ईण = ग्रामीण)', true, '57328aa6-337c-4b5e-bf23-a5e69835aa59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac762d84-b69f-4daa-89d9-9877c6f657ca', 'नगरी और ग्रामी', false, '57328aa6-337c-4b5e-bf23-a5e69835aa59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('325c7f1e-032b-4134-a525-5f4ee501e40a', 'नगरवासी और ग्रामवासी', false, '57328aa6-337c-4b5e-bf23-a5e69835aa59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('404fb0a5-a883-4195-8047-44e5d9074895', 'नगरिक और ग्रामीन', false, '57328aa6-337c-4b5e-bf23-a5e69835aa59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8eac73d-8329-43f4-abc7-efb28c067bff', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से ''अशुद्ध विशेषण प्रयोग'' वाला वाक्य छाँटिए:', 'उत्तमावस्था में ''सबसे'' और ''तम'' प्रत्यय का एक साथ प्रयोग व्याकरणिक दृष्टि से वर्जित पुनरुक्ति दोष है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('232af796-daa0-4c2b-bf66-a8b689c8303c', '''वह बहुत सबसे सुंदरतम लड़की है।'' (अशुद्ध: ''सबसे'' और ''सुंदरतम'' दोनों का एक साथ प्रयोग पुनरुक्ति दोष है ; शुद्ध: ''वह सुंदरतम लड़की है'' या ''वह सबसे सुंदर लड़की है'')', true, 'b8eac73d-8329-43f4-abc7-efb28c067bff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bca89fa-38a6-4ddf-8145-99c10d546141', '''वह बहुत परिश्रमी छात्र है।''', false, 'b8eac73d-8329-43f4-abc7-efb28c067bff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd4dc1d0-b835-4c34-8640-8c01d074efda', '''गंगा भारत की सबसे पवित्र नदी है।''', false, 'b8eac73d-8329-43f4-abc7-efb28c067bff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bad7643b-0ee8-4576-9469-5ed70d1ffa9f', '''यह पुस्तक अत्यंत उपयोगी है।''', false, 'b8eac73d-8329-43f4-abc7-efb28c067bff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03f6a39d-bf93-4bb3-8c3a-fdf2b8ebce60', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''व्यक्ति'' संज्ञा शब्द से बनने वाला सही विशेषण क्या होगा?', 'व्यक्ति + गत = व्यक्तिगत (Personal / Individual)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff9a6424-564d-407b-9d6a-5d510946961c', 'व्यक्तिगत (व्यक्ति + गत, जैसे: व्यक्तिगत राय)', true, '03f6a39d-bf93-4bb3-8c3a-fdf2b8ebce60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46287b80-1240-40bf-8128-09d4f1782983', 'व्यक्तित्व', false, '03f6a39d-bf93-4bb3-8c3a-fdf2b8ebce60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c27d0e6-a9ae-4045-af8e-ad6504bd2e6f', 'व्यक्तिपरक', false, '03f6a39d-bf93-4bb3-8c3a-fdf2b8ebce60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0334908-8caf-4e3d-9ef2-937d0c7c0f59', 'व्यक्तिमान', false, '03f6a39d-bf93-4bb3-8c3a-fdf2b8ebce60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2745c621-3274-4612-9557-e7c81b59e59a', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''रस'' संज्ञा शब्द से बनने वाला उपयुक्त विशेषण क्या होगा?', 'रस + ईला = रसीला (विशेषण)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0dec6bf-8a84-4eb7-a359-5d928746e392', 'रसीला (जैसे: ''रसीला आम'')', true, '2745c621-3274-4612-9557-e7c81b59e59a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40baa468-54ac-42a2-b70d-f115ae0766fa', 'रसायन', false, '2745c621-3274-4612-9557-e7c81b59e59a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf6ff44d-3416-46c8-84d9-6eaf60feeaf5', 'रसिकता', false, '2745c621-3274-4612-9557-e7c81b59e59a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92680aa1-de13-4bbd-889d-d79bb189964c', 'रसमयता', false, '2745c621-3274-4612-9557-e7c81b59e59a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2da1c017-7254-4398-ba92-7bdcef17f57a', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'विशेषण और विशेष्य के अन्वय (Agreement) का भाषा-सौंदर्य और वाक्य-शुद्धि में क्या सर्वोच्च महत्व है?', 'हिंदी में आकारांत विशेषणों का रूप विशेष्य के लिंग और वचन के अनुसार अनिवार्यतः रूपांतरित होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e60c5384-47ae-417b-ba17-0462daecd966', 'विशेषण का लिंग और वचन सदैव अपने विशेष्य (संज्ञा) के लिंग और वचन के अनुसार ही निर्धारित होता है (जैसे: ''अच्छा लड़का'', ''अच्छी लड़की'', ''अच्छे लड़के'') ; इस अन्वय के बिना भाषा अशुद्ध हो जाती है', true, '2da1c017-7254-4398-ba92-7bdcef17f57a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c5e8aa0-a137-4a03-801b-b6b1fef08c6c', 'विशेषण का लिंग कभी नहीं बदलता', false, '2da1c017-7254-4398-ba92-7bdcef17f57a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68f246b6-b69e-4a34-b5e5-0bed0d38cc0a', 'विशेषण केवल वाक्यों को लंबा करने के लिए प्रयुक्त होते हैं', false, '2da1c017-7254-4398-ba92-7bdcef17f57a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7de8476d-d5a4-4853-837c-6fb7d189ab36', 'विशेषण का भाषा में कोई महत्व नहीं है', false, '2da1c017-7254-4398-ba92-7bdcef17f57a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b39b802b-4c39-4c3b-9e3e-907641ceda0a', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'In standard circuit diagrams, how is an ELECTRIC CELL represented symbolically?', 'Symbolic convention: the longer, thinner parallel line represents the positive terminal (+), and the shorter, thicker line represents the negative terminal (-).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8a19abe-8656-4990-8abc-77772203f5f5', 'A long thin vertical line (representing the POSITIVE terminal) parallel to a shorter thick vertical line (representing the NEGATIVE terminal)', true, 'b39b802b-4c39-4c3b-9e3e-907641ceda0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b39a08b-9ca8-4a37-b60f-df2005a04278', 'A complete closed circle with a cross', false, 'b39b802b-4c39-4c3b-9e3e-907641ceda0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db1030e6-49df-4fc3-afaa-3d4a100963ca', 'Two identical thick squares', false, 'b39b802b-4c39-4c3b-9e3e-907641ceda0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbd44ec8-5a2c-4c9d-81e6-16057de118cc', 'A wavy spiral line', false, 'b39b802b-4c39-4c3b-9e3e-907641ceda0a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('554c0e7d-0aa1-4feb-af26-f07607f84305', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'A combination of two or more electric cells connected together in series is called a:', 'A battery is a connected group of electrochemical cells where the positive terminal of one cell connects to the negative terminal of the next.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28bf231e-8f71-4d6e-9b73-5aec142f449d', 'Battery', true, '554c0e7d-0aa1-4feb-af26-f07607f84305');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e615ac5a-f282-482f-ac73-43d9601a48ef', 'Switch', false, '554c0e7d-0aa1-4feb-af26-f07607f84305');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fde4735a-328d-424d-81fc-5669f3611ad5', 'Fuse', false, '554c0e7d-0aa1-4feb-af26-f07607f84305');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcab8b7a-3d36-4a88-ae95-515c302bbcb7', 'Electromagnet', false, '554c0e7d-0aa1-4feb-af26-f07607f84305');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6746b9f-a319-48ca-87b9-f4d5aa201873', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What is the phenomenon where a conducting wire gets intensely HOT when an electric current passes through it called?', 'Joule''s heating effect: electrical resistance dissipates electric potential energy into thermal kinetic heat (H = I²Rt).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd9e6213-f3d4-426e-aed2-03ddc64c0cd5', 'Heating Effect of Electric Current (Joule Heating)', true, 'c6746b9f-a319-48ca-87b9-f4d5aa201873');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b8f4b19-bb1e-4768-8a4d-94dea56c9db7', 'Magnetic Effect', false, 'c6746b9f-a319-48ca-87b9-f4d5aa201873');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('206b7043-92c1-4e08-9e6b-1a839cf79306', 'Chemical Effect', false, 'c6746b9f-a319-48ca-87b9-f4d5aa201873');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910f9e46-008f-4679-bcc6-7bae03215f6b', 'Cooling Effect', false, 'c6746b9f-a319-48ca-87b9-f4d5aa201873');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8883da25-bf05-49e3-a88b-3f8cdbc9a72c', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What is the high-resistance metallic wire coil inside electric room heaters, electric irons, toasters, and geysers that glows red-hot to produce heat called?', 'An electric heating element is made of high-resistivity Nichrome alloy (nickel-chromium) that resists oxidation at high temperatures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18e7c2ef-c2af-4942-a29d-60de7dbdc84f', 'An Heating Element (made of Nichrome alloy)', true, '8883da25-bf05-49e3-a88b-3f8cdbc9a72c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95424c28-f5d3-4476-900c-5f0c9c526e69', 'A Filament', false, '8883da25-bf05-49e3-a88b-3f8cdbc9a72c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32e0b938-7c3d-4a78-9090-5dbafd76aa2d', 'A Fuse wire', false, '8883da25-bf05-49e3-a88b-3f8cdbc9a72c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cf138a5-e42f-4d6b-b989-eac31f4d9052', 'A Switch', false, '8883da25-bf05-49e3-a88b-3f8cdbc9a72c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80f2a0e1-3b8c-4841-80fe-feadb5a87df1', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'Which high-melting-point metal is used to make the thin glowing FILAMENT inside an incandescent electric bulb?', 'Tungsten has an exceptionally high melting point (~3,422°C), glowing white-hot to emit light without melting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6e47740-c9fa-47fd-838d-103bcd936726', 'Tungsten (melting point ~3,422°C)', true, '80f2a0e1-3b8c-4841-80fe-feadb5a87df1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c83d0182-8dee-44df-af37-833bc71e041e', 'Copper', false, '80f2a0e1-3b8c-4841-80fe-feadb5a87df1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2628d10f-0950-4b60-98a5-473fd71211b5', 'Aluminum', false, '80f2a0e1-3b8c-4841-80fe-feadb5a87df1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('705346e7-4007-4614-9142-451290bd3530', 'Lead', false, '80f2a0e1-3b8c-4841-80fe-feadb5a87df1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d93784f-efba-4839-91ec-df8d39a3dcd2', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What is an Electric Fuse and what is its primary safety function in household electrical circuits?', 'An electric fuse prevents electrical fires and appliance damage by melting when current exceeds the rated safety threshold.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62de74e3-9e8a-4697-8a25-55717c5c9518', 'A safety device containing a low-melting-point wire that melts and breaks the circuit if excessive dangerous electric current flows through it', true, '9d93784f-efba-4839-91ec-df8d39a3dcd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc6da185-0b0e-4408-86a9-5e59498b4eac', 'A device to generate more electricity', false, '9d93784f-efba-4839-91ec-df8d39a3dcd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef5674a4-00f7-4671-b06c-61857c8e6bbe', 'A switch that makes bulbs brighter', false, '9d93784f-efba-4839-91ec-df8d39a3dcd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac716417-4ef5-4a9a-9215-02897cc7b9ff', 'A meter to measure voltage', false, '9d93784f-efba-4839-91ec-df8d39a3dcd2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9eb8d53e-94ea-4a7f-9d54-0f67f0e51af2', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What modern automatic safety switches are increasingly replacing traditional melting wire fuses in household electrical wiring?', 'MCBs automatically trip and switch OFF when current exceeds safe limits, and can easily be reset manually without replacing wires.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15cb4cda-c829-425e-b3a8-fdd9e150f39b', 'Miniature Circuit Breakers (MCBs)', true, '9eb8d53e-94ea-4a7f-9d54-0f67f0e51af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d08370a5-f83c-4580-8cd7-8f647e53d3bf', 'Transformers', false, '9eb8d53e-94ea-4a7f-9d54-0f67f0e51af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a97c8fc-fcb2-403b-b6cc-4619cbf20e64', 'Capacitors', false, '9eb8d53e-94ea-4a7f-9d54-0f67f0e51af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fb3c0fc-9531-4110-a26f-ac7db00ec962', 'Batteries', false, '9eb8d53e-94ea-4a7f-9d54-0f67f0e51af2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a2d817c-6354-462e-a59b-6420b0f20e86', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'Which Danish physicist discovered in 1820 that an electric current flowing through a wire creates a MAGNETIC FIELD that deflects a nearby magnetic compass needle?', 'Hans Christian Oersted discovered electromagnetism in 1820 when he noticed an electric current deflects a magnetic compass needle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73b11eba-a999-4e65-9377-4415e4ac6cf5', 'Hans Christian Oersted', true, '9a2d817c-6354-462e-a59b-6420b0f20e86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('096f42b0-53a1-4edd-8c64-f04eaa5e79bb', 'Michael Faraday', false, '9a2d817c-6354-462e-a59b-6420b0f20e86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c92cdcb1-7c1e-4125-b389-b423be15ca12', 'Thomas Edison', false, '9a2d817c-6354-462e-a59b-6420b0f20e86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43fed06e-0a04-45e4-b7b7-ba1a17443056', 'James Watt', false, '9a2d817c-6354-462e-a59b-6420b0f20e86');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb42b6ae-008a-42e3-9562-b3255939243d', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'A coil of insulated wire wound around an iron core that acts as a magnet only when electric current flows through it is called an:', 'An electromagnet is a temporary magnet whose magnetic field is generated and controlled by an electric current in its coil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64bf81cf-cc51-42c5-bb62-1e2a7c74fd80', 'Electromagnet', true, 'cb42b6ae-008a-42e3-9562-b3255939243d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3aa18d9-0f84-4def-acb6-bcb0a546deaf', 'Permanent Bar Magnet', false, 'cb42b6ae-008a-42e3-9562-b3255939243d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71375b17-8f95-4a6a-921c-9f67b5cf6c89', 'Electric Cell', false, 'cb42b6ae-008a-42e3-9562-b3255939243d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b26adb92-15ba-4f1d-9829-13af2985d447', 'Electric Fuse', false, 'cb42b6ae-008a-42e3-9562-b3255939243d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4bbba75-3384-4a0c-9e63-b67d2e81248b', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What happens to the magnetic field of an Electromagnet when the electric current is switched OFF?', 'Electromagnets are temporary magnets made of soft iron cores that lose magnetic properties the moment current stops flowing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ca16e42-5cfb-4b8c-9a4f-019d371e3b58', 'It loses its magnetism almost immediately', true, 'c4bbba75-3384-4a0c-9e63-b67d2e81248b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6815d673-091a-4637-9f90-656bf4f69ee6', 'It becomes twice as strong', false, 'c4bbba75-3384-4a0c-9e63-b67d2e81248b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('751e82b4-6239-4a78-88bb-4aaa5c726bbc', 'It explodes', false, 'c4bbba75-3384-4a0c-9e63-b67d2e81248b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c8ff396-04d7-44c5-8f2e-7963be9bd75f', 'It becomes a permanent magnet forever', false, 'c4bbba75-3384-4a0c-9e63-b67d2e81248b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('907d14bd-6f96-40fb-bcc8-4d4c5dba8e6f', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'Which everyday electromechanical acoustic device operates using an Electromagnet, a soft iron armature, a striker hammer, and a brass gong?', 'An electric bell uses an electromagnet that attracts an iron armature, striking the gong and breaking the contact in a rapid make-and-break cycle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e31ad03-050d-49fc-b9d4-8d764ee8287e', 'An Electric Bell', true, '907d14bd-6f96-40fb-bcc8-4d4c5dba8e6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a60457d-b5dc-4f2c-99f2-e99b077033ee', 'A Flashlight', false, '907d14bd-6f96-40fb-bcc8-4d4c5dba8e6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c838fff-531e-4a06-9b84-77d160a75a26', 'An Electric Heater', false, '907d14bd-6f96-40fb-bcc8-4d4c5dba8e6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('269a023f-c19f-452b-a9f9-5c122405443b', 'An Electric Iron', false, '907d14bd-6f96-40fb-bcc8-4d4c5dba8e6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a255666-3698-479c-9959-0b250da1694a', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'Which standard certification mark issued by the Bureau of Indian Standards (BIS) should consumers look for on electrical appliances to ensure quality and safety?', 'The ISI certification mark guarantees that electrical appliances conform to national safety, efficiency, and quality standards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('206b241a-bb92-417e-8caa-0dd0380bcef6', 'ISI Mark', true, '3a255666-3698-479c-9959-0b250da1694a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c96eaa5-726b-4c59-a625-48a8d2e4ac29', 'Agmark', false, '3a255666-3698-479c-9959-0b250da1694a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e0096ce-4d0f-4a46-a0ab-37510f631961', 'FSSAI Mark', false, '3a255666-3698-479c-9959-0b250da1694a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36135654-385f-47f3-8192-1a3e31643072', 'Hallmark', false, '3a255666-3698-479c-9959-0b250da1694a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc4c4770-44ca-490e-88a0-18778fe7394f', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Why are energy-efficient LED (Light Emitting Diode) bulbs and CFLs preferred over traditional incandescent filament bulbs?', 'LEDs use solid-state electroluminescence, consuming 80–90% less energy than resistive incandescent filament bulbs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8dc0544-5133-4d6c-9a39-4e6118c1f603', 'Incandescent bulbs waste a large proportion of electrical energy as unwanted Heat, whereas LEDs convert almost all electrical energy directly into Light without heat wastage', true, 'bc4c4770-44ca-490e-88a0-18778fe7394f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa5581c7-b915-4031-ba0f-6e45b9b4e6a5', 'Incandescent bulbs are too bright for human eyes', false, 'bc4c4770-44ca-490e-88a0-18778fe7394f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e26460ea-f0ba-4f38-a1c8-cb8e0a9d1f1a', 'LED bulbs do not require any electricity', false, 'bc4c4770-44ca-490e-88a0-18778fe7394f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42cb4866-026e-4045-a4b0-af1e13aaf14c', 'LED bulbs last only for one day', false, 'bc4c4770-44ca-490e-88a0-18778fe7394f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0638798a-a5e4-4693-9574-5979e2f24c61', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'How should cells be arranged in a battery holder so that electric current flows properly?', 'Series electrochemical connection requires alternating polarities (+ to -) to add individual cell voltages together.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d8ab279-d679-42b4-b713-f804bff84495', 'The POSITIVE (+) terminal of one cell must be connected to the NEGATIVE (-) terminal of the next cell in a continuous series', true, '0638798a-a5e4-4693-9574-5979e2f24c61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37abc82e-4247-4cff-8e40-dbec69c8b67a', 'Positive terminal must connect to positive terminal', false, '0638798a-a5e4-4693-9574-5979e2f24c61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1242c137-e5e9-4a95-bfdc-b82aa4fc88ee', 'Negative terminal must connect to negative terminal', false, '0638798a-a5e4-4693-9574-5979e2f24c61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f82c6f-bbcd-4a38-8041-1e936e99766b', 'Cells can be placed in any random direction', false, '0638798a-a5e4-4693-9574-5979e2f24c61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29762d0a-1198-48de-90d7-e347d501ed4e', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What two dangerous electrical fault conditions cause an excessive, surging current to flow through domestic wiring, triggering fires or blowing fuses?', 'Short circuits bypass load resistance (R ≈ 0, surging I) and overloading draws additive current exceeding cable ampacity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f5360eb-86c5-4af6-a81b-f2d14f3b1eb3', '1. Short Circuit (direct contact between live and neutral wires due to damaged insulation) ; and 2. Overloading (connecting too many high-power appliances to a single socket)', true, '29762d0a-1198-48de-90d7-e347d501ed4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e47e777-ed4e-45a2-b628-24f16b398593', 'High room temperature and heavy rain', false, '29762d0a-1198-48de-90d7-e347d501ed4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62dbaec9-736a-4021-a5d0-bbe0b157e9e3', 'Turning on light bulbs during the day', false, '29762d0a-1198-48de-90d7-e347d501ed4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c22a5566-0586-421e-9917-8da7a6114d6b', 'Using long wires', false, '29762d0a-1198-48de-90d7-e347d501ed4e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30e6f380-7862-4bd5-80c4-8136e2043d40', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'How can the magnetic strength of a simple solenoid Electromagnet be significantly INCREASED?', 'Magnetic flux density B is directly proportional to turn density and current (B = μ·n·I) around a ferromagnetic soft iron core.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72c5a59a-8abd-4a8b-9457-047a1b1c5b95', 'By increasing the number of turns of the insulated wire coil, and by increasing the magnitude of electric current flowing through it', true, '30e6f380-7862-4bd5-80c4-8136e2043d40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fb8d041-0808-4c97-a590-cb5e0ed8e323', 'By using a plastic core instead of iron', false, '30e6f380-7862-4bd5-80c4-8136e2043d40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d8ac9af-46ca-4adb-8d13-1401f4540bc4', 'By reducing the number of turns to one', false, '30e6f380-7862-4bd5-80c4-8136e2043d40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e37fa23-a1df-4c1a-b882-2e955568e34b', 'By cooling the wire in ice', false, '30e6f380-7862-4bd5-80c4-8136e2043d40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7420d80-b5e9-453f-bff7-b621c28ea1a9', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Why should an ordinary copper wire NEVER be used as a replacement fuse wire in a fuse carrier?', 'Copper has a high melting point (~1,085°C), defeating the safety purpose of a calibrated low-melting-point lead-tin eutectic fuse wire.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f25d66b1-fda2-41ff-af2d-c2f0d8d2fffb', 'Copper has a very high melting point and low resistance; it will NOT melt during heavy current overloads, causing house wires to catch fire and burn appliances', true, 'b7420d80-b5e9-453f-bff7-b621c28ea1a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8985a8ad-65f4-4124-b54e-460ba248c8f4', 'Copper does not conduct electricity', false, 'b7420d80-b5e9-453f-bff7-b621c28ea1a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3d0c838-d679-43a6-86b1-041c21702cea', 'Copper attracts lightning', false, 'b7420d80-b5e9-453f-bff7-b621c28ea1a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e276475-924a-4d9a-a1c8-9544b7bd6c6a', 'Copper turns into water', false, 'b7420d80-b5e9-453f-bff7-b621c28ea1a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf8755cb-bdf6-4a86-b86e-0e2978706356', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'How does the ''Make-and-Break'' contact screw mechanism work in an Electric Bell?', 'The electromechanical contact interrupter self-oscillates: magnetic attraction breaks the circuit, spring restores contact, creating continuous ringing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7e3eba8-2021-4b70-911b-42bbcf94c9e6', 'When the electromagnet attracts the iron armature to strike the gong, it pulls the contact strip away from the screw, breaking the circuit; the electromagnet loses magnetism, the spring pulls the armature back, re-establishing contact to repeat the cycle rapidly', true, 'cf8755cb-bdf6-4a86-b86e-0e2978706356');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0f6ebff-9cd1-4632-83ca-1e775e10aa86', 'The bell is struck by hand', false, 'cf8755cb-bdf6-4a86-b86e-0e2978706356');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74c93e64-704c-409d-844d-3a478cdbc773', 'A motor rotates the bell', false, 'cf8755cb-bdf6-4a86-b86e-0e2978706356');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa1b43bc-a432-4eb8-9860-a2d3a2642890', 'The bell rings by sound waves', false, 'cf8755cb-bdf6-4a86-b86e-0e2978706356');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e3ea07e-0ace-428e-b53a-823451e79860', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Why are powerful industrial Electromagnets attached to giant cranes in junkyards and steel factories?', 'Heavy-duty lifting electromagnets switch magnetic hold instantaneously, revolutionizing scrap metal handling without mechanical hooks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcc5585a-0ca0-4cbe-9393-95f117f851c1', 'To effortlessly lift, move, and sort heavy scrap iron, steel plates, and magnetic debris by simply turning the electric current ON to pick up and OFF to drop', true, '8e3ea07e-0ace-428e-b53a-823451e79860');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33b5e106-c9e7-4e56-9090-8c073d6eb9c7', 'To weld cars together', false, '8e3ea07e-0ace-428e-b53a-823451e79860');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6387bc7-e9ca-4925-980f-801547c6b63e', 'To generate electricity from trash', false, '8e3ea07e-0ace-428e-b53a-823451e79860');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8128b2b-483c-4bdd-895e-a3fe95ab3bf1', 'To paint steel beams', false, '8e3ea07e-0ace-428e-b53a-823451e79860');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de71f065-7487-4264-a6a7-b74ed09949d4', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What is the medical application of tiny specialized Electromagnets in hospitals?', 'Eye surgeons use micro-electromagnets to non-invasively extract ferromagnetic foreign particles embedded in ocular tissues.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e2bf030-e7a6-4362-baad-cb28c8ae4623', 'Ophthalmic surgeons use miniature electromagnets to safely extract tiny accidental iron splinters from a patient''s eye', true, 'de71f065-7487-4264-a6a7-b74ed09949d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e53b7d7c-b88c-4d21-89b4-cda7fd6427ad', 'To heal broken bones', false, 'de71f065-7487-4264-a6a7-b74ed09949d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec66861a-fc91-4f16-b300-2190732736a9', 'To test blood sugar', false, 'de71f065-7487-4264-a6a7-b74ed09949d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e8c9adb-3d3b-4778-9ecb-7a7201d772c1', 'To measure body temperature', false, 'de71f065-7487-4264-a6a7-b74ed09949d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ab43e0c-a274-4505-90ec-7823a9898415', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What physical factors determine the amount of heat produced in a current-carrying wire according to Joule''s Heating Law?', 'Joule''s heat H = I²Rt depends on current squared (I²), resistance R (governed by material ρ, length L, and cross-section A), and time t.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c61b4d97-7a50-4ce1-a14f-d1ae7128bdb6', 'The Material of the wire (resistivity), its Length, its Thickness (cross-sectional area), and the Duration of time current flows through it (H ∝ I²Rt)', true, '0ab43e0c-a274-4505-90ec-7823a9898415');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f827d211-3e86-4441-8b74-79b6fab1b6da', 'The color of the wire only', false, '0ab43e0c-a274-4505-90ec-7823a9898415');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a01f0c-a1a6-4b0b-9806-2847814437ad', 'The atmospheric air pressure only', false, '0ab43e0c-a274-4505-90ec-7823a9898415');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adae62e1-6292-43d9-ae21-f35083e2afa9', 'The shape of the switch', false, '0ab43e0c-a274-4505-90ec-7823a9898415');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('202d1234-0c4e-4f93-ac1d-64e7507bfcde', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What happens when a magnetic compass is placed near an electric wire and the switch is turned ON?', 'Oersted effect: the concentric magnetic field lines induced by the current exert a torque on the compass magnetic dipole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a1fa9d6-5432-4b73-9fb1-7976f9a67e8e', 'The magnetic needle immediately deflects from its North-South alignment due to the magnetic field generated by the electric current', true, '202d1234-0c4e-4f93-ac1d-64e7507bfcde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7987a0f-b083-48f9-af0d-638f47d6feba', 'The compass needle spins forever like a fan', false, '202d1234-0c4e-4f93-ac1d-64e7507bfcde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c06d183-5147-49ea-8712-11477fdb5d98', 'The compass catches fire', false, '202d1234-0c4e-4f93-ac1d-64e7507bfcde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85fa8267-cb06-44e1-9f70-34cd0e443e87', 'Nothing happens to the compass', false, '202d1234-0c4e-4f93-ac1d-64e7507bfcde');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44c9b744-3bb0-46ae-a203-ba10caaaedba', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Why does the connecting copper wire in an electric circuit remain cool while the Nichrome element in an electric toaster glows bright red?', 'In a series circuit with constant current I, heat generation is directly proportional to resistance (H ∝ R); R_nichrome >> R_copper.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c45e36-9587-4ed3-8f68-d99a28e2760b', 'Copper has extremely low electrical resistance (producing negligible heat), whereas Nichrome has very high resistance and dissipates immense heat (H ∝ R)', true, '44c9b744-3bb0-46ae-a203-ba10caaaedba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c9b1282-e366-4693-b91c-6d90864e1fdf', 'Copper is kept in water', false, '44c9b744-3bb0-46ae-a203-ba10caaaedba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('008288a4-4b18-4c85-9faf-18a662c778e2', 'Nichrome is painted red', false, '44c9b744-3bb0-46ae-a203-ba10caaaedba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c536f6f-8046-40fc-80d7-1398fa2d866c', 'Copper has no current', false, '44c9b744-3bb0-46ae-a203-ba10caaaedba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87d7459a-d0f3-479a-857e-d10feb3454af', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What happens when the filament of an electric bulb breaks (burns out / gets ''fused'')?', 'A severed filament creates an open circuit (infinite resistance), arresting current flow through the bulb.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dc0d39c-64e9-46bf-ad05-f124e3c8da3b', 'The electrical circuit becomes OPEN (broken), current stops flowing, and the bulb cannot emit light', true, '87d7459a-d0f3-479a-857e-d10feb3454af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72cfe36d-a839-4808-b3cc-b022a84835dd', 'The bulb shines twice as bright', false, '87d7459a-d0f3-479a-857e-d10feb3454af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e56cc74-6df8-4924-a050-c89d91e2324f', 'The battery charges automatically', false, '87d7459a-d0f3-479a-857e-d10feb3454af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4c62244-b085-4d36-bf9d-64d00a2bf5b9', 'The bulb changes color to green', false, '87d7459a-d0f3-479a-857e-d10feb3454af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6461e3c3-73c8-49e2-b8c7-8d061f5d5f90', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Which of the following household appliances utilizes the HEATING effect of electric current?', 'Geysers, toasters, irons, and room heaters convert electrical energy into thermal energy via resistive Joule heating elements.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('826d8b9a-8acf-4a2d-94c7-83c6df8f06aa', 'Electric Geyser, Electric Toaster, Electric Iron, Room Heater', true, '6461e3c3-73c8-49e2-b8c7-8d061f5d5f90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3c356cc-8125-441e-985c-9a60e9886b63', 'Electric Fan, Mixer Grinder, Washing Machine', false, '6461e3c3-73c8-49e2-b8c7-8d061f5d5f90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65393f0a-9098-4ea0-928c-ade2e33fa05e', 'Radio, Television, Mobile phone', false, '6461e3c3-73c8-49e2-b8c7-8d061f5d5f90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bd1fb69-995f-4e86-8e95-cdb0ec6d8adc', 'Refrigerator, Air Conditioner', false, '6461e3c3-73c8-49e2-b8c7-8d061f5d5f90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('739bb207-7c3c-4971-aa17-4925790e1580', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Which of the following household appliances utilizes the MAGNETIC effect of electric current (Electric Motors)?', 'Electric motors in fans, washing machines, and pumps convert electrical energy into mechanical rotation via electromagnetic Lorentz forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fe64a95-18c5-439b-80b2-79163a399bf5', 'Electric Fan, Washing Machine, Mixer Grinder, Water Pump', true, '739bb207-7c3c-4971-aa17-4925790e1580');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356c7985-4edc-45e3-ba47-52a323a0cd0b', 'Electric Kettle, Immersion Rod, Electric Heater', false, '739bb207-7c3c-4971-aa17-4925790e1580');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88c3f742-ce14-468d-a8af-3b5462cff04f', 'Flashlight bulb, Candle, Lamp', false, '739bb207-7c3c-4971-aa17-4925790e1580');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7af0bacc-818f-4a53-ada8-731e27ba6dba', 'Electric Iron', false, '739bb207-7c3c-4971-aa17-4925790e1580');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('766312a0-0aa0-46a0-8a7d-5009c28b155c', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What is the function of a Switch (Key) in an electric circuit?', 'A switch mechanically bridges or opens circuit continuity to control current flow to electrical loads.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea45427d-5849-4749-a5a4-780484fb5753', 'It is a simple deliberate device used to either close (COMPLETE) or open (BREAK) the electric circuit at will', true, '766312a0-0aa0-46a0-8a7d-5009c28b155c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('595a15f8-2c77-4ef2-bab0-2e5700065f07', 'It generates electric voltage', false, '766312a0-0aa0-46a0-8a7d-5009c28b155c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8346831-13c9-4c09-afbb-34e7fc0daaf9', 'It changes AC into DC', false, '766312a0-0aa0-46a0-8a7d-5009c28b155c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0b8b3f4-309b-42c8-8e19-b6d6b805591f', 'It cools the wires', false, '766312a0-0aa0-46a0-8a7d-5009c28b155c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('845d188f-a8af-4a7e-997a-1c4692330204', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What is the core material traditionally used inside an electromagnet coil to achieve maximum temporary magnetic strength?', 'Soft iron possesses high magnetic permeability and low retentivity (coercivity), magnetizing strongly and demagnetizing instantly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30c73486-f326-4834-b76b-8184586772e9', 'Soft Iron (due to high magnetic permeability and low retentivity)', true, '845d188f-a8af-4a7e-997a-1c4692330204');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('612f90ea-45bb-47cc-9a2a-68e4136fe517', 'Hard Steel', false, '845d188f-a8af-4a7e-997a-1c4692330204');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56c1e8ff-44ec-4abf-9199-7b6bba82508d', 'Wood', false, '845d188f-a8af-4a7e-997a-1c4692330204');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef6c8ae1-3fb9-4f3e-9125-f4b91cc5920d', 'Glass', false, '845d188f-a8af-4a7e-997a-1c4692330204');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('949be86e-4919-4211-b23a-d6f25d932059', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0ffc532-cf09-48eb-bb26-8c56207f3136', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '949be86e-4919-4211-b23a-d6f25d932059');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a58b1b4d-400b-4996-8107-b2b0f9b281c5', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '949be86e-4919-4211-b23a-d6f25d932059');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09241896-a002-4be4-961a-11ea01f1fdae', '(A) is true, but (R) is false.', false, '949be86e-4919-4211-b23a-d6f25d932059');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39ccf692-35c7-4a42-85e3-e11f303acfab', '(A) is false, but (R) is true.', false, '949be86e-4919-4211-b23a-d6f25d932059');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0133ff51-e37a-4a0b-9ad7-33b23c83d522', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Spot the IMPOSTER in the following group of Electrical Components and their standard circuit symbols:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d6e76b6-2c76-43aa-9806-6b4704d2b745', 'Symbol 1', false, '0133ff51-e37a-4a0b-9ad7-33b23c83d522');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e768aed-b36f-49b1-adf0-24df3eae75f6', 'Symbol 2', false, '0133ff51-e37a-4a0b-9ad7-33b23c83d522');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02d30820-ebe2-4728-a855-678f357b826c', 'Symbol 3', false, '0133ff51-e37a-4a0b-9ad7-33b23c83d522');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23b45bd7-07b9-4f52-b53d-c74cf2b94616', 'Symbol 4 (The standard symbol for an electric bulb is a circle with a LOOPED FILAMENT inside, NOT a live burning fire)', true, '0133ff51-e37a-4a0b-9ad7-33b23c83d522');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e7845d6-d84a-4da7-9820-81c8f27f750a', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'If an electric iron draws a current of 5 A from a 220 V supply line and has an internal resistance of 44 Ω, calculate the amount of HEAT energy generated in 10 minutes (600 seconds):', 'H = I²Rt = (25)(44)(600) = 660,000 J = 660 kJ.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90e0e4b9-a2b1-4716-9a05-3a7c29f715e4', '660,000 Joules or 660 kJ (Heat H = I² × R × t = 5² × 44 × 600 = 25 × 44 × 600 = 1,100 × 600 = 660,000 J)', true, '0e7845d6-d84a-4da7-9820-81c8f27f750a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2698b51-46bf-48fa-b276-3ec9c6633c8c', '330,000 J', false, '0e7845d6-d84a-4da7-9820-81c8f27f750a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30bf80c5-2943-43b7-9930-ddd0efb8fddd', '550,000 J', false, '0e7845d6-d84a-4da7-9820-81c8f27f750a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b4a0268-f8e9-47bf-9267-e8f1eb58fb0f', '440,000 J', false, '0e7845d6-d84a-4da7-9820-81c8f27f750a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e32d6bb-e4ef-4c05-b41f-07a9c3a5a260', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Match Column I (Electrical Devices) with Column II (Core Physical Operating Principles):
(a) Electric Geyser   -> (i) High-resistance Joule heating effect in Nichrome
(b) Electric Bell     -> (ii) Rapid electromechanical make-and-break electromagnetic attraction
(c) Electric Fuse     -> (iii) Sacrificial thermal melting at rated ampacity threshold
(d) Magnetic Compass  -> (iv) Deflection by induced magnetic dipole torque around current', 'Geyser = Joule heating; Bell = make-break electromagnetism; Fuse = thermal melting; Compass = Oersted deflection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeabed00-e904-452e-81f9-a30fcd47a718', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '5e32d6bb-e4ef-4c05-b41f-07a9c3a5a260');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddc98a88-5c80-407c-be8a-522158a2a232', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '5e32d6bb-e4ef-4c05-b41f-07a9c3a5a260');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0a90f74-980c-4874-bfa1-6b27de2be955', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '5e32d6bb-e4ef-4c05-b41f-07a9c3a5a260');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da5b295a-e979-44c5-a15c-e85e5fa6d11a', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '5e32d6bb-e4ef-4c05-b41f-07a9c3a5a260');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b93bee0-f0e9-4e95-9799-e394f62c7ba9', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Read the statements regarding electromagnetism:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('765d2d6b-1f8c-44f0-842d-328fb8f51990', 'Statements 1 and 2 only', true, '0b93bee0-f0e9-4e95-9799-e394f62c7ba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a20bcdb9-2ada-46b9-89fa-5393a0f817bf', 'Statements 2 and 3 only', false, '0b93bee0-f0e9-4e95-9799-e394f62c7ba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f135c8e-add9-4166-96d8-a768bac2a439', 'Statements 1 and 3 only', false, '0b93bee0-f0e9-4e95-9799-e394f62c7ba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86359112-1afb-4e8b-b11c-32986bea6620', 'All Statements 1, 2, and 3', false, '0b93bee0-f0e9-4e95-9799-e394f62c7ba9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf59e8dd-da5b-4d72-a602-aebd14d86f1f', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Why is an inert gas mixture (like Argon with Nitrogen) filled inside traditional incandescent glass light bulbs instead of ordinary air?', 'Inert argon/nitrogen atmosphere prevents high-temperature oxidation of tungsten and retards filament vaporization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5e6f3c0-0775-499b-91e1-11b051ddba87', 'Ordinary air contains Oxygen, which would instantly oxidize and burn up the white-hot Tungsten filament into smoke; inert Argon prevents oxidation and suppresses tungsten evaporation', true, 'bf59e8dd-da5b-4d72-a602-aebd14d86f1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0ba1b83-bbb7-4bae-9806-0899e735057a', 'To make the bulb lighter so it can float', false, 'bf59e8dd-da5b-4d72-a602-aebd14d86f1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15003a45-a366-4c95-bfb3-fe6132067ddf', 'Because argon is cheaper than air', false, 'bf59e8dd-da5b-4d72-a602-aebd14d86f1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c13c6392-5a5d-45aa-882c-0010b87f48e4', 'To produce colored sparks', false, 'bf59e8dd-da5b-4d72-a602-aebd14d86f1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d62baf91-3f32-4a6e-a006-175230fda327', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'How do Maglev (Magnetic Levitation) high-speed bullet trains use superconducting Electromagnets to travel at speeds exceeding 500 km/h?', 'Electromagnetic suspension (EMS) and linear synchronous propulsion eliminate mechanical wheel-rail friction in Maglev transit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4fa6aae-99d6-4fdc-a3cc-42dd68b07539', 'Powerful electromagnets create magnetic repulsion that levitates the train frictionless above the guideway track, propelling it forward with alternating linear electromagnetic fields', true, 'd62baf91-3f32-4a6e-a006-175230fda327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7de118b3-ed88-424c-af3c-7b6da6029b51', 'They burn coal in giant boilers', false, 'd62baf91-3f32-4a6e-a006-175230fda327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a000fb8-043a-42a7-b50d-bd4945b3a4d4', 'They have giant rubber wheels moved by wind', false, 'd62baf91-3f32-4a6e-a006-175230fda327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a95ea903-b0b3-4cb2-9c8d-fa3fb8be486e', 'They slide on ice tracks', false, 'd62baf91-3f32-4a6e-a006-175230fda327');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2013e416-8c6b-4d58-8dde-59859b900e88', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Consider four circuit configurations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2acfd2d-e585-41cd-93f3-254d2f02b7a3', 'Configurations 1, 2, and 4 only', true, '2013e416-8c6b-4d58-8dde-59859b900e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('782dab9b-f6a8-4a4c-b7d3-09a67f9edbee', 'Configuration 3 only', false, '2013e416-8c6b-4d58-8dde-59859b900e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8be46dbc-4863-4d7b-aa2a-45dd8392c0d8', 'Configurations 2 and 3 only', false, '2013e416-8c6b-4d58-8dde-59859b900e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c368b83e-5a61-407e-84bd-d7d8736a6515', 'All 1, 2, 3, and 4', false, '2013e416-8c6b-4d58-8dde-59859b900e88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a63e5b15-c61b-4c9f-8674-adf7b6160afe', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'What physical property distinguishes a Bimetallic Strip used in thermal thermostat switches and thermal MCBs?', 'Differential linear thermal expansion (α_brass > α_iron) forces mechanical curvature that trips electrical contacts in thermal overloads.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a29ec1c-8a9f-46cb-a98c-5af54558d92b', 'Two different metals (e.g. brass and iron) with different thermal expansion coefficients bonded together; differential expansion causes the strip to bend upon heating, breaking the circuit at a set temperature', true, 'a63e5b15-c61b-4c9f-8674-adf7b6160afe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73e8736e-7c99-4171-b1ee-de62e4c5cfaf', 'It produces electricity from light', false, 'a63e5b15-c61b-4c9f-8674-adf7b6160afe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('537f9403-1d8c-48dc-b4ef-694bbac644fc', 'It turns into liquid metal', false, 'a63e5b15-c61b-4c9f-8674-adf7b6160afe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acdecfac-7269-4e4c-8a4c-6456ddc46563', 'It magnetizes wood', false, 'a63e5b15-c61b-4c9f-8674-adf7b6160afe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96f487ea-275e-4c53-b9a4-4ffc8105fb5b', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Why does an electric heater element made of Nichrome (resistance ~50 Ω) glow red-hot, while the copper connecting cord (resistance ~0.05 Ω) supplying the exact same current remains completely cool to the touch?', 'Series current is uniform; thermal dissipation scales strictly with resistance (P = I²R), producing 1000× more heat in Nichrome.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d4fa3e-f472-42c2-848b-655a45bcf0c9', 'Because power dissipation P = I²R is 1,000 times greater in the Nichrome element than in the copper leads carrying identical series current', true, '96f487ea-275e-4c53-b9a4-4ffc8105fb5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97fe654a-2850-4487-b5af-c23d10ab5eff', 'Because copper is insulated with cold water', false, '96f487ea-275e-4c53-b9a4-4ffc8105fb5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb72566a-27ad-4b57-8d39-b894743c06d8', 'Because current only enters the Nichrome', false, '96f487ea-275e-4c53-b9a4-4ffc8105fb5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71cd128f-7b77-4103-89aa-5d40d1919801', 'Because Nichrome absorbs cold from the room', false, '96f487ea-275e-4c53-b9a4-4ffc8105fb5b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f86655e1-d524-4e1e-8252-4bc20f6e1a17', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'What is the function of the permanent magnet inside an acoustic Loudspeaker when combined with an electromagnetic Voice Coil?', 'Electrodynamic speakers translate variable AC audio currents into mechanical diaphragmatic acoustic vibrations via Lorentz forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b732b6e-e11b-4937-94d2-a1d363135bee', 'Audio electrical signals passing through the voice coil generate fluctuating magnetic fields that interact with the permanent magnet, rapidly vibrating the speaker cone to produce audible sound waves', true, 'f86655e1-d524-4e1e-8252-4bc20f6e1a17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4aa10fdb-476f-467d-985e-2735f3f38ebc', 'To keep the speaker cool', false, 'f86655e1-d524-4e1e-8252-4bc20f6e1a17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ae3ea56-debe-404b-8e9b-2c20146603f8', 'To store digital songs', false, 'f86655e1-d524-4e1e-8252-4bc20f6e1a17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3da6a494-e69b-4096-8028-e553bd98e72f', 'To filter radio stations', false, 'f86655e1-d524-4e1e-8252-4bc20f6e1a17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bb09623-8571-4b71-885a-24bd0eb6e0ca', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'What grand technological unification is established in Chapter 10 of NCERT Class 7 Science?', 'Chapter 10 unifies electro-thermal conversion, circuit schematic symbology, safety interruption, and foundational electromagnetism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95fb399b-0925-49b5-9a0c-58a60f9ce572', 'The profound transformation of electrical energy into thermal heat, radiant light, and controllable magnetic forces—underpinning the entire infrastructure of modern domestic appliances, electrical safety engineering, and electromechanical automation', true, '1bb09623-8571-4b71-885a-24bd0eb6e0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('050920ea-33bd-4683-9ccf-67ea6b207403', 'That electricity is dangerous and should never be used', false, '1bb09623-8571-4b71-885a-24bd0eb6e0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b39e67a-4ed6-42f5-955a-a93725896013', 'That magnets have no connection to electricity', false, '1bb09623-8571-4b71-885a-24bd0eb6e0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c25f582c-2bbf-47a1-8f81-dc6bb0bb603a', 'That all circuits must be powered by steam engines', false, '1bb09623-8571-4b71-885a-24bd0eb6e0ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8c49932-6111-4407-9dc9-7e240c967f1b', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'In an algebraic expression, a quantity that can take various numerical values is called a:', 'A variable is a letter or symbol that represents an unknown quantity capable of assuming different numerical values.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bca5860-23c7-4fd8-ac77-43f4a0fd751f', 'Variable (e.g. x, y, z, a, b)', true, 'e8c49932-6111-4407-9dc9-7e240c967f1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bead9be6-3093-4a79-a930-7ab0881dcdff', 'Constant', false, 'e8c49932-6111-4407-9dc9-7e240c967f1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85fe2b61-6681-490d-ba4f-02ff7956e52e', 'Coefficient only', false, 'e8c49932-6111-4407-9dc9-7e240c967f1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('972621c5-af58-4d1f-a283-59a73ddbfa9c', 'Exponent', false, 'e8c49932-6111-4407-9dc9-7e240c967f1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67212b4e-4edb-4bed-a864-a614941ca48c', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'A quantity in an algebraic expression that has a FIXED numerical value is called a:', 'A constant is a term with a fixed, unchangeable numeric value.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('530fc062-aafb-41de-90f2-2e6250dfe039', 'Constant (e.g. 4, -7, 100)', true, '67212b4e-4edb-4bed-a864-a614941ca48c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd5ed540-e9ae-4e63-b0af-a21ae46bd62c', 'Variable', false, '67212b4e-4edb-4bed-a864-a614941ca48c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2718dd4-7ea8-4cc9-8c43-f63b7d2eb36a', 'Literal coefficient', false, '67212b4e-4edb-4bed-a864-a614941ca48c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c3518a-296a-48cc-81c1-757fe65b801c', 'Degree', false, '67212b4e-4edb-4bed-a864-a614941ca48c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9538afc-502c-489b-af42-bb244cb8a5c8', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'What are the TERMS of the algebraic expression 4x² - 3xy + 7?', 'Terms are parts of an expression separated by addition or subtraction: 4x², -3xy, and 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7db634a9-2152-4e2f-aae6-0034960b3acd', '4x², -3xy, and 7', true, 'a9538afc-502c-489b-af42-bb244cb8a5c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3ef798f-3703-412d-93c9-360546a954f4', '4x, 3xy, and 7', false, 'a9538afc-502c-489b-af42-bb244cb8a5c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bd29989-d658-4e6e-b757-c0c72c5aa04b', '4, -3, and 7', false, 'a9538afc-502c-489b-af42-bb244cb8a5c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('987fff2b-e1e7-40a2-9216-31430b529bd3', 'x² and xy', false, 'a9538afc-502c-489b-af42-bb244cb8a5c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddd01d49-8f8e-4913-be73-e364213f9806', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'In the algebraic term -7xy², what is the NUMERICAL COEFFICIENT?', 'The numerical factor in a term is its numerical coefficient (-7).', NOW()) ON CONFLICT DO NOTHING;
