INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08348937-5c6c-4def-a3d4-deced2fc95e2', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'An algebraic expression containing exactly ONE single term (e.g. 7xy, -5x², 3) is called a:', 'A monomial is an algebraic expression consisting of a single term.', NOW()) ON CONFLICT DO NOTHING;
