INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa117f2a-0098-4d33-821a-b7d7829d3241', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'An algebraic expression containing exactly TWO unlike terms (e.g. a + b, 4l + 5m) is called a:', 'A binomial consists of exactly two non-zero unlike terms.', NOW()) ON CONFLICT DO NOTHING;
