INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41773f31-65ef-493e-bac9-c55b0691b138', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'An algebraic expression containing exactly THREE unlike terms (e.g. x + y + z, 2a - 3b + 5) is called a:', 'A trinomial contains exactly three non-zero unlike terms.', NOW()) ON CONFLICT DO NOTHING;
