INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('662f2f7f-fe91-4f6f-a9e8-e2f1822511a7', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'Terms that have the EXACT SAME algebraic variable factors and powers (e.g. 7x and -12x, or 3xy² and 8y²x) are called:', 'Like terms have identical variable components with matching exponents, differing only in numerical coefficients.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f46b3064-c006-42fc-9c3f-c33168f7d464', 'Like Terms', true, '662f2f7f-fe91-4f6f-a9e8-e2f1822511a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0a57f99-fdc4-4f3e-a7ff-ea1cfe7fe11c', 'Unlike Terms', false, '662f2f7f-fe91-4f6f-a9e8-e2f1822511a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d216f86-b243-40d9-8627-0ebc49db7baa', 'Constants', false, '662f2f7f-fe91-4f6f-a9e8-e2f1822511a7');
