INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09d62eb7-507e-47a0-8f59-488101b3e2bf', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'Simplify by combining like terms: 12m² - 9m + 5m - 4m² - 7m + 10:', '(12-4)m² + (-9+5-7)m + 10 = 8m² - 11m + 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f936a7bb-112f-4df3-8f63-8cee128972bb', '8m² - 11m + 10 ((12 - 4)m² + (-9 + 5 - 7)m + 10 = 8m² - 11m + 10)', true, '09d62eb7-507e-47a0-8f59-488101b3e2bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed05f8a4-8ca9-48e9-8fed-bdfbd674ef78', '16m² - 11m + 10', false, '09d62eb7-507e-47a0-8f59-488101b3e2bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff01b93c-6c55-417d-89c1-7ff384656e05', '8m² + 11m - 10', false, '09d62eb7-507e-47a0-8f59-488101b3e2bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73b27a31-9f3b-4881-a2f2-d1b6f8a0fa93', '8m² - 21m + 10', false, '09d62eb7-507e-47a0-8f59-488101b3e2bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('157acd82-926c-41d7-99fc-4a94b5ec6f0e', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'If m = 2, find the value of the algebraic expression 3m - 5:', '3(2) - 5 = 6 - 5 = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ad60ac0-9af5-4603-9912-a47552028e92', '1 (3 × 2 - 5 = 6 - 5 = 1)', true, '157acd82-926c-41d7-99fc-4a94b5ec6f0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e4fd9da-170f-4ae2-b08e-9f379612b0d2', '-1', false, '157acd82-926c-41d7-99fc-4a94b5ec6f0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8505d474-fed0-4aa1-8999-0ef82a69fb66', '5', false, '157acd82-926c-41d7-99fc-4a94b5ec6f0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b6a7b62-56da-4d41-81cf-9cc8c505fcfa', '6', false, '157acd82-926c-41d7-99fc-4a94b5ec6f0e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3777d032-fbf9-4363-a933-51a58e8afb4b', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'If x = -1, find the value of 2x² - x - 2:', '2(-1)² - (-1) - 2 = 2(1) + 1 - 2 = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e56967d-7fe2-40b7-beaf-fdcd470cbbea', '1 (2 × (-1)² - (-1) - 2 = 2 × 1 + 1 - 2 = 3 - 2 = 1)', true, '3777d032-fbf9-4363-a933-51a58e8afb4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b734d73-a277-46e5-bd89-d79e66276bdb', '-1', false, '3777d032-fbf9-4363-a933-51a58e8afb4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7da281bf-9bf1-4af0-bfec-11067e79885d', '3', false, '3777d032-fbf9-4363-a933-51a58e8afb4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('357ae50e-4880-4f5e-86f9-8ae3d701d0fc', '0', false, '3777d032-fbf9-4363-a933-51a58e8afb4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a90955d8-330e-4985-a956-517cac986a1d', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'Subtract -5y² from y²:', 'y² - (-5y²) = y² + 5y² = 6y².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ceaabfaa-4c5b-48e8-94b1-5de09d303512', '6y² (y² - (-5y²) = y² + 5y² = 6y²)', true, 'a90955d8-330e-4985-a956-517cac986a1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e29dd4e-eace-4147-a343-da2b7360fba3', '-4y²', false, 'a90955d8-330e-4985-a956-517cac986a1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('828837f4-8668-4961-aaaf-bbeb1598d8ee', '4y²', false, 'a90955d8-330e-4985-a956-517cac986a1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c525192d-83a4-4066-95e9-212b09d80d98', '-6y²', false, 'a90955d8-330e-4985-a956-517cac986a1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99eafe10-05aa-4f80-b792-b7d874f106f0', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Add the algebraic expressions: 7mn + 5, 12mn + 2, 9mn - 8, and -2mn - 3:', 'Sum of coefficients = (7+12+9-2)mn + (5+2-8-3) = 26mn - 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82fa2779-fd9a-4eca-9fb6-4584f6b7455a', '26mn - 4 ((7 + 12 + 9 - 2)mn + (5 + 2 - 8 - 3) = 26mn - 4)', true, '99eafe10-05aa-4f80-b792-b7d874f106f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c33d5e3-7428-4de9-b7f9-13063b121f47', '28mn - 4', false, '99eafe10-05aa-4f80-b792-b7d874f106f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4ad3382-8152-43e5-9290-0bdbd2e7b6ca', '26mn + 4', false, '99eafe10-05aa-4f80-b792-b7d874f106f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14d911ea-c11c-4bb1-962f-41b2e420d0df', '24mn - 6', false, '99eafe10-05aa-4f80-b792-b7d874f106f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9536821a-5ef5-4ea7-a828-2b963d38ff57', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Subtract 24ab - 10b - 18a from 30ab + 12b + 14a:', '(30-24)ab + (12+10)b + (14+18)a = 6ab + 22b + 32a.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5988ccb1-91fa-4398-ae3c-2abbb6ec4f84', '6ab + 22b + 32a ((30 - 24)ab + (12 - (-10))b + (14 - (-18))a = 6ab + 22b + 32a)', true, '9536821a-5ef5-4ea7-a828-2b963d38ff57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abeaed03-7099-497d-b667-7c2296d607fe', '6ab + 2b - 4a', false, '9536821a-5ef5-4ea7-a828-2b963d38ff57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5a5f43f-726a-4f23-ba8d-5481dcc6cd96', '54ab + 22b + 32a', false, '9536821a-5ef5-4ea7-a828-2b963d38ff57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f41a7a7-323b-4b05-8f83-3cf381e8a68c', '6ab + 22b - 4a', false, '9536821a-5ef5-4ea7-a828-2b963d38ff57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffae4457-1196-4bfd-9cd9-1179d9c32f19', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'What should be added to x² + xy + y² to obtain 2x² + 3xy?', '(2x² + 3xy) - (x² + xy + y²) = x² + 2xy - y².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3823ec3-28f5-40fa-8310-a100d43eab0e', 'x² + 2xy - y² ((2x² + 3xy) - (x² + xy + y²) = (2-1)x² + (3-1)xy - y² = x² + 2xy - y²)', true, 'ffae4457-1196-4bfd-9cd9-1179d9c32f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b26d56a-bd6f-428c-8243-689154c7928f', 'x² + 4xy + y²', false, 'ffae4457-1196-4bfd-9cd9-1179d9c32f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a10ab7a-c07f-4ec8-b882-8a4d10311650', '3x² + 4xy + y²', false, 'ffae4457-1196-4bfd-9cd9-1179d9c32f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc94c20a-cc3a-4a20-96da-65774d8e3bdf', '-x² - 2xy + y²', false, 'ffae4457-1196-4bfd-9cd9-1179d9c32f19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fee73780-50a8-4bfa-b384-aac0a68aa52a', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'What should be subtracted from 2a + 8b + 10 to get -3a + 7b + 16?', '(2a + 8b + 10) - (-3a + 7b + 16) = 5a + b - 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3022bae-9577-4b8f-9abf-98c05b110918', '5a + b - 6 ((2a + 8b + 10) - (-3a + 7b + 16) = (2+3)a + (8-7)b + (10-16) = 5a + b - 6)', true, 'fee73780-50a8-4bfa-b384-aac0a68aa52a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e56af447-e2dc-4889-93fd-f29943ad03ae', '-a + 15b + 26', false, 'fee73780-50a8-4bfa-b384-aac0a68aa52a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6df03a1-c049-4f01-9a25-a2aa8b115d66', '5a - b + 6', false, 'fee73780-50a8-4bfa-b384-aac0a68aa52a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e18a7fc4-ab3d-4030-8428-a4a0df505942', '-5a - b + 6', false, 'fee73780-50a8-4bfa-b384-aac0a68aa52a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bde3f08-8086-4e6c-85ea-be26a089d451', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'From the sum of 3x - y + 11 and -y - 11, subtract 3x - y - 11:', 'Sum = 3x - 2y. Result = (3x - 2y) - (3x - y - 11) = -y + 11.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7590559-d961-4a33-bb4a-4d10f1e320bf', '-y + 11 (Sum = 3x - 2y ; Subtracting: (3x - 2y) - (3x - y - 11) = -2y + y + 11 = -y + 11)', true, '1bde3f08-8086-4e6c-85ea-be26a089d451');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed52f160-6681-46ec-8126-aed9c687f32d', 'y + 11', false, '1bde3f08-8086-4e6c-85ea-be26a089d451');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43cccdd6-7445-4571-9e24-254de82425ad', '-y - 11', false, '1bde3f08-8086-4e6c-85ea-be26a089d451');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59078bdd-91e1-46c2-9907-b5c2ffb6e9f8', '6x - 3y', false, '1bde3f08-8086-4e6c-85ea-be26a089d451');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60c923fd-4452-478a-b223-17a88d19f7eb', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'If a = 2 and b = -2, find the value of a² + ab + b²:', '2² + 2(-2) + (-2)² = 4 - 4 + 4 = 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a627c67-ddba-41a4-910c-e66d44d53835', '4 (2² + (2 × -2) + (-2)² = 4 - 4 + 4 = 4)', true, '60c923fd-4452-478a-b223-17a88d19f7eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb80ea1c-9e5a-4e54-a047-51ede153c3ac', '0', false, '60c923fd-4452-478a-b223-17a88d19f7eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e1ed793-2884-4000-815f-1eb9647ad58e', '8', false, '60c923fd-4452-478a-b223-17a88d19f7eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b9c966a-6883-485c-868d-5df885549039', '12', false, '60c923fd-4452-478a-b223-17a88d19f7eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e936903-c32e-433f-b79a-8e8397d272e7', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'If x = 0 and y = -1, find the value of 2x²y + 2xy² + xy:', '2(0)²(-1) + 2(0)(-1)² + (0)(-1) = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffbbd143-2e9d-4fa5-9e38-7c5b8cb33e29', '0 (Since x = 0, every product term containing x becomes 0: 0 + 0 + 0 = 0)', true, '5e936903-c32e-433f-b79a-8e8397d272e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b144bce7-4979-48bd-a4bc-850a8fa29c45', '-1', false, '5e936903-c32e-433f-b79a-8e8397d272e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98939358-6279-4ba7-8f88-6bf0705d1e97', '2', false, '5e936903-c32e-433f-b79a-8e8397d272e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fc95516-e1d0-45a4-99e5-2f82f4ece02b', '-2', false, '5e936903-c32e-433f-b79a-8e8397d272e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e79d1c49-9edf-4c3e-98e1-7ebb14d8eeb9', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Simplify the expression and find its value when x = 3:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a05b5bdf-030d-46a2-8f17-30a128eaee96', '39 (Expression = 2x² + 2xy - xy + 3 = 2x² + xy + 3 ; For x=3, y=2: 2(9) + (3×2) + 3 = 18 + 6 + 3 = 27 ... Wait: 2(3² + 3×2) + 3 - (3×2) = 2(9+6) + 3 - 6 = 30 + 3 - 6 = 27)', false, 'e79d1c49-9edf-4c3e-98e1-7ebb14d8eeb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eed595e-e3f9-4893-a598-31bfe51caf50', '27 (2(9+6) + 3 - 6 = 30 + 3 - 6 = 27)', true, 'e79d1c49-9edf-4c3e-98e1-7ebb14d8eeb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9caabd8d-6c59-40be-bf82-3e2a226c2c0d', '33', false, 'e79d1c49-9edf-4c3e-98e1-7ebb14d8eeb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8ff9794-1efd-4b47-b56a-f87b95b7f15c', '24', false, 'e79d1c49-9edf-4c3e-98e1-7ebb14d8eeb9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f23ba356-60e7-4ba3-afb0-2b0af52fd136', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'If the general nth term of a number sequence pattern is given by (3n + 1), find the 10th term and the 25th term of the sequence:', 'T₁₀ = 3(10) + 1 = 31. T₂₅ = 3(25) + 1 = 76.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e3947d4-c0f0-487f-b5f9-297a4587f4e2', '10th term = 31 ; 25th term = 76 (For n = 10: 3(10) + 1 = 31 ; For n = 25: 3(25) + 1 = 76)', true, 'f23ba356-60e7-4ba3-afb0-2b0af52fd136');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10775968-aa1e-484a-9260-a15dc39f36dd', '10th term = 30 ; 25th term = 75', false, 'f23ba356-60e7-4ba3-afb0-2b0af52fd136');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39d10b27-c4ac-4434-8d04-63a4a871a8e5', '10th term = 34 ; 25th term = 79', false, 'f23ba356-60e7-4ba3-afb0-2b0af52fd136');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d90cf53e-2c23-47c4-8ee4-ee91b6483541', '10th term = 29 ; 25th term = 74', false, 'f23ba356-60e7-4ba3-afb0-2b0af52fd136');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a713e303-ab40-48f7-b142-02f4cd4d36a6', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Find the algebraic expression for the PERIMETER of an equilateral triangle of side ''s'':', 'Perimeter of an equilateral triangle = 3 × side = 3s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('326161ec-adcd-456a-ab5d-2b6f9b83d2a2', '3s (Perimeter = s + s + s = 3s)', true, 'a713e303-ab40-48f7-b142-02f4cd4d36a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f5b3879-b314-41c7-bfd2-d83aba297baf', 's³', false, 'a713e303-ab40-48f7-b142-02f4cd4d36a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24d84fa8-41c0-454c-8421-e351e6ba3502', '3 + s', false, 'a713e303-ab40-48f7-b142-02f4cd4d36a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76fb4b79-c02f-4b15-b818-1531282ca09e', 's² / 3', false, 'a713e303-ab40-48f7-b142-02f4cd4d36a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c14e8085-aeec-4280-9512-113b630c447a', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'What is the tree diagram factor representation of the term -ab + 2b² - 3a²?', 'Tree factor breakdown: -ab → (-1, a, b); 2b² → (2, b, b); -3a² → (-3, a, a).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec73d62a-322d-4874-89f6-b8d3b5b3b0a8', 'Terms: (-ab) with factors -1, a, b ; (2b²) with factors 2, b, b ; (-3a²) with factors -3, a, a', true, 'c14e8085-aeec-4280-9512-113b630c447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b21cb011-f9e8-402f-92f4-092a77d86387', 'Terms: a, b, and 3', false, 'c14e8085-aeec-4280-9512-113b630c447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3cf1cd1-5464-4e0a-9eff-fa2e979af934', 'Terms: a²b²', false, 'c14e8085-aeec-4280-9512-113b630c447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dad912a7-7932-4fbf-8d1b-e76f4837ac64', 'Factors are only positive numbers', false, 'c14e8085-aeec-4280-9512-113b630c447a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c764bb70-da44-4c51-b3b8-d4478c3f4c9f', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Identify which pair consists of LIKE TERMS:', '14xy and 42yx are like terms because variable factors xy and yx are algebraically identical.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbfea2ed-d3d8-4a02-9748-14ea984f9d4d', '-29x and -29y are unlike ; 14xy and 42yx are LIKE TERMS (xy = yx by commutative law)', true, 'c764bb70-da44-4c51-b3b8-d4478c3f4c9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9003b616-ba19-48d3-b100-3a28a5c2b729', '1 and 100 are unlike', false, 'c764bb70-da44-4c51-b3b8-d4478c3f4c9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b64b8fa-afe3-4678-bde5-93d343edb62b', '4m²p and 4mp² are like', false, 'c764bb70-da44-4c51-b3b8-d4478c3f4c9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e48b0506-2d6d-4e88-8eab-b53ddcd100ff', '12xz and 12x²z² are like', false, 'c764bb70-da44-4c51-b3b8-d4478c3f4c9f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0056a5d4-7c90-40a4-9acf-957d122d8947', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Find the value of (2a - 2b - 4) - (a - b) when a = 3 and b = 2:', '(2a - a) - (2b - b) - 4 = a - b - 4 = 3 - 2 - 4 = -3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('979aa885-cc37-4d7d-a1ac-066eb2e00002', '-3 ((2a - a) - (2b - b) - 4 = a - b - 4 = 3 - 2 - 4 = -3)', true, '0056a5d4-7c90-40a4-9acf-957d122d8947');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb473e34-bae6-46cb-aaa6-1b703548b0ac', '-1', false, '0056a5d4-7c90-40a4-9acf-957d122d8947');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('438356c9-3076-424b-826a-aa0a288d1d5f', '3', false, '0056a5d4-7c90-40a4-9acf-957d122d8947');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c59c7bc6-777d-41b6-b722-c76df447258b', '-5', false, '0056a5d4-7c90-40a4-9acf-957d122d8947');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6d1d7cb-7a6e-4a7b-9194-4dad777941dc', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'If z = 10, find the value of z³ - 3(z - 10):', '10³ - 3(10 - 10) = 1000 - 0 = 1,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('165a3fed-465e-4247-a716-6f86d5ff8419', '1,000 (z³ - 3(z - 10) = 10³ - 3(10 - 10) = 1000 - 3(0) = 1,000)', true, 'a6d1d7cb-7a6e-4a7b-9194-4dad777941dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b005f41-016d-424e-b525-81dfe8d4e8ac', '970', false, 'a6d1d7cb-7a6e-4a7b-9194-4dad777941dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bf881f3-a8aa-4a63-b986-9e1b407493ab', '1,030', false, 'a6d1d7cb-7a6e-4a7b-9194-4dad777941dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42018ca8-fbe8-4e66-aeb7-8d9769401b74', '0', false, 'a6d1d7cb-7a6e-4a7b-9194-4dad777941dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da701f74-4554-49d1-b2a6-3af8e05c8503', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'What is the degree of the term 5x²y³?', 'Degree of a monomial term is the sum of exponents of its variable factors: 2 + 3 = 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0b36661-cabd-4c2c-a712-0bdffe4d95b4', '5 (Sum of exponents of variables = 2 + 3 = 5)', true, 'da701f74-4554-49d1-b2a6-3af8e05c8503');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1526ffe7-0e4b-4916-9f74-8ea572347e40', '6', false, 'da701f74-4554-49d1-b2a6-3af8e05c8503');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('520efb7d-ee8b-440b-8e8a-5edab46f76b1', '2', false, 'da701f74-4554-49d1-b2a6-3af8e05c8503');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('228cbc1b-c799-4cf9-af69-76c56984908e', '3', false, 'da701f74-4554-49d1-b2a6-3af8e05c8503');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7a79097-3e9d-4a46-82b4-d3a9b45f1eb6', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Write the algebraic expression for: ''Sum of numbers a and b subtracted from their product'':', 'Product = ab; Sum = (a + b). Subtraction of sum from product = ab - (a + b).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d950d36-779a-43a9-82ba-9679b738d235', 'ab - (a + b)', true, 'a7a79097-3e9d-4a46-82b4-d3a9b45f1eb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('745e870e-ab81-4b47-b168-1caf84c65230', '(a + b) - ab', false, 'a7a79097-3e9d-4a46-82b4-d3a9b45f1eb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74f5b7df-d6c5-4639-ab85-78a64503019c', 'ab + (a + b)', false, 'a7a79097-3e9d-4a46-82b4-d3a9b45f1eb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24097a98-ca4e-4e18-bdff-3b9146374d21', 'ab / (a + b)', false, 'a7a79097-3e9d-4a46-82b4-d3a9b45f1eb6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5449768c-369d-46eb-855c-3199255c4e1a', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c50b4f1-eb21-4a2e-a7a8-d718e7b014f8', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '5449768c-369d-46eb-855c-3199255c4e1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d35d220a-07ae-49ec-9d6d-89e1db0f7b1c', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '5449768c-369d-46eb-855c-3199255c4e1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56b905cf-1c06-4640-b3c6-ddf025103001', '(A) is true, but (R) is false.', false, '5449768c-369d-46eb-855c-3199255c4e1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c71bd9bb-34b5-44bb-9887-8c2c40ff318e', '(A) is false, but (R) is true.', false, '5449768c-369d-46eb-855c-3199255c4e1a');
