INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7930f577-b816-4f24-99bd-7e4afd8b206b', 'Expression 1', false, 'f87e3a31-9d3c-4830-842e-2d62c73f7763');
