INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d992bd1-524e-4933-8b9b-a462ee190fb1', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'If 2x² + x - a = 5 for x = 0, what is the value of ''a''?', '0 + 0 - a = 5 → -a = 5 → a = -5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24617f29-5dc1-4811-847e-7b280ecd3d87', '-5 (Substitute x = 0: 2(0)² + (0) - a = 5 ⇒ -a = 5 ⇒ a = -5)', true, '7d992bd1-524e-4933-8b9b-a462ee190fb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbbcaff2-4e3a-49c9-9744-a3c6bc08a548', '5', false, '7d992bd1-524e-4933-8b9b-a462ee190fb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68b56fd4-654d-46d9-ad29-fe220aeef392', '0', false, '7d992bd1-524e-4933-8b9b-a462ee190fb1');
