INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('856c29fd-856f-4fff-9e50-1555b9b6cb41', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Match Column I (Algebraic Word Statements) with Column II (Exact Algebraic Expressions):
(a) One-fourth of the product of p and q -> (i) 1/4 pq (or pq/4)
(b) Number 5 added to 3 times product of m & n -> (ii) 3mn + 5
(c) Product of y and z subtracted from 10 -> (iii) 10 - yz
(d) Number x multiplied by itself and added to y² -> (iv) x² + y²', '1/4 pq; 3mn + 5; 10 - yz; x² + y².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba309166-f3a2-42b5-ae43-22535e1a8456', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '856c29fd-856f-4fff-9e50-1555b9b6cb41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27cf4549-913d-4258-a37c-f5a86ac53c03', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '856c29fd-856f-4fff-9e50-1555b9b6cb41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb567cde-22e3-47ad-b83d-ad906d1d1ac4', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '856c29fd-856f-4fff-9e50-1555b9b6cb41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7b81c3c-e408-45ea-9b99-5dc31abc5de3', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '856c29fd-856f-4fff-9e50-1555b9b6cb41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88a708d0-0068-48c1-94a2-5f28394f4664', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Read the statements regarding algebraic rules:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('935a256c-7d00-44f9-9b62-ed6e483b6a8c', 'Statements 1 and 2 only', true, '88a708d0-0068-48c1-94a2-5f28394f4664');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('690cee77-7fb6-4ae0-84c6-70237ea8ed73', 'Statements 2 and 3 only', false, '88a708d0-0068-48c1-94a2-5f28394f4664');
