INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40ffd2bd-539d-439a-92df-975bfd4a8f25', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Simplify the complex algebraic expression:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ff68ca3-99f6-4f47-88ee-a78701cac46b', '4x² - 2x + 1 (3x² - [2x - x² + 4] + 5 = 3x² - 2x + x² - 4 + 5 = 4x² - 2x + 1)', true, '40ffd2bd-539d-439a-92df-975bfd4a8f25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2509d5ac-0844-4c28-befc-59768392552f', '2x² - 2x + 9', false, '40ffd2bd-539d-439a-92df-975bfd4a8f25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39522e54-b523-44ee-80a2-37bf0137af06', '4x² + 2x - 1', false, '40ffd2bd-539d-439a-92df-975bfd4a8f25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b32850e8-7818-4100-bcde-009eb86b795b', '3x² - 2x + 1', false, '40ffd2bd-539d-439a-92df-975bfd4a8f25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ff942a8-ef2d-4559-be1d-1d793cbc6990', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'If A = 3x² - 4x + 1, B = 5x² + 3x - 8, and C = 4x² - 7x + 3, find the expression (A + B - C):', '(3+5-4)x² + (-4+3+7)x + (1-8-3) = 4x² + 6x - 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96e24e9c-d9b2-4bf2-99b8-c131a84ffc0e', '4x² + 6x - 10 ((3 + 5 - 4)x² + (-4 + 3 - (-7))x + (1 - 8 - 3) = 4x² + 6x - 10)', true, '2ff942a8-ef2d-4559-be1d-1d793cbc6990');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('869b92cf-7440-4b60-b219-e355179d3ea6', '4x² - 8x + 6', false, '2ff942a8-ef2d-4559-be1d-1d793cbc6990');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b3f7b90-f2e6-4d03-91cf-247cd4084138', '12x² - 8x - 4', false, '2ff942a8-ef2d-4559-be1d-1d793cbc6990');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3658f9b7-cd21-4316-b88b-32bf6ef193da', '4x² + 6x + 10', false, '2ff942a8-ef2d-4559-be1d-1d793cbc6990');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('540eae71-808c-4bfc-9a49-002ab6ee5473', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'A digital digit display uses matchsticks to form numbers. The number of matchsticks required to form ''n'' repeated digits of the numeral ''8'' follows the formula (5n + 1). How many matchsticks are needed to form 12 digits of ''8''?', 'Number of matchsticks = 5(12) + 1 = 61.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c64dd5e-2871-44a6-8a27-5e7cdab363e5', '61 matchsticks (For n = 12: 5(12) + 1 = 60 + 1 = 61 matchsticks)', true, '540eae71-808c-4bfc-9a49-002ab6ee5473');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('984a66b1-83d8-48ae-aa46-e02f4145daa8', '60 matchsticks', false, '540eae71-808c-4bfc-9a49-002ab6ee5473');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0535e37f-3f23-4ff6-a8a8-4524f9bdeb1a', '65 matchsticks', false, '540eae71-808c-4bfc-9a49-002ab6ee5473');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1977ddfb-0504-4f94-9ef0-5972f249b674', '72 matchsticks', false, '540eae71-808c-4bfc-9a49-002ab6ee5473');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91dd566c-a45c-4fac-acaa-fad3ddcba978', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'If x = -2, y = -1, and z = 3, evaluate the algebraic expression: x³ + y³ + z³ - 3xyz:', 'Since x + y + z = -2 + (-1) + 3 = 0, the algebraic identity x³ + y³ + z³ - 3xyz = (x+y+z)(x²+y²+z²-xy-yz-zx) = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47bd57f6-d5e5-4627-b345-d6113b245d4d', '0 (x³ = -8 ; y³ = -1 ; z³ = 27 ; Sum = 18 ; 3xyz = 3(-2)(-1)(3) = 18 ; Value = 18 - 18 = 0)', true, '91dd566c-a45c-4fac-acaa-fad3ddcba978');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df2ce677-84ee-4ac2-9c26-ee7c598c9c22', '36', false, '91dd566c-a45c-4fac-acaa-fad3ddcba978');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92c92758-f5db-4821-91b4-22476ae0c2db', '-18', false, '91dd566c-a45c-4fac-acaa-fad3ddcba978');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b04a2c91-cba8-4e9a-992a-aca934d523e4', '18', false, '91dd566c-a45c-4fac-acaa-fad3ddcba978');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f8aca71-3406-41dd-a34d-220440db7276', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'What is the coefficient of x²y in the algebraic expansion of 3(x²y - 2xy²) - 4(2x²y + 5xy²)?', '3x²y - 8x²y = -5x²y. The numerical coefficient is -5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a21711e3-4107-457f-afd8-7ea97d4f8802', '-5 (3x²y - 6xy² - 8x²y - 20xy² = (3 - 8)x²y - (6 + 20)xy² = -5x²y - 26xy² ; Coefficient of x²y is -5)', true, '6f8aca71-3406-41dd-a34d-220440db7276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c69a9b09-ea0e-432e-a677-0ea60416c18a', '5', false, '6f8aca71-3406-41dd-a34d-220440db7276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bb19fb3-b733-40b3-9d98-05d55c8a5963', '-26', false, '6f8aca71-3406-41dd-a34d-220440db7276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ed5db32-87fb-45ac-bc8e-60c38e3e534c', '-11', false, '6f8aca71-3406-41dd-a34d-220440db7276');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a6849c5-24fa-4a4e-bfe0-3fefe090b021', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'If p = -10, find the value of p² - 2p - 100:', '100 + 20 - 100 = 20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07727600-fdfb-40bb-a8d8-7a4d3d7accd8', '20 ((-10)² - 2(-10) - 100 = 100 + 20 - 100 = 20)', true, '9a6849c5-24fa-4a4e-bfe0-3fefe090b021');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39bc23c1-817b-4fc4-bccb-fe00e89ec908', '-20', false, '9a6849c5-24fa-4a4e-bfe0-3fefe090b021');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af49d74e-ef58-47d4-ad8f-a30b5d075a56', '0', false, '9a6849c5-24fa-4a4e-bfe0-3fefe090b021');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0e55a32-972c-4f4c-aef4-fa5f0fd80e65', '40', false, '9a6849c5-24fa-4a4e-bfe0-3fefe090b021');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2bd7f087-cc3e-419a-b591-02d5b79c7165', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Why are Algebraic Expressions considered the fundamental generalized language of modern science, algorithms, and computational modeling?', 'Algebra abstracts arithmetic into symbolic generalizations, enabling formulation of physical laws, algorithmic proofs, and variable parametric modeling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de19c1ec-e2bb-41e5-9b07-bd3e81ad8d6f', 'They allow generalized mathematical laws, geometric formulas, physical principles, and algorithmic patterns to be stated concisely and manipulated systematically for any arbitrary inputs', true, '2bd7f087-cc3e-419a-b591-02d5b79c7165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bc828ba-d8a1-4883-adf4-0274c7b95b43', 'Because letters take up less paper than numbers', false, '2bd7f087-cc3e-419a-b591-02d5b79c7165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dd41240-0e17-4ce3-961b-6e9128151b11', 'Because algebra eliminates the need for arithmetic', false, '2bd7f087-cc3e-419a-b591-02d5b79c7165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3136691-0417-4cd2-9f99-4337a7d6d8d4', 'Because computers only understand English letters', false, '2bd7f087-cc3e-419a-b591-02d5b79c7165');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7201c48-955b-4f70-8f05-7eb71ea854ac', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Where and approximately how many centuries ago did the sport of CRICKET originate as a rural English bat-and-ball game?', 'Cricket grew out of traditional English bat-and-ball folk pastimes played over 500 years ago in rural southeastern England.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7e80021-85ee-49c8-9f52-89e7942919ec', 'In England, over 500 years ago (16th century)', true, 'a7201c48-955b-4f70-8f05-7eb71ea854ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac925b1f-4716-4ffd-a388-ae030f078cd1', 'In Australia, 100 years ago', false, 'a7201c48-955b-4f70-8f05-7eb71ea854ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a0e8d18-399b-4e0d-b1e0-dda96aeea1a5', 'In India, during the Mughal era', false, 'a7201c48-955b-4f70-8f05-7eb71ea854ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62f1a3c7-ee72-428e-98d0-562a9800a47c', 'In America, in 1850', false, 'a7201c48-955b-4f70-8f05-7eb71ea854ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('990402a8-837f-4771-bcd9-53f4c502375a', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What was the shape of early cricket bats before the 1760s?', 'Early cricket was bowled underarm, so bats curved outwards at the base like hockey sticks to sweep the ball off the turf.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24093fe2-4436-4642-a774-4e2fae8ed587', 'Curved at the bottom like modern Hockey Sticks (to hit the ball bowled underarm along the ground)', true, '990402a8-837f-4771-bcd9-53f4c502375a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62dae141-eeb6-4cc9-8a20-111cf53e4a2b', 'Flat and straight like modern cricket bats', false, '990402a8-837f-4771-bcd9-53f4c502375a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('233f60f8-340a-42ac-960d-92d9c55ab2d1', 'Round like baseball bats', false, '990402a8-837f-4771-bcd9-53f4c502375a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b424cd3-ba30-4bfb-9c26-e67e4171a79c', 'Square shaped like wooden boards', false, '990402a8-837f-4771-bcd9-53f4c502375a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c67fcfd-7113-40b0-ab0c-a25c36b6ee67', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What is the fixed, standardized length of a cricket PITCH according to the official Laws of Cricket?', 'The Laws of Cricket specify pitch length precisely as 22 yards between the wickets, while ground boundary size remains variable.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b07a34c-d371-4bdf-91be-4dc0ed6decb6', '22 Yards (66 feet / 20.12 metres)', true, '3c67fcfd-7113-40b0-ab0c-a25c36b6ee67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27e22dfa-114c-49d5-98c2-68a5e265ca0e', '20 Yards', false, '3c67fcfd-7113-40b0-ab0c-a25c36b6ee67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e49db2b-7b14-4fcb-a2e5-c58d78269347', '25 Yards', false, '3c67fcfd-7113-40b0-ab0c-a25c36b6ee67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4168eb6-f141-41d0-bbc9-5179daee4d92', '30 Yards', false, '3c67fcfd-7113-40b0-ab0c-a25c36b6ee67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1bbd71f-74e5-4178-af80-0960b8ec9325', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Which famous London cricket club founded in 1787 became the supreme guardian and custodian of the Laws of Cricket?', 'The MCC (Marylebone Cricket Club), founded in 1787, framed the official Laws of Cricket and remains their custodian.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c97ff32b-6649-4560-840e-4e603e9ba31f', 'The Marylebone Cricket Club (MCC at Lord''s)', true, 'e1bbd71f-74e5-4178-af80-0960b8ec9325');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade54455-4399-4679-9846-a2ea9f30cc1a', 'The Hambledon Club', false, 'e1bbd71f-74e5-4178-af80-0960b8ec9325');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77dee177-755f-48df-a976-d7940c1ba4ac', 'The Melbourne Cricket Club', false, 'e1bbd71f-74e5-4178-af80-0960b8ec9325');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d8aa4cd-34f5-46e8-85f3-36289e47599a', 'The Surrey Club', false, 'e1bbd71f-74e5-4178-af80-0960b8ec9325');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dc0c10c-9002-4989-aa9a-9eec71e07589', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Which Indian community founded the FIRST Indian cricket club in Bombay (The Oriental Cricket Club) in 1848?', 'The Zoroastrian Parsi community of Bombay established the Oriental Cricket Club in 1848, pioneering Indian cricket.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90ab0c66-de36-4bb4-b1f0-d352753af56a', 'The Parsi Community', true, '4dc0c10c-9002-4989-aa9a-9eec71e07589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2cb54da-9490-4db8-ad95-10b04c9cd433', 'The Gujarati Community', false, '4dc0c10c-9002-4989-aa9a-9eec71e07589');
