INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f57bf9b-76c9-4c3e-8004-b420ade3059a', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'In what year did India play its first official Test match in England at Lord''s?', 'India played its inaugural Test match against England at Lord''s in June 1932.', NOW()) ON CONFLICT DO NOTHING;
