INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad8e4e48-1e01-4327-afd5-a4963131b98d', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What natural, pre-industrial materials are traditional cricket bat and ball made from even today?', 'Unlike other modern games, cricket''s bat and ball equipment remains hand-crafted from natural timber willow, cane, cork, and leather.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a8d9ac8-a824-4d9e-8a86-101185ecf656', 'Bat from Willow wood, cane, and twine ; Ball from leather, cork, and twine', true, 'ad8e4e48-1e01-4327-afd5-a4963131b98d');
