INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08934ab8-3be2-437b-aece-9a0ad47a0e35', 'Glass and fiber', false, 'ad8e4e48-1e01-4327-afd5-a4963131b98d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bca48156-4e82-4528-a60e-4dfca3bff8ca', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Which Australian television tycoon revolutionized modern cricket in 1977 by launching ''World Series Cricket'' with colored clothes, white balls, and day-night matches?', 'Kerry Packer signed the world''s best cricketers in 1977, transforming cricket into a televised spectacle with floodlit day-night games and colorful uniforms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb643f2b-1b5e-4899-b781-d0cae8449dee', 'Kerry Packer', true, 'bca48156-4e82-4528-a60e-4dfca3bff8ca');
