INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3da9156a-1579-42e0-9920-e89794651bbc', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Which country won the historic 1983 Cricket World Cup by defeating the mighty West Indies at Lord''s, transforming cricket into a national passion in India?', 'Kapil Dev''s ''Kapil''s Devils'' stunned the two-time champion West Indies at Lord''s on 25 June 1983, igniting modern Indian cricket mania.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1790f224-9413-43bc-80d1-535a58be00cd', 'India (captained by Kapil Dev)', true, '3da9156a-1579-42e0-9920-e89794651bbc');
