INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fcc4412-bf1a-4657-99c3-b76dec800062', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What is unique about the DURATION of a Test match in cricket compared to all other modern team sports?', 'Cricket is unique among modern sports: Test matches span 5 days (up to 30 hours of play) and can legitimately conclude in a draw.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbedc518-6a11-4bee-b32e-d292968e96ee', 'A Test match can last for FIVE FULL DAYS and can still end in a DRAW without a winner', true, '5fcc4412-bf1a-4657-99c3-b76dec800062');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a91c6df0-4a48-4a74-8da7-c295c6cf0673', 'It lasts only for 90 minutes', false, '5fcc4412-bf1a-4657-99c3-b76dec800062');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b6119ff-e4a1-4d1f-9d93-edfc9c2f1abb', 'It is played over one hour', false, '5fcc4412-bf1a-4657-99c3-b76dec800062');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d664a54-8ff6-4223-b1e0-32ace049e0c5', 'It never ends', false, '5fcc4412-bf1a-4657-99c3-b76dec800062');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac3f0f6b-34de-488d-a9e1-f0cd33908e5f', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What modern protective synthetic equipment was introduced to cricket only after the invention of vulcanized rubber in the 19th century?', 'Vulcanized rubber enabled the invention of padded batting gloves (1848) and protective leg-guard pads, followed by synthetic helmets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4edadca9-c71c-441c-84b7-59e4fad50ad2', 'Pads (Leg-guards) and Batting Gloves', true, 'ac3f0f6b-34de-488d-a9e1-f0cd33908e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d1d2f8-b7e4-4d22-9e4b-5aea8574d612', 'Wooden Wickets', false, 'ac3f0f6b-34de-488d-a9e1-f0cd33908e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('756b63d0-e169-4e6a-a46b-f559b130211f', 'Leather Ball', false, 'ac3f0f6b-34de-488d-a9e1-f0cd33908e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09e27642-9098-4e3b-b29b-56fe999adeab', 'Willow Bat', false, 'ac3f0f6b-34de-488d-a9e1-f0cd33908e5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5c5df7c-c9c8-4040-882b-f4bc7b5b7783', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'How did the introduction of pitching the ball through the air (instead of rolling it on the ground) in the 1760s transform cricket batting and bowling?', 'Airborne bowling introduced swing, seam, and deception in flight, prompting the invention of straight willow bats for precise defensive strokeplay.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ee9b45d-1b88-419b-b5a0-fbc7540c19b4', 'Bowlers gained the ability to generate curved swing and spin in the air, forcing batsmen to replace curved hockey-style bats with straight, flat bats for timing and defense', true, 'f5c5df7c-c9c8-4040-882b-f4bc7b5b7783');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34ada2ab-99ea-4d16-9ce3-7a2e45ea1d21', 'Batsmen started using baseball bats', false, 'f5c5df7c-c9c8-4040-882b-f4bc7b5b7783');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('377997f5-36c7-4a88-a9ed-27c46ba39b12', 'Bowlers were forced to throw the ball like a stone', false, 'f5c5df7c-c9c8-4040-882b-f4bc7b5b7783');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51a0efd1-5998-4de5-a2d6-602020130d67', 'The pitch was made round', false, 'f5c5df7c-c9c8-4040-882b-f4bc7b5b7783');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b852c3d-0fab-45dd-8f66-ef56289e3bb9', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What was the social distinction between ''GENTLEMEN'' (Amateurs) and ''PLAYERS'' (Professionals) in historic English cricket?', 'Aristocratic class hierarchy: Gentlemen (unpaid amateur batsmen/captains) vs Players (hired working-class professional bowlers).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1da2dd0-1f1f-45df-b46b-b628b6cdb29b', 'Gentlemen were wealthy aristocratic aristocrats who played for leisure and honor without pay ; Players were working-class men paid wages to bowl and field', true, '3b852c3d-0fab-45dd-8f66-ef56289e3bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0deba758-9aed-466f-98e5-efe7454b8aed', 'Gentlemen were bowlers and Players were umpires', false, '3b852c3d-0fab-45dd-8f66-ef56289e3bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd3aea57-8136-4538-9231-013d15295a15', 'Gentlemen played only in winter', false, '3b852c3d-0fab-45dd-8f66-ef56289e3bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29390215-1dee-4597-8832-43a1343d9e80', 'There was no social distinction', false, '3b852c3d-0fab-45dd-8f66-ef56289e3bb9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ada4340b-17bc-4c88-b7a6-0d83e9574901', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'Why does the shape and boundary size of cricket grounds vary so widely across the world (e.g. oval Melbourne vs round Chepauk), unlike football pitches?', 'Cricket''s pastoral origins on unfenced village greens created flexible boundary geometry while preserving fixed 22-yard pitch distances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('290af5c5-cf1e-4583-8203-9eed7ca0c45e', 'Cricket originated as a pre-industrial village green game where matches were played on open village commons without artificial boundary fences', true, 'ada4340b-17bc-4c88-b7a6-0d83e9574901');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5d5cd47-61aa-49cb-8d61-fdc217009311', 'Because builders did not have tape measures', false, 'ada4340b-17bc-4c88-b7a6-0d83e9574901');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5f993a8-a4c1-4969-aeee-9c9a1be25618', 'Because every country wanted a different shape', false, 'ada4340b-17bc-4c88-b7a6-0d83e9574901');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ad7c8f5-3f4c-4778-8727-43af263f493a', 'Because round stadiums are cheaper', false, 'ada4340b-17bc-4c88-b7a6-0d83e9574901');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bf93dca-1205-4b21-a0b2-ee8e3a53ee8d', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What was the famous ''Bombay Pentangular'' tournament played in colonial India based on?', 'The colonial Bombay tournament evolved from Triangular to Quadrangular to Pentangular, organized strictly along communal lines (opposed by Mahatma Gandhi).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d11188a6-f762-443c-b101-4e0c25805672', 'Communal religious and ethnic teams: The Europeans, The Parsis, The Hindus, The Muslims, and The Rest', true, '1bf93dca-1205-4b21-a0b2-ee8e3a53ee8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a0d834a-e9cd-40e1-83fb-60c4a89f1f3a', 'Five city corporations', false, '1bf93dca-1205-4b21-a0b2-ee8e3a53ee8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92c71bb7-91fc-4ab5-b9c3-3ee1487e6fe7', 'Five universities', false, '1bf93dca-1205-4b21-a0b2-ee8e3a53ee8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c5e5eba-48e0-4ee3-b419-9a1d2d012a65', 'Five army divisions', false, '1bf93dca-1205-4b21-a0b2-ee8e3a53ee8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f4b22bd-9b14-462a-ac77-b2f074502c36', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'How did the advent of Television and Satellite Broadcasting shift the global economic center of gravity of cricket from London to South Asia (India)?', 'Demographic and media revolution: South Asia''s colossal broadcast viewership made the subcontinental market the dominant financial engine of world cricket.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7a1679d-a498-419a-bad9-c53a19f50dae', 'South Asia possessed the largest television viewing audience and consumer marketplace in the cricket-playing world, generating massive advertising revenues that enriched the BCCI', true, '4f4b22bd-9b14-462a-ac77-b2f074502c36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40cdfaac-a4e2-4b6a-adaa-bd8cade5028d', 'Because India invented satellites', false, '4f4b22bd-9b14-462a-ac77-b2f074502c36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d49f9b0c-a405-40a6-a186-2e786bb73afd', 'Because cricket was banned in England', false, '4f4b22bd-9b14-462a-ac77-b2f074502c36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d142f209-26e7-421f-b836-d4f02a915268', 'Because matches were played only in Delhi', false, '4f4b22bd-9b14-462a-ac77-b2f074502c36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8fdb4e0-b7f5-49cb-a2e2-de0f7067a67f', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'Why was Palwankar Baloo, a legendary slow left-arm spinner of the Bombay Hindus team in the 1900s, a milestone figure in Indian social history?', 'Baloo Palwankar challenged untouchability through athletic brilliance, acclaimed by Dr. B.R. Ambedkar as a pioneer of Dalit social elevation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6f875e1-ffa7-4712-a082-d8424de9c4f9', 'He was from the oppressed Dalit (Untouchable) community who broke caste barriers through his supreme cricketing genius, becoming India''s first great indigenous sporting hero', true, 'e8fdb4e0-b7f5-49cb-a2e2-de0f7067a67f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75c82a6b-1872-48ac-9a7a-2f9d85a3c96f', 'He was the first British governor', false, 'e8fdb4e0-b7f5-49cb-a2e2-de0f7067a67f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef0cc065-47b5-45e9-845b-93f79cde61e1', 'He invented cricket shoes', false, 'e8fdb4e0-b7f5-49cb-a2e2-de0f7067a67f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('061eef54-3fd8-4d79-abfe-0c700e61c1dd', 'He was a royal prince', false, 'e8fdb4e0-b7f5-49cb-a2e2-de0f7067a67f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4551ae8b-dad8-40b3-a524-6e943da86d3b', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What is the meaning of the English idiom ''It''s not cricket'' in conversational usage?', 'The Victorian idiom ''It''s not cricket'' signifies any conduct that violates the spirit of fair play, honor, and sportsmanship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55ece5ef-d1a6-4089-8eef-bad0551161e4', 'It is unfair, dishonorable, or unsporting behavior', true, '4551ae8b-dad8-40b3-a524-6e943da86d3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c89b289a-47cd-429a-afc2-4e79437ced53', 'It is not a baseball match', false, '4551ae8b-dad8-40b3-a524-6e943da86d3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5468d462-5fa2-4499-a622-e25e97545e49', 'The weather is rainy', false, '4551ae8b-dad8-40b3-a524-6e943da86d3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a382910-9ab7-42f6-9b44-b1cb49c1ed36', 'The ball is lost', false, '4551ae8b-dad8-40b3-a524-6e943da86d3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7708e20-0496-4e5b-a50e-301060b64f05', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What is the meaning of ''Decolonization'' in the context of international cricket history?', 'Decolonization transformed cricket from an instrument of imperial cultural hegemony into a vibrant arena of post-colonial national pride.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3de9255e-dd22-4841-a341-c335fd052d08', 'The decline of British imperial administrative dominance over the game and the rise of formerly colonized nations (India, Pakistan, West Indies, Sri Lanka) as sovereign global cricket superpowers', true, 'c7708e20-0496-4e5b-a50e-301060b64f05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5ae67bd-d78d-435d-8d13-470f2181f52f', 'Banning wooden bats', false, 'c7708e20-0496-4e5b-a50e-301060b64f05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b60097b5-663c-48f2-ba38-6897fb038570', 'Changing the rules every year', false, 'c7708e20-0496-4e5b-a50e-301060b64f05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1381033e-a21f-482d-8b06-2ba4d2ea141a', 'Playing matches without umpires', false, 'c7708e20-0496-4e5b-a50e-301060b64f05');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76282c86-16a2-4006-bd02-c53841f88563', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What is the SYNONYM of ''Idiosyncrasy'' as applied to cricket''s unique rules?', '''Idiosyncrasy'' denotes an eccentric, highly distinctive individual peculiarity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f08f453-f7e6-4fc5-9e37-83782c9b12ce', 'Quirk / Peculiarity / Unique characteristic', true, '76282c86-16a2-4006-bd02-c53841f88563');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('397544ed-7e5f-498a-bb9d-25f2d67687ae', 'Commonplace', false, '76282c86-16a2-4006-bd02-c53841f88563');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01fa439c-7a34-4354-8c7d-db2cd2d1553a', 'Boring rule', false, '76282c86-16a2-4006-bd02-c53841f88563');
