INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9fd7dc8-f6cf-443b-b55b-d2ec354ef0eb', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What is the ANTONYM of ''Amateur'' in sports terminology?', 'The antonym of ''amateur'' (playing unpaid for pleasure) is ''professional'' (earning a livelihood from the sport).', NOW()) ON CONFLICT DO NOTHING;
