INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1eba5f6-2352-4f15-b203-8cd1f4cb6acd', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'Identify the part of speech of the underlined word in: ''Cricket evolved **gradually** from rural pastimes.''', '''Gradually'' is an adverb of manner modifying the verb ''evolved''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b9b2845-a250-4f89-8dee-13e6d9899f01', 'Adverb of Manner', true, 'e1eba5f6-2352-4f15-b203-8cd1f4cb6acd');
