INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48ebf28f-f54b-44bd-aabe-46d154021e6e', '''The first Indian cricket club was established in Bombay by the Parsis.''', true, '3de9da38-0bd6-4d9c-91cc-bfbef52dc0be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('583f6457-1782-479b-887e-f7fd6f6d1fb5', '''The first Indian cricket club established the Parsis in Bombay.''', false, '3de9da38-0bd6-4d9c-91cc-bfbef52dc0be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('580ae242-cf66-49d4-b110-3e4330da8afa', '''In Bombay had been established the first Indian cricket club.''', false, '3de9da38-0bd6-4d9c-91cc-bfbef52dc0be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('101e54d3-0a81-4f45-bb39-a37c0dd264c4', '''The Parsis were established by the first cricket club.''', false, '3de9da38-0bd6-4d9c-91cc-bfbef52dc0be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fd150c6-d764-44a8-9ee3-012794351b6f', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'Why did English colonists believe that cricket was a civilizing sport for colonized peoples?', 'British imperial ideology promoted cricket as a moralizing exercise in Victorian discipline, stoicism, and gentlemanly etiquette.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('353e3c46-5dd4-4367-b4cd-1a1b50c2f194', 'They believed it instilled Victorian virtues of fair play, imperial discipline, obedience to codified rules, and emotional self-control', true, '0fd150c6-d764-44a8-9ee3-012794351b6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d93f0837-72b1-4025-9d4a-a4301d262e5e', 'Because cricket was easy to learn in a day', false, '0fd150c6-d764-44a8-9ee3-012794351b6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d06519ed-7410-4cf9-b5f3-6e077040eb8d', 'Because they wanted to sell bats', false, '0fd150c6-d764-44a8-9ee3-012794351b6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9cc89d1-5047-400e-bef1-97824964d3a6', 'Because cricket had no rules', false, '0fd150c6-d764-44a8-9ee3-012794351b6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c15ba83-e90e-45ac-bcd8-9e958bd26643', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What technological revolution allowed millions of fans across small Indian towns and villages to watch international cricket live simultaneously?', 'Satellite television telecasts democraticized cricket viewing across rural and urban India, creating a shared national collective ritual.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('324e6e40-236e-44a4-8c7b-4ad03ba05cf6', 'Satellite Television Broadcasting (Doordarshan and private satellite channels)', true, '1c15ba83-e90e-45ac-bcd8-9e958bd26643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5faacba-9537-4edf-a3a1-e9fa719ba9c3', 'Printed newspapers only', false, '1c15ba83-e90e-45ac-bcd8-9e958bd26643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6528fa18-1bb0-499b-bc8b-f4d2583b952b', 'Radio commentary in Morse code', false, '1c15ba83-e90e-45ac-bcd8-9e958bd26643');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f214df5f-c7c0-418e-b3e0-4598e8afafbb', 'Postal letters', false, '1c15ba83-e90e-45ac-bcd8-9e958bd26643');
