INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0a7988e-708a-47d5-b5d6-d295f434dc8e', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'cbfce6b5-d4b1-40af-882a-977a5ac0745d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdfefce4-3a8b-4618-bb86-1b452819cea6', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'cbfce6b5-d4b1-40af-882a-977a5ac0745d');
