INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffc2c90a-ea15-4a54-b1f3-6b96aac44592', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Spot the IMPOSTER in the following historical timeline of cricket evolution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b260751a-eaf4-4611-b33c-8192bb93d8ec', 'Event 1', false, 'ffc2c90a-ea15-4a54-b1f3-6b96aac44592');
