INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a975614-c3e4-4099-a057-d5574146b53d', 'Event 3', false, 'ffc2c90a-ea15-4a54-b1f3-6b96aac44592');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab98abdf-5ee0-4d5a-81ad-959a4552e9f1', 'Event 4 (Hawk-Eye digital ball-tracking computer systems were developed in the 21st CENTURY [circa 2001], not the year 1500)', true, 'ffc2c90a-ea15-4a54-b1f3-6b96aac44592');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4915f8c5-44a0-4388-aa0a-1c47bf13fa13', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Analyze the social sociology of early cricket in colonial India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('459ebc89-f470-4732-a34f-e9bb2ff1f00e', 'The Parsis were a wealthy, westernized commercial merchant community in Bombay with close business ties to the British East India Company, embracing English sports and culture early', true, '4915f8c5-44a0-4388-aa0a-1c47bf13fa13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a359e62-bddb-4b28-8dd3-5ac1fa522ee8', 'Because only Parsis were allowed to buy bats', false, '4915f8c5-44a0-4388-aa0a-1c47bf13fa13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0233da6c-fc13-4c44-ba7b-b9c631886428', 'Because cricket was invented in Persia', false, '4915f8c5-44a0-4388-aa0a-1c47bf13fa13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5381363b-cf2a-4ec2-b608-eaf48fdb1925', 'Because Parsis were professional athletes in Britain', false, '4915f8c5-44a0-4388-aa0a-1c47bf13fa13');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d114cb7e-8277-4a7f-8d82-44030a1e842d', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Match Column I (Cricket Innovations / Historical Milestones) with Column II (Historical Causes & Consequences):
(a) Airborne Bowling (1760s)    -> (i) Prompted the invention of straight, flat willow bats
(b) Kerry Packer''s WSC (1977)    -> (ii) Inaugurated colored clothing, white balls, and day-night telecasts
(c) 1983 World Cup Victory       -> (iii) Catalyzed India''s commercial cricket boom and mass fanaticism
(d) Subcontinental TV Market     -> (iv) Shifted the global financial headquarters of cricket to South Asia', 'Airborne bowling = straight bats; Packer = colored kits & night games; 1983 victory = mass mania; TV market = shift to South Asia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4c67111-52c7-4cf0-a6a7-82c04d5a047c', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'd114cb7e-8277-4a7f-8d82-44030a1e842d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c325fc0b-24ad-44c7-9305-02ba5d0f31a6', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'd114cb7e-8277-4a7f-8d82-44030a1e842d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06454e9b-5c62-4c6b-a657-a2c41b739c20', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'd114cb7e-8277-4a7f-8d82-44030a1e842d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39838899-4856-4f38-be3c-39349a804d86', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'd114cb7e-8277-4a7f-8d82-44030a1e842d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49ac8de0-85a5-4a7c-a70e-a8d0f60e2cbb', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Read the statements regarding the transformation of cricket rules:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c14e66e-a538-4bd0-884c-ff54dbe43000', 'Statements 1 and 2 only', true, '49ac8de0-85a5-4a7c-a70e-a8d0f60e2cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e982b54-0fe8-43d8-9459-9bdec18cef74', 'Statements 2 and 3 only', false, '49ac8de0-85a5-4a7c-a70e-a8d0f60e2cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a3eba95-1687-4cc8-8b8d-83ea2253fe2c', 'Statements 1 and 3 only', false, '49ac8de0-85a5-4a7c-a70e-a8d0f60e2cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e55936e-6953-4ee2-a845-b994fb26a886', 'All Statements 1, 2, and 3', false, '49ac8de0-85a5-4a7c-a70e-a8d0f60e2cbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6db46b16-8456-49e1-be14-88e4fb229e69', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Identify the grammatical role of the underlined clause in: ''**Although cricket originated in England**, its contemporary economic empire is firmly headquartered in India.''', '''Although cricket originated in England'' is a subordinate concessive adverbial clause introduced by ''Although''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dffc830d-1072-4df7-a7d3-9c8fea0e75b9', 'Adverbial Clause of Concession / Contrast modifying the main clause', true, '6db46b16-8456-49e1-be14-88e4fb229e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c39ea84-d110-4aa5-b9e0-8fff93b5d22e', 'Noun Clause in apposition', false, '6db46b16-8456-49e1-be14-88e4fb229e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83e07875-8b08-431a-a924-efacf978fec0', 'Relative Clause of manner', false, '6db46b16-8456-49e1-be14-88e4fb229e69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b16bcfe9-46c3-43a0-bb07-61ddecbabe04', 'Coordinate independent clause', false, '6db46b16-8456-49e1-be14-88e4fb229e69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('210e09b7-7d1b-4976-a491-54f6c6600df5', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Why did Mahatma Gandhi and nationalist leaders oppose communal cricket tournaments like the Bombay Pentangular?', 'Gandhi denounced communal Pentangular cricket as a divisive imperial legacy, arguing sports should unify rather than fracture society.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f95ff37d-9716-467a-9977-575fa8119ee0', 'They believed that dividing sporting teams along sectarian religious lines (Hindus, Muslims, Parsis, Europeans) hardened communal divisions and undermined anti-colonial national unity', true, '210e09b7-7d1b-4976-a491-54f6c6600df5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc72d5e8-6735-4a01-aa9b-59f48993dcd6', 'Because Gandhi disliked all sports', false, '210e09b7-7d1b-4976-a491-54f6c6600df5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b4797b1-2276-43ee-9ec9-e3fae4c1f082', 'Because they wanted cricket to be played without rules', false, '210e09b7-7d1b-4976-a491-54f6c6600df5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6e9ed2b-3d09-4d2e-8abc-0b4d822baaac', 'Because foreign teams were not invited', false, '210e09b7-7d1b-4976-a491-54f6c6600df5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e71422a-290c-42d5-98ee-428dc64bc99f', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'How did the invention of the ''Doosra'' and ''Reverse Swing'' by Pakistani fast bowlers (Sarfaraz Nawaz, Imran Khan, Wasim Akram) subvert traditional Anglo-Australian bowling orthodoxy?', 'Subcontinental bowling innovations (reverse swing, doosra) shattered Eurocentric bowling dogmas, enriching international bowling tactics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33625e9d-9ef4-4c41-aa34-1eea23bee646', 'They mastered innovative aerodynamics using scuffed and polished ball surfaces to create deceptive late swing under hot subcontinental conditions, revolutionizing fast bowling worldwide', true, '4e71422a-290c-42d5-98ee-428dc64bc99f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5656e4e5-fce2-4ce3-97c8-f8b3c5e222b2', 'They made the ball heavier with lead', false, '4e71422a-290c-42d5-98ee-428dc64bc99f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae305a5d-016e-4520-9de8-a173681b0da8', 'They changed the pitch dimensions', false, '4e71422a-290c-42d5-98ee-428dc64bc99f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e11862d5-dd42-42b9-995d-b801be100d7b', 'They used metal bats', false, '4e71422a-290c-42d5-98ee-428dc64bc99f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4380d82-cc4b-43b4-80a3-2934ce3ae2d9', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'What literary device is employed in the phrase: ''Cricket''s connection with a pre-industrial rural past is woven into the very fabric of its willow wood and leather ball.''?', 'The metaphor ''woven into the fabric'' and synecdoche of willow/leather crystallize cricket''s deep organic roots in pre-industrial craft culture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eba12b44-7233-45c2-977c-b2e7ba78851b', 'Metaphor and Synecdoche (using physical implements of the sport to symbolize its historical pastoral origins)', true, 'e4380d82-cc4b-43b4-80a3-2934ce3ae2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef97d118-f9a9-4040-aa8e-f1dc9892ddfb', 'Hyperbole only', false, 'e4380d82-cc4b-43b4-80a3-2934ce3ae2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('242df69d-889f-4e74-ac1d-5ca13cc2048f', 'Simile', false, 'e4380d82-cc4b-43b4-80a3-2934ce3ae2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e2f032b-9678-461f-b01a-fdc8791d74d7', 'Irony only', false, 'e4380d82-cc4b-43b4-80a3-2934ce3ae2d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35584904-d2ed-470b-8fd2-b4bf15d205b7', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Which of the following sentences correctly utilizes the Subjunctive Mood in sporting commentary?', 'Mandative subjunctive after verbs of demand (''demanded that every fielder be alert'' with bare infinitive ''be'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78b77518-b91b-4b58-b1a0-2beac14aa2b2', '"The captain demanded that every fielder be alert on the boundary."', true, '35584904-d2ed-470b-8fd2-b4bf15d205b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d60346d-40ff-426a-a8f4-5dbd18d1e95a', '"The captain demanded that every fielder is alert."', false, '35584904-d2ed-470b-8fd2-b4bf15d205b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71b6406f-ddfc-45ff-9611-60a694f27fc2', '"The captain was demanding for alert."', false, '35584904-d2ed-470b-8fd2-b4bf15d205b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f79ad8d-ee9c-49b6-9231-dfee912b68db', '"Fielders were alerting by the captain."', false, '35584904-d2ed-470b-8fd2-b4bf15d205b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c9f138e-5a25-40f8-88f7-ceb541780aec', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'What socio-economic shift explains why contemporary Indian cricket stars come from small towns and rural hinterlands (like MS Dhoni from Ranchi) rather than big elite metropolitan cities?', 'Grassroots democratization: television inspiration and professional domestic contracts transformed cricket into a meritocratic vehicle for small-town talent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ffc25e5-2e01-4045-b6aa-b34973c3fa63', 'The spread of television, localized cricket academies, talent scouting, and lucrative franchise leagues (IPL) democratized access, merit, and financial rewards across all socio-economic strata', true, '3c9f138e-5a25-40f8-88f7-ceb541780aec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481172cc-f03a-46d8-aaa8-f629c15dbf66', 'City players were legally banned from playing cricket', false, '3c9f138e-5a25-40f8-88f7-ceb541780aec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dd2c5b0-5a53-41ef-b57b-83084780f597', 'Small towns have larger stadiums', false, '3c9f138e-5a25-40f8-88f7-ceb541780aec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20002821-32eb-45b6-8a67-6ca38f9bfc91', 'Matches are no longer played in big cities', false, '3c9f138e-5a25-40f8-88f7-ceb541780aec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d773a23e-7b02-4bc5-9d93-35b362066057', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'What master sociological insight is articulated in Chapter 10 of NCERT Class 7 English?', 'Ramachandra Guha''s essay uses cricket as a profound sociological lens to illuminate class, empire, race, technology, and cultural decolonization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08df38c1-3479-4cb1-8cfd-c29a4b4707e3', 'Sports are not mere games; they are living mirrors of human history, reflecting the evolution of social class, colonial power dynamics, technological revolutions, media commercialism, and post-colonial national identity', true, 'd773a23e-7b02-4bc5-9d93-35b362066057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f6a434c-f515-4e83-8144-1f818e1366a5', 'That cricket is the only sport worth playing', false, 'd773a23e-7b02-4bc5-9d93-35b362066057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d31eb4c4-0139-4743-a392-14bd2f21564a', 'That sports have no relation to history or society', false, 'd773a23e-7b02-4bc5-9d93-35b362066057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98b4317c-96ac-4ca3-b875-d0aa7ed51286', 'That cricket will be forgotten in the future', false, 'd773a23e-7b02-4bc5-9d93-35b362066057');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('081f17e4-8a25-45da-bbfb-0da07c4637c5', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who is celebrated as the ''Father of the Computer'' for conceptualizing the first programmable mechanical computing machine (the Analytical Engine)?', 'Charles Babbage designed the mechanical Difference Engine and the general-purpose programmable Analytical Engine in the 1830s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7008e53c-333a-4b0f-b5cd-5813107aac68', 'Charles Babbage', true, '081f17e4-8a25-45da-bbfb-0da07c4637c5');
