INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cdff862-e8dc-4cf9-8b31-bd623ea72c94', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who is celebrated as the ''Father of Modern Computer Science and Artificial Intelligence'' for inventing the theoretical Turing Machine and cracking the Nazi Enigma cipher during WWII?', 'Alan Turing formalized algorithmic computation (Turing machine), broke the naval Enigma code at Bletchley Park, and proposed the Turing Test.', NOW()) ON CONFLICT DO NOTHING;
