INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e614533-5020-4879-acc7-297e55f2231a', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who invented the WORLD WIDE WEB (WWW) at CERN in 1989, designing HTML, HTTP, and the first web browser?', 'Sir Tim Berners-Lee invented the World Wide Web at CERN in 1989, releasing the technology royalty-free to the entire world.', NOW()) ON CONFLICT DO NOTHING;
