INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b3c0d53-45c4-4c58-86df-1bab500087ec', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Which Scottish physician-bacteriologist accidentally discovered the world''s first wonder antibiotic—PENICILLIN—from Penicillium mold in 1928?', 'Alexander Fleming discovered penicillin in 1928, revolutionizing modern medicine and saving hundreds of millions of lives from bacterial infections.', NOW()) ON CONFLICT DO NOTHING;
