INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ddde5aa-bc60-43c3-a811-c8d6e4a7ba4f', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who developed the world''s FIRST VACCINE (for Smallpox) in 1796 using cowpox fluid, pioneering the field of Immunology?', 'Edward Jenner''s 1796 cowpox inoculation created the smallpox vaccine, leading to the global eradication of smallpox by the WHO in 1980.', NOW()) ON CONFLICT DO NOTHING;
