INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('407a475a-7250-479a-856d-472d6a89bb19', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Which two scientists discovered the 3D DOUBLE HELIX molecular structure of DNA in 1953 (building on Rosalind Franklin''s X-ray crystallography)?', 'Watson and Crick deduced the antiparallel double-helix structure of DNA in 1953, unlocking the genetic code of all biological life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c12c9f2c-4130-4720-841b-e3020eb885bc', 'James Watson and Francis Crick', true, '407a475a-7250-479a-856d-472d6a89bb19');
