INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ccd3cac-be38-40b0-b0e0-99af9b29cfb5', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'What is Albert Einstein''s world-famous mass-energy equivalence equation derived from his Special Theory of Relativity (1905)?', 'E = mc² establishes that mass and energy are interchangeable, forming the foundational principle of nuclear energy and astrophysics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f44a4691-c470-441b-848a-540c20c23ef5', 'E = mc² (where E = Energy, m = mass, c = speed of light)', true, '9ccd3cac-be38-40b0-b0e0-99af9b29cfb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6578885b-5133-45bb-9b6f-e943be804790', 'F = ma', false, '9ccd3cac-be38-40b0-b0e0-99af9b29cfb5');
