INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ff48f49-7f99-4f48-a24f-17d0c540ece0', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is ''Moore''s Law'', articulated by Intel co-founder Gordon Moore in 1965?', 'Moore''s Law accurately guided semiconductor miniaturization and exponential computational power scaling for over five decades.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f704446c-aac1-47ae-a6c0-79e6faf00a02', 'The empirical observation that the number of transistors on a microchip DOUBLES approximately every two years, while the cost of computers is halved', true, '2ff48f49-7f99-4f48-a24f-17d0c540ece0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40ba99c8-1481-4574-bf53-80e531b4b2b1', 'That computers will stop working after 10 years', false, '2ff48f49-7f99-4f48-a24f-17d0c540ece0');
