INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5aca6f0a-8423-465b-bd08-72186433e043', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Which Rajput ruler of Amber (Jaipur) was a brilliant astronomer and statesman who founded the planned pink city of JAIPUR and built five astronomical observatories (Jantar Mantars)?', 'Sawai Raja Jai Singh II built Jaipur (1727) and five masonry observatories (Jantar Mantar) in Delhi, Jaipur, Ujjain, Mathura, and Varanasi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e9c21e3-4fd9-4358-8b11-47214adf317b', 'Sawai Raja Jai Singh (Jai Singh II)', true, '5aca6f0a-8423-465b-bd08-72186433e043');
