INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a47ac6c-bfba-4883-b79f-b64e9f77a63b', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Who was the great Maratha warrior-king who carved out a stable independent kingdom in Maharashtra using guerrilla warfare against Mughal forces?', 'Chhatrapati Shivaji Maharaj established the sovereign Maratha Swarajya with support from powerful Deshmukh peasant-warrior Marathas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44345394-56ed-4265-8d4e-3650270ed83f', 'Chhatrapati Shivaji Maharaj (1627–1680)', true, '5a47ac6c-bfba-4883-b79f-b64e9f77a63b');
