INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14252958-def3-43ed-b782-fb278822c6e9', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'In the Maratha revenue administration, what was ''CHAUTH''?', 'Chauth was a 25% (1/4th) protection levy claimed by Maratha rulers from territories outside the Swarajya core.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2e0a2a1-5bdf-4383-8bac-22fa11406f9d', 'A tax of 25% (one-fourth) of the land revenue collected by Marathas from non-Maratha neighboring territories in exchange for protection from plundering', true, '14252958-def3-43ed-b782-fb278822c6e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a48715e-a1e8-4cbb-8362-b62c1fa45ea2', 'A tax on salt', false, '14252958-def3-43ed-b782-fb278822c6e9');
