INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0f626c1-bf16-4872-906a-83274a4aaf96', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'What was ''SARDESHMUKHI'' collected by the Marathas in addition to Chauth?', 'Sardeshmukhi was a 9–10% surcharge levied on the entire revenue by Shivaji in his capacity as the hereditary Sardeshmukh (head of Deshmukhs).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9dab8e9-10f8-410f-a4e5-52d1f7a986de', 'An additional 9 to 10 per cent tax claimed by the Maratha King as the hereditary Chief Headman (Sardeshmukh) of the Deccan', true, 'c0f626c1-bf16-4872-906a-83274a4aaf96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65a6088c-90eb-4da5-bbcb-a236ee692343', 'A tax on ships', false, 'c0f626c1-bf16-4872-906a-83274a4aaf96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76bc7a4a-86c4-4382-bcee-cee258e3bc9c', 'A tax on temples', false, 'c0f626c1-bf16-4872-906a-83274a4aaf96');
