INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b706bc78-ca01-4b05-a42c-5a4e43e10712', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Who was the legendary Sikh general who led a fierce armed rebellion against Mughal authority in Punjab after Guru Gobind Singh''s passing, minting coins in the names of Guru Nanak and Guru Gobind Singh?', 'Banda Singh Bahadur captured Sirhind in 1710, abolished the Zamindari system, and established Sikh sovereign rule before his capture in 1715.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7865a43-d7c3-4672-a653-3430ebdd5ede', 'Banda Singh Bahadur (Banda Bairagi)', true, 'b706bc78-ca01-4b05-a42c-5a4e43e10712');
