INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b0ee18f-5091-497f-99fd-aea95f4aedff', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Which powerful Jat king led the kingdom of BHARATPUR to its political and military zenith, building the impregnable Lohagarh Fort?', 'Maharaja Suraj Mal (the ''Plato of the Jat tribe'') consolidated Bharatpur into a formidable power, defending Lohagarh fort against all invaders.', NOW()) ON CONFLICT DO NOTHING;
