INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0db3afd0-438b-42b0-b167-df17bf7f6f26', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'What were the two major competing noble factions in the later Mughal court whose bitter rivalry paralyzed central imperial administration?', 'Imperial factionalism between Irani and Turani grandees reduced later Mughal emperors (Farrukhsiyar, Muhammad Shah) to helpless puppets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93734ac7-5a8b-46e2-b36e-8ca70b194116', 'The IRANIS (nobles of Persian origin) and the TURANIS (nobles of Central Asian Turkish origin)', true, '0db3afd0-438b-42b0-b167-df17bf7f6f26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a04dcb2-a820-4dca-a890-fa30c69174f9', 'The Afghans and Rajputs only', false, '0db3afd0-438b-42b0-b167-df17bf7f6f26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df985e41-d394-49d3-bde0-6911c449ddc6', 'The English and French factions', false, '0db3afd0-438b-42b0-b167-df17bf7f6f26');
