INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('060b0cfa-5499-45cc-adbd-c52d79fd9f36', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'What was the ''Ijaradari System'' (revenue farming) introduced in 18th-century Awadh and Bengal?', 'Under Ijaradari, the provincial governors auctioned revenue rights to bankers and contractors, centralizing cash flow while pressuring cultivators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1007a7e5-1407-4b06-85c9-b0f99314454f', 'The right to collect land revenue was auctioned to the highest bidding revenue contractors (Ijaradars) in return for a fixed sum of money guaranteed to the state', true, '060b0cfa-5499-45cc-adbd-c52d79fd9f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8aee2c6-edb3-4858-b131-edb7dae2410e', 'Farmers paid no tax', false, '060b0cfa-5499-45cc-adbd-c52d79fd9f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81ff3078-6da2-4a7b-9b65-498deee6588b', 'Land was divided equally among all villagers', false, '060b0cfa-5499-45cc-adbd-c52d79fd9f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec759c74-3d3d-4594-94b1-4c023d257e1a', 'Revenue was collected only in gold coins', false, '060b0cfa-5499-45cc-adbd-c52d79fd9f36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c48a1a68-5422-45c9-83a0-6d8cd1270a8d', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'Which immensely wealthy banking house in Bengal wielded enormous financial and political influence under Murshid Quli Khan, Alivardi Khan, and the British East India Company?', 'The Jagat Seths (''Bankers of the World'') managed Bengal''s imperial mint, state revenues, and hundi credit networks with colossal financial power.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d4e93a2-bfdb-4a54-9069-ca97677ce4a8', 'The Banking House of JAGAT SETH (Fateh Chand)', true, 'c48a1a68-5422-45c9-83a0-6d8cd1270a8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b4f4e27-7640-4f7a-9ec6-8b567e34cb06', 'The House of Rothschild', false, 'c48a1a68-5422-45c9-83a0-6d8cd1270a8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1688c28c-5f35-4305-a5a2-7045cfe2838e', 'The Surat Hundi Syndicate', false, 'c48a1a68-5422-45c9-83a0-6d8cd1270a8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('019783a8-ce1f-4c77-80c4-a108c8b16e16', 'The Chettiar Guild', false, 'c48a1a68-5422-45c9-83a0-6d8cd1270a8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e576a3a9-0005-4095-9cc9-9c956ad22c0b', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'What were the ''Watan Jagirs'' enjoyed by Rajput rulers under Mughal paramountcy?', 'Watan Jagirs recognized Rajput princes'' inalienable hereditary ancestral domains, preserving regional Rajput autonomy under imperial suzerainty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5847b11d-f708-487f-92fc-5d04f1d38067', 'Hereditary homeland territories (Watans) in Rajasthan that Rajput princes were allowed to rule autonomously without imperial interference, in return for military service', true, 'e576a3a9-0005-4095-9cc9-9c956ad22c0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61ffd191-2052-4d15-9cde-4f8520f915ea', 'Lands in Bengal given to Rajputs', false, 'e576a3a9-0005-4095-9cc9-9c956ad22c0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86b0f85b-93e9-48f6-b581-26963f10d8e1', 'Tax-free temple lands', false, 'e576a3a9-0005-4095-9cc9-9c956ad22c0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff805cc6-9b6b-4244-a664-18f0bd4197bf', 'Forts built in Delhi', false, 'e576a3a9-0005-4095-9cc9-9c956ad22c0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f763d4c-7fe5-4f17-9ec2-6ecddcd5168c', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'Who was the dynamic Peshwa (reigned 1720–1740) who championed northern Maratha expansion, preaching ''Strike at the trunk of the withering Mughal tree and the branches will fall of themselves''?', 'Baji Rao I was a military genius who expanded the Maratha confederacy across Malwa, Gujarat, and Bundelkhand, threatening Delhi itself.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bec5c77c-6eb4-4d04-86bb-4f1354a59882', 'Peshwa Baji Rao I', true, '5f763d4c-7fe5-4f17-9ec2-6ecddcd5168c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63dcbdca-3a1c-4b46-ba8d-514da16dc08d', 'Balaji Vishwanath', false, '5f763d4c-7fe5-4f17-9ec2-6ecddcd5168c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd46a19c-a963-4602-8d21-12d15a619302', 'Balaji Baji Rao (Nana Saheb)', false, '5f763d4c-7fe5-4f17-9ec2-6ecddcd5168c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f7461b3-bec2-4867-842e-1bfc8ac847a1', 'Madhav Rao I', false, '5f763d4c-7fe5-4f17-9ec2-6ecddcd5168c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44e7909c-d9df-40d5-b407-9a4c5e80d56d', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'Which four great Maratha military dynasties (Chiefs / Sardar houses) dominated regional territories within the decentralized Maratha Confederacy?', 'The Maratha confederacy was led by four powerful martial houses: Sindhia (Gwalior), Holkar (Indore), Gaekwad (Baroda), and Bhonsle (Nagpur).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42f4b8f2-a7d8-4d90-a7cf-6e8f371e4171', '1. Gaekwads (Baroda) ; 2. Bhonsles (Nagpur) ; 3. Holkars (Indore) ; 4. Sindhias (Gwalior)', true, '44e7909c-d9df-40d5-b407-9a4c5e80d56d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3426ec76-746f-4199-9dfd-05bf084eefc4', 'Nawabs, Nizams, Sultans, and Rajas', false, '44e7909c-d9df-40d5-b407-9a4c5e80d56d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd2c8c61-4bc9-4ba8-ae42-f4da6fd1327d', 'Peshwas, Mughals, Rajputs, and Sikhs', false, '44e7909c-d9df-40d5-b407-9a4c5e80d56d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70cd9abe-87bb-42bd-88cf-2859d99806f7', 'Cholas, Cheras, Pandyas, and Pallavas', false, '44e7909c-d9df-40d5-b407-9a4c5e80d56d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('354094f9-6a0b-4c41-9d60-6093af651be0', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'What catastrophic event on January 14, 1761, halted the Marathas'' ambition to rule all of India from Delhi?', 'The Third Battle of Panipat (1761) inflicted catastrophic casualties on the Maratha leadership, creating a political vacuum exploited by the British.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('080c24e6-a13e-403f-a405-93daacfa7e4b', 'The THIRD BATTLE OF PANIPAT (where Ahmad Shah Abdali routed the Maratha army under Sadashivrao Bhau)', true, '354094f9-6a0b-4c41-9d60-6093af651be0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82d75992-7983-4d5c-8eda-815d1f0a6063', 'The Battle of Plassey', false, '354094f9-6a0b-4c41-9d60-6093af651be0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('715d6ae9-b86d-486f-9543-514299100be6', 'The Battle of Buxar', false, '354094f9-6a0b-4c41-9d60-6093af651be0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6880321-1e1b-4ff1-bab5-01bbe570a38e', 'The Battle of Haldighati', false, '354094f9-6a0b-4c41-9d60-6093af651be0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c2db4da-16ee-40fb-863e-a1f88bddf082', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'What was the ''Dal Khalsa'' and the ''Rakhi'' system organized by Sikh bands in 18th-century Punjab?', 'Dal Khalsa unified Sikh military misls under collective ''Gurmata'' consensus; the Rakhi system secured peasant agriculture against Afghan marauders.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e689bbcd-cf0a-457b-8dec-4c8e318f8db8', 'Dal Khalsa was the grand unified army of Sikh Misls meeting at Amritsar on Baisakhi/Diwali ; Rakhi was a security system offering protection to cultivators against external raids for a 20% revenue payment', true, '7c2db4da-16ee-40fb-863e-a1f88bddf082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38754d4b-7e03-453a-b0e8-11986992335a', 'A trading guild for selling wheat', false, '7c2db4da-16ee-40fb-863e-a1f88bddf082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52157d3c-14bc-429b-9869-82f9111da32c', 'A royal palace guard in Lahore', false, '7c2db4da-16ee-40fb-863e-a1f88bddf082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d50758e-3472-4199-8c16-0dbe1ef6a843', 'A religious pilgrimage to the Himalayas', false, '7c2db4da-16ee-40fb-863e-a1f88bddf082');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99963847-c89e-4d41-a31d-f2649684506b', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'Who united all the independent Sikh Misls and established a powerful sovereign Sikh kingdom with its capital at LAHORE in 1799?', 'Maharaja Ranjit Singh captured Lahore in 1799, creating a formidable secular empire spanning Punjab, Kashmir, and Peshawar with modern Fauj-i-Khas artillery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5611450-7d68-4a14-b866-dd86f5f125ed', 'Maharaja Ranjit Singh (''Lion of Punjab'')', true, '99963847-c89e-4d41-a31d-f2649684506b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55e7931e-7c22-4def-9629-bf2c159ba61e', 'Banda Singh Bahadur', false, '99963847-c89e-4d41-a31d-f2649684506b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d6d06f5-9065-4207-991a-3a00ea26d51f', 'Charat Singh Sukerchakia', false, '99963847-c89e-4d41-a31d-f2649684506b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c685899-38b8-4ccb-a831-bb49cee670a7', 'Hari Singh Nalwa', false, '99963847-c89e-4d41-a31d-f2649684506b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bfaf8dd-c935-417d-8a5e-ce4699885384', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'Why did the states of Awadh, Bengal, and Hyderabad—despite their de facto independence—continue to formally acknowledge the Mughal Emperor in Delhi?', 'Mughal symbolic paramountcy persisted: regional Nawabs and Nizams derived legal legitimacy from nominal imperial investiture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d5838a6-b14e-4be4-9ffb-fb28c409bb77', 'The Mughal Emperor remained the supreme source of political legitimacy and symbolic prestige; regional rulers minted coins in the Emperor''s name and sought imperial titles (Farman) to legitimize their rule', true, '7bfaf8dd-c935-417d-8a5e-ce4699885384');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ada68c92-1632-438e-a2e0-6c1961b8a35f', 'Because the Emperor had a massive army in Delhi', false, '7bfaf8dd-c935-417d-8a5e-ce4699885384');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('633b8f78-ed28-4910-9218-3bd474a41adc', 'Because the Emperor paid their salaries', false, '7bfaf8dd-c935-417d-8a5e-ce4699885384');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0b9597c-c5d9-460a-b3b2-60895e5c5154', 'Because they wanted to conquer Europe', false, '7bfaf8dd-c935-417d-8a5e-ce4699885384');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1533a64-6740-4854-b5f7-6117d9a4fbb2', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'What distinct architectural style is represented in the magnificent palaces and garden pavilions of Deeg near Bharatpur built by Jat rulers?', 'The Deeg water palaces synthesized Shahjahani aesthetic elegance with Rajasthani courtyards and hydraulic fountain technology.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('941c2297-11be-44cb-b9b9-a79626df4efb', 'A graceful fusion of Mughal architectural forms (Shahjahani jharokhas, bangla eaves) with traditional Rajput palatial motifs and water fountains', true, 'a1533a64-6740-4854-b5f7-6117d9a4fbb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbdbd7a9-3789-4872-8383-ed716ba1fd18', 'Pure Gothic European style', false, 'a1533a64-6740-4854-b5f7-6117d9a4fbb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd1a2646-df75-4d78-864d-b3a3d89e5cee', 'Ancient Greek column style', false, 'a1533a64-6740-4854-b5f7-6117d9a4fbb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e365622b-95b0-4125-9783-6b3bfbfa1f9d', 'Chinese pagoda style', false, 'a1533a64-6740-4854-b5f7-6117d9a4fbb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('942448d5-a36b-415d-b310-ce23f0195601', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'Which pastoral-peasant community formed the backbone of the formidable Maratha armies under Shivaji and the Peshwas?', 'Hardy Kunbi peasant-warriors provided the mobile light cavalry that executed Shivaji''s devastating Ganimi Kava (guerrilla) maneuvers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91954661-2f99-4c45-a38c-25e4bcf56bf8', 'The Kunbi Peasants (Kunbi Marathas)', true, '942448d5-a36b-415d-b310-ce23f0195601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4319ea6b-e2d1-4d39-b300-8fb7acc96ac6', 'The Gujjars', false, '942448d5-a36b-415d-b310-ce23f0195601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec0904f3-4b22-4ac1-9493-36bda3bb9641', 'The Jats', false, '942448d5-a36b-415d-b310-ce23f0195601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('793c4e9a-2c64-4587-a8aa-1ae86ae0950a', 'The Ahirs', false, '942448d5-a36b-415d-b310-ce23f0195601');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ab3600a-7838-4d09-a65f-1328d597182e', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'How did the Peshwas transform Pune in the 18th century?', 'Under the Chitpavan Peshwas, Pune evolved from a small garrison town into the grand imperial seat of the Maratha confederacy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd16eda5-ed7d-419c-ab46-6636c6d381d6', 'Pune became the thriving political, administrative, and banking capital of the entire Maratha Empire, bustling with merchants, scholars, and diplomats', true, '2ab3600a-7838-4d09-a65f-1328d597182e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb6b71aa-bd35-4ce7-9d98-ef3f6d7c7f88', 'Pune was abandoned and turned into a forest', false, '2ab3600a-7838-4d09-a65f-1328d597182e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9027f46a-0df1-40af-b804-8a8a35833cde', 'Pune was sold to the British in 1720', false, '2ab3600a-7838-4d09-a65f-1328d597182e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce76b469-1efa-4fe2-9e97-91fca20b25f4', 'Pune became an ocean port', false, '2ab3600a-7838-4d09-a65f-1328d597182e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6179e3b8-8bec-4a54-9aee-87fcdac9bb11', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'What were the ''Misls'' in 18th-century Sikh history?', 'The 12 Sikh Misls were egalitarian martial confederacies that carved up and governed Punjab after defeating Afghan incursions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1a99300-47c6-4227-a46a-803304526cf8', 'Twelve autonomous sovereign military-administrative confederacies/clans (such as Sukerchakia, Ahluwalia, Bhangi) that collectively defended Punjab against foreign invasions', true, '6179e3b8-8bec-4a54-9aee-87fcdac9bb11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('669a0348-8eca-4156-b711-7d9d95c34a54', 'Religious books written in Persian', false, '6179e3b8-8bec-4a54-9aee-87fcdac9bb11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99e61e4f-210d-43a6-8c2b-db076985a66d', 'Special cavalry swords', false, '6179e3b8-8bec-4a54-9aee-87fcdac9bb11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cc83a1e-c038-48d9-8ece-c4ddc983a6fd', 'Taxes on grain', false, '6179e3b8-8bec-4a54-9aee-87fcdac9bb11');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71bff763-1140-4b39-814c-04defba48a9b', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'What common administrative feature united the three successor states of Awadh, Bengal, and Hyderabad?', 'The financial alliance between regional statecraft and indigenous banking houses (Mahajans, Sahukars) was a defining hallmark of 18th-century polity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('913288a2-eb8f-45c4-8858-45ad5139f667', 'All three states relied heavily on wealthy regional Moneylenders and Bankers (like Jagat Seths, Mahajans) for credit, loans, and revenue guarantees', true, '71bff763-1140-4b39-814c-04defba48a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5e9afca-5025-443e-b512-7285bcd05669', 'All three states banned the use of money', false, '71bff763-1140-4b39-814c-04defba48a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaf1a363-afb7-4fda-a012-e0fd2b86de44', 'All three states abolished armies', false, '71bff763-1140-4b39-814c-04defba48a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1695be1f-877c-4ba4-9990-3c18e4711681', 'All three states converted to Buddhism', false, '71bff763-1140-4b39-814c-04defba48a9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20ffee31-3ba5-4240-855a-98320e9c69bc', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Medium', 'Who was the French-trained general who modernized Maharaja Ranjit Singh''s Sikh army (Fauj-i-Khas) into the second-best military force in Asia after the British East India Company?', 'Napoleonic veterans (Allard, Ventura, Court, Avitabile) drilled the Sikh Fauj-i-Khas in European infantry tactics, cavalry maneuvers, and heavy brass artillery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a4cfb26-4e80-440f-bfee-0f9914a63a70', 'General Jean-François Allard and General Ventura', true, '20ffee31-3ba5-4240-855a-98320e9c69bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('657b837a-5c38-4766-b789-53000079712a', 'General Dupleix', false, '20ffee31-3ba5-4240-855a-98320e9c69bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a82aa47-c5ca-4265-a662-10d8bc067ae0', 'General Lally', false, '20ffee31-3ba5-4240-855a-98320e9c69bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56654d6a-b2a8-46c1-bd99-482030703e6c', 'General Bussy', false, '20ffee31-3ba5-4240-855a-98320e9c69bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e24e1c88-c2b2-42f9-b14b-2627053bfe3a', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('482527ba-ad2e-4167-86f5-b7f1ba8d5225', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'e24e1c88-c2b2-42f9-b14b-2627053bfe3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10a97d9f-860a-4bc2-88a0-831877f6c55f', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'e24e1c88-c2b2-42f9-b14b-2627053bfe3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5081f99-af31-41db-ab92-7d4c897c3c5f', '(A) is true, but (R) is false.', false, 'e24e1c88-c2b2-42f9-b14b-2627053bfe3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('831d6311-b906-4ef1-a101-989fac317d5e', '(A) is false, but (R) is true.', false, 'e24e1c88-c2b2-42f9-b14b-2627053bfe3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f34aa705-44a3-4be6-a3e6-1654c30c4496', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'Spot the IMPOSTER in the following regional states of 18th-century India and their founding leaders:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94c51205-01ad-4672-975d-f57bb44b54fd', 'State 1', false, 'f34aa705-44a3-4be6-a3e6-1654c30c4496');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d899bea-9d8e-46a0-bb94-11e86c7a7ca6', 'State 2', false, 'f34aa705-44a3-4be6-a3e6-1654c30c4496');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ecc3b04-81ab-4aac-a26f-ad7e081bcbfc', 'State 3', false, 'f34aa705-44a3-4be6-a3e6-1654c30c4496');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('314d9150-8ecf-487c-a137-3e0ab3239b3c', 'State 4 (The Maratha kingdom was founded by CHHATRAPATI SHIVAJI MAHARAJ, not ancient Roman general Julius Caesar)', true, 'f34aa705-44a3-4be6-a3e6-1654c30c4496');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f6c6e84-5250-4d64-aa4f-63829a1f984f', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'Analyze the structural collapse of the Mughal ''Jagirdari Crisis'' in the late 17th and early 18th centuries:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1766534-9d10-43ef-b007-c7307d10a84b', 'The rapid influx of new nobles (Mansabdars) created an acute shortage of fertile crown land (Paibaqi) to assign as Jagirs; corrupt nobles extracted extortionate revenues from desperate peasants while maintaining inadequate military contingents', true, '3f6c6e84-5250-4d64-aa4f-63829a1f984f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1ee86c1-b4df-4218-9363-58f4ca825bd1', 'Mughal coins lost all value because gold was banned', false, '3f6c6e84-5250-4d64-aa4f-63829a1f984f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcb56ba6-9287-4baa-bc34-79b0e4db6568', 'All farmers refused to plant crops for 50 years', false, '3f6c6e84-5250-4d64-aa4f-63829a1f984f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e7d1c7a-8dfd-44b8-b336-31a5e4cfddf1', 'The Mughal emperor gave all lands to European traders', false, '3f6c6e84-5250-4d64-aa4f-63829a1f984f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71899115-2103-4b9c-bd6c-391558f52287', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'Match Column I (18th-Century Political Formations) with Column II (Defining Administrative & Geopolitical Features):
(a) Awadh (Sa''adat Khan)       -> (i) Ijaradari revenue farming & synthesis of Awadhi court culture
(b) Bengal (Murshid Quli Khan)  -> (ii) Strict revenue centralization & alliance with Jagat Seth banking house
(c) Maratha Confederacy        -> (iii) Chauth and Sardeshmukhi levies & mobile cavalry warfare
(d) Sikh Misls (Dal Khalsa)    -> (iv) Gurmata democratic consensus & Rakhi protection system', 'Awadh = Ijaradari; Bengal = Jagat Seth alliance; Marathas = Chauth/Sardeshmukhi; Sikhs = Gurmata/Rakhi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66748ac3-ecfe-489d-9b5d-9fb24f2f14c7', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '71899115-2103-4b9c-bd6c-391558f52287');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b208d42c-cadc-428e-bc54-7bbcb59024b0', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '71899115-2103-4b9c-bd6c-391558f52287');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05693fc6-8777-46e6-8949-1beea124754a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '71899115-2103-4b9c-bd6c-391558f52287');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acd65ff6-0321-4766-af1b-6052cdac4df9', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '71899115-2103-4b9c-bd6c-391558f52287');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db37c5d9-b5f6-4b93-a70c-bfd3bdc3717a', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'Read the statements regarding the strategic defeat of the Marathas at the Third Battle of Panipat (1761):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db2505b9-6d82-47c0-ad63-f33afd7f8ef8', 'Statements 1 and 2 only', true, 'db37c5d9-b5f6-4b93-a70c-bfd3bdc3717a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c496420-9b05-4f20-bf17-15b4a528ef2a', 'Statements 2 and 3 only', false, 'db37c5d9-b5f6-4b93-a70c-bfd3bdc3717a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fd47c90-3ed0-4b56-8815-edd9ab0178d6', 'Statements 1 and 3 only', false, 'db37c5d9-b5f6-4b93-a70c-bfd3bdc3717a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf709d1d-0e84-4bd3-94d8-6d9ac2d2f094', 'All Statements 1, 2, and 3', false, 'db37c5d9-b5f6-4b93-a70c-bfd3bdc3717a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b0ddd3f-3767-4347-b344-e172feb31d30', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'Why did the English East India Company manage to conquer the regional successor states of 18th-century India one by one?', 'British colonial conquest exploited regional fragmentation, deploying modern fiscal-military statecraft, naval logistics, and divide-and-rule diplomacy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41f673be-3692-4f82-9b65-ffddf342bccb', 'The regional states lacked pan-Indian political unity, fought ceaseless internecine wars among themselves, and could not match the Company''s disciplined European-trained mercenary armies, modern naval power, and limitless credit from British bond markets', true, '6b0ddd3f-3767-4347-b344-e172feb31d30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a508c4e7-770a-44cc-8155-72a18b7556b8', 'Because Indian states had no soldiers', false, '6b0ddd3f-3767-4347-b344-e172feb31d30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6e5672-cce7-4317-bf4c-a4652285e0d3', 'Because all Indian kings surrendered voluntarily in 1700', false, '6b0ddd3f-3767-4347-b344-e172feb31d30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a1cd7d9-c578-4668-80e4-418586f525f7', 'Because the British possessed nuclear weapons in the 18th century', false, '6b0ddd3f-3767-4347-b344-e172feb31d30');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d2dd566-83b9-40a5-bd2e-71d687050a26', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'What was the administrative significance of the ''Ashtapradhan'' council of eight ministers instituted by Chhatrapati Shivaji Maharaj?', 'Shivaji''s Ashtapradhan was a proto-modern bureaucratic cabinet that institutionalized departmental administration paid in cash (Nagdi).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50283b4b-87db-47fa-beae-47f47f24415c', 'A centralized cabinet where each minister (Peshwa, Amatya, Senapati, Nyayadhish, etc.) headed a specific state department and received direct cash salaries from the treasury, eliminating feudal land grants', true, '1d2dd566-83b9-40a5-bd2e-71d687050a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7acad6db-28a0-4d3c-9d1e-665b7668386f', 'A group of foreign ambassadors', false, '1d2dd566-83b9-40a5-bd2e-71d687050a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20dd19f9-9551-47bd-8202-c74322ad73b0', 'A committee of tax collectors only', false, '1d2dd566-83b9-40a5-bd2e-71d687050a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97b95d55-a789-4d22-ad3c-715cbcbc7f61', 'Eight kings ruling together', false, '1d2dd566-83b9-40a5-bd2e-71d687050a26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02380ec7-e735-4e43-901f-f2a0e313408c', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'How did Sawai Raja Jai Singh''s astronomical ''Jantar Mantars'' contribute to 18th-century scientific observation in India?', 'Sawai Jai Singh''s Jantar Mantars combined Ptolemaic, Islamic (Ulugh Beg), and European observational astronomy in monumental stone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80fe7bb4-9901-44b4-b0af-84c88d0d254f', 'He constructed monumental masonry instruments (like the massive Samrat Yantra sundial) that measured celestial coordinates, solar time, planetary orbits, and eclipses with remarkable geometric precision', true, '02380ec7-e735-4e43-901f-f2a0e313408c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aa846c5-07af-4cdf-8268-c9d080ad6877', 'They were magical astrology temples only', false, '02380ec7-e735-4e43-901f-f2a0e313408c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78737f3b-d15d-4cd8-a9ee-f1a6e74a7614', 'They were built to store gunpowder', false, '02380ec7-e735-4e43-901f-f2a0e313408c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ee8efcd-88b9-423f-a0bf-f1f01a5f31fb', 'They were residential palaces for soldiers', false, '02380ec7-e735-4e43-901f-f2a0e313408c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5560fba3-d3f9-43c5-9a81-9eb3a9f41b78', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'Consider four regional military powers of 18th-century India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('170483ad-bd20-4005-84c2-25302b8450ea', 'Exceptional mobility, terrain mastery, resilient peasant-warrior mobilization, and rapid adoption of innovative ballistics and firearms', true, '5560fba3-d3f9-43c5-9a81-9eb3a9f41b78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e782245-0e8b-4ee1-8be3-fa319c8043e3', 'They all fought on foot without any weapons', false, '5560fba3-d3f9-43c5-9a81-9eb3a9f41b78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9332ba4-b088-4ad0-8425-3b4f7ca830d3', 'They only defended mountain tops', false, '5560fba3-d3f9-43c5-9a81-9eb3a9f41b78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fd603be-76e7-4697-b198-ea4137135e90', 'They bought all their weapons from China', false, '5560fba3-d3f9-43c5-9a81-9eb3a9f41b78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61ee8a85-fa2d-49b5-a732-0b29e8ea93e3', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'Why was the Battle of Plassey (1757) and Battle of Buxar (1764) in Bengal a monumental turning point in modern Indian history?', 'The 1765 Treaty of Allahabad grant of Diwani transformed a commercial trading company into the sovereign territorial master of India''s richest province.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8743cd09-d015-4ac3-9216-e19eb48ba15e', 'The defeat of Nawab Siraj-ud-Daulah and the grant of the Diwani (civil tax collection rights of Bengal, Bihar, and Odisha) to the British East India Company in 1765 laid the foundational territorial empire of British rule in India', true, '61ee8a85-fa2d-49b5-a732-0b29e8ea93e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64101554-7a59-446c-98df-e7dd5e95dc29', 'They ended all wars in India forever', false, '61ee8a85-fa2d-49b5-a732-0b29e8ea93e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c58bbd0d-21db-45c0-9f6d-b07c72dc0dea', 'They resulted in the revival of the Mughal Empire', false, '61ee8a85-fa2d-49b5-a732-0b29e8ea93e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2d50408-4c16-467f-bc34-0b4fc4713911', 'They created the Indian Republic in 1765', false, '61ee8a85-fa2d-49b5-a732-0b29e8ea93e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f7a466e-4116-4c90-a815-0a001173ff93', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'What socio-economic legacy did 18th-century regional state formation leave for modern Indian federal geography?', '18th-century regional formations prefigured the linguistic and socio-cultural geography of modern federal India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('827012f0-1c2a-4d69-ade7-a3dde96f6ccf', 'It demarcated the linguistic, cultural, and political contours of modern Indian states (Maharashtra, Punjab, Bengal, Rajasthan, Hyderabad/Telangana-Andhra, Awadh/UP)', true, '6f7a466e-4116-4c90-a815-0a001173ff93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b8641c9-21dd-4a80-b97a-8d11231336c5', 'It erased all cultural diversity in India', false, '6f7a466e-4116-4c90-a815-0a001173ff93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e939cbb-6f6e-4a4a-8618-84d2a8e9bb27', 'It made all Indians speak only Persian', false, '6f7a466e-4116-4c90-a815-0a001173ff93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d55da497-2ff5-49b6-b4e9-14ccb16cbd5d', 'It turned India into a desert', false, '6f7a466e-4116-4c90-a815-0a001173ff93');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42be5d95-e27e-45ff-967c-272b6f1c036c', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Hard', 'What master historiographical perspective concludes Chapter 10 of NCERT Class 7 History?', 'Chapter 10 encapsulates the political reorganization of 18th-century India: imperial devolution, regional flourishing, and the impending colonial encounter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f781c485-2cdc-49ed-8a92-14be08358e17', 'The eighteenth century was a profound transitional epoch—where the fragmentation of centralized Mughal imperial authority gave birth to vibrant regional kingdoms, setting the stage for the dramatic confrontation between indigenous Indian powers and rising British colonial imperialism', true, '42be5d95-e27e-45ff-967c-272b6f1c036c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02ee24c3-f290-4e33-a215-d8f8e357c09a', 'That the Mughal Empire continued unchanged until today', false, '42be5d95-e27e-45ff-967c-272b6f1c036c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644927c2-a1cd-4b5f-9019-154920ecc72c', 'That India was completely peaceful with no political events', false, '42be5d95-e27e-45ff-967c-272b6f1c036c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9adc3f5-20d0-437f-99b9-0614b1fd54b4', 'That regional kingdoms had no impact on Indian history', false, '42be5d95-e27e-45ff-967c-272b6f1c036c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59e6205c-1be4-4443-8796-7379017889bf', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'जिस शब्द से किसी कार्य के करने या होने का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'क्रिया: जिन शब्दों से किसी कार्य के करने या होने की सूचना मिलती है, उन्हें क्रिया कहते हैं (जैसे: पढ़ना, लिखना, खेलना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('046104a1-3b33-434b-9efa-0fda770aee32', 'क्रिया (Verb)', true, '59e6205c-1be4-4443-8796-7379017889bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b786548-5c5b-45cc-b1f7-450bf686a07c', 'संज्ञा', false, '59e6205c-1be4-4443-8796-7379017889bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32bde35e-65a4-4cf8-9f23-e780da9450c0', 'सर्वनाम', false, '59e6205c-1be4-4443-8796-7379017889bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeb7de55-f2b6-483c-8b00-7f10d19dc446', 'विशेषण', false, '59e6205c-1be4-4443-8796-7379017889bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff0cfbc5-6cbb-48c6-b2da-9f55f74dbd01', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'क्रिया के मूल रूप को व्याकरण में क्या कहा जाता है?', 'धातु: क्रिया के मूल रूप को धातु कहते हैं; इसमें ''ना'' प्रत्यय जोड़ने से क्रिया का सामान्य रूप बनता है (पढ़ + ना = पढ़ना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a1a90f0-acd3-42a8-ab88-50c9bad96693', 'धातु (Root - जैसे: पढ़, लिख, खा, जा, हँस)', true, 'ff0cfbc5-6cbb-48c6-b2da-9f55f74dbd01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8b4820e-a8f7-453e-bd07-16479f70727f', 'प्रत्यय', false, 'ff0cfbc5-6cbb-48c6-b2da-9f55f74dbd01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a75f33c1-3c60-4882-b21d-2a2e9cc422b7', 'उपसर्ग', false, 'ff0cfbc5-6cbb-48c6-b2da-9f55f74dbd01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21af31a4-38c8-4b4e-8794-f0d3ae4276f3', 'कारक', false, 'ff0cfbc5-6cbb-48c6-b2da-9f55f74dbd01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('acff4d8c-06e4-41f5-871e-28c2730fb46d', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'कर्म के आधार पर क्रिया के मुख्य रूप से कितने भेद होते हैं?', 'कर्म के आधार पर क्रिया के 2 भेद होते हैं: अकर्मक (Intransitive) और सकर्मक (Transitive)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a58899d-414d-4602-bce3-11250d1868fb', 'दो भेद (1. अकर्मक क्रिया, 2. सकर्मक क्रिया)', true, 'acff4d8c-06e4-41f5-871e-28c2730fb46d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('625380f6-79a8-4108-87e1-69e2830c6fac', 'तीन भेद', false, 'acff4d8c-06e4-41f5-871e-28c2730fb46d');
