INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ecbbde4-27c7-4840-a279-a512a2223cbd', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'जिस क्रिया में कर्म की आवश्यकता नहीं होती और क्रिया का फल सीधे कर्ता पर पड़ता है (जैसे: ''रोहन सोता है'', ''पक्षी उड़ते हैं''), उसे क्या कहते हैं?', 'अकर्मक क्रिया: जिस क्रिया के साथ कर्म नहीं होता (जैसे: रोना, सोना, हँसना, दौड़ना, उड़ना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6e70270-e27e-4c17-a018-945f5c5208ac', 'अकर्मक क्रिया (Intransitive Verb)', true, '8ecbbde4-27c7-4840-a279-a512a2223cbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbfce35f-95cd-4f38-94b9-6175e5aee2ff', 'सकर्मक क्रिया', false, '8ecbbde4-27c7-4840-a279-a512a2223cbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0735c2e0-cf09-4553-99d3-6a7630734af5', 'प्रेरणार्थक क्रिया', false, '8ecbbde4-27c7-4840-a279-a512a2223cbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7b6b88d-88e8-4dfc-a1c1-bc42d1bf88f7', 'द्विकर्मक क्रिया', false, '8ecbbde4-27c7-4840-a279-a512a2223cbd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('370c8efc-3ce1-4509-95e0-58150edbfd3f', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'जिस क्रिया में कर्म उपस्थित होता है और क्रिया का फल कर्ता पर न पड़कर कर्म पर पड़ता है (जैसे: ''अमित पुस्तक पढ़ता है''), उसे क्या कहते हैं?', 'सकर्मक क्रिया: जिस क्रिया में कार्य का प्रभाव कर्म पर पड़ता है (''अमित पुस्तक पढ़ता है'' में ''पुस्तक'' कर्म है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e0f69d7-af18-47f8-b205-00c9de45678e', 'सकर्मक क्रिया (Transitive Verb)', true, '370c8efc-3ce1-4509-95e0-58150edbfd3f');
