INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af6171a1-0514-48e0-b899-58dbe764e60c', 'नामधातु क्रिया', false, '370c8efc-3ce1-4509-95e0-58150edbfd3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('173d570a-93f7-4d33-b56c-316ff397dcaf', 'पूर्वकालिक क्रिया', false, '370c8efc-3ce1-4509-95e0-58150edbfd3f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81d24a81-9683-40f8-bad2-dcbc6fde4e7e', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'क्रिया के जिस रूप से कार्य के संपन्न होने के ''समय'' (Time) का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'काल: क्रिया के जिस रूप से उसके होने के समय का पता चले, उसे काल कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c455407e-561a-4013-a903-73422b0c84e0', 'काल (Tense)', true, '81d24a81-9683-40f8-bad2-dcbc6fde4e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be782d95-44ef-48c6-ad2e-b36903e3cb77', 'कारक', false, '81d24a81-9683-40f8-bad2-dcbc6fde4e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7489a48-af5b-48ff-bd79-815bdc32960e', 'वाच्य', false, '81d24a81-9683-40f8-bad2-dcbc6fde4e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d74eb4aa-7f02-46fd-b8b6-870af12169d4', 'पुरुष', false, '81d24a81-9683-40f8-bad2-dcbc6fde4e7e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('799f16dc-1f86-4889-a8d5-bed33869a00a', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'हिंदी में काल के मुख्य रूप से कितने भेद होते हैं?', 'काल के 3 मुख्य भेद हैं: भूतकाल (Past), वर्तमान काल (Present), और भविष्यत काल (Future)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bc7462c-5368-4be8-b6bf-f1c87820f661', 'तीन भेद (1. भूतकाल, 2. वर्तमान काल, 3. भविष्यत काल)', true, '799f16dc-1f86-4889-a8d5-bed33869a00a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd7f521f-8a86-47c5-89b3-d6013e567ee9', 'दो भेद', false, '799f16dc-1f86-4889-a8d5-bed33869a00a');
