INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27e40aef-1a66-4372-8c15-49a0867bd1ed', 'पाँच भेद', false, '799f16dc-1f86-4889-a8d5-bed33869a00a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e84ddcb-2b3c-4258-ab1c-3e53a033cc4b', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'क्रिया के जिस रूप से बीते हुए समय में कार्य के संपन्न होने का बोध हो (जैसे: ''वह कल आया था''), उसे क्या कहते हैं?', 'भूतकाल: बीते हुए समय में क्रिया के होने का बोध कराने वाला काल रूप।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('958d8f31-5de8-4f91-86d7-d24ddd475c3e', 'भूतकाल (Past Tense)', true, '8e84ddcb-2b3c-4258-ab1c-3e53a033cc4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d25980c0-b1b4-4af1-86fe-bf711f6592c9', 'वर्तमान काल', false, '8e84ddcb-2b3c-4258-ab1c-3e53a033cc4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40d87d3c-881f-4e28-a852-2585d7b982c8', 'भविष्यत काल', false, '8e84ddcb-2b3c-4258-ab1c-3e53a033cc4b');
