INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('357bfa14-6fe5-41c3-9e85-176dc78e9486', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'क्रिया के जिस रूप से चल रहे वर्तमान समय में कार्य के होने का बोध हो (जैसे: ''बच्चा खेल रहा है''), उसे क्या कहते हैं?', 'वर्तमान काल: वर्तमान समय में क्रिया के संपन्न होने की सूचना देता है।', NOW()) ON CONFLICT DO NOTHING;
