INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c51d8927-efe2-48c9-9084-81ef40a603a0', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'क्रिया के जिस रूप से आने वाले समय में कार्य के होने का बोध हो (जैसे: ''हम कल दिल्ली जाएँगे''), उसे क्या कहते हैं?', 'भविष्यत काल: आने वाले समय में होने वाली क्रिया का बोध कराता है।', NOW()) ON CONFLICT DO NOTHING;
