INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cb91493-0449-47b5-af97-153d5be09010', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', '''रोना, हँसना, सोना, दौड़ना, चलना'' क्रियाएँ सामान्यतः किस भेद के अंतर्गत आती हैं?', 'रोना, हँसना, सोना, जागना, उछलना, तैरना स्वाभाविक शारीरिक अवस्थाएँ हैं जो नित्य अकर्मक होती हैं।', NOW()) ON CONFLICT DO NOTHING;
