INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('453e9e76-46fd-4088-bbbc-cc153bca8200', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', '''अध्यापक ने छात्रों को हिंदी पढ़ाई।'' इस वाक्य में ''पढ़ाई'' किस प्रकार की सकर्मक क्रिया है?', 'द्विकर्मक क्रिया: जिस क्रिया में दो कर्म होते हैं (किसे = छात्रों को, क्या = हिंदी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3c5f638-9ee9-4261-b264-8bb7cb60705b', 'द्विकर्मक क्रिया (इसमें दो कर्म हैं: ''छात्रों को'' [गौण कर्म] और ''हिंदी'' [मुख्य कर्म])', true, '453e9e76-46fd-4088-bbbc-cc153bca8200');
