INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc5d419f-4959-428f-ade2-4d7c39736860', 'नामधातु क्रिया', false, '453e9e76-46fd-4088-bbbc-cc153bca8200');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2bf6a18-39a0-4b85-a362-896518acfb6f', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'सकर्मक और अकर्मक क्रिया की पहचान करने के लिए क्रिया के साथ कौन-से प्रश्नवाचक शब्द लगाकर प्रश्न पूछा जाता है?', 'पहचान नियम: क्रिया + ''क्या/किसे/किसको'' = उत्तर मिले तो सकर्मक, न मिले तो अकर्मक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a0a28b6-61e9-49ac-be13-37b3c153060d', '''क्या'', ''किसे'' या ''किसको'' लगाकर (यदि उत्तर मिल जाए तो सकर्मक, और यदि उत्तर न मिले तो अकर्मक)', true, 'c2bf6a18-39a0-4b85-a362-896518acfb6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cea9229-1c7d-4012-b102-4a6ce468119a', '''कब'' और ''कहाँ'' लगाकर', false, 'c2bf6a18-39a0-4b85-a362-896518acfb6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e936a9e2-3f75-4d1d-916e-f4f7f89defea', '''क्यों'' और ''कैसे'' लगाकर', false, 'c2bf6a18-39a0-4b85-a362-896518acfb6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65ba409e-47cc-471f-9499-b5c6a9bed8c1', '''कितना'' लगाकर', false, 'c2bf6a18-39a0-4b85-a362-896518acfb6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ede62a34-43fc-4ef8-aaa1-8fa1009bec1e', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'जब कर्ता स्वयं कार्य न करके किसी अन्य को कार्य करने के लिए प्रेरित करता है (जैसे: ''माँ नौकरानी से कपड़े धुलवाती है''), तो उस क्रिया को क्या कहते हैं?', 'प्रेरणार्थक क्रिया: जहाँ कर्ता स्वयं कार्य न कर दूसरे को कार्य के लिए प्रेरित करे (लिखना → लिखाना / लिखवाना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69abe005-635d-423f-b6b1-16d0bdc9b657', 'प्रेरणार्थक क्रिया (Causative Verb)', true, 'ede62a34-43fc-4ef8-aaa1-8fa1009bec1e');
