INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f903062-eefb-478c-8d7d-70e429f15f03', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'संज्ञा, सर्वनाम अथवा विशेषण शब्दों से बनने वाली क्रियाओं को क्या कहा जाता है (जैसे: हाथ → हथियाना, बात → बतियाना, शर्म → शर्माना, अपना → अपनाना)?', 'नामधातु क्रिया: संज्ञा, सर्वनाम और विशेषण शब्दों में प्रत्यय जोड़कर बनाई जाने वाली क्रियाएँ।', NOW()) ON CONFLICT DO NOTHING;
