INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('022c5e36-f3a0-4a59-a980-3629f967515e', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'जब दो या दो से अधिक क्रियाएँ मिलकर एक पूर्ण क्रिया का अर्थ प्रकट करती हैं (जैसे: ''वह खाना खा चुका'', ''रेलगाड़ी चल पड़ी''), तो उसे क्या कहते हैं?', 'संयुक्त क्रिया: दो या अधिक धातुओं के मेल से बनी क्रिया (जैसे: ''चल पड़ी'', ''खा लिया'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('679f286a-aec7-4513-8279-3bd309bafacf', 'संयुक्त क्रिया (Compound Verb)', true, '022c5e36-f3a0-4a59-a980-3629f967515e');
