INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('250810cb-168e-4929-b0d0-0a8c196e1f12', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'क्रिया के जिस रूप से यह पता चले कि क्रिया अभी-अभी कुछ ही समय पहले समाप्त हुई है (जैसे: ''मैंने अभी चाय पी है'', ''गाड़ी आई है''), उसे भूतकाल का कौन-सा भेद कहते हैं?', 'आसन्न भूत: क्रिया का निकट अतीत (अभी-अभी) में संपन्न होना प्रकट करने वाला रूप।', NOW()) ON CONFLICT DO NOTHING;
