INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbabbdd7-baf2-4286-8605-718128d2fb12', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'क्रिया के जिस रूप से यह ज्ञात हो कि कार्य भूतकाल में प्रारंभ हुआ था, परन्तु बोलते समय तक समाप्त नहीं हुआ था (जैसे: ''वर्षा हो रही थी'', ''अमित पढ़ रहा था''), उसे क्या कहते हैं?', 'अपूर्ण भूतकाल: भूतकाल में क्रिया की निरंतरता (असमाप्ति) का बोध कराता है।', NOW()) ON CONFLICT DO NOTHING;
