INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('003ff2ec-c334-476d-9507-903083d122d1', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'क्रिया के जिस रूप से भूतकाल में कार्य के पूरा होने में संदेह प्रकट हो (जैसे: ''उसने पत्र पढ़ लिया होगा'', ''गाड़ी छूट गई होगी''), उसे क्या कहते हैं?', 'संदिग्ध भूतकाल: भूतकालिक क्रिया के संपन्न होने में संदेह की स्थिति (होगा/होगी युक्त)।', NOW()) ON CONFLICT DO NOTHING;
