INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0bb9f8f-8745-4a8f-9805-6b4cd9399f95', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'जहाँ भूतकाल की एक क्रिया का होना किसी दूसरी क्रिया पर निर्भर करता है (जैसे: ''यदि परिश्रम करते, तो अवश्य सफल होते''), उसे क्या कहते हैं?', 'हेतुहेतुमद्भूत: जहाँ कारण-कार्य (शर्त) के कारण भूतकाल की क्रिया संपन्न न हो सकी हो।', NOW()) ON CONFLICT DO NOTHING;
