INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30063ca7-81c7-44ad-87d7-55eba730eec0', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', '''सूर्य पूरब में उगता है।'' वाक्य में ''उगता है'' किस काल का उदाहरण है?', 'सामान्य वर्तमान: क्रिया का वर्तमान में सामान्य स्वभाव या सार्वकालिक सत्य प्रकट करने वाला रूप।', NOW()) ON CONFLICT DO NOTHING;
