INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b5b7c06-7d7e-4d73-bec0-6bafd7b8aabc', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', '''लिखना'' क्रिया के प्रथम प्रेरणार्थक और द्वितीय प्रेरणार्थक रूप क्रमशः क्या होंगे?', 'मूल = लिखना; प्रथम प्रेरणार्थक = लिखाना; द्वितीय प्रेरणार्थक = लिखवाना।', NOW()) ON CONFLICT DO NOTHING;
