INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00e8b11b-5d63-4ffe-bdfd-a781ea25a5a7', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', '''गरम'' विशेषण शब्द से बनने वाली ''नामधातु क्रिया'' क्या होगी?', 'गरम (विशेषण) से ''गरमाना'' नामधातु क्रिया बनती है (''ठंडा'' से ''ठंडाना'')।', NOW()) ON CONFLICT DO NOTHING;
