INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6562aa2d-ce4c-4920-b29e-31be029b3705', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', '''बच्चा दूध पीकर स्कूल गया।'' वाक्य में ''पीकर'' क्या है?', '''पीकर'' मुख्य क्रिया ''गया'' से पूर्व संपन्न होने वाली पूर्वकालिक क्रिया है।', NOW()) ON CONFLICT DO NOTHING;
