INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11cff7c8-4067-4fae-b57e-39d142d8b0d4', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', '''पिताजी अखबार पढ़ रहे हैं।'' वाक्य में क्रिया का प्रकार और काल क्या है?', 'कर्म = अखबार (सकर्मक); पढ़ रहे हैं = अपूर्ण/तात्कालिक वर्तमान काल।', NOW()) ON CONFLICT DO NOTHING;
