INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76cd024f-cb6e-42ac-87f5-b67fbf863965', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'भूतकाल के कुल कितने उप-भेद (Sub-types) होते हैं?', 'हिंदी व्याकरण में भूतकाल के 6 उपभेद होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb65017-e47a-4a41-b9d7-38e8135f5e94', '6 उप-भेद (सामान्य भूत, आसन्न भूत, पूर्ण भूत, अपूर्ण भूत, संदिग्ध भूत, हेतुहेतुमद्भूत)', true, '76cd024f-cb6e-42ac-87f5-b67fbf863965');
