INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee294680-9235-45cc-88b4-5ed118893974', '5 उप-भेद', false, '76cd024f-cb6e-42ac-87f5-b67fbf863965');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53abc8b7-b86a-4a8d-a6a2-48821fab3088', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29852d0a-ca8a-4c10-b5a1-2c69473c3a18', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '53abc8b7-b86a-4a8d-a6a2-48821fab3088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ea1a359-2279-488b-b468-7c2d818dced6', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '53abc8b7-b86a-4a8d-a6a2-48821fab3088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3b0b604-a881-4b26-bc5c-f260e27f9bf7', '(A) सही है, परन्तु (R) गलत है।', false, '53abc8b7-b86a-4a8d-a6a2-48821fab3088');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99f4cb0b-2b5f-4466-abd1-0c68aeca605d', '(A) गलत है, परन्तु (R) सही है।', false, '53abc8b7-b86a-4a8d-a6a2-48821fab3088');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f90c6063-55fe-49e4-a160-4488c7d2897f', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'Spot the IMPOSTER in the following group of मूल धातु और उनसे बनी नामधातु क्रियाओं में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('242328ad-b1ba-4395-91d6-bcff07a093e5', 'युग्म 1', false, 'f90c6063-55fe-49e4-a160-4488c7d2897f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9d005ee-24fc-4bf4-8dc0-94db388fa833', 'युग्म 2', false, 'f90c6063-55fe-49e4-a160-4488c7d2897f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('385e1bf1-1ed7-4120-871e-9b3d0b36a8fa', 'युग्म 3', false, 'f90c6063-55fe-49e4-a160-4488c7d2897f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e5e637a-b5a4-4a37-a686-3d59fbbb9c9a', 'युग्म 4 (''चलना'' क्रिया है और ''चलाना'' प्रेरणार्थक क्रिया है ; यह संज्ञा/सर्वनाम से बनी नामधातु क्रिया नहीं है)', true, 'f90c6063-55fe-49e4-a160-4488c7d2897f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87f87abc-20e6-4d02-97b2-9f89a110d81c', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'सुमेलित कीजिए (वाक्य और उनके काल का सही भेद):
(क) उसने खाना खाया था      -> (i) पूर्ण भूतकाल
(ख) वह पत्र लिख रहा था      -> (ii) अपूर्ण भूतकाल
(ग) वह घर पहुँच गया होगा    -> (iii) संदिग्ध भूतकाल
(घ) यदि वर्षा होती तो फसल अच्छी होती -> (iv) हेतुहेतुमद्भूत काल', 'खाया था = पूर्ण भूत; लिख रहा था = अपूर्ण भूत; गया होगा = संदिग्ध भूत; वर्षा होती तो = हेतुहेतुमद्भूत।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a262bcb-ad48-4c20-a5a1-2b4500c808e5', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '87f87abc-20e6-4d02-97b2-9f89a110d81c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03883fc9-cd29-4002-82f1-44dfb9a1addd', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '87f87abc-20e6-4d02-97b2-9f89a110d81c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3209fcf-02bc-4f90-802c-4e7c809fede9', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '87f87abc-20e6-4d02-97b2-9f89a110d81c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f24c078-c1b6-4c1c-afa7-afe1f85ef1a0', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '87f87abc-20e6-4d02-97b2-9f89a110d81c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58dae856-047e-41ae-99d5-01099da804bc', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'सकर्मक क्रिया के दो भेद ''एककर्मक'' और ''द्विकर्मक'' में मुख्य कर्म और गौण कर्म की क्या विशेषता होती है?', 'गौण कर्म = सजीव + ''को'' (विभक्ति सहित); मुख्य कर्म = निर्जीव + क्रिया के सन्निकट (विभक्ति रहित)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc509d2d-9563-4f2a-8700-2bd5ca5d0e22', 'मुख्य कर्म प्रायः अप्राणिवाचक (निर्जीव) होता है और क्रिया के ठीक पहले आता है (बिना विभक्ति के) ; जबकि गौण कर्म प्राणिवाचक (सजीव) होता है और ''को'' विभक्ति सहित आता है (जैसे: ''उसने मुझे [गौण] पुस्तक [मुख्य] दी'')', true, '58dae856-047e-41ae-99d5-01099da804bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b251711-eaa1-4ba2-8bfe-0c66e486b422', 'दोनों कर्म हमेशा सजीव होते हैं', false, '58dae856-047e-41ae-99d5-01099da804bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f8785f7-fa48-4a69-ba10-572641dbec8f', 'मुख्य कर्म हमेशा ''को'' से युक्त होता है', false, '58dae856-047e-41ae-99d5-01099da804bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25642272-892a-453c-ac38-3a59e520375d', 'द्विकर्मक क्रिया में केवल एक ही कर्म होता है', false, '58dae856-047e-41ae-99d5-01099da804bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01aaad9a-5db1-478e-80ec-95bbcdbb2564', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''अकर्मक क्रिया'' का जब ''सकर्मक'' में रूपांतरण किया जाता है, तो कौन-सा युग्म शुद्ध है?', 'अकर्मक से सकर्मक रूपांतरण: गिरना→गिराना, कटना→काटना, मरना→मारना, खुलना→खोलना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51cffdc4-5bd1-4f86-92f5-03f3d3bca55c', 'गिरना (अकर्मक) -> गिराना (सकर्मक) ; कटना (अकर्मक) -> काटना (सकर्मक) ; मरना (अकर्मक) -> मारना (सकर्मक)', true, '01aaad9a-5db1-478e-80ec-95bbcdbb2564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f09c268b-2fc7-49a2-a52d-44420c4e5f9d', 'रोना -> हँसना', false, '01aaad9a-5db1-478e-80ec-95bbcdbb2564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7194f291-0793-4d24-8360-b4242bcd932b', 'सोना -> जागना', false, '01aaad9a-5db1-478e-80ec-95bbcdbb2564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbc1855-b481-4527-8ec6-62035b6cd3d9', 'उड़ना -> दौड़ना', false, '01aaad9a-5db1-478e-80ec-95bbcdbb2564');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bd9022e-61e8-4da9-be92-3a99029b1e26', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'सहायक क्रिया (Auxiliary Verb) और रंजक क्रिया (Explicator) का मुख्य क्रिया के साथ क्या संबंध होता है?', 'सहायक क्रिया काल रूप बनाती है (''रहा है''); रंजक क्रिया संयुक्त क्रिया में अर्थगत छटा व तीव्रता जोड़ती है (''चल दिया'', ''हँस पड़ा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbe1b198-858c-44cc-b53e-317acc801c3a', 'सहायक क्रिया काल और वाच्य का निर्धारण करती है (जैसे: ''है'', ''था'', ''होगा'') ; जबकि रंजक क्रिया मुख्य क्रिया के अर्थ में विशिष्ट भाव, गतिशीलता या आकस्मिकता लाती है (जैसे: ''हँस पड़ा'', ''रो बैठा'')', true, '5bd9022e-61e8-4da9-be92-3a99029b1e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b3f8d21-65d6-4c1c-99fb-40876dae7781', 'सहायक क्रिया केवल स्त्रीलिंग होती है', false, '5bd9022e-61e8-4da9-be92-3a99029b1e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4636432b-388e-4728-be78-d28de5a6c91c', 'रंजक क्रिया का कोई अर्थ नहीं होता', false, '5bd9022e-61e8-4da9-be92-3a99029b1e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4daad81c-de6d-4ebe-9123-2eb5c94205f8', 'दोनों मिलकर क्रिया को अकर्मक बनाती हैं', false, '5bd9022e-61e8-4da9-be92-3a99029b1e26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('550f6294-8c34-4c0e-9cca-60fc977762fc', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'निम्नलिखित वाक्यों में से ''द्विकर्मक क्रिया'' वाले वाक्य का चयन कीजिए:', '''किसे दिखाए'' = पर्यटकों को (गौण कर्म); ''क्या दिखाए'' = गुलाब (मुख्य कर्म) → द्विकर्मक क्रिया।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f18d7925-b40b-4539-9ccc-cd1ecd5bef1f', '''माली ने पर्यटकों को सुंदर गुलाब दिखाए।'' (गौण कर्म: पर्यटकों को, मुख्य कर्म: सुंदर गुलाब)', true, '550f6294-8c34-4c0e-9cca-60fc977762fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64570aae-ca34-464b-aa70-412c810c3543', '''माली पौधों में पानी दे रहा है।''', false, '550f6294-8c34-4c0e-9cca-60fc977762fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cedf91c2-d31d-4783-837f-1957e06f63e8', '''पर्यटक बगीचे में घूम रहे हैं।''', false, '550f6294-8c34-4c0e-9cca-60fc977762fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a0d7d37-2a8e-4e38-8c6b-5b575fcedbab', '''गुलाब बहुत सुंदर खिलते हैं।''', false, '550f6294-8c34-4c0e-9cca-60fc977762fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67b4875a-928f-43b5-b21c-d35edede45fc', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''वह प्रतिदिन पाँच किलोमीटर दौड़ता है।'' वाक्य में ''दौड़ता है'' क्रिया किस भेद की है?', '''पाँच किलोमीटर'' दूरी/मात्रा बताने वाला क्रियाविशेषण है, कर्म नहीं; ''दौड़ना'' नित्य अकर्मक क्रिया है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('880a22bd-863d-4406-8885-ca2cba2922b7', 'अकर्मक क्रिया (क्योंकि ''पाँच किलोमीटर'' यहाँ कर्म नहीं, बल्कि परिमाणवाचक क्रियाविशेषण है)', true, '67b4875a-928f-43b5-b21c-d35edede45fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f41278af-fa9c-43ab-a0f6-b53c14a4783d', 'सकर्मक क्रिया', false, '67b4875a-928f-43b5-b21c-d35edede45fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb11f341-bc07-4631-9e75-cfafab63f450', 'द्विकर्मक क्रिया', false, '67b4875a-928f-43b5-b21c-d35edede45fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('054c07b9-7c0c-4bce-bc65-67e904f5cc89', 'प्रेरणार्थक क्रिया', false, '67b4875a-928f-43b5-b21c-d35edede45fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f80d6995-43f3-453c-80ce-86e075d18dbb', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''अनुराग ने फल खाए।'' इस भूतकालिक वाक्य में कर्ता के साथ ''ने'' विभक्ति का प्रयोग क्यों हुआ?', 'हिंदी व्याकरण का स्वर्णिम नियम: भूतकाल में सकर्मक धातुओं के साथ कर्ता में ''ने'' का प्रयोग अनिवार्य है (Ergative construction)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3015af5f-5fe4-4a5b-aa15-68faaf6896fd', 'सकर्मक क्रिया के भूतकाल (सामान्य, आसन्न, पूर्ण, संदिग्ध) में कर्ता के साथ ''ने'' परसर्ग (कारक चिह्न) का प्रयोग अनिवार्य होता है', true, 'f80d6995-43f3-453c-80ce-86e075d18dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e59b0301-9492-4599-a0eb-1e33615511c1', 'क्योंकि अनुराग पुल्लिंग है', false, 'f80d6995-43f3-453c-80ce-86e075d18dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('540ead57-6726-4f3b-b477-7dcc072939cc', 'क्योंकि फल बहुत मीठे थे', false, 'f80d6995-43f3-453c-80ce-86e075d18dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75964485-a1b6-48b5-9815-a1c512f2f2c2', 'अकर्मक क्रिया के कारण', false, 'f80d6995-43f3-453c-80ce-86e075d18dbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06058ec2-2cec-41ee-b023-92d8e0e91190', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''रामू चाय बना रहा होगा।'' इस वाक्य की क्रिया किस काल की है?', 'रहा होगा / ता होगा = संदिग्ध वर्तमान काल (''इस समय रामू चाय बना रहा होगा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f978e46-d8e2-4222-a105-a92d6ea156dd', 'संदिग्ध वर्तमान काल (वर्तमान में क्रिया के घटित होने में संदेह)', true, '06058ec2-2cec-41ee-b023-92d8e0e91190');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d16bbca-3228-4568-8c81-12234b821410', 'संदिग्ध भूतकाल', false, '06058ec2-2cec-41ee-b023-92d8e0e91190');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56e947ec-6e70-4df8-b83a-371aa11bb288', 'सामान्य भविष्यत काल', false, '06058ec2-2cec-41ee-b023-92d8e0e91190');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb5001c7-bc88-4fe2-a0ff-9142d9703885', 'अपूर्ण भूतकाल', false, '06058ec2-2cec-41ee-b023-92d8e0e91190');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0b23d3e-8c5f-4580-a00a-3f13e0fdb2d9', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''यदि डॉक्टर समय पर आ जाते, तो रोगी की जान बच जाती।'' यह वाक्य किस काल का प्रतिनिधित्व करता है?', 'हेतुहेतुमद्भूत: भूतकाल में कार्य-कारण शर्त पूरी न होने पर क्रिया संपन्न न होने का बोध।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('851a93a9-ae51-4893-8d76-1dfc2984fb4a', 'हेतुहेतुमद्भूत काल', true, 'a0b23d3e-8c5f-4580-a00a-3f13e0fdb2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd0f1ac3-fb0d-49b8-9ed7-021f942ea8fb', 'संदिग्ध भूतकाल', false, 'a0b23d3e-8c5f-4580-a00a-3f13e0fdb2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cd20eed-57bb-4964-9e11-700296fb275b', 'आसन्न भूतकाल', false, 'a0b23d3e-8c5f-4580-a00a-3f13e0fdb2d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('463cbaa8-6338-4965-a463-f29bfcc87346', 'हेतुहेतुमद्भविष्यत काल', false, 'a0b23d3e-8c5f-4580-a00a-3f13e0fdb2d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00911ec8-757a-4d96-b3c4-6b545f88ed23', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'क्रिया और काल के गहन व्याकरणिक ज्ञान का भाषा में क्या सर्वोच्च महत्व है?', 'क्रिया वाक्य का अपरिहार्य संरचनात्मक नाभिक है; क्रिया और काल के शुद्ध अन्वय से ही भाषा में भाव, समय और सार्थकता की पूर्ण अभिव्यक्ति संभव है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad569fba-ceda-4509-9b09-d95d51285edc', 'क्रिया वाक्य का अनिवार्य केंद्रीय मेरुदंड (Spine) है जिसके बिना कोई वाक्य पूर्ण नहीं हो सकता ; काल क्रिया की समय-स्थिति और यथार्थता को सटीक संप्रेषित करता है', true, '00911ec8-757a-4d96-b3c4-6b545f88ed23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82cc581d-d91c-4d4c-bb3c-bcbca1890efd', 'क्रिया केवल नाटकों में प्रयुक्त होती है', false, '00911ec8-757a-4d96-b3c4-6b545f88ed23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d21d0cf6-7e4f-4fa6-b7b6-5dd63e1ba7bc', 'काल केवल ज्योतिष में प्रयुक्त होता है', false, '00911ec8-757a-4d96-b3c4-6b545f88ed23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94c66c5f-7eaf-4970-a5a6-5ed193d76bd3', 'इनके बिना भी वाक्य रचना शुद्ध रहती है', false, '00911ec8-757a-4d96-b3c4-6b545f88ed23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('095ab45e-335c-43ae-957b-f11c2b11dcf1', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'Light travels along which geometric path through a uniform, transparent medium (Rectilinear Propagation of Light)?', 'Rectilinear propagation: light travels along straight lines, causing the formation of sharp shadows and pinhole camera images.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd65e202-70e8-4587-8d50-0638bf26a20b', 'Straight Lines', true, '095ab45e-335c-43ae-957b-f11c2b11dcf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96d4118a-6e39-4241-bdb8-bed281d69281', 'Curved circular lines', false, '095ab45e-335c-43ae-957b-f11c2b11dcf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('474a43fb-16a4-4c39-bd2e-28aa5ff5cf38', 'Zig-zag paths', false, '095ab45e-335c-43ae-957b-f11c2b11dcf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ba230cc-cc54-4933-be83-6f55549da8d8', 'Spiral waves only', false, '095ab45e-335c-43ae-957b-f11c2b11dcf1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10f993b6-f36d-4d0d-b20d-472a2515e442', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'What is the phenomenon of bouncing back of light rays from a polished, shiny, or reflective surface called?', 'Reflection is the change in direction and bouncing back of a light wavefront at an interface between two different media.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b725e22-dab1-4bd4-91b8-f50de345221e', 'Reflection of Light', true, '10f993b6-f36d-4d0d-b20d-472a2515e442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2e4dbe6-09bb-43fe-a215-03746394912f', 'Refraction of Light', false, '10f993b6-f36d-4d0d-b20d-472a2515e442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50673af5-c865-44af-ac7a-c3f9588df9a6', 'Dispersion of Light', false, '10f993b6-f36d-4d0d-b20d-472a2515e442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ece0e361-fc90-43f3-9002-2781f07d7ca7', 'Absorption', false, '10f993b6-f36d-4d0d-b20d-472a2515e442');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a759274-51c3-4245-aefc-5eb8d3eb9aaf', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'What are the characteristics of an image formed by a flat PLANE MIRROR?', 'A plane mirror forms an erect, virtual image of identical size, located at the same distance behind the mirror as the object in front.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0abe96f-7590-4e6f-828c-5618dbb9cc2e', 'Erect (upright), Virtual (cannot be obtained on a screen), Same size as the object, and Laterally Inverted', true, '5a759274-51c3-4245-aefc-5eb8d3eb9aaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dfc384f-77b2-499f-941f-c6489775a4c0', 'Inverted, Real, and Magnified', false, '5a759274-51c3-4245-aefc-5eb8d3eb9aaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42887c76-3974-4c2e-b3df-1a1f0b040cec', 'Real, Diminished, and Upside-down', false, '5a759274-51c3-4245-aefc-5eb8d3eb9aaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6417b0e-70c9-4c3d-a8fb-19759fb48deb', 'Virtual and ten times larger', false, '5a759274-51c3-4245-aefc-5eb8d3eb9aaf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4548f38-3a3e-48d2-a130-0b446ad0df77', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'What optical phenomenon causes your right hand to appear as the left hand and your left hand to appear as the right hand in a mirror image?', 'Lateral inversion is the apparent sideways reversal of left and right in a planar reflection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c051dac-7281-4add-ada1-817c25aeab06', 'Lateral Inversion', true, 'a4548f38-3a3e-48d2-a130-0b446ad0df77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ea4cb60-21d7-4d72-b201-2cdb4e2d7299', 'Refraction', false, 'a4548f38-3a3e-48d2-a130-0b446ad0df77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03e7005b-32c7-48ef-86a7-78d826229c34', 'Dispersion', false, 'a4548f38-3a3e-48d2-a130-0b446ad0df77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c16c2f3-3f20-4b31-81f4-468c153c020a', 'Total Internal Reflection', false, 'a4548f38-3a3e-48d2-a130-0b446ad0df77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ada69ce-351f-4d2d-9e3c-c28981f9dcff', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'Why is the word ''AMBULANCE'' written in reverse laterally inverted script (''ECNALUBMA'') on emergency medical vehicles?', 'Pre-inverting the lettering ensures that when viewed through a driver''s rear-view mirror, lateral inversion renders ''AMBULANCE'' right-side up.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdaa4b2a-a513-4aab-a21f-e3ef43ffbafb', 'So that drivers of vehicles ahead can read the word correctly as ''AMBULANCE'' in their rear-view mirrors and immediately give way', true, '6ada69ce-351f-4d2d-9e3c-c28981f9dcff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('078abec2-8d45-4ab8-bcb5-15ca8fdda76a', 'It is a foreign language spelling', false, '6ada69ce-351f-4d2d-9e3c-c28981f9dcff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acb53768-c47a-45ea-8c50-2cf3934f39de', 'To confuse pedestrians on the road', false, '6ada69ce-351f-4d2d-9e3c-c28981f9dcff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('274846e6-430b-49a9-b3be-3b9ba1892797', 'It is an artistic design', false, '6ada69ce-351f-4d2d-9e3c-c28981f9dcff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9fbc4f4-fc87-47c5-b6f7-4b53cbd2fdf9', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'A spherical mirror whose reflecting surface is curved INWARDS (like the inside surface of a shining spoon) is called a:', 'A concave mirror has an inward-curving converging reflecting surface.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05fea4ed-beae-4c43-b775-117bd174509f', 'Concave Mirror', true, 'f9fbc4f4-fc87-47c5-b6f7-4b53cbd2fdf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3c22759-230e-42ee-92b6-6ee381991dd1', 'Convex Mirror', false, 'f9fbc4f4-fc87-47c5-b6f7-4b53cbd2fdf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6b5582c-0a32-423f-8e7a-a6b0eb54bde0', 'Plane Mirror', false, 'f9fbc4f4-fc87-47c5-b6f7-4b53cbd2fdf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dffed94-3f2a-4d5b-90f3-5377337966ec', 'Cylindrical Mirror', false, 'f9fbc4f4-fc87-47c5-b6f7-4b53cbd2fdf9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0311293f-c3bf-4a45-bbbd-83d509e618ee', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'A spherical mirror whose reflecting surface is curved OUTWARDS (like the back outer surface of a shining spoon) is called a:', 'A convex mirror has an outward-bulging diverging reflecting surface.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39105bfc-01ff-4a9f-9770-ed36e29a66e8', 'Convex Mirror', true, '0311293f-c3bf-4a45-bbbd-83d509e618ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c416b025-7401-4e94-9ec9-5ef76aeb8119', 'Concave Mirror', false, '0311293f-c3bf-4a45-bbbd-83d509e618ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a7164df-04d5-45c3-bc88-3df5eded944b', 'Plane Mirror', false, '0311293f-c3bf-4a45-bbbd-83d509e618ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7718ff5e-c8eb-488f-a7d8-309fd520976e', 'Parabolic Mirror', false, '0311293f-c3bf-4a45-bbbd-83d509e618ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('582ee28a-52da-48bb-851d-ec3bd4381509', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'An image that can be formed and projected onto a physical SCREEN is called a:', 'A real image is formed by the actual physical intersection of reflected/refracted light rays and can be captured on a screen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7522bbd4-74dd-4602-b0d2-93acb4705a5a', 'Real Image', true, '582ee28a-52da-48bb-851d-ec3bd4381509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07292bf8-e982-4619-9e97-eaa950352e28', 'Virtual Image', false, '582ee28a-52da-48bb-851d-ec3bd4381509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89af8656-474d-40c9-8396-2ef4ddb59622', 'Lateral Image', false, '582ee28a-52da-48bb-851d-ec3bd4381509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb19a8e7-58b7-4a3d-a3a1-d6fa3f0afd66', 'Inverted Image only', false, '582ee28a-52da-48bb-851d-ec3bd4381509');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b435d2f-36da-4baf-a3ae-14075738ca0b', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'An image that CANNOT be obtained or projected on a screen is called a:', 'A virtual image occurs where light rays only appear to diverge from a point behind the mirror/lens and cannot be captured on a screen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a968413-4f59-449e-9d82-61cc65f7c000', 'Virtual Image', true, '2b435d2f-36da-4baf-a3ae-14075738ca0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e634d4e8-7975-44d6-bf86-a0db61102bff', 'Real Image', false, '2b435d2f-36da-4baf-a3ae-14075738ca0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('104f7188-2d63-4a7c-b72e-ebc6728905d4', 'Shadow', false, '2b435d2f-36da-4baf-a3ae-14075738ca0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('036b4a07-1ee1-4261-94bf-8f2eca43be3f', 'Magnified Image', false, '2b435d2f-36da-4baf-a3ae-14075738ca0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('244832e7-f4af-4e5c-8fd9-5a95211e641c', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'A transparent optical lens that is THICKER in the middle than at the edges, converging parallel light rays to a focus, is called a:', 'A convex lens is thicker at its center and converges incident parallel light rays toward a real focal point.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2010c92-747e-4bcb-9e58-ed6dc80fbec5', 'Convex Lens (Converging Lens)', true, '244832e7-f4af-4e5c-8fd9-5a95211e641c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb36daf8-e6bc-4043-930d-e4d364a43790', 'Concave Lens', false, '244832e7-f4af-4e5c-8fd9-5a95211e641c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c96f2466-5ee3-4092-b1db-27985ad7546b', 'Plane Lens', false, '244832e7-f4af-4e5c-8fd9-5a95211e641c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35516db3-3e83-420b-8aa0-4b307b8b3ea8', 'Cylindrical Lens', false, '244832e7-f4af-4e5c-8fd9-5a95211e641c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45fbefbd-b273-4d39-9397-689c3465ad49', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'A transparent optical lens that is THINNER in the middle than at the edges, diverging light rays outwards, is called a:', 'A concave lens is thinner at the center than at the periphery, causing parallel light rays to diverge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93653c5d-9b26-409a-835a-3238a2eedbea', 'Concave Lens (Diverging Lens)', true, '45fbefbd-b273-4d39-9397-689c3465ad49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43481075-0df3-4a69-9ad8-6651d87d56f6', 'Convex Lens', false, '45fbefbd-b273-4d39-9397-689c3465ad49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80fbe5fb-b378-4d24-bbf2-66aefe018b65', 'Biconvex Lens', false, '45fbefbd-b273-4d39-9397-689c3465ad49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a78da223-230c-4487-a05a-54959dc361a5', 'Magnifying Lens', false, '45fbefbd-b273-4d39-9397-689c3465ad49');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4cfc5ca-ad50-493f-abb3-1c6c06983c7d', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'White sunlight consists of how many distinct spectral colors that can be split by a glass prism (VIBGYOR)?', 'White light is a polychromatic mixture of seven constituent spectral wavelengths: Violet, Indigo, Blue, Green, Yellow, Orange, Red (VIBGYOR).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb229168-fe7a-4d5d-92a3-63c8bc18e363', 'Seven Colors (Violet, Indigo, Blue, Green, Yellow, Orange, Red)', true, 'c4cfc5ca-ad50-493f-abb3-1c6c06983c7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f7e9e22-7491-4214-95f2-2e5cfd6d496d', 'Three Colors (Red, Blue, Green)', false, 'c4cfc5ca-ad50-493f-abb3-1c6c06983c7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0eccc2d-ff6f-4fc2-acfc-fc33ad186478', 'Five Colors', false, 'c4cfc5ca-ad50-493f-abb3-1c6c06983c7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccb8d5f0-b090-4b37-935a-131e0eba8b2c', 'Only One Color', false, 'c4cfc5ca-ad50-493f-abb3-1c6c06983c7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('056126d3-66ea-48b3-8fe8-5fd1f8787523', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Which type of spherical mirror is used by Dentists to see an enlarged, magnified, and erect image of a patient''s teeth?', 'When an object is placed between the pole and principal focus of a concave mirror, it produces an erect, magnified, virtual image.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('691747a7-0b5e-4772-ac99-5b8c304f5500', 'Concave Mirror (held close to the teeth within its focal length)', true, '056126d3-66ea-48b3-8fe8-5fd1f8787523');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a216d3e-f626-4cdc-9b94-b02300694ae1', 'Convex Mirror', false, '056126d3-66ea-48b3-8fe8-5fd1f8787523');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4e31789-8aad-4168-ad62-09b3d1d9650e', 'Plane Mirror', false, '056126d3-66ea-48b3-8fe8-5fd1f8787523');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38919e12-e3e1-435e-9ede-a8747d509799', 'Bifocal Mirror', false, '056126d3-66ea-48b3-8fe8-5fd1f8787523');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c510c352-aad8-4fe1-9520-38bdd3b89f48', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Why are CONVEX MIRRORS universally installed as side REAR-VIEW MIRRORS in cars, buses, and motorcycles?', 'Convex mirrors curve outwards, producing upright, diminished virtual images that capture an expansive panoramic field of traffic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfdb0c99-5c7f-4930-95c8-764e05add02d', 'They always form erect, diminished images and provide a vastly WIDER FIELD OF VIEW, allowing drivers to see large traffic behind them', true, 'c510c352-aad8-4fe1-9520-38bdd3b89f48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4ecede7-0058-4a9a-934f-c5fdb6dbdc35', 'They magnify objects to look ten times closer', false, 'c510c352-aad8-4fe1-9520-38bdd3b89f48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d661ced-4b5e-4592-b61a-66b9a4b8ec7b', 'They absorb heat from the road', false, 'c510c352-aad8-4fe1-9520-38bdd3b89f48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('480a1b74-4ced-49d8-b43a-3fc0addc0e33', 'They glow in the dark', false, 'c510c352-aad8-4fe1-9520-38bdd3b89f48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0af6a782-bb33-4c70-ba28-0f286f49a482', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What type of spherical mirror is used as reflectors in automobile Headlights, Searchlights, and Solar Furnaces to throw powerful parallel beams of light?', 'Placing a lamp bulb at the focal point of a concave mirror produces a powerful, non-diverging parallel beam of reflected light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3db9e66-0fda-47d4-be29-42611e0a29c1', 'Concave Mirrors (with the light bulb placed at its principal focus)', true, '0af6a782-bb33-4c70-ba28-0f286f49a482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbde83a8-5134-470f-9e44-e46c0e5c989d', 'Convex Mirrors', false, '0af6a782-bb33-4c70-ba28-0f286f49a482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a3bc6b0-bbc9-46c3-aea7-af63c1a263c0', 'Plane Mirrors', false, '0af6a782-bb33-4c70-ba28-0f286f49a482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61066e37-4b3b-4fd1-a97e-d3362d52d038', 'Cylindrical Mirrors', false, '0af6a782-bb33-4c70-ba28-0f286f49a482');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f4cd1f1-fc8c-4d99-b5a9-eedcc999e023', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What type of lens is used as a simple Handheld MAGNIFYING GLASS to read fine print or examine small insect parts?', 'A convex lens produces a magnified, upright, virtual image when an object is held within its focal distance (acting as a simple microscope).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39bdf92f-649f-445b-ab8b-2f6a6c684a17', 'A Convex Lens (held close to the object)', true, '0f4cd1f1-fc8c-4d99-b5a9-eedcc999e023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92f7290a-05f2-486a-887d-3961a6c904e8', 'A Concave Lens', false, '0f4cd1f1-fc8c-4d99-b5a9-eedcc999e023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04dc4ebc-62c9-4f67-96ca-583e3b2b832a', 'A Plane glass plate', false, '0f4cd1f1-fc8c-4d99-b5a9-eedcc999e023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bba6441-ef5d-46be-8dbe-e85d790f7a36', 'A Tinted sunglasses lens', false, '0f4cd1f1-fc8c-4d99-b5a9-eedcc999e023');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c95a4a8-0797-4aab-a987-a7a7ba297766', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What type of image is ALWAYS formed by a CONCAVE LENS, regardless of how far or close the object is placed?', 'A diverging concave lens always forms a virtual, erect, and diminished image located between the optical center and the principal focus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033b6b1b-444a-4b5d-bc90-583d8519ca88', 'Virtual, Erect (upright), and DIMINISHED (smaller in size than the object)', true, '2c95a4a8-0797-4aab-a987-a7a7ba297766');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('608f6a58-578a-452a-98c2-be7a7603bee1', 'Real, Inverted, and Magnified', false, '2c95a4a8-0797-4aab-a987-a7a7ba297766');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cf6e25b-34a7-4aec-b0d7-1f33c50d97c7', 'Real, Erect, and Same size', false, '2c95a4a8-0797-4aab-a987-a7a7ba297766');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89b73672-a031-4649-94bf-744de22138fe', 'Virtual and Magnified', false, '2c95a4a8-0797-4aab-a987-a7a7ba297766');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab87698e-b5f0-4d50-8f12-354d4d2d8b34', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What is the phenomenon of splitting white sunlight into its seven constituent spectral colors when passing through a triangular Glass Prism called?', 'Dispersion occurs because different wavelengths (colors) of light refract (bend) at slightly different angles when passing through glass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c20714e-bb28-46cf-a76e-4ccaa1466406', 'Dispersion of Light', true, 'ab87698e-b5f0-4d50-8f12-354d4d2d8b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edeb33e4-3eac-416d-b69f-25de55df7db1', 'Reflection', false, 'ab87698e-b5f0-4d50-8f12-354d4d2d8b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1862a61b-8ce9-4253-b359-7edcfed10d81', 'Scattering', false, 'ab87698e-b5f0-4d50-8f12-354d4d2d8b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b63157b9-7737-45cd-9a18-f9a65fd6b39a', 'Diffraction', false, 'ab87698e-b5f0-4d50-8f12-354d4d2d8b34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf7935c1-3c91-418d-bc59-c989dbe24244', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'How is a natural RAINBOW formed in the sky after rain showers?', 'Atmospheric raindrops act as spherical prisms: refracting light on entry, internally reflecting it, and dispersing it upon exit into an arc.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e3c3634-b317-4565-95f4-8ca2f47282bd', 'Millions of tiny suspended airborne raindrops act like miniature optical prisms, refracting, dispersing, and internally reflecting sunlight into a spectrum', true, 'cf7935c1-3c91-418d-bc59-c989dbe24244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2355723c-ccec-4c61-bc51-51f26ffb9dd5', 'Clouds paint colors in the sky with water', false, 'cf7935c1-3c91-418d-bc59-c989dbe24244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('525c10f2-2427-443b-9fbd-3493bc64a2b6', 'Sunlight reflects off ocean waves into the sky', false, 'cf7935c1-3c91-418d-bc59-c989dbe24244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66d029aa-9462-4648-b45a-969f547828e8', 'Lightning leaves behind colored dust', false, 'cf7935c1-3c91-418d-bc59-c989dbe24244');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32c9f2b7-1714-4092-affc-5c07ce273bc2', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What happens when a circular circular disc painted with all seven rainbow color segments (Newton''s Disc) is rotated RAPIDLY on its central axis?', 'Newton''s disc demonstrates additive color synthesis: rapid retinal persistence of vision (~1/16 s) superimposes the 7 colors into white light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cfdcde4-3b3e-4346-83e9-f8d5606ef7e1', 'The seven colors blend together due to the persistence of vision, and the disc appears completely WHITE (or pale grayish-white)', true, '32c9f2b7-1714-4092-affc-5c07ce273bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0346d703-7726-4b4e-ac7f-6a59b1bac7a1', 'The disc turns solid black', false, '32c9f2b7-1714-4092-affc-5c07ce273bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba814126-a7d2-4580-9bd2-fe7956d01b45', 'The disc catches fire', false, '32c9f2b7-1714-4092-affc-5c07ce273bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8de8b11d-4216-4d23-8142-4e4829882460', 'The disc becomes transparent like glass', false, '32c9f2b7-1714-4092-affc-5c07ce273bc2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa386820-7cde-4f3e-b61a-f9f51c316816', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'If an object is placed at a distance of 0.5 m in front of a flat plane mirror, what is the total distance between the OBJECT and its IMAGE?', 'Image distance behind mirror equals object distance in front (d = 0.5 m). Total distance between object and image = 0.5 + 0.5 = 1.0 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea6271bb-7bc8-4693-834a-f26032632585', '1.0 m (0.5 m in front + 0.5 m behind = 1.0 m)', true, 'fa386820-7cde-4f3e-b61a-f9f51c316816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95bb3e3d-dc6b-47e4-a39c-de3f16558480', '0.5 m', false, 'fa386820-7cde-4f3e-b61a-f9f51c316816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14c33242-94a5-4346-816f-d619ba2d2a83', '0.25 m', false, 'fa386820-7cde-4f3e-b61a-f9f51c316816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c7b042-64d8-44e6-9847-b5d05d231075', '2.0 m', false, 'fa386820-7cde-4f3e-b61a-f9f51c316816');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bff2436-079d-41d9-97b9-259cf4aab483', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'David is observing his image in a plane mirror. The distance between the mirror and his image is 4 m. If he moves 1 m towards the mirror, what will be the new distance between David and his image?', 'When David moves 1 m closer, object distance = 4 - 1 = 3 m. Image distance = 3 m. Distance between David and his image = 3 + 3 = 6 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46dbe378-4b57-4007-8e98-30529cb2849c', '6 m (New object distance = 3 m ; New image distance = 3 m ; Total = 3 + 3 = 6 m)', true, '5bff2436-079d-41d9-97b9-259cf4aab483');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd9d83d6-f8cf-4b2d-a788-682012224728', '8 m', false, '5bff2436-079d-41d9-97b9-259cf4aab483');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('060fa72e-2cbc-49b3-a365-df1d923ea214', '4 m', false, '5bff2436-079d-41d9-97b9-259cf4aab483');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e7d7c4e-3020-42ae-bbc9-b6fdbcdd3341', '5 m', false, '5bff2436-079d-41d9-97b9-259cf4aab483');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b98c776-45d1-4ff8-b020-3f52a311c7f8', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What happens when you focus direct bright sunlight onto a dry sheet of paper using a powerful CONVEX LENS for a couple of minutes?', 'A converging convex lens focuses incident solar irradiance into a tiny focal spot, concentrating thermal energy above the paper''s kindling point.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6f4421e-5906-4a9a-86bb-9683fa0e6564', 'The lens converges all solar rays to a single intense focal point; thermal concentration heats the paper until it scorches, smokes, and catches fire', true, '0b98c776-45d1-4ff8-b020-3f52a311c7f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0549f690-a465-4afc-a39f-68673a2879d9', 'The paper turns into ice', false, '0b98c776-45d1-4ff8-b020-3f52a311c7f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38d5bc91-885c-4606-830a-77bbf36f132c', 'The paper turns into a mirror', false, '0b98c776-45d1-4ff8-b020-3f52a311c7f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67768f6c-7f78-4620-a931-5c059057ef16', 'The lens breaks into pieces', false, '0b98c776-45d1-4ff8-b020-3f52a311c7f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('418e34c2-3f15-44ad-98d2-41a18588df0d', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Why does the rear-view mirror of a car carry the printed safety warning: ''OBJECTS IN MIRROR ARE CLOSER THAN THEY APPEAR''?', 'Convex mirrors minify images to gain field-of-view; human visual perception equates smaller retinal size with greater distance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4847e06f-2ebc-4bc3-bba2-1eb250cbc61b', 'Because convex mirrors form diminished (smaller) images, which makes approaching vehicles appear further away than their actual physical distance', true, '418e34c2-3f15-44ad-98d2-41a18588df0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b13a3a93-9daf-4fac-9bcb-4fec234da481', 'Because the mirror has a magnifier', false, '418e34c2-3f15-44ad-98d2-41a18588df0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4b2a06e-da1f-4c2e-890d-ca962687c627', 'Because the glass is curved inwards', false, '418e34c2-3f15-44ad-98d2-41a18588df0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5439c8d0-4e73-4cb0-8142-857cd7d6c1d6', 'Because the mirror works with radio waves', false, '418e34c2-3f15-44ad-98d2-41a18588df0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f552de2d-1ee0-4d10-a7d6-e35cd4a1b55c', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Which color of light bends (refracts) the MOST and which color bends the LEAST when white light passes through a glass prism?', 'Cauchy''s dispersion formula: refractive index is inversely proportional to wavelength. High-frequency violet refracts most; low-frequency red refracts least.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e06932e9-7ee0-40af-bfbe-f8a8d3cd6ab6', 'VIOLET bends the most (shortest wavelength), and RED bends the least (longest wavelength)', true, 'f552de2d-1ee0-4d10-a7d6-e35cd4a1b55c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('421596da-aeb5-465b-90c8-e19456ac9730', 'Red bends the most, and Violet bends the least', false, 'f552de2d-1ee0-4d10-a7d6-e35cd4a1b55c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90fdfb7d-10ad-43d9-af77-655868f10753', 'Green bends the most, and Yellow bends the least', false, 'f552de2d-1ee0-4d10-a7d6-e35cd4a1b55c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ac4d287-db57-4ef5-b9ba-fe2a6c3b9248', 'All colors bend at the exact same angle', false, 'f552de2d-1ee0-4d10-a7d6-e35cd4a1b55c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96a12bca-149b-47d5-9d9d-537ac5685646', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What type of mirror is used in large Solar Cookers to concentrate solar energy onto cooking pots?', 'Large parabolic concave mirrors concentrate solar irradiance onto the focal point where cooking utensils are placed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca338c19-e970-4a3a-933d-2ae2360d91d5', 'Concave Mirror (Converging reflector)', true, '96a12bca-149b-47d5-9d9d-537ac5685646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f44feb8b-0f62-4937-bc90-69533bfc05ef', 'Convex Mirror', false, '96a12bca-149b-47d5-9d9d-537ac5685646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4085cadb-7619-41e3-a28c-2e23aa339577', 'Plane Mirror only', false, '96a12bca-149b-47d5-9d9d-537ac5685646');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a62153e-b978-40a0-bddc-042b5dae4fb6', 'Tinted dark glass', false, '96a12bca-149b-47d5-9d9d-537ac5685646');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('531649ff-f27e-41e1-84ea-a28d2d8b5ad2', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Which of the following optical instruments uses combinations of CONVEX LENSES to magnify distant celestial objects like the Moon and planets?', 'Refracting astronomical telescopes combine an objective convex lens of long focal length with an ocular eyepiece convex lens to resolve distant stars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97ce948f-1a7b-48f8-858f-22c1ef812add', 'An Astronomical Telescope', true, '531649ff-f27e-41e1-84ea-a28d2d8b5ad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e689642a-081c-498f-882d-20a32b087f03', 'A Stethoscope', false, '531649ff-f27e-41e1-84ea-a28d2d8b5ad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bb4f2c2-47db-4b7a-a453-69919d425232', 'A Periscope', false, '531649ff-f27e-41e1-84ea-a28d2d8b5ad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9280be03-fa4d-4a2f-be46-6f2786ce7f92', 'A Barometer', false, '531649ff-f27e-41e1-84ea-a28d2d8b5ad2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4fe7ccb0-2210-4b32-8b47-e22dd5707802', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What is the speed of light in vacuum (c)?', 'The universal speed of light in vacuum is approximately 299,792,458 m/s (≈ 3 × 10⁸ m/s or 300,000 km/s).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d1e5e67-6cdf-4109-94e7-ede5a0bec908', 'Approximately 3 × 10⁸ m/s (300,000 km/s)', true, '4fe7ccb0-2210-4b32-8b47-e22dd5707802');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8590f837-88be-4fe7-906c-480eb1140c5c', '3 × 10⁵ m/s', false, '4fe7ccb0-2210-4b32-8b47-e22dd5707802');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0b7c52e-5dde-43f4-a30f-7a68140eb8b6', '3,000 m/s', false, '4fe7ccb0-2210-4b32-8b47-e22dd5707802');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bc7175d-cba0-42e9-b54e-f6942dee9aa9', '300 m/s', false, '4fe7ccb0-2210-4b32-8b47-e22dd5707802');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9063b3a1-673b-4e88-ba0a-45725d5b7c9f', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae28fbe1-c74b-47e3-bd50-62679cc3a6c3', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '9063b3a1-673b-4e88-ba0a-45725d5b7c9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('561a445b-8133-4698-ae1a-c083f3a0280e', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '9063b3a1-673b-4e88-ba0a-45725d5b7c9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce1599f8-c2f6-4892-85da-76023a4f839b', '(A) is true, but (R) is false.', false, '9063b3a1-673b-4e88-ba0a-45725d5b7c9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32eddb11-9f16-4554-8142-e57c482767f4', '(A) is false, but (R) is true.', false, '9063b3a1-673b-4e88-ba0a-45725d5b7c9f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90c9d393-bd1c-4b30-99b6-45257237f7d9', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Spot the IMPOSTER in the following group of Optical Devices and their signature lens/mirror types:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3355b20-64ac-45a0-92ad-d37faa27567f', 'Device 1', false, '90c9d393-bd1c-4b30-99b6-45257237f7d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a62113e-e79b-4bf7-af5d-4489f8ea987d', 'Device 2', false, '90c9d393-bd1c-4b30-99b6-45257237f7d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0197cf1e-23fb-4bca-8d31-d08c364b3ec1', 'Device 3', false, '90c9d393-bd1c-4b30-99b6-45257237f7d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('951234d7-a918-4984-85fc-0fe9c182ce66', 'Device 4 (Astronomical refracting telescopes use precision high-purity CONVEX OPTICAL LENSES, not flat window glass)', true, '90c9d393-bd1c-4b30-99b6-45257237f7d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac96d34c-e0ac-4692-97d2-f6e36ca77042', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Sir Isaac Newton proved in 1666 that white light is a combination of colors by using two identical glass prisms. How did he conduct this experiment?', 'Newton''s classic recombination experiment: an inverted second prism cancels the angular dispersion of the first prism, synthesizing white light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1efa573-77fd-4ddf-9a87-e44be6cc56a1', 'He placed a second identical inverted glass prism in the path of the dispersed spectrum from the first prism, recombining all seven colors back into a single beam of WHITE LIGHT', true, 'ac96d34c-e0ac-4692-97d2-f6e36ca77042');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a26c01da-8647-4916-88ed-40efb7e671e8', 'He painted the second prism with oil', false, 'ac96d34c-e0ac-4692-97d2-f6e36ca77042');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28d94683-2040-4205-b1cf-87730e00fd96', 'He melted the second prism into water', false, 'ac96d34c-e0ac-4692-97d2-f6e36ca77042');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dd17fef-2101-410b-8fa5-4e81678655bd', 'He burned the light beam with a match', false, 'ac96d34c-e0ac-4692-97d2-f6e36ca77042');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3e877ea-4ef2-4e32-b670-2cc51e88ff94', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Match Column I (Optical Elements) with Column II (Image Characteristics & Applications):
(a) Plane Mirror    -> (i) Virtual, erect, identical size, lateral inversion
(b) Convex Mirror   -> (ii) Always virtual, erect, diminished with wide field of view
(c) Concave Mirror  -> (iii) Shaving & dental mirror (magnified virtual image when close)
(d) Concave Lens    -> (iv) Always virtual, erect, diminished; corrects myopia', 'Plane = identical size; Convex mirror = diminished wide field; Concave mirror = shaving/dental; Concave lens = diverging myopia correction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79c1a633-7482-4c0b-af9c-e6d9e665c052', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'a3e877ea-4ef2-4e32-b670-2cc51e88ff94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bbcc32d-7619-4478-b7d4-9f95fa53812d', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'a3e877ea-4ef2-4e32-b670-2cc51e88ff94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0fe8e9e-29a4-4f53-aea9-f6f49a6c13a8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'a3e877ea-4ef2-4e32-b670-2cc51e88ff94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa0aec4b-8ea4-4026-a3fb-56adb1aa1696', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'a3e877ea-4ef2-4e32-b670-2cc51e88ff94');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44d1e80f-b35d-42c7-80a2-b90ca2ad0fea', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Read the statements regarding optical reflection and refraction:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5326127f-1984-42ad-a8b9-ee6f4f932683', 'Statements 1 and 2 only', true, '44d1e80f-b35d-42c7-80a2-b90ca2ad0fea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('201e71b2-4413-4980-a51a-dc802edc245c', 'Statements 2 and 3 only', false, '44d1e80f-b35d-42c7-80a2-b90ca2ad0fea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e858072-c3f4-47b5-973f-1e32a257ebc8', 'Statements 1 and 3 only', false, '44d1e80f-b35d-42c7-80a2-b90ca2ad0fea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fde67024-ce63-415e-a7e8-1181bb4f9d05', 'All Statements 1, 2, and 3', false, '44d1e80f-b35d-42c7-80a2-b90ca2ad0fea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7091e8e-cc85-401c-a976-44a8aeb00e5f', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Why does a pencil partly immersed in a glass tumbler of water appear BENT or BROKEN at the water-air boundary?', 'Refraction at the planar water-air boundary shifts the apparent position of the submerged pencil tip upwards, creating an apparent bend.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db96acf2-ee1c-4b0a-8372-45769e1c9a0e', 'Due to Refraction: light rays emerging from the underwater portion of the pencil bend away from the normal as they pass from denser water into rarer air', true, 'c7091e8e-cc85-401c-a976-44a8aeb00e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d21b5a5e-a7c1-43bb-b0d3-d18b73f91a66', 'Because water dissolves the pencil', false, 'c7091e8e-cc85-401c-a976-44a8aeb00e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee5f23d5-e366-49b4-8af0-62132cd6c28d', 'Because water acts as a mirror', false, 'c7091e8e-cc85-401c-a976-44a8aeb00e5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('245a4241-761a-4bcd-9d26-151988a0cffc', 'Because the glass is curved', false, 'c7091e8e-cc85-401c-a976-44a8aeb00e5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f522cfab-6194-40de-8335-17167246e21c', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'How does a Periscope (used in submarines and military trenches) enable an observer to see objects over walls or above the water surface?', 'A periscope utilizes two plane mirrors set at 45° to provide twin successive 90° reflections, shifting the line of sight over obstacles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a04f9c6f-11c2-45ae-a6ac-8a2b0818081f', 'It uses TWO parallel plane mirrors inclined at an angle of 45° to each other, successively reflecting light rays downwards through a tube', true, 'f522cfab-6194-40de-8335-17167246e21c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('346a84b7-d923-461e-88e5-ee0802c3534f', 'It uses an electric camera with a screen', false, 'f522cfab-6194-40de-8335-17167246e21c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13e7ac1c-e76b-4bf6-a647-dd165a09e075', 'It uses two magnifying lenses only', false, 'f522cfab-6194-40de-8335-17167246e21c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02f41138-1a6d-4c7b-a85b-8e6eb4a3ee4e', 'It works with sound waves', false, 'f522cfab-6194-40de-8335-17167246e21c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46120e68-aca0-4951-b600-03d8d25aa1c0', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Consider four optical scenarios:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3957325f-c868-41b8-9d7a-1f8d2d523c36', 'Scenario 4 only', true, '46120e68-aca0-4951-b600-03d8d25aa1c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fb57fce-4d5a-4dd5-9a8e-ef6828e0b7b7', 'Scenarios 1 and 2 only', false, '46120e68-aca0-4951-b600-03d8d25aa1c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d5e78c0-8ef2-408c-8c5f-4603657d8303', 'Scenarios 2 and 3 only', false, '46120e68-aca0-4951-b600-03d8d25aa1c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a16d24f5-8155-47a8-aff5-3198ec0e108c', 'All 1, 2, 3, and 4', false, '46120e68-aca0-4951-b600-03d8d25aa1c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c5dad26-4f00-4241-86e8-751bc48a771c', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Why does the primary rainbow always appear in the sky in the direction OPPOSITE to the position of the Sun (e.g. in the East in the late afternoon)?', 'Rainbow geometry requires anti-solar alignment: the observer''s back is to the sun so that internal reflection at ~40–42° enters the retina.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('035836ac-3175-474a-8d86-5eb0a3bccad8', 'Because sunlight must enter the raindrops from behind the observer and be internally reflected back towards the observer''s eyes at an angle of ~42°', true, '4c5dad26-4f00-4241-86e8-751bc48a771c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e71c0d61-4305-4824-bee0-08dec6fc41d8', 'Because the Moon pulls the rainbow', false, '4c5dad26-4f00-4241-86e8-751bc48a771c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5efb29b-4dae-4207-b6e5-a162d8be6f6c', 'Because clouds only exist in the east', false, '4c5dad26-4f00-4241-86e8-751bc48a771c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ae8e301-4d16-49fe-8f47-cd5f1ffb3764', 'Because wind blows the colors opposite to the sun', false, '4c5dad26-4f00-4241-86e8-751bc48a771c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6010a60-e350-4dd1-a029-7e8ae09a65b5', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'What is the optical mechanism of ''Persistence of Vision'' in human eye biology that makes motion pictures and Newton''s rotating color disc work?', 'Retinal photoreceptors retain photochemical activation for ~1/16 s (persistence of vision), enabling cinematic animation and color fusion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f143d6b2-30ef-41bf-9c5a-c8483c0d5a52', 'The visual impression of an image on the human retina remains for approximately 1/16th of a second after the light stimulus disappears, allowing sequential frames to blend seamlessly into continuous motion or white light', true, 'b6010a60-e350-4dd1-a029-7e8ae09a65b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('743dcc65-8c1b-4fda-aa85-ec3a27a8b2cf', 'The eye stores images in memory for one hour', false, 'b6010a60-e350-4dd1-a029-7e8ae09a65b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28b6d88d-c7f3-4137-9d50-a58d64171d98', 'The eye blinks every second', false, 'b6010a60-e350-4dd1-a029-7e8ae09a65b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96e35dc6-d5b4-4faa-b417-823cea7b28ac', 'The cornea turns into a prism', false, 'b6010a60-e350-4dd1-a029-7e8ae09a65b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1cecce4-7303-4b59-b4e8-0eced97556aa', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Why are high-intensity parabolic Concave Mirrors used in solar thermal power plants (like Ivanpah or Bhadla Solar Park)?', 'Concentrated Solar Power (CSP) employs massive concave parabolic mirror fields to focus solar flux onto molten-salt heat exchangers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a567e4b7-0968-4460-a58e-b0c67e399561', 'Thousands of giant concave mirrors (heliostats) track the Sun and concentrate thousands of megawatts of thermal solar flux onto a central molten-salt receiver tower to generate superheated steam for turbines', true, 'e1cecce4-7303-4b59-b4e8-0eced97556aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1932a0f5-53cf-4428-bc0a-4bf473da2207', 'To produce cold water for cities', false, 'e1cecce4-7303-4b59-b4e8-0eced97556aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cade1ec-864c-48dd-b0bd-852cf7cc5513', 'To illuminate the night sky', false, 'e1cecce4-7303-4b59-b4e8-0eced97556aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b3112f4-8b6b-470e-bf4f-9045ae76988a', 'To reflect light away from the Earth', false, 'e1cecce4-7303-4b59-b4e8-0eced97556aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07837c2c-9efa-4ca9-9c95-cc4fdfdda437', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'What grand unifying optical principle is established in Chapter 11 of NCERT Class 7 Science?', 'Chapter 11 establishes foundational geometric optics: rectilinear ray propagation, planar and spherical reflection/refraction, and chromatic dispersion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f22c3c8-19f2-46f8-8f5c-9c7f419fe0b2', 'Light—the primary medium of visual perception—governs rectilinear ray propagation, geometric reflection, refractive dispersion, and spherical image formation that underpins modern microscopy, vision correction, astronomical exploration, and solar energy technologies', true, '07837c2c-9efa-4ca9-9c95-cc4fdfdda437');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05fdc450-2927-4458-bf3f-e5226b36cd7d', 'That light has no physical laws', false, '07837c2c-9efa-4ca9-9c95-cc4fdfdda437');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ac4a742-6158-45d4-9118-d0dab8e310dc', 'That colors exist only inside glass prisms', false, '07837c2c-9efa-4ca9-9c95-cc4fdfdda437');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfdbc815-3110-4aef-b0b7-d9ab23f2037b', 'That mirrors can only be made of silver', false, '07837c2c-9efa-4ca9-9c95-cc4fdfdda437');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e2f6f2e-c7f4-4cc6-8bcc-952264aeeca6', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'In the exponential expression 10⁴, what is the BASE and what is the EXPONENT (Power)?', 'In aⁿ, ''a'' is the base that is repeatedly multiplied, and ''n'' is the exponent specifying how many times the base occurs as a factor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a49d5d82-25a0-4903-96b0-82448876c505', 'Base = 10 and Exponent = 4', true, '7e2f6f2e-c7f4-4cc6-8bcc-952264aeeca6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7530a3e-c41a-4fd5-ac88-07389fea6f67', 'Base = 4 and Exponent = 10', false, '7e2f6f2e-c7f4-4cc6-8bcc-952264aeeca6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33fbef67-a927-4fe2-81b1-de6ab78aafac', 'Base = 40 and Exponent = 1', false, '7e2f6f2e-c7f4-4cc6-8bcc-952264aeeca6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1de3b010-c9e2-4ddc-a42f-d90549b11247', 'Base = 100 and Exponent = 4', false, '7e2f6f2e-c7f4-4cc6-8bcc-952264aeeca6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('716cca34-8510-40ae-95e4-5049a27c22ce', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is the numerical value of 2⁶?', '2⁶ = 2 × 2 × 2 × 2 × 2 × 2 = 64.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cabc1512-51e5-4a05-b823-1c6dcb81a792', '64 (2 × 2 × 2 × 2 × 2 × 2 = 64)', true, '716cca34-8510-40ae-95e4-5049a27c22ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f2bdda0-17d1-4b7e-83e9-819df9da7038', '32', false, '716cca34-8510-40ae-95e4-5049a27c22ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f8c66bf-4f06-4a94-94a1-a75f2a9fc3a4', '12', false, '716cca34-8510-40ae-95e4-5049a27c22ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15cd305a-b059-4d65-8401-0cbf51b33723', '128', false, '716cca34-8510-40ae-95e4-5049a27c22ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49590f5a-f5d7-4f1e-a576-5a55b41e902a', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'Express 343 as a power of 7:', '343 = 7 × 49 = 7 × 7 × 7 = 7³.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27292111-df5d-4b06-a20d-96e12f311335', '7³ (7 × 7 × 7 = 49 × 7 = 343)', true, '49590f5a-f5d7-4f1e-a576-5a55b41e902a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bcf592c-180f-40a7-a48c-07b8644420a3', '7⁴', false, '49590f5a-f5d7-4f1e-a576-5a55b41e902a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b18e06f-27e9-4686-ba56-e5dcbe4c3018', '7²', false, '49590f5a-f5d7-4f1e-a576-5a55b41e902a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa4475a7-6202-4fc0-a62f-120bf6209800', '7⁵', false, '49590f5a-f5d7-4f1e-a576-5a55b41e902a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0129bb54-3b2b-497e-a84f-6cae93a3f523', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'Which number is GREATER: 5³ or 3⁵?', '3⁵ = 243 and 5³ = 125; since 243 > 125, 3⁵ is greater.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('079a4079-b2da-44d7-8824-d981e1918a3a', '3⁵ is greater (3⁵ = 243, while 5³ = 125 ; 243 > 125)', true, '0129bb54-3b2b-497e-a84f-6cae93a3f523');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfb986ba-6262-4bfa-8462-6d2825bed4c4', '5³ is greater', false, '0129bb54-3b2b-497e-a84f-6cae93a3f523');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f60bbc6f-6bb0-471f-bfd3-b119fda77b75', 'Both are equal', false, '0129bb54-3b2b-497e-a84f-6cae93a3f523');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49d8ef4a-94e2-4871-8ad5-c149c447c1fa', 'Cannot be determined', false, '0129bb54-3b2b-497e-a84f-6cae93a3f523');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e4ebadd-a3e3-4580-be73-2feca31b9b2c', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'According to the Law of Exponents for MULTIPLICATION with the same base, what is (aᵐ × aⁿ) equal to?', 'Multiplication law of exponents: aᵐ × aⁿ = aᵐ⁺ⁿ.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1f6af12-305e-484a-87fa-54d57eb2952b', 'aᵐ⁺ⁿ', true, '3e4ebadd-a3e3-4580-be73-2feca31b9b2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9297a7e-e9f6-4499-8aec-cd364ab4f0d6', 'aᵐ⁻ⁿ', false, '3e4ebadd-a3e3-4580-be73-2feca31b9b2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e728178e-c0f0-4f03-934b-8dddb64d6b60', 'aᵐⁿ', false, '3e4ebadd-a3e3-4580-be73-2feca31b9b2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d92a311-57b6-4f47-b6d3-9b60265e267b', '(ab)ᵐ⁺ⁿ', false, '3e4ebadd-a3e3-4580-be73-2feca31b9b2c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1348e93-19ff-4382-9657-60ad4eb6afd7', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'According to the Law of Exponents for DIVISION with the same base (where m > n), what is (aᵐ ÷ aⁿ) equal to?', 'Division law of exponents: aᵐ ÷ aⁿ = aᵐ⁻ⁿ.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dd7efd0-8311-46cd-ac82-22b21b240c14', 'aᵐ⁻ⁿ', true, 'f1348e93-19ff-4382-9657-60ad4eb6afd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('451672c2-7a7f-4473-9ee8-6b7796e6e7b8', 'aᵐ⁺ⁿ', false, 'f1348e93-19ff-4382-9657-60ad4eb6afd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09d266b8-9cdf-4bba-916f-34d73531ad81', 'aᵐ/ⁿ', false, 'f1348e93-19ff-4382-9657-60ad4eb6afd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfb5a9fa-acd7-48a2-96e1-377590750fc9', '1', false, 'f1348e93-19ff-4382-9657-60ad4eb6afd7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2104131d-1de9-48a5-8dca-3671514d08e0', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is (aᵐ)ⁿ (power of a power) equal to?', 'Power of a power rule: (aᵐ)ⁿ = aᵐⁿ.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6522b89-223c-4b38-a9b9-395146d68341', 'aᵐⁿ (a raised to the power m × n)', true, '2104131d-1de9-48a5-8dca-3671514d08e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5473ac72-bfd1-4ce8-adc5-7e136955e541', 'aᵐ⁺ⁿ', false, '2104131d-1de9-48a5-8dca-3671514d08e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3551269f-e034-4e34-aba5-6633bd3fa3a4', 'aᵐ⁻ⁿ', false, '2104131d-1de9-48a5-8dca-3671514d08e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcc5ad18-49ba-4b00-af91-aa0e7cb340e0', 'aᵐ/ⁿ', false, '2104131d-1de9-48a5-8dca-3671514d08e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b44481b1-b48b-4330-8e73-79dd27e7f396', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is the value of any non-zero number raised to the power 0 (i.e. a⁰ where a ≠ 0)?', 'Zero exponent law: a⁰ = aᵐ⁻ᵐ = aᵐ / aᵐ = 1 for any non-zero base a.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52fc64ee-352d-4f94-9e46-418add675fef', '1 (e.g. 7⁰ = 1, 100⁰ = 1, x⁰ = 1)', true, 'b44481b1-b48b-4330-8e73-79dd27e7f396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb804d3f-48e3-443f-9fe8-fefad25566bd', '0', false, 'b44481b1-b48b-4330-8e73-79dd27e7f396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33932b7e-c61c-4d66-a93b-2b8f7cd6d576', 'a', false, 'b44481b1-b48b-4330-8e73-79dd27e7f396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('276c068b-2702-4e61-9282-8f531938ca88', 'Infinity', false, 'b44481b1-b48b-4330-8e73-79dd27e7f396');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec9f177b-50c0-41ed-844f-cf8e4443eedd', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is (-1) raised to an EVEN power (e.g. (-1)⁴, (-1)¹⁰⁰) equal to?', 'Negative one raised to any even natural power is always +1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d838ee8-6d8e-4695-862a-880fcc182f7f', '+1', true, 'ec9f177b-50c0-41ed-844f-cf8e4443eedd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e14cbc3-0f43-45ca-8230-b3fb486d8cbb', '-1', false, 'ec9f177b-50c0-41ed-844f-cf8e4443eedd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b2a027f-e91c-421b-9db8-476ff65ae44b', '0', false, 'ec9f177b-50c0-41ed-844f-cf8e4443eedd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53a618dd-511c-4073-9bca-c53f38387d14', 'Even number', false, 'ec9f177b-50c0-41ed-844f-cf8e4443eedd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b618b8c-dd94-40b1-9a09-eef51b630230', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is (-1) raised to an ODD power (e.g. (-1)³, (-1)⁵¹) equal to?', 'Negative one raised to any odd natural power is always -1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2789f3c-b05a-4198-8d48-7d602d7f7f66', '-1', true, '3b618b8c-dd94-40b1-9a09-eef51b630230');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21dae3a3-2ad6-4390-b3bc-50e2dbb61a15', '+1', false, '3b618b8c-dd94-40b1-9a09-eef51b630230');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32557382-ff24-42c5-9f0a-153bcb4b4b35', '0', false, '3b618b8c-dd94-40b1-9a09-eef51b630230');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7929a053-7993-40c7-b0e1-72a1c7181b5c', 'Odd number', false, '3b618b8c-dd94-40b1-9a09-eef51b630230');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0a68c6e-277b-422f-ac80-96ec643ec9d5', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'Simplify: 3² × 3⁴ × 3⁸:', '3²⁺⁴⁺⁸ = 3¹⁴.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08882736-5a15-49d5-a822-6bdb8f9b8f2e', '3¹⁴ (3²⁺⁴⁺⁸ = 3¹⁴)', true, 'd0a68c6e-277b-422f-ac80-96ec643ec9d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30634383-4902-45f4-85fc-ee4a25d51b30', '3⁶⁴', false, 'd0a68c6e-277b-422f-ac80-96ec643ec9d5');
