INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b06cedf9-8e1e-4bcb-ba8a-862a13154f7e', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'Express the speed of light (300,000,000 m/s) in STANDARD SCIENTIFIC NOTATION:', 'Standard form: a number between 1.0 and 10.0 multiplied by a power of 10 → 3.0 × 10⁸ m/s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c1ed97a-56a2-43e4-bf81-90ec7a67b26e', '3.0 × 10⁸ m/s', true, 'b06cedf9-8e1e-4bcb-ba8a-862a13154f7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfea8363-41fe-4c8f-bde4-45087a223879', '30 × 10⁷ m/s', false, 'b06cedf9-8e1e-4bcb-ba8a-862a13154f7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16ee3f8e-81c5-4209-88c9-06a8f29f872e', '0.3 × 10⁹ m/s', false, 'b06cedf9-8e1e-4bcb-ba8a-862a13154f7e');
