INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d60cb9a5-9606-4ae4-b64f-355898d2b503', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Express 729 as a product of powers of prime factors in exponential form:', 'Prime factorization of 729 = 3⁶.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a220168d-e8c1-4de4-9dc3-789618a0e6a7', '3⁶ (729 = 3 × 3 × 3 × 3 × 3 × 3 = 3⁶)', true, 'd60cb9a5-9606-4ae4-b64f-355898d2b503');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2d6c523-817a-47ce-9154-c21cb42ad0c2', '9³', false, 'd60cb9a5-9606-4ae4-b64f-355898d2b503');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('218b8420-67c3-4047-9e4b-3da74a266fcb', '3⁵ × 2', false, 'd60cb9a5-9606-4ae4-b64f-355898d2b503');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29a5942a-d56e-4b64-97b6-d35ccb8839fa', '27²', false, 'd60cb9a5-9606-4ae4-b64f-355898d2b503');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('555945b7-d764-4ab7-97f6-0592a6677f80', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Express 108 × 192 as a product of prime factors only in exponential form:', '108 = 2² × 3³; 192 = 2⁶ × 3¹. Combined product = 2⁸ × 3⁴.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910e991c-6694-471f-9f7a-cded57b5f9b1', '2⁸ × 3⁴ (108 = 2² × 3³ ; 192 = 2⁶ × 3¹ ; Product = 2²⁺⁶ × 3³⁺¹ = 2⁸ × 3⁴)', true, '555945b7-d764-4ab7-97f6-0592a6677f80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b25d260-2cb5-4524-9cb5-e50aff02cd89', '2⁷ × 3⁵', false, '555945b7-d764-4ab7-97f6-0592a6677f80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f6ba4e4-a7e2-489d-a63e-89f27ed8e49a', '2⁶ × 3⁴', false, '555945b7-d764-4ab7-97f6-0592a6677f80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a88e207-c275-4b67-b165-8ec8a7e6409d', '2⁸ × 3⁵', false, '555945b7-d764-4ab7-97f6-0592a6677f80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a1867ef-0a78-4b7f-a203-e6dd1020adb3', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify and write in exponential form: (2²⁰ ÷ 2¹⁵) × 2³:', '2²⁰⁻¹⁵ × 2³ = 2⁵ × 2³ = 2⁸.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdae7998-8f51-41b5-9a1d-c7b0df6ff17e', '2⁸ ((2²⁰⁻¹⁵) × 2³ = 2⁵ × 2³ = 2⁵⁺³ = 2⁸ = 256)', true, '5a1867ef-0a78-4b7f-a203-e6dd1020adb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14d8f0d5-9903-4ec1-8f76-a9579ab9d345', '2⁵', false, '5a1867ef-0a78-4b7f-a203-e6dd1020adb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb7d3d3d-2d19-41ae-a747-1d362c1ed5b0', '2¹⁰', false, '5a1867ef-0a78-4b7f-a203-e6dd1020adb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf660a73-0527-4fb6-9f33-987b9c011fab', '2⁶', false, '5a1867ef-0a78-4b7f-a203-e6dd1020adb3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e28edf59-14b5-412a-8ab2-7c3cf15250de', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (3⁰ + 2⁰) × 5⁰:', '3⁰ = 1, 2⁰ = 1, 5⁰ = 1 → (1 + 1) × 1 = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('489a0f34-ecce-481a-ba82-b8e4afe9d6c6', '2 ((1 + 1) × 1 = 2 × 1 = 2)', true, 'e28edf59-14b5-412a-8ab2-7c3cf15250de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5896197-88dc-468a-bf4b-fd5f010a91f8', '1', false, 'e28edf59-14b5-412a-8ab2-7c3cf15250de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dce1bb4a-f2b0-4509-ab73-246be22a98ac', '0', false, 'e28edf59-14b5-412a-8ab2-7c3cf15250de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c9e8b5d-cd1a-42ec-8254-e5d67a353428', '6', false, 'e28edf59-14b5-412a-8ab2-7c3cf15250de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b08ff725-ec7f-4b58-a4ed-1ac89b733ae6', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (3⁷ / (3⁴ × 3³)):', '3⁷ / 3⁷ = 3⁰ = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62387b3d-f132-47bc-92a0-1558802a2994', '1 (3⁷ / 3⁴⁺³ = 3⁷ / 3⁷ = 3⁷⁻⁷ = 3⁰ = 1)', true, 'b08ff725-ec7f-4b58-a4ed-1ac89b733ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8962b02d-ea7d-4e28-90d4-91ea72b58c96', '3', false, 'b08ff725-ec7f-4b58-a4ed-1ac89b733ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26ca4fc8-5790-448d-a244-8e8344ae5954', '0', false, 'b08ff725-ec7f-4b58-a4ed-1ac89b733ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78e32e43-e71a-4fa7-864d-fbbaab948997', '9', false, 'b08ff725-ec7f-4b58-a4ed-1ac89b733ae6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('617f01a9-d6cc-4177-b937-b4b09a3a5cb8', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify and express in exponential form: (2³ × 3⁴ × 4) / (3 × 32):', '(2⁵ × 3⁴) / (2⁵ × 3¹) = 2⁰ × 3³ = 3³ = 27.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed444059-873e-417b-9254-5d630ff67d5b', '3³ (4 = 2² ; 32 = 2⁵ ; Numerator = 2³ × 2² × 3⁴ = 2⁵ × 3⁴ ; Denominator = 2⁵ × 3¹ ; Value = 2⁵⁻⁵ × 3⁴⁻¹ = 2⁰ × 3³ = 1 × 3³ = 3³ = 27)', true, '617f01a9-d6cc-4177-b937-b4b09a3a5cb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ce534fb-a1c0-436d-825a-efe4280e75cb', '3⁴', false, '617f01a9-d6cc-4177-b937-b4b09a3a5cb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('778bfa7b-e785-43c8-a916-fbbc51f72385', '2³ × 3²', false, '617f01a9-d6cc-4177-b937-b4b09a3a5cb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12f919cc-e935-4002-8d6f-3f2ff2647834', '3²', false, '617f01a9-d6cc-4177-b937-b4b09a3a5cb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63b7683f-7252-4a1a-b13c-e7d0f0ec4e93', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (2⁸ × a⁵) / (4³ × a³):', '4³ = 2⁶. Result = 2⁸⁻⁶ × a⁵⁻³ = 2²a² = 4a².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecf353e2-0caa-4fdc-8e59-42ab203fa350', '4a² or 2²a² (4³ = (2²)³ = 2⁶ ; Expression = (2⁸ / 2⁶) × (a⁵ / a³) = 2⁸⁻⁶ × a⁵⁻³ = 2² × a² = 4a²)', true, '63b7683f-7252-4a1a-b13c-e7d0f0ec4e93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ea5f64-2700-4bfa-874b-d8b74e1db8a1', '2a²', false, '63b7683f-7252-4a1a-b13c-e7d0f0ec4e93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89fd12a4-8f02-4072-9458-29f8cce91502', '8a³', false, '63b7683f-7252-4a1a-b13c-e7d0f0ec4e93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6492d250-8b0a-4446-88d3-eeac55d31bb1', '2⁴a²', false, '63b7683f-7252-4a1a-b13c-e7d0f0ec4e93');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d7c6d7a-01d7-46f8-ad81-a3bfc74eb941', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Expand the number 279,404 in expanded decimal exponential notation:', '279,404 = 2×10⁵ + 7×10⁴ + 9×10³ + 4×10² + 0×10¹ + 4×10⁰.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f806f7f9-3b2d-44bc-85b3-0c4dedaa3b93', '2 × 10⁵ + 7 × 10⁴ + 9 × 10³ + 4 × 10² + 0 × 10¹ + 4 × 10⁰', true, '5d7c6d7a-01d7-46f8-ad81-a3bfc74eb941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c3febf6-074d-46bc-91c5-45a4451ad916', '2 × 10⁴ + 7 × 10³ + 9 × 10² + 4 × 10¹ + 4 × 10⁰', false, '5d7c6d7a-01d7-46f8-ad81-a3bfc74eb941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43dd4452-dc5b-4751-8ab4-f26769e6e416', '2 × 10⁶ + 7 × 10⁵ + 9 × 10⁴ + 4 × 10³ + 4 × 10²', false, '5d7c6d7a-01d7-46f8-ad81-a3bfc74eb941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bec3f035-9690-4b30-aa4e-108cd0af0a28', '279 × 10³ + 404', false, '5d7c6d7a-01d7-46f8-ad81-a3bfc74eb941');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a9b6275-fbba-4dd3-a4b6-073f928f6bac', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Find the number from the expanded form: 8 × 10⁴ + 6 × 10³ + 0 × 10² + 4 × 10¹ + 5 × 10⁰:', '80,000 + 6,000 + 0 + 40 + 5 = 86,045.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3a89d3d-c744-45c7-84e1-f99801f951fc', '86,045', true, '1a9b6275-fbba-4dd3-a4b6-073f928f6bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96c76609-901d-4639-b2b3-8d143dd213fc', '86,450', false, '1a9b6275-fbba-4dd3-a4b6-073f928f6bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fde21029-09ad-489f-817a-d9cb6959b508', '806,045', false, '1a9b6275-fbba-4dd3-a4b6-073f928f6bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91fbc29c-900d-499a-bbbb-6f6938f19f4c', '86,405', false, '1a9b6275-fbba-4dd3-a4b6-073f928f6bac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43b36c68-599b-445e-9116-b05c937e5eac', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'The distance between Sun and Earth is 149,600,000,000 metres. Express this distance in STANDARD SCIENTIFIC FORM:', '149,600,000,000 = 1.496 × 10¹¹ m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6568cc3e-0648-47a2-9620-a9e977aa07ba', '1.496 × 10¹¹ m', true, '43b36c68-599b-445e-9116-b05c937e5eac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e07a650-4e92-4cd8-8f3a-245d7f08dabd', '14.96 × 10¹⁰ m', false, '43b36c68-599b-445e-9116-b05c937e5eac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c317608-b4dc-46c6-8b04-18b2c1bce79c', '149.6 × 10⁹ m', false, '43b36c68-599b-445e-9116-b05c937e5eac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('feb1e570-93e0-44b2-ac85-f84bd83cd6f0', '1.496 × 10¹² m', false, '43b36c68-599b-445e-9116-b05c937e5eac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ba7f0ef-9edc-40e4-bfcb-fd63fdf836dd', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'The population of India in a census was approximately 1,350,000,000. Express it in scientific standard form:', '1,350,000,000 = 1.35 × 10⁹.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86b41672-c840-4208-908d-f6fd80ac3fde', '1.35 × 10⁹', true, '0ba7f0ef-9edc-40e4-bfcb-fd63fdf836dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('012ac0b3-6efd-4c77-b547-7c6d57bce585', '13.5 × 10⁸', false, '0ba7f0ef-9edc-40e4-bfcb-fd63fdf836dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('258cf834-53f4-42bf-bef7-21fa12f5648d', '135 × 10⁷', false, '0ba7f0ef-9edc-40e4-bfcb-fd63fdf836dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3b4577d-4123-4206-98e1-c98142f91724', '1.35 × 10¹⁰', false, '0ba7f0ef-9edc-40e4-bfcb-fd63fdf836dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5b0c570-0d3e-4080-9c4a-1056c5ec3edd', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Compare the numbers: 2.7 × 10¹² and 1.5 × 10⁸:', 'Comparing exponents: 10¹² >> 10⁸, so 2.7 × 10¹² is roughly 18,000 times larger.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe564371-dd8c-475c-b239-08c5eefd55d8', '2.7 × 10¹² is vastly GREATER than 1.5 × 10⁸ (since 10¹² is 10,000 times larger than 10⁸)', true, 'c5b0c570-0d3e-4080-9c4a-1056c5ec3edd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94e2fa3f-500e-4a1f-aaca-0822c3a40b72', '1.5 × 10⁸ is greater', false, 'c5b0c570-0d3e-4080-9c4a-1056c5ec3edd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99f4e244-1a14-4284-80e4-3dcb7b1ad23b', 'Both are approximately equal', false, 'c5b0c570-0d3e-4080-9c4a-1056c5ec3edd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e097fa27-45ff-4b71-9fc3-cfafb121893a', 'Cannot be compared without full expansion', false, 'c5b0c570-0d3e-4080-9c4a-1056c5ec3edd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef6b6f22-2ade-4e16-9aae-e5ad1e4385d3', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: ((5²)³ × 5⁴) ÷ 5⁷:', '5⁶⁺⁴⁻⁷ = 5³ = 125.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca29471-c05d-40ed-9b8a-c502b0f3a2d9', '5³ or 125 ((5⁶ × 5⁴) ÷ 5⁷ = 5⁶⁺⁴ ÷ 5⁷ = 5¹⁰ ÷ 5⁷ = 5¹⁰⁻⁷ = 5³ = 125)', true, 'ef6b6f22-2ade-4e16-9aae-e5ad1e4385d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c5d3633-5bdb-4ea4-8b48-873b4a621669', '5²', false, 'ef6b6f22-2ade-4e16-9aae-e5ad1e4385d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb5fb8c-bea1-494d-95ee-70081fd198b7', '5⁵', false, 'ef6b6f22-2ade-4e16-9aae-e5ad1e4385d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a4b2877-3525-470b-bdec-e3d3e032666a', '1', false, 'ef6b6f22-2ade-4e16-9aae-e5ad1e4385d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('345b2da9-b214-45da-ad90-ce18e94d230e', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (25 × 5² × t⁸) / (10³ × t⁴):', '(5⁴ × t⁸) / (2³ × 5³ × t⁴) = (5⁴⁻³ / 2³) × t⁸⁻⁴ = (5/8) t⁴.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('745081ee-de7e-46dd-aa21-c969759609ad', '(5 / 8) t⁴ (25 × 5² = 5² × 5² = 5⁴ = 625 ; 10³ = (2×5)³ = 2³ × 5³ = 8 × 125 = 1000 ; 625/1000 = 5/8 ; t⁸/t⁴ = t⁴)', true, '345b2da9-b214-45da-ad90-ce18e94d230e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbf63a00-9f77-4720-a6cd-f00665129b8a', '(5 / 4) t⁴', false, '345b2da9-b214-45da-ad90-ce18e94d230e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efbc02df-8141-4753-93f2-e3f28fcaa37f', '(1 / 8) t⁴', false, '345b2da9-b214-45da-ad90-ce18e94d230e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cce6fb6b-b40c-4fc1-acb9-4de819803b97', '5t⁴', false, '345b2da9-b214-45da-ad90-ce18e94d230e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7eb737b0-5271-4591-b4fa-0db798c808f8', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (3⁵ × 10⁵ × 25) / (5⁷ × 6⁵):', '(3⁵ × 2⁵ × 5⁷) / (3⁵ × 2⁵ × 5⁷) = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c90ba4-48b7-41ee-8a9b-98e361477f90', '1 (10⁵ = (2×5)⁵ = 2⁵ × 5⁵ ; 25 = 5² ; 6⁵ = (2×3)⁵ = 2⁵ × 3⁵ ; Numerator = 3⁵ × 2⁵ × 5⁵⁺² = 3⁵ × 2⁵ × 5⁷ ; Denominator = 5⁷ × 2⁵ × 3⁵ ; Value = 1)', true, '7eb737b0-5271-4591-b4fa-0db798c808f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f92e8c1-717d-42c2-856e-9d38526dc386', '5', false, '7eb737b0-5271-4591-b4fa-0db798c808f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bde3f739-0fa2-4be1-8b67-662dcdb0d0b6', '0', false, '7eb737b0-5271-4591-b4fa-0db798c808f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1afa603-97d0-45ab-8cd5-4bde616d7ef4', '10', false, '7eb737b0-5271-4591-b4fa-0db798c808f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbdc9c14-e0e6-443d-bf1d-9b436ebca981', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'If 2ⁿ = 128, find the value of n:', '2⁷ = 2 × 2 × 2 × 2 × 2 × 2 × 2 = 128, so n = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7de20c30-bae4-4292-afab-6167d051f9d8', 'n = 7 (2⁷ = 128)', true, 'fbdc9c14-e0e6-443d-bf1d-9b436ebca981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a744ba73-fd29-4330-93b2-bd0cab8ed7b1', 'n = 6', false, 'fbdc9c14-e0e6-443d-bf1d-9b436ebca981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed3e2136-2c21-4398-98ce-719c5147d274', 'n = 8', false, 'fbdc9c14-e0e6-443d-bf1d-9b436ebca981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c60c2ab-f60c-46d9-b1c0-5c4a2c31bc86', 'n = 5', false, 'fbdc9c14-e0e6-443d-bf1d-9b436ebca981');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60706422-4f6e-4357-8f58-586542b8f044', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecb7c4c0-0a35-407d-b940-f507ae881081', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '60706422-4f6e-4357-8f58-586542b8f044');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc593101-9e1d-4f9b-b1eb-fb6ed9dee5e6', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '60706422-4f6e-4357-8f58-586542b8f044');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7817ab56-eede-4b0e-9d4a-30f77d549853', '(A) is true, but (R) is false.', false, '60706422-4f6e-4357-8f58-586542b8f044');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62f019de-8dcf-46a7-8f15-dc2afc8f76a9', '(A) is false, but (R) is true.', false, '60706422-4f6e-4357-8f58-586542b8f044');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fec71dc-8b6d-48ae-8696-b9d78fb1049e', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Spot the IMPOSTER in the following applications of Laws of Exponents:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41f36e44-ebdf-4d97-ac1e-66f128122fa1', 'Application 1', false, '1fec71dc-8b6d-48ae-8696-b9d78fb1049e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26f0f4cf-0829-4c79-918f-88665eb3efb4', 'Application 2', false, '1fec71dc-8b6d-48ae-8696-b9d78fb1049e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93c32fda-3660-4fc9-a6d4-55b59f757907', 'Application 3', false, '1fec71dc-8b6d-48ae-8696-b9d78fb1049e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41ac79bf-7b27-4e38-8867-e4ee33c25aa7', 'Application 4 (2³ + 2⁴ = 8 + 16 = 24, whereas 2⁷ = 128 ; Exponents cannot be added under ADDITION)', true, '1fec71dc-8b6d-48ae-8696-b9d78fb1049e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2594068b-dde0-4574-a1b9-62f2b33c3644', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'If (2/9)³ × (2/9)⁻⁶ = (2/9)²ᵐ⁻¹, find the value of ''m'':', '3 - 6 = 2m - 1 → -3 = 2m - 1 → 2m = -2 → m = -1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e0f7e9f-df4c-43fb-9d7b-7b62b620fb2c', 'm = -1 (LHS = (2/9)³⁺⁽⁻⁶⁾ = (2/9)⁻³ ; Equating exponents: 2m - 1 = -3 ⇒ 2m = -2 ⇒ m = -1)', true, '2594068b-dde0-4574-a1b9-62f2b33c3644');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81872f16-21a5-4ca7-95ae-7c5112774553', 'm = 1', false, '2594068b-dde0-4574-a1b9-62f2b33c3644');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2055754-8367-4524-a6a2-4e6baf9678cc', 'm = -2', false, '2594068b-dde0-4574-a1b9-62f2b33c3644');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a5bd84-d895-4ca2-b37c-15ecc76debae', 'm = 0', false, '2594068b-dde0-4574-a1b9-62f2b33c3644');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fd45785-ad07-4da5-840b-34cb50688a76', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Match Column I (Exponential Expressions) with Column II (Simplified Values):
(a) (-2)³ × (-10)³ -> (i) 8,000 ((-8) × (-1000) = 8,000)
(b) (-3)² × (-5)²  -> (ii) 225 (9 × 25 = 225)
(c) 0 × 10²⁰       -> (iii) 0
(d) (-1)⁵⁰⁰        -> (iv) +1', '(-2)³(-10)³ = 8000; (-3)²(-5)² = 225; 0×10²⁰ = 0; (-1)⁵⁰⁰ = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c5b3f2f-4ce8-44a1-87f1-4bd1d02376c7', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '1fd45785-ad07-4da5-840b-34cb50688a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad2e94e3-7043-41bf-abfb-cd995075915e', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '1fd45785-ad07-4da5-840b-34cb50688a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60d835cd-66fc-4f38-99fd-f7a069c18d6a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1fd45785-ad07-4da5-840b-34cb50688a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ad5d89b-1741-41a3-b6a9-33080f182b3b', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1fd45785-ad07-4da5-840b-34cb50688a76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b93d1fd6-8c7d-438b-a1b9-a910dc185371', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Read the statements regarding exponential sizes:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3f7cb84-79be-40cf-8808-35ab3c2e8385', 'Statements 1 and 2 only', true, 'b93d1fd6-8c7d-438b-a1b9-a910dc185371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35ee666a-e89a-41be-a64f-f8b651b06502', 'Statements 2 and 3 only', false, 'b93d1fd6-8c7d-438b-a1b9-a910dc185371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa1e6637-2690-46f2-9409-c988dc6f6025', 'Statements 1 and 3 only', false, 'b93d1fd6-8c7d-438b-a1b9-a910dc185371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85cb837f-b139-4040-ba55-29dad5fad070', 'All Statements 1, 2, and 3', false, 'b93d1fd6-8c7d-438b-a1b9-a910dc185371');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6120512a-09b5-45d7-a66f-dcc46863bf13', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Evaluate the expression:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfc65d84-8775-459b-832c-ec1e794bf810', '-9 ((-2)⁴ = 16 ; 3² = 9 ; 5⁰ = 1 ; Numerator = 16 × 9 × 1 = 144 ; Denominator = 16 × (-1) = -16 ; Value = 144 / -16 = -9)', true, '6120512a-09b5-45d7-a66f-dcc46863bf13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17359cea-ba9b-4f1a-ba33-ed197c242fee', '+9', false, '6120512a-09b5-45d7-a66f-dcc46863bf13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df869727-233a-4875-aafc-f60d9482d636', '-16', false, '6120512a-09b5-45d7-a66f-dcc46863bf13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4afcb19f-6900-4abd-a26b-681279cad844', '0', false, '6120512a-09b5-45d7-a66f-dcc46863bf13');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('581f4269-068f-42bf-8fa9-9c1986a951ba', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'If 5²ˣ⁺¹ ÷ 25 = 125, find the value of x:', '5²ˣ⁻¹ = 5³ → 2x - 1 = 3 → 2x = 4 → x = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e2d5d00-f260-48da-b72b-9364d798db43', 'x = 2 (5²ˣ⁺¹ ÷ 5² = 5²ˣ⁺¹⁻² = 5²ˣ⁻¹ ; 125 = 5³ ; 2x - 1 = 3 ⇒ 2x = 4 ⇒ x = 2)', true, '581f4269-068f-42bf-8fa9-9c1986a951ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76bb8c8e-97b1-438a-9488-b73109b97269', 'x = 1', false, '581f4269-068f-42bf-8fa9-9c1986a951ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e73c1bdb-bc65-4f32-8e98-72afc42f92fa', 'x = 3', false, '581f4269-068f-42bf-8fa9-9c1986a951ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74cd64d0-142e-470f-82d2-870d6b7799e8', 'x = 4', false, '581f4269-068f-42bf-8fa9-9c1986a951ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a28603f1-8653-42e5-9688-a6a58a1025eb', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Express (3.2 × 10⁶) + (4.5 × 10⁵) in standard scientific form:', '3.2 × 10⁶ + 0.45 × 10⁶ = 3.65 × 10⁶.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01051d82-c85f-44d6-b2d0-0b32b1d53876', '3.65 × 10⁶ (Convert to matching exponent: 4.5 × 10⁵ = 0.45 × 10⁶ ; Sum = (3.2 + 0.45) × 10⁶ = 3.65 × 10⁶)', true, 'a28603f1-8653-42e5-9688-a6a58a1025eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46c0805b-edc5-44bd-96e0-daddfb47bdf4', '7.7 × 10¹¹', false, 'a28603f1-8653-42e5-9688-a6a58a1025eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3427957-9ae2-49dc-978f-8b7b73b2534c', '7.7 × 10⁶', false, 'a28603f1-8653-42e5-9688-a6a58a1025eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b4f243c-8161-4acb-8fda-07f1dd0140cc', '3.65 × 10⁷', false, 'a28603f1-8653-42e5-9688-a6a58a1025eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88ce6423-7657-4049-894f-e6e142b2556c', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'If 3⁴ × 2⁵ × a = 12⁴, what is the value of ''a''?', '12⁴ = (3 × 4)⁴ = 3⁴ × 2⁸. LHS = 3⁴ × 2⁵ × a. Hence a = 2⁸ / 2⁵ = 2³ = 8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5459cda7-f180-4f9b-8e19-8aad0a411cda', 'a = 16 or 2⁴ (12⁴ = (3 × 2²)⁴ = 3⁴ × 2⁸ ; LHS = 3⁴ × 2⁵ × a ; Equating: 3⁴ × 2⁵ × a = 3⁴ × 2⁸ ⇒ a = 2⁸⁻⁵ = 2³ = 8 ... wait: (2²)⁴ = 2⁸ ; 2⁸ / 2⁵ = 2³ = 8)', false, '88ce6423-7657-4049-894f-e6e142b2556c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98a410c6-8591-44cf-9f52-e6efd952d267', 'a = 8 (2³ = 8)', true, '88ce6423-7657-4049-894f-e6e142b2556c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0ed31e3-67a2-4494-9d17-e3c3bca86b1e', 'a = 4', false, '88ce6423-7657-4049-894f-e6e142b2556c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b6eca01-fb13-4203-a925-2b6f4eb95111', 'a = 2', false, '88ce6423-7657-4049-894f-e6e142b2556c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f0b9f1b-a7c5-4276-99b8-7dd78e18e01a', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'A digital memory card has a capacity of 64 Gigabytes (GB). If 1 GB = 2³⁰ bytes, how many bytes of data can the card store in pure power of 2?', '64 × 2³⁰ = 2⁶ × 2³⁰ = 2³⁶ bytes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3e7dd18-3a75-4598-a240-ac5fb044c5ba', '2³⁶ bytes (64 = 2⁶ ; Capacity = 2⁶ × 2³⁰ = 2⁶⁺³⁰ = 2³⁶ bytes)', true, '5f0b9f1b-a7c5-4276-99b8-7dd78e18e01a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d240bbe4-26fe-4ad6-b1c4-f86587628ab0', '2³⁴ bytes', false, '5f0b9f1b-a7c5-4276-99b8-7dd78e18e01a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2dce44c-23fc-4d6b-b78d-730997b97040', '2⁴⁰ bytes', false, '5f0b9f1b-a7c5-4276-99b8-7dd78e18e01a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bfbc25e-0be0-4940-8b83-4c9f38a8b28e', '2³² bytes', false, '5f0b9f1b-a7c5-4276-99b8-7dd78e18e01a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19f93258-6514-4178-ac7a-1d3fb0c03119', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Simplify: (a³b²c⁴)³ ÷ (a²bc³)²:', 'a⁹⁻⁴ b⁶⁻² c¹²⁻⁶ = a⁵b⁴c⁶.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fcf851f-14ae-4e7c-b713-299dc3cb4a68', 'a⁵b⁴c⁶ (Numerator = a⁹b⁶c¹² ; Denominator = a⁴b²c⁶ ; Quotient = a⁹⁻⁴ b⁶⁻² c¹²⁻⁶ = a⁵b⁴c⁶)', true, '19f93258-6514-4178-ac7a-1d3fb0c03119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ace3a9e-7297-4b67-a86f-da2682fd64a0', 'a⁷b⁴c⁵', false, '19f93258-6514-4178-ac7a-1d3fb0c03119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0332d27b-04b4-48f3-9778-112aabb360e1', 'a⁵b²c⁶', false, '19f93258-6514-4178-ac7a-1d3fb0c03119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d55f961-ef55-4dde-8158-20e0ea089fd7', 'a⁶b⁴c⁶', false, '19f93258-6514-4178-ac7a-1d3fb0c03119');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c16b5ad-fc90-40bc-9313-909c9ea9c196', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Why is Exponential Notation and Standard Form indispensable across modern science, computer science, and astrophysics?', 'Exponential standard notation compresses extreme dynamic ranges spanning subatomic particle scales to cosmic galactic dimensions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3176728d-4608-4e5a-8629-f99c1b7d499e', 'It enables astronomical cosmic scales (like the mass of galaxies 10⁴² kg) and subatomic quantum scales (like Planck length 10⁻³⁵ m) to be written concisely, computed without errors, and manipulated systematically', true, '5c16b5ad-fc90-40bc-9313-909c9ea9c196');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('578694df-b2b8-45f7-b4b2-bd10c99f11d3', 'Because zero takes too long to type', false, '5c16b5ad-fc90-40bc-9313-909c9ea9c196');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4851647d-98fd-4928-88f4-4b5c12129aeb', 'Because calculators cannot display numbers without exponents', false, '5c16b5ad-fc90-40bc-9313-909c9ea9c196');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aa64750-2930-4127-9198-f1b204503571', 'Because ordinary multiplication is banned in physics', false, '5c16b5ad-fc90-40bc-9313-909c9ea9c196');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f139535-cea5-428d-815d-1cad828221c5', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'Who is the author of the celebrated science-fiction story ''An Alien Hand''?', 'Eminent Indian astrophysicist and science-fiction writer Dr. Jayant Narlikar authored ''An Alien Hand''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f830743-bf1c-4051-b76c-35c6aa52095d', 'Jayant Narlikar', true, '6f139535-cea5-428d-815d-1cad828221c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e68a12c7-7ef2-474a-92ac-b6f21e526065', 'Ruskin Bond', false, '6f139535-cea5-428d-815d-1cad828221c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef036fe0-5345-49d8-87f7-3d756015df18', 'Satyajit Ray', false, '6f139535-cea5-428d-815d-1cad828221c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d156b030-6b2e-4fb1-8bd0-9652680d6dbb', 'R.K. Narayan', false, '6f139535-cea5-428d-815d-1cad828221c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf3868d2-e20c-4fdf-a1d6-4c7e0a54dec8', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'Where do Tilloo and his family live in the story ''An Alien Hand''?', 'Tilloo and his parents reside in an underground subterranean habitat on Mars equipped with artificial life-support systems.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('034b68b3-6210-43a6-a1f3-326c7c787048', 'In a technologically advanced underground colony beneath the surface of the planet Mars', true, 'bf3868d2-e20c-4fdf-a1d6-4c7e0a54dec8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('966e1112-76f7-4679-9915-411de20bd5ba', 'On planet Earth in a cave', false, 'bf3868d2-e20c-4fdf-a1d6-4c7e0a54dec8');
