INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27a245de-6f5d-4b14-8f73-6bfd9bc1dc81', 'On a space station orbiting Jupiter', false, 'bf3868d2-e20c-4fdf-a1d6-4c7e0a54dec8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2cbd7b6f-034d-4f6d-a7f2-c1b857631f15', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'Why were the inhabitants of Mars forced to abandon the surface and live underground?', 'Solar atmospheric cooling degraded the Martian surface environment, compelling the survivors to build subterranean biospheres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74ecbe02-c4f5-4322-8062-0e744ac2bfbc', 'The Sun grew hostile and cooled down, upsetting the delicate planetary climate and extinguishing surface life, water, and breathable atmosphere', true, '2cbd7b6f-034d-4f6d-a7f2-c1b857631f15');
