INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f00679c-64d8-4d13-b92c-b438d0444682', 'They loved living in tunnels', false, '2cbd7b6f-034d-4f6d-a7f2-c1b857631f15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2321dad-032a-4909-89d6-7b590f411cab', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'How did Tilloo''s father travel to work each day through the forbidden underground passage?', 'Tilloo''s father used an electronic security card (keycard) to unlock the sealed metal security doors leading to the surface passage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd695ab4-6c60-41ca-9b16-01d45952002f', 'By swiping a specialized electronic security access card into the automatic door slot', true, 'e2321dad-032a-4909-89d6-7b590f411cab');
