INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b4c9c53-df16-4878-b289-58dc4474a0f0', 'By using a heavy iron key', false, 'e2321dad-032a-4909-89d6-7b590f411cab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4d9efe7-21f1-4325-b7e4-a7775243b073', 'By climbing a rope ladder', false, 'e2321dad-032a-4909-89d6-7b590f411cab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d737b8c5-4faa-4057-8153-a4b98fbc0f8e', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What happened when curious Tilloo secretly took his father''s security card and entered the forbidden surface passage?', 'Automated biometric sensors detected Tilloo''s unauthorized entry, alerting security guards who safely returned him to his mother.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc61cccd-468a-4ff7-8542-d92b61ac1ac6', 'Hidden surveillance sensors and mechanical security devices detected him, photographed him, and security guards escorted him back home', true, 'd737b8c5-4faa-4057-8153-a4b98fbc0f8e');
