INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b1a9f79-5947-410b-b739-7ab2cb509d71', 'He was lost forever in the dark', false, 'd737b8c5-4faa-4057-8153-a4b98fbc0f8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69c660c8-0c9e-4db2-9ced-5097156238c7', 'He found buried treasure', false, 'd737b8c5-4faa-4057-8153-a4b98fbc0f8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13177c06-ac2b-4897-9ebd-b9c3b0e2601c', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What special equipment is necessary for Martian scientists to survive while working on the hostile surface of Mars?', 'Mars surface survival mandates an airtight spacesuit for thermal protection, pressure balance, and supplemental oxygen supply.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef0775de-bd35-4160-83a0-0d6668ba0e8e', 'A pressurized protective spacesuit with boots and an oxygen reservoir pack to withstand freezing cold and thin air', true, '13177c06-ac2b-4897-9ebd-b9c3b0e2601c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd6ffbfd-6a40-4fa2-abfc-1e5a93b34f84', 'A warm woolen coat only', false, '13177c06-ac2b-4897-9ebd-b9c3b0e2601c');
