INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e2d802a-93cc-4b4f-b2a6-cab4de76dfb2', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What unexpected celestial event created widespread commotion in the Martian Central Control Room?', 'The Central Control Room radar detected two unmanned interplanetary probes (NASA''s Viking orbiters/landers) heading toward Mars.', NOW()) ON CONFLICT DO NOTHING;
