INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92013a96-6ebe-46eb-9704-8cb78fd17ac5', 'A volcanic eruption underground', false, '8e2d802a-93cc-4b4f-b2a6-cab4de76dfb2');
