INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b82ff54-a45d-4eb1-b84b-ac4fa716ecf1', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What mechanical part emerged from the landed alien spacecraft onto the Martian soil?', 'The Viking lander extended a telescopic mechanical sampler arm (an ''alien hand'') to scoop regolith soil for biological analysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5256351-6a2d-41ce-9015-14abe7c23034', 'A metallic mechanical robotic arm (the ''alien hand'') reaching down to collect Martian soil samples', true, '8b82ff54-a45d-4eb1-b84b-ac4fa716ecf1');
