INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('054ca3c1-4699-45e2-9c31-65f193989f90', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What irresistible object on the Control Room panel caught young Tilloo''s eye when he visited with his father?', 'A bright, prominent red button on the control console fascinated Tilloo, tempting his childish curiosity.', NOW()) ON CONFLICT DO NOTHING;
