INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3fd7628-3683-4bb5-ad45-3cf53459f2d9', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What happened when Tilloo pressed the tempting red button on the console?', 'Pressing the red button activated an interference signal that rendered the mechanical robotic arm on the Martian surface inactive.', NOW()) ON CONFLICT DO NOTHING;
