INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28c14cc7-7355-49f7-8288-d9a5d918cdf6', 'Lights turned off completely', false, 'c3fd7628-3683-4bb5-ad45-3cf53459f2d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2bce5d20-1600-4556-9868-a96f62b402ae', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'Who was the ''Alien'' in the title ''An Alien Hand'' from the perspective of the Martian inhabitants?', 'In a brilliant role-reversal twist, the ''aliens'' are human scientists on Earth whose robotic arm is probing Mars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3ff2591-d7d6-41bb-8956-55ac0b70e944', 'Human beings on Earth (and NASA''s Viking robotic lander)', true, '2bce5d20-1600-4556-9868-a96f62b402ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5002058b-99f1-414c-b031-8381d1d63210', 'Monsters from another galaxy', false, '2bce5d20-1600-4556-9868-a96f62b402ae');
