INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98b4061a-a827-4863-805f-62e48d9a2593', 'Tilloo''s father', false, '2bce5d20-1600-4556-9868-a96f62b402ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ff6d942-9386-4ef8-9d16-11f90ba38f56', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What real-life NASA space exploration mission inspired Dr. Jayant Narlikar''s story ''An Alien Hand''?', 'NASA''s 1976 Viking 1 and 2 Mars lander missions with robotic soil-sampling arms inspired Narlikar''s imaginative perspective.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3481a21c-451e-4c15-8923-cc6a49cbef94', 'The VIKING Mission to Mars (Viking 1 and Viking 2, 1976)', true, '9ff6d942-9386-4ef8-9d16-11f90ba38f56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45bffb13-a9b5-42fe-b0a9-fe9a0066726f', 'The Apollo 11 Moon landing', false, '9ff6d942-9386-4ef8-9d16-11f90ba38f56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e524c752-90eb-49dc-95dd-9a76530e5401', 'The Voyager 1 mission', false, '9ff6d942-9386-4ef8-9d16-11f90ba38f56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd86677c-e42f-4826-959f-0c4c177712c8', 'The Hubble Space Telescope', false, '9ff6d942-9386-4ef8-9d16-11f90ba38f56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5071596b-9c47-4cec-8f11-555bba92447a', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What wise advice did Number One (the in-charge of defense) give to the President''s advisory council regarding the alien spacecraft?', 'Number One argued for strategic discretion: destroying the probes would reveal Martian presence and invite retaliatory exploration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0df54d1f-c415-473a-8d38-2ac14807b25f', 'He advised passive observation and non-interference, warning that destroying the spacecraft would reveal their existence and location to unknown alien civilizations', true, '5071596b-9c47-4cec-8f11-555bba92447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e04c395-6443-4398-b88a-5d81e472c070', 'He advised shooting missiles at the spacecraft immediately', false, '5071596b-9c47-4cec-8f11-555bba92447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07561e05-5244-4857-992c-2de961eee589', 'He advised inviting the aliens to dinner', false, '5071596b-9c47-4cec-8f11-555bba92447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b08384fd-e1d1-4dba-b37e-dc2e7f375bd6', 'He advised abandoning Mars', false, '5071596b-9c47-4cec-8f11-555bba92447a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd2b90f6-ae6a-423b-a802-77faf46978ac', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What did Number Two (the chief scientist) conclude about the approaching alien spacecraft?', 'Number Two''s sensor telemetry confirmed the alien probes carried only robotic instruments without living biological crew.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f0aefa2-a0bc-4bcc-b115-42649a347391', 'He confirmed that the spacecraft were completely unmanned and contained only automated electronic recording instruments, so passive non-interference posed zero danger', true, 'fd2b90f6-ae6a-423b-a802-77faf46978ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('697f47ec-6932-4e8b-bd6e-1fe61f02457f', 'He said the craft were filled with dangerous soldiers', false, 'fd2b90f6-ae6a-423b-a802-77faf46978ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb895124-eace-4db4-a210-4d7d15cf4c01', 'He thought they were birds', false, 'fd2b90f6-ae6a-423b-a802-77faf46978ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97438951-e7cb-4fa5-a5e1-8d0d03f7daec', 'He claimed they were asteroids', false, 'fd2b90f6-ae6a-423b-a802-77faf46978ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4eac6d5f-3cde-4840-881d-dab905bcba09', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'How did NASA scientists on Earth explain the sudden mechanical failure of the Viking lander''s robotic arm to news reporters?', 'NASA scientists treated the arm stoppage as an enigmatic electronic malfunction and restored functionality remotely via radio telecommands.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd211b71-6110-41e8-8f15-1f99f3150f60', 'They announced that the mechanical arm had developed a minor unexpected technical glitch, but their Earth-based engineers were transmitting corrective radio signals to reactivate it', true, '4eac6d5f-3cde-4840-881d-dab905bcba09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d06bf3-d02e-4855-b4cb-2b39d5026f7d', 'They announced they were attacked by Martians', false, '4eac6d5f-3cde-4840-881d-dab905bcba09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('551152fe-e81e-40e9-9881-9e6eb049c96e', 'They said the mission was abandoned', false, '4eac6d5f-3cde-4840-881d-dab905bcba09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cf736e4-ed6a-4869-90d8-6b22e8598b62', 'They claimed the camera broke', false, '4eac6d5f-3cde-4840-881d-dab905bcba09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74cec068-29fd-4d48-a335-b6eafe2ea6cf', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What was the final conclusion reached by Earth scientists after analyzing the Martian soil samples collected by the Viking lander?', 'The ironic climax: NASA concluded Mars is lifeless, while the underground Martian civilization continues to flourish in secret.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17f14060-2bfb-4134-8a5f-2c7f2404ea4f', 'The soil samples showed NO SIGNS OF LIFE, leaving Earth scientists disappointed, while the Martians remained safely hidden underground', true, '74cec068-29fd-4d48-a335-b6eafe2ea6cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7ebe94d-afbb-4019-b4ca-7fc2bb2c3cc3', 'They discovered intelligent aliens living in cities', false, '74cec068-29fd-4d48-a335-b6eafe2ea6cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('313c89e0-ae69-4083-bce6-b7f938d361f0', 'They found vast gold mines', false, '74cec068-29fd-4d48-a335-b6eafe2ea6cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc93851a-aea3-4538-9c27-11312d7559f9', 'They proved Mars was made of cheese', false, '74cec068-29fd-4d48-a335-b6eafe2ea6cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f0830db-01f2-4a8e-abdb-42ec5ddd33b2', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What literary technique is central to the narrative perspective of ''An Alien Hand''?', 'Perspective inversion: presenting humanity as mysterious ''aliens'' through the empathetic eyes of a Martian boy and his family.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00322ce5-c3f6-4a87-b307-2912c0049698', 'Dramatic Irony and Role Reversal (narrating human space exploration from the viewpoint of the Martian natives)', true, '5f0830db-01f2-4a8e-abdb-42ec5ddd33b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd3d7862-1942-48ca-9b95-1d77ab14f0a1', 'Tragic Flashback', false, '5f0830db-01f2-4a8e-abdb-42ec5ddd33b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b34fb9f8-352d-45f6-bdcf-1d45b7f6ad34', 'Allegorical Satire on Animals', false, '5f0830db-01f2-4a8e-abdb-42ec5ddd33b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4e9df51-7407-45c6-996f-2ca0098101da', 'Poetic Verse', false, '5f0830db-01f2-4a8e-abdb-42ec5ddd33b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e2bdcfb-adfd-401b-9d0e-f2c9c721f4b2', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What is the SYNONYM of ''Hostile'' as used to describe the Martian surface climate?', '''Hostile'' environment denotes an inhospitable, severe, life-threatening physical climate.', NOW()) ON CONFLICT DO NOTHING;
