INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71302293-e2fb-41e4-aac0-9e24fe3dc5dd', 'Tilloo asked his father if he could go to the surface that day.', true, 'd9463f99-2fe9-40a6-9043-d358f39ed90f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6017a7b2-131a-40d3-890a-365c9a6ce17d', 'Tilloo asked his father that can I go to surface today.', false, 'd9463f99-2fe9-40a6-9043-d358f39ed90f');
