INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b20361d2-5ca0-4b86-afe8-04474ec6e08f', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What character trait is prominently displayed by Tilloo throughout the story?', 'Tilloo embodies universal childhood curiosity: daring to swipe the card, longing to see the sun, and pressing the mysterious red button.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10a84282-a5c9-4fdb-a38f-edfbd300ef5b', 'Irrepressible curiosity, youthful adventure, and eagerness to explore the unknown', true, 'b20361d2-5ca0-4b86-afe8-04474ec6e08f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('313b1244-e7ee-4f12-9342-11f3de2fbc8c', 'Cowardice and fear of shadows', false, 'b20361d2-5ca0-4b86-afe8-04474ec6e08f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c987ecb0-7496-4a51-a428-c07142c57c54', 'Greed for money', false, 'b20361d2-5ca0-4b86-afe8-04474ec6e08f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82e6d37b-e1ed-46b7-8c35-388ef84fdec5', 'Anger towards his parents', false, 'b20361d2-5ca0-4b86-afe8-04474ec6e08f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fd0166c-32bc-4733-b48c-316229927992', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What is the meaning of the phrase ''A blessing in disguise''?', 'Idiom meaning: something that seems unfortunate at first (Tilloo getting caught / pressing button) but results in positive outcomes/safety.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb6003a5-f6a1-421c-81ce-29459112ad51', 'An apparent misfortune or mistake that ultimately produces a beneficial outcome', true, '7fd0166c-32bc-4733-b48c-316229927992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85f815b0-1635-4393-82d1-d4393ff77c06', 'A religious ritual', false, '7fd0166c-32bc-4733-b48c-316229927992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32fe3933-13d4-4d50-8554-03b5a36e711f', 'A gift wrapped in paper', false, '7fd0166c-32bc-4733-b48c-316229927992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d482ee42-5524-40d2-bdb2-c0b19c94c877', 'A curse that brings harm', false, '7fd0166c-32bc-4733-b48c-316229927992');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e2ac4c8-2cc8-4412-b911-2556d4f1b5bb', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'Identify the figure of speech in: ''The mechanical hand was like a giant metallic spider reaching for the soil.''', 'Explicit comparison utilizing the comparative connector ''like'' constitutes a Simile.', NOW()) ON CONFLICT DO NOTHING;
