INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9537dfc-6b06-494b-9fa9-a2bc00a72e05', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What do the Martian leaders value above all in their response to the alien arrival?', 'The Martian council demonstrates scientific wisdom, restraint, and calculated pacifism to protect their subterranean community.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5aa266da-4e68-42ac-a5a5-d04435894b38', 'Prudence, collective consensus, non-violence, and self-preservation of their hidden civilization', true, 'a9537dfc-6b06-494b-9fa9-a2bc00a72e05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9458054e-eb85-4f31-b491-36377a5f1f3c', 'Aggressive military conquest of other planets', false, 'a9537dfc-6b06-494b-9fa9-a2bc00a72e05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f75b6c-ee9d-4066-9701-239c69755a75', 'Destroying every object in space', false, 'a9537dfc-6b06-494b-9fa9-a2bc00a72e05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e5802cb-602b-41f5-9e68-bbccd7809514', 'Surrendering without thinking', false, 'a9537dfc-6b06-494b-9fa9-a2bc00a72e05');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f677bcd4-11f8-46e0-8d54-50c2b8999c66', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What scientific truth about Mars does the story reflect accurately?', 'Dr. Narlikar incorporates rigorous astrophysics: Mars'' rarefied CO₂ atmosphere, extreme cold, and barren regolith.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7a8cc71-3b30-431e-a91b-3e0d7505154a', 'Mars has extremely thin unbreathable atmosphere, freezing sub-zero temperatures, and barren dry soil regolith', true, 'f677bcd4-11f8-46e0-8d54-50c2b8999c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e034c449-788b-4d3d-9604-84b28864f89e', 'Mars has vast tropical oceans with fish', false, 'f677bcd4-11f8-46e0-8d54-50c2b8999c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71f8a3ba-f585-4733-a4ce-d69680a70dd5', 'Mars is covered with green forests', false, 'f677bcd4-11f8-46e0-8d54-50c2b8999c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24e299ee-0926-4c2f-9013-88aa1998e852', 'Mars is hotter than Venus', false, 'f677bcd4-11f8-46e0-8d54-50c2b8999c66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83cb56cf-8c68-49b7-85fe-5732d73c6cdb', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87d2682f-3646-45e8-bd66-493f206ef61e', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '83cb56cf-8c68-49b7-85fe-5732d73c6cdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b1a46c9-53c1-43ca-bcc6-f8832fde3ff4', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '83cb56cf-8c68-49b7-85fe-5732d73c6cdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60cda698-184d-46fe-a894-ec6bdbce3cdd', '(A) is true, but (R) is false.', false, '83cb56cf-8c68-49b7-85fe-5732d73c6cdb');
