INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53ee25bd-31bf-415c-bc75-e44ac0873030', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'Spot the IMPOSTER in the following character roles and decisions in ''An Alien Hand'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45b92bae-8e85-417d-8894-19f1ca830cf9', 'Character 1', false, '53ee25bd-31bf-415c-bc75-e44ac0873030');
