INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6399b5-0305-407c-a6bb-d78449aac58b', 'Character 3', false, '53ee25bd-31bf-415c-bc75-e44ac0873030');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5728f897-34c0-4c4e-888d-57bb0ffc2757', 'Character 4 (Tilloo''s father is a gentle, dedicated subterranean maintenance technician, NOT a space pirate)', true, '53ee25bd-31bf-415c-bc75-e44ac0873030');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4888c037-0ed0-4c08-b920-46a41f4da898', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'Analyze the profound ecological cautionary tale embedded in the backstory of Martian subterranean life:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aafa28e3-eafc-4219-8c76-6265b95fbe13', 'Disrupting planetary climate and solar-ecological equilibrium can destroy surface habitability, rendering a thriving planet barren and forcing survivors into precarious subterranean technological shelters', true, '4888c037-0ed0-4c08-b920-46a41f4da898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c295f844-07ad-4803-9113-d75b83bd7898', 'That building rockets is useless', false, '4888c037-0ed0-4c08-b920-46a41f4da898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('673a0088-fa7a-444a-88ed-fdf0d86f2046', 'That living underground is always better than living in nature', false, '4888c037-0ed0-4c08-b920-46a41f4da898');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('208f1bd5-4722-45e3-af0d-66084ff9811d', 'That aliens will soon destroy Earth''s atmosphere', false, '4888c037-0ed0-4c08-b920-46a41f4da898');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d6fa3d9-cd94-4208-8439-bb6f3d5e56b1', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'Match Column I (Literary Elements of ''An Alien Hand'') with Column II (Story Manifestations):
(a) Inciting Incident   -> (i) Tilloo steals father''s security card and explores surface tunnel
(b) Rising Action       -> (ii) Two alien Viking spacecraft approach and land on Mars
(c) Climax              -> (iii) Tilloo presses the red button, halting the mechanical arm
(d) Resolution          -> (iv) NASA repairs the arm remotely and declares Mars lifeless', 'Inciting incident = card theft; Rising action = Viking landing; Climax = red button press; Resolution = NASA declaration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('360bc264-5c90-4fb6-bf9f-6db62526ad1f', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '1d6fa3d9-cd94-4208-8439-bb6f3d5e56b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2791572-08b4-4f85-bf7d-54dbbd4c3ba6', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '1d6fa3d9-cd94-4208-8439-bb6f3d5e56b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5755297e-695b-4cfd-9405-e4b595c6220b', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1d6fa3d9-cd94-4208-8439-bb6f3d5e56b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af321c2b-99b8-4067-a4a6-17edab90fbeb', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1d6fa3d9-cd94-4208-8439-bb6f3d5e56b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('039f87b9-72d5-4853-9dbe-b47fe30b2570', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'Read the statements regarding the story''s climax:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c88a9bf-a8cd-41bb-b0c6-9f8a07269643', 'Statements 1 and 2 only', true, '039f87b9-72d5-4853-9dbe-b47fe30b2570');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0279620a-b03b-459f-9463-95331c18bfb4', 'Statements 2 and 3 only', false, '039f87b9-72d5-4853-9dbe-b47fe30b2570');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83091e51-ee5c-4135-85be-1335ba5b93b4', 'Statements 1 and 3 only', false, '039f87b9-72d5-4853-9dbe-b47fe30b2570');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('994ea46c-0c8b-428f-97ad-b8a7002087ae', 'All Statements 1, 2, and 3', false, '039f87b9-72d5-4853-9dbe-b47fe30b2570');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db263ecd-457e-4f9e-b1c2-309625bcec61', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'Identify the syntactic structure of: ''**Had Tilloo not pressed the red button**, the alien mechanical hand would have gathered soil samples without interruption.''', 'Inverted conditional without ''if'' (''Had Tilloo not pressed...'') forms a formal Third Conditional expressing unreal past conditions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a988510-adee-4cdf-806e-c3f8bd8b82fa', 'Inverted Third Conditional expressing hypothetical past counterfactual condition', true, 'db263ecd-457e-4f9e-b1c2-309625bcec61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1b6c157-d6fb-4d48-bb5c-3313d4844038', 'First conditional in future tense', false, 'db263ecd-457e-4f9e-b1c2-309625bcec61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28ead606-6b5c-452d-81cc-ab0fe3063eaa', 'Simple compound sentence', false, 'db263ecd-457e-4f9e-b1c2-309625bcec61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('691cc84d-3ae0-402d-a030-cd958fb74427', 'Relative coordinate clause', false, 'db263ecd-457e-4f9e-b1c2-309625bcec61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0b80e5e-c755-4c77-b458-dd56da5d9ce6', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'Why did the Martian leadership choose NOT to communicate with or broadcast radio signals to the Viking spacecraft?', 'The Dark Forest / precautionary principle: avoiding unilateral contact with potentially dangerous unknown cosmic civilizations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('686d07ca-7738-4d7e-b9d4-6fb6d9e9cda0', 'They did not know the technological level or intentions of the alien civilization, fearing that contact might invite colonizing invasions or exploitation of their limited resources', true, 'c0b80e5e-c755-4c77-b458-dd56da5d9ce6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cde1e798-3ccc-461f-9cf1-dbdbda3fcb53', 'Because they did not understand radio waves', false, 'c0b80e5e-c755-4c77-b458-dd56da5d9ce6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2f9a98d-f006-4949-8182-1976da01f12c', 'Because their radios were broken', false, 'c0b80e5e-c755-4c77-b458-dd56da5d9ce6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3e950ac-ce6e-4ec6-b607-52e1bfb5527d', 'Because they thought the craft was a bird', false, 'c0b80e5e-c755-4c77-b458-dd56da5d9ce6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a62bffaa-95cc-4bdd-9cf5-eb63dce2a3a1', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'What makes the ending of ''An Alien Hand'' delightfully humorous yet intellectually stimulating?', 'Exquisite situational irony: human certainty of Mars'' sterility juxtaposed against the living subterranean Martian world.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fd61eab-0cfc-48dd-8c5f-0271a6dd9032', 'The contrast between NASA''s triumphant scientific press conference claiming ''No Life on Mars'' and the reality that a highly intelligent civilization is observing them in secret from underneath the soil', true, 'a62bffaa-95cc-4bdd-9cf5-eb63dce2a3a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62c55a48-61a4-4c5c-96f3-eae226e3ff4a', 'Tilloo eating Martian ice cream', false, 'a62bffaa-95cc-4bdd-9cf5-eb63dce2a3a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11afb52f-39cc-46f1-84b4-4a9be4721c04', 'The rocket exploding into fireworks', false, 'a62bffaa-95cc-4bdd-9cf5-eb63dce2a3a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe6a63eb-406f-428a-aee3-5a75cfa5f939', 'The scientists crying on television', false, 'a62bffaa-95cc-4bdd-9cf5-eb63dce2a3a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4cbb03f-b754-4e2b-968f-72e0bd6519f9', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'What is the grammatical function of the underlined gerund phrase in: ''**Living underground** required sophisticated technological coordination and perpetual vigilance.''?', '''Living underground'' is a Gerund Phrase functioning as the grammatical subject of the main predicate verb ''required''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d05089cd-498b-486d-ac8c-9d1e82ce546d', 'Subject of the sentence', true, 'c4cbb03f-b754-4e2b-968f-72e0bd6519f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1c7c120-5a4a-427b-b980-bf863996cd52', 'Direct object of the verb', false, 'c4cbb03f-b754-4e2b-968f-72e0bd6519f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50cc000f-7295-4376-b8d8-370f57962026', 'Subject complement', false, 'c4cbb03f-b754-4e2b-968f-72e0bd6519f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77b36e8b-4860-4cb6-96e7-209f7b47cfec', 'Adverbial adjunct', false, 'c4cbb03f-b754-4e2b-968f-72e0bd6519f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99e60a03-d2d4-42bd-94dd-a0a536e7d2ee', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'Which literary trope is subverted when the story reveals that the ''Alien'' is actually a robotic probe from Planet Earth?', 'Subversion of xenophobic pulp sci-fi: redefining the ''alien'' through the eyes of indigenous non-human protagonists.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcd7e2a1-e2da-442f-b1ca-f323b64b3518', 'The ''Alien Invasion / Space Monster'' trope (human beings are revealed to be the enigmatic extraterrestrial visitors)', true, '99e60a03-d2d4-42bd-94dd-a0a536e7d2ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77d93bc5-5f18-49a6-93a8-4eb1d5953c0e', 'The Fairy Tale princess trope', false, '99e60a03-d2d4-42bd-94dd-a0a536e7d2ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6afb4ffb-6b2c-4d41-8bf3-9599b55cbec2', 'The Detective murder mystery trope', false, '99e60a03-d2d4-42bd-94dd-a0a536e7d2ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42ba9da0-f5ef-4045-bd64-ab9d17f022f4', 'The Ghost story haunting trope', false, '99e60a03-d2d4-42bd-94dd-a0a536e7d2ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2214fd1d-c3c9-4506-a34d-5b553424a948', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'How does Dr. Jayant Narlikar balance scientific realism with accessible youth storytelling in ''An Alien Hand''?', 'Narlikar seamlessly weaves hard astrophysical principles with universal domestic family dynamics and youth adventure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3696286b-f39a-4707-9a7d-26452e55b660', 'By integrating authentic astrophysical telemetry, bio-suits, and NASA robotic missions into a warm, relatable coming-of-age story of parental care and childhood curiosity', true, '2214fd1d-c3c9-4506-a34d-5b553424a948');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cf97876-d4ee-44a7-b0ec-56813ff643bb', 'By using magic wands and wizards', false, '2214fd1d-c3c9-4506-a34d-5b553424a948');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e852a1d7-ce9a-4cdc-8f3b-e20a95756d9a', 'By using complex mathematical equations on every page', false, '2214fd1d-c3c9-4506-a34d-5b553424a948');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf87e01e-1c20-4538-a205-bd99402359ef', 'By eliminating all dialogue', false, '2214fd1d-c3c9-4506-a34d-5b553424a948');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07d4f991-a943-4a92-9acf-a31b381b8440', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Hard', 'What master theme does ''An Alien Hand'' impart to young learners?', 'Chapter 11 champions cosmic humility, scientific imagination, perspective-taking, and planetary environmental consciousness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6d76dc7-026b-40fd-bf20-cae15cee9c5d', 'The universe is vast and full of wonder; true scientific inquiry requires humility, empathy for other perspectives, respect for fragile planetary ecologies, and the courage to explore beyond our immediate horizons', true, '07d4f991-a943-4a92-9acf-a31b381b8440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('babb03ec-dc4b-4c9d-ba43-545d17a32231', 'That space exploration should be banned', false, '07d4f991-a943-4a92-9acf-a31b381b8440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20da3072-95be-4e0e-878b-0c656f40ee9d', 'That children should never ask questions', false, '07d4f991-a943-4a92-9acf-a31b381b8440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01572db5-3fcf-4922-b9d3-aa0959dacb23', 'That technology is evil', false, '07d4f991-a943-4a92-9acf-a31b381b8440');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a7fdbac-90e0-400d-b0a2-429f45b6c7e1', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'What does the fundamental macroeconomic term ''GDP'' stand for?', 'Gross Domestic Product (GDP) is the total monetary or market value of all finished goods and services produced within a country in a specific time period.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fdbcee0-8c66-4573-98f2-8bed6b4eed0c', 'Gross Domestic Product', true, '8a7fdbac-90e0-400d-b0a2-429f45b6c7e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01f2da6a-d8f4-4c00-9e79-c9b226158817', 'Global Development Plan', false, '8a7fdbac-90e0-400d-b0a2-429f45b6c7e1');
