INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7853f770-d73b-4398-8961-9a4c083ba9b7', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'Which international financial institution headquartered in Washington, D.C., works to foster global monetary cooperation, secure financial stability, and provide balance-of-payments loans to member nations?', 'The IMF (190 member countries) promotes international financial stability, exchange rate cooperation, and emergency balance-of-payments assistance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc9f68f0-bb37-43be-a13e-44effd98ece9', 'The International Monetary Fund (IMF)', true, '7853f770-d73b-4398-8961-9a4c083ba9b7');
