INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cc723ea-47b0-41d3-b86c-5a8bae6fb2e6', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'Which global development institution headquartered in Washington, D.C., provides low-interest loans, zero-interest credits, and grants to developing nations for infrastructure, education, and health?', 'The World Bank focuses on long-term poverty alleviation, financing roads, power grids, schools, and sustainable development across developing countries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39ec2342-fb46-4347-b72d-f9bf0c475d36', 'The World Bank (IBRD & IDA)', true, '6cc723ea-47b0-41d3-b86c-5a8bae6fb2e6');
