INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92ec0f1e-7c29-4ac7-8b9f-a8a302ca1d9b', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'Which international organization headquartered in Geneva, Switzerland, oversees and regulates the rules of international trade and resolves trade disputes between nations?', 'The WTO (established in 1995, succeeding GATT) administers global trade agreements and adjudicates international trade disputes.', NOW()) ON CONFLICT DO NOTHING;
