INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8de217c-b540-42fc-9aa3-548b167aaa1e', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'What is the CENTRAL BANK of India that regulates the nation''s banking system, issues currency notes, and controls monetary policy?', 'The Reserve Bank of India (RBI, established in 1935 with headquarters in Mumbai) is India''s apex monetary authority and central banking institution.', NOW()) ON CONFLICT DO NOTHING;
