INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e2f32c9-7042-4fa1-894b-f53a97ba537b', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'Which central banking system of the United States wields immense global financial influence over interest rates and dollar liquidity?', 'The Federal Reserve (headed by the Federal Reserve Board of Governors) sets US monetary policy and federal funds interest rates.', NOW()) ON CONFLICT DO NOTHING;
