INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3dc3cb17-59d7-448c-841b-7ae6e871f119', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'What is the oldest stock exchange in ASIA, established in 1875 at Dalal Street, Mumbai?', 'The Bombay Stock Exchange (BSE, founded by Premchand Roychand in 1875) is Asia''s first and oldest stock exchange.', NOW()) ON CONFLICT DO NOTHING;
