INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5586ac2-1fbb-44e8-b2d1-9cca5326088c', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'In financial stock markets, what does a ''BULL MARKET'' represent?', 'A Bull Market (derived from a bull thrusting its horns upward) signifies surging stock indices and robust investor optimism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f10e303b-646e-4042-966c-b62f70aea46c', 'A rising financial market where stock prices are increasing and investor optimism/confidence is high', true, 'e5586ac2-1fbb-44e8-b2d1-9cca5326088c');
