INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71feaa60-ffe4-4735-acf4-bff7f4f281af', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'In financial stock markets, what does a ''BEAR MARKET'' represent?', 'A Bear Market (derived from a bear swiping its paws downward) describes a prolonged downturn with widespread asset declines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d2cdf53-7067-4039-9636-b2e01a1a5816', 'A declining market characterized by falling stock prices (typically 20%+ drop from recent highs) and widespread investor pessimism', true, '71feaa60-ffe4-4735-acf4-bff7f4f281af');
