INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('680a95dd-432c-4871-98aa-9e1c32e3d6a6', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'Which country''s currency is the ''YEN'' (¥)?', 'The Japanese Yen is the official currency of Japan and one of the world''s major foreign exchange reserve currencies.', NOW()) ON CONFLICT DO NOTHING;
