INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6fd5aab-c62b-43fc-bbef-2030e0c0a16e', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is ''Foreign Direct Investment'' (FDI)?', 'FDI entails substantial long-term cross-border capital ownership, technology transfer, and direct operational management in foreign enterprises.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356b6913-32fc-4d51-bc21-f798e234d4eb', 'An investment made by a company or individual in one country into business interests (factories, offices, joint ventures) located in another country', true, 'd6fd5aab-c62b-43fc-bbef-2030e0c0a16e');
