INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('495dfd30-656e-475d-a115-f84d592cddc2', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is the key difference between NOMINAL GDP and GDP measured at PURCHASING POWER PARITY (PPP)?', 'PPP adjustment compares real purchasing power across borders: India is the 5th largest economy by Nominal GDP, but 3rd largest by GDP (PPP).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b82afb0b-409e-435e-8f20-0b0cc13a5726', 'Nominal GDP converts national output into US Dollars using current market exchange rates ; GDP (PPP) adjusts for local price level differences and cost of living in each country', true, '495dfd30-656e-475d-a115-f84d592cddc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16447326-be93-4931-b034-adcad175cfc4', 'Nominal GDP counts only food items', false, '495dfd30-656e-475d-a115-f84d592cddc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a18bb92-4698-43c8-83c4-61c03ccee36d', 'GDP (PPP) includes only paper money', false, '495dfd30-656e-475d-a115-f84d592cddc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('490124b0-eaeb-47c8-bd6d-cc77a66515fa', 'There is no difference between them', false, '495dfd30-656e-475d-a115-f84d592cddc2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb74d0f3-af70-4070-ab5a-d8943b992c9d', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is the ''REPO RATE'' (Repurchase Option Rate) set by the Reserve Bank of India (RBI)?', 'Repo rate is the RBI''s primary policy tool: raising repo rates tightens credit to quell inflation; lowering rates stimulates investment and growth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('350e3853-3014-4438-b486-8ea2f47ab5f1', 'The benchmark interest rate at which the RBI lends short-term money to commercial banks against government securities to manage liquidity and control inflation', true, 'eb74d0f3-af70-4070-ab5a-d8943b992c9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f1d85d0-efe5-445a-9712-7728447964ff', 'The tax charged on income', false, 'eb74d0f3-af70-4070-ab5a-d8943b992c9d');
