INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d4b92c4-b640-4239-9f0a-a1cb469fa4e5', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'Which geopolitical and economic bloc originally comprised Brazil, Russia, India, China, and South Africa (expanded in 2024 to include Egypt, Ethiopia, Iran, UAE)?', 'BRICS represents leading emerging market economies collaborating on multipolar trade, development financing (New Development Bank), and south-south cooperation.', NOW()) ON CONFLICT DO NOTHING;
