INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d7cdb2c-03bb-4475-9fc5-a72885bb5c36', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is the ''G7'' (Group of Seven)?', 'The G7 meets annually to coordinate international economic governance, security policies, and global financial stability.', NOW()) ON CONFLICT DO NOTHING;
