INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db095023-eef7-4a45-a2c4-d94bb09447f2', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What does ''Fiscal Deficit'' mean in government budgetary economics?', 'Fiscal deficit indicates the net amount of money the government must borrow to meet its spending requirements.', NOW()) ON CONFLICT DO NOTHING;
