INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f2196ad-f59f-42ca-9ce4-2412cb98e010', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is an ''Initial Public Offering'' (IPO) in corporate finance?', 'An IPO transitions a private unlisted company into a publicly traded corporation on stock exchanges (like BSE/NSE or NYSE).', NOW()) ON CONFLICT DO NOTHING;
