INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('907f0f19-f30e-4906-a023-6a2a21619d61', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is a ''Free Trade Agreement'' (FTA) between countries?', 'FTAs dismantle tariff and non-tariff barriers, boosting mutual trade volumes and economic integration between partner nations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d05eac9b-b39f-41a0-a6a0-e6aba868d765', 'A treaty between two or more nations to substantially eliminate tariffs, import duties, and trade quotas, fostering seamless cross-border commerce', true, '907f0f19-f30e-4906-a023-6a2a21619d61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b6cc4e0-9aa1-471d-83b7-49b0b25780ae', 'An agreement to give goods away for free', false, '907f0f19-f30e-4906-a023-6a2a21619d61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d11f51e6-f748-4a77-b090-c758008e80c2', 'A ban on all imports', false, '907f0f19-f30e-4906-a023-6a2a21619d61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf21742-7721-4798-8b93-f047266f8e5a', 'A plan to use a single language in business', false, '907f0f19-f30e-4906-a023-6a2a21619d61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a84f4395-66bc-479a-b06e-5409d020dc9f', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is ''Sovereign Wealth Fund'' (SWF)?', 'SWFs invest national surplus revenues internationally to generate intergenerational wealth, fiscal stability, and strategic asset diversification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56cfdd84-5f34-4a90-bc6a-6e36211119cb', 'A state-owned state investment fund comprising financial assets (stocks, bonds, real estate) financed by foreign exchange reserves or commodity revenues (like Norway''s Oil Fund or Abu Dhabi ADIA)', true, 'a84f4395-66bc-479a-b06e-5409d020dc9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5583abc-553b-484c-a377-48e5d823647b', 'A royal family''s personal bank account', false, 'a84f4395-66bc-479a-b06e-5409d020dc9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36941b5-dfef-4a21-b7c7-80a03fdd8b41', 'A fund for printing stamps', false, 'a84f4395-66bc-479a-b06e-5409d020dc9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f48d8aa-b39e-4401-89b3-d590aac85a26', 'A charity for homeless people', false, 'a84f4395-66bc-479a-b06e-5409d020dc9f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7eb2d3c-ecb5-4b38-8f23-940892d87045', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18b74aad-00fa-4445-b4cd-a6389412cf19', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'a7eb2d3c-ecb5-4b38-8f23-940892d87045');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9b4b478-644e-4bb4-be6e-696a05986c47', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'a7eb2d3c-ecb5-4b38-8f23-940892d87045');
