INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4024b844-ccca-4d59-9ab1-4b8814655f4d', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Spot the IMPOSTER in the following major Global Economic Institutions and their respective headquarters:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67435896-9309-479f-a7bc-e6545deae4b4', 'Institution 1', false, '4024b844-ccca-4d59-9ab1-4b8814655f4d');
