INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0090d479-3806-41e1-b736-6b072c1ddaf0', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Analyze the monetary transmission mechanism of ''Quantitative Easing'' (QE) employed by major central banks during severe economic crises:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30ca282a-7c9e-4963-9ca7-b40ba30872f3', 'The central bank purchases large quantities of government bonds and financial assets from commercial markets, expanding the central bank''s balance sheet and injecting massive liquidity to lower long-term interest rates', true, '0090d479-3806-41e1-b736-6b072c1ddaf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c94a8991-2c19-4734-8e5f-e6a1ffc52ffd', 'The government prints paper money and drops it from helicopters on streets', false, '0090d479-3806-41e1-b736-6b072c1ddaf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abc90d04-4815-4f70-9eb1-ee1edf1ab5e1', 'The central bank closes all private banks', false, '0090d479-3806-41e1-b736-6b072c1ddaf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f290097f-43e0-4dbc-8198-9f006da85a7f', 'The government increases taxes by 100%', false, '0090d479-3806-41e1-b736-6b072c1ddaf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca099295-1747-4434-ad47-41bb5144d25c', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Match Column I (Global Economic Indices / Concepts) with Column II (Economic Definitions):
(a) Consumer Price Index (CPI) -> (i) Measures average change in retail prices paid by households for a basket of goods
(b) Gini Coefficient          -> (ii) Statistical measure of income or wealth inequality within a nation (0 to 1)
(c) Purchasing Power Parity    -> (iii) Exchange rate theory equalizing the price of an identical basket of goods across currencies
(d) Special Drawing Rights (SDR) -> (iv) International reserve asset created by the IMF based on a basket of 5 currencies', 'CPI = retail inflation; Gini = inequality index; PPP = price parity; SDR = IMF supplementary reserve currency basket.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed7231cc-92bf-4068-b1f1-6af223630889', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'ca099295-1747-4434-ad47-41bb5144d25c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('116337c5-b3ec-4f10-a3f3-f28c28cb3b18', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'ca099295-1747-4434-ad47-41bb5144d25c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c944d919-fa2f-403f-9189-0d10d1636733', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'ca099295-1747-4434-ad47-41bb5144d25c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2af1472-6a5b-41b8-af70-6e85d846902a', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'ca099295-1747-4434-ad47-41bb5144d25c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1098ff89-9601-43ec-a7e9-b59213a1c32c', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Read the statements regarding India''s Foreign Trade and Forex Reserves:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa1c2ad3-fed0-439c-9cb0-26c5b33433a2', 'Statements 1 and 2 only', true, '1098ff89-9601-43ec-a7e9-b59213a1c32c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef2ef12c-28ce-42ac-8380-689283eb2f33', 'Statements 2 and 3 only', false, '1098ff89-9601-43ec-a7e9-b59213a1c32c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('788720a1-8a18-4be6-bc11-36829413081d', 'Statements 1 and 3 only', false, '1098ff89-9601-43ec-a7e9-b59213a1c32c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaa09b7c-0edc-4b22-a814-11f1a967edb0', 'All Statements 1, 2, and 3', false, '1098ff89-9601-43ec-a7e9-b59213a1c32c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('531ff080-0d72-4c55-8b06-c44097a70976', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What was the ''Bretton Woods Conference'' of July 1944 in New Hampshire, USA?', 'Bretton Woods established the post-war multilateral architecture: institutionalizing the IMF, IBRD, and fixed-rate convertible dollar-gold standards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97a9c38f-5365-4fe7-9167-1c960fc02aa9', 'A landmark gathering of 44 Allied nations that designed the post-WWII international monetary order, creating the IMF, the World Bank, and fixing gold-pegged exchange rates', true, '531ff080-0d72-4c55-8b06-c44097a70976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee2b369e-5c88-4841-9545-f40b5cc331ed', 'A meeting to end World War I', false, '531ff080-0d72-4c55-8b06-c44097a70976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('533307f2-19f2-4df8-974d-831fc89cf6b0', 'A conference that founded the European Union', false, '531ff080-0d72-4c55-8b06-c44097a70976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdb1466b-eb7a-4d48-8be0-7cb0df80e959', 'A summit to establish oil pipelines', false, '531ff080-0d72-4c55-8b06-c44097a70976');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ca016f3-e58d-4ada-98a9-c0030ee401a9', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What is ''De-Dollarization'' in contemporary global geopolitics?', 'De-dollarization seeks to mitigate sanctions risks, currency volatility, and extraterritorial jurisdiction by promoting alternative bilateral currency settlement mechanisms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c21e7df1-a7d3-482f-839d-c8f973773c3e', 'The strategic initiative by emerging economies (like BRICS) to reduce reliance on the US Dollar in bilateral trade settlement, using local national currencies (Rupee, Ruble, Yuan) and central bank digital currencies', true, '8ca016f3-e58d-4ada-98a9-c0030ee401a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('891ba2b4-fd1b-449a-9bcd-59f16928a8bb', 'Banning all paper money completely', false, '8ca016f3-e58d-4ada-98a9-c0030ee401a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15293180-1121-494d-bf12-59f925d308bb', 'A law forcing everyone to use gold coins only', false, '8ca016f3-e58d-4ada-98a9-c0030ee401a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b7dbb6-d20e-45c3-81b7-de2ba9ade13d', 'The closure of all American banks', false, '8ca016f3-e58d-4ada-98a9-c0030ee401a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b315420f-174b-4ca9-9018-d943ce14c6eb', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Consider four financial instruments:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90b3545c-278f-4fb4-9ed8-47b488eff007', 'Instrument 3 only (Treasury Bills)', true, 'b315420f-174b-4ca9-9018-d943ce14c6eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3ee3e0a-30f8-4c1a-a194-0ba55efffb61', 'Instruments 1 and 2 only', false, 'b315420f-174b-4ca9-9018-d943ce14c6eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aae7ce42-54fc-460a-b61d-3164177027b0', 'Instruments 2 and 4 only', false, 'b315420f-174b-4ca9-9018-d943ce14c6eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8943ad9-46fe-4a0c-aa1d-3a1e16250afa', 'All 1, 2, 3, and 4', false, 'b315420f-174b-4ca9-9018-d943ce14c6eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('124ac79f-8132-48c7-917f-e334ea2600f0', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What is the ''Triffin Dilemma'' in international economics?', 'Robert Triffin noted that the reserve currency issuer must run continuous balance of payments deficits to supply global liquidity, eventually undermining trust in its currency.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eb127fc-d814-4287-9ded-f44ba1e08469', 'The fundamental conflict of interest between domestic monetary objectives and international obligations for a country whose national currency serves as the world''s global reserve currency', true, '124ac79f-8132-48c7-917f-e334ea2600f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b55437a3-93ca-4efb-b7b5-0fb790b54751', 'The problem of counting paper money in banks', false, '124ac79f-8132-48c7-917f-e334ea2600f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31f1198a-10e6-4164-ac8a-20191e784a8e', 'The conflict between farmers and factory owners', false, '124ac79f-8132-48c7-917f-e334ea2600f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ea9c0b1-ba7d-4bc4-8757-1245a06e9f69', 'The difficulty of setting shipping container prices', false, '124ac79f-8132-48c7-917f-e334ea2600f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de553c72-6af6-429a-8187-44977d0a9fa0', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Why is ''Venture Capital'' (VC) critical to the modern startup and innovation ecosystem?', 'Venture capital finances disruptive, high-risk innovation, creating global tech unicorns (fintech, AI, clean tech, biotech) that transform markets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93d561be-448b-4541-821d-c1e5df2f4bf1', 'It provides high-risk equity funding, mentorship, and strategic growth capital to early-stage technology startups with high growth potential before they achieve profitability', true, 'de553c72-6af6-429a-8187-44977d0a9fa0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('672d1b13-0001-4e87-9f68-0071903d3bb9', 'It lends money only to government departments', false, 'de553c72-6af6-429a-8187-44977d0a9fa0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfde39e2-8271-446c-87d5-b214be427c62', 'It insures houses against floods', false, 'de553c72-6af6-429a-8187-44977d0a9fa0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45ee668e-a679-4293-92c5-28359e0307da', 'It manages pension funds for retired persons only', false, 'de553c72-6af6-429a-8187-44977d0a9fa0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8da17e3d-f42a-4ca7-9a02-13bf545ea981', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What is ''Financial Inclusion'' and why is it a cornerstone of modern national development strategy?', 'Financial inclusion (driven by Pradhan Mantri Jan Dhan Yojana and UPI) empowers vulnerable populations, reduces poverty, and formalizes the economy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32b575ab-46ed-436b-9281-82456a35f44e', 'Ensuring that all individuals and businesses—especially marginalized, rural, and low-income populations—have universal access to useful, affordable formal financial products (banking accounts, savings, credit, insurance, digital payments)', true, '8da17e3d-f42a-4ca7-9a02-13bf545ea981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82e4ab07-ff46-440c-a030-14b55f1f3181', 'Making everyone pay the same income tax', false, '8da17e3d-f42a-4ca7-9a02-13bf545ea981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1edbc733-9c5d-4200-a5a4-d20743309bb5', 'Giving free stock shares to all citizens', false, '8da17e3d-f42a-4ca7-9a02-13bf545ea981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baa7d62d-d2f5-41e0-9e6e-6b9cbd766d9d', 'Banning all private banks', false, '8da17e3d-f42a-4ca7-9a02-13bf545ea981');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c1dbaab-c02a-4bcd-b233-e8cec8a32f03', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What overarching economic wisdom is synthesized in Chapter 11 of General Knowledge?', 'Chapter 11 synthesizes the dynamics of global finance: central banking, international development, multilateral trade, market mechanisms, and socio-economic equity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c369aa2-40e0-4e0c-93fb-19d44ecc4567', 'A healthy, equitable global economy requires prudent monetary policy, open rules-based international trade, ethical financial regulation, and inclusive financial systems that convert capital into sustainable human development, scientific innovation, and shared prosperity', true, '0c1dbaab-c02a-4bcd-b233-e8cec8a32f03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49184a23-71e3-4370-ab5e-2450c8275f68', 'That only stock brokers understand economics', false, '0c1dbaab-c02a-4bcd-b233-e8cec8a32f03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22f1e63f-0138-4308-967a-f6666095d57c', 'That trade between nations always causes conflict', false, '0c1dbaab-c02a-4bcd-b233-e8cec8a32f03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4826d201-c205-4ca3-af7b-78133f6edc02', 'That economic growth has no relation to human well-being', false, '0c1dbaab-c02a-4bcd-b233-e8cec8a32f03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad2a6802-e20c-4476-8b09-802a7fcb031a', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'What is the outermost, thinnest solid layer of the Earth called?', 'The crust is the outermost solid lithospheric layer of the Earth, averaging 35 km on continental masses and only 5 km on ocean floors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('807a17f3-cd9c-4424-be8b-70f12e61c7d1', 'The Crust', true, 'ad2a6802-e20c-4476-8b09-802a7fcb031a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89f0003d-f8fd-4a1e-87cf-1bb9cf606abd', 'The Mantle', false, 'ad2a6802-e20c-4476-8b09-802a7fcb031a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c5ffd52-7582-4c98-a3ba-42c7924cc673', 'The Outer Core', false, 'ad2a6802-e20c-4476-8b09-802a7fcb031a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('617cddf5-a81e-4fd8-a863-cdcf96c0f301', 'The Inner Core', false, 'ad2a6802-e20c-4476-8b09-802a7fcb031a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fd0435e-914b-4a0f-834a-3732bff05cd5', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'What are the two main mineral constituents of the CONTINENTAL CRUST (often called ''SIAL'')?', 'The continental crust is composed predominantly of Silica and Alumina, hence abbreviated as SIAL.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dc4f94b-7482-4bb3-a1e7-ca46210434e6', 'Silica and Alumina (SIAL)', true, '7fd0435e-914b-4a0f-834a-3732bff05cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1dd9cf0-8bcb-4158-96e4-1118641bfe20', 'Silica and Magnesium (SIMA)', false, '7fd0435e-914b-4a0f-834a-3732bff05cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e6e0a3e-01de-45cc-9bbf-a884f8cba6b8', 'Nickel and Iron (NIFE)', false, '7fd0435e-914b-4a0f-834a-3732bff05cd5');
