INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38227dad-bf2a-4027-ae10-014837fe82d1', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'What are the main mineral constituents of the OCEANIC CRUST (called ''SIMA'')?', 'The basaltic oceanic crust mainly comprises Silica and Magnesium, hence named SIMA.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('812b626d-67bd-4390-a9c3-8f92605db15d', 'Silica and Magnesium (SIMA)', true, '38227dad-bf2a-4027-ae10-014837fe82d1');
