INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cfd90a1-be10-4d55-a2ca-aa7e74f6ce3a', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'What are the main mineral constituents of the innermost central layer of the Earth—the CORE (called ''NIFE'')?', 'The Earth''s core (radius ~3,500 km) is composed of heavy dense metals: Nickel (Ni) and Ferrous/Iron (Fe), termed NIFE.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a8ed37-e658-4bb4-923b-efeb5341b177', 'Nickel and Ferrous / Iron (NIFE)', true, '6cfd90a1-be10-4d55-a2ca-aa7e74f6ce3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('549cd823-75b4-4e77-96c8-0c8502e0c4f3', 'Silica and Magnesium', false, '6cfd90a1-be10-4d55-a2ca-aa7e74f6ce3a');
