INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('195548e7-785a-4074-b7ba-e03ca60cf649', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Which layer of the Earth lies directly beneath the crust and extends to a depth of 2,900 km?', 'The mantle forms the intermediate layer of the Earth, extending to a depth of 2,900 km below the crust.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b3a19b2-a620-4b0f-b907-b1a0466c2434', 'The Mantle (Asthenosphere)', true, '195548e7-785a-4074-b7ba-e03ca60cf649');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9664a92-ff7e-412a-8f92-0ba2b48a173b', 'The Crust', false, '195548e7-785a-4074-b7ba-e03ca60cf649');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16287cdb-4a1c-4f19-a59b-90e3ddd41390', 'The Inner Core', false, '195548e7-785a-4074-b7ba-e03ca60cf649');
