INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77728cc3-1c58-4430-ba36-c20c60185087', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Rocks that are formed directly by the cooling and solidification of molten magma or lava are called:', 'Igneous rocks (Latin ''Ignis'' = fire) are the primary parent rocks formed directly from cooling magma or lava.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25bf0cc0-0d6c-4efd-8d8d-1489217b704d', 'Igneous Rocks (Primary Rocks)', true, '77728cc3-1c58-4430-ba36-c20c60185087');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e561e77-4516-4173-a190-7ca69a985397', 'Sedimentary Rocks', false, '77728cc3-1c58-4430-ba36-c20c60185087');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e9a29c5-4ff3-4db2-97f5-2c25c0ff0ee1', 'Metamorphic Rocks', false, '77728cc3-1c58-4430-ba36-c20c60185087');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3bb2f56-a92c-4938-8f67-3ccaf0b586b4', 'Fossil Rocks', false, '77728cc3-1c58-4430-ba36-c20c60185087');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be396966-8e68-46d8-94c1-8e02f29dfc34', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Which type of igneous rock is formed when molten lava comes out onto the Earth''s surface and cools down RAPIDLY, forming fine-grained rocks like the Basalt of the Deccan Plateau?', 'Extrusive (volcanic) rocks cool rapidly on the surface, producing fine-grained crystalline structures like Basalt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b45ca9c2-3943-4a2f-80a2-c16f9d0ad0ef', 'Extrusive Igneous Rocks (e.g. Basalt)', true, 'be396966-8e68-46d8-94c1-8e02f29dfc34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59a76b5b-1716-4889-824d-ae6bf4647a87', 'Intrusive Igneous Rocks', false, 'be396966-8e68-46d8-94c1-8e02f29dfc34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('924319bb-5b01-4c18-878a-b611c37fd792', 'Sedimentary Rocks', false, 'be396966-8e68-46d8-94c1-8e02f29dfc34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0203b8c2-9358-4996-b1d8-3c215f2caf8c', 'Metamorphic Rocks', false, 'be396966-8e68-46d8-94c1-8e02f29dfc34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b7ca3fe-dc02-4ab3-83ec-0e4e76917fe9', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Which type of igneous rock is formed when molten magma cools SLOWLY deep inside the Earth''s crust, forming large crystals like Granite?', 'Intrusive (plutonic) rocks cool slowly within the crust, forming coarse-grained crystalline textures like Granite.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00344dc2-d96d-4ca8-9ef9-46ae846c77dd', 'Intrusive Igneous Rocks (e.g. Granite)', true, '0b7ca3fe-dc02-4ab3-83ec-0e4e76917fe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('254efc11-c6f7-46ea-846e-3d74541b7d0d', 'Extrusive Igneous Rocks', false, '0b7ca3fe-dc02-4ab3-83ec-0e4e76917fe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d3fd89a-bc07-4982-afcd-c2f0fc36f8b4', 'Sedimentary Rocks', false, '0b7ca3fe-dc02-4ab3-83ec-0e4e76917fe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cef483b4-7b96-4d77-9bc9-f8e8d6fbd2a8', 'Sandstone', false, '0b7ca3fe-dc02-4ab3-83ec-0e4e76917fe9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66b9147c-c3fa-442d-82a7-a3de110b951d', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Rocks formed by the deposition, accumulation, and compression of mineral sediments and organic remains in layers (containing FOSSILS) are called:', 'Sedimentary rocks (Latin ''sedimentum'' = settle down) are layered strata formed by compacted sediments and frequently contain fossils.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c48ffe5-ec22-4ae2-abd6-97ae757bab89', 'Sedimentary Rocks (e.g. Sandstone, Limestone, Shale)', true, '66b9147c-c3fa-442d-82a7-a3de110b951d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27552ad2-f623-4fa2-be5a-1b50c66ffd32', 'Igneous Rocks', false, '66b9147c-c3fa-442d-82a7-a3de110b951d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4b570e3-9ebb-4101-8f5e-3d3682172da6', 'Metamorphic Rocks', false, '66b9147c-c3fa-442d-82a7-a3de110b951d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6787a1d-4037-4f01-8b11-3a8bc01b548d', 'Basalt', false, '66b9147c-c3fa-442d-82a7-a3de110b951d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25069211-daa4-4df4-8271-6094a071cc35', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'When igneous and sedimentary rocks undergo dramatic transformations under intense HEAT and extreme PRESSURE, what new class of rocks is formed?', 'Metamorphic rocks (Greek ''metamorphose'' = change of form) result from recrystallization under extreme heat and pressure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e3d51fe-f2a9-43e0-8a89-924499254b48', 'Metamorphic Rocks (e.g. Clay into Slate, Limestone into Marble)', true, '25069211-daa4-4df4-8271-6094a071cc35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d51b376a-9cda-45f5-85f5-7d37e2711943', 'Primary Rocks', false, '25069211-daa4-4df4-8271-6094a071cc35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb3f98c7-3cd2-4839-8205-4bc257055569', 'Extrusive Rocks', false, '25069211-daa4-4df4-8271-6094a071cc35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cb0d7eb-0a61-4c60-bfbd-bb5ad887982b', 'Magma', false, '25069211-daa4-4df4-8271-6094a071cc35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a20d77d7-316b-499a-aa99-0e8fe48ae58e', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'The continuous geological transformation of one rock type into another under cyclical physical processes is known as the:', 'The rock cycle describes the cyclic transitions among igneous, sedimentary, and metamorphic rocks driven by geological forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('145df16a-98a9-4280-8cf2-6e1c126c610a', 'The Rock Cycle', true, 'a20d77d7-316b-499a-aa99-0e8fe48ae58e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8693ba2d-52a2-43a1-8cfe-3677ae18e763', 'The Water Cycle', false, 'a20d77d7-316b-499a-aa99-0e8fe48ae58e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b32a86c1-e75b-4cd0-861d-785da2e9e951', 'The Nitrogen Cycle', false, 'a20d77d7-316b-499a-aa99-0e8fe48ae58e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14f1a970-7184-47c2-8818-d1d14d99cf0a', 'The Carbon Cycle', false, 'a20d77d7-316b-499a-aa99-0e8fe48ae58e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8f22409-6bf0-416c-b7b8-b411e47e3a0b', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Which white metamorphic rock, transformed from sedimentary limestone under high temperature, was used to construct the world-famous TAJ MAHAL at Agra?', 'Makrana white marble (metamorphosed limestone from Rajasthan) was used to construct the iconic Taj Mahal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1868d9f0-fde2-4f16-a099-cc76e3f49fdf', 'White Marble (Makrana Marble)', true, 'a8f22409-6bf0-416c-b7b8-b411e47e3a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e774fe5c-0ea4-4cc8-bbb4-b79d39667a07', 'Red Sandstone', false, 'a8f22409-6bf0-416c-b7b8-b411e47e3a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6933f04e-db7b-4544-8f6f-9c66c4d5e5be', 'Granite', false, 'a8f22409-6bf0-416c-b7b8-b411e47e3a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8eba725-c5cf-4632-9fb3-bff1ec24a5bf', 'Basalt', false, 'a8f22409-6bf0-416c-b7b8-b411e47e3a0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3421cda4-651d-4e31-ac45-639d853ba61f', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the fundamental difference between ENDOGENIC forces and EXOGENIC forces shaping the Earth''s surface?', 'Endogenic = internal tectonic/magmatic forces; Exogenic = external geomorphic weathering and erosional agents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c116367-810f-43f9-824b-2c2848044e35', 'Endogenic forces originate deep within the Earth''s interior (causing earthquakes, volcanic eruptions, and mountain building) ; Exogenic forces operate on the Earth''s exterior surface (weathering and erosion by rivers, wind, glaciers, sea waves)', true, '3421cda4-651d-4e31-ac45-639d853ba61f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a25ea37-dda7-40ef-90ae-765dd0105a0f', 'Endogenic forces are in oceans and Exogenic forces are in air', false, '3421cda4-651d-4e31-ac45-639d853ba61f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7f760bb-1533-441c-be60-db1aac308935', 'Endogenic forces cause rain and Exogenic forces cause fire', false, '3421cda4-651d-4e31-ac45-639d853ba61f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5b1bb94-d91f-43ae-809c-36ff0beaa417', 'There is no difference', false, '3421cda4-651d-4e31-ac45-639d853ba61f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed44fb54-aa0e-4cf3-98e9-802f369fb92d', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the place in the Earth''s crust where an earthquake vibration originates called, and what is the point on the surface directly above it called?', 'The focus is the subterranean seismic rupture origin; the epicenter is the surface point directly perpendicular above the focus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('158e7e49-2168-48f2-96f1-ccbca0874427', 'The origin point inside the crust is the FOCUS (Hypocenter) ; The point on the surface directly above the focus is the EPICENTER', true, 'ed44fb54-aa0e-4cf3-98e9-802f369fb92d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('255c7590-86c1-4f23-8dbe-6352f058b625', 'Surface is Focus and interior is Epicenter', false, 'ed44fb54-aa0e-4cf3-98e9-802f369fb92d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd877d03-0465-4368-a1cf-a79195d55382', 'Both are called Crater', false, 'ed44fb54-aa0e-4cf3-98e9-802f369fb92d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daee91dd-eb33-4673-ae94-291183d2e5a2', 'Both are called Magma Chamber', false, 'ed44fb54-aa0e-4cf3-98e9-802f369fb92d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ae35e41-ad9b-40f8-8a24-1a0b1cd9ca2e', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'Which scientific instrument is used to record and measure the vibrations and waves of an Earthquake?', 'Earthquake seismic tremors are recorded by seismographs, with magnitude quantified on the logarithmic Richter scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25aa161b-ff59-4a60-8e74-8bf44149de05', 'A Seismograph (and measured on the Richter Scale)', true, '3ae35e41-ad9b-40f8-8a24-1a0b1cd9ca2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19c2bfcc-fd46-43b1-85bc-474c017a5ad8', 'A Barometer', false, '3ae35e41-ad9b-40f8-8a24-1a0b1cd9ca2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c124c8bc-a22f-4137-9a1c-35c88ec5a8ea', 'An Anemometer', false, '3ae35e41-ad9b-40f8-8a24-1a0b1cd9ca2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adeb0392-addc-483e-93fb-ef65a8b51d06', 'A Hygrometer', false, '3ae35e41-ad9b-40f8-8a24-1a0b1cd9ca2e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ab0aec5-d1a2-4b4e-b57b-7583dcdd3f2c', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the large S-shaped curves and loops formed by a meandering river across a flat valley plain called?', 'Meanders are sinuous serpentine curves formed along a mature river''s course by continuous lateral erosion and deposition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c34d3539-b531-4fa2-85fa-26952c36ca65', 'Meanders', true, '0ab0aec5-d1a2-4b4e-b57b-7583dcdd3f2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdb3710e-5ae2-4e77-a4cc-2469dcbcc446', 'Waterfalls', false, '0ab0aec5-d1a2-4b4e-b57b-7583dcdd3f2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bfbab87-def8-4a45-be9d-267d0349ec8a', 'Glacial moraines', false, '0ab0aec5-d1a2-4b4e-b57b-7583dcdd3f2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c09321d-f4dc-4fb4-936e-5e94d2dd18d9', 'Sand dunes', false, '0ab0aec5-d1a2-4b4e-b57b-7583dcdd3f2c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('edcf3c88-cfc9-4792-b63a-550612b233a5', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What happens when a river meander loop becomes so acute that the river cuts through the narrow neck, leaving behind a crescent-shaped cutoff water body?', 'An oxbow lake is a crescent-shaped cutoff lake formed when a river cuts straight through a meandering loop neck during floods.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f58d7c8-08b8-4cc3-89ff-bf94d4f727d9', 'An Oxbow Lake', true, 'edcf3c88-cfc9-4792-b63a-550612b233a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50119533-1d0a-421b-b1cb-bc2740fc2279', 'A Waterfall', false, 'edcf3c88-cfc9-4792-b63a-550612b233a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32bcf2f0-e93b-4d5e-b497-7c0168658e33', 'A Delta', false, 'edcf3c88-cfc9-4792-b63a-550612b233a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('854f3a16-1989-4d06-8d1a-80cd8bd3bee0', 'A Canyon', false, 'edcf3c88-cfc9-4792-b63a-550612b233a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c95d122a-dc70-46aa-b235-1e106186d168', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the triangular landform formed at the mouth of a river where it enters the sea and deposits its entire sediment load called?', 'A delta is a triangular depositional landform formed at a river mouth by distributaries depositing silt into a standing sea/lake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69b715c7-6cbf-4327-b3e3-5849cf748849', 'A River Delta (like the Sundarbans Delta)', true, 'c95d122a-dc70-46aa-b235-1e106186d168');
