INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5752196-fd12-41f3-98ea-7170e221534a', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the vast deposits of fine, yellowish, wind-blown silt found extensively in northern China called?', 'Loess is fine, mineral-rich, windblown silt deposited over extensive regional plains (notably in China''s Loess Plateau).', NOW()) ON CONFLICT DO NOTHING;
