INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef031401-5801-4723-9f17-31cf35c4e0bd', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the ridges of rocks, gravel, sand, and clay deposited by melting glaciers along their valley margins called?', 'Glacial moraines are linear ridges of unsorted glacial till (boulders, gravel, sand, clay) dumped by retreating valley glaciers.', NOW()) ON CONFLICT DO NOTHING;
