INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('195e5ae3-cbaa-4b1d-a2d6-bf3aec5598b6', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'Which of the following sedimentary rocks was extensively used to construct the historic RED FORT in Delhi?', 'The Mughal Red Fort in Delhi and Agra Fort were constructed using red quartzitic sandstone quarried in Rajasthan.', NOW()) ON CONFLICT DO NOTHING;
