INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02895f2e-1a3a-44be-b39c-45e034203dd8', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are ''Fossils'' found embedded within sedimentary rock strata?', 'Fossils are organic paleontological relics entombed within sedimentary depositional beds over geological epochs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3bdd8e5-4f81-4ed8-894d-96623de2ce8d', 'The preserved mineralized remains, impressions, or traces of ancient dead plants, animals, and microorganisms trapped in layered rocks millions of years ago', true, '02895f2e-1a3a-44be-b39c-45e034203dd8');
