INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('222c9ec5-3444-4a47-b0ed-718c86e2dd43', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the ''Asthenosphere'' in geology?', 'The ductile asthenosphere undergoes slow convection currents, transporting the rigid lithospheric tectonic plates floating above it.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b047f04-6bdf-464c-8e01-3adb08104f93', 'The semi-fluid, ductile upper region of the Earth''s mantle directly below the lithosphere where extreme heat permits solid rock to flow slowly, driving plate tectonics', true, '222c9ec5-3444-4a47-b0ed-718c86e2dd43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a058426-d33b-4598-bc5c-df8d39ce071c', 'The layer of air around the Earth', false, '222c9ec5-3444-4a47-b0ed-718c86e2dd43');
