INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57cc7db3-268d-40c7-846a-ac273323c468', 'The solid center of the core', false, '222c9ec5-3444-4a47-b0ed-718c86e2dd43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97977740-3a3b-44b1-8e3f-1249f3c2e9e6', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'Why is the inner core of the Earth solid despite scorching temperatures exceeding 5,000°C?', 'Extreme lithostatic pressure (~3.6 million atmospheres) raises the melting point of iron-nickel, keeping the inner core solid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a42d8fc2-0056-4b43-ad2d-b11dcbb319a8', 'The colossal, overwhelming overlying gravitational Pressure at the Earth''s center compresses the iron-nickel atoms into a solid crystalline state', true, '97977740-3a3b-44b1-8e3f-1249f3c2e9e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b9bc911-dcdd-4c35-81df-4ffffa3b3dba', 'Because the core is made of ice', false, '97977740-3a3b-44b1-8e3f-1249f3c2e9e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df92c4eb-0b54-44d2-a653-9ca5f8536d9d', 'Because no heat reaches the center', false, '97977740-3a3b-44b1-8e3f-1249f3c2e9e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('107283c9-99da-4bcc-8378-35606a4e4e1c', 'Because the core rotates too fast', false, '97977740-3a3b-44b1-8e3f-1249f3c2e9e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e14ce02-4a55-482f-a67d-a8729171a278', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the steep, nearly vertical rock face rising directly above sea water formed by continuous wave erosion called?', 'A sea cliff is a dramatic vertical coastal rock precipice produced by hydraulic wave action undercutting the shoreface.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ecbc644-eff2-4c8a-ae38-ccf08abf99f6', 'A Sea Cliff', true, '2e14ce02-4a55-482f-a67d-a8729171a278');
