INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77152ae7-5d7e-4727-80e6-9e0267db4acc', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Analyze the three types of seismic earthquake waves generated during a tectonic fault slip:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73b654f8-70b6-4730-bd20-6f1872cd6d26', 'S-Waves completely disappear at the core-mantle boundary (2,900 km depth), proving conclusively that the Earth''s OUTER CORE is in a MOLTEN LIQUID state', true, '77152ae7-5d7e-4727-80e6-9e0267db4acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda3714f-eb11-4756-a5fd-e7ec5dec4b5d', 'S-Waves prove that the whole Earth is hollow', false, '77152ae7-5d7e-4727-80e6-9e0267db4acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea84ed30-5711-4a20-9fca-598698669d6d', 'S-Waves show that the core is made of diamond', false, '77152ae7-5d7e-4727-80e6-9e0267db4acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98e07bc4-8bf5-4d80-9c02-7a307a5a239b', 'S-Waves reflect back into space', false, '77152ae7-5d7e-4727-80e6-9e0267db4acc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10f78332-6d00-4eff-b577-28b5fbe7de16', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Match Column I (Geomorphic Landforms) with Column II (Primary Natural Agents of Erosion / Deposition):
(a) Meanders and Oxbow Lakes -> (i) Running River Water (Fluvial agent)
(b) Mushroom Rocks and Dunes   -> (ii) Desert Wind Action (Aeolian agent)
(c) Moraines and U-Valleys    -> (iii) Moving Glacial Ice (Glacial agent)
(d) Sea Stacks and Sea Arches -> (iv) Coastal Ocean Waves (Marine agent)', 'Meanders = rivers; Mushroom rocks = wind; Moraines = glaciers; Stacks = sea waves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9ab4d80-6aa1-436a-981d-66ea424041c5', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '10f78332-6d00-4eff-b577-28b5fbe7de16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecdd9b71-4eaa-4833-be70-bcb8b6012a10', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '10f78332-6d00-4eff-b577-28b5fbe7de16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45a5eff6-911e-49f1-b332-f4a64d50ab65', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '10f78332-6d00-4eff-b577-28b5fbe7de16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a472ff3-fc66-4c43-857c-b8bc696182d3', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '10f78332-6d00-4eff-b577-28b5fbe7de16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2696513d-01bf-4719-ace2-be779e8ad264', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Read the statements regarding the Earth''s geological layers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25d670ce-645c-4577-875c-04939cf47aed', 'Statements 1 and 2 only', true, '2696513d-01bf-4719-ace2-be779e8ad264');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7a7b835-4545-40fd-b1e3-354f905182a5', 'Statements 2 and 3 only', false, '2696513d-01bf-4719-ace2-be779e8ad264');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('330f26f5-874c-4f02-a77b-f8016a895004', 'Statements 1 and 3 only', false, '2696513d-01bf-4719-ace2-be779e8ad264');
