INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eaaa4b55-8e87-4300-82e5-ae5394ce88ba', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'How did the massive volcanic lava plateaus (like the DECCAN TRAPS in western and central India) form around 66 million years ago?', 'The Deccan Traps formed via flood basalt volcanism during India''s passage over the Reunion thermal mantle plume in the Late Cretaceous.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b70048be-6b55-45ff-b07f-528d6e474492', 'Enormous fissure eruptions poured millions of cubic kilometers of fluid basaltic magma over the landscape, creating thick horizontal flood-basalt lava sheets', true, 'eaaa4b55-8e87-4300-82e5-ae5394ce88ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d91cd5c4-cb66-4df9-91a3-eeb8c446ba64', 'A giant meteor made of basalt crashed into India', false, 'eaaa4b55-8e87-4300-82e5-ae5394ce88ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d0d5abb-7515-4e2d-8db9-a4dd700601d0', 'Basalt was washed down from the Himalayas by rivers', false, 'eaaa4b55-8e87-4300-82e5-ae5394ce88ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6954c31c-bf44-4a7f-8633-41a435f75c74', 'Humans mined and piled up the basalt rocks', false, 'eaaa4b55-8e87-4300-82e5-ae5394ce88ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08e4d594-9bf3-41e9-b0f5-a677ecc95d38', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'What is the crucial role of the Earth''s molten metallic liquid OUTER CORE in generating the GEOMAGNETIC FIELD (the Geodynamo)?', 'The convective geodynamo in the liquid iron outer core generates Earth''s magnetosphere, shielding life from lethal solar winds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6de5e6e-25d7-4f3e-b6f8-2b504def5a1d', 'Thermal convection currents of molten iron and nickel, combined with planetary Coriolis rotation, generate powerful electric currents that produce the Earth''s protective magnetic shield against solar radiation', true, '08e4d594-9bf3-41e9-b0f5-a677ecc95d38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78373849-6b1c-46fb-8824-7a95072e206c', 'It acts as a giant refrigerator cooling the crust', false, '08e4d594-9bf3-41e9-b0f5-a677ecc95d38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caac5987-ec05-46c6-afa1-ab840f4ce86d', 'It generates ocean tides', false, '08e4d594-9bf3-41e9-b0f5-a677ecc95d38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23fec69f-bdf4-4b84-9342-46b24700da00', 'It creates oxygen for the atmosphere', false, '08e4d594-9bf3-41e9-b0f5-a677ecc95d38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87a30e70-a77d-4b4f-81e6-4ca388f7799c', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Consider four geographical features:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34aa77ab-fc43-4564-8753-130f8c3564f5', 'Features 1, 2, and 3 only', true, '87a30e70-a77d-4b4f-81e6-4ca388f7799c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a215c763-6cc5-4909-b9c5-e5d55be927f0', 'Feature 4 only', false, '87a30e70-a77d-4b4f-81e6-4ca388f7799c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d3dd07a-8c4c-4c16-93a4-9e2901ed7405', 'Features 2 and 4 only', false, '87a30e70-a77d-4b4f-81e6-4ca388f7799c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4929d0d-51a5-44c8-8e13-e9f7fbc36e21', 'All 1, 2, 3, and 4', false, '87a30e70-a77d-4b4f-81e6-4ca388f7799c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f002361-3d2c-41ed-afc8-8e076770ecd6', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'What is the geological origin of ''Natural Levees'' along the banks of mature lowland rivers?', 'Natural levees are coarse sediment embankments deposited parallel to river channels during flood overflows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5213c76f-0052-4662-b43c-71c5f93bc657', 'During seasonal overbank flooding, coarse sediments are deposited immediately along river margins where water velocity drops first, building elevated natural embankment ridges', true, '7f002361-3d2c-41ed-afc8-8e076770ecd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b176b750-5d2a-4fc1-b1d2-569124979baa', 'Humans constructed them with concrete', false, '7f002361-3d2c-41ed-afc8-8e076770ecd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95fbe303-0b7b-4a3f-9cc6-205da4401e67', 'Wind blew sand onto the river banks', false, '7f002361-3d2c-41ed-afc8-8e076770ecd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b7cc5d4-f2cb-4132-85c1-5e44576b75a8', 'Earthquakes pushed the banks upwards', false, '7f002361-3d2c-41ed-afc8-8e076770ecd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f257a37-9909-4cb7-a47f-e5463290f076', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Why do metamorphic rocks often exhibit distinct parallel mineral bands, foliation, or striped textures (such as in Gneiss or Schist)?', 'Metamorphic foliation is the structural alignment of mineral grains perpendicular to principal tectonic stress directions under high P-T conditions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('486e6c25-e5dc-4493-9a68-cdd9fabb3501', 'Extreme directional tectonic pressure and shear stress force platy and elongated minerals to realign perpendicular to the compressive stress axis', true, '4f257a37-9909-4cb7-a47f-e5463290f076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('018bcc26-f811-468f-abf1-2b23247bdf56', 'Because different colored paints were applied to them', false, '4f257a37-9909-4cb7-a47f-e5463290f076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('387843ca-84ed-4bff-a1eb-b38c15673307', 'Because water carved lines into them', false, '4f257a37-9909-4cb7-a47f-e5463290f076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9de2f88-8759-48dd-ab45-8e3cd8651b5a', 'Because they were made by lightning', false, '4f257a37-9909-4cb7-a47f-e5463290f076');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('359e50b7-2aa3-4a73-b37a-9cdacb1214e7', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'What distinguishes a ''Mineral'' from an ordinary rock?', 'Minerals are homogeneous crystalline chemical compounds (e.g. Quartz, Feldspar, Calcite), whereas rocks are heterogeneous lithified aggregates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05076f89-32f3-4e0a-9519-c4f22ded43e6', 'A mineral is a naturally occurring inorganic substance with a definite chemical composition and an ordered internal atomic crystalline structure, whereas a rock is an aggregate of one or more minerals', true, '359e50b7-2aa3-4a73-b37a-9cdacb1214e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fecde434-d9b5-4781-9319-a77bc8ed6945', 'Minerals are artificial man-made materials', false, '359e50b7-2aa3-4a73-b37a-9cdacb1214e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('059e7a8e-d331-4030-b195-a3fb09246f15', 'Rocks are always transparent', false, '359e50b7-2aa3-4a73-b37a-9cdacb1214e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93410de4-2402-42d5-8de7-44ac5c1f1b2e', 'Minerals do not exist inside rocks', false, '359e50b7-2aa3-4a73-b37a-9cdacb1214e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f5ca84b-9ea8-4e5e-a481-920cb9a3b93c', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'What master geographical insight is established in Chapter 11 of NCERT Class 7 Geography?', 'Chapter 11 establishes dynamic planetary geomorphology: the perpetual equilibrium between endogenic tectonic construction and exogenic denudational sculpting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07ad980e-eea4-4451-a3fe-6f1d63cea31e', 'The Earth is a dynamic, living planet in perpetual transformation—where internal convective forces constantly build and reshape lithospheric crust, while external erosional agents continuously sculpt majestic landforms that sustain human agriculture, civilizational settlements, and mineral wealth', true, '6f5ca84b-9ea8-4e5e-a481-920cb9a3b93c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa3a577a-a011-4c80-b731-a179a696206b', 'That the Earth''s surface never changes', false, '6f5ca84b-9ea8-4e5e-a481-920cb9a3b93c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fc8a414-6473-46cd-815a-b7c8d7179b40', 'That rocks have no economic or ecological value', false, '6f5ca84b-9ea8-4e5e-a481-920cb9a3b93c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9e5f92b-7e46-46db-919b-60117b512364', 'That all continents will sink into the core tomorrow', false, '6f5ca84b-9ea8-4e5e-a481-920cb9a3b93c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41a702ff-8394-474a-8db8-fe7f576f2b74', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'जिन शब्दों के रूप में लिंग, वचन, कारक, काल आदि के प्रभाव से कभी कोई विकार (परिवर्तन) नहीं होता, उन्हें क्या कहते हैं?', 'अव्यय (अविकारी): जिनका रूप कभी नहीं बदलता (जैसे: और, किन्तु, धीरे-धीरे, प्रतिदिन, अरे, तक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d39affec-352b-4de2-a180-002df84379b6', 'अव्यय या अविकारी शब्द (Indeclinable words)', true, '41a702ff-8394-474a-8db8-fe7f576f2b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4405841e-b959-42f9-8f10-184fe7680c8c', 'विकारी शब्द', false, '41a702ff-8394-474a-8db8-fe7f576f2b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01fda116-7e18-4c22-a947-81391209d10e', 'संज्ञा शब्द', false, '41a702ff-8394-474a-8db8-fe7f576f2b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('827dfd34-a351-48ab-b4f8-8bb59cc536cc', 'सर्वनाम शब्द', false, '41a702ff-8394-474a-8db8-fe7f576f2b74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48e74814-e31a-48a3-901c-b2d3071112f2', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'हिंदी व्याकरण में अव्यय के मुख्य रूप से कितने भेद माने जाते हैं?', 'अव्यय के 5 भेद हैं: क्रियाविशेषण, संबंधबोधक, समुच्चयबोधक, विस्मयादिबोधक और निपात।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('410b6c08-dcfc-4c55-a43d-96efd2aca3fa', '5 भेद (1. क्रियाविशेषण, 2. संबंधबोधक, 3. समुच्चयबोधक, 4. विस्मयादिबोधक, 5. निपात)', true, '48e74814-e31a-48a3-901c-b2d3071112f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13089064-02aa-45e4-b88f-625b363ea89c', '2 भेद', false, '48e74814-e31a-48a3-901c-b2d3071112f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd2c61a5-abf8-48cf-8a8f-c02a5f08819c', '3 भेद', false, '48e74814-e31a-48a3-901c-b2d3071112f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfc08267-4bf1-468b-a324-7f58d41df35d', '8 भेद', false, '48e74814-e31a-48a3-901c-b2d3071112f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f47bca70-cb0a-4f89-b94d-6d62e7ba8bc2', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'क्रिया की विशेषता (समय, स्थान, परिमाण, रीति आदि) बताने वाले अव्यय शब्दों को क्या कहते हैं?', 'क्रियाविशेषण: जो अव्यय शब्द क्रिया के घटित होने की विशेषता (कब, कहाँ, कैसे, कितना) बताते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e459ec94-e98f-4ba2-8357-cbe4e60feb22', 'क्रियाविशेषण (Adverb)', true, 'f47bca70-cb0a-4f89-b94d-6d62e7ba8bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cac46fb9-1cbc-4ad9-9d22-94c55ca65ffa', 'विशेषण', false, 'f47bca70-cb0a-4f89-b94d-6d62e7ba8bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a644b049-59fd-4651-b48d-53e45b41831c', 'संबंधबोधक', false, 'f47bca70-cb0a-4f89-b94d-6d62e7ba8bc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47e94313-ec8f-4af6-9ddf-a964bf1b4709', 'समुच्चयबोधक', false, 'f47bca70-cb0a-4f89-b94d-6d62e7ba8bc2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19d2c582-50cf-41d9-98e8-316710c5e8c3', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'क्रियाविशेषण के मुख्य रूप से कितने भेद होते हैं?', 'क्रियाविशेषण के 4 भेद हैं: कालवाचक (कब), स्थानवाचक (कहाँ), परिमाणवाचक (कितना), रीतिवाचक (कैसे)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f82bc6f-9022-46f6-8f23-b1c12a15d5dc', '4 भेद (1. कालवाचक, 2. स्थानवाचक, 3. परिमाणवाचक, 4. रीतिवाचक)', true, '19d2c582-50cf-41d9-98e8-316710c5e8c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0143a76-688a-4960-a2de-79a6d7afc56e', '2 भेद', false, '19d2c582-50cf-41d9-98e8-316710c5e8c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f762316-c2dd-4edd-928b-ae8174c99f43', '6 भेद', false, '19d2c582-50cf-41d9-98e8-316710c5e8c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('957e1db1-cbd2-432f-aa56-9a3d89f3b181', '3 भेद', false, '19d2c582-50cf-41d9-98e8-316710c5e8c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1ba4ff3-0db9-4d55-a2b9-b21f24ea36ad', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', '''कछुआ धीरे-धीरे चलता है।'' वाक्य में ''धीरे-धीरे'' किस प्रकार का क्रियाविशेषण है?', '''धीरे-धीरे'' क्रिया के संपन्न होने की रीति (ढंग) बता रहा है, अतः यह रीतिवाचक क्रियाविशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8fe4b6d-d145-4447-b576-2cbc929db2eb', 'रीतिवाचक क्रियाविशेषण (Adverb of Manner - कैसे चलता है)', true, 'e1ba4ff3-0db9-4d55-a2b9-b21f24ea36ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('108a4940-a932-457f-a17b-caafb82e4003', 'कालवाचक', false, 'e1ba4ff3-0db9-4d55-a2b9-b21f24ea36ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94c3ebb3-fbc1-4f39-a08b-03d6f407721f', 'स्थानवाचक', false, 'e1ba4ff3-0db9-4d55-a2b9-b21f24ea36ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc5c729e-51b9-444a-8de9-ac869e0aa107', 'परिमाणवाचक', false, 'e1ba4ff3-0db9-4d55-a2b9-b21f24ea36ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5a69d36-da27-45ca-9d31-443a355755e4', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', '''हम प्रतिदिन व्यायाम करते हैं।'' वाक्य में ''प्रतिदिन'' किस प्रकार का क्रियाविशेषण है?', '''प्रतिदिन'' क्रिया के होने का समय (काल) बता रहा है, अतः यह कालवाचक क्रियाविशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee5c4f3b-e5ab-4f0b-ba3e-dc0a60b87809', 'कालवाचक क्रियाविशेषण (Adverb of Time - कब करते हैं)', true, 'f5a69d36-da27-45ca-9d31-443a355755e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e91e4c0f-fc65-498a-bd30-16f9a7c2b479', 'स्थानवाचक', false, 'f5a69d36-da27-45ca-9d31-443a355755e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52a160ad-872a-41e3-8b3a-9cbb72163058', 'रीतिवाचक', false, 'f5a69d36-da27-45ca-9d31-443a355755e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89903c47-3278-44da-944a-5d7c0903ee4b', 'परिमाणवाचक', false, 'f5a69d36-da27-45ca-9d31-443a355755e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c04338ab-cf8e-4cb4-8907-d3cd1bfade09', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', '''बच्चे ऊपर खेल रहे हैं।'' वाक्य में ''ऊपर'' किस प्रकार का क्रियाविशेषण है?', '''ऊपर'' क्रिया के संपन्न होने का स्थान बता रहा है, अतः यह स्थानवाचक क्रियाविशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db50cc5d-14ca-40cf-857f-0ec39b9f1dc8', 'स्थानवाचक क्रियाविशेषण (Adverb of Place - कहाँ खेल रहे हैं)', true, 'c04338ab-cf8e-4cb4-8907-d3cd1bfade09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef717aa9-bf3c-4c8a-b035-78b49e1486fd', 'कालवाचक', false, 'c04338ab-cf8e-4cb4-8907-d3cd1bfade09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('248edd9b-4714-4d9c-95ff-9b9138cf496c', 'परिमाणवाचक', false, 'c04338ab-cf8e-4cb4-8907-d3cd1bfade09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83cd4159-be1e-4b7f-80d8-cd2a920da911', 'रीतिवाचक', false, 'c04338ab-cf8e-4cb4-8907-d3cd1bfade09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f29f3eae-d477-436b-8a88-afdb6d2580a9', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', '''कम बोलो, अधिक काम करो।'' वाक्य में ''कम'' और ''अधिक'' किस प्रकार के क्रियाविशेषण हैं?', '''कम'' और ''अधिक'' क्रिया की मात्रा/परिमाण का बोध कराते हैं, अतः परिमाणवाचक क्रियाविशेषण हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1eba8c5-e150-43c6-ad0a-cfbeda397c44', 'परिमाणवाचक क्रियाविशेषण (Adverb of Quantity - कितना)', true, 'f29f3eae-d477-436b-8a88-afdb6d2580a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b46fa021-79f1-4920-827c-a3610ec60446', 'कालवाचक', false, 'f29f3eae-d477-436b-8a88-afdb6d2580a9');
