INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52d7a083-3816-4c0a-a4f5-7ebcf9a4cc40', 'रीतिवाचक', false, 'f29f3eae-d477-436b-8a88-afdb6d2580a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1c932aa-b2ce-44e8-9158-dcb23ff1a9ee', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'जो अव्यय शब्द संज्ञा या सर्वनाम के बाद आकर उसका संबंध वाक्य के अन्य शब्दों से जोड़ते हैं (जैसे: ''के बिना'', ''के साथ'', ''के सामने''), वे क्या कहलाते हैं?', 'संबंधबोधक: संज्ञा/सर्वनाम के पीछे प्रयुक्त होकर वाक्य के अन्य पदों से संबंध बताने वाले अव्यय।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea9c0c74-d440-4cf1-b958-600e6d886665', 'संबंधबोधक अव्यय (Postposition)', true, 'c1c932aa-b2ce-44e8-9158-dcb23ff1a9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c23f6d0a-cc84-453a-94b8-b196d862d0d4', 'समुच्चयबोधक', false, 'c1c932aa-b2ce-44e8-9158-dcb23ff1a9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f02fa75b-b067-488a-a3b0-7b287ef650fa', 'विस्मयादिबोधक', false, 'c1c932aa-b2ce-44e8-9158-dcb23ff1a9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25ab8429-5de0-44fc-acf1-fcc95161850d', 'क्रियाविशेषण', false, 'c1c932aa-b2ce-44e8-9158-dcb23ff1a9ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8c5b354-1b7a-4506-a865-8cf7d0961c8d', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'दो शब्दों, वाक्यांशों या वाक्यों को आपस में जोड़ने वाले अव्यय शब्दों (जैसे: ''और'', ''किन्तु'', ''परन्तु'', ''क्योंकि'') को क्या कहते हैं?', 'समुच्चयबोधक (योजक): दो पदों, उपवाक्यों या वाक्यों को परस्पर जोड़ने वाले अव्यय शब्द।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82bf4ef6-8679-4502-9ddd-349a1cd2bb69', 'समुच्चयबोधक या योजक (Conjunction)', true, 'c8c5b354-1b7a-4506-a865-8cf7d0961c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1eb75fa1-56c8-43e7-adba-c96f971b61fe', 'संबंधबोधक', false, 'c8c5b354-1b7a-4506-a865-8cf7d0961c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94294405-01e1-4d03-9eeb-b8479dd170be', 'विस्मयादिबोधक', false, 'c8c5b354-1b7a-4506-a865-8cf7d0961c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f06fd27-0708-4263-8833-54ef57df578b', 'निपात', false, 'c8c5b354-1b7a-4506-a865-8cf7d0961c8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dde78df-76cb-4b83-b57e-f0a44a7cf076', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'हर्ष, शोक, भय, आश्चर्य, घृणा, चेतावनी आदि तीव्र मनोभावों को प्रकट करने वाले अव्यय (जैसे: ''अरे!'', ''वाह!'', ''शाबाश!'', ''हाय!'') क्या कहलाते हैं?', 'विस्मयादिबोधक: मनोभावों (आश्चर्य, दुःख, उल्लास) को व्यक्त करने वाले अव्यय, जिनके बाद ''!'' चिह्न लगता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06968f55-e0d2-4f6e-b1b1-29286a0f5bbe', 'विस्मयादिबोधक अव्यय (Interjection)', true, '6dde78df-76cb-4b83-b57e-f0a44a7cf076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('725db9ff-94b1-494c-81c0-3bd633f5637c', 'संबंधबोधक', false, '6dde78df-76cb-4b83-b57e-f0a44a7cf076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8b5e645-7071-4e57-9ace-d73aad98b4c8', 'क्रियाविशेषण', false, '6dde78df-76cb-4b83-b57e-f0a44a7cf076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d71e0976-b305-42f9-8dfd-d7c48034d1fc', 'निपात', false, '6dde78df-76cb-4b83-b57e-f0a44a7cf076');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3e702e2-68f9-4e2e-9e3a-2660c1f22b48', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'जो अव्यय शब्द किसी शब्द के बाद लगकर उसके अर्थ में विशेष ''बल'' (Emphasis) प्रदान करते हैं (जैसे: ''ही'', ''भी'', ''तो'', ''मात्र'', ''तक''), वे क्या कहलाते हैं?', 'निपात: किसी पद पर विशेष बल देने के लिए प्रयुक्त होने वाले अव्यय (जैसे: ''वह भी जाएगा'', ''तुम ही आओगे'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33e50bd8-4446-4d15-95e1-a751f5e7c4c8', 'निपात (Particles)', true, 'f3e702e2-68f9-4e2e-9e3a-2660c1f22b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0044afb-8ae3-41b5-867c-dd322b143b17', 'क्रियाविशेषण', false, 'f3e702e2-68f9-4e2e-9e3a-2660c1f22b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39762127-436c-44b4-8b6f-7f7db69a3fa2', 'संबंधबोधक', false, 'f3e702e2-68f9-4e2e-9e3a-2660c1f22b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3866983b-dac1-41b5-988b-389f6fc93718', 'विशेषण', false, 'f3e702e2-68f9-4e2e-9e3a-2660c1f22b48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1db2541-ab1f-4f2b-9c4a-0138e347bcb6', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', 'क्रियाविशेषण और विशेषण में क्या मूलभूत व्याकरणिक अंतर होता है?', 'विशेषण संज्ञा/सर्वनाम की विशेषता प्रकट करता है; क्रियाविशेषण क्रिया की विशेषता (ढंग/समय/स्थान/मात्रा) बताता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a86c5911-abd6-40f4-baa3-105023c816cd', 'विशेषण ''संज्ञा या सर्वनाम'' की विशेषता बताता है (जैसे: ''मीठा सेब'') ; जबकि क्रियाविशेषण ''क्रिया'' की विशेषता बताता है (जैसे: ''मधुर गाता है'')', true, 'f1db2541-ab1f-4f2b-9c4a-0138e347bcb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22c8dba2-cf6c-4c0a-856c-20869b759792', 'दोनों में कोई अंतर नहीं होता', false, 'f1db2541-ab1f-4f2b-9c4a-0138e347bcb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02c3210f-9718-4102-89c3-6e7cb139e547', 'विशेषण केवल वाक्यों के अंत में आता है', false, 'f1db2541-ab1f-4f2b-9c4a-0138e347bcb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bc21bc9-1b0e-49cc-84ae-2729e425e4b0', 'क्रियाविशेषण में विकार होता है', false, 'f1db2541-ab1f-4f2b-9c4a-0138e347bcb6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e23917b1-8036-4988-a27e-8219af604798', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', 'समुच्चयबोधक (योजक) के मुख्य रूप से दो भेद कौन-से होते हैं?', 'समुच्चयबोधक के 2 भेद हैं: समानाधिकरण (समान स्तर के उपवाक्यों को जोड़ने वाले) और व्यधिकरण (आश्रित उपवाक्य जोड़ने वाले)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d6a146c-ec3c-4e96-b037-4b7ca9bc7fab', '1. समानाधिकरण समुच्चयबोधक (और, तथा, या, किन्तु, परन्तु, इसलिए) ; 2. व्यधिकरण समुच्चयबोधक (क्योंकि, ताकि, यद्यपि-तथापि, जिससे कि)', true, 'e23917b1-8036-4988-a27e-8219af604798');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('779aad7d-e73e-48b3-ad26-a73537da8b18', 'सकर्मक और अकर्मक', false, 'e23917b1-8036-4988-a27e-8219af604798');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42a2ed21-1ac6-4561-9819-5d527e3d39ae', 'गुणवाचक और संख्यावाचक', false, 'e23917b1-8036-4988-a27e-8219af604798');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1af19a79-03c9-4636-a921-af43a6f2a228', 'व्यक्तिवाचक और जातिवाचक', false, 'e23917b1-8036-4988-a27e-8219af604798');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87795d5c-6e61-4034-aa1a-1bb935c818d2', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''विद्या के बिना जीवन व्यर्थ है।'' इस वाक्य में ''के बिना'' किस प्रकार का अव्यय है?', '''के बिना'' संज्ञा ''विद्या'' के बाद आकर वाक्य के अन्य शब्दों से संबंध जोड़ रहा है, अतः यह संबंधबोधक अव्यय है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22fcd63c-a54b-44c8-a5d0-29acb7c66fac', 'संबंधबोधक अव्यय', true, '87795d5c-6e61-4034-aa1a-1bb935c818d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db427f5a-d081-4b84-bb35-b27ad1997005', 'क्रियाविशेषण', false, '87795d5c-6e61-4034-aa1a-1bb935c818d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd89fd4e-2490-4a2b-b45e-93816b968e35', 'समुच्चयबोधक', false, '87795d5c-6e61-4034-aa1a-1bb935c818d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a50a4306-77d0-4054-bcaa-8e166e5d0d91', 'विस्मयादिबोधक', false, '87795d5c-6e61-4034-aa1a-1bb935c818d2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('787eb6a6-779d-4284-a455-0f2e6fb1bca4', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''वह विद्यालय नहीं गया क्योंकि वह बीमार था।'' इस वाक्य में ''क्योंकि'' किस प्रकार का समुच्चयबोधक है?', '''क्योंकि'' मुख्य उपवाक्य के साथ कारण बताने वाले आश्रित उपवाक्य को जोड़ता है, अतः यह कारणवाचक व्यधिकरण समुच्चयबोधक है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9672bab7-c82b-43f4-a635-4299f52e6a87', 'कारणवाचक व्यधिकरण समुच्चयबोधक', true, '787eb6a6-779d-4284-a455-0f2e6fb1bca4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74530b9c-77e3-4dd6-9d9d-386cb4c77a6b', 'संयोजक समानाधिकरण', false, '787eb6a6-779d-4284-a455-0f2e6fb1bca4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6831cdbc-e169-4653-8ed0-830b68d0b92f', 'विभाजक', false, '787eb6a6-779d-4284-a455-0f2e6fb1bca4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2abf2a9-5ea0-4587-8406-7bb2b7ef1e56', 'परिणामदर्शक', false, '787eb6a6-779d-4284-a455-0f2e6fb1bca4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65371fd3-068c-4b1f-a9c6-1ed7160e9e59', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''शाबाश! तुमने परीक्षा में प्रथम स्थान प्राप्त किया।'' वाक्य में ''शाबाश!'' किस मनोभाव को प्रकट करने वाला विस्मयादिबोधक है?', '''शाबाश!'' प्रशंसा, उत्साह और अनुमोदन व्यक्त करने वाला विस्मयादिबोधक अव्यय है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47b37db7-ee37-4982-ab72-40b43b775172', 'प्रशंसा / हर्षसूचक विस्मयादिबोधक', true, '65371fd3-068c-4b1f-a9c6-1ed7160e9e59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b52b119b-d661-45d5-9856-933b723fb0c0', 'शोकसूचक', false, '65371fd3-068c-4b1f-a9c6-1ed7160e9e59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4f6d76c-1c79-44f6-9057-f84b63ce6106', 'भयसूचक', false, '65371fd3-068c-4b1f-a9c6-1ed7160e9e59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a27c1e1-2e7e-4768-a129-00b682da3773', 'घृणासूचक', false, '65371fd3-068c-4b1f-a9c6-1ed7160e9e59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('790ab26a-5695-420b-b82c-0190fc3d70cd', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''राम ने ही यह काम किया है।'' और ''राम ने यह काम भी किया है।'' में ''ही'' और ''भी'' निपात का क्या प्रभाव है?', '''ही'' सीमा/अवधारण (केवल वही) तथा ''भी'' समुच्चय/समावेश (वह भी) का विशिष्ट अर्थगत बल प्रदान करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83873fd4-e444-4ca3-96e1-7bef70e7cf8b', '''ही'' केवल राम पर अनन्य बल देता है (किसी अन्य ने नहीं) ; जबकि ''भी'' अतिरिक्तता/समावेश का बोध कराता है (अन्य के साथ राम ने भी)', true, '790ab26a-5695-420b-b82c-0190fc3d70cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd307bcc-0df1-421c-adb5-3f356ef2b556', 'दोनों वाक्यों का अर्थ बिल्कुल एकसमान है', false, '790ab26a-5695-420b-b82c-0190fc3d70cd');
