INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c01faed-ff38-4728-bdc9-b86989c4a95c', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''भीतर'' शब्द का प्रयोग निम्नलिखित दो वाक्यों में किस रूप में हुआ है?
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d69420e7-a5d3-4278-a2e9-4d4e4f7d1fa4', 'वाक्य 1 में ''भीतर'' = स्थानवाचक क्रियाविशेषण ; वाक्य 2 में ''के भीतर'' = संबंधबोधक अव्यय', true, '5c01faed-ff38-4728-bdc9-b86989c4a95c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bef7e8f-6d27-444f-9a45-b164b593be35', 'दोनों में क्रियाविशेषण है', false, '5c01faed-ff38-4728-bdc9-b86989c4a95c');
