INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85d7de55-fc9c-4c4d-9025-b208cfd17592', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''छी-छी! यहाँ कितनी गंदगी फैली है।'' वाक्य में ''छी-छी!'' किस प्रकार का विस्मयादिबोधक है?', '''छी-छी!'' घृणा, अरुचि और तिरस्कार का मनोभाव प्रकट करता है।', NOW()) ON CONFLICT DO NOTHING;
