INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d7ff44e-e0d6-454e-87c5-6bec837182cb', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''तुम चाय पियोगे अथवा कॉफ़ी?'' वाक्य में ''अथवा'' किस प्रकार का समुच्चयबोधक है?', '''अथवा / या'' दो विकल्पों में से किसी एक के चयन का बोध कराने वाला विभाजक समुच्चयबोधक है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf3e572a-fb12-4e23-a298-75604023298a', 'विभाजक / विकल्पसूचक समानाधिकरण समुच्चयबोधक', true, '0d7ff44e-e0d6-454e-87c5-6bec837182cb');
