INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84d53882-dead-49c3-8944-02e138299a29', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''उसने बहुत परिश्रम किया किन्तु सफल न हो सका।'' वाक्य में ''किन्तु'' किस प्रकार का समुच्चयबोधक है?', '''किन्तु / परन्तु / लेकिन'' पहले उपवाक्य के विपरीत परिणाम/विरोध को प्रकट करता है।', NOW()) ON CONFLICT DO NOTHING;
