INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eebbcb42-0add-41a2-bed3-8ebe9d34ce81', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''अरे! तुम कब आए?'' वाक्य में ''अरे!'' किस भाव को व्यक्त करता है?', '''अरे!'' आकस्मिक विस्मय और आश्चर्य प्रकट करने वाला अव्यय है।', NOW()) ON CONFLICT DO NOTHING;
