INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a3f0327-212a-4e28-a093-91dbed72e22b', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''घर के सामने एक विशाल बरगद का पेड़ है।'' वाक्य में ''के सामने'' क्या है?', '''के सामने'' संज्ञा ''घर'' और ''बरगद के पेड़'' के बीच स्थानिक संबंध स्थापित करने वाला संबंधबोधक अव्यय है।', NOW()) ON CONFLICT DO NOTHING;
