INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32213add-4a8b-4f9e-8f3a-12c84972a7b9', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''अव्यय'' (अविकारी) नहीं है?', '''सुंदर'' विशेषण (विकारी) है, जबकि ''और'', ''धीरे-धीरे'', ''किन्तु'' अपरिवर्तनशील अव्यय हैं।', NOW()) ON CONFLICT DO NOTHING;
