INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc8645d7-ca77-4593-b3f8-be68ac746e11', 'वर्ग 2', false, '3ce14ef4-a465-4d0c-9f63-16fcb560e5e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d765d5ac-824e-4db0-abee-e9b30106479a', 'वर्ग 3', false, '3ce14ef4-a465-4d0c-9f63-16fcb560e5e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69467bdb-a092-4b2a-92f6-c5b7729304af', 'वर्ग 4 (''पुस्तक'' और ''हिमालय'' संज्ञा शब्द [विकारी] हैं, विस्मयादिबोधक अव्यय नहीं)', true, '3ce14ef4-a465-4d0c-9f63-16fcb560e5e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('024f56a6-cae0-4b11-a078-7bf344587474', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'सुमेलित कीजिए (क्रियाविशेषण के 4 भेद और उनके प्रश्नवाचक पहचान शब्द):
(क) कालवाचक क्रियाविशेषण   -> (i) ''कब'' (When)
(ख) स्थानवाचक क्रियाविशेषण -> (ii) ''कहाँ'' (Where)
(ग) परिमाणवाचक क्रियाविशेषण-> (iii) ''कितना'' (How much)
(घ) रीतिवाचक क्रियाविशेषण   -> (iv) ''कैसे / किस प्रकार'' (How)', 'काल = कब; स्थान = कहाँ; परिमाण = कितना; रीति = कैसे।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('079df067-8740-4ed5-bdfc-8ec0034b62c9', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '024f56a6-cae0-4b11-a078-7bf344587474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0440afad-f356-4f39-9a1c-1574518bcef0', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '024f56a6-cae0-4b11-a078-7bf344587474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f55d8ea-e9d1-405a-98ee-95faa17d31ae', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '024f56a6-cae0-4b11-a078-7bf344587474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('476a89ca-9ae6-4b9e-bdb7-e6712a1dec43', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '024f56a6-cae0-4b11-a078-7bf344587474');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3490bb90-412b-4d1d-b70d-f873ff1bf4bd', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'समानाधिकरण समुच्चयबोधक के 4 उप-भेदों का सही मिलान कौन-सा है?', 'समानाधिकरण के 4 रूप: संयोजक (जोड़ने वाला), विभाजक (विकल्प), विरोधदर्शक (अंतर), परिणामदर्शक (फलस्वरूप)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bddc44f-b456-46ec-a241-bb230f5275b6', '1. संयोजक (और, तथा) ; 2. विभाजक (या, अथवा) ; 3. विरोधदर्शक (किन्तु, परन्तु, मगर) ; 4. परिणामदर्शक (इसलिए, अतः, फलस्वरूप)', true, '3490bb90-412b-4d1d-b70d-f873ff1bf4bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b25a778-ca27-4699-a757-744111f38475', 'संयोजक केवल स्त्रीलिंग होता है', false, '3490bb90-412b-4d1d-b70d-f873ff1bf4bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d7df3c6-ba73-4cdf-b67b-ccf8877083d0', 'विभाजक में हमेशा नकारात्मक क्रिया होती है', false, '3490bb90-412b-4d1d-b70d-f873ff1bf4bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f79e3f6-460b-4118-9fa4-ee5107674fa3', 'परिणामदर्शक केवल भविष्यत में आता है', false, '3490bb90-412b-4d1d-b70d-f873ff1bf4bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1d27c22-c802-4113-9060-4c5cce7312ee', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''निपात'' का गलत स्थान पर प्रयोग होने से वाक्य का अभीष्ट अर्थ बदल गया है?', 'निपात का स्थान बदलने से वाक्य में बल और अर्थ का केंद्र पूरी तरह बदल जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eaebe1d-927c-4596-8991-181e7d6fa8e7', '''केवल उसने मुझे एक पुस्तक दी।'' (अर्थ: सिर्फ उसी व्यक्ति ने दी, किसी और ने नहीं ; यदि ''उसने मुझे केवल एक पुस्तक दी'' लिखा जाए तो अर्थ: सिर्फ एक ही पुस्तक दी)', true, 'e1d27c22-c802-4113-9060-4c5cce7312ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5688d93-2415-4b03-bdeb-d33a2823b7a2', '''वह कल आएगा।''', false, 'e1d27c22-c802-4113-9060-4c5cce7312ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a750f8d-b9b9-4047-a402-ac271c9aa5ec', '''हम सब भारतवासी हैं।''', false, 'e1d27c22-c802-4113-9060-4c5cce7312ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdd6c45c-75d5-4fe8-8630-e8b69f3bf5be', '''सत्य की सदैव विजय होती है।''', false, 'e1d27c22-c802-4113-9060-4c5cce7312ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79af43ae-386d-4142-b30b-e95053fe57eb', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', '''यद्यपि वह निर्धन है तथापि अत्यंत ईमानदार है।'' वाक्य में ''यद्यपि...तथापि'' किस प्रकार का समुच्चयबोधक युग्म है?', '''यद्यपि...तथापि'' / ''यदि...तो'' संकेतवाचक व्यधिकरण समुच्चयबोधक युग्म (Correlative conjunctions) हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce8d3bb4-2b9c-4f60-8a8b-20a26bf78730', 'संकेतवाचक / विरोधसूचक व्यधिकरण समुच्चयबोधक', true, '79af43ae-386d-4142-b30b-e95053fe57eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1742073-0e80-4e98-b3ce-3451d6b67844', 'संयोजक समानाधिकरण', false, '79af43ae-386d-4142-b30b-e95053fe57eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cd53e71-e8b4-4d4a-9903-27ebd6839e7e', 'विभाजक', false, '79af43ae-386d-4142-b30b-e95053fe57eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('316711ef-64a4-40cb-994e-fa7df620fc1f', 'उद्देश्यवाचक', false, '79af43ae-386d-4142-b30b-e95053fe57eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c3aa59a-9dff-41ba-b4e6-93f2afd75bc9', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'क्रियाविशेषण की रचना के आधार पर ''मूल क्रियाविशेषण'' और ''यौगिक क्रियाविशेषण'' में क्या अंतर होता है?', 'मूल क्रियाविशेषण रूढ़ होते हैं; यौगिक क्रियाविशेषण प्रत्यय योग, समास अथवा शब्द-युग्मों की द्विरुक्ति से निर्मित होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ff41057-6e0f-4934-ab88-d0a8ff28e251', 'मूल क्रियाविशेषण बिना किसी प्रत्यय या रूपांतरण के स्वतंत्र रूप में आते हैं (जैसे: ठीक, अचानक, दूर, पास) ; जबकि यौगिक क्रियाविशेषण प्रत्यय, समास या द्विरुक्ति से बनते हैं (जैसे: प्रेमपूर्वक, हाथों-हाथ, धीरे-धीरे, प्रतिदिन)', true, '7c3aa59a-9dff-41ba-b4e6-93f2afd75bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58fb45cd-a8f3-4bff-be5d-f6afa84bfb67', 'दोनों में कोई अंतर नहीं होता', false, '7c3aa59a-9dff-41ba-b4e6-93f2afd75bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5ebd213-09f5-45d7-a477-529f49b32a29', 'मूल क्रियाविशेषण केवल एक अक्षर का होता है', false, '7c3aa59a-9dff-41ba-b4e6-93f2afd75bc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('191a8a39-5475-480a-86c2-f37b8e6c2a17', 'यौगिक क्रियाविशेषण केवल संस्कृत में होते हैं', false, '7c3aa59a-9dff-41ba-b4e6-93f2afd75bc9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e0345b0-b886-4d52-88c9-30475af67e55', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', '''सावधान! आगे गहरा गड्ढा है।'' वाक्य में ''सावधान!'' किस प्रकार का विस्मयादिबोधक है?', '''सावधान! / होशियार! / बचो!'' आने वाले खतरे के प्रति सतर्क करने वाले चेतावनीसूचक विस्मयादिबोधक अव्यय हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('896ba81b-4dae-4e4f-8bec-1138f14ca7fe', 'चेतावनीसूचक विस्मयादिबोधक', true, '0e0345b0-b886-4d52-88c9-30475af67e55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f83e0e17-e283-41a3-bd7e-a4a4f0b19a85', 'हर्षसूचक', false, '0e0345b0-b886-4d52-88c9-30475af67e55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee6b3020-b6b7-41f8-ac24-ef1c70990534', 'शोकसूचक', false, '0e0345b0-b886-4d52-88c9-30475af67e55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04dbe020-a527-48f8-b175-642a66228e82', 'संबोधनसूचक', false, '0e0345b0-b886-4d52-88c9-30475af67e55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a5669d2-f900-4fbe-a198-95fa6298a734', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'निम्नलिखित में से किस वाक्य में ''स्थानवाचक क्रियाविशेषण'' का शुद्ध प्रयोग हुआ है?', '''चारों ओर / इधर-उधर / सर्वत्र'' स्थान व दिशा का बोध कराने वाले स्थानवाचक क्रियाविशेषण हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a2b62dc-bf6f-462c-8826-fdc0d7282c20', '''पक्षी आकाश में चारों ओर उड़ रहे हैं।'' (''चारों ओर'' क्रिया के घटित होने की दिशा/स्थान बता रहा है)', true, '2a5669d2-f900-4fbe-a198-95fa6298a734');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abf73d54-d1c5-4484-be29-984b6fcb1222', '''वह कल आएगा।''', false, '2a5669d2-f900-4fbe-a198-95fa6298a734');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab913355-02cb-4959-83db-1d8b101d6152', '''उसने बहुत खाया।''', false, '2a5669d2-f900-4fbe-a198-95fa6298a734');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd16304b-3d34-4788-8665-94ecf31472dc', '''वह धीरे-धीरे बोला।''', false, '2a5669d2-f900-4fbe-a198-95fa6298a734');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74feb543-eacc-4863-8a40-1efcad16b479', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', '''हाय! बेचारा दुर्घटना में घायल हो गया।'' वाक्य में ''हाय!'' किस मनोभाव को व्यक्त करता है?', '''हाय! / उफ़! / आह!'' दुःख, वेदना और शोक की तीव्र भावात्मक अभिव्यक्ति करते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bac5c8c1-412c-4916-a4a4-1e72a68e2f08', 'शोक / पीड़ा / सहानुभूति का भाव', true, '74feb543-eacc-4863-8a40-1efcad16b479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d48e99c-a83d-4c79-aa23-7c11ccdbafa1', 'प्रसन्नता का भाव', false, '74feb543-eacc-4863-8a40-1efcad16b479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f1a81ae-5304-4591-ae23-0e885d51b15a', 'क्रोध का भाव', false, '74feb543-eacc-4863-8a40-1efcad16b479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed2afc4d-8c23-4393-8750-fdbdba34ec60', 'उल्लास का भाव', false, '74feb543-eacc-4863-8a40-1efcad16b479');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc3e49e1-1f90-40bc-a8fb-2ed75bb0de9d', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'प्रमुख 9 निपातों (ही, भी, तो, तक, मात्र, भर, केवल, सा, जी) का वाक्य में क्या सर्वोच्च प्रयोजन होता है?', 'निपात वाक्य में विशेष अर्थगत अवधारण, आग्रह, सीमा अथवा बल की सूक्ष्म अभिव्यक्ति हेतु प्रयुक्त होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15939678-828b-4ca3-8547-7437dd264b77', 'ये किसी पद के साथ प्रयुक्त होकर उसके अर्थ को सीमित, निश्चित, विस्तारित या विशिष्ट भावात्मक बल (Emphatic force) प्रदान करते हैं', true, 'bc3e49e1-1f90-40bc-a8fb-2ed75bb0de9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bf0b668-ce8f-45b6-82bd-5f511201c112', 'ये केवल वाक्य को लंबा बनाते हैं', false, 'bc3e49e1-1f90-40bc-a8fb-2ed75bb0de9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62b18742-89eb-410c-ac32-401b931d6350', 'ये संज्ञा का लिंग बदल देते हैं', false, 'bc3e49e1-1f90-40bc-a8fb-2ed75bb0de9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ae1661c-3d35-4765-a307-baf645364bd8', 'ये क्रिया को भूतकाल में बदल देते हैं', false, 'bc3e49e1-1f90-40bc-a8fb-2ed75bb0de9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('921c0aa1-6104-49af-958d-82327af758e7', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'अव्यय (अविकारी शब्दों) का हिंदी भाषा संरचना में क्या केंद्रीय महत्व है?', 'अव्यय भाषा की तार्किक सुसंबद्धता (Cohesion), मनोभाव प्रकटन और संश्लिष्ट वाक्य-संयोजन के अनिवार्य माध्यम हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fe80497-47a9-4d92-ad3a-9bc48dc809d9', 'अव्यय भाषा को सुगठित, प्रवाहपूर्ण और तार्किक बनाते हैं; ये उपवाक्यों को जोड़ते हैं, क्रिया की सटीक परिस्थितियाँ स्पष्ट करते हैं, और भाषा में सूक्ष्म मनोभावों तथा अर्थ-बल का संचार करते हैं', true, '921c0aa1-6104-49af-958d-82327af758e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df33c8b2-37a3-443b-a5e4-dc41c3c9eadf', 'अव्यय केवल कविताओं में प्रयुक्त होते हैं', false, '921c0aa1-6104-49af-958d-82327af758e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1f31fd0-44f7-4919-8f62-c3eba70200e2', 'इनके बिना भी भाषा का रूप अपरिवर्तित रहता है', false, '921c0aa1-6104-49af-958d-82327af758e7');
