INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('131293eb-a50c-425f-aa21-d789fe530101', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What is the continuous roof-like overhead layer formed by the leafy branches and foliage of tall trees in a dense forest called?', 'The canopy is the uppermost continuous ceiling formed by the interlocking leafy crowns of mature tall trees in a forest.', NOW()) ON CONFLICT DO NOTHING;
