INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae006e59-4af7-42db-b988-1b8f2e287425', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What is the branchy upper part of an individual tree above the stem or trunk called?', 'The crown is the top portion of a tree comprising branches, twigs, and foliage radiating outward above the trunk.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('216cc8f0-108d-4457-8045-4cae9bb6cd45', 'The Crown of the tree', true, 'ae006e59-4af7-42db-b988-1b8f2e287425');
