INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('738f469f-cdf2-44b8-a538-3424ba0011bc', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What are the horizontal vegetation layers of smaller trees, shrubs, tall herbs, and grasses growing beneath the high canopy called?', 'The understorey consists of intermediate vegetation strata (small trees, shrubs, bushes, herbs) thriving in the shade below the canopy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2969b77-2cfc-40ea-814d-ccde3f62a297', 'The Understorey', true, '738f469f-cdf2-44b8-a538-3424ba0011bc');
