INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26871c4a-dd7b-4c3d-a094-72e7e8b72fd9', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'Why are forests celebrated and referred to as the ''GREEN LUNGS'' of our planet?', 'Forests regulate planetary gas exchange: green plants fix carbon dioxide and release life-sustaining oxygen during photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('841f8094-35e9-4a99-b1b1-f01d7987247f', 'Through photosynthesis, forest trees release vast amounts of OXYGEN into the atmosphere and absorb CARBON DIOXIDE, maintaining atmospheric gas balance', true, '26871c4a-dd7b-4c3d-a094-72e7e8b72fd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd79549f-32ca-4519-ab9b-83fff458b7a8', 'Because trees are green in color', false, '26871c4a-dd7b-4c3d-a094-72e7e8b72fd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54e878d6-8a70-4ec8-ba69-8935cf3185a7', 'Because leaves look like human lungs', false, '26871c4a-dd7b-4c3d-a094-72e7e8b72fd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f48de4d7-1a74-45cf-8ebd-9618681f4374', 'Because animals sleep in forests', false, '26871c4a-dd7b-4c3d-a094-72e7e8b72fd9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ec1f559-cedc-4355-895f-705286e6274f', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What are the specialized micro-organisms (bacteria and fungi) that break down dead plant and animal matter into dark, nutrient-rich HUMUS called?', 'Decomposers recycle organic biomass by converting decaying detritus into dark fertile humus that replenishes soil nutrients.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f8b3a9e-a0fc-4e01-b399-dadb481a6e95', 'Decomposers (Saprophytes)', true, '6ec1f559-cedc-4355-895f-705286e6274f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbd7164d-6c28-4a66-9879-27ed03ec22c8', 'Producers', false, '6ec1f559-cedc-4355-895f-705286e6274f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8272238c-be38-42b8-a4b6-101069755b3e', 'Herbivores', false, '6ec1f559-cedc-4355-895f-705286e6274f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e07c31f-ea39-4860-818d-a03221852f64', 'Carnivores', false, '6ec1f559-cedc-4355-895f-705286e6274f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('412e70a7-de8c-4f43-a927-6423b9f9273a', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'How do forest tree root systems and the forest floor prevent destructive FLASH FLOODS and SOIL EROSION?', 'Forest leaf litter and dense root networks decelerate raindrops, arrest surface runoff, facilitate groundwater percolation, and bind topsoil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('550129c1-8776-4a10-9f38-708ea47304e8', 'The thick forest floor and root networks act as a giant natural sponge, slowing down rainwater runoff, allowing water to seep into the ground to recharge groundwater', true, '412e70a7-de8c-4f43-a927-6423b9f9273a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6729c80c-9546-4726-82f9-7b871e2c74da', 'Trees block rain from falling from clouds', false, '412e70a7-de8c-4f43-a927-6423b9f9273a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('325fb762-fc13-47ea-b6e5-d69db21b69c0', 'Trees push water into the ocean directly', false, '412e70a7-de8c-4f43-a927-6423b9f9273a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e468c4b1-27ab-4a15-9766-488aa310a5f3', 'Trees turn rainwater into solid ice', false, '412e70a7-de8c-4f43-a927-6423b9f9273a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95d1c002-3227-465c-a0bb-f876fd457d62', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What is ''SEWAGE'' in environmental science?', 'Sewage is municipal liquid waste carrying fecal matter, detergents, pathogens, organic refuse, and hazardous chemical contaminants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f8c211e-b2d4-4e0c-a007-176c566462f6', 'Liquid wastewater produced by households, industries, hospitals, and commercial establishments carrying dissolved and suspended contaminants', true, '95d1c002-3227-465c-a0bb-f876fd457d62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df5615e2-afc5-4540-8687-942ce84ebd06', 'Clean drinking water from mountain streams', false, '95d1c002-3227-465c-a0bb-f876fd457d62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('940d4e30-65b8-4138-827f-1f0bf5b8b078', 'Rainwater stored in reservoirs', false, '95d1c002-3227-465c-a0bb-f876fd457d62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c74b4e7-a049-4f13-9dcf-afa5f1059241', 'Solid garbage collected in trucks', false, '95d1c002-3227-465c-a0bb-f876fd457d62');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92f69c48-0f41-4a8a-83c0-374bc6e0f891', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What does the technological abbreviation ''WWTP'' stand for in municipal water management?', 'A Wastewater Treatment Plant (WWTP) is a facility that removes physical, biological, and chemical pollutants from sewage water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cf57841-2633-4b57-ba15-607a11dc3908', 'Wastewater Treatment Plant', true, '92f69c48-0f41-4a8a-83c0-374bc6e0f891');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af3935b9-b4e5-491b-a28a-224b492d6001', 'Water Wind Turbine Project', false, '92f69c48-0f41-4a8a-83c0-374bc6e0f891');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5263392-5f8f-4693-8caf-87ef2c50db21', 'Waste Weather Temperature Program', false, '92f69c48-0f41-4a8a-83c0-374bc6e0f891');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e5e1238-077f-408c-9a37-b7e379f00446', 'Worldwide Tanker Petroleum', false, '92f69c48-0f41-4a8a-83c0-374bc6e0f891');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ab2e674-e887-40ef-bdb3-34501ec4b671', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'In the first primary stage of a WWTP, what mechanical filters are used to screen out large physical debris such as rags, plastic bottles, sticks, and cans?', 'Bar screens are vertical metal grids that intercept and remove coarse floating solids (plastics, rags, wood) from raw sewage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67e8e513-47cc-4d21-be7c-7e117460dc8b', 'Bar Screens', true, '7ab2e674-e887-40ef-bdb3-34501ec4b671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('797ee299-af25-4a6f-8707-be90bca18392', 'Sand filters', false, '7ab2e674-e887-40ef-bdb3-34501ec4b671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee28f9e6-2006-41f0-86f4-cff67989a48a', 'Aeration tanks', false, '7ab2e674-e887-40ef-bdb3-34501ec4b671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4a9058-c553-481f-beff-47fc3338d336', 'Chlorine chambers', false, '7ab2e674-e887-40ef-bdb3-34501ec4b671');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e6b7ab8-139d-4fee-819e-beae7a3ebe1d', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What is the semi-solid organic matter that settles at the bottom of the large central sedimentation tank (clarifier) in a WWTP called?', 'Sludge is the settled organic particulate matter scraped from clarifier bottoms, subsequently digested in anaerobic bio-reactors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63b5bfa5-0331-4767-8405-7d6d37bbbfd9', 'Sludge (Primary / Activated Sludge)', true, '7e6b7ab8-139d-4fee-819e-beae7a3ebe1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02bf5853-e29e-4c5b-b195-456481776a08', 'Grit', false, '7e6b7ab8-139d-4fee-819e-beae7a3ebe1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6067cfc7-f472-4dd4-baa6-74823bc325d0', 'Scum', false, '7e6b7ab8-139d-4fee-819e-beae7a3ebe1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d5170e2-3d84-41bb-b8bb-630fd30cac6b', 'Foam', false, '7e6b7ab8-139d-4fee-819e-beae7a3ebe1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('763d023a-f17e-4961-9f30-f48636d5ab0c', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What common disinfectant chemical (or gas) is added to treated wastewater before releasing it into rivers to kill harmful disease-causing microbes?', 'Chlorination (or UV irradiation/ozonation) oxidizes and eradicates pathogenic bacteria, viruses, and parasites before environmental discharge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23a1ba63-aa54-4be6-b6fc-728713786ede', 'Chlorine (or Ozone / Ultraviolet Light)', true, '763d023a-f17e-4961-9f30-f48636d5ab0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ad49903-9a24-44f2-bfec-f110369b217b', 'Salt', false, '763d023a-f17e-4961-9f30-f48636d5ab0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3354e78d-66a5-4713-a6e2-400ee6f5a095', 'Sugar', false, '763d023a-f17e-4961-9f30-f48636d5ab0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d49c474-7d79-4e5c-94ae-c627e6003dc1', 'Sulfuric acid', false, '763d023a-f17e-4961-9f30-f48636d5ab0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ae22a8a-1b51-4e79-9646-deb9631e1bcd', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'Which fast-growing tree species is recommended to be planted alongside wastewater sewage ponds because it absorbs surplus wastewater rapidly and releases pure water vapor into the air?', 'Eucalyptus trees have high transpiration rates, absorbing large volumes of wastewater and purifying groundwater bio-ecologically.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f85a8eb-bb1d-4412-90d9-9306856a0844', 'Eucalyptus Trees', true, '1ae22a8a-1b51-4e79-9646-deb9631e1bcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f5ed75f-7184-45db-9c0a-b84dffbb5e2a', 'Cactus', false, '1ae22a8a-1b51-4e79-9646-deb9631e1bcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84ead207-db6b-45e3-a28d-9718fd32eb3b', 'Banyan Tree', false, '1ae22a8a-1b51-4e79-9646-deb9631e1bcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2fd50ec-f635-4b30-a473-8aaf2bb4f265', 'Pine Tree', false, '1ae22a8a-1b51-4e79-9646-deb9631e1bcd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b480d9f-1ba6-4707-bb2e-e907bb0066c9', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Why is a forest referred to as a ''DYNAMIC LIVING ENTITY — FULL OF LIFE AND VITALITY''?', 'Forest ecosystems exhibit complex trophic self-regulation: producers, consumers, and decomposers recycle matter in an enduring dynamic equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24fc8d78-262c-42cb-891b-18ebf835216c', 'It sustains an interconnected web of diverse flora, fauna, insects, and decomposers where nutrients are endlessly recycled, energy flows continuously, and life regenerates autonomously', true, '1b480d9f-1ba6-4707-bb2e-e907bb0066c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e882fbe-d655-4366-8d19-886aced29212', 'Because trees walk around at night', false, '1b480d9f-1ba6-4707-bb2e-e907bb0066c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7c8def2-1fba-4669-bde7-ed3c79bab58b', 'Because it is powered by electric generators', false, '1b480d9f-1ba6-4707-bb2e-e907bb0066c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8084d1b5-1dbb-4c00-9566-c078b5b4b24d', 'Because humans plant every tree every year', false, '1b480d9f-1ba6-4707-bb2e-e907bb0066c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4396b4a8-bbbe-4d71-9a1d-97d863980e21', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What occurs during the ''AERATION'' stage in a modern Wastewater Treatment Plant?', 'Aeration tanks supply dissolved oxygen to heterotrophic aerobic microorganisms, accelerating the biological decomposition of organic pollutants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ef92cdf-e621-4696-84df-dece4d385a1d', 'Compressed air is vigorously pumped into clarified wastewater to stimulate the rapid growth of AEROBIC BACTERIA that consume human waste, food residue, and soaps', true, '4396b4a8-bbbe-4d71-9a1d-97d863980e21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f15a42-9f78-42ba-9fcf-aeb8215aa446', 'Water is frozen into solid ice blocks', false, '4396b4a8-bbbe-4d71-9a1d-97d863980e21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('632fcd01-964e-4ce4-8e27-2e4434300926', 'Water is boiled in giant furnaces', false, '4396b4a8-bbbe-4d71-9a1d-97d863980e21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d032b2fa-810e-461c-aa80-f29dc8ac079a', 'Chemicals are added to dye the water blue', false, '4396b4a8-bbbe-4d71-9a1d-97d863980e21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c896785-64a4-4bdf-ba3c-568b2d841e1b', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'How is the organic ''Sludge'' collected from clarifier tanks beneficially utilized in sustainable waste management?', 'Anaerobic sludge digestion yields methane-rich biogas for renewable energy and sterile bio-solids for agricultural soil fertilization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('443cd355-23e4-4d8b-a815-513787e5fb55', 'It is transferred to closed digester tanks where ANAEROBIC BACTERIA decompose it, producing BIOGAS (used as fuel/electricity) and nutrient-rich manure for farming', true, '4c896785-64a4-4bdf-ba3c-568b2d841e1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eef9822e-28b6-4c9e-8a96-9ba50e44aee8', 'It is thrown into the ocean', false, '4c896785-64a4-4bdf-ba3c-568b2d841e1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f4adf9d-34b1-411b-addd-c2080ee72c1b', 'It is turned into plastic toys', false, '4c896785-64a4-4bdf-ba3c-568b2d841e1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6076dfc9-7093-4c74-84cb-ca44d2025b60', 'It is burned as coal in train engines', false, '4c896785-64a4-4bdf-ba3c-568b2d841e1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35f7ecb6-de2c-4faa-aa15-1a4d90aedb0e', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Why should used cooking oils and animal fats NEVER be poured down domestic kitchen sink drains?', 'Cooking fats congeal into stubborn ''fatbergs'', obstructing sewer lines and coating soil particles, which impedes wastewater filtration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abb29431-61ec-4975-8f90-e1adb965d07c', 'Fats harden and solidify inside drain pipes, clogging plumbing, and in open drains they block soil pores, impairing natural water filtration', true, '35f7ecb6-de2c-4faa-aa15-1a4d90aedb0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73cc0c80-88a0-431b-b279-d8d6177f1e59', 'Fats attract fish into the pipes', false, '35f7ecb6-de2c-4faa-aa15-1a4d90aedb0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78a9e9b0-a7fb-477e-8877-af60b2d27d4d', 'Fats make water smell like roses', false, '35f7ecb6-de2c-4faa-aa15-1a4d90aedb0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5e3aa83-f7f1-410d-b92d-085a9b8dd20a', 'Fats dissolve metal pipes instantly', false, '35f7ecb6-de2c-4faa-aa15-1a4d90aedb0e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d5ea002-5dbc-4fe2-baba-30adefe3b101', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Why should discarded chemical paints, solvents, motor oil, and expired medicines not be thrown into toilets or drains?', 'Toxic chemicals and pharmaceuticals poison the beneficial biocatalytic bacterial populations essential for biological sewage purification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bde53234-168a-460f-a854-2064b06c05ed', 'These toxic chemicals kill the beneficial microbes in wastewater treatment plants that naturally break down sewage waste', true, '6d5ea002-5dbc-4fe2-baba-30adefe3b101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0cfe4e3-ba3a-4486-af83-3e3fa35e281e', 'They cause water to turn into solid rock', false, '6d5ea002-5dbc-4fe2-baba-30adefe3b101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22aad5c9-4a3f-41b9-ae85-7766b4528ba3', 'They make water too clear to see', false, '6d5ea002-5dbc-4fe2-baba-30adefe3b101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc65fb4c-223e-4d49-9abe-d0975394bdb1', 'They freeze the sewer pipes', false, '6d5ea002-5dbc-4fe2-baba-30adefe3b101');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5db96386-3d9a-44d4-9b8c-4fdf0a8c6df8', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is a ''Septic Tank'' on-site sewage disposal system?', 'Septic tanks provide decentralized on-site anaerobic sewage digestion and effluent soil absorption for unsewered locations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b11d7536-92f6-4364-a6ef-934ac7a60be4', 'A watertight underground settling chamber where sewage decomposes anaerobically; suitable for isolated homes, rural hospitals, or clusters of houses without municipal sewer networks', true, '5db96386-3d9a-44d4-9b8c-4fdf0a8c6df8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e83ea93c-731d-4685-9e7d-65efee70998c', 'A large tank that stores clean rainwater', false, '5db96386-3d9a-44d4-9b8c-4fdf0a8c6df8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f5febcb-5af3-4d23-8df3-bc38d0543af4', 'A truck that transports bottled water', false, '5db96386-3d9a-44d4-9b8c-4fdf0a8c6df8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2528f1da-eb64-45b1-a1ab-41f0e146c6d1', 'A chemical factory making fertilizers', false, '5db96386-3d9a-44d4-9b8c-4fdf0a8c6df8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b83a97a-bfae-48c0-bb40-ee454a1ab3b6', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is the ''Vermi-Processing Toilet'' developed and tested successfully in India?', 'Vermi-toilets utilize earthworms to bioconvert human fecal sludge into odorless, pathogen-free, high-grade organic vermicompost.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f5169f9-186e-4e0b-96d5-29d5b40888da', 'A low-cost, hygienic, water-saving toilet system where earthworms (like red worms) completely process human excreta into high-nutrient vermicompost cakes', true, '3b83a97a-bfae-48c0-bb40-ee454a1ab3b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bc982d8-733a-4bf4-b239-aeeeec23c699', 'A toilet with electric heaters', false, '3b83a97a-bfae-48c0-bb40-ee454a1ab3b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('061840f0-e8a8-45f8-8dc0-cbef226284d4', 'A toilet connected to car engines', false, '3b83a97a-bfae-48c0-bb40-ee454a1ab3b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44129b3d-d4bc-487c-9c8e-528eacda55ee', 'A toilet that uses chemical gases', false, '3b83a97a-bfae-48c0-bb40-ee454a1ab3b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6b39d52-cae0-48d1-955f-b56038dfa482', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'How do forests influence the local atmospheric CLIMATE and the WATER CYCLE?', 'Evapotranspiration from forest canopies generates regional atmospheric moisture flux, lowering surface temperatures and promoting convective precipitation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8019778-b8ca-4348-ac3d-b6e5baf5c9f3', 'Forests transpire enormous volumes of water vapor into the air through their leaves, cooling the ambient climate, increasing atmospheric humidity, and inducing rainfall', true, 'a6b39d52-cae0-48d1-955f-b56038dfa482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d784ec78-4d3c-41f7-9d5a-ff20628afd32', 'Forests heat the air like stoves', false, 'a6b39d52-cae0-48d1-955f-b56038dfa482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('837a9583-1a0b-477f-8dcb-7e750a67d339', 'Forests absorb all clouds', false, 'a6b39d52-cae0-48d1-955f-b56038dfa482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('288a7379-99e4-4cc6-900f-c8f1b95df6aa', 'Forests stop winds from blowing', false, 'a6b39d52-cae0-48d1-955f-b56038dfa482');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75cc4832-163c-43b4-96d6-d14b0c2cbb60', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Consider a typical forest food chain: Grass → Insects → Frog → Snake → Eagle. What happens if all the FROGS are removed from this ecosystem?', 'Trophic cascade: removing intermediate secondary consumers (frogs) triggers pest outbreaks at lower levels and predator starvation at higher levels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67e74da2-95f2-4255-9428-cf8165629cd7', 'The population of insects will explode and damage vegetation, while snakes will face food scarcity and starve, destabilizing the food web', true, '75cc4832-163c-43b4-96d6-d14b0c2cbb60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddc6721a-73f8-4b62-b93b-405831726c8c', 'Eagles will start eating grass', false, '75cc4832-163c-43b4-96d6-d14b0c2cbb60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('161a617b-74c9-49d0-a9a0-0908dbf814f4', 'Nothing will change in the forest', false, '75cc4832-163c-43b4-96d6-d14b0c2cbb60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2cf89a8-a50e-4360-adf9-02caa2941467', 'Grass will stop growing', false, '75cc4832-163c-43b4-96d6-d14b0c2cbb60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a7ab673-6201-49f3-9396-67e373708d1f', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is ''Scum'' in a WWTP sedimentation clarifier tank?', 'Low-density floatable contaminants (fats, oils, grease) float to the surface as scum and are skimmed off mechanically.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a38f6ed6-9384-4498-9382-300c39514e92', 'Light, floatable impurities such as oils, grease, and fats that float on the water surface and are removed by a specialized mechanical skimmer', true, '4a7ab673-6201-49f3-9396-67e373708d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e73c8385-ac26-4bd4-ba45-a33532df04f3', 'Heavy rocks at the bottom', false, '4a7ab673-6201-49f3-9396-67e373708d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('899d36b2-a578-4da6-bd25-6d0595f7eb58', 'Air bubbles in the pipes', false, '4a7ab673-6201-49f3-9396-67e373708d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0db6f3a3-43d8-477e-a628-e42a992d29fd', 'Clean water flowing out', false, '4a7ab673-6201-49f3-9396-67e373708d1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9859ec42-27f5-4df8-975d-0b6c38d240f8', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is ''Grit and Sand Removal'' in a WWTP?', 'Velocity retardation in grit chambers causes dense mineral particles (sand, gravel) to precipitate out without settling organic matter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f122cd41-aba7-497b-a20f-a5253c9550b4', 'Wastewater passes through a tank at a reduced velocity so that heavy coarse sand, grit, and small pebbles settle down by gravity', true, '9859ec42-27f5-4df8-975d-0b6c38d240f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b1d3a00-7514-4a23-9a1a-3518d59d9901', 'Water is filtered through silk cloth', false, '9859ec42-27f5-4df8-975d-0b6c38d240f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48dc63c2-11b2-4874-abd6-6ef2676d633b', 'Water is spun in a centrifuge', false, '9859ec42-27f5-4df8-975d-0b6c38d240f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('867ada9b-a281-440a-bce7-ad1b3f2557b2', 'Sand is added to make water cleaner', false, '9859ec42-27f5-4df8-975d-0b6c38d240f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bc4fcdc-ff43-4888-8d31-6bcf19063e77', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Why does deforestation lead to severe SOIL EROSION and LAND DEGRADATION?', 'Arbor root networks anchor soil horizons; deforested slopes suffer catastrophic topsoil sheet wash, rill erosion, and desertification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96b33d9b-93d9-4233-8e94-f7b91aa1e572', 'Tree roots physically bind the soil together; in the absence of trees, heavy rain and wind wash away the fertile topsoil, turning fertile land into barren desert (desertification)', true, '1bc4fcdc-ff43-4888-8d31-6bcf19063e77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8985e6d7-91a7-4a38-8e19-1c95ea49c143', 'Because trees eat the soil', false, '1bc4fcdc-ff43-4888-8d31-6bcf19063e77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87dd64c6-062f-4406-bd01-450f0109e560', 'Because dead roots turn into water', false, '1bc4fcdc-ff43-4888-8d31-6bcf19063e77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a61d6b83-a1d6-4710-9083-99d8396ea289', 'Because wind cannot blow in forests', false, '1bc4fcdc-ff43-4888-8d31-6bcf19063e77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13481cea-0261-4f87-9de2-9a9ba5611ca7', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What deadly water-borne diseases are transmitted by untreated municipal sewage contaminating drinking water sources?', 'Untreated fecal wastewater contains microbial pathogens (Vibrio cholerae, Salmonella typhi, Entamoeba) that cause lethal diarrheal epidemics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a878fbca-4e19-415b-becc-1b89f2c0ac7c', 'Cholera, Typhoid, Dysentery, Hepatitis, and Polio', true, '13481cea-0261-4f87-9de2-9a9ba5611ca7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14df78ef-5c26-44da-b245-6240a78d2f31', 'Malaria and Dengue only', false, '13481cea-0261-4f87-9de2-9a9ba5611ca7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b9c46be-6b1f-4112-a6d2-0335dda09795', 'Asthma and Bronchitis', false, '13481cea-0261-4f87-9de2-9a9ba5611ca7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3b3c30f-d8f1-4e6a-be35-7895c78f278f', 'Diabetes and Hypertension', false, '13481cea-0261-4f87-9de2-9a9ba5611ca7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0a4822c-ce3c-4326-9b9a-0230eb5dd42f', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is ''Activated Sludge'' produced in the aeration tank of a WWTP?', 'Activated sludge is a living microbial floc of active aerobic decomposers that digest organic pollutants in aeration basins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f814533-82c2-4c4d-a65d-f34c271ebe01', 'A concentrated biological mass consisting of millions of active aerobic bacteria, protozoa, and suspended organic matter (~97% water)', true, 'e0a4822c-ce3c-4326-9b9a-0230eb5dd42f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('107f4bc4-04b3-4aaa-baf4-da4976329821', 'A radioactive sludge', false, 'e0a4822c-ce3c-4326-9b9a-0230eb5dd42f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aed02c30-de11-4835-bfa4-65025f0cd45f', 'Sludge mixed with gasoline', false, 'e0a4822c-ce3c-4326-9b9a-0230eb5dd42f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea24546d-2bea-465c-8bd0-b9c95e9fbc13', 'Solid plastic powder', false, 'e0a4822c-ce3c-4326-9b9a-0230eb5dd42f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a2fa70e-b2c3-4c1f-818d-1d8ab063663d', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is the primary role of forest tree canopy in regulating the impact of HEAVY MONSOON RAINS on soil?', 'Canopy interception dissipates the destructive kinetic energy of torrential rain, converting erosive downpours into gentle stemflow and leaf drip.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea9a72f0-d4fb-4cdd-b53e-21d0646db795', 'The multi-tiered canopy intercept the falling raindrops, breaking their kinetic velocity so that water drips gently down branches and trunks, preventing soil compaction', true, '9a2fa70e-b2c3-4c1f-818d-1d8ab063663d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68643f30-dbeb-484e-8e0c-2793c04da27d', 'It completely evaporates all rain before it reaches the ground', false, '9a2fa70e-b2c3-4c1f-818d-1d8ab063663d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7842e1b4-8003-41e1-a51a-3ac4c974121c', 'It turns rain into hail', false, '9a2fa70e-b2c3-4c1f-818d-1d8ab063663d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54619602-fffe-435b-9961-6adc001d7c55', 'It reflects rain back into clouds', false, '9a2fa70e-b2c3-4c1f-818d-1d8ab063663d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('605a2591-f7ba-4249-9caf-2f59bba91256', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is a ''Manhole'' in urban municipal sewerage systems?', 'Manholes provide vital physical maintenance entry points along subterranean sewer networks at standardized intervals and directional junctions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b75a542e-390b-436a-b806-76f8946d9d3a', 'An access opening located every 50 to 60 metres along sewer lines, at junctions and bends, allowing sanitary workers to inspect, clean, and unblock underground pipes', true, '605a2591-f7ba-4249-9caf-2f59bba91256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f89d8ea-0463-4b3b-bcaa-b5d277741751', 'A place to store drinking water', false, '605a2591-f7ba-4249-9caf-2f59bba91256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b80bc419-a077-4e8d-8688-2ab45832534a', 'A doorway into a subway train', false, '605a2591-f7ba-4249-9caf-2f59bba91256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f0241b7-6673-4c6c-b476-37265286f867', 'A trash bin on the street', false, '605a2591-f7ba-4249-9caf-2f59bba91256');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3ea5b35-1108-4614-8cbf-7e1fd4e6ef61', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('040d1387-b6c0-4560-a5c5-8ebd6ea140a9', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c3ea5b35-1108-4614-8cbf-7e1fd4e6ef61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8871c6d5-66c0-4f8b-9fd3-d0b3eba2bedc', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c3ea5b35-1108-4614-8cbf-7e1fd4e6ef61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7622bde2-eeb0-491d-945f-014ce5d9e741', '(A) is true, but (R) is false.', false, 'c3ea5b35-1108-4614-8cbf-7e1fd4e6ef61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa402144-7734-4487-a7c3-f81c11caa0f7', '(A) is false, but (R) is true.', false, 'c3ea5b35-1108-4614-8cbf-7e1fd4e6ef61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbca7e75-d955-49fa-a259-92501819c900', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Spot the IMPOSTER in the following sequence of Wastewater Treatment Plant (WWTP) unit operations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cc02a41-6cd3-438c-b108-0272ba86d1b7', 'Unit 1', false, 'dbca7e75-d955-49fa-a259-92501819c900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55a216ab-ab5b-484d-b615-9a21604dbac7', 'Unit 2', false, 'dbca7e75-d955-49fa-a259-92501819c900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('defe4bd9-b2e4-49c1-b910-d81b097c12c3', 'Unit 3', false, 'dbca7e75-d955-49fa-a259-92501819c900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9be2eaf9-ba28-446d-9c60-685aa1e82cdb', 'Unit 4 (WWTP processes involve physical clarification, biological digestion, and chemical disinfection; they NEVER add confectionery sugars or chocolate syrup)', true, 'dbca7e75-d955-49fa-a259-92501819c900');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9065eecb-3a65-4c73-9455-517d9c1c86e0', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Analyze the biological mechanism of ''Biochemical Oxygen Demand'' (BOD) in wastewater analysis:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('411f4ffd-75ce-428d-b128-72224623aa01', 'High BOD indicates a massive load of organic pollutants; as aerobic bacteria consume dissolved oxygen to decompose this waste, oxygen levels in the river plummet to near zero, causing catastrophic fish suffocations', true, '9065eecb-3a65-4c73-9455-517d9c1c86e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a5c175-edc8-4923-a87a-0de5dd38fb9c', 'High BOD turns water into acid that melts fish scales', false, '9065eecb-3a65-4c73-9455-517d9c1c86e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e598ea0-dbef-41c4-b7a7-de066b35999d', 'High BOD freezes the river solid', false, '9065eecb-3a65-4c73-9455-517d9c1c86e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08b7bfea-95af-4a0b-9cff-aca1093e156a', 'High BOD increases river water salinity to ocean levels', false, '9065eecb-3a65-4c73-9455-517d9c1c86e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a99268f6-0090-41d9-917f-78fce41b74bc', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Match Column I (WWTP Treatment Stages) with Column II (Primary Environmental Functions):
(a) Bar Screens         -> (i) Mechanical removal of coarse solid plastic/rag debris
(b) Aeration Basin      -> (ii) Aerobic microbiological oxidation of dissolved organic wastes
(c) Anaerobic Digester  -> (iii) Methanogenic fermentation of sludge producing combustible biogas
(d) UV / Chlorination   -> (iv) Pathogen disinfection and destruction of waterborne bacteria', 'Bar screens = coarse screening; Aeration = aerobic oxidation; Digester = biogas generation; Chlorination = pathogen disinfection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d141d05e-15aa-41ef-9c38-e0a1b3bf7926', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'a99268f6-0090-41d9-917f-78fce41b74bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cee60a68-8646-4ace-b74a-0bd6ee87d6ba', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'a99268f6-0090-41d9-917f-78fce41b74bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74c19080-a41d-42cc-a901-26fe4eed424d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'a99268f6-0090-41d9-917f-78fce41b74bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9c3bfe2-a0f3-4c1f-adfd-e02e987daaa9', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'a99268f6-0090-41d9-917f-78fce41b74bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41de2ed7-8316-489c-8f70-750c686cba92', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Read the statements regarding forest ecology:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4c172da-95df-49d5-8aa3-299eb67a3b47', 'Statements 1 and 2 only', true, '41de2ed7-8316-489c-8f70-750c686cba92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff99d1c1-06cd-48bf-9751-a49a685112b9', 'Statements 2 and 3 only', false, '41de2ed7-8316-489c-8f70-750c686cba92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fd68772-3049-4b49-a248-8029a25ed986', 'Statements 1 and 3 only', false, '41de2ed7-8316-489c-8f70-750c686cba92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a76f6ba-8a17-4cac-ad87-b87729733e9f', 'All Statements 1, 2, and 3', false, '41de2ed7-8316-489c-8f70-750c686cba92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3155d36f-5046-4399-ae32-c4731e5f620e', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'What is the biological role of ''Fungi and Micro-arthropods'' in the humification process on the forest floor?', 'Saprophytic fungi (white-rot, brown-rot) and soil micro-arthropods enzymatically cleave complex lignin/cellulose polymers into nutrient-rich humus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3f40cdb-0379-4d9c-9396-cfbf52a04e76', 'They secrete extracellular enzymes that digest recalcitrant plant polymers (lignin, cellulose), transforming leaf litter into stable, dark, mineral-rich colloidal humus', true, '3155d36f-5046-4399-ae32-c4731e5f620e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9699edd7-20ac-49be-a1fe-2ae565684c9c', 'They eat living tree trunks and kill the forest', false, '3155d36f-5046-4399-ae32-c4731e5f620e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48de399f-0b5e-4cef-b864-9014b2036cd3', 'They convert soil into solid glass', false, '3155d36f-5046-4399-ae32-c4731e5f620e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f872982b-8b39-4a04-a344-f64d55f07f29', 'They absorb all sunlight on the ground', false, '3155d36f-5046-4399-ae32-c4731e5f620e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43043eca-3087-4793-925d-a2caee3ea8cc', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'How do constructed wetland bio-filtration systems (like Phytoremediation reed beds) purify sewage water without electricity?', 'Phytoremediation leverages rhizosphere microbiology and macrophyte bio-accumulation to remediate wastewater naturally and passively.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b030e35b-a41a-49b7-8faa-90edf075aa97', 'Aquatic plants (like reeds and cattails) absorb heavy metals and excess nitrogen/phosphorus, while microbial biofilms around their root zones biologically degrade organic pollutants', true, '43043eca-3087-4793-925d-a2caee3ea8cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64e7156c-b8ca-4eff-9666-4f276595aa67', 'By boiling water using solar mirrors', false, '43043eca-3087-4793-925d-a2caee3ea8cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf3d35bd-db3b-4aa7-aecb-5f54f4939122', 'By adding chemical dyes that hide dirt', false, '43043eca-3087-4793-925d-a2caee3ea8cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('130d946f-bcd2-4aeb-8e57-48b3f768e18c', 'By freezing sewage into ice bricks', false, '43043eca-3087-4793-925d-a2caee3ea8cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fefea6b-dc64-49ed-bff0-71d5a6097f02', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Consider four environmental management practices:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aeb6b0b0-a98f-4bca-b6b7-e3bde6732bf3', 'Practices 1, 2, and 4 only', true, '2fefea6b-dc64-49ed-bff0-71d5a6097f02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cfbc96b-2ddd-40ce-a69c-802d2a134ada', 'Practice 3 only', false, '2fefea6b-dc64-49ed-bff0-71d5a6097f02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fba709a9-1080-4633-a381-9c4ff4980d4f', 'Practices 1 and 3 only', false, '2fefea6b-dc64-49ed-bff0-71d5a6097f02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad4e280c-f028-42aa-a7b6-55fcbade2f30', 'All 1, 2, 3, and 4', false, '2fefea6b-dc64-49ed-bff0-71d5a6097f02');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19e30a44-907a-4bf1-8873-0b28827cbc16', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Why does the presence of high levels of Coliform Bacteria (such as E. coli) in a river or well indicate severe water pollution?', 'Coliforms serve as universal microbiological fecal indicator organisms, demonstrating sewage contamination and the presence of enteric waterborne pathogens.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ec22aed-6b21-43be-a53c-4136dfdb9740', 'Coliform bacteria are natural inhabitants of the human and warm-blooded animal intestinal tract; their presence proves direct contamination by raw sewage and high risk of lethal enteric pathogens', true, '19e30a44-907a-4bf1-8873-0b28827cbc16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('079ec4d8-0f91-4368-97c6-210dea52afca', 'Because coliform bacteria eat fish', false, '19e30a44-907a-4bf1-8873-0b28827cbc16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6436bd32-1aa5-4240-8f2d-2fcda3e138c1', 'Because they produce poisonous radioactive gases', false, '19e30a44-907a-4bf1-8873-0b28827cbc16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4d3e2eb-b11d-4df0-a483-3333fbfca5df', 'Because they make water turn red', false, '19e30a44-907a-4bf1-8873-0b28827cbc16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af3b9b2c-3f43-4f84-97b0-c09f72d72b6b', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'What is the physical cause of ''Eutrophication'' in freshwater lakes receiving untreated domestic sewage and detergent runoff?', 'Nutrient hyper-enrichment (phosphates/nitrates) drives algal blooms whose subsequent decomposition induces severe lake hypolimnetic anoxia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('047f5859-07e4-4781-a6dd-a0f4138a45b8', 'Excessive nitrogen and phosphate nutrients trigger explosive algal blooms; when the algae die, decomposing bacteria consume all dissolved oxygen, suffocating aquatic animals', true, 'af3b9b2c-3f43-4f84-97b0-c09f72d72b6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('262bb944-ce10-4d2c-bf35-92b32b54e79e', 'The lake gets too cold to support fish', false, 'af3b9b2c-3f43-4f84-97b0-c09f72d72b6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad6d701f-4029-47be-9f54-25319e27ec22', 'Detergents turn water into solid jelly', false, 'af3b9b2c-3f43-4f84-97b0-c09f72d72b6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c145a076-cad3-42fc-a117-0db5e97317cd', 'Algae turn into large carnivorous plants', false, 'af3b9b2c-3f43-4f84-97b0-c09f72d72b6b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d11d66b2-7e9e-4298-967f-063bb120c268', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'How do deep-rooted forest trees prevent Hillside LANDSLIDES during torrential cloudbursts?', 'Arbor roots provide tensile soil reinforcement, increasing mechanical shear strength and relieving pore-water pressure that triggers slope failure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa3dc9e2-16bf-453e-9ea3-138cd2cb0559', 'The extensive taproot and lateral root networks act as bio-mechanical anchors, interlocking soil strata and bedrock, while continuous transpiration drains excess soil pore-water pressure', true, 'd11d66b2-7e9e-4298-967f-063bb120c268');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdc9f666-9cb7-4655-a3cf-3d4b55326a0c', 'Trees build stone walls with their branches', false, 'd11d66b2-7e9e-4298-967f-063bb120c268');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e6b06f1-87e5-457e-940e-d96b4196bb14', 'Trees absorb earthquakes', false, 'd11d66b2-7e9e-4298-967f-063bb120c268');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffa38463-7585-482a-aeb9-0d57517729c5', 'Trees freeze the mud', false, 'd11d66b2-7e9e-4298-967f-063bb120c268');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f00a797-e0b0-4c8e-819c-63d12a021df2', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'What supreme ecological synthesis concludes the NCERT Class 7 Science curriculum in Chapter 12?', 'Chapter 12 synthesizes forest conservation, hydrological cycles, ecological stewardship, and circular environmental engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed235c83-8dfc-4004-8170-0d63791d3be3', 'Human health, ecological balance, clean water, and planetary survival depend inextricably on conserving living forest biomes as our vital life-support systems and adopting responsible, closed-loop circular sanitation to keep our water bodies pure and vibrant', true, '6f00a797-e0b0-4c8e-819c-63d12a021df2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18103e71-f0d4-4dc1-8482-066f3789661f', 'That nature can be destroyed without consequences', false, '6f00a797-e0b0-4c8e-819c-63d12a021df2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f57443f4-c72f-4aba-944c-c278aa99d8f2', 'That wastewater treatment is unnecessary', false, '6f00a797-e0b0-4c8e-819c-63d12a021df2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51d6869a-7503-4f8e-b3d3-3ec14816b670', 'That technology will replace all natural forests', false, '6f00a797-e0b0-4c8e-819c-63d12a021df2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d36d162-abae-4ffe-bd82-73717eb7c1bc', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'A geometric line that divides a plane figure into two identical, matching halves such that one half completely folds over and covers the other is called a:', 'A line of symmetry is an axis of reflection that bisects a figure into two congruent, mirror-image halves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fceff2de-e23f-4707-97cc-6468ab094b79', 'Line of Symmetry (Axis of Symmetry)', true, '0d36d162-abae-4ffe-bd82-73717eb7c1bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('511986a6-34de-45b9-97c8-82038485682a', 'Diagonal only', false, '0d36d162-abae-4ffe-bd82-73717eb7c1bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19583ba9-4c6b-4dda-afcc-e75f303b3b55', 'Radius', false, '0d36d162-abae-4ffe-bd82-73717eb7c1bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89d0ad03-e24e-4e79-bcb6-a5689d3fe6dc', 'Perimeter line', false, '0d36d162-abae-4ffe-bd82-73717eb7c1bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2e9afe2-55d1-417d-bc26-091a56cb875f', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'How many lines of symmetry does an EQUILATERAL TRIANGLE have?', 'An equilateral triangle has 3 lines of symmetry passing through each vertex to the midpoint of the opposite side.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1820ea24-d9a0-4fc2-aefc-86e0f3653f1b', '3 Lines of Symmetry', true, 'a2e9afe2-55d1-417d-bc26-091a56cb875f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f159b72-cca9-4136-9e83-66e49e75818c', '1 Line', false, 'a2e9afe2-55d1-417d-bc26-091a56cb875f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72f2b103-a567-4a25-a212-cf70e60f1e02', '2 Lines', false, 'a2e9afe2-55d1-417d-bc26-091a56cb875f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f68350a-c30e-4bd9-9d49-ba677a3a463f', 'Infinite Lines', false, 'a2e9afe2-55d1-417d-bc26-091a56cb875f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c9233b8-1a40-452c-b4b6-acdccbdfc27d', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'How many lines of symmetry does a regular SQUARE have?', 'A square has 4 lines of symmetry: 2 vertical/horizontal medians and 2 diagonal lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c78a409-fa40-4e38-bc2b-83ec38d818fc', '4 Lines of Symmetry (2 through midpoints of opposite sides, 2 along diagonals)', true, '5c9233b8-1a40-452c-b4b6-acdccbdfc27d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6af37cd4-972f-40de-9e38-2d0a9bd321de', '2 Lines', false, '5c9233b8-1a40-452c-b4b6-acdccbdfc27d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e16be50e-2208-4515-9d60-56ce65e99155', '3 Lines', false, '5c9233b8-1a40-452c-b4b6-acdccbdfc27d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('881c7b4d-f85f-404b-851a-28cb709d0fc2', '8 Lines', false, '5c9233b8-1a40-452c-b4b6-acdccbdfc27d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('799610eb-88f7-4cfa-a40d-15df27db5eb8', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'How many lines of symmetry does a CIRCLE have?', 'A circle has an infinite number of lines of symmetry passing through its center along any diameter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6bd6988-601b-4e9f-8384-1e7ac7de6939', 'Infinitely Many Lines (any diameter is a line of symmetry)', true, '799610eb-88f7-4cfa-a40d-15df27db5eb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b8e5ef3-6b86-4788-ac66-4c2645a2c94a', '4 Lines', false, '799610eb-88f7-4cfa-a40d-15df27db5eb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbff89ec-1584-47b4-9efc-fdaf6c7168d5', '360 Lines', false, '799610eb-88f7-4cfa-a40d-15df27db5eb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e323bc35-b7e3-4333-876e-bdce71d119b8', '100 Lines', false, '799610eb-88f7-4cfa-a40d-15df27db5eb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('022eae9c-977d-487c-8c51-8aa46e652963', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is the smallest angle through which a figure is rotated around a central point to look EXACTLY THE SAME as its original position called?', 'The angle of rotation is the minimum angle of turn around the center of rotation that maps the figure onto itself.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6275cfad-1367-48ed-a6f4-f03e97fc4efd', 'Angle of Rotation', true, '022eae9c-977d-487c-8c51-8aa46e652963');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d2019c6-b74c-4fe4-8c44-82cae09decbc', 'Order of Symmetry', false, '022eae9c-977d-487c-8c51-8aa46e652963');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8576b442-2c9e-42bb-8a2a-d5beb13290e7', 'Reflective Angle', false, '022eae9c-977d-487c-8c51-8aa46e652963');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1bd0b47-fb03-4a96-825e-c9358adc3f0c', 'Supplementary Angle', false, '022eae9c-977d-487c-8c51-8aa46e652963');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f01fd2a8-e4d3-40b8-a8fa-af2d3825edd3', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is the ORDER OF ROTATIONAL SYMMETRY of a square in one complete 360° turn?', 'A square maps onto itself 4 times during a 360° rotation (every 90°), hence its rotational symmetry order is 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ae2a8ef-7dd1-4176-8f78-b39f1a3c38fd', 'Order 4 (at angles 90°, 180°, 270°, 360°)', true, 'f01fd2a8-e4d3-40b8-a8fa-af2d3825edd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1775c3d6-5211-452e-8131-c34af32a1cab', 'Order 2', false, 'f01fd2a8-e4d3-40b8-a8fa-af2d3825edd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42cd3bee-f2f0-4b4d-b476-091ee09bd1f8', 'Order 1', false, 'f01fd2a8-e4d3-40b8-a8fa-af2d3825edd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dba807d-f87e-4191-876d-5f9c42ea0ce4', 'Order 8', false, 'f01fd2a8-e4d3-40b8-a8fa-af2d3825edd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17d1ad07-3bd0-4153-ae9f-3a9d0f11a293', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is the ORDER OF ROTATIONAL SYMMETRY and ANGLE OF ROTATION of a RECTANGLE (non-square)?', 'A rectangle looks identical twice in a complete turn (at 180° and 360°), so order = 2 and angle of rotation = 180°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e77e1430-c49e-4066-96be-60ec59e76315', 'Order = 2 and Angle of Rotation = 180°', true, '17d1ad07-3bd0-4153-ae9f-3a9d0f11a293');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('311a33eb-e7e4-4cf3-9748-53f67c90bc87', 'Order = 4 and Angle = 90°', false, '17d1ad07-3bd0-4153-ae9f-3a9d0f11a293');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1043a082-83a2-42d7-9661-a0aa00acb22d', 'Order = 1 and Angle = 360°', false, '17d1ad07-3bd0-4153-ae9f-3a9d0f11a293');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7abd6255-4c6f-4347-bc54-08695e393123', 'Order = 3 and Angle = 120°', false, '17d1ad07-3bd0-4153-ae9f-3a9d0f11a293');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e472edfd-7b03-4e58-bc6b-eaf32241fc30', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'How many FACES (F), VERTICES (V), and EDGES (E) does a standard 3D CUBE have?', 'A cube has 6 square faces, 8 corner vertices, and 12 straight edges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a01e699-c632-438a-baaa-b2d9f011ba73', '6 Faces, 8 Vertices, 12 Edges', true, 'e472edfd-7b03-4e58-bc6b-eaf32241fc30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f48408aa-50a2-4bb3-ad5f-1932725ced89', '8 Faces, 6 Vertices, 12 Edges', false, 'e472edfd-7b03-4e58-bc6b-eaf32241fc30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64db424d-89ea-4247-82ed-1e7515ff46ab', '6 Faces, 12 Vertices, 8 Edges', false, 'e472edfd-7b03-4e58-bc6b-eaf32241fc30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8977492c-d192-4a7a-a88c-3bbaac0b37e8', '4 Faces, 4 Vertices, 6 Edges', false, 'e472edfd-7b03-4e58-bc6b-eaf32241fc30');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c76c0319-6183-446d-8272-41b95d609d90', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is EULER''S FORMULA relating Faces (F), Vertices (V), and Edges (E) for any convex polyhedron?', 'Euler''s Polyhedral Formula: F + V - E = 2 holds universally for all simple convex polyhedra.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2875d9e4-c8aa-4099-bf5f-8d1214f70945', 'F + V - E = 2 (or F + V = E + 2)', true, 'c76c0319-6183-446d-8272-41b95d609d90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a384ac1-8c4a-4812-bbd3-8b67a18284b4', 'F + E - V = 2', false, 'c76c0319-6183-446d-8272-41b95d609d90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42a6e188-46b2-4dde-ba23-9c6a457c4f63', 'F + V + E = 2', false, 'c76c0319-6183-446d-8272-41b95d609d90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d408d30b-feb6-47f5-9846-0936acaa6642', 'F × V = E + 2', false, 'c76c0319-6183-446d-8272-41b95d609d90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07f13a65-bb22-476a-ad7e-1dd1acf90f7b', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'A flat 2D skeletal pattern or layout that can be folded along its edges to construct a 3D solid shape is called a:', 'A net is a 2D planar unfolded diagram consisting of adjacent polygons that fold together to construct a 3D polyhedron.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9a09f3b-d415-429f-a0c7-601cf0842d9c', 'Net of the solid', true, '07f13a65-bb22-476a-ad7e-1dd1acf90f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd2be14f-2961-4c02-8ea9-f7bb241d40f1', 'Cross-section', false, '07f13a65-bb22-476a-ad7e-1dd1acf90f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20afc2b5-6cfa-4bfd-b5e6-e50e19a4c891', 'Isometric sheet', false, '07f13a65-bb22-476a-ad7e-1dd1acf90f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aec9c15-e973-485b-8702-cc52b071c19f', 'Oblique sketch', false, '07f13a65-bb22-476a-ad7e-1dd1acf90f7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14700de1-1bad-4383-a516-aef0ff3925d8', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is the cross-section obtained when a vertical cut (slicing) is made through an apple or a circular cylinder?', 'A horizontal cut through a cylinder gives a circle; cutting an apple transversely also yields a circular cross-section.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a09d14ed-4fe3-467c-93d8-aae06a32ee1b', 'A Circle', true, '14700de1-1bad-4383-a516-aef0ff3925d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('979ad95b-3696-40d8-a86f-01d835ce9383', 'A Triangle', false, '14700de1-1bad-4383-a516-aef0ff3925d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d00042ca-4a4e-4700-b495-470e858cad5e', 'A Square only', false, '14700de1-1bad-4383-a516-aef0ff3925d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bde353ff-d234-4181-9939-9b24cd82208e', 'A Hexagon', false, '14700de1-1bad-4383-a516-aef0ff3925d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b488e498-86af-4c78-afe4-ea5ce227ae7c', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'Which English capital letter has BOTH horizontal and vertical lines of symmetry as well as rotational symmetry of order 2?', 'Letter ''H'' possesses 2 lines of symmetry (horizontal and vertical) and rotational symmetry of order 2 (180°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fea6d7a-0800-49dd-bc9d-732072b4e4ed', 'H (and O, X, I)', true, 'b488e498-86af-4c78-afe4-ea5ce227ae7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('711ec937-9629-4179-ab17-9cdacbf2b728', 'A', false, 'b488e498-86af-4c78-afe4-ea5ce227ae7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a8bac17-0c18-4bda-aab0-bb0fb8e95d9c', 'B', false, 'b488e498-86af-4c78-afe4-ea5ce227ae7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1395cb7f-ac6b-44f1-95a8-e5ac0892b65c', 'C', false, 'b488e498-86af-4c78-afe4-ea5ce227ae7c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c08cf8fc-9ae0-4380-bb2d-429a220cb256', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'How many lines of symmetry does a REGULAR HEXAGON have, and what is its order of rotational symmetry?', 'A regular n-gon has n lines of symmetry and rotational symmetry of order n; for a regular hexagon, n = 6 (angle = 360°/6 = 60°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16bdf959-a9de-4739-b547-7d453ad17204', '6 Lines of Symmetry and Order of Rotational Symmetry = 6 (Angle of rotation = 60°)', true, 'c08cf8fc-9ae0-4380-bb2d-429a220cb256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7406cad7-4958-4c04-9d51-2c54e5b7186e', '4 Lines and Order 4', false, 'c08cf8fc-9ae0-4380-bb2d-429a220cb256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('857a37fa-f7f3-4260-a8e3-b2dff1d98dcf', '3 Lines and Order 3', false, 'c08cf8fc-9ae0-4380-bb2d-429a220cb256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1432a6ac-402a-4f1f-9d96-0af3f09a4646', '12 Lines and Order 12', false, 'c08cf8fc-9ae0-4380-bb2d-429a220cb256');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad08da16-12c0-4e36-bfb5-e01f23ceebf3', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Using Euler''s Formula (F + V - E = 2), find the number of EDGES (E) of a polyhedron having 8 faces and 12 vertices:', 'E = F + V - 2 = 8 + 12 - 2 = 18.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e59b0ee9-59fe-429b-94d7-a2bb26154e30', '18 Edges (F + V - E = 2 ⇒ 8 + 12 - E = 2 ⇒ 20 - E = 2 ⇒ E = 18)', true, 'ad08da16-12c0-4e36-bfb5-e01f23ceebf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26594491-b441-4286-95eb-b80cd5384995', '16 Edges', false, 'ad08da16-12c0-4e36-bfb5-e01f23ceebf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccf2201f-8117-4afa-851b-f21f7263af83', '20 Edges', false, 'ad08da16-12c0-4e36-bfb5-e01f23ceebf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('637ddd54-c1ea-465c-9588-f9d16e86c456', '14 Edges', false, 'ad08da16-12c0-4e36-bfb5-e01f23ceebf3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3556484e-3bd9-4536-9605-1f2773f0055d', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Using Euler''s Formula, find the number of VERTICES (V) of a polyhedron with 20 faces and 30 edges (an Icosahedron):', 'V = E + 2 - F = 30 + 2 - 20 = 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35abb20d-52b1-4362-a8e0-8825c31d4268', '12 Vertices (F + V - E = 2 ⇒ 20 + V - 30 = 2 ⇒ V - 10 = 2 ⇒ V = 12)', true, '3556484e-3bd9-4536-9605-1f2773f0055d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bab152b3-9343-43e2-bc16-f5c3c9472f9f', '10 Vertices', false, '3556484e-3bd9-4536-9605-1f2773f0055d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af2ae102-c673-4523-8fef-7a6f1dd15607', '14 Vertices', false, '3556484e-3bd9-4536-9605-1f2773f0055d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aff251e5-b598-443d-876f-10c0d35711dc', '16 Vertices', false, '3556484e-3bd9-4536-9605-1f2773f0055d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aad1a879-2235-4e27-925c-8783df0e73e7', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'How many FACES, VERTICES, and EDGES does a TRIANGULAR PRISM have?', 'A triangular prism has 5 faces, 6 vertices, and 9 edges, satisfying Euler''s formula (5 + 6 - 9 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4da25e94-7678-4702-8a39-1741aadc6067', '5 Faces (2 triangular bases + 3 rectangular side faces), 6 Vertices, 9 Edges (Check: 5 + 6 - 9 = 2)', true, 'aad1a879-2235-4e27-925c-8783df0e73e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb45dd60-d5fe-44de-b4ce-2795b0c8b7f6', '6 Faces, 8 Vertices, 12 Edges', false, 'aad1a879-2235-4e27-925c-8783df0e73e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee3f397d-1a84-48a7-a74d-66d302803255', '4 Faces, 4 Vertices, 6 Edges', false, 'aad1a879-2235-4e27-925c-8783df0e73e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32d551c0-cf30-4197-8480-598f9a26bcc9', '5 Faces, 5 Vertices, 8 Edges', false, 'aad1a879-2235-4e27-925c-8783df0e73e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88b69f81-a312-4966-aab7-23dcc5ad5d29', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'How many FACES, VERTICES, and EDGES does a SQUARE PYRAMID have?', 'A square pyramid has 5 faces (1 base + 4 triangular sides), 5 vertices (4 base + 1 apex), and 8 edges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b09693f7-74d9-4102-8570-bfc12bfa9910', '5 Faces (1 square base + 4 triangular faces), 5 Vertices, 8 Edges (Check: 5 + 5 - 8 = 2)', true, '88b69f81-a312-4966-aab7-23dcc5ad5d29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97c0be2b-20ab-4bd3-973e-8ddcd417e05f', '4 Faces, 4 Vertices, 6 Edges', false, '88b69f81-a312-4966-aab7-23dcc5ad5d29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63abdaa7-7c25-4e9f-88a4-f3abfa37e6d3', '6 Faces, 6 Vertices, 10 Edges', false, '88b69f81-a312-4966-aab7-23dcc5ad5d29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10795285-b47e-4fb3-8f95-f7e8244915f2', '5 Faces, 6 Vertices, 9 Edges', false, '88b69f81-a312-4966-aab7-23dcc5ad5d29');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87206608-447e-4171-b67d-4b610c5d2257', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What is the difference between an OBLIQUE SKETCH and an ISOMETRIC SKETCH of a 3D solid?', 'Isometric projections use a 30° equilateral triangular dot grid preserving scale proportions along axes, unlike oblique pictorial sketches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('906e53d5-69f1-40a4-9451-4b4064e67a73', 'An oblique sketch does not preserve exact proportional dimensions of receding depths ; an isometric sketch is drawn on an isometric dot grid where exact scaled measurements are preserved', true, '87206608-447e-4171-b67d-4b610c5d2257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d8734fa-9136-42ad-9fe7-6a39902d9259', 'Oblique sketches are drawn with circles only', false, '87206608-447e-4171-b67d-4b610c5d2257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcf86c5b-8dd0-456d-a7fb-9b1fee63775c', 'Isometric sketches are drawn without rulers', false, '87206608-447e-4171-b67d-4b610c5d2257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cb223ea-eb3b-43db-89ec-5ef6fe81b37b', 'There is no mathematical difference', false, '87206608-447e-4171-b67d-4b610c5d2257');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('620541ea-b1ef-4901-88a9-2ee4adc0879e', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'On a standard playing DIE (Dice), the sum of the numbers of dots on opposite faces is ALWAYS equal to:', 'Standard dice convention: opposite faces always sum to 7 (1+6=7, 2+5=7, 3+4=7).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1eec4bfc-b734-48a7-a72c-f88884d97303', '7 (1 opposite 6, 2 opposite 5, 3 opposite 4)', true, '620541ea-b1ef-4901-88a9-2ee4adc0879e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e51bf4be-e133-4426-aefb-5115097fcade', '6', false, '620541ea-b1ef-4901-88a9-2ee4adc0879e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f1b6770-27b9-4f58-85c6-db9d8aca498c', '8', false, '620541ea-b1ef-4901-88a9-2ee4adc0879e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2442fa78-53fe-421c-bdf3-e9b89034aa58', '10', false, '620541ea-b1ef-4901-88a9-2ee4adc0879e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f97722a1-a593-4472-b499-35bf458da18d', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What is the cross-section shape obtained when you make a VERTICAL SLICE through a solid Brick (Cuboid)?', 'A vertical or horizontal planar slice through a cuboid always yields a rectangular (or square) cross-section.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7102103-6d3a-4493-8dd9-5ae21517e20d', 'A Rectangle (or Square depending on cut)', true, 'f97722a1-a593-4472-b499-35bf458da18d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e8a9b66-e5f6-49f7-936d-c2958caf62e8', 'A Circle', false, 'f97722a1-a593-4472-b499-35bf458da18d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ee0e645-b984-4c26-a6a9-dfe8da49bd9e', 'A Triangle', false, 'f97722a1-a593-4472-b499-35bf458da18d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0cda2d3-473a-4816-b3e2-94dff08ad095', 'A Pentagon', false, 'f97722a1-a593-4472-b499-35bf458da18d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('089c8327-963e-4857-bdcd-bdba24407c18', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What is the cross-section obtained when you make a VERTICAL SLICE through the apex of a solid CONE?', 'A vertical axial cross-section passing through the apex of a right circular cone produces an isosceles triangle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('238211f1-3ea5-436b-a328-4bf9393171fa', 'An Isosceles Triangle', true, '089c8327-963e-4857-bdcd-bdba24407c18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c00d0199-501a-4471-9078-67113e180511', 'A Circle', false, '089c8327-963e-4857-bdcd-bdba24407c18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d0c5279-0790-4c83-8609-5b238e50bffc', 'A Rectangle', false, '089c8327-963e-4857-bdcd-bdba24407c18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94b12c4a-ef46-4dfd-93ba-53bb843c3128', 'An Oval', false, '089c8327-963e-4857-bdcd-bdba24407c18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6de4ce67-6445-4091-b9ca-ac3f7ea90d76', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Which of the following geometric figures has ONLY Rotational Symmetry of Order > 1 but NO Line of Symmetry?', 'A standard non-rhombic parallelogram has rotational symmetry of order 2 (180°), but zero reflectional lines of symmetry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdb2db8e-88a4-4a28-830d-fafaf0aa4651', 'A Parallelogram (Rotational symmetry of order 2, but 0 lines of symmetry)', true, '6de4ce67-6445-4091-b9ca-ac3f7ea90d76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cb1210a-1185-4265-baec-16f18066941d', 'A Square', false, '6de4ce67-6445-4091-b9ca-ac3f7ea90d76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b44ed82f-324c-40f9-bd0c-00a51e06b366', 'An Equilateral Triangle', false, '6de4ce67-6445-4091-b9ca-ac3f7ea90d76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d362d011-3d27-4529-b5cc-702a120d7b02', 'A Regular Pentagon', false, '6de4ce67-6445-4091-b9ca-ac3f7ea90d76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('382386a2-9de6-42fd-9b25-154bee94d020', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What is the order of rotational symmetry of a regular PENTAGON?', 'A regular pentagon has order 5 and angle of rotation = 360°/5 = 72°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d91a4b1-a82b-45a6-92da-18bd66d994d9', 'Order = 5 and Angle of rotation = 72° (360° / 5 = 72°)', true, '382386a2-9de6-42fd-9b25-154bee94d020');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d7ea710-1bd2-4af8-a65e-36db4c5747d1', 'Order = 5 and Angle = 60°', false, '382386a2-9de6-42fd-9b25-154bee94d020');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90740c9e-7f9e-4c62-b585-9c38b60c7ab8', 'Order = 10 and Angle = 36°', false, '382386a2-9de6-42fd-9b25-154bee94d020');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3946150-91b7-4dd7-9e02-33510fb1cd0c', 'Order = 3 and Angle = 120°', false, '382386a2-9de6-42fd-9b25-154bee94d020');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62a4821b-d927-48f7-86c5-38b6d32a611b', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Three cubes each of edge 2 cm are placed side-by-side to form a single CUBOID. What are the dimensions (length, breadth, height) of the resulting cuboid?', 'Placing 3 identical cubes of side 2 cm linearly results in a cuboid of dimensions 6 cm × 2 cm × 2 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed8e8a8d-b174-4373-951d-e2831052234f', 'Length = 6 cm, Breadth = 2 cm, Height = 2 cm (Length = 2 + 2 + 2 = 6 cm)', true, '62a4821b-d927-48f7-86c5-38b6d32a611b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8b074f7-9148-463e-9e14-f97b1e451bc0', 'Length = 2 cm, Breadth = 2 cm, Height = 2 cm', false, '62a4821b-d927-48f7-86c5-38b6d32a611b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aea99505-1d9a-4cb5-b8d9-09fbb6adf889', 'Length = 6 cm, Breadth = 6 cm, Height = 6 cm', false, '62a4821b-d927-48f7-86c5-38b6d32a611b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17c80c88-8a43-4a7e-9b4a-88586f7245b7', 'Length = 8 cm, Breadth = 2 cm, Height = 2 cm', false, '62a4821b-d927-48f7-86c5-38b6d32a611b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4cda848-b421-4bf9-944a-c256425446ad', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Can a polyhedron have 10 faces, 20 edges, and 15 vertices?', 'By Euler''s formula, F + V - E must equal 2. Here 10 + 15 - 20 = 5 ≠ 2, so no such polyhedron can exist.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a0e77e-c81b-4fe4-a0a9-edbe28cfa72c', 'YES, it satisfies Euler''s formula: F + V - E = 10 + 15 - 20 = 25 - 20 = 5 ≠ 2 ... Wait! 10 + 15 - 20 = 5 ≠ 2 ; Therefore, NO, such a polyhedron CANNOT exist', false, 'c4cda848-b421-4bf9-944a-c256425446ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('852b33f7-966a-4e19-9eae-1b66a7ed73f8', 'NO, because F + V - E = 10 + 15 - 20 = 5 ≠ 2 (violating Euler''s formula)', true, 'c4cda848-b421-4bf9-944a-c256425446ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ae504f2-bf98-43dc-b252-462ed1354c10', 'YES, it is a pyramid', false, 'c4cda848-b421-4bf9-944a-c256425446ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca05b42c-99e5-4810-877b-adfbfe89fe15', 'YES, it is a prism', false, 'c4cda848-b421-4bf9-944a-c256425446ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9dce0f3d-4d09-4488-aec9-4c35d7fd1a7d', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What solid shape is generated when a right-angled triangular sheet is rotated rapidly around one of its perpendicular sides as the axis?', 'Rotating a right-angled triangle around its altitude sweeps out a 3D right circular cone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04b7fe91-f45e-4a13-a95c-40d79aa2b2a6', 'A Right Circular Cone', true, '9dce0f3d-4d09-4488-aec9-4c35d7fd1a7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c55de90a-4a30-41fb-806d-12a67b3b6ea6', 'A Cylinder', false, '9dce0f3d-4d09-4488-aec9-4c35d7fd1a7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e84f19bd-fd12-4571-afae-76d76ab547f1', 'A Sphere', false, '9dce0f3d-4d09-4488-aec9-4c35d7fd1a7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcb0a590-e27d-4733-a0c6-9074d65825c7', 'A Prism', false, '9dce0f3d-4d09-4488-aec9-4c35d7fd1a7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9d71f09-ecce-45d3-bb5d-8298a5a22834', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What solid shape is generated when a flat rectangular sheet is rotated rapidly around one of its sides?', 'Rotating a rectangle around one edge generates a 3D circular cylinder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e66a0f9-64ef-4df5-b9a5-b03a6a7bda31', 'A Cylinder', true, 'a9d71f09-ecce-45d3-bb5d-8298a5a22834');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0fd1321-93df-42d8-a801-c08eb46494ce', 'A Cone', false, 'a9d71f09-ecce-45d3-bb5d-8298a5a22834');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f28a5cf-1aea-47de-aa6e-211f52c114e5', 'A Sphere', false, 'a9d71f09-ecce-45d3-bb5d-8298a5a22834');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ecc547d-df0d-4fcb-96d7-f16d5f909090', 'A Pyramid', false, 'a9d71f09-ecce-45d3-bb5d-8298a5a22834');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('735937cf-99f6-4bf9-883e-562a94aa980e', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'How many lines of symmetry does a RHOMBUS have?', 'A non-square rhombus has exactly 2 lines of symmetry coinciding with its perpendicular diagonals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ac51982-8049-4524-988b-43c703dd2034', '2 Lines of Symmetry (along its two diagonals)', true, '735937cf-99f6-4bf9-883e-562a94aa980e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ee6464a-a215-4fd0-82dc-144ee951a66d', '4 Lines', false, '735937cf-99f6-4bf9-883e-562a94aa980e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a60c8889-e961-48f2-9ed7-b8784e76e37c', '1 Line', false, '735937cf-99f6-4bf9-883e-562a94aa980e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1ec6bc7-9582-4375-af6e-06ed2b0a7e9f', '0 Lines', false, '735937cf-99f6-4bf9-883e-562a94aa980e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('569f3497-3277-4bfe-969f-f8a1462cde01', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919b785a-947a-48db-8f1b-722b7a4dbb8e', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '569f3497-3277-4bfe-969f-f8a1462cde01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a808924-2ac8-4fdb-8725-228aafd1d179', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '569f3497-3277-4bfe-969f-f8a1462cde01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c524a25-512b-4f23-b702-db1c82704bc4', '(A) is true, but (R) is false.', false, '569f3497-3277-4bfe-969f-f8a1462cde01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eeff9d5-0353-4cf9-9f10-41bac06f1407', '(A) is false, but (R) is true.', false, '569f3497-3277-4bfe-969f-f8a1462cde01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f77772c-0a82-4634-9b2b-1fc4d95db6fb', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Spot the IMPOSTER in the following polyhedra and their Euler characteristic components (F, V, E):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('252c79fa-60eb-4839-ac5a-e3276aad565a', 'Polyhedron 1', false, '8f77772c-0a82-4634-9b2b-1fc4d95db6fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8525d92c-6447-4963-875e-ae8aa296606d', 'Polyhedron 2', false, '8f77772c-0a82-4634-9b2b-1fc4d95db6fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8deed6f7-645b-4d6d-a6de-9d4d1b812607', 'Polyhedron 3', false, '8f77772c-0a82-4634-9b2b-1fc4d95db6fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f0772af-aa42-4941-8848-4c55193246b0', 'Polyhedron 4 (Polyhedron 4 violates Euler''s Theorem F + V - E = 2; a solid with 4 vertices and 4 faces is a Tetrahedron with E = 6, NOT E = 20)', true, '8f77772c-0a82-4634-9b2b-1fc4d95db6fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f7b01fc-0993-4516-8381-1bd1c690f697', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'A net for a dice cube has numbers marked on its 6 square faces. If face 1 is opposite face ''x'', face 2 is opposite face ''y'', and face 3 is opposite face ''z'' on a standard die, find the value of (x + y - z):', 'x = 6, y = 5, z = 4. Calculation: 6 + 5 - 4 = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f7963b3-c177-47bb-94bc-e72332c4bcd7', '7 (Since opposite faces sum to 7: x = 7 - 1 = 6 ; y = 7 - 2 = 5 ; z = 7 - 3 = 4 ; Value = 6 + 5 - 4 = 11 - 4 = 7)', true, '0f7b01fc-0993-4516-8381-1bd1c690f697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d4c24db-506d-4a80-9c9a-9182f4ad9d74', '5', false, '0f7b01fc-0993-4516-8381-1bd1c690f697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92e42809-1698-4aee-94ed-5a97add59496', '9', false, '0f7b01fc-0993-4516-8381-1bd1c690f697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d52756ef-bf24-4797-be2a-f90ab1cc1e50', '11', false, '0f7b01fc-0993-4516-8381-1bd1c690f697');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fef790a-b481-43ca-b41b-5110b6852af0', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Match Column I (Geometric Figures) with Column II (Order of Rotational Symmetry & Line Symmetry):
(a) Equilateral Triangle -> (i) 3 Lines of symmetry & Rotational Order 3 (120°)
(b) Regular Hexagon      -> (ii) 6 Lines of symmetry & Rotational Order 6 (60°)
(c) Parallelogram        -> (iii) 0 Lines of symmetry & Rotational Order 2 (180°)
(d) Scalene Triangle     -> (iv) 0 Lines of symmetry & Rotational Order 1 (360° only)', 'Equilateral triangle = 3 & 3; Hexagon = 6 & 6; Parallelogram = 0 & 2; Scalene = 0 & 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2dfc8ac-b9a6-4768-95ee-f5a8600da883', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '0fef790a-b481-43ca-b41b-5110b6852af0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d7b3ff5-5950-4238-8e2f-d66e70491408', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '0fef790a-b481-43ca-b41b-5110b6852af0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e94d195-08d0-40a5-ab5c-18ff0e57229f', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '0fef790a-b481-43ca-b41b-5110b6852af0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6af49fb-7560-4eed-9994-6e3934468ce9', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '0fef790a-b481-43ca-b41b-5110b6852af0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af6c0e31-a696-4a3c-932a-1acec0daa669', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Read the statements regarding 3D projections:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff6c939d-8a79-4cab-b544-8e6006135f23', 'Statements 1 and 2 only', true, 'af6c0e31-a696-4a3c-932a-1acec0daa669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db8e7fd4-4c0c-4e5f-85af-3e09eeead2fa', 'Statements 2 and 3 only', false, 'af6c0e31-a696-4a3c-932a-1acec0daa669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eac74898-9353-4531-9d19-a75b0099ab60', 'Statements 1 and 3 only', false, 'af6c0e31-a696-4a3c-932a-1acec0daa669');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a386e39-b9f5-44c7-a64f-a9cae6c87aa4', 'All Statements 1, 2, and 3', false, 'af6c0e31-a696-4a3c-932a-1acec0daa669');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('031dd73a-45d5-432a-9a58-d340ba20ce3f', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'A solid geometric shape has 1 curved face and 2 flat circular planar faces. What is the solid shape, and what is its horizontal cross-section?', 'A cylinder has 2 circular flat bases and 1 curved lateral surface; horizontal cuts parallel to bases yield circular cross-sections.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d153008-d197-4a75-a148-14299e236c54', 'A Cylinder ; its horizontal cross-section is a Circle', true, '031dd73a-45d5-432a-9a58-d340ba20ce3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32efda2b-180a-4074-9651-0d3998c859f4', 'A Cone ; its cross-section is a square', false, '031dd73a-45d5-432a-9a58-d340ba20ce3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcb31dde-3cf0-43ee-8881-76c1d91d6f0d', 'A Sphere ; its cross-section is a triangle', false, '031dd73a-45d5-432a-9a58-d340ba20ce3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b0bec93-18d1-404b-ab38-d0186000bbb1', 'A Prism ; its cross-section is a rectangle', false, '031dd73a-45d5-432a-9a58-d340ba20ce3f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb69dde7-aa30-4e9c-824b-e71be15ad514', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'If a regular polygon has an angle of rotational symmetry equal to 45°, how many sides does the polygon have, and how many lines of symmetry does it possess?', 'n = 360° / 45° = 8 (regular octagon), which has 8 lines of symmetry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1301291-270f-4787-a682-3dc92959f91a', '8 sides (Octagon) and 8 lines of symmetry (Number of sides n = 360° / 45° = 8)', true, 'bb69dde7-aa30-4e9c-824b-e71be15ad514');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99c4a20d-c77d-49ce-8461-0a8509e65afa', '6 sides and 6 lines', false, 'bb69dde7-aa30-4e9c-824b-e71be15ad514');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09914cf3-d9bc-458b-8ecb-39edfd7e0538', '10 sides and 10 lines', false, 'bb69dde7-aa30-4e9c-824b-e71be15ad514');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('900f3b53-0af9-4144-9667-0f5ecab9802c', '12 sides and 12 lines', false, 'bb69dde7-aa30-4e9c-824b-e71be15ad514');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17466c40-a7f7-4dd9-9462-79fdf50e98d4', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Consider four geometric 3D shapes:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de0d2c0f-16b4-4cc1-862c-3d39fc531b38', 'Cuts 1, 2, and 3 only', true, '17466c40-a7f7-4dd9-9462-79fdf50e98d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e7d717f-a5e8-4ffd-a7e9-f8a312c9b6a7', 'Cut 4 only', false, '17466c40-a7f7-4dd9-9462-79fdf50e98d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3576886c-cd90-496e-8476-cf950fc58682', 'Cuts 2 and 4 only', false, '17466c40-a7f7-4dd9-9462-79fdf50e98d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('316d4cd0-db63-459d-84ac-a087dc794dc6', 'All 1, 2, 3, and 4', false, '17466c40-a7f7-4dd9-9462-79fdf50e98d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5adfd1a-563e-4257-991b-4e56e1b7e211', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'How many unit cubes (1 cm × 1 cm × 1 cm) are required to build a solid hollow cubical box of outer dimension 4 cm × 4 cm × 4 cm with walls 1 cm thick?', 'Outer volume = 4³ = 64. Inner void = (4-2)³ = 2³ = 8. Required unit cubes = 64 - 8 = 56.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18318e23-fcb8-44c7-97b1-d4511b8b6fe5', '56 unit cubes (Total outer volume = 4³ = 64 cm³ ; Inner hollow volume = 2³ = 8 cm³ ; Required cubes = 64 - 8 = 56 cubes)', true, 'a5adfd1a-563e-4257-991b-4e56e1b7e211');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0339fbb3-51de-49bf-a8ab-b04d31098cf2', '64 cubes', false, 'a5adfd1a-563e-4257-991b-4e56e1b7e211');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6b8c4ca-203c-4379-a6c3-4786c0b7efec', '48 cubes', false, 'a5adfd1a-563e-4257-991b-4e56e1b7e211');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c00a2a8a-4520-449e-9654-4de7d303f5e5', '52 cubes', false, 'a5adfd1a-563e-4257-991b-4e56e1b7e211');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7aa5852d-9807-45c4-b786-8ca82c466d2d', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'What is the maximum number of acute angles a convex polyhedron''s polygonal face can have in 3D Euclidean geometry?', 'A polygon can have at most 3 acute interior angles regardless of the number of sides (as exterior angles would otherwise exceed 360°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16442cac-9dac-408b-b7df-23ce165605d2', '3 acute angles (in a triangle)', true, '7aa5852d-9807-45c4-b786-8ca82c466d2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08e9ef84-a487-4d4c-8481-d7902bdb37cb', '4', false, '7aa5852d-9807-45c4-b786-8ca82c466d2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('349dffc3-92e7-49e7-a1a0-a42fd51cdf77', '5', false, '7aa5852d-9807-45c4-b786-8ca82c466d2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc6fb42-1a39-4b76-aca7-f8dc19b3ff31', 'Infinite', false, '7aa5852d-9807-45c4-b786-8ca82c466d2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('536c9ed0-b3a5-4e8c-bbfe-6433b79a130e', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Why can a solid polyhedron NEVER have only 7 edges?', 'Every polyhedron face has ≥ 3 edges (2E ≥ 3F) and each vertex has degree ≥ 3 (2E ≥ 3V). No polyhedron can have E = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01fcaf3-3a65-4047-8f60-0873dd4c9707', 'By Euler''s formula and face-edge degree bounds (2E ≥ 3F and 2E ≥ 3V), for E = 7, F + V = 9; combining bounds yields 3(F + V) = 27 ≤ 4E = 28, which admits no integer solution for planar polygonal faces', true, '536c9ed0-b3a5-4e8c-bbfe-6433b79a130e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92a5d1be-c9d7-4ffe-877f-042155c167b8', 'Because 7 is an odd number', false, '536c9ed0-b3a5-4e8c-bbfe-6433b79a130e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad450b0a-9bca-4fa8-9243-89ce594ef0fc', 'Because polyhedra must have even number of faces only', false, '536c9ed0-b3a5-4e8c-bbfe-6433b79a130e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('983dd299-6d60-4f7c-a689-4a147872b882', 'Because edges must be multiples of 4', false, '536c9ed0-b3a5-4e8c-bbfe-6433b79a130e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ed231e5-82d3-44f5-b877-eb9ffc48c8c9', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'What grand spatial and geometric unification concludes the NCERT Class 7 Mathematics curriculum in Chapter 12?', 'Chapter 12 establishes spatial reasoning: reflectional/rotational invariance, polyhedral topology (Euler''s characteristic), and isometric projection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0c07c2d-bb56-400a-81bb-a35978b81a40', 'Geometric symmetry and spatial 3D visualization unite reflectional invariants, rotational group orders, topological polyhedral networks (Euler''s formula), and 2D-to-3D projection mappings—forming the bedrock of modern architecture, computer graphics, CAD engineering, and crystallographic science', true, '1ed231e5-82d3-44f5-b877-eb9ffc48c8c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e03d6cf-60ef-4cda-b933-55e1e4e91f71', 'That geometry is only useful for drawing paper shapes', false, '1ed231e5-82d3-44f5-b877-eb9ffc48c8c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3778a7c1-e996-4357-916d-b9f6de65fbf7', 'That 3D solids cannot be drawn on 2D paper', false, '1ed231e5-82d3-44f5-b877-eb9ffc48c8c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52322402-9da5-4589-8c26-1f01f747050c', 'That symmetry exists only in circles', false, '1ed231e5-82d3-44f5-b877-eb9ffc48c8c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ea51a99-08c8-4a40-aeb3-ce2654534939', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'In Leo Tolstoy''s opening parable ''Three Questions'' in Honeycomb, what three essential questions did the King seek answers to?', 'The King sought wisdom on the right time to act, the most important people to trust, and the supreme duty to perform.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('846b3ec6-85a0-497c-829c-f278aa8f8bae', '1. What was the right time to begin everything? 2. Which people should he listen to? 3. What was the most important thing for him to do?', true, '6ea51a99-08c8-4a40-aeb3-ce2654534939');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a94fc985-8fed-4b50-bc74-a949b550474d', 'How to win wars, where to find gold, and how to live forever', false, '6ea51a99-08c8-4a40-aeb3-ce2654534939');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e31fe8e-5b08-4696-a10b-e1aaa30b34cf', 'When to eat, where to sleep, and who to appoint as minister', false, '6ea51a99-08c8-4a40-aeb3-ce2654534939');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4249d55-6538-400c-be97-a8dbac62e288', 'How to build castles, buy horses, and rule kingdoms', false, '6ea51a99-08c8-4a40-aeb3-ce2654534939');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('684219df-77d6-4148-9729-0c86b9405dfd', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'In ''The Gift of Chappals'', what selfless act of kindness do the children (Ravi, Meena, and Mridu) perform for the blistered beggar?', 'Moved by compassion for the beggar''s blistered bare feet, the children spontaneously gift him the music teacher''s chappals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e82820b8-06a3-40f6-834c-818505988901', 'They give him the music-master''s comfortable old leather chappals (slippers) because the beggar''s bare feet were scorched and blistered by the burning road', true, '684219df-77d6-4148-9729-0c86b9405dfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f9c1857-e356-4ab1-829f-7232e0acb2c2', 'They give him gold coins', false, '684219df-77d6-4148-9729-0c86b9405dfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82291b8a-91cf-434d-b0fd-72c78a1b0ff4', 'They buy him a new car', false, '684219df-77d6-4148-9729-0c86b9405dfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f0806e4-1dff-44e1-9f17-4d79d36526b9', 'They invite him to live in their palace', false, '684219df-77d6-4148-9729-0c86b9405dfd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bae0b59-fb7a-4793-8cf2-9a840f7b2b10', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'In John Galsworthy''s moving short story ''Quality'', what craft did the noble German bootmaker Mr. Gessler dedicate his entire life to?', 'Mr. Gessler was a master craftsman who chose slow, artisanal perfection in bootmaking over cheap mass-produced commercialism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d07b5339-52ad-4e1b-8290-5855b140f916', 'Handmade bespoke leather boots of supreme craftsmanship and extraordinary durability', true, '1bae0b59-fb7a-4793-8cf2-9a840f7b2b10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8839c7d5-f9ae-472c-a248-6f193bd360bd', 'Tailoring royal woolen coats', false, '1bae0b59-fb7a-4793-8cf2-9a840f7b2b10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bb48124-d69f-43d0-88d7-35287453dc60', 'Making wooden furniture', false, '1bae0b59-fb7a-4793-8cf2-9a840f7b2b10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56bb03e2-2106-4e9e-9556-cea6011c6267', 'Painting oil portraits', false, '1bae0b59-fb7a-4793-8cf2-9a840f7b2b10');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96d4e577-2a7b-4fc2-ad6e-9dcbede6c206', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'What is the supreme moral conclusion delivered by the wise Hermit in ''Three Questions''?', 'The Hermit teaches: the only important time is ''Now'' (the present moment), our companions are our immediate priority, and doing good is our supreme purpose.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('208ce8b3-5654-489b-bac3-99e0bcfa8b53', 'The most important time is NOW (the present); the most important person is the one you are with; and the most important business is to DO GOOD to that person', true, '96d4e577-2a7b-4fc2-ad6e-9dcbede6c206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f49b04f-6797-467a-82b6-e3de153eea89', 'Wealth is the only goal in life', false, '96d4e577-2a7b-4fc2-ad6e-9dcbede6c206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e7a131e-248c-4766-95c5-14ee9567947f', 'Past actions determine everything', false, '96d4e577-2a7b-4fc2-ad6e-9dcbede6c206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41aca3c7-17af-4640-807b-cab47f10fe9b', 'Kings should never help strangers', false, '96d4e577-2a7b-4fc2-ad6e-9dcbede6c206');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c2f3641-4085-47c3-9d57-daa6cadd8800', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Identify the part of speech of the underlined word in: ''She sang **sweetly** during the concert.''', '''Sweetly'' is an adverb of manner modifying the verb ''sang''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('460d91b8-bfbb-45ff-91c9-fb6e09341169', 'Adverb of Manner', true, '2c2f3641-4085-47c3-9d57-daa6cadd8800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bacfaa9d-20ea-4a9c-83e8-00576796bc5a', 'Adjective', false, '2c2f3641-4085-47c3-9d57-daa6cadd8800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fff46ff-3050-45e2-896f-e410506ccfaa', 'Noun', false, '2c2f3641-4085-47c3-9d57-daa6cadd8800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f02dad1-fc23-4eff-bec4-21c70dd681e4', 'Preposition', false, '2c2f3641-4085-47c3-9d57-daa6cadd8800');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d493bec-5754-4499-b8c0-72447ad13b1d', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Fill in the blank with the correct modal auxiliary verb expressing strong obligation:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb33efb7-f43c-4290-8019-24fb7fa6266e', 'must', true, '8d493bec-5754-4499-b8c0-72447ad13b1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc32ade1-95e3-4282-876a-d5ddf34ba6ff', 'might', false, '8d493bec-5754-4499-b8c0-72447ad13b1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('754a17f0-fb29-479a-9b65-0ecc4d0cf23c', 'could', false, '8d493bec-5754-4499-b8c0-72447ad13b1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0894c390-f4a4-4a45-ab96-61e6df7a8113', 'may', false, '8d493bec-5754-4499-b8c0-72447ad13b1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9cd2054c-9a01-4a17-b71a-c27c75af4b7b', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Choose the correct antonym of the word ''Ancient'':', 'The antonym of ''ancient'' (belonging to the distant past) is ''modern''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a1352e7-5dfa-4f48-a47d-8e45467e7ee6', 'Modern', true, '9cd2054c-9a01-4a17-b71a-c27c75af4b7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15bf39af-0472-400b-a5a2-cb36972a1c05', 'Antique', false, '9cd2054c-9a01-4a17-b71a-c27c75af4b7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f97b15fc-f7a0-444c-a6e0-ab4158837f2b', 'Historic', false, '9cd2054c-9a01-4a17-b71a-c27c75af4b7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa2feb0-f05b-4959-8681-df2b1702012f', 'Aged', false, '9cd2054c-9a01-4a17-b71a-c27c75af4b7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e354fb9-4e4c-40a9-86af-784bc3557a50', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Choose the correct synonym of ''Compassion'':', '''Compassion'' signifies deep sympathetic pity and concern for the sufferings of others.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb9ca9dd-ea3d-4d63-8fbb-b7fc88f572db', 'Empathy / Kindness / Sympathy', true, '9e354fb9-4e4c-40a9-86af-784bc3557a50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3519c9b4-c590-4aa4-9e36-4620d240f009', 'Cruelty', false, '9e354fb9-4e4c-40a9-86af-784bc3557a50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a84b424-c4ac-4a7b-bf82-1c6e98992082', 'Jealousy', false, '9e354fb9-4e4c-40a9-86af-784bc3557a50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cf69276-6239-4ddf-b4f9-c980c15f0de5', 'Arrogance', false, '9e354fb9-4e4c-40a9-86af-784bc3557a50');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7712bdd-3bfb-45a1-b218-4a9587a926d4', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Convert into PASSIVE VOICE:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8389994e-85b7-4a38-b1a7-ffaabd6c3193', '''These durable leather boots were made by the master craftsman.''', true, 'd7712bdd-3bfb-45a1-b218-4a9587a926d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f0100d1-20d3-449f-8f43-ff4061b87339', '''These durable leather boots made the master craftsman.''', false, 'd7712bdd-3bfb-45a1-b218-4a9587a926d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5dac94b-8ff7-4c36-a7da-42efbae984b0', '''The boots was made by master craftsman.''', false, 'd7712bdd-3bfb-45a1-b218-4a9587a926d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eefb970c-bde2-40e5-ac72-22a06eff0806', '''By the boots were made the craftsman.''', false, 'd7712bdd-3bfb-45a1-b218-4a9587a926d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31db14a9-9053-47b2-9bb7-88ff3b6c0838', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'What is a ''Gerund'' in English grammar?', 'A gerund is a non-finite verbal noun formed by adding ''-ing'' to the base verb (e.g. ''Reading enriches the mind'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deb3257d-2299-4495-b625-b3cba11f7ba0', 'A verb form ending in ''-ing'' that functions as a NOUN in a sentence (e.g. ''Swimming is healthy'')', true, '31db14a9-9053-47b2-9bb7-88ff3b6c0838');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ae70bc2-84d1-4c5b-b5a3-5f8539fd9918', 'A verb in past tense', false, '31db14a9-9053-47b2-9bb7-88ff3b6c0838');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba74bca3-9c84-421f-9ca5-b3a45442f88c', 'An adjective that describes colors', false, '31db14a9-9053-47b2-9bb7-88ff3b6c0838');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8278420b-f7b0-475f-beda-9e4f77c05ea6', 'A conjunction connecting two sentences', false, '31db14a9-9053-47b2-9bb7-88ff3b6c0838');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('213bb27f-fddd-4a94-86d6-78071b6228a2', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Which punctuation mark is used to enclose direct spoken dialogue in English narrative writing?', 'Direct speech in dialogue is framed within quotation marks / inverted commas (" ").', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bede1d79-9022-4084-bda8-96178295fa8d', 'Quotation Marks / Inverted Commas (" ")', true, '213bb27f-fddd-4a94-86d6-78071b6228a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ad0e186-1207-4662-a41b-40d13f244aae', 'Semicolon (;)', false, '213bb27f-fddd-4a94-86d6-78071b6228a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22865a1b-4c97-4612-8ede-33219ef6eaef', 'Hyphen (-)', false, '213bb27f-fddd-4a94-86d6-78071b6228a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e461ad22-d497-48fe-9630-f475107dbd40', 'Slash (/)', false, '213bb27f-fddd-4a94-86d6-78071b6228a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09f7a6ba-5f82-40a9-a7c1-cdc8803b6555', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'In the poem ''The Rebel'' by D.J. Enright, what does the rebel always do?', 'D.J. Enright''s poem humorously portrays the rebel as someone who habitually contradicts social conventions to be uniquely different.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fc3ff78-3c78-493d-a2d9-6d56e868d882', 'He does the exact opposite of what everybody else is doing to assert his individuality', true, '09f7a6ba-5f82-40a9-a7c1-cdc8803b6555');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2a41670-9bfe-481d-9b57-5c6b25006ddb', 'He follows all rules strictly', false, '09f7a6ba-5f82-40a9-a7c1-cdc8803b6555');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08dc9268-2e78-482e-96fb-98c0c2287776', 'He sleeps all day', false, '09f7a6ba-5f82-40a9-a7c1-cdc8803b6555');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf8c7753-d6ca-4fcd-bd67-9e878f66e14b', 'He never speaks', false, '09f7a6ba-5f82-40a9-a7c1-cdc8803b6555');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36be2e30-06b0-4d79-80f4-cfed6abc5594', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'In ''The Cop and the Anthem'' by O. Henry, why does Soapy desperately try to get arrested by a police officer?', 'Soapy, a homeless man in New York, deliberately seeks arrest to secure free shelter and meals in the island prison for the winter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3285572-245c-488e-bfe8-28eca0932ac7', 'He wants to spend the three harsh winter months in the warmth and comfort of Blackwell''s Island prison with guaranteed food and shelter', true, '36be2e30-06b0-4d79-80f4-cfed6abc5594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fc61ba7-c950-4404-9c82-fc8a73d6af76', 'He wants to become a police officer', false, '36be2e30-06b0-4d79-80f4-cfed6abc5594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8114f23-f05a-4bc9-8863-ef6b926dce58', 'He wants to steal a diamond necklace', false, '36be2e30-06b0-4d79-80f4-cfed6abc5594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1af96a68-a41d-42c9-bb44-dfa7251917ed', 'He wants to leave New York by train', false, '36be2e30-06b0-4d79-80f4-cfed6abc5594');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7f05c8d-53d6-40e1-8abc-4f4ee83fb17d', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'What is the poignant situational irony at the end of O. Henry''s ''The Cop and the Anthem''?', 'Classic O. Henry twist: Soapy fails when trying to get arrested, but gets arrested the exact moment he resolves to reform his life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ce31fde-85ba-407f-96a2-4f7846d5d11c', 'Just when an organ anthem at a church inspires Soapy to reform his life and find honest work, a policeman arrests him for loitering, and the judge sentences him to three months in prison', true, 'd7f05c8d-53d6-40e1-8abc-4f4ee83fb17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fea33ecf-ecaa-4089-bd58-b5e8d0a9e2ef', 'Soapy finds a million dollars on the street', false, 'd7f05c8d-53d6-40e1-8abc-4f4ee83fb17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e93a06e-c0b7-4f9e-8cea-6786e97c3279', 'The church burns down', false, 'd7f05c8d-53d6-40e1-8abc-4f4ee83fb17d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3200cfd0-6a14-4813-be7c-11583e00a515', 'Soapy becomes mayor of the city', false, 'd7f05c8d-53d6-40e1-8abc-4f4ee83fb17d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e95b4dda-3113-46e5-ae52-6f7bb6c2b3e0', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'In Ruskin Bond''s charming story ''A Tiger in the House'', how did grandfather discover the tiger cub Timothy?', 'Grandfather discovered the abandoned eighteen-inch tiger cub in the Terai jungles and brought him home, naming him Timothy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ec7a392-a2cb-42fa-8bde-7843df2065a4', 'During a hunting expedition in the Terai jungle near Dehra, grandfather found the tiny eighteen-inch cub hiding among the roots of a banyan tree', true, 'e95b4dda-3113-46e5-ae52-6f7bb6c2b3e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec446361-e5e9-4a48-84f3-2c6aea982c75', 'He bought it from a pet shop', false, 'e95b4dda-3113-46e5-ae52-6f7bb6c2b3e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('582e0d85-7635-4b81-b0c3-a8191e9e1fc3', 'The cub walked into their kitchen', false, 'e95b4dda-3113-46e5-ae52-6f7bb6c2b3e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eccd633-5029-4a65-86fc-5ff7d0a99e5c', 'He found it at the zoo', false, 'e95b4dda-3113-46e5-ae52-6f7bb6c2b3e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41f68a05-d5c5-4123-ab8c-be9da0e49226', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Why did Grandfather decide to transfer Timothy the tiger to the Lucknow zoo when Timothy turned six months old?', 'As Timothy matured into an apex carnivore, his predatory instincts emerged, making it unsafe to keep him in a domestic household.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2bd9d9f-903b-471c-a353-d8488646e1d2', 'Timothy grew steadily less friendly, stalked the family cat with sinister intent, and began eyeing the cook Mahmoud hungrily', true, '41f68a05-d5c5-4123-ab8c-be9da0e49226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4caa0a2-4faa-47f1-8c90-cc1e0533467b', 'Timothy stopped eating meat', false, '41f68a05-d5c5-4123-ab8c-be9da0e49226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('312eef1a-f62c-46e5-9de6-9236dc385c9e', 'Grandfather moved to London', false, '41f68a05-d5c5-4123-ab8c-be9da0e49226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e8a781d-26e7-44db-bf76-51a003f8792f', 'The house was sold', false, '41f68a05-d5c5-4123-ab8c-be9da0e49226');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd9ada61-4d9b-4936-a5a8-70924c8ce635', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'In ''I Want Something in a Cage'' by L.E. Morgan, what does the mysterious stranger do with the two white doves he buys from Mr. Purcell''s pet shop?', 'Having spent ten agonizing years in prison, the stranger understands the supreme value of liberty, spending his hard-earned money to liberate caged doves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e69af9d-e114-44cc-a0c9-ee6e3a612ee4', 'He immediately takes them outside the shop and releases them into the open sky to fly free', true, 'fd9ada61-4d9b-4936-a5a8-70924c8ce635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae8a9040-a7f4-4ca1-ac41-e523945b0a6a', 'He cooks them for dinner', false, 'fd9ada61-4d9b-4936-a5a8-70924c8ce635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a82d6a1-fac9-4727-af74-7c5560a75a0f', 'He puts them in a gold cage', false, 'fd9ada61-4d9b-4936-a5a8-70924c8ce635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb3a4641-ed90-450a-8098-4d2c2b857b37', 'He sells them to another shop', false, 'fd9ada61-4d9b-4936-a5a8-70924c8ce635');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f61bafa-b329-4e9e-bc39-f1106a2c366d', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'In ''Chandni'' by Zakir Husain, why does the courageous goat Chandni choose to fight the wolf on the mountain rather than return to the safety of Abbu Khan''s hut?', 'Chandni embodies the heroic spirit of freedom, choosing mortal combat for liberty over comfortable domestic confinement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53cf9fd5-a322-4f3d-b55f-05cca7a95ddf', 'She values freedom and self-respect above a long life of captivity in a closed hut: ''Death in an open field is better than life in a small hut''', true, '8f61bafa-b329-4e9e-bc39-f1106a2c366d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1124f4e-567f-4494-a91c-ff98224c950b', 'She believes she is stronger than the wolf', false, '8f61bafa-b329-4e9e-bc39-f1106a2c366d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2edb5db-cd8e-4294-bcbb-92de99f25289', 'She hates Abbu Khan', false, '8f61bafa-b329-4e9e-bc39-f1106a2c366d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c484c1a9-9fa2-49ec-bf60-499397dc243c', 'She wants to rule the mountain', false, '8f61bafa-b329-4e9e-bc39-f1106a2c366d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22cef397-b5e5-4988-822e-233ac7fe3803', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Identify the SUBJECT and PREDICATE in the sentence:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('868e760d-f975-463c-941b-91034c614ac9', 'Subject: ''The ancient banyan tree in the village'' ; Predicate: ''provided shade to weary travelers''', true, '22cef397-b5e5-4988-822e-233ac7fe3803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10a9a1da-af75-4254-a4b4-2418a05b3beb', 'Subject: ''The ancient'' ; Predicate: ''banyan tree''', false, '22cef397-b5e5-4988-822e-233ac7fe3803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6dea0e7-1321-455a-bfad-f5cd306cc32e', 'Subject: ''weary travelers'' ; Predicate: ''provided shade''', false, '22cef397-b5e5-4988-822e-233ac7fe3803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89ac37d8-5f2e-46d1-aa72-ace09c07156d', 'Subject: ''in the village'' ; Predicate: ''tree provided''', false, '22cef397-b5e5-4988-822e-233ac7fe3803');
