INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1b2b5e0-9117-4a3f-8bec-7dbedaefc40e', 'was', true, 'd1752622-cf4b-465f-89bf-0b514802b69b');
