INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aaf8f10f-4aeb-41c8-b1fb-571c0cedcd35', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Convert to INDIRECT SPEECH:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fa53c23-9258-491d-be75-c62e6290fe4c', 'The hermit told the king that he had already been answered.', true, 'aaf8f10f-4aeb-41c8-b1fb-571c0cedcd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae3d9c6c-70bc-40d2-b11a-93df1d3cd936', 'The hermit said the king that you have been answered.', false, 'aaf8f10f-4aeb-41c8-b1fb-571c0cedcd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37a1b9e6-c52d-49ae-93ad-b3b8558590aa', 'The hermit asked the king if he was answered.', false, 'aaf8f10f-4aeb-41c8-b1fb-571c0cedcd35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cb13b6f-6c60-4b25-b241-3e9433e60c29', 'The hermit told the king you had already been answered.', false, 'aaf8f10f-4aeb-41c8-b1fb-571c0cedcd35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('469e126b-ec3b-4fc4-bc8e-ad5af22aa8a5', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'What is the meaning of the phrasal verb ''To give up''?', '''Give up'' is an idiomatic phrasal verb meaning to quit, abandon an effort, or surrender.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4877c811-5132-4807-ab57-71f005f4a422', 'To abandon / To cease doing something / To surrender', true, '469e126b-ec3b-4fc4-bc8e-ad5af22aa8a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce9ff496-7aa1-4598-9ed4-ef200f39ee17', 'To hand over a gift', false, '469e126b-ec3b-4fc4-bc8e-ad5af22aa8a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b06ebec-c49a-49d9-9118-303454148837', 'To climb upwards', false, '469e126b-ec3b-4fc4-bc8e-ad5af22aa8a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e1d7aac-fc4a-476c-988d-c3ae0726ffa8', 'To look for something', false, '469e126b-ec3b-4fc4-bc8e-ad5af22aa8a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cabf8a36-3164-4be7-acd4-b5e659878f2f', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Identify the figure of speech in: ''The wind whispered through the dark pine trees.''', 'Personification endows natural elements (wind) with human behavioral traits (whispering).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('247d588a-c65c-474d-b848-be89f08fad3e', 'Personification (attributing the human action of ''whispering'' to non-human wind)', true, 'cabf8a36-3164-4be7-acd4-b5e659878f2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60aac93a-5831-488f-99bf-90dab020d096', 'Simile', false, 'cabf8a36-3164-4be7-acd4-b5e659878f2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2096674-18da-4ec8-9549-4cf9b568b8f8', 'Metaphor only', false, 'cabf8a36-3164-4be7-acd4-b5e659878f2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45699553-6b87-4589-9a8d-dc3f529542e4', 'Hyperbole', false, 'cabf8a36-3164-4be7-acd4-b5e659878f2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c9ff1c4-b337-4a50-a89f-8fc3559e26ab', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'What type of conditional clause is: ''If it rains tomorrow, we will cancel the outdoor picnic.''?', 'First Conditional structures express realistic future possibilities using ''If + Present Simple, will + Infinitive''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81ec66f4-0974-43fa-b783-28343035c983', 'First Conditional (Real / Probable future condition: If + Present Simple, will + base verb)', true, '6c9ff1c4-b337-4a50-a89f-8fc3559e26ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a44b333e-265f-4b00-9628-508b37bab12c', 'Zero Conditional', false, '6c9ff1c4-b337-4a50-a89f-8fc3559e26ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('554cd5f5-d270-4dbb-8599-4c307c8d1a83', 'Second Conditional', false, '6c9ff1c4-b337-4a50-a89f-8fc3559e26ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71e5f0b5-4e22-4e49-91d6-94c1ba293bce', 'Third Conditional', false, '6c9ff1c4-b337-4a50-a89f-8fc3559e26ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bc31aab-4619-42bd-a3a5-0527eaa44306', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Choose the correct spelling:', 'Correct orthography: P-E-R-S-E-V-E-R-A-N-C-E.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc6d6728-ba7b-4425-96ed-897a75020cc3', 'Perseverance', true, '9bc31aab-4619-42bd-a3a5-0527eaa44306');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d8a6206-6789-43bb-8bd7-aa26bc983dd5', 'Perseverence', false, '9bc31aab-4619-42bd-a3a5-0527eaa44306');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c80f09e-767d-4901-81e9-df5084e884e9', 'Perceverance', false, '9bc31aab-4619-42bd-a3a5-0527eaa44306');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd5c8398-c79f-43df-993b-014f8f14233c', 'Persevarance', false, '9bc31aab-4619-42bd-a3a5-0527eaa44306');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5732839e-d232-4a42-adef-136f2cef016d', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'What is the meaning of the idiom ''To burn the candle at both ends''?', 'Idiom meaning: exhausting one''s physical energy through relentless overwork and late-night toil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d161ec6-340e-48b4-8ffc-3634e406b4bf', 'To work excessively hard from early morning until late at night without adequate rest', true, '5732839e-d232-4a42-adef-136f2cef016d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8dcd79c-15f6-4629-8be1-be962d095586', 'To waste money on candles', false, '5732839e-d232-4a42-adef-136f2cef016d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3730b266-e597-4ced-aa12-357b9acaf5d0', 'To set a house on fire', false, '5732839e-d232-4a42-adef-136f2cef016d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7ef9a68-a29a-448e-9df7-67f10751694a', 'To make candles in a factory', false, '5732839e-d232-4a42-adef-136f2cef016d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('141613b6-1d4c-4f59-a1aa-80f66cc22361', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Identify the type of non-finite verb in the underlined phrase: ''**Walking briskly**, she reached the station on time.''', '''Walking briskly'' is a Present Participial Phrase modifying the subject pronoun ''she''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73eb7947-1cb7-435b-a30b-34866e9c8555', 'Present Participle (functioning as a participial modifier)', true, '141613b6-1d4c-4f59-a1aa-80f66cc22361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3e70471-f85b-4a6a-9ada-1e27ad42fd71', 'Gerund', false, '141613b6-1d4c-4f59-a1aa-80f66cc22361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83f752cc-0cec-4064-9152-ae5ececb4e6c', 'Infinitive', false, '141613b6-1d4c-4f59-a1aa-80f66cc22361');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b409d07-fdbb-49d9-aca3-6b97c6900c47', 'Finite verb', false, '141613b6-1d4c-4f59-a1aa-80f66cc22361');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab10419e-1885-4b88-a578-cb8dac7024cc', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1d4df40-6bbc-488a-a618-9fd34ec1c493', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'ab10419e-1885-4b88-a578-cb8dac7024cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d88cb5a2-cdb1-4a26-b1f1-05e03edded67', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'ab10419e-1885-4b88-a578-cb8dac7024cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf256c31-368d-4b19-9a78-9e4f6c3c3094', '(A) is true, but (R) is false.', false, 'ab10419e-1885-4b88-a578-cb8dac7024cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef0b842b-f0e7-4651-9dac-e461f0131e2c', '(A) is false, but (R) is true.', false, 'ab10419e-1885-4b88-a578-cb8dac7024cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5874da8a-c007-47c8-ade7-c81a82137e47', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Spot the IMPOSTER in the following matching of NCERT Class 7 English classic stories and their overarching thematic motifs:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c83dcf6-3627-4c21-9e94-a42b87069400', 'Story 1', false, '5874da8a-c007-47c8-ade7-c81a82137e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66d77255-5c78-4dce-8392-18fcd506da8f', 'Story 2', false, '5874da8a-c007-47c8-ade7-c81a82137e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59f9c492-1918-450b-89aa-fb8836eb26a2', 'Story 3', false, '5874da8a-c007-47c8-ade7-c81a82137e47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d4eb1f3-8c20-4c36-bea3-7103ef3dbc02', 'Story 4 (''The Story of Cricket'' by Ramachandra Guha is a historical-sociological essay on sports, empire, and media, NOT a fairy tale about dragons)', true, '5874da8a-c007-47c8-ade7-c81a82137e47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66c1d7a4-8413-4a6b-9ed1-700616cd3e74', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Analyze the syntactic grammar of the complex sentence:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('605c6e40-14b1-4dd9-9577-abbe34bbcfbf', '''he refused to compromise on the flawless quality of his craftsmanship''', true, '66c1d7a4-8413-4a6b-9ed1-700616cd3e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a79c31ef-1d58-44fb-8082-536aa80858a0', '''Although Mr. Gessler suffered immense financial loss''', false, '66c1d7a4-8413-4a6b-9ed1-700616cd3e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f84f7ce-fd32-487f-bc72-efafb0270053', '''because large commercial firms dominated the boot market''', false, '66c1d7a4-8413-4a6b-9ed1-700616cd3e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bd9e1d9-1524-447c-9995-cb18b49ba56e', '''of his craftsmanship''', false, '66c1d7a4-8413-4a6b-9ed1-700616cd3e74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e2435b2-7fef-464a-ab24-3ca4b7fe75a2', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Match Column I (Grammatical Structures) with Column II (Illustrative Sentence Examples):
(a) Subjunctive Mood       -> (i) The committee recommended that he **be** appointed immediately.
(b) Third Conditional      -> (ii) If he **had practiced**, he **would have won** the debate.
(c) Gerund Phrase          -> (iii) **Reading classical literature** broadens human empathy.
(d) Passive Transformation  -> (iv) The sacred manuscripts **were preserved** by the monks.', 'Subjunctive = bare ''be''; 3rd conditional = had practiced/would have won; Gerund = Reading literature; Passive = were preserved.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76ea197b-5ff0-4e65-b9d4-bc903cda0440', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '8e2435b2-7fef-464a-ab24-3ca4b7fe75a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b3e6cb6-ab45-4757-98b3-5ecf31498a83', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '8e2435b2-7fef-464a-ab24-3ca4b7fe75a2');
