INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06ef435f-497e-4841-9512-bbbab3cb3c03', 'Statements 1 and 2 only', true, '4ba62c5c-52ee-4f22-aa8b-d0073c2f1fb5');
