INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3789683-3101-4bbf-bf60-76ccb23caa01', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'In John Galsworthy''s ''Quality'', what tragic fate befalls master craftsman Mr. Gessler at the climax of the story?', 'Mr. Gessler''s tragic demise: dying of chronic malnutrition (''slow starvation'') while stubbornly upholding uncompromising artisanal perfection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b0aca65-5a57-445c-afec-5b57a0c9f08a', 'He dies of slow starvation (''starvation of character'') because he invested all his earnings into rent and the finest leathers, starving himself to finish customer orders', true, 'd3789683-3101-4bbf-bf60-76ccb23caa01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d220b001-51fc-486b-b81f-8f5c69d4f35f', 'He becomes a wealthy factory owner', false, 'd3789683-3101-4bbf-bf60-76ccb23caa01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4670e697-07e2-4947-9c8b-c36774b473fe', 'He moves to America to build rockets', false, 'd3789683-3101-4bbf-bf60-76ccb23caa01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6641840a-bc63-4867-b08e-2dd907ec731f', 'He is elected mayor of London', false, 'd3789683-3101-4bbf-bf60-76ccb23caa01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8db420a-2ca4-41a1-a075-f3b08a601d87', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Which of the following sentences exhibits FLAWLESS punctuation, capitalization, and syntax?', 'Option 1 follows standard dialogue punctuation: comma inside quotes, lower-case attribution tag, followed by lowercase continuation quote.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a077abb7-6085-4b24-a28d-8c10a6bd96fe', '"If you have compassion for all living beings," remarked the philosopher, "you will find true inner peace."', true, 'c8db420a-2ca4-41a1-a075-f3b08a601d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59989549-2e3c-4da2-8bc3-4157b5effd58', '"If you have compassion for all living beings" remarked the philosopher, "You will find true inner peace."', false, 'c8db420a-2ca4-41a1-a075-f3b08a601d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69e7d9ef-7f5b-4ed2-93eb-6e80ce0c1843', 'If you have compassion for all living beings, remarked the philosopher "you will find true inner peace."', false, 'c8db420a-2ca4-41a1-a075-f3b08a601d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb4ee3e7-c83a-4eef-befa-09d2fad62443', '"If you have compassion for all living beings", remarked the philosopher; "you will find true inner peace."', false, 'c8db420a-2ca4-41a1-a075-f3b08a601d87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78d80a8f-5985-4570-ba9a-e484785dff81', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'What is the psychological significance of the bear in ''The Bear Story'' by Axel Munthe?', 'Axel Munthe''s comedy of errors: mistaken identity between a gentle domesticated pet bear and a bewildered wild forest bear.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea545da8-61fe-4611-a20f-96592258d26f', 'The tame, vegetarian bear is so gentle and disciplined that when the lady mistakenly scolds and beats a wild bear in the forest thinking it was her pet, the real pet bear looks bewildered at her anger at home', true, '78d80a8f-5985-4570-ba9a-e484785dff81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f3e71dd-6ba3-471d-939d-487075378ecb', 'The bear was a robot', false, '78d80a8f-5985-4570-ba9a-e484785dff81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc5b3bda-3087-4633-b0e5-fa935b0c283b', 'The bear ate everyone in the village', false, '78d80a8f-5985-4570-ba9a-e484785dff81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be26d378-49a4-4464-b86f-e800248df956', 'The bear was invisible', false, '78d80a8f-5985-4570-ba9a-e484785dff81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1730e0fd-05b5-4796-8d6b-905a200755a7', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Identify the grammatical error in the sentence:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50c86346-502d-4b95-8018-605de2a8d725', 'Error in verb: ''was'' should be replaced by ''were'' (because the plural subject ''sailors'' is closer to the verb)', true, '1730e0fd-05b5-4796-8d6b-905a200755a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7179e7dd-d218-47ad-a706-8ba0bb72b648', 'Error in ''neither...nor''', false, '1730e0fd-05b5-4796-8d6b-905a200755a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dfcd4a4-8915-4c38-8c47-c8fa6d35a8bc', 'Error in ''during the hurricane''', false, '1730e0fd-05b5-4796-8d6b-905a200755a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38252e7b-b589-43a6-832c-c62f02ea6675', 'There is no error in the sentence', false, '1730e0fd-05b5-4796-8d6b-905a200755a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7840eeb4-e117-4293-8d20-007dcb866160', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'What is the rhetorical effect of ''Anaphora'' in poetic verse?', 'Anaphora (e.g. in ''Trees'' or ''Meadow Surprises'') builds cumulative emotional resonance through rhythmic initial phrase repetition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1462e76b-339f-4dc4-aac4-3ccf87a6014e', 'The deliberate repetition of a word or phrase at the beginning of successive sentences or verse lines to create rhythm, emotional intensity, and thematic emphasis', true, '7840eeb4-e117-4293-8d20-007dcb866160');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99f926b5-7c05-476b-8e13-52b0fa3d921a', 'Using rhymes at the end of lines only', false, '7840eeb4-e117-4293-8d20-007dcb866160');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f480f2ac-bd75-4616-8803-8157159feede', 'Writing without any verbs', false, '7840eeb4-e117-4293-8d20-007dcb866160');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1494c3af-3b10-4a63-85d1-86b89129e274', 'Translating poems into Latin', false, '7840eeb4-e117-4293-8d20-007dcb866160');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fea1c2c7-cb74-48a2-9036-ffa31e2a88d0', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'In ''Golu Grows a Nose'' by Rudyard Kipling, how did the inquisitive young elephant Golu obtain his long trunk?', 'Kipling''s ''Just So'' fable: Golu''s nose stretches during a tug-of-war with a crocodile on the banks of the great grey-green Limpopo River.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a59c854-5c8d-427c-8936-e531faf0d6dd', 'The Crocodile in the Limpopo River seized Golu by his small bulgy nose and pulled; during the intense tug-of-war, Golu''s nose stretched out into a five-foot-long versatile trunk', true, 'fea1c2c7-cb74-48a2-9036-ffa31e2a88d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92333674-6cd9-4401-8933-0b4abdfa07f3', 'He was born with it', false, 'fea1c2c7-cb74-48a2-9036-ffa31e2a88d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f16846d-90d8-4fa8-b03d-a3b17ecc6da6', 'A doctor gave him a magic potion', false, 'fea1c2c7-cb74-48a2-9036-ffa31e2a88d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69c6a61e-d39d-4551-84dc-7d9f957601c2', 'A tree branch fell on his face', false, 'fea1c2c7-cb74-48a2-9036-ffa31e2a88d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87b9b5ec-2276-4edc-b848-c7d57fbc89f6', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'What grand linguistic and humanistic mastery concludes Chapter 12 of NCERT Class 7 English?', 'Chapter 12 synthesizes syntactic mastery, applied rhetoric, ethical contemplation, and nuanced literary appreciation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('065043fd-b07d-44db-8852-d718d3ff2db9', 'Mastery of the English language integrates grammatical precision, sophisticated rhetorical eloquence, and deep literary contemplation—empowering learners to articulate ideas persuasively, understand human nature, and cultivate lifelong intellectual empathy', true, '87b9b5ec-2276-4edc-b848-c7d57fbc89f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a3823b6-6dfa-42e8-a771-2ddb3b8a84b7', 'That grammar rules should be memorized without understanding', false, '87b9b5ec-2276-4edc-b848-c7d57fbc89f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d02f1ef0-31db-4754-8a35-a1ba81a3a718', 'That literature has no connection to real life', false, '87b9b5ec-2276-4edc-b848-c7d57fbc89f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('711bd6c2-286e-42f0-8c4e-31c222e4b4ab', 'That writing is only for passing school exams', false, '87b9b5ec-2276-4edc-b848-c7d57fbc89f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe8e9e28-9216-45a6-ab3c-8fc1674285df', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'When is ''WORLD ENVIRONMENT DAY'' celebrated globally every year under the United Nations Environment Programme (UNEP)?', 'World Environment Day is observed on June 5 annually since 1973 to drive global awareness and action for environmental protection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('077409a6-b22c-41df-b2f9-a4588d371f97', 'June 5', true, 'fe8e9e28-9216-45a6-ab3c-8fc1674285df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e328f828-3033-4622-8cb0-5d8381ea09b7', 'April 22', false, 'fe8e9e28-9216-45a6-ab3c-8fc1674285df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('574633a8-3ba1-49e6-b998-e50a6c603a02', 'March 21', false, 'fe8e9e28-9216-45a6-ab3c-8fc1674285df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61dd055e-349a-4116-a74d-8991aa35308e', 'September 16', false, 'fe8e9e28-9216-45a6-ab3c-8fc1674285df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d86ff26-3e18-4bc3-ba20-0b52b744efb9', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'When is ''EARTH DAY'' celebrated internationally each year to demonstrate support for environmental protection?', 'Earth Day (first celebrated on 22 April 1970) mobilizes over a billion people in 190+ countries for environmental conservation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99bcfc7f-0315-45b3-a1d7-acafccc018d3', 'April 22', true, '5d86ff26-3e18-4bc3-ba20-0b52b744efb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0a2e382-61e7-4fca-836c-9d25ad981739', 'June 5', false, '5d86ff26-3e18-4bc3-ba20-0b52b744efb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3875b83-3f42-4497-9b30-44b5c00a816d', 'May 1', false, '5d86ff26-3e18-4bc3-ba20-0b52b744efb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3224791d-0a7f-4166-a0fb-0cb487069f98', 'March 3', false, '5d86ff26-3e18-4bc3-ba20-0b52b744efb9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29da44d9-3f9e-4b73-96c8-263352f1f1b7', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'What is the primary human-generated GREENHOUSE GAS responsible for the majority of global warming and climate change?', 'Carbon dioxide (emitted primarily by burning fossil fuels like coal, oil, and gas) is the predominant driver of anthropogenic global warming.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d2894d4-07df-4409-86b3-28a9d5185089', 'Carbon Dioxide (CO₂)', true, '29da44d9-3f9e-4b73-96c8-263352f1f1b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c314a3e9-a2b1-47ea-9ee5-0d6cb7f9578c', 'Oxygen (O₂)', false, '29da44d9-3f9e-4b73-96c8-263352f1f1b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('432142a4-3537-4c47-b063-8eecfc8ce2f9', 'Nitrogen (N₂)', false, '29da44d9-3f9e-4b73-96c8-263352f1f1b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55088bc5-b84f-45e4-981a-c032e9e3be41', 'Argon', false, '29da44d9-3f9e-4b73-96c8-263352f1f1b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc91dace-1e4e-4562-8f83-06cce2c4d59d', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'Which landmark international climate treaty was adopted by 196 nations at COP21 in 2015 to limit global warming to well below 2°C (preferably 1.5°C) above pre-industrial levels?', 'The Paris Climate Agreement (2015) commits world nations to legally binding national climate action plans (NDCs) to limit warming to 1.5°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d597a4a-3e04-4abb-8066-ed967d7b4c3b', 'The Paris Agreement', true, 'cc91dace-1e4e-4562-8f83-06cce2c4d59d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3bc0b8f-d580-4698-b267-174e63b4e02c', 'The Kyoto Protocol', false, 'cc91dace-1e4e-4562-8f83-06cce2c4d59d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1e5cb8a-48a4-461b-a50f-cc0af454ae0a', 'The Montreal Protocol', false, 'cc91dace-1e4e-4562-8f83-06cce2c4d59d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1da28cd4-87aa-4db1-87bf-b6ffbf193e39', 'The Geneva Convention', false, 'cc91dace-1e4e-4562-8f83-06cce2c4d59d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58a0870b-939d-40c2-8fb9-2ca1a11180d7', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'Which successful 1987 international treaty mandated the global phase-out of Chlorofluorocarbons (CFCs) to protect the Earth''s OZONE LAYER?', 'The Montreal Protocol (1987) successfully phased out 99% of ozone-depleting substances, enabling the Antarctic ozone layer to heal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dad92d4-3b69-4aa1-9606-5242ffd766e4', 'The Montreal Protocol', true, '58a0870b-939d-40c2-8fb9-2ca1a11180d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d2331c9-f612-4924-97bf-f040708561f9', 'The Paris Agreement', false, '58a0870b-939d-40c2-8fb9-2ca1a11180d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('987208f6-ad6f-4721-ad9e-4412809cd4b2', 'The Ramsar Convention', false, '58a0870b-939d-40c2-8fb9-2ca1a11180d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7653b025-4ecd-4c8d-a01a-19bccb7fd3c4', 'The Basel Convention', false, '58a0870b-939d-40c2-8fb9-2ca1a11180d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9401bb67-af13-4763-a13a-139553c6b420', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'Which international treaty signed in Iran in 1971 is dedicated to the conservation and sustainable use of WETLANDS of international importance?', 'The Ramsar Convention (1971) safeguards ecologically crucial wetlands (Ramsar Sites) worldwide.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49343c11-ee1a-45ad-81ae-97bb59cd7c25', 'The Ramsar Convention', true, '9401bb67-af13-4763-a13a-139553c6b420');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f794865-df83-489b-9e37-d04185d1fdb4', 'The Kyoto Protocol', false, '9401bb67-af13-4763-a13a-139553c6b420');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cf180e4-1b5f-44d4-b8e9-b35a9cbb52d0', 'The Rio Summit', false, '9401bb67-af13-4763-a13a-139553c6b420');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca1c07e7-bd75-4d81-a3d1-54bf702302df', 'CITES', false, '9401bb67-af13-4763-a13a-139553c6b420');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a182ac7a-14a6-4077-af86-194511912351', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'Which species of big cat was reintroduced to India in Kuno National Park (Madhya Pradesh) in September 2022 after being declared extinct in India in 1952?', 'Project Cheetah brought African cheetahs to Kuno National Park in 2022 to re-establish the extinct feline apex predator in Indian grasslands.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1d6904f-963e-48eb-9dde-acc75b012607', 'Cheetah (from Namibia and South Africa)', true, 'a182ac7a-14a6-4077-af86-194511912351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40b246a4-be32-498b-af96-bde880eeca9c', 'Snow Leopard', false, 'a182ac7a-14a6-4077-af86-194511912351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9fc3681-87cd-41bb-a8b2-b2b7123c676d', 'Jaguar', false, 'a182ac7a-14a6-4077-af86-194511912351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73f2357b-b0c6-4c6d-9a52-7d83688ac779', 'Cougar', false, 'a182ac7a-14a6-4077-af86-194511912351');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c6b71f5-97ac-4416-973f-ca710b03f2bb', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'What is the name of the flagship wildlife conservation initiative launched by the Government of India in 1973 to protect the Royal Bengal Tiger?', 'Project Tiger, launched in 1973 at Corbett National Park, revived India''s tiger population to over 3,600+ tigers (75% of global wild tigers).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f53d88e5-c103-4815-900f-b02050cf7809', 'Project Tiger (1973)', true, '7c6b71f5-97ac-4416-973f-ca710b03f2bb');
