INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('980d43cd-1706-4b79-a54c-85f4f7ce5051', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'How many SUSTAINABLE DEVELOPMENT GOALS (SDGs) were established by the United Nations General Assembly in 2015 to be achieved by the year 2030?', 'The UN 2030 Agenda consists of 17 Sustainable Development Goals (SDGs) spanning poverty eradication, clean water, climate action, and peace.', NOW()) ON CONFLICT DO NOTHING;
