INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2f7f8ef-0804-4f23-b379-d98375a3a95b', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'Which National Park in Assam is world-famous as the supreme sanctuary for the endangered GREAT ONE-HORNED RHINOCEROS?', 'Kaziranga National Park in Assam hosts two-thirds of the world''s great one-horned rhinoceros population and is a UNESCO World Heritage site.', NOW()) ON CONFLICT DO NOTHING;
