INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('031c3e7a-96d6-498a-b885-efd330e227de', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Net-Zero Emissions'' (Carbon Neutrality)?', 'Net-Zero means emissions are slashed to near-zero, with any residual unavoidable emissions absorbed by natural carbon sinks or DAC technologies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebaec9e0-35fd-4708-a4a4-ef7f3b77479d', 'Achieving an overall balance where any human-caused greenhouse gas emissions released into the atmosphere are completely balanced and neutralized by equivalent carbon removal (via forests, carbon capture, ocean sinks)', true, '031c3e7a-96d6-498a-b885-efd330e227de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a14758b-7c3a-4741-a66c-abf320c5e4c7', 'Banning all factories and electricity', false, '031c3e7a-96d6-498a-b885-efd330e227de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45dc8568-3e1a-426a-944f-ddc5e5f2c0e6', 'Stopping all human transportation', false, '031c3e7a-96d6-498a-b885-efd330e227de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80d19ec5-8134-4ccb-8190-8eafadbce19c', 'Planting only one tree per person', false, '031c3e7a-96d6-498a-b885-efd330e227de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6712874-8a76-485c-b383-61e49f97ed58', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'By which target year has India committed at COP26 to achieve NET-ZERO CARBON EMISSIONS (Panchamrit goals)?', 'Prime Minister Narendra Modi announced at COP26 Glasgow that India will reach Net-Zero carbon emissions by 2070 while installing 500 GW non-fossil energy by 2030.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82ec3592-8943-4256-a512-a725e1519870', '2070', true, 'a6712874-8a76-485c-b383-61e49f97ed58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('846e937a-b525-4599-8835-8b72bc86f485', '2050', false, 'a6712874-8a76-485c-b383-61e49f97ed58');
