INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3644b67-75d8-4b93-86f7-ebdf9064f29d', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''GREEN HYDROGEN'' in clean energy transition?', 'Green Hydrogen is the holy grail of zero-emission fuel, decarbonizing heavy industries (steel, cement, fertilizers, shipping) using renewable electrolysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9060792-83f0-43e1-943e-b323d3caf33d', 'Hydrogen gas produced by splitting water (H₂O) into hydrogen and oxygen through electrolysis powered exclusively by RENEWABLE ENERGY (solar/wind), producing zero carbon emissions', true, 'e3644b67-75d8-4b93-86f7-ebdf9064f29d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21b362c7-d4ef-467b-b7f6-b55722c6e831', 'Hydrogen painted with green dye', false, 'e3644b67-75d8-4b93-86f7-ebdf9064f29d');
