INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e634f22-3c0e-4e0e-a6cb-4954e21a51b0', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is the ''Intergovernmental Panel on Climate Change'' (IPCC)?', 'The IPCC (Nobel Peace Prize 2007) produces definitive Assessment Reports (like AR6) guiding global climate policy and treaty negotiations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('339c90aa-ceb8-4759-912c-4d05314120d9', 'The United Nations scientific body that assesses and synthesizes comprehensive peer-reviewed scientific research on climate change, its risks, and mitigation options', true, '3e634f22-3c0e-4e0e-a6cb-4954e21a51b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('340ea472-5444-4684-94ea-c6debf223dd2', 'A military police force that arrests polluters', false, '3e634f22-3c0e-4e0e-a6cb-4954e21a51b0');
