INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbd2bce4-6a60-4962-8759-00a10d1974d3', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Carbon Footprint''?', 'A carbon footprint quantifies individual, corporate, or national greenhouse gas emissions expressed in equivalent metric tonnes of CO₂ (tCO₂e).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1870d5ac-4d5e-4479-bf00-20b197236d68', 'The total amount of greenhouse gases (including carbon dioxide and methane) generated directly and indirectly by our individual, organizational, or product actions', true, 'dbd2bce4-6a60-4962-8759-00a10d1974d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f824e9f-6b42-4d8b-aa60-120a4cc206f9', 'The footprint left by coal miners in dirt', false, 'dbd2bce4-6a60-4962-8759-00a10d1974d3');
