INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ce3dfe6-b7a8-4ec9-86d0-789c39bc72b4', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Ocean Acidification'' caused by rising atmospheric carbon dioxide levels?', 'CO₂ + H₂O → H₂CO₃; seawater acidification depletes carbonate ions, imperiling coral reefs (Great Barrier Reef) and marine food webs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1508dce-25de-4dab-b4b2-c038d13eb4f1', 'The oceans absorb ~30% of atmospheric CO₂, forming carbonic acid, which lowers seawater pH and dissolves calcium carbonate shells/skeletons of corals, mollusks, and plankton', true, '4ce3dfe6-b7a8-4ec9-86d0-789c39bc72b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a73ddc4d-ff84-4018-ae3a-ac995f064856', 'Oceans turning into vinegar', false, '4ce3dfe6-b7a8-4ec9-86d0-789c39bc72b4');
