INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a238c7-d1a4-4028-a3e9-13ed4d29db51', 'Ocean water turning into fresh drinking water', false, '4ce3dfe6-b7a8-4ec9-86d0-789c39bc72b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1289e7b0-fe76-4606-947e-e8fd781b53b0', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'Which global conservation organization publishes the authoritative ''IUCN RED LIST'' of threatened biological species?', 'The IUCN Red List of Threatened Species is the world''s most comprehensive inventory of the global conservation status of biological species.', NOW()) ON CONFLICT DO NOTHING;
