INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a2c0fb5-e598-4439-a2d3-cfa8be0342c8', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is the ''Great Green Wall'' initiative in Africa?', 'The Great Green Wall combats desertification across 11 Sahelian nations by restoring 100 million hectares of degraded land by 2030.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('158f9df1-ac48-40fe-a591-aa97d9c25849', 'An ambitious 8,000-km ecological restoration project planting a continuous belt of trees across the entire width of the Sahel to halt the southward expansion of the Sahara Desert', true, '6a2c0fb5-e598-4439-a2d3-cfa8be0342c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff9b8eaf-991e-49a0-bafa-3bcc7f858628', 'A giant concrete wall built along borders', false, '6a2c0fb5-e598-4439-a2d3-cfa8be0342c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d25c70e2-fda4-499d-beb6-a5162e788d86', 'A green glass greenhouse', false, '6a2c0fb5-e598-4439-a2d3-cfa8be0342c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e102b07d-e2f8-4166-a0f4-7aed641dfaf9', 'A highway through the rainforest', false, '6a2c0fb5-e598-4439-a2d3-cfa8be0342c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b90adb97-37d2-4846-bc47-b45430840d86', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Mission LiFE'' (Lifestyle for Environment) launched by India at the 2021 Glasgow Climate Summit?', 'Mission LiFE mobilizes citizens worldwide as ''Pro-Planet People'' (P3) to reduce waste, save water, conserve energy, and practice circular lifestyles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1425ff19-2774-418a-9e58-7580dd6c5bfa', 'A global mass movement encouraging individuals and communities to adopt sustainable, mindful, environmentally conscious everyday consumption choices instead of mindless consumerism', true, 'b90adb97-37d2-4846-bc47-b45430840d86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b85a3d2-cac6-4c09-9dce-8086feabe9d1', 'A medical insurance plan for doctors', false, 'b90adb97-37d2-4846-bc47-b45430840d86');
