INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb20bc72-e1de-419a-90be-034dbaf7c2b6', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'Which is the OLDEST National Park in India, established in 1936 in Uttarakhand (originally named Hailey National Park)?', 'Jim Corbett National Park (established in 1936 as Hailey National Park) is India''s first and oldest national park.', NOW()) ON CONFLICT DO NOTHING;
