INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c251bb9-00d8-44d6-8f4b-35ad91b343c5', 'Sundarbans National Park', false, 'eb20bc72-e1de-419a-90be-034dbaf7c2b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbb892bb-a452-426d-a22b-594a0f18e4aa', 'Bandipur National Park', false, 'eb20bc72-e1de-419a-90be-034dbaf7c2b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3468b8e-3bba-42c2-978c-971ca2b3d090', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''E-Waste'' (Electronic Waste) and why is its recycling critical?', 'E-waste recycling prevents neurotoxic heavy metals from leaching into groundwater while recovering critical rare earth elements and lithium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80617216-be47-44c4-9d22-957d5178e603', 'Discarded electronic devices (smartphones, computers, batteries) containing hazardous heavy metals (lead, mercury, cadmium) as well as recoverable precious metals (gold, copper, lithium)', true, 'c3468b8e-3bba-42c2-978c-971ca2b3d090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cb65089-df68-4644-8123-8052010dd09f', 'Old paper books thrown into garbage', false, 'c3468b8e-3bba-42c2-978c-971ca2b3d090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d8578fe-68ac-405b-b03c-e4028527a127', 'Plastic shopping bags', false, 'c3468b8e-3bba-42c2-978c-971ca2b3d090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14cac56e-2c61-4758-beac-042d893c09c4', 'Food waste from restaurants', false, 'c3468b8e-3bba-42c2-978c-971ca2b3d090');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ce7147e-e45d-468c-9387-2e715e338157', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Microplastics'' pollution?', 'Microplastics (<5mm) ubiquitously pollute marine biospheres, bio-accumulating up trophic levels into fish, table salt, and human tissues.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1652f0c-9ad4-4ffa-9f2c-a82d8604d61c', 'Tiny microscopic plastic fragments (less than 5 mm in size) resulting from the degradation of plastic waste, synthetic textiles, and cosmetics that contaminate oceans, marine food chains, and human bloodstream', true, '2ce7147e-e45d-468c-9387-2e715e338157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d771ff5-bb32-4e45-9302-33c22b29deae', 'Plastic toys for dolls', false, '2ce7147e-e45d-468c-9387-2e715e338157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5a8378d-570a-4516-b529-400e129d219e', 'Small plastic coins used in board games', false, '2ce7147e-e45d-468c-9387-2e715e338157');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5aa18cb6-1e3e-4969-bd6e-cd88bf020b15', 'Plastic buttons on shirts', false, '2ce7147e-e45d-468c-9387-2e715e338157');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbfb7558-db3c-4018-903c-6ae1437bdd58', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What are ''Biodiversity Hotspots''?', 'Norman Myers defined 36 global Biodiversity Hotspots: regions with ≥1,500 endemic vascular plant species having lost ≥70% primary habitat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd6d35bf-9c03-49bd-9def-987df50835de', 'Biogeographic regions that possess exceptionally high concentrations of endemic biological species (found nowhere else on Earth) and are undergoing severe habitat loss (e.g. Western Ghats and Eastern Himalayas)', true, 'cbfb7558-db3c-4018-903c-6ae1437bdd58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc1957d0-b780-4827-b702-ffad75e00531', 'Volcanoes with lava', false, 'cbfb7558-db3c-4018-903c-6ae1437bdd58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22021171-d6d5-48cc-811f-fbd760e24ece', 'Desert areas with high temperature', false, 'cbfb7558-db3c-4018-903c-6ae1437bdd58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65293285-1f4c-49ad-9eca-1853b4ede5d4', 'Zoos with many animals', false, 'cbfb7558-db3c-4018-903c-6ae1437bdd58');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cca0f3a1-9288-4efe-b4dd-4d734653a456', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is the ''Albedo Effect'' in polar climate science?', 'The ice-albedo feedback is a critical climate tipping element: loss of reflective sea ice increases oceanic heat absorption.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f599940-4a6b-4756-90f7-c26ee5ac75ac', 'The fraction of solar radiation reflected by a surface: white polar ice has high albedo (reflects ~80% sunlight), but melting ice exposes dark ocean water which absorbs heat, accelerating global warming in a feedback loop', true, 'cca0f3a1-9288-4efe-b4dd-4d734653a456');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a130d575-dfe2-4ad1-af7b-c4effae3c3ff', 'The color of polar bears'' fur', false, 'cca0f3a1-9288-4efe-b4dd-4d734653a456');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84387381-d061-41d0-9f83-f8ad181215bc', 'The sound made by glaciers breaking', false, 'cca0f3a1-9288-4efe-b4dd-4d734653a456');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20f132df-8e35-465a-9f05-186887d59b0d', 'The depth of polar ice sheets', false, 'cca0f3a1-9288-4efe-b4dd-4d734653a456');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd505b7a-81ff-49d8-aac4-10e746100874', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Circular Economy''?', 'The circular economy replaces the linear ''take-make-dispose'' paradigm with closed-loop regenerative resource cycles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da7464e1-078f-4f03-aacf-368112620057', 'An economic model aimed at eliminating waste through continuous cycles of designing for durability, reuse, repairing, refurbishing, and recycling materials indefinitely', true, 'cd505b7a-81ff-49d8-aac4-10e746100874');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('947b436e-29e1-48de-a14c-d569c77560f0', 'An economy that prints round coins only', false, 'cd505b7a-81ff-49d8-aac4-10e746100874');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16d2dfb5-4334-4a02-9687-349d2f03879e', 'Trading goods only in circular markets', false, 'cd505b7a-81ff-49d8-aac4-10e746100874');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc413a1f-96ee-4b7e-aad4-4261beb5b316', 'An economy where prices go in circles', false, 'cd505b7a-81ff-49d8-aac4-10e746100874');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('477e8ed8-3a99-4d39-a390-b92b894deb79', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('607441e0-e6c1-40b6-ba11-41a40940b6ee', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '477e8ed8-3a99-4d39-a390-b92b894deb79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a335215d-cb17-4e27-83a0-17d25a3393aa', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '477e8ed8-3a99-4d39-a390-b92b894deb79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df22c548-3b97-4027-a497-83cb40259188', '(A) is true, but (R) is false.', false, '477e8ed8-3a99-4d39-a390-b92b894deb79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4d3ed16-2742-4eca-a043-7a23d98a5d90', '(A) is false, but (R) is true.', false, '477e8ed8-3a99-4d39-a390-b92b894deb79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8636c38c-93fa-4bfc-95c0-411fc1b25a5f', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Spot the IMPOSTER in the following major Global Environmental Treaties and their conservation mandates:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a70150f9-3424-4f7e-9e28-971792a074e2', 'Treaty 1', false, '8636c38c-93fa-4bfc-95c0-411fc1b25a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('624f8a41-6221-4e48-ba3e-420dba5e5252', 'Treaty 2', false, '8636c38c-93fa-4bfc-95c0-411fc1b25a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcaca832-e50e-4612-a670-402c3a6e6f50', 'Treaty 3', false, '8636c38c-93fa-4bfc-95c0-411fc1b25a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e39df22f-808f-4772-8333-62c1a22953d6', 'Treaty 4 (The Treaty of Versailles was a 1919 post-WWI peace treaty among European nations, NOT an environmental pact to plant trees on Mars)', true, '8636c38c-93fa-4bfc-95c0-411fc1b25a5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49d943e0-f484-47b0-8b21-cd680431e9b5', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Analyze the ecological concept of ''Carrying Capacity'' of an ecosystem:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f5c953e-df27-4295-82a4-526f3f59aa99', 'Resource depletion (food, water, territory) occurs, leading to environmental degradation, reproductive decline, disease outbreaks, and a sharp population crash (overshoot and collapse)', true, '49d943e0-f484-47b0-8b21-cd680431e9b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71c64fbd-d846-4cad-9e1c-4747e93ecf1b', 'The ecosystem instantly doubles in size', false, '49d943e0-f484-47b0-8b21-cd680431e9b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('632f09a6-efa7-494b-b182-b5d0842a0c15', 'Animals evolve into different species within a day', false, '49d943e0-f484-47b0-8b21-cd680431e9b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd656b66-8bbd-47f0-95fb-842e14b63797', 'Nothing happens because nature has infinite resources', false, '49d943e0-f484-47b0-8b21-cd680431e9b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5887258f-b173-47dc-aa33-3023b725f1a7', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Match Column I (UN Sustainable Development Goals - SDGs) with Column II (Target Agendas):
(a) SDG 4  -> (i) Quality Education for all
(b) SDG 6  -> (ii) Clean Water and Sanitation
(c) SDG 7  -> (iii) Affordable and Clean Energy
(d) SDG 13 -> (iv) Climate Action', 'SDG 4 = Quality Education; SDG 6 = Clean Water; SDG 7 = Clean Energy; SDG 13 = Climate Action.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f299209-77df-4131-951e-a1de72627b58', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '5887258f-b173-47dc-aa33-3023b725f1a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d399da24-aa86-445b-b71f-56f51b423cd1', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '5887258f-b173-47dc-aa33-3023b725f1a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb9804ff-b814-4a5a-9154-4d265b9fb092', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '5887258f-b173-47dc-aa33-3023b725f1a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7700b87-66b5-489c-9e09-78e1e64c11ee', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '5887258f-b173-47dc-aa33-3023b725f1a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6d75391-d150-43a2-a360-6ef18fcabb57', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Read the statements regarding renewable energy transition in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a1c710b-702f-4d19-8076-e4244e09c75e', 'Statements 1 and 2 only', true, 'a6d75391-d150-43a2-a360-6ef18fcabb57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e0419fe-9c28-4ecd-8a2f-1ee400228819', 'Statements 2 and 3 only', false, 'a6d75391-d150-43a2-a360-6ef18fcabb57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61decfb2-99ec-4634-999c-8331330bc8a1', 'Statements 1 and 3 only', false, 'a6d75391-d150-43a2-a360-6ef18fcabb57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('701a0db1-f22b-49f3-81b0-32630123b17b', 'All Statements 1, 2, and 3', false, 'a6d75391-d150-43a2-a360-6ef18fcabb57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd363fb3-b886-477b-b30f-6968ef25db96', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What is the biogeochemical danger of ''Permafrost Thawing'' in the Arctic tundra regions?', 'Permafrost holds ~1,500 gigatons of frozen carbon—twice the carbon currently in the atmosphere; thawing creates a catastrophic carbon-feedback loop.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7b7b4af-a714-419a-8708-d8abf48b04ef', 'Thawing permafrost awakens ancient microbes that decompose trapped organic matter, releasing hundreds of billions of tons of potent METHANE (CH₄) and CO₂ into the atmosphere, triggering runaway warming', true, 'bd363fb3-b886-477b-b30f-6968ef25db96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('007b75fd-5fdd-483d-8aff-146da7861534', 'It causes all rivers to turn into saltwater', false, 'bd363fb3-b886-477b-b30f-6968ef25db96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5279ec5-91e8-4780-85da-7560e4d8662c', 'It stops the Earth''s magnetic field', false, 'bd363fb3-b886-477b-b30f-6968ef25db96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('573f65cb-23f6-429b-aea0-031812771599', 'It turns rocks into gold', false, 'bd363fb3-b886-477b-b30f-6968ef25db96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8a4486f-1fab-4802-8d6e-b2d31de7eb2f', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What is ''Payment for Ecosystem Services'' (PES) in environmental economics?', 'PES programs (e.g. Costa Rica''s PSA) internalize ecological externalities by rewarding indigenous and rural communities for preserving living ecosystems.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910bc4d4-ac4e-47a2-9da8-652d20d21393', 'Incentives and financial compensations paid to local farmers, forest dwellers, and landowners who manage their land sustainably to provide vital ecological services (clean water filtration, carbon sequestration, flood prevention)', true, 'a8a4486f-1fab-4802-8d6e-b2d31de7eb2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82cbb1f4-6073-4d9d-93df-4157465d3eae', 'Taxes paid to enter city parks', false, 'a8a4486f-1fab-4802-8d6e-b2d31de7eb2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b2a40d4-7099-403c-b68b-dfd89628c26a', 'Salaries paid to zoo guards', false, 'a8a4486f-1fab-4802-8d6e-b2d31de7eb2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63acd0ac-41d1-4156-b700-28671a1777d5', 'Prices charged for buying bottled water', false, 'a8a4486f-1fab-4802-8d6e-b2d31de7eb2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e19db58-92ae-42e4-a7ad-9d45ace976fe', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Consider four environmental conservation initiatives in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd664a61-3a67-4493-8386-be45c872a43d', 'Grassroots non-violent Gandhian eco-activism led by indigenous communities and women fighting to safeguard forest ecosystems and ecological livelihoods', true, '3e19db58-92ae-42e4-a7ad-9d45ace976fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c85a5c6-5132-403b-b41d-5b3475010135', 'They were corporate advertising campaigns for wood companies', false, '3e19db58-92ae-42e4-a7ad-9d45ace976fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f641bdc-5a25-47f5-8499-7c52016f529b', 'They were government projects to cut down forests', false, '3e19db58-92ae-42e4-a7ad-9d45ace976fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75bd081a-2c1c-4693-816b-6377828dec3c', 'They were sports clubs', false, '3e19db58-92ae-42e4-a7ad-9d45ace976fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87d94994-382c-44d7-93f9-4818500eaa44', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What is the ''Loss and Damage Fund'' established at COP27 (Sharm el-Sheikh) and operationalized at COP28 (Dubai)?', 'The Loss and Damage Fund operationalizes climate justice: compensating climate-vulnerable global South nations for irreversible climate shocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0adaa0a6-71ae-48c3-8138-e90cf091cca4', 'A dedicated international climate finance facility where historical polluting developed nations provide financial assistance to vulnerable developing countries suffering irreversible climate disasters (floods, droughts, sea-level rise)', true, '87d94994-382c-44d7-93f9-4818500eaa44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a460fdd6-30b1-4c13-9654-0cd10bad3c58', 'A fund to pay insurance for broken cars', false, '87d94994-382c-44d7-93f9-4818500eaa44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f26898b-8501-469f-beea-cda4b4c02ff6', 'A tax on tourist travel', false, '87d94994-382c-44d7-93f9-4818500eaa44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('160cac41-fa2e-4c29-b6f5-0f2e4f837345', 'A bank loan for oil companies', false, '87d94994-382c-44d7-93f9-4818500eaa44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81300b05-39af-4ca6-acc8-0405fff52388', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Why are ''Mangrove Ecosystems'' (like the Sundarbans) hailed as super-heroes of coastal climate resilience?', 'Mangroves are premier Blue Carbon sinks and bio-shields against coastal erosion, storm surges, and tsunami devastation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fac2b73-4a7a-4416-a25c-23502a30a1a1', 'They store up to 5 times more carbon per hectare than tropical rainforests (Blue Carbon), buffer coastal communities against ferocious cyclone surges and tsunamis, and serve as vital nursery grounds for marine biodiversity', true, '81300b05-39af-4ca6-acc8-0405fff52388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2dd01c3-9799-4bb7-a412-26b2c9d62061', 'Because they produce pure gold crystals in their roots', false, '81300b05-39af-4ca6-acc8-0405fff52388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ffbc406-0a91-4a55-b58d-10805228d987', 'Because they can walk across oceans', false, '81300b05-39af-4ca6-acc8-0405fff52388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b50b2358-be0b-4bd7-8a3b-bcbd5bfadaae', 'Because they prevent rain from falling', false, '81300b05-39af-4ca6-acc8-0405fff52388');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15cadd15-adf6-470e-9f1a-71cf749a4c2b', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What is ''Ecological Footprint'' articulated by Mathis Wackernagel and William Rees?', 'Ecological footprint measures human demand on natural capital versus planetary biocapacity (calculated annually on Earth Overshoot Day).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('653ca3ae-b898-4fad-8b79-86e4b6f2c92b', 'A metric that compares human consumption of natural resources against the Earth''s biocapacity to regenerate those resources and absorb our waste; currently, humanity consumes resources at the rate of 1.7 Earths', true, '15cadd15-adf6-470e-9f1a-71cf749a4c2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbd457b5-ec21-4296-841c-334e1bdedecc', 'The weight of human feet on soil', false, '15cadd15-adf6-470e-9f1a-71cf749a4c2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('941a0fda-f981-4884-8ad7-13ce2a82b380', 'The number of trees planted in a garden', false, '15cadd15-adf6-470e-9f1a-71cf749a4c2b');
