INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31b0c699-ebf9-4e1b-ae14-e59b1e8f1f20', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What supreme planetary ethical manifesto concludes the General Knowledge curriculum in Chapter 12?', 'Chapter 12 culminates in the universal ethic of ecological stewardship: harmonizing human civilization with planetary boundaries for intergenerational sustainability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f854dcb7-d11e-4c70-89e2-db3082bdea3a', 'We do not inherit the Earth from our ancestors; we borrow it from our children. Sustainable development demands that human economic ambition harmonize with the finite ecological boundaries of our living planet, fostering intergenerational justice and reverence for all life', true, '31b0c699-ebf9-4e1b-ae14-e59b1e8f1f20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aec5c9f3-3fd8-4b19-97cd-8767f39d0331', 'That human beings should exploit every natural resource until nothing is left', false, '31b0c699-ebf9-4e1b-ae14-e59b1e8f1f20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b82120a5-8b12-4ce2-99b6-118aa4c9eb9b', 'That technology eliminates the need for nature', false, '31b0c699-ebf9-4e1b-ae14-e59b1e8f1f20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('852477b5-5063-4517-bed8-6cd8e545beab', 'That environmental problems will solve themselves automatically', false, '31b0c699-ebf9-4e1b-ae14-e59b1e8f1f20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62f7a2ed-4add-431b-acb5-9eebbfaf7718', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'What is the seasonal migration of pastoral nomadic people with their livestock between highland summer pastures and lowland winter valleys called?', 'Transhumance is the seasonal movement of pastoralists with their herds in response to seasonal changes in mountain pastures and weather.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a1582b0-529a-4f4f-9b23-57b530240d5c', 'Transhumance (e.g. Gujjars and Bakarwals)', true, '62f7a2ed-4add-431b-acb5-9eebbfaf7718');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf69e54d-daff-4d83-95d3-578156818bfd', 'Urbanization', false, '62f7a2ed-4add-431b-acb5-9eebbfaf7718');
