INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9fb87f1-1c62-46d3-9bda-9715a005f117', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which highway project in India connects the four major metropolitan mega-cities—Delhi, Mumbai, Chennai, and Kolkata—with 4/6-lane expressways?', 'The Golden Quadrilateral (5,846 km) connects Delhi, Mumbai, Chennai, and Kolkata, forming the backbone of India''s arterial expressway network.', NOW()) ON CONFLICT DO NOTHING;
