INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc8eac73-f554-4a4d-a00d-9cccb918a14b', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which two famous nomadic pastoral tribes inhabit the Sahara Desert, rearing camels, goats, sheep, and horses for milk, hides, and hair?', 'The Bedouins and Tuaregs are traditional nomadic pastoralists of the Sahara, wearing heavy robes to protect against sandstorms and blazing heat.', NOW()) ON CONFLICT DO NOTHING;
