INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5039e064-342b-47b5-ba50-01cdfa41ea1e', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which endangered animal found in Ladakh, the ''Chiru'' (Tibetan Antelope), is hunted for its fine, light, and exceptionally warm wool called:', 'The Chiru or Tibetan antelope yields ''Shahtoosh''—the world''s finest, lightest, and warmest wool, now strictly protected by wildlife laws.', NOW()) ON CONFLICT DO NOTHING;
