INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('235bb3f5-c984-4861-9fee-579f0ee6845e', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which domestic animal of Ladakh provides rich milk for making local butter and cheese (''Chhurpi''), meat, and thick hair for weaving tents and boots?', 'The shaggy-haired Yak is the indispensable beast of burden in high-altitude Ladakh, supplying milk for butter/cheese, wool, and draught power.', NOW()) ON CONFLICT DO NOTHING;
