INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4d9d424-c644-4924-9126-47c27ef63c74', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'What are the traditional Buddhist monasteries with their unique prayer halls and colorful stupas found across Ladakh called?', 'Gompas (like Hemis, Thiksey, Shey, and Lamayuru) are iconic fortified Buddhist monasteries that form the spiritual and cultural heart of Ladakh.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59b76cae-1fa7-4239-a048-30cc56ce7b8c', 'Gompas (e.g. Hemis, Thiksey, Shey, Lamayuru)', true, 'c4d9d424-c644-4924-9126-47c27ef63c74');
