INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39ddffe2-12a6-4c8a-8477-c2db4ac7b9c9', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Why does Ladakh experience such EXTREME ARIDITY (Dryness) and receive as little as 10 cm of rainfall annually?', 'The colossal Himalayan barrier intercepts monsoon clouds, casting the trans-Himalayan Ladakh plateau into an arid rain-shadow zone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b57b81e-6a59-46d2-a9b4-a1ff90afea07', 'Ladakh lies in the ''RAIN-SHADOW'' of the towering Great Himalayas, which block the moisture-laden southwest monsoon winds from entering the region', true, '39ddffe2-12a6-4c8a-8477-c2db4ac7b9c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e11b8f78-5bfa-4b5d-b848-ce664833bc70', 'Because clouds are too heavy to fly over mountains', false, '39ddffe2-12a6-4c8a-8477-c2db4ac7b9c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d17a0ba3-3077-452b-aab2-d5cc920011cc', 'Because there is no sun in Ladakh', false, '39ddffe2-12a6-4c8a-8477-c2db4ac7b9c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b750611-678d-47da-b540-112b414aa3b5', 'Because winds blow backwards', false, '39ddffe2-12a6-4c8a-8477-c2db4ac7b9c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d71c5ecb-9c19-40cd-aa1d-f12179b24efe', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is an ''OASIS'' in the desert landscape, such as the famous Tafilalet Oasis in Morocco?', 'Deflation hollows reaching groundwater create oases: lush green centers of date-palm agriculture and trading caravan towns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd6dfe83-9549-4c60-8774-683397364deb', 'A fertile, lush depression in a desert where underground aquifer water reaches the surface, supporting date palms, crops, and human settlements', true, 'd71c5ecb-9c19-40cd-aa1d-f12179b24efe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('779940b3-2301-4830-b65e-6ab246ee720e', 'A mirage that disappears when approached', false, 'd71c5ecb-9c19-40cd-aa1d-f12179b24efe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0e74dfd-e339-4635-b8c9-ea90249b39c2', 'A mountain of gold in the sand', false, 'd71c5ecb-9c19-40cd-aa1d-f12179b24efe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a123770f-5e93-4afe-867a-399ab599d5e3', 'A dry salt flat with no water', false, 'd71c5ecb-9c19-40cd-aa1d-f12179b24efe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc436400-5952-46fa-997a-eacce8077f42', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is the difference between a ''COMPACT SETTLEMENT'' and a ''SCATTERED SETTLEMENT''?', 'Compact settlements thrive in nucleated agricultural plains, whereas scattered homesteads characterize rugged mountain and desert terrains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce444fb9-d6d5-48ba-b80c-879f84e75b3e', 'A compact settlement consists of closely built dwellings on flat fertile plains ; a scattered settlement has houses spaced far apart over vast hilly, forested, or desert tracts', true, 'bc436400-5952-46fa-997a-eacce8077f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a1e5940-66dc-4fd2-a4d3-4f60e079a1c0', 'Compact settlements have no roads', false, 'bc436400-5952-46fa-997a-eacce8077f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41c66a83-fe1f-4e45-bfb7-22510cc8a7e8', 'Scattered settlements are built on boats', false, 'bc436400-5952-46fa-997a-eacce8077f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34b4b6f5-df5b-4b2f-8c00-5f5149155e4a', 'There is no difference', false, 'bc436400-5952-46fa-997a-eacce8077f42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e0da1ac-bbc2-4dac-b3b8-6f045f2d6e1f', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Why are WATERWAYS the cheapest and most energy-efficient mode of transport for carrying heavy and bulky goods across long distances?', 'Hydrodynamic buoyancy and low fluid friction make maritime and inland freight shipping the most cost-effective bulk transport mode.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74d807b1-d198-4db6-8438-7ce310f6a5e3', 'Water provides immense natural buoyancy with minimal surface friction, requiring significantly less fuel energy per ton-kilometer than road or air transport', true, '3e0da1ac-bbc2-4dac-b3b8-6f045f2d6e1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24ec2897-8ec5-4e3e-b0b5-c26abfab5c4b', 'Because ships do not require any fuel', false, '3e0da1ac-bbc2-4dac-b3b8-6f045f2d6e1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1126a25e-0f84-4907-a566-efde6d7a479f', 'Because water flows in all directions automatically', false, '3e0da1ac-bbc2-4dac-b3b8-6f045f2d6e1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba4037bd-8944-4986-bf10-637788e7aaf8', 'Because water transport is faster than airplanes', false, '3e0da1ac-bbc2-4dac-b3b8-6f045f2d6e1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dff63b5a-637d-4388-9556-30f8d3233632', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Which artificial waterway opened in 1869 in Egypt, connecting the Mediterranean Sea to the Red Sea, revolutionizing international maritime shipping between Europe and Asia?', 'The Suez Canal slashed maritime transit distance between Europe and India/Asia by over 7,000 km, bypassing the Cape of Good Hope.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81159e55-6fd4-4d15-a728-a41ad16c45e3', 'The Suez Canal', true, 'dff63b5a-637d-4388-9556-30f8d3233632');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd9d2843-edad-450b-9324-b5db2cc228ff', 'The Panama Canal', false, 'dff63b5a-637d-4388-9556-30f8d3233632');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b223787-3bbb-4566-bb02-20dbb21e6042', 'The Kiel Canal', false, 'dff63b5a-637d-4388-9556-30f8d3233632');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9adbffdf-0fd9-41c8-bb7a-fc20af5a615c', 'The Erie Canal', false, 'dff63b5a-637d-4388-9556-30f8d3233632');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40e8eb43-0572-4eb7-9a5b-f8592c93d85c', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Which engineering marvel canal opened in 1914, cutting across the Isthmus of Panama to connect the Atlantic Ocean directly to the Pacific Ocean?', 'The Panama Canal with its lock system eliminated the hazardous 15,000 km voyage around South America''s Cape Horn.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de56fd8d-b861-44bf-b570-e96db1d5c772', 'The Panama Canal', true, '40e8eb43-0572-4eb7-9a5b-f8592c93d85c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('996ea700-7d6f-4d87-9089-bb4a2549eb74', 'The Suez Canal', false, '40e8eb43-0572-4eb7-9a5b-f8592c93d85c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13c5befe-9c1f-4053-b842-14e72ca74400', 'The Corinth Canal', false, '40e8eb43-0572-4eb7-9a5b-f8592c93d85c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f4c511b-45ea-4572-9b89-a16f57ef32e2', 'The Grand Canal', false, '40e8eb43-0572-4eb7-9a5b-f8592c93d85c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0571766f-327e-40bc-a872-5d2a39ef11f8', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is National Waterway 1 (NW-1) in India?', 'NW-1 is India''s premier inland waterway along the Ganga, connecting Prayagraj, Varanasi, Patna, and Haldia port.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54b160d3-02b6-4dbf-bc9e-2510c5d002b8', 'The Ganga-Bhagirathi-Hooghly river system stretching 1,620 km from Prayagraj (Allahabad) to Haldia', true, '0571766f-327e-40bc-a872-5d2a39ef11f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5f033f9-28c3-43d8-80c2-348c637cd8a9', 'The Brahmaputra river from Sadiya to Dhubri', false, '0571766f-327e-40bc-a872-5d2a39ef11f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81343b1d-47d9-4844-bfd6-2cd3635695da', 'The Godavari river canal', false, '0571766f-327e-40bc-a872-5d2a39ef11f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('899edd64-c36b-4141-935b-02b756cdb251', 'The Kerala backwaters', false, '0571766f-327e-40bc-a872-5d2a39ef11f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb4f0af3-705e-4d51-99d0-3b9b4d4c1403', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What agricultural crops are cultivated during the brief, pleasant summer season in the irrigated oasis valleys of Ladakh?', 'During the sunny summer, glacial meltwater channels irrigate terraced fields for barley, peas, potatoes, apricots, and walnuts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f84dc709-5be5-4ed0-a4cc-29b96bd0c39f', 'Barley, Peas, Wheat, Potatoes, Turnips, Apricots, and Walnuts', true, 'eb4f0af3-705e-4d51-99d0-3b9b4d4c1403');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14049838-13a3-4d13-8614-c2802b65a887', 'Rice, Sugarcane, and Jute', false, 'eb4f0af3-705e-4d51-99d0-3b9b4d4c1403');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4811719-7d53-46a9-9c3f-6b72be3b00ab', 'Tea, Coffee, and Rubber', false, 'eb4f0af3-705e-4d51-99d0-3b9b4d4c1403');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaab2f51-db39-4d41-a952-c408457970f4', 'Cotton and Tobacco', false, 'eb4f0af3-705e-4d51-99d0-3b9b4d4c1403');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ef505e6-ae2a-4cfc-a25e-67812e87e404', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is ''Pashmina Wool'' for which Ladakh and Kashmir are world-renowned?', 'High-altitude Changthangi mountain goats grow an ultra-fine underfleece to endure -40°C winters, spun into exquisite Pashmina shawls.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('098b032e-0d44-4a38-a422-7430e35adffd', 'An exceptionally fine, soft, and warm undercoat wool combed from mountain goats (Capra hircus) raised at altitudes above 4,000 metres', true, '2ef505e6-ae2a-4cfc-a25e-67812e87e404');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff316e42-c644-48d1-be79-462928ca2378', 'Wool obtained from camels', false, '2ef505e6-ae2a-4cfc-a25e-67812e87e404');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a541c99-d0cd-437f-88ae-76ac1d461778', 'Synthetic nylon fiber', false, '2ef505e6-ae2a-4cfc-a25e-67812e87e404');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('516efed3-4bc6-411b-aea3-84dc1b8c7adb', 'Wool sheared from desert sheep', false, '2ef505e6-ae2a-4cfc-a25e-67812e87e404');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('814248c8-29e2-4c17-950f-650ae2cccf33', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'How has the development of the MANALI-LEH HIGHWAY transformed accessibility to Ladakh?', 'The Manali-Leh strategic highway traverses four formidable Himalayan passes, linking the Kullu valley directly to Leh.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99b91e22-c751-469d-8b28-e904e5ef1867', 'It crosses four high mountain passes (Rohtang La, Baralacha La, Lungalacha La, Tanglang La) at elevations above 4,000 metres, opening Ladakh to trade, military logistics, and global tourism during summer', true, '814248c8-29e2-4c17-950f-650ae2cccf33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e1b3877-7e25-46c0-8181-e71d2e58c66c', 'It is an underground metro railway tunnel', false, '814248c8-29e2-4c17-950f-650ae2cccf33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b66012d0-e580-44e5-b9fc-1214977af7ee', 'It is a canal for large ships', false, '814248c8-29e2-4c17-950f-650ae2cccf33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5d5f4e5-bf96-443c-b721-97195191e3ff', 'It is a road built on ice that melts in winter', false, '814248c8-29e2-4c17-950f-650ae2cccf33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5e5d11b-9048-49c3-93a8-ff224e926c44', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is the capital and largest administrative and commercial town of the Union Territory of Ladakh?', 'Leh is the historic capital of Ladakh, situated at 3,500 m altitude, featuring the 17th-century nine-storey Leh Palace.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd7b0736-22dc-44df-9cab-2159898cc775', 'Leh (connected by road and Kushok Bakula Rimpochee Airport)', true, 'e5e5d11b-9048-49c3-93a8-ff224e926c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('622c4b56-4421-4784-8209-10e0148732f5', 'Kargil', false, 'e5e5d11b-9048-49c3-93a8-ff224e926c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8008bea3-ee25-4b37-91b9-3f9e775fe852', 'Diskit', false, 'e5e5d11b-9048-49c3-93a8-ff224e926c44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4834f68-4226-4e95-ade7-bd92a569f493', 'Padum', false, 'e5e5d11b-9048-49c3-93a8-ff224e926c44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c04d42b8-a7af-43d9-8637-f84310ab7dcd', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Why do the people of the Sahara Desert wear loose, flowing, heavy robes and head coverings?', 'Loose, layered woolen and cotton robes create an insulative microclimate, shielding desert dwellers from extreme thermal radiation and sandstorms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72ffa2f9-f548-44ba-b6d5-b60463f6e2fb', 'To protect their skin and eyes from fierce scorching desert heat, drying ultraviolet sun rays, and blinding dust/sand storms', true, 'c04d42b8-a7af-43d9-8637-f84310ab7dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d328f0d-e26b-43b6-8acd-dd5d5022d47d', 'Because they do not have modern clothes', false, 'c04d42b8-a7af-43d9-8637-f84310ab7dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac63fc65-243d-42f7-8e69-26a2d783de7b', 'Because the government ordered them to wear robes', false, 'c04d42b8-a7af-43d9-8637-f84310ab7dcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02860719-975a-47c0-b5b0-75a6709fcc5e', 'To look taller on camels', false, 'c04d42b8-a7af-43d9-8637-f84310ab7dcd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('963115ff-ac95-42cf-9124-336e4f3a6738', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What remarkable adaptation of human ecology is practiced by the people of Ladakh in managing their scarce resources?', 'Ladakhi ecological culture is a global paradigm of sustainable frugality: zero-waste recycling and sacred stewardship of scarce water and biomass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('064ec06f-8fb3-459a-bf52-e20a3045e672', 'Extreme reverence for nature and meticulous conservation: not a single drop of water or scrap of fuel/wood is wasted, recycling all organic matter in harmony with the fragile environment', true, '963115ff-ac95-42cf-9124-336e4f3a6738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82e7e1e2-b103-4f7d-9e8b-75cefbaf059f', 'Cutting down all trees for firewood', false, '963115ff-ac95-42cf-9124-336e4f3a6738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43dfd9b1-df21-4f3a-898c-75e48fb6a472', 'Diverting rivers into other countries', false, '963115ff-ac95-42cf-9124-336e4f3a6738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc44f4f7-226d-40ad-8980-cc834f327fea', 'Living without any shelter in winter', false, '963115ff-ac95-42cf-9124-336e4f3a6738');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9e2727d-c663-44b5-a19f-ced45beda23b', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What role do modern communication SATELLITES play in human connectivity and resource management?', 'Geostationary and low-Earth orbit satellites power global ICT connectivity, remote sensing earth observation, and real-time meteorology.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f540736-7022-45b6-a2e0-8a646828641c', 'They enable instant global cellular telecommunications, internet routing, television broadcasting, weather forecasting, disaster warnings, and mineral/groundwater mapping', true, 'f9e2727d-c663-44b5-a19f-ced45beda23b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b07aca3-6a38-43bd-aacc-2fcb485fd708', 'They take tourists to outer space for holidays', false, 'f9e2727d-c663-44b5-a19f-ced45beda23b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbfd040c-f838-4c32-b297-06b92f23b928', 'They shine bright lights to replace street lamps', false, 'f9e2727d-c663-44b5-a19f-ced45beda23b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c15804b-bc52-4257-882a-bf6ce24d2450', 'They make rain fall on deserts', false, 'f9e2727d-c663-44b5-a19f-ced45beda23b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbee520b-762b-4351-b8d9-4bfb4bd9129e', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is ''Mass Media'' in modern human society?', 'Mass media encompasses print and digital broadcast communications transmitting news, culture, and democratic discourse to millions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9feab5d-54cf-4714-9b94-e649b88f250b', 'Means of communication that reach millions of people simultaneously across the nation and globe, such as Newspapers, Radio, Television, and the Internet', true, 'bbee520b-762b-4351-b8d9-4bfb4bd9129e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74d282de-cecc-4b70-af4d-d93a823865ff', 'Private phone calls between two friends', false, 'bbee520b-762b-4351-b8d9-4bfb4bd9129e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e79fa6b-7f7d-40f7-be0a-0eb28a85998f', 'Personal handwritten diaries', false, 'bbee520b-762b-4351-b8d9-4bfb4bd9129e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94fbd92c-a01c-4ab8-bda6-9e4fbbe785c3', 'Whispering in a classroom', false, 'bbee520b-762b-4351-b8d9-4bfb4bd9129e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56025c36-ca5d-47ec-aa47-1e3ad59ade3d', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Why do houses in heavy-rainfall regions (like Assam) have STEEPLY SLOPING ROOFS and are built on raised STILTS (Piles)?', 'Vernacular stilt architecture (Chang Ghar) prevents flood inundation, while sloping thatch/tin roofs facilitate rapid storm drainage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c0a648c-678c-4844-87bf-a4491bbdb76a', 'Steep roofs allow torrential rainwater to drain off rapidly, and raised wooden/bamboo stilts protect the living rooms from seasonal floodwaters and wild animals', true, '56025c36-ca5d-47ec-aa47-1e3ad59ade3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b149fd-22cf-45fc-80dd-7095d83d6847', 'To make houses look taller than trees', false, '56025c36-ca5d-47ec-aa47-1e3ad59ade3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77440daf-1232-410a-8fae-2365141856ea', 'Because flat roofs are illegal in Assam', false, '56025c36-ca5d-47ec-aa47-1e3ad59ade3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7b9c6e8-046f-400e-9bd1-0fec7129e8c2', 'To catch more wind during storms', false, '56025c36-ca5d-47ec-aa47-1e3ad59ade3d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0c6af7b-2288-4b0c-91ba-93eb41048267', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('246f476d-34c3-4c08-baa4-0629ac994ffa', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'e0c6af7b-2288-4b0c-91ba-93eb41048267');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf550b95-1d07-40de-8e0e-4071b2028675', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'e0c6af7b-2288-4b0c-91ba-93eb41048267');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9e1d144-6a7c-43c9-b4cf-1e37c186df63', '(A) is true, but (R) is false.', false, 'e0c6af7b-2288-4b0c-91ba-93eb41048267');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17e9812a-5e60-4b2e-b641-6501db38bae3', '(A) is false, but (R) is true.', false, 'e0c6af7b-2288-4b0c-91ba-93eb41048267');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('857fd269-1db2-4055-b9ae-d25830030ffe', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Spot the IMPOSTER in the following comparative geographical features of the SAHARA (Hot Desert) vs LADAKH (Cold Desert):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17cc9c6f-73d1-46d6-b3e5-b24a1ec9ac51', 'Feature 1', false, '857fd269-1db2-4055-b9ae-d25830030ffe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b282f716-dd38-4aab-bd21-e77f1e33e3bf', 'Feature 2', false, '857fd269-1db2-4055-b9ae-d25830030ffe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11174e6e-22b7-4a67-a509-971947c464ab', 'Feature 3', false, '857fd269-1db2-4055-b9ae-d25830030ffe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93feef86-015c-41d5-913e-dc7572bd1b0c', 'Feature 4 (Ladakh is a high-altitude Himalayan COLD ARID DESERT with stunted alpine scrub, NOT a tropical rainforest with chimpanzees)', true, '857fd269-1db2-4055-b9ae-d25830030ffe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c87bca4b-5199-422d-a3e2-5a5fc9bf0fc1', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Analyze the environmental impact of modern mass tourism on the fragile ecology of Ladakh:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cab4495a-5ab4-4344-ace7-0b4843caa110', 'Massive tourist influx causes severe groundwater depletion for luxury hotels, diesel vehicular pollution, plastic waste accumulation, and strains the traditional subsistence agriculture of Ladakhi villages', true, 'c87bca4b-5199-422d-a3e2-5a5fc9bf0fc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61721200-fcb9-4125-b4b5-853019fae142', 'Tourism has turned Ladakh into a hot tropical swamp', false, 'c87bca4b-5199-422d-a3e2-5a5fc9bf0fc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('278fbc27-3982-4f5e-8ec1-6fb3174bda09', 'Tourism has completely stopped all cultural festivals', false, 'c87bca4b-5199-422d-a3e2-5a5fc9bf0fc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe2a3064-41fc-4705-a40a-7c736f457e96', 'Tourists have removed all the Himalayan mountains', false, 'c87bca4b-5199-422d-a3e2-5a5fc9bf0fc1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5a5aa09-d215-4629-992a-f98250e504ea', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Match Column I (Major Global Transport Routes / Channels) with Column II (Geographic Connections & Strategic Significance):
(a) Trans-Siberian Railway -> (i) St. Petersburg (Baltic) to Vladivostok (Pacific) across 9,289 km
(b) Suez Canal              -> (ii) Mediterranean Sea to Red Sea, slashing Euro-Asian maritime route
(c) Panama Canal            -> (iii) Atlantic Ocean to Pacific Ocean across the Central American Isthmus
(d) Golden Quadrilateral    -> (iv) 5,846 km expressway connecting Delhi, Mumbai, Chennai, Kolkata', 'Trans-Siberian = Russia rail; Suez = Med-Red sea; Panama = Atlantic-Pacific; Golden Quad = India mega-corridor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6977c1a2-3a55-4f58-a3d8-024176d8f916', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'b5a5aa09-d215-4629-992a-f98250e504ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c167754-a978-4efb-bb89-693852923966', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'b5a5aa09-d215-4629-992a-f98250e504ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6d1fa45-d937-410f-a015-ef8b7e2ec11a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b5a5aa09-d215-4629-992a-f98250e504ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7789091d-ff56-4471-b468-247445cb9388', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b5a5aa09-d215-4629-992a-f98250e504ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89b9fc5d-5bf5-48d0-8346-40819f85a790', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Read the statements regarding extreme desert adaptations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7360c5c-edaf-47f6-bc26-eb138a40a844', 'Statements 1 and 2 only', true, '89b9fc5d-5bf5-48d0-8346-40819f85a790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86db1b83-c143-4a46-a59c-2944ab0d0992', 'Statements 2 and 3 only', false, '89b9fc5d-5bf5-48d0-8346-40819f85a790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5570a40a-0fbf-4324-8f15-6e8f708e18a2', 'Statements 1 and 3 only', false, '89b9fc5d-5bf5-48d0-8346-40819f85a790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0e5fb83-78ea-4f7a-adb6-f3b70a7d1daa', 'All Statements 1, 2, and 3', false, '89b9fc5d-5bf5-48d0-8346-40819f85a790');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('171d4fd8-0e8b-454f-a24a-de4eacd9f30b', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'How did the invention of Containerization (standardized steel Intermodal Shipping Containers) revolutionize 20th-century global trade?', 'Malcom McLean''s containerization innovation enabled frictionless intermodal logistics, driving post-war economic globalization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7108536e-288b-43ea-b008-b02ddc1d49c0', 'Standardized 20-foot and 40-foot containers allow seamless mechanized transfer of freight between cargo ships, trains, and trucks without manual re-handling, slashing global freight shipping costs by over 90%', true, '171d4fd8-0e8b-454f-a24a-de4eacd9f30b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4deafc9-1581-4046-ae71-d67303c2a47e', 'Containers made ships float in the air', false, '171d4fd8-0e8b-454f-a24a-de4eacd9f30b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7f6b669-1250-4407-9fd4-32fd174c9b71', 'Containers eliminated the need for ports', false, '171d4fd8-0e8b-454f-a24a-de4eacd9f30b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('608a6fb1-fc87-42a9-8817-39ef12231506', 'Containers are used only for transporting gold', false, '171d4fd8-0e8b-454f-a24a-de4eacd9f30b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2264544a-b5a7-4ba3-b94d-eea658f9ef6e', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'What is the cultural and religious significance of the annual ''Hemis Festival'' in Ladakh?', 'The Hemis Tsechu festival honors Guru Padmasambhava with mystical tantric masked cham dances depicting the triumph of dharma over demonic forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0ba7ad3-5563-4a79-ad4c-7664c50b1611', 'A vibrant Buddhist festival celebrated at Hemis Gompa commemorating the birth anniversary of Guru Padmasambhava with sacred masked ''Chham'' dances and traditional music', true, '2264544a-b5a7-4ba3-b94d-eea658f9ef6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fc1bedb-8c83-4a7c-92e4-f172f3d7e05e', 'A boat race festival on the Indus river', false, '2264544a-b5a7-4ba3-b94d-eea658f9ef6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38d94a87-79a3-4eca-aaf1-78093f63d9ef', 'A harvest festival celebrating mangoes', false, '2264544a-b5a7-4ba3-b94d-eea658f9ef6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04692bd6-c042-4329-8bb5-44043ec5b78f', 'A horse race across the Himalayas', false, '2264544a-b5a7-4ba3-b94d-eea658f9ef6e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51ffbb22-5e5b-4d46-9244-85c2b74103fd', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Consider four types of human settlements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b6df687-9aff-440b-a714-1fefc94872de', 'Topography, water availability, agricultural land fertility, and climate constraints dictating spatial human organization', true, '51ffbb22-5e5b-4d46-9244-85c2b74103fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71d8fc7c-bd4c-4a9d-9179-2d4bf84308c3', 'Government orders telling people where to sleep', false, '51ffbb22-5e5b-4d46-9244-85c2b74103fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93648ca4-32db-4bb6-9f33-907fbe030773', 'The color of local soil only', false, '51ffbb22-5e5b-4d46-9244-85c2b74103fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24bf8fcf-1822-4ef7-a421-dd0bfdf7f266', 'Random chance with no geographic logic', false, '51ffbb22-5e5b-4d46-9244-85c2b74103fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('849fa39c-c092-46b2-a8b3-6120afca2908', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'How did the ancient ''Silk Route'' passing through the high Karakoram passes of Ladakh historically connect India with Central Asia, Tibet, and China?', 'Leh was a pivotal crossroad on the trans-Himalayan Silk Road network, linking Kashmir and Punjab to Yarkand, Kashgar, and Lhasa.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3593ef4-ccc8-439e-a981-0eb9647a6922', 'Leh served as a bustling entrepôt caravan trade hub where Indian merchants traded spices, cotton, and dyes for Central Asian silk, raw wool, charas, and turquoise stones', true, '849fa39c-c092-46b2-a8b3-6120afca2908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('770c9ac0-5b8b-4ad7-b208-4b6684116278', 'Trade was carried out using submarine boats', false, '849fa39c-c092-46b2-a8b3-6120afca2908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7c7e115-c1a8-4403-9b86-da6364925e4c', 'It was a modern railway line built 2,000 years ago', false, '849fa39c-c092-46b2-a8b3-6120afca2908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42e64acf-8868-497d-b353-a7cc3ad0bfbf', 'It was an air route for flying carpets', false, '849fa39c-c092-46b2-a8b3-6120afca2908');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f3fd8ee-2726-445c-9dd8-bf4914fd1438', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Why is ''Information Highway'' (High-Speed Fiber-Optic Broadband & 5G Satellite Internet) considered the modern equivalent of 19th-century railway networks?', 'Broadband data infrastructure is the 21st-century neural network of global capitalism, accelerating frictionless virtual commerce, research, and communication.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e82ca986-eb09-4c74-8a04-59663b2b9124', 'Just as railways revolutionized the physical transport of freight and labor during the Industrial Revolution, high-speed digital networks transport massive data, finance, commerce, and knowledge instantly across the globe', true, '4f3fd8ee-2726-445c-9dd8-bf4914fd1438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2676cf96-4917-4b42-9947-91820acd3a5a', 'Because fiber-optic cables are made of iron rails', false, '4f3fd8ee-2726-445c-9dd8-bf4914fd1438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d47cd5ad-c25b-4189-b574-9abb31a23cc4', 'Because internet cables carry physical train cars', false, '4f3fd8ee-2726-445c-9dd8-bf4914fd1438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae29da54-49e9-4771-a664-e7319af5731b', 'Because internet was invented in the 19th century', false, '4f3fd8ee-2726-445c-9dd8-bf4914fd1438');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f1c71c9-f79f-4305-a3f6-ed2c468cfd17', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'What is the engineering challenge and significance of the ''Atal Tunnel'' (Rohtang) and upcoming ''Zojila Tunnel'' in the Himalayan transport network?', 'Atal Tunnel (9.02 km) and Zojila Tunnel (14.2 km) conquer extreme mountain geography, ensuring year-round strategic and socioeconomic connectivity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a384374d-e21b-431e-bc09-457799e623ca', 'They provide all-weather, year-round strategic military and civilian road connectivity beneath avalanche-prone high passes, ending months of winter isolation for Ladakh and Lahaul-Spiti', true, '4f1c71c9-f79f-4305-a3f6-ed2c468cfd17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70cbd1e2-d4ba-47f1-850d-a6beff1e9c58', 'They are built to store water', false, '4f1c71c9-f79f-4305-a3f6-ed2c468cfd17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fc96e27-0e40-4203-a71b-c8e485b5857e', 'They are giant shopping malls inside mountains', false, '4f1c71c9-f79f-4305-a3f6-ed2c468cfd17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ac106fe-4a90-42c9-81b1-c2945c918a63', 'They were constructed for tourist trains to Europe', false, '4f1c71c9-f79f-4305-a3f6-ed2c468cfd17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5d9910d-2211-40af-9cb1-45520f4d1dd9', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'What grand humanistic and geographic perspective concludes the NCERT Class 7 Social Science curriculum in Chapter 12?', 'Chapter 12 concludes the Class 7 Social Science curriculum by synthesizing human ecological adaptability, technological connectivity, and sustainable biocultural conservation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74f9446b-024b-49d5-a2e5-0256923703e4', 'Humanity is an integral part of the living Earth—our settlements, global transport networks, and communication technologies reflect our creative adaptability, demanding that we live in harmonious balance with natural ecosystems, respecting cultural diversity and conserving planetary resources for future generations', true, 'e5d9910d-2211-40af-9cb1-45520f4d1dd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5c9e96c-5158-489d-8dc2-638783f9e60a', 'That human beings should conquer and destroy all natural environments', false, 'e5d9910d-2211-40af-9cb1-45520f4d1dd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9025ede0-4cf3-4c73-86c8-e544bc76197a', 'That deserts are useless wastelands that have no culture or life', false, 'e5d9910d-2211-40af-9cb1-45520f4d1dd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c351d83-ecb3-4207-a846-68afe3db27f9', 'That all humans should live in identical cities', false, 'e5d9910d-2211-40af-9cb1-45520f4d1dd9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cdf9c5b-9c19-4cfe-bd58-1f2b77a05996', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'सार्थक शब्दों का वह व्यवस्थित एवं क्रमबद्ध समूह जो किसी विचार या भाव को पूर्ण रूप से स्पष्ट करता है, क्या कहलाता है?', 'वाक्य: सार्थक शब्दों का व्यवस्थित एवं व्याकरण सम्मत समूह जिससे वक्ता का पूर्ण अभिप्राय स्पष्ट हो।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54efebef-3f8d-46c0-849d-78dbad78953a', 'वाक्य (Sentence)', true, '3cdf9c5b-9c19-4cfe-bd58-1f2b77a05996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eecb28e3-4782-433f-a6ad-9f8e1390f28b', 'वर्णमाला', false, '3cdf9c5b-9c19-4cfe-bd58-1f2b77a05996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14e52421-50e6-4367-9d11-54ccc46debf5', 'शब्दकोश', false, '3cdf9c5b-9c19-4cfe-bd58-1f2b77a05996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cb7d421-fcbe-4f98-bf6b-5b2ae7b35b9a', 'पदबंध मात्र', false, '3cdf9c5b-9c19-4cfe-bd58-1f2b77a05996');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5562d8d2-08fa-4676-bfe1-65891a3d85d7', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'व्याकरण की दृष्टि से वाक्य के मुख्य रूप से दो अनिवार्य अंग कौन-से होते हैं?', 'वाक्य के दो अनिवार्य घटक (अंग) होते हैं: उद्देश्य (जिसके बारे में बात हो) और विधेय (उद्देश्य के बारे में जो कहा जाए)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edd80c4f-b871-4ad5-9c8a-6c660f55b563', '1. उद्देश्य (Subject) और 2. विधेय (Predicate)', true, '5562d8d2-08fa-4676-bfe1-65891a3d85d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acd34474-f7f0-4e25-aabc-154b834f27a1', '1. संज्ञा और 2. सर्वनाम', false, '5562d8d2-08fa-4676-bfe1-65891a3d85d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b9925fd-4982-428e-be70-180d1e44520f', '1. स्वर और 2. व्यंजन', false, '5562d8d2-08fa-4676-bfe1-65891a3d85d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85f50111-2034-4365-a60f-b3e29e1516b2', '1. तत्सम और 2. तद्भव', false, '5562d8d2-08fa-4676-bfe1-65891a3d85d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1513a38-65a7-4634-acfb-8de354a85327', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'वाक्य में जिसके विषय में कुछ कहा जाता है, उसे व्याकरण में क्या कहते हैं?', 'उद्देश्य: वाक्य में जिसके विषय में कोई विधान या बात की जाए, वह उद्देश्य (Subject) कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb487ad3-1ec2-4534-8743-31debf4180a7', 'उद्देश्य (जैसे: ''रोहन पुस्तक पढ़ता है'' में ''रोहन'')', true, 'c1513a38-65a7-4634-acfb-8de354a85327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed8b0bed-6906-4422-82cb-788d23b98549', 'विधेय', false, 'c1513a38-65a7-4634-acfb-8de354a85327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b51488e5-c0c5-4cb9-9dc5-2f8dceed36e6', 'क्रिया', false, 'c1513a38-65a7-4634-acfb-8de354a85327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3e1bc0e-f1d8-4f29-b82c-0750b0b8b8bb', 'कर्म', false, 'c1513a38-65a7-4634-acfb-8de354a85327');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ebef480-7e31-43a8-8be4-59951f1097f0', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'वाक्य में उद्देश्य (कर्ता) के विषय में जो कुछ कहा जाता है, उसे क्या कहते हैं?', 'विधेय: उद्देश्य के बारे में कही गई समस्त बात/क्रिया विधेय कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
