INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f69f7355-6f00-45ab-9f4f-3efc77280bb2', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', 'लिखते समय जब कोई शब्द या अंश छूट जाता है, तो उसे पंक्ति के ऊपर लिखकर किस त्रुटिपूरक चिह्न का प्रयोग किया जाता है?', 'हंसपद / काकपद (^): लिखते समय छूटे हुए शब्द को पंक्ति के ऊपर दर्शाने हेतु प्रयुक्त चिह्न।', NOW()) ON CONFLICT DO NOTHING;
