INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('588b7e98-a38b-4c70-a663-19a19716d5d8', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', 'शब्दों को संक्षिप्त रूप में लिखने के लिए किस चिह्न (जैसे: पं०, डाॅ०, कृ०पृ०उ०) का प्रयोग किया जाता है?', 'लाघव चिह्न (०): बड़े शब्दों के संक्षिप्त रूप (Abbreviation) को प्रदर्शित करने के लिए प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
