INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11dcb59a-adfe-499f-9fa6-6526bbe9db1e', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', '''ऊँट के मुँह में जीरा'' लोकोक्ति का सही अर्थ क्या है?', '''ऊँट के मुँह में जीरा'': अत्यधिक खुराक या आवश्यकता की तुलना में बहुत नगण्य वस्तु मिलना।', NOW()) ON CONFLICT DO NOTHING;
