INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf70d4bb-160c-4002-a333-f5bd27096a79', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', '''दूर के ढोल सुहावने होना'' लोकोक्ति का सही अर्थ क्या है?', '''दूर के ढोल सुहावने'': दूर से वस्तुएँ मनोहर प्रतीत होती हैं किंतु यथार्थ में कठिनाइयाँ छिपी होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab239930-da9f-47ea-a560-64a40c9338c9', 'दूर से चीजें अच्छी और आकर्षक लगती हैं, परन्तु पास जाने पर वास्तविकता कुछ और होती है', true, 'cf70d4bb-160c-4002-a333-f5bd27096a79');
